-- B1 DEPENDS: BEFORE:PT:PROCESS_START

CREATE PROCEDURE ATP_A0_CREATE_DB_TYPES ()
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
cnt int;
BEGIN
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_INT_QTY' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE ATP_INT_QTY CASCADE');
	end if;
	
	EXEC('
		CREATE TYPE ATP_INT_QTY AS TABLE(
			DATE INT,
			QTY DECIMAL(21,6)
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_DATE_QTY' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE ATP_DATE_QTY CASCADE');
	end if;
	
	EXEC('
		CREATE TYPE ATP_DATE_QTY AS TABLE(
			"Date" DATE,
			"Qty" DECIMAL(21,6)
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_COUNTER_DATE_QTY' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE ATP_COUNTER_DATE_QTY CASCADE');
	end if;
	
	EXEC('
		CREATE TYPE ATP_COUNTER_DATE_QTY AS TABLE(
			"Counter" INTEGER,
			"Date" DATE,
			"Qty" DECIMAL(21,6)
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_T_NUMB_RECHECK' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE ATP_T_NUMB_RECHECK CASCADE');
	end if;
	
	EXEC('
		CREATE TYPE ATP_T_NUMB_RECHECK AS TABLE(
			"Counter" INTEGER,
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_T_CONF' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE ATP_T_CONF CASCADE');
	end if;
		
	EXEC('
		CREATE TYPE ATP_T_CONF AS TABLE(
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER,
			"SchdLine" INTEGER,
			"CfmDate" DATE,
			"CfmQty" DECIMAL(21,6)
			)
	');
	
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_T_DONATORS' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE ATP_T_DONATORS CASCADE');
	end if;
	
	EXEC('
		CREATE TYPE ATP_T_DONATORS AS TABLE(
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER,
			"SchdLine" INTEGER,
			"CfmDate" DATE,
			"CfmQty" DECIMAL(21,6),
			"DonQty" DECIMAL(21,6)
		)
	');
	
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".SEQUENCES WHERE SEQUENCE_NAME = 'OSLD_S' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP SEQUENCE OSLD_S CASCADE');
	end if;
	
	EXEC('CREATE SEQUENCE OSLD_S START WITH 1');
END;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START AFTER:SP:ATP_A0_CREATE_DB_TYPES
CREATE PROCEDURE ATP_A1_CREATE_DB_OBJECTS ()
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
cnt int;
BEGIN
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_CHECKS' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE ATP_CHECKS CASCADE');
	end if;

	EXEC('
		CREATE COLUMN TABLE ATP_CHECKS(
	       "CheckID" INTEGER,
	       "ItemCode" NVARCHAR(50),
	       "WhsCode" NVARCHAR(8),
	       "Date" TIMESTAMP,
	       "Qty" DECIMAL(21,6),
    	 PRIMARY KEY ("CheckID")
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".SEQUENCES WHERE SEQUENCE_NAME = 'ATP_CHECK_ID' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP SEQUENCE ATP_CHECK_ID CASCADE');
	end if;

	EXEC('
		CREATE SEQUENCE ATP_CHECK_ID
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'OTQA' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE OTQA CASCADE');
	end if;

	EXEC('
		CREATE HISTORY COLUMN TABLE OTQA(
			"CheckID" INTEGER,
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER,
			"SchdLine" INTEGER,
			"TQAType" SMALLINT, -- 0 normal TQA, 1 invisible TQA (confirmations are already covered by existing OSLD entries)
			"ItemCode" NVARCHAR(50),
			"WhsCode" NVARCHAR(8),
			"CfmDate" TIMESTAMP,
			"CfmQty" DECIMAL(21,6),
			"ReqQty" DECIMAL(21,6),
			-- it is not necessary to add the transaction time, we can use time travel to get this information
			PRIMARY KEY ("CheckID", "ObjType", "DocEntry", "DocLineNum", "SchdLine","TQAType")
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ATP_LOCK' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE ATP_LOCK CASCADE');
	end if;

	EXEC('
		CREATE ROW TABLE ATP_LOCK(
		    "ItemCode" NVARCHAR(50),
		    "WhsCode" NVARCHAR(8),
		    PRIMARY KEY("ItemCode", "WhsCode")
		)
	');

	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'ODON' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE ODON CASCADE');
	end if;

	EXEC('
		CREATE GLOBAL TEMPORARY TABLE ODON(
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER,
			"ItemCode" NVARCHAR(50),
			"WhsCode" NVARCHAR(8),
			"CfmDate" TIMESTAMP,
			"DonQty" DECIMAL(21,6),
			"SequenceID" Integer)
	');
	
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'OCAN' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE OCAN CASCADE');
	end if;
	
	EXEC('
		CREATE GLOBAL TEMPORARY TABLE OCAN(
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER,
			"CanQty" DECIMAL(21,6),
			"date" DATE,
			"SequenceID" Integer)
	');
	
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'DOC_LINES_VERSIONS' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE DOC_LINES_VERSIONS CASCADE');
	end if;
	
	EXEC('
		CREATE GLOBAL TEMPORARY TABLE DOC_LINES_VERSIONS(
			"ObjType" NVARCHAR (20),
			"DocEntry" INTEGER,
			"DocLineNum" INTEGER,
			"Version" INTEGER
			)
	');
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_A2_NORM_TQA(
    IN item NVARCHAR(50),
    IN whs NVARCHAR(8),
    IN check_type INTEGER,
    OUT doc_lines DOC_LINES_VERSIONS,
    OUT result ATP_DATE_QTY
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
READS SQL DATA
AS
-- read TQA from the database
-- quantities in OTQA are positive -> multiply by -1 to get negative quantities
-- only TQAType 0 is relevant for the ATP calculation
-- If check_type == 1 we check against required quantities
-- else if :check_type == 2 --check against confirmed quantities
BEGIN
    docline_series  = 	SELECT "ObjType", "DocEntry", "DocLineNum", TO_DATE("CfmDate") as "Date",
            	CASE WHEN :check_type = 1 THEN -1*"ReqQty" ELSE -1*"CfmQty" END as "Qty"
               	FROM OTQA
               	WHERE "ItemCode" = :item AND "WhsCode" = :whs AND "TQAType" = 0;
	doc_lines = Select "ObjType", "DocEntry", "DocLineNum", 0 as "Version" From :docline_series;
	RESULT = SELECT "Date", cast("Qty" as DECIMAL(21,6)) as "Qty" From :docline_series;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_A3_EXISTING_REQUIREMENTS (
    IN obj_type NVARCHAR (20),
    IN doc_entry INTEGER,
    IN doc_line_num INTEGER,
    IN item_code NVARCHAR(50),
    IN whs_code NVARCHAR(8),
    OUT result_req ATP_DATE_QTY,
    OUT result_cfm ATP_DATE_QTY)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
READS SQL DATA
AS
BEGIN
	OILM_REQ = SELECT TO_DATE("DocDueDate") as "Date",
	                CASE WHEN ("AccumType" = 2 AND ("ActionType" = 1 or "ActionType" = 13) AND "IsNegLnQty" = 'N' OR
	                	("AccumType" = 3 AND ("ActionType" = 2 or "ActionType" = 14) AND "IsNegLnQty" = 'Y' ))
	                         THEN "EffectQty"
	                         ELSE -"EffectQty"
	                END as "Qty"
	FROM (SELECT cast("TransType" as nvarchar(20)) as "TransType", "DocEntry", "DocLineNum", "BaseType", "BaseAbsEnt", "BaseLine", "DocDueDate", "AccumType", "ActionType", "IsNegLnQty", "EffectQty", "ItemCode", "LocCode" FROM OILM)
	WHERE "AccumType" in (2,3) AND "ActionType" in (1,2,13,14) AND
	(("AccumType" = 2 AND ("ActionType" = 1 or "ActionType" = 13) AND "IsNegLnQty" = 'N')
	OR   ("AccumType" = 3 AND ("ActionType" = 2 or "ActionType" = 14) AND "IsNegLnQty" = 'Y' )
	OR   ("AccumType" = 2 AND ("ActionType" = 2 or "ActionType" = 14) AND "IsNegLnQty" = 'N' )
	OR   ("AccumType" = 3 AND ("ActionType" = 1 or "ActionType" = 13) AND "IsNegLnQty" = 'Y' ))
	AND "ItemCode" = :item_code AND "LocCode" = :whs_code AND
		(("TransType" = :obj_type AND "DocEntry" = :doc_entry AND "DocLineNum" = :doc_line_num AND "TransType" NOT IN (18,22,163) and  "ActionType" = 1) OR
		 ("TransType" = :obj_type AND "DocEntry" = :doc_entry AND "DocLineNum" = :doc_line_num and "TransType" in (18,22,163) and  "ActionType" = 2))
		OR ("BaseType"= :obj_type  and "BaseAbsEnt"= :doc_entry and "BaseLine"= :doc_line_num AND "LocCode" = :whs_code );
	-- Aggregate the changes of the document line
	RESULT_REQ = Select "Date", cast(Sum("Qty")  as DECIMAL(21,6)) as "Qty" From :OILM_REQ Group By "Date";
	RESULT_CFM = SELECT TO_DATE("CfmDate") as "Date", "CfmQty" as "Qty"
	         FROM OSLD
	         WHERE "ObjType" = :obj_type AND "DocEntry" = :doc_entry AND "DocLineNum" = :doc_line_num AND
			        "ItemCode" = :item_code AND "WhsCode" = :whs_code;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_A3_INSERT_TQA(
	IN check_id INTEGER,
	IN obj_type INTEGER,
	IN doc_entry INTEGER,
	IN doc_line_num INTEGER,
	IN schd_line INTEGER,
	IN tqa_type SMALLINT, -- 0 normal TQA, 1 invisible TQA (confirmations are already covered by existing OSLD entries)
	IN item NVARCHAR(50),
	IN whs NVARCHAR(8),
	IN cfm_date TIMESTAMP,
	IN cfm_qty DECIMAL(21,6),
	IN req_qty DECIMAL(21,6)
	)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
-- manual manipulation of TQA (caller has to know what he/she does!)
-- inserts one entry with the attributes provided via the interface to table OTQA
-- TODO: replace SELECT ... FROM DUMMY by INSERT
BEGIN
	INSERT INTO OTQA VALUES(:check_id,:obj_type,:doc_entry,:doc_line_num,:schd_line,:tqa_type,:item,:whs,:cfm_date,:cfm_qty,:req_qty
	);
END;

-- B1 DEPENDS: AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_A4_CLEANUP_TQA(IN keep_seconds INTEGER)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
cleanup_until varchar(30);
check_id INTEGER;
minCmTime TimeStamp;
-- delete TQA that were not removed properly
BEGIN
	Select Min(Commit_Time) Into minCmTime From "PUBLIC".Transaction_History;
	If :minCmTime Is Not NULL Then
		SELECT TO_CHAR(add_seconds(CURRENT_UTCTIMESTAMP, - :keep_seconds)) INTO cleanup_until FROM DUMMY;
		If To_TimeStamp(:cleanup_until) >= :minCmTime Then
			EXEC('SET HISTORY SESSION TO UTCTIMESTAMP ' || '''' || :cleanup_until || '''');
			SELECT MAX("CheckID") INTO check_id FROM OTQA;
		    EXEC('SET HISTORY SESSION TO NOW');
		    DELETE FROM OTQA WHERE "CheckID" <= :check_id;
		End If;
	End If;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
CREATE PROCEDURE ATP_A5_NORM_OITW (
    IN item NVARCHAR(50),
    IN whs NVARCHAR(8),
    OUT result ATP_DATE_QTY)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

READS SQL DATA
AS
-- read stock from the database
BEGIN
	result = select TO_DATE('19000101') as "Date", "OnHand" as "Qty"
	from OITW
	where "ItemCode" = :item and "WhsCode" = :whs;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
CREATE PROCEDURE ATP_A6_NORM_OILM (
    IN item NVARCHAR(50),
    IN whs NVARCHAR(8),
    IN includePastReceipt TINYINT,
    OUT doc_lines DOC_LINES_VERSIONS,
    OUT result ATP_DATE_QTY)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

READS SQL DATA
AS
-- read planned goods receipts from the database
BEGIN
	docline_series = Select TT."ItemCode", TT."LocCode", cast(TT."TransType" as nvarchar(20)) as "ObjType", TT."DocEntry", TT."DocLineNum",
	-- if BaseDueDate is null, use DocDueDate, for production order, use document end date
	CASE WHEN TT."TransType" = '202' AND TT."DocLineNum" = -1 THEN TO_DATE(P0."DueDate")
	     WHEN TT."TransType" = '202' AND TT."DocLineNum" >= 0 THEN TO_DATE(P1."EndDate")
	     WHEN (("AccumType" = 2 AND "ActionType" = 1  AND "IsNegLnQty" = 'Y' ) OR
	           ("AccumType" = 3 AND "ActionType" = 2  AND "IsNegLnQty" = 'N' )) 
	           THEN TO_DATE(IFNULL(B0."BaseDueDate", "DocDueDate"))
	     ELSE "DocDueDate" END AS "Date", 
	TO_DATE(TT."DocDueDate") AS "RefDate", P0."DueDate", P1."EndDate",
	CASE WHEN (("AccumType" = 2 AND ("ActionType" = 2 or "ActionType" = 14) AND "IsNegLnQty" = 'Y' ) OR
	   ("AccumType" = 3 AND ("ActionType" = 1 or "ActionType" = 13) AND "IsNegLnQty" = 'N' )) THEN IFNULL(Q1."OpenInvQty", "EffectQty")
	    ELSE - IFNULL(Q1."OpenInvQty", "EffectQty")
	    END AS "Qty"
	-- Add column BaseDueDate for "cancel out" messages in OILM
	FROM OILM TT LEFT OUTER JOIN
	(
		-- find max BaseDueDate for messages in OILM has another line accumType = 1
		-- for normal records except Issue For Production (ObjType <> 60)
		SELECT T."MessageID", MAX(B."DocDueDate") AS "BaseDueDate"
		FROM OILM T LEFT OUTER JOIN 
		(
			SELECT T1."MessageID", T1."TransType", T1."DocEntry", T1."DocLineNum",
			T1."ItemCode", T1."LocCode", T1."AccumType", T1."ActionType",
			CASE WHEN T1."TransType" = '202' AND T1."DocLineNum" = -1 THEN P0."DueDate"
	    	 WHEN T1."TransType" = '202' AND T1."DocLineNum" >= 0 THEN P1."EndDate"
	    	 ELSE "DocDueDate" END AS "DocDueDate",
	    	 "DocDueDate" AS "RefDate",
	    	 P0."DueDate", P1."EndDate"
			FROM OILM T1
			LEFT OUTER JOIN OWOR P0
			-- find end date for production order header
			ON T1."TransType" = '202' AND
			   T1."DocEntry" = P0."DocEntry" AND
			   T1."DocLineNum" = -1
			LEFT OUTER JOIN WOR1 P1
			-- find end date for production order line
			ON T1."TransType" = '202' AND
			   T1."DocEntry" = P1."DocEntry" AND
			   T1."DocLineNum" >= 0 AND
			   T1."DocLineNum" = P1."LineNum"
			WHERE
			T1."ItemCode" = :item AND T1."LocCode" = :whs
		)B
		ON T."BaseType" = B."TransType" and T."BaseAbsEnt" = B."DocEntry" and T."BaseLine" = B."DocLineNum"
		WHERE
			 T."BaseType" <> '202' AND
			T."ItemCode" = :item AND T."LocCode" = :whs AND
			 T."AccumType" IN (2,3) AND T."ActionType" IN (1,2) AND
                -- If the OILM has reverse action against base doc( 3,1 vs 3,2 or 2,2 vs 3,1 )
                -- means it is a "cancel out" record during copy to,
                -- such as PO to Reserve, PO to PDN, Reserve to PDN,
                -- or negative SO to Reserve, SO to DLN, Reserve to DLN,
                -- use the BaseDueDate for the outgoing direction qty.
                -- For CEE, it always considers the delta changes,
                -- so there's no such "cancel out" record.
			 T."AccumType" = B."AccumType" AND
			 T."ActionType" + B."ActionType" = 3 AND
			( (T."AccumType" = 2 AND (T."ActionType" = 2 or T."ActionType" = 14) AND T."IsNegLnQty" = 'Y') OR
			(T."AccumType" = 3 AND (T."ActionType" = 1 or T."ActionType" = 13) AND T."IsNegLnQty" = 'N') OR
			(T."AccumType" = 2 AND (T."ActionType" = 1 or T."ActionType" = 13) AND T."IsNegLnQty" = 'Y') OR
			(T."AccumType" = 3 AND (T."ActionType" = 2 or T."ActionType" = 14) AND T."IsNegLnQty" = 'N') )
		GROUP BY T."MessageID"
		-- end of for normal records except Issue For Production (ObjType <> 60)		
		UNION ALL
		-- for Issue For Production of disassembly BOM (ObjType = 60)
		SELECT T."MessageID", MAX(B."DocDueDate") AS "BaseDueDate"
		FROM OILM T LEFT OUTER JOIN 
		(
			SELECT T1."MessageID", T1."TransType", T1."DocEntry", T1."DocLineNum",
			T1."ItemCode", T1."LocCode",
			CASE WHEN T1."DocLineNum" = -1 THEN P0."DueDate"
	    	 WHEN T1."DocLineNum" >= 0 THEN P1."EndDate"
	    	 ELSE "DocDueDate" END AS "DocDueDate",
	    	 "DocDueDate" AS "RefDate",
	    	 P0."DueDate", P1."EndDate"
			FROM OILM T1
			LEFT OUTER JOIN OWOR P0
			-- find end date for production order header
			ON T1."TransType" = '202' AND
			   T1."DocEntry" = P0."DocEntry" AND
			   T1."DocLineNum" = -1
			LEFT OUTER JOIN WOR1 P1
			-- find end date for production order line
			ON T1."TransType" = '202' AND
			   T1."DocEntry" = P1."DocEntry" AND
			   T1."DocLineNum" >= 0 AND
			   T1."DocLineNum" = P1."LineNum"
			WHERE T1."TransType" = '202' AND
			T1."ItemCode" = :item AND T1."LocCode" = :whs
		)B
		ON T."BaseType" = B."TransType" and T."BaseAbsEnt" = B."DocEntry" and T."AppObjLine" = B."DocLineNum"
		WHERE
			 T."BaseType" = '202' AND
			T."ItemCode" = :item AND T."LocCode" = :whs AND
			 T."AccumType" IN (2,3) AND T."ActionType" IN (1,2,13,14) AND
			 EXISTS (
			 	SELECT 1 FROM OILM U WHERE U."AccumType" = 1 AND
			 	T."TransType" = U."TransType" AND T."DocEntry" = U."DocEntry" AND T."DocLineNum" = U."DocLineNum" 
			 ) AND
			( (T."AccumType" = 2 AND (T."ActionType" = 2 or T."ActionType" = 14) AND T."IsNegLnQty" = 'Y') OR
			(T."AccumType" = 3 AND (T."ActionType" = 1 or T."ActionType" = 13) AND T."IsNegLnQty" = 'N') OR
			(T."AccumType" = 2 AND (T."ActionType" = 1 or T."ActionType" = 13) AND T."IsNegLnQty" = 'Y') OR
			(T."AccumType" = 3 AND (T."ActionType" = 2 or T."ActionType" = 14) AND T."IsNegLnQty" = 'N') )
		GROUP BY T."MessageID"
		-- end of for Issue For Production of disassembly BOM (ObjType = 60)
	) B0
	ON TT."MessageID" = B0."MessageID"
	LEFT OUTER JOIN OWOR P0
	-- find end date for production order header
	ON TT."TransType" = '202' AND
	   TT."DocEntry" = P0."DocEntry" AND
	   TT."DocLineNum" = -1
	LEFT OUTER JOIN WOR1 P1
	-- find end date for production order line
	ON TT."TransType" = '202' AND
	   TT."DocEntry" = P1."DocEntry" AND
	   TT."DocLineNum" >= 0 AND
	   TT."DocLineNum" = P1."LineNum"
	LEFT JOIN WTQ1 Q1
	-- find openqty for wtq1 line
	ON TT."TransType" = '1250000001' 
	   AND TT."DocEntry" = Q1."DocEntry" 
	   AND TT."ItemCode" = Q1."ItemCode"
	   AND TT."DocLineNum" = Q1."LineNum"
	WHERE
	TT."ItemCode" = :item AND TT."LocCode" = :whs AND
	TT."AccumType" in (2,3) and TT."ActionType" in (1,2,13,14) and
	( (TT."AccumType" = 2 AND (TT."ActionType" = 2 or TT."ActionType" = 14) AND TT."IsNegLnQty" = 'Y') OR
	(TT."AccumType" = 3 AND (TT."ActionType" = 1 or TT."ActionType" = 13) AND TT."IsNegLnQty" = 'N') OR
	(TT."AccumType" = 2 AND (TT."ActionType" = 1 or TT."ActionType" = 13) AND TT."IsNegLnQty" = 'Y') OR
	(TT."AccumType" = 3 AND (TT."ActionType" = 2 or TT."ActionType" = 14) AND TT."IsNegLnQty" = 'N') ) AND
	(:includePastReceipt = 1 OR 
	 (TT."TransType" = '202' AND TT."DocLineNum" = -1 AND P0."DueDate" >= Current_date) OR
	 (TT."TransType" = '202' AND TT."DocLineNum" >= 0 AND P1."EndDate" >= Current_date) OR
	 (TT."TransType" <> '202' AND IFNULL(B0."BaseDueDate", "DocDueDate") >= Current_date)) AND TT."TransType" <> '67'
	 AND NOT EXISTS(Select 1 FROM OILM TTT  WHERE TTT."TransType" = TT."BaseType" AND TTT."DocEntry" = TT."BaseAbsEnt" AND TTT."DocLineNum" = TT."BaseLine" AND TTT."ActionType" = 19)
	;
	doc_lines = Select "ObjType", "DocEntry", "DocLineNum", 0 as "Version" From :docline_series;
	result = Select "Date", "Qty" From :docline_series;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_A7_NORM_OSLD ( IN item NVARCHAR(50),
	 IN whs NVARCHAR(8),
	 IN obj_type NVARCHAR (20),
	 IN doc_entry INTEGER,
	 IN doc_line_num INTEGER,
	 IN check_type INTEGER,
	 OUT doc_lines DOC_LINES_VERSIONS,
	 OUT result ATP_DATE_QTY) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
READS SQL DATA 
AS 
BEGIN 
IF :check_type = 1 --check against required quantities

THEN -- Query to get plan issues, which will be needed to subtract when checking against required qty ------
 -- Get the plan issues through posted transactions
 TRANS_REQ = 

SELECT cast(TT."TransType" as nvarchar(20))          as "ObjType", 
       TT."DocEntry", 
       TT."DocLineNum", 
		CASE WHEN TT."TransType" = '202' AND TT."DocLineNum" = -1 THEN TO_DATE(P0."StartDate")
		     WHEN TT."TransType" = '202' AND TT."DocLineNum" >= 0 THEN TO_DATE(P1."StartDate")
		     ELSE TO_DATE(IFNULL(B0."BaseDueDate", "DocDueDate")) END AS "Date", 
--		TO_DATE(TT."DocDueDate") AS "RefDate", P0."StartDate", P1."StartDate",
       CASE 
         WHEN ( "TransType" not in ( 163, 165 ) 
                and ( "AccumType" = 2 
                      AND "ActionType" = 1 
                      AND "IsNegLnQty" = 'N' 
                       OR ( "AccumType" = 3 
                            AND "ActionType" = 2 
                            AND "IsNegLnQty" = 'Y' ) ) ) THEN IFNULL(Q1."OpenInvQty", "EffectQty")  
         WHEN ( "TransType" not in ( 163, 165 ) 
                and "AccumType" = 2 
                AND "ActionType" = 2 
                AND "IsNegLnQty" = 'N' 
                 OR ( "AccumType" = 3 
                      AND "ActionType" = 1 
                      AND "IsNegLnQty" = 'Y' ) ) THEN IFNULL(-Q1."OpenInvQty", -"EffectQty")  
         --use action=13,14,5 as was line(opposite line to reverse)  
         --use action=2 as should be line  
         WHEN ( "TransType" in ( 165 ) 
                and "AccumType" = 2 
                AND "ActionType" in ( 2 ) 
                AND "IsNegLnQty" = 'N' ) THEN "CIShbQty" 
         WHEN ( "TransType" in ( 165 ) 
                and "AccumType" = 2 
                AND "ActionType" in ( 2 ) 
                AND "IsNegLnQty" = 'Y' ) THEN -"CIShbQty" 
         WHEN ( "TransType" in ( 165 ) 
                and ( ( "AccumType" = 2 
                        AND "ActionType" in ( 13 ) ) 
                       or ( "AccumType" = 0 
                            AND "ActionType" = 5 ) ) 
                AND "IsNegLnQty" = 'N' ) THEN "EffectQty" - "CIShbQty" 
         WHEN ( "TransType" in ( 165 ) 
                and ( "AccumType" = 2 
                      AND "ActionType" in ( 14 ) ) 
                AND "IsNegLnQty" = 'N' ) THEN -( "EffectQty" + "CIShbQty" ) 
         WHEN ( "TransType" in ( 165 ) 
                and ( ( "AccumType" = 2 
                        AND "ActionType" in ( 14 ) ) 
                       or ( "AccumType" = 0 
                            AND "ActionType" = 5 ) ) 
                AND "IsNegLnQty" = 'Y' ) THEN "CIShbQty" - "EffectQty" 
         WHEN ( "TransType" in ( 165 ) 
                and ( "AccumType" = 2 
                      AND "ActionType" in ( 13 ) ) 
                AND "IsNegLnQty" = 'Y' ) THEN "EffectQty" + "CIShbQty" 
         --use action=13,14,5 as was line(opposite line to reverse)  
         --use action=2 as should be line  
         WHEN ( "TransType" in ( 163 ) 
                and "AccumType" = 3 
                AND "ActionType" in ( 2 ) 
                AND "IsNegLnQty" = 'N' ) THEN -"CIShbQty" 
         WHEN ( "TransType" in ( 163 ) 
                and "AccumType" = 3 
                AND "ActionType" in ( 2 ) 
                AND "IsNegLnQty" = 'Y' ) THEN "CIShbQty" 
         WHEN ( "TransType" in ( 163 ) 
                and ( ( "AccumType" = 3 
                        AND "ActionType" in ( 14 ) ) 
                       or ( "AccumType" = 0 
                            AND "ActionType" = 5 ) ) 
                AND "IsNegLnQty" = 'N' ) THEN "EffectQty" + "CIShbQty" 
         WHEN ( "TransType" in ( 163 ) 
                and ( "AccumType" = 3 
                      AND "ActionType" in ( 13 ) ) 
                AND "IsNegLnQty" = 'N' ) THEN "CIShbQty" - "EffectQty" 
         WHEN ( "TransType" in ( 163 ) 
                and ( ( "AccumType" = 3 
                        AND "ActionType" in ( 13 ) ) 
                       or ( "AccumType" = 0 
                            AND "ActionType" = 5 ) ) 
                AND "IsNegLnQty" = 'Y' ) THEN -( "EffectQty" + "CIShbQty" ) 
         WHEN ( "TransType" in ( 163 ) 
                and ( "AccumType" = 3 
                      AND "ActionType" in ( 14 ) ) 
                AND "IsNegLnQty" = 'Y' ) THEN "EffectQty" - "CIShbQty" 
         ELSE -"EffectQty" 
       END                   as "Qty" 
-- Add column BaseDueDate for messages in OILM has another line accumType = 1
FROM OILM TT LEFT OUTER JOIN
(
	-- find max BaseDueDate for messages in OILM has another line accumType = 1
	SELECT T."MessageID", MAX(B."DocDueDate") AS "BaseDueDate"
	FROM OILM T LEFT OUTER JOIN 
	(
		SELECT T1."MessageID", T1."TransType", T1."DocEntry", T1."DocLineNum",
		T1."ItemCode", T1."LocCode",
		CASE WHEN T1."TransType" = '202' AND T1."DocLineNum" = -1 THEN P0."StartDate"
    	 WHEN T1."TransType" = '202' AND T1."DocLineNum" >= 0 THEN P1."StartDate"
    	 ELSE "DocDueDate" END AS "DocDueDate",
    	 "DocDueDate" AS "RefDate",
    	 P0."DueDate", P1."EndDate"
		FROM OILM T1
		LEFT OUTER JOIN OWOR P0
		-- find start date for production order header
		ON T1."TransType" = '202' AND
		   T1."DocEntry" = P0."DocEntry" AND
		   T1."DocLineNum" = -1
		LEFT OUTER JOIN WOR1 P1
		-- find start date for production order line
		ON T1."TransType" = '202' AND
		   T1."DocEntry" = P1."DocEntry" AND
		   T1."DocLineNum" >= 0 AND
		   T1."DocLineNum" = P1."LineNum"
		WHERE T1."ItemCode" = :item 
     	  and T1."LocCode" = :whs 
	)B
	ON T."BaseType" = B."TransType" and T."BaseAbsEnt" = B."DocEntry" and T."BaseLine" = B."DocLineNum"
	WHERE T."ItemCode" = :item 
       and T."LocCode" = :whs 
       and T."AccumType" IN (0,2,3) AND T."ActionType" IN (1,2,5,13,14) AND
		 EXISTS (
		 	SELECT 1 FROM OILM U WHERE U."AccumType" = 1 AND
		 	T."TransType" = U."TransType" AND T."DocEntry" = U."DocEntry" AND T."DocLineNum" = U."DocLineNum" 
		 ) AND
		 ( ( "AccumType" = 2 AND "ActionType" in (1, 13) AND "IsNegLnQty" = 'N' ) OR 
		   ( "AccumType" = 3 AND "ActionType" in (2, 14) AND "IsNegLnQty" = 'Y' ) OR 
		   ( "AccumType" = 2 AND "ActionType" in (2, 14) AND "IsNegLnQty" = 'N' ) OR
           ( "AccumType" = 3 AND "ActionType" in (1, 13) AND "IsNegLnQty" = 'Y' ) OR 
           ( "AccumType" = 0 AND "ActionType" = 5 ) )
	GROUP BY T."MessageID"
) B0
	ON TT."MessageID" = B0."MessageID"
	LEFT OUTER JOIN OWOR P0
	-- find end date for production order header
	ON TT."TransType" = '202' AND
	   TT."DocEntry" = P0."DocEntry" AND
	   TT."DocLineNum" = -1
	LEFT OUTER JOIN WOR1 P1
	-- find end date for production order line
	ON TT."TransType" = '202' AND
	   TT."DocEntry" = P1."DocEntry" AND
	   TT."DocLineNum" >= 0 AND
	   TT."DocLineNum" = P1."LineNum"
	LEFT OUTER JOIN WTQ1 Q1
	-- find openqty for wtq1 line
	ON TT."TransType" = '1250000001' AND
	   TT."DocEntry" = Q1."DocEntry" AND
	   TT."DocLineNum" = Q1."LineNum"
WHERE  	TT."ItemCode" = :item AND TT."LocCode" = :whs AND
		"AccumType" in ( 0, 2, 3 ) 
       and "ActionType" in ( 1, 2, 5, 13, 14 ) 
       and "TransType" <> '67'
       and ( ( "AccumType" = 2 
               AND "ActionType" in (1, 13) 
               AND "IsNegLnQty" = 'N' ) 
              OR ( "AccumType" = 3 
                   AND  "ActionType" in (2, 14)
                   AND "IsNegLnQty" = 'Y' ) 
              OR ( "AccumType" = 2 
                   AND "ActionType" in (2, 14)  
                   AND "IsNegLnQty" = 'N' ) 
              OR ( "AccumType" = 3 
                   AND "ActionType" in (1, 13 ) 
                   AND "IsNegLnQty" = 'Y' ) 
              OR ( "AccumType" = 0 AND "ActionType" = 5 AND "TransType" <> '163') ) 
              --AND ((part 1 and part 2) or part 3 or part 4)
--part 1 = non-CI docs which need ATP check
--part 2 = part what was copied away part
--part 3 = AP correction reserve invoice
--part 4 = AR correction reserve invoice
       AND ( (( ( ( "TransType" != :obj_type 
				OR TT."DocEntry" != :doc_entry 
				OR TT."DocLineNum" != :doc_line_num
				or  "AccumType"!=2 or "ActionType" !=1)  
				 and ( "TransType" != :obj_type 
				OR TT."DocEntry" != :doc_entry 
				OR TT."DocLineNum" != :doc_line_num
				or  "AccumType"!=3 or "ActionType" !=2))--these two kinds will need ATP check in non-CI docs
			and "TransType" not in ( 163,
	 165 ) ) --no need to exclude 164/166 since they don't have ATP
	 
	  
		and ( ( TT."BaseType" != :obj_type --Base fields here are for current line's partially copied part
				OR "BaseAbsEnt" != :doc_entry 
				OR TT."BaseLine" != :doc_line_num ) 
			and (TT."BaseType" not in ( 163, 165 )  or "TransType" in ( 164, 166 )) ))
              --no partial copy in CI     
              or (( ( "TransType" != :obj_type 
                       OR TT."DocEntry" != :doc_entry 
                       OR TT."DocLineNum" != :doc_line_num 
                       or "AccumType" != 3 ) 
                    and "TransType" = 163 )) 
              or (( ( "TransType" != :obj_type 
                       OR TT."DocEntry" != :doc_entry 
                       OR TT."DocLineNum" != :doc_line_num 
                       --keep accumtype=0 as was line(opposite line to reverse)  
                       or "AccumType" != 2 ) 
                    and "TransType" = 165 )) )  
;
 -- Get the plan issues that still waiting for approvement.
 -- When creating a draft that sent for approvement, the required quantity will be insert into OSLD
 WFA_REQ = Select
	 "ObjType",
	 "DocEntry",
	 "DocLineNum",
	 TO_DATE("CfmDate") as "Date",
	 "ReqQty" as "Qty" 
From OSLD 
Where "ReqQty" != 0 
And "ItemCode" = :item 
And "WhsCode" = :whs 
And ("ObjType" != :obj_type 
	OR "DocEntry" != :doc_entry 
	OR "DocLineNum" != :doc_line_num)
;
 docline_series = Select
	 "ObjType",
	 "DocEntry",
	 "DocLineNum",
	 "Date",
	 cast(-"Qty" as DECIMAL(21,6)) as "Qty" 
From :TRANS_REQ 
UNION ALL Select
	 "ObjType",
	 "DocEntry",
	 "DocLineNum",
	 "Date",
	 cast(-"Qty" as DECIMAL(21,6)) as "Qty" 
From :WFA_REQ
;
 doc_lines = Select
	 "ObjType",
	 "DocEntry",
	 "DocLineNum",
	 0 as "Version" 
From :docline_series
;
 Result = Select
	 "Date",
	 cast("Qty" as DECIMAL(21,6)) as "Qty"
From :docline_series
;
ELSEIF :check_type = 2 --check against confirmed quantities

THEN -- ignore confirmations of order line with key (obj_type, doc_entry, doc_line_num)
 docline_series = SELECT
	 "ObjType",
	 "DocEntry",
	 "DocLineNum",
	 TO_DATE("CfmDate") as "Date",
	 cast(-1*"CfmQty" as DECIMAL(21,6)) as "Qty" 
FROM OSLD 
WHERE "ItemCode" = :item 
AND "WhsCode" = :whs 
AND ("ObjType" != :obj_type 
	OR "DocEntry" != :doc_entry 
	OR "DocLineNum" != :doc_line_num)
;
 doc_lines = Select
	 "ObjType",
	 "DocEntry",
	 "DocLineNum",
	 0 as "Version" 
From :docline_series
;
 Result = Select
	 "Date",
	 cast("Qty" as DECIMAL(21,6)) as "Qty"
From :docline_series
;

END 
IF
;

END
;

-- B1 DEPENDS: AFTER:SP:ATP_A2_NORM_TQA AFTER:SP:ATP_A6_NORM_OILM AFTER:SP:ATP_A7_NORM_OSLD AFTER:SP:ATP_A5_NORM_OITW AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
CREATE PROCEDURE ATP_A8_AGG_TIME_SERIES (
    IN item NVARCHAR(50),
    IN whs NVARCHAR(8),
    IN obj_type NVARCHAR(20),
    IN doc_entry INTEGER,
    IN doc_line_num INTEGER,
    IN check_type INTEGER,
    IN includePastReceipt TINYINT,
    OUT INVOLOVED_DOC_LINES DOC_LINES_VERSIONS,
    OUT RESULT ATP_DATE_QTY)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

READS SQL DATA
AS
BEGIN
    CALL ATP_A5_NORM_OITW (:item, :whs, norm_oitw);
    CALL ATP_A6_NORM_OILM (:item, :whs, :includePastReceipt, ilm_doc_lines, norm_oilm);
    CALL ATP_A7_NORM_OSLD (:item, :whs, :obj_type, :doc_entry, :doc_line_num, :check_type, sld_doc_lines, norm_osld);
    CALL ATP_A2_NORM_TQA(:item, :whs, :check_type, tqa_doc_lines, norm_tqa);
	UNION_ALL = SELECT * FROM :NORM_OITW
				UNION ALL
				SELECT * FROM :NORM_OILM
				UNION ALL
				SELECT * FROM :NORM_OSLD
				UNION ALL
				SELECT * FROM :NORM_TQA;
    RESULT = SELECT "Date", cast( SUM("Qty") as DECIMAL(21,6)) as "Qty"
	     	 FROM :UNION_ALL GROUP BY "Date";
	INVOLOVED_DOC_LINES =
		Select Distinct * From :ilm_doc_lines
		UNION ALL
		Select Distinct * From :sld_doc_lines
		UNION ALL
		Select Distinct * From :tqa_doc_lines
		UNION ALL
		Select Distinct "ObjType", "DocEntry", "DocLineNum", 0 From ODON
		UNION ALL
		Select Distinct "ObjType", "DocEntry", "DocLineNum", 0 From OCAN
		UNION ALL
		Select :obj_type, :doc_entry, :doc_line_num, 0 From DUMMY;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
CREATE PROCEDURE ATP_A9_CANDALGO (
     IN timeSeries ATP_INT_QTY,
     IN scheduleLines ATP_INT_QTY,
     OUT confirmations ATP_INT_QTY)
LANGUAGE LLANG
SQL SECURITY INVOKER
READS SQL DATA
AS
BEGIN
typedef Int32 DATE_T;
typedef Fixed12<6> QTY_T;
typedef Column<DATE_T> COL_DATE_T;
typedef Column<QTY_T> COL_QTY_T;
typedef Table<DATE_T "DATE", QTY_T "QTY"> DATE_QTY_TABLE_T;
typedef Block<QTY_T> AAD_T;
typedef DATE_QTY_TABLE_T CANDIDATE_T;
typedef DATE_QTY_TABLE_T TS_T;
typedef DATE_QTY_TABLE_T SL_T;
Void traceTab(CANDIDATE_T & data) {
    Trace t;
    t.append("Candidates").endl();
    t.append(data, data.getSize());
}
Void addCandidate(CANDIDATE_T & candidates,
                  DATE_T date,
                  QTY_T value)
{
    COL_DATE_T dates = candidates.getColumn<DATE_T>("DATE");
    COL_QTY_T values = candidates.getColumn<QTY_T>("QTY");
    Size currSize = dates.getSize();
    dates[currSize] = date;
    values[currSize] = value;
}
Void removeCandidates(CANDIDATE_T & candidates,
                      QTY_T accumulated)

{
    //Trace t;
    //t.append("rm cand amount").append(accumulated).endl();
    COL_DATE_T dates = candidates.getColumn<DATE_T>("DATE");
    COL_QTY_T values = candidates.getColumn<QTY_T>("QTY");
    Size currSize = Size(dates.getSize());
    QTY_T lastValue;
    QTY_T zero;
    while ((accumulated < zero) && (currSize > 0z)) {
        lastValue = values[currSize - 1z];
        //t.append(accumulated).append(" ").append(lastValue).endl(); */
        if ((lastValue + accumulated) <= zero)
        {
            accumulated = accumulated + lastValue;
            // BUG: In lieu of currSize = currSize - 1z;
            if (currSize == 1z) { currSize = 0z; } else { currSize = currSize - 1z; }
            dates.setSize(currSize);
            values.setSize(currSize);
        }
        else
        {
            values[currSize - 1z] = values[currSize - 1z] + accumulated;
            accumulated = zero;
        }
    }
}
Void modify(DATE_T date,
            AAD_T & aad,
            CANDIDATE_T & candidates)
{
    //Trace t;
    //t.append("Modify ").append(date).endl();
    Size accumulatedz = 0z;
    Size acquiredz = 1z;
    Size desiredz = 2z;
    // Increase readability of the following part by extracting aad into vars
    QTY_T acquired = aad[acquiredz];
    QTY_T accumulated = aad[accumulatedz];
    QTY_T desired = aad[desiredz];
    QTY_T zero;
    //t.append("AAD ").append(accumulated).append(" ").append(acquired).append(" ").append(desired).endl();
    //t.append("acc - des = ").append(acquired - desired).endl();
    // The time series item is larger than what we need (desired-acquired)
    // and what we need is larger than zero
    if ((accumulated >= (desired - acquired)) && ((desired - acquired) > zero)) {
        addCandidate(candidates, date, desired - acquired);
        accumulated = accumulated - (desired - acquired);
        acquired = desired;
    // What we need is larger than accumulated and there is actually something
    // to accumulate
    } else if (((desired - acquired) > accumulated) && (accumulated > zero)) {
        addCandidate(candidates, date, accumulated);
        acquired = acquired + accumulated;
        accumulated = zero;
    } else {
        if (accumulated < zero) {
            QTY_T oldAcquired = acquired;
            removeCandidates(candidates, accumulated);
            acquired = acquired + accumulated;
            if (acquired < zero) {
                acquired = zero;
            }
            accumulated = accumulated + oldAcquired;
            if (accumulated > zero) {
                accumulated = zero;
            }
        }
    }
    //t.append("AAD after").append(accumulated).append(" ").append(acquired).append(" ").append(desired).endl();
    aad[accumulatedz] = accumulated;
    aad[acquiredz] = acquired;
    aad[desiredz] = desired;
}
Void calculateCandidates(TS_T timeSeries,
                         SL_T scheduleLines,
                         CANDIDATE_T & candidates)
{
    //Trace t;
    //t.append("TS").endl();
    //traceTab(timeSeries);
    //t.append("SL").endl();
    //traceTab(scheduleLines);
    
    Block<QTY_T> aad = Block<QTY_T>(3z);
    aad.setSize(3z);
    
    Size accumulated = 0z;
    Size acquired = 1z;
    Size desired = 2z;
    QTY_T oldAccumulated;
    COL_DATE_T tsDates = timeSeries.getColumn<DATE_T>("DATE");
    COL_QTY_T tsQuantities = timeSeries.getColumn<QTY_T>("QTY");
    COL_DATE_T slDates = scheduleLines.getColumn<DATE_T>("DATE");
    COL_QTY_T slQuantities = scheduleLines.getColumn<QTY_T>("QTY");
    Size row; // pointer to current element of timeseries
    Size line; // pointer to current element of schedule line
    DATE_T currDate; // current date of timeseries
    QTY_T currQty; // current qty of timeseries
    DATE_T desiredDate; // current date of schedule lines
    QTY_T desiredAmount; // current qty of schedule lines
    DATE_T checkDate;
    while ((row < timeSeries.getSize()) || (line < scheduleLines.getSize()))
    {
        //t.append("row ").append(row).append(" / ").append(timeSeries.getSize()).append("       ").append("line ").append(line).append(" / ").append(scheduleLines.getSize()).endl();
        if ((line >= scheduleLines.getSize()) || (row < timeSeries.getSize() && tsDates[row] < slDates[line]))  {
            currDate = tsDates[row];
            currQty  = tsQuantities[row];
            aad[accumulated] = aad[accumulated] + currQty;
            checkDate = currDate;
            row = row + 1z;
        }
        else {
            if (row >= timeSeries.getSize() ||
               (line < scheduleLines.getSize() && slDates[line] < (tsDates[row]) )  ) {
                desiredDate = slDates[line];
                desiredAmount  = slQuantities[line];
                aad[desired] = aad[desired] + desiredAmount;
                checkDate = desiredDate;
                line = line + 1z;
            }
            else {
                currDate = tsDates[row];
                currQty  = tsQuantities[row];
                aad[accumulated] = aad[accumulated] + currQty;
                checkDate = currDate;
                row = row + 1z;
                desiredDate = slDates[line];
                desiredAmount  = slQuantities[line];
                aad[desired] = aad[desired] + desiredAmount;
                checkDate = desiredDate;
                line = line + 1z;
            }
        }
        //t.append("row ").append(row).append("       ").append("line ").append(line).endl();
        modify(checkDate, aad, candidates);
    }
}
export Void main(TS_T "timeSeries" timeSeries,
                 SL_T "scheduleLines" scheduleLines,
                 CANDIDATE_T "confirmations" & confirmations)
{
    calculateCandidates(timeSeries, scheduleLines, confirmations);
}
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
CREATE PROCEDURE ATP_B1_ADD_TQA(
    IN NEW_CONF ATP_DATE_QTY, -- time series of new confirmations
    IN OLD_CONF ATP_DATE_QTY, -- time series of old confirmations
    OUT RESULT ATP_COUNTER_DATE_QTY) -- time series of additional temporary quantity assignments (TQA)
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
READS SQL DATA
AS
-- calculate additional TQA of type 0 that are necessary to make OLD_CONF as strong as NEW_CONF
BEGIN
-- combine the two input time series into one time series
MATCH = SELECT
        CASE WHEN o."Date" is null THEN n."Date" ELSE o."Date" END AS "Date",
        CASE WHEN o."Qty" is null THEN 0 ELSE o."Qty" END AS "OldQty",
        CASE WHEN n."Qty" is null THEN 0 ELSE n."Qty" END AS "NewQty"
        FROM :NEW_CONF n FULL OUTER JOIN :OLD_CONF o ON n."Date" = o."Date";
-- cumulate old and new confirmations,
-- put difference of cumulated rows to column Diff if greater than 0,
-- get a row number into column Counter to be able to join with the previous row
NUM_AGG = SELECT count(*) as "Counter", m1."Date", GREATEST(sum(m2."NewQty") - sum(m2."OldQty"),0) as "Diff"
          FROM :MATCH m1, :MATCH m2 WHERE m2."Date" <= m1."Date" GROUP BY m1."Date" ORDER BY m1."Date";
-- calculate final result [Qty(n) = Diff(n) - Diff(n-1)]
RESULT = SELECT cast("Counter" as int) as "Counter", "Date", cast("Qty" as DECIMAL(21,6)) as "Qty" FROM
         (SELECT a1."Counter", a1."Date", CASE WHEN a2."Counter" is null THEN a1."Diff" ELSE a1."Diff" - a2."Diff" END as "Qty"
          FROM :NUM_AGG a1 LEFT OUTER JOIN  :NUM_AGG a2 ON a2."Counter" = a1."Counter" - 1)
         WHERE "Qty" != 0;
END;

-- B1 DEPENDS: AFTER:SP:ATP_B1_ADD_TQA AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:SP:ATP_A3_EXISTING_REQUIREMENTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_B2_GATEWAY(
    IN obj_type NVARCHAR (20),
    IN check_id INTEGER,
    IN item NVARCHAR(50),
    IN whs NVARCHAR(8),
    IN check_strategy INTEGER,
    IN check_id_for_recheck INTEGER,
    IN doc_entry INTEGER,
    IN doc_line_num INTEGER,
    IN LINEITEMS ATP_INT_QTY,
    IN check_type INTEGER,
    IN includePastReceipt TINYINT,
    OUT RESULT ATP_DATE_QTY
)
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
AS
tqa_type SMALLINT;
resSize Integer;
BEGIN
	DELETE FROM OTQA WHERE "CheckID" = :check_id_for_recheck;
    CALL ATP_A8_AGG_TIME_SERIES (:item, :whs, :obj_type, :doc_entry, :doc_line_num, :check_type, :includePastReceipt, doc_lines, TS);
    CALL ATP_E0_RECORD_LINES_VERSIONS(:doc_lines);
    TIMESERIES = SELECT TO_INT(TO_DATS("Date")) AS date, "Qty" AS qty FROM :ts WHERE "Qty" != 0 ORDER BY "Date";
    CALL ATP_A9_CANDALGO(:TIMESERIES, :LINEITEMS, CONFIRMATIONS);
-- adapt confirmations according to check strategy (not used at the moment, strategy 1 is hard coded)
    IF :check_strategy = 1
-- normal case: keep confirmations as they are
    THEN
    RESULT = SELECT TO_DATE(TO_NCHAR(date)) as "Date", qty as "Qty" FROM :CONFIRMATIONS;
    ELSEIF :check_strategy = 2
    THEN
-- keep earliest delivery only
    RESULT = SELECT TOP 1 TO_DATE(TO_NCHAR(date)) as "Date", qty as "Qty" FROM :CONFIRMATIONS ORDER BY date;
    ELSE
-- complete delivery (at latest delivery date)
    RESULT = SELECT MAX(TO_DATE(TO_NCHAR(date))) as "Date", cast(SUM(qty) as DECIMAL(21,6)) as "Qty" FROM :CONFIRMATIONS;
    END IF;
-- read existing confirmations for checked document
   LINEITEMS_TMP = SELECT TO_DATE(TO_NCHAR(date)) as "Date", qty as "Qty" FROM :LINEITEMS;
   TQA_TMP = SELECT
        CASE WHEN o."Date" is null THEN n."Date" ELSE o."Date" END AS "Date",
        CASE WHEN n."Qty" is null THEN 0 ELSE n."Qty" END AS "ReqQty",
        CASE WHEN o."Qty" is null THEN 0 ELSE o."Qty" END AS "CfmQty"
        FROM :LINEITEMS_TMP n FULL OUTER JOIN :RESULT o ON n."Date" = o."Date";
-- create schedule line number
    TQA = CE_PROJECTION(:TQA_TMP, [CE_CALC('rownum()', integer) as "SchdLine", "Date", "ReqQty", "CfmQty"]);
	CALL ATP_A3_EXISTING_REQUIREMENTS(:obj_type, :doc_entry, :doc_line_num, :item, :whs, OLDCONF_REQ, OLDCONF_CFM);
-- TQAType must be 1 when there are already confirmations (otherwise it is 0)
    SELECT COUNT(*) INTO tqa_type FROM (SELECT TOP 1 * FROM (SELECT * FROM :OLDCONF_REQ UNION ALL SELECT * FROM :OLDCONF_CFM));
-- write TQA of type tqa_type (0 if there are no old OSLD entries, 1 if there are OSLD entries) to table OTQA
    SELECT :check_id as "CheckID", :obj_type as "ObjType", :doc_entry as "DocEntry", :doc_line_num as "DocLineNum", "SchdLine"+1, -- Make SchdLine start from 1
     	   :tqa_type as "TQAType", :item as "ItemCode", :whs as "WhsCode", "Date" as "CfmDate", "CfmQty", "ReqQty"
	FROM :TQA INTO OTQA;
-- Align with the OTQA table. RESULT stores the confirmaion data, but OTQA may only have required data.
	Select Count(*) into resSize From :RESULT;
	IF :resSize = 0 Then
    RESULT = SELECT "Date", "Qty" From :RESULT
    		 UNION ALL
    		 SELECT Distinct TO_DATE("CfmDate"), "CfmQty" FROM OTQA Where "CfmQty" = 0 And "ItemCode" =:item And "WhsCode" = :whs
    		 	And "CheckID" = :check_id;
   	End If;
 -- calculate additional TQA of type 0 when tqa_type is 1 (i.e., there are old OSLD or REQUIREMENT entries)
    IF :tqa_type = 1
    THEN
	    NEWCONF_REQ = SELECT "Date", "ReqQty" as "Qty" FROM :TQA;
	    NEWCONF_CFM = SELECT "Date", "CfmQty" as "Qty" FROM :TQA;
	    CALL ATP_B1_ADD_TQA(:NEWCONF_REQ, :OLDCONF_REQ, ADD_TQA_REQ);
	    CALL ATP_B1_ADD_TQA(:NEWCONF_CFM, :OLDCONF_CFM, ADD_TQA_CFM);
	    TQA_DELTA_TMP = SELECT
	        CASE WHEN cfm."Date" is null THEN req."Date" ELSE cfm."Date" END AS "Date",
	        CASE WHEN cfm."Qty" is null THEN 0 ELSE cfm."Qty" END AS "CfmQty",
	        CASE WHEN req."Qty" is null THEN 0 ELSE req."Qty" END AS "ReqQty"
	        FROM :ADD_TQA_REQ req FULL OUTER JOIN :ADD_TQA_CFM cfm ON req."Date" = cfm."Date";
        TQA_DELTA = CE_PROJECTION(:TQA_DELTA_TMP, [CE_CALC('rownum()', integer) as "SchdLine", "Date", "ReqQty", "CfmQty"]);
	-- write additional TQA of type 0 to table OTQA
		SELECT :check_id as "CheckID", :obj_type as "ObjType", :doc_entry as "DocEntry", :doc_line_num as "DocLineNum", "SchdLine"+1, -- make SchdLine start from 1
	    0 as "TQAType", :item as "ItemCode", :whs as "WhsCode", "Date" as "CfmDate", "CfmQty", "ReqQty"
	    FROM :TQA_DELTA INTO OTQA;
-- TODO: we need a TQA entry even when there is nothing to confirm to be able to delete the old OSLD entries (only necessary when tqa_type=1)
    END IF;
END;

