CREATE PROCEDURE ATP_B4_CHECK_LOCKED(
       IN obj_type NVARCHAR (20),
       IN item NVARCHAR(50),
       IN whs NVARCHAR(8),
       IN check_id_for_recheck INTEGER,
       IN doc_entry INTEGER,
       IN doc_line_num INTEGER,
       IN LINEITEMS ATP_DATE_QTY,
       IN check_type INTEGER,
       IN includePastReceipt TINYINT,
       OUT check_id INTEGER,
       OUT RESULT ATP_DATE_QTY
) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
    
    SELECT * FROM ATP_LOCK WHERE "ItemCode" = :item AND "WhsCode" = :whs FOR UPDATE;

SELECT ATP_CHECK_ID.NEXTVAL INTO check_id FROM DUMMY;

SELECT :check_id as "CheckID", :item as "ItemCode", :whs as "WarehouseCode", "Date", "Qty" FROM :LINEITEMS INTO ATP_CHECKS;
SL = SELECT TO_INT(TO_DATS("Date")) as date, "Qty" as qty FROM :LINEITEMS;

CALL ATP_B2_GATEWAY(:obj_type, :check_id, :item, :whs, 1, :check_id_for_recheck, :doc_entry, :doc_line_num, :SL, :check_type, :includePastReceipt, result);
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
CREATE PROCEDURE ATP_B8_CUMULATE (
IN TIMESERIES ATP_INT_QTY,
OUT CUMULATED ATP_INT_QTY)
LANGUAGE LLANG
SQL SECURITY INVOKER
READS SQL DATA
AS
BEGIN
typedef Int32 DATE_T;
typedef Fixed12<6> QTY_T;
typedef Column<DATE_T> COL_DATE_T;
typedef Column<QTY_T> COL_QTY_T;
typedef Table<DATE_T "DATE", QTY_T "QTY"> DATE_QTY_TABLE_T;
typedef DATE_QTY_TABLE_T TS_T;
Void cumulate(TS_T timeSeries, TS_T & cumulated)
{
    
    
    COL_QTY_T tsQuantities = timeSeries.getColumn<QTY_T>("QTY");
    COL_DATE_T tsDates = timeSeries.getColumn<DATE_T>("DATE");
    COL_QTY_T cuQuantities = cumulated.getColumn<QTY_T>("QTY");
    COL_DATE_T cuDates = cumulated.getColumn<DATE_T>("DATE");
	cuQuantities.setSize(tsQuantities.getSize());
    cuDates.setSize(tsDates.getSize());
    Size row = 0z;
    // copy output table
    while(row < tsQuantities.getSize())
    {
		cuQuantities[row] = tsQuantities[row];
		cuDates[row] = tsDates[row];
		row = row + 1z;
    }
    row = 0z;
    // calculate free atp sets
    QTY_T zeroQty = Fixed12<6>(0);
    QTY_T qty = zeroQty;
    QTY_T deduced = zeroQty;
    while(row < cuQuantities.getSize())
    {
		qty = cuQuantities[row];
		if(qty < zeroQty)
		{
		    cuQuantities[row] = zeroQty;
		    deduced = qty;
		    if(row > 0z)
		    {
			    Size j = row - 1z;
			    while(j >= 0z)
			    {
					QTY_T prev = cuQuantities[j];

					    deduced = qty + prev;
					    if(deduced <= zeroQty)
					    {
							cuQuantities[j] = zeroQty;
							qty = deduced;
					    }
					    else
					    {
							cuQuantities[j] = deduced;
							deduced = zeroQty;
							break;
					    }

					// L cannot make size -1 (would throw arithmetic error)
					if(j == 0z)
					{
						break;
					}
					j = j - 1z;
			    }
		    }
		    if(deduced < zeroQty)
		    {
				cuQuantities[0z] = cuQuantities[0z] + deduced;
		    }
		}
		row = row + 1z;
    }
    // accumulate free atp sets
    QTY_T current = zeroQty;
    row = 0z;
    while(row < cuQuantities.getSize())
    {
		current = current + cuQuantities[row];
		cuQuantities[row] = current;
		row = row + 1z;
    }
}
export Void main(TS_T "timeSeries" timeSeries, TS_T "cumulated" & cumulated)
{
    cumulate(timeSeries, cumulated);
}
END;

-- B1 DEPENDS: AFTER:SP:ATP_B4_CHECK_LOCKED AFTER:SP:ATP_A4_CLEANUP_TQA AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_B9_CHECK (
       IN obj_type NVARCHAR (20),
       IN item NVARCHAR(50), -- Product
       IN whs NVARCHAR(8), -- Warehouse
       IN date DATE,
       IN qty DECIMAL(21,6),
       IN concurrency_strategy VARCHAR(255), -- `concurrency_strategy` : supported values are `'optimistic'` and `'locked'`
       IN check_id_for_recheck INTEGER, -- check_id of previous check in the same transaction (0 for first check)
       IN doc_entry INTEGER, -- only needed for recheck (0 for first check)
       IN doc_line_num INTEGER, -- only needed for recheck (0 for first check)
       IN check_type INTEGER, -- `check_type` : supported values are 1 (=check against required quantities) and 2 (=check against confirmed quantities)
       IN includePastReceipt TINYINT -- 0: Exclude, 1: Include
       -- check_id of lines in table `TEMPORARY_QUANTITY_ASSIGNMENTS`
       --(needed to remove TQAs when order is added and for recheck in same transaction
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
check_id INTEGER;
BEGIN
    CALL ATP_A4_CLEANUP_TQA(3600); -- deletes all TQA that are older than 1 hour
	LINEITEMS = SELECT :date as "Date", :qty as "Qty" FROM DUMMY;
    CALL ATP_B4_CHECK_LOCKED(:obj_type, :item, :whs, :check_id_for_recheck, :doc_entry, :doc_line_num, :LINEITEMS, :check_type, :includePastReceipt, check_id, RESULT);
    SELECT :check_id as "CheckID", "Date", "Qty" FROM :RESULT;
END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_C0_ADD_CONFIRMATIONS(
IN check_id INTEGER,
IN doc_entry INTEGER, -- only used when initial in OTQA
IN doc_line_num INTEGER -- only used when DocEntry is initial in OTQA
)

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
tqa_type SMALLINT;
obj_type NVARCHAR(20);
-- to be used when user accepts the check result
-- copy TQA from OTQA to OSLD, delete TQA
BEGIN
-- if there are TQAs of types 0 and 1, we copy only type 1
	SELECT max("TQAType") INTO tqa_type FROM OTQA WHERE "CheckID" = :check_id;
-- delete existing confirmations (new confirmations replace the existing ones)
	DELETE FROM OSLD WHERE ("ObjType","DocEntry", "DocLineNum") IN
	(SELECT DISTINCT "ObjType","DocEntry", "DocLineNum" FROM OTQA WHERE "CheckID" = :check_id AND "TQAType" = :tqa_type);
    SELECT OSLD_S.NEXTVAL as "AbsEntry", "ObjType",
    CASE WHEN "DocEntry" = 0 THEN :doc_entry ELSE "DocEntry" END as "DocEntry",
    CASE WHEN "DocEntry" = 0 THEN :doc_line_num ELSE "DocLineNum" END as "DocLineNum",
    "SchdLine", "ItemCode", "WhsCode", "CfmDate", "CfmQty", 'N' as "FixedCfm", "ReqQty"
    FROM OTQA WHERE "CheckID" = :check_id AND "TQAType" = :tqa_type AND "CfmQty" != 0 INTO OSLD;
    DELETE FROM OTQA WHERE "CheckID" = :check_id;

END;

