-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_C5_READ_DONATORS(
	OUT num_recheck smallint, -- number of lines of table DONATORS (needed for FOR loop)
	OUT DONATORS ATP_T_DONATORS, -- existing confirmations of the donating orders enriched by donated quantity
	OUT NUMB_RECHECK ATP_T_NUMB_RECHECK, -- order lines of donating orders that are to be checked again
	OUT STABLE_CONF ATP_T_DONATORS -- confirmations of donating orders that remain unchanged
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
-- read data of donating orders
-- calculate confirmations of donating orders that remain unchanged
BEGIN
	DONATORS = SELECT d."ObjType", d."DocEntry", d."DocLineNum", o."SchdLine", TO_DATE(d."CfmDate") as "CfmDate", cast(o."CfmQty" as DECIMAL(21,6)) as "CfmQty",
					  Case When d."DonQty" <= o."CfmQty" Then d."DonQty" Else cast(o."CfmQty" as DECIMAL(21,6)) End as "DonQty"
	           FROM OSLD o, ODON d
	           WHERE o."ObjType" = d."ObjType" And
	           		o."DocEntry" = d."DocEntry" And
	           		o."DocLineNum" = d."DocLineNum" And
	           		o."ItemCode" = d."ItemCode" And
	           		o."WhsCode" = d."WhsCode" And
	           		o."CfmDate" = d."CfmDate"
	            order by "SequenceID" asc;
	-- get the documnet lines which need recheck
	RECHECK = SELECT "ObjType", "DocEntry", "DocLineNum"
	          FROM :DONATORS GROUP BY "ObjType", "DocEntry", "DocLineNum";
	-- get a row number for the documnet lines need recheck
	NUMB_RECHECK = CE_PROJECTION(:RECHECK,[CE_CALC('rownum()', smallint) as "Counter", "ObjType", "DocEntry","DocLineNum"]);
	SELECT COUNT(*) INTO num_recheck FROM :NUMB_RECHECK;
	-- get the OSLD records those need recheck
	DONATOR_CONF = SELECT o."ObjType", o."DocEntry", o."DocLineNum", o."ItemCode", o."WhsCode", TO_DATE(o."CfmDate") as "CfmDate"
					FROM OSLD o, :RECHECK r
					WHERE o."ObjType" = r."ObjType" And o."DocEntry" = r."DocEntry" AND o."DocLineNum" = r."DocLineNum";
	UNTOUCHED_CONF = SELECT "ObjType", "DocEntry", "DocLineNum", "ItemCode", "WhsCode", TO_DATE("CfmDate") as "CfmDate" FROM :DONATOR_CONF
					 Except
					 SELECT "ObjType", "DocEntry", "DocLineNum", "ItemCode", "WhsCode", TO_DATE("CfmDate") as "CfmDate" FROM ODON;
	STABLE_CONF = (SELECT "ObjType", "DocEntry", "DocLineNum", "SchdLine", TO_DATE("CfmDate") as "CfmDate", cast("CfmQty" - "DonQty" as DECIMAL(21,6)) as "CfmQty", 0 as "DonQty"
	               FROM :DONATORS WHERE "DonQty" < "CfmQty")
	              UNION ALL
	              (SELECT o."ObjType", o."DocEntry", o."DocLineNum", o."SchdLine", TO_DATE(o."CfmDate") as "CfmDate", o."CfmQty", 0 as "DonQty"
	               FROM OSLD o, :UNTOUCHED_CONF u
	               WHERE o."ObjType" = u."ObjType" And o."DocEntry"=u."DocEntry" And o."DocLineNum"=u."DocLineNum" And
	               		 o."ItemCode" = u."ItemCode" And o."WhsCode" = u."WhsCode" And o."CfmDate"=u."CfmDate");
END;

-- B1 DEPENDS: AFTER:SP:ATP_B1_ADD_TQA AFTER:SP:ATP_A3_EXISTING_REQUIREMENTS AFTER:SP:ATP_A8_AGG_TIME_SERIES AFTER:SP:ATP_C5_READ_DONATORS AFTER:SP:ATP_A9_CANDALGO AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:SP:ATP_C2_QTY_WORKAROUND AFTER:PT:PROCESS_END


CREATE PROCEDURE ATP_C6_RESCHEDULE_GATEWAY(
       IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
       IN obj_type NVARCHAR(20), -- ObjType of winner
       IN doc_entry INTEGER, -- DocEntry of winner
       IN doc_line_num INTEGER, -- DocLineNum of winner
       IN item NVARCHAR(50), -- Product
       IN whs NVARCHAR(8), -- Warehouse
       IN date DATE, -- requested date of winner
       IN qty DECIMAL(21,6), -- requested quantity of winner
       IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
       IN includePastReceipt TINYINT,
       OUT RESULT OTQA
       )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	-- recheck one order (called "winner") that has not got a full confirmation after taking back
	-- confirmations of orders in table ODON (called "donators")
	-- donators are rechecked afterwards
	check_id INTEGER;
	i SMALLINT;
	num_recheck SMALLINT;
	confirmations_size INTEGER;
	available_qty DECIMAL(21,6);
	don_obj_type NVARCHAR(20);
	don_doc_entry INTEGER;
	don_doc_line_num INTEGER;
	doc_line_ReqQty DECIMAL(21,6);
BEGIN
	DELETE FROM OTQA WHERE "CheckID" = :check_id_for_recheck;
	SELECT ATP_CHECK_ID.NEXTVAL INTO check_id FROM DUMMY;
	-- TODO: replace SELECT ... FROM DUMMY INTO by INSERT
	SELECT :check_id as "CheckID", :item as "ItemCode", :whs as "WarehouseCode", :date as "Date", :qty as "Qty"
	FROM DUMMY INTO ATP_CHECKS;
	-- workaround because of bug 13906 (see details in comments of procedure)
	CALL ATP_C2_QTY_WORKAROUND(:date, :qty, LINEITEMS);
	
	-- process donators
	CALL ATP_C5_READ_DONATORS(num_recheck, DONATORS, NUMB_RECHECK, STABLE_CONF);
	-- read planned goods receipts and issues
	-- explicitly check against confirmed quantity (2) chosen
	CALL ATP_A8_AGG_TIME_SERIES (:item, :whs, :obj_type, :doc_entry, :doc_line_num, 2, :includePastReceipt, doc_lines, TS);
	CALL ATP_E0_RECORD_LINES_VERSIONS(:doc_lines);
	-- take confirmations of donators out of the time series
	TIMESERIES = SELECT TO_INT(TO_DATS("Date")) as date, cast(SUM("Qty") as DECIMAL(21,6)) as qty
				 FROM (
				 		(SELECT "CfmDate" as "Date", "DonQty" as "Qty" FROM :DONATORS)
				 		UNION ALL
				 		(SELECT * FROM :TS)
				 )
	             GROUP BY "Date" ORDER BY "Date";
	-- execute ATP check for "winner"
	CALL ATP_A9_CANDALGO(:TIMESERIES, :LINEITEMS, CONFIRMATIONS); -- call of the L routine that does the ATP check
	IF :check_strategy = 'O' THEN
		-- keep earliest delivery only
		CONFIRMATIONS = SELECT Date, Qty FROM :CONFIRMATIONS Where Date = To_Int(TO_Dats(:Date));
	ELSEIF :check_strategy = 'C'   THEN
		-- complete delivery (at latest delivery date)
		CONFIRMATIONS = SELECT MAX(date) as Date, cast(SUM(qty) as DECIMAL(21,6)) as Qty FROM :CONFIRMATIONS;
		Select Qty into available_qty From :CONFIRMATIONS;
		If :available_qty < :Qty Then
			-- Future receipt couldn't satisfy the requirement of the current document line
			-- According to "Complete" strategy, the document line should donate all it has acquired
			CONFIRMATIONS = Select Date, Qty From :CONFIRMATIONS Where 1 <> 1;
		END IF;
	ELSE
		-- normal case: keep confirmations as they are
		CONFIRMATIONS = SELECT Date, Qty  FROM :CONFIRMATIONS;
	END IF;
	ALL_CONFIRMATIONS = SELECT :obj_type AS "ObjType", :doc_entry as "DocEntry", :doc_line_num as "DocLineNum",
			TO_DATE(TO_NCHAR(date)) as "CfmDate", qty as "CfmQty" FROM :CONFIRMATIONS;
	TIMESERIES = SELECT date, cast(SUM(qty) as DECIMAL(21,6)) as qty
				 FROM (
				 		(SELECT date, qty*(-1) as qty FROM :CONFIRMATIONS)
						UNION ALL
						(SELECT * FROM :TIMESERIES)
				)
				GROUP BY date ORDER BY date;
-- recheck donators
	FOR i IN 0 .. num_recheck - 1 DO
          SELECT "ObjType", "DocEntry", "DocLineNum" INTO don_obj_type, don_doc_entry, don_doc_line_num
          FROM :NUMB_RECHECK WHERE "Counter" = :i;
          CALL ATP_A3_EXISTING_REQUIREMENTS(:don_obj_type, :don_doc_entry, :don_doc_line_num, :item, :whs, DON_REQ_QTY,DON_CFM_QTY);
          -- local version of timeseries for this iteration, which includes the reserved qtys of this donator (we dont want to block his own qty)
          ITERATION_TIMESERIES = SELECT date, cast(SUM(qty) as DECIMAL(21,6)) as qty
                                FROM ((SELECT TO_INT(TO_DATS("Date")) as DATE, "Qty" as QTY FROM :DON_CFM_QTY)
                                        UNION ALL
                                       (SELECT * FROM :TIMESERIES)
                                        UNION ALL
                                       (SELECT TO_INT(TO_DATS("CfmDate")) as date, "DonQty"*(-1) as qty
                                        FROM :DONATORS
                                        WHERE "ObjType" = :don_obj_type AND "DocEntry" = :don_doc_entry AND "DocLineNum" = :don_doc_line_num))
                                GROUP BY date ORDER BY date;
          DONATOR_REQUIREMENTS = SELECT TO_INT(TO_DATS("Date")) as DATE, "Qty" as QTY FROM :DON_REQ_QTY;
          CALL ATP_A9_CANDALGO(:ITERATION_TIMESERIES, :DONATOR_REQUIREMENTS, CONFIRMATIONS);

		IF :check_strategy = 'O' THEN
			-- keep earliest delivery only
			CONFIRMATIONS = SELECT T0.Date, T0.Qty FROM :CONFIRMATIONS T0, :DONATOR_REQUIREMENTS T1 Where T0.Date = T1.Date;
			select count(*) INTO confirmations_size FROM :CONFIRMATIONS;
			IF :confirmations_size = 0 THEN
				Continue;
			END IF;
	    ELSEIF :check_strategy = 'C'   THEN
			-- complete delivery (at latest delivery date)
			CONFIRMATIONS = SELECT MAX(date) as Date, cast(SUM(qty) as DECIMAL(21,6)) as Qty FROM :CONFIRMATIONS;
			Select Qty into available_qty From :CONFIRMATIONS;
			Select Qty Into doc_line_ReqQty From :DONATOR_REQUIREMENTS;
			If :available_qty < :doc_line_ReqQty Then
				-- Future receipt couldn't satisfy the requirement of the current document line
				-- According to "Complete" strategy, the document line should donate all it has acquired
				Continue;
			END IF;
	    ELSE
			-- normal case: keep confirmations as they are
			CONFIRMATIONS = SELECT Date, Qty  FROM :CONFIRMATIONS;
	    END IF;
		TIMESERIES = (SELECT * FROM :ITERATION_TIMESERIES)
					UNION ALL
					(SELECT date, cast(qty*(-1) as DECIMAL(21,6)) as qty FROM :CONFIRMATIONS);
		-- append confirmations to all_confirmations
		ALL_CONFIRMATIONS = SELECT "ObjType", "DocEntry", "DocLineNum", "CfmDate", cast(sum("CfmQty") as DECIMAL(21,6)) as "CfmQty"
							FROM (
									(SELECT * FROM :ALL_CONFIRMATIONS)
									UNION ALL
									(SELECT :don_obj_type as "ObjType", :don_doc_entry as "DocEntry", :don_doc_line_num as "DocLineNum",
									 TO_DATE(TO_NCHAR(date)) as "CfmDate", qty as "CfmQty"	FROM :CONFIRMATIONS)
							)
							GROUP BY "ObjType", "DocEntry", "DocLineNum", "CfmDate";
END FOR;
	-- create TQA of type 1 (consolidated confirmations of all orders merged with stable confirmations)
	NEW_TQA = SELECT :check_id as "CheckID", "ObjType", "DocEntry", "DocLineNum", "CfmDate", "CfmQty"
    	  FROM :ALL_CONFIRMATIONS;
-- calculate schedule line number
	CONS_TQA = SELECT t1."CheckID", t1."ObjType", t1."DocEntry", t1."DocLineNum", COUNT(*) as "SchdLine" ,
	                  1 as "TQAType", :item as "ItemCode", :whs as "WhsCode", TO_DATE(t1."CfmDate") as "CfmDate", t1."CfmQty"
	           FROM :NEW_TQA t1, :NEW_TQA t2
	           WHERE t1."ObjType" = t2."ObjType" AND t1."DocEntry" = t2."DocEntry" AND t1."DocLineNum" = t2."DocLineNum"
	           AND t2."CfmDate" <= t1."CfmDate"
	           GROUP BY t1."CheckID", t1."ObjType", t1."DocEntry", t1."DocLineNum",  t1."CfmDate", t1."CfmQty";
      -- write TQA of type 1 to DB table
	SELECT *, 0 as "ReqQty" FROM :CONS_TQA INTO OTQA;
     -- we need a TQA entry for the donators even when there is nothing to confirm to be able to delete the OSLD entries
      -- of the donator
	Insert Into OTQA
		SELECT :check_id as "CheckID", "ObjType", "DocEntry", "DocLineNum", 0 as "SchdLine", 1 as "TQAType",
				:item as "ItemCode", :whs as "WhsCode", '19000101' as "CfmDate", 0 as "CfmQty", 0 as "ReqQty"
		FROM :NUMB_RECHECK
		Where ("ObjType", "DocEntry", "DocLineNum") Not In (Select Distinct "ObjType", "DocEntry", "DocLineNum" From :NEW_TQA);
	---------------------------------------------------------------
	-- calculate output which return all TQA of type 1
	RESULT = Select * from OTQA where "CheckID" = :check_id;
	---------------------------------------------------------------
-- delta calculation of cfm qty calculate TQA of type 0 (additional TQA that need to be seen by other transactions) and write them to DB table OTQA
      NEW_TQA_GROUPED_BY_DAY = SELECT "CfmDate" as "Date", SUM("CfmQty") as "Qty"
                    FROM :NEW_TQA
                    GROUP BY "CfmDate";
      OLDCONF = SELECT o."CfmDate" as "Date", SUM(o."CfmQty") as "Qty"
                   FROM OSLD o JOIN :ALL_CONFIRMATIONS c
                   ON (o."ObjType" = c."ObjType" AND o."DocEntry" = c."DocEntry" AND o."DocLineNum" = c."DocLineNum")
                   GROUP BY o."CfmDate";
      CALL ATP_B1_ADD_TQA(:NEW_TQA_GROUPED_BY_DAY, :OLDCONF, ADD_TQA);
-- delta calculation of req qty
	NEWCONF_REQ = SELECT :date as "Date", :qty as "Qty" FROM DUMMY;
	CALL ATP_A3_EXISTING_REQUIREMENTS(:obj_type, :doc_entry, :doc_line_num, :item, :whs, OLDCONF_REQ, OLDCONF_CFM);
	CALL ATP_B1_ADD_TQA(:NEWCONF_REQ, :OLDCONF_REQ, ADD_TQA_REQ);
-- merge cfm qty with req qty & write OTQA
	OTQA_TEMP = SELECT
		:check_id as "CheckID",
		-- not needed
		0 as "ObjType",
		0 as "DocEntry",
		0 as "DocLineNum",
		0 as "TQAType",
		:item as "ItemCode",
		:whs as "WhsCode",
		CASE WHEN c."Date" is null THEN r."Date" ELSE c."Date" END as "CfmDate",
		CASE WHEN c."Qty" is null THEN 0 ELSE c."Qty" END as "CfmQty",
		CASE WHEN r."Qty" is null THEN 0 ELSE r."Qty" END AS "ReqQty"
	FROM :ADD_TQA c FULL OUTER JOIN :ADD_TQA_REQ r ON c."Date" = r."Date";
	OTQA = CE_PROJECTION(:OTQA_TEMP,
	["CheckID", "ObjType", "DocEntry", "DocLineNum", CE_CALC('rownum()', smallint) as "SchdLine",
	 "TQAType", "ItemCode", "WhsCode", "CfmDate", "CfmQty", "ReqQty"
	]);
	SELECT "CheckID", "ObjType", "DocEntry", "DocLineNum", "SchdLine" + 1, -- make SchdLine start from 1
	 "TQAType", "ItemCode", "WhsCode", "CfmDate", "CfmQty", "ReqQty"
	 FROM :OTQA INTO OTQA;
END;

-- B1 DEPENDS: AFTER:SP:ATP_C6_RESCHEDULE_GATEWAY AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_C7_RESCHEDULE_LOCKED(
       IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
       IN obj_type NVARCHAR (20),
       IN doc_entry INTEGER,
       IN doc_line_num INTEGER,
       IN item NVARCHAR(50), -- Product
       IN whs NVARCHAR(8), -- Warehouse
       IN date DATE,
       IN qty DECIMAL(21,6),
       IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
       IN includePastReceipt TINYINT,
       OUT RESULT OTQA
       )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	SELECT * FROM ATP_LOCK WHERE "ItemCode" = :item AND "WhsCode" = :whs FOR UPDATE;
 	CALL ATP_C6_RESCHEDULE_GATEWAY(:check_id_for_recheck, :obj_type, :doc_entry, :doc_line_num, :item, :whs, :date, :qty, :check_strategy, :includePastReceipt, RESULT);
END;

-- B1 DEPENDS: AFTER:SP:ATP_C6_RESCHEDULE_GATEWAY AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_C8_RESCHEDULE_OPTIMISTIC(
       IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
       IN obj_type NVARCHAR (20),
       IN doc_entry INTEGER,
       IN doc_line_num INTEGER,
       IN item NVARCHAR(50), -- Product
       IN whs NVARCHAR(8), -- Warehouse
       IN date DATE,
       IN qty DECIMAL(21,6),
       IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
       IN includePastReceipt TINYINT,
       OUT RESULT OTQA
       )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	commit_id INT := 0;
BEGIN
	-- under construction!!!
	  CALL ATP_C6_RESCHEDULE_GATEWAY(:check_id_for_recheck, :obj_type, :doc_entry, :doc_line_num, :item, :whs, :date, :qty, :check_strategy, :includePastReceipt, RESULT);
	  SELECT MAX(COMMIT_ID) INTO commit_id FROM TRANSACTION_HISTORY
	  WHERE COMMIT_ID < (SELECT LAST_COMMIT_ID FROM M_TRANSACTIONS WHERE CONNECTION_ID = CURRENT_CONNECTION AND PORT like '%03');
	  EXEC('SET HISTORY SESSION TO COMMIT ID ' || :commit_id);
	  CALL ATP_C6_RESCHEDULE_GATEWAY(:check_id_for_recheck, :obj_type, :doc_entry, :doc_line_num, :item, :whs, :date, :qty, :check_strategy, :includePastReceipt, RESULT);
END;

-- B1 DEPENDS: AFTER:SP:ATP_C7_RESCHEDULE_LOCKED AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_C9_RESCHEDULE(
       IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
       IN obj_type NVARCHAR (20),
       IN doc_entry INTEGER,
       IN doc_line_num INTEGER,
       IN item NVARCHAR(50), -- Product
       IN whs NVARCHAR(8), -- Warehouse
       IN date DATE,
       IN qty DECIMAL(21,6),
       IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
       IN includePastReceipt TINYINT,
       IN concurrency_strategy VARCHAR(255) -- `concurrency_strategy` : supported values are `'optimistic'` and `'locked'`
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	IF :concurrency_strategy = 'optimistic'
 	THEN
 		-- optimistic procedure is still under construction, we use locked version instead
  		CALL ATP_C8_RESCHEDULE_OPTIMISTIC(:check_id_for_recheck, :obj_type, :doc_entry, :doc_line_num, :item, :whs, :date, :qty, :check_strategy, :includePastReceipt, RESULT);
 	ELSE
  		CALL ATP_C7_RESCHEDULE_LOCKED(:check_id_for_recheck, :obj_type, :doc_entry, :doc_line_num, :item, :whs, :date, :qty, :check_strategy, :includePastReceipt, RESULT);
 	END IF;
 	SELECT "CheckID","ObjType","DocEntry","DocLineNum",
 		"SchdLine","TQAType",
 	"ItemCode","WhsCode","CfmDate","CfmQty" FROM :RESULT ORDER BY "DocEntry", "CfmDate"; -- sorting is only for test

END;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
Create Procedure ATP_D0_GetItemTQA(In ItemCode NVarChar(50))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
Begin
	Select T0."CheckID",
		T0."ObjType",
		T0."DocEntry",
		T0."DocLineNum",
		T0."SchdLine",
		T0."TQAType",
		T0."ItemCode",
		T0."WhsCode",
		T1."WhsName",
		T0."CfmDate",
		T0."CfmQty",
		T0."ReqQty"
-- it is not necessary to add the transaction time, we can use time travel to get this information
       From OTQA T0 Join OWHS T1 on T0."WhsCode" = T1."WhsCode"
       Where T0."ItemCode" = :ItemCode;
End;

-- B1 DEPENDS: AFTER:SP:ATP_A0_CREATE_DB_TYPES AFTER:PT:PROCESS_END
Create Procedure ATP_D1_GETTQA_BY_CHECKID(In CheckID Integer)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
Begin
	Select T0."CheckID",
       	T0."CfmDate",
       	T0."CfmQty",
       	T0."TQAType",
       	T0."ReqQty",
		T0."ObjType",
		T0."DocEntry",
		T0."DocLineNum",
		T0."SchdLine",
		T0."ItemCode",
		T0."WhsCode",
		T1."WhsName"
-- it is not necessary to add the transaction time, we can use time travel to get this information
       From OTQA T0 Join OWHS T1 on T0."WhsCode" = T1."WhsCode"
       Where T0."CheckID" = :CheckID;
End;

-- B1 DEPENDS: AFTER:SP:ATP_A8_AGG_TIME_SERIES AFTER:SP:ATP_A9_CANDALGO AFTER:SP:ATP_B1_ADD_TQA AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_D6_GENERAL_RESCHEDULE_GATEWAY (
	IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
	IN item NVARCHAR(50), -- Product
	IN whs NVARCHAR(8), -- Warehouse
	IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
	IN includePastReceipt TINYINT,
	OUT check_id INTEGER,
	OUT result OTQA
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
-- A general rescheduling algorithm
AS
	i SMALLINT;
	confirmations_size INTEGER;
	available_qty DECIMAL(21,6);
	-- assume TIMESERIES variable
	CURSOR it1 FOR
		SELECT "date" as "Date", "CanQty" as "Qty", "DocEntry", "DocLineNum", "ObjType"
		FROM OCAN
		ORDER BY "SequenceID" ASC;
BEGIN
	DELETE FROM OTQA WHERE "CheckID" = :check_id_for_recheck;
	SELECT ATP_CHECK_ID.NEXTVAL INTO check_id FROM DUMMY;
	-- The donators are all the entries in the OCAN table
	DONATORS = SELECT o."ObjType", o."DocEntry", o."DocLineNum", "SchdLine", "CfmDate", "CfmQty","CanQty"
			   FROM OSLD o, OCAN oc
			   WHERE o."ObjType" = oc."ObjType" AND o."DocEntry" = oc."DocEntry" AND o."DocLineNum" = oc."DocLineNum";
	-- SELECT * FROM :DONATORS;
	-- read planned goods receipts and issues - for general rescheduling we might also reschedule
	-- the current doc entry so we do not need to exclude it from our query of OSLD
	-- explicitly check against confirmed quantity (2)
	CALL ATP_A8_AGG_TIME_SERIES (:item, :whs, '-1', 0, 0, 2, :includePastReceipt, doc_lines, TS);
	CALL ATP_E0_RECORD_LINES_VERSIONS(:doc_lines);
	-- take confirmations of donators out of the time series
	TIMESERIES = SELECT TO_INT(TO_DATS("Date")) as date, SUM("Qty") as qty FROM
				 ((SELECT "CfmDate" as "Date", "CfmQty" as "Qty" FROM :DONATORS) UNION ALL (SELECT * FROM :TS))
				 GROUP BY "Date" ORDER BY "Date";
	--SELECT * FROM :TIMESERIES;
	-- create empty variable to capture new confirmations
	NEW_CONF =
		SELECT "ObjType", "DocEntry", "DocLineNum", "date" as "CfmDate", "CanQty" as "CfmQty"
		FROM OCAN
		WHERE 1 <> 1;
	-- loop OCAN
	FOR cur_row as it1 DO
		-- get current lineitems
		-- somehow, here, the cursor cannot find the right types, so we explicitly specify them here
		LINEITEMS = SELECT TO_INT(TO_DATS(cur_row."Date")) as Date, TO_DECIMAL(cur_row."Qty", 21, 6) as Qty FROM DUMMY;
		-- ATP check
		CALL ATP_A9_CANDALGO(:TIMESERIES, :LINEITEMS, CONFIRMATIONS); -- call of the L routine that does the ATP check

		IF :check_strategy = 'O' THEN
			-- keep earliest delivery only
			CONFIRMATIONS = SELECT Date, Qty FROM :CONFIRMATIONS Where date = TO_INT(TO_DATS(cur_row."Date"));
			select count(*) INTO confirmations_size FROM :CONFIRMATIONS;
			IF :confirmations_size = 0 THEN
				Continue;
			END IF;
	    ELSEIF :check_strategy = 'C'   THEN
			-- complete delivery (at latest delivery date)
			CONFIRMATIONS = SELECT MAX(date) as Date, cast(SUM(qty) as DECIMAL(21,6)) as Qty FROM :CONFIRMATIONS;
			Select Qty into available_qty From :CONFIRMATIONS;
			If :available_qty IS NULL OR :available_qty < cur_row."Qty" Then
				-- Future receipt couldn't satisfy the requirement of the current document line
				-- According to "Complete" strategy, the document line should donate all it has acquired
				Continue;
			END IF;
	    ELSE
			-- normal case: keep confirmations as they are
			CONFIRMATIONS = SELECT Date, Qty  FROM :CONFIRMATIONS;
	    END IF;
		-- timeseries for next calculation
		TIMESERIES = SELECT date, SUM(qty) as qty FROM
					((SELECT Date, Qty FROM :TIMESERIES) UNION ALL (SELECT Date, -Qty FROM :CONFIRMATIONS))
					GROUP BY date ORDER BY date;
	    -- add to new confirmations
		NEW_CONF = (SELECT * FROM :NEW_CONF)
				   UNION ALL
				   SELECT cast(cur_row."ObjType" as nvarchar(20)), cur_row."DocEntry", cur_row."DocLineNum", TO_DATE(TO_NCHAR(date)) AS "CfmDate", cast(qty as DECIMAL(21,6)) as "CfmQty"
				   FROM :CONFIRMATIONS;
	END FOR;
	TQA = SELECT :check_id as "CheckID", "ObjType", "DocEntry", "DocLineNum", :item as "ItemCode", :whs as "WhsCode", "CfmDate", "CfmQty"
	      FROM :NEW_CONF;
	-- calculate schedule lines
	CONS_TQA = SELECT t1."CheckID", t1."ObjType", t1."DocEntry", t1."DocLineNum", COUNT(*) as "SchdLine" ,
	                  1 as "TQAType", :item as "ItemCode", :whs as "WhsCode", TO_DATE(t1."CfmDate") as "CfmDate", t1."CfmQty"
	           FROM :TQA t1, :TQA t2
	           WHERE t1."ObjType" = t2."ObjType" AND t1."DocEntry" = t2."DocEntry" AND t1."DocLineNum" = t2."DocLineNum"
	           AND t2."CfmDate" <= t1."CfmDate"
	           GROUP BY t1."CheckID", t1."ObjType", t1."DocEntry", t1."DocLineNum",  t1."CfmDate", t1."CfmQty";
	-- write TQAs with type 1
	SELECT *, 0 as "ReqQty"
	FROM :CONS_TQA INTO OTQA;
	-- we need a TQA entry for the donators even when there is nothing to confirm to be able to delete the OSLD entries
	-- of the donator
	SELECT DISTINCT :check_id as "CheckID", r."ObjType", r."DocEntry", r."DocLineNum", 0 as "SchdLine",
			1 as "TQAType", :item as "ItemCode", :whs as "WhsCode", '19000101' as "CfmDate", 0 as "CfmQty", 0 as "ReqQty"
	FROM :DONATORS r LEFT OUTER JOIN :TQA t
	ON r."ObjType" = t."ObjType" AND r."DocEntry" = t."DocEntry" AND r."DocLineNum" = t."DocLineNum"
	WHERE t."DocEntry" is null INTO OTQA;
	-- calculate result
	-- RESULT should includes the new scheduled lines and also the lines without scheduled data.
	-- If there are not enough items in time-series, some document lines may get no scheduled data.
	-- The OTQA table stores no delta data so far.
	RESULT = SELECT * FROM OTQA Where "CheckID" = :check_id;
	-- calculate delta
	NEWCONF = SELECT "CfmDate" as "Date", SUM("CfmQty") as "Qty" FROM :NEW_CONF GROUP BY "CfmDate";
	OLDCONF = SELECT "CfmDate" as "Date", SUM("CfmQty") as "Qty" FROM :DONATORS GROUP BY "CfmDate";
	CALL ATP_B1_ADD_TQA(:NEWCONF, :OLDCONF, ADD_TQA);
	-- write TQAs with type 0
	SELECT :check_id as "CheckID", '' as "ObjType", 0 as "DocEntry", 0 as "DocLineNum", "Counter" as "SchdLine",
	       0 as "TQAType", :item as "ItemCode", :whs as "WhsCode", "Date" as "CfmDate", "Qty" as "CfmQty", 0 as "ReqQty"
	FROM :ADD_TQA INTO OTQA;
END;

-- B1 DEPENDS: AFTER:SP:ATP_D6_GENERAL_RESCHEDULE_GATEWAY AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_D7_GENERAL_RESCHEDULE_LOCKED(
       IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
       IN item NVARCHAR(50), -- Product
       IN whs NVARCHAR(8), -- Warehouse
       IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
       IN includePastReceipt TINYINT,
       OUT check_id INTEGER,
       OUT RESULT OTQA
       )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
      SELECT * FROM ATP_LOCK WHERE "ItemCode" = :item AND "WhsCode" = :whs FOR UPDATE;
     CALL ATP_D6_GENERAL_RESCHEDULE_GATEWAY(:check_id_for_recheck, :item, :whs, :check_strategy, :includePastReceipt, check_id, RESULT);
END;

-- B1 DEPENDS: AFTER:SP:ATP_D7_GENERAL_RESCHEDULE_LOCKED AFTER:PT:PROCESS_END

CREATE PROCEDURE ATP_D9_GENERAL_RESCHEDULE (
      IN check_id_for_recheck INTEGER, -- CheckId of initial check of the order that needs donations
      IN item NVARCHAR(50), -- Product
      IN whs NVARCHAR(8), -- Warehouse
      IN check_strategy NVARCHAR(1),   -- D: Delivery Proposal, O: One-Time, C: Complete
      IN includePastReceipt TINYINT,
      IN concurrency_strategy VARCHAR(255) -- to be removed
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
-- A general rescheduling algorithm
AS
	check_id Integer;
BEGIN
      CALL ATP_D7_GENERAL_RESCHEDULE_LOCKED(:check_id_for_recheck, :item, :whs, :check_strategy, :includePastReceipt, check_id, RESULT);
	  SELECT :check_id as "CheckID", S."ObjType", S."DocEntry", S."DocLineNum",
	  		 IFNULL(R."SchdLine", 0) as "SchdLine",
	  		 IFNULL(R."TQAType", 0) as "TQAType",
	   		 :item as "ItemCode", :whs as "WhsCode",
	   		 IFNULL(R."CfmDate", S."date") as "CfmDate",
	   		 IFNULL(R."CfmQty", 0) As "CfmQty"
	      FROM :RESULT R Right Join OCAN S On R."ObjType" = S."ObjType" And R."DocEntry" = S."DocEntry" And R."DocLineNum" = S."DocLineNum"
	      ORDER BY S."SequenceID";
END;

-- B1 DEPENDS: AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

Create Procedure ATP_E0_RECORD_LINES_VERSIONS(
	IN involved_doc_lines DOC_LINES_VERSIONS
	)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
Begin
	Delete From DOC_LINES_VERSIONS;
	Insert Into DOC_LINES_VERSIONS
		Select T0."ObjType", T0."DocEntry", T0."DocLineNum", Max(T1."MessageID")
			From :involved_doc_lines T0 JOIN (SELECT cast("TransType" as nvarchar(20)) as "TransType", "DocEntry", "DocLineNum", "MessageID" FROM OILM) T1 On T0."ObjType" = T1."TransType" And T0."DocEntry"=T1."DocEntry" And T0."DocLineNum"=T1."DocLineNum"
			Group By T0."ObjType", T0."DocEntry", T0."DocLineNum";
End;

-- B1 DEPENDS: AFTER:SP:ATP_A1_CREATE_DB_OBJECTS AFTER:PT:PROCESS_END

Create Procedure ATP_E1_CHECK_LINES_VERSIONS()
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
rec_size Integer;
changed TinyInt;
Begin
		-- Check the update of Documetn Lines Versions
	VersionDiff = Select T0."ObjType", T0."DocEntry", T0."DocLineNum", Max(T1."MessageID") as "NewVersion"
		From DOC_LINES_VERSIONS T0
		Join (SELECT cast("TransType" as nvarchar(20)) as "TransType", "DocEntry", "DocLineNum", "MessageID" FROM OILM) T1 On T0."ObjType" = T1."TransType" And
						T0."DocEntry" = T1."DocEntry" And
						T0."DocLineNum" = T1."DocLineNum"
		Group By T0."ObjType", T0."DocEntry", T0."DocLineNum", T0."Version"
		Having T0."Version" < Max(T1."MessageID");
	Select Count(*) into rec_size From :VersionDiff;
	IF :rec_size > 0 Then
		changed := 1;
	Else
		changed := 0;
	End If;
	Select :changed From Dummy;
End;


	CREATE PROCEDURE B1CFLConsiderHoliday(v_dtIn DATE, v_nvHldCode NVARCHAR(20), out v_dtOut DATE)
	AS
		v_siWndFrm SMALLINT; -- Although OHLD.WndFrm is NVARCHAR(1) !!!
		v_siWndTo SMALLINT; -- Although OHLD.WndTo is NVARCHAR(1) !!!
		v_cIsCurYear NVARCHAR(1);
		v_cIgnrWnd NVARCHAR(1);
		v_siWeekDay SMALLINT;
		v_dtLast DATE;
		l_dtIn DATE;
		v_cnt integer := 0;
BEGIN
	IF IFNULL(:V_NVHLDCODE,'') = '' THEN
		v_dtOut := :V_DTIN;
	ELSE 
		
		select count(*) into v_cnt FROM OHLD WHERE "HldCode" = :V_NVHLDCODE;
		if :V_CNT > 0 then
			SELECT to_smallint("WndFrm"),to_smallint("WndTo"),"isCurYear","ignrWnd" INTO v_siWndFrm, v_siWndTo, 
			v_cIsCurYear,v_cIgnrWnd FROM OHLD WHERE "HldCode" = :V_NVHLDCODE;
		end if;
		v_dtLast := :V_DTIN;
		l_dtIn := :V_DTIN;
		
		WHILE :V_DTLAST is not null do
		
			IF :V_CISCURYEAR = 'Y' then
				select count(*) into v_cnt FROM HLD1 WHERE "HldCode" = :V_NVHLDCODE AND :L_DTIN >= "StrDate" AND :L_DTIN <= "EndDate";
				if :V_CNT > 0 then
					SELECT MAX("EndDate") into v_dtLast FROM HLD1 WHERE "HldCode" = :V_NVHLDCODE AND :L_DTIN >= "StrDate" AND :L_DTIN <= "EndDate";
				else 
					v_dtLast := Null;
				end if;
			ELSE
				select count(*) into v_cnt FROM HLD1
					WHERE "HldCode" = :V_NVHLDCODE AND
					:L_DTIN >= add_months(add_days(to_date(to_varchar(YEAR(:L_DTIN))),EXTRACT (DAY FROM "StrDate") - 1),MONTH("StrDate") - 1) AND
					:L_DTIN <= add_months(add_days(to_date(to_varchar(YEAR(:L_DTIN))),EXTRACT (DAY FROM "EndDate") - 1),MONTH("EndDate") - 1);
				if :V_CNT > 0 then
					SELECT MAX(add_months(add_days(to_date(to_varchar(YEAR(:L_DTIN))),EXTRACT (DAY FROM "EndDate") - 1),MONTH("EndDate") - 1)) INTO v_dtLast FROM HLD1
					WHERE "HldCode" = :V_NVHLDCODE AND
					:L_DTIN >= add_months(add_days(to_date(to_varchar(YEAR(:L_DTIN))),EXTRACT (DAY FROM "StrDate") - 1),MONTH("StrDate") - 1) AND
					:L_DTIN <= add_months(add_days(to_date(to_varchar(YEAR(:L_DTIN))),EXTRACT (DAY FROM "EndDate") - 1),MONTH("EndDate") - 1);
				else 
					v_dtLast := null;
				end if;

			END IF;
			
			IF :V_DTLAST is not null then 
				l_dtIn := ADD_DAYS(:L_DTIN,DAYS_BETWEEN(:L_DTIN, :V_DTLAST) + 1);
			ELSE
				IF :V_CIGNRWND = 'N' then						
					select MAP(WEEKDAY(:L_DTIN),0,2,1,3,2,4,3,5,4,6,5,7,6,1) into v_siWeekDay from dummy;
					IF :V_SIWNDFRM <= :V_SIWNDTO THEN
						IF :V_SIWEEKDAY >= :V_SIWNDFRM AND :V_SIWEEKDAY <= :V_SIWNDTO THEN
							l_dtIn := ADD_DAYS(:L_DTIN,:V_SIWNDTO - :V_SIWEEKDAY + 1);
							v_dtLast := :L_DTIN;
						END IF;
					ELSE
						IF :V_SIWEEKDAY >= :V_SIWNDFRM then
							l_dtIn := ADD_DAYS(:L_DTIN,8 + :V_SIWNDTO - :V_SIWEEKDAY);
							v_dtLast := l_dtIn;
						ELSE
							IF :V_SIWEEKDAY <= :V_SIWNDTO THEN
								l_dtIn := ADD_DAYS(:L_DTIN, 1 + :V_SIWNDTO - :V_SIWEEKDAY);
								v_dtLast := :L_DTIN;
							END IF;
						END if;
					END IF;
				END IF;
			END if;
		end while;
		v_dtOut := to_date(:L_DTIN);
	END IF;
END

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE BEM_CLEAR_OLD_DATA ()
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN

UPDATE OBEM SET "Status" = 'E', "RepMessage" = 'Replication time out.'
WHERE "Status" IN ('I', 'R', 'P') AND DAYS_BETWEEN ("UpdateDate", CURRENT_DATE) > 1;

UPDATE BEM1 SET "MDStatus" = 'E', "RepMessage" = 'Master Data replication time out.'
WHERE "MDStatus" IN ('I', 'R', 'P') AND DAYS_BETWEEN ("UpdMDDate", CURRENT_DATE) > 1;

UPDATE BEM1 SET "ScpStatus" = 'E', "RepMessage" = 'Scope replication time out.'
WHERE "ScpStatus" IN ('I', 'R', 'P') AND DAYS_BETWEEN ("UpdScpDate", CURRENT_DATE) > 1;

DELETE FROM BEM2 WHERE DAYS_BETWEEN ("CreateDate", CURRENT_DATE) > 10;

END;

-- B1 DEPENDS: AFTER:SP:BEM_CLEAR_OLD_DATA AFTER:PT:PROCESS_END

CREATE PROCEDURE BEM_CLEAR_TRANS_REP (
	-- input parameters
	REP_ID NVARCHAR (36)	-- replication id from bem, all data in BEM2 with this rep will be removed.
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
BEGIN

CALL BEM_CLEAR_OLD_DATA();
DELETE FROM BEM2 WHERE "RepId" = :REP_ID;

END;

-- B1 DEPENDS: AFTER:SP:BEM_CLEAR_TRANS_REP AFTER:PT:PROCESS_END

CREATE PROCEDURE BEM_PREPARE_TRANS_REP (
	-- input parameters
	REP_ID NVARCHAR (36),			-- replication id from bem
	PERIOD_ENTRY INT				-- AbsEntry in b1 table OBEM
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
BEGIN

DECLARE COUNTER INT;
DECLARE BEM_SCOPE_KEY NVARCHAR (36);	-- scope key
DECLARE START_DATE DATE;				-- start date of the period
DECLARE END_DATE DATE;					-- start date of the period
DECLARE BEM_DIMENSION INT;

-- 1. Clear old transaction data in BEM2
CALL BEM_CLEAR_TRANS_REP (:REP_ID);


-- 2. Update LastRepId in OBEM
SELECT COUNT(*) INTO COUNTER FROM OBEM
	WHERE "AbsEntry" = :PERIOD_ENTRY;
		
-- SELECT :COUNTER AS "No. of Periods Found" FROM DUMMY;

IF :COUNTER = 1 THEN
	SELECT "ScopeKey", "StartDate", "EndDate" INTO BEM_SCOPE_KEY, START_DATE, END_DATE
		FROM OBEM
		WHERE "AbsEntry" = :PERIOD_ENTRY;
	UPDATE OBEM SET "LastRepId" = :REP_ID
		WHERE "AbsEntry" = :PERIOD_ENTRY;
	
-- SELECT :BEM_SCOPE_KEY AS "BEM scope key", :START_DATE AS "Start Date", :END_DATE AS "End Date" FROM DUMMY;

-- Set Dimension of BEM
SELECT IFNULL("Dimension", 0) INTO BEM_DIMENSION FROM BEM1;
 
-- 3. Map ItemCode to Standard UOM
CREATE COLUMN TABLE ITEM_UOM AS (
SELECT
	II."ItemCode",
	II."IUoMEntry",
	CASE WHEN II."WeightKGM" > 0 THEN II."WeightKGM"
		WHEN UUU."UomEntry" IS NOT NULL THEN UUU."UomFactor"
		ELSE 1 END AS "UomFactor",
	CASE WHEN II."WeightKGM" > 0 THEN 'KGM'
		WHEN UUU."UomEntry" IS NOT NULL THEN UUU."UomStandard"
		ELSE 'EA' END AS "UomStandard"
FROM
(
	SELECT 
		I."ItemCode",
		I."IUoMEntry",
		(IFNULL(I."IWeight1" * W1."WightInMG", 0) + IFNULL(I."IWeight2" * W2."WightInMG", 0)) / 1000000 AS "WeightKGM" -- / 1000000 to get KG
	FROM OITM I
		LEFT OUTER JOIN OWGT W1
		ON I."IWght1Unit" = W1."UnitCode"
		LEFT OUTER JOIN OWGT W2
		ON I."IWght2Unit" = W2."UnitCode"
) II
LEFT OUTER JOIN
(
	SELECT
		"UomEntry",
		CASE WHEN "WeightKGM" > 0 THEN "WeightKGM"
			WHEN "VolumeInM3" > 0 THEN "VolumeInM3"	
			WHEN "LengthMTR" > 0 AND "WidthMTR" > 0 AND "HeightMTR" > 0 THEN "LengthMTR" * "WidthMTR" * "HeightMTR"	-- 1,1,1
			WHEN "LengthMTR" > 0 AND "WidthMTR" > 0 AND "HeightMTR" = 0 THEN "LengthMTR" * "WidthMTR"					-- 1,1,0
			WHEN "LengthMTR" > 0 AND "WidthMTR" = 0 AND "HeightMTR" > 0 THEN "LengthMTR" * "HeightMTR"					-- 1,0,1
			WHEN "LengthMTR" > 0 AND "WidthMTR" = 0 AND "HeightMTR" = 0 THEN "LengthMTR"								-- 1,0,0
			WHEN "LengthMTR" = 0 AND "WidthMTR" > 0 AND "HeightMTR" > 0 THEN "WidthMTR" * "HeightMTR"					-- 0,1,1
			WHEN "LengthMTR" = 0 AND "WidthMTR" > 0 AND "HeightMTR" = 0 THEN "WidthMTR"								-- 0,1,0
			WHEN "LengthMTR" = 0 AND "WidthMTR" = 0 AND "HeightMTR" > 0 THEN "HeightMTR"								-- 0,0,1
			ELSE 1 END AS "UomFactor",
		CASE WHEN "WeightKGM" > 0 THEN 'KGM'
			WHEN "VolumeInM3" > 0 THEN 'MTQ'	
			WHEN "LengthMTR" > 0 AND "WidthMTR" > 0 AND "HeightMTR" > 0 THEN 'MTQ'	-- 1,1,1
			WHEN "LengthMTR" > 0 AND "WidthMTR" > 0 AND "HeightMTR" = 0 THEN 'MTK'	-- 1,1,0
			WHEN "LengthMTR" > 0 AND "WidthMTR" = 0 AND "HeightMTR" > 0 THEN 'MTK'	-- 1,0,1
			WHEN "LengthMTR" > 0 AND "WidthMTR" = 0 AND "HeightMTR" = 0 THEN 'MTR'	-- 1,0,0
			WHEN "LengthMTR" = 0 AND "WidthMTR" > 0 AND "HeightMTR" > 0 THEN 'MTK'	-- 0,1,1
			WHEN "LengthMTR" = 0 AND "WidthMTR" > 0 AND "HeightMTR" = 0 THEN 'MTR'	-- 0,1,0
			WHEN "LengthMTR" = 0 AND "WidthMTR" = 0 AND "HeightMTR" > 0 THEN 'MTR'	-- 0,0,1
			ELSE 'EA' END AS "UomStandard"
	FROM	
	(
		SELECT
			U."UomEntry",
			(IFNULL(U."Weight1" * W1."WightInMG", 0) + IFNULL(U."Weight2" * W2."WightInMG", 0)) / 1000000 AS "WeightKGM", -- / 1000000 to get KG
			IFNULL(U."Volume" * V."SizeInMM" * V."SizeInMM" * V."SizeInMM", 0) / 1000000000 AS "VolumeInM3", --  / 1000000000 to get M3
			(IFNULL(U."Length1" * LL1."SizeInMM", 0) + IFNULL(U."length2" * LL2."SizeInMM", 0)) / 1000 AS "LengthMTR", -- / 1000 to get MTR
			(IFNULL(U."Width1" * LW1."SizeInMM", 0) + IFNULL(U."Width2" * LW2."SizeInMM", 0)) / 1000 AS "WidthMTR", -- / 1000 to get MTR
			(IFNULL(U."Height1" * LH1."SizeInMM", 0) + IFNULL(U."Height2" * LH2."SizeInMM", 0)) / 1000 AS "HeightMTR" -- / 1000 to get MTR
		FROM OUOM U
		LEFT OUTER JOIN OWGT W1
		ON U."WghtUnit" = W1."UnitCode"
		LEFT OUTER JOIN OWGT W2
		ON U."Wght2Unit" = W2."UnitCode"
		LEFT OUTER JOIN OLGT V
		ON U."VolUnit" = V."UnitCode"
		LEFT OUTER JOIN OLGT LL1
		ON U."Len1Unit" = LL1."UnitCode"
		LEFT OUTER JOIN OLGT LL2
		ON U."Len2Unit" = LL2."UnitCode"
		LEFT OUTER JOIN OLGT LW1
		ON U."Wdth1Unit" = LW1."UnitCode"
		LEFT OUTER JOIN OLGT LW2
		ON U."Wdth2Unit" = LW2."UnitCode"
		LEFT OUTER JOIN OLGT LH1
		ON U."Hght1Unit" = LH1."UnitCode"
		LEFT OUTER JOIN OLGT LH2
		ON U."Hght2Unit" = LH2."UnitCode"
	) UU
) UUU
ON II."IUoMEntry" = UUU."UomEntry"
);


-- 4. Insert Data into BEM2
-- 4-01. 604, Opening Stock
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode") AS "RowNumber",
		'604' AS "BEMDocType",
		'Opening Stock' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		'' AS "VendorCode",
		'' AS "WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (	
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."Quantity" AS "InQty",
				0 AS "OutQty",
				T1."Quantity" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIQI T0
				INNER JOIN IQI1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"Project"
	) GRP		
) IQI;
-- 4-01. 604, Opening Stock, end

-- 4-02. 301, Goods Receipt From Supplier
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode", "VendorCode") AS "RowNumber",
		'301' AS "BEMDocType",
		'Goods Receipt From Supplier' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		"VendorCode",
		'' AS "WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"CardCode" AS "VendorCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- GRPO
			SELECT 
				T0."ObjType",
				T0."CardCode",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OPDN T0
				INNER JOIN PDN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocType" = 'I'
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
			
			UNION ALL
			-- AP Invoice not base on GRPO
			SELECT 
				T0."ObjType",
				T0."CardCode",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OPCH T0
				INNER JOIN PCH1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocType" = 'I' AND T0."isIns" = 'N'
				AND T1."BaseType" <> 20
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"CardCode",			
			"Project"
	) GRP		
) PDNPCH;
-- 4-02. 301, Goods Receipt From Supplier, end

-- 4-03. 343, Goods Return To Supplier
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode", "VendorCode") AS "RowNumber",
		'343' AS "BEMDocType",
		'Goods Return To Supplier' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		"VendorCode",
		'' AS "WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"CardCode" AS "VendorCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- Goods Return
			SELECT 
				T0."ObjType",
				T0."CardCode",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM ORPD T0
				INNER JOIN RPD1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocType" = 'I'
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
				
			UNION ALL
			-- AP Credit Memo with inventory movement
			SELECT 
				T0."ObjType",
				T0."CardCode",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				L."InQty" AS "InQty",
				L."OutQty" AS "OutQty",
				L."OutQty" - L."InQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM ORPC T0
				INNER JOIN RPC1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OIVL L ON T0."ObjType" = L."TransType" AND T0."DocEntry" = L."CreatedBy" 
					AND T1."LineNum" = L."DocLineNum"
			WHERE T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"CardCode",
			"Project"
	) GRP		
) PDNPCH;
-- 4-03. 343, Goods Return To Supplier, end

-- 4-04. 302, Customer Return
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode") AS "RowNumber",
		'302' AS "BEMDocType",
		'Customer Return' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		'' AS "VendorCode",
		'' AS "WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- Return
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM ORDN T0
				INNER JOIN RDN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocType" = 'I'
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE

			UNION ALL
			-- AR Credit Memo with inventory movement
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				L."InQty" AS "InQty",
				L."OutQty" AS "OutQty",
				L."InQty" - L."OutQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM ORIN T0
				INNER JOIN RIN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OIVL L ON T0."ObjType" = L."TransType" AND T0."DocEntry" = L."CreatedBy" 
					AND T1."LineNum" = L."DocLineNum"
			WHERE T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"Project"
	) GRP		
) RDNRIN;
-- 4-04. 302, Customer Return, end

-- 4-05. 341, Goods Issue For Customer
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode") AS "RowNumber",
		'341' AS "BEMDocType",
		'Goods Issue For Customer' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		'' AS "VendorCode",
		'' AS "WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- Delivery
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM ODLN T0
				INNER JOIN DLN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocType" = 'I'
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
			
			UNION ALL
			-- AR Invoice not based on Delivery
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OINV T0
				INNER JOIN INV1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T0."DocType" = 'I' AND T0."isIns" = 'N'
				AND T1."BaseType" <> 15
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"Project"
	) GRP		
) DLNINV;
-- 4-05. 341, Goods Issue For Customer, end

-- 4-06. 344, Goods Issue For Production
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode") AS "RowNumber",
		'344' AS "BEMDocType",
		'Goods Issue For Production' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		'' AS "VendorCode",
		"WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"BaseEntry" AS "WOREntry",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- Goods Issue For Production (Issue Component for Standard and Special)
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGE T0
				INNER JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND (P."Type" = 'S' OR P."Type" = 'P') -- standard or special production order, not disasembly
				AND T1."BaseLine" >= 0 -- production order components
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
			
			UNION ALL
			-- Goods Issue For Production (Issue Parent for Disassembly)
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGE T0
				INNER JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND P."Type" = 'D' -- disassembly production order
				AND (T1."BaseLine" < 0 OR T1."BaseLine" IS NULL) -- disassembly parent
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
			
			UNION ALL
			-- Return Components (Regard these receipt as negative value of issue)
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" * (-1) AS "OutQty",
				0 - T1."InvQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND T1."BaseLine" >= 0 -- production order components
				AND (T1."IsByPrdct" = 'N' OR T1."IsByPrdct" IS NULL) -- not by product item
				AND (P."Type" = 'S' OR P."Type" = 'P') -- standard or special production order, not disasembly
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE

			UNION ALL
			-- Return parent for Disassembly, regard as negative issue component
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" * (-1) AS "OutQty",
				0 - T1."InvQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND P."Type" = 'D' -- disassembly production order
				AND (T1."BaseLine" < 0 OR T1."BaseLine" IS NULL) -- disassembly parent
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"BaseEntry",
			"UomStandard",
			"Project"
	) GRP		
) IGEWOR;
-- 4-06. 344, Goods Issue For Production, end

-- 4-07. 303, Goods Receipt From Production
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode") AS "RowNumber",
		'303' AS "BEMDocType",
		'Goods Receipt From Production' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		'' AS "VendorCode",
		"WOREntry",
		"RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"WhsCode" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"BaseEntry" AS "WOREntry",
			"RoleCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- Goods Receipt From Production, Main Product
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				CASE WHEN T1."IsByPrdct" = 'Y' THEN 'BP'
					ELSE 'MP' END
					AS "RoleCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND ("BaseLine" < 0 OR "BaseLine" is null) -- Parent Item
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
			
			UNION ALL
			-- Goods Receipt From Production, By Product
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				'BP' AS "RoleCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND T1."BaseLine" >= 0 -- production order components
				AND T1."IsByPrdct" = 'Y' -- by product item
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE

			UNION ALL
			-- Disassembly Child, Manual Receipt from Production
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				'MP' AS "RoleCode",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND T1."BaseLine" >= 0 -- production order components
				AND (T1."IsByPrdct" = 'N' OR T1."IsByPrdct" IS NULL) -- not by product item
				AND P."Type" = 'D' -- disassembly production order
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE

			UNION ALL
			-- Disassembly Child, Backflush component, found from OIVL
			SELECT 
				T0."ObjType",
				L."ItemCode",
				L."LocCode" AS "WhsCode",
				T1."BaseEntry",
				'MP' AS "RoleCode",
				IFNULL(T1."Project", '') AS "Project",
				L."InQty",
				L."OutQty",
				L."InQty" - L."OutQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIVL L
				INNER JOIN OIGE T0 ON T0."ObjType" = L."TransType"
					AND T0."DocEntry" = L."CreatedBy"
				INNER JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON L."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE L."InQty" > 0 AND L."OutQty" = 0
				AND T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND (T1."BaseLine" < 0 OR T1."BaseLine" is null) -- backflush of Parent Item
				AND P."Type" = 'D' -- disassembly production order
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE

			UNION ALL
			-- Disassembly Child, Manual return to Production, regard as negative receipt from production
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."BaseEntry",
				'MP' AS "RoleCode",
				IFNULL(T1."Project", '') AS "Project",
				0 AS "InQty",
				T1."InvQty" * (-1) AS "OutQty",
				0 -T1."InvQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OIGE T0
				INNER JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OWOR P ON T1."BaseType" = P."ObjType"
					AND T1."BaseEntry" = P."DocEntry"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 4 -- 4 is for Item
				AND T1."BaseLine" >= 0 -- production order components
				AND (T1."IsByPrdct" = 'N' OR T1."IsByPrdct" IS NULL) -- not by product item
				AND P."Type" = 'D' -- disassembly production order
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"BaseEntry",
			"RoleCode",
			"Project"
	) GRP		
) IGNWOR;
-- 4-07. 303, Goods Receipt From Production


-- 4-08, 403, Internal Service Confirmation
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "RscCode", "WhseCode", "WOREntry") AS "RowNumber",
		'403' AS "BEMDocType",
		'Internal Service Confirmation' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		'' AS "ItemCode",
		"WhseCode",
		'' AS "UomCode",
		"InQty",
		"OutQty",
		0 AS "Quantity",
		'' AS "VendorCode",
		"WOREntry",
		'' AS "RoleCode",
		"RscCode",
		"RscQtySec" / 3600 AS "RscQty",
		'HUR' AS "RscUomCode", -- hour
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"WhsCode" AS "WhseCode",
			"BaseEntry" AS "WOREntry",
			"ResCode" AS "RscCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "TimeResUn") AS "RscQtySec" -- second
		FROM (
			-- Goods Issue For Production, Resource
			SELECT 
				T0."ObjType",
				T1."WhsCode",
				T1."BaseEntry",
				IFNULL(T1."Project", '') AS "Project",
				R."ResCode",
				0 AS "InQty",
				T1."Quantity" AS "OutQty",
				T1."Quantity" - 0 AS "InvQty",
				R."TimeResUn"
			FROM OIGE T0
				INNER JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ORSC R ON T1."ItemCode" = R."ResCode"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 290 -- 290 is for Resource
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
			
			UNION ALL
			-- Return Components, Resource
			SELECT 
				T0."ObjType",
				T1."WhsCode",
				T1."BaseEntry",
				IFNULL(T1."Project", '') AS "Project",
				R."ResCode",
				0 AS "InQty",
				T1."Quantity" * (-1) AS "OutQty",
				0 - T1."Quantity" AS "InvQty",
				R."TimeResUn"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ORSC R ON T1."ItemCode" = R."ResCode"
			WHERE T1."BaseType" = 202 -- 202 is Production Order
				AND T1."ItemType" = 290 -- 290 is for Resource
				AND T0."DocDate" >= :START_DATE AND T0."DocDate" <= :END_DATE
				
		) ORIGIN
		GROUP BY
			"ObjType",
			"WhsCode",
			"BaseEntry",
			"ResCode",
			"Project"
	) GRP		
) RSCWOR;
-- 4-08, 403, Internal Service Confirmation, end

-- 4-09, 381, Goods Transfer
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "ItemCode", "WhseCode", "UomCode", "ToWhseCode") AS "RowNumber",
		'381' AS "BEMDocType",
		'Goods Transfer' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		"ItemCode",
		"WhseCode",
		"UomCode",
		"InQty",
		"OutQty",
		"Quantity",
		'' AS "VendorCode",
		'' AS "WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		"ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"ItemCode",
			"FromWhsCod" AS "WhseCode",
			"UomStandard" AS "UomCode",
			"WhsCode" AS "ToWhseCode",
			"Project",
			SUM("InQty") AS "InQty",
			SUM("OutQty") AS "OutQty",
			SUM("InvQty") AS "InvQty",
			SUM("InvQty" * "UomFactor") AS "Quantity"
		FROM (
			-- Inventory Transfer
			SELECT 
				T0."ObjType",
				T1."ItemCode",
				T1."WhsCode",
				T1."FromWhsCod",
				IFNULL(T1."Project", '') AS "Project",
				T1."InvQty" AS "InQty",
				T1."InvQty" AS "OutQty",
				T1."InvQty" AS "InvQty",
				I."UomFactor",
				I."UomStandard"
			FROM OWTR T0
				INNER JOIN WTR1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
			WHERE T1."WhsCode" <> T1."FromWhsCod"
				AND T1."ActDelDate" >= :START_DATE AND T1."ActDelDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"FromWhsCod",
			"UomStandard",
			"Project"
	) GRP		
) WTR;
-- 4-09, 381, Goods Transfer, end

