				0 AS "OutQty",
				T1."InvQty" - 0 AS "InvQty",
				I."UomFactor",
				I."UomStandard",
				T2."PrcCode" AS "CostCenter",
				CASE WHEN T2."OcrTotal" = 0 THEN 1
					 ELSE T2."PrcAmount" / T2."OcrTotal"
					 END AS "DistRate"
			FROM OIGN T0
				INNER JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry"
				INNER JOIN ITEM_UOM I ON T1."ItemCode" = I."ItemCode"
				INNER JOIN OCR1 T2 ON T2."OcrCode" =  
									  (CASE WHEN :BEM_DIMENSION = 1 THEN T1."OcrCode"
											WHEN :BEM_DIMENSION = 2 THEN T1."OcrCode2"
											WHEN :BEM_DIMENSION = 3 THEN T1."OcrCode3"
											WHEN :BEM_DIMENSION = 4 THEN T1."OcrCode4"
											WHEN :BEM_DIMENSION = 5 THEN T1."OcrCode5"
											ELSE ''
										END)
			WHERE (T1."BaseType" <> 202 OR T1."BaseType" IS NULL)
				AND (CASE WHEN :BEM_DIMENSION = 1 THEN IFNULL(T1."OcrCode", '')
						  WHEN :BEM_DIMENSION = 2 THEN IFNULL(T1."OcrCode2", '')
						  WHEN :BEM_DIMENSION = 3 THEN IFNULL(T1."OcrCode3", '')
						  WHEN :BEM_DIMENSION = 4 THEN IFNULL(T1."OcrCode4", '')
						  WHEN :BEM_DIMENSION = 5 THEN IFNULL(T1."OcrCode5", '')
						  ELSE ''
					 END) <> ''
				AND T1."DocDate" >= :START_DATE AND T1."DocDate" <= :END_DATE
		) ORIGIN
		GROUP BY
			"ObjType",
			"ItemCode",
			"WhsCode",
			"UomStandard",
			"CostCenter"
	) GRP		
) WTR;
-- 4-15, 306, Goods Return From Cost Center, end

-- 4-16, PRODUCTION_DOCUMENT, Production Document
INSERT INTO BEM2 SELECT
	"RowNumber", "BEMDocType", "BEMDocName", "ScopeKey", "RepId",
	"StartDate", "EndDate", "CreateDate", "B1ObjCode",
	"ItemCode", "WhseCode", "UomCode",
	"InQty", "OutQty", "Quantity",
	"VendorCode", "WOREntry", "RoleCode",
	"RscCode", "RscQty", "RscUomCode",
	"Project", "ToWhseCode", "CostCenter"
FROM (
	SELECT ROW_NUMBER() OVER 
		(ORDER BY "WOREntry", "WhseCode", "Project") AS "RowNumber",
		'0' AS "BEMDocType",
		'Production Document' AS "BEMDocName",
		:BEM_SCOPE_KEY AS "ScopeKey",
		:REP_ID AS "RepId",
		:START_DATE AS "StartDate",
		:END_DATE AS "EndDate",
		CURRENT_DATE AS "CreateDate",
		"B1ObjCode",
		'' AS "ItemCode",
		"WhseCode",
		'' AS "UomCode",
		0 AS "InQty",
		0 AS "OutQty",
		0 AS "Quantity",
		'' AS "VendorCode",
		"WOREntry",
		'' AS "RoleCode",
		'' AS "RscCode",
		0 AS "RscQty",
		'' AS "RscUomCode",
		"Project",
		'' AS "ToWhseCode",
		'' AS "CostCenter"
	FROM (
		SELECT
			"ObjType" AS "B1ObjCode",
			"Warehouse" AS "WhseCode",
			"DocEntry" AS "WOREntry",
			IFNULL("Project", '') AS "Project"
		FROM OWOR P
		WHERE CAST("DocEntry" AS NVARCHAR(60)) IN (
			SELECT "WOREntry" FROM BEM2 B
			WHERE B."RepId" = :REP_ID
			)
		GROUP BY
			"ObjType",
			"Warehouse",
			"DocEntry",
			"Project"
	) GRP
) WOR;
-- 4-16, PRODUCTION_DOCUMENT, Production Document, end

DROP TABLE ITEM_UOM;
END IF;
-- END IF for PERIOD_ENTRY exists.

-- 5. Return Data Count
SELECT "BEMDocType", "BEMDocName", COUNT(*) AS "RowCount"
FROM BEM2
WHERE "RepId" = :REP_ID
GROUP BY "BEMDocType", "BEMDocName"
ORDER BY "BEMDocType";


END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_ADDDATE (IN origDate		DATE, 
							  IN endDate		DATE,
							  IN frequency		NVARCHAR(1), 
							  OUT newDate		DATE) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
AS 
BEGIN
	IF(:frequency = 'D') THEN
		newDate := ADD_DAYS(:origDate, 1);
	ELSEIF (:frequency = 'W') THEN
		newDate := ADD_DAYS(:origDate, 7);
	ELSEIF (:frequency = 'A') THEN
		newDate := ADD_YEARS(:origDate, 1);
	ELSEIF (:frequency = 'M') THEN
		newDate := ADD_MONTHS(:origDate, 1);
	ELSEIF (:frequency = 'S') THEN
		newDate := ADD_MONTHS(:origDate, 6);
	ELSEIF (:frequency = 'Q') THEN
		newDate := ADD_MONTHS(:origDate, 3);
	ELSE
		newDate := ADD_DAYS(:endDate, 1);
	END IF; 
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_ADDDATE
CREATE PROCEDURE CFF_BLANKETAGREEMENT_DETAIL (IN dateFrom		DATE, 
											  IN dateTo			DATE)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	curAmnt		DECIMAL(21,6);
	occurrence	INTEGER;
	newDate		DATE;
	nextDate	DATE;
	docSum		DECIMAL(21,6);
	recCount	INTEGER;
	--- Variable FOR curser BAQry
	fromDate	TIMESTAMP;
	toDate		TIMESTAMP;
	frequency	NVARCHAR(1);
	quantity	DECIMAL(21,6);
	agrEfctNum 	INTEGER;
	agrLineNum	INTEGER;
	unitPrice	DECIMAL(21,6);
	currency	NVARCHAR(5);
	bpCode		NVARCHAR(15);
	absID		INTEGER;
	cardType	NVARCHAR(1);
	addSF		INTEGER;
	addEF		INTEGER; 
CURSOR BAQry(qyDateFrom DATE, qyDateTo DATE) FOR
	SELECT T2."FromDate", T2."ToDate", T2."DatePeriod", T2."Quantity", T2."AgrEfctNum", T1."AgrLineNum", T1."UnitPrice", T1."Currency", T0."BpCode", T0."AbsID", T3."CardType"
	FROM "OOAT" T0
	INNER JOIN "OAT1" T1 ON T1."AgrNo" = T0."AbsID"
	INNER JOIN "OAT2" T2 ON T1."AgrNo" = T2."AgrNo" AND T1."AgrLineNum" = T2."AgrLnNum"
	INNER JOIN "OCRD" T3 ON T3."CardCode" = T0."BpCode"
	WHERE T0."Status" = 'A' 
		AND T0."Cancelled" = 'N'
		AND T2."FromDate" <= :qyDateTo
		AND T2."ToDate" >= :qyDateFrom
		AND (T3."CardType" = 'C' or T3."CardType" = 'S')
	ORDER BY T0."AbsID", T1."AgrLineNum", T2."AgrEfctNum";
BEGIN 

	SELECT COUNT(*) INTO addSF FROM "CFF_TMP_GROUP" WHERE "Group" = 'SF';
	SELECT COUNT(*) INTO addEF FROM "CFF_TMP_GROUP" WHERE "Group" = 'EF';
	
	OPEN BAQry(:dateFrom, :dateTo);
	FETCH BAQry INTO fromDate, toDate, frequency, quantity, agrEfctNum, agrLineNum, unitPrice, currency, bpCode, absID, cardType;
	WHILE not BAQry::NOTFOUND DO
		-- The date inteval is out of range, do not need to process the BA
		IF :fromDate > :dateTo OR :toDate < :dateFrom THEN
			CONTINUE;
		END IF;
		
		occurrence := 0;
		newDate := :fromDate;
		WHILE :newDate <= :toDate DO
			occurrence := :occurrence + 1;
			CALL CFF_ADDDATE(:newDate, :toDate, :frequency, :newDate);
		END WHILE; -- End date loop
			
		newDate := :fromDate;
		WHILE :newDate <= :toDate DO
			IF :newDate >= :dateFrom AND :newDate <= :dateTo THEN
				docSum := 0;
				curAmnt := :unitPrice * :quantity / :occurrence;
			
				IF (:cardType = 'C') THEN
					IF (:addSF > 0) THEN
						-- Get BP document related to this BA
						SELECT COUNT(*), SUM(T1."LineTotal") INTO recCount, docSum 
						FROM "ORIN" T0
						INNER JOIN "RIN1" T1 ON T1."DocEntry" = T0."DocEntry"
						WHERE T0."DocDate" BETWEEN :newDate AND :nextDate
							AND T1."AgrNo" = :absID
							AND T1."AgrLnNum" = :agrLineNum;
						
						IF(:recCount > 0) THEN
							curAmnt := :curAmnt - :docSum;
						END IF;
						
						SELECT COUNT(*), SUM(T1."LineTotal") INTO recCount, docSum
						FROM "OINV" T0
						INNER JOIN "INV1" T1 ON T1."DocEntry" = T0."DocEntry"
						WHERE T0."DocDate" BETWEEN :newDate AND :nextDate
							AND T1."AgrNo" = :absID
							AND T1."AgrLnNum" = :agrLineNum;
						
						
						IF(:recCount > 0) THEN
							curAmnt := :curAmnt - :docSum;
						END IF;
						
						IF(:curAmnt < 0) THEN
							curAmnt := 0;
						END IF;
						--INSERT INTO TmpDocSum VALUES(:newDate, :nextDate, :bpCode, :curAmnt-:DocTotal, :DocTotal, :curAmnt);								
						-- End
						INSERT INTO "CFF_TMP_DETAIL_BA" VALUES(:newDate, '1250000025', :absID, :absID, '', :bpCode, '', :curAmnt, 0, '17', 'SF');
					END IF;
				ELSE
					IF (:addEF > 0) THEN
						-- Get BP document related to this BA
						SELECT COUNT(*), SUM(T1."LineTotal") INTO recCount, docSum 
						FROM "ORPC" T0
						INNER JOIN "RPC1" T1 ON T1."DocEntry" = T0."DocEntry"
						WHERE T0."DocDate" BETWEEN :newDate AND :nextDate
							AND T1."AgrNo" = :absID
							AND T1."AgrLnNum" = :agrLineNum;
						
						IF(:recCount > 0) THEN
							curAmnt := :curAmnt - :docSum;
						END IF;
						
						SELECT COUNT(*), SUM(T1."LineTotal") INTO recCount, docSum
						FROM "OPCH" T0
						INNER JOIN "PCH1" T1 ON T1."DocEntry" = T0."DocEntry"
						WHERE T0."DocDate" BETWEEN :newDate AND :nextDate
							AND T1."AgrNo" = :absID
							AND T1."AgrLnNum" = :agrLineNum;
						
						IF(:recCount > 0) THEN
							curAmnt := :curAmnt - :docSum;
						END IF;
						IF(:curAmnt < 0) THEN
							curAmnt := 0;
						END IF;				
						-- End			
						INSERT INTO "CFF_TMP_DETAIL_BA" VALUES(:newDate, '1250000025', :absID, :absID, '', :bpCode, '', 0, :curAmnt, '22', 'EF');
					END IF;
				END IF;	
			END IF;
			
			CALL CFF_ADDDATE(:newDate, :toDate, :frequency, :nextDate);
			newDate := :nextDate;
		END WHILE; -- End date loop
		
		FETCH BAQry INTO fromDate, toDate, frequency, quantity, agrEfctNum, agrLineNum, unitPrice, currency, bpCode, absID, cardType;
	END WHILE; -- End BAQry loop
	CLOSE BAQry;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_BLANKETAGREEMENT_DETAIL

CREATE PROCEDURE CFF_BLANKETAGREEMENT_OVERVIEW (IN dateFrom	DATE, 
												IN dateTo	DATE)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN 
	CALL CFF_BLANKETAGREEMENT_DETAIL(:dateFrom, :dateTo);
	
	INSERT INTO "CFF_TMP_OVERVIEW_BA"
		SELECT T1."EndDate", SUM(T0."Debit"), SUM(T0."Credit"), T0."ObjType", T0."Group", COUNT(*) FROM "CFF_TMP_DETAIL_BA" T0
		INNER JOIN "CFF_TMP_DATE" T1 ON T0."DueDate" BETWEEN T1."StartDate" AND T1."EndDate"
		GROUP BY T1."EndDate", T0."ObjType", T0."Group";

END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_GENERAL_DETAIL
CREATE PROCEDURE CFF_CASHFLOW_DETAIL (IN dateFrom	DATE, 
									  IN dateTo		DATE, 
									  IN objList	NVARCHAR(200),
									  IN options	NVARCHAR(50),
									  IN groups		NVARCHAR(50),
									  IN topNum		INTEGER)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	addRP			NVARCHAR(1);
	addRT			NVARCHAR(1);
	addBA			NVARCHAR(1);
	addJV			NVARCHAR(1);
	addDD			NVARCHAR(1);
	addDP			NVARCHAR(1);
BEGIN 
	-- Parse Object list
	CALL CFF_PARSEOBJLIST(:objList, :groups);
	
	CALL CFF_PARSEOPTIONS(:options, :addRP, :addRT, :addBA, :addJV, :addDD, :addDP);

	CALL CFF_GENERAL_DETAIL(:dateFrom, :dateTo, :addRP, :addBA, :addJV, :addDP);
	
	CALL CFF_DOCUMENT_DETAIL(:dateFrom, :dateTo, :addRT, :addDD, :addDP);
	
	IF :topNum > 0 THEN
		SELECT TOP :topNum T0."ObjType",
			   T0."DueDate",
			   T0."DocType",
			   T0."DocEntry",
			   T0."DocNum",
			   T0."InstImnt",
			   T0."CtrlAcct",
			   T0."Account",
			   T0."Debit",
			   T0."Credit"
		  FROM "CFF_TMP_DETAIL" T0 
			ORDER BY T0."DueDate";
	ELSE
		SELECT T0."ObjType",
			   T0."DueDate",
			   T0."DocType",
			   T0."DocEntry",
			   T0."DocNum",
			   T0."InstImnt",
			   T0."CtrlAcct",
			   T0."Account",
			   T0."Debit",
			   T0."Credit"
		  FROM "CFF_TMP_DETAIL" T0 
			ORDER BY T0."DueDate";	
	END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_GENERAL_OVERVIEW AFTER:SP:CFF_DOCUMENT_OVERVIEW

CREATE PROCEDURE CFF_CASHFLOW_OVERVIEW (IN dateFrom	DATE, 
										IN dateTo	DATE, 
										IN interval	NVARCHAR(1),
										IN objList	NVARCHAR(200),
										IN options	NVARCHAR(50),
										IN groups	NVARCHAR(50))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	addRP			NVARCHAR(1);
	addRT			NVARCHAR(1);
	addBA			NVARCHAR(1);
	addJV			NVARCHAR(1);
	addDD			NVARCHAR(1);
	addDP			NVARCHAR(1);
BEGIN 
	CALL CFF_PARSEOBJLIST(:objList, :groups);
	
	CALL CFF_PARSEOPTIONS(:options, :addRP, :addRT, :addBA, :addJV, :addDD, :addDP);

	CALL CFF_GENERAL_OVERVIEW(:dateFrom, :dateTo, :interval, :addRP, :addBA, :addJV, :addDP);
	
	CALL CFF_DOCUMENT_OVERVIEW(:dateFrom, :dateTo, :interval, :addRT, :addDD, :addDP);
	
	SELECT	T1."Index", 
			T1."ObjType", 
			SUM(T1."Debit") as "Debit", 
			SUM(T1."Credit") as "Credit",
			SUM(T1."Number") as "Number"
	FROM	"CFF_TMP_OVERVIEW"	T1
	INNER JOIN  "CFF_TMP_GROUP" T2 ON T2."Group" = T1."Group"
	GROUP BY	T1."Index", T1."Group", T1."ObjType"
	ORDER BY	T1."Index";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE CFF_CREATEDBOBJECTS
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	IsExists INTEGER;
	SqlStr   NVARCHAR(15000);
BEGIN
	-- CFF_TMP_OVERVIEW
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_OVERVIEW' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_OVERVIEW CASCADE;
	END IF;
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_OVERVIEW (
		"Index"				INTEGER,
		"DueDate"			DATE, 
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"ObjType"			NVARCHAR(20),
		"Group"				NVARCHAR(2),
		"Number"			INTEGER
	);

	-- CFF_TMP_OVERVIEW_BA for Blanket Agreement
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_OVERVIEW_BA' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_OVERVIEW_BA CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_OVERVIEW_BA (
		"DueDate"			DATE, 
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"ObjType"			NVARCHAR(20),
		"Group"				NVARCHAR(2),
		"Number"			INTEGER
	);	

	-- CFF_TMP_RP for Recurring Posting
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_RP' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_RP CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_RP (
		"DueDate"			DATE, 
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"AcctCode"			NVARCHAR(15), 
		"CtrlAcct"			NVARCHAR(15) 
	);

	-- CFF_TMP_RP_OB for Openning Balance of Recurring Posting
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_RP_OB' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_RP_OB CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_RP_OB (
		"DueDate"			DATE, 
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"AcctCode"			NVARCHAR(15), 
		"CtrlAcct"			NVARCHAR(15) 
	);
	
	-- CFF_TMP_DETAIL
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_DETAIL' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_DETAIL CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_DETAIL (
		"DueDate"			DATE,
		"DocType"			NVARCHAR(20),
		"DocEntry"			NVARCHAR(20),
		"CtrlAcct"			NVARCHAR(15),
		"Account"			NVARCHAR(15),
		"Remarks"			NVARCHAR(50),
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"ObjType"			NVARCHAR(20),
		"Group"				NVARCHAR(2),
		"InstImnt"			INTEGER,
		"DocNum"			NVARCHAR(20)
	);

	-- CFF_TMP_DETAIL_RP for Recurring Posting
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_DETAIL_RP' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_DETAIL_RP CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_DETAIL_RP (
		"DueDate"			DATE, 
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"AcctCode"			NVARCHAR(15), 
		"CtrlAcct"			NVARCHAR(15), 
		"DocEntry"			NVARCHAR(20), 
		"Remarks"			NVARCHAR(50)
	);
		
	-- CFF_TMP_DETAIL_BA for Blanket Agreement
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_DETAIL_BA' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_DETAIL_BA CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_DETAIL_BA (
		"DueDate"			DATE,
		"DocType"			NVARCHAR(20),
		"DocEntry"			INTEGER,
		"DocNum"			INTEGER,
		"CtrlAcct"			NVARCHAR(15),
		"Account"			NVARCHAR(15),
		"Remarks"			NVARCHAR(50),
		"Debit"				DECIMAL(21,6), 
		"Credit"			DECIMAL(21,6), 
		"ObjType"			NVARCHAR(20),
		"Group"				NVARCHAR(2)
	);

	-- CFF_TMP_OCRD
	-- Purpose to filter out inactive BPs
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_OCRD' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_OCRD CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_OCRD (
		"CardCode"			NVARCHAR(15),
		"CardType"			NVARCHAR(1),
		"AvrageLate"		INTEGER
	);	

	-- CFF_TMP_DATE
	-- Used to calculate date interval
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_DATE' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_DATE CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_DATE (
		"StartDate"			DATE,
		"EndDate"			DATE,
		"Index"				INTEGER
	);	
	
	-- CFF_TMP_BOEACCT
	-- Used to store BOE account which's from OACP and BP's control account
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_BOEACCT' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_BOEACCT CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_BOEACCT (
		"AcctCode" NVARCHAR(15)
	);	

	-- CFF_TMP_OBJLIST
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_OBJLIST' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_OBJLIST CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_OBJLIST (
		"ObjType"			NVARCHAR(20)
	);
	
	-- B1_CashFlowForecastPredictDueDateDocumentsView
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".VIEWS 
	WHERE VIEW_NAME = 'B1_CashFlowForecastPredictDueDateDocumentsView' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		SqlStr := 'DROP VIEW "B1_CashFlowForecastPredictDueDateDocumentsView"';
  	    EXEC(:SqlStr);		
	END IF;	
	SqlStr := 'CREATE VIEW "B1_CashFlowForecastPredictDueDateDocumentsView"
	  AS
	  --1. Sales Order
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate",
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays",
			 IFNULL(T1."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum", 
			 IFNULL(T2."IntsNo", 0)				AS "InstID",
			 IFNULL(T1."InstNum", 0)			AS "InstNum",
			 IFNULL(T2."InstMonth", 0)			AS "InstMonth",
			 IFNULL(T2."InstDays", 0)			AS "InstDays",
			 IFNULL(T2."InstPrcnt", 100)		AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
	         T0."DocTotal" - T0."PaidToDate"	AS "Debit", 
	         0 									AS "Credit",
			 ''SF''								AS "Group",
			 1 									AS "PredictFlag",
			 T3."AvrageLate",
			 IFNULL(T3."HldCode", '''')			AS "HldCode"
	    FROM "ORDR" T0
  INNER JOIN "OCTG" T1 
		  ON T1."GroupNum" = T0."GroupNum"
   LEFT JOIN "CTG1" T2 
		  ON T2."CTGCode" = T1."GroupNum"
  INNER JOIN "OCRD" T3
		  ON T3."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
	UNION ALL
	--2. Delivery
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 IFNULL(T1."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
