			 100								AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
	         T0."DocTotal" - T0."PaidToDate"	AS "Debit", 
	         0									AS "Credit",
			 ''SF''								AS "Group",
			 1									AS "PredictFlag",
			 T3."AvrageLate",
			 IFNULL(T3."HldCode", '''')			AS "HldCode"
	    FROM "ODLN" T0
  INNER JOIN "OCTG" T1
		  ON T1."GroupNum" = T0."GroupNum"
  INNER JOIN "OCRD" T3
		  ON T3."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
	UNION ALL
	--3. Purchase Order
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 IFNULL(T1."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T2."IntsNo", 0)				AS "InstID",
			 IFNULL(T1."InstNum", 0)			AS "InstNum",
			 IFNULL(T2."InstMonth", 0)			AS "InstMonth",
			 IFNULL(T2."InstDays", 0)			AS "InstDays",
			 IFNULL(T2."InstPrcnt", 100)		AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
	         0									AS "Debit", 
	         T0."DocTotal" - T0."PaidToDate"	AS "Credit",
			 ''EF''								AS "Group",
			 1									AS "PredictFlag",
			 T4."AvrageLate",
			 IFNULL(T3."HldCode", '''')			AS "HldCode"
	    FROM "OPOR" T0
  INNER JOIN "OCTG" T1 
		  ON T1."GroupNum" = T0."GroupNum"
   LEFT JOIN "CTG1" T2 
		  ON T2."CTGCode" = T1."GroupNum"
   LEFT JOIN "OADM" T3
		  ON T3."Code" = T3."Code"
  INNER JOIN "OCRD" T4
		  ON T4."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
	UNION ALL
	-- 4. Draft(Sales Order & Purchase Order)
	  SELECT T0."DocEntry", 
	  		 ''112'' 							AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || ''d''				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 IFNULL(T2."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T3."IntsNo", 0)				AS "InstID",
			 IFNULL(T2."InstNum", 0)			AS "InstNum",
			 IFNULL(T3."InstMonth", 0)			AS "InstMonth",
			 IFNULL(T3."InstDays", 0)			AS "InstDays",
			 IFNULL(T3."InstPrcnt", 100)		AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN ''22'' THEN
					0
				WHEN ''17'' THEN
					(T0."DocTotal" - T0."PaidToDate")
			 END								AS "Debit",
			 CASE	T0."ObjType"
				WHEN ''22'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''17'' THEN
					0
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN ''22'' THEN
					''EF''
				WHEN ''17'' THEN
					''SF''
			 END								AS "Group",
			 1									AS "PredictFlag",
			 T5."AvrageLate",
			 CASE T0."ObjType"
				WHEN ''22'' THEN
					IFNULL(T5."HldCode", '''')
				WHEN ''17'' THEN
					IFNULL(T4."HldCode", '''')
			 END								AS "HldCode"
	    FROM "ODRF" T0
   LEFT JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = ''N''
  INNER JOIN "OCTG" T2
		  ON T2."GroupNum" = T0."GroupNum"
   LEFT JOIN "CTG1" T3
		  ON T3."CTGCode" = T2."GroupNum" 
   LEFT JOIN "OADM" T4
		  ON T4."Code" = T4."Code"
  INNER JOIN "OCRD" T5
		  ON T5."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
		 AND T1."DraftEntry" IS NULL
		 AND T0."ObjType" IN (''22'', ''17'')
	UNION ALL
	-- 4. Draft(Delivery)
	  SELECT T0."DocEntry", 
	  		 ''112'' 							AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || ''d''				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 IFNULL(T2."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt", 
			 T0."Installmnt",
	         T0."DocDueDate", 
			 (T0."DocTotal" - T0."PaidToDate")	AS "Debit",
			 0									AS "Credit",
			 ''SF''								AS "Group",
			 1									AS "PredictFlag",
			 T4."AvrageLate",
			 IFNULL(T4."HldCode", '''')			AS "HldCode"
	    FROM "ODRF" T0
   LEFT JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = ''N''
  INNER JOIN "OCTG" T2
		  ON T2."GroupNum" = T0."GroupNum"
  INNER JOIN "OCRD" T4
		  ON T4."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
		 AND T1."DraftEntry" IS NULL
		 AND T0."ObjType" = ''15''
		 UNION ALL
	  --5.  Return Request
      SELECT 
      T0."DocEntry",
      T0."ObjType"						AS "DocType", 
      T0."DocNum", 
      T0."CardCode", 
      T0."CtlAccount",
      T0."TransId", 
      T0."JrnlMemo", 
      T0."ObjType",
      T0."ObjType"						AS "OriginalType", 
      T0."CreateDate", 
      T0."TaxDate", 
      T0."ClsDate", 
      T0."PayDuMonth", 
      T0."ExtraMonth", 
      T0."ExtraDays",
      IFNULL(T1."TolDays", 0)			AS "TolDays",
      T0."GroupNum", 
	  IFNULL(T0."Installmnt", 0)		AS "InstID", 
	  IFNULL(T0."Installmnt", 0)		AS "InstNum", 
	  0			                        AS "InstMonth",
	  0			                        AS "InstDays",
	  100		                        AS "InstPrcnt",
      T0."Installmnt",
      T0."DocDueDate", 
      CASE T3."NegAmount" 
		WHEN ''N'' THEN
			0
		WHEN ''Y'' THEN
			0 - (T0."DocTotal" - T0."PaidToDate")
		END								AS "Debit", 
	  CASE T3."NegAmount" 
		WHEN ''N'' THEN
			(T0."DocTotal" - T0."PaidToDate")
		WHEN ''Y'' THEN
			0
		END								AS "Credit",
      ''SF''								AS "Group",
      1									AS "PredictFlag",
      IFNULL(T2."AvrageLate", 0) AS "AvrageLate", 
      IFNULL(T2."HldCode", '''')			AS "HldCode"
      FROM  "ORRR" T0 
      INNER JOIN "OCTG" T1 
		  ON T1."GroupNum" = T0."GroupNum"
	  INNER  JOIN "OCRD" T2  ON  T2."CardCode" = T0."CardCode"    
	  LEFT   JOIN "OADM" T3  ON T3."Code" = T3."Code"
      WHERE T0."CANCELED" <> ''Y'' AND  T0."DocStatus" = ''O''
      UNION ALL
     --6. Goods Return Request
      SELECT 
      T0."DocEntry",
      T0."ObjType"						AS "DocType", 
      T0."DocNum", 
      T0."CardCode", 
      T0."CtlAccount",
      T0."TransId", 
      T0."JrnlMemo", 
      T0."ObjType",
      T0."ObjType"						AS "OriginalType", 
      T0."CreateDate", 
      T0."TaxDate", 
      T0."ClsDate", 
      T0."PayDuMonth", 
      T0."ExtraMonth", 
      T0."ExtraDays",
	  IFNULL(T1."TolDays", 0)			AS "TolDays", 
	  T0."GroupNum", 
	  IFNULL(T0."Installmnt", 0)		AS "InstID", 
	  IFNULL(T0."Installmnt", 0)		AS "InstNum", 
	  0			                        AS "InstMonth",
	  0			                        AS "InstDays",
	  100		                        AS "InstPrcnt",
      T0."Installmnt",
      T0."DocDueDate", 
	  CASE T3."NegAmount" 
	    WHEN ''N'' THEN
	    	(T0."DocTotal" - T0."PaidToDate")
	    WHEN ''Y'' THEN
	    	0
	    END								AS "Debit", 
	  CASE T3."NegAmount" 
	    WHEN ''N'' THEN
	    	0
	    WHEN ''Y'' THEN
	    	0 - (T0."DocTotal" - T0."PaidToDate")
	    END								AS "Credit",
      ''EF''								AS "Group",
      1									AS "PredictFlag",
      IFNULL(T2."AvrageLate", 0) AS "AvrageLate", 
      IFNULL(T3."HldCode", '''')			AS "HldCode"
      FROM  "OPRR" T0
      INNER JOIN "OCTG" T1 
		  ON T1."GroupNum" = T0."GroupNum"  
	  INNER  JOIN "OCRD" T2  ON  T2."CardCode" = T0."CardCode"   
	  LEFT   JOIN "OADM" T3  ON T3."Code" = T3."Code"
      WHERE T0."CANCELED" <> ''Y'' AND  T0."DocStatus" = ''O''
	  UNION ALL
	  --7.draft(Return Request, Goods Return Request)
	  SELECT 
      T0."DocEntry",
      ''112''						       AS "DocType", 
      T0."DocNum", 
      T0."CardCode", 
      T0."CtlAccount",
      T0."TransId", 
      T0."JrnlMemo", 
      T0."ObjType" || ''d''               AS "ObjType",
      T0."ObjType"						AS "OriginalType", 
      T0."CreateDate", 
      T0."TaxDate", 
      T0."ClsDate", 
      T0."PayDuMonth", 
      T0."ExtraMonth", 
      T0."ExtraDays",
	  IFNULL(T2."TolDays", 0)			AS "TolDays", 
	  T0."GroupNum",  
	  IFNULL(T0."Installmnt", 0)			AS "InstID", 
	  IFNULL(T0."Installmnt", 0)			AS "InstNum", 
	  0									AS "InstMonth", 
	  0									AS "InstDays", 
	  100								AS "InstPrcnt", 
      T0."Installmnt",
      T0."DocDueDate", 
      CASE	T0."ObjType" 
          WHEN ''234000031'' THEN
            CASE T4."NegAmount" 
		        WHEN ''N'' THEN
			          0
		        WHEN ''Y'' THEN
			          0 - (T0."DocTotal" - T0."PaidToDate")
		    END
		  WHEN ''234000032'' THEN
		     CASE T4."NegAmount" 
		  	    WHEN ''N'' THEN
	    	          (T0."DocTotal" - T0."PaidToDate")
	            WHEN ''Y'' THEN
	    	           0
	    	  END
	   END                                      AS "Debit",  
      CASE	T0."ObjType" 
          WHEN ''234000031'' THEN
            CASE T4."NegAmount" 
		        WHEN ''N'' THEN
			          (T0."DocTotal" - T0."PaidToDate")
		        WHEN ''Y'' THEN
			          0
		    END
		  WHEN ''234000032'' THEN
		     CASE T4."NegAmount" 
		  	    WHEN ''N'' THEN
	    	          0
	            WHEN ''Y'' THEN
	    	          0 - (T0."DocTotal" - T0."PaidToDate")
	    	  END
	   END                                      AS "Credit",
	   CASE T0."ObjType"
		   WHEN ''234000031'' THEN
			    ''SF''
		   WHEN ''234000032'' THEN
				''EF''
	   END								AS "Group",
      1									AS "PredictFlag",
      IFNULL(T3."AvrageLate", 0) AS "AvrageLate",    
	  CASE T0."ObjType"
		  WHEN ''234000031'' THEN
				IFNULL(T3."HldCode", '''')
		  WHEN ''234000032'' THEN
				IFNULL(T4."HldCode", '''')
	  END								AS "HldCode"	  
      FROM "ODRF" T0
 LEFT JOIN "ORCP" T1 
	     ON T0."ObjType" = T1."DocObjType"
		AND T0."DocEntry" = T1."DraftEntry"
		AND T1."IsRemoved" = ''N''
INNER JOIN "OCTG" T2
		 ON T2."GroupNum" = T0."GroupNum"
INNER JOIN "OCRD" T3  
         ON  T3."CardCode" = T0."CardCode"    
LEFT  JOIN "OADM" T4  
         ON T4."Code" = T4."Code"
      WHERE  T0."CANCELED" <> ''Y'' 
        AND  T0."DocStatus" = ''O''
        AND  T1."DraftEntry" IS NULL
        AND  T0."ObjType" IN (''234000031'', ''234000032'')';
		 
	EXEC(:SqlStr);
	
	-- B1_CashFlowForecastRecurringTrasactionView
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".VIEWS 
	WHERE VIEW_NAME = 'B1_CashFlowForecastRecurringTrasactionView' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		SqlStr := 'DROP VIEW "B1_CashFlowForecastRecurringTrasactionView"';
  	    EXEC(:SqlStr);		
	END IF;	
	SqlStr := 'CREATE VIEW "B1_CashFlowForecastRecurringTrasactionView"
	  AS
	-- 1. Recurring Trasaction(have Installments)
	  SELECT T0."DocEntry", 
	  		 ''540000043''						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || ''r''				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays",
			 IFNULL(T2."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T3."IntsNo", 0)				AS "InstID",
			 IFNULL(T2."InstNum", 0)			AS "InstNum",
			 IFNULL(T3."InstMonth", 0)			AS "InstMonth",
			 IFNULL(T3."InstDays", 0)			AS "InstDays",
			 IFNULL(T3."InstPrcnt", 100)		AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN ''22'' THEN
					0
				WHEN ''204'' THEN
					0
				WHEN ''18'' THEN
					0
				WHEN ''163'' THEN
					CASE T4."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''164'' THEN
					0
				WHEN ''17'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''203'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''13'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''165'' THEN
					CASE T4."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''166'' THEN
					(T0."DocTotal" - T0."PaidToDate")
			 END								AS "Debit",
			 CASE	T0."ObjType"
				WHEN ''22'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''204'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''18'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''163'' THEN
					CASE T4."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''164'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''17'' THEN
					0
				WHEN ''203'' THEN
					0
				WHEN ''13'' THEN
					0
				WHEN ''165'' THEN
					CASE T4."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''166'' THEN
					0
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN ''22'' THEN
					''EF''
				WHEN ''204'' THEN
					''EF''
				WHEN ''18'' THEN
					''EF''
				WHEN ''163'' THEN
					''EF''
				WHEN ''164'' THEN
					''EF''
				WHEN ''17'' THEN
					''SF''
				WHEN ''203'' THEN
					''SF''
				WHEN ''13'' THEN
					''SF''
				WHEN ''165'' THEN
					''SF''
				WHEN ''166'' THEN
					''SF''
			 END								AS "Group",
			 CASE T0."ObjType"
				WHEN ''17'' THEN
					1
				WHEN ''22'' THEN
					1
				ELSE
					0
			 END								AS "PredictFlag",
			 T5."AvrageLate",
			 CASE T0."ObjType"
				WHEN ''22'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''204'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''18'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''163'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''164'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''17'' THEN
					IFNULL(T5."HldCode", '''')
				WHEN ''203'' THEN
					IFNULL(T5."HldCode", '''')
				WHEN ''13'' THEN
					IFNULL(T5."HldCode", '''')
				WHEN ''165'' THEN
					IFNULL(T5."HldCode", '''')
				WHEN ''166'' THEN
					IFNULL(T5."HldCode", '''')
			 END								AS "HldCode"
	    FROM "ODRF" T0
  INNER JOIN "ORCP" T1
		  ON T0."ObjType" = ABS(T1."DocObjType")
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = ''N''
  INNER JOIN "OCTG" T2
		  ON T2."GroupNum" = T0."GroupNum"
   LEFT JOIN "CTG1" T3
		  ON T3."CTGCode" = T2."GroupNum"
   LEFT JOIN "OADM" T4
		  ON T4."Code" = T4."Code"
  INNER JOIN "OCRD" T5
		  ON T5."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
		 AND T1."DraftEntry" IS NOT NULL
		 AND T0."ObjType" IN(''17'', ''203'', ''13'', ''165'', ''166'', ''22'', ''204'', ''18'', ''163'', ''164'')
	UNION ALL
	-- 2. Recurring Trasaction(not have Installments)
	  SELECT T0."DocEntry", 
	  		 ''540000043''						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || ''r''				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays",
			 IFNULL(T2."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN ''20'' THEN
					0
				WHEN ''21'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''19'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''15'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''16'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''14'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''234000031'' THEN
                    CASE T3."NegAmount" 
		                WHEN ''N'' THEN
			                0
		                WHEN ''Y'' THEN
			                0 - (T0."DocTotal" - T0."PaidToDate")
		            END
		        WHEN ''234000032'' THEN
		            CASE T3."NegAmount" 
		  	            WHEN ''N'' THEN
	    	               (T0."DocTotal" - T0."PaidToDate")
	                    WHEN ''Y'' THEN
	    	                0
	    	        END
			 END								AS "Debit",
			 CASE	T0."ObjType"
				WHEN ''20'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''21'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''19'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''15'' THEN
					0
				WHEN ''16'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''14'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''234000031'' THEN
                    CASE T3."NegAmount" 
		                WHEN ''N'' THEN
			                (T0."DocTotal" - T0."PaidToDate")
		                WHEN ''Y'' THEN
			                0
		            END
		        WHEN ''234000032'' THEN
		            CASE T3."NegAmount" 
		                WHEN ''N'' THEN
	    	                0
	                    WHEN ''Y'' THEN
	    	                0 - (T0."DocTotal" - T0."PaidToDate")
	    	        END
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN ''20'' THEN
					''EF''
				WHEN ''21'' THEN
					''EF''
				WHEN ''19'' THEN
					''EF''
				WHEN ''15'' THEN
					''SF''
				WHEN ''16'' THEN
					''SF''
				WHEN ''14'' THEN
					''SF''
				WHEN ''234000031'' THEN
			        ''SF''
		        WHEN ''234000032'' THEN
				    ''EF''
			 END								AS "Group",
			 CASE T0."ObjType"
				WHEN ''15'' THEN
					1
				WHEN ''234000031'' THEN
				    1
				WHEN ''234000032'' THEN
				    1
				ELSE
					0
			 END								AS "PredictFlag",
			 T4."AvrageLate",
			 CASE T0."ObjType"
				WHEN ''20'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''21'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''19'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''15'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''16'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''14'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''234000031'' THEN
				    IFNULL(T4."HldCode", '''')
				WHEN ''234000032'' THEN
				    IFNULL(T3."HldCode", '''')
			 END								AS "HldCode"
	    FROM "ODRF" T0
  INNER JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = ''N''
  INNER JOIN "OCTG" T2
		  ON T2."GroupNum" = T0."GroupNum"
   LEFT JOIN "OADM" T3
		  ON T3."Code" = T3."Code"
  INNER JOIN "OCRD" T4
		  ON T4."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
		 AND T1."DraftEntry" IS NOT NULL
		 AND T0."ObjType" IN (''15'', ''16'', ''14'', ''20'', ''21'', ''19'', ''234000031'', ''234000032'')';
		 
	EXEC(:SqlStr); 
		 
	-- B1_CashFlowForecastDueDateDocumentsView
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".VIEWS 
	WHERE VIEW_NAME = 'B1_CashFlowForecastDueDateDocumentsView' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		SqlStr := 'DROP VIEW "B1_CashFlowForecastDueDateDocumentsView"';
  	    EXEC(:SqlStr);		
	END IF;	
	SqlStr := 'CREATE VIEW "B1_CashFlowForecastDueDateDocumentsView"
	  AS
	--1. Revert Delivery
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum", 
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt", 
			 T0."Installmnt",
	         T0."DocDueDate", 
	         CASE T2."NegAmount" 
				WHEN ''N'' THEN
					0
				WHEN ''Y'' THEN
					0 - (T0."DocTotal" - T0."PaidToDate")
			 END								AS "Debit", 
			 CASE T2."NegAmount" 
				WHEN ''N'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''Y'' THEN
					0
			 END								AS "Credit",
			 ''SF''								AS "Group",
			 0									AS "PredictFlag",
			 T1."AvrageLate",
			 IFNULL(T1."HldCode", '''')			AS "HldCode"
	    FROM "ORDN" T0
  INNER JOIN "OCRD" T1
		  ON T1."CardCode" = T0."CardCode" 
   LEFT JOIN "OADM" T2
		  ON T2."Code" = T2."Code"
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
	UNION ALL
	--2. A/R Down Payment Request
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",  
			 T0."Installmnt",
	         T2."DueDate"						AS "DocDueDate", 
	         T2."InsTotal" - T2."PaidToDate"	AS "Debit", 
	         0									AS "Credit",
			 ''SF''								AS "Group",
			 0									AS "PredictFlag",
			 T1."AvrageLate",
			 IFNULL(T1."HldCode", '''')			AS "HldCode"
	    FROM "ODPI" T0
  INNER JOIN "OCRD" T1
		  ON T1."CardCode" = T0."CardCode" 
  INNER JOIN "DPI6" T2
		  ON T2."DocEntry" = T0."DocEntry"
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
		 AND T0."Posted" = ''N''
	UNION ALL
	--3. Purchase Delivery
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",  
			 T0."Installmnt",
	         T0."DocDueDate", 
	         0 AS "Debit", 
	         T0."DocTotal" - T0."PaidToDate"	AS "Credit",
			 ''EF''								AS "Group",
			 0									AS "PredictFlag",
			 T2."AvrageLate",
			 IFNULL(T1."HldCode", '''')			AS "HldCode"
	    FROM "OPDN" T0
   LEFT JOIN "OADM" T1
		  ON T1."Code" = T1."Code"
  INNER JOIN "OCRD" T2
		  ON T2."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
	UNION ALL
	--4. Revert Purchase
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",  
			 T0."Installmnt",
	         T0."DocDueDate",
			 CASE T1."NegAmount" 
				WHEN ''N'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''Y'' THEN
					0
			 END								AS "Debit", 
			 CASE T1."NegAmount" 
				WHEN ''N'' THEN
					0
				WHEN ''Y'' THEN
					0 - (T0."DocTotal" - T0."PaidToDate")
			 END								AS "Credit",
			 ''EF''								AS "Group",
			 0									AS "PredictFlag",
			 T2."AvrageLate",
			 IFNULL(T1."HldCode", '''')			AS "HldCode"
	    FROM "ORPD" T0
   LEFT JOIN "OADM" T1
		  ON T1."Code" = T1."Code"
  INNER JOIN "OCRD" T2
		  ON T2."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
	UNION ALL
	--5. A/P Down Payment Request
	  SELECT T0."DocEntry", 
	  		 T0."ObjType"						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo", 
	         T0."ObjType", 
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",  
			 T0."Installmnt",
	         T3."DueDate"						AS "DocDueDate", 
	         0									AS "Debit", 
	         T3."InsTotal" - T3."PaidToDate"	AS "Credit",
			 ''EF''								AS "Group",
			 0									AS "PredictFlag",
			 T2."AvrageLate",
			 IFNULL(T1."HldCode", '''')			AS "HldCode"
	    FROM "ODPO" T0
   LEFT JOIN "OADM" T1
		  ON T1."Code" = T1."Code"
  INNER JOIN "OCRD" T2
		  ON T2."CardCode" = T0."CardCode" 
  INNER JOIN "DPO6" T3
		  ON T3."DocEntry" = T0."DocEntry"
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
		 AND T0."Posted" = ''N''
	UNION ALL
	-- 6. Draft(not have installments)
	  SELECT T0."DocEntry", 
	  		 ''112''							AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || ''d''				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",  
			 T0."Installmnt",
	         T0."DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN ''20'' THEN
					0
				WHEN ''21'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''19'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''16'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''14'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
			 END								AS "Debit",
			 CASE	T0."ObjType"
				WHEN ''20'' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN ''21'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''19'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN ''16'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''14'' THEN
					CASE T2."NegAmount" 
						WHEN ''N'' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN ''20'' THEN
					''EF''
				WHEN ''21'' THEN
					''EF''
				WHEN ''19'' THEN
					''EF''
				WHEN ''16'' THEN
					''SF''
				WHEN ''14'' THEN
					''SF''
			 END								AS "Group",
			 0									AS "PredictFlag",
			 T3."AvrageLate",
			 CASE T0."ObjType"
				WHEN ''20'' THEN
					IFNULL(T2."HldCode", '''')
				WHEN ''21'' THEN
					IFNULL(T2."HldCode", '''')
				WHEN ''19'' THEN
					IFNULL(T2."HldCode", '''')
				WHEN ''16'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''14'' THEN
					IFNULL(T3."HldCode", '''')
			 END								AS "HldCode"
	    FROM "ODRF" T0
   LEFT JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = ''N''
   LEFT JOIN "OADM" T2
		  ON T2."Code" = T2."Code"
  INNER JOIN "OCRD" T3
		  ON T3."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
		 AND T1."DraftEntry" IS NULL
		 AND T0."ObjType" IN (''16'', ''14'', ''21'', ''20'', ''19'')
	UNION ALL
	-- 7. Draft(have installments)
	  SELECT T0."DocEntry", 
	  		 ''112''							AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || ''d''				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",  
			 T2."InstlmntID"					AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0                            		AS "InstMonth", 
			 0                            		AS "InstDays", 
			 100								AS "InstPrcnt", 
			 T0."Installmnt",
	         T2."DueDate"						AS "DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN ''204'' THEN
					0
				WHEN ''18'' THEN
					0
				WHEN ''163'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							(T2."InsTotal" - T2."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''164'' THEN
					0
				WHEN ''203'' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN ''13'' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN ''165'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T2."InsTotal" - T2."PaidToDate")
					END
				WHEN ''166'' THEN
					(T2."InsTotal" - T2."PaidToDate")
			 END								AS	"Debit",
			 CASE	T0."ObjType"
				WHEN ''204'' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN ''18'' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN ''163'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							0
						WHEN ''Y'' THEN
							0 - (T2."InsTotal" - T2."PaidToDate")
					END
				WHEN ''164'' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN ''203'' THEN
					0
				WHEN ''13'' THEN
					0
				WHEN ''165'' THEN
					CASE T3."NegAmount" 
						WHEN ''N'' THEN
							(T2."InsTotal" - T2."PaidToDate")
						WHEN ''Y'' THEN
							0
					END
				WHEN ''166'' THEN
					0
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN ''204'' THEN
					''EF''
				WHEN ''18'' THEN
					''EF''
				WHEN ''163'' THEN
					''EF''
				WHEN ''164'' THEN
					''EF''
				WHEN ''203'' THEN
					''SF''
				WHEN ''13'' THEN
					''SF''
				WHEN ''165'' THEN
					''SF''
				WHEN ''166'' THEN
					''SF''
			 END								AS "Group",
			 0									AS "PredictFlag",
			 T4."AvrageLate",
			 CASE T0."ObjType"
				WHEN ''204'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''18'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''163'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''164'' THEN
					IFNULL(T3."HldCode", '''')
				WHEN ''203'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''13'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''165'' THEN
					IFNULL(T4."HldCode", '''')
				WHEN ''166'' THEN
					IFNULL(T4."HldCode", '''')
			 END								AS "HldCode"
	    FROM "ODRF" T0
   LEFT JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = ''N''
  INNER JOIN "DRF6" T2
		  ON T2."DocEntry" = T0."DocEntry"
   LEFT JOIN "OADM" T3
		  ON T3."Code" = T3."Code"
  INNER JOIN "OCRD" T4
		  ON T4."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> ''Y''
	     AND T0."DocStatus" = ''O''
		 AND T1."DraftEntry" IS NULL
		 AND T0."ObjType" IN (''203'', ''13'', ''165'', ''166'', ''204'', ''18'', ''163'', ''164'')';
     
    EXEC(:SqlStr);
		
	-- CFF_TMP_PAYMENTDATE
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_PAYMENTDATE' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_PAYMENTDATE CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_PAYMENTDATE (
		"CardCodePayment"	NVARCHAR (15),
		"DueDateDay"		SMALLINT, 
		"PmntDate"			SMALLINT,
		"NextMonth"			SMALLINT
	);

	-- CFF_TMP_ORCL
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_ORCL' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_ORCL CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_ORCL (
		"AbsEntry"			INTEGER,
		"RcpEntry"			INTEGER,
		"Instance"			INTEGER  DEFAULT 0,
		"PlanDate"			DATE,
		"Status"			NVARCHAR (1) DEFAULT 'N',
		"DocObjType"		NVARCHAR(20),
		"DocEntry"			INTEGER
	);	
	
	-- CFF_TMP_GROUP
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_GROUP' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_GROUP CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_GROUP (
		"Group"				NVARCHAR(2)
	);
	
	-- CFF_TMP_HOLIDAY
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_TMP_HOLIDAY' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		DROP TABLE CFF_TMP_HOLIDAY CASCADE;
	END IF;	
	CREATE GLOBAL TEMPORARY TABLE CFF_TMP_HOLIDAY
	(
		"HldCode"			NVARCHAR(20),
		"Intervals"			INT
	);
	
	-- CFF_DATE_T
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_DATE_T' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		SqlStr := 'DROP TYPE CFF_DATE_T CASCADE';
		EXEC(:SqlStr);
	END IF;	
	SqlStr := 'CREATE TYPE CFF_DATE_T AS TABLE(
		"AbsEntry"			INTEGER,
		"DocDueDate"		DATE, 
		"AdjustDocDueDate"	TINYINT, 
		"DeltaMonths"		SMALLINT, 
		"AdjustDay"			SMALLINT,
		"HldCode"			NVARCHAR(20),
		"DocType"			NVARCHAR(20),
		"DocEntry"			INTEGER,
		"CardCode"			NVARCHAR (15),
		"CtlAccount"		NVARCHAR (15),
		"Debit"				DECIMAL(21,6),
		"Credit"			DECIMAL(21,6),
		"OriginalType"		NVARCHAR(20),
		"Group"				NVARCHAR(2),
		"InstID"			SMALLINT,
		"DocNum"			INTEGER,
		"AvrageLate"		SMALLINT
	)';
	EXEC(:SqlStr);

	-- CFF_HOLIDAY_T
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_HOLIDAY_T' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		SqlStr := 'DROP TYPE CFF_HOLIDAY_T CASCADE';
		EXEC(:SqlStr);
	END IF;	
	SqlStr := 'CREATE TYPE CFF_HOLIDAY_T AS TABLE(
		"HldCode"			NVARCHAR(20), 
		"WndFrm"			TINYINT, 
		"WndTo"				TINYINT,
		"IsCurYear"			TINYINT,
		"IgnrWnd"			TINYINT,
		"StrDate"			DATE, 
		"EndDate"			DATE
	)';
	EXEC(:SqlStr);
	
	-- CFF_PREDICT_DUEDATE_T
	SELECT COUNT(*) INTO IsExists FROM "PUBLIC".M_TABLES 
	WHERE TABLE_NAME = 'CFF_PREDICT_DUEDATE_T' AND SCHEMA_NAME = CURRENT_SCHEMA;
	IF :IsExists <> 0 THEN
		SqlStr := 'DROP TYPE CFF_PREDICT_DUEDATE_T CASCADE';
		EXEC(:SqlStr);
	END IF;	
	SqlStr := 'CREATE TYPE CFF_PREDICT_DUEDATE_T AS TABLE(
		"AbsEntry"			INTEGER, 
		"PredictDueDate"	DATE
	)';
	EXEC(:SqlStr);
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_FILLPAYMENTDATE AFTER:SP:CFF_GETPREDICTDUEDATE
CREATE PROCEDURE CFF_DOCUMENT_DETAIL (IN  dateFrom		DATE, 
									  IN  dateTo		DATE,
									  IN  addRT			NVARCHAR(1),
									  IN  addDD			NVARCHAR(1),
									  IN  addDP			NVARCHAR(1)
									  )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	predictDueDate	DATE;
	beginPoint		INT;
	hldCode			NVARCHAR(20);
BEGIN
	
	SELECT IFNULL("HldCode", '') INTO hldCode FROM OADM;
	
	--Generate payment date table.
	CALL CFF_FILLPAYMENTDATE;
	
	--Generate holiday info
	CALL CFF_GETLONGESTHOLIDAY;
		
	--Document.
	IF :addRT = 'N' THEN
		dueDates = 
			SELECT	T0."DueDateOnDoc"						AS	"DocDueDate",
					T0."CalDueDate",
					MAP(T0."CardCodePayment", NULL, 0, 1)	AS	"AdjustDocDueDate",
					IFNULL(T0."NextMonth", 0)				AS	"DeltaMonths",
					IFNULL(T0."PmntDate", 0)				AS	"AdjustDay",
					T0."HldCode",
					T0."DocType",
					T0."DocEntry",
					T0."CardCode",
					T0."CtlAccount",
					T0."Debit",
					T0."Credit",
					T0."OriginalType",
					T0."Group",
					T0."InstID",
					T0."DocNum",
					T0."AvrageLate"
			FROM
				(
				SELECT	T0."DocEntry", 
						T0."DocNum", 
						T0."DocType",
						T0."CardCode", 
						T0."CtlAccount", 
						T0."TransId", 
						T0."JrnlMemo", 
						T0."ObjType",
						T0."OriginalType", 
						T0."CreateDate", 
						T0."TaxDate", 
						T0."ClsDate", 
						T0."GroupNum", 
						T0."DueDate", 
						MAP(T1."CardCodePayment", NULL, T0."DueDateOnDoc", ADD_MONTHS( ADD_DAYS( TO_DATE ( YEAR(T0."DueDateOnDoc") || '-' || ( MONTH(T0."DueDateOnDoc") || '-' || '01' ), 'YYYY-MM-DD'), IFNULL(T1."PmntDate", 0) - 1 ), IFNULL(T1."NextMonth", 0) ) ) AS "DueDateOnDoc",
						T0."Debit",
						T0."Credit",
						T0."Group",  
						T0."InstID",
						T0."AvrageLate", 
						T0."HldCode",
						T0."CalDueDate",
						T0."PredictFlag",
						1							AS "Instance",
						T1."CardCodePayment",
						T1."NextMonth",
						T1."PmntDate"
				FROM
					(
						SELECT	T0."DocEntry", 
								T0."DocNum", 
								T0."DocType",
								T0."CardCode", 
								T0."CtlAccount", 
								T0."TransId", 
								T0."JrnlMemo", 
								T0."ObjType",
								T0."OriginalType", 
								T0."CreateDate", 
								T0."TaxDate", 
								T0."ClsDate", 
								T0."GroupNum",
								T0."DocDueDate"				AS "DueDate",
								CASE	T0."PayDuMonth"
									WHEN 'N' THEN
										ADD_DAYS( ADD_MONTHS(T0."DocDueDate", IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									WHEN 'Y' THEN
										ADD_DAYS( ADD_MONTHS( ADD_DAYS( LAST_DAY(T0."DocDueDate"), 1 ), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									WHEN 'H' THEN
										ADD_DAYS( ADD_MONTHS( ADD_DAYS( LAST_DAY (T0."DocDueDate"), 1 - DAYOFMONTH( LAST_DAY(T0."DocDueDate") ) / 2 ), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									WHEN 'E' THEN
										ADD_DAYS( ADD_MONTHS( LAST_DAY(T0."DocDueDate"), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									ELSE
										NULL
								END							AS "DueDateOnDoc", 
								T0."Debit" * IFNULL(T0."InstPrcnt", 100) * 0.01 AS "Debit", 
								T0."Credit" * IFNULL(T0."InstPrcnt", 100) * 0.01 AS "Credit",
								T0."Group",  
								T0."InstID",
								T0."AvrageLate", 
								T0."HldCode",
								T0."DocDueDate"				AS "CalDueDate",
								T0."PredictFlag"
						  FROM	"B1_CashFlowForecastPredictDueDateDocumentsView" T0
						 WHERE	T0."ObjType" IN (SELECT "ObjType" FROM "CFF_TMP_OBJLIST" WHERE "ObjType" IN ('17', '22', '15', '234000031', '234000032', '17d', '22d', '15d', '234000031d', '234000032d'))
					)	T0
			LEFT JOIN	"CFF_TMP_PAYMENTDATE" T1 
				   ON	T1."CardCodePayment" = T0."CardCode"
				  AND	T1."DueDateDay" = DAYOFMONTH(T0."DueDateOnDoc")
				WHERE	T0."DueDate" IS NOT NULL
				)	T0
		LEFT JOIN	"CFF_TMP_HOLIDAY" T1
			   ON	T0."HldCode" = T1."HldCode"
			WHERE	T0."Group" IN (SELECT T2."Group" FROM "CFF_TMP_GROUP" T2)
			  AND	ADD_DAYS( T0."DueDateOnDoc", IFNULL(T1."Intervals", 0) + IFNULL(T0."AvrageLate", 0) ) >= :dateFrom
			  AND	T0."DueDateOnDoc" <= :dateTo;
		  
	ELSE
			
		--generate recurring trasaction date
		CALL CFF_RECURRINGTRASACTIONDATES(:dateFrom, :dateTo);
		
	--Recurring Transaction. 
	dueDates = 
			SELECT	T0."DueDateOnDoc"						AS	"DocDueDate",
					T0."CalDueDate",
					MAP(T0."CardCodePayment", NULL, 0, 1)	AS	"AdjustDocDueDate",
					IFNULL(T0."NextMonth", 0)				AS	"DeltaMonths",
					IFNULL(T0."PmntDate", 0)				AS	"AdjustDay",
					T0."HldCode",
					T0."DocType",
					T0."DocEntry",
					T0."CardCode",
					T0."CtlAccount",
					T0."Debit",
					T0."Credit",
					T0."OriginalType",
					T0."Group",
					T0."InstID",
					T0."DocNum",
					T0."AvrageLate"
			FROM
				(
				SELECT	T0."DocEntry", 
						T0."DocNum", 
						T0."DocType",
						T0."CardCode", 
						T0."CtlAccount", 
						T0."TransId", 
						T0."JrnlMemo", 
						T0."ObjType",
						T0."OriginalType", 
						T0."CreateDate", 
						T0."TaxDate", 
						T0."ClsDate", 
						T0."GroupNum", 
						T0."DueDate", 
						MAP(T1."CardCodePayment", NULL, T0."DueDateOnDoc", ADD_MONTHS( ADD_DAYS( TO_DATE ( YEAR(T0."DueDateOnDoc") || '-' || ( MONTH(T0."DueDateOnDoc") || '-' || '01' ), 'YYYY-MM-DD'), IFNULL(T1."PmntDate", 0) - 1 ), IFNULL(T1."NextMonth", 0) ) ) AS "DueDateOnDoc",
						T0."Debit",
						T0."Credit",
						T0."Group",  
						T0."InstID",
						T0."AvrageLate", 
						T0."HldCode",
						T0."CalDueDate",
						T0."PredictFlag",
						1							AS "Instance",
						T1."CardCodePayment",
						T1."NextMonth",
						T1."PmntDate"
				FROM
					(
						SELECT	T0."DocEntry", 
								T0."DocNum", 
								T0."DocType",
								T0."CardCode", 
								T0."CtlAccount", 
								T0."TransId", 
								T0."JrnlMemo", 
								T0."ObjType",
								T0."OriginalType", 
								T0."CreateDate", 
								T0."TaxDate", 
								T0."ClsDate", 
								T0."GroupNum",
								T0."DocDueDate"				AS "DueDate",
								CASE	T0."PayDuMonth"
									WHEN 'N' THEN
										ADD_DAYS( ADD_MONTHS(T0."DocDueDate", IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									WHEN 'Y' THEN
										ADD_DAYS( ADD_MONTHS( ADD_DAYS( LAST_DAY(T0."DocDueDate"), 1 ), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									WHEN 'H' THEN
										ADD_DAYS( ADD_MONTHS( ADD_DAYS( LAST_DAY (T0."DocDueDate"), 1 - DAYOFMONTH( LAST_DAY(T0."DocDueDate") ) / 2 ), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									WHEN 'E' THEN
										ADD_DAYS( ADD_MONTHS( LAST_DAY(T0."DocDueDate"), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
									ELSE
										NULL
								END							AS "DueDateOnDoc", 
								T0."Debit" * IFNULL(T0."InstPrcnt", 100) * 0.01 AS "Debit", 
								T0."Credit" * IFNULL(T0."InstPrcnt", 100) * 0.01 AS "Credit",
								T0."Group",  
								T0."InstID",
								T0."AvrageLate", 
								T0."HldCode",
								T0."DocDueDate"				AS "CalDueDate",
								T0."PredictFlag"
						  FROM	"B1_CashFlowForecastPredictDueDateDocumentsView" T0
						 WHERE	T0."ObjType" IN (SELECT "ObjType" FROM "CFF_TMP_OBJLIST" WHERE "ObjType" IN ('17', '22', '15', '234000031', '234000032', '17d', '22d', '15d', '234000031d', '234000032d'))
					)	T0
			LEFT JOIN	"CFF_TMP_PAYMENTDATE" T1 
				   ON	T1."CardCodePayment" = T0."CardCode"
				  AND	T1."DueDateDay" = DAYOFMONTH(T0."DueDateOnDoc")
				WHERE	T0."DueDate" IS NOT NULL
				)	T0
		LEFT JOIN	"CFF_TMP_HOLIDAY" T1
			   ON	T0."HldCode" = T1."HldCode"
			WHERE	T0."Group" IN (SELECT T2."Group" FROM "CFF_TMP_GROUP" T2)
			  AND	ADD_DAYS( T0."DueDateOnDoc", IFNULL(T1."Intervals", 0) + IFNULL(T0."AvrageLate", 0) ) >= :dateFrom
			  AND	T0."DueDateOnDoc" <= :dateTo
	UNION ALL
		SELECT	T0."DueDateOnDoc"						AS	"DocDueDate",
				T0."CalDueDate",
				MAP(T0."CardCodePayment", NULL, 0, 1)	AS	"AdjustDocDueDate",
				IFNULL(T0."NextMonth", 0)				AS	"DeltaMonths",
				IFNULL(T0."PmntDate", 0)				AS	"AdjustDay",
				T0."HldCode",
				T0."DocType",
				T0."DocEntry",
				T0."CardCode",
				T0."CtlAccount",
				T0."Debit",
				T0."Credit",
				T0."OriginalType",
				T0."Group",
				T0."InstID",
				T0."DocNum",
				T0."AvrageLate"
		FROM
			(		
			SELECT 	T0."DocEntry", 
					T0."DocNum", 
					T0."DocType",
					T0."CardCode", 
					T0."CtlAccount", 
					T0."TransId", 
					T0."JrnlMemo", 
					T0."ObjType", 
					T0."OriginalType",
					T0."CreateDate", 
					T0."TaxDate", 
					T0."ClsDate", 
					T0."GroupNum",  
					T0."DueDate", 
					MAP(T1."CardCodePayment", NULL, T0."DueDateOnDoc", ADD_MONTHS( ADD_DAYS( TO_DATE ( YEAR(T0."DueDateOnDoc") || '-' || ( MONTH(T0."DueDateOnDoc") || '-' || '01' ), 'YYYY-MM-DD'), IFNULL(T1."PmntDate", 0) - 1 ), IFNULL(T1."NextMonth", 0) ) ) AS "DueDateOnDoc",
					T0."Debit",
					T0."Credit", 
					T0."Group",	            
					T0."InstID",
					T0."AvrageLate", 
					MAP(T0."OriginalType", '22', :hldCode, '20', :hldCode, '21', :hldCode, '204', :hldCode, '18', :hldCode, '19', :hldCode, '163', :hldCode, '164', :hldCode, T0."HldCode") AS "HldCode",
					T0."CalDueDate",
					T0."PredictFlag",
					T0."Instance",
					T1."CardCodePayment",
					T1."NextMonth",
					T1."PmntDate"					
			FROM(
					SELECT	T0."DocEntry", 
							T0."DocNum", 
							T0."DocType",
							T0."CardCode", 
							T0."CtlAccount", 
							T0."TransId", 
							T0."JrnlMemo", 
							T0."ObjType",
							T0."OriginalType", 
							T0."CreateDate", 
							T0."TaxDate", 
							T0."ClsDate",
							T0."GroupNum",  
							T2."PlanDate"				AS "DueDate", 
							CASE	T0."PayDuMonth"
								WHEN 'N' THEN
									ADD_DAYS( ADD_MONTHS(T2."PlanDate", IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
								WHEN 'Y' THEN
									ADD_DAYS( ADD_MONTHS( ADD_DAYS( LAST_DAY(T2."PlanDate"), 1 ), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
								WHEN 'H' THEN
									ADD_DAYS( ADD_MONTHS( ADD_DAYS( LAST_DAY (T2."PlanDate"), 1 - DAYOFMONTH( LAST_DAY(T2."PlanDate") ) / 2 ), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
								WHEN 'E' THEN
									ADD_DAYS( ADD_MONTHS( LAST_DAY(T2."PlanDate"), IFNULL(T0."ExtraMonth", 0) + IFNULL(T0."InstMonth", 0) ), IFNULL(T0."ExtraDays", 0) + IFNULL(T0."InstDays", 0) - IFNULL(T0."TolDays", 0) )
								ELSE
									NULL
							END							AS "DueDateOnDoc",							
							T0."Debit" * IFNULL(T0."InstPrcnt", 100) * 0.01 AS "Debit", 
							T0."Credit" * IFNULL(T0."InstPrcnt", 100) * 0.01 AS "Credit", 
							T0."Group",  
							T0."InstID",
							T0."AvrageLate", 
							T0."HldCode",
							T2."PlanDate"				AS "CalDueDate",
							T0."PredictFlag",
							T2."Instance"
					  FROM	"B1_CashFlowForecastRecurringTrasactionView" T0
				INNER JOIN	
							(
								SELECT * 
								  FROM ORCL
							 UNION ALL
								SELECT *
								  FROM CFF_TMP_ORCL
							)	T2
						ON	T2."DocEntry" = T0."DocEntry" 
					   AND	ABS(T2."DocObjType") = T0."OriginalType" 
					   AND	T2."Status" = 'N'
					 WHERE	T0."ObjType" IN (SELECT "ObjType" FROM "CFF_TMP_OBJLIST")
			)	T0
		LEFT JOIN	"CFF_TMP_PAYMENTDATE" T1 
			   ON	T1."CardCodePayment" = T0."CardCode"
			  AND	T1."DueDateDay" = DAYOFMONTH(T0."DueDateOnDoc")
			WHERE	T0."DueDate" IS NOT NULL				
			)	T0
	LEFT JOIN	"CFF_TMP_HOLIDAY" T1
		   ON	T0."HldCode" = T1."HldCode"
		WHERE	T0."Group" IN (SELECT T2."Group" FROM "CFF_TMP_GROUP" T2)
		  AND	ADD_DAYS( T0."DueDateOnDoc", IFNULL(T1."Intervals", 0) + IFNULL(T0."AvrageLate", 0) ) >= :dateFrom
		  AND	T0."DueDateOnDoc" <= :dateTo;
	END IF;

	numDueDates = CE_Projection(:dueDates, [CE_calc('rownum()', integer) AS "AbsEntry", "DocDueDate", 
								"AdjustDocDueDate", "DeltaMonths", "AdjustDay", "HldCode", "DocType", "DocEntry", "CardCode", "CtlAccount", "Debit", "Credit", "OriginalType", "Group", "InstID", "DocNum", "AvrageLate"] );

	holidays = Select T0."HldCode",
					   "WndFrm",
					   "WndTo",
					   Case "isCurYear"
						 When 'Y' Then
						  1
						 Else
						  0
					   End											AS "IsCurYear",
					   Case "ignrWnd"
						 When 'Y' Then
						  1
						 Else
						  0
					   End											AS "IgnrWnd",
					   IFNULL(T1."StrDate", To_Date('00010101'))	AS "StrDate",
					   IFNULL(T1."EndDate", To_Date('00010101'))	AS "EndDate"
			  From OHLD T0
			  Left Join HLD1 T1
				On T0."HldCode" = T1."HldCode"
			 Order By T0."HldCode", T1."StrDate";
			 
	Call CFF_GETPREDICTDUEDATE(:numDueDates, :holidays, predictDates);

	--Consider Delays in Payments.
	IF :addDP = 'Y' THEN
		INSERT INTO "CFF_TMP_DETAIL"
		SELECT	ADD_DAYS(T0."PredictDueDate", IFNULL(T1."AvrageLate", 0)), 
				T1."DocType", 
				T1."DocEntry", 
				T1."CardCode",
				T1."CtlAccount" AS "ControlAccount", 
				NULL AS "Remarks", 
				T1."Debit", 
				T1."Credit",
				T1."OriginalType",
				T1."Group",
				T1."InstID",
				T1."DocNum"
		  FROM	:numDueDates T1, :predictDates T0
	 	 WHERE	T0."AbsEntry" = T1."AbsEntry"
		   	AND	ADD_DAYS(T0."PredictDueDate", IFNULL(T1."AvrageLate", 0)) >= :dateFrom
		   	AND	ADD_DAYS(T0."PredictDueDate", IFNULL(T1."AvrageLate", 0)) <= :dateTo
		UNION ALL
		SELECT	ADD_DAYS(T1."DocDueDate", IFNULL(T1."AvrageLate", 0)),
				T1."DocType", 
				T1."DocEntry", 
				T1."CardCode",
				T1."CtlAccount" AS "ControlAccount", 
				NULL AS "Remarks", 
				T1."Debit", 
				T1."Credit",
				T1."OriginalType",
				T1."Group",
				T1."InstID",
				T1."DocNum"
		  FROM	"B1_CashFlowForecastDueDateDocumentsView" T1,
		  		"OCRD" T0
		 WHERE	ADD_DAYS(T1."DocDueDate", IFNULL(T0."AvrageLate", 0)) >= :dateFrom
		   AND	ADD_DAYS(T1."DocDueDate", IFNULL(T0."AvrageLate", 0)) <= :dateTo
		   AND	T1."ObjType" IN (SELECT "ObjType" FROM "CFF_TMP_OBJLIST")
		   AND  T1."Group" IN (SELECT T2."Group" FROM "CFF_TMP_GROUP" T2)
		   AND	T1."CardCode" = T0."CardCode";
	ELSE
		INSERT INTO "CFF_TMP_DETAIL"
		SELECT	T0."PredictDueDate", 
				T1."DocType", 
				T1."DocEntry", 
				T1."CardCode",
				T1."CtlAccount" AS "ControlAccount", 
				NULL AS "Remarks", 
				T1."Debit", 
				T1."Credit",
				T1."OriginalType",
				T1."Group",
				T1."InstID",
				T1."DocNum"
		  FROM	:numDueDates T1, :predictDates T0
	 	 WHERE	T0."AbsEntry" = T1."AbsEntry"
	 	   AND	T0."PredictDueDate" >= :dateFrom
		   AND	T0."PredictDueDate" <= :dateTo
		UNION ALL
		SELECT	T1."DocDueDate",
				T1."DocType", 
				T1."DocEntry", 
				T1."CardCode",
				T1."CtlAccount" AS "ControlAccount", 
				NULL AS "Remarks", 
				T1."Debit", 
				T1."Credit",
				T1."OriginalType",
				T1."Group",
				T1."InstID",
				T1."DocNum"
		  FROM	"B1_CashFlowForecastDueDateDocumentsView" T1,
		  		"OCRD" T0
		 WHERE	ADD_DAYS(T1."DocDueDate", IFNULL(T0."AvrageLate", 0)) >= :dateFrom
		   AND	ADD_DAYS(T1."DocDueDate", IFNULL(T0."AvrageLate", 0)) <= :dateTo
		   AND	T1."ObjType" IN (SELECT "ObjType" FROM "CFF_TMP_OBJLIST")
		   AND  T1."Group" IN (SELECT T2."Group" FROM "CFF_TMP_GROUP" T2)
		   AND	T1."CardCode" = T0."CardCode";
	END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_FILLPAYMENTDATE AFTER:SP:CFF_GETPREDICTDUEDATE

CREATE PROCEDURE CFF_DOCUMENT_OVERVIEW (IN dateFrom		DATE, 
										IN dateTo		DATE, 
										IN interval		NVARCHAR(1),
									    IN addRT		NVARCHAR(1),
									    IN addDD		NVARCHAR(1),
									    IN addDP		NVARCHAR(1)
										) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	
	CALL CFF_DOCUMENT_DETAIL(:dateFrom, :dateTo, :addRT, :addDD, :addDP);
	
	INSERT INTO "CFF_TMP_OVERVIEW"
	SELECT  T1."Index",
			T1."EndDate", 
			SUM(T0."Debit"), 
			SUM(T0."Credit"), 
			T0."ObjType", 
			T0."Group", 
			COUNT(*)
	  FROM	"CFF_TMP_DETAIL" T0,
			"CFF_TMP_DATE" T1
	 WHERE	T0."DueDate" BETWEEN  T1."StartDate" AND T1."EndDate"
  GROUP BY	T1."EndDate", T0."ObjType", T1."Index", T0."Group";
	
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_FILLBOEACCT () 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 

BEGIN 	
	
	DELETE FROM "CFF_TMP_BOEACCT";

	INSERT INTO "CFF_TMP_BOEACCT"

	SELECT "CBoERcvble" FROM "OACP" WHERE  "CBoERcvble" IS NOT NULL UNION
	SELECT "CBoEOnClct" FROM "OACP" WHERE  "CBoEOnClct" IS NOT NULL UNION
	SELECT "CBoEPresnt" FROM "OACP" WHERE  "CBoEPresnt" IS NOT NULL UNION
	SELECT "CBoEDiscnt" FROM "OACP" WHERE  "CBoEDiscnt" IS NOT NULL UNION
	SELECT "CUnpaidBoE" FROM "OACP" WHERE  "CUnpaidBoE" IS NOT NULL UNION
	SELECT "VBoEPayble" FROM "OACP" WHERE  "VBoEPayble" IS NOT NULL UNION
	SELECT "VAsstBoEPy" FROM "OACP" WHERE  "VAsstBoEPy" IS NOT NULL UNION
	SELECT DISTINCT "AcctCode" FROM "CRD3" WHERE "AcctType" IN ('R', 'P', 'C', 'S', 'Y', 'I', 'U') ;

END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_FILLDATETABLE (IN dateFrom		DATE, 
									IN dateTo		DATE, 
									IN intervalVal	NVARCHAR(1)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	dateIter	DATE;
	dateEnd		DATE;
	iter		INTEGER;
	months		INTEGER;
BEGIN
	dateIter := :dateFrom;
	iter := 1;
	months := 1;
	WHILE (:dateIter <= :dateTo) DO
		IF (:intervalVal = 'D') THEN
			INSERT INTO "CFF_TMP_DATE" VALUES (:dateIter, :dateIter, :iter-1);
			dateIter := ADD_DAYS(:dateIter, 1);
		ELSEIF (:intervalVal = 'W') THEN
			dateEnd := ADD_DAYS(ADD_DAYS(:dateIter, 7), -1);
			IF(:dateEnd > :dateTo) THEN
				dateEnd := :dateTo;
			END IF;
			INSERT INTO "CFF_TMP_DATE" VALUES (:dateIter, :dateEnd, :iter-1);
			dateIter := ADD_DAYS(:dateIter, 7);
		ELSE
			dateEnd := ADD_DAYS(ADD_MONTHS(:dateFrom, :months), -1);
			IF(:dateEnd > :dateTo) THEN
				dateEnd := :dateTo;
			END IF;
			INSERT INTO "CFF_TMP_DATE" VALUES (:dateIter, :dateEnd, :iter-1);
			dateIter := ADD_DAYS(:dateEnd, 1);
			months := :months + 1;
		END IF;
				
		iter := :iter + 1;
	END WHILE;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_FILLPAYMENTDATE 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	cardCode			NVARCHAR(15);
	cardCodeBeforeNext	NVARCHAR(15);
	siPmntDate			SMALLINT;
	siPmntDateDayFirst	SMALLINT;
	siDueDateDay		SMALLINT;
	
	perCount			INT;
	
	CURSOR c_cursor FOR 
		SELECT T0."CardCode", T0."PmntDate" FROM (SELECT "CardCode", CAST("PmntDate" AS SMALLINT) AS "PmntDate" FROM "CRD5") T0 
		ORDER BY T0."CardCode" ASC, T0."PmntDate" ASC; 
BEGIN
	
	OPEN c_cursor;

	IF c_cursor::ISCLOSED THEN
		RETURN;		
	END IF;	
	
	FETCH c_cursor INTO cardCode, siPmntDate;
	
	perCount := 1;
	siPmntDateDayFirst := :siPmntDate;
	siDueDateDay := 1;
	
	WHILE NOT c_cursor::NOTFOUND DO 
		
		WHILE :siDueDateDay <= :siPmntDate DO
			INSERT INTO "CFF_TMP_PAYMENTDATE" VALUES (:cardCode, :siDueDateDay, :siPmntDate, 0);
			siDueDateDay := :siDueDateDay + 1;
		END WHILE;
		
		cardCodeBeforeNext := :cardCode;
				
		FETCH c_cursor INTO cardCode, siPmntDate;
		IF c_cursor::NOTFOUND THEN
			BREAK;
		END IF;
		perCount := :perCount + 1;
		
		IF :cardCodeBeforeNext <> :cardCode THEN
			WHILE :siDueDateDay <= 31 DO
				INSERT INTO "CFF_TMP_PAYMENTDATE" VALUES (:cardCodeBeforeNext, :siDueDateDay, :siPmntDateDayFirst, 1);
				siDueDateDay := :siDueDateDay + 1;
			END WHILE;
			siPmntDateDayFirst := :siPmntDate;
			siDueDateDay := 1;
		END IF; 
	END WHILE;
	
	WHILE siDueDateDay <= 31 AND cardCodeBeforeNext IS NOT NULL DO
		INSERT INTO "CFF_TMP_PAYMENTDATE" VALUES (:cardCodeBeforeNext, :siDueDateDay, :siPmntDateDayFirst, 1);
		siDueDateDay := :siDueDateDay + 1;
	END WHILE;
	
	CLOSE c_cursor;
	 
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_PARSEOBJLIST AFTER:SP:CFF_PARSEOPTIONS AFTER:SP:CFF_FILLBOEACCT AFTER:SP:CFF_BLANKETAGREEMENT_DETAIL
CREATE PROCEDURE CFF_GENERAL_DETAIL (IN	dateFrom	DATE, 
									 IN	dateTo		DATE, 
									 IN	addRP		NVARCHAR(1),
									 IN	addBA		NVARCHAR(1),
									 IN	addJV		NVARCHAR(1),
									 IN	addDP		NVARCHAR(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	frequency		NVARCHAR(1);
	subFrequency	SMALLINT;
	limitFlag		NVARCHAR(1);
	limitDate		TIMESTAMP;
	currency		NVARCHAR(3);
	ctrlAcct			NVARCHAR(15);
	acctCode		NVARCHAR(15);
	nextDue			TIMESTAMP;
	debit			DECIMAL(21,6);
	credit			DECIMAL(21,6);
	mainInstance	SMALLINT;
	subInstance		SMALLINT;
	rcurCode		NVARCHAR(20);
	rcurDesc		NVARCHAR(50);
	newNextDue		DATE;
	filterInBPFlag	NVARCHAR(1);
CURSOR RecurTransQry(qyDateTo DATE) for 
	SELECT T0."Frequency", T0."Remind", T0."LimitRtrns", T0."LimitDate", T1."Currency", T1."CtrlAcct", T1."AcctCode", T0."Instance" as "MainInstance", T1."Instance" as "SubInstance", T0."NextDeu", T1."Debit", T1."Credit", T1."RcurCode", T0."RcurDesc" 
			FROM "ORCR" T0 INNER JOIN "RCR1" T1 ON T1."RcurCode" = T0."RcurCode" 
			WHERE T0."Frequency" <> 'T' AND T0."NextDeu" <= :qyDateTo AND (T0."LimitRtrns" <> 'Y' OR T0."NextDeu" <= T0."LimitDate") ;
BEGIN 	
	-- Fill BOE table
	CALL CFF_FILLBOEACCT ();
	-- Fill date table
	INSERT INTO "CFF_TMP_DATE" VALUES(:dateFrom, :dateTo, -1);
			
--	SELECT "DspFrznBP" INTO filterInBPFlag FROM "OADM";
	
	-- Filter the inactive BP
--	IF(:filterInBPFlag = 'Y') THEN
--		INSERT INTO "OCRD" SELECT "CardCode", "CardType", "AvrageLate" FROM "OCRD";
--	ELSE
--		INSERT INTO "OCRD" SELECT "CardCode", "CardType", "AvrageLate" FROM "OCRD" 
--			WHERE ("CardCode" IS NULL OR 
--					("validFor"='Y' OR ("frozenFor" = 'Y' AND ("frozenFrom" IS NOT NULL OR "frozenTo" IS NOT NULL )) OR ("validFor" = 'N' AND "frozenFor" = 'N')));
--	END IF;
	
	-- AcctType: 'B' represent BOE account, 'N' represent NOT BOE account
	--BOEAcctResult = SELECT DISTINCT "AcctCode", "CardCode", (CASE WHEN "AcctType" IN ('R', 'P', 'C', 'S', 'Y', 'I', 'U') THEN 'BOE' ELSE 'NBOE' END) AS "AcctType" FROM "CRD3";
	
	--- No OPEN balance
	--- Cash, ObjType='A'
	INSERT INTO "CFF_TMP_DETAIL" 
	SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
		SELECT T0."DueDate" AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
				T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
				IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-50' AS "ObjType",(CASE WHEN IFNULL(T0."BalDueDeb",0) <> 0 THEN 'CI' ELSE 'CO' END) AS "Group" 
		FROM "JDT1" T0 
		INNER JOIN "OACT" T1 ON T0."Account" = T1."AcctCode"
		WHERE T0."Account" = T0."ShortName" 
			AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
			AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
			AND T1."Finanse" = 'Y'
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group"; 
		 
	--- Check, ObjType='C'
	INSERT INTO "CFF_TMP_DETAIL" 
	SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
		SELECT T0."DueDate" AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
				T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
				IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-27' AS "ObjType",(CASE WHEN IFNULL(T0."BalDueDeb",0) <> 0 THEN 'CI' ELSE 'CO' END) AS "Group" 
		FROM "JDT1" T0 
		WHERE T0."Account" = T0."ShortName" 
			AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
			AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)					
			AND T0."Account" IN (SELECT DISTINCT "CashCheck" FROM "OCHH")
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";
		 	 
	--- Credit, ObjType='D'
	INSERT INTO "CFF_TMP_DETAIL" 
	SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
		SELECT T0."DueDate" AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry",  T0."BaseRef" AS "DocNum",
				T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
				IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-72' AS "ObjType", (CASE WHEN IFNULL(T0."BalDueDeb",0) <> 0 THEN 'CI' ELSE 'CO' END) AS "Group" 
		FROM "JDT1" T0 
		INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T1 ON T0."Account" = T1."CreditAcct"
		WHERE T0."Account" = T0."ShortName" 
			AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
			AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group"; 
		 
	--- BoE, ObjType='E'
	IF (:addDP = 'Y') THEN
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT ADD_DAYS(T0."DueDate", IFNULL(T2."AvrageLate",0)) AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T2."CardType" = 'C' THEN 'CI' ELSE 'CO' END) AS "Group" 
			FROM "JDT1" T0 
			INNER JOIN "CFF_TMP_BOEACCT" T1 ON T0."Account" = T1."AcctCode"
			INNER JOIN "OCRD" T2 ON T0."ShortName" = T2."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
				AND (ADD_DAYS(T0."DueDate", IFNULL(T2."AvrageLate",0)) BETWEEN :dateFrom AND :dateTo)	 
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";	
	ELSE
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T2."CardType" = 'C' THEN 'CI' ELSE 'CO' END) AS "Group" 
			FROM "JDT1" T0 
			INNER JOIN "CFF_TMP_BOEACCT" T1 ON T0."Account" = T1."AcctCode"
			INNER JOIN "OCRD" T2 ON T0."ShortName" = T2."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo) 
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";	
	END IF;
		 
	--- Customer Liabilities, ObjType='M'
	IF(:addDP = 'Y') THEN
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT ADD_DAYS(T0."DueDate", IFNULL (T1."AvrageLate",0)) AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", T0."TransType" AS "ObjType", 'CI' AS "Group" 
			FROM "JDT1" T0 
			INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
				AND (ADD_DAYS(T0."DueDate", IFNULL (T1."AvrageLate",0)) BETWEEN :dateFrom AND :dateTo)
				AND T1."CardType" = 'C'
				AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 			
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";	
	ELSE
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", T0."TransType" AS "ObjType", 'CI' AS "Group" 
			FROM "JDT1" T0 
			INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
				AND T1."CardType" = 'C'
				AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 			
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";	
	END IF;
		 		
	--- Debts to Vendors, ObjType='V'
	IF (:addDP = 'Y') THEN
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT ADD_DAYS(T0."DueDate", IFNULL (T1."AvrageLate",0)) AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", T0."TransType" AS "ObjType", 'CO' AS "Group" 
			FROM "JDT1" T0
			INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
				AND (ADD_DAYS(T0."DueDate", IFNULL (T1."AvrageLate",0)) BETWEEN :dateFrom AND :dateTo)
				AND T1."CardType" = 'S'
				AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 			

			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";			
	ELSE
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", T0."TransType" AS "DocType", T0."CreatedBy" AS "DocEntry", T0."BaseRef" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", T0."TransType" AS "ObjType", 'CO' AS "Group" 
			FROM "JDT1" T0
			INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
				AND T1."CardType" = 'S'
				AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 				
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";			
	END IF;		
	
	IF(:addJV = 'Y') THEN
		--- Journal Voucher, no OPEN balance
		--- Cash, ObjType='A'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", '28' AS "DocType", T0."BatchNum" AS "DocEntry", T0."BatchNum" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-50' AS "ObjType",(CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "BTF1" T0 
			INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
			INNER JOIN "OACT" T3 ON T0."Account" = T3."AcctCode"
			WHERE T0."Account" = T0."ShortName"
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)  
				AND T1."BtfStatus" <> 'C'
				AND T3."Finanse" = 'Y' 
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";
			 	
		--- Check, ObjType='C'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", '28' AS "DocType", T0."BatchNum" AS "DocEntry", T0."BatchNum" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-27' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "BTF1" T0 
			INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
			WHERE T0."Account" = T0."ShortName"
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)  
				AND T1."BtfStatus" <> 'C'
				AND T0."Account" IN (SELECT DISTINCT "CashCheck" FROM "OCHH")
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group"; 
			 	
		--- Credit, ObjType='D'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", '28' AS "DocType", T0."BatchNum" AS "DocEntry", T0."BatchNum" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-72' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "BTF1" T0
			INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
			INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T3 ON T0."Account" = T3."CreditAcct"
			WHERE T0."Account" = T0."ShortName"
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
				AND T1."BtfStatus" <> 'C'
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group"; 
			 	
		--- BOE, ObjType='E'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", '28' AS "DocType", T0."BatchNum" AS "DocEntry", T0."BatchNum" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T2."CardType" = 'C' THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "BTF1" T0 
			INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
			INNER JOIN "OCRD" T2 ON T0."ShortName" = T2."CardCode"
			INNER JOIN "CFF_TMP_BOEACCT" T3 ON T0."Account" = T3."AcctCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
				AND T1."BtfStatus" <> 'C'
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";
			
		--- Customer Liabilities, ObjType='M'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" FROM(
			SELECT T0."DueDate" AS "DueDate", '28' AS "DocType", T0."BatchNum" AS "DocEntry", T0."BatchNum" AS "DocNum",
					T0."ShortName" AS "CtrlAcct", T0."Account" AS "Account", T0."LineMemo" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", 
					CASE WHEN T2."CardType" = 'C' THEN '17' ELSE '22' END AS "ObjType", 
					CASE WHEN T2."CardType" = 'C' THEN 'SF' ELSE 'EF' END AS "Group" 
			FROM "BTF1" T0 
			INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
			INNER JOIN "OCRD" T2 ON T0."ShortName" = T2."CardCode"
			WHERE T0."Account" <> T0."ShortName"
				AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
				AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 				
				AND T1."BtfStatus" <> 'C'
				AND T2."CardType" IN ('C','S')
			) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
					INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";

		--- Debts to Vendors, ObjType='V'

	END IF;
	
	--- Recurring postings
	IF(:addRP = 'Y') THEN
		OPEN RecurTransQry(:dateTo);
		FETCH RecurTransQry INTO frequency, subFrequency, limitFlag, limitDate, currency, ctrlAcct, acctCode, mainInstance, subInstance, nextDue, debit, credit, rcurCode, rcurDesc;
		WHILE NOT RecurTransQry::NOTFOUND DO
			newNextDue := :nextDue;		-- This is a workaround for HANA. Otherwise nextDue will be null when insert into the table.
			WHILE :newNextDue <= :dateTo AND (:limitFlag <> 'Y' OR :newNextDue <= :limitDate) DO
				-- Not OPEN balance
				IF(:newNextDue >= :dateFrom AND :mainInstance = :subInstance AND (:frequency <> 'O' OR :mainInstance <> 0)) THEN
					INSERT INTO "CFF_TMP_DETAIL_RP" VALUES(:newNextDue, :debit, :credit, :acctCode, :ctrlAcct, :rcurCode, :rcurDesc);
				END IF;
								
				IF (:frequency = 'D') THEN
					newNextDue := ADD_DAYS(:newNextDue, 1);
				ELSEIF (:frequency = 'W') THEN
					newNextDue := ADD_DAYS(:newNextDue, 7);
				ELSEIF (:frequency = 'A') THEN
					newNextDue := ADD_YEARS(:newNextDue, 1);
				ELSEIF (:frequency = 'M') THEN
					newNextDue := ADD_MONTHS(:newNextDue, 1);
				ELSEIF (:frequency = 'S') THEN
					newNextDue := ADD_MONTHS(:newNextDue, 6);
				ELSEIF (:frequency = 'Q') THEN
					newNextDue := ADD_MONTHS(:newNextDue, 3);
				ELSEIF (:frequency = 'O') THEN
					break;
				ELSE
				 	newNextDue := ADD_DAYS(:newNextDue, 7);
				END IF;
			END WHILE;
			FETCH RecurTransQry INTO frequency, subFrequency, limitFlag, limitDate, currency, ctrlAcct, acctCode, mainInstance, subInstance, nextDue, debit, credit, rcurCode, rcurDesc;
		END WHILE;
		close RecurTransQry;
		
		--- No OPEN balance
		--- Cash, ObjType='A'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" 
		FROM (
			SELECT T0."DueDate" AS "DueDate", '34' AS "DocType", T0."DocEntry" AS "DocEntry", T0."DocEntry" AS "DocNum",
					T0."CtrlAcct" AS "CtrlAcct", T0."AcctCode" AS "Account", T0."Remarks" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-50' AS "ObjType",(CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "CFF_TMP_DETAIL_RP" T0 
			INNER JOIN "OACT" T1 ON T0."CtrlAcct" = T1."AcctCode"
			WHERE T0."AcctCode" = T0."CtrlAcct"
				AND T1."Finanse" = 'Y' 
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";
			 
		--- Check, ObjType='C'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" 
		FROM (
			SELECT T0."DueDate" AS "DueDate", '34' AS "DocType", T0."DocEntry" AS "DocEntry", T0."DocEntry" AS "DocNum",
					T0."CtrlAcct" AS "CtrlAcct", T0."AcctCode" AS "Account", T0."Remarks" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-27' AS "ObjType",(CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "CFF_TMP_DETAIL_RP" T0 
			WHERE T0."AcctCode" = T0."CtrlAcct"
				AND T0."CtrlAcct" IN (SELECT DISTINCT "CashCheck" FROM "OCHH") 
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";
			
		--- Credit, ObjType='D'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" 
		FROM (
			SELECT T0."DueDate" AS "DueDate", '34' AS "DocType", T0."DocEntry" AS "DocEntry", T0."DocEntry" AS "DocNum",
					T0."CtrlAcct" AS "CtrlAcct", T0."AcctCode" AS "Account", T0."Remarks" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-72' AS "ObjType",(CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "CFF_TMP_DETAIL_RP" T0 
			INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T1 ON T0."CtrlAcct" = T1."CreditAcct"
			WHERE T0."AcctCode" = T0."CtrlAcct"
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group"; 
 	
		--- BoE, ObjType='E'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" 
		FROM (
			SELECT T0."DueDate" AS "DueDate", '34' AS "DocType", T0."DocEntry" AS "DocEntry", T0."DocEntry" AS "DocNum",
					T0."CtrlAcct" AS "CtrlAcct", T0."AcctCode" AS "Account", T0."Remarks" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-182' AS "ObjType",(CASE WHEN T2."CardType" = 'C' THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "CFF_TMP_DETAIL_RP" T0 
			INNER JOIN "CFF_TMP_BOEACCT" T1 ON T0."CtrlAcct" = T1."AcctCode"
			INNER JOIN "OCRD" T2 ON T0."AcctCode" = T2."CardCode"
			WHERE T0."AcctCode" <> T0."CtrlAcct"
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group"; 
			 	
		--- Customer Liabilities, ObjType='M'
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" 
		FROM (
			SELECT T0."DueDate" AS "DueDate", '34' AS "DocType", T0."DocEntry" AS "DocEntry", T0."DocEntry" AS "DocNum",
					T0."CtrlAcct" AS "CtrlAcct", T0."AcctCode" AS "Account", T0."Remarks" AS "Remarks", 
					IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", 
					CASE WHEN T1."CardType" = 'C' THEN '17' ELSE '22' END AS "ObjType", 
					CASE WHEN T1."CardType" = 'C' THEN 'SF' ELSE 'EF' END AS "Group" 
			FROM "CFF_TMP_DETAIL_RP" T0 
			INNER JOIN "OCRD" T1 ON T0."AcctCode" = T1."CardCode"
			WHERE T0."AcctCode" <> T0."CtrlAcct"
				AND T1."CardType" IN ('C','S')
				AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."CtrlAcct" ) 	 
				
		)AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";  
		--- Debts to Vendors, ObjType='V'
		
	END IF;	
	
	--- Blanket Agreement
	IF(:addBA = 'Y') THEN
		CALL CFF_BLANKETAGREEMENT_DETAIL(:dateFrom, :dateTo);
		INSERT INTO "CFF_TMP_DETAIL" 
		SELECT T5."DueDate", T5."DocType", T5."DocEntry", T5."CtrlAcct", T5."Account", T5."Remarks", T5."Debit", T5."Credit", T5."ObjType", T5."Group", 1, T5."DocNum" 
		FROM (
			SELECT * FROM "CFF_TMP_DETAIL_BA"
		) AS T5 INNER JOIN "CFF_TMP_OBJLIST" T6 ON T5."ObjType" = T6."ObjType"
				INNER JOIN  "CFF_TMP_GROUP" T7 ON T7."Group" = T5."Group";
	
	END IF;
					
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_PARSEOPTIONS AFTER:SP:CFF_PARSEOBJLIST AFTER:SP:CFF_FILLDATETABLE AFTER:SP:CFF_FILLBOEACCT AFTER:SP:CFF_BLANKETAGREEMENT_OVERVIEW
CREATE PROCEDURE CFF_GENERAL_OVERVIEW (IN	dateFrom	DATE, 
									   IN	dateTo		DATE, 
									   IN	intervalVal	NVARCHAR(1),
									   IN 	addRP 		NVARCHAR(1),
									   IN	addBA 		NVARCHAR(1),
									   IN	addJV 		NVARCHAR(1),
									   IN	addDP 		NVARCHAR(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	frequency		NVARCHAR(1);
	subFrequency	SMALLINT;
	limitFlag		NVARCHAR(1);
	limitDate		TIMESTAMP;
	currency		NVARCHAR(3);
	ctrlAcct		NVARCHAR(15);
	acctCode		NVARCHAR(15);
	nextDue			TIMESTAMP;
	Debit			DECIMAL(21,6);
	credit			DECIMAL(21,6);
	mainInstance	SMALLINT;
	subInstance		SMALLINT;
	newNextDue		DATE;
	filterInBPFlag	NVARCHAR(1);
	addBB			INTEGER;
	addCB           INTEGER;
CURSOR RecurTransQry(qyDateTo DATE) FOR 
	SELECT T0."Frequency", T0."Remind", T0."LimitRtrns", T0."LimitDate", T1."Currency", T1."CtrlAcct", T1."AcctCode", T0."Instance" as "MainInstance", T1."Instance" as "SubInstance", T0."NextDeu", T1."Debit", T1."Credit" 
			FROM "ORCR" T0 INNER JOIN "RCR1" T1 ON T1."RcurCode" = T0."RcurCode" 
			WHERE T0."Frequency" <> 'T' AND T0."NextDeu" <= :qyDateTo AND (T0."LimitRtrns" <> 'Y' OR T0."NextDeu" <= T0."LimitDate") ;
BEGIN 	
	-- Fill Date table
	CALL CFF_FILLDATETABLE(:dateFrom, :dateTo, :intervalVal);
	-- Fill BOE table
	CALL CFF_FILLBOEACCT ();
	
	SELECT COUNT(*) INTO addBB FROM "CFF_TMP_GROUP" WHERE "Group" = 'BB';
	SELECT COUNT(*) INTO addCB FROM "CFF_TMP_GROUP" WHERE "Group" = 'CB';
	
--	SELECT "DspFrznBP" INTO filterInBPFlag FROM "OADM";
	
	-- Filter the inactive BP
--	IF(:filterInBPFlag = 'Y') THEN
--		INSERT INTO "OCRD" SELECT "CardCode", "CardType", "AvrageLate" FROM "OCRD";
--	ELSE
--		INSERT INTO "OCRD" SELECT "CardCode", "CardType", "AvrageLate" FROM "OCRD" 
--			WHERE ("CardCode" IS NULL OR 
--					("validFor"='Y' OR ("frozenFor" = 'Y' AND ("frozenFrom" IS NOT NULL OR "frozenTo" IS NOT NULL )) OR ("validFor" = 'N' AND "frozenFor" = 'N')));
--	END IF;
	
	-- AcctType: 'B' represent BOE account, 'N' represent NOT BOE account
--	BOEAcctResult = SELECT DISTINCT "AcctCode", "CardCode", (CASE WHEN "AcctType" IN ('R', 'P', 'C', 'S', 'Y', 'I', 'U') THEN 'BOE' ELSE 'NBOE' END) AS "AcctType" FROM "CRD3";
	
			
	--- No OPEN balance
	ResultNOB = SELECT T5."EndDate" AS "EndDate", SUM(T5."Debit") AS "Debit", SUM(T5."Credit") AS "Credit", T5."ObjType" AS "ObjType", T5."Group" AS "Group", COUNT(*) AS "Number" FROM (
		--- Cash, ObjType='A'
		SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-50' AS "ObjType", (CASE WHEN IFNULL(T0."BalDueDeb",0) <> 0 THEN 'CI' ELSE 'CO' END) AS "Group" 
			FROM "JDT1" T0 
				INNER JOIN "OACT" T1 ON T0."Account" = T1."AcctCode"
				INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
				WHERE T0."Account" = T0."ShortName" 
					AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
					AND T1."Finanse" = 'Y' 
		UNION ALL 
		--- Check, ObjType='C'
		SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-27' AS "ObjType", (CASE WHEN IFNULL(T0."BalDueDeb",0) <> 0 THEN 'CI' ELSE 'CO' END) AS "Group"
			FROM "JDT1" T0 
				INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
				WHERE T0."Account" = T0."ShortName" 
					AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
					AND T0."Account" IN (SELECT DISTINCT "CashCheck" FROM "OCHH") 
		UNION ALL 
		--- Credit, ObjType='D'
		SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-72' AS "ObjType", (CASE WHEN IFNULL(T0."BalDueDeb",0) <> 0 THEN 'CI' ELSE 'CO' END) AS "Group"
			FROM "JDT1" T0 
				INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T1 ON T0."Account" = T1."CreditAcct"
				INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
				WHERE T0."Account" = T0."ShortName" 
					AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0) 
		) AS T5 GROUP BY T5."EndDate", T5."ObjType", T5."Group";
		
	IF (:addDP = 'Y') THEN
		ResultNOBDP = SELECT T5."EndDate" AS "EndDate", SUM(T5."Debit") AS "Debit", SUM(T5."Credit") AS "Credit", T5."ObjType" AS "ObjType", T5."Group" AS "Group", COUNT(*) AS "Number" FROM (
		--- BoE, ObjType='E'
			SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T3."CardType" = 'C' THEN 'CI' ELSE 'CO' END) AS "Group"
				FROM "JDT1" T0 
					INNER JOIN "CFF_TMP_BOEACCT" T1 ON T0."Account" = T1."AcctCode"
					INNER JOIN "OCRD" T3 ON T0."ShortName" = T3."CardCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON ADD_DAYS(T0."DueDate", IFNULL(T3."AvrageLate",0) ) BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."Account" <> T0."ShortName"
						AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)		
			UNION ALL			
			--- Customer Liabilities, ObjType='M'
			SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", T0."TransType" AS "ObjType", 
				CASE WHEN T1."CardType"='C' THEN 'CI' ELSE 'CO' END AS "Group"
				FROM "JDT1" T0 
					INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON ADD_DAYS(T0."DueDate", IFNULL( T1."AvrageLate",0) ) BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."Account" <> T0."ShortName"
						AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
						AND T1."CardType" IN ('C','S')
						AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 
			) AS T5 GROUP BY T5."EndDate", T5."ObjType", T5."Group";
	ELSE
		ResultNOBDP = SELECT T5."EndDate" AS "EndDate", SUM(T5."Debit") AS "Debit", SUM(T5."Credit") AS "Credit", T5."ObjType" AS "ObjType", T5."Group" AS "Group", COUNT(*) AS "Number" FROM (
			--- BoE, ObjType='E'
			SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T3."CardType" = 'C' THEN 'CI' ELSE 'CO' END) AS "Group"
				FROM "JDT1" T0 
					INNER JOIN "CFF_TMP_BOEACCT" T1 ON T0."Account" = T1."AcctCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					INNER JOIN "OCRD" T3 ON T0."ShortName" = T3."CardCode"
					WHERE T0."Account" <> T0."ShortName"
						AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
			UNION ALL								
			--- Customer Liabilities, ObjType='M'
			SELECT T2."EndDate", IFNULL(T0."BalDueDeb",0) AS "Debit", IFNULL(T0."BalDueCred",0) AS "Credit", T0."TransType" AS "ObjType", 
				CASE WHEN T1."CardType"='C' THEN 'CI' ELSE 'CO' END AS "Group"
				FROM "JDT1" T0 
					INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."Account" <> T0."ShortName"
						AND (IFNULL(T0."BalDueDeb",0) <> 0 OR IFNULL(T0."BalDueCred",0) <> 0)
						AND T1."CardType" IN ('C','S')
						AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 	 
			) AS T5 GROUP BY T5."EndDate", T5."ObjType", T5."Group";	
	END IF;
												
	--- Open balance
	IF	(:addBB > 0) THEN
		ResultOB = SELECT :dateFrom AS "EndDate", SUM (T5."OpenBalance") AS "Debit", 0.0 AS "Credit", T5."ObjType" AS "ObjType", T5."Group" AS "Group", COUNT(*) AS "Number" FROM (
			--- Cash, ObjType='A'
			SELECT SUM(IFNULL(T0."BalDueDeb",0) - IFNULL(T0."BalDueCred",0)) AS "OpenBalance", '-50' AS "ObjType", 'BB' AS "Group" 
				FROM "JDT1" T0 
					INNER JOIN "OACT" T1 ON T0."Account" = T1."AcctCode"
					WHERE T0."DueDate" < :dateFrom
						AND (:addCB > 0 OR T0."TransType" <> '-3')
						AND T0."Account" = T0."ShortName"
						AND T1."Finanse" = 'Y'
			UNION ALL 
			--- Check, ObjType='C'
			SELECT SUM(IFNULL(T0."BalDueDeb",0) - IFNULL(T0."BalDueCred",0)) AS "OpenBalance", '-27' AS "ObjType", 'BB' AS "Group" 
				FROM "JDT1" T0 
					WHERE T0."DueDate" < :dateFrom
						AND (:addCB > 0 OR T0."TransType" <> '-3') 
						AND T0."Account" = T0."ShortName"
						AND T0."Account" IN (SELECT DISTINCT "CashCheck" FROM "OCHH") 
			UNION ALL 	
			--- Credit, ObjType='D'
			SELECT SUM(IFNULL(T0."BalDueDeb",0) - IFNULL(T0."BalDueCred",0)) AS "OpenBalance", '-72' AS "ObjType", 'BB' AS "Group" 
				FROM "JDT1" T0 
					INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T1 ON T0."Account" = T1."CreditAcct"
					WHERE T0."DueDate" < :dateFrom
						AND (:addCB > 0 OR T0."TransType" <> '-3') 
						AND T0."Account" = T0."ShortName" 
			UNION ALL 
			--- BoE, ObjType='E'
			SELECT SUM(IFNULL(T0."BalDueDeb",0) - IFNULL(T0."BalDueCred",0)) AS "OpenBalance", '-182' AS "ObjType", 'BB' AS "Group"
				FROM "JDT1" T0 
					INNER JOIN "CFF_TMP_BOEACCT" T1 ON T0."Account" = T1."AcctCode"
					WHERE T0."DueDate" < :dateFrom 
						AND T0."Account" <> T0."ShortName"
						AND (:addCB > 0 OR T0."TransType" <> '-3')
			UNION ALL 
			--- Customer Liabilities, ObjType='M'
			SELECT SUM(IFNULL(T0."BalDueDeb",0) - IFNULL(T0."BalDueCred",0)) AS "OpenBalance", T0."TransType" AS "ObjType", 'BB' AS "Group"
				FROM "JDT1" T0 
					INNER JOIN "OCRD" T1 ON T0."ShortName" = T1."CardCode"
					WHERE T0."DueDate" < :dateFrom 
						AND T0."Account" <> T0."ShortName"
						AND T1."CardType" IN ('C','S')
						AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 	 
						
					GROUP BY T0."TransType" 
		
			) T5 GROUP BY T5."ObjType", T5."Group" ;	
	ELSE
		ResultOB = SELECT :dateFrom AS "EndDate", 0.0 AS "Debit", 0.0 AS "Credit", 'X' AS "ObjType", 'BB' AS "Group", 0 AS "Number" FROM dummy;
	END IF;
		
	
	IF (:addJV = 'Y') THEN
		--- Journal Voucher, no OPEN balance
		ResultNOBJV = SELECT T5."EndDate" AS "EndDate", SUM(T5."Debit") AS "Debit", SUM(T5."Credit") AS "Credit", T5."ObjType" AS "ObjType", T5."Group" AS "Group", COUNT(*) AS "Number" FROM (
			--- Cash, ObjType='A'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-50' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0) <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
				FROM "BTF1" T0 
					INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					INNER JOIN "OACT" T3 ON T0."Account" = T3."AcctCode"
					WHERE T0."Account" = T0."ShortName" 
						AND T1."BtfStatus" <> 'C'
						AND T3."Finanse" = 'Y' 
			UNION ALL 	
			--- Check, ObjType='C'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-27' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0)  <> 0 THEN 'SF' ELSE 'EF' END) AS "Group"
				FROM "BTF1" T0 
					INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."Account" = T0."ShortName"
						AND T1."BtfStatus" <> 'C'
						AND T0."Account" IN (SELECT DISTINCT "CashCheck" FROM "OCHH") 
			UNION ALL 	
			--- Credit, ObjType='D'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-72' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0)  <> 0 THEN 'SF' ELSE 'EF' END) AS "Group"
				FROM "BTF1" T0
					INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T3 ON T0."Account" = T3."CreditAcct"
					WHERE T0."Account" = T0."ShortName"
						AND T1."BtfStatus" <> 'C' 
			UNION ALL 	
			--- BOE, ObjType='E'
			SELECT T4."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T2."CardType" = 'C' THEN 'SF' ELSE 'EF' END) AS "Group" 
			FROM "BTF1" T0 
				INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
				INNER JOIN "OCRD" T2 ON T0."ShortName" = T2."CardCode"
				INNER JOIN "CFF_TMP_BOEACCT" T3 ON T0."Account" = T3."AcctCode"
				INNER JOIN "CFF_TMP_DATE" T4 ON T0."DueDate" BETWEEN T4."StartDate" AND T4."EndDate"
				WHERE T0."Account" <> T0."ShortName"
					AND (T0."DueDate" BETWEEN :dateFrom AND :dateTo)
					AND T1."BtfStatus" <> 'C'
			UNION ALL			
			--- Customer Liabilities, ObjType='M'
			SELECT T3."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", 
				CASE WHEN T2."CardType" = 'C' THEN '17' ELSE '22' END AS "ObjType", 
				CASE WHEN T2."CardType" = 'C' THEN 'SF' ELSE 'EF' END AS "Group"
				FROM "BTF1" T0 
					INNER JOIN "OBTF" T1 ON T0."BatchNum" = T1."BatchNum" AND T0."TransId" = T1."TransId"
					INNER JOIN "OCRD" T2 ON T0."ShortName" = T2."CardCode"
					INNER JOIN "CFF_TMP_DATE" T3 ON T0."DueDate" BETWEEN T3."StartDate" AND T3."EndDate"
					WHERE T0."Account" <> T0."ShortName"
						AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."Account" ) 
						AND T1."BtfStatus" <> 'C'
						AND T2."CardType" IN ('C','S')
			) AS T5 GROUP BY T5."EndDate", T5."ObjType", T5."Group";						
	ELSE
		ResultNOBJV = SELECT :dateFrom AS "EndDate", 0.0 AS "Debit", 0.0 AS "Credit", 'X' AS "ObjType", 'XX' AS "Group", 0 AS "Number" FROM dummy;
	END IF;
	
	--- Recurring postings
	IF(:addRP = 'Y') THEN
		OPEN RecurTransQry(:dateTo);
		FETCH RecurTransQry INTO frequency, subFrequency, limitFlag, limitDate, currency, ctrlAcct, acctCode, mainInstance, subInstance, nextDue, debit, credit;
		WHILE NOT RecurTransQry::NOTFOUND DO
			-- This is a workaround for HANA. Otherwise nextDue will be null when insert into the table.
			newNextDue := :nextDue;
			WHILE :newNextDue <= :dateTo AND (:limitFlag <> 'Y' OR :newNextDue <= :limitDate) DO
				-- Not OPEN balance
				IF(:newNextDue >= :dateFrom AND :mainInstance = :subInstance AND (:frequency <> 'O' OR :mainInstance <> 0)) THEN
					INSERT INTO "CFF_TMP_RP" VALUES(:newNextDue, :debit, :credit, :acctCode, :ctrlAcct);					
				END IF;
				
				-- Open balance
				IF(:newNextDue < :dateFrom AND :subInstance = 0 AND :debit <> :Credit) THEN
					INSERT INTO "CFF_TMP_RP_OB" VALUES(:dateFrom, 0, (:debit - :credit), :acctCode, :ctrlAcct);
				END IF;
								
				IF (:frequency = 'D') THEN
					newNextDue := ADD_DAYS(:newNextDue, 1);
				ELSEIF (:frequency = 'W') THEN
					newNextDue := ADD_DAYS(:newNextDue, 7);
				ELSEIF (:frequency = 'A') THEN
					newNextDue := ADD_YEARS(:newNextDue, 1);
				ELSEIF (:frequency = 'M') THEN
					newNextDue := ADD_MONTHS(:newNextDue, 1);
				ELSEIF (:frequency = 'S') THEN
					newNextDue := ADD_MONTHS(:newNextDue, 6);
				ELSEIF (:frequency = 'Q') THEN
					newNextDue := ADD_MONTHS(:newNextDue, 3);
				ELSEIF (:frequency = 'O') THEN
					break;
				ELSE
				 	newNextDue := ADD_DAYS(:newNextDue, 7);
				END IF;

			END WHILE;
			FETCH RecurTransQry INTO frequency, subFrequency, limitFlag, limitDate, currency, ctrlAcct, acctCode, mainInstance, subInstance, nextDue, debit, credit;
		END WHILE;
		CLOSE RecurTransQry;
		
		--- No OPEN balance
		ResultNOBRP = SELECT T5."EndDate" AS "EndDate", SUM(T5."Debit") AS "Debit", SUM(T5."Credit") AS "Credit", T5."ObjType" AS "ObjType", T5."Group", COUNT(*) AS "Number" FROM (
			--- Cash, ObjType='A'
			SELECT T2."EndDate" AS "EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-50' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0)  <> 0 THEN 'SF' ELSE 'EF' END) AS "Group" 
				FROM "CFF_TMP_RP" T0 
					INNER JOIN "OACT" T1 ON T0."CtrlAcct" = T1."AcctCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."AcctCode" = T0."CtrlAcct" 
						AND T1."Finanse" = 'Y' 
			UNION ALL 
			--- Check, ObjType='C'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-27' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0)  <> 0 THEN 'SF' ELSE 'EF' END) AS "Group"
				FROM "CFF_TMP_RP" T0 
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."AcctCode" = T0."CtrlAcct"
					AND T0."CtrlAcct" IN (SELECT DISTINCT "CashCheck" FROM "OCHH") 
			UNION ALL 	
			--- Credit, ObjType='D'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-72' AS "ObjType", (CASE WHEN IFNULL(T0."Debit",0)  <> 0 THEN 'SF' ELSE 'EF' END) AS "Group"
				FROM "CFF_TMP_RP" T0 
					INNER JOIN (SELECT DISTINCT "CreditAcct" from "OCRH") T1 ON T0."CtrlAcct" = T1."CreditAcct"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."AcctCode" = T0."CtrlAcct" 
			UNION ALL 	
			--- BoE, ObjType='E'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", '-182' AS "ObjType", (CASE WHEN T3."CardType" = 'C' THEN 'SF' ELSE 'EF' END) AS "Group"
				FROM "CFF_TMP_RP" T0 
					INNER JOIN (SELECT DISTINCT "AcctCode", "CardCode" FROM "CRD3" WHERE "AcctType" IN ('R', 'P', 'C', 'S', 'Y', 'I', 'U')) T1 ON T0."CtrlAcct" = T1."AcctCode" AND T0."AcctCode" = T1."CardCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					INNER JOIN "OCRD" T3 ON T0."AcctCode" = T3."CardCode"
					WHERE T0."AcctCode" <> T0."CtrlAcct"
			UNION ALL 	
			--- Customer Liabilities, ObjType='M'
			SELECT T2."EndDate", IFNULL(T0."Debit",0) AS "Debit", IFNULL(T0."Credit",0) AS "Credit", 
				CASE WHEN T1."CardType" = 'C' THEN '17' ELSE '22' END AS "ObjType", 
				CASE WHEN T1."CardType" = 'C' THEN 'SF' ELSE 'EF' END AS "Group"
				FROM "CFF_TMP_RP" T0 
					INNER JOIN "OCRD" T1 ON T0."AcctCode" = T1."CardCode"
					INNER JOIN "CFF_TMP_DATE" T2 ON T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate"
					WHERE T0."AcctCode" <> T0."CtrlAcct"
						AND T1."CardType" IN ('C','S')
						AND NOT EXISTS ( SELECT 1 FROM "CFF_TMP_BOEACCT" WHERE "AcctCode" = T0."CtrlAcct" ) 
			) AS T5 GROUP BY T5."EndDate", T5."ObjType", T5."Group";
	ELSE
		ResultNOBRP = SELECT :dateFrom AS "EndDate", 0.0 AS "Debit", 0.0 AS "Credit", 'X' AS "ObjType", 'XX' AS "Group", 0 AS "Number" FROM dummy;
	END IF;	
	
	-- Blanket Agreement, the result IS IN CFF_TMP_OVERVIEW_BA table
	IF(:addBA = 'Y') THEN
		CALL CFF_BLANKETAGREEMENT_OVERVIEW(:dateFrom, :dateTo);
	END IF;
	
	INSERT INTO "CFF_TMP_OVERVIEW" 
		SELECT T6."Index", T5."EndDate", SUM(T5."Debit"), SUM(T5."Credit"), T5."ObjType", T5."Group", SUM("Number") FROM (
			SELECT * FROM :ResultNOB
			UNION ALL
			SELECT * FROM :ResultNOBDP 
			UNION ALL 
			SELECT * FROM :ResultNOBJV WHERE "ObjType" <> 'X'
			UNION ALL
			SELECT * FROM :ResultNOBRP WHERE "ObjType" <> 'X'
			UNION ALL
			SELECT * FROM "CFF_TMP_OVERVIEW_BA"
			) AS T5 
			INNER JOIN "CFF_TMP_DATE" T6 ON T5."EndDate" = T6."EndDate"
			INNER JOIN "CFF_TMP_OBJLIST" T7 ON T7."ObjType" = T5."ObjType" 
			GROUP BY T5."EndDate", T5."ObjType", T5."Group", T6."Index";
	
	IF :addBB > 0 THEN
		INSERT INTO "CFF_TMP_OVERVIEW" 
			SELECT -1, :dateFrom, T5."Debit", 0, T5."ObjType", T5."Group", T5."Number" 
			FROM :ResultOB T5
			INNER JOIN "CFF_TMP_OBJLIST" T6 ON T6."ObjType" = T5."ObjType";
	END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_GETLONGESTHOLIDAY 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	INSERT INTO CFF_TMP_HOLIDAY
	SELECT T1."HldCode", MAX(DAYS_BETWEEN(T1."StrDate", T1."EndDate") + 3) FROM HLD1 T1 GROUP BY T1."HldCode";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE CFF_GETNEXTPLANDATE (IN	startDate		DATE, 
									  IN 	fromDate		DATE,
									  IN	onDay			INT,
									  IN	frequncy		NVARCHAR(1),
									  OUT	nextPlanDate	DATE)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	VAL_DAILY			NVARCHAR(1) := 'D';
	VAL_WEEKLY			NVARCHAR(1) := 'W';
	VAL_MONTHLY			NVARCHAR(1) := 'M';	
	VAL_QUARTERLY		NVARCHAR(1) := 'Q';
	VAL_SEMIANNUALLY	NVARCHAR(1) := 'S';
	VAL_ANNUALLY		NVARCHAR(1) := 'A';
	VAL_ONCE			NVARCHAR(1) := 'O';
									  
	dayDiff		INT;

	weekOfDay	INT;
	offset		INT;

	yearOfDay	INT;
	monthOfDay	INT;
	maxMonthDay	INT;
	
	monthPeriod	INT;
	
	startYear	INT;
	startMonth	INT;
	startDay	INT;
	
	fromYear	INT;
	fromMonth	INT;
	fromDay		INT;
	
	realYear	INT;
	realMonth	INT;
	realDay		INT;
	
	monthOffset	INT;
BEGIN 
	IF :frequncy = :VAL_DAILY THEN
	
		IF :fromDate <= :startDate THEN
			nextPlanDate := :startDate;
			RETURN;
		END IF;
	
		dayDiff := DAYS_BETWEEN (:startDate, :fromDate);
		IF MOD(:dayDiff, :onDay) > 0 THEN
			nextPlanDate := ADD_DAYS(:fromDate, :onDay - MOD(:dayDiff, :onDay) );
		ELSE
			nextPlanDate := fromDate;
		END IF;
		
	ELSEIF :frequncy = :VAL_WEEKLY THEN
	
		IF :fromDate < :startDate THEN
			nextPlanDate := :startDate;
		ELSE
			nextPlanDate := :fromDate;
		END IF;
		
		weekOfDay := MOD( WEEKDAY(:nextPlanDate) + 2, 7 );
		IF :onDay - :weekOfDay >= 0 THEN
			offset := :onDay - :weekOfDay; 
		ELSE
			offset := 7 + :onDay - :weekOfDay;
		END IF;
		
		nextPlanDate := ADD_DAYS(:nextPlanDate, :offset);
		
	ELSEIF :frequncy = :VAL_MONTHLY THEN
		
		IF :fromDate <= :startDate THEN
			nextPlanDate := :startDate;
		ELSE
			nextPlanDate := :fromDate;
		END IF;
		
		yearOfDay := YEAR(:nextPlanDate);
		monthOfDay := MONTH(:nextPlanDate);
		maxMonthDay := DAYOFMONTH( LAST_DAY(:nextPlanDate) );
		
		IF :onDay > :maxMonthDay THEN
			nextPlanDate := TO_DATE(:yearOfDay || '-' || :monthOfDay || '-' || :maxMonthDay, 'YYYY-MM-DD');
		ELSE
			nextPlanDate := TO_DATE(:yearOfDay || '-' || :monthOfDay || '-' || :onDay, 'YYYY-MM-DD');
		END IF;
		
		IF :nextPlanDate < fromDate THEN
			nextPlanDate := ADD_MONTHS(:nextPlanDate, 1);
		END IF;
	
	ELSEIF :frequncy = :VAL_ONCE THEN
	
		IF :fromDate > :startDate THEN
			nextPlanDate := CURRENT_DATE; 
		END IF;
		
		nextPlanDate := :startDate;
	
	ELSE
		
		IF :fromDate <= :startDate THEN
			nextPlanDate := :startDate;
			RETURN;
		END IF;
	
		IF :frequncy = :VAL_QUARTERLY THEN
			monthPeriod := 3;
		ELSEIF :frequncy = :VAL_SEMIANNUALLY THEN
			monthPeriod := 6;
		ELSEIF :frequncy = :VAL_ANNUALLY THEN
			monthPeriod := 12;
		END IF;
		
		startYear := YEAR(:startDate);
		startMonth := MONTH(:startDate);
		startDay := DAYOFMONTH(:startDate);
		
		fromYear := YEAR(:fromDate);
		fromMonth := MONTH(:fromDate);
		fromDay := DAYOFMONTH(:fromDate);
		
		IF :fromDay > :startDay THEN
			fromMonth := :fromMonth + 1;
		END IF;
		
		monthOffset := MOD(:startMonth, :monthPeriod) - MOD(:fromMonth, :monthPeriod);
		
		-- can't go back in time
		IF :monthOffset < 0 THEN
			monthOffset := :monthOffset + :monthPeriod;
		END IF;
		
		realMonth := :fromMonth + :monthOffset;
		realYear := :fromYear;
		IF :realMonth > 12 THEN 
			realMonth := :realMonth - 12;
			realYear := :realYear + 1;
		END IF;
		
		maxMonthDay := DAYOFMONTH( LAST_DAY( TO_DATE(:realYear || '-' || :realMonth || '-' || '01', 'YYYY-MM-DD') ) );
		
		IF :startDay > :maxMonthDay THEN
			realDay := :maxMonthDay;
		ELSE
			realDay := :startDay;
		END IF;
		
		nextPlanDate := TO_DATE(:realYear || '-' || :realMonth || '-' || :realDay, 'YYYY-MM-DD');
		
	END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_GETPREDICTDUEDATE( IN dueDates			CFF_DATE_T, 
										IN holidays			CFF_HOLIDAY_T,
										OUT predictDueDates	CFF_PREDICT_DUEDATE_T)
LANGUAGE LLANG 
SQL SECURITY INVOKER
AS
BEGIN
	typedef Table<Int32 "AbsEntry", Date "DocDueDate", Int32 "AdjustDocDueDate", 
				  Int32 "DeltaMonths", Int32 "AdjustDay", String "HldCode",
				  String "DocType", Int32 "DocEntry", String "CardCode", 
				  String "CtlAccount", Fixed12<6> "Debit", Fixed12<6> "Credit", 
				  String "OriginalType", String "Group", Int32 "InstID", 
				  Int32 "DocNum", Int32 "AvrageLate"> T_DUEDATES;

	typedef Table<String "HldCode", Int32 "WndFrm", Int32 "WndTo",
				  Int32 "IsCurYear", Int32 "IgnrWnd",
				  Date "StrDate", Date "EndDate">  T_HOLIDAYS;
	typedef Table<Int32 "AbsEntry", Date "PredictDueDate"> T_PREDICT_DUEDATE;
	
	
	typedef Column<Int32> COL_INT;
	typedef Column<Date> COL_DATE;
	typedef Column<String> COL_STR;
	
	Date predictDueDate(Date dueDate, String hldCode, T_HOLIDAYS holidays)
	{
		COL_STR colHldCode = holidays."HldCode";
		COL_DATE colStrDate = holidays."StrDate";
		COL_DATE colEndDate = holidays."EndDate";
		
		COL_INT colWndFrom = holidays."WndFrm";
		COL_INT colWndTo = holidays."WndTo";
		
		Date predictedDate = dueDate;
		Date strDate;
		Date endDate;
		
		Int32 weekday;
		Int32 wndFrom;
		Int32 wndTo;
		
		Size row = 0z;
		while(row < holidays.getSize() )
		{
			if (hldCode != colHldCode[row])
			{
				row = row + 1z;
				continue;
			}
			strDate = colStrDate[row];
			endDate = colEndDate[row];
			wndFrom = colWndFrom[row];
			wndTo = colWndTo[row];
			
			if(0 == holidays."IsCurYear"[row])
			{
				strDate = Date(dueDate.getYear(), strDate.getMonth(), strDate.getDay());
				endDate = Date(dueDate.getYear(), endDate.getMonth(), endDate.getDay());
			}
			if(strDate <= predictedDate && predictedDate <= endDate )
			{
				predictedDate = endDate.addDays(1);
			}
			
			if(0 == holidays."IgnrWnd"[row])
			{
				// Monday, Tuesday, ..., Saturday, Sunday
				// B1: 	2, 3, ..., 7, 1
				// HANA:0, 1, ..., 5, 6
				weekday = (predictedDate.getWeekDay() + 2) % 7;
				
				if (wndFrom <= wndTo)
				{
					if (wndFrom <= weekday && weekday <= wndTo)
					{
						predictedDate = predictedDate.addDays(wndTo - weekday + 1);
					}
				}
				else 
				{
					if (weekday >= wndFrom )
					{
						predictedDate = predictedDate.addDays(8 + wndTo - weekday);
					}
					else if (weekday <= wndTo)
					{
						predictedDate = predictedDate.addDays(wndTo - weekday + 1);
					}
				}
			}

			row = row + 1z;
		} 
		
		return predictedDate;
	}
	
	export Void main(T_DUEDATES dueDates, T_HOLIDAYS holidays,T_PREDICT_DUEDATE &predictDueDates)
	{
		COL_INT colAdjust = dueDates."AdjustDocDueDate";
		COL_DATE colDueDate = dueDates."DocDueDate";
		
		COL_INT colPredictEntry = predictDueDates."AbsEntry";
		COL_DATE colPredictDate = predictDueDates."PredictDueDate";
		colPredictEntry.setSize(dueDates.getSize());
		colPredictDate.setSize(dueDates.getSize());

		Int32 curYear;
		Int32 curMonth;
		Int32 deltaMonths;
		Int32 adjustDay;
		String hldCode;
		
		Size row = 0z;
		while (row < dueDates.getSize())
		{
			colPredictDate[row] = colDueDate[row];

			hldCode = dueDates."HldCode"[row];
			colPredictDate[row] = predictDueDate(colPredictDate[row], hldCode, holidays);
			colPredictEntry[row] = dueDates."AbsEntry"[row];

			row = row + 1z;
			
		}
		
	}
END;

