CREATE PROCEDURE CFF_GETTOTALINSTANCES(IN		startDate		DATE, 
									   IN		endDate			DATE,
									   IN		onDay			INT,
									   IN		frequncy		NVARCHAR(1),
									   OUT		nextInstance	INT) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	VAL_DAILY			NVARCHAR(1) := 'D';
	VAL_WEEKLY			NVARCHAR(1) := 'W';
	VAL_MONTHLY			NVARCHAR(1) := 'M';
	VAL_QUARTERLY		NVARCHAR(1) := 'Q';
	VAL_SEMIANNUALLY	NVARCHAR(1) := 'S';
	VAL_ANNUALLY		NVARCHAR(1) := 'A';
	VAL_ONCE			NVARCHAR(1) := 'O';
 
	offset			INT;
	
	realStartDate	DATE;
	circleCount		INT;
	
	startYear		INT;
	startMonth		INT;
	startDay		INT;
	
	endYear			INT;
	endMonth		INT;
	endDay			INT;
	fullMonth		INT;
	
	maxMonthDay		INT;
	
	monthOffset		INT;
	period			INT;
	tempDate		DATE;
	
	yearOffset		INT;
BEGIN 
	IF :frequncy = :VAL_DAILY THEN
		offset := DAYS_BETWEEN (:startDate, :endDate);
		nextInstance := :offset / :onDay + 1;
	ELSEIF :frequncy = :VAL_WEEKLY THEN
		CALL CFF_GETNEXTPLANDATE(:startDate, :startDate, :onDay, :frequncy, :realStartDate);
		IF :realStartDate > :endDate THEN
			nextInstance := 0;
			RETURN;
		END IF;
		
		circleCount := DAYS_BETWEEN (:realStartDate, :endDate) / 7;
		nextInstance := :circleCount + 1;
	ELSEIF :frequncy = :VAL_MONTHLY THEN
		CALL CFF_GETNEXTPLANDATE(:startDate, :startDate, :onDay, :frequncy, :realStartDate);
		IF :realStartDate > :endDate THEN
			nextInstance := 0;
			RETURN;		
		END IF;
		startYear := YEAR(:realStartDate);
		startMonth := MONTH(:realStartDate);
		startDay := DAYOFMONTH(:realStartDate);
		endYear := YEAR(:endDate);
		endMonth := MONTH(:endDate);
		endDay := DAYOFMONTH(:endDate);
		
		fullMonth := 12 * (:endYear - :startYear) + :endMonth - :startMonth;
		maxMonthDay := DAYOFMONTH( LAST_DAY(:endDate) );
		
		IF :onDay > :maxMonthDay THEN
			IF :maxMonthDay <= :endDay THEN
				nextInstance := :fullMonth + 1;
			ELSE
				nextInstance := :fullMonth;
			END IF;
		ELSE
			IF :onDay <= :endDay THEN
				nextInstance := :fullMonth + 1;
			ELSE
				nextInstance := :fullMonth;
			END IF;		
		END IF;
	ELSEIF :frequncy = :VAL_QUARTERLY THEN
		startYear := YEAR(:startDate);
		startMonth := MONTH(:startDate);
		startDay := DAYOFMONTH(:startDate);
		
		endYear := YEAR(:endDate);
		endMonth := MONTH(:endDate);
		endDay := DAYOFMONTH(:endDate);
		
		monthOffset := 12 * (:endYear - :startYear) + :endMonth - :startMonth;
		period := :monthOffset / 3;
		
		tempDate := ADD_MONTHS(:startDate, 3 * period);
		IF :tempDate <= :endDate THEN
			period := :period + 1;
		END IF;
		
		nextInstance := :period;
	ELSEIF :frequncy = :VAL_SEMIANNUALLY THEN
		startYear := YEAR(:startDate);
		startMonth := MONTH(:startDate);
		startDay := DAYOFMONTH(:startDate);
		
		endYear := YEAR(:endDate);
		endMonth := MONTH(:endDate);
		endDay := DAYOFMONTH(:endDate);
		
		monthOffset := 12 * (:endYear - :startYear) + :endMonth - :startMonth;
		period := :monthOffset / 6;
		
		tempDate := ADD_MONTHS(:startDate, 6 * period);
		IF :tempDate <= :endDate THEN
			period := :period + 1;
		END IF;
		
		nextInstance := :period;
	ELSEIF :frequncy = :VAL_ANNUALLY THEN
		startYear := YEAR(:startDate);
		endYear := YEAR(:endDate);
		
		yearOffset := :endYear - :startYear;
		
		tempDate := ADD_YEARS(:startDate, :yearOffset);
		IF :tempDate <= :endDate THEN
			yearOffset := :yearOffset + 1;
		END IF;
		
		nextInstance := :yearOffset;
	ELSEIF :frequncy = :VAL_ONCE THEN
		nextInstance := 1;
	END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS

CREATE PROCEDURE CFF_PARSEOBJLIST (IN	objList		NVARCHAR(200), 
								   IN	groups		NVARCHAR(50))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	objListStr 		NVARCHAR(200);
	tempStr			NVARCHAR(200);
	pos				INTEGER; 
BEGIN
	objListStr := :objList || ',';
	pos := LOCATE(:objListStr, ',');
	WHILE :pos > 0 DO
		tempStr := TRIM( SUBSTRING(:objListStr, 1, :pos-1) );
		objListStr := SUBSTRING(:objListStr, :pos+1);
		INSERT INTO "CFF_TMP_OBJLIST" VALUES(:tempStr);
		pos := LOCATE(:objListStr, ',');
	END WHILE;
	
	objListStr := :groups || ',';
	pos := LOCATE(:objListStr, ',');
	WHILE :pos > 0 DO
		tempStr := TRIM(SUBSTRING(:objListStr, 1, :pos-1));
		objListStr := SUBSTRING(:objListStr, :pos+1);
		INSERT INTO "CFF_TMP_GROUP" VALUES(:tempStr);
		pos := LOCATE(:objListStr, ',');
	END WHILE;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS
CREATE PROCEDURE CFF_PARSEOPTIONS(IN	options		NVARCHAR(50), 
								  OUT	addRP		NVARCHAR(1), 
								  OUT	addRT		NVARCHAR(1), 
								  OUT	addBA		NVARCHAR(1),
								  OUT	addJV		NVARCHAR(1),
								  OUT	addDD		NVARCHAR(1),
								  OUT	addDP		NVARCHAR(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	optionStr	NVARCHAR(50);
	tempStr		NVARCHAR(50);
	pos			INTEGER;
BEGIN
	addRP := 'N';
	addRT := 'N';
	addBA := 'N';
	addJV := 'N';
	addDD := 'N';
	addDP := 'N';
	
	optionStr := :options || ',';
	pos := LOCATE(:optionStr, ',');	
	WHILE :pos > 0 DO
		tempStr := TRIM( SUBSTRING(:optionStr, 1, :pos-1) );
		optionStr := TRIM( SUBSTRING(:optionStr, :pos+1) );
				
		IF(LOCATE(:tempStr, 'RP') > 0) THEN
			addRP := 'Y';
			--INSERT INTO CFF_TEMP VALUES('RP', :addRP);
		ELSEIF (LOCATE(:tempStr, 'RT') > 0) THEN
			addRT := 'Y';
			INSERT INTO "CFF_TMP_OBJLIST"
			SELECT "ObjType" || 'r' FROM "CFF_TMP_OBJLIST" WHERE "ObjType" NOT LIKE '%d' AND "ObjType" NOT LIKE '%r' AND "ObjType" NOT LIKE '-%';
			--INSERT INTO CFF_TEMP VALUES('RT', :addRT);
		ELSEIF (LOCATE(:tempStr, 'BA') > 0) THEN
			addBA := 'Y';
			--INSERT INTO CFF_TEMP VALUES('BA', :addBA);
		ELSEIF (LOCATE(:tempStr, 'JV') > 0) THEN
			addJV := 'Y';
			--INSERT INTO CFF_TEMP VALUES('JV', :addJV);
		ELSEIF (LOCATE(:tempStr, 'DD') > 0) THEN
			addDD := 'Y';
			INSERT INTO "CFF_TMP_OBJLIST"
			SELECT "ObjType" || 'd' FROM "CFF_TMP_OBJLIST" WHERE "ObjType" NOT LIKE '%d' AND "ObjType" NOT LIKE '%r' AND "ObjType" NOT LIKE '-%';
			--INSERT INTO CFF_TEMP VALUES('DD', :addDD);
		ELSEIF (LOCATE(:tempStr, 'DP') > 0) THEN
			addDP := 'Y';
			--INSERT INTO CFF_TEMP VALUES('DP', :addDP);
		END IF;
		
		pos := LOCATE(:optionStr, ',');
		
	END WHILE;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CFF_CREATEDBOBJECTS AFTER:SP:CFF_GETNEXTPLANDATE AFTER:SP:CFF_GETTOTALINSTANCES

CREATE PROCEDURE CFF_RECURRINGTRASACTIONDATES(IN	fromDate	DATE, 
											  IN	toDate		DATE
											 )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	rcpSize			INT;
	onDay			INT;
	nextInstance	INT;
	startDate		DATE;
	endDate			DATE;
	nextDAte		DATE;
	planSinceDate	DATE;
	tillDay			DATE;
	DAILY_BASE		INT := 100;
	WEEKLY_BASE		INT := 0;
	MONTHLY_BASE	INT := 1000;
	CURSOR c_cursor FOR
		SELECT * FROM ORCP WHERE "IsRemoved" <> 'Y';
BEGIN
	-- get recurring trasaction template
	FOR cur_row as c_cursor DO
	
		onDay := cur_row."Remind";
		--get orcp_abs_entry, orcp_doc_object_type, orcp_draft_entry
		IF cur_row."Frequency" = 'D' THEN
			-- For daily, onDay should be 1, 2, 3, ..., 10, 15, 30, 45, 60
			onDay := :onDay - :DAILY_BASE;
		ELSEIF cur_row."Frequency" = 'W' THEN
			-- For weekly, onDay should be SUN, MON, ..., SAT
			onDay := :onDay - :WEEKLY_BASE;
		ELSEIF cur_row."Frequency" = 'M' THEN
			-- For monthly, onDay should be 1, 2, 3, ..., 31
			onDay := :onDay - :MONTHLY_BASE;
		ELSE
			onDay := 0;
		END IF;
		
		startDate := cur_row."StartDate";
		IF cur_row."EndDate" IS NULL THEN 
			endDate   := :toDate;
		ELSE
			endDate   := cur_row."EndDate";
		END IF;

		SELECT ADD_DAYS(CURRENT_DATE, 1) INTO planSinceDate FROM DUMMY; -- tomorrow
		CALL CFF_GETNEXTPLANDATE(:startDate, :planSinceDate, :onDay, cur_row."Frequency", :nextDate);
		CALL CFF_GETTOTALINSTANCES(:startDate, :nextDate, :onDay, cur_row."Frequency", :nextInstance);
		
		IF :toDate IS NULL THEN
			tillDay := CURRENT_DATE;
		ELSE
			tillDay := :toDate;
		END IF;
		
		IF cur_row."Frequency" = 'O' THEN
			IF :nextDate <= CURRENT_DATE THEN
				INSERT INTO CFF_TMP_ORCL VALUES('1', cur_row."AbsEntry", :nextInstance, :nextDate, 'N', cur_row."DocObjType", cur_row."DraftEntry");
			END IF;
		ELSE
			WHILE :nextDate <= :tillDay AND :nextDate <= :endDate DO

				INSERT INTO CFF_TMP_ORCL VALUES('1', cur_row."AbsEntry", :nextInstance, :nextDate, 'N', cur_row."DocObjType", cur_row."DraftEntry");
				nextDate := ADD_DAYS(:nextDate, 1);
				nextInstance := :nextInstance + 1;
				CFF_GETNEXTPLANDATE(:startDate, :nextDate, :onDay, cur_row."Frequency", :nextDate);
				
			END WHILE;
		END IF;
		
	END FOR;

	SELECT * FROM CFF_TMP_ORCL;
END;

