create procedure CRSP_Annual_Sales_Analysis_Quarter (
	in DocDateFrom_in nvarchar(4),
	in DocumentType_in nvarchar(3)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
	ObjectType 		nvarchar(3);
	ShowType 		nvarchar(3);
	DocDateFrom 		datetime;
	DocDateTo		datetime;
	DocDueDateFrom 	datetime;
	DocDueDateTo		datetime;
	CardCodeFrom		nvarchar(30);
	CardCodeTo		nvarchar(30);
	CrdGroupCode  		nvarchar(11);
	ItemCodeFrom		nvarchar(50);
	ItemCodeTo		nvarchar(50);
	ItmGroupCode  		nvarchar(11);
	ItmProps	   	nvarchar(70);
	CrdProps   		nvarchar(70);
	SlpCodeFrom		nvarchar(32);
	SlpCodeTo		nvarchar(32);
	TaxDateFrom 		datetime;
	TaxDateTo		datetime;
	Brand			nvarchar(11);
	PrjCode		nvarchar(8);
	RptType		int; 	    
	cutbyObject		nchar(3);
	DspFrznBP		nvarchar(1);
	DspFrznITM		nvarchar(1);
	Header 	nvarchar(4);
	Lines  	nvarchar(4);
	InstLines  	nvarchar(4);
	opObject 	nvarchar(4);
	tmpStr 	nvarchar(4000);
	PropsRel 	nvarchar(10);
	ii 		int;
	jj 		int;
	GrossBySal 	nChar(1);
	WhereStr 	nvarchar(4000);
	VatSysColName 	nvarchar(20);
	Mult 		nvarchar(5);
	WTLines	nvarchar(4);
	prevDocDateFrom datetime;
	prevDocDateTo datetime;
	prevDueDateFrom datetime;
	prevDueDateTo datetime;
	prevTaxDateFrom datetime;
	prevTaxDateTo datetime;
	FormatStr nvarchar(200);
	specialIndicator int;
begin
	delete from "CRSPAnnualSalesAnalysisQuarter_TmpPsar";

	ObjectType := :DocumentType_in;
	ShowType := 'SNG';
	RptType := 0;
	
	if (:ObjectType = 'INV')then
		opObject := 'RIN';
	end if;

	if (:ObjectType = 'RDR')then
		opObject := 'NON';
	end if;
	
	if (:ObjectType = 'DLN')then
		opObject := 'RDN';
	end if;

	cutbyObject := 'NON';
	DspFrznBP := 'Y';
	DspFrznITM := 'Y';

	DocDueDateFrom := '19700101';
	DocDueDateTo := '21000101';
	TaxDateFrom := '19700101';
	TaxDateTo := '21000101';
	prevDueDateFrom := '19700101';
	prevDueDateTo := '21000101';
	prevTaxDateFrom := '19700101';
	prevTaxDateTo := '21000101';
	
	if LENGTH(:DocDateFrom_in) <> 4 then
		DocDateFrom := '19700101';
	else
		DocDateFrom := :DocDateFrom_in || '0101';
	end if;
		
	DocDateTo := ADD_DAYS(ADD_YEARS(:DocDateFrom, 1), -1);-- ADD_DAYS(dd, -1, ADD_YEARS(year,1,:DocDateFrom));
	prevDocDateFrom := ADD_YEARS(:DocDateFrom,-1);--ADD_YEARS(year,-1,:DocDateFrom);
	prevDocDateTo := ADD_YEARS(:DocDateTo,-1);--ADD_YEARS(year,-1,:DocDateTo);

	VatSysColName :='tmp';

	if(:ObjectType <> 'NON') then
		call CRSP_Annual_Sales_Analysis_Quarter_Insert(:ObjectType, :ShowType, :VatSysColName, :DspFrznBP, :DocDateFrom, :DocDateTo,
		 					 :DocDueDateFrom, :DocDueDateTo, :TaxDateFrom, :TaxDateTo, 1); 	  													
 	  	call CRSP_Annual_Sales_Analysis_Quarter_Insert(:ObjectType, :ShowType, :VatSysColName, :DspFrznBP, :prevDocDateFrom, 
 	  				:prevDocDateTo, :prevDueDateFrom, :prevDueDateTo, :prevTaxDateFrom, :prevTaxDateTo, 0);
 	  				
		if (:ShowType = 'SNG') then
  			ObjectType := :opObject;
  			ShowType := 'NST';
  			
  			if (:ObjectType <> 'NON') then
  				call CRSP_Annual_Sales_Analysis_Quarter_Insert(:ObjectType, :ShowType, :VatSysColName, :DspFrznBP, :DocDateFrom, :DocDateTo,
		 					 :DocDueDateFrom, :DocDueDateTo, :TaxDateFrom, :TaxDateTo, 1); 	  													
 	  			call CRSP_Annual_Sales_Analysis_Quarter_Insert(:ObjectType, :ShowType, :VatSysColName, :DspFrznBP, :prevDocDateFrom, 
 	  				:prevDocDateTo, :prevDueDateFrom, :prevDueDateTo, :prevTaxDateFrom, :prevTaxDateTo, 0);
  			end if;
 		end if;
	end if;
	
	--Card Code range

	/*Loop_End:*/
	tmpStr := ' Insert Into "CRSPAnnualSalesAnalysisQuarter_TmpPsar" Select "CardCode", "CardName" , "Quarter", "Year", Sum("Sales"), Sum("GrossPrft") , 0 , 0 , Sum("SalesForPrcnt") , -1 From "CRSPAnnualSalesAnalysisQuarter_TmpPsar" ' || 
				' Group By "CardCode", "CardName", "Quarter", "Year" ';
	exec (:tmpStr);
	
	Select "T0"."CardCode", "T0"."CardName", "T0"."Quarter", "T0"."Year", "T0"."Sales", "T0"."GrossPrft", "T0"."SalesForPrcnt",
		Sum(Case "T1"."Quarter" When 1 Then "T1"."Sales" ELse 0 End), Sum(Case "T1"."Quarter" When 1 Then "T1"."GrossPrft" ELse 0 End), Sum(Case "T1"."Quarter" When 1 Then "T1"."SalesForPrcnt" ELse 0 End),
		Sum(Case "T1"."Quarter" When 2 Then "T1"."Sales" ELse 0 End), Sum(Case "T1"."Quarter" When 2 Then "T1"."GrossPrft" ELse 0 End), Sum(Case "T1"."Quarter" When 2 Then "T1"."SalesForPrcnt" ELse 0 End),
		Sum(Case "T1"."Quarter" When 3 Then "T1"."Sales" ELse 0 End), Sum(Case "T1"."Quarter" When 3 Then "T1"."GrossPrft" ELse 0 End), Sum(Case "T1"."Quarter" When 3 Then "T1"."SalesForPrcnt" ELse 0 End),
		Sum(Case "T1"."Quarter" When 4 Then "T1"."Sales" ELse 0 End), Sum(Case "T1"."Quarter" When 4 Then "T1"."GrossPrft" ELse 0 End), Sum(Case "T1"."Quarter" When 4 Then "T1"."SalesForPrcnt" ELse 0 End)
		From "CRSPAnnualSalesAnalysisQuarter_TmpPsar" T0 Inner Join "CRSPAnnualSalesAnalysisQuarter_TmpPsar" T1 On "T0"."CardCode" = "T1"."CardCode" and "T0"."Year" = "T1"."Year" and "T1"."SalesForPrcntSys" = "T0"."SalesForPrcntSys"
		Where "T0"."SalesForPrcntSys" = -1
		Group By "T0"."CardCode", "T0"."CardName", "T0"."Quarter", "T0"."Year", "T0"."Sales", "T0"."GrossPrft", "T0"."SalesForPrcnt"
		Order By "T0"."CardCode", "T0"."Year", "T0"."Quarter";
	
	delete from "CRSPAnnualSalesAnalysisQuarter_TmpPsar";		
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

create procedure CRSP_Annual_Sales_Analysis_Quarter_Insert
(
	in ObjectType 		nChar(3),
	in ShowType 		nChar(3),
	in VatSysColName 	nvarchar(20),
	in DspFrznBP		nvarchar(1),
	in DocDateFrom 		datetime,
	in DocDateTo 		datetime,
	in DocDueDateFrom 	datetime,
	in DocDueDateTo 	datetime,
	in TaxDateFrom 		datetime,
	in TaxDateTo 		datetime,
	in yearv 			int	
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
	tmpStr0 	nvarchar(4000);
	tmpStr 		nvarchar(4000);
	WhereStr 	nvarchar(4000);
	Mult 		nvarchar(5);
	Header 		nvarchar(4);
	Lines  		nvarchar(4);
	InstLines  	nvarchar(4);
	opObject 	nvarchar(4);
	WTLines		nvarchar(4);
	FormatStr 	nvarchar(200);
begin

delete from "CRSPAnnualSalesAnalysisQuarterInsert_TMPMonth";

if(:ObjectType <> 'NON') then
	if (:ShowType = 'SNG' or :ShowType = 'SN1') then
		Mult := ' 1 ';
	else
		Mult :=  ' -1 ';
	end if;
	if (:ObjectType = 'INV')then
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		opObject := 'RIN';
		WTLines := 'INV5';
	end if;
	if (:ObjectType = 'CSI')then
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
  		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV')then
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
  		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR')then
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN')then
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN')then
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN')then
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;
	
	SELECT TOP 1 COLUMN_NAME into VatSysColName FROM "PUBLIC"."TABLE_COLUMNS" as A WHERE TABLE_NAME = :Header and POSITION = 57;
	
		
	WhereStr := 'Main."DocDate" >= '''|| :DocDateFrom || '''  And  Main."DocDate" <='''|| :DocDateTo || 
		''' And Inst."DueDate" >= '''|| :DocDueDateFrom ||
		''' And Inst."DueDate" <= ''' || :DocDueDateTo || ''' And Main."TaxDate" >= '''|| :TaxDateFrom ||
		''' And Main."TaxDate" <= '''|| :TaxDateTo || ''' And Main."Instance" = 0 ';
		
	if (:ObjectType <> 'CSI') then
		WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''N'' ';
	end if;
	if (:ObjectType = 'RIN') then
		WhereStr := :WhereStr || '  AND NOT  EXISTS (SELECT 1 FROM '|| :ObjectType || '1 T1 WHERE T1."DocEntry" = Main."DocEntry"  AND T1."BaseType" = 203) '; 
	end if;
	
	tmpStr0 := 'insert into "CRSPAnnualSalesAnalysisQuarterInsert_TMPMonth" select Main."DocEntry", floor((MONTH(Main."DocDate")+2)/3) from ' || :Header ||
			' Main ';--inner join '|| :InstLines ||' Inst On inst."DocEntry" = Main."DocEntry"  where ' || :WhereStr;
			
	exec(:tmpStr0);
		
	tmpStr0 := 'insert into  "CRSPAnnualSalesAnalysisQuarter_TmpPsar" Select Crdg."GroupCode", Crdg."GroupName", TX."Quarter" As Quarter, ';
	tmpStr := ' As Year, (Sum(Inst."InsTotal") - Sum(Inst."VatSum") - Sum(Inst."TotalExpns") 
				+ (CASE   (SELECT MIN(Wt."Category")   FROM ' || :WTLines || ' Wt where Wt."AbsEntry" = Main."DocEntry")
	         	WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)
				 + Sum(Main."DpmAmnt" * floor(Inst."InstPrcnt" / 100)) - Sum(Main."RoundDif" * floor(Inst."InstPrcnt" / 100)) )  * ' || :Mult || ' As Sales, Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100)  * ' 
				|| :Mult || ' As GrossProfit, (Sum(Inst."InsTotalSy") - Sum(Inst."' || :VatSysColName || '") - Sum(Inst."TotalExpSC") +
				(CASE (SELECT MIN(Wt."Category")   FROM ' || :WTLines || ' Wt where Wt."AbsEntry" = Main."DocEntry")
	         	WHEN ''I''  THEN Sum(Inst."WTSumSC") ELSE 0 END)
	         	   + Sum(Main."DpmAmntSC" * Inst."InstPrcnt" / 100) -  Sum(Main."RoundDifSy" * Inst."InstPrcnt" / 100) )  * ' || :Mult || '  As SalesSys, (Sum(Main."GrosProfSy" * Inst."InstPrcnt" / 100))  * ' 
	  			|| :Mult || '  As GrossProfitSys,';
	
	tmpStr := :tmpStr || ' (Select  (Sum(aa."DocTotal") - Sum(aa."VatSum") - Sum(aa."TotalExpns") + 
			(CASE 
				(SELECT MIN(Wt."Category") FROM ' || :WTLines || ' Wt where Wt."AbsEntry" = Main."DocEntry")
			         	WHEN ''I'' THEN 
			         		Sum(Inst."WTSum") 
			         	ELSE 
							0
	  		END) + Sum(aa."DpmAmnt") - Sum(aa."RoundDif")
			) From ' || :Header || ' aa   Where  aa."DocEntry" = Main."DocEntry" )  * ' || :Mult || '  As  SalesForPrcnt  , 0 As  SalesForPrcntSys ';

	tmpStr := :tmpStr || ' From  ' || :Header || ' Main 
	Inner  Join OCRD Cards On Cards."CardCode" = Main."CardCode"
	Inner  Join OCRG Crdg On Crdg."GroupCode" = Cards."GroupCode"
	Inner join "CRSPAnnualSalesAnalysisQuarterInsert_TMPMonth" TX on TX."DocEntry" = Main."DocEntry"
	Inner  Join ' || :InstLines || ' Inst On inst."DocEntry" = Main."DocEntry" ';
	
	if (:DspFrznBP = 'N') then
		WhereStr := '(' || :WhereStr || ') And ' || 
					'(Cards."validFor" = ''Y'' or (Cards."frozenFor" = ''Y'' and (Cards."frozenFrom" is not null or Cards."frozenTo" is not null)) or (Cards."validFor" = ''N'' and Cards."frozenFor" = ''N''))';
	end if;
	
	WhereStr := ' Where ' || :WhereStr || '  Group By  Crdg."GroupCode", Crdg."GroupName",  TX."Quarter",   Year(Main."DocDate"), Main."DocEntry"
  				Order By Crdg."GroupCode" , Year(Main."DocDate")';
  				
  	tmpStr := :tmpStr || :WhereStr;
  	
	exec(:tmpStr0 || :yearv || :tmpStr);
  	delete from "CRSPAnnualSalesAnalysisQuarterInsert_TMPMonth";
  	
	/* End Here */
end if;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_BABS_Layout_TR (in DateTypeIn varchar(256), in FromDateIn timestamp, in ToDateIn timestamp, in MinAmountIn integer) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
DateType varchar(256);
DateFrom timestamp;
DateTo timestamp;
MinAmount integer;
Category nchar(4);
BEGIN 
    /* Default values in case parameters are not provided */
    DateType := 'TaxDate';
    SELECT 
    (SELECT MIN(T0."TaxDate") 
    FROM "OJDT" T0) INTO DateFrom FROM DUMMY;
    SELECT 
    (SELECT MAX(T0."TaxDate") 
    FROM "OJDT" T0) INTO DateTo FROM DUMMY;
    MinAmount := 5000;
    Category := 'BABS';/* Possible values are: BA, BS, BABS (both)*/
    /* Parameters (Comment this to test query) */
    DateType := DateTypeIn;
    DateFrom := FromDateIn;
    --DateFrom := '2016-01-01 00:00:00.000';
    DateTo := ToDateIn;
    --DateTo := '2016-01-12 00:00:00.000';
    MinAmount := MinAmountIn;
    --Category := CategoryIn;

SELECT T10."Category", ROW_NUMBER() OVER ( ORDER BY T10."CardName") AS "Row", T10."CardCode", T10."CardName", 
        T10."Country", IFNULL(T10."TaxOffice", '') AS "TaxOffice", T10."LicTradNum" AS "TaxCode", (
        CASE 
            WHEN T10."CmpPrivate" = 'C' THEN T10."LicTradNum" 
            ELSE '' 
        END) AS "LicTradNum", (
        CASE 
            WHEN T10."CmpPrivate" = 'I' THEN T10."LicTradNum" 
            ELSE '' 
        END) AS "IDNumber", SUM(T10."Transactions") AS "SumTransactions", 
    ROUND(SUM(T10."BaseSum"), 0) AS "SumBaseSum" 
    FROM 
    (
        SELECT 'BA' AS "Category", T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", 
        IFNULL(T3."LicTradNum", '') AS "LicTradNum", COUNT(DISTINCT (T0."TransId")) AS "Transactions", 
        SUM(T1."BaseSum") AS "BaseSum" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN OPCH T2 ON T0."TransId" = T2."TransId" 
        INNER JOIN OCRD T3 ON T2."CardCode" = T3."CardCode" 
        INNER JOIN OVTG T4 ON T1."VatGroup" = T4."Code" 
        LEFT OUTER JOIN CRD1 T5 ON T3."CardCode" = T5."CardCode" AND T3."ShipToDef" = T5."Address" AND
             T5."AdresType" = 'S' 
    WHERE (:Category = 'BA' OR :Category = 'BABS') AND 1 = 1 AND T4."Category" = 'I' AND T4."Correction" = 'N' AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END >= :DateFrom AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END <= :DateTo AND T0."TransType" = '18' AND T2.CANCELED = 'N' 
    GROUP BY T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", T3."LicTradNum"
    /* AP credit note, Input tax code, correction tax (return invoice to supplier) */ 
    UNION ALL 
    SELECT 'BA' AS "Category", T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", 
        IFNULL(T3."LicTradNum", '') AS "LicTradNum", 
        CASE 
            WHEN T2."DocStatus" = 'O' THEN COUNT(DISTINCT (T0."TransId")) 
            WHEN T2."DocTotal" <> 
            (SELECT MAX(IFNULL(T8."DocTotal", 0.0)) 
            FROM RPC1 T6 
                INNER JOIN PCH1 T7 ON T6."BaseEntry" = T7."DocEntry" AND T6."BaseType" = '18' 
                INNER JOIN OPCH T8 ON T7."DocEntry" = T8."DocEntry" 
            WHERE T6."DocEntry" = T2."DocEntry") THEN 0 
            ELSE COUNT(DISTINCT (T0."TransId")) * (-1) 
        END AS "Transactions", SUM(T1."BaseSum") * (-1) AS "BaseSum" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN ORPC T2 ON T0."TransId" = T2."TransId" 
        INNER JOIN OCRD T3 ON T2."CardCode" = T3."CardCode" 
        INNER JOIN OVTG T4 ON T1."VatGroup" = T4."Code" 
        LEFT OUTER JOIN CRD1 T5 ON T3."CardCode" = T5."CardCode" AND T3."ShipToDef" = T5."Address" AND
             T5."AdresType" = 'S' 
    WHERE (:Category = 'BA' OR :Category = 'BABS') AND T4."Category" = 'I' AND T4."Correction" = 'N' AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END >= :DateFrom AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END <= :DateTo AND T0."TransType" = '19' AND
         T2.CANCELED = 'N' 
    GROUP BY T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", T3."LicTradNum", T2."DocStatus", T2."DocEntry", T2."DocTotal" 
    /*AR credit note, Output tax code, correction tax (return invoice from customer) */
    UNION ALL 
    SELECT 'BA' AS "Category", T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", 
        IFNULL(T3."LicTradNum", '') AS "LicTradNum", COUNT(DISTINCT (T0."TransId")) AS "Transactions", 
        SUM(T1."BaseSum") AS "BaseSum" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN ORIN T2 ON T0."TransId" = T2."TransId" 
        INNER JOIN OCRD T3 ON T2."CardCode" = T3."CardCode" 
