        IFNULL(T3."LicTradNum", '') AS "LicTradNum", 
        CASE 
            WHEN T2."DocStatus" = 'O' THEN COUNT(DISTINCT (T0."TransId")) 
            WHEN T2."DocTotal" <> 
            (SELECT MAX(IFNULL(T8."DocTotal", 0.0)) 
            FROM RIN1 T6 
                INNER JOIN INV1 T7 ON T6."BaseEntry" = T7."DocEntry" AND T6."BaseType" = '13' 
                INNER JOIN OINV T8 ON T7."DocEntry" = T8."DocEntry" 
            WHERE T6."DocEntry" = T2."DocEntry") THEN 0 
            ELSE COUNT(DISTINCT (T0."TransId")) * (-1) 
        END AS "Transactions", SUM(T1."BaseSum") * (-1) AS "BaseSum" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN ORIN T2 ON T0."TransId" = T2."TransId" 
        INNER JOIN OCRD T3 ON T2."CardCode" = T3."CardCode" 
        INNER JOIN OVTG T4 ON T1."VatGroup" = T4."Code" 
        LEFT OUTER JOIN CRD1 T5 ON T3."CardCode" = T5."CardCode" AND T3."ShipToDef" = T5."Address" AND
             T5."AdresType" = 'S' 
    WHERE (:Category = 'BS' OR :Category = 'BABS') AND T4."Category" = 'O' AND T4."Correction" = 'N' AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END >= :DateFrom AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END <= :DateTo AND T0."TransType" = '14' AND
         T2.CANCELED = 'N' 
    GROUP BY T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", T3."LicTradNum", T2."DocStatus", T2."DocEntry", T2."DocTotal" 
    /* AP credit note, Input tax code, correction tax (return invoice to supplier) */
    UNION ALL 
    SELECT 'BS' AS "Category", T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", 
        IFNULL(T3."LicTradNum", '') AS "LicTradNum", COUNT(DISTINCT (T0."TransId")) AS "Transactions", 
        SUM(T1."BaseSum") AS "BaseSum" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN ORPC T2 ON T0."TransId" = T2."TransId" 
        INNER JOIN OCRD T3 ON T2."CardCode" = T3."CardCode" 
        INNER JOIN OVTG T4 ON T1."VatGroup" = T4."Code" 
        LEFT OUTER JOIN CRD1 T5 ON T3."CardCode" = T5."CardCode" AND T3."ShipToDef" = T5."Address" AND
             T5."AdresType" = 'S' 
    WHERE (:Category = 'BS' OR :Category = 'BABS') AND T4."Category" = 'I' AND T4."Correction" = 'Y' AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END >= :DateFrom AND 
        CASE :DateType 
            WHEN 'RefDate' THEN T0."RefDate" 
            WHEN 'DueDate' THEN T0."DueDate" 
            ELSE T0."TaxDate" 
        END <= :DateTo AND T0."TransType" = '19' AND T2.CANCELED = 'N' 
    GROUP BY T3."CmpPrivate", T3."CardCode", T3."CardName", T3."Country", T5."TaxOffice", T3."LicTradNum"
        )
        T11 
        WHERE T11."CardName" = T10."CardName" AND
         T11."Category" = T10."Category") >= :MinAmount 
    GROUP BY T10."Category", T10."CardCode", T10."CardName", T10."Country", T10."TaxOffice", T10."LicTradNum", T10."CmpPrivate" 
    ORDER BY T10."CardName";
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE CRSP_BPMONTHLY_WRAPPER
(
	FromDate1 Date,
	ToDate1 Date,
	DataType VARCHAR(1),
	execSQL NCLOB
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	FromDate VARCHAR(20);
	ToDate VARCHAR(20);
	FromDate2 timestamp;
	ToDate2 timestamp;
	IsExists INTEGER := 0;
	currentDate NVARCHAR(8);
BEGIN

	call _TmSp_ValidateSpParam(DataType);
	call _TmSp_ValidateSpParam(execSQL);
	
	DELETE FROM CRSP_TEMP_OCRD;
	exec ('INSERT INTO CRSP_TEMP_OCRD SELECT T0."CardCode", T0."CardName", T0."GroupCode", T0."Balance" FROM OCRD T0 WHERE ' || :execSQL );

	/*MonthBegin*/
	SELECT TO_CHAR(FromDate1, 'YYYYMMDD'), TO_CHAR(ToDate1, 'YYYYMMDD') INTO FromDate, ToDate FROM DUMMY;
	SELECT COUNT(*) INTO IsExists 
	FROM M_TEMPORARY_TABLES
	WHERE TABLE_NAME = '#MONTHBEGIN' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	
	IF :IsExists > 0 THEN
		DROP TABLE #MONTHBEGIN;
	END IF;
	CREATE LOCAL TEMPORARY ROW TABLE #MONTHBEGIN
	( "DATE" date);
	/*Work around for HANA rev74*/
	DELETE FROM #MONTHBEGIN WHERE 1=1;
	
	currentDate := :FromDate;
	WHILE LEFT(:currentDate, 6) < LEFT(:ToDate, 6) DO
		currentDate := TO_NVARCHAR(ADD_DAYS(LAST_DAY(TO_DATE(:currentDate)),1), 'YYYYMMDD');
		INSERT INTO #MONTHBEGIN VALUES(TO_DATE(:currentDate));
	END WHILE;
					
	select add_months(to_date(substr(:FromDate,1,6)||'01'),-1), 
	TO_DATE(last_day(add_months(to_date(substr(:FromDate,1,6)||'01'),-1))) 
	into FromDate2, ToDate2 from dummy;
	if :DataType = 'P'
	then
	/*Ordered*/
	TBL1 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			CAST(Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns" + T1."WTSum" - T1."RoundDif") AS DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			CAST(Sum(T1."GrosProfit") AS DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
	from ORDR T1 join CRSP_TEMP_OCRD T2 on T1."CardCode" = T2."CardCode" 
	where T1."CANCELED" = 'N' 
	and ( (T1."DocDate" >= :FromDate and T1."DocDate" <= :ToDate)
		or (T1."DocDate" >= :FromDate2 
			and T1."DocDate" <= :ToDate2))
	group by T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")) 
	;
	/*Order's Gross Base Total*/
	TBL2 = 
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			CAST ((Case When T4."GrossBySal" = 'Y' then Sum(T3."LineTotal") - Sum(T1."DiscSum")
				 Else Sum(T3."GPTtlBasPr")
			End) AS DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From ORDR T1 
		Join CRSP_TEMP_OCRD T2
		 On T1."CardCode" = T2."CardCode"
		Join "RDR1" T3
		 on T1."DocEntry" = T3."DocEntry"
		Cross Join "OADM" T4
		Where T1."CANCELED" = 'N'
		and		((T1."DocDate" >= :FromDate and T1."DocDate" <= :ToDate)
			or	(T1."DocDate" >= :FromDate2
				and T1."DocDate" <= :ToDate2))
		Group By T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")), T4."GrossBySal"
	;
	/*Delivered*/
	TBL3 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			CAST(Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns") AS DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From "ODLN" T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" 
		Where T1."DocDate" >= :FromDate 
		and T1."DocDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")) 
	;
	/*Returned*/
	TBL4 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			CAST(Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns") AS DECIMAL(21,6))as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From "ORDN" T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" 
		Where T1."DocDate" >= :FromDate 
		and T1."DocDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")) 
	;
	/*Invoiced*/
	TBL51 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From "OINV" T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."DocDate" >= :FromDate 
		and T1."DocDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR	FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")) 
	;
	TBL52 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			CAST(Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From "OCSI" T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."DocDate" >= :FromDate 
		and T1."DocDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate"))
	;
	TBL53 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From "OCSV" T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."DocDate" >= :FromDate 
		and T1."DocDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")) 
	;
	/*Credited*/
	TBL6 =
		select
			YEAR(T1."DocDate") as "YEARPARAM",
			MONTH(T1."DocDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE" 
		From "ORIN" T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."DocDate" >= :FromDate 
		and T1."DocDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR FROM (T1."DocDate")),extract(MONTH FROM (T1."DocDate")) 
	;
	/*Collected*/
	TBL7 =
		select
			YEAR(T1."RefDate") as "YEARPARAM",
			MONTH(T1."RefDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			CAST (Sum(T4."DocTotal") AS DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE" 
		From "JDT1" T1 Join CRSP_TEMP_OCRD T2 On T1."ShortName" = T2."CardCode" Join "OJDT" T3 On T1."TransId" = T3."TransId" 
		And T1."TransType" = 24 
		And T3."StornoToTr" IS NULL Join "ORCT" T4 On T3."CreatedBy" = T4."DocEntry" 
		Where T1."RefDate" >= :FromDate 
		and T1."RefDate" <= :ToDate 
		Group By T2."CardCode",extract(YEAR FROM (T1."RefDate")),extract(MONTH FROM (T1."RefDate")) 
	;
	/*OpenBalance*/
	TBL8 =
		Select
			YEAR(T0."Date") as "YEARPARAM",
			MONTH(T0."Date") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			CAST ((Max(T2."Balance") - (Sum(T1."Debit") - Sum(T1."Credit"))) AS DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE" 
		From "JDT1" T1 Join CRSP_TEMP_OCRD T2 on T1."ShortName" = T2."CardCode"
		Join 
		(
			select To_Date(:FromDate) as "Date" from DUMMY
			union
			select "DATE" from #MONTHBEGIN
		) T0
		On T1."RefDate" >= T0."Date" 
		Group By T2."CardCode",YEAR(T0."Date"),MONTH(T0."Date")
	;
	/*CloseBalance*/
	TBL9 =
		Select
			YEAR(T0."Date") as "YEARPARAM",
			MONTH(T0."Date") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			CAST ((Max(T2."Balance") - (Sum(T1."Debit") - Sum(T1."Credit"))) AS DECIMAL(21,6)) as "CLOSEBALANCE" 
		From "JDT1" T1 Join CRSP_TEMP_OCRD T2 on T1."ShortName" = T2."CardCode"
		Join 
		(
			select ADD_DAYS("DATE",-1) as "Date" from #MONTHBEGIN
			where  ADD_DAYS("DATE",-1) >= To_Date(:FromDate)
			union
			select To_Date(:ToDate) as "Date" from DUMMY
		) T0 
		On T1."RefDate" > T0."Date" 
		Group By T2."CardCode",YEAR(T0."Date"),MONTH(T0."Date")
	;

	TBL10 = SELECT * FROM :TBL1
			UNION ALL
			SELECT * FROM :TBL2
			UNION ALL
			SELECT * FROM :TBL3
			UNION ALL
			SELECT * FROM :TBL4
			UNION ALL
			SELECT * FROM :TBL51
			UNION ALL
			SELECT * FROM :TBL52
			UNION ALL
			SELECT * FROM :TBL53
			UNION ALL
			SELECT * FROM :TBL6
			UNION ALL			
			SELECT * FROM :TBL7
			UNION ALL
			SELECT * FROM :TBL8
			UNION ALL
			SELECT * FROM :TBL9
			;
	 
	/*TblResult*/
	TBL11 =
		select
			"YEARPARAM",
			"MONTHPARAM",
			"CARDCODE",
			Max("CARDNAME")as "CARDNAME",
			Max("GROUPCODE") as "GROUPCODE",
			Sum("RDRTOTAL") as "RDRTOTAL",
			Sum("GROSSBASE") as "GROSSBASE",
			Sum("GROSSPROFIT") as "GROSSPROFIT",
			Sum("DLNTOTAL") as "DLNTOTAL",
			Sum("RDNTOTAL") as "RDNTOTAL",
			Sum("INVTOTAL") as "INVTOTAL",
			Sum("RINTOTAL") as "RINTOTAL",
			Sum("RCTTOTAL") as "RCTTOTAL",
			Sum("OPENBALANCE") as "OPENBALANCE",
			Sum("CLOSEBALANCE") as "CLOSEBALANCE" 
		from :TBL10
		Group By "CARDCODE", "YEARPARAM", "MONTHPARAM" 
	;
	select
		T0."YEARPARAM",
		T0."MONTHPARAM",
		T0."CARDCODE",
		T0."CARDNAME",
		T0."GROUPCODE",
		T0."RDRTOTAL",
		T0."GROSSBASE",
		T0."GROSSPROFIT",
		T0."DLNTOTAL",
		T0."RDNTOTAL",
		T0."INVTOTAL",
		T0."RINTOTAL",
		T0."RCTTOTAL",
		Case When "OPENBALANCE" is null
			 And  T0."YEARPARAM" >= Year(To_Date(:FromDate))
			 And  T0."MONTHPARAM" >= Month(To_Date(:FromDate))
			 Then T1."Balance"
			 Else "OPENBALANCE"
		End as "OPENBALANCE",
		Case When "CLOSEBALANCE" is null 
			 And  T0."YEARPARAM" >= Year(To_Date(:FromDate))
			 And  T0."MONTHPARAM" >= Month(To_Date(:FromDate))
			 Then T1."Balance" 
			 Else "CLOSEBALANCE" 
		End as "CLOSEBALANCE"
	from :TBL11 T0 
	Join CRSP_TEMP_OCRD T1
	On T0."CARDCODE" = T1."CardCode"
	Order By T0."CARDCODE" Asc, T0."YEARPARAM" Desc, T0."MONTHPARAM" Desc 
	;
	else
	/*Ordered*/
	TBL1 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			CAST (Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns" + T1."WTSum" - T1."RoundDif") AS DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			CAST (Sum(T1."GrosProfit") AS DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
	from ORDR T1 join CRSP_TEMP_OCRD T2 on T1."CardCode" = T2."CardCode" 
	where T1."CANCELED" = 'N' 
	and ( (T1."TaxDate" >= :FromDate and T1."TaxDate" <= :ToDate)
		or (T1."TaxDate" >= :FromDate2 
			and T1."TaxDate" <= :ToDate2))
	group by T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate") 
	;
	/*Order's Gross Base Total*/
	TBL2 = 
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			CAST ((Case When T4."GrossBySal" = 'Y' then Sum(T3."LineTotal") - Sum(T1."DiscSum")
				 Else Sum(T3."GPTtlBasPr")
			End) AS DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From ORDR T1 
		Join CRSP_TEMP_OCRD T2
		 On T1."CardCode" = T2."CardCode"
		Join RDR1 T3
		 on T1."DocEntry" = T3."DocEntry"
		Cross Join OADM T4
		Where T1."CANCELED" = 'N'
		and		((T1."TaxDate" >= :FromDate and T1."TaxDate" <= :ToDate)
			or	(T1."TaxDate" >= :FromDate2
				and T1."TaxDate" <= :ToDate2))
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate"), T4."GrossBySal"
	;
	/*Delivered*/
	TBL3 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			CAST (Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns") AS DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From ODLN T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" 
		Where T1."TaxDate" >= :FromDate 
		and T1."TaxDate" <= :ToDate 
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate") 
	;
	/*Returned*/
	TBL4 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			CAST (Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns") AS DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From ORDN T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" 
		Where T1."TaxDate" >= :FromDate 
		and T1."TaxDate" <= :ToDate 
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate") 
	;
	/*Invoiced*/
	TBL51 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From OINV T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."TaxDate" >= :FromDate 
		and T1."TaxDate" <= :ToDate 
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate") 
	;
	TBL52 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From OCSI T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."TaxDate" >= :FromDate 
		and T1."TaxDate" <= :ToDate 
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate")
	;
	TBL53 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE"
		From OCSV T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."TaxDate" >= :FromDate 
		and T1."TaxDate" <= :ToDate 
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate") 
	;
	/*Credited*/
	TBL6 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			CAST (Sum(T3."Debit" - T3."Credit") AS DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE" 
		From ORIN T1 Join CRSP_TEMP_OCRD T2 On T1."CardCode" = T2."CardCode" Join "JDT1" T3 on T1."TransId" = T3."TransId" 
		and T3."ShortName" = T2."CardCode" 
		Where T1."TaxDate" >= :FromDate 
		and T1."TaxDate" <= :ToDate 
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate") 
	;
	/*Collected*/
	TBL7 =
		select
			YEAR(T1."TaxDate") as "YEARPARAM",
			MONTH(T1."TaxDate") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			CAST (Sum(T1."DocTotal") AS DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE" 
		From (select T3."TransId", T4."DocTotal",T4."Canceled",T1."ShortName",T1."TransType",T1."TaxDate" from JDT1 T1 
		join OJDT T3 On T1."TransId" = T3."TransId" And T1."TransType" = 24 And T3."StornoToTr" IS NULL
		join ORCT T4 on T4."DocEntry" = T3."CreatedBy" where T4."Canceled" = 'N'
		group by T4."Canceled",T3."TransId", T4."DocTotal",T1."ShortName",T1."TransType",T1."TaxDate") T1 
		Join CRSP_TEMP_OCRD T2 On T1."ShortName" = T2."CardCode"
		Where T1."TaxDate" >= :FromDate
		and T1."TaxDate" <= :ToDate
		Group By T2."CardCode",YEAR(T1."TaxDate"),MONTH(T1."TaxDate")
		;
	/*OpenBalance*/
	TBL8 =
		Select
			YEAR(T0."Date") as "YEARPARAM",
			MONTH(T0."Date") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			CAST ((Max(T2."Balance") - (Sum(T1."Debit") - Sum(T1."Credit"))) AS DECIMAL(21,6)) as "OPENBALANCE",
			cast (null as DECIMAL(21,6)) as "CLOSEBALANCE" 
		From JDT1 T1 Join CRSP_TEMP_OCRD T2 on T1."ShortName" = T2."CardCode"
		Join 
		(
			select To_Date(:FromDate) as "Date" from DUMMY
			union
			select "DATE" from #MONTHBEGIN
		) T0
		On T1."TaxDate" >= T0."Date" 
		Group By T2."CardCode",YEAR(T0."Date"),MONTH(T0."Date")
	;
	/*CloseBalance*/
	TBL9 =
		Select
			YEAR(T0."Date") as "YEARPARAM",
			MONTH(T0."Date") as "MONTHPARAM",
			T2."CardCode" as "CARDCODE",
			Max(T2."CardName") as "CARDNAME",
			Max(T2."GroupCode") as "GROUPCODE",
			cast (null as DECIMAL(21,6)) as "RDRTOTAL",
			cast (null as DECIMAL(21,6)) as "GROSSBASE",
			cast (null as DECIMAL(21,6)) as "GROSSPROFIT",
			cast (null as DECIMAL(21,6)) as "DLNTOTAL",
			cast (null as DECIMAL(21,6)) as "RDNTOTAL",
			cast (null as DECIMAL(21,6)) as "INVTOTAL",
			cast (null as DECIMAL(21,6)) as "RINTOTAL",
			cast (null as DECIMAL(21,6)) as "RCTTOTAL",
			cast (null as DECIMAL(21,6)) as "OPENBALANCE",
			CAST((Max(T2."Balance") - (Sum(T1."Debit") - Sum(T1."Credit"))) AS DECIMAL(21,6)) as "CLOSEBALANCE" 
		From JDT1 T1 Join CRSP_TEMP_OCRD T2 on T1."ShortName" = T2."CardCode"
		Join 
		(
			select ADD_DAYS("DATE",-1) as "Date" from #MONTHBEGIN
			where  ADD_DAYS("DATE",-1) >= To_Date(:FromDate)
			union
			select To_Date(:ToDate) as "Date" from DUMMY
		) T0
		On T1."TaxDate" > T0."Date" 
		Group By T2."CardCode",YEAR(T0."Date"),MONTH(T0."Date")
	;

	TBL10 = SELECT * FROM :TBL1
			UNION ALL
			SELECT * FROM :TBL2
			UNION ALL
			SELECT * FROM :TBL3
			UNION ALL
			SELECT * FROM :TBL4
			UNION ALL
			SELECT * FROM :TBL51
			UNION ALL
			SELECT * FROM :TBL52
			UNION ALL
			SELECT * FROM :TBL53
			UNION ALL
			SELECT * FROM :TBL6
			UNION ALL			
			SELECT * FROM :TBL7
			UNION ALL
			SELECT * FROM :TBL8
			UNION ALL
			SELECT * FROM :TBL9
			;
			
	/*TblResult*/
	TBL11 =
		select
			"YEARPARAM",
			"MONTHPARAM",
			"CARDCODE",
			Max("CARDNAME")as "CARDNAME",
			Max("GROUPCODE") as "GROUPCODE",
			Sum("RDRTOTAL") as "RDRTOTAL",
			Sum("GROSSBASE") as "GROSSBASE",
			Sum("GROSSPROFIT") as "GROSSPROFIT",
			Sum("DLNTOTAL") as "DLNTOTAL",
			Sum("RDNTOTAL") as "RDNTOTAL",
			Sum("INVTOTAL") as "INVTOTAL",
			Sum("RINTOTAL") as "RINTOTAL",
			Sum("RCTTOTAL") as "RCTTOTAL",
			Sum("OPENBALANCE") as "OPENBALANCE",
			Sum("CLOSEBALANCE") as "CLOSEBALANCE" 
		from :TBL10
		Group By "CARDCODE", "YEARPARAM", "MONTHPARAM" 
	;
	select
		T0."YEARPARAM",
		T0."MONTHPARAM",
		T0."CARDCODE",
		T0."CARDNAME",
		T0."GROUPCODE",
		T0."RDRTOTAL",
		T0."GROSSBASE",
		T0."GROSSPROFIT",
		T0."DLNTOTAL",
		T0."RDNTOTAL",
		T0."INVTOTAL",
		T0."RINTOTAL",
		T0."RCTTOTAL",
		Case When "OPENBALANCE" is null
			 And  T0."YEARPARAM" >= Year(To_Date(:FromDate))
			 And  T0."MONTHPARAM" >= Month(To_Date(:FromDate))
			 Then T1."Balance"
			 Else "OPENBALANCE"
		End as "OPENBALANCE",
		Case When "CLOSEBALANCE" is null 
			 And  T0."YEARPARAM" >= Year(To_Date(:FromDate))
			 And  T0."MONTHPARAM" >= Month(To_Date(:FromDate))
			 Then T1."Balance" 
			 Else "CLOSEBALANCE" 
		End as "CLOSEBALANCE" 
	from :TBL11 T0 
	Join CRSP_TEMP_OCRD T1
	On T0."CARDCODE" = T1."CardCode" 
	Order By T0."CARDCODE" Asc, T0."YEARPARAM" Desc, T0."MONTHPARAM" Desc
	;
	end if;
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE CRSP_BPRANGE
(
	execSQL NCLOB
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	call _TmSp_ValidateSpParam(execSQL);
	
	DELETE FROM CRSP_TEMP_BPRANGE;
	exec ('INSERT INTO CRSP_TEMP_BPRANGE SELECT MIN("CardCode"), MAX("CardCode") FROM (SELECT "CardCode" FROM OCRD T0 WHERE ' || :execSQL || ')');
	SELECT MINCODE, MAXCODE FROM CRSP_TEMP_BPRANGE;
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

Create Procedure CRSP_Calendar_Daily_Across_Items(
In DisplayDate NVarChar(8),
In HolidaysCode NVarChar(20), 
In EmployeeIDs CLOB, 
In UserIDs CLOB, 
In MinutesPerRow SmallInt, 
In RecurringInstances NVarChar(1000), 
In ShowEmployeeAbsEdu TinyInt,
In ShowPhoneCall TinyInt, 
In ShowMeeting TinyInt, 
In ShowOther TinyInt, 
In ShowTask TinyInt, 
In ShowPersonal TinyInt, 
In ShowServiceCalls TinyInt)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
	RecInstances nvarchar(4800);
	timev int;
	span int;
	entry int;
	tmpStr nvarchar(4800);
	curr int;
	prev int;
	Code_Sep int;
	Instance nvarchar(50);
	tmpRecontact nvarchar(100);
    tmpEndDate nvarchar(100);
    tmpClgCode nvarchar(100);
Begin

	call _TmSp_ValidateSpParam(DisplayDate);
	call _TmSp_ValidateSpParam(HolidaysCode);
	call _TmSp_ValidateSpParam(EmployeeIDs);
	call _TmSp_ValidateSpParam(UserIDs);
	call _TmSp_ValidateSpParam(RecurringInstances);
		
	delete from "CRSPCalendarDailyAcrossItemsUsers";
	delete from "CRSPCalendarDailyAcrossItemsEmployees";
	delete from "CRSPCalendarDailyAcrossItemsCalendarMD";
	delete from "CRSPCalendarDailyAcrossItemsEmployeesAbsEdu";
	delete from "CRSPCalendarDailyAcrossItemsServiceCalls";
	delete from "CRSPCalendarDailyAcrossItemsInstances";

	RecInstances := RecurringInstances;
	
	tmpStr := 'insert into "CRSPCalendarDailyAcrossItemsUsers" select "USERID", "USER_CODE", "U_NAME" from OUSR' ||
		' where "USERID" in ' || :UserIDs;	
	exec(:tmpStr);

	tmpStr := 'insert into "CRSPCalendarDailyAcrossItemsEmployees" select "empID", "firstName", "middleName", "lastName"' ||
		' from OHEM where "empID" in ' || :EmployeeIDs;
	exec(:tmpStr);

	entry := 0;
	span := :MinutesPerRow;
	timev := 0;
	
	-- Insert the Holidays
	if (length(:HolidaysCode) > 0) then
		insert into "CRSPCalendarDailyAcrossItemsCalendarMD" (HldCode, Recontact, EndDate, Details)
			select "HldCode", "StrDate", "EndDate", "Rmrks" From HLD1 where "HldCode" = :HolidaysCode
			And (("StrDate" = :DisplayDate Or "EndDate" = :DisplayDate) Or ("StrDate" < :DisplayDate And "EndDate" > :DisplayDate));
	end if;
	
	
	-- Store Employee Absence and Education to the temporary table
	if (:ShowEmployeeAbsEdu = 1) then
	
		tmpStr := 'insert into "CRSPCalendarDailyAcrossItemsEmployeesAbsEdu"(UserId, EmployeeId, StartDate, EndDate, Details)' ||
		-- Absence
			' select T1."userId", T0."empID", T0."fromDate", T0."toDate", T0."reason"' ||
			' from HEM1 T0' || 
			' inner join OHEM T1 On T1."empID" = T0."empID" ' ||
			' where ' || 
			' ((T0."fromDate" >= '''|| :DisplayDate || ''' And T0."fromDate" <= '''|| :DisplayDate || ''') Or' ||
	 		' (T0."toDate" >= '''|| :DisplayDate || ''' And T0."toDate" <= '''|| :DisplayDate || ''') Or' ||
	 		' (T0."fromDate" < '''|| :DisplayDate || ''' And T0."toDate" > '''|| :DisplayDate || ''')) And' ||
			' (T1."userId" in '|| :UserIDs || ' Or T1."empID" in '|| :EmployeeIDs || ')' ||
			' union all' ||
			-- Education
			' select T1."userId", T0."empID", T0."fromDate", T0."toDate", T2."name"' || 
			' from HEM2 T0' ||
			' inner join OHEM T1 On T1."empID" = T0."empID"' ||
			' inner join OHED T2 On T2."edType" = T0."type"' ||
			' where ' ||
			' ((T0."fromDate" >= '''|| :DisplayDate || ''' And T0."fromDate" <= '''|| :DisplayDate || ''') Or' ||
			' (T0."toDate" >= '''|| :DisplayDate || ''' And T0."toDate" <= '''|| :DisplayDate || ''') Or' ||
			' (T0."fromDate" < '''|| :DisplayDate || ''' And T0."toDate" > '''|| :DisplayDate || ''')) And' ||
			' (T1."userId" in '|| :UserIDs || ' Or T1."empID" in '|| :EmployeeIDs || ')' ||
			' order By T0."fromDate", T0."toDate" Desc';
			
		exec(:tmpStr);
	
		-- Insert Employee Absence and Education to #CalendarMD
		insert into "CRSPCalendarDailyAcrossItemsCalendarMD"(AbsEduSeq, UserId, EmployeeId, Recontact, EndDate, Details)
			select AbsEduSeq, UserId, EmployeeId, StartDate, EndDate, Details 
			from "CRSPCalendarDailyAcrossItemsEmployeesAbsEdu";
	end if;
	
	if :ShowServiceCalls = 1 then
		tmpStr := 'insert into "CRSPCalendarDailyAcrossItemsServiceCalls"(CallID, StartDate, EndDate, BeginTime, EndTime, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, Instance)' ||
			' select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee", T2."manager", T1."userId",' || 
			' T0."technician", ''A''' ||
			' from OSCL T0 left Outer Join OHEM T1 On T1."empID" = T0."technician"' ||
			' left Outer Join OQUE T2 On T2."queueID" = T0."Queue"' ||
			' where T0."DisplInCal" = ''Y'' And' ||
			' ((T0."StartDate" >= '''|| :DisplayDate || ''' And T0."StartDate" <= '''|| :DisplayDate || ''') Or' ||
	 		' (T0."EndDate" >= '''|| :DisplayDate || ''' And T0."EndDate" <= '''|| :DisplayDate || ''') Or' ||
	 		' (T0."StartDate" < '''|| :DisplayDate || ''' And T0."EndDate" > '''|| :DisplayDate || ''')) And' ||
    		' T0."StartDate" <> T0."EndDate" And' ||
    		' (T0."assignee" in ' || :UserIDs || ' Or T2."manager" in ' || :UserIDs || ')' || 
			' union all' ||
			' select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee",'||
			' T2."manager", T1."userId", T0."technician", ''T''' ||
			' from OSCL T0 left outer join OHEM T1 On T1."empID" = T0."technician"' ||
			' left outer join OQUE T2 On T2."queueID" = T0."Queue"' ||
			' where T0."DisplInCal" = ''Y'' And' ||
			' ((T0."StartDate" >= '''|| :DisplayDate || ''' And T0."StartDate" <= '''|| :DisplayDate || ''') Or' ||
	 		' (T0."EndDate" >= '''|| :DisplayDate || ''' And T0."EndDate" <= '''|| :DisplayDate || ''') Or' ||
	 		' (T0."StartDate" < '''|| :DisplayDate || ''' And T0."EndDate" > '''|| :DisplayDate || ''')) And' ||
    		' T0."StartDate" <> T0."EndDate" And' ||
    		' (T1."userId" in ' || :UserIDs || ' Or T0."technician" in '|| :EmployeeIDs || ')' || 
			' order by T0."StartDate", T0."EndDate" Desc, T0."StartTime", T0."EndTime" Desc';
		
		exec(:tmpStr);

		-- Insert Service calls to #CalendarMD
		insert into "CRSPCalendarDailyAcrossItemsCalendarMD"(CallID, AssigneeUID, QueueManagerUID, TechUID, TechEID, SCInstance, Recontact, 
			EndDate, BeginTime, EndTime, Details)
			select CallID, AssigneeUID, QueueManagerUID, TechUID, TechEID, Instance, StartDate, EndDate, BeginTime, EndTime, Details 
			from "CRSPCalendarDailyAcrossItemsServiceCalls" order by StartDate, EndDate Desc, BeginTime, EndTime Desc, Instance;
	end if;    
	
	tmpStr := 'insert into "CRSPCalendarDailyAcrossItemsCalendarMD"(ClgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal,' ||
		' Details, UserId, EmployeeId)' ||
		' select T0."ClgCode", T0."Recontact", T0."endDate", T0."BeginTime", T0."ENDTime", T0."Action", T0."personal", T0."Details", T0."AttendUser", T0."AttendEmpl"' ||
		' from OCLG T0 join "CRSPCalendarDailyAcrossItemsUsers" T1 On T0."AttendUser" = T1.UserId where ' ||
		' (((T0."Recontact" >= '''|| :DisplayDate || ''' AND T0."Recontact" <= '''|| :DisplayDate || ''' )  or' ||
		' (T0."endDate" >= '''|| :DisplayDate || ''' AND T0."endDate" <= '''|| :DisplayDate || ''' )) or' ||
		' ( T0."Recontact" < '''|| :DisplayDate || '''  AND  T0."endDate" > '''|| :DisplayDate || ''' )' ||
		' ) AND T0."endDate" <> T0."Recontact" And (T0."RecurPat" = ''N'' Or T0."SeriesNum" is not null) And' ||
		' (T0."personal" = ''N'' ';
		
	if :ShowPersonal = 1 then
		tmpStr := :tmpStr || 'OR T0."personal" = ''Y''';
	end if;

	tmpStr := :tmpStr || ') And (T0."Action" = ''_'' ';

	if :ShowPhoneCall = 1 then 
		tmpStr := :tmpStr || 'Or T0."Action" = ''C'' ';
	end if;
	
	if :ShowMeeting = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''M'' ';
	end if;
	
	if :ShowOther = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''N'' ';
	end if;
	
	if :ShowTask = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''T'' ';
	end if;

	tmpStr := :tmpStr || ') union all' ||
		' select T0."ClgCode", T0."Recontact", T0."endDate", T0."BeginTime", T0."ENDTime", T0."Action", T0."personal", T0."Details", T0."AttendUser", T0."AttendEmpl"' ||
		' from OCLG T0 join "CRSPCalendarDailyAcrossItemsEmployees" T2 On T0."AttendEmpl" = T2.EmployeeID where' ||
		' (((T0."Recontact" >= '''|| :DisplayDate || ''' AND T0."Recontact" <= '''|| :DisplayDate || ''' )  OR' ||
		' (T0."endDate" >= '''|| :DisplayDate || ''' AND T0."endDate" <= '''|| :DisplayDate || ''' ) ) OR' ||
		' ( T0."Recontact" < '''|| :DisplayDate || '''  AND  T0."endDate" > '''|| :DisplayDate || ''' )' ||
		' ) AND T0."endDate" <> T0."Recontact" And' || 
		' (T0."RecurPat" = ''N'' Or T0."SeriesNum" is not null) And (T0."personal" = ''N'' ';

	if :ShowPersonal = 1 then
		tmpStr := :tmpStr || 'OR T0."personal" = ''Y''';
	end if;	
		
	tmpStr := :tmpStr || ') And (T0."Action" = ''_'' ';

	if :ShowPhoneCall = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''C'' ';
	end if;
	
	if :ShowMeeting = 1 then 
		tmpStr := :tmpStr || 'Or T0."Action" = ''M'' ';
	end if;
	
	if :ShowOther = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''N'' ';
	end if;
		
	if :ShowTask = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''T'' ';
	end if;
	
	tmpStr := :tmpStr || ') order by T0."Recontact", T0."BeginTime"';

	exec (:tmpStr);
	
		while length(:RecInstances) > 0 do
       curr := locate(:RecInstances, ' ');
      
       if :curr > 0 then
			Instance := SUBSTRING(:RecInstances, 0, :curr);
		else
			Instance := :RecInstances;
		end if;
		
		tmpClgCode := substr(:Instance, 0, locate(:Instance, ',')-1);
        Instance := substr_after(:Instance, ',');
        tmpRecontact := substr(:Instance, 0, locate(:Instance, ',')-1);
        tmpEndDate := rtrim(substr_after(:Instance, ','), ' ');
                      
        insert into "CRSPCalendarDailyAcrossItemsInstances" (ClgCode, Recontact, EndDate) 
       	values(:tmpClgCode, :tmpRecontact, :tmpEndDate);

        RecInstances := substr_after(RecInstances, ' ');
    end While;
    
    -- Get other information from OCLG
	update "CRSPCalendarDailyAcrossItemsInstances" T0
	set AttendUser = (select MIN(T1."AttendUser") from OCLG T1 where T0.ClgCode = T1."ClgCode"), 
		AttendEmployee = (select MIN(T1."AttendEmpl") from OCLG T1 where T0.ClgCode = T1."ClgCode"), 
		BeginTime = (select MIN(T1."BeginTime") from OCLG T1 where T0.ClgCode = T1."ClgCode"), 
		EndTime = (select MIN(T1."ENDTime") from OCLG T1 where T0.ClgCode = T1."ClgCode"), 
		Action = (select MIN(T1."Action") from OCLG T1 where T0.ClgCode = T1."ClgCode"), 
		Personal = (select MIN(T1."personal") from OCLG T1 where T0.ClgCode = T1."ClgCode"), 
		Details = (select MIN(T1."Details") from OCLG T1 where T0.ClgCode = T1."ClgCode");

	-- Delete the original recurring Activity, because the instances also include it
	delete from "CRSPCalendarDailyAcrossItemsCalendarMD" where clgCode in (Select Distinct clgCode From "CRSPCalendarDailyAcrossItemsInstances");
	
	-- Insert the instances filtered by users
	insert into "CRSPCalendarDailyAcrossItemsCalendarMD"(ClgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, UserId, EmployeeId)
	select clgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, AttendUser, AttendEmployee 
	From "CRSPCalendarDailyAcrossItemsInstances" T0 
	Join "CRSPCalendarDailyAcrossItemsUsers" T1 On T0.AttendUser = T1.UserID
	Where T0.Recontact = :DisplayDate Or T0.endDate = :DisplayDate Or T0.Recontact < :DisplayDate And T0.EndDate > :Displaydate;

	-- Insert the instances filtered by employees
	Insert Into "CRSPCalendarDailyAcrossItemsCalendarMD"(ClgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, UserId, EmployeeId)
	Select clgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, AttendUser, AttendEmployee 
	From "CRSPCalendarDailyAcrossItemsInstances" T0 
	Join "CRSPCalendarDailyAcrossItemsEmployees" T2 On T0.AttendEmployee = T2.EmployeeID
	Where T0.Recontact = :DisplayDate Or T0.endDate = :DisplayDate Or T0.Recontact < :DisplayDate And T0.EndDate > :Displaydate;
	    
	select * from "CRSPCalendarDailyAcrossItemsCalendarMD";   -- Order By Recontact, BeginTime

	delete from "CRSPCalendarDailyAcrossItemsUsers";
	delete from "CRSPCalendarDailyAcrossItemsEmployees";
	delete from "CRSPCalendarDailyAcrossItemsCalendarMD";
	delete from "CRSPCalendarDailyAcrossItemsEmployeesAbsEdu";
	delete from "CRSPCalendarDailyAcrossItemsServiceCalls";
	delete from "CRSPCalendarDailyAcrossItemsInstances";
End;

