Create Procedure CRSP_Calendar_Daily_Group_Across_Days_Items(
In DisplayDateIn NVarChar(8),
In HolidaysCodeIn NVarChar(20),
In EmployeeIDIn Integer,
In UserIDIn Integer,
In MinutesPerRowIn SmallInt,
In RecurringInstancesIn NVarChar(1000),
In ShowEmployeeAbsEduIn TinyInt,
In ShowPhoneCallIn TinyInt,
In ShowMeetingIn TinyInt,
In ShowOtherIn TinyInt,
In ShowTaskIn TinyInt,
In ShowPersonalIn TinyInt,
In ShowServiceCallsIn TinyInt)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
DisplayDate DateTime;
HolidaysCode NVarChar(20);
ShowPhoneCall tinyint;
ShowMeeting tinyint;
ShowOther tinyint;
ShowTask tinyint;
ShowPersonal tinyint;
ShowEmployeeAbsEdu tinyint;
ShowServiceCalls tinyint;
GapPerRow int;
RecurringInstances NVarChar(1000);
time int;
span int;
entry int;
curr int;
prev int;
seq int;
Code_Sep int;
Instance NVarChar(50);
sqlStr NCLOB;
UserId Integer;
EmployeeID Integer;
tmpClgCode int;
tmpRecontact DateTime;
tmpEndDate DateTime;
tmpUserId int;
tempEmpId int;
fromDate DateTime;
toDate DateTime;
reason NVarChar(120);

cursor hem_c (DisplayDate Datetime, UserId int, EmployeeID int) for Select T1."userId", T0."empID", T0."fromDate", T0."toDate", T0."reason"
	From HEM1 T0 
	Inner Join OHEM T1 On T1."empID" = T0."empID"
	Where 
		((T0."fromDate" >= :DisplayDate And T0."fromDate" <= :DisplayDate) Or
		(T0."toDate" >= :DisplayDate And T0."toDate" <= :DisplayDate) Or
		(T0."fromDate" < :DisplayDate And T0."toDate" > :DisplayDate)) And
		(T1."userId" = :UserId Or T1."empID" = :EmployeeID)
	Union All
	-- Education
	Select T1."userId", T0."empID", T0."fromDate", T0."toDate", T2."name"
	From HEM2 T0 
	Inner Join OHEM T1 On T1."empID" = T0."empID"
	Inner Join OHED T2 On T2."edType" = T0."type"
	Where 
		((T0."fromDate" >= :DisplayDate And T0."fromDate" <= :DisplayDate) Or
		(T0."toDate" >= :DisplayDate And T0."toDate" <= :DisplayDate) Or
		(T0."fromDate" < :DisplayDate And T0."toDate" > :DisplayDate)) And
		(T1."userId" =:UserID Or T1."empID" =:EmployeeID)
	Order By T0."fromDate", T0."toDate" Desc;
Begin
---------------------------------------------------------------------

call _TmSp_ValidateSpParam(DisplayDateIn);
call _TmSp_ValidateSpParam(HolidaysCodeIn);
call _TmSp_ValidateSpParam(RecurringInstancesIn);

HolidaysCode := :HolidaysCodeIn;
DisplayDate := :DisplayDateIn;
ShowPhoneCall := :ShowPhoneCallIn;
ShowMeeting := :ShowMeetingIn;
ShowOther := :ShowOtherIn;
ShowTask := :ShowTaskIn;
ShowPersonal := :ShowPersonalIn;
ShowEmployeeAbsEdu := :ShowEmployeeAbsEduIn;
ShowServiceCalls := :ShowServiceCallsIn;
GapPerRow := :MinutesPerRowIn;
RecurringInstances := :RecurringInstancesIn;
UserId := :UserIDIn;
EmployeeID := :EmployeeIDIn;
---------------------------------------------------------------------

delete from "CRSPCalendarDailyGroupAcrossDaysItemsInstances"; 
delete from "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD";


entry := 0;
span := :GapPerRow;
time := 0;

-- Insert the Holidays
If :HolidaysCode <> '' Then
	Insert into "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD" (HldCode, Recontact, EndDate, Details)
	Select "HldCode", "StrDate",  "EndDate", "Rmrks" From HLD1 where "HldCode" = :HolidaysCode
	And 
	( 
		("StrDate" = :DisplayDate Or "EndDate" = :DisplayDate)
		Or
		("StrDate" < :DisplayDate And "EndDate" > :DisplayDate)
	);
End If;


seq := 1;
-- Store Employee Absence and Education to the temporary table
If :ShowEmployeeAbsEdu = 1 Then

	open hem_c (:DisplayDate, :UserId, :EmployeeID);
	
	fetch hem_c into tmpUserId, tempEmpId, fromDate, toDate, reason;
	
	while not hem_c::NOTFOUND do
		insert Into "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD" (AbsEduSeq, UserId, EmployeeId, Recontact, EndDate, Details)
		values (:seq, :tmpUserId, :tempEmpId, :fromDate, :toDate, :reason);
	
		seq := :seq +1;
		fetch hem_c into tmpUserId, tempEmpId, fromDate, toDate, reason;
	end while;
	
	close hem_c;
	
	-- Insert Employee Absence and Education to "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"
End If;

-- Store Service calls to the temporary table
If :ShowServiceCalls = 1 Then
		
	Insert Into "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"(CallID, Recontact, EndDate, BeginTime, EndTime, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, SCInstance)
	
	
	Select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee", T2."manager", T1."userId", T0."technician", 'A'
	From OSCL T0
	Left Outer Join OHEM T1 On T1."empID" = T0."technician"
	Left Outer Join OQUE T2 On T2."queueID" = T0."Queue"
	Where 
		T0."DisplInCal" = 'Y' And
		((T0."StartDate" >= :DisplayDate And T0."StartDate" <= :DisplayDate) Or
		(T0."EndDate" >= :DisplayDate And T0."EndDate" <= :DisplayDate) Or
		(T0."StartDate" < :DisplayDate And T0."EndDate" > :DisplayDate)) And
		T0."StartDate" <> T0."EndDate" And
		(T0."assignee" =:UserID Or T2."manager" =:EmployeeID) 
	Union All
	Select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee", T2."manager", T1."userId", T0."technician", 'T'
	From OSCL T0
	Left Outer Join OHEM T1 On T1."empID" = T0."technician"
	Left Outer Join OQUE T2 On T2."queueID" = T0."Queue"
	Where 
		T0."DisplInCal" = 'Y' And
		((T0."StartDate" >= :DisplayDate And T0."StartDate" <= :DisplayDate) Or
		(T0."EndDate" >= :DisplayDate And T0."EndDate" <= :DisplayDate) Or
		(T0."StartDate" < :DisplayDate And T0."EndDate" > :DisplayDate)) And
		T0."StartDate" <> T0."EndDate" And
		(T1."userId" =:UserID Or T0."technician" =:EmployeeID) 
	Order By T0."StartDate", T0."EndDate" Desc;
	
End IF;

-- Store the filtered activites to the temporary table
SqlStr := 'Insert Into "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"(ClgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, UserId, EmployeeId)
	Select T0."ClgCode", T0."Recontact", T0."endDate", T0."BeginTime", T0."ENDTime", T0."Action", T0."personal", T0."Details", T0."AttendUser", T0."AttendEmpl"
	From OCLG T0 
	Where T0."AttendUser" =' || :UserId ||' And
	(
		(
			(T0."Recontact" >= ''' ||  :DisplayDate || ''' AND T0."Recontact" <= ''' || :DisplayDate || ''')  OR
			(T0."endDate" >= ''' || :DisplayDate || ''' AND T0."endDate" <= ''' || :DisplayDate || ''') 
		) OR
		( T0."Recontact" < ''' || :DisplayDate || ''' AND  T0."endDate" > ''' || :DisplayDate || ''' )
	) AND T0."endDate" <> T0."Recontact" And 
	(T0."RecurPat" = ''N'' Or T0."SeriesNum" IS NOT NULL) And (T0."personal" = ''N'' )';
	
If :ShowPersonal = 1 Then
	SqlStr := :SqlStr || 'OR (T0."personal" = ''Y'')';
End If;

SqlStr := :SqlStr || 'And (T0."Action" = ''_'' ';

If :ShowPhoneCall = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''C'' ';
End If;
If :ShowMeeting = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''M'' ';
End If;
If :ShowOther = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''N'' ';
End If;
If :ShowTask = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''T'' ';
End If;

SqlStr := :SqlStr || ') ';
SqlStr := :SqlStr || 'Union All
	Select T0."ClgCode", T0."Recontact", T0."endDate", T0."BeginTime", T0."ENDTime", T0."Action", T0."personal", T0."Details", T0."AttendUser", T0."AttendEmpl"
	From OCLG T0 
	Where T0."AttendEmpl" = ' || :EmployeeID || ' And
	(
		(
			(T0."Recontact" >= ''' || :DisplayDate || ''' AND T0."Recontact" <= ''' || :DisplayDate || ''')  OR
			(T0."endDate" >= ''' || :DisplayDate || ''' AND T0."endDate" <= ''' || :DisplayDate || ''') 
		) OR
		( T0."Recontact" < ''' || :DisplayDate || ''' AND  T0."endDate" > ''' || :DisplayDate || ''' )
	) AND T0."endDate" <> T0."Recontact" And 
	(T0."RecurPat" = ''N'' Or T0."SeriesNum" IS NOT NULL) And
	(T0."personal" = ''N'' ';
	
If :ShowPersonal = 1 Then
	SqlStr := :SqlStr || 'OR T0."personal" = ''Y''';
End IF;
SqlStr := :SqlStr || ') ';

SqlStr := :SqlStr || 'And (T0."Action" = ''_'' ';

If :ShowPhoneCall = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''C'' ';
End If;
If :ShowMeeting = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''M'' ';
End If;
If :ShowOther = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''N'' ';
End If;
If :ShowTask = 1 Then
	SqlStr := :SqlStr || 'Or T0."Action" = ''T'' ';
End IF;
SqlStr := :SqlStr || ') ';
SqlStr := :SqlStr || 'Order By T0."Recontact", T0."BeginTime"';
exec (:SqlStr);

--insert into debug values (SqlStr);

-- Insert the recurring instances

curr := 1;
prev := 1;

	-- Store the recurring instances in the temporary table

While length(:RecurringInstances) > 0 DO
	curr := locate(:RecurringInstances, ' ');
	if :curr>0 then
			Instance := SUBSTRING(:RecurringInstances, 0, :curr);
	else
			Instance := :RecurringInstances;
	end if;
	tmpClgCode := substr(:Instance, 0, locate(:Instance, ',')-1);
	Instance := substr_after(:Instance, ',');
	tmpRecontact := substr(:Instance, 0, locate(:Instance, ',')-1);
	tmpEndDate := rtrim(substr_after(:Instance, ','));

	insert into "CRSPCalendarDailyGroupAcrossDaysItemsInstances" (Select :tmpClgCode, 0, 0, :tmpRecontact, :tmpEndDate, 0, 0, ' ', ' ', ' ' FROM DUMMY);

	RecurringInstances := substr_after(RecurringInstances, ' ');
End While;

	-- Get other information from OCLG
Update "CRSPCalendarDailyGroupAcrossDaysItemsInstances" T0
Set AttendUser = (SELECT "AttendUser" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode"), 
AttendEmployee = (SELECT "AttendEmpl" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode"), 
BeginTime = (SELECT "BeginTime" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode"), 
EndTime = (SELECT "ENDTime" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode"), 
Action = (SELECT "Action" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode"), 
Personal = (SELECT "personal" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode"), 
Details = (SELECT "Details" FROM OCLG T1 Where T0.ClgCode = T1."ClgCode");

	-- Delete the original recurring Activity, because the instances also include it
Delete FROM "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"
Where clgCode in (Select Distinct clgCode From "CRSPCalendarDailyGroupAcrossDaysItemsInstances");

	-- Insert the instances filtered by users
Insert Into "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"(ClgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, UserId, EmployeeId)
Select clgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, AttendUser, AttendEmployee 
From "CRSPCalendarDailyGroupAcrossDaysItemsInstances" T0 
Where T0.AttendUser = :UserID And T0.Recontact = :DisplayDate Or T0.endDate = :DisplayDate Or 
T0.Recontact < :DisplayDate And T0.EndDate > :Displaydate;

	-- Insert the instances filtered by employees
Insert Into "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"(ClgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, UserId, EmployeeId)
Select clgCode, Recontact, EndDate, BeginTime, EndTime, Action, Personal, Details, AttendUser, AttendEmployee 
From "CRSPCalendarDailyGroupAcrossDaysItemsInstances" T0 
Where T0.AttendEmployee = :EmployeeID And T0.Recontact = :DisplayDate Or T0.endDate = :DisplayDate Or 
T0.Recontact < :DisplayDate And T0.EndDate > :Displaydate;

Select * From "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD"; -- Order By Recontact, BeginTime

delete from "CRSPCalendarDailyGroupAcrossDaysItemsInstances";
delete from "CRSPCalendarDailyGroupAcrossDaysItemsCalendarMD";

End;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

create procedure CRSP_Calendar_Monthly_ActivityInLine (
	In Activity1 integer,
	In Activity2 integer,
	In Activity3 integer,
	In Activity4 integer,
	In Activity5 integer,
	In Activity6 integer,
	In Activity7 integer,
	In EmployeeAbs1 integer, 
	In EmployeeAbs2 integer, 
	In EmployeeAbs3 integer, 
	In EmployeeAbs4 integer, 
	In EmployeeAbs5 integer,
	In EmployeeAbs6 integer,
	In EmployeeAbs7 integer,
	In EmployeeIDList NClob,
	In FirstDayIn tinyint,
	In FirstWeekDay tinyint,
	In GotoDate NVarchar(30),
	In HldCode Nvarchar(40),
	In ServiceCall1 integer,
	In ServiceCall2 integer,
	In ServiceCall3 integer,
	In ServiceCall4 integer,
	In ServiceCall5 integer,
	In ServiceCall6 integer,
	In ServiceCall7 integer,
	In ServiceCallInstance1 NVarchar(1),
	In ServiceCallInstance2 NVarchar(1),
	In ServiceCallInstance3 NVarchar(1),
	In ServiceCallInstance4 NVarchar(1),
	In ServiceCallInstance5 NVarchar(1),
	In ServiceCallInstance6 NVarchar(1),
	In ServiceCallInstance7 NVarchar(1),
	In ShowEmployeeAbsEntry tinyint,
	In ShowServiceCall tinyint,
	In UserDList NClob)
  
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as

	Diff int;
	DateStartPoint datetime;
	DateEndPoint datetime;
	FirstDay tinyint;
	ShowEmployeeAbsEdu tinyint;
	ShowServiceCalls tinyint;
	UserIDs NCLOB; 
	UserId int;
	EmployeeIDs NCLOB; 
	EmployeeId int;
	sqlStr NCLOB;
	
begin
	
	call _TmSp_ValidateSpParam(EmployeeIDList);
	call _TmSp_ValidateSpParam(UserDList);
	call _TmSp_ValidateSpParam(GotoDate);
	call _TmSp_ValidateSpParam(HldCode);
	call _TmSp_ValidateSpParam(ServiceCallInstance1);
	call _TmSp_ValidateSpParam(ServiceCallInstance2);
	call _TmSp_ValidateSpParam(ServiceCallInstance3);
	call _TmSp_ValidateSpParam(ServiceCallInstance4);
	call _TmSp_ValidateSpParam(ServiceCallInstance5);
	call _TmSp_ValidateSpParam(ServiceCallInstance6);
	call _TmSp_ValidateSpParam(ServiceCallInstance7);
	
	delete from "CRSPCalendarMonthlyActivityInLineCalendar";
	delete from "CRSPCalendarMonthlyActivityInLineEmployeeAbsEdu";
	delete from "CRSPCalendarMonthlyActivityInLineServiceCalls";
	delete from CRSPCalendarMonthlyActivityInLine_users;
	delete from CRSPCalendarMonthlyActivityInLine_employees;
	
	UserIDs := UserDList;
	EmployeeIDs := EmployeeIDList;
	
	if (:ShowEmployeeAbsEntry = 1) then
	   	ShowEmployeeAbsEdu := 1;
	else
    	ShowEmployeeAbsEdu := 0;
    end if;	
    
	if (:ShowServiceCall = 1) then
	    ShowServiceCalls := 1;
	else
	    ShowServiceCalls := 0;
	end if;
	
	sqlStr := 'Insert Into CRSPCalendarMonthlyActivityInLine_users
	Select UserId
	From OUSR
	Where USERID in ' || :UserIDs;
	exec (:sqlStr);

	sqlStr := 'Insert Into CRSPCalendarMonthlyActivityInLine_employees
	Select "empID"
	From OHEM
	Where "empID" in ' || :EmployeeIDs;
	exec (:sqlStr);
	
	FirstDay := :FirstDayIn;

--- get the real start date 
	DateStartPoint := ADD_DAYS(:GotoDate, - DAYOFMONTH(:GotoDate) + 1);
	
	Diff :=  :FirstWeekDay - (WEEKDAY(:DateStartPoint)+2);
	if (:Diff > 0) then
	  Diff := :Diff - 7;
	end if;
	DateStartPoint := ADD_DAYS(:DateStartPoint, :Diff);
	DateEndPoint := ADD_DAYS(:DateStartPoint, 34);
	
	insert into "CRSPCalendarMonthlyActivityInLineCalendar"(clgCode, HldCode, AbsEduSeq, CallID, Details, Action, Personal, AttendUser, AttendEmpl)
	(
		select T0."ClgCode", '', 0, 0, 'A' || '|' || Cast(T0."BeginTime" As Nvarchar(6)) || '|' || Cast(T0."ENDTime" As Nvarchar(6)) || '|' || IFNULL(T0."Details", ' ') As Description, T0."Action", T0."personal", T0."AttendUser", T0."AttendEmpl"
		from OCLG T0 
		where "ClgCode" In (:Activity1, :Activity2, :Activity3, :Activity4, :Activity5, :Activity6, :Activity7)
	);

	insert into "CRSPCalendarMonthlyActivityInLineCalendar"(clgCode, HldCode, AbsEduSeq, CallID, Details)
	(
		select DAYS_BETWEEN("EndDate", "StrDate")*10 + DAYS_BETWEEN("StrDate", :DateStartPoint) - 1, HldCode, 0, 0, 'H' || '|' || IFNull(T0."Rmrks", ' ')
		from HLD1 T0 
		where HldCode = :HldCode And DAYS_BETWEEN("EndDate", "StrDate")*10 + DAYS_BETWEEN("StrDate", :DateStartPoint) - 1 In (:Activity1, :Activity2, :Activity3, :Activity4, :Activity5, :Activity6, :Activity7)
	);

-- Store Employee Absence and Education to the temporary table
	if (:ShowEmployeeAbsEdu = 1) then
		insert into "CRSPCalendarMonthlyActivityInLineEmployeeAbsEdu"(UserId, EmployeeId, StartDate, EndDate, Details)
		(
-- Absence
			select T1."userId", T0."empID", T0."fromDate", T0."toDate", T0."reason"
			from HEM1 T0 
			inner join OHEM T1 On T1."empID" = T0."empID"
			where 
				((T0."fromDate" >= :DateStartPoint And T0."fromDate" <= :DateEndPoint) Or
				 (T0."toDate" >= :DateStartPoint And T0."toDate" <= :DateEndPoint) Or
				 (T0."fromDate" < :DateStartPoint And T0."toDate" > :DateEndPoint )) And
				(T1."userId" in (select uId from CRSPCalendarMonthlyActivityInLine_users) Or T1."empID" in (select empId from CRSPCalendarMonthlyActivityInLine_employees))
			union All
-- Education
			select T1."userId", T0."empID", T0."fromDate", T0."toDate", T2."name" 
			from HEM2 T0 
			inner join OHEM T1 on T1."empID" = T0."empID"
			inner join OHED T2 on T2."edType" = T0."type"
			where 
				((T0."fromDate" >= :DateStartPoint And T0."fromDate" <= :DateEndPoint) Or
				 (T0."toDate" >= :DateStartPoint And T0."toDate" <= :DateEndPoint) Or
				 (T0."fromDate" < :DateStartPoint And T0."toDate" > :DateEndPoint )) And
				(T1."userId" in (select uId from CRSPCalendarMonthlyActivityInLine_users) Or T1."empID" in (select empId from CRSPCalendarMonthlyActivityInLine_employees))
			order by T0."fromDate", T0."toDate" desc
		);
		
		
		insert into "CRSPCalendarMonthlyActivityInLineCalendar"(clgCode, HldCode, AbsEduSeq, CallID, Details, AttendUser, AttendEmpl)
		(
			select 0, '', AbsEduSeq, 0, 'E' || '|' || IFNull(T0.Details, ' ') As Description, T0.UserId, T0.EmployeeId
			from "CRSPCalendarMonthlyActivityInLineEmployeeAbsEdu" T0 
			where AbsEduSeq In (:EmployeeAbs1, :EmployeeAbs2, :EmployeeAbs3, :EmployeeAbs4, :EmployeeAbs5, :EmployeeAbs6, :EmployeeAbs7)
		);

	end if;

-- Store Service calls to the temporary table
	if (:ShowServiceCalls = 1) then

		insert into "CRSPCalendarMonthlyActivityInLineServiceCalls"(CallID, StartDate, EndDate, BeginTime, EndTime, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, Instance)
		(
			select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee", T2."manager", T1."userId", T0."technician", 'A'
			from OSCL T0
			left outer join OHEM T1 On T1."empID" = T0."technician"
			left outer join OQUE T2 On T2."queueID" = T0."Queue"
			where 
				T0."DisplInCal" = 'Y' And
				((T0."StartDate" >= :DateStartPoint And T0."StartDate" <= :DateEndPoint) Or
				 (T0."EndDate" >= :DateStartPoint And T0."EndDate" <= :DateEndPoint) Or
				 (T0."StartDate" < :DateStartPoint And T0."EndDate" > :DateEndPoint )) And
			    (T0."assignee" in (select uId from CRSPCalendarMonthlyActivityInLine_users) Or T2."manager" in (select uId from CRSPCalendarMonthlyActivityInLine_users)) And
			    T0."callID" In (:ServiceCall1, :ServiceCall2, :ServiceCall3, :ServiceCall4, :ServiceCall5, :ServiceCall6, :ServiceCall7)
			union All
			select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee", T2."manager", T1."userId", T0."technician", 'T'
			from OSCL T0
			left outer join OHEM T1 On T1."empID" = T0."technician"
			left outer join OQUE T2 On T2."queueID" = T0."Queue"
			where 
				T0."DisplInCal" = 'Y' And
				((T0."StartDate" >= :DateStartPoint And T0."StartDate" <= :DateEndPoint) Or
				 (T0."EndDate" >= :DateStartPoint And T0."EndDate" <= :DateEndPoint) Or
				 (T0."StartDate" < :DateStartPoint And T0."EndDate" > :DateEndPoint )) And
			    (T1."userId" in (select uId from CRSPCalendarMonthlyActivityInLine_users) Or T0."technician" in (select empId from CRSPCalendarMonthlyActivityInLine_employees)) And
			    T0."callID" In (:ServiceCall1, :ServiceCall2, :ServiceCall3, :ServiceCall4, :ServiceCall5, :ServiceCall6, :ServiceCall7)
			order by T0."StartDate", T0."EndDate" Desc, T0."StartTime", T0."EndTime" desc
		);
		
		
		insert into "CRSPCalendarMonthlyActivityInLineCalendar"(clgCode, HldCode, AbsEduSeq, CallID, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, SCInstance)
		(
			select 0, '', 0, CallID, 'S' || '|' || Cast(T0.BeginTime As Nvarchar(6)) || '|' || Cast(T0.EndTime As Nvarchar(6)) || '|' || IFNull(T0.Details, ' ') As Description, T0.AssigneeUID, T0.QueueManagerUID, T0.TechUID, T0.TechEID, T0.Instance
			from "CRSPCalendarMonthlyActivityInLineServiceCalls" T0 
			where (CallID = :ServiceCall1 And Instance = :ServiceCallInstance1) Or
				  (CallID = :ServiceCall2 And Instance = :ServiceCallInstance2) Or
				  (CallID = :ServiceCall3 And Instance = :ServiceCallInstance3) Or
				  (CallID = :ServiceCall4 And Instance = :ServiceCallInstance4) Or
				  (CallID = :ServiceCall5 And Instance = :ServiceCallInstance5) Or
				  (CallID = :ServiceCall6 And Instance = :ServiceCallInstance6) Or
				  (CallID = :ServiceCall7 And Instance = :ServiceCallInstance7)
		);

	end if;   

select * from "CRSPCalendarMonthlyActivityInLineCalendar";

delete from "CRSPCalendarMonthlyActivityInLineCalendar";
delete from "CRSPCalendarMonthlyActivityInLineEmployeeAbsEdu";
delete from "CRSPCalendarMonthlyActivityInLineServiceCalls";
delete from CRSPCalendarMonthlyActivityInLine_users;
delete from CRSPCalendarMonthlyActivityInLine_employees;

end;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

Create Procedure CRSP_Calendar_Monthly_GrossActivities (
in ActivityTypes int, 
in EmployeeIDList nclob, 
in FirstWeekDay int, 
in HolidaysCode nvarchar(40), 
in GotoDate nvarchar(30),
in RecurringInstancesMonth nclob, 
in ShowEmployeeEdu tinyint, 
in ShowPersonal tinyint, 
in ShowServiceCalls int, 
in UserIDList nclob)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
As
	RdsLmt int;
	ClgCode int;
	AbsEduSeq int;
	CallID int; 
	SCInstance nvarchar(1);
	Diff int;
	Iter int;
	IsClg int;
	IsAbsEdu int;
	IsScl int;
	DateStartPoint TIMESTAMP;
	DateEndPoint TIMESTAMP;
	DateFrom TIMESTAMP;
	HldCode nvarchar(40);
	QryStr nvarchar(400);
	Personal nvarchar(1);
	PhoneCall nvarchar(1);
	Meeting nvarchar(1);
	Other nvarchar(1);
	Task nvarchar(1);
-- recurring scenatio
	RecurringInstances nclob;
	Curr int;
	Prev int;
	Code_Sep int;
	Instance nvarchar(50);
	StartDate TIMESTAMP;
	EndDate TIMESTAMP;
	ActTypes int;
	ShowPhoneCall tinyint;
	ShowMeeting tinyint;
	ShowOther tinyint;
	ShowTask tinyint;
	Counter int;
	recLen int;
	tmpClgCode nvarchar(100);
	tmpRecontact nvarchar(100);
	tmpEndDate nvarchar(100);
	tmpStr NCLOB;
	
-- Cursor for Holidays
cursor CursorHld (DateStartPoint TIMESTAMP, DateEndPoint TIMESTAMP) for select "StrDate", "EndDate" From HLD1 
	Where "HldCode" = :HolidaysCode And  (("StrDate" >= :DateStartPoint And "StrDate" <= :DateEndPoint) Or
	 	("EndDate" >= :DateStartPoint And "EndDate" <= :DateEndPoint) Or ("StrDate" < :DateStartPoint And "EndDate" > :DateEndPoint)) 
	order by "StrDate", "EndDate";
-- Cursor for Employee absence and education
cursor CursorAbsEdu for select "AbsEduSeq", "StartDate", "EndDate" From "CRSPCalMGA_EmployeesAbsEdu"
	order by "StartDate", "EndDate" Desc;
-- Cursor for Service calls
cursor CursorScl for select "CallID", "Instance", "StartDate", "EndDate" From "CRSPCalMGA_ServiceCalls"
	order by "StartDate", "EndDate" Desc, "BeginTime", "EndTime" Desc, "Instance";
-- Cursor for Activities
cursor CursorClg for select "ClgCode", "ReContact", "EndDate" From "CRSPCalMGA_Clg"
	order by "ReContact", "EndDate" Desc, "BeginTime", "EndTime" Desc;	
Begin

	call _TmSp_ValidateSpParam(EmployeeIDList);
	call _TmSp_ValidateSpParam(HolidaysCode);
	call _TmSp_ValidateSpParam(GotoDate);
	call _TmSp_ValidateSpParam(RecurringInstancesMonth);
	call _TmSp_ValidateSpParam(UserIDList);
	
	RdsLmt := 7;
	Iter := 0;
	ActTypes := :ActivityTypes;
	Personal := 'N';
	PhoneCall := '';
	Task := '';
	Meeting := '';
	Other := '';
	Curr := 1;
	Prev := 1;
	RecurringInstances := :RecurringInstancesMonth;
	Counter := 0;
		
	if :ShowPersonal = 1 then
		Personal := 'Y';
	end if;
	
	ShowTask := mod(floor(:ActTypes/1000), 10);
	ShowPhoneCall := mod(floor(:ActTypes/100), 10);
	ShowMeeting := mod(floor(:ActTypes/10), 10);
	ShowOther := mod(:ActTypes, 10); 
	
	if :ShowTask = 1 then
		Task := 'T';
	end if;
	
	if :ShowPhoneCall = 1 then
		PhoneCall := 'C';
	end if;
	
	if :ShowMeeting = 1 then
		Meeting := 'M';
	end if;
	
	if :ShowOther = 1 then
		Other := 'N';
	end if;	
	
	DateStartPoint := ADD_DAYS(TO_DATE(:GotoDate), 1 - dayofmonth(:GotoDate));
	Diff := :FirstWeekDay - (weekday(:DateStartPoint) + 2);
	
	if :Diff > 0 then
		Diff := :Diff - 7;
	end if;
	
	DateStartPoint := Add_days(:DateStartPoint, :Diff);
	DateEndPoint := Add_days(:DateStartPoint, 35 - 1);
	
	delete from "CRSPCalMGA_Res";
	delete from "CRSPCalMGA_Seq";
	delete from "CRSPCalMGA_Clg";
	delete from "CRSPCalMGA_EmployeesAbsEdu";
	delete from "CRSPCalMGA_ServiceCalls";
	
	while :Counter < :RdsLmt + 23 do
		insert into "CRSPCalMGA_Seq" values(:Counter + 1, 0, 0, 0, '', null, null, 0);	
		Counter := :Counter + 1;
	end while;
	
	--- insert activity recurring instances
	recLen := length(:RecurringInstances);
	Counter := 1;
	
	while length(:RecurringInstances) > 0 do
       	curr := locate(:RecurringInstances, ' ');
      
         if :curr > 0 then
			Instance := SUBSTRING(:RecurringInstances, 0, :curr);
		else
			Instance := :RecurringInstances;
		end if;

        tmpClgCode := substr(:Instance, 0, locate(:Instance, ',')-1);
        Instance := substr_after(:Instance, ',');
        tmpRecontact := substr(:Instance, 0, locate(:Instance, ',')-1);
        tmpEndDate := rtrim(substr_after(:Instance, ','), ' ');
                      
        insert into "CRSPCalMGA_Clg" 
		select :tmpClgCode, :tmpRecontact, :tmpEndDate, 0, 0 from DUMMY;
        Counter := :Counter + 1;

        RecurringInstances := substr_after(RecurringInstances, ' ');
    End While;
		
	Update "CRSPCalMGA_Clg" T0 
	Set T0."BeginTime" = (select T1."BeginTime" from OCLG T1 where T0."ClgCode" = T1."ClgCode"),
		T0."EndTime" = (select T1."ENDTime" from OCLG T1 where T0."ClgCode" = T1."ClgCode"); 
		
	--- insert activity normal instances into temporary table
	tmpStr := ' insert into "CRSPCalMGA_Clg"' || 
	' Select "ClgCode", "Recontact", "endDate", "BeginTime", "ENDTime" ' || 
	' From OCLG T0 ' || 
	' Where "personal" IN (''N'', ''' || :Personal || ''') And "Action" IN (''' || :PhoneCall || ''','''|| :Meeting ||''','''|| :Other ||''', '''|| :Task ||''') And ' || 
		' ("AttendUser" IN (' || :UserIDList || ') Or "AttendEmpl" IN ('|| :EmployeeIDList ||')) And "inactive" = ''N'' And "IsRemoved" = ''N''' ||
		' And ((T0."Recontact" >= ''' || :DateStartPoint || ''' And T0."Recontact" <= ''' || :DateEndPoint || ''') Or' ||
	 	' (T0."endDate" >= ''' || :DateStartPoint || ''' And T0."endDate" <= ''' || :DateEndPoint || ''') Or' ||
	 	' (T0."Recontact" < ''' || :DateStartPoint || ''' And T0."endDate" > ''' || :DateEndPoint || ''' ))' ||
		' And "ClgCode" NOT IN (Select "SeriesNum" From OCLG Where "SeriesNum" IS NOT NULL)'  ||
		' And Not Exists (Select 1 From "CRSPCalMGA_Clg" T1 Where T0."ClgCode" = T1."ClgCode"' || 
		' And T0."Recontact" = T1."ReContact" And T0."endDate" = T1."EndDate")';
		
	exec(:tmpStr);

	-- Store Employee Absence and Education to the temporary table
	if :ShowEmployeeEdu = 1 then
		tmpStr := 'insert Into "CRSPCalMGA_EmployeesAbsEdu"("UserId", "EmployeeId", "StartDate", "EndDate", "Details")' ||	
			-- Absences
			' select T1."userId", T0."empID", T0."fromDate", T0."toDate", T0."reason" From HEM1 T0' || 
			' inner Join OHEM T1 On T1."empID" = T0."empID"' ||
			' where ((T0."fromDate" >= ''' || :DateStartPoint || ''' And T0."fromDate" <= ''' || :DateEndPoint || ''') Or' ||
	 		' (T0."toDate" >= ''' || :DateStartPoint || ''' And T0."toDate" <= ''' || :DateEndPoint || ''') Or' ||
	 		' (T0."fromDate" < ''' || :DateStartPoint || ''' And T0."toDate" > ''' || :DateEndPoint || ''' )) And' ||
			' (T1."userId" in ' || :UserIDList || ' Or T1."empID" in ' || EmployeeIDList || ') ' ||
			' Union All ' ||
			-- Education
			' select T1."userId", T0."empID", T0."fromDate", T0."toDate", T2."name"' || 
			' from HEM2 T0 ' || 
			' inner Join OHEM T1 On T1."empID" = T0."empID" ' ||
			' inner Join OHED T2 On T2."edType" = T0."type" ' ||
			' where ((T0."fromDate" >= ''' || :DateStartPoint || ''' And T0."fromDate" <= '''|| :DateEndPoint || ''') Or ' ||
	 		' (T0."toDate" >= ''' || :DateStartPoint || ''' And T0."toDate" <= ''' || :DateEndPoint || ''') Or ' ||
	 		' (T0."fromDate" < ''' || :DateStartPoint || ''' And T0."toDate" > ''' || :DateEndPoint || ''' )) And ' ||
			' (T1."userId" in ' || :UserIDList || ' Or T1."empID" in ' || :EmployeeIDList || ') ' ||
			' Order By T0."fromDate", T0."toDate" Desc';
			
		exec(:tmpStr);
	end if;
	
	-- Store Service calls to the temporary table
	if :ShowServiceCalls = 1 then
		tmpStr := 'insert into "CRSPCalMGA_ServiceCalls"("CallID", "StartDate", "EndDate", "BeginTime", "EndTime",' || 
			' "Details", "AssigneeUID", "QueueManagerUID", "TechUID", "TechEID", "Instance")' ||
			' select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee",' || 
			' T2."manager", T1."userId", T0."technician", ''A''' ||
			' From OSCL T0' ||
			' Left Outer Join OHEM T1 On T1."empID" = T0."technician" ' ||
			' Left Outer Join OQUE T2 On T2."queueID" = T0."Queue" ' ||
			' Where T0."DisplInCal" = ''Y'' And ' ||
			' ((T0."StartDate" >= ''' || :DateStartPoint || ''' And T0."StartDate" <= ''' || :DateEndPoint || ''') Or' ||
	 		' (T0."EndDate" >= ''' || :DateStartPoint || ''' And T0."EndDate" <= ''' || :DateEndPoint || ''') Or' ||
	 		' (T0."StartDate" < ''' || :DateStartPoint || ''' And T0."EndDate" > ''' || :DateEndPoint || ''' )) And' ||
    		' (T0."assignee" in (' || :UserIDList || ') Or T2."manager" in (' || :EmployeeIDList || '))' || 
			' Union All' ||
			' Select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", T0."subject", T0."assignee",' ||
			' T2."manager", T1."userId", T0."technician", ''T''' ||
			' From OSCL T0 ' ||
			' Left Outer Join OHEM T1 On T1."empID" = T0."technician"' ||
			' Left Outer Join OQUE T2 On T2."queueID" = T0."Queue"' ||
			' Where T0."DisplInCal" = ''Y'' And' ||
			' ((T0."StartDate" >= ''' || :DateStartPoint || ''' And T0."StartDate" <= ''' || :DateEndPoint || ''') Or' ||
	 		' (T0."EndDate" >= ''' || :DateStartPoint || ''' And T0."EndDate" <= ''' || :DateEndPoint || ''') Or' ||
	 		' (T0."StartDate" < ''' || :DateStartPoint || ''' And T0."EndDate" > ''' || :DateEndPoint || ''' )) And' ||
    		' (T1."userId" in (' || :UserIDList || ') Or T0."technician" in (' || :EmployeeIDList || '))' || 
			' order By T0."StartDate", T0."EndDate" Desc, T0."StartTime", T0."EndTime" Desc';
			
			exec(:tmpStr);
	end if;    
	
	-- Initialize #TmpRes table (all calendar item rows per day for whole month)
	DateFrom := :DateStartPoint;
	Iter := 0;
	
	while :DateFrom <= :DateEndPoint do
  		insert into "CRSPCalMGA_Res" Select ID, 0, 0, 0, '', :DateFrom, NULL, NULL, CAST(floor(:Iter/7) As Int) from "CRSPCalMGA_Seq";
  		Iter := :Iter + 1;
  		DateFrom := ADD_DAYS(:DateFrom, 1);
	end while;
	
	--- Insert Holidays
	open CursorHld (:DateStartPoint, :DateEndPoint);
	fetch CursorHld into StartDate, EndDate;
	
	while not CursorHld::NOTFOUND do
		
		update "CRSPCalMGA_Res" 
		set "ClgCode" = DAYS_BETWEEN(:EndDate, :StartDate) * 10 + DAYS_BETWEEN(:StartDate, :DateStartPoint) - 1,
			"StartDate" = :StartDate, "EndDate" = :EndDate
		where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "ClgCode" = 0 and "AbsEduSeq" = 0 and "CallID" = 0 
			and "ID" = (select Min("LineID") from 
			(select "ID" As "LineID", COUNT("ID") as "CountIDs", 
  			DAYS_BETWEEN(case when :StartDate > :DateStartPoint then :StartDate else :DateStartPoint end,
  						case when :EndDate <= :DateEndPoint then :EndDate else :DateEndPoint end) + 1 as "ItemLen" 
  		from "CRSPCalMGA_Res" where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "StartDate" is null and "EndDate" is null group by "ID") 
  		"VirtT" where "CountIDs" = "ItemLen");  	
		
		fetch CursorHld into StartDate, EndDate;
	end while;
	
	close CursorHld;

	-- Cursor for Employee absence and education	
	open CursorAbsEdu;
	fetch CursorAbsEdu into AbsEduSeq, StartDate, EndDate;
	
	while not CursorAbsEdu::NOTFOUND do
		
		update "CRSPCalMGA_Res" 
		set "AbsEduSeq" = :AbsEduSeq, "StartDate" = :StartDate, "EndDate" = :EndDate
		where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "ClgCode" = 0 and "AbsEduSeq" = 0 and "CallID" = 0 
			and "ID" = (select Min("LineID") from 
			(select "ID" As "LineID", COUNT("ID") as "CountIDs", 
  			DAYS_BETWEEN(case when :StartDate > :DateStartPoint then :StartDate else :DateStartPoint end,
  						case when :EndDate <= :DateEndPoint then :EndDate else :DateEndPoint end) + 1 as "ItemLen" 
  		from "CRSPCalMGA_Res" where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "StartDate" is null and "EndDate" is null group by "ID") 
  		"VirtT" where "CountIDs" = "ItemLen");
		
		fetch CursorAbsEdu into AbsEduSeq, StartDate, EndDate;
	end while;

	close CursorAbsEdu;

	-- Cursor for Service calls	
	open CursorScl;
	fetch CursorScl into CallID, SCInstance, StartDate, EndDate;
	
	while not CursorScl::NOTFOUND do
	
		update "CRSPCalMGA_Res" 
		set "CallID" = :CallID, "SCInstance" = :SCInstance, "StartDate" = :StartDate, "EndDate" = :EndDate
		where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "ClgCode" = 0 and "AbsEduSeq" = 0 and "CallID" = 0 
			and "ID" = (select Min("LineID") from 
			(select "ID" As "LineID", COUNT("ID") as "CountIDs", 
  			DAYS_BETWEEN(case when :StartDate > :DateStartPoint then :StartDate else :DateStartPoint end,
  						case when :EndDate <= :DateEndPoint then :EndDate else :DateEndPoint end) + 1 as "ItemLen" 
  		from "CRSPCalMGA_Res" where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "StartDate" is null and "EndDate" is null group by "ID") 
  		"VirtT" where "CountIDs" = "ItemLen");
		
		fetch CursorScl into CallID, SCInstance, StartDate, EndDate;
	end while;

	close CursorScl;

	-- Cursor for Activities	
	open CursorClg;
	fetch CursorClg into ClgCode, StartDate, EndDate;
	
	while not CursorClg::NOTFOUND do
	
		update "CRSPCalMGA_Res" 
		set "ClgCode" = :ClgCode, "StartDate" = :StartDate, "EndDate" = :EndDate
		where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "ClgCode" = 0 and "AbsEduSeq" = 0 and "CallID" = 0 
			and "ID" = (select Min("LineID") from 
			(select "ID" As "LineID", COUNT("ID") as "CountIDs", 
  			DAYS_BETWEEN(case when :StartDate > :DateStartPoint then :StartDate else :DateStartPoint end,
  						case when :EndDate <= :DateEndPoint then :EndDate else :DateEndPoint end) + 1 as "ItemLen" 
  		from "CRSPCalMGA_Res" where "CalendarDay" >= :StartDate and "CalendarDay" <= :EndDate and "StartDate" is null and "EndDate" is null group by "ID") 
  		"VirtT" where "CountIDs" = "ItemLen");
		
		fetch CursorClg into ClgCode, StartDate, EndDate;
	end while;

	close CursorClg;
	
	Select MAX("ClgCode") - MIN("ClgCode"), MAX("AbsEduSeq") - MIN("AbsEduSeq"), MAX("CallID") - MIN(CallID)
		into IsClg, IsAbsEdu, IsScl from "CRSPCalMGA_Res";
		
	if :IsClg = 0 And :IsAbsEdu = 0 And :IsScl = 0 then
   		update "CRSPCalMGA_Res" Set "ID" = DAYOFMONTH("CalendarDay");
  		select * From "CRSPCalMGA_Res";
	
	else
  		select * From "CRSPCalMGA_Res" Where "ID" < :RdsLmt
  		union all
  		select :RdsLmt, MAX("ClgCode"), MAX("AbsEduSeq"), MAX("CallID"),
		"SCInstance", "CalendarDay", null, null, "WeekNum" From "CRSPCalMGA_Res" 
  		where "ID" >= :RdsLmt group by "WeekNum", "CalendarDay", "SCInstance";
	end if;
	
	delete from "CRSPCalMGA_Res";
	delete from "CRSPCalMGA_Seq";
	delete from "CRSPCalMGA_Clg";
	delete from "CRSPCalMGA_EmployeesAbsEdu";
	delete from "CRSPCalMGA_ServiceCalls";
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE CRSP_Customer_Open_Item_List
(
in DateTypeIn nvarchar(1),
in DateValueIn datetime,
in ReconDateValueIn datetime,
in CustomerIdsIn nclob,
in IncludeDPMRequestIn nvarchar(1)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
execSQL 			nclob;
dateType 			nvarchar(1);
dateValue 			datetime;
reconDateValue 		datetime;
acctList  			nclob;
customerIds 		nclob;
includeDPMRequest 	nvarchar(1);
tableName			nvarchar(132);
dateField			nvarchar(16);
BEGIN

call _TmSp_ValidateSpParam (:DateTypeIn);
call _TmSp_ValidateSpParam (:IncludeDPMRequestIn);

dateType := :DateTypeIn;
dateValue := :DateValueIn;
reconDateValue := :ReconDateValueIn;
customerIds := :CustomerIdsIn;
includeDPMRequest := :IncludeDPMRequestIn;

If :IncludeDPMRequestIn = '1' Then
	includeDPMRequest := 'Y';
END IF;

delete from "CRSP_Customer_Open_Item_List_TmpResult";
delete from "Customer_Open_Item_List_TempOpenDocumentViewByPosting";
delete from "Customer_Open_Item_List_TempOpenDocumentViewByDocDate";
delete from "Customer_Open_Item_List_TempJournalSource";
delete from "Customer_Open_Item_List_TempInstallmentsDocument";

execSQL:= 'insert into "Customer_Open_Item_List_TempInstallmentsDocument" 
(SELECT T0."DocEntry", T0."InstlmntID", 
T0."ObjType", T1."CardCode", T1."CardName", T1."NumAtCard", T1."SlpCode", 
T0."InsTotal", T0."InsTotalFC", T0."InsTotalSy", T1."BlockDunn", T0."DunnLevel", T1."Installmnt", T0."DunDate",
N''Y'' AS "IsSales", N''Y'' AS "IsDunnable" FROM  INV6 T0  INNER  JOIN OINV T1  
ON  T1."DocEntry" = T0."DocEntry" where T1."CardCode" in ' || :customerIds || ' 
Union All
SELECT T0."DocEntry", T0."InstlmntID", 
T0."ObjType", T1."CardCode", T1."CardName", T1."NumAtCard", T1."SlpCode", 
T0."InsTotal", T0."InsTotalFC", T0."InsTotalSy", T1."BlockDunn", T0."DunnLevel",  T1."Installmnt", T0."DunDate",
N''Y'' AS "IsSales", N''N'' AS "IsDunnable" FROM  RIN6 T0  INNER  JOIN ORIN T1  
ON  T1."DocEntry" = T0."DocEntry" where T1."CardCode" in ' || :customerIds || '
Union All
SELECT T0."DocEntry", T0."InstlmntID", 
T0."ObjType", T1."CardCode", T1."CardName", T1."NumAtCard", T1."SlpCode", 
T0."InsTotal", T0."InsTotalFC", T0."InsTotalSy", T1."BlockDunn", T0."DunnLevel",  T1."Installmnt", T0."DunDate",
N''Y'' AS "IsSales", N''Y'' AS "IsDunnable" FROM  DPI6 T0  INNER  JOIN ODPI T1  
ON  T1."DocEntry" = T0."DocEntry" where T1."CardCode" in ' || :customerIds || ')'
;

exec (:execSQL);

insert into  "Customer_Open_Item_List_TempJournalSource" (
SELECT T0."DocEntry", T0."InstlmntID", T0."Installmnt", T0."DunDate",T0."ObjType", 
T0."CardCode", T0."CardName", T0."NumAtCard", T0."SlpCode", 
T0."InsTotal" as "InsTotal", T0."InsTotalFC" as "InsTotalFC", T0."InsTotalSy" as "InsTotalSy", T0."BlockDunn", 
T0."DunnLevel", N'I' AS "TransType", T0."IsSales", T0."IsDunnable", 
0 AS "BoeNum", N'' AS "BoeStatus" FROM  "Customer_Open_Item_List_TempInstallmentsDocument"  T0  
UNION ALL SELECT T0."DocEntry", 0 AS "InstlmntID", 0 as "Installmnt", NULL as "DunDate",T0."ObjType", T0."CardCode", 
T0."CardName", N'' AS "NumAtCard", -1 AS "SlpCode", T0."DocTotal" as InsTotal, T0."DocTotalFC" as "InsTotalFC", 
T0."DocTotalSy" as "InsTotalSy", N'Y' AS "BlockDunn", 0 AS "DunnLevel", N'P' AS "SrcType", 
N'' AS "IsSales", N'N' AS "IsDunnable", 0 AS "BoeNum", N'' AS "BoeStatus" FROM  ORCT T0  
 UNION ALL SELECT T0."DeposId", 0 AS "InstlmntID", 0 as "Installmnt", NULL as "DunDate",
T0."ObjType", N'' AS "CardCode", N'' AS "CardName", N'' AS "NumAtCard", -1 AS "SlpCode", 
T0."LocTotal" as "InsTotal" , T0."FcTotal" as "InsTotalFC" , T0."SysTotal" as "InsTotalSy", N'Y' AS "BlockDunn", 0 AS "DunnLevel", 
N'D' AS "SrcType", N'' AS "IsSales", N'N' AS "IsDunnable", T1."BoeNum", T1."BoeStatus" 
FROM  ODPS T0   LEFT OUTER  JOIN OBOE T1  ON  T1."BoeKey" = T0."DeposId" 
); 

if :dateType = '1' then
	execSQL:= ' 
	INSERT INTO "Customer_Open_Item_List_TempOpenDocumentViewByPosting" (
	SELECT Max(T5."DocEntry") as DocEntry,T0."TransId", T0."Line_ID", Max("InstlmntID") as InstlmntID, MAX(T0."Account") as Account, MAX(T0."ShortName") as ShortName, MAX(T4."Address") as Address, MAX(T4."Phone1") as Phone, MAX(T0."TransType") as TransType, MAX(T0."CreatedBy") as CreatedBy, MAX(T0."BaseRef") as BaseRef, MAX(T0."SourceLine") as SourceLine, MAX(T0."Debit") as Debit, Max(T0."Credit") as Credit, Max(T0."FCDebit") as FCDebit, Max(T0."FCCredit") as FCCredit,Max(T0."DebCred") as DebCred,
	MAX(T0."RefDate") as RefDate , MAX(T0."DueDate") as DueDate, MAX(T0."TaxDate") as TaxDate, (MAX(T0."BalDueCred") + SUM(T1."ReconSum")) as BalDueCred, (MAX(T0."BalFcCred") + SUM(T1."ReconSumFC")) as BalFCCred,( MAX(T0."BalScCred") + 
	SUM(T1."ReconSumSC")) as BalScCred, MAX(T0."LineMemo") as LineMemo, MAX(T0."Indicator") as Indicator, MAX(T4."CardName") as CardName, MAX(T5."CardCode") as CardCode, MAX(T5."CardName") as CardName1, 
	MAX(T4."Balance") as Balance, (SUM(T0."Debit") + SUM(T0."Credit")) as DocTotal, SUM(T0."FCDebit") + SUM(T0."FCCredit") as DocTotalFC, SUM(T0."SYSDeb") + 
	SUM(T0."SYSCred") as DocTotalSC, MAX(T5."DunnLevel") as DunnLevel , MAX(T5."IsSales") as IsSales, MAX(T4."Currency") as BPCurrency, MAX(T0."FCCurrency") as JEFCCurrency , 
	Max(T5."Installmnt") as Installmnt, Max(T5."DunDate") as DunDate, Max(T5."InsTotal") as InsTotal, Max(T5."InsTotalFC") as InsTotalFC, Max(T5."InsTotalSy") as InsTotalSy
	FROM  JDT1 T0  INNER  JOIN ITR1 T1  ON  T1."TransId" = T0."TransId"  AND  T1."TransRowId" = T0."Line_ID"   INNER  JOIN 
	OITR T2  ON  T2."ReconNum" = T1."ReconNum"   INNER  JOIN OJDT T3  ON  T3."TransId" = T0."TransId"   INNER  JOIN OCRD T4  ON  T4."CardCode" = T0."ShortName"    
	LEFT OUTER  JOIN "Customer_Open_Item_List_TempJournalSource" T5  ON  T5."ObjType" = T0."TransType"  AND  T5."DocEntry" = T0."CreatedBy"  AND  (T5."TransType" <> N''I''  OR  (T5."TransType" = N''I'' 
	AND  T5."InstlmntID" = T0."SourceLine" ))  WHERE T0."RefDate" <= ''' || :dateValue || ''' AND  T4."CardType" = ''C''  AND  T4."Balance" <>0  AND  T4."CardCode"  in ' || :customerIds || '  AND  T2."ReconDate" > ''' || :reconDateValue || ''' AND  T1."IsCredit" = ''C''  GROUP BY T0."TransId", T0."Line_ID" HAVING MAX(T0."BalFcCred") <>- 
	SUM(T1."ReconSumFC")  OR  MAX(T0."BalDueCred") <>- SUM(T1."ReconSum")  
	Union All
	SELECT Max(T5."DocEntry") as DocEntry,T0."TransId", T0."Line_ID", Max("InstlmntID") as InstlmntID, MAX(T0."Account") as Account, MAX(T0."ShortName") as ShortName, MAX(T4."Address") as Address, MAX(T4."Phone1") as Phone,MAX(T0."TransType") as TransType, MAX(T0."CreatedBy") as CreatedBy, MAX(T0."BaseRef") as BaseRef, MAX(T0."SourceLine") as SourceLine, MAX(T0."Debit") as Debit, Max(T0."Credit") as Credit, Max(T0."FCDebit") as FCDebit, Max(T0."FCCredit") as FCCredit,Max(T0."DebCred") as DebCred,
	MAX(T0."RefDate") as RefDate, MAX(T0."DueDate") as DueDate, MAX(T0."TaxDate") as TaxDate,  (- MAX(T0."BalDueDeb") - SUM(T1."ReconSum")) as BalDueCred,  (- MAX(T0."BalFcDeb") - SUM(T1."ReconSumFC")) as BalFCCred,  (- MAX(T0."BalScDeb") - SUM(T1."ReconSumSC")) as BalScCred, MAX(T0."LineMemo") as LineMeno, MAX(T0."Indicator") as Indicator, MAX(T4."CardName") as CardName, MAX(T5."CardCode") as CardCode, MAX(T5."CardName") as CardName1, MAX(T4."Balance") as Balance,(SUM(T0."Debit") + 
	SUM(T0."Credit")) as DocTotal, (SUM(T0."FCDebit") + SUM(T0."FCCredit")) as DocTotalFC, (SUM(T0."SYSDeb") + SUM(T0."SYSCred")) as  DocTotalSC, MAX(T5."DunnLevel") as DunnLevel,
	MAX(T5."IsSales") as IsSales, MAX(T4."Currency") as BPCurrency, MAX(T0."FCCurrency") as JEFCCurrency  ,Max(T5."Installmnt") as Installmnt, Max(T5."DunDate") as DunDate
	, Max(T5."InsTotal") as InsTotal, Max(T5."InsTotalFC") as InsTotalFC, Max(T5."InsTotalSy") as InsTotalSy
	FROM  JDT1 T0  INNER  JOIN ITR1 T1  ON  
	T1."TransId" = T0."TransId"  AND  T1."TransRowId" = T0."Line_ID"   INNER  JOIN OITR T2  ON  T2."ReconNum" = T1."ReconNum"  INNER  JOIN OJDT T3  ON  T3."TransId" = 
	T0."TransId"   INNER  JOIN OCRD T4  ON  T4."CardCode" = T0."ShortName"    LEFT OUTER  JOIN "Customer_Open_Item_List_TempJournalSource" T5  ON  T5."ObjType" = T0."TransType"  AND  
	T5."DocEntry" = T0."CreatedBy"  AND  (T5."TransType" <> N''I''  OR  (T5."TransType" = N''I''  AND  T5."InstlmntID" = T0."SourceLine" ))  WHERE T0."RefDate" <= 
	''' || :dateValue || ''' AND  T4."CardType" = ''C''  AND  T4."Balance" <>0  AND  T4."CardCode" in ' ||  customerIds || '  AND  T2."ReconDate" > ''' || :reconDateValue || '''  AND  T1."IsCredit" = 
	''D''   GROUP BY T0."TransId", T0."Line_ID" HAVING MAX(T0."BalFcDeb") <>- SUM(T1."ReconSumFC")  OR  MAX(T0."BalDueDeb") <>- SUM(T1."ReconSum")   
	UNION ALL 
	SELECT (Case IfNull(Max(T3."DocEntry"), -1) when -1  Then T0."TransId" Else Max(T3."DocEntry") end )  as DocEntry, T0."TransId", T0."Line_ID", Max("InstlmntID") as InstlmntID, MAX(T0."Account") as Account, MAX(T0."ShortName") as ShortName, MAX(T2."Address") as Address, MAX(T2."Phone1") as Phone,MAX(T0."TransType") as TransType, MAX(T0."CreatedBy") as CreatedBy, MAX(T0."BaseRef") as BaseRef, MAX(T0."SourceLine") as SourceLine,MAX(T0."Debit") as Debit, Max(T0."Credit") as Credit, Max(T0."FCDebit") as FCDebit, Max(T0."FCCredit") as FCCredit,Max(T0."DebCred") as DebCred,
	MAX(T0."RefDate")  as RefDate, MAX(T0."DueDate") as DueDate, MAX(T0."TaxDate") as TaxDate, (MAX(T0."BalDueCred") - MAX(T0."BalDueDeb")) as BalDueCred, (MAX(T0."BalFcCred") - MAX(T0."BalFcDeb")) as BalFCCred, (MAX(T0."BalScCred") - MAX(T0."BalScDeb")) as BalSCCred, MAX(T0."LineMemo") as LineMemo ,MAX(T0."Indicator") as Indicator, MAX(T2."CardName") as CardName, MAX(T3."CardCode") as CardCode, MAX(T3."CardName") as CardName1, MAX(T2."Balance") as Balance, 
	(SUM(T0."Debit") + SUM(T0."Credit")) as DocTotal,( SUM(T0."FCDebit") + SUM(T0."FCCredit")) as DocToalFC,( SUM(T0."SYSDeb") + SUM(T0."SYSCred")) as DocTotalSC, 
	MAX(T3."DunnLevel") as DunnLevel, MAX(T3."IsSales") as IsSales, MAX(T2."Currency") as BPCurrency, MAX(T0."FCCurrency") as JEFCCurrency,
	Max(T3."Installmnt") as Installmnt, Max(T3."DunDate") as DunDate, Max(T3."InsTotal") as InsTotal, Max(T3."InsTotalFC") as InsTotalFC, Max(T3."InsTotalSy") as InsTotalSy
	FROM  JDT1 T0  INNER  JOIN OJDT T1  ON  T1."TransId" = T0."TransId"  INNER  JOIN OCRD T2  ON  T2."CardCode" = T0."ShortName"    LEFT 
	OUTER  JOIN  "Customer_Open_Item_List_TempJournalSource" T3  ON  T3."ObjType" = T0."TransType"  AND  T3."DocEntry" = T0."CreatedBy"  AND  (T3."TransType" <> N''I''  OR  (T3."TransType" = N''I''  AND  
	T3."InstlmntID" = T0."SourceLine" ))  WHERE  T0."RefDate" <= ''' || :dateValue || ''' AND  T2."CardType" =''C''  AND  T2."Balance" <> 0  AND  T2."CardCode" in ' || :customerIds || ' AND  (T0."BalDueCred" <> T0."BalDueDeb"  OR  T0."BalFcCred" <> T0."BalFcDeb" ) AND   NOT EXISTS (SELECT U0."TransId", U0."TransRowId" FROM  
	ITR1 U0  INNER  JOIN OITR U1  ON  U1."ReconNum" = U0."ReconNum"   WHERE T0."TransId" = U0."TransId"  AND  T0."Line_ID" = U0."TransRowId"  AND  U1."ReconDate" > 
	''' || :reconDateValue || ''')   GROUP BY T0."TransId", T0."Line_ID")';
	--insert into debug values (:execSQL);
	exec (:execSQL);
Else 
	execSQL:= '
	Insert into "Customer_Open_Item_List_TempOpenDocumentViewByDocDate" (
	SELECT Max(T5."DocEntry") as DocEntry, T0."TransId", T0."Line_ID", Max("InstlmntID") as InstlmntID, MAX(T0."Account") as Account, MAX(T0."ShortName") as ShortName, MAX(T4."Address") as Address, MAX(T4."Phone1") as Phone, MAX(T0."TransType") as TransType, MAX(T0."CreatedBy") as CreatedBy, MAX(T0."BaseRef") as BaseRef, MAX(T0."SourceLine") as SourceLine, MAX(T0."Debit") as Debit, Max(T0."Credit") as Credit, Max(T0."FCDebit") as FCDebit, Max(T0."FCCredit") as FCCredit,Max(T0."DebCred") as DebCred,
	MAX(T0."RefDate") as RefDate , MAX(T0."DueDate") as DueDate, MAX(T0."TaxDate") as TaxDate, (MAX(T0."BalDueCred") + SUM(T1."ReconSum")) as BalDueCred, (MAX(T0."BalFcCred") + SUM(T1."ReconSumFC")) as BalFCCred,( MAX(T0."BalScCred") + 
	SUM(T1."ReconSumSC")) as BalScCred, MAX(T0."LineMemo") as LineMemo, MAX(T0."Indicator") as Indicator, MAX(T4."CardName") as CardName, MAX(T5."CardCode") as CardCode, MAX(T5."CardName") as CardName1, 
	MAX(T4."Balance") as Balance, (SUM(T0."Debit") + SUM(T0."Credit")) as DocTotal, SUM(T0."FCDebit") + SUM(T0."FCCredit") as DocTotalFC, SUM(T0."SYSDeb") + 
	SUM(T0."SYSCred") as DocTotalSC, MAX(T5."DunnLevel") as DunnLevel , MAX(T5."IsSales") as IsSales, MAX(T4."Currency") as BPCurrency, MAX(T0."FCCurrency") as JEFCCurrency , 
	Max(T5."Installmnt") as Installmnt, Max(T5."DunDate") as DunDate, Max(T5."InsTotal") as InsTotal, Max(T5."InsTotalFC") as InsTotalFC, Max(T5."InsTotalSy") as InsTotalSy
	FROM  JDT1 T0  INNER  JOIN ITR1 T1  ON  T1."TransId" = T0."TransId"  AND  T1."TransRowId" = T0."Line_ID"   INNER  JOIN 
	OITR T2  ON  T2."ReconNum" = T1."ReconNum"   INNER  JOIN OJDT T3  ON  T3."TransId" = T0."TransId"   INNER  JOIN OCRD T4  ON  T4."CardCode" = T0."ShortName"  
	LEFT OUTER  JOIN "Customer_Open_Item_List_TempJournalSource" T5  ON  T5."ObjType" = T0."TransType"  AND  T5."DocEntry" = T0."CreatedBy"  AND  (T5."TransType" <> N''I''  OR  (T5."TransType" = N''I'' 
	AND  T5."InstlmntID" = T0."SourceLine" ))  WHERE T0."TaxDate" <=  ''' || :dateValue || '''  AND  T4."CardType" = ''C''  AND  T4."Balance" <>0  AND  T4."CardCode"  in ' || :customerIds || '  AND  T2."ReconDate" > ''' || :reconDateValue || ''' AND  T1."IsCredit" = ''C''  GROUP BY T0."TransId", T0."Line_ID" HAVING MAX(T0."BalFcCred") <>-	SUM(T1."ReconSumFC")  OR  MAX(T0."BalDueCred") <>- SUM(T1."ReconSum")  
	Union All
	SELECT Max(T5."DocEntry") as DocEntry, T0."TransId", T0."Line_ID", Max("InstlmntID") as InstlmntID, MAX(T0."Account") as Account, MAX(T0."ShortName") as ShortName, MAX(T4."Address") as Address, MAX(T4."Phone1") as Phone,MAX(T0."TransType") as TransType, MAX(T0."CreatedBy") as CreatedBy, MAX(T0."BaseRef") as BaseRef, MAX(T0."SourceLine") as SourceLine, MAX(T0."Debit") as Debit, Max(T0."Credit") as Credit, Max(T0."FCDebit") as FCDebit, Max(T0."FCCredit") as FCCredit,Max(T0."DebCred") as DebCred,
	MAX(T0."RefDate") as RefDate, MAX(T0."DueDate") as DueDate, MAX(T0."TaxDate") as TaxDate,  (- MAX(T0."BalDueDeb") - SUM(T1."ReconSum")) as BalDueCred,  (- MAX(T0."BalFcDeb") - SUM(T1."ReconSumFC")) as BalFCCred,  (- MAX(T0."BalScDeb") - SUM(T1."ReconSumSC")) as BalScCred, MAX(T0."LineMemo") as LineMeno, MAX(T0."Indicator") as Indicator, MAX(T4."CardName") as CardName, MAX(T5."CardCode") as CardCode, MAX(T5."CardName") as CardName1, MAX(T4."Balance") as Balance,(SUM(T0."Debit") + 
	SUM(T0."Credit")) as DocTotal, (SUM(T0."FCDebit") + SUM(T0."FCCredit")) as DocTotalFC, (SUM(T0."SYSDeb") + SUM(T0."SYSCred")) as  DocTotalSC, MAX(T5."DunnLevel") as DunnLevel,
	MAX(T5."IsSales") as IsSales, MAX(T4."Currency") as BPCurrency, MAX(T0."FCCurrency") as JEFCCurrency, Max(T5."Installmnt") as Installmnt, Max(T5."DunDate") as DunDate
	, Max(T5."InsTotal") as InsTotal, Max(T5."InsTotalFC") as InsTotalFC, Max(T5."InsTotalSy") as InsTotalSy
	FROM  JDT1 T0  INNER  JOIN ITR1 T1  ON  
	T1."TransId" = T0."TransId"  AND  T1."TransRowId" = T0."Line_ID"   INNER  JOIN OITR T2  ON  T2."ReconNum" = T1."ReconNum"  INNER  JOIN OJDT T3  ON  T3."TransId" = 
	T0."TransId"   INNER  JOIN OCRD T4  ON  T4."CardCode" = T0."ShortName"    LEFT OUTER  JOIN "Customer_Open_Item_List_TempJournalSource" T5  ON  T5."ObjType" = T0."TransType"  AND  
	T5."DocEntry" = T0."CreatedBy"  AND  (T5."TransType" <> N''I''  OR  (T5."TransType" = N''I''  AND  T5."InstlmntID" = T0."SourceLine" ))  WHERE T0."TaxDate" <= ''' || :dateValue || ''' 
	AND  T4."CardType" = ''C''  AND  T4."Balance" <>0  AND  T4."CardCode" in ' || :customerIds || ' AND  T2."ReconDate" > ''' || :reconDateValue || ''' AND  T1."IsCredit" = ''D''   GROUP BY T0."TransId", T0."Line_ID" HAVING MAX(T0."BalFcDeb") <>- SUM(T1."ReconSumFC")  OR  MAX(T0."BalDueDeb") <>- SUM(T1."ReconSum")   
	UNION ALL 
	SELECT (Case IfNull(Max(T3."DocEntry"), -1) when -1  Then T0."TransId" Else Max(T3."DocEntry") end )  as "DocEntry", T0."TransId", T0."Line_ID", Max("InstlmntID") as "InstlmntID", MAX(T0."Account") as Account, MAX(T0."ShortName") as ShortName, MAX(T2."Address") as Address, MAX(T2."Phone1") as Phone,MAX(T0."TransType") as "TransType", MAX(T0."CreatedBy") as "CreatedBy", MAX(T0."BaseRef") as "BaseRef", MAX(T0."SourceLine") as "SourceLine" ,MAX(T0."Debit") as "Debit", Max(T0."Credit") as "Credit", Max(T0."FCDebit") as "FCDebit", Max(T0."FCCredit") as "FCCredit",Max(T0."DebCred") as "DebCred",
	MAX(T0."RefDate")  as "RefDate", MAX(T0."DueDate") as "DueDate", MAX(T0."TaxDate") as "TaxDate", (MAX(T0."BalDueCred") - MAX(T0."BalDueDeb")) as "BalDueCred", (MAX(T0."BalFcCred") - MAX(T0."BalFcDeb")) as "BalFCCred", (MAX(T0."BalScCred") - MAX(T0."BalScDeb")) as "BalSCCred", MAX(T0."LineMemo") as "LineMemo" ,MAX(T0."Indicator") as "Indicator", MAX(T2."CardName") as "CardName", MAX(T3."CardCode") as "CardCode", MAX(T3."CardName") as "CardName1", MAX(T2."Balance") as "Balance", 
	(SUM(T0."Debit") + SUM(T0."Credit")) as "DocTotal",( SUM(T0."FCDebit") + SUM(T0."FCCredit")) as "DocTotalFC",( SUM(T0."SYSDeb") + SUM(T0."SYSCred")) as "DocTotalSC", 
	MAX(T3."DunnLevel") as "DunnLevel", MAX(T3."IsSales") as "IsSales", MAX(T2."Currency") as "BPCurrency", MAX(T0."FCCurrency") as "JEFCCurrency",
	Max(T3."Installmnt") as "Installmnt", Max(T3."DunDate") as "DunDate", Max(T3."InsTotal") as "InsTotal", Max(T3."InsTotalFC") as "InsTotalFC", Max(T3."InsTotalSy") as "InsTotalSy"
	FROM JDT1 T0 INNER JOIN OJDT T1  ON  T1."TransId" = T0."TransId"   INNER  JOIN OCRD T2  ON  T2."CardCode" = T0."ShortName"    LEFT 
	OUTER  JOIN  "Customer_Open_Item_List_TempJournalSource" T3  ON  T3."ObjType" = T0."TransType"  AND  T3."DocEntry" = T0."CreatedBy"  AND  (T3."TransType" <> N''I''  OR  (T3."TransType" = N''I''  AND  
	T3."InstlmntID" = T0."SourceLine" ))  WHERE T0."TaxDate" <= ''' || :dateValue || ''' AND  T2."CardType" = ''C''  AND  T2."Balance" <> 0  AND  T2."CardCode" in ' || :customerIds || ' AND  (T0."BalDueCred" <> T0."BalDueDeb"  OR  T0."BalFcCred" <> T0."BalFcDeb" ) AND   NOT EXISTS (SELECT U0."TransId", U0."TransRowId" FROM  
	ITR1 U0  INNER  JOIN OITR U1  ON  U1."ReconNum" = U0."ReconNum"   WHERE T0."TransId" = U0."TransId"  AND  T0."Line_ID" = U0."TransRowId"  AND  U1."ReconDate" > 
	''' || :reconDateValue || ''')   GROUP BY T0."TransId", T0."Line_ID"
	)';
	--insert into debug values (:execSQL);
	exec (:execSQL);
End If;
	
If :dateType = '1' Then
	tableName := '"Customer_Open_Item_List_TempOpenDocumentViewByPosting"';
Else
	tableName := '"Customer_Open_Item_List_TempOpenDocumentViewByDocDate"';
End If;

execSQL := '	
	insert into "CRSP_Customer_Open_Item_List_TmpResult" Select
	T0."Address", T0."BalDueCred", T0."BalFCCred", T0."BaseRef", T0."BPCurrency", 
	T0."CardCode", T0."CardName", T0."Credit", T0."Debit", T0."DebCred", T0."DocEntry",
	T0."DunDate", T0."DueDate", T0."DunnLevel",T0."FCCredit", T0."FCDebit", 
	T0."Installmnt", T0."InstlmntID", T0."InsTotal", T0."InsTotalFC", T0."InsTotalSy",T1."IsCredit", 
	T0."FCCurrency",T0."Line_ID", T0."LineMemo",T0."Phone",T4."ReconBaseRef",T0."RefDate",
	T4."ReconTransId",T4."ReconRefDate",T4."ReconDocumentDate",T5."ReconJrnlMemo",T5."ReconDebCred", 
	T5."ReconDebit", T5."ReconCredit",T5."ReconDebitFc", T5."ReconCreditFC" , T5."ReconJEFCCurrency",
	T2."ReconDate", T2."ReconCurr", T0."ShortName", T1."SrcObjAbs", T1."SrcObjTyp", T0."TaxDate", T0."TransType",
	CURRENT_DATE as ServerDate,T3."Name" as IndicatorName , (Case IFNULL("ReconDate", ''19700101'') When ''19700101'' Then 0 Else "ReconSum" end ) as realReconSum ,
	(Case IFNull("ReconDate", ''19700101'') When ''19700101'' Then 0 Else "ReconSumFC" end ) as realReconSumFC, ''N'' as IsDPMRequest from ' || :tableName || ' T0 
	Left Outer  Join ITR1 T1 On T1."ReconNum" in (Select U0."ReconNum" from ITR1 U0 where U0."TransId" = T0."TransId" and U0."TransRowId" = T0."Line_ID") and (T1."TransId"<> T0."TransId" Or T1."TransRowId"<> T0."Line_ID")
	Left Outer Join OITR T2 On T2."ReconNum" = T1."ReconNum" and  T2."ReconDate" <= ''' || :reconDateValue || '''
	Left Outer Join (Select "TransId" as "ReconTransId", "BaseRef" as "ReconBaseRef", "RefDate" as "ReconRefDate", "TaxDate" as "ReconDocumentDate"  From OJDT) T4 On T4."ReconTransId" = T1."TransId" 
	Left Outer Join (Select "TransId" as "ReconTransId1", "Line_ID" as "ReconJELine_Id", "LineMemo" as "ReconJrnlMemo", "DebCred" as "ReconDebCred", "Debit" as "ReconDebit", "Credit" as "ReconCredit", "FCDebit" as "ReconDebitFc", "FCCredit" as "ReconCreditFC" , "FCCurrency" as "ReconJEFCCurrency"  From JDT1) T5 on T5."ReconTransId1" = T4."ReconTransId" and T5."ReconJELine_Id" = T1."TransRowId"
	Left Outer Join  OIDC  T3 On T3."Code" = T0."Indicator"';

if :includeDPMRequest = 'Y' Then
	 If :dateType = '1' Then
	 	dateField := '"DocDate"';
	 Else 
	 	dateField := '"TaxDate"';
	 End IF;

	 execSQL := :execSQL || ' Union All ';
 	 execSQL := :execSQL || ' Select T4."Address",0 as BalDueCred,0 as BalFCCred, T0."DocNum" as BaseRef, T4."Currency" as BPCurrency, 
	T4."CardCode", T4."CardName", 0 as Credit, 0 as Debit, '''' as DebCred, T0."DocEntry",
	T3."DunDate", T0."DocDueDate" as DueDate, T3."DunnLevel", 0 as FCCredit, 0 as FCDebit, 
	-1 as Installmnt, -1 as InstlmntID, T3."InsTotal", T3."InsTotalFC", T3."InsTotalSy",'''' as IsCredit, 
	'''' as JEFCCurrency, -1 as Line_ID, T0."JrnlMemo",T4."Phone1",'''' as ReconBaseRef,T0."DocDate" as RefDate,
	-1 as ReconTransID, NULL as ReconRefDate,NULL as ReconDocumentDate,NULL as ReconJrnlMemo, '''' as ReconDebCred, 
	0 as ReconDebit, 0 as ReconCredit, 0 as ReconDebitFc, 0 as ReconCreditFC , T0."DocCur" as ReconJEFCCurrency,
	NULL as ReconDate, T0."CurSource" as ReconCurr, T4."CardCode" as ShortName, T0."DocEntry" as SrcObjAbs, ''203'' as SrcObjTyp, T0."TaxDate", ''203'' as TransType,
	CURRENT_DATE as ServerDate,T5."Name" as IndicatorName ,0 as realReconSum , 0 as realRconSumFC, ''Y'' as IsDPMRequest
	From ODPI T0 Inner Join DPI6 T3 On T0."CreateTran" =''N'' and T0."DocEntry" = T3."DocEntry" and T0."DocEntry" in
	(
	Select U0."DocEntry" from odpi U0 Left Outer Join RCT2 T1 On U0."CreateTran" =''N'' and T1."InvType" = ''203'' and T1."DocEntry" = U0."DocEntry"
	Join ORCT T2 on T2."DocEntry" = T1."DocNum" Where TO_DATE(T2. ' || :dateField || ') <= ''' ||  :dateValue || ''' Or U0."DocStatus" = ''O'' 
	Group By U0."DocEntry" 
	Having Sum(T1."SumApplied") <> Max(U0."DocTotal") Or Max(U0."DocStatus") = ''O''
	) 
	Inner Join OCRD T4 On T4."CardCode" = T0."CardCode"
	Left Outer Join OIDC T5 On T5."Code" = T0."Indicator" ';

END IF;

--insert into debug values (:execSQL);
exec(:execSQL);

select * from "CRSP_Customer_Open_Item_List_TmpResult" order by "RefDate", "BaseRef", "ReconDate";
delete from "CRSP_Customer_Open_Item_List_TmpResult";

END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_DetailLedger_AllAccount
(In PrintJVoucherIn tinyint,
In PrintAdjustTransIn tinyint
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
execSQL nvarchar(4000);
whereStr nvarchar(1000);
selectStr nvarchar(1000);
groupStr nvarchar(200);
groupStr2 nvarchar(200);
orderStr nvarchar(200);
orderStr2 nvarchar(200);
printJVoucher tinyint;
printAdjTran tinyint;
postDateFrom nvarchar(30);
postDateTo nvarchar(30);
BEGIN
--insert into debug values ('DetailLedger_AllAccount ' || TO_CHAR(:PrintJVoucherIn));
--insert into debug values ('DetailLedger_AllAccount ' || TO_CHAR(:PrintAdjustTransIn));

delete from "CRSPDetailLedgerAllAccountResult";

printAdjTran := :PrintAdjustTransIn;
printJVoucher := :PrintJVoucherIn;
                  
selectStr := 'Select T0."AcctCode", 
		Max(T0."AcctName") as AcctName,
		T1."RefDate",
		Year(T1."RefDate") as RefYear, 
		Month(T1."RefDate") as RefMonth ,
		DAYOFYEAR(T1."RefDate")as RefDay,
	    Max(T2."Number") as Number, 
		Max(T1."LineMemo")as Memo, 
		Sum(T1."FCDebit") as FCDebit,
		Sum(T1."FCCredit")as FCCredit, 
		Max(T1."FCCurrency") as FCCurrency,
		Sum(T1."Debit") as Debit,
		Sum(T1."Credit") as Credit, 
		Max(T0."BalDirect") as BalDirect,
        Max(T1."Line_ID") as LineID,
        Max(T2."TransId") as TransID';
whereStr := '';
groupStr := 'Group By  Year(T1."RefDate"), Month(T1."RefDate"),T0."AcctCode", T2."TransId", T1."RefDate" ';
orderStr := 'Order By  T5."RefDate", T5."Number" ';
orderStr2 := 'Order By T5."RefDate", T5."Number"';
groupStr2 := 'Group By  Year(T1."RefDate"), Month(T1."RefDate"),T0."AcctCode",T2."TransId", T2."BatchNum", T1."Line_ID", T1."RefDate" ';

execSQL :=  :selectStr || '
		From OACT T0 inner join JDT1 T1 on T0."AcctCode" = T1."Account"
		inner join OJDT T2 on T2."TransId" = T1."TransId"  ';

If :printJVoucher = 0 Then
	if :printAdjTran = 0 Then
		whereStr := ' Where T2."AdjTran" <> ''Y'' ';
        execSQL := :execSQL || :whereStr;
	End	if;
	execSQL := execSQL || :groupStr;
	execSQL := 'Select  T5."AcctCode", T5.AcctName, T5."RefDate", T5.RefYear, T5.RefMonth , T5.RefDay, T5.Number, T5.Memo, 
						T5.FCDebit, T5.FCCredit, T5.FCCurrency, T5.Debit, T5.Credit, T5.BalDirect, T5.LineId, T5.TransId,
                        T4."CurOnRight", T4."DecSep", T4."SumDec", T4."ThousSep", T4."DateFormat", T4."CharMonth", T4."DateSep", T4."TimeFormat",
                        T6."LogoImage", T6."LogoFile", T6."MnhlNote", T4."CompnyName"  From ('  || :execSQL || ') T5 
						join (select *  from OADP ) T6 on 1=1 join  (Select *  from OADM) T4 on 1=1 ';
Else
	--Print Journal Voucher
	if :printAdjTran = 0 Then
		whereStr :=  ' Where T2."AdjTran" <> ''Y''  ';
        execSQL := :execSQL || :whereStr;
	End If;
		
	execSQL := :execSQL || :groupStr;	
	execSQL := :execSQL || ' union all ';
	execSQL := :execSQL || :selectStr;
	execSQL := :execSQL || '
			From OACT T0 inner join BTF1 T1 on T0."AcctCode" = T1."Account"
			inner join OBTF T2 on T2."TransId" = T1."TransId" and T1."BatchNum" = T2."BatchNum" and T2."BtfStatus" <>''C''  ';
	  	if :printAdjTran = 0 Then
			whereStr := ' where T2."AdjTran" <> ''Y''';
           execSQL := :execSQL || :whereStr;
		End If;
		execSQL :=  :execSQL || :groupStr2;
		execSQL := 'Select  T5."AcctCode", T5.AcctName, T5."RefDate", T5.RefYear, T5.RefMonth , T5.RefDay,
	                T5.Number, T5.Memo, T5.FCDebit, T5.FCCredit, T5.FCCurrency, T5.Debit, T5.Credit, 
					T5.BalDirect, T5.LineID, T5.TransId, T4."CurOnRight", T4."DecSep", T4."SumDec", T4."ThousSep",
                   T4."DateFormat", T4."CharMonth", T4."DateSep", T4."TimeFormat", T6."LogoImage", T6."LogoFile",
                    T6."MnhlNote", T4."CompnyName" From ('  || :execSQL || ')  T5 
					join (select *  from OADP ) T6 on 1=1
                    join (Select * from OADM) T4 on 1=1 ';
End If;

execSQL := 'Insert into "CRSPDetailLedgerAllAccountResult" (' || :execSQL || ' union all   
Select NULL as AcctCode, NULL as AcctName, NULL as RefDate, NULL as RefYear, NULL as   RefMonth,     NULL as RefDay,
   NULL as Number, NULL as Memo, NULL as FCDebit, NULL as FCCredit, NULL as FCCurrency, NULL as Debit, NULL as Credit,
   NULL as BalDirect, NULL as LineID, NULL as TransID,  T0."CurOnRight", T0."DecSep", T0."SumDec", T0."ThousSep", T0."DateFormat",
  T0."CharMonth", T0."DateSep", T0."TimeFormat", T1."LogoImage", T1."LogoFile", T1."MnhlNote", T0."CompnyName" from OADM T0 join OADP T1   on  1=1  Order by "RefDate", Number
)';
    
--    insert into debug values(:execSQL);

	Exec (:execSQL);
	
	select * from "CRSPDetailLedgerAllAccountResult";

delete from "CRSPDetailLedgerAllAccountResult";
	
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:SP:_TmSp_ValidateSpParam

Create Procedure CRSP_DetailLedger_OpenBalance (
 IsFromFilled TinyInt,
 PrintJVoucherIn NVarchar(1),
 PostDateFromIn NVarchar(30),
 PrintAdjustTransIn NVarchar(1),
 AccountCodeIn NVarchar(100)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
execSQL nvarchar(4000);
whereStr nvarchar(1000);
selectStr nvarchar(1000);
printAdjTran NVarchar(1);
printJVoucher NVarchar(1);
accountCode nvarchar(100);
postDateFrom nvarchar(30);
Begin
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:PrintJVoucherIn);    
	call _TmSp_ValidateSpParam(:PostDateFromIn);    
    call _TmSp_ValidateSpParam(:PrintAdjustTransIn);    
	call _TmSp_ValidateSpParam(:AccountCodeIn);    
	
--insert into debug values ('DetailLedger_OpenBalance ' || TO_CHAR(:IsFromFilled));
--insert into debug values ('DetailLedger_OpenBalance ' || :PrintJVoucherIn);
--insert into debug values ('DetailLedger_OpenBalance ' || :PostDateFromIn);
--insert into debug values ('DetailLedger_OpenBalance ' || :PrintAdjustTransIn);
--insert into debug values ('DetailLedger_OpenBalance ' || :AccountCodeIn);

delete from "CRSPDetailLedgerOpenBalanceResult";

postDateFrom := :PostDateFromIn;

If :IsFromFilled = 1 then
  postDateFrom := :PostDateFromIn;
Else
  postDateFrom := '';
End If;

accountCode := AccountCodeIn;

printAdjTran := 'N';
printJVoucher := 'N';

If :PrintAdjustTransIn = 'Y' then
  printAdjTran := 'Y';
End If;

If :PrintJVoucherIn = 'Y' then 
  printJVoucher := 'Y';
End If;

--If user input NO from , Set Opening Balance to ZERO
If length(:postDateFrom) = 0 then
	execSQL := 'insert into "CRSPDetailLedgerOpenBalanceResult" Select 0 as Debit, 0 as Credit from DUMMY';
Else
	If :printJVoucher = 'N' then
		selectStr := 'insert into "CRSPDetailLedgerOpenBalanceResult" select Sum("Debit") as Debit , Sum("Credit") as Credit From JDT1 T0 ';
		whereStr := '  Where  T0."Account" = ''' || :accountCode || ''' ';
		whereStr := :whereStr || '  And T0."RefDate" < ''' || :postDateFrom || ''' ';
		If :printAdjTran = 'N' Then
			whereStr := :whereStr || 'And T0."AdjTran" <>''Y'' ';
		End If;
		
		execSQL := :selectStr || :whereStr;
	Else
		selectStr :=  'insert into "CRSPDetailLedgerOpenBalanceResult" Select Sum("Debit") as Debit , Sum("Credit") as Credit From JDT1 T0 ';
		whereStr := '  Where  T0."Account" = ''' || :accountCode || ''' ';
		whereStr := :whereStr || '  And T0."RefDate" < ''' || :postDateFrom  || ''' ';
		If :printAdjTran = 'N' Then
			whereStr := :whereStr || 'And T0."AdjTran" <>''Y'' ';
		End If;
		
		execSQL := :selectStr || :whereStr;
		execSQL := :execSQL || ' union all ';
		selectStr := 'Select Sum("Debit") as Debit , Sum("Credit") as Credit From BTF1 T0 
				join OBTF T1 on T0."BatchNum" = T1."BatchNum" and T0."TransId" = T1."TransId" ';
		whereStr := '  Where  T0."Account" = ''' || :accountCode || ''' ';
		whereStr := :whereStr || ' And T1."BtfStatus" <> ''C'' And T0."RefDate" < ''' || :postDateFrom || ''' ';
		If :printAdjTran = 'N' Then
			whereStr := :whereStr || 'And T0."AdjTran" <>''Y'' ';
		End If;
		
		execSQL := :execSQL || :selectStr || :whereStr;
	End If;
End If;

--insert into debug values (:execSQL);



Exec (:execSQL);
select * from "CRSPDetailLedgerOpenBalanceResult";

delete from "CRSPDetailLedgerOpenBalanceResult";

End;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE CRSP_GeneralLedger_AllAccount
(In AcctCodeList NCLOB,
In PrintJVoucher NVarchar(1),
In PrintAdjustTrans NVarchar(1),
In PostDateFromIn NVarchar(30),
in PostDateToIn nvarchar(30)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
PrintAdjJE nvarchar(1);
SelectStr  nvarchar(4000);
JoinStr   nvarchar(4000);
execSQL  NCLOB;
tableName nvarchar(5);
preTable nvarchar(5);
fatherName nvarchar(10);
loopCounter int;
ind int;
AcctList  NCLOB;
UpdateStr nvarchar(1000);
CaseStr nvarchar(200);
dateTableStr NCLOB;
mainSQL NCLOB;
iYearFrom char(4);
iMonthFrom char(2);
iYearTo char(4);
iMonthTo char(2);
PostDateFrom NVarchar(30);
PostDateTo nvarchar(30);
numDate int;
BEGIN
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:AcctCodeList);    
	call _TmSp_ValidateSpParam(:PrintJVoucher);    
	call _TmSp_ValidateSpParam(:PrintAdjustTrans);    
    call _TmSp_ValidateSpParam(:PostDateFromIn);    
	call _TmSp_ValidateSpParam(:PostDateToIn);    
	
PrintAdjJE := :PrintAdjustTrans;
AcctList := :AcctCodeList;
PostDateFrom := :PostDateFromIn;
PostDateTo := :PostDateToIn;

--insert into debug values ('AllAccount ' || :AcctCodeList);
--insert into debug values ('AllAccount ' || :PrintJVoucher);
--insert into debug values ('AllAccount ' || :PrintAdjustTrans);
--insert into debug values ('AllAccount ' || :PostDateFromIn);
--insert into debug values ('AllAccount ' || :PostDateToIn);

delete from "CRSPGeneralLedgerAllAccountDateTable";
delete from "CRSPGeneralLedgerAllAccountAcctFatherSonResult";
delete from "CRSPGeneralLedgerAllAccountAcctFatherSon";
delete from "CRSPGeneralLedgerAllAccountAcctFatherSonTable";

If length(:PostDateFrom) = 0 Then
     PostDateFrom := '1970-03-17';
end if;

If length(:PostDateTo) = 0 Then
    PostDateTo := '2020-03-17';
end if;

execSQL := 'insert into "CRSPGeneralLedgerAllAccountAcctFatherSonTable" (Select '' '' as GroupCode, T0."AcctCode", T0."AcctName",  T0."FatherNum" as Father0 ,T1."FatherNum" as Father1, T2."FatherNum" as Father2, T3."FatherNum" as Father3, T4."FatherNum" as Father4 
From OACT T0   
Left outer Join (Select "AcctCode", "FatherNum" from OACT) T1 on T1."AcctCode" = T0."FatherNum"  
Left outer Join (Select "AcctCode", "FatherNum" from OACT) T2 on T2."AcctCode" = T1."FatherNum"  
Left outer Join (Select "AcctCode", "FatherNum" from OACT) T3 on T3."AcctCode" = T2."FatherNum"  
Left outer Join (Select "AcctCode", "FatherNum" from OACT) T4 on T4."AcctCode" = T3."FatherNum"  where T0."AcctCode" in ' || :AcctList || ')';

--insert into debug values (:execSQL);
exec (:execSQL);

Update "CRSPGeneralLedgerAllAccountAcctFatherSonTable" Set GroupCode = ( Case When (length(AcctCode) = 4 
	And ascii(substr(AcctCode, 0, 1)) > 47 And ascii(substr(AcctCode, 0, 1)) < 58
	And ascii(substr(AcctCode, 1, 1)) > 47 And ascii(substr(AcctCode, 1, 1)) < 58
	And ascii(substr(AcctCode, 2, 1)) > 47 And ascii(substr(AcctCode, 2, 1)) < 58
	And ascii(substr(AcctCode, 3, 1)) > 47 And ascii(substr(AcctCode, 3, 1)) < 58
	) Then Acctcode  When (length(Father0) = 4) 
		And ascii(substr(Father0, 0, 1)) > 47 And ascii(substr(Father0, 0, 1)) < 58 
		And ascii(substr(Father0, 1, 1)) > 47 And ascii(substr(Father0, 1, 1)) < 58 
		And ascii(substr(Father0, 2, 1)) > 47 And ascii(substr(Father0, 2, 1)) < 58 
		And ascii(substr(Father0, 3, 1)) > 47 And ascii(substr(Father0, 3, 1)) < 58 Then Father0 When (length(Father1) = 4) 
		And ascii(substr(Father1, 0, 1)) > 47 And ascii(substr(Father1, 0, 1)) < 58 
		And ascii(substr(Father1, 1, 1)) > 47 And ascii(substr(Father1, 1, 1)) < 58 
		And ascii(substr(Father1, 2, 1)) > 47 And ascii(substr(Father1, 2, 1)) < 58 
		And ascii(substr(Father1, 3, 1)) > 47 And ascii(substr(Father1, 3, 1)) < 58 Then Father1 When (length(Father2) = 4) 
		And ascii(substr(Father2, 0, 1)) > 47 And ascii(substr(Father2, 0, 1)) < 58 
		And ascii(substr(Father2, 1, 1)) > 47 And ascii(substr(Father2, 1, 1)) < 58 
		And ascii(substr(Father2, 2, 1)) > 47 And ascii(substr(Father2, 2, 1)) < 58 
		And ascii(substr(Father2, 3, 1)) > 47 And ascii(substr(Father2, 3, 1)) < 58 Then Father2 When (length(Father3) = 4) 
		And ascii(substr(Father3, 0, 1)) > 47 And ascii(substr(Father3, 0, 1)) < 58 
		And ascii(substr(Father3, 1, 1)) > 47 And ascii(substr(Father3, 1, 1)) < 58 
		And ascii(substr(Father3, 2, 1)) > 47 And ascii(substr(Father3, 2, 1)) < 58 
		And ascii(substr(Father3, 3, 1)) > 47 And ascii(substr(Father3, 3, 1)) < 58 Then Father3 When (length(Father4) = 4) 
		And ascii(substr(Father4, 0, 1)) > 47 And ascii(substr(Father4, 0, 1)) < 58 
		And ascii(substr(Father4, 1, 1)) > 47 And ascii(substr(Father4, 1, 1)) < 58 
		And ascii(substr(Father4, 2, 1)) > 47 And ascii(substr(Father4, 2, 1)) < 58 
		And ascii(substr(Father4, 3, 1)) > 47 And ascii(substr(Father4, 3, 1)) < 58 Then Father4 Else Acctcode End);

insert into "CRSPGeneralLedgerAllAccountAcctFatherSon" 
(select T0.GroupCode, T1."AcctName" as GroupName, T1."BalDirect" as GroupDirect, T0.AcctCode, T0.AcctName 
from "CRSPGeneralLedgerAllAccountAcctFatherSonTable" T0 
inner join OACT T1 on T0.GroupCode = T1."AcctCode"
);

insert into "CRSPGeneralLedgerAllAccountDateTable"
(Select Year(T0."RefDate") as AllYear, Month(T0."RefDate") as AllMonth from JDT1 T0 
group by Year(T0."RefDate"), Month(T0."RefDate")
);


If Year(:PostDateFrom) > 1970 then
	select Count(*) into numDate from "CRSPGeneralLedgerAllAccountDateTable" where AllYear = LTrim(Year(:PostDateFrom)) and AllMonth = LTrim(Month(:PostDateFrom));
Else
	select Count(*) into numDate from "CRSPGeneralLedgerAllAccountDateTable" where AllYear = LTrim(Year(:PostDateTo)) and AllMonth = LTrim(Month(:PostDateTo));
End if;

If :numDate = 0 Then
    If Year(:PostDateFrom) > 1970 then  
		Insert into "CRSPGeneralLedgerAllAccountDateTable" values (TO_NVARCHAR(Year(:PostDateFrom)),TO_NVARCHAR(Month(:PostDateFrom)));
	Else 
		Insert into "CRSPGeneralLedgerAllAccountDateTable" values (TO_NVARCHAR(Year(:PostDateTo)),TO_NVARCHAR(Month(:PostDateTo)));
	End If;
End If;


--Begin Create 'MainTable' for JE

SelectStr := 'Select J1."Account", J1."Debit", J1."Credit", J1."TransId", J1."Line_ID", J1."RefDate", Year(J1."RefDate") as Year, Month(J1."RefDate") as Month, DAYOFYEAR(J1."RefDate") as Day,J1."LineMemo", J0."Number" ';
mainSQL :=  :SelectStr || ' From JDT1 J1 inner join OJDT J0 on J1."TransId" = J0."TransId"  where J1."Account" in ' || :AcctList || ' And J1."RefDate" >=''' || :PostDateFrom || '''  And J1."RefDate" <=''' || :PostDateTo || '''';

If :PrintAdjJE = 'N' then
	mainSQL := :mainSQL || ' And  J0."AdjTran" <> ''Y''';
End if;

if :PrintJVoucher = 'Y' then
	mainSQL := :mainSQL || 'Union all ';
    mainSQL := :mainSQL || :SelectStr;
	mainSQL := :mainSQL || ' From BTF1 J1 inner join OBTF J0 on J1."TransId" = J0."TransId" and J1."BatchNum" = J0."BatchNum"  where  J0."BtfStatus" <>''C''  and  J1."Account" in ' || :AcctList || ' And J1."RefDate" >=''' || :PostDateFrom || '''  And J1."RefDate" <=''' || :PostDateTo || '''';
	If  :PrintAdjJE = 'N' then
		mainSQL := :mainSQL || ' And  J0."AdjTran" <> ''Y''';
	End if;
End if;

--End Create 'MainTable' for 
iYearFrom := LTrim(Year(:PostDateFrom));
iYearTo := LTrim(Year(:PostDateTo));
iMonthFrom :=  LTrim(Month(:PostDateFrom));
iMonthTo :=  LTrim(Month(:PostDateTo));

--Label :Add date filter here, use Year * 100 + Month to compare ( '1980-03' : 1980*100 + 3 = 19800

execSQL := ' Insert into "CRSPGeneralLedgerAllAccountAcctFatherSonResult" (Select * from "CRSPGeneralLedgerAllAccountAcctFatherSon" T0 join "CRSPGeneralLedgerAllAccountDateTable" T1 on
 ( T1.AllYear * 100 + T1.AllMonth >= ' || :iYearFrom || ' * 100 +' ||  :iMonthFrom || ' And T1.AllYear * 100 + T1.AllMonth <= ' || :iYearTo || ' * 100 + ' || :iMonthTo || ') '
	|| '  Left Outer Join  (' || :mainSQL || ') TMain on TMain."Account" = T0.AcctCode and TMain.Year = T1.AllYear and TMain.Month = T1.AllMonth  ';

--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--Some Account HAS JE in JDT1 in some month, but the RefDate is out of the Date Range, to keep the Account Info , Here it has to Use 'Union' ,haha!!
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------

execSQL := :execSQL || ' Union all  Select * , NULL as Account, 0 as Debit, 0 as Credit , NULL as TransId, NULL as Line_id, NULL as RefDate, NULL as Year, NULL as Month, NULL as Day, NULL as LineMemo, NULL as Number  from "CRSPGeneralLedgerAllAccountAcctFatherSon" A0 Join "CRSPGeneralLedgerAllAccountDateTable" A1 on '
 ' ( A1.AllYear * 100 + A1.AllMonth >= ' || :iYearFrom || ' * 100 +' ||  :iMonthFrom ||  ' And A1.AllYear * 100 + A1.AllMonth <= ' || :iYearTo || ' * 100 + ' || :iMonthTo || ') ' ||
 ' order by T1.AllYear, T1.AllMonth, T0.AcctCode )';

	--print (@execSQL);

	exec (:execSQL);
--	insert into debug values (:CaseStr);
--	insert into debug values (:UpdateStr);
--	insert into debug values (:execSQL);

	select * from "CRSPGeneralLedgerAllAccountAcctFatherSonResult";
	
	delete from "CRSPGeneralLedgerAllAccountDateTable";
	delete from "CRSPGeneralLedgerAllAccountAcctFatherSonResult";
	delete from "CRSPGeneralLedgerAllAccountAcctFatherSon";
	delete from "CRSPGeneralLedgerAllAccountAcctFatherSonTable";
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

create procedure CRSP_GeneralLedger_OpenBalance (
	in AcctCodeList NCLOB,
	in PrintJVoucher nvarchar(1),
	in PrintAdjustTrans nvarchar(1),
	in PostDateFromIn nvarchar(30),
	in PostDateToIn nvarchar(30)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
PrintAdjJE nvarchar(1);
acctList1  NCLOB;
SelectStr  nvarchar(4000);
FromStr   NCLOB;
JoinStr   nvarchar(4000);
whereStr  nvarchar(4000);
execSQL   NCLOB;
tableName nvarchar(5);
preTable nvarchar(5);
fatherName nvarchar(10);
loopCounter int;
ind int;
postDateFrom nvarchar(30);
postDateTo   nvarchar(30);
GetOpeningBal  nvarchar(1000); 
UpdateStr NCLOB;
CaseStr NCLOB;
BEGIN
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
	call _TmSp_ValidateSpParam(:AcctCodeList);    
    call _TmSp_ValidateSpParam(:PrintJVoucher);    
	call _TmSp_ValidateSpParam(:PrintAdjustTrans);    
    call _TmSp_ValidateSpParam(:PostDateFromIn);    
	call _TmSp_ValidateSpParam(:PostDateToIn);    
	
--insert into debug values ('OpenBalance ' || :AcctCodeList);
--insert into debug values ('OpenBalance ' || :PrintJVoucher);
--insert into debug values ('OpenBalance ' || :PrintAdjustTrans);
--insert into debug values ('OpenBalance ' || :PostDateFromIn);
--insert into debug values ('OpenBalance ' || :PostDateToIn);

	delete from CRSPGeneralLedgerOpenBalance_tempLDGTable;

	loopCounter := 4;
	ind := 1;
	JoinStr := '';
	acctList1 := :AcctCodeList;
	postDateFrom := :PostDateFromIn;
	postDateTo := :PostDateToIn;
	PrintAdjJE := :PrintAdjustTrans;

	SelectStr := 'Select '' '' as GroupColumn, T0."AcctCode", T0."AcctName",  T0."FatherNum" as Father0 ';
	WHILE :loopCounter >= :ind Do
		tableName := 'T' || :ind;
		preTable := 'T' || (:ind-1);
		fatherName := 'Father' || :ind;
		SelectStr := :SelectStr || ',' || :tableName ||'."FatherNum" as ' || :fatherName;
		JoinStr := :JoinStr || ' Left outer Join (Select "AcctCode", "FatherNum" from OACT)' || tableName || ' on '|| :tableName ||'."AcctCode" = ' || :preTable ||'."FatherNum" ';
		ind := :ind + 1;
	End while;

	FromStr := ', T0."Postable", T0."Levels", T0."BalDirect", J0."Debit", J0."Credit", J0."TransId", J0."Line_ID", J0."RefDate", Year(J0."RefDate") as Year, Month(J0."RefDate") as Month, DAYOFYEAR(J0."RefDate") as Day, J0."LineMemo", J1."Number" From (Select * from OACT  where "AcctCode" in '|| :acctList1 || ') T0 Left Outer Join (Select * from JDT1 where  ';
	
	If length(:postDateFrom) = 0 Then
    	postDateFrom := '19700101';
	End if;

	FromStr := :FromStr || 'JDT1."RefDate" < ''' || :postDateFrom || ''' ';

	FromStr := :FromStr || ') J0 on T0."AcctCode" = J0."Account"  Inner Join OJDT J1  on J1."TransId" = J0."TransId" ';
	If :PrintAdjJE = 'N' Then
		FromStr := :FromStr || ' And J1."AdjTran" <> ''Y''';
	End If;

	execSQL := :SelectStr || :FromStr || :JoinStr;

	if :PrintJVoucher = 'Y' Then
		execSQL := :execSQL || 'Union all ';

		FromStr := ', T0."Postable", T0."Levels", T0."BalDirect", J0."Debit", J0."Credit", J0."TransId", J0."Line_ID", J0."RefDate", Year(J0."RefDate") as Year, Month(J0."RefDate") as Month, DAYOFYEAR(J0."RefDate") as Day,J0."LineMemo", J1."Number" From (Select * from OACT  where "AcctCode" in '||:acctList1 ||') T0 Left Outer Join (Select * from BTF1 where '; 
    	FromStr := :FromStr || 'BTF1."RefDate" <''' || :postDateFrom || ''' ';
		FromStr := :FromStr || ') J0 on T0."AcctCode" = J0."Account"  Inner Join OBTF J1  on J1."TransId" = J0."TransId" and J1."BatchNum" = J0."BatchNum" and J1."BtfStatus" <>''C'' ';
		
		If :PrintAdjJE = 'N' Then
			FromStr := :FromStr || ' And J1."AdjTran" <> ''Y''';
		End If;
    	execSQL := :execSQL || :SelectStr || :FromStr || :JoinStr;
	End If;

	execSQL := 'Insert into CRSPGeneralLedgerOpenBalance_tempLDGTable (' || :execSQL || ')';
	UpdateStr := ' Update CRSPGeneralLedgerOpenBalance_tempLDGTable Set GroupColumn = ( Case When (length(AcctCode) = 4 
	And ascii(substr(AcctCode, 0, 1)) > 47 And ascii(substr(AcctCode, 0, 1)) < 58
	And ascii(substr(AcctCode, 1, 1)) > 47 And ascii(substr(AcctCode, 1, 1)) < 58
	And ascii(substr(AcctCode, 2, 1)) > 47 And ascii(substr(AcctCode, 2, 1)) < 58
	And ascii(substr(AcctCode, 3, 1)) > 47 And ascii(substr(AcctCode, 3, 1)) < 58
	) Then Acctcode ';

--Begin to search GL Account , fill it into 'GroupColumn'
	ind := 0;

	While :loopCounter >= :ind Do
		fatherName := 'Father' || :ind;
		CaseStr := ' When (length(' || :fatherName || ') = 4) 
		And ascii(substr(' || :fatherName || ', 0, 1)) > 47 And ascii(substr(' || :fatherName || ', 0, 1)) < 58 
		And ascii(substr(' || :fatherName || ', 1, 1)) > 47 And ascii(substr(' || :fatherName || ', 1, 1)) < 58 
		And ascii(substr(' || :fatherName || ', 2, 1)) > 47 And ascii(substr(' || :fatherName || ', 2, 1)) < 58 
		And ascii(substr(' || :fatherName || ', 3, 1)) > 47 And ascii(substr(' || :fatherName || ', 3, 1)) < 58 Then ' || :fatherName;
		UpdateStr := :UpdateStr || :CaseStr;
		ind := :ind + 1;
	End while;

	UpdateStr := :UpdateStr || ' Else Acctcode End)';
--End Search

	Exec (:execSQL);
	Exec (:UpdateStr);
	
	Select  GroupColumn, Sum(Debit) as OBDebit, Sum(Credit) as OBCredit from CRSPGeneralLedgerOpenBalance_tempLDGTable T0 group by  T0.GroupColumn;

--	insert into debug values(:execSQL);
--	insert into debug values(:UpdateStr);

	delete from CRSPGeneralLedgerOpenBalance_tempLDGTable;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam


