CREATE PROCEDURE CRSP_GLAccountStatement_BR_enUS (in FromDate timestamp, in ToDate timestamp) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
CompanyName nvarchar(200);
BEGIN /*
    
***** General Information *****
Name: OJDT_AccountJournal
Description: Return A/R Invoices and A/R Credit Memos in a certain Date Range

Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22
*/
    /* Internal parameters */
    SELECT 
    (SELECT "CompnyName" 
    FROM OADM) INTO CompanyName FROM DUMMY;
    /*********************************/
    /*Months before (Opening Balance) */
    SELECT T1."Account", T2."AcctName", :CompanyName AS "CompanyName", NULL AS "RefDate", NULL AS "TaxDate", 
        '' AS "Ref1", '' AS "ContraAct", 'Previous Month(s)' AS "LineMemo", -1 AS "TransID", NULL AS "FCCurrency", 
        ifnull(SUM(T1."Debit"), 0) - ifnull(SUM(T1."Credit"), 0) AS "OpeningBalance", ifnull(SUM(T1."FCDebit"), 0) -
         ifnull(SUM(T1."FCCredit"), 0) AS "FCOpeningBalance", 0 AS "Debit", 0 AS "Credit", 0 AS "FCDebit", 
        0 AS "FCCredit" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN OACT T2 ON T1."Account" = T2."AcctCode" 
    WHERE T0."RefDate" < :FromDate 
    GROUP BY T1."Account", T2."AcctName" 
    UNION ALL 
    SELECT T1."Account", T2."AcctName", :CompanyName AS "CompanyName", T0."RefDate", T0."TaxDate", T0."Ref1", 
        T1."ContraAct", T1."LineMemo", T0."TransId", T1."FCCurrency", NULL AS "OpeningBalance", 
        NULL AS "FCOpeningBalance", T1."Debit", T1."Credit", T1."FCDebit", T1."FCCredit" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN OACT T2 ON T1."Account" = T2."AcctCode" 
    WHERE T0."RefDate" BETWEEN :FromDate AND :ToDate;
    /* Journal Rows */
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_InventoryTurnover_BR_enUS (in DateFromParam timestamp, in DateToParam timestamp, in DateTypeParam varchar(32), in ItemCodeFromParam varchar(50), in ItemCodeToParam varchar(50)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
DateFrom timestamp;
DateTo timestamp;
DateType varchar(32);
ItemCodeFrom varchar(50);
ItemCodeTo varchar(50);
BEGIN 
    DateFrom := DateFromParam;
    DateTo := DateToParam;
    DateType := DateTypeParam;
    ItemCodeFrom := ItemCodeFromParam;
    ItemCodeTo := ItemCodeToParam;
		
	
	IF ItemCodeFrom = '' THEN
		SELECT  (SELECT MIN("ItemCode")  FROM OITM) INTO ItemCodeFrom FROM DUMMY;
	END IF;
	
	IF ItemCodeTo = '' THEN
		SELECT  (SELECT MAX("ItemCode")  FROM OITM) INTO ItemCodeTo FROM DUMMY;
	END IF;

    SELECT T0."ItemCode", T1."ItemName", CAST(T2."ItmsGrpCod" AS nvarchar(20)) AS "ItmsGrpCod", T2."ItmsGrpNam", 
        T0."Warehouse", T1."CreateDate", T0."Currency", ifnull(
        (SELECT SUM(T10."InQty") - SUM(T10."OutQty") 
        FROM OINM T10 
        WHERE T10."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T10."DocDate" 
                WHEN 'CreateDate' THEN T10."CreateDate" 
                ELSE T10."DocDate" 
            END) < :DateFrom AND T10."Warehouse" =T0."Warehouse" AND T10."ItemCode" = T0."ItemCode"), 0) AS "InStockBegin", ifnull(
        (SELECT SUM(T20."TransValue") 
        FROM OINM T20 
        WHERE T20."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T20."DocDate" 
                WHEN 'CreateDate' THEN T20."CreateDate" 
                ELSE T20."DocDate" 
            END) < :DateFrom AND T20."Warehouse" =T0."Warehouse" AND T20."ItemCode" = T0."ItemCode"), 0) AS "StockValueBegin", ifnull(
        (SELECT SUM(T30."TransValue") 
        FROM OINM T30 
        WHERE T30."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T30."DocDate" 
                WHEN 'CreateDate' THEN T30."CreateDate" 
                ELSE T30."DocDate" 
            END) >= :DateFrom AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T30."DocDate" 
                WHEN 'CreateDate' THEN T30."CreateDate" 
                ELSE T30."DocDate" 
            END) <= :DateTo AND T30."Warehouse" =T0."Warehouse" AND T30."ItemCode" = T0."ItemCode" AND T30."TransValue" > 0), 0) AS "Receipts", ifnull(
        (SELECT SUM(T31."InQty") 
        FROM OINM T31 
        WHERE T31."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T31."DocDate" 
                WHEN 'CreateDate' THEN T31."CreateDate" 
                ELSE T31."DocDate" 
            END) >= :DateFrom AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T31."DocDate" 
                WHEN 'CreateDate' THEN T31."CreateDate" 
                ELSE T31."DocDate" 
            END) <= :DateTo AND T31."Warehouse" =T0."Warehouse" AND T31."ItemCode" = T0."ItemCode"), 0) AS "ReceiptsQuant", ifnull(
        (SELECT SUM(T40."TransValue") * -1 
        FROM OINM T40 
        WHERE T40."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T40."DocDate" 
                WHEN 'CreateDate' THEN T40."CreateDate" 
                ELSE T40."DocDate" 
            END) >= :DateFrom AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T40."DocDate" 
                WHEN 'CreateDate' THEN T40."CreateDate" 
                ELSE T40."DocDate" 
            END) <= :DateTo AND T40."Warehouse" =T0."Warehouse" AND T40."ItemCode" = T0."ItemCode" AND T40."TransValue" < 0), 0) AS "Issues", ifnull(
        (SELECT SUM(T41."OutQty") 
        FROM OINM T41 
        WHERE T41."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T41."DocDate" 
                WHEN 'CreateDate' THEN T41."CreateDate" 
                ELSE T41."DocDate" 
            END) >= :DateFrom AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T41."DocDate" 
                WHEN 'CreateDate' THEN T41."CreateDate" 
                ELSE T41."DocDate" 
            END) <= :DateTo AND T41."Warehouse" =T0."Warehouse" AND T41."ItemCode" = T0."ItemCode"), 0) AS "IssuesQuant", ifnull(
        (SELECT SUM(T50."InQty") - SUM(T50."OutQty") 
        FROM OINM T50 
        WHERE T50."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T50."DocDate" 
                WHEN 'CreateDate' THEN T50."CreateDate" 
                ELSE T50."DocDate" 
            END) <= :DateTo AND T50."Warehouse" =T0."Warehouse" AND T50."ItemCode" = T0."ItemCode"), 0) AS "InStockEnd", ifnull(
        (SELECT SUM(T60."TransValue") 
        FROM OINM T60 
        WHERE T60."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T60."DocDate" 
                WHEN 'CreateDate' THEN T60."CreateDate" 
                ELSE T60."DocDate" 
            END) <= :DateTo AND T60."Warehouse" =T0."Warehouse" AND T60."ItemCode" = T0."ItemCode"), 0) AS "StockValueEnd", ifnull(
        (SELECT SUM(T60."TransValue") 
        FROM OINM T60 
        WHERE T60."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T60."DocDate" 
                WHEN 'CreateDate' THEN T60."CreateDate" 
                ELSE T60."DocDate" 
            END) <= :DateTo AND T60."Warehouse" =T0."Warehouse" AND T60."ItemCode" = T0."ItemCode"), 0) - ifnull(
        (SELECT SUM(T20."TransValue") 
        FROM OINM T20 
        WHERE T20."TransType" <> 67 AND (
            CASE :DateType 
                WHEN 'PostingDate' THEN T20."DocDate" 
                WHEN 'CreateDate' THEN T20."CreateDate" 
                ELSE T20."DocDate" 
            END) < :DateFrom AND T20."Warehouse" =T0."Warehouse" AND T20."ItemCode" = T0."ItemCode"), 0) AS "Turnover" 
    FROM OINM T0 
        INNER JOIN OITM T1 ON T0."ItemCode" = T1."ItemCode" 
        INNER JOIN OITB T2 ON T1."ItmsGrpCod" = T2."ItmsGrpCod" 
    WHERE T0."TransType" <> 67 AND (
        CASE :DateType 
            WHEN 'PostingDate' THEN T0."DocDate" 
            WHEN 'CreateDate' THEN T0."CreateDate" 
            ELSE T0."DocDate" 
        END) >= :DateFrom AND (
        CASE :DateType 
            WHEN 'PostingDate' THEN T0."DocDate" 
            WHEN 'CreateDate' THEN T0."CreateDate" 
            ELSE T0."DocDate" 
        END) <= :DateTo AND 
        T0."ItemCode" >= :ItemCodeFrom AND T0."ItemCode" <= :ItemCodeTo 
    GROUP BY T0."ItemCode", T1."ItemName", T2."ItmsGrpCod", T2."ItmsGrpNam", T0."Warehouse", T1."CreateDate", T0."Currency" 
    ORDER BY T0."ItemCode";
    --[Note:Modifier] HANA doesn't have CONVERT you may you see CAST or implicit casting or TO_... functions
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_Inventory_Counting
(
in DocKey_in integer
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
AS
selectStr nvarchar(256);
fromStr nvarchar(256);
whereStr nvarchar(64);
docKey integer;
taker1Type integer;
taker2Type integer;
typeUSR integer := 12;
typeHEM integer := 171;
taker1 nvarchar(64);
taker2 nvarchar(64);
joinTbl1 nvarchar(5);
joinTbl2 nvarchar(5);
joinCol1 nvarchar(16);
joinCol2 nvarchar(16);
counter integer;
BEGIN 
    joinTbl2 := '';
    joinCol2 := '';
    docKey := :DocKey_in;
    SELECT count("Taker1Type") into counter FROM OINC where "DocEntry" = :docKey;
    if( (:counter) > 0 ) then
    	SELECT "Taker1Type" INTO taker1Type FROM OINC where "DocEntry" = :docKey;
    end if;
    
    SELECT count("Taker2Type") into counter FROM OINC where "DocEntry" = :docKey;
    if ( (:counter) > 0 ) then
    	SELECT "Taker2Type" INTO taker2Type FROM OINC where "DocEntry" = :docKey;
    end if;
    
    IF (:taker1Type = :typeUSR) THEN 
        taker1 := 'T1."U_NAME"';
        joinTbl1 := 'OUSR';
        joinCol1 := '"USERID"';
    ELSE 
        taker1 := 'T1."lastName"||'' ''||T1."firstName"';
        joinTbl1 := 'OHEM';
        joinCol1 := '"empID"';
    END IF;
    IF (:taker2Type = :typeUSR) THEN 
        taker2 := 'T2."U_NAME"';
        joinTbl2 := 'OUSR';
        joinCol2 := '"USERID"';
    ELSE 
        IF (:taker2Type = :typeHEM) THEN 
            taker2 := 'T2."lastName"||'' ''||T2."firstName"';
            joinTbl2 := 'OHEM';
            joinCol2 := '"empID"';
        ELSE 
            taker2 := :taker1;
        END IF;
    END IF;
    selectStr := 'select T0."DocEntry", T0."DocNum", T0."CountDate", T0."Time", T0."CountType", '
    			|| :taker1 || ' as "Taker1", '
    			|| :taker2 || ' as "Taker2", '
    			|| 'T0."Ref2", T0."Remarks"';
    fromStr := ' from OINC T0';
    fromStr := :fromStr || ' join ' || :joinTbl1 || ' T1 on T0."Taker1Id" = T1.' || :joinCol1;
    IF (:joinTbl2 <> '') THEN 
        fromStr := :fromStr || ' join ' || :joinTbl2 || ' T2 on T0."Taker2Id" = T2.' || :joinCol2;
    END IF;
    whereStr := ' where T0."DocEntry" = ' || :docKey;
    execute immediate(:selectStr || :fromStr || :whereStr);
	--select :selectStr || :fromStr || :whereStr from dummy;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_Inventory_Counting_GetCounterName(
in DocKey nvarchar(12),
in MultipleCounterType nvarchar(1),
in MultipleCounterOrder nvarchar(12)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
selectStr nvarchar(256);
fromStr nvarchar(256);
whereStr nvarchar(64);

CountingType nvarchar(1);

taker1Type int;

typeUSR int := 12;
typeHEM int := 171;
CountTypeSingle nvarchar(1) := '1';
CountTypeMultiple nvarchar(1) := '2';

CounterTypeTeam nvarchar(1) := 'T';
CounterTypeIndividual nvarchar(1) := 'I';

MainTable nvarchar(16);
Counter nvarchar(64);
joinTbl nvarchar(16);
joinCol nvarchar(16);

ResultCounterName nvarchar(16) := 'CounterName';

DocEntry nvarchar(16) := :DocKey;
CounterOrder nvarchar(16) := :MultipleCounterOrder;
BEGIN


whereStr := ' where "T0"."DocEntry"=' || :DocEntry;

select "T0"."CountType" INTO CountingType from "OINC" "T0" where "T0"."DocEntry"= :DocKey;
select "Taker1Type" INTO Taker1Type from "OINC" where "DocEntry"= :DocKey;

IF (:CountingType = :CountTypeSingle )
THEN
        SELECT "Taker1Type" INTO Taker1Type from "OINC" where "DocEntry"= :DocKey;
        
        IF(:taker1Type = :typeUSR)
        THEN
             Counter := ' "T1"."U_NAME" ';
             joinTbl := ' "OUSR" ';
             joinCol := ' "USERID" ';
        ELSE
             Counter := ' "T1"."lastName"||'' ''||"T1"."firstName" ';
             joinTbl := ' "OHEM" ';
             joinCol := ' "empID" ';
        End IF;

        selectStr := 'select ' || :Counter || ' as ' || :ResultCounterName || ' from "OINC"  "T0" ' ||  ' join ' || :joinTbl || ' "T1" on "T0"."Taker1Id" = "T1".' || :joinCol || :whereStr;
ELSE
        IF(:MultipleCounterType = :CounterTypeTeam)
        THEN
              MainTable :=' "INC4" "T0" ';
        ELSE
              MainTable :=' "INC8" "T0" ';
        End IF;
       
        selectStr := 'select ' ||  ' "T0"."CounteName" '|| ' as ' || :ResultCounterName || ' from '|| :MainTable  ||  :whereStr || ' and "T0"."VisOrder" = ' || :CounterOrder;
END IF;

EXECUTE IMMEDIATE (:selectStr);

END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_Inventory_Counting_PerCounter(
in DocKey nvarchar(12),
in MultipleCounterType nvarchar(1),
in MultipleCounterOrder nvarchar(12)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
CountType nvarchar(1);
CountNumber int;
BEGIN


SELECT  "OINC"."CountType" into CountType FROM "OINC" WHERE "OINC"."DocEntry" = :DocKey;

IF :CountType = '1' --single counter
THEN 
		SELECT "T1"."DocEntry", "T1"."ItemCode", "T1"."ItemDesc", "T1"."WhsCode", "T1"."BinEntry", "T2"."BinCode", "T1"."InWhsQty", "T1"."Counted", "T1"."CountQty" 
		FROM "INC1" "T1" LEFT JOIN "OBIN" "T2" ON "T1"."BinEntry"="T2"."AbsEntry" WHERE "T1"."DocEntry"= :DocKey ORDER BY "T1"."VisOrder";
 
ELSE  --multiple counters
	IF :MultipleCounterType = 'I' --individual counter
	THEN
		SELECT "T1"."CounterNum" INTO CountNumber FROM "INC8" "T1" WHERE "T1"."DocEntry" = :DocKey AND "T1"."VisOrder" = :MultipleCounterOrder;
		
		SELECT "T1"."DocEntry", "T1"."ItemCode", "T1"."ItemDesc", "T1"."WhsCode", "T1"."BinEntry", "T2"."BinCode", "T1"."InWhsQty", "T1"."Counted", "T3"."TotalQty" AS "CountQty" 
		FROM "INC1" "T1" 
		LEFT JOIN "OBIN" "T2" ON "T1"."BinEntry"="T2"."AbsEntry"
		LEFT JOIN "INC9" "T3" ON "T1"."DocEntry"="T3"."DocEntry" AND  "T1"."LineNum"="T3"."LineNum" AND "T3"."CounterNum" = :CountNumber
		WHERE "T1"."DocEntry"= :DocKey ORDER BY "T1"."VisOrder";
	ELSE  --Team counters
		SELECT "T1"."CounterNum" INTO CountNumber FROM "INC4" "T1" WHERE "T1"."DocEntry" = :DocKey AND "T1"."VisOrder" = :MultipleCounterOrder;
		
		SELECT "T1"."DocEntry", "T1"."ItemCode", "T1"."ItemDesc", "T1"."WhsCode", "T1"."BinEntry", "T2"."BinCode", "T1"."InWhsQty", "T1"."Counted", "T3"."TotalQty" AS "CountQty" 
		FROM "INC1" "T1" 
		LEFT JOIN "OBIN" "T2" ON "T1"."BinEntry"="T2"."AbsEntry"
		LEFT JOIN "INC5" "T3" ON "T1"."DocEntry"="T3"."DocEntry" AND  "T1"."LineNum"="T3"."LineNum" AND "T3"."CounterNum" = :CountNumber
		WHERE "T1"."DocEntry"= :DocKey ORDER BY "T1"."VisOrder";
	END IF;
END IF;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_Inventory_Taking_Report
(
in itemCodeList_in nvarchar(15000),
in whseCodeList_in nvarchar(15000),
in binLocationList_in nvarchar(15000),
in userCodeList_in nvarchar(15000),
in employeeList_in nvarchar(15000),
in whseUsedType_in nvarchar(32),
in countDateFrom_in timestamp,
in countDateTo_in timestamp,
in postDateFrom_in timestamp,
in postDateTo_in timestamp,
in itemFrom_in nvarchar(50),
in itemTo_in nvarchar(50),
in supplierFrom_in nvarchar(16),
in supplierTo_in nvarchar(16),
in whseIncludeFrom_in nvarchar(16),
in whseIncludeTo_in nvarchar(16),
in whseExcludeFrom_in nvarchar(16),
in whseExcludeTo_in nvarchar(16),
in countingDisplayType_in nvarchar(16),
in notCountSince_in timestamp,
in postDiffPercGT_in nvarchar(16),
in whseIncludeChecked_in integer,
in whseExcludeChecked_in integer,
in binLocationChecked_in integer,
in displayCounting_in integer,
in userChecked_in integer,
in employeeChecked_in integer,
in notCountSinceChecked_in integer,
in displayPosting_in integer,
in postDiffPercGTChecked_in integer
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
AS
execSQL nvarchar(30000);
countingSQL nvarchar(15000);
postingSQL nvarchar(15000);
nullSQL nvarchar(15000);
itwSQL nvarchar(15000);
ibqSQL nvarchar(15000);
subSQL1 nvarchar(1000);
subSQL2 nvarchar(1000);
selectStr nvarchar(1000);
fromStr nvarchar(1000);
whereStr nvarchar(15000);
whereCommon nvarchar(15000);
whereItemAndWhs nvarchar(15000);
itemCodeList nvarchar(15000);
whseCodeList nvarchar(15000);
binLocationList nvarchar(15000);
userCodeList nvarchar(15000);
employeeList nvarchar(15000);
whseUsedType nvarchar(32);
countDateFrom timestamp;
countDateTo timestamp;
postDateFrom timestamp;
postDateTo timestamp;
itemFrom nvarchar(50);
itemTo nvarchar(50);
supplierFrom nvarchar(16);
supplierTo nvarchar(16);
whseIncludeFrom nvarchar(16);
whseIncludeTo nvarchar(16);
whseExcludeFrom nvarchar(16);
whseExcludeTo nvarchar(16);
countingDisplayType nvarchar(16);
notCountSince timestamp;
postDiffPercGT nvarchar(16);
whseIncludeChecked integer;
whseExcludeChecked integer;
binLocationChecked integer;
displayCounting integer;
userChecked integer;
employeeChecked integer;
notCountSinceChecked integer;
displayPosting integer;
postDiffPercGTChecked integer;
transType nvarchar(2);
typeUSR integer := 12;
typeHEM integer := 171;
BEGIN 
    itemCodeList			:= :itemCodeList_in;
	whseCodeList			:= :whseCodeList_in;
	binLocationList			:= :binLocationList_in;
	userCodeList			:= :userCodeList_in;
	employeeList			:= :employeeList_in;
	whseUsedType			:= :whseUsedType_in;
	countDateFrom			:= :countDateFrom_in;
	countDateTo				:= :countDateTo_in;
	postDateFrom			:= :postDateFrom_in;
	postDateTo				:= :postDateTo_in;
	itemFrom				:= :itemFrom_in;
	itemTo					:= :itemTo_in;
	supplierFrom			:= :supplierFrom_in;
	supplierTo				:= :supplierTo_in;
	whseIncludeFrom			:= :whseIncludeFrom_in;
	whseIncludeTo			:= :whseIncludeTo_in;
	whseExcludeFrom			:= :whseExcludeFrom_in;
	whseExcludeTo			:= :whseExcludeTo_in;
	countingDisplayType		:= :countingDisplayType_in;
	notCountSince			:= :notCountSince_in;
	postDiffPercGT			:= :postDiffPercGT_in;
	whseIncludeChecked		:= :whseIncludeChecked_in;
	whseExcludeChecked		:= :whseExcludeChecked_in;
	binLocationChecked		:= :binLocationChecked_in;
	displayCounting			:= :displayCounting_in;
	userChecked				:= :userChecked_in;
	employeeChecked 		:= :employeeChecked_in;
	notCountSinceChecked	:= :notCountSinceChecked_in;
	displayPosting			:= :displayPosting_in;
	postDiffPercGTChecked	:= postDiffPercGTChecked_in;
    whereItemAndWhs 	:= ' where T0."ItemCode" in ' || :itemCodeList;
    
    IF (LENGTH(:itemFrom) > 0) THEN 
        whereItemAndWhs := :whereItemAndWhs || ' and T0."ItemCode" >= ''' || :itemFrom || ''' ';
    END IF;
    IF (LENGTH(:itemTo) > 0) THEN 
        whereItemAndWhs := :whereItemAndWhs || ' and T0."ItemCode" <= ''' || :itemTo || ''' ';
    END IF;
    IF (:whseUsedType = 'L') THEN
    	----------- Used By Location
        whereItemAndWhs := :whereItemAndWhs || ' and T0."WhsCode" in ' || :whseCodeList;
    ELSE
   		----------- Used By Warehouse 
        IF (:whseIncludeChecked = 1) THEN 
            IF (LENGTH(:whseIncludeFrom) > 0) THEN 
                whereItemAndWhs := :whereItemAndWhs || ' and T0."WhsCode" >= ''' || :whseIncludeFrom || ''' ';
            END IF;
            IF (LENGTH(:whseIncludeTo) > 0) THEN 
                whereItemAndWhs := :whereItemAndWhs || ' and T0."WhsCode" <= ''' || :whseIncludeTo || ''' ';
            END IF;
        END IF;
        IF (:whseExcludeChecked = 1) THEN 
            IF ((LENGTH(:whseExcludeFrom) > 0) AND (LENGTH(:whseExcludeTo) > 0)) THEN 
                whereItemAndWhs := :whereItemAndWhs || ' and (';
                whereItemAndWhs := :whereItemAndWhs || ' T0."WhsCode" < ''' || :whseExcludeFrom || ''' ';
                whereItemAndWhs := :whereItemAndWhs || ' or ';
                whereItemAndWhs := :whereItemAndWhs || ' T0."WhsCode" > ''' || :whseExcludeTo || ''' ';
                whereItemAndWhs := :whereItemAndWhs || ')';
            ELSE 
                IF (LENGTH(:whseExcludeFrom) > 0) THEN 
                    whereItemAndWhs := :whereItemAndWhs || n' and T0."WhsCode" < ''' || :whseExcludeFrom || ''' ';
                END IF;
                IF (LENGTH(:whseExcludeTo) > 0) THEN 
                    whereItemAndWhs := :whereItemAndWhs || n' and T0."WhsCode" > ''' || :whseExcludeTo || ''' ';
                END IF;
            END IF;
        END IF;
    END IF;
  
    whereCommon := :whereItemAndWhs;
    IF (:binLocationChecked = 1) THEN 
        whereCommon := :whereCommon || n' and (T0."BinEntry" in ' || :binLocationList || ')';
    END IF;
    IF (LENGTH(:countDateFrom) > 0) THEN 
        whereCommon := :whereCommon || ' and T0."CountDate" >= ''' || :countDateFrom || ''' ';
    END IF;
    IF (LENGTH(:countDateTo) > 0) THEN 
        whereCommon := :whereCommon || ' and T0."CountDate" <= ''' || :countDateTo || ''' ';
    END IF;
    IF (:displayCounting = 1) THEN 
        transType := 'C';
        selectStr := 'Select ''' || :transType || ''' as "TransType", ';
        selectStr := :selectStr ||
        			' T0."DocEntry",
        			  T1."DocNum",
        			  T0."VisOrder" as "LineNum",
        			  T0."ItemCode",
        			  T0."ItemDesc",
        			  T0."WhsCode",
        			  T0."BinEntry",
        			  T2."BinCode",
        			  T0."InWhsQty",
        			  T0."CountQty",
        			  T0."Difference",
        			  T0."DiffPercen" as "DiffPercnt",
        			  NULL as "Price",
        			  NULL as "Total",
        			  NULL as "Currency",
        			  T0."CountDate",
        			  NULL as "PostDate",
        			  T1."Status",
        			  T0."LineStatus"';
        fromStr := ' FROM INC1 T0 join OINC T1 on T0."DocEntry" = T1."DocEntry" left outer join OBIN T2 on T0."BinEntry = T2."AbsEntry"';
        whereStr := :whereCommon;
        IF (LENGTH(:supplierFrom) > 0) THEN 
            whereStr := :whereStr || ' and T0."PrefVendor" >= ''' || :supplierFrom || ''' ';
        END IF;
        IF (LENGTH(:supplierTo) > 0) THEN 
            whereStr := :whereStr || ' and T0."PrefVendor" <= ''' || :supplierTo || ''' ';
        END IF;
        IF (:userChecked = 1) THEN 
            whereStr := :whereStr || ' and ((';
            whereStr := :whereStr || ' T1."Taker1Type" = ' || :typeUSR;
            whereStr := :whereStr || ' and T1."Taker1Id" in ' || :userCodeList;
            whereStr := :whereStr || ') or (';
            whereStr := :whereStr || ' T1."Taker2Type" = ' || :typeUSR;
            whereStr := :whereStr || ' and T1."Taker2Id" in ' || :userCodeList;
            whereStr := :whereStr || '))';
        END IF;
        IF (:employeeChecked = 1) THEN 
            whereStr := :whereStr || ' and ((';
            whereStr := :whereStr || ' T1."Taker1Type" = ' || :typeHEM;
            whereStr := :whereStr || ' and T1."Taker1Id" in ' || :employeeList;
            whereStr := :whereStr || ') or (';
            whereStr := :whereStr || ' T1."Taker2Type" = ' || :typeHEM;
            whereStr := :whereStr || ' and T1."Taker2Id" in ' || :employeeList;
            whereStr := :whereStr || '))';
        END IF;
        IF (:countingDisplayType = 'O' OR :countingDisplayType = 'C') THEN 
            whereStr := :whereStr || ' and T0."LineStatus" = ''' || :countingDisplayType || ''' ';
        END IF;
        IF (:notCountSinceChecked = 1 AND LENGTH(:notCountSince) > 0) THEN 
            whereStr := :whereStr || ' and (';
            whereStr := :whereStr || ' T0."Counted" = ''' || 'N' || ''' ';
            whereStr := :whereStr || ' and ';
            whereStr := :whereStr || ' T0."CountDate" >= ''' || :notCountSince || ''' ';
            whereStr := :whereStr || ')';
        END IF;
        countingSQL := :selectStr || :fromStr || :whereStr;
    END IF;
    IF (:displayPosting = 1) THEN 
        transType := 'P';
        selectStr := 'Select ''' || :transType || ''' as "TransType", ';
        selectStr := :selectStr || 
        			' T0."DocEntry", 
        			T1."DocNum", 
        			T0."DocLineNum" as "LineNum", 
        			T0."ItemCode", 
        			T0."ItemName" as "ItemDesc", 
        			T0."WhsCode", 
        			T0."BinEntry", 
        			T2."BinCode", 
        			T0."OnHandBef" as "InWhsQty", 
        			T0."CountQty", 
        			T0."Quantity" as "Difference", 
        			T0."DiffPercnt", 
        			T0."Price", 
        			T0."DocTotal" as "Total", 
        			T0."Currency", 
        			T0."CountDate", 
        			T1."DocDate" as "PostDate", 
        			T1."Status", 
        			NULL as "LineStatus"';
        fromStr := ' FROM IQR1 T0 join OIQR T1 on T0."DocEntry" = T1."DocEntry" left outer join OBIN T2 on T0."BinEntry" = T2."AbsEntry"';
        whereStr := :whereCommon;
        IF (LENGTH(:supplierFrom) > 0) THEN 
            whereStr := :whereStr || ' and T0."CardCode" >= ''' || :supplierFrom || ''' ';
        END IF;
        IF (LENGTH(:supplierTo) > 0) THEN 
            whereStr := :whereStr || ' and T0."CardCode" <= ''' || :supplierTo || ''' ';
        END IF;
        IF (LENGTH(:postDateFrom) > 0) THEN 
            whereStr := :whereStr || ' and T1."DocDate" >= ''' || :postDateFrom || ''' ';
        END IF;
        IF (LENGTH(:postDateTo) > 0) THEN 
            whereStr := :whereStr || ' and T1."DocDate" <= ''' || :postDateTo || ''' ';
        END IF;
        IF (:postDiffPercGTChecked = 1 AND :postDiffPercGT <> '') THEN 
            whereStr := :whereStr || ' and T0."DiffPercnt" >= ' || :postDiffPercGT;
        END IF;
        postingSQL := :selectStr || :fromStr || :whereStr;
    END IF;
    nullSQL := 'Select Cast(NULL as nvarchar(1)) as "TransType", NULL as "DocEntry", NULL as "DocNum", NULL as "LineNum", Cast(NULL as char(20)) as "ItemCode", '||
    			'Cast(NULL as char(200)) as "ItemDesc", Cast(NULL as char(8)) as "WhsCode", NULL as "BinEntry", Cast(NULL as char(228)) as "BinCode", NULL as "InWhsQty", '||
    			'NULL as "CountQty", NULL as "Difference", NULL as "DiffPercnt", NULL as "Price", NULL as "Total", Cast(NULL as char(20)) as "Currency", '||
    			'Cast(NULL as DateTime) as "CountDate", Cast(NULL as DateTime) as "PostDate", Cast(NULL as nvarchar(1)) as "Status", Cast(NULL as nvarchar(1)) as "LineStatus" from DUMMY';
    execSQL := :nullSQL;
    IF (:displayCounting = 1 AND :displayPosting = 1) THEN 
        execSQL := :execSQL || ' union all ' || :countingSQL || ' union all ' || :postingSQL;
    ELSE 
        IF (:displayCounting = 1) THEN 
            execSQL := :execSQL || ' union all ' || :countingSQL;
        ELSE 
            IF (:displayPosting = 1) THEN 
                execSQL := :execSQL || ' union all ' || :postingSQL;
            END IF;
        END IF;
    END IF;
    IF (:notCountSinceChecked = 1 AND LENGTH(:notCountSince) > 0) THEN
    	------------------------------Load not counted items from oitw that the record is not in INC1 table--------------------------------------------------------------------------------- 
        selectStr := 'Select NULL as "TransType", NULL as "DocEntry", NULL as "DocNum", NULL as "LineNum", T0."ItemCode", T1."ItemName" as "ItemDesc", T0."WhsCode", '|| 
        				'NULL as "BinEntry", Cast(NULL as char(228)) as "BinCode", T0."OnHand" as "InWhsQty", NULL as "CountQty", NULL as "Difference", NULL as "DiffPercnt", '||
        				'NULL as "Price", NULL as "Total", Cast(NULL as char(20)) as "Currency", Cast(NULL as DateTime) as "CountDate", Cast(NULL as DateTime) as "PostDate", '||
        				'Cast(NULL as nvarchar(1)) as "Status", Cast(NULL as nvarchar(1)) as "LineStatus"';
        fromStr := ' from OITW T0 join OITM T1 on T0."ItemCode" = T1."ItemCode"';
        subSQL1 := ' and not exists (' || 'select T2."ItemCode", T2."WhsCode" from INC1 T2 where T0."ItemCode" = T2."ItemCode" and T0."WhsCode" = T2."WhsCode" and T2."BinEntry" is NULL '||
        			'GROUP BY T2."ItemCode", T2."WhsCode" HAVING Max(T2."CountDate")<=''' || :notCountSince || ''')';
        subSQL2 := ' and not exists (' || ' select T4."ItemCode", T4."WhsCode" from IQR1 T4 where T0."ItemCode" = T4."ItemCode" and T0."WhsCode" = T4."WhsCode" and T4."BinEntry" is NULL '||
        			'GROUP BY T4."ItemCode", T4."WhsCode" HAVING Max(T4."CountDate")<= ''' || :notCountSince || ''')';
        itwSQL := :selectStr || :fromStr || :whereItemAndWhs || :subSQL1 || :subSQL2;
        ------------------------------Load not counted items from OIBQ that the warehouse is bin active and the record is not in INC1 table------------------------------------------     
        selectStr := 'Select NULL as "TransType", NULL as "DocEntry", NULL as "DocNum", NULL as "LineNum", T0."ItemCode", T1."ItemName" as "ItemDesc", T0."WhsCode", T2."AbsEntry" as "BinEntry", T2."BinCode", '|| 
 					'T0."OnHandQty" as "InWhsQty", NULL as "CountQty", NULL as "Difference", NULL as "DiffPercnt", NULL as "Price", NULL as "Total", Cast(NULL as char(20)) as "Currency", Cast(NULL as DateTime) as "CountDate", '||
 					'Cast(NULL as DateTime) as "PostDate", Cast(NULL as nvarchar(1)) as "Status", Cast(NULL as nvarchar(1)) as "LineStatus"';
        fromStr := ' from OIBQ T0 join OITM T1 on T0."ItemCode" = T1."ItemCode" join OBIN T2 on T0."BinAbs" = T2."AbsEntry"';
        subSQL1 := ' and not exists (' || 'select T3."ItemCode", T3."WhsCode" from INC1 T3 where T0."ItemCode" = T3."ItemCode" and T0."WhsCode" = T3."WhsCode" and T0."BinAbs" = T3."BinEntry" '||
        			' GROUP BY T3."ItemCode", T3."WhsCode" HAVING Max(T3."CountDate")<= ''' || :notCountSince || ''')';
        subSQL2 := ' and not exists (' || ' select T5."ItemCode", T5."WhsCode" from IQR1 T5 where T0."ItemCode" = T5."ItemCode" and T0."WhsCode" = T5."WhsCode" and T0."BinAbs" = T5."BinEntry" '|| 
        			' GROUP BY T5."ItemCode", T5."WhsCode" HAVING Max(T5."CountDate")<= ''' || :notCountSince || ''')';
        ibqSQL := :selectStr || :fromStr || :whereItemAndWhs || :subSQL1 || :subSQL2;
        IF (:binLocationChecked = 1) THEN 
            ibqSQL := :ibqSQL || ' and (T2."AbsEntry" in ' || :binLocationList || ')';
        END IF;
        execSQL := :nullSQL || ' union all ' || :itwSQL || ' union all ' || :ibqSQL;
    END IF;
    execute immediate(:execSQL);
	--select :execSQL from dummy;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

Create Procedure CRSP_INVENTORY_TURNOVER_RATE(
	In FromDate NVarChar(20), 
	In ToDate nVarChar(20), 
	In Items NCLOB
	)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
As 
	IsExists INTEGER := 0;
BEGIN
	call _TmSp_ValidateSpParam(FromDate);
	call _TmSp_ValidateSpParam(ToDate);
	call _TmSp_ValidateSpParam(Items);
	
	-- Delete existing temp table if it exists
	SELECT COUNT(*) INTO IsExists 
	FROM M_TEMPORARY_TABLES
	WHERE TABLE_NAME = '#CRSP_INVENTORY_ITEMS_LOCAL' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection; 
	
	IF :IsExists > 0 THEN
		DROP TABLE #CRSP_INVENTORY_ITEMS_LOCAL;
	END IF;
	
	CREATE LOCAL TEMPORARY COLUMN TABLE #CRSP_INVENTORY_ITEMS_LOCAL ("ItemCode" NVARCHAR(50));
	
	-- Insert selected result to temp table created above
	Exec ('INSERT INTO #CRSP_INVENTORY_ITEMS_LOCAL SELECT T0."ItemCode" FROM OITM T0 Where ' || :items);
	
	-- Fetch IssueQty from OILM instead of OIVL for scenario like "Return" based on "Delivery"
	with cte1
	as
	(
		select "MessageID", "DocEntry", "TransType", "DocLineNum", "ActionType", T0."ItemCode", "LocCode", "BaseType", "BaseAbsEnt", "BaseLine", "LocType",
		case when "ActionType" = 1 then "EffectQty"
		when "ActionType" = 2 then -"EffectQty"	end as "EffectQty"
		from oilm T0
		Join #CRSP_INVENTORY_ITEMS_LOCAL T1 On T0."ItemCode" = T1."ItemCode"
		where "AccumType"=1 and "ActionType" in (1,2) and "DocDate" Between :FromDate And :ToDate
		and not exists (select 'a' from oilm U0 where u0."TransType"=u0."BaseType" and u0."TransType" in (13,14,15,16,18,19,20,21)
		and u0."BaseType"=t0."TransType" and u0."BaseAbsEnt"=t0."DocEntry" and u0."BaseLine"=t0."DocLineNum")
		and not(t0."TransType"=t0."BaseType" and t0."TransType" in (13,14,15,16,18,19,20,21))
	),
	cte2
	as
	(
		select
			case when t1."TransType" is null then t0."TransType" else t0."BaseType" end as "TransType",
			case when t1."DocEntry" is null then t0."DocEntry" else t0."BaseAbsEnt" end as "DocEntry",
			case when t1."DocLineNum" is null then t0."DocLineNum" else t0."BaseLine" end as "DocLineNum",
			t0."ItemCode", t0."LocCode", t0."LocType", t0."EffectQty"
		from cte1 t0 left join cte1 t1
		on t0."BaseType" = t1."TransType" and t0."BaseAbsEnt" = t1."DocEntry" and t0."BaseLine" = t1."DocLineNum"
	)
	
	select 
			T1."LocType" as LocType,
			T1."LocCode" as LocCode,
			T1."ItemCode" as ItemCode,
			T1."CloseStock" as CloseStock,
			T4."OpenStock"as OpenStock,
			T5."IssueQty" as IssueQty,
			T6."LastDate" as LastDate,
			T2."OnHand" as OnHandTotal,
			T6."OnHand" as OnHand,
			T6."MinStock" as MinStock,
			T6."WhsCode" as WhsCode,
			T3."WhsName" as WhsName,
			T2."ItmsGrpCod" as ItmsGrpCod,
			T2."ItemName" as ItemName,
			T2."MinLevel" as MinLevel,
			T2."ByWh" as ByWh,
			T2."InvntryUom" as InvntryUom,
			T2."LeadTime" as LeadTime,
			T2."ItmsGrpNam" as ItmsGrpNam
	from
	(
		Select	"LocType", "LocCode", "ItemCode", Sum("InQty" - "OutQty") as "CloseStock" 
		From "OIVL"
		Where TO_DATE("DocDate") <= TO_DATE(:ToDate)  
		Group by "LocType", "LocCode", "ItemCode"
	) T1 /*CloseStock*/
	Join
	(
		SELECT	T0."ItemCode",
				T0."ItmsGrpCod", 
				T0."ItemName", 
				T0."OnHand",
				T0."MinLevel", 
				T0."ByWh", 
				T0."InvntryUom", 
				T0."LeadTime",
				T1."ItmsGrpNam"
		From "OITM"	T0
		Join "OITB"	T1 On	T0."ItmsGrpCod" = T1."ItmsGrpCod"
		Join #CRSP_INVENTORY_ITEMS_LOCAL T2 On T0."ItemCode" = T2."ItemCode"		
	) T2 /*OITM & OITB*/
		on	T1."ItemCode" = T2."ItemCode"
	Join
	(
		SELECT T0."WhsCode", T0."WhsName" 
		From "OWHS" T0
	) T3 /*OWHS*/ on	T1."LocCode" = T3."WhsCode"
	left join
	(
		Select	"LocType", "LocCode", "ItemCode", Sum("InQty" - "OutQty") as "OpenStock" 
		From "OIVL"
		Where TO_DATE("DocDate") < TO_DATE(:FromDate) 
		Group by "LocType", "LocCode", "ItemCode"
	) T4 /*OpenStock*/
	on	T1."LocType" = T4."LocType"
	and	T1."LocCode" = T4."LocCode"
	and	T1."ItemCode" = T4."ItemCode"
	left join
	(
		select t0."ItemCode", t0."LocCode", t0."LocType", ABS(sum(t0."EffectQty")) as "IssueQty" from
		(
			select "ItemCode", "LocCode", "LocType", sum("EffectQty") as "EffectQty" from cte2 
			group by "TransType", "DocEntry", "DocLineNum","ItemCode", "LocCode", "LocType"
			having sum("EffectQty") < 0
		) as t0
		group by t0."ItemCode", t0."LocCode", t0."LocType"
	) T5 /*IssueQty*/
	on	T1."LocType" = T5."LocType"
	and	T1."LocCode" = T5."LocCode"
	and	T1."ItemCode" = T5."ItemCode"
	left join
	(
		select T1."LocType", T1."LocCode", T1."ItemCode", T1."LastDate", 
			   T2."WhsCode", T2."OnHand", T2."MinStock" from
		(
			Select	"LocType", "LocCode", "ItemCode", max(TO_DATE("DocDate")) as "LastDate"
			From "OIVL"
			Where "InQty" > 0 
			Group By "LocType", "LocCode", "ItemCode"
		) T1 /*LastDate*/
		join
		(
			SELECT "ItemCode", "WhsCode", "OnHand", "MinStock" From "OITW"
		) T2 /*OITW*/
		on	T1."ItemCode" = T2."ItemCode" and T1."LocCode" = T2."WhsCode"
	) T6
	on	T1."LocType" = T6."LocType"
	and	T1."LocCode" = T6."LocCode"
	and	T1."ItemCode" = T6."ItemCode";
	
	--DROP TABLE #CRSP_INVENTORY_ITEMS_LOCAL;	/* cause client of rev48 disconnected */
	
 END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_InvoiceLedger_BR_enUS (in DateTypeIn varchar(256), in FromDateIn timestamp, in ToDateIn timestamp) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
CompnyName nvarchar(200);
MainCurncy nvarchar(3);
Country nvarchar(3);

DateType varchar(256);
FromDate timestamp;
ToDate timestamp;
BEGIN /*
    
***** General Information *****
Name: OINV_InvoiceLedger 
Description: Return A/R Invoices and A/R Credit Memos in a certain Date Range

Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22
*/
    /* Internal Variables */
    SELECT 
    (SELECT "CompnyName" 
    FROM OADM) INTO CompnyName FROM DUMMY;
    
    SELECT 
    (SELECT UPPER("MainCurncy") 
    FROM OADM) INTO MainCurncy FROM DUMMY;
    
    
    SELECT 
    (SELECT "LawsSet" 
    FROM CINF) INTO Country FROM DUMMY;
    
    
    /* Date Type to set the filter and sort by. Possible values are DocDate, TaxDate and DocDueDate. */
    DateType := DateTypeIn;
    /* Date Filter From and To Dates. Format 'YYYYMMDD' */
    FromDate := FromDateIn;
    ToDate := ToDateIn;
    
    SELECT :CompnyName AS "CompanyName", :Country AS "Country", 
        CASE :Country 
            WHEN 'BR' THEN 
            (SELECT COUNT(DISTINCT ("TaxCode")) 
            FROM INV1 
            WHERE "DocEntry" = OINV."DocEntry") 
            ELSE 
            (SELECT COUNT(DISTINCT ("VatGroup")) 
            FROM INV1 
            WHERE "DocEntry" = OINV."DocEntry") 
        END AS "VatCount", OINV."DocEntry", OINV."DocNum", OINV."ObjType", OINV."CardCode", OCRD."CardName", 
        OINV."DocDate", OINV."TaxDate", OINV."DocDueDate", 
        CASE :MainCurncy 
            WHEN UPPER(OINV."DocCur") THEN UPPER(OINV."DocCur") 
            ELSE :MainCurncy 
        END AS "DocCur", OINV."DocTotal" - OINV."VatSum" AS "DocTotalNet", OINV."VatSum", OINV."DocTotal", 
        CASE :MainCurncy 
            WHEN UPPER(OINV."DocCur") THEN '' 
            ELSE UPPER(OINV."DocCur") 
        END AS "DocCurFC", OINV."DocTotalFC" - OINV."VatSumFC" AS "DocTotalFCNet", OINV."VatSumFC", 
        OINV."DocTotalFC", OINV."DiscPrcnt", OINV."DiscSum", OINV."DiscSumFC", OINV."DpmAmnt", OINV."DpmAmntFC", 
        OINV."TotalExpns", OINV."TotalExpFC", OINV."TaxOnExp", OINV."TaxOnExpFc", OINV."RoundDif", OINV."RoundDifFC", 
        OINV."FolioPref", OINV."FolioNum", OINV."Model", OINV."SeqCode", OINV."Serial", OINV."SeriesStr", 
        OINV."SubStr" 
    FROM OINV 
        INNER JOIN OCRD ON OINV."CardCode" = OCRD."CardCode" 
    WHERE 
        CASE :DateType 
            WHEN 'DocDueDate' THEN OINV."DocDueDate" 
            WHEN 'TaxDate' THEN OINV."TaxDate" 
            ELSE OINV."DocDate" 
        END >= :FromDate AND 
        CASE :DateType 
            WHEN 'DocDueDate' THEN OINV."DocDueDate" 
            WHEN 'TaxDate' THEN OINV."TaxDate" 
            ELSE OINV."DocDate" 
        END <= :ToDate 
    UNION 
    SELECT :CompnyName AS "CompanyName", :Country AS "Country", 
        CASE :Country 
            WHEN 'BR' THEN 
            (SELECT COUNT(DISTINCT ("TaxCode")) 
            FROM RIN1 
            WHERE "DocEntry" = ORIN."DocEntry") 
            ELSE 
            (SELECT COUNT(DISTINCT ("VatGroup")) 
            FROM RIN1 
            WHERE "DocEntry" = ORIN."DocEntry") 
        END AS "VatCount", ORIN."DocEntry", ORIN."DocNum", ORIN."ObjType", ORIN."CardCode", OCRD."CardName", 
        ORIN."DocDate", ORIN."TaxDate", ORIN."DocDueDate", 
        CASE :MainCurncy 
            WHEN UPPER(ORIN."DocCur") THEN UPPER(ORIN."DocCur") 
            ELSE :MainCurncy 
        END AS "DocCur", (ORIN."DocTotal" - ORIN."VatSum") * -1 AS "DocTotalNet", ORIN."VatSum" * -1, 
        ORIN."DocTotal" * -1, 
        CASE :MainCurncy 
            WHEN UPPER(ORIN."DocCur") THEN '' 
            ELSE UPPER(ORIN."DocCur") 
        END AS "DocCurFC", (ORIN."DocTotalFC" - ORIN."VatSumFC") * -1 AS "DocTotalFCNet", ORIN."VatSumFC" * -1, 
        ORIN."DocTotalFC" * -1, ORIN."DiscPrcnt", ORIN."DiscSum" * -1, ORIN."DiscSumFC" * -1, ORIN."DpmAmnt" * -1, 
        ORIN."DpmAmntFC" * -1, ORIN."TotalExpns" * -1, ORIN."TotalExpFC" * -1, ORIN."TaxOnExp" * -1, 
        ORIN."TaxOnExpFc", ORIN."RoundDif" * -1, ORIN."RoundDifFC" * -1, ORIN."FolioPref", ORIN."FolioNum", 
        ORIN."Model", ORIN."SeqCode", ORIN."Serial", ORIN."SeriesStr", ORIN."SubStr" 
    FROM ORIN 
        INNER JOIN OCRD ON ORIN."CardCode" = OCRD."CardCode" 
    WHERE 
        CASE :DateType 
            WHEN 'DocDueDate' THEN ORIN."DocDueDate" 
            WHEN 'TaxDate' THEN ORIN."TaxDate" 
            ELSE ORIN."DocDate" 
        END >= :FromDate AND 
        CASE :DateType 
            WHEN 'DocDueDate' THEN ORIN."DocDueDate" 
            WHEN 'TaxDate' THEN ORIN."TaxDate" 
            ELSE ORIN."DocDate" 
        END <= :ToDate;
    /* Fields specific for CL, MX */
    /* Fields Specific for BR */
    /* BR - Document Header */
    /* Fields specific for CL, MX */
    /* Fields Specific for BR */
    /* BR - Document Header */
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE CRSP_Monthly_Customer_Status_Report
(
in DateTypeIn nvarchar(1),
in FromDateIn datetime,
in ToDateIn datetime,
in CustomerIdsIn nclob
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
execSQL 		nclob;
DateType 		nvarchar(1);
FromDate 		datetime;
ToDate 			datetime;
targetField		VarChar(50);	--- The total field in the global table (CRSP_Monthly_Customer_Status_Report_BPMonthly)
sourceField		VarChar(200);	--- The total field from the source tables (RDR, DLN, INV, ...)
dateField		varChar(12);	--- Date field from source tables
date_parts		varchar(200);
dateInSpan		varchar(200);
newLine			char(2);
tblName			Char(4);
_insert			varchar(200);
_select			varchar(200);
_from			Char(6);
_where			varchar(1000);
parameters		nvarchar(100);
_lastMonthBegin DateTime;
_lastMonthEnd	DateTime;
GrossBySal		nvarchar(1);
_DateVar		Date;

BEGIN
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:DateTypeIn);    
	call _TmSp_ValidateSpParam(:CustomerIdsIn);  
DateType := :DateTypeIn;
FromDate := :FromDateIn;
ToDate := :ToDateIn;

delete from "CRSP_Monthly_Customer_Status_Report_Customers";
delete from "CRSP_Monthly_Customer_Status_Report_BPMonthly";
delete from "CRSP_Monthly_Customer_Status_Report_MonthBegin";
delete from "CRSP_Monthly_Customer_Status_Report_TblResult";

execSQL:= '
Insert Into "CRSP_Monthly_Customer_Status_Report_Customers"
	Select "CardCode","CardName","GroupCode","Balance" From OCRD where "CardCode" in ' || :CustomerIdsIn;
	
exec (:execSQL);

IF :DateType = N'P' THEN
	dateField := 'T1."DocDate"';
ELSE
	dateField := 'T1."TaxDate"';
END IF;

 -- Get the month before the from date for sales order growth calculation
_lastMonthBegin := ADD_MONTHS(ADD_DAYS(:FromDate, 1 - dayofmonth(:FromDate)), -1); 
_lastMonthEnd := ADD_DAYS(:FromDate, 1 - dayofmonth(:FromDate) - 1); 
	
date_parts := 'Year(' || :dateField || ')' || ',Month(' || :dateField || ')';
dateInSpan := ' ''' || :FromDate || ''' <= ' || :dateField || ' and ' || :dateField || ' <= ''' || ToDate || ''' ';
newLine := char(9) || char(10);

_insert := 'INSERT INTO "CRSP_Monthly_Customer_Status_Report_BPMonthly" (YearParam, MonthParam, CardCode, CardName, GroupCode, ';
_select := ') Select ' || :date_parts || ', T2.CardCode, Max(T2.CardName), Max(T2.GroupCode), ';
_from := ' From ';

-- Ordered
_where := ' T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 On T1."CardCode" = T2.CardCode
Where T1."CANCELED" = ''N'' and ('|| :dateInSpan || ' Or ''' || :_lastMonthBegin || ''' <= ' || :dateField || ' and ' || :dateField || ' <= ''' || :_lastMonthEnd || ''')
Group By T2.CardCode,' || :date_parts;

tblName := 'ORDR';
targetField := 'RDRTotal, GrossProfit';
sourceField := 'Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns" + T1."WTSum" - T1."RoundDif"), Sum(T1."GrosProfit")';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);

 -- Order's Gross Base Total 
targetField := 'GrossBase';
select "GrossBySal" into GrossBySal from OADM;
IF :GrossBySal = 'Y' THEN
	sourceField := 'Sum(T3."LineTotal") - Sum(T1."DiscSum")';
ELSE
	sourceField := 'Sum(T3."GPTtlBasPr")';
END IF;

_where := ' T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 On T1."CardCode" = T2.CardCode
Join RDR1 T3 on T1."DocEntry" = T3."DocEntry"
Where T1."CANCELED" = ''N'' and ('|| :dateInSpan || ' Or ''' || :_lastMonthBegin || ''' <= ' || :dateField || ' and ' || :dateField || ' <= ''' || :_lastMonthEnd || ''')
Group By T2.CardCode,' || :date_parts;
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


----------- Set the SQL components for Documents
_where := ' T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 On T1."CardCode" = T2.CardCode
Where ' || :dateInSpan || ' Group By T2.CardCode,' || :date_parts;

-- Delivered
tblName := 'ODLN';
targetField := 'DLNTotal';
sourceField := 'Sum(T1."DocTotal" - T1."VatSum" - T1."TotalExpns")';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


-- Returned
tblName := 'ORDN';
targetField := 'RDNTotal';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


-- Invoiced
_where := ' T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 On T1."CardCode" = T2.CardCode
Join JDT1 T3 on T1."TransId" = T3."TransId" and T3."ShortName" = T2.CardCode
Where ' || :dateInSpan || ' Group By T2.CardCode,' || :date_parts;

tblName := 'OINV';
targetField := 'INVTotal';
sourceField := 'Sum(T3."Debit" - T3."Credit")';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


tblName := 'OCSI';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);

tblName := 'OCSV';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


-- Credited
tblName := 'ORIN';
targetField := 'RINTotal';
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


-- Collected
tblName := 'JDT1';

IF :DateType = N'P' THEN
	dateField := 'T1."RefDate"';
ELSE
	dateField := 'T1."TaxDate"';
END IF;
 
date_parts := 'Year(' || :dateField || ')' || ',Month(' || :dateField || ')';
dateInSpan := '''' || :FromDate || ''' <= ' || :dateField || ' and ' || :dateField || ' <= ''' || :ToDate || '''';
_select := ')
Select ' || :date_parts || ', T2.CardCode, Max(T2.CardName), Max(T2.GroupCode), ';

targetField := 'RCTTotal';
SourceField := 'Sum(T4."DocTotal")';
_where := ' T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 On T1."ShortName" = T2.CardCode
Join OJDT T3 On T1."TransId" = T3."TransId" And T1."TransType" = 24 And T3."StornoToTr" IS NULL
Join ORCT T4 On T3."CreatedBy" = T4."DocEntry"
Where ' || :dateInSpan || ' Group By T2.CardCode,' || :date_parts;
execSQL := :_insert || :targetField || :_select || :sourceField || :newLine || :_from || :tblName || :_where;

exec(:execSQL);


---------------------------------------------------------
-- Create the table of Month Beginings between the FromDate and ToDate
_DateVar := ADD_MONTHS(ADD_DAYS(:FromDate, 1 - dayofmonth(:FromDate)), 1); --DATEADD(M, DateDiff(M, 0, @_FromDate) + 1, 0)

WHILE :_DateVar <= :ToDate DO
	INSERT INTO "CRSP_Monthly_Customer_Status_Report_MonthBegin" Select :_DateVar from DUMMY;
	_DateVar := ADD_MONTHS(:_Datevar, 1); 
END WHILE;


IF :DateType = 'P' THEN
	INSERT INTO "CRSP_Monthly_Customer_Status_Report_BPMonthly" (YearParam, MonthParam, CardCode, CardName, GroupCode, OpenBalance)
	Select Year(T0.Date), Month(T0.Date), T2.CardCode, Max(T2.CardName), Max(T2.GroupCode), Max(T2.Balance) - Sum(T1."Debit"- T1."Credit")
	From JDT1 T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 on T1."ShortName" = T2.CardCode --COLLATE database_default
	Join ( Select :FromDate as Date from DUMMY
	Union
	Select MonthBegin from "CRSP_Monthly_Customer_Status_Report_MonthBegin"
	) as T0 
	on T1."RefDate" >= T0.Date 
	Group By T2.CardCode, Year(T0.Date), Month(T0.Date);
ELSE
	INSERT INTO "CRSP_Monthly_Customer_Status_Report_BPMonthly" (YearParam, MonthParam, CardCode, CardName, GroupCode, OpenBalance)
	Select Year(T0.Date), Month(T0.Date), T2.CardCode, Max(T2.CardName), Max(T2.GroupCode), Max(T2.Balance) - Sum(T1."Debit"- T1."Credit") 
	From JDT1 T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 on T1."ShortName" = T2.CardCode --COLLATE database_default
	Join ( Select :FromDate as Date from DUMMY
	 Union
	Select MonthBegin from "CRSP_Monthly_Customer_Status_Report_MonthBegin" 
	) as T0 
	on T1."TaxDate" >= T0.Date 
	Group By T2.CardCode, Year(T0.Date), Month(T0.Date);
END IF;

-- Close Balance 
If :DateType = 'P' THEN
	INSERT INTO "CRSP_Monthly_Customer_Status_Report_BPMonthly" (YearParam, MonthParam, CardCode, CardName, GroupCode, CloseBalance)
	Select Year(T0.Date), Month(T0.Date), T2.CardCode, Max(T2.CardName), Max(T2.GroupCode), Max(T2.Balance) - Sum(T1."Debit"- T1."Credit") 
	From JDT1 T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 on T1."ShortName" = T2.CardCode --COLLATE database_default
	Join ( Select ADD_DAYS(MonthBegin, -1) as Date from "CRSP_Monthly_Customer_Status_Report_MonthBegin"
	Where ADD_DAYS(MonthBegin, -1) >= :FromDate
	Union 
	Select :ToDate from DUMMY) as T0 
	on T1."RefDate" > T0.Date 
	Group By T2.CardCode, Year(T0.Date), Month(T0.Date);
ELSE
	INSERT INTO "CRSP_Monthly_Customer_Status_Report_BPMonthly" (YearParam, MonthParam, CardCode, CardName, GroupCode, CloseBalance)
	Select Year(T0.Date), Month(T0.Date), T2.CardCode, Max(T2.CardName), Max(T2.GroupCode), Max(T2.Balance) - Sum(T1."Debit" - T1."Credit") 
	From JDT1 T1 Join "CRSP_Monthly_Customer_Status_Report_Customers" T2 on T1."ShortName" = T2.CardCode --COLLATE database_default
	Join ( Select ADD_DAYS(MonthBegin, -1) as Date from "CRSP_Monthly_Customer_Status_Report_MonthBegin" 
	Where ADD_DAYS(MonthBegin, -1) >= :FromDate
	Union 
	Select :ToDate from DUMMY) as T0 
	on T1."TaxDate" > T0.Date 
	Group By T2.CardCode, Year(T0.Date), Month(T0.Date);
END IF;


-----------------------------------------------------------------------------------------------------------------

Insert Into "CRSP_Monthly_Customer_Status_Report_TblResult"
select YearParam, MonthParam, CardCode, Max(CardName)as CardName, Max(GroupCode) as GroupCode, 
	Sum(RDRTotal) as RDRTotal, Sum(GrossBase) as GrossBase, Sum(GrossProfit) as GrossProfit, 
	Sum(DLNTotal) as DLNTotal, Sum(RDNTotal) as RDNTotal, 
	Sum(INVTotal) as INVTotal, Sum(RINTotal) as RINTotal, Sum(RCTTotal) as RCTTotal,
	Sum(OpenBalance) as OpenBalance, Sum(CloseBalance) as CloseBalance
from "CRSP_Monthly_Customer_Status_Report_BPMonthly" 
Group By CardCode, YearParam, MonthParam 
Order By CardCode Asc, YearParam Desc, MonthParam Desc;

-- Udpate the OpenBalance and CloseBalance if they are NULL. 
-- NOTE: The month before the from date is not necessary to update.
Update "CRSP_Monthly_Customer_Status_Report_TblResult" T0
Set T0.OpenBalance = (Select  T1.Balance From "CRSP_Monthly_Customer_Status_Report_Customers" T1 
Where T1.CardCode = T0.CardCode )
WHERE T0.OpenBalance Is NULL And T0.YearParam >= YEAR(:FromDate) And T0.MonthParam >= Month(:FromDate);



Update "CRSP_Monthly_Customer_Status_Report_TblResult" T0
Set CloseBalance = (Select T1.Balance From "CRSP_Monthly_Customer_Status_Report_Customers" T1
Where T0.CardCode = T1.CardCode )
WHERE T0.CloseBalance Is NULL And YearParam >= YEAR(:FromDate) And MonthParam >= Month(:FromDate);

Select * From "CRSP_Monthly_Customer_Status_Report_TblResult";

delete from "CRSP_Monthly_Customer_Status_Report_Customers";
delete from "CRSP_Monthly_Customer_Status_Report_BPMonthly";
delete from "CRSP_Monthly_Customer_Status_Report_MonthBegin";
delete from "CRSP_Monthly_Customer_Status_Report_TblResult";
END;

