CREATE PROCEDURE CRSP_OpenItemsList_BR_enUS (in CardType nvarchar(1), in DateType varchar(256), in FromDate timestamp, in ToDate timestamp) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
CompanyName nvarchar(200);
MainCurncyVar varchar(3);
SysCurrncy varchar(3);
BEGIN 
/*    
***** General Information *****
Name: OJDT_BPCalc 
Description: Return Journal Entries related to Invoices, Credit Memos and Payments for Business Partners

Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22
*/
	
    /* Internal Variables */
    SELECT 
    (SELECT "CompnyName" 
    FROM OADM) INTO CompanyName FROM DUMMY;
	
    SELECT 
    (SELECT TOP 1 T2."MainCurncy" 
    FROM OADM T2) INTO MainCurncyVar FROM DUMMY;
	
    SELECT 
    (SELECT TOP 1 T2."SysCurrncy" 
    FROM OADM T2) INTO SysCurrncy FROM DUMMY;
	
	
    SELECT :CompanyName AS "CompanyName", T1."ShortName", T2."CardName", T2."CardCode", T2."CardFName", 
        T2."CardType", T1."Ref1", T0."Number", T0."DocSeries", T0."BaseRef", 
        CASE T1."TransType" 
            WHEN 13 THEN T3."DocNum" 
            WHEN 14 THEN T4."DocNum" 
            WHEN 18 THEN T7."DocNum" 
            WHEN 19 THEN T8."DocNum" 
            ELSE T1."BaseRef" 
        END AS "BaseDocNum", 
        CASE T1."TransType" 
            WHEN 13 THEN T3."DocEntry" 
            WHEN 14 THEN T4."DocEntry" 
            WHEN 18 THEN T7."DocEntry" 
            WHEN 19 THEN T8."DocEntry" 
            ELSE T1."BaseRef" 
        END AS "BaseDocEntry", T0."Memo", T1."TransId", T1."TransType", T1."DueDate", T1."RefDate", T1."TaxDate", 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END AS "SelectionDate", T1."Project", :MainCurncyVar AS "MainCurncy", :SysCurrncy AS "SysCurrncy", 
        IFNULL(T1."FCCurrency", '') AS "FCCurrency", 
        CASE T2."CardType" 
            WHEN 'C' THEN CAST(T1."Debit" AS DECIMAL(21,6)) 
            ELSE 
            CASE 
                WHEN CAST(T1."Debit" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."Debit" AS DECIMAL(21,6)) -
                 CAST(T1."BalDueDeb" AS DECIMAL(21,6)) 
                ELSE CAST(T1."BalDueCred" AS DECIMAL(21,6)) 
            END 
        END AS "Debit", 
        CASE T2."CardType" 
            WHEN 'S' THEN CAST(T1."Debit" AS DECIMAL(21,6)) 
            ELSE 
            CASE 
                WHEN CAST(T1."Debit" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."Debit" AS DECIMAL(21,6)) -
                 CAST(T1."BalDueDeb" AS DECIMAL(21,6)) 
                ELSE CAST(T1."BalDueCred" AS DECIMAL(21,6)) 
            END 
        END AS "Credit", 
        CASE T2."CardType" 
            WHEN 'C' THEN 1 
            ELSE -1 
        END * (CAST(T1."Debit" AS DECIMAL(21,6)) - 
        CASE 
            WHEN CAST(T1."Debit" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."Debit" AS DECIMAL(21,6)) - CAST(T1."BalDueDeb" AS DECIMAL(21,6)) 
            ELSE CAST(T1."BalDueCred" AS DECIMAL(21,6)) 
        END) AS "Balance", 
        CASE T2."CardType" 
            WHEN 'C' THEN CAST(T1."FCDebit" AS DECIMAL(21,6)) 
            ELSE 
            CASE 
                WHEN CAST(T1."FCDebit" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."FCDebit" AS DECIMAL(21,6)) -
                 CAST(T1."BalFcDeb" AS DECIMAL(21,6)) 
                ELSE CAST(T1."BalFcCred" AS DECIMAL(21,6)) 
            END 
        END AS "FcDebit", 
        CASE T2."CardType" 
            WHEN 'S' THEN CAST(T1."FCDebit" AS DECIMAL(21,6)) 
            ELSE 
            CASE 
                WHEN CAST(T1."FCDebit" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."FCDebit" AS DECIMAL(21,6)) -
                 CAST(T1."BalFcDeb" AS DECIMAL(21,6)) 
                ELSE CAST(T1."BalFcCred" AS DECIMAL(21,6)) 
            END 
        END AS "FcCredit", 
        CASE T2."CardType" 
            WHEN 'C' THEN 1 
            ELSE -1 
        END * (CAST(T1."FCDebit" AS DECIMAL(21,6)) - 
        CASE 
            WHEN CAST(T1."FCDebit" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."FCDebit" AS DECIMAL(21,6)) -
             CAST(T1."BalFcDeb" AS DECIMAL(21,6)) 
            ELSE CAST(T1."BalFcCred" AS DECIMAL(21,6)) 
        END) AS "FcBalance", 
        CASE T2."CardType" 
            WHEN 'C' THEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) 
            ELSE 
            CASE 
                WHEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) -
                 CAST(T1."BalScDeb" AS DECIMAL(21,6)) 
                ELSE CAST(T1."BalScCred" AS DECIMAL(21,6)) 
            END 
        END AS "SysDeb", 
        CASE T2."CardType" 
            WHEN 'S' THEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) 
            ELSE 
            CASE 
                WHEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) -
                 CAST(T1."BalScDeb" AS DECIMAL(21,6)) 
                ELSE CAST(T1."BalScCred" AS DECIMAL(21,6)) 
            END 
        END AS "SysCred", 
        CASE T2."CardType" 
            WHEN 'C' THEN 1 
            ELSE -1 
        END * (CAST(T1."SYSDeb" AS DECIMAL(21,6)) - 
        CASE 
            WHEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) <> 0 THEN CAST(T1."SYSDeb" AS DECIMAL(21,6)) - CAST(T1."BalScDeb" AS DECIMAL(21,6)) 
            ELSE CAST(T1."BalScCred" AS DECIMAL(21,6)) 
        END) AS "SysBal", 
        CASE T1."TransType" 
            WHEN 13 THEN T3."PayBlock" 
            WHEN 14 THEN T4."PayBlock" 
            WHEN 18 THEN T7."PayBlock" 
            WHEN 19 THEN T8."PayBlock" 
            ELSE T1."PayBlock" 
        END AS "PayBlock", 
        CASE T1."TransType" 
            WHEN 13 THEN T3."Comments" 
            WHEN 14 THEN T4."Comments" 
            WHEN 18 THEN T7."Comments" 
            WHEN 19 THEN T8."Comments" 
            WHEN 24 THEN T11."Comments" 
            WHEN 46 THEN T13."Comments" 
            ELSE T0."Memo" 
        END AS "Comments" 
    FROM OJDT T0 
        INNER JOIN JDT1 T1 ON T0."TransId" = T1."TransId" 
        INNER JOIN OCRD T2 ON T2."CardCode" = T1."ShortName" 
        LEFT OUTER JOIN OINV T3 ON T1."BaseRef" = T3."DocNum" AND T0."DocSeries" = T3."Series" 
        LEFT OUTER JOIN ORIN T4 ON T1."BaseRef" = T4."DocNum" AND T0."DocSeries" = T4."Series" 
        LEFT OUTER JOIN OPCH T7 ON T1."BaseRef" = T7."DocNum" AND T0."DocSeries" = T7."Series" 
        LEFT OUTER JOIN ORPC T8 ON T1."BaseRef" = T8."DocNum" AND T0."DocSeries" = T8."Series" 
        LEFT OUTER JOIN ORCT T11 ON T1."BaseRef" = T11."DocNum" AND T0."DocSeries" = T11."Series" 
        LEFT OUTER JOIN OVPM T13 ON T1."BaseRef" = T13."DocNum" AND T0."DocSeries" = T13."Series" 
    WHERE T2."CardType" = :CardType AND (T1."BalDueDeb" <> 0 OR T1."BalDueCred" <> 0 OR T1."BalFcDeb" <> 0 OR
         T1."BalFcCred" <> 0) AND 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END >= :FromDate AND 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END <= :ToDate AND T1."TransType" IN ('13','14','18','19','24','46') 
    ORDER BY T2."CardCode", T1."TransType", 
        CASE :DateType 
            WHEN 'DueDate' THEN T1."DueDate" 
            WHEN 'TaxDate' THEN T1."TaxDate" 
            ELSE T1."RefDate" 
        END, T1."TransId", T1."Line_ID";
    --[Note:Modifier] HANA doesn't have CONVERT you may you see CAST or implicit casting or TO_... functions
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_Open_Inventory_Counting() 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
selectStr nvarchar(5000);
fromStr nvarchar(1000);
whereStr nvarchar(128);
tmpSQL nvarchar(256);
typeUSR integer := 12;
typeHEM integer := 171;
BEGIN
    tmpSQL := 'SELECT ' ||   :typeUSR  || ' as "TakerType", "USERID" as "TakerId", "U_NAME" as "TakerName" FROM OUSR'
    		  || ' UNION ALL SELECT ' ||  :typeHEM  || ' as "Takertype", "empID" as "Takerid", "lastName" || '' '' || "firstName" as "TakerName" FROM OHEM';
    
    selectStr := 'SELECT T0."DocEntry", T0."CountDate", T0."Time", T0."CountType", T1."TakerName" as "Taker1", T2."TakerName" as "Taker2", T0."Ref2"';
    
    fromStr := ' FROM OINC T0'
    			|| ' LEFT OUTER JOIN (' || :tmpSQL || ' ) T1 on T0."Taker1Type" = T1."TakerType" and T0."Taker1Id" = T1."TakerId"'
    			|| ' LEFT OUTER JOIN (' || :tmpSQL || ' ) T2 on T0."Taker2Type" = T2."TakerType" and T0."Taker2Id" = T2."TakerId"';
    
    whereStr := ' WHERE T0."Status" = ''O'' ';
    execute immediate (:selectStr || :fromStr || :whereStr);
	--select (:selectStr || :fromStr || :whereStr) from dummy;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

Create Procedure CRSP_OPEN_ITEM_LIST(
	In DateType nvarchar(1),
	In DateValue NVarChar(8),
	In ReconDateValue NVarChar(8),
	IN custs NCLOB,
	IN IncludeDPMRequestIn nvarchar(1) -- Bollean parameter from CR, '1' means True, '0' means False.
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
retCount integer;
BEGIN

DECLARE IsExists INTEGER;

call _TmSp_ValidateSpParam (:DateType);
call _TmSp_ValidateSpParam (:DateValue);
call _TmSp_ValidateSpParam (:ReconDateValue);
call _TmSp_ValidateSpParam (:IncludeDPMRequestIn);

SELECT COUNT(*) INTO IsExists 
  FROM M_TEMPORARY_TABLES
  WHERE TABLE_NAME = '#CRSP_TEMP_OCRD_COL' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
  
IF :IsExists > 0 THEN
    DROP TABLE #CRSP_TEMP_OCRD_COL;
END IF;
  

create LOCAL TEMPORARY column table #CRSP_TEMP_OCRD_COL( 
    "CardCode" NVARCHAR(15) ,
    "CardName" NVARCHAR(200) ,
    "GroupCode" SMALLINT ,
    "Balance" DECIMAL(21,6)  
); 


exec ('INSERT INTO #CRSP_TEMP_OCRD_COL SELECT T0."CardCode", T0."CardName", T0."GroupCode", T0."Balance" FROM OCRD T0 WHERE ' || :custs );


JOURNALSOURCE= SELECT
     T1."CardCode" AS "WHERE_CARD",
     T0."DocEntry",
     T0."InstlmntID",
     T1."Installmnt",
     T0."DunDate",
     T0."ObjType",
     T1."CardCode",
     T1."CardName",
     T1."NumAtCard",
     T1."SlpCode",
     T0."InsTotal",
     T0."InsTotalFC",
     T0."InsTotalSy",
     T1."BlockDunn",
     T0."DunnLevel",
     N'I' AS "TransType",
     N'Y' AS "IsSales",
     N'Y' AS "IsDunnable" ,
     0 AS "BoeNum",
     N'' AS "BoeStatus" 
FROM "INV6" T0 
INNER JOIN "OINV" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN #CRSP_TEMP_OCRD_COL T2 On T1."CardCode" = T2."CardCode"
UNION ALL SELECT
     T1."CardCode" AS "WHERE_CARD",
     T0."DocEntry",
     T0."InstlmntID",
     T1."Installmnt",
     T0."DunDate",
     T0."ObjType",
     T1."CardCode",
     T1."CardName",
     T1."NumAtCard",
     T1."SlpCode",
     T0."InsTotal",
     T0."InsTotalFC",
     T0."InsTotalSy",
     T1."BlockDunn",
     T0."DunnLevel",
     N'I' AS "TransType",
     N'Y' AS "IsSales",
     N'N' AS "IsDunnable" ,
     0 AS "BoeNum",
     N'' AS "BoeStatus" 
FROM "RIN6" T0 
INNER JOIN "ORIN" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN #CRSP_TEMP_OCRD_COL T2 On T1."CardCode" = T2."CardCode" 
UNION ALL SELECT
     T1."CardCode" AS "WHERE_CARD",
     T0."DocEntry",
     T0."InstlmntID",
     T1."Installmnt",
     T0."DunDate",
     T0."ObjType",
     T1."CardCode",
     T1."CardName",
     T1."NumAtCard",
     T1."SlpCode",
     T0."InsTotal",
     T0."InsTotalFC",
     T0."InsTotalSy",
     T1."BlockDunn",
     T0."DunnLevel",
     N'I' AS "TransType",
     N'Y' AS "IsSales",
     N'Y' AS "IsDunnable" ,
     0 AS "BoeNum",
     N'' AS "BoeStatus" 
FROM "DPI6" T0 
INNER JOIN "ODPI" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN #CRSP_TEMP_OCRD_COL T2 On T1."CardCode" = T2."CardCode"
UNION ALL SELECT
     '-1' AS "WHERE_CARD",
     T0."DocEntry",
     0 AS "InstlmntID",
     0 AS "Installmnt",
     NULL AS "DunDate",
    T0."ObjType",
     T0."CardCode",
     T0."CardName",
     N'' AS "NumAtCard",
     -1 AS "SlpCode",
     T0."DocTotal" AS "InsTotal",
     T0."DocTotalFC" AS "InsTotalFC",
     T0."DocTotalSy" AS "InsTotalSy",
     N'Y' AS "BlockDunn",
     0 AS "DunnLevel",
     N'P' AS "SrcType",
     N'' AS "IsSales",
     N'N' AS "IsDunnable",
     0 AS "BoeNum",
     N'' AS "BoeStatus" 
FROM "ORCT" T0 
UNION ALL SELECT
     '-1' AS "WHERE_CARD",
     T0."DeposId",
     0 AS "InstlmntID",
     0 AS "Installmnt",
     NULL AS "DunDate",
     T0."ObjType",
     N'' AS "CardCode",
     N'' AS "CardName",
     N'' AS "NumAtCard",
     -1 AS "SlpCode",
     T0."LocTotal" AS "InsTotal" ,
     T0."FcTotal" AS "InsTotalFC" ,
     T0."SysTotal" AS "InsTotalSy",
     N'Y' AS "BlockDunn",
     0 AS "DunnLevel",
     N'D' AS "SrcType",
     N'' AS "IsSales",
     N'N' AS "IsDunnable",
     T1."BoeNum",
     T1."BoeStatus" 
FROM "ODPS" T0 
LEFT OUTER JOIN "OBOE" T1 ON T1."BoeKey" = T0."DeposId"
;

IF :DateType = '1' 
THEN PostedTrans = SELECT
     T0."DocEntry",
     T0."TransId",
     T0."Line_ID",
     T0."InstlmntID",
     T0."ShortName",
     T0."Address",
     T0."Phone",
     T0."TransType",
     T0."CreatedBy",
     T0."BaseRef",
     T0."Debit",
     T0."Credit",
     T0."FCDebit",
     T0."FCCredit",
     T0."DebCred",
     T0."RefDate",
     T0."DueDate",
     T0."TaxDate",
     T0."BalDueCred",
     T0."BalFCCred",
     T0."LineMemo" ,
     T0."CardName",
     T0."CardCode",
     T0."DunnLevel",
     T0."BPCurrency",
     T0."JEFCCurrency",
     T0."JEFCCurrency" as "FCCurrency",
     T0."Installmnt",
     T0."DunDate",
     T0."InsTotal",
     T0."InsTotalFC" ,
     T0."InsTotalSy",
     T1."SrcObjTyp",
     T1."SrcObjAbs",
     T1."IsCredit",
     T2."ReconDate",
     T2."ReconCurr",
     T4."ReconBaseRef",
     T4."ReconRefDate",
     T4."ReconDocumentDate",
     T5."ReconJrnlMemo",
     T5."ReconDebCred",
     T5."ReconDebit",
     T5."ReconCredit",
     T5."ReconDebitFc",
     T5."ReconCreditFC" ,
     T5."ReconJEFCCurrency",
     CURRENT_DATE AS "ServerDate",
    T3."Name" AS "IndicatorName" ,
     (CASE WHEN T2."ReconDate" IS NULL 
    THEN 0 
    ELSE T1."ReconSum" 
    END ) AS "realReconSum" ,
     (CASE WHEN T2."ReconDate" IS NULL 
    THEN 0 
    ELSE T1."ReconSumFC" 
    END ) AS "realReconSumFC" ,
    'N' As "IsDPMRequest" 
FROM ( SELECT
     MAX(T5."DocEntry") AS "DocEntry",
    T0."TransId",
     T0."Line_ID",
     MAX("InstlmntID") AS "InstlmntID",
     MAX(T0."Account") AS "Account",
     MAX(T0."ShortName") AS "ShortName",
     MAX(T4."Address") AS "Address",
     MAX(T4."Phone1") AS "Phone",
     MAX(T0."TransType") AS "TransType",
     MAX(T0."CreatedBy") AS "CreatedBy",
     MAX(T0."BaseRef") AS "BaseRef",
     MAX(T0."SourceLine") AS "SourceLine",
     MAX(T0."Debit") AS "Debit",
     MAX(T0."Credit") AS "Credit",
     MAX(T0."FCDebit") AS "FCDebit",
     MAX(T0."FCCredit") AS "FCCredit",
    MAX(T0."DebCred") AS "DebCred",
     MAX(T0."RefDate") AS "RefDate" ,
     MAX(T0."DueDate") AS "DueDate",
     MAX(T0."TaxDate") AS "TaxDate",
     (MAX(T0."BalDueCred") + SUM(T1."ReconSum")) AS "BalDueCred",
     (MAX(T0."BalFcCred") + SUM(T1."ReconSumFC")) AS "BalFCCred",
    ( MAX(T0."BalScCred") + SUM(T1."ReconSumSC")) AS "BalScCred",
     MAX(T0."LineMemo") AS "LineMemo",
     MAX(T0."Indicator") AS "Indicator",
     MAX(T4."CardName") AS "CardName",
     MAX(T4."CardCode") AS "CardCode",
     MAX(T5."CardName") AS "CardName1",
     MAX(T4."Balance") AS "Balance",
     (SUM(T0."Debit") + SUM(T0."Credit")) AS "DocTotal",
     SUM(T0."FCDebit") + SUM(T0."FCCredit") AS "DocTotalFC",
     SUM(T0."SYSDeb") + SUM(T0."SYSCred") AS "DocTotalSC",
     MAX(T5."DunnLevel") AS "DunnLevel" ,
     MAX(T5."IsSales") AS "IsSales",
     MAX(T4."Currency") AS "BPCurrency",
     MAX(T0."FCCurrency") AS "JEFCCurrency" ,
     MAX(T5."Installmnt") AS "Installmnt",
     MAX(T5."DunDate") AS "DunDate",
     MAX(T5."InsTotal") AS "InsTotal",
     MAX(T5."InsTotalFC") AS "InsTotalFC",
     MAX(T5."InsTotalSy") AS "InsTotalSy" 
    FROM "JDT1" T0 
    INNER JOIN "ITR1" T1 ON T1."TransId" = T0."TransId" 
    AND T1."TransRowId" = T0."Line_ID" 
    INNER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
    INNER JOIN "OJDT" T3 ON T3."TransId" = T0."TransId" 
    INNER JOIN "OCRD" T4 ON T4."CardCode" = T0."ShortName" 
    INNER JOIN #CRSP_TEMP_OCRD_COL T6 On T4."CardCode" = T6."CardCode"
       
    LEFT OUTER JOIN :JOURNALSOURCE T5 ON T5."ObjType" = T0."TransType" 
    AND T5."DocEntry" = T0."CreatedBy" 
    AND (T5."TransType" <> N'I' 
        OR T5."InstlmntID" = T0."SourceLine" ) 
    WHERE 
    --TO_CHAR(T0."RefDate", 
    --'YYYYMMDD') <= :DateValue
     T0."RefDate" <= to_timestamp(:DateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7')
    AND T4."CardType" = 'C' 
    --AND T4."Balance" <>0 
    --AND TO_CHAR(T2."ReconDate",    
    --'YYYYMMDD')>:ReconDateValue
    AND T2."ReconDate" > to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T1."IsCredit" = 'C' 
    GROUP BY T0."TransId",
     T0."Line_ID" HAVING MAX(T0."BalFcCred") <>- SUM(T1."ReconSumFC") 
    OR MAX(T0."BalDueCred") <>- SUM(T1."ReconSum") 
    UNION ALL SELECT
     (CASE WHEN MAX(T5."DocEntry") IS NULL 
        THEN T0."TransId" 
        ELSE MAX(T5."DocEntry") 
        END ) AS "DocEntry",
    T0."TransId",
     T0."Line_ID",
     MAX("InstlmntID") AS "InstlmntID",
     MAX(T0."Account") AS "Account",
     MAX(T0."ShortName") AS "ShortName",
     MAX(T4."Address") AS "Address",
     MAX(T4."Phone1") AS "Phone",
    MAX(T0."TransType") AS "TransType",
     MAX(T0."CreatedBy") AS "CreatedBy",
     MAX(T0."BaseRef") AS "BaseRef",
     MAX(T0."SourceLine") AS "SourceLine",
     MAX(T0."Debit") AS "Debit",
     MAX(T0."Credit") AS "Credit",
     MAX(T0."FCDebit") AS "FCDebit",
     MAX(T0."FCCredit") AS "FCCredit",
    MAX(T0."DebCred") AS "DebCred",
     MAX(T0."RefDate") AS "RefDate",
     MAX(T0."DueDate") AS "DueDate",
     MAX(T0."TaxDate") AS "TaxDate",
     (- MAX(T0."BalDueDeb") - SUM(T1."ReconSum")) AS "BalDueCred",
     (- MAX(T0."BalFcDeb") - SUM(T1."ReconSumFC")) AS "BalFCCred",
     (- MAX(T0."BalScDeb") - SUM(T1."ReconSumSC")) AS "BalScCred",
     MAX(T0."LineMemo") AS "LineMemo",
     MAX(T0."Indicator") AS "Indicator",
     MAX(T4."CardName") AS "CardName",
     MAX(T4."CardCode") AS "CardCode",
     MAX(T5."CardName") AS "CardName1",
     MAX(T4."Balance") AS "Balance",
    (SUM(T0."Debit") + SUM(T0."Credit")) AS "DocTotal",
     (SUM(T0."FCDebit") + SUM(T0."FCCredit")) AS "DocTotalFC",
     (SUM(T0."SYSDeb") + SUM(T0."SYSCred")) AS "DocTotalSC",
     MAX(T5."DunnLevel") AS "DunnLevel",
     MAX(T5."IsSales") AS "IsSales",
     MAX(T4."Currency") AS "BPCurrency",
     MAX(T0."FCCurrency") AS "JEFCCurrency" ,
    MAX(T5."Installmnt") AS "Installmnt",
     MAX(T5."DunDate") AS "DunDate" ,
     MAX(T5."InsTotal") AS "InsTotal",
     MAX(T5."InsTotalFC") AS "InsTotalFC",
     MAX(T5."InsTotalSy") AS "InsTotalSy" 
    FROM "JDT1" T0 
    INNER JOIN "ITR1" T1 ON T1."TransId" = T0."TransId" 
    AND T1."TransRowId" = T0."Line_ID" 
    INNER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
    INNER JOIN "OJDT" T3 ON T3."TransId" = T0."TransId" 
    INNER JOIN "OCRD" T4 ON T4."CardCode" = T0."ShortName" 
    INNER JOIN #CRSP_TEMP_OCRD_COL T6 On T4."CardCode" = T6."CardCode" 
    LEFT OUTER JOIN :JOURNALSOURCE T5 ON T5."ObjType" = T0."TransType" 
    AND T5."DocEntry" = T0."CreatedBy" 
    AND (T5."TransType" <> N'I' 
        OR T5."InstlmntID" = T0."SourceLine" ) 
    WHERE 
    --TO_CHAR(T0."RefDate",     'YYYYMMDD') <= :DateValue
    T0."RefDate" <= to_timestamp(:DateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T4."CardType" = 'C' 
    --AND T4."Balance" <>0 
    --AND TO_CHAR(T2."ReconDate",    'YYYYMMDD') >:ReconDateValue
    AND T2."ReconDate" > to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7')
    AND T1."IsCredit" = 'D' 
    GROUP BY T0."TransId",
     T0."Line_ID" HAVING MAX(T0."BalFcDeb") <>- SUM(T1."ReconSumFC") 
    OR MAX(T0."BalDueDeb") <>- SUM(T1."ReconSum") 
    UNION ALL SELECT
     (CASE WHEN MAX(T3."DocEntry") IS NULL 
        THEN T0."TransId" 
        ELSE MAX(T3."DocEntry") 
        END ) AS "DocEntry",
     T0."TransId",
     T0."Line_ID",
     MAX("InstlmntID") AS "InstlmntID",
     MAX(T0."Account") AS "Account",
     MAX(T0."ShortName") AS "ShortName",
     MAX(T2."Address") AS "Address",
     MAX(T2."Phone1") AS "Phone",
    MAX(T0."TransType") AS "TransType",
     MAX(T0."CreatedBy") AS "CreatedBy",
     MAX(T0."BaseRef") AS "BaseRef",
     MAX(T0."SourceLine") AS "SourceLine",
    MAX(T0."Debit") AS "Debit",
     MAX(T0."Credit") AS "Credit",
     MAX(T0."FCDebit") AS "FCDebit",
     MAX(T0."FCCredit") AS "FCCredit",
    MAX(T0."DebCred") AS "DebCred",
     MAX(T0."RefDate") AS "RefDate",
     MAX(T0."DueDate") AS "DueDate",
     MAX(T0."TaxDate") AS "TaxDate",
     (MAX(T0."BalDueCred") - MAX(T0."BalDueDeb")) AS "BalDueCred",
     (MAX(T0."BalFcCred") - MAX(T0."BalFcDeb")) AS "BalFCCred",
     (MAX(T0."BalScCred") - MAX(T0."BalScDeb")) AS "BalSCCred",
     MAX(T0."LineMemo") AS "LineMemo" ,
    MAX(T0."Indicator") AS "Indicator",
     MAX(T2."CardName") AS "CardName",
     MAX(T2."CardCode") AS "CardCode",
     MAX(T3."CardName") AS "CardName1",
     MAX(T2."Balance") AS "Balance",
     (SUM(T0."Debit") + SUM(T0."Credit")) AS "DocTotal",
    ( SUM(T0."FCDebit") + SUM(T0."FCCredit")) AS "DocToalFC",
    ( SUM(T0."SYSDeb") + SUM(T0."SYSCred")) AS "DocTotalSC",
     MAX(T3."DunnLevel") AS "DunnLevel",
     MAX(T3."IsSales") AS "IsSales",
     MAX(T2."Currency") AS "BPCurrency",
     MAX(T0."FCCurrency") AS "JEFCCurrency",
     MAX(T3."Installmnt") AS "Installmnt",
     MAX(T3."DunDate") AS "DunDate",
     MAX(T3."InsTotal") AS "InsTotal",
     MAX(T3."InsTotalFC") AS "InsTotalFC",
     MAX(T3."InsTotalSy") AS "InsTotalSy" 
    FROM "JDT1" T0 
    INNER JOIN "OJDT" T1 ON T1."TransId" = T0."TransId" 
    INNER JOIN "OCRD" T2 ON T2."CardCode" = T0."ShortName" 
    INNER JOIN #CRSP_TEMP_OCRD_COL T6 On T2."CardCode" = T6."CardCode" 
    LEFT OUTER JOIN :JOURNALSOURCE T3 ON T3."ObjType" = T0."TransType" 
    AND T3."DocEntry" = T0."CreatedBy" 
    AND (T3."TransType" <> N'I' 
        OR T3."InstlmntID" = T0."SourceLine" ) 
    WHERE 
    --TO_CHAR(T0."RefDate",    'YYYYMMDD') <=:DateValue
    T0."RefDate" <= to_timestamp(:DateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T2."CardType" ='C' 
    --AND T2."Balance" <> 0 
    AND (T0."BalDueCred" <> T0."BalDueDeb" 
        OR T0."BalFcCred" <> T0."BalFcDeb" ) 
    AND NOT EXISTS (SELECT
     U0."TransId",
     U0."TransRowId" 
        FROM "ITR1" U0 
        INNER JOIN "OITR" U1 ON U1."ReconNum" = U0."ReconNum" 
        WHERE T0."TransId" = U0."TransId" 
        AND T0."Line_ID" = U0."TransRowId" 
        --AND TO_CHAR(U1."ReconDate",    'YYYYMMDD') > :ReconDateValue
        AND U1."ReconDate" > to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
        GROUP BY U0."TransId",
     U0."TransRowId") 
    GROUP BY T0."TransId",
     T0."Line_ID" ) T0 
LEFT OUTER JOIN "ITR1" T1 ON T1."ReconNum" IN (select
     U0."ReconNum" 
    from "ITR1" U0 
    where U0."TransId" = T0."TransId" 
    AND U0."TransRowId" = T0."Line_ID") 
and (T1."TransId"<> T0."TransId" 
    Or T1."TransRowId"<> T0."Line_ID") --LEFT OUTER JOIN "ITR1" U0 ON T1."ReconNum" =U0."ReconNum" AND U0."TransId" = T0."TransId" AND U0."TransRowId" = T0."Line_ID" 
LEFT OUTER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
--AND TO_CHAR(T2."ReconDate",    'YYYYMMDD') <= :ReconDateValue
AND T2."ReconDate" <= to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7')
LEFT OUTER JOIN (SELECT
     "TransId" AS "ReconTransID",
     "BaseRef" AS "ReconBaseRef",
     "RefDate" AS "ReconRefDate" ,
     "TaxDate" AS "ReconDocumentDate" 
    From "OJDT") T4 ON T4."ReconTransID" = T1."TransId" 
LEFT OUTER JOIN (SELECT
     "TransId" AS "ReconTransID1",
     "Line_ID" AS "ReconJELine_ID",
     "LineMemo" AS "ReconJrnlMemo",
     "DebCred" AS "ReconDebCred",
     "Debit" AS "ReconDebit",
     "Credit" AS "ReconCredit",
     "FCDebit" AS "ReconDebitFc",
     "FCCredit" AS "ReconCreditFC" ,
     "FCCurrency" AS "ReconJEFCCurrency" 
    From "JDT1") T5 on T5."ReconTransID1" = T4."ReconTransID" 
AND T5."ReconJELine_ID" = T1."TransRowId" 
LEFT OUTER JOIN "OIDC" T3 ON T3."Code" = T0."Indicator" 
ORDER BY T0."RefDate",
     T0."BaseRef" ,
     T2."ReconDate" 
; 
 DPRequest = Select
     T0."DocEntry",
     -1 as "TransId",
     -1 as "Line_ID",
     -1 as InstlmntID,
     T4."CardCode" as ShortName,
     T4."Address",
     T4."Phone1",
     '203' as TransType,
     '-1' As CreatedBy,
     To_NVarChar(T0."DocNum") as BaseRef,
     0 as Debit,
     0 as Credit,
     0 as FCDebit,
     0 as FCCredit,
     '' as DebCred,
     T0."DocDate" as RefDate,
     T0."DocDueDate" as DueDate,
     T0."TaxDate",
     0 as BalDueCred,
     0 as BalFCCred,
     T0."JrnlMemo" as "LineMemo",
     T4."CardName",
     T4."CardCode",
     T3."DunnLevel",
     T4."Currency" as BPCurrency,
     '' as JEFCCurrency,
     '' as "FCCurrency",
     -1 as Installmnt,
     T3."DunDate",
     T3."InsTotal",
     T3."InsTotalFC",
     T3."InsTotalSy",
     '203' as SrcObjTyp,
     T0."DocEntry" as SrcObjAbs,
     '' as IsCredit,
     NULL as ReconDate,
     T0."CurSource" as ReconCurr,
     '' as ReconBaseRef,
     NULL as ReconRefDate,
     NULL as ReconDocumentDate,
     NULL as ReconJrnlMemo,
     '' as ReconDebCred,
     0 as ReconDebit,
     0 as ReconCredit,
     0 as ReconDebitFc,
     0 as ReconCreditFC ,
     T0."DocCur" as ReconJEFCCurrency,
     CURRENT_DATE as ServerDate,
    T5."Name" as IndicatorName ,
    0 as realReconSum ,
     0 as realRconSumFC,
     'Y' as IsDPMRequest 
From ODPI T0 
Inner Join DPI6 T3 On T0."CreateTran" ='N' 
and T0."DocEntry" = T3."DocEntry" 
and T0."DocEntry" in ( Select
     U0."DocEntry" 
    from odpi U0 
    Left Outer Join RCT2 T1 On U0."CreateTran" ='N' 
    and T1."InvType" = '203' 
    and T1."DocEntry" = U0."DocEntry" 
    Left Outer Join ORCT T2 on T2."DocEntry" = T1."DocNum" 
    Where TO_DATE(T2."DocDate") <= To_Date(:DateValue) 
    Or U0."DocStatus" = 'O' 
    Group By U0."DocEntry" Having Sum(T1."SumApplied") <> Max(U0."DocTotal") 
    Or Max(U0."DocStatus") = 'O' ) 
Inner Join OCRD T4 On T4."CardCode" = T0."CardCode" 
Inner Join #CRSP_TEMP_OCRD_COL T6 On T6."CardCode" = T4."CardCode"
Left Outer Join OIDC T5 On T5."Code" = T0."Indicator" 
Where :IncludeDPMRequestIn = '1'
;

ELSE PostedTrans = SELECT 
     T0."DocEntry",
     T0."TransId",
     T0."Line_ID",
     T0."InstlmntID",
     T0."ShortName",
     T0."Address",
     T0."Phone",
    T0."TransType",
     T0."CreatedBy",
     T0."BaseRef",
     T0."Debit",
     T0."Credit",
     T0."FCDebit",
     T0."FCCredit",
    T0."DebCred",
     T0."RefDate",
     T0."DueDate",
     T0."TaxDate",
     T0."BalDueCred",
     T0."BalFCCred",
     T0."LineMemo" ,
     T0."CardName",
     T0."CardCode",
     T0."DunnLevel",
     T0."BPCurrency",
     T0."JEFCCurrency",
     T0."JEFCCurrency" as "FCCurrency",
     T0."Installmnt",
     T0."DunDate",
     T0."InsTotal",
     T0."InsTotalFC" ,
     T0."InsTotalSy",
     T1."SrcObjTyp",
     T1."SrcObjAbs",
     T1."IsCredit",
     T2."ReconDate",
     T2."ReconCurr",
     T4."ReconBaseRef",
     T4."ReconRefDate",
     T4."ReconDocumentDate",
     T5."ReconJrnlMemo",
    T5."ReconDebCred",
     T5."ReconDebit",
     T5."ReconCredit",
     T5."ReconDebitFc",
     T5."ReconCreditFC" ,
     T5."ReconJEFCCurrency",
     CURRENT_DATE AS "ServerDate",
    T3."Name" AS "IndicatorName" ,
     (CASE WHEN T2."ReconDate" IS NULL 
    THEN 0 
    ELSE T1."ReconSum" 
    END ) AS "realReconSum" ,
     (CASE WHEN T2."ReconDate" IS NULL 
    THEN 0 
    ELSE T1."ReconSumFC" 
    END ) AS "realReconSumFC" ,
     'N' As "IsDPMRequest" 
FROM ( SELECT
     MAX(T5."DocEntry") AS "DocEntry",
    T0."TransId",
     T0."Line_ID",
     MAX("InstlmntID") AS "InstlmntID",
     MAX(T0."Account") AS "Account",
     MAX(T0."ShortName") AS "ShortName",
     MAX(T4."Address") AS "Address",
     MAX(T4."Phone1") AS "Phone",
     MAX(T0."TransType") AS "TransType",
     MAX(T0."CreatedBy") AS "CreatedBy",
     MAX(T0."BaseRef") AS "BaseRef",
     MAX(T0."SourceLine") AS "SourceLine",
     MAX(T0."Debit") AS "Debit",
     MAX(T0."Credit") AS "Credit",
     MAX(T0."FCDebit") AS "FCDebit",
     MAX(T0."FCCredit") AS "FCCredit",
    MAX(T0."DebCred") AS "DebCred",
     MAX(T0."RefDate") AS "RefDate" ,
     MAX(T0."DueDate") AS "DueDate",
     MAX(T0."TaxDate") AS "TaxDate",
     (MAX(T0."BalDueCred") + SUM(T1."ReconSum")) AS "BalDueCred",
     (MAX(T0."BalFcCred") + SUM(T1."ReconSumFC")) AS "BalFCCred",
    ( MAX(T0."BalScCred") + SUM(T1."ReconSumSC")) AS "BalScCred",
     MAX(T0."LineMemo") AS "LineMemo",
     MAX(T0."Indicator") AS "Indicator",
     MAX(T4."CardName") AS "CardName",
     MAX(T4."CardCode") AS "CardCode",
     MAX(T5."CardName") AS "CardName1",
     MAX(T4."Balance") AS "Balance",
     (SUM(T0."Debit") + SUM(T0."Credit")) AS "DocTotal",
     SUM(T0."FCDebit") + SUM(T0."FCCredit") AS "DocTotalFC",
     SUM(T0."SYSDeb") + SUM(T0."SYSCred") AS "DocTotalSC",
     MAX(T5."DunnLevel") AS "DunnLevel" ,
     MAX(T5."IsSales") AS "IsSales",
     MAX(T4."Currency") AS "BPCurrency",
     MAX(T0."FCCurrency") AS "JEFCCurrency" ,
     MAX(T5."Installmnt") AS "Installmnt",
     MAX(T5."DunDate") AS "DunDate",
     MAX(T5."InsTotal") AS "InsTotal",
     MAX(T5."InsTotalFC") AS "InsTotalFC",
     MAX(T5."InsTotalSy") AS "InsTotalSy" 
    FROM "JDT1" T0 
    INNER JOIN "ITR1" T1 ON T1."TransId" = T0."TransId" 
    AND T1."TransRowId" = T0."Line_ID" 
    INNER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
    INNER JOIN "OJDT" T3 ON T3."TransId" = T0."TransId" 
    INNER JOIN "OCRD" T4 ON T4."CardCode" = T0."ShortName" 
    INNER JOIN #CRSP_TEMP_OCRD_COL T6 On T4."CardCode" = T6."CardCode" 
    LEFT OUTER JOIN :JOURNALSOURCE T5 ON T5."ObjType" = T0."TransType" 
    AND T5."DocEntry" = T0."CreatedBy" 
    AND (T5."TransType" <> N'I' 
        OR T5."InstlmntID" = T0."SourceLine" ) 
    WHERE 
    --TO_CHAR(T0."TaxDate",    'YYYYMMDD') <= :DateValue
    T0."TaxDate" <= to_timestamp(:DateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T4."CardType" = 'C' 
    --AND T4."Balance" <>0 
    --AND TO_CHAR(T2."ReconDate",     'YYYYMMDD') >:ReconDateValue
    AND T2."ReconDate" > to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T1."IsCredit" = 'C' 
    GROUP BY T0."TransId",
     T0."Line_ID" HAVING MAX(T0."BalFcCred") <>- SUM(T1."ReconSumFC") 
    OR MAX(T0."BalDueCred") <>- SUM(T1."ReconSum") 
    UNION ALL SELECT
     MAX(T5."DocEntry") AS "DocEntry",
    T0."TransId",
     T0."Line_ID",
     MAX("InstlmntID") AS "InstlmntID",
     MAX(T0."Account") AS "Account",
     MAX(T0."ShortName") AS "ShortName",
     MAX(T4."Address") AS "Address",
     MAX(T4."Phone1") AS "Phone",
    MAX(T0."TransType") AS "TransType",
     MAX(T0."CreatedBy") AS "CreatedBy",
     MAX(T0."BaseRef") AS "BaseRef",
     MAX(T0."SourceLine") AS "SourceLine",
     MAX(T0."Debit") AS "Debit",
     MAX(T0."Credit") AS "Credit",
     MAX(T0."FCDebit") AS "FCDebit",
     MAX(T0."FCCredit") AS "FCCredit",
    MAX(T0."DebCred") AS "DebCred",
     MAX(T0."RefDate") AS "RefDate",
     MAX(T0."DueDate") AS "DueDate",
     MAX(T0."TaxDate") AS "TaxDate",
     (- MAX(T0."BalDueDeb") - SUM(T1."ReconSum")) AS "BalDueCred",
     (- MAX(T0."BalFcDeb") - SUM(T1."ReconSumFC")) AS "BalFCCred",
     (- MAX(T0."BalScDeb") - SUM(T1."ReconSumSC")) AS "BalScCred",
     MAX(T0."LineMemo") AS "LineMemo",
     MAX(T0."Indicator") AS "Indicator",
     MAX(T4."CardName") AS "CardName",
     MAX(T4."CardCode") AS "CardCode",
     MAX(T5."CardName") AS "CardName1",
     MAX(T4."Balance") AS "Balance",
    (SUM(T0."Debit") + SUM(T0."Credit")) AS "DocTotal",
     (SUM(T0."FCDebit") + SUM(T0."FCCredit")) AS "DocTotalFC",
     (SUM(T0."SYSDeb") + SUM(T0."SYSCred")) AS "DocTotalSC",
     MAX(T5."DunnLevel") AS "DunnLevel",
     MAX(T5."IsSales") AS "IsSales",
     MAX(T4."Currency") AS "BPCurrency",
     MAX(T0."FCCurrency") AS "JEFCCurrency" ,
    MAX(T5."Installmnt") AS "Installmnt",
     MAX(T5."DunDate") AS "DunDate" ,
     MAX(T5."InsTotal") AS "InsTotal",
     MAX(T5."InsTotalFC") AS "InsTotalFC",
     MAX(T5."InsTotalSy") AS "InsTotalSy" 
    FROM "JDT1" T0 
    INNER JOIN "ITR1" T1 ON T1."TransId" = T0."TransId" 
    AND T1."TransRowId" = T0."Line_ID" 
    INNER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
    INNER JOIN "OJDT" T3 ON T3."TransId" = T0."TransId" 
    INNER JOIN "OCRD" T4 ON T4."CardCode" = T0."ShortName" 
    INNER JOIN #CRSP_TEMP_OCRD_COL T6 On T4."CardCode" = T6."CardCode" 
    LEFT OUTER JOIN :JOURNALSOURCE T5 ON T5."ObjType" = T0."TransType" 
    AND T5."DocEntry" = T0."CreatedBy" 
    AND (T5."TransType" <> N'I' 
        OR T5."InstlmntID" = T0."SourceLine" ) 
    WHERE 
    --TO_CHAR(T0."TaxDate",     'YYYYMMDD') <=:DateValue
    T0."TaxDate" <= to_timestamp(:DateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T4."CardType" = 'C' 
    --AND T4."Balance" <>0 
    --AND TO_CHAR(T2."ReconDate",    'YYYYMMDD') >:ReconDateValue
    AND T2."ReconDate" > to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T1."IsCredit" = 'D' 
    GROUP BY T0."TransId",
     T0."Line_ID" HAVING MAX(T0."BalFcDeb") <>- SUM(T1."ReconSumFC") 
    OR MAX(T0."BalDueDeb") <>- SUM(T1."ReconSum") 
    UNION ALL SELECT
     (CASE WHEN MAX(T3."DocEntry") IS NULL 
        THEN T0."TransId" 
        ELSE MAX(T3."DocEntry") 
        END ) AS "DocEntry",
     T0."TransId",
     T0."Line_ID",
     MAX("InstlmntID") AS "InstlmntID",
     MAX(T0."Account") AS "Account",
     MAX(T0."ShortName") AS "ShortName",
     MAX(T2."Address") AS "Address",
     MAX(T2."Phone1") AS "Phone",
    MAX(T0."TransType") AS "TransType",
     MAX(T0."CreatedBy") AS "CreatedBy",
     MAX(T0."BaseRef") AS "BaseRef",
     MAX(T0."SourceLine") AS "SourceLine",
    MAX(T0."Debit") AS "Debit",
     MAX(T0."Credit") AS "Credit",
     MAX(T0."FCDebit") AS "FCDebit",
     MAX(T0."FCCredit") AS "FCCredit",
    MAX(T0."DebCred") AS "DebCred",
     MAX(T0."RefDate") AS "RefDate",
     MAX(T0."DueDate") AS "DueDate",
     MAX(T0."TaxDate") AS "TaxDate",
     (MAX(T0."BalDueCred") - MAX(T0."BalDueDeb")) AS "BalDueCred",
     (MAX(T0."BalFcCred") - MAX(T0."BalFcDeb")) AS "BalFCCred",
     (MAX(T0."BalScCred") - MAX(T0."BalScDeb")) AS "BalSCCred",
     MAX(T0."LineMemo") AS "LineMemo" ,
    MAX(T0."Indicator") AS "Indicator",
     MAX(T2."CardName") AS "CardName",
     MAX(T2."CardCode") AS "CardCode",
     MAX(T3."CardName") AS "CardName1",
     MAX(T2."Balance") AS "Balance",
     (SUM(T0."Debit") + SUM(T0."Credit")) AS "DocTotal",
    ( SUM(T0."FCDebit") + SUM(T0."FCCredit")) AS "DocToalFC",
    ( SUM(T0."SYSDeb") + SUM(T0."SYSCred")) AS "DocTotalSC",
     MAX(T3."DunnLevel") AS "DunnLevel",
     MAX(T3."IsSales") AS "IsSales",
     MAX(T2."Currency") AS "BPCurrency",
     MAX(T0."FCCurrency") AS "JEFCCurrency",
     MAX(T3."Installmnt") AS "Installmnt",
     MAX(T3."DunDate") AS "DunDate",
     MAX(T3."InsTotal") AS "InsTotal",
     MAX(T3."InsTotalFC") AS "InsTotalFC",
     MAX(T3."InsTotalSy") AS "InsTotalSy" 
    FROM "JDT1" T0 
    INNER JOIN "OJDT" T1 ON T1."TransId" = T0."TransId" 
    INNER JOIN "OCRD" T2 ON T2."CardCode" = T0."ShortName" 
    INNER JOIN #CRSP_TEMP_OCRD_COL T6 On T2."CardCode" = T6."CardCode" 
    LEFT OUTER JOIN :JOURNALSOURCE T3 ON T3."ObjType" = T0."TransType" 
    AND T3."DocEntry" = T0."CreatedBy" 
    AND (T3."TransType" <> N'I' 
        OR (T3."TransType" = N'I' 
            AND T3."InstlmntID" = T0."SourceLine" )) 
    WHERE 
    --TO_CHAR(T0."TaxDate",    'YYYYMMDD') <=:DateValue

    T0."TaxDate" <= to_timestamp(:DateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7') 
    AND T2."CardType" ='C' 
    --AND T2."Balance" <> 0 
    AND (T0."BalDueCred" <> T0."BalDueDeb" 
        OR T0."BalFcCred" <> T0."BalFcDeb" ) 
    AND NOT EXISTS (SELECT
     U0."TransId",
     U0."TransRowId" 
        FROM "ITR1" U0 
        INNER JOIN "OITR" U1 ON U1."ReconNum" = U0."ReconNum" 
        WHERE T0."TransId" = U0."TransId" 
        AND T0."Line_ID" = U0."TransRowId" 
        --AND TO_CHAR(U1."ReconDate",     'YYYYMMDD') > :ReconDateValue
        AND U1."ReconDate" > to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7')
        GROUP BY U0."TransId",
     U0."TransRowId") 
    GROUP BY T0."TransId",
     T0."Line_ID" ) T0 
LEFT OUTER JOIN "ITR1" T1 ON T1."ReconNum" IN (select
     U0."ReconNum" 
    from "ITR1" U0 
    where U0."TransId" = T0."TransId" 
    AND U0."TransRowId" = T0."Line_ID") 
and (T1."TransId"<> T0."TransId" 
    Or T1."TransRowId"<> T0."Line_ID") --LEFT OUTER JOIN "ITR1" U0 ON T1."ReconNum" =U0."ReconNum" AND U0."TransId" = T0."TransId" AND U0."TransRowId" = T0."Line_ID"
LEFT OUTER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
--AND TO_CHAR(T2."ReconDate",    'YYYYMMDD') <= :ReconDateValue
AND T2."ReconDate" <= to_timestamp(:ReconDateValue || ' 23:59:59.9999999', 'yyyymmdd hh:mi:ss.ff7')
LEFT OUTER JOIN (SELECT
     "TransId" AS "ReconTransID",
     "BaseRef" AS "ReconBaseRef",
     "RefDate" AS "ReconRefDate" ,
     "TaxDate" AS "ReconDocumentDate" 
    From "OJDT") T4 ON T4."ReconTransID" = T1."TransId" 
LEFT OUTER JOIN (SELECT
     "TransId" AS "ReconTransID1",
     "Line_ID" AS "ReconJELine_ID",
     "LineMemo" AS "ReconJrnlMemo",
     "DebCred" AS "ReconDebCred",
     "Debit" AS "ReconDebit",
     "Credit" AS "ReconCredit",
     "FCDebit" AS "ReconDebitFc",
     "FCCredit" AS "ReconCreditFC" ,
     "FCCurrency" AS "ReconJEFCCurrency" 
    From "JDT1") T5 on T5."ReconTransID1" = T4."ReconTransID" 
AND T5."ReconJELine_ID" = T1."TransRowId" 
LEFT OUTER JOIN "OIDC" T3 ON T3."Code" = T0."Indicator" 
ORDER BY T0."RefDate",
     T0."BaseRef" ,
     T2."ReconDate" 
;
DPRequest = Select
     T0."DocEntry",
     -1 as "TransId",
     -1 as "Line_ID",
     -1 as InstlmntID,
     T4."CardCode" as ShortName,
     T4."Address",
     T4."Phone1",
     '203' as TransType,
     '-1' As CreatedBy,
     To_NVarChar(T0."DocNum") as BaseRef,
     0 as Debit,
     0 as Credit,
     0 as FCDebit,
     0 as FCCredit,
     '' as DebCred,
     T0."DocDate" as RefDate,
     T0."DocDueDate" as DueDate,
     T0."TaxDate",
     0 as BalDueCred,
     0 as BalFCCred,
     T0."JrnlMemo" as "LineMemo",
     T4."CardName",
     T4."CardCode",
     T3."DunnLevel",
     T4."Currency" as BPCurrency,
     '' as JEFCCurrency,
     '' as "FCCurrency",
     -1 as Installmnt,
     T3."DunDate",
     T3."InsTotal",
     T3."InsTotalFC",
     T3."InsTotalSy",
     '203' as SrcObjTyp,
     T0."DocEntry" as SrcObjAbs,
     '' as IsCredit,
     NULL as ReconDate,
     T0."CurSource" as ReconCurr,
     '' as ReconBaseRef,
     NULL as ReconRefDate,
     NULL as ReconDocumentDate,
     NULL as ReconJrnlMemo,
     '' as ReconDebCred,
     0 as ReconDebit,
     0 as ReconCredit,
     0 as ReconDebitFc,
     0 as ReconCreditFC ,
     T0."DocCur" as ReconJEFCCurrency,
     CURRENT_DATE as ServerDate,
    T5."Name" as IndicatorName ,
    0 as realReconSum ,
     0 as realRconSumFC,
     'Y' as IsDPMRequest 
From ODPI T0 
Inner Join DPI6 T3 On T0."CreateTran" ='N' 
and T0."DocEntry" = T3."DocEntry" 
and T0."DocEntry" in ( Select
     U0."DocEntry" 
    from odpi U0 
    Left Outer Join RCT2 T1 On U0."CreateTran" ='N' 
    and T1."InvType" = '203' 
    and T1."DocEntry" = U0."DocEntry" 
    Left Outer Join ORCT T2 on T2."DocEntry" = T1."DocNum" 
    Where TO_DATE(T2."DocDate") <= To_Date(:DateValue) 
    Or U0."DocStatus" = 'O' 
    Group By U0."DocEntry" Having Sum(T1."SumApplied") <> Max(U0."DocTotal") 
    Or Max(U0."DocStatus") = 'O' ) 
Inner Join OCRD T4 On T4."CardCode" = T0."CardCode" 
Inner Join #CRSP_TEMP_OCRD_COL T6 On T6."CardCode" = T4."CardCode"
Left Outer Join OIDC T5 On T5."Code" = T0."Indicator" 
Where :IncludeDPMRequestIn = '1'
;
END 
IF
;
Select
     * 
From :PostedTrans 
Union All Select
     * 
From :DPRequest 
Order By "RefDate",
     "BaseRef",
     "ReconDate"
;

--drop table #CRSP_TEMP_OCRD_COL; /* cause client of rev48 disconnected */

END

-- B1 DEPENDS: AFTER:SP:CRSP_PayableReceivable_BR_enUS2
-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2
--DROP PROCEDURE CRSP_PayableReceivable_BR_enUS
CREATE PROCEDURE CRSP_PayableReceivable_BR_enUS
(
in PayDateType nvarchar(150),
in PayDateFrom timestamp,
in PayDateTo timestamp,
in PayDateType2 nvarchar(150),
in PayDateFrom2 timestamp,
in PayDateTo2 timestamp
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
AS 
DateType nvarchar(150);
FromDate timestamp;
ToDate timestamp;
FinancYear timestamp;
Country nvarchar(3);
sqlSelect nvarchar(30000);
ObjectID nvarchar(20);
TableName nvarchar(3);
ObjDesc nvarchar(100);
Factor nvarchar(2);
invoice_DocDueDate integer;
temp_var_0 integer;
next INT;
columnName nvarchar(100);
columnName2 nvarchar(100);--for other CASE WHEN THEN END statements
columnName3 nvarchar(100);--for other CASE WHEN THEN END statements
canceledColumn nvarchar(100);
v__sql nvarchar(5000);
CURSOR doctables_Cursor FOR SELECT "ObjectID", "TableName", "ObjDesc", 
    "Factor" 
FROM "CRSP_PaymentsOnInvoice" 
WHERE "ObjectID" IN ('13','14','18','19','203','204','24','46','30');
BEGIN /*
***** General Information *****
Name: ODOC_PayableReceivable
Description:
Returns the Relevant information of Sales and Purchasing documents
and payments

Creator: coresystems ag, muf@coresystems.ch
Create Date: 2011-20-10

***** Updates *****

*/
    /* ***** PARAMETERS FOR STANDARD FILTERS ***** */
    /* ***** DEFAULT PARAMETER VALUES ***** */
    DateType := 'DocDate';
    /* Get the current Date without the time */
    SELECT TO_TIMESTAMP(CURRENT_DATE, 'YYYY-MM-DD') into ToDate FROM DUMMY;
    /* Get the current Finance Year */
    SELECT 
    (SELECT T0."FinancYear" 
    FROM OACP T0 
        INNER JOIN OFPR T1 ON T0."PeriodCat" = T1."Category" 
    WHERE T1."F_RefDate" <= :ToDate AND T1."T_RefDate" >= :ToDate) INTO FinancYear FROM DUMMY;
    FromDate := ADD_YEARS(:FinancYear, -1);
    ToDate := ADD_DAYS(ADD_YEARS(:FinancYear, 1), -1);
    /* Set the parameter values (comment for debugging) */
    DateType := :PayDateType;
    FromDate := :PayDateFrom;
    ToDate := :PayDateTo;
    /* ***** INTERNAL PARAMETERS ***** */
    SELECT 
    (SELECT "LawsSet" 
    FROM CINF) INTO Country FROM DUMMY;
    sqlSelect := '';
    /* ***** CREATE A TEMP TABLE TO STORE THE RELEVANT INFORMATION FOR ALL SUPPORTED MARKETING DOCUMENTS ***** */
    insert into "CRSP_PaymentsOnInvoice" values('13', 'INV', 'AR Invoice', '1');
	insert into "CRSP_PaymentsOnInvoice" values('14', 'RIN', 'AR Credit Note', '-1');
	insert into "CRSP_PaymentsOnInvoice" values('15', 'DLN', 'Delivery', '1');
	insert into "CRSP_PaymentsOnInvoice" values('17', 'RDR', 'Sales Order', '1');
	insert into "CRSP_PaymentsOnInvoice" values('18', 'PCH', 'AP Invoice', '-1');
	insert into "CRSP_PaymentsOnInvoice" values('19', 'RPC', 'AP Credit Note', '1');
	insert into "CRSP_PaymentsOnInvoice" values('20', 'PDN', 'Goods Receipt PO', '-1');
	insert into "CRSP_PaymentsOnInvoice" values('203', 'DPI', 'AR Down Payment', '1');
	insert into "CRSP_PaymentsOnInvoice" values('204', 'DPO', 'AP Down Payment', '-1');
	insert into "CRSP_PaymentsOnInvoice" values('22', 'POR', 'Purchase Order', '-1');
	insert into "CRSP_PaymentsOnInvoice" values('23', 'QUT', 'Sales Quotation', '1');
	insert into "CRSP_PaymentsOnInvoice" values('24', 'RCT', 'Incoming Payment', '1');
	insert into "CRSP_PaymentsOnInvoice" values('46', 'VPM', 'Outgoing Payment', '-1');
	insert into "CRSP_PaymentsOnInvoice" values('30', 'JDT', 'Journal Posting', '1');
	
    /* ***** CREATE THE CURSOR FOR THE TABLES TO USE. 
 Define here which tables are interesting for the report
***** */
    OPEN doctables_Cursor;
    
    next := 1;
	WHILE :next > 0 DO
    	FETCH doctables_Cursor INTO ObjectID, TableName, ObjDesc, Factor; 
        if doctables_Cursor::NOTFOUND THEN
        	next := -1;
    		continue;
    	end if;
    	if (:DateType = 'DocDueDate') then
    		columnName := '"DocDueDate"';
    	elseif (:DateType = 'TaxDate') then
    		columnName := '"TaxDate"';
    	else
    		columnName := '"DocDate"';
    	end if;
    	--
		--exec('select count("ObjType") into temp_var_0 from O'||:TableName ||' where "ObjType" IN (''13'', ''14'')');
    	if (:DateType = 'DocDueDate') then
    		columnName2 := '"DocDueDate"';
    	elseif (:DateType = 'TaxDate') then
    		columnName2 := '"TaxDate"';
    	else
    		columnName2 := '"DocDate"';
    	end if;
    	--
		if (:DateType = 'DocDueDate') then
			  columnName3 := '"DueDate"';
        elseif (:DateType = 'TaxDate') then
    		columnName3 := '"TaxDate"';
        else
    		columnName3 := '"RefDate"';
        end if;
    	--
		if (:TableName = 'VPM' OR :TableName = 'RCT') then
			canceledColumn := '"Canceled"';
		else
			canceledColumn := 'CANCELED';
		end if;	 
		--
        IF :sqlSelect <> '' THEN 
    		sqlSelect := :sqlSelect || ' UNION ALL ';
        /* PART 1: DOCUMENTS */
        END IF;
        IF (:ObjectID = '13' OR  :ObjectID = '14' OR :ObjectID = '18' OR  :ObjectID = '19' OR :ObjectID = '203' OR  :ObjectID = '204') THEN 
        
        	IF ( (:ObjectID = '13' OR :ObjectID = '14' OR :ObjectID = '18' OR :ObjectID = '19' ) and (:DateType = 'DocDueDate') ) THEN 
				invoice_DocDueDate := 1;
	     	ELSE invoice_DocDueDate := 0; 
			END IF;
				
            sqlSelect := :sqlSelect || 'SELECT 
 /* Unique IDs*/
 ''ObjType''||CAST(T1."ObjType" AS NVARCHAR(100))||''DocEntry''||CAST(T0."DocEntry" AS NVARCHAR(100)) AS DocID
 ,''ObjType''||CAST(T1."ObjType" AS NVARCHAR(100))||''DocEntry''||CAST(T0."DocEntry" AS NVARCHAR(100))||''InstID''||CAST(T0."InstlmntID" AS NVARCHAR(100)) AS DocInstID
 /* Object */
 ,''' || :ObjectID || ''' AS ObjectID
 ,''' || :TableName || ''' AS TableName
 ,''' || :ObjDesc || ''' AS ObjDesc
 ,' || :Factor || ' AS Factor
 /* Company */
 ,''' || :Country || ''' AS Country
 /* ODOC */
 ,T1.'|| :columnName2 || ' AS FilterDate
 ,T1."DocDate"
 ,T1."DocDueDate"
 ,T1."TaxDate"
 ,T1."CardCode"
 ,T1."CardName"
 ,T1."DocCur"
 ,T1."DocEntry"
 ,T1."DocNum"
 ,IFNULL(T1."DocStatus",''O'') AS DocStatus
 ,T1."FolioNum"
 ,T1."FolioPref"
 ,T1."IsICT"
 ,T1."isIns"
 ,T1."ObjType"
 ,T1."PeyMethod"
 ,T1."Posted"
 ,T1."Model"
 ,T1."Serial"
 ,T1."SeriesStr"
 ,T1."SubStr"
 ,T1."SeqCode"
 /* DOC6 */
 ,T0."DueDate"
 ,T0."InstlmntID"
 ,T0."InsTotal"
 ,T0."InsTotalFC"
 ,T0."InsTotalSy"
 ,T0."Paid"
 ,T0."PaidFC"
 ,T0."PaidSc"
 ,IFNULL(T0."Status",''O'') AS InsStatus
 /* OPAY */
 ,0.0 AS BoeSum
 ,0.0 AS BoeSumFc
 ,0.0 AS BoeSumSc
 ,0.0 AS CashSum
 ,0.0 AS CashSumFC
 ,0.0 AS CashSumSy
 ,0.0 AS CheckSum
 ,0.0 AS CheckSumFC
 ,0.0 AS CheckSumSy
 ,0.0 AS CreditSum
 ,0.0 AS CredSumFC
 ,0.0 AS CredSumSy
 ,0.0 AS TrsfrSum
 ,0.0 AS TrsfrSumFC
 ,0.0 AS TrsfrSumSy
 FROM ' || :TableName || '6 T0
 INNER JOIN O' || :TableName || ' T1 ON T0."DocEntry" = T1."DocEntry"
 WHERE T1.'|| :canceledColumn ||' = ''N'' AND (T0."InsTotal" <> 0 OR T0."InsTotalFC" <> 0 OR T0."InsTotalSy" <> 0)
AND CASE('||:invoice_DocDueDate||') WHEN 1 THEN T0."DueDate" ELSE T1.'|| :columnName2 || ' END >= ''' || :FromDate || ''' 
AND CASE('||:invoice_DocDueDate||') WHEN 1 THEN T0."DueDate" ELSE T1.'|| :columnName2 || ' END <= ''' || :ToDate || ''' 
 ';
 ELSE 
            IF :ObjectID = '24' OR  :ObjectID = '46' THEN 
                sqlSelect := :sqlSelect || '
                
 SELECT
 /* Unique IDs*/
 ''ObjType''||CAST(IFNULL(T2."InvType",T1."ObjType") AS NVARCHAR(100))||''DocEntry''||CAST(IFNULL(T2."DocEntry",T1."DocEntry") AS NVARCHAR(100)) AS DocID
 ,''ObjType''||CAST(IFNULL(T2."InvType",T1."ObjType") AS NVARCHAR(100))||''DocEntry''||CAST(IFNULL(T2."DocEntry",T1."DocEntry") AS NVARCHAR(100))||''InstID''||CAST(IFNULL(T2."DocLine",-1) || 1 AS NVARCHAR(100)) AS DocInstID
 /* Object */
 ,''' || :ObjectID || ''' AS ObjectID
 ,''' || :TableName || ''' AS TableName
 ,''' || :ObjDesc || ''' AS ObjDesc
 ,' || :Factor || ' AS Factor
 /* Company */
 ,''' || :Country || ''' AS Country
 /* OPAY / ODOC */
 ,T1.'|| :columnName || ' AS FilterDate
 ,T1."DocDate"
 ,T1."DocDueDate"
 ,T1."TaxDate"
 ,T1."CardCode"
 ,IFNULL(T1."CardName",T1."JrnlMemo") AS CardName
 ,T1."DocCurr" AS DocCur
 ,T1."DocEntry"
 ,T1."DocNum"
 ,''C'' AS DocStatus
 ,NULL AS FolioNum
 ,NULL AS FolioPref
 ,NULL AS IsICT
 ,NULL AS isIns
 ,T1."ObjType"
 ,NULL AS PeyMethod
 ,NULL AS Posted
 ,NULL AS Model
 ,T1."Serial"
 ,T1."SeriesStr"
 ,T1."SubStr"
 ,T1."SeqCode"
 /* OPAY / DOC6 */
 ,T1."DocDueDate" AS DueDate
 ,-1 AS InstlmntID
 ,0.0 AS InsTotal
 ,0.0 AS InsTotalFC
 ,0.0 AS InsTotalSy
 ,(T1."OpenBal") * -1 AS Paid
 ,(T1."OpenBalFc") * -1 AS PaidFC
 ,(T1."OpenBalSc") * -1 AS PaidSc
 ,''C'' AS InsStatus
 /* OPAY */
 ,T1."BoeSum"
 ,T1."BoeSumFc"
 ,T1."BoeSumSc"
 ,T1."CashSum"
 ,T1."CashSumFC"
 ,T1."CashSumSy"
 ,T1."CheckSum"
 ,T1."CheckSumFC"
 ,T1."CheckSumSy"
 ,T1."CreditSum"
 ,T1."CredSumFC"
 ,T1."CredSumSy"
 ,T1."TrsfrSum"
 ,T1."TrsfrSumFC"
 ,T1."TrsfrSumSy"
 FROM O' || :TableName || ' T1
 LEFT OUTER JOIN ' || :TableName || '2 T2 ON T1."DocEntry" = T2."DocNum"
 WHERE T1.'|| :canceledColumn ||' = ''N'' AND T1."DocType" <> ''A''
 AND T1.'|| :columnName || ' >= ''' ||:FromDate||'''
 AND T1.'|| :columnName || ' <= ''' ||:ToDate||'''
 AND IFNULL(T2."InvType",''-1'') NOT IN (''13'',''14'',''18'',''19'',''203'',''204'',''24'',''46'',''30'')
 ';
                /* DEBUG 
 PRINT @sqlSelect 
 */
            ELSE 
                IF  :ObjectID = '30' THEN 
                    sqlSelect := :sqlSelect || '
                    
 SELECT 
 /* Unique IDs*/
 ''ObjType''||CAST(T1."ObjType" AS NVARCHAR(100))||''DocEntry''||CAST(T0."TransId" AS NVARCHAR(100)) AS DocID
 ,''ObjType''||CAST(T1."ObjType" AS NVARCHAR(100))||''DocEntry''||CAST(T0."TransId" AS NVARCHAR(100))||''InstID''||CAST(T0."Line_ID" || 1 AS NVARCHAR(100)) AS DocInstID
 /* Object */
 ,''' || :ObjectID || ''' AS ObjectID
 ,''' || :TableName || ''' AS TableName
 ,''' || :ObjDesc || ''' AS ObjDesc
 ,' || 'CASE T2."CardType" WHEN ''C'' THEN ''1'' ELSE ''-1'' END' || ' AS Factor
 /* Company */
 ,''' || :Country || ''' AS Country
 /* ODOC */
 ,T1.'|| :columnName3 || ' AS FilterDate
 ,T1."RefDate"
 ,T1."DueDate"
 ,T1."TaxDate"
 ,T0."ShortName" AS CardCode
 ,T2."CardName" AS CardName
 ,T1."TransCurr" AS DocCur
 ,T1."TransId" AS DocEntry
 ,T1."Number" AS DocNum
 ,''O'' AS DocStatus
 ,T1."FolioNum"
 ,T1."FolioPref"
 ,''N'' AS IsICT
 ,''N'' AS isIns
 ,T1."ObjType"
 ,''N'' AS PeyMethod
 ,''Y'' AS Posted
 ,'''' AS Model
 ,T1."Serial"
 ,T1."SeriesStr"
 ,T1."SubStr"
 ,T1."SeqCode"
 /* JDT1 */
 ,T0."DueDate"
 ,T0."Line_ID" AS InstlmntID
 ,' || 'CASE T2."CardType" WHEN ''C'' THEN T0."Debit" - T0."Credit" ELSE T0."Credit"-T0."Debit" END' || ' AS InsTotal
 ,' || 'CASE T2."CardType" WHEN ''C'' THEN T0."FCDebit" - T0."FCCredit" ELSE T0."FCCredit"-T0."FCDebit" END' || ' AS InsTotalFC
 ,' || 'CASE T2."CardType" WHEN ''C'' THEN T0."SYSDeb" - T0."SYSCred" ELSE T0."SYSCred"-T0."SYSDeb" END' || ' AS InsTotalSy
 ,T0."Debit" - T0."Credit" - (T0."BalDueDeb" - T0."BalDueCred") AS Paid
 ,T0."FCDebit" - T0."FCCredit" - (T0."BalFcDeb" - T0."BalFcCred") AS PaidFC
 ,T0."SYSDeb" - T0."SYSCred" - (T0."BalScDeb" - T0."BalScCred") AS PaidSc
 ,''O'' AS InsStatus
 /* OPAY */
 ,0.0 AS BoeSum
 ,0.0 AS BoeSumFc
 ,0.0 AS BoeSumSc
 ,0.0 AS CashSum
 ,0.0 AS CashSumFC
 ,0.0 AS CashSumSy
 ,0.0 AS CheckSum
 ,0.0 AS CheckSumFC
 ,0.0 AS CheckSumSy
 ,0.0 AS CreditSum
 ,0.0 AS CredSumFC
 ,0.0 AS CredSumSy
 ,0.0 AS TrsfrSum
 ,0.0 AS TrsfrSumFC
 ,0.0 AS TrsfrSumSy
 FROM ' || :TableName || '1 T0
 INNER JOIN O' || :TableName || ' T1 ON T0."TransId" = T1."TransId"
 INNER JOIN OCRD T2 ON T0."ShortName" = T2."CardCode"
 WHERE T1."TransType" = ''30''
 AND T0.'|| :columnName3 || ' >= ''' ||:FromDate||'''
 AND T0.'|| :columnName3 || ' <= ''' ||:ToDate||'''
 ';
                END IF;
                /* PART 3: MANUAL JOURNAL POSTINGS FOR BUSINESS PARTNERS */
            END IF;
            /* PART 2: PAYMENTS */
 /* DEBUG 
 PRINT @sqlSelect 
 */        

         END IF;
    END WHILE;
    CLOSE doctables_Cursor;
    delete from "CRSP_PaymentsOnInvoice";
    /* DEBUG 
PRINT @sqlSelect 
*/
	CALL CRSP_PayableReceivable_BR_enUS2(:PayDateType2, :PayDateFrom2, :PayDateTo2, v__sql);
	sqlSelect := 'select * from (' || :sqlSelect || ') t1 left outer join (' || v__sql  || ') t2 on t1."DOCINSTID"=t2."DOCINSTID"';-- select "DocEntry"from ORDR) t1 left outer join (select "DocEntry" from RDR1) t2 on t1."DocEntry"=t2."DocEntry"
    execute immediate (:sqlSelect);
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2
--DROP PROCEDURE CRSP_PayableReceivable_BR_enUS2
CREATE PROCEDURE CRSP_PayableReceivable_BR_enUS2
(
in PayDateType nvarchar(150),
in PayDateFrom timestamp,
in PayDateTo timestamp,
out v__sql nvarchar(5000)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
DateType nvarchar(150);
FromDate timestamp;
ToDate timestamp;
FinancYear timestamp;
Country nvarchar(3);
sqlSelect nvarchar(32000);
ObjectID nvarchar(20);
TableName nvarchar(3);
ObjDesc nvarchar(100);
Factor nvarchar(2);
temp_var_0 integer;
next INT;
columnName nvarchar(100);
CURSOR doctables_Cursor FOR SELECT "ObjectID", "TableName", "ObjDesc", 
    "Factor"
FROM "CRSP_PaymentsOnInvoice" 
WHERE "ObjectID" IN ('24','46');

BEGIN /*
***** General Information *****
Name: OPAY_PaymentsOnInvoices
Description:
Returns the Relevant information of incoming and outgoing payments linked invoices

Creator: coresystems ag, muf@coresystems.ch
Create Date: 2011-20-10

***** Updates *****

*/
    /* ***** PARAMETERS FOR STANDARD FILTERS ***** */
    /* ***** DEFAULT PARAMETER VALUES ***** */
    DateType := 'DocDate';
    /* Get the current Date without the time */
    SELECT TO_TIMESTAMP(CURRENT_DATE, 'YYYY-MM-DD') into ToDate FROM DUMMY;
    /* Get the current Finance Year */
    SELECT 
    (SELECT T0."FinancYear" 
    FROM OACP T0 
        INNER JOIN OFPR T1 ON T0."PeriodCat" = T1."Category" 
    WHERE T1."F_RefDate" <= :ToDate AND T1."T_RefDate" >= :ToDate) INTO FinancYear FROM DUMMY;
    FromDate := ADD_YEARS(:FinancYear, -1);
    ToDate := ADD_DAYS(ADD_YEARS(:FinancYear, 1), -1);
    /* Set the parameter values (comment for debugging) */
    DateType := :PayDateType;
    FromDate := :PayDateFrom;
    ToDate := :PayDateTo;
    /* ***** INTERNAL PARAMETERS ***** */
    SELECT 
    	(SELECT "LawsSet" FROM CINF) 
    INTO Country FROM DUMMY;
    sqlSelect := '';
    /* ***** CREATE A TEMP TABLE TO STORE THE RELEVANT INFORMATION FOR ALL SUPPORTED MARKETING DOCUMENTS ***** */
	
	insert into "CRSP_PaymentsOnInvoice" values( '13', 'INV', 'AR Invoice', '1');
    insert into "CRSP_PaymentsOnInvoice" values( '14', 'RIN', 'AR Credit Note', '-1');
    insert into "CRSP_PaymentsOnInvoice" values( '15', 'DLN', 'Delivery', '1');
    insert into "CRSP_PaymentsOnInvoice" values( '17', 'RDR', 'Sales Order', '1');
    insert into "CRSP_PaymentsOnInvoice" values( '18', 'PCH', 'AP Invoice', '-1');
    insert into "CRSP_PaymentsOnInvoice" values( '19', 'RPC', 'AP Credit Note', '1');
    insert into "CRSP_PaymentsOnInvoice" values( '20', 'PDN', 'Goods Receipt PO', '-1');
    insert into "CRSP_PaymentsOnInvoice" values( '203', 'DPI', 'AR Down Payment', '1');
    insert into "CRSP_PaymentsOnInvoice" values( '204', 'DPO', 'AP Down Payment', '-1'); 
    insert into "CRSP_PaymentsOnInvoice" values( '22', 'POR', 'Purchase Order', '-1'); 
    insert into "CRSP_PaymentsOnInvoice" values( '23', 'QUT', 'Sales Quotation', '1');
    insert into "CRSP_PaymentsOnInvoice" values( '30', 'JDT', 'Journal Entries', '1'); 
    insert into "CRSP_PaymentsOnInvoice" values( '24', 'RCT', 'Incoming Payment', '1'); 
    insert into "CRSP_PaymentsOnInvoice" values( '46', 'VPM', 'Outgoing Payment', '-1');
    
    /* ***** CREATE THE CURSOR FOR THE TABLES TO USE. 
 	Define here which tables are interesting for the report
	***** */
	
    --OPEN doctables_Cursor;
    OPEN doctables_Cursor;
    
	next := 1;
	WHILE :next > 0 DO
    	FETCH doctables_Cursor INTO ObjectID, TableName, ObjDesc, Factor;
    	if doctables_Cursor::NOTFOUND THEN
    		next := -1;
    		continue;
    	end if;
    	IF :sqlSelect <> '' THEN 
    		sqlSelect := :sqlSelect || 'UNION ALL';
    	END IF;
    	if (:DateType = 'DocDueDate') then
    		columnName := '"DocDueDate"';
    	end if;
    	if (:DateType = 'TaxDate') then
    		columnName := '"TaxDate"';
    	else
    		columnName := '"DocDate"';
    	end if;
        sqlSelect := :sqlSelect || '  
  SELECT
  /* Unique IDs*/
''ObjType''||CAST(IFNULL(T2."InvType",0) AS NVARCHAR(100))||''DocEntry''||CAST(IFNULL(T2."DocEntry",0) AS NVARCHAR(100)) AS DocID
 ,''ObjType''||CAST(IFNULL(T2."InvType",0) AS NVARCHAR(100))||''DocEntry''||CAST(IFNULL(T2."DocEntry",0) AS NVARCHAR(100))||''InstID''||CAST(IFNULL(T2."DocLine",-1) + 1 AS NVARCHAR(100)) AS DocInstID
 ,''ObjType''||CAST(T1."ObjType" AS NVARCHAR(100))||''DocEntry''||CAST(T1."DocEntry" AS NVARCHAR(100)) AS PayID
 ,''ObjType''||CAST(IFNULL(T1."ObjType",0) AS NVARCHAR(100))||''DocEntry''||CAST(IFNULL(T1."DocEntry",0) AS NVARCHAR(100))||''InvoiceId''||CAST(IFNULL(T2."InvoiceId",0) AS NVARCHAR(100)) AS PayInvID
 /* Object */
 ,''' || :ObjectID || ''' AS ObjectID
 ,''' || :TableName || ''' AS TableName
 ,''' || :ObjDesc || ''' AS ObjDesc
 ,' || :Factor || ' AS Factor
 /* Company */
 ,''' || :Country || ''' AS Country
 /* PAY2 */
 ,T2."InvType"
 ,T2."DocEntry" AS InvEntry
 ,T2."InvoiceId"
 ,T2."DocLine" AS InvLine
 ,T1.'|| :columnName || ' AS FilterDate
 /* OPAY */
 ,T1."DocDate"
 ,T1."DocDueDate"
 ,T1."TaxDate"
 ,T1."CardCode"
 ,T1."CardName"
 ,T1."DocCurr" AS DocCur
 ,T1."DocEntry"
 ,T1."DocNum"
 ,T1."Status" AS DocStatus
 ,T1."ObjType"
 ,T1."Serial"
 ,T1."SeriesStr"
 ,T1."SubStr"
 ,T1."SeqCode"
 ,T1."BoeSum"
 ,T1."BoeSumFc"
 ,T1."BoeSumSc"
 ,T1."CashSum"
 ,T1."CashSumFC"
 ,T1."CashSumSy"
 ,T1."CheckSum"
 ,T1."CheckSumFC"
 ,T1."CheckSumSy"
 ,T1."CreditSum"
 ,T1."CredSumFC"
 ,T1."CredSumSy"
 ,T1."TrsfrSum"
 ,T1."TrsfrSumFC"
 ,T1."TrsfrSumSy"
 /* PAY2 */
 ,T2."SumApplied"
 ,T2."AppliedFC"
 ,T2."AppliedSys"
 FROM O' || :TableName || ' T1
 LEFT OUTER JOIN ' || :TableName || '2 T2 ON T1."DocEntry" = T2."DocNum"
 WHERE T1."Canceled" = ''N''
 AND T1.'|| :columnName || ' >= ''' ||:FromDate||'''
 AND T1.'|| :columnName || ' <= ''' ||:ToDate||'''
 AND T2."InvType" IN (''13'',''14'',''18'',''19'',''203'',''204'',''24'',''46'',''30'')
 ';


/* DEBUG 
 PRINT @sqlSelect 
 */
    END WHILE;
    
	CLOSE doctables_Cursor;
    
	delete from "CRSP_PaymentsOnInvoice";
    /* DEBUG 
PRINT @sqlSelect 
*/
	v__sql := :sqlSelect;
    --execute immediate(:sqlSelect);
	
END;

-- B1 DEPENDS: AFTER:SP:CRSP_POIL_INTERNAL_GETINCCOMPAREUNIT AFTER:SP:CRSP_POIL_INTERNAL_ADDTONTHLINE AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_POIL_DOCUMENTS (in DocEntryIn integer, in object nvarchar(4)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
strSQL nvarchar(5000);
DocEntry integer;
searchRow integer;
searchVal nvarchar(5000);
matchRow integer;
matchVal nvarchar(5000);
searchUnitSize integer;
matchUnitSize integer;
joinRow integer;
lineFrom integer;
lineTo integer;
joined nvarchar(1);
recNum integer;
exists1 integer;
i integer;
tmpStr nvarchar(2000);

CURSOR c_cursor1 FOR SELECT "Joined" FROM "CR_SalesBOMSummaryByItem" ORDER BY "VisOrder";
CURSOR c_cursor2 FOR SELECT "Joined" FROM "CR_SalesBOMSummaryByItem" ORDER BY "VisOrder";

BEGIN 

	delete from "CR_BeforeSummaryINV1";
	delete from "CR_SalesBOMSummaryByItem";
	
	--The main logic code simulates the C++ code
	--in B1 source code function SRIncByItem
	    
    DocEntry := DocEntryIn;
    --Get the Whole Data of INV1
    --Result table

	tmpStr := 'INSERT INTO "CR_BeforeSummaryINV1" (SELECT 
    	"VisOrder", 
    	''N'' AS "Joined",     
    	"ItemCode", 
		IFNULL(' || :object || '."SubCatNum", ''''),
		"Dscription",
		"TreeType",
		"UseBaseUn",
		"Price",
		"DiscPrcnt",
		"Factor1", 
		"Factor2",
		"Factor3",
		"Factor4",
		"PriceAfVAT",
		"TaxOnly",
		IFNULL(' || :object || '."unitMsr", ''''),
		"NumPerMsr",
		"WhsCode",
		"Quantity",
		"PriceBefDi",
		"LineTotal",
		"TotalSumSy",
		"TotalFrgn"    
     FROM ' || :object || ' WHERE ' || :object || '."DocEntry" = ' || :DocEntry || ')';
     
    exec(:tmpStr);

    tmpStr := 'INSERT INTO "CR_SalesBOMSummaryByItem" (SELECT "DocEntry", ''N'' AS "Joined", "VisOrder", "TreeType", "VendorNum", 
        "ItemCode", "Dscription", "Quantity", "unitMsr", "Price", "DiscPrcnt", "PriceBefDi", "LineTotal", 
        "TotalSumSy", "TotalFrgn", "Currency", "WhsCode" FROM ' || :object || ' WHERE ' || :object || '."DocEntry" = ' || :DocEntry || ')';
       
    exec(:tmpStr);
      
    searchRow := 1;
    searchVal := '';
    matchRow := 1;
    matchVal := '';
    searchUnitSize := 1;
    matchUnitSize := 1;
    joinRow := 0;
    SELECT COUNT(*) INTO recNum FROM "CR_BeforeSummaryINV1";
    WHILE :searchRow <= :recNum DO 
        --CALL CRSP_POIL_INTERNAL_ISJOINED(:searchRow, :joined);

		i := 1;
		OPEN c_cursor1;
		FETCH c_cursor1 INTO joined;
		
		WHILE ((NOT c_cursor1::NOTFOUND) AND :i < :searchRow) DO
			i := :i + 1;
			FETCH c_cursor1 INTO joined;
		END WHILE;			
		close c_cursor1;
       
        IF :joined = 'Y' THEN 
            searchUnitSize := 1;
            searchRow := :searchRow + :searchUnitSize;
            CONTINUE;
        END IF;

                  
        CALL CRSP_POIL_INTERNAL_GETINCCOMPAREUNIT(:searchRow, :searchVal, :searchUnitSize);
       
        matchRow := :searchRow + :searchUnitSize;
        WHILE :matchRow <= :recNum DO 
            --CALL CRSP_POIL_INTERNAL_ISJOINED(:matchRow, :joined);
			i := 1;
			OPEN c_cursor2;
			FETCH c_cursor2 INTO joined;
			
			WHILE ((NOT c_cursor2::NOTFOUND) AND :i < :searchRow) DO
				i := :i + 1;
				FETCH c_cursor2 INTO joined;
			END WHILE;			
			close c_cursor2;
			
            IF :joined = 'Y' THEN 
                matchUnitSize := 1;
                matchRow := :matchRow + :matchUnitSize;
                CONTINUE;
            END IF;
            CALL CRSP_POIL_INTERNAL_GETINCCOMPAREUNIT(:matchRow, :matchVal, :matchUnitSize);
            IF :matchUnitSize = :SearchUnitSize AND :searchVal = :matchVal THEN 
                joinRow := 0;
                WHILE :joinRow < :searchUnitSize DO 
                    lineTo := :joinRow + :searchRow;
                    lineFrom := :joinRow + :matchRow;
                    --SELECT 'match ' || CAST(:lineTo AS nvarchar(4)) || ':' || CAST(:lineFrom AS nvarchar(4)) FROM DUMMY;
                    --[Note:Modifier] SAP HANA does not have CONVERT function; you may use CAST function or use implicit casting functions
                    CALL CRSP_POIL_INTERNAL_ADDTONTHLINE(:lineTo, :lineFrom);
                    joinRow := :joinRow + 1;
                END WHILE;
            END IF;
            matchRow := :matchRow + :matchUnitSize;
        END WHILE;
        searchRow := :searchRow + :searchUnitSize;
    END WHILE;

    DELETE FROM "CR_SalesBOMSummaryByItem" WHERE "Joined" = 'Y';
	
    --Result
    SELECT "DocEntry", "Joined", "VisOrder", "TreeType", "VendorNum", "ItemCode", "Dscription", "Quantity", 
        "unitMsr", "Price", "Discprcnt", "PriceBefDi", "LineTotal", "TotalSumSy", "TotalFrgn", "Currency", 
        T0."WhsCode", T1."WhsName" 
    FROM "CR_SalesBOMSummaryByItem" T0 
        LEFT OUTER JOIN OWHS T1 ON T0."WhsCode" = T1."WhsCode";
        
    delete from "CR_BeforeSummaryINV1";
	delete from "CR_SalesBOMSummaryByItem";    
    
END;

-- B1 DEPENDS: AFTER:SP:CRSP_POIL_INTERNAL_GETDOCNTHLINE

CREATE PROCEDURE CRSP_POIL_INTERNAL_ADDTONTHLINE (IN lineTo integer, IN lineFrom integer) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
itemCode nvarchar(50);
subCatNum nvarchar(20);
description nvarchar(100);
treeType nvarchar(1);
useBaseUn nvarchar(1);
price DECIMAL(21,6);
discPrcnt DECIMAL(21,6);
factor1 DECIMAL(21,6);
factor2 DECIMAL(21,6);
factor3 DECIMAL(21,6);
factor4 DECIMAL(21,6);
priceAfVAT DECIMAL(21,6);
taxOnly nvarchar(1);
unitMsr nvarchar(20);
numPerMsr DECIMAL(21,6);
whsCode nvarchar(20);
joined nvarchar(1);
quantity DECIMAL(21,6);
priceBefDi DECIMAL(21,6);
lineTotal DECIMAL(21,6);
totalSumSy DECIMAL(21,6);
totalFrgn DECIMAL(21,6);

BEGIN 
	CALL CRSP_POIL_INTERNAL_GETDOCNTHLINE(:lineFrom, 1, :itemCode, :subCatNum, :description, :treeType, :useBaseUn, :price, :discPrcnt,
	 :factor1, :factor2, :factor3, :factor4, :priceAfVAT, :taxOnly, :unitMsr, :numPerMsr, :whsCode, :joined,
     :quantity, :priceBefDi, :lineTotal, :totalSumSy, :totalFrgn);

    UPDATE "CR_SalesBOMSummaryByItem" SET "Quantity" = "Quantity" + :quantity, "LineTotal" = "LineTotal" +
         :lineTotal, "TotalSumSy" = "TotalSumSy" + :totalSumSy, "TotalFrgn" = "TotalFrgn" + :totalFrgn 
    WHERE "VisOrder" = :lineTo - 1;

    UPDATE "CR_SalesBOMSummaryByItem" SET "Joined" = 'Y' Where "VisOrder" = :lineFrom -1;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables

CREATE PROCEDURE CRSP_POIL_INTERNAL_GETDOCNTHLINE(
	IN recOffset integer,
	IN isSearchTable integer,
	OUT itemCode nvarchar(50),
	OUT subCatNum nvarchar(20),
	OUT description nvarchar(100),
	OUT treeType nvarchar(1),
	OUT useBaseUn nvarchar(1),
	OUT price DECIMAL(21,6),
	OUT discPrcnt DECIMAL(21,6),
	OUT factor1 DECIMAL(21,6),
	OUT factor2 DECIMAL(21,6),
	OUT factor3 DECIMAL(21,6),
	OUT factor4 DECIMAL(21,6),
	OUT priceAfVAT DECIMAL(21,6),
	OUT taxOnly nvarchar(1),
	OUT unitMsr nvarchar(20),
	OUT numPerMsr DECIMAL(21,6),
	OUT whsCode nvarchar(20),
	OUT joined nvarchar(1),
	OUT quantity DECIMAL(21,6),
	OUT priceBefDi DECIMAL(21,6),
	OUT lineTotal DECIMAL(21,6),
	OUT totalSumSy DECIMAL(21,6),
	OUT totalFrgn DECIMAL(21,6)
) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	i int;	
	
	CURSOR c_cursor1 FOR SELECT "ItemCode", "SubCatNum", "Dscription", "TreeType", "UseBaseUn", "Price", "DiscPrcnt", "Factor1", "Factor2",
		 "Factor3", "Factor4", "PriceAfVAT", "TaxOnly", "unitMsr", "NumPerMsr", "WhsCode", "Joined", "Quantity", "PriceBefDi", "LineTotal",
		 "TotalSumSy", "TotalFrgn" FROM "CR_BeforeSummaryINV1" ORDER BY "VisOrder";
BEGIN
	i := 1;
	OPEN c_cursor1;
	FETCH c_cursor1 INTO itemCode, subCatNum, description, treeType, useBaseUn, 
		price, discPrcnt, factor1, factor2, factor3, factor4, priceAfVAT, taxOnly, unitMsr, numPerMsr, whsCode, joined, 
		quantity, priceBefDi, lineTotal, totalSumSy, totalFrgn;

	WHILE ((NOT c_cursor1::NOTFOUND) AND :i < :recOffset) DO
		i := :i + 1;
		FETCH c_cursor1 INTO itemCode, subCatNum, description, treeType, useBaseUn, 
			price, discPrcnt, factor1, factor2, factor3, factor4, priceAfVAT, taxOnly, unitMsr, numPerMsr, whsCode, joined, 
			quantity, priceBefDi, lineTotal, totalSumSy, totalFrgn;
	END WHILE;	
 	
 	CLOSE c_cursor1;
END;

-- B1 DEPENDS: AFTER:SP:CRSP_POIL_INTERNAL_GETNUMOFINGREDIENTS AFTER:SP:CRSP_POIL_INTERNAL_GETDOCNTHLINE AFTER:SP:CRSP_POIL_INTERNAL_GETSUMMARYCOMPARECOLSTRING

CREATE PROCEDURE CRSP_POIL_INTERNAL_GETINCCOMPAREUNIT (
	IN paramStartLine integer, 
	OUT outparamString nvarchar(5000), 
	OUT outparamNumOfLines integer) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	inc integer;
	p_itemCode nvarchar(50);
	p_subCatNum nvarchar(20);
	p_description nvarchar(100);
	p_treeType nvarchar(1);
	p_useBaseUn nvarchar(1);
	p_price DECIMAL(21,6);
	p_discPrcnt DECIMAL(21,6);
	p_factor1 DECIMAL(21,6);
	p_factor2 DECIMAL(21,6);
	p_factor3 DECIMAL(21,6);
	p_factor4 DECIMAL(21,6);
	p_priceAfVAT DECIMAL(21,6);
	p_taxOnly nvarchar(1);
	p_unitMsr nvarchar(20);
	p_numPerMsr DECIMAL(21,6);
	p_whsCode nvarchar(20);
	p_joined nvarchar(1);
	p_quantity DECIMAL(21,6);
	p_priceBefDi DECIMAL(21,6);
	p_lineTotal DECIMAL(21,6);
	p_totalSumSy DECIMAL(21,6);
	p_totalFrgn DECIMAL(21,6);
	lineNumber integer;
	summaryCompareColString nvarchar(1000);
BEGIN 
	CALL CRSP_POIL_INTERNAL_GETNUMOFINGREDIENTS(:paramStartLine, :outparamNumOfLines);

    outparamNumOfLines := :outparamNumOfLines + 1;
    inc := 0;
    outparamString := '';
    WHILE :inc < :outparamNumOfLines DO 
        lineNumber := :inc +:paramStartLine;
		
        CALL CRSP_POIL_INTERNAL_GETDOCNTHLINE(:lineNumber, 1, :p_itemCode, :p_subCatNum, :p_description, :p_treeType, :p_useBaseUn, :p_price,
			:p_discPrcnt, :p_factor1, :p_factor2, :p_factor3, :p_factor4, :p_priceAfVAT, :p_taxOnly, :p_unitMsr, :p_numPerMsr,
			:p_whsCode, :p_joined, :p_quantity, :p_priceBefDi, :p_lineTotal, :p_totalSumSy, :p_totalFrgn);
	
		CALL CRSP_POIL_INTERNAL_GETSUMMARYCOMPARECOLSTRING(IFNULL(:p_itemCode, ''), IFNULL(:p_subCatNum, ''), IFNULL(:p_description, ''), IFNULL(:p_treeType, ''), IFNULL(:p_useBaseUn, ''), IFNULL(:p_price, '0'), IFNULL(:p_discPrcnt, '0'),
			IFNULL(:p_factor1, '0'), IFNULL(:p_factor1, '0'), IFNULL(:p_factor1, '0'), IFNULL(:p_factor1, '0'), IFNULL(:p_priceAfVAT, '0'), :p_taxOnly, IFNULL(:p_unitMsr, ''), IFNULL(:p_numPerMsr, '0'), IFNULL(:p_whsCode,''), :summaryCompareColString);	
	
        inc := :inc + 1;
        outparamString := :outparamString || :summaryCompareColString;
    END WHILE;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables

CREATE PROCEDURE CRSP_POIL_INTERNAL_GETNUMOFINGREDIENTS (IN paramFatherRow integer, OUT paramNumOfSons integer) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	treeTyp nvarchar(1);
	CURSOR treeType_Cursor FOR SELECT "TreeType" FROM "CR_BeforeSummaryINV1";
	inc integer;
BEGIN 
	inc := 0;
    paramNumOfSons := 0;
	
    OPEN treeType_Cursor;
    FETCH treeType_Cursor INTO treeTyp;
	
    WHILE NOT treeType_Cursor::NOTFOUND DO 
        inc := :inc + 1;
        IF :inc >= :paramFatherRow + 1 THEN 
            IF :treeTyp <> 'I' THEN 
                BREAK;
            END IF;
            paramNumOfSons := :paramNumOfSons + 1;
        END IF;
        FETCH treeType_Cursor INTO treeTyp;
    END WHILE;
	
    CLOSE treeType_Cursor;    
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables

CREATE PROCEDURE CRSP_POIL_INTERNAL_GETSUMMARYCOMPARECOLSTRING (
	IN itemCode nvarchar(50),
	IN subCatNum nvarchar(20),
	IN description nvarchar(100),
	IN treeType nvarchar(1),
	IN useBaseUn nvarchar(1),
	IN price nvarchar(20),
	IN discPrcnt nvarchar(20),
	IN factor1 nvarchar(20),
	IN factor2 nvarchar(20),
	IN factor3 nvarchar(20),
	IN factor4 nvarchar(20),
	IN priceAfVAT nvarchar(20),
	IN taxOnly nvarchar(1),
	IN unitMsr nvarchar(20),
	IN numPerMsr nvarchar(20),
	IN whsCode nvarchar(20),
	OUT retVal nvarchar(1000)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN
	SELECT :itemCode || ',' || IFNULL(:subCatNum, '') || ',' || IFNULL(:description, '') || ',' || IFNULL(:treeType, '') || ',' || 
		IFNULL(:useBaseUn, '') || ',' || IFNULL(:price, '0') || ',' || 
		IFNULL(:discPrcnt, '0') || ',' || IFNULL(:factor1, '0') || ',' ||
		IFNULL(:factor2, '0') || ',' || IFNULL(:factor3, '0') || ',' || 
		IFNULL(:factor4, '0') || ',' || 
		IFNULL(:priceAfVAT, '0') || ',' || :taxOnly || ',' || IFNULL(:unitMsr, '') || ',' || 
		IFNULL(:numPerMsr, '0') || ',' || IFNULL(:whsCode, '') INTO retVal FROM DUMMY;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables

CREATE PROCEDURE CRSP_POIL_INTERNAL_ISJOINED (IN line integer, OUT joined nvarchar(1)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
	i int;	
	CURSOR c_cursor1 FOR SELECT "Joined" FROM "CR_SalesBOMSummaryByItem" ORDER BY "VisOrder";
BEGIN
	i := 1;
	OPEN c_cursor1;
	FETCH c_cursor1 INTO joined;

	WHILE ((NOT c_cursor1::NOTFOUND) AND :i < :line) DO
		i := :i + 1;
		FETCH c_cursor1 INTO joined;
	END WHILE;	
 	
 	CLOSE c_cursor1;
END;

-- B1 DEPENDS: AFTER:SP:CRSP_ProfitAndLostByCC_BR_enUS_cont
/*
    
***** General Information *****
Name: JDT1_AccountCalc (including Prepare for account structure)
Description: Return Journal Entries distributed according to distribution rules to cost centers
with relevant filters
Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22

HANA version converted by SAP
*/
CREATE PROCEDURE CRSP_ProfitAndLostByCC_BR_enUS (in planId nvarchar(20), in Currency nvarchar(10), in ignoreAdj_in varchar(1), in AddVoucher_in varchar(1),
	in DateType varchar(256),
	in DimCode nvarchar(10),			/* Dimension new since Version 8.81.*/ 
	in budgId_in nvarchar(20),
	in FromDate timeStamp,			/* Date Filter From and To Dates. Format 'YYYYMMDD' */ /* timestamp original */
	in ToDate timeStamp				/* Date Filter From and To Dates. Format 'YYYYMMDD' */ /* timestamp original */	
	)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
 
AS 
MinGroupMask integer;
PlanType varchar(1);
IgnoreAdj varchar(1);
AddVoucher varchar(1);			
OcrCode nvarchar(5000);
PrcCode nvarchar(5000);
PrjCode nvarchar(5000);
BudgId int;
BroughtForward varchar(1);
EndYear varchar(1);
MainCurr varchar(3);
SysCurr varchar(3);
FinancYear timestamp;
UpperBoundary timestamp;
BEGIN 
	
	delete from "CRSPProfitLostByCCBR_JDT1";
	delete from "CRSPProfitLostByCCBR_Res";
	delete from "CRSPProfitLostByCCBR_OCR1DistRule";
	delete from "CRSPProfitLostByCCBR_TmplAcct";
	delete from "CRSPProfitLostByCCBR_Plan";
	delete from "CRSPProfitLostByCCBR_Plan0";
	delete from "CRSPProfitLostByCCBR_AcctLang";
	
	--Set future date when null date is in db field
	select ADD_DAYS(ADD_MONTHS(ADD_YEARS('1900-01-01',YEAR(NOW()) - 1900 + 99), MONTH(NOW()) - 1), DAYOFMONTH(NOW()) - 1) into UpperBoundary from DUMMY;

	--Set date format dmy - skipped
    /*
     Here we define the type of the report (P = Profit and Loss) and the Minimum Group Mask for Profit and Loss accounts 
This can be different for different localizations a mapping should be included. 
Therefore it is not supported in the official Version. It is kept in the datasource to enable this option in case a customer needs it. Then the MinGroupMask can be adjusted. 
    */
    MinGroupMask := 3;
    PlanType := 'P';
    /* Select which currency to display in the report */
    /* Parameters for AccountCalc */
    /*
     Include Journal Entries with checkbox "Ignore Adjustments (13. Per)" selected (Y) or not (N). Param '[%IgnoreAdj]' 
    */
    IF :ignoreAdj_in = '0' THEN 
        IgnoreAdj := 'N';
    ELSE 
        IgnoreAdj := 'Y';
        /* Include Journal Vouchers (Y) or not (N). */
    END IF;
    IF :AddVoucher_in = '0' THEN 
        AddVoucher := 'N';
    ELSE 
        AddVoucher := 'Y';
        /* Date Type to set the filter and sort by. Possible values are RefDate, TaxDate and DueDate. */
    END IF;

    /* Filter for Cost Center, Distribution Rules, Projects and Budget.
	In Crystal Reports this filter is set in the report itself */
    OcrCode := '';
    PrcCode := '';
    PrjCode := '';
    /* Include Amount Brought Forward (Y) or not (N). */
    /* Hardcoded for this report */
    BroughtForward := 'N';
    /* Include End Year Closing (Y) or not (N). */
    /* Hardcoded for this report */
    EndYear := 'N';
	
    /* Internal Parameters */
    /* Local Currency */
    SELECT TOP 1 T2."MainCurncy" INTO MainCurr FROM OADM T2;
    /* System Currency */
	SELECT TOP 1 T2."SysCurrncy" INTO SysCurr FROM OADM T2;	
	
    /* The Finance Year is determined by the RefDate no matter how the parameter DateType is set */
    SELECT TOP 1 T0."FinancYear" INTO FinancYear 
    FROM OACP T0 
    INNER JOIN OFPR T1 ON T0."PeriodCat" = T1."Category"
    WHERE T1."F_RefDate" <= :ToDate AND T1."T_RefDate" >= :ToDate;
   
   /* If BudgetId = -1, all Budgetdata includet to the total */
    IF :budgId_in = '' THEN 
        BudgId := -1;
    ELSE 
    	BudgId := :budgId_in;
    END IF;
	
    INSERT INTO "CRSPProfitLostByCCBR_TmplAcct"
	SELECT CAST(T0."CatId" AS nvarchar(32)) AS "Code", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherNum", 
        T0."Name" AS "Description", T0."Levels" AS "Lvl", T0."VisOrder" * 10000 AS "Sort", T2."DocType", 
        'N' AS "Postable", CAST(T0."CatId" AS nvarchar(32)) AS "FormatCode", 
        CAST(T0."CatId" AS nvarchar(32)) AS "AcctCodeDisp", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_0", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_1", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_2", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_3", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_4", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_5", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_6", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_7", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_8", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_9", '##' AS "ActCurr", 0 AS "GroupMask", 
        CAST(T0."CatId" AS nvarchar(32)) AS "AccntntCod", T0."FrgnName" 
    FROM OFRC T0 
    INNER JOIN OFRT T2 ON T0."TemplateId" = T2."AbsId" 
    WHERE CAST(T0."TemplateId" AS nvarchar) = :planId 
	
    UNION 
	
    SELECT CAST(LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) AS nvarchar(32)) AS "Code", 
        CAST(T0."CatId" AS nvarchar(32)) AS "FatherNum", T1."AcctName" AS "Description", 
        (SELECT MAX("Levels") 
        FROM OFRC 
        WHERE "CatId" = T0."CatId" AND CAST("TemplateId" AS nvarchar) = :planId) + 1 AS "Lvl", 
        (SELECT MAX("VisOrder") * 10000 
        FROM OFRC 
        WHERE "CatId" = T0."CatId" AND CAST("TemplateId" AS nvarchar) = :planId) + T0."VisOrder" AS "Sort", 
        T2."DocType", 'Y' AS "Postable", LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) AS "FormatCode", 
        CASE 
            WHEN T1."FormatCode" IS NULL THEN LTRIM(RTRIM(T1."AcctCode")) 
            WHEN T1."FormatCode" = T1."AcctCode" THEN LTRIM(RTRIM(T1."AcctCode")) 
            ELSE REPLACE( 
				IFNULL(T1."Segment_0", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_1", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_2", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_3", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_4", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_5", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_6", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_7", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_8", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T1."Segment_9", 'x'), 
				(SELECT TOP 1 "ActSep" FROM OADM) || 'x', '') 
        END AS "AcctCodeDisp", 
		T1."Segment_0", T1."Segment_1", T1."Segment_2", T1."Segment_3", T1."Segment_4", 
        T1."Segment_5", T1."Segment_6", T1."Segment_7", T1."Segment_8", T1."Segment_9", 
		T1."ActCurr", T1."GroupMask", T1."AccntntCod", T1."FrgnName" 
    FROM FRC1 T0 
        INNER JOIN OACT T1 ON T0."AcctCode" = T1."AcctCode" 
        INNER JOIN OFRT T2 ON T0."TemplateId" = T2."AbsId" 
    WHERE CAST(T0."TemplateId" AS nvarchar) = :planId;
    
	/* The Accounts (including Template) */
	INSERT INTO "CRSPProfitLostByCCBR_AcctLang"
    SELECT "AcctCode" AS "Code", "AcctName" AS "Description" FROM OACT WHERE :planId = '@@Account' 
    UNION 
    SELECT "Code", "Description" FROM "CRSPProfitLostByCCBR_TmplAcct"  WHERE :planId <> '@@Account';
	
    /* OACT Structure */
	INSERT INTO "CRSPProfitLostByCCBR_Plan0"
    SELECT T0."Levels" AS "Lvl", T0."AcctCode" AS "AcctCode", T0."AcctName" AS "Description", 
		T0."Postable", 0.0 AS "Variator", '' AS "Liq", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T6."FormatCode", T6."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T7."FormatCode", T7."AcctCode"))) 
            ELSE '' 
        END AS "Level1", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T6."FormatCode", T6."AcctCode"))) 
            ELSE '' 
        END AS "Level2", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            ELSE '' 
        END AS "Level3", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            ELSE '' 
        END AS "Level4", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            ELSE '' 
        END AS "Level5", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            ELSE '' 
        END AS "Level6", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."FormatCode")) 
            ELSE '' 
        END AS "Level8", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T6."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T7."AccntntCod")) 
            ELSE '' 
        END AS "Level1AccntntCod", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T6."AccntntCod")) 
            ELSE '' 
        END AS "Level2AccntntCod", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            ELSE '' 
        END AS "Level3AccntntCod", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            ELSE '' 
        END AS "Level4AccntntCod", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            ELSE '' 
        END AS "Level5AccntntCod", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            ELSE '' 
        END AS "Level6AccntntCod", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            ELSE '' 
        END AS "Level7AccntntCod", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            ELSE '' 
        END AS "Level8AccntntCod", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T5."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T6."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T7."FrgnName")) 
            ELSE '' 
        END AS "Level1FrgnName", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T5."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T6."FrgnName")) 
            ELSE '' 
        END AS "Level2FrgnName", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T5."FrgnName")) 
            ELSE '' 
        END AS "Level3FrgnName", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T4."FrgnName")) 
            ELSE '' 
        END AS "Level4FrgnName", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T3."FrgnName")) 
            ELSE '' 
        END AS "Level5FrgnName", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T2."FrgnName")) 
            ELSE '' 
        END AS "Level6FrgnName", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T1."FrgnName")) 
            ELSE '' 
        END AS "Level7FrgnName", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."FrgnName")) 
            ELSE '' 
        END AS "Level8FrgnName", T0."GroupMask" * 10000 + T0."GrpLine" AS "Sort", 
        CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherId", 
		CAST(T0."AcctCode" AS nvarchar(32)) AS "Id", 
        LTRIM(RTRIM(IFNULL(T0."FormatCode", T0."AcctCode"))) AS "FormatCode", 
        CASE 
            WHEN T0."FormatCode" IS NULL THEN LTRIM(RTRIM(T0."AcctCode")) 
            WHEN T0."FormatCode" = T0."AcctCode" THEN LTRIM(RTRIM(T0."AcctCode")) 
            ELSE REPLACE(
				IFNULL(T0."Segment_0", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_1", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_2", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_3", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_4", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_5", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_6", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_7", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_8", 'x') || (SELECT TOP 1 "ActSep" FROM OADM) || 
				IFNULL(T0."Segment_9", 'x'), 
				(SELECT TOP 1 "ActSep" FROM OADM) || 'x', '') 
		END AS "AcctCodeDisp", 
		T0."Segment_0", T0."Segment_1", T0."Segment_2", T0."Segment_3", T0."Segment_4", 
        T0."Segment_5", T0."Segment_6", T0."Segment_7", T0."Segment_8", T0."Segment_9", 
		T0."ActCurr", T0."GroupMask", 
		/* This is important to know which Group Masks belong to Balance and which to Profit and Loss 
		   It can change for different localizations */
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END AS "DocType", 
		T0."AccntntCod", T0."FrgnName" 
    FROM OACT T0 
        LEFT OUTER JOIN OACT T1 ON T0."FatherNum" = T1."AcctCode" 
        LEFT OUTER JOIN OACT T2 ON T1."FatherNum" = T2."AcctCode" 
        LEFT OUTER JOIN OACT T3 ON T2."FatherNum" = T3."AcctCode" 
        LEFT OUTER JOIN OACT T4 ON T3."FatherNum" = T4."AcctCode" 
        LEFT OUTER JOIN OACT T5 ON T4."FatherNum" = T5."AcctCode" 
        LEFT OUTER JOIN OACT T6 ON T5."FatherNum" = T6."AcctCode" 
        LEFT OUTER JOIN OACT T7 ON T6."FatherNum" = T7."AcctCode" 
    WHERE :planId = '@@Account' AND ((:PlanType = 'P' AND 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' ELSE 'B' END = 'P') OR 
			(:PlanType = 'B' AND 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END = 'B') OR :PlanType = '')
		
    UNION 
	
    SELECT T0."Lvl", T0."Code" AS "AcctCode", T0."Description", T0."Postable", 
		0.0 AS "Variator", '' AS "Liq", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."Code" 
            WHEN T0."Lvl" = 2 THEN T1."Code" 
            WHEN T0."Lvl" = 3 THEN T2."Code" 
            WHEN T0."Lvl" = 4 THEN T3."Code" 
            WHEN T0."Lvl" = 5 THEN T4."Code" 
            WHEN T0."Lvl" = 6 THEN T5."Code" 
            WHEN T0."Lvl" = 7 THEN T6."Code" 
            WHEN T0."Lvl" = 8 THEN T7."Code" 
            ELSE '' 
        END AS "Level1", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."Code" 
            WHEN T0."Lvl" = 3 THEN T1."Code" 
            WHEN T0."Lvl" = 4 THEN T2."Code" 
            WHEN T0."Lvl" = 5 THEN T3."Code" 
            WHEN T0."Lvl" = 6 THEN T4."Code" 
            WHEN T0."Lvl" = 7 THEN T5."Code" 
            WHEN T0."Lvl" = 8 THEN T6."Code" 
            ELSE '' 
        END AS "Level2", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."Code" 
            WHEN T0."Lvl" = 4 THEN T1."Code" 
            WHEN T0."Lvl" = 5 THEN T2."Code" 
            WHEN T0."Lvl" = 6 THEN T3."Code" 
            WHEN T0."Lvl" = 7 THEN T4."Code" 
            WHEN T0."Lvl" = 8 THEN T5."Code" 
            ELSE '' 
        END AS "Level3", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."Code" 
            WHEN T0."Lvl" = 5 THEN T1."Code" 
            WHEN T0."Lvl" = 6 THEN T2."Code" 
            WHEN T0."Lvl" = 7 THEN T3."Code" 
            WHEN T0."Lvl" = 8 THEN T4."Code" 
            ELSE '' 
        END AS "Level4", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."Code" 
            WHEN T0."Lvl" = 6 THEN T1."Code" 
            WHEN T0."Lvl" = 7 THEN T2."Code" 
            WHEN T0."Lvl" = 8 THEN T3."Code" 
            ELSE '' 
        END AS "Level5", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."Code" 
            WHEN T0."Lvl" = 7 THEN T1."Code" 
            WHEN T0."Lvl" = 8 THEN T2."Code" 
            ELSE '' 
        END AS "Level6", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T1."Code" 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            ELSE '' 
        END AS "Level8", 
		/* External Code */
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."Code" 
            WHEN T0."Lvl" = 2 THEN T1."Code" 
            WHEN T0."Lvl" = 3 THEN T2."Code" 
            WHEN T0."Lvl" = 4 THEN T3."Code" 
            WHEN T0."Lvl" = 5 THEN T4."Code" 
            WHEN T0."Lvl" = 6 THEN T5."Code" 
            WHEN T0."Lvl" = 7 THEN T6."Code" 
            WHEN T0."Lvl" = 8 THEN T7."Code" 
            ELSE '' 
        END AS "Level1AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."Code" 
            WHEN T0."Lvl" = 3 THEN T1."Code" 
            WHEN T0."Lvl" = 4 THEN T2."Code" 
            WHEN T0."Lvl" = 5 THEN T3."Code" 
            WHEN T0."Lvl" = 6 THEN T4."Code" 
            WHEN T0."Lvl" = 7 THEN T5."Code" 
            WHEN T0."Lvl" = 8 THEN T6."Code" 
            ELSE '' 
        END AS "Level2AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."Code" 
            WHEN T0."Lvl" = 4 THEN T1."Code" 
            WHEN T0."Lvl" = 5 THEN T2."Code" 
            WHEN T0."Lvl" = 6 THEN T3."Code" 
            WHEN T0."Lvl" = 7 THEN T4."Code" 
            WHEN T0."Lvl" = 8 THEN T5."Code" 
            ELSE '' 
        END AS "Level3AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."Code" 
            WHEN T0."Lvl" = 5 THEN T1."Code" 
            WHEN T0."Lvl" = 6 THEN T2."Code" 
            WHEN T0."Lvl" = 7 THEN T3."Code" 
            WHEN T0."Lvl" = 8 THEN T4."Code" 
            ELSE '' 
        END AS "Level4AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."Code" 
            WHEN T0."Lvl" = 6 THEN T1."Code" 
            WHEN T0."Lvl" = 7 THEN T2."Code" 
            WHEN T0."Lvl" = 8 THEN T3."Code" 
            ELSE '' 
        END AS "Level5AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."Code" 
            WHEN T0."Lvl" = 7 THEN T1."Code" 
            WHEN T0."Lvl" = 8 THEN T2."Code" 
            ELSE '' 
        END AS "Level6AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T1."Code" 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            ELSE '' 
        END AS "Level8AccntntCod", 
		/* Foreign Name */
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 2 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 3 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T5."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T6."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T7."FrgnName" 
            ELSE '' 
        END AS "Level1FrgnName", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 3 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T5."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T6."FrgnName" 
            ELSE '' 
        END AS "Level2FrgnName", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T5."FrgnName" 
            ELSE '' 
        END AS "Level3FrgnName", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T4."FrgnName" 
            ELSE '' 
        END AS "Level4FrgnName", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T3."FrgnName" 
            ELSE '' 
        END AS "Level5FrgnName", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T2."FrgnName" 
            ELSE '' 
        END AS "Level6FrgnName", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T1."FrgnName" 
            ELSE '' 
        END AS "Level7FrgnName", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T0."FrgnName" 
            ELSE '' 
        END AS "Level8FrgnName", 
		T0."Sort", 
		CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherId", 
        CAST(T0."Code" AS nvarchar(32)) AS "Id", 
		T0."FormatCode", T0."AcctCodeDisp", T0."Segment_0", T0."Segment_1", 
        T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", 
		T0."Segment_7", T0."Segment_8", T0."Segment_9", T0."ActCurr", T0."GroupMask", 
		T0."DocType", T0."AccntntCod", T0."FrgnName" 
    FROM "CRSPProfitLostByCCBR_TmplAcct" T0 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T1 ON T0."FatherNum" = T1."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T2 ON T1."FatherNum" = T2."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T3 ON T2."FatherNum" = T3."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T4 ON T3."FatherNum" = T4."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T5 ON T4."FatherNum" = T5."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T6 ON T5."FatherNum" = T6."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_TmplAcct" T7 ON T6."FatherNum" = T7."Code" 
    WHERE :planId <> '@@Account';
	
	
    INSERT INTO "CRSPProfitLostByCCBR_Plan" (SELECT T1.*, 
        (SELECT MAX("Lvl") 
        FROM "CRSPProfitLostByCCBR_Plan0") AS "MaxLvl", T21."Description" AS "Desc1", T22."Description" AS "Desc2", 
        T23."Description" AS "Desc3", T24."Description" AS "Desc4", T25."Description" AS "Desc5", 
        T26."Description" AS "Desc6", T27."Description" AS "Desc7", T28."Description" AS "Desc8", 
        T1."Description" AS "DescAll", 
        CASE 
            WHEN :planId = '@@Account' THEN T1."AcctCode" 
            ELSE T1."Id" 
        END AS "Code" 
    FROM "CRSPProfitLostByCCBR_Plan0" T1 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T21 ON T1."Level1" = T21."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T22 ON T1."Level2" = T22."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T23 ON T1."Level3" = T23."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T24 ON T1."Level4" = T24."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T25 ON T1."Level5" = T25."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T26 ON T1."Level6" = T26."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T27 ON T1."Level7" = T27."Code" 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_AcctLang" T28 ON T1."Level8" = T28."Code" 
    ORDER BY T1."Sort");
	
	/* Here the actual AccountCalc Query starts */
	
    /* Distribution Rule (OOCR, OCR1) 
	 *
	 * Temp. Table with distribution rules, created with ValidFrom and ValidTo
	 * Desc: If only 1 Rule per Date oder the last one, the ValidTo Column ist ToDay+99Years 
	*/
	
    /* Amount Brought Forward */				
    INSERT INTO "CRSPProfitLostByCCBR_OCR1DistRule" (SELECT T0."OcrCode", T0."PrcCode", 
        CASE WHEN T0."OcrTotal" = 0 THEN 1 ELSE T0."OcrTotal" END AS "OcrTotal", 
        CASE WHEN T0."OcrTotal" = 0 THEN 1 ELSE T0."PrcAmount" END AS "PrcAmount", 
        CASE WHEN T0."OcrTotal" = 0 THEN 1 ELSE T0."PrcAmount" END / 
			CASE WHEN T0."OcrTotal" = 0 THEN 1 ELSE T0."OcrTotal" END AS "OcrFactor", 
		T0."Direct", T0."ValidFrom", 
		IFNULL((SELECT MIN(ADD_DAYS(T1."ValidFrom", -1)) 
        FROM OCR1 T1 
        WHERE T1."OcrCode" = T0."OcrCode" AND
		T1."ValidFrom" > T0."ValidFrom"), :UpperBoundary) AS "ValidTo" FROM OCR1 T0 
    ORDER BY T0."OcrCode", T0."ValidFrom", T0."PrcCode");

    call CRSP_ProfitAndLostByCC_BR_enUS_cont(:Currency, :IgnoreAdj, :AddVoucher, :DateType, :DimCode,
		:BudgId, :FromDate, :ToDate, :BroughtForward, :OcrCode, :PrcCode, :PrjCode, :EndYear, :FinancYear);	
			
    INSERT INTO "CRSPProfitLostByCCBR_Res" (SELECT T0."Typ", T0."RefDate", T0."FinancYear", 
		T0."Account", IFNULL(T0."PrcCode", '') AS "PrcCode", IFNULL(T0."OcrCode", '') AS "OcrCode", 
        IFNULL(T0."PrjCode", '') AS "PrjCode", SUM(T0."Credit") AS "Credit", 
        SUM(T0."CreditPreviousYear") AS "CreditPreviousYear", SUM(T0."Debit") AS "Debit", 
        SUM(T0."DebitPreviousYear") AS "DebitPreviousYear", SUM(T0."CreditBudget") AS "CreditBudget", 
        SUM(T0."DebitBudget") AS "DebitBudget", SUM(T0."CreditBudgetPrevYear") AS "CreditBudgetPrevYear", 
        SUM(T0."DebitBudgetPrevYear") AS "DebitBudgetPrevYear", 
		SUM(T0."CreditActualMonth") AS "CreditActualMonth", 
        SUM(T0."CreditMonthPreviousYear") AS "CreditMonthPreviousYear", 
        SUM(T0."DebitActualMonth") AS "DebitActualMonth", 
        SUM(T0."DebitMonthPreviousYear") AS "DebitMonthPreviousYear", 
        SUM(T0."CreditActualMonthBudget") AS "CreditActualMonthBudget", 
        SUM(T0."DebitActualMonthBudget") AS "DebitActualMonthBudget", 
        SUM(T0."CreditFinancYear") AS "CreditFinancYear", SUM(T0."DebitFinancYear") AS "DebitFinancYear", 
        SUM(T0."CreditFinancYearBudget") AS "CreditFinancYearBudget", 
        SUM(T0."DebitFinancYearBudget") AS "DebitFinancYearBudget", 
        SUM(T0."CreditPrevFinancYear") AS "CreditPrevFinancYear", 
        SUM(T0."DebitPrevFinancYear") AS "DebitPrevFinancYear", SUM(T0."BFDebit") AS "BFDebit", 
        SUM(T0."BFCredit") AS "BFCredit", SUM(T0."OBDebit") AS "OBDebit", SUM(T0."OBCredit") AS "OBCredit", 
        SUM(T0."BFOBDebit") AS "BFOBDebit", 
        SUM(T0."BFOBCredit") AS "BFOBCredit" 
    FROM "CRSPProfitLostByCCBR_JDT1" T0 
    GROUP BY T0."Typ", T0."RefDate", T0."FinancYear", T0."Account", T0."PrcCode", 	T0."OcrCode", T0."PrjCode");

	
    SELECT IFNULL(T1."Typ", 'Acct') AS "Typ", -1 AS "TransId", -1 AS "Line_ID", T0."Lvl", IFNULL(T0."AcctCode", '') AS "AcctCode", T0."Description", 
        T0."Postable", T0."Variator", T0."Liq", T0."Level1", T0."Level2", T0."Level3", T0."Level4", T0."Level5", 
        T0."Level6", T0."Level7", T0."Level8", T0."Level1AccntntCod", T0."Level2AccntntCod", T0."Level3AccntntCod", 
        T0."Level4AccntntCod", T0."Level5AccntntCod", T0."Level6AccntntCod", T0."Level7AccntntCod", 
        T0."Level8AccntntCod", T0."Level1FrgnName", T0."Level2FrgnName", T0."Level3FrgnName", T0."Level4FrgnName", 
        T0."Level5FrgnName", T0."Level6FrgnName", T0."Level7FrgnName", T0."Level8FrgnName", T0."Sort", 
        IFNULL(T0."FatherId", '') AS "FatherId", T0."Id", T0."MaxLvl", IFNULL(T0."Desc1", '') AS "Desc1", 
        IFNULL(T0."Desc2", '') AS "Desc2", IFNULL(T0."Desc3", '') AS "Desc3", IFNULL(T0."Desc4", '') AS "Desc4", 
        IFNULL(T0."Desc5", '') AS "Desc5", IFNULL(T0."Desc6", '') AS "Desc6", IFNULL(T0."Desc7", '') AS "Desc7", 
        IFNULL(T0."Desc8", '') AS "Desc8", IFNULL(T0."DescAll", '') AS "DescAll", T1."RefDate", 
        IFNULL(T1."FinancYear", :FinancYear) AS "FinancYear", IFNULL(T1."PrcCode", '') AS "PrcCode", 
        IFNULL(T1."OcrCode", '') AS "OcrCode", IFNULL(T1."PrjCode", '') AS "PrjCode", 
        IFNULL(T1."Credit", 0) AS "Credit", IFNULL(T1."CreditPreviousYear", 0) AS "CreditPreviousYear", 
        IFNULL(T1."Debit", 0) AS "Debit", IFNULL(T1."DebitPreviousYear", 0) AS "DebitPreviousYear", 
        IFNULL(T1."CreditBudget", 0) AS "CreditBudget", IFNULL(T1."DebitBudget", 0) AS "DebitBudget", 
        IFNULL(T1."CreditBudgetPrevYear", 0) AS "CreditBudgetPrevYear", 
        IFNULL(T1."DebitBudgetPrevYear", 0) AS "DebitBudgetPrevYear", 
        IFNULL(T1."CreditActualMonth", 0) AS "CreditActualMonth", 
        IFNULL(T1."CreditMonthPreviousYear", 0) AS "CreditMonthPreviousYear", 
        IFNULL(T1."DebitActualMonth", 0) AS "DebitActualMonth", 
        IFNULL(T1."DebitMonthPreviousYear", 0) AS "DebitMonthPreviousYear", 
        IFNULL(T1."CreditActualMonthBudget", 0) AS "CreditActualMonthBudget", 
        IFNULL(T1."DebitActualMonthBudget", 0) AS "DebitActualMonthBudget", 
        IFNULL(T1."CreditFinancYear", 0) AS "CreditFinancYear", IFNULL(T1."DebitFinancYear", 0) AS "DebitFinancYear", 
        IFNULL(T1."CreditFinancYearBudget", 0) AS "CreditFinancYearBudget", 
        IFNULL(T1."DebitFinancYearBudget", 0) AS "DebitFinancYearBudget", 
        IFNULL(T1."CreditPrevFinancYear", 0) AS "CreditPrevFinancYear", 
        IFNULL(T1."DebitPrevFinancYear", 0) AS "DebitPrevFinancYear", IFNULL(T1."BFDebit", 0) AS "BFDebit", 
        IFNULL(T1."BFCredit", 0) AS "BFCredit", IFNULL(T1."OBDebit", 0) AS "OBDebit", 
        IFNULL(T1."OBCredit", 0) AS "OBCredit", IFNULL(T1."BFOBDebit", 0) AS "BFOBDebit", 
        IFNULL(T1."BFOBCredit", 0) AS "BFOBCredit", IFNULL(T6."OcrName", '') AS "OcrName", 
        IFNULL(T7."OcrName", '') AS "PrcName", IFNULL(T8."PrjName", '') AS "PrjName", 
        IFNULL(T9."GrpCode", '') AS "PrcGrpCode", T3."AcctName", T3."CurrTotal", T3."Finanse", T3."Budget", 
        T3."Frozen", T3."Levels", IFNULL(T3."ExportCode", '') AS "ExportCode", T3."GrpLine", T0."DocType", 
        T3."ActType", IFNULL(T3."OverCode", '') AS "OverCode", IFNULL(T3."Project", '') AS "OACTProject", 
        IFNULL(T0."FormatCode", '') AS "FormatCode", IFNULL(T0."AcctCodeDisp", '') AS "AcctCodeDisp", 
        IFNULL(T0."ActCurr", '##') AS "ActCurr", IFNULL(T0."GroupMask", 0) AS "GroupMask", T0."Segment_0", 
        T0."Segment_1", T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", 
        T0."Segment_7", T0."Segment_8", T0."Segment_9", IFNULL(T0."AccntntCod", '') AS "AccntntCod", 
        IFNULL(T0."FrgnName", '') AS "FrgnName" 
    FROM "CRSPProfitLostByCCBR_Plan" T0 
        LEFT OUTER JOIN "CRSPProfitLostByCCBR_Res" T1 ON T0."AcctCode" = T1."Account" 
        LEFT OUTER JOIN OACT T3 ON T0."AcctCode" = T3."AcctCode" 
        LEFT OUTER JOIN OOCR T6 ON T1."OcrCode" = T6."OcrCode" 
        LEFT OUTER JOIN OOCR T7 ON T1."PrcCode" = T7."OcrCode" 
        LEFT OUTER JOIN OPRJ T8 ON T1."PrjCode" = T8."PrjCode" 
        LEFT OUTER JOIN OPRC T9 ON T1."PrcCode" = T9."PrcCode" 
    WHERE T0."Postable" = 'N' OR (
		(T1."OcrCode" IN (:OcrCode) OR :OcrCode = '') AND 
		(T1."PrcCode" IN (:PrcCode) OR :PrcCode = '') AND 
		(T1."PrjCode" IN (:PrjCode) OR :PrjCode = '')) 
    ORDER BY T0."Sort";
	
	delete from "CRSPProfitLostByCCBR_JDT1";
	delete from "CRSPProfitLostByCCBR_Res";
	delete from "CRSPProfitLostByCCBR_OCR1DistRule";
	delete from "CRSPProfitLostByCCBR_TmplAcct";
	delete from "CRSPProfitLostByCCBR_Plan";
	delete from "CRSPProfitLostByCCBR_Plan0";
	delete from "CRSPProfitLostByCCBR_AcctLang";
	
END;

CREATE PROCEDURE CRSP_ProfitAndLostByCC_BR_enUS2 (in plan nvarchar(20)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN /*
    
***** General Information *****
Name: OFRT_FinancialTemplates
Description:
Return name and absid for selected financial template

Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22

HANA version converted by SAP.

***** Updates *****
*/
    /* Financial Template ID, @@Account for Chart of Accounts. Param: '[%TemplateID]' */
    
    IF :Plan = '@@Account' THEN 
        SELECT '@@Account' AS "AbsId", 'Chart of Accounts' AS "Name" FROM DUMMY;
    ELSE 
        SELECT "AbsId", "Name" FROM OFRT 
        WHERE "AbsId" = :Plan;
    END IF;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_ProfitAndLostByCC_BR_enUS3 (in BudgId integer) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN /*
    
***** General Information *****
Name: OBGS_Budget
Description:
Return name and absid for selected Budget

Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-10-03

***** Updates *****
*/
    SELECT "AbsId" AS "AbsID", "Name", "FinancYear", 
        CAST(YEAR("FinancYear") AS varchar) || ' - ' || "Name" AS "BudgetYearName" 
    FROM OBGS 
    WHERE "AbsId" = :BudgId;
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2
CREATE PROCEDURE CRSP_ProfitAndLostByCC_BR_enUS_cont(
in Currency nvarchar(10),
in IgnoreAdj varchar(1),
in AddVoucher varchar(1),
in DateType varchar(256),
in DimCode nvarchar(10),
in BudgId int,
in FromDate timeStamp,
in ToDate timeStamp,
in BroughtForward varchar(1),
in OcrCode nvarchar(5000),
in PrcCode nvarchar(5000),
in PrjCode nvarchar(5000),
in EndYear varchar(1),
in FinancYear timestamp
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN	
	/* Amount Brought Forward */
	INSERT INTO "CRSPProfitLostByCCBR_JDT1"
    SELECT T0."TransId", T0."Line_ID", NULL AS "RefDate", NULL AS "FinancYear", T0."Account" AS "Account", 
        'BFJDT1' AS "Typ", IFNULL(T2."PrcCode", '') AS "PrcCode", IFNULL(T2."OcrCode", '') AS "OcrCode", 
        IFNULL(T0."Project", '') AS "PrjCode", 0 AS "Credit", 0 AS "CreditPreviousYear", 0 AS "Debit", 
        0 AS "DebitPreviousYear", 0 AS "CreditBudget", 0 AS "DebitBudget", 0 AS "CreditBudgetPrevYear", 
        0 AS "DebitBudgetPrevYear", 0 AS "CreditActualMonth", 0 AS "CreditMonthPreviousYear", 
        0 AS "DebitActualMonth", 0 AS "DebitMonthPreviousYear", 0 AS "CreditActualMonthBudget", 
        0 AS "DebitActualMonthBudget", 0 AS "CreditFinancYear", 0 AS "DebitFinancYear", 
        0 AS "CreditFinancYearBudget", 0 AS "DebitFinancYearBudget", 0 AS "CreditPrevFinancYear", 
        0 AS "DebitPrevFinancYear", 
		/* Case for different Date Types depending on the Parameter @DateType */
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFDebit", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFCredit",
		/* Opening Balance for selected Period */
		0 AS "OBDebit", 0 AS "OBCredit",
		/* Opening Balance Brought Forward This is still included in the BFCredit / BFDebit for compatibility reason */
        CASE 
            WHEN T0."TransType" = '-2' AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFOBDebit", 
        CASE 
            WHEN T0."TransType" = '-2' AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFOBCredit" 
    FROM JDT1 T0 
	/* Link the Distribution Rule and Amounts*/
	LEFT OUTER JOIN "CRSPProfitLostByCCBR_OCR1DistRule" T2 ON T2."OcrCode" = 
		CASE :DimCode 
			WHEN '2' THEN T0."OcrCode2" 
			WHEN '3' THEN T0."OcrCode3" 
			WHEN '4' THEN T0."OcrCode4" 
			WHEN '5' THEN T0."OcrCode5" 
			ELSE T0."ProfitCode" 
		END AND 
		CASE :DateType 
			WHEN 'DueDate' THEN T0."DueDate" 
			WHEN 'TaxDate' THEN T0."TaxDate" 
			ELSE T0."RefDate" 
		END >= T2."ValidFrom" AND 
		CASE :DateType 
			WHEN 'DueDate' THEN T0."DueDate" 
			WHEN 'TaxDate' THEN T0."TaxDate" 
			ELSE T0."RefDate" 
		END <= T2."ValidTo" 
	INNER JOIN "CRSPProfitLostByCCBR_Plan" T4 ON T0."Account" = T4."AcctCode" 
    WHERE 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END < :FromDate
		/* Exclude Adj. Journals */
		AND ((:IgnoreAdj = 'Y' AND T0."AdjTran" = 'N') OR (:IgnoreAdj = 'N') OR (:IgnoreAdj = 'O' AND
         T0."AdjTran" = 'Y'))
		/* Exclude Endyear Closings */ 
		 AND ((T4."DocType" = 'B' AND NOT (
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END = ADD_YEARS(ADD_DAYS(:FinancYear, -1), 1) AND T0."TransType" = -3) OR (T4."DocType" = 'P' AND
         NOT T0."TransType" = -3)) OR :EndYear = 'Y') 
		 /* TODO: Check if this can be implemented with Crystal */
		 AND (T2."OcrCode" IN (:OcrCode) OR :OcrCode = '') 
		 AND (T2."PrcCode" IN (:PrcCode) OR :PrcCode = '') 
		 AND (T0."Project" IN (:PrjCode) OR :PrjCode = '') 
		 AND :BroughtForward = 'Y'

	/* Journals (JDT1) Financ Year*/
    UNION
    SELECT T0."TransId", T0."Line_ID", 
		/* Create Date (01.MM.YYYY) */
		CAST('01.' || CAST(MONTH(
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END) AS varchar) || '.' || CAST(YEAR(
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END) AS varchar) AS timestamp) AS "RefDate", :FinancYear AS "FinancYear", T0."Account" AS "Account", 
        'JDT1' AS "Typ", 
		/* Actual Periode FormDate - ToDate */
		IFNULL(T2."PrcCode", '') AS "PrcCode", 
		IFNULL(T2."OcrCode", '') AS "OcrCode", 
        IFNULL(T0."Project", '') AS "PrjCode", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FromDate AND 
            CASE :DateType 
