= (select Min(Action), MIN(Personal), MIN(UserId), MIN(EmployeeId), MIN(Recontact), MIN(EndDate), MIN(BeginTime), MIN(ENDTime), MIN(Details)  from "CRSPPublicCrossDaysItemsActivities" T1 where T0.ClgCode1 = T1.ClgCode);

