-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

--drop procedure CRSP_Public_Day_Items;           
create procedure CRSP_Public_Day_Items (
	in DisplayDate nvarchar(8),
	in EmployeeIDs clob,
	in UserIDs clob,
	in MinBegin_in int,				-- Minimum Begin Worktime in the week
	in MaxEnd_in int,				-- Maximum End Worktime in the week
	in WorkBegin_in int,
	in WorkEnd_in int,
	in MinutesPerRow smallint,
	in RecurringInstances_in nvarchar(4000),
	in Visible tinyint,
	in ShowPhoneCall tinyint,
	in ShowMeeting tinyint,
	in ShowOther tinyint,
	in ShowTask tinyint,
	in ShowPersonal tinyint,
	in ShowServiceCall tinyint
) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
	timev int; 
	span int;
	entry int;
	tmpStr nvarchar(4000);
	--sqlStr nvarchar(2000);
	curr int;
	prev int;
	Code_Sep int;
	Instance nvarchar(50);
	RecurringInstances nvarchar(4000);
	ds int;
	MinBegin int;
	MaxEnd int;
	WorkBegin int;
	WorkEnd int;
	tmpClgCode nvarchar(100);
    tmpRecontact nvarchar(100);
    tmpEndDate nvarchar(100);
    ClgCode int; 
    Recontact TIMESTAMP; 
    BeginTime int;  
    EndTime int; 
    Actionv nvarchar(1); 
    Personal nvarchar(1); 
    Details nvarchar(120); 
    Userv int;
    Employee int;
    CallID int;
    StartDate TIMESTAMP;
    EndDate TIMESTAMP;
    AssigneeUID int;
    QueueManagerUID int;
    TechUID int; 
    TechEID int; 
    SCInstance nvarchar(1);
	cnt int;
	i int;
    
cursor activityCursor for select * from "CRSPPubDayItems_Activities" order by "Recontact", "BeginTime";
cursor serviceCallCursor for select * from "CRSPPubDayItems_ServiceCalls" 
	order by "StartDate", "EndDate" Desc, "BeginTime", "EndTime" Desc, "Instance";
cursor actCursor(WorkBegin int, WorkEnd int) for select "ClgCode", "Action", "Personal", "Details", "UserId", "EmployeeId" from "CRSPPubDayItems_Activities"
	where "EndTime" <= :WorkBegin Or "BeginTime" >= :WorkEnd order by "BeginTime";
cursor scCursor(WorkBegin int, WorkEnd int) for select "CallID", "Instance", "Details", "AssigneeUID", "QueueManagerUID", "TechUID", "TechEID" from "CRSPPubDayItems_ServiceCalls" 
	where "EndTime" <= :WorkBegin Or "BeginTime" >= :WorkEnd order by "StartDate", "EndDate" Desc, "BeginTime", "EndTime" Desc, "Instance";
Begin
	
    call _TmSp_ValidateSpParam(DisplayDate);
	call _TmSp_ValidateSpParam(RecurringInstances_in);
	call _TmSp_ValidateSpParam(EmployeeIDs);
	call _TmSp_ValidateSpParam(UserIDs);
	
	entry := 0;
	span := :MinutesPerRow;
	timev := 0;
	
	--delete from "CRSPPubDayItems_OffTimeActs";
	--delete from "CRSPPubDayItems_OffTimeSC";
	delete from "CRSPPubDayItems_Instances";
	delete from "CRSPPubDayItems_Activities";
	delete from "CRSPPubDayItems_ServiceCalls";
	delete from "CRSPPubDayItems_Calendar";
	delete from "CRSPPubDayItems_Users";
	delete from "CRSPPubDayItems_Employees";
	
	RecurringInstances := :RecurringInstances_in;
	
	MinBegin := :MinBegin_in;
	MaxEnd := :MaxEnd_in;
	WorkBegin := :WorkBegin_in;
	WorkEnd := :WorkEnd_in;
	
	if :Visible = 0 then
		return;
	end if;
	
	tmpStr := 'insert into "CRSPPubDayItems_Users" select "USERID", "USER_CODE", "U_NAME" from OUSR where "USERID" in ' || :UserIDs;
	exec (:tmpStr);

	tmpStr := 'insert into "CRSPPubDayItems_Employees" select "empID", "firstName", "middleName", "lastName" from OHEM where "empID" in ' ||
		 :EmployeeIDs;
	exec (:tmpStr);
	
	While :timev < 2400 do
		insert into "CRSPPubDayItems_Calendar" ("AbsEntry", "TimeSection") Values(:entry, :timev);
		entry := :entry + 1;

		if :span >= 60 then
			timev := :timev + floor(:span / 60) * 100;
		else
			timev := timev + :span;
			if mod(timev,100) >= 60 then
				timev := :timev - mod(:timev, 100) + 100;
			end if;
		end if;
	end while;

	-- Round the Begin and End times
	if :span < 60 then 
		MinBegin := :MinBegin - mod(mod(:MinBegin, 100), :span);
		MaxEnd := :MaxEnd - mod(mod(:MaxEnd, 100), :span);
	
		WorkBegin := :WorkBegin - mod(mod(:WorkBegin, 100), :span);
		WorkEnd := :WorkEnd - mod(mod(:WorkEnd, 100), :span);
	else
	    ds := floor(:span/60);
		MinBegin := floor(floor(MinBegin/100)/:ds) * :ds * 100;
		MaxEnd := floor(floor(MaxEnd/100)/:ds) * :ds * 100;
	
		WorkBegin := floor(floor(:WorkBegin/100)/:ds) * :ds * 100;
		WorkEnd := floor(floor(:WorkEnd/100)/:ds) * :ds * 100;
	end if;
	
	-- Store the filtered activites to the temporary table
	tmpStr := 'insert into "CRSPPubDayItems_Activities" select T0."ClgCode", T0."Recontact", T0."BeginTime", T0."ENDTime", T0."Action",' ||
		' T0."personal", T0."Details", T0."AttendUser", T0."AttendEmpl" From OCLG T0' ||
		' join "CRSPPubDayItems_Users" T1 On T0."AttendUser" = T1."UserID"' ||
		' where (T0."RecurPat" = ''N'' Or T0."SeriesNum" is not null) And T0."IsRemoved" = ''N'' And' ||
		' T0."inactive" = ''N'' And T0."Recontact" = ''' || :DisplayDate || ''' And T0."Recontact" = T0."endDate"' ||
		' And (T0."personal" = ''N'' ';
				
	if :ShowPersonal = 1 then
		tmpStr := :tmpStr || 'OR T0."personal" = ''Y''';
	end if;
	
	tmpStr := :tmpStr || ') And (T0."Action" = ''_'' ';

	if :ShowPhoneCall = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''C'' ';
	end if;
		
	if :ShowMeeting = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''M'' ';
	end if;
	
	if :ShowOther = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''N'' ';
	end if;
	
	if :ShowTask = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''T'' ';
	end if;

	tmpStr := :tmpStr || ') union all ';
	tmpStr := :tmpStr || 'select T0."ClgCode", T0."Recontact", T0."BeginTime", T0."ENDTime", T0."Action", T0."personal",' ||
		 ' T0."Details", T0."AttendUser", T0."AttendEmpl" From OCLG T0' ||
		 ' join "CRSPPubDayItems_Employees" T2 On T0."AttendEmpl" = T2."EmployeeID"' ||
		 ' where (T0."RecurPat" = ''N'' Or T0."SeriesNum" is not null) And T0."IsRemoved" = ''N'' And T0."inactive" = ''N''' ||
		 ' And T0."Recontact" = ''' || :DisplayDate || ''' And T0."Recontact" = T0."endDate" And (T0."personal" = ''N'' ';

	if :ShowPersonal = 1 then
		tmpStr := :tmpStr || 'OR T0."personal" = ''Y''';
	end if;
		
	tmpStr := :tmpStr || ') And (T0."Action" = ''_'' ';

	if :ShowPhoneCall = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''C'' ';
	end if;

	if :ShowMeeting = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''M'' ';
	end if;
		
	if :ShowOther = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''N'' ';
	end if;

	if :ShowTask = 1 then
		tmpStr := :tmpStr || 'Or T0."Action" = ''T'' ';
	end if;

	tmpStr := :tmpStr || ') Order By T0."Recontact", T0."BeginTime"';
		
	--insert into TST values(:tmpStr);
	exec (:tmpStr);
	
	-- Insert the recurring instances
	-- Store the recurring instances in the temporary table
	
	while length(:RecurringInstances) > 0 do
       curr := locate(:RecurringInstances, ' ');
      
       if :curr > 0 then
			Instance := SUBSTRING(:RecurringInstances, 0, :curr);
		else
			Instance := :RecurringInstances;
		end if;
		
		tmpClgCode := substr(:Instance, 0, locate(:Instance, ',')-1);
        Instance := substr_after(:Instance, ',');
        tmpRecontact := substr(:Instance, 0, locate(:Instance, ',')-1);
        tmpEndDate := rtrim(substr_after(:Instance, ','), ' ');
                      
        insert into "CRSPPubDayItems_Instances" ("ClgCode", "Recontact", "EndDate") 
       	values(:tmpClgCode, :tmpRecontact, :tmpEndDate);

        RecurringInstances := substr_after(RecurringInstances, ' ');
    end While;
    
    	-- Get other information from OCLG
	update "CRSPPubDayItems_Instances" T0
	set ("AttendUser", "AttendEmployee", "BeginTime", "EndTime", "Action", "Personal", "Details")  = 
		(select min(T1."AttendUser"), min(T1."AttendEmpl"), min(T1."BeginTime"), min(T1."ENDTime"), 
			min(T1."Action"), min(T1."personal"), min(T1."Details") from OCLG T1 where T1."ClgCode" = T0."ClgCode")
		where exists (select 1 from OCLG TX where TX."ClgCode" = T0."ClgCode");
		
	-- Delete the original recurring Activity, because the instances also include it
	delete from "CRSPPubDayItems_Activities"
	where "ClgCode" in (select distinct "ClgCode" from "CRSPPubDayItems_Instances");

	-- Insert the instances for users
	insert into "CRSPPubDayItems_Activities"
	select "ClgCode", "Recontact", "BeginTime", "EndTime", "Action", "Personal", "Details", "AttendUser", "AttendEmployee"
	from "CRSPPubDayItems_Instances" T0 
	join "CRSPPubDayItems_Users" T1 On T0."AttendUser" = T1."UserID"
	where T0."Recontact" = :DisplayDate;

	-- Insert the instances for employees
	insert into "CRSPPubDayItems_Activities" 
	select "ClgCode", "Recontact", "BeginTime", "EndTime", "Action", "Personal", "Details", "AttendUser", "AttendEmployee"
	from "CRSPPubDayItems_Instances" T0 
	join "CRSPPubDayItems_Employees" T2 On T0."AttendEmployee" = T2."EmployeeID"
	where T0."Recontact" = :DisplayDate;
    
 	--select * From "CRSPPubDayItems_Calendar";
	--select * from "CRSPPubDayItems_Instances";

	open activityCursor;
	fetch activityCursor into ClgCode, Recontact, BeginTime, EndTime, Actionv, Personal, Details, Userv, Employee;
	
	while not activityCursor::NOTFOUND do
	
		if :span < 60 then 
			BeginTime := :BeginTime - mod(mod(:BeginTime, 100), :span);
			EndTime := (:EndTime - 1) - mod(mod((:EndTime - 1), 100), :span); -- If an activity?s @EndTime happens to be equal to the @WorkBegin, it should not show in the working time.
		else
			ds := floor(:span/60);
			BeginTime := floor(floor(:BeginTime/100)/:ds) * :ds * 100;
			EndTime := floor(floor(:EndTime/100)/:ds) * :ds * 100;			
		end if;
	
		if :EndTime >= :WorkBegin And :BeginTime < :WorkEnd then
			update "CRSPPubDayItems_Calendar"
			set "ClgCode1" = :ClgCode, "Action1" = :Actionv, "Personal1" = :Personal, "Details1" = :Details, "User1" = :Userv, "Employee1" = :Employee
			where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime 
			And (select max("ClgCode1") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime and "TimeSection" <= :EndTime) is null;
		
			update "CRSPPubDayItems_Calendar"
			set "ClgCode2" = :ClgCode, "Action2" = :Actionv, "Personal2" = :Personal, "Details2" = :Details, "User2" = :Userv, "Employee2" = :Employee
			where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime
			And ("ClgCode1" <> :ClgCode Or "ClgCode1" Is NULL)
			And	(select max("ClgCode2") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime and "TimeSection" <= :EndTime) is null;

			update "CRSPPubDayItems_Calendar"
			set "ClgCode3" = :ClgCode, "Action3" = :Actionv, "Personal3" = :Personal, "Details3" = :Details, "User3" = :Userv, "Employee3" = :Employee
			where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime
			And ("ClgCode1" <> :ClgCode Or "ClgCode1" Is NULL) And ("ClgCode2" <> :ClgCode  Or "ClgCode2" is null)
			And	(select max("ClgCode3") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime and "TimeSection" <= :EndTime) is null;
		end if;
		
		fetch activityCursor into ClgCode, Recontact, BeginTime, EndTime, Actionv, Personal, Details, Userv, Employee;
	end while;
	
	close activityCursor;
	
	-- Store Service calls to the temporary table
	If :ShowServiceCall = 1 then
		--(CallID, StartDate, EndDate, BeginTime, EndTime, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, Instance)
		tmpStr := 'insert into "CRSPPubDayItems_ServiceCalls"' ||
			' select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime",' ||
			' T0."subject", T0."assignee", T2."manager", T1."userId", T0."technician", ''A''' ||
			' From OSCL T0' ||
			' left outer join OHEM T1 On T1."empID" = T0."technician"' ||
			' left outer join OQUE T2 On T2."queueID" = T0."Queue"' ||
			' where T0."DisplInCal" = ''Y'' And' ||
			' T0."StartDate" =''' || :DisplayDate || ''' And' || 
			' T0."EndDate" =''' || :DisplayDate || ''' And' ||
    		' (T0."assignee" in ' || :UserIDs || ' Or T2."manager" in ' || :UserIDs || ')' 
			' Union All' ||
			' Select T0."callID", T0."StartDate", T0."EndDate", T0."StartTime", T0."EndTime", ' ||
			' T0."subject", T0."assignee", T2."manager", T1."userId", T0."technician", ''T''' ||
			' From OSCL T0' ||
			' Left Outer Join OHEM T1 On T1."empID" = T0."technician"' ||
			' Left Outer Join OQUE T2 On T2."queueID" = T0."Queue"' ||
			' where T0."DisplInCal" = ''Y'' And' ||
			' T0."StartDate" = ''' || :DisplayDate || ''' And' || 
			' T0."EndDate" =''' || :DisplayDate || ''' And' ||
    		' (T1."userId" in ' || :UserIDs || ' Or T0."technician" in ' || :EmployeeIDs || ')' 
			' order by T0."StartDate", T0."EndDate" Desc, T0."StartTime", T0."EndTime" Desc';
		
		--insert into TST values(:tmpStr);
		exec(:tmpStr);
	end if;    
	
	-- Rollover Service Calls and update #Calendar
	open serviceCallCursor;
	fetch serviceCallCursor Into CallID, StartDate, EndDate, BeginTime, EndTime, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, SCInstance;

	while not serviceCallCursor::NOTFOUND do
	
		if :span < 60 then 
			BeginTime := :BeginTime - mod(mod(:BeginTime, 100), :span);
			EndTime := (:EndTime - 1) - mod(mod((:EndTime - 1), 100), :span); -- If an service call's @EndTime happens to be equal to the @WorkBegin, it should not show in the working time.
		else
			ds := floor(:span/60);
			BeginTime := floor(floor(:BeginTime/100)/:ds) * :ds * 100;
			EndTime := floor(floor(:EndTime/100)/:ds) * :ds * 100;			
		end if;

		update "CRSPPubDayItems_Calendar"
		set "CallID1" = :CallID, "SCInstance1" = :SCInstance, "Details1" = :Details, "AssigneeUID1" = :AssigneeUID, 
			"QueueManagerUID1" = :QueueManagerUID, "TechUID1" = :TechUID, "TechEID1" = :TechEID
		where :EndTime >= :WorkBegin And :BeginTime < :WorkEnd And "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime 
			And (Select Max("ClgCode1") From "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime) is null
			And (select max("CallID1") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime) is null;
	
		update "CRSPPubDayItems_Calendar"
 		set "CallID2" = :CallID, "SCInstance2" = :SCInstance, "Details2" = :Details, "AssigneeUID2" = :AssigneeUID, 
 			"QueueManagerUID2" = :QueueManagerUID, "TechUID2" = :TechUID, "TechEID2" = :TechEID
 		where :EndTime >= :WorkBegin And :BeginTime < :WorkEnd And "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime
			And ("CallID1" <> :CallID Or "SCInstance1" <> :SCInstance Or "CallID1" is null)
			And	(select max("ClgCode2") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime) is null
			And	(select max("CallID2") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime) is null;

		update "CRSPPubDayItems_Calendar"
 		set "CallID3" = :CallID, "SCInstance3" = :SCInstance, "Details3" = :Details, "AssigneeUID3" = :AssigneeUID, 
 			"QueueManagerUID3" = :QueueManagerUID, "TechUID3" = :TechUID, "TechEID3" = :TechEID
 		where :EndTime >= :WorkBegin And :BeginTime < :WorkEnd And "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime
			And ("CallID1" <> :CallID Or "SCInstance1" <> :SCInstance Or "CallID1" is null) 
			And ("CallID2" <> :CallID Or "SCInstance2" <> :SCInstance Or "CallID2" is null)
			And	(select max("CallID3") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime) is null
			And	(select max("ClgCode3") from "CRSPPubDayItems_Calendar" where "TimeSection" >= :BeginTime And "TimeSection" <= :EndTime) is null;

		fetch ServiceCallCursor into CallID, StartDate, EndDate, BeginTime, EndTime, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID, SCInstance;
	end while;

	close ServiceCallCursor;
	
	-- Clear the activities and service calls in offtime
	update "CRSPPubDayItems_Calendar"
	set "EntryCount"=NULL, 
	"ClgCode1"=NULL, "Action1"=NULL, "Personal1"=NULL, "Details1"=NULL, "User1"=NULL, "Employee1"=NULL, "CallID1"=NULL, "SCInstance1"=NULL, "AssigneeUID1"=NULL, 
	"QueueManagerUID1"=NULL, "TechUID1"=NULL, "TechEID1"=NULL,
	"ClgCode2"=NULL, "Action2"=NULL, "Personal2"=NULL, "Details2"=NULL, "User2"=NULL, "Employee2"=NULL, "CallID2"=NULL, "SCInstance2"=NULL, "AssigneeUID2"=NULL, 
	"QueueManagerUID2"=NULL, "TechUID2"=NULL, "TechEID2"=NULL,
	"ClgCode3"=NULL, "Action3"=NULL, "Personal3"=NULL, "Details3"=NULL, "User3"=NULL, "Employee3"=NULL, "CallID3"=NULL, "SCInstance3"=NULL, "AssigneeUID3"=NULL, 
	"QueueManagerUID3"=NULL, "TechUID3"=NULL, "TechEID3"=NULL
	where "TimeSection" < :WorkBegin Or "TimeSection" >= :WorkEnd;
	
	--------------Move the Off-time activities to the bottom (Begin)------------------
	
	open actCursor(:WorkBegin,:WorkEnd);
	fetch actCursor into ClgCode, Actionv, Personal, Details, Userv, Employee;
	i := 1;
	
	while not actCursor::NOTFOUND  do
		--insert into "CRSPPubDayItems_OffTimeActs" values(:i, 1, :ClgCode, :Actionv, :Personal, :Details, :Userv, :Employee); 
		
		update "CRSPPubDayItems_Calendar"
		set "EntryCount" = 1, "ClgCode1" = :ClgCode, "Action1" = Actionv, "Personal1" = Personal, "Details1" = Details, "User1" = :Userv, "Employee1" = :Employee
		where "TimeSection" = :MaxEnd + floor((:i-1)*:span/60)*100 + mod((:i-1)*:span, 60);
		i := :i + 1;
	
		--insert into TST values(:i || ' ' || :WorkBegin ||' ' || :WorkEnd ||' ' || floor((:i-1)*:span/60)*100 + mod((:i-1)*:span, 60) || ' ' || :MaxEnd);
				
		fetch actCursor into ClgCode, Actionv, Personal, Details, Userv, Employee;
	end while;
	
	close actCursor;
	--------------Move the Off-time activities to the bottom (End)------------------
	
	--------------Move the Off-time service calls to the bottom (Begin)------------------
	open scCursor(:WorkBegin, :WorkEnd);
	fetch scCursor into CallID, Instance, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID;
	i := 1;
	
	select count(1) into cnt from "CRSPPubDayItems_ServiceCalls" where "EndTime" <= :WorkBegin Or "BeginTime" >= :WorkEnd;
	
	while not scCursor::NOTFOUND  do
		--insert into "CRSPPubDayItems_OffTimeSC" values (:i, 1, :CallID, :Instance, :Details, :AssigneeUID, :QueueManagerUID, :TechUID, :TechEID);
	
		update "CRSPPubDayItems_Calendar"	
		set "EntryCount" = 1, "CallID1" = :CallID, "SCInstance1" = :Instance, "Details1" = :Details, "AssigneeUID1" = :AssigneeUID, 
			"QueueManagerUID1" = :QueueManagerUID, "TechUID1" = :TechUID, "TechEID1" = :TechEID
		where "TimeSection" = :MaxEnd + floor((:cnt + :i - 1)*:span/60)*100 + mod((:cnt + :i - 1)*:span, 60);
	
		i := :i + 1;
		fetch scCursor into CallID, Instance, Details, AssigneeUID, QueueManagerUID, TechUID, TechEID;
	end while;
	close scCursor;

	--------------Move the Off-time service calls to the bottom (End)------------------

	delete from "CRSPPubDayItems_CalT";
	delete from "CRSPPubDayItems_CalM";
	
	insert into "CRSPPubDayItems_CalT"
	select "AbsEntry", null, ifnull("CallID1",0), ifnull("CallID2",0), ifnull("CallID3",0),
	 ifnull("ClgCode1",0), ifnull("ClgCode2",0), ifnull("ClgCode3",0) from "CRSPPubDayItems_Calendar";

	insert into "CRSPPubDayItems_CalM" select ifnull(T1."CallID1",0), ifnull(T1."ClgCode1",0),
		(1 + (case when COUNT(distinct T1."ClgCode2") > 0 then 1 else (case when COUNT(Distinct T1."CallID2") > 0 then 1 else 0 end) end) +
		(case When COUNT(distinct T1."ClgCode3") > 0 then 1 else (case when COUNT(Distinct T1."CallID3") > 0 then 1 else 0 end) end))
	from "CRSPPubDayItems_Calendar" T1 
	where T1."ClgCode1" is not null or T1."CallID1" is not null
	group by T1."ClgCode1", T1."CallID1";
	
	update "CRSPPubDayItems_CalT" TX
	set "EntryCount" = (select "EntryCount" from "CRSPPubDayItems_CalM" T1 
							where T1."ClgCode" = TX."ClgCode1" and T1."CallID" = TX."CallID1")
	where TX."ClgCode1" in (select "ClgCode" from "CRSPPubDayItems_CalM") and 
		TX."CallID1" in (select "CallID" from "CRSPPubDayItems_CalM");
	
	delete from "CRSPPubDayItems_CalM";
	insert into "CRSPPubDayItems_CalM"
	select ifnull(T1."CallID2",0), ifnull(T1."ClgCode2",0),
		(1 + (case when COUNT(distinct T1."ClgCode3") > 0 then 1 else (case when COUNT(Distinct T1."CallID3") > 0 then 1 else 0 end) end) +
		(case When COUNT(distinct T1."ClgCode1") > 0 then 1 else (case when COUNT(Distinct T1."CallID1") > 0 then 1 else 0 end) end))
	from "CRSPPubDayItems_Calendar" T1 
	where T1."ClgCode2" is not null or T1."CallID2" is not null
	group by T1."ClgCode2", T1."CallID2";
	
	update "CRSPPubDayItems_CalT" TX
	set "EntryCount" = (select "EntryCount" from "CRSPPubDayItems_CalM" T1 where T1."ClgCode" = TX."ClgCode2" and T1."CallID" = TX."CallID2")
	where TX."ClgCode2" in (select "ClgCode" from "CRSPPubDayItems_CalM") and TX."CallID2" in (select "CallID" from "CRSPPubDayItems_CalM");

	delete from "CRSPPubDayItems_CalM";
	insert into "CRSPPubDayItems_CalM" select ifnull(T1."CallID3",0), ifnull(T1."ClgCode3",0),
		(1 + (case when COUNT(distinct T1."ClgCode2") > 0 then 1 else (case when COUNT(Distinct T1."CallID2") > 0 then 1 else 0 end) end) +
		(case When COUNT(distinct T1."ClgCode1") > 0 then 1 else (case when COUNT(Distinct T1."CallID1") > 0 then 1 else 0 end) end))
	from "CRSPPubDayItems_Calendar" T1 
	where T1."ClgCode3" is not null or T1."CallID3" is not null
	group by T1."ClgCode3", T1."CallID3";
	
	update "CRSPPubDayItems_CalT" TX
	set "EntryCount" = (select "EntryCount" from "CRSPPubDayItems_CalM" T1 where T1."ClgCode" = TX."ClgCode3" and T1."CallID" = TX."CallID3")
	where TX."ClgCode3" in (select "ClgCode" from "CRSPPubDayItems_CalM") and TX."CallID3" in (select "CallID" from "CRSPPubDayItems_CalM");  

	update "CRSPPubDayItems_CalT" TC
	set TC."EntryCount" = (select MAX(TX."EntryCount") from "CRSPPubDayItems_CalT" TX 
						where TX."ClgCode1" = TC."ClgCode1" and TX."CallID1" = TC."CallID1" 
						group by TX."ClgCode1", TX."CallID1")
	where TC."CallID1" > 0 or TC."ClgCode1" > 0; 

	update "CRSPPubDayItems_CalT" TC
	set TC."EntryCount" = (select MAX(TX."EntryCount") from "CRSPPubDayItems_CalT" TX 
						where TX."ClgCode2" = TC."ClgCode2" and TX."CallID2" = TC."CallID2" 
						group by TX."ClgCode2", TX."CallID2")
	where TC."CallID2" > 0 or TC."ClgCode2" > 0; 

	update "CRSPPubDayItems_CalT" TC
	set TC."EntryCount" = (select MAX(TX."EntryCount") from "CRSPPubDayItems_CalT" TX 
						where TX."ClgCode3" = TC."ClgCode3" and TX."CallID3" = TC."CallID3" 
						group by TX."ClgCode3", TX."CallID3")
	where TC."CallID3" > 0 or TC."ClgCode3" > 0; 
	
	update "CRSPPubDayItems_Calendar" TC
		set "EntryCount" = (select TX."EntryCount" from "CRSPPubDayItems_CalT" TX where TX."AbsEntry" = TC."AbsEntry"); 
	
	delete from "CRSPPubDayItems_CalT";
	delete from "CRSPPubDayItems_CalM";
							
	-------------Set the begintimes and endtimes---------------------------
	-- Activities
	update "CRSPPubDayItems_Calendar" T0
		set ("BeginTime1", "EndTime1")  = (select MIN("BeginTime"), MIN("ENDTime") from OCLG where "ClgCode" = T0."ClgCode1")
		where exists (select 1 from OCLG T1 where T1."ClgCode" = T0."ClgCode1");
			
	update "CRSPPubDayItems_Calendar" T0
		set ("BeginTime2", "EndTime2")  = (select MIN("BeginTime"), MIN("ENDTime") from OCLG where "ClgCode" = T0."ClgCode2")
		where exists (select 1 from OCLG T1 where T1."ClgCode" = T0."ClgCode2");
			
	update "CRSPPubDayItems_Calendar" T0
		set ("BeginTime3", "EndTime3")  = (select MIN("BeginTime"), MIN("ENDTime") from OCLG where "ClgCode" = T0."ClgCode3")
		where exists (select 1 from OCLG T1 where T1."ClgCode" = T0."ClgCode3");
			
	-- Service Calls	 	
	update "CRSPPubDayItems_Calendar" T0 
		set ("BeginTime1", "EndTime1")  = (select MIN ("BeginTime"), MIN("EndTime") from "CRSPPubDayItems_ServiceCalls" where "CallID" = T0."CallID1")
		where exists (select 1 from "CRSPPubDayItems_ServiceCalls" where "CallID" = T0."CallID1");
	
	update "CRSPPubDayItems_Calendar" T0 
		set ("BeginTime2", "EndTime2")  = (select MIN ("BeginTime"), MIN("EndTime") from "CRSPPubDayItems_ServiceCalls" where "CallID" = T0."CallID2")
		where exists (select 1 from "CRSPPubDayItems_ServiceCalls" where "CallID" = T0."CallID2");
	
	update "CRSPPubDayItems_Calendar" T0 
		set ("BeginTime3", "EndTime3")  = (select MIN ("BeginTime"), MIN("EndTime") from "CRSPPubDayItems_ServiceCalls" where "CallID" = T0."CallID3")
		where exists (select 1 from "CRSPPubDayItems_ServiceCalls" where "CallID" = T0."CallID3");
		 		
	select * from "CRSPPubDayItems_Calendar";
	
	--delete from "CRSPPubDayItems_OffTimeActs";
	--delete from "CRSPPubDayItems_OffTimeSC";
	delete from "CRSPPubDayItems_Instances";
	delete from "CRSPPubDayItems_Activities";
	delete from "CRSPPubDayItems_ServiceCalls";
	delete from "CRSPPubDayItems_Calendar";
	delete from "CRSPPubDayItems_Users";
	delete from "CRSPPubDayItems_Employees";
End;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

Create Procedure CRSP_Public_UserNames (
In UserIDs nclob, 
In EmployeeIDs nclob)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
	employeeID Int;
	firstName nvarchar(50);
	middleName nvarchar(50);
	lastName nvarchar(50); 
	name nvarchar(160);
cursor empCursor for select * From "CRSPPubUN_Employees";
Begin
		
	call _TmSp_ValidateSpParam(UserIDs);
	call _TmSp_ValidateSpParam(EmployeeIDs);
	
	delete from "CRSPPubUN_UsersEmployees";
	delete from "CRSPPubUN_Employees";
    
    exec ('insert into "CRSPPubUN_UsersEmployees" select "USERID", null, "U_NAME" from OUSR where "USERID" in ' || :UserIDs); 
 	exec ('insert into "CRSPPubUN_Employees" select "empID", ifnull("firstName", ''''), "middleName", "lastName" From OHEM Where "empID" in ' || :EmployeeIDs );
 	
 	open empCursor;
	fetch empCursor into employeeID, firstName, middleName, lastName;
	
	while not empCursor::NOTFOUND do
		
		name := ifnull(:lastName, '');
				
		if length(:firstName) > 0 then
			name := :name || ', ' || :firstName;
		end if;
				
		exec ('insert into "CRSPPubUN_UsersEmployees" values(null,' || :employeeID || ',''' || :name ||''')');
		
		fetch empCursor into employeeID, firstName, middleName, lastName;
	end while;
	
	close empCursor;
	select * from "CRSPPubUN_UsersEmployees";
	
	delete from "CRSPPubUN_UsersEmployees";
	delete from "CRSPPubUN_Employees";
End;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_StockAging_BR_enUS (in ValuationDateParam timestamp, in DateTypeParam varchar(32), in ItemCodeFromParam varchar(50), ItemCodeToParam varchar(50)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
ValuationDate timestamp;
DateType varchar(32);
ItemCodeFrom varchar(50);
ItemCodeTo varchar(50);
BEGIN /*
    
***** General Information *****
Name: OINM_StockAging
Description: Return inventory postings within 2 years before the selected valuation date
Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22
*/
    /* Define parameters */
    --SELECT (SELECT CAST(FLOOR(CAST(GETDATE() AS decimal(12, 5))) AS timestamp)) INTO ValuationDate FROM DUMMY;
    /* Parameters to enter */
    ValuationDate := ValuationDateParam;
    DateType := DateTypeParam;
    ItemCodeFrom := ItemCodeFromParam;
    ItemCodeTo := ItemCodeToParam;
	
	
	IF ItemCodeFrom = '' THEN
		SELECT  (SELECT MIN("ItemCode")  FROM OITM) INTO ItemCodeFrom FROM DUMMY;
	END IF;
	
	IF ItemCodeTo = '' THEN
		SELECT  (SELECT MAX("ItemCode")  FROM OITM) INTO ItemCodeTo FROM DUMMY;
	END IF;
	
	
    SELECT T0."ItemCode", IFNULL(T1."ItemName", '') AS "ItemName", 
        CAST(T2."ItmsGrpCod" AS nvarchar(20)) AS "ItmsGrpCod", IFNULL(T2."ItmsGrpNam", '') AS "ItmsGrpNam", 
        T0."Warehouse", T1."CreateDate", SUM(T0."InQty") - SUM(T0."OutQty") AS "InStock", 
        SUM(T0."TransValue") AS "TransValue", SUM(
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'CreateDate' THEN T0."CreateDate" 
                ELSE T0."DocDate" 
            END >= ADD_YEARS(:ValuationDate, -2) THEN IFNULL(T0."OutQty", 0.0) 
            ELSE 0.0 
        END) AS "ConsumptionL2Y", 
        CASE 
            WHEN SUM(
            CASE 
                WHEN 
                CASE :DateType 
                    WHEN 'CreateDate' THEN T0."CreateDate" 
                    ELSE T0."DocDate" 
                END >= ADD_YEARS(:ValuationDate, -2) THEN IFNULL(T0."OutQty", 0.0) 
                ELSE 0.0 
            END) = 0.0 THEN 0.0 
            ELSE 24 * (SUM(T0."InQty") - SUM(T0."OutQty")) / SUM(
            CASE 
                WHEN 
                CASE :DateType 
                    WHEN 'CreateDate' THEN T0."CreateDate" 
                    ELSE T0."DocDate" 
                END >= ADD_YEARS(:ValuationDate, -2) THEN IFNULL(T0."OutQty", 0.0) 
                ELSE 0.0 
            END) 
        END AS "StockReach", MAX(
        CASE 
            WHEN T0."TransType" = 67 OR T0."InQty" <= 0.0 THEN '19000101' 
            ELSE (
            CASE :DateType 
                WHEN 'CreateDate' THEN T0."CreateDate" 
                ELSE T0."DocDate" 
            END) 
        END) AS "LastReceiptDate", IFNULL(
        (SELECT SUM(IFNULL(T31."InQty", 0.0)) 
        FROM OINM T31 
        WHERE T31."InQty" > 0 AND T31."TransType" <> 67 AND 
            (CASE :DateType WHEN 'CreateDate' THEN T31."CreateDate" ELSE T31."DocDate" END) = 
            ( SELECT MAX(CASE WHEN T131."TransType" = 67 OR T131."InQty" <= 0.0 THEN '19000101' ELSE (
                CASE :DateType WHEN 'CreateDate' THEN T131."CreateDate" ELSE T131."DocDate" END) END)
              FROM OINM T131 WHERE T131."InQty" > 0 AND T131."TransType" <> 67 AND T131."ItemCode" = T0."ItemCode" AND T131."Warehouse" = T0."Warehouse"
            	AND (CASE :DateType WHEN 'CreateDate' THEN T31."CreateDate" ELSE T31."DocDate" END) <= :ValuationDate ) 
            AND T31."ItemCode" = T0."ItemCode" AND T31."Warehouse" = T0."Warehouse" AND (
            CASE :DateType 
                WHEN 'CreateDate' THEN T31."CreateDate" 
                ELSE T31."DocDate" 
            END) <= :ValuationDate), 0.0) AS "LastReceiptQuant", MAX(
        CASE 
            WHEN T0."TransType" = 67 OR T0."OutQty" <= 0.0 THEN '19000101' 
            ELSE (
            CASE :DateType 
                WHEN 'CreateDate' THEN T0."CreateDate" 
                ELSE T0."DocDate" 
            END) 
        END) AS "LastIssueDate", IFNULL(
        (SELECT SUM(IFNULL(T41."OutQty", 0.0)) 
        FROM OINM T41 
        WHERE T41."OutQty" > 0 AND T41."TransType" <> 67 AND 
        	(CASE :DateType WHEN 'CreateDate' THEN T41."CreateDate" ELSE T41."DocDate" END) = 
        	( SELECT MAX(CASE WHEN T141."TransType" = 67 OR T141."OutQty" <= 0.0 THEN '19000101' ELSE (
                CASE :DateType WHEN 'CreateDate' THEN T141."CreateDate" ELSE T141."DocDate" END) END)  
            FROM OINM T141 WHERE T141."OutQty" > 0 AND T141."TransType" <> 67 AND T141."ItemCode" = T0."ItemCode" AND T141."Warehouse" = T0."Warehouse" 
            	AND ( CASE :DateType WHEN 'CreateDate' THEN T141."CreateDate" ELSE T141."DocDate" END) <= :ValuationDate)
            AND T41."ItemCode" = T0."ItemCode" AND T41."Warehouse" = T0."Warehouse" AND (
            CASE :DateType 
                WHEN 'CreateDate' THEN T41."CreateDate" 
                ELSE T41."DocDate" 
            END) <= :ValuationDate), 0.0) AS "LastIssueQuant" 
    FROM OINM T0 
        INNER JOIN OITM T1 ON T0."ItemCode" = T1."ItemCode" 
        INNER JOIN OITB T2 ON T1."ItmsGrpCod" = T2."ItmsGrpCod" 
    WHERE (
        CASE :DateType 
            WHEN 'CreateDate' THEN T0."CreateDate" 
            ELSE T0."DocDate" 
        END) <= :ValuationDate AND T0."ItemCode" >= :ItemCodeFrom AND
     T0."ItemCode" <= :ItemCodeTo 
    GROUP BY T0."ItemCode", T1."ItemName", T2."ItmsGrpCod", T2."ItmsGrpNam", T0."Warehouse", T1."CreateDate" 
    ORDER BY T0."ItemCode";
    --[Note:Modifier] HANA doesn't have CONVERT you may you see CAST or implicit casting or TO_... functions
    /* Total Outgoing Quantity within 2 years before valuation date */
    /* Stock Availability in Months */
    /* Zero for inactive and new items (consumption last 2 years = 0.0) */
    /* Last Receipt Date before Valuation Date */
    /* 24 * (Total Quantity in Stock at valuation date) / (Total Outgoing Quantity within 2 years before valuation date) 
    */
    /* Last Receipt Quantity before Valuation Date */
    /* Last Issue Date before Valuation Date */
    /* Last Issue Quantity before Valuation Date */
END

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam


CREATE PROCEDURE CRSP_TRAILBALANCE_ALLACCOUNTS (
      In AcctCodeList NClob,
      In AdjustFlag NVarchar(10),
      In ClosingPeriodFlag NVarchar(10),
      In DataType NVarchar(10),
      In MaxEndDate NVarchar(30),
      In PeriodBegDate NVarchar(30),
      In PeriodEndDate NVarchar(30), 
      In PostableFlag NVarchar(10),
      In FrgnCurrencySymbol1 NVarchar(3),
      In FrgnCurrencySymbol2 NVarchar(3),
      In FrgnCurrencySymbol3 NVarchar(3),
      In FrgnCurrencySymbol4 NVarchar(3),
      In FrgnCurrencySymbol5 NVarchar(3),
      In VoucherFlag NVarchar(2),
      In YearBegin NVarchar(30),
      In YearEnd NVarchar(30))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as 
queryStr NCLOB :='';
queryStr2 nvarchar(5000) :='';
whereStr  nvarchar(2000);
initCase nvarchar(1000);
periodCase nvarchar(1000);
yearCase nvarchar(1000);
sufCreditCase nvarchar(1000) :=' THEN T1."Credit" ELSE 0 END ';
sufDebitCase nvarchar(1000) := ' THEN T1."Debit" ELSE 0 END';
sufFCCreditCase nvarchar(1000) :=' THEN T1."FCCredit" ELSE 0 END ';
sufFCDebitCase nvarchar(1000) :=' THEN T1."FCDebit" ELSE 0 END ';
fcCurrencyStr nvarchar(1000) :='CASE WHEN T1."FCCurrency" =  ';
lcCurrencyStr nvarchar(1000) :='CASE WHEN T1."FCCurrency" IS NULL OR T1."FCCurrency" = ''''';
v_sql nvarchar(4000);
DO_WHILE_FLAG int;
TEMP_COUNT int;
V_ACCT_CODE nvarchar(15);
V_SCANED nvarchar(1);
SCANED_COUNT int;
i int:=1;
count_son int;
BEGIN
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:AcctCodeList);    
    call _TmSp_ValidateSpParam(:AdjustFlag);    
	call _TmSp_ValidateSpParam(:ClosingPeriodFlag);   
	call _TmSp_ValidateSpParam(:DataType);   
	call _TmSp_ValidateSpParam(:MaxEndDate);   
	call _TmSp_ValidateSpParam(:PeriodBegDate);   
	call _TmSp_ValidateSpParam(:PeriodEndDate);  
	call _TmSp_ValidateSpParam(:PostableFlag);  	
	call _TmSp_ValidateSpParam(:FrgnCurrencySymbol1);  
	call _TmSp_ValidateSpParam(:FrgnCurrencySymbol2);  
	call _TmSp_ValidateSpParam(:FrgnCurrencySymbol3);  
	call _TmSp_ValidateSpParam(:FrgnCurrencySymbol4);  
	call _TmSp_ValidateSpParam(:FrgnCurrencySymbol5);  
	call _TmSp_ValidateSpParam(:VoucherFlag);  
	call _TmSp_ValidateSpParam(:YearBegin);  
	call _TmSp_ValidateSpParam(:YearEnd);  
	
IF :DataType  = 'Doc' THEN 
  whereStr := ' WHERE T1."RefDate" < '''||:MaxEndDate||'''';
  initCase := 'CASE WHEN T1."RefDate" < '''||:PeriodBegDate||''' OR (T1."RefDate" < '''||:PeriodEndDate||''' And T1."TransType" = -2) ';
  periodCase := 'CASE WHEN T1."RefDate" Between '''||:PeriodBegDate||'''  And '''||:PeriodEndDate||''' And T1."TransType" <> -2 ';
  yearCase := 'CASE WHEN T1."RefDate"  Between '''||:YearBegin||''' And '''||:YearEnd||'''  And T1."TransType" <> -2 ';
ELSEIF :DataType = 'Due' THEN
  whereStr := ' WHERE T1."DueDate" < '''||:MaxEndDate||'''';
  initCase := 'CASE WHEN T1."DueDate" < '''||:PeriodBegDate||''' OR (T1."RefDate" < '''||:PeriodEndDate||''' And T1."TransType" = -2) ';
periodCase := 'CASE WHEN T1."DueDate" Between ('''||:PeriodBegDate||''')  And  ('''||:PeriodEndDate||''') And T1."TransType" <> -2 ';
  yearCase := 'CASE WHEN T1."DueDate" Between ('''||:YearBegin||''') And ('''||:YearEnd||''')  And T1."TransType" <> -2 ';
ELSE
  whereStr := ' WHERE T1."TaxDate" < '''||:MaxEndDate||'''';
  initCase := 'CASE WHEN T1."TaxDate" < '''||:PeriodBegDate||''' OR (T1."RefDate" < '''||:PeriodEndDate||''' And T1."TransType" = -2) ';
  periodCase := 'CASE WHEN T1."TaxDate" Between ('''||:PeriodBegDate||''')  And  ('''||:PeriodEndDate||''') And T1."TransType" <> -2 ';
  yearCase := 'CASE WHEN T1."TaxDate"  Between ('''||:YearBegin||''') And ('''||:YearEnd||''')  And T1."TransType" <> -2 ';
END IF;

IF :ClosingPeriodFlag  = 'N' THEN
  whereStr := :whereStr || ' AND T1."TransType" <> ''-3''';
END IF;

IF :AdjustFlag  = 'N' THEN
  whereStr := :whereStr || ' AND T1."AdjTran" <> ''Y''';
END IF;

IF :PostableFlag = 'N' THEN 
      delete from "TMP_TrailBalance_AcctCode";
      v_sql:='CREATE SEQUENCE temp_code_sequence INCREMENT BY 1 START WITH 1';
      exec (:v_sql);
      --select max("Levels") into max_level from oact;
      v_sql:='insert into "TMP_TrailBalance_AcctCode" select "AcctCode","Levels",temp_code_sequence.nextval,null from oact a where a."AcctCode" in ' || :AcctCodeList;
      exec (:v_sql);
      do_while_flag:=1;
      
      while do_while_flag>0 do
            
        select count(*) into temp_count from "TMP_TrailBalance_AcctCode";
        for i in 1..temp_count do
        if :v_scaned is null then
                  update "TMP_TrailBalance_AcctCode" a set a.scaned = 'I';
                  
                  v_sql:='insert into "TMP_TrailBalance_AcctCode" (acct_code, acct_level) select DISTINCT(a."FatherNum"),a."Levels" from oact a INNER JOIN "TMP_TrailBalance_AcctCode" b on a."AcctCode" = b."ACCT_CODE" where b."SCANED" = ''I'' and a."FatherNum" NOT IN (select DISTINCT ("ACCT_CODE") from "TMP_TrailBalance_AcctCode")';
                  exec (:v_sql);

                  update "TMP_TrailBalance_AcctCode" a set a.scaned = 'Y';
                              
         end if;
            
            
        --select count(*) into temp_count from "TMP_TrailBalance_AcctCode";
        select count(*) into temp_count from "TMP_TrailBalance_AcctCode";
        end for;
        
		--select count(*) into temp_count from "TMP_TrailBalance_AcctCode";
        select count(*) into scaned_count from "TMP_TrailBalance_AcctCode" where scaned = 'Y';
        select count(*) into temp_count from "TMP_TrailBalance_AcctCode";
        if temp_count=scaned_count then 
            do_while_flag:=-1;
        end if;
        
      end while;
      
      delete from "TMP_TrailBalance_AcctLimited";

      insert into "TMP_TrailBalance_AcctLimited"
      SELECT T0."AcctCode", T0."AcctName", T0."AccntntCod", T0."FrgnName", T0."Levels", T0."FatherNum", T0."Postable", T0."GroupMask", T0."GrpLine", T0."BalDirect" FROM OACT T0, "TMP_TrailBalance_AcctCode" T1
      where T0."AcctCode"=T1.acct_code;
      v_sql:='drop sequence temp_code_sequence';
      exec (:v_sql);
      
END IF;
queryStr := :queryStr || ' SELECT T4.AcctCode, T4.AcctName, T4.AccntntCod, T4.FrgnName, T4.Levels,  T4.FatherNum,  T4.Postable, T4.GroupMask, T4.GrpLine, T4.BalDirect, 1 AS VirtualGroup, T3.InitCredit, T3.InitDebit, T3.CurrentCredit, T3.CurrentDebit, T3.YearCredit, T3.YearDebit,  T3.LCCredit,   T3.LCDebit, T3.FC1Credit, T3.FC1Debit, T3.FC2Credit, T3.FC2Debit, T3.FC3Credit, T3.FC3Debit, T3.FC4Credit, T3.FC4Debit,  T3.FC5Credit, T3.FC5Debit FROM ( ';

IF PostableFlag = 'N' THEN 
  queryStr := :queryStr || ' SELECT DISTINCT * FROM "TMP_TrailBalance_AcctLimited" ';
ELSE
  queryStr := :queryStr || ' SELECT T0."AcctCode" as ACCTCODE, T0."AcctName" AS ACCTNAME, T0."AccntntCod" AS ACCNTNTCOD, T0."FrgnName" AS FRGNNAME, T0."Levels" AS LEVELS, T0."FatherNum" AS FATHERNUM, T0."Postable" AS POSTABLE, T0."GroupMask" AS GROUPMASK, T0."GrpLine" AS GRPLINE, T0."BalDirect" AS BALDIRECT, 1 AS "VirtualGroup" FROM OACT AS T0 WHERE T0."AcctCode" IN '||:AcctCodeList;
END IF;
queryStr := :queryStr || ' ) AS T4 LEFT OUTER  JOIN ( ';

IF :VoucherFlag = 'Y' THEN 
   queryStr := :queryStr || ' SELECT "AcctCode", SUM(InitCredit) AS InitCredit, SUM(InitDebit) AS InitDebit, SUM(CurrentCredit) AS CurrentCredit, SUM(CurrentDebit) AS CurrentDebit, SUM(YearCredit) AS YearCredit, SUM(YearDebit) AS YearDebit,  SUM(LCCredit) AS LCCredit, SUM(LCDebit) AS LCDebit, SUM(FC1Credit) AS FC1Credit, SUM(FC1Debit) AS FC1Debit, SUM(FC2Credit) AS FC2Credit, SUM(FC2Debit) AS FC2Debit, SUM(FC3Credit) AS FC3Credit, SUM(FC3Debit) AS FC3Debit, SUM(FC4Credit) AS FC4Credit, SUM(FC4Debit) AS FC4Debit, SUM(FC5Credit) AS FC5Credit, SUM(FC5Debit) AS FC5Debit FROM ( ';
END IF;

queryStr := :queryStr 
                  ||' SELECT T0."AcctCode", SUM( ' || :initCase || :sufCreditCase || ') AS InitCredit, ' 
                  ||'SUM( ' || :initCase || :sufDebitCase || ') AS InitDebit, SUM( ' || :periodCase || :sufCreditCase || ') AS CurrentCredit, '
                  ||'SUM( ' || :periodCase || :sufDebitCase || ') AS CurrentDebit, SUM( ' || :yearCase || :sufCreditCase || ') AS YearCredit, '
                  ||'SUM( ' || :yearCase || :sufDebitCase || ') AS YearDebit, SUM( ' || :lcCurrencyStr || :sufCreditCase || ') AS LCCredit, '
                  ||'SUM( ' || :lcCurrencyStr || :sufDebitCase || ') AS LCDebit, SUM( ' || :fcCurrencyStr || ''''|| :FrgnCurrencySymbol1||'''' || :sufFCCreditCase || ') AS FC1Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol1||''''|| :sufFCDebitCase || ') AS FC1Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol2||'''' || :sufFCCreditCase || ') AS FC2Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol2||''''|| :sufFCDebitCase || ') AS FC2Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol3||'''' || :sufFCCreditCase || ') AS FC3Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol3||''''|| :sufFCDebitCase || ') AS FC3Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol4||'''' || :sufFCCreditCase || ') AS FC4Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol4||''''|| :sufFCDebitCase || ') AS FC4Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol5||'''' || :sufFCCreditCase || ') AS FC5Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol5||''''|| :sufFCDebitCase || ') AS FC5Debit ';
queryStr := :queryStr ||' FROM OACT AS T0 LEFT OUTER JOIN JDT1 T1 ON  T1."Account" = T0."AcctCode" LEFT OUTER  JOIN OJDT T2 ON  T2."TransId" = T1."TransId" ';
queryStr:= :queryStr|| :whereStr||' GROUP BY T0."AcctCode" ';
IF :VoucherFlag = 'Y' THEN 
queryStr2:= ' UNION ALL ';
queryStr2:= :queryStr2
                  ||' SELECT T0."AcctCode", SUM( ' || :initCase || :sufCreditCase || ') AS InitCredit, ' 
                  ||'SUM( ' || :initCase || :sufDebitCase || ') AS InitDebit, SUM( ' || :periodCase || :sufCreditCase || ') AS CurrentCredit, '
                  ||'SUM( ' || :periodCase || :sufDebitCase || ') AS CurrentDebit, SUM( ' || :yearCase || :sufCreditCase || ') AS YearCredit, '
                  ||'SUM( ' || :yearCase || :sufDebitCase || ') AS YearDebit, SUM( ' || :lcCurrencyStr || :sufCreditCase || ') AS LCCredit, '
                  ||'SUM( ' || :lcCurrencyStr || :sufDebitCase || ') AS LCDebit, SUM( ' || :fcCurrencyStr || ''''|| :FrgnCurrencySymbol1||'''' || :sufFCCreditCase || ') AS FC1Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol1||''''|| :sufFCDebitCase || ') AS FC1Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol2||'''' || :sufFCCreditCase || ') AS FC2Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol2||''''|| :sufFCDebitCase || ') AS FC2Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol3||'''' || :sufFCCreditCase || ') AS FC3Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol3||''''|| :sufFCDebitCase || ') AS FC3Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol4||'''' || :sufFCCreditCase || ') AS FC4Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol4||''''|| :sufFCDebitCase || ') AS FC4Debit, SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol5||'''' || :sufFCCreditCase || ') AS FC5Credit, '
                  ||'SUM( ' || :fcCurrencyStr || ''''||:FrgnCurrencySymbol5||''''|| :sufFCDebitCase || ') AS FC5Debit ';
queryStr2 := :queryStr2 ||' FROM OACT AS T0 LEFT OUTER JOIN BTF1 T1 ON T1."Account" = T0."AcctCode" LEFT OUTER  JOIN OBTF T2 ON  T2."TransId" = T1."TransId" ';
queryStr2:= :queryStr2|| :whereStr||' GROUP BY T0."AcctCode" ) AS Q0 GROUP BY Q0."AcctCode"';
END IF;

queryStr2 := queryStr2 || ' ) AS T3 ON T4.AcctCode = T3."AcctCode" ORDER BY T4.GroupMask, T4.GrpLine';
--EXECUTE sp_executesql @queryStr, @formatStr, '{?maxEnd}', '{?periodBegin}','{?periodEnd}','{?yearBegin}','{?yearEnd}'

delete from "TMP_TrailBalance_Output";
--select queryStr||queryStr2 from dummy;
EXEC ('insert into "TMP_TrailBalance_Output" select * from ('|| :queryStr || :queryStr2 || ')');

select * from "TMP_TrailBalance_Output";

delete from "TMP_TrailBalance_AcctCode";
delete from "TMP_TrailBalance_AcctLimited";
delete from "TMP_TrailBalance_Output";

END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE CRSP_TrailBalance_General_Setting ()
--out beginDate datetime, out endDate datetime, out symbol nvarchar(10), out symbol1 nvarchar(10),out symbol2 nvarchar(10), out symbol3 nvarchar(10),
--out symbol4 nvarchar(10), out symbol5 nvarchar(10), out LogoFile NVARCHAR(200), out LogoImage BLOB, out DecSep NVARCHAR(1), out DateSep NVARCHAR(1),) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
loopParm int;
curFCCurrency nvarchar(3);
symbol nvarchar(10);
symbol1 nvarchar(10) :='1';
symbol2 nvarchar(10) :='2';
symbol3 nvarchar(10) :='3';
symbol4 nvarchar(10) :='4';
symbol5 nvarchar(10) :='5';
beginDate date;
endDate date;
CURSOR curTemp FOR SELECT DISTINCT "FCCurrency" FROM JDT1 WHERE "FCCurrency" <> '';
begin
	SELECT MIN("F_RefDate"),MAX("T_RefDate") into beginDate,endDate FROM OFPR;
	loopParm := 1;

	For cur_row as curTemp Do 
		symbol := cur_row."FCCurrency";

		IF :loopParm = 1 then 
		 	symbol1 := symbol;
		ELSEIF :loopParm = 2 then 
			symbol2 := symbol;
		ELSEIF :loopParm = 3 then 
			symbol3 := symbol;
		ELSEIF loopParm = 4 then 
			symbol4 := symbol;
		ELSE
		 	symbol5 := symbol;
		End IF;
		loopParm := loopParm + 1;
	End For;
	
	SELECT :beginDate AS BeginDate, :endDate AS EndDate, :symbol1 AS symbol1, :symbol2 AS symbol2, :symbol3 AS symbol3, :symbol4 AS symbol4, :symbol5 AS symbol5, 
	T0."LogoFile", T0."LogoImage",T1."DecSep", T1."DateSep", T1."TimeFormat", T1."DateFormat", T1."ThousSep", T1."CurOnRight", T1."CompnyName", T1."MainCurncy", T1."SumDec", T1."CharMonth" 
	FROM OADP T0, OADM T1;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CRSP_TrialBalanceByCostCenter_BR_enUS_cont
CREATE PROCEDURE CRSP_TrialBalanceByCostCenter_BR_enUS
(
in TemplateID VARCHAR(20),
in in_Currency VARCHAR(10),
in in_IgnoreAdj VARCHAR(1),
in in_AddVoucher VARCHAR(1),
in in_DateType varchar(256),
in in_FromDate timestamp,
in in_ToDate timestamp,
in in_DimCode nvarchar(10)
) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
Plan varchar(20);
MinGroupMask integer;
PlanType varchar(1);
Currency varchar(10);
IgnoreAdj varchar(1);
AddVoucher varchar(1);
DateType varchar(256);
FromDate timestamp;
ToDate timestamp;
DimCode nvarchar(10);
BroughtForward varchar(1);
EndYear varchar(1);
MainCurr varchar(3);
SysCurr varchar(3);
FinancYear timestamp;
BEGIN /*
    
***** General Information *****
Name: JDT1_AccountCalc (including Preparation for account structure)
Description: Return Journal Entries distributed according to distribution rules to cost centers
with relevant filters.
This datasource includes branches for intercompany only supported from SAP B1 8.81 PL10 or higher
Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22
*/
    Plan := :TemplateID;
    /*
     Here we define the type of the report (P = Profit and Loss) and the Minimum Group Mask for Profit and Loss accounts 
This can be different for different localizations a mapping should be included. 
Therefore it is not supported in the official Version. 
It is kept in the datasource to enable this option in case a customer needs it. Then the MinGroupMask can be adjusted. 
    */
    MinGroupMask := 3;
    PlanType := 'P';
    /* Select which currency to display in the report. Possible values are Loc and Sys.*/
    Currency := :in_Currency;
    /*
     Include Journal Entries with checkbox "Ignore Adjustments (13. Per)" selected (Y) or not (N). Param '[%IgnoreAdj]' 
    */
    IgnoreAdj := :in_IgnoreAdj;
    IF :IgnoreAdj = '0' THEN 
        IgnoreAdj := 'N';
    ELSE 
        IgnoreAdj := 'Y';
        /* Include Journal Vouchers (Y) or not (N). */
    END IF;
    AddVoucher := :in_AddVoucher;
    IF :AddVoucher = '0' THEN 
        AddVoucher := 'N';
    ELSE 
        AddVoucher := 'Y';
        /* Date Type to set the filter and sort by. Possible values are RefDate, TaxDate and DueDate. */
    END IF;
    DateType := :in_DateType;
    /* Date Filter From and To Dates. Format 'YYYYMMDD' */
    FromDate := :in_FromDate;
    ToDate := :in_ToDate;
    /* Dimension new since Version 8.81.*/
    DimCode := in_DimCode;
    /* Include Amount Brought Forward (Y) or not (N). */
    /* Hardcoded for this report */
    BroughtForward := 'Y';
    /* Include End Year Closing (Y) or not (N). */
    /* Hardcoded for this report */
    EndYear := 'Y';
    /* Internal Parameters */
    /* Local Currency */
    SELECT 
    (
    	SELECT TOP 1 T2."MainCurncy" FROM OADM T2
    ) INTO MainCurr FROM DUMMY;
    /* System Currency */
    SELECT
    (
    	SELECT TOP 1 T2."SysCurrncy" FROM OADM T2
    ) INTO SysCurr FROM DUMMY;
    /* The Finance Year is determined by the RefDate no matter how the parameter DateType is set */
    SELECT 
    (
    	SELECT T0."FinancYear" FROM OACP T0 
        INNER JOIN OFPR T1 ON T0."PeriodCat" = T1."Category" 
    	WHERE T1."F_RefDate" <= :ToDate AND T1."T_RefDate" >= :ToDate
    ) INTO FinancYear FROM DUMMY;
    /* Account structure preparation */
    insert into "CRSP_TemplateAccount" 
    (
    	SELECT CAST(T0."CatId" AS nvarchar(32)) AS "Code", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherNum", 
        T0."Name" AS "Description", T0."Levels" AS "Lvl", T0."VisOrder" * 10000 AS "Sort", T2."DocType", 
        'N' AS "Postable", CAST(T0."CatId" AS nvarchar(32)) AS "FormatCode", 
        CAST(T0."CatId" AS nvarchar(32)) AS "AcctCodeDisp", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_0", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_1", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_2", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_3", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_4", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_5", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_6", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_7", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_8", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_9", '' AS "ActCurr", 0 AS "GroupMask", 
        CAST(T0."CatId" AS nvarchar(32)) AS "AccntntCod", T0."FrgnName" 
    	FROM OFRC T0 
        INNER JOIN OFRT T2 ON T0."TemplateId" = T2."AbsId" 
    	WHERE CAST(T0."TemplateId" AS nvarchar) = :Plan 
    	
    	UNION 
    	
    	SELECT CAST(LTRIM(RTRIM(T1."AcctCode")) AS nvarchar(32)) AS "Code", 
        CAST(T0."CatId" AS nvarchar(32)) AS "FatherNum", T1."AcctName" AS "Description", 
        (
        	SELECT MAX("Levels") FROM OFRC 
        	WHERE "CatId" = T0."CatId" AND CAST("TemplateId" AS nvarchar) = :Plan
        ) + 1 AS "Lvl", 
        (
        	SELECT MAX("VisOrder") * 10000 
        	FROM OFRC 
        	WHERE "CatId" = T0."CatId" AND CAST("TemplateId" AS nvarchar) = :Plan) + T0."VisOrder" AS "Sort", 
        	T2."DocType", 'Y' AS "Postable", LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) AS "FormatCode", 
        	CASE 
           		WHEN T1."FormatCode" IS NULL THEN LTRIM(RTRIM(T1."AcctCode")) 
           		WHEN T1."FormatCode" = T1."AcctCode" THEN LTRIM(RTRIM(T1."AcctCode")) 
           		ELSE REPLACE(IFNULL(T1."Segment_0", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_1", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_2", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_3", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_4", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_5", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_6", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_7", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_8", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_9", 'x'), 
           		(SELECT TOP 1 "ActSep" FROM OADM) || 'x', '') 
        	END AS "AcctCodeDisp", T1."Segment_0", T1."Segment_1", T1."Segment_2", T1."Segment_3", T1."Segment_4", 
        	T1."Segment_5", T1."Segment_6", T1."Segment_7", T1."Segment_8", T1."Segment_9", T1."ActCurr", T1."GroupMask", 
        	T1."AccntntCod", T1."FrgnName" 
    		FROM FRC1 T0 
 	    	INNER JOIN OACT T1 ON T0."AcctCode" = T1."AcctCode" 
    	   	INNER JOIN OFRT T2 ON T0."TemplateId" = T2."AbsId" 
    		WHERE CAST(T0."TemplateId" AS nvarchar) = :Plan
    );
    /* The Accounts (including Template) */
    insert into "CRSP_AcctLang"
    (
    	SELECT "AcctCode" AS "Code", "AcctName" AS "Description" 
    	FROM OACT 
    	WHERE :Plan = '@@Account' 
    	UNION 
    	SELECT "Code", "Description" 
    	FROM "CRSP_TemplateAccount" 
    	WHERE :Plan <> '@@Account'
    );

	insert into "CRSP_Plan0"
	(
    	/* OACT Structure */
    	SELECT T0."Levels" AS "Lvl", T0."AcctCode" AS "AcctCode", T0."AcctName" AS "Description", T0."Postable", 
        0.0 AS "Variator", '' AS "Liq", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T6."FormatCode", T6."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T7."FormatCode", T7."AcctCode"))) 
            ELSE '' 
        END AS "Level1", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T6."FormatCode", T6."AcctCode"))) 
            ELSE '' 
        END AS "Level2", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            ELSE '' 
        END AS "Level3", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            ELSE '' 
        END AS "Level4", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            ELSE '' 
        END AS "Level5", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            ELSE '' 
        END AS "Level6", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."FormatCode")) 
            ELSE '' 
        END AS "Level8", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T6."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T7."AccntntCod")) 
            ELSE '' 
        END AS "Level1AccntntCod", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T6."AccntntCod")) 
            ELSE '' 
        END AS "Level2AccntntCod", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            ELSE '' 
        END AS "Level3AccntntCod", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            ELSE '' 
        END AS "Level4AccntntCod", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            ELSE '' 
        END AS "Level5AccntntCod", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            ELSE '' 
        END AS "Level6AccntntCod", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            ELSE '' 
        END AS "Level7AccntntCod", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            ELSE '' 
        END AS "Level8AccntntCod", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T5."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T6."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T7."FrgnName")) 
            ELSE '' 
        END AS "Level1FrgnName", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T5."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T6."FrgnName")) 
            ELSE '' 
        END AS "Level2FrgnName", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T5."FrgnName")) 
            ELSE '' 
        END AS "Level3FrgnName", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T4."FrgnName")) 
            ELSE '' 
        END AS "Level4FrgnName", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T3."FrgnName")) 
            ELSE '' 
        END AS "Level5FrgnName", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T2."FrgnName")) 
            ELSE '' 
        END AS "Level6FrgnName", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T1."FrgnName")) 
            ELSE '' 
        END AS "Level7FrgnName", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."FrgnName")) 
            ELSE '' 
        END AS "Level8FrgnName", 
        T0."GroupMask" * 10000 + T0."GrpLine" AS "Sort", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherId", CAST(T0."AcctCode" AS nvarchar(32)) AS "Id", 
        LTRIM(RTRIM(IFNULL(T0."FormatCode", T0."AcctCode"))) AS "FormatCode", 
        CASE 
            WHEN T0."FormatCode" IS NULL THEN LTRIM(RTRIM(T0."AcctCode")) 
            WHEN T0."FormatCode" = T0."AcctCode" THEN LTRIM(RTRIM(T0."AcctCode")) 
            ELSE REPLACE(IFNULL(T0."Segment_0", 'x') || 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_1", 'x') || 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_2", 'x') || 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_3", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_4", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_5", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_6", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_7", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_8", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_9", 'x'), 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || 'x', '') 
        END AS "AcctCodeDisp", 
        T0."Segment_0", T0."Segment_1", T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", T0."Segment_7", T0."Segment_8", T0."Segment_9", 
        T0."ActCurr", T0."GroupMask", 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END AS "DocType", T0."AccntntCod", T0."FrgnName"
    	
    	FROM OACT T0 
        LEFT OUTER JOIN OACT T1 ON T0."FatherNum" = T1."AcctCode" 
        LEFT OUTER JOIN OACT T2 ON T1."FatherNum" = T2."AcctCode" 
        LEFT OUTER JOIN OACT T3 ON T2."FatherNum" = T3."AcctCode" 
        LEFT OUTER JOIN OACT T4 ON T3."FatherNum" = T4."AcctCode" 
        LEFT OUTER JOIN OACT T5 ON T4."FatherNum" = T5."AcctCode" 
        LEFT OUTER JOIN OACT T6 ON T5."FatherNum" = T6."AcctCode" 
        LEFT OUTER JOIN OACT T7 ON T6."FatherNum" = T7."AcctCode" 
    	WHERE :Plan = '@@Account' AND ((:PlanType = 'P' AND 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END = 'P') OR (:PlanType = 'B' AND 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END = 'B') OR :PlanType = '') 
    	
    	UNION 
    	
    	SELECT T0."Lvl", T0."Code" AS "AcctCode", T0."Description", T0."Postable", 0.0 AS "Variator", '' AS "Liq", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."Code" 
            WHEN T0."Lvl" = 2 THEN T1."Code" 
            WHEN T0."Lvl" = 3 THEN T2."Code" 
            WHEN T0."Lvl" = 4 THEN T3."Code" 
            WHEN T0."Lvl" = 5 THEN T4."Code" 
            WHEN T0."Lvl" = 6 THEN T5."Code" 
            WHEN T0."Lvl" = 7 THEN T6."Code" 
            WHEN T0."Lvl" = 8 THEN T7."Code" 
            ELSE '' 
        END AS "Level1", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."Code" 
            WHEN T0."Lvl" = 3 THEN T1."Code" 
            WHEN T0."Lvl" = 4 THEN T2."Code" 
            WHEN T0."Lvl" = 5 THEN T3."Code" 
            WHEN T0."Lvl" = 6 THEN T4."Code" 
            WHEN T0."Lvl" = 7 THEN T5."Code" 
            WHEN T0."Lvl" = 8 THEN T6."Code" 
            ELSE '' 
        END AS "Level2", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."Code" 
            WHEN T0."Lvl" = 4 THEN T1."Code" 
            WHEN T0."Lvl" = 5 THEN T2."Code" 
            WHEN T0."Lvl" = 6 THEN T3."Code" 
            WHEN T0."Lvl" = 7 THEN T4."Code" 
            WHEN T0."Lvl" = 8 THEN T5."Code" 
            ELSE '' 
        END AS "Level3", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."Code" 
            WHEN T0."Lvl" = 5 THEN T1."Code" 
            WHEN T0."Lvl" = 6 THEN T2."Code" 
            WHEN T0."Lvl" = 7 THEN T3."Code" 
            WHEN T0."Lvl" = 8 THEN T4."Code" 
            ELSE '' 
        END AS "Level4", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."Code" 
            WHEN T0."Lvl" = 6 THEN T1."Code" 
            WHEN T0."Lvl" = 7 THEN T2."Code" 
            WHEN T0."Lvl" = 8 THEN T3."Code" 
            ELSE '' 
        END AS "Level5", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."Code" 
            WHEN T0."Lvl" = 7 THEN T1."Code" 
            WHEN T0."Lvl" = 8 THEN T2."Code" 
            ELSE '' 
        END AS "Level6", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T1."Code" 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            ELSE '' 
        END AS "Level8", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."Code" 
            WHEN T0."Lvl" = 2 THEN T1."Code" 
            WHEN T0."Lvl" = 3 THEN T2."Code" 
            WHEN T0."Lvl" = 4 THEN T3."Code" 
            WHEN T0."Lvl" = 5 THEN T4."Code" 
            WHEN T0."Lvl" = 6 THEN T5."Code" 
            WHEN T0."Lvl" = 7 THEN T6."Code" 
            WHEN T0."Lvl" = 8 THEN T7."Code" 
            ELSE '' 
        END AS "Level1AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."Code" 
            WHEN T0."Lvl" = 3 THEN T1."Code" 
            WHEN T0."Lvl" = 4 THEN T2."Code" 
            WHEN T0."Lvl" = 5 THEN T3."Code" 
            WHEN T0."Lvl" = 6 THEN T4."Code" 
            WHEN T0."Lvl" = 7 THEN T5."Code" 
            WHEN T0."Lvl" = 8 THEN T6."Code" 
            ELSE '' 
        END AS "Level2AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."Code" 
            WHEN T0."Lvl" = 4 THEN T1."Code" 
            WHEN T0."Lvl" = 5 THEN T2."Code" 
            WHEN T0."Lvl" = 6 THEN T3."Code" 
            WHEN T0."Lvl" = 7 THEN T4."Code" 
            WHEN T0."Lvl" = 8 THEN T5."Code" 
            ELSE '' 
        END AS "Level3AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."Code" 
            WHEN T0."Lvl" = 5 THEN T1."Code" 
            WHEN T0."Lvl" = 6 THEN T2."Code" 
            WHEN T0."Lvl" = 7 THEN T3."Code" 
            WHEN T0."Lvl" = 8 THEN T4."Code" 
            ELSE '' 
        END AS "Level4AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."Code" 
            WHEN T0."Lvl" = 6 THEN T1."Code" 
            WHEN T0."Lvl" = 7 THEN T2."Code" 
            WHEN T0."Lvl" = 8 THEN T3."Code" 
            ELSE '' 
        END AS "Level5AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."Code" 
            WHEN T0."Lvl" = 7 THEN T1."Code" 
            WHEN T0."Lvl" = 8 THEN T2."Code" 
            ELSE '' 
        END AS "Level6AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T1."Code" 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            ELSE '' 
        END AS "Level8AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 2 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 3 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T5."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T6."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T7."FrgnName" 
            ELSE '' 
        END AS "Level1FrgnName", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 3 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T5."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T6."FrgnName" 
            ELSE '' 
        END AS "Level2FrgnName", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T5."FrgnName" 
            ELSE '' 
        END AS "Level3FrgnName", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T4."FrgnName" 
            ELSE '' 
        END AS "Level4FrgnName", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T3."FrgnName" 
            ELSE '' 
        END AS "Level5FrgnName", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T2."FrgnName" 
            ELSE '' 
        END AS "Level6FrgnName", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T1."FrgnName" 
            ELSE '' 
        END AS "Level7FrgnName", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T0."FrgnName" 
            ELSE '' 
        END AS "Level8FrgnName", T0."Sort", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherId", 
        CAST(T0."Code" AS nvarchar(32)) AS "Id", T0."FormatCode", T0."AcctCodeDisp", T0."Segment_0", T0."Segment_1", 
        T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", T0."Segment_7", 
        T0."Segment_8", T0."Segment_9", T0."ActCurr", T0."GroupMask", T0."DocType", T0."AccntntCod", T0."FrgnName" 
    	FROM "CRSP_TemplateAccount" T0 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T1 ON T0."FatherNum" = T1."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T2 ON T1."FatherNum" = T2."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T3 ON T2."FatherNum" = T3."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T4 ON T3."FatherNum" = T4."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T5 ON T4."FatherNum" = T5."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T6 ON T5."FatherNum" = T6."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T7 ON T6."FatherNum" = T7."Code" 
    	WHERE :Plan <> '@@Account'
    );
    /* This is important to know which Group Masks belong to Balance and which to Profit and Loss 
 It can change for different localizations */
    /* Here the actual AccountCalc Query starts and the account preparation ends*/
    /*
     Distribution Rule (OOCR, OCR1) 
 * Temp. Table with distribution rules, created with ValidFrom and ValidTo
 * Desc: If only 1 Rule per Date oder the last one, the ValidTo Column ist ToDay+99Years 
 */
    insert into "CRSP_Plan" 
    (
    	SELECT T1.*, (SELECT MAX("Lvl") FROM "CRSP_Plan0") AS "MaxLvl", T21."Description" AS "Desc1", T22."Description" AS "Desc2", 
        T23."Description" AS "Desc3", T24."Description" AS "Desc4", T25."Description" AS "Desc5", 
        T26."Description" AS "Desc6", T27."Description" AS "Desc7", T28."Description" AS "Desc8", 
        T1."Description" AS "DescAll", 
        CASE 
            WHEN (select :Plan from dummy) = '@@Account' THEN T1."AcctCode" 
            ELSE T1."Id"
        END AS "Code" 
    	FROM "CRSP_Plan0" T1
        LEFT OUTER JOIN "CRSP_AcctLang" T21 ON T1."Level1" = T21."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T22 ON T1."Level2" = T22."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T23 ON T1."Level3" = T23."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T24 ON T1."Level4" = T24."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T25 ON T1."Level5" = T25."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T26 ON T1."Level6" = T26."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T27 ON T1."Level7" = T27."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T28 ON T1."Level8" = T28."Code" 
    	ORDER BY T1."Sort"
    );

    /* Amount Brought Forward */
    
    INSERT INTO "CRSP_OCR1DistRule"
    (
    	SELECT T0."OcrCode", T0."PrcCode", 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."OcrTotal" 
        END AS "OcrTotal", 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."PrcAmount" 
        END AS "PrcAmount", 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."PrcAmount" 
        END / 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."OcrTotal" 
        END AS "OcrFactor", T0."Direct", T0."ValidFrom", IFNULL
        (
        	(
        	SELECT ADD_DAYS(T1."ValidTo", -1) FROM
        	(
        		SELECT U0."OcrCode", MIN(U1."ValidFrom") AS "ValidTo"
        		FROM OCR1 U0 INNER JOIN OCR1 U1 ON U1."OcrCode" = U0."OcrCode" AND U1."ValidFrom" > U0."ValidFrom"
        		GROUP BY U0."OcrCode"
        	) T1 
        	WHERE T1."OcrCode" = T0."OcrCode" AND T1."ValidTo" > T0."ValidFrom" 
        	), ADD_YEARS(NOW(), 99)
        ) AS "ValidTo" 
        FROM OCR1 T0 
        ORDER BY T0."OcrCode", T0."ValidFrom", T0."PrcCode"
	);

	call CRSP_TrialBalanceByCostCenter_BR_enUS_cont(:Currency, :IgnoreAdj, :AddVoucher, :DateType,
				:FromDate, :ToDate, :DimCode, :BroughtForward, :EndYear);
	
	SELECT IFNULL(T1."Typ", 'Acct') AS "Typ", IFNULL(T1."TransId", 0) AS "TransId", 
        IFNULL(T1."Line_ID", -1) AS "Line_ID", T0."Lvl", IFNULL(T0."AcctCode", '') AS "AcctCode", T0."Description", 
        T0."Postable", T0."Variator", T0."Liq", T0."Level1", T0."Level2", T0."Level3", T0."Level4", T0."Level5", 
        T0."Level6", T0."Level7", T0."Level8", T0."Level1AccntntCod", T0."Level2AccntntCod", T0."Level3AccntntCod", 
        T0."Level4AccntntCod", T0."Level5AccntntCod", T0."Level6AccntntCod", T0."Level7AccntntCod", 
        T0."Level8AccntntCod", T0."Level1FrgnName", T0."Level2FrgnName", T0."Level3FrgnName", T0."Level4FrgnName", 
        T0."Level5FrgnName", T0."Level6FrgnName", T0."Level7FrgnName", T0."Level8FrgnName", T0."Sort", 
        IFNULL(T0."FatherId", '') AS "FatherId", T0."Id", T0."MaxLvl", IFNULL(T0."Desc1", '') AS "Desc1", 
        IFNULL(T0."Desc2", '') AS "Desc2", IFNULL(T0."Desc3", '') AS "Desc3", IFNULL(T0."Desc4", '') AS "Desc4", 
        IFNULL(T0."Desc5", '') AS "Desc5", IFNULL(T0."Desc6", '') AS "Desc6", IFNULL(T0."Desc7", '') AS "Desc7", 
        IFNULL(T0."Desc8", '') AS "Desc8", IFNULL(T0."DescAll", '') AS "DescAll", T1."RefDate", 
        IFNULL(T1."FinancYear", :FinancYear) AS "FinancYear", IFNULL(T1."PrcCode", '') AS "PrcCode", 
        IFNULL(T1."OcrCode", '') AS "OcrCode", IFNULL(T1."PrjCode", '') AS "PrjCode", 
        IFNULL(T1."Credit", 0) AS "Credit", IFNULL(T1."CreditPreviousYear", 0) AS "CreditPreviousYear", 
        IFNULL(T1."Debit", 0) AS "Debit", IFNULL(T1."DebitPreviousYear", 0) AS "DebitPreviousYear", 
        IFNULL(T1."CreditBudget", 0) AS "CreditBudget", IFNULL(T1."DebitBudget", 0) AS "DebitBudget", 
        IFNULL(T1."CreditBudgetPrevYear", 0) AS "CreditBudgetPrevYear", 
        IFNULL(T1."DebitBudgetPrevYear", 0) AS "DebitBudgetPrevYear", 
        IFNULL(T1."CreditActualMonth", 0) AS "CreditActualMonth", 
        IFNULL(T1."CreditMonthPreviousYear", 0) AS "CreditMonthPreviousYear", 
        IFNULL(T1."DebitActualMonth", 0) AS "DebitActualMonth", 
        IFNULL(T1."DebitMonthPreviousYear", 0) AS "DebitMonthPreviousYear", 
        IFNULL(T1."CreditActualMonthBudget", 0) AS "CreditActualMonthBudget", 
        IFNULL(T1."DebitActualMonthBudget", 0) AS "DebitActualMonthBudget", 
        IFNULL(T1."CreditFinancYear", 0) AS "CreditFinancYear", IFNULL(T1."DebitFinancYear", 0) AS "DebitFinancYear", 
        IFNULL(T1."CreditFinancYearBudget", 0) AS "CreditFinancYearBudget", 
        IFNULL(T1."DebitFinancYearBudget", 0) AS "DebitFinancYearBudget", 
        IFNULL(T1."CreditPrevFinancYear", 0) AS "CreditPrevFinancYear", 
        IFNULL(T1."DebitPrevFinancYear", 0) AS "DebitPrevFinancYear", IFNULL(T1."BFDebit", 0) AS "BFDebit", 
        IFNULL(T1."BFCredit", 0) AS "BFCredit", IFNULL(T1."OBDebit", 0) AS "OBDebit", 
        IFNULL(T1."OBCredit", 0) AS "OBCredit", IFNULL(T1."BFOBDebit", 0) AS "BFOBDebit", 
        IFNULL(T1."BFOBCredit", 0) AS "BFOBCredit", IFNULL(T6."OcrName", '') AS "OcrName", 
        IFNULL(T7."OcrName", '') AS "PrcName", IFNULL(T8."PrjName", '') AS "PrjName", 
        IFNULL(T9."GrpCode", '') AS "PrcGrpCode", T3."AcctName", T3."CurrTotal", T3."Finanse", T3."Budget", 
        T3."Frozen", T3."Levels", IFNULL(T3."ExportCode", '') AS "ExportCode", T3."GrpLine", T0."DocType", 
        T3."ActType", IFNULL(T3."OverCode", '') AS "OverCode", IFNULL(T3."Project", '') AS "OACTProject", 
        IFNULL(T0."FormatCode", '') AS "FormatCode", IFNULL(T0."AcctCodeDisp", '') AS "AcctCodeDisp", 
        IFNULL(T0."ActCurr", '') AS "ActCurr", IFNULL(T0."GroupMask", 0) AS "GroupMask", T0."Segment_0", 
        T0."Segment_1", T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", 
        T0."Segment_7", T0."Segment_8", T0."Segment_9", IFNULL(T0."AccntntCod", '') AS "AccntntCod", 
        IFNULL(T0."FrgnName", '') AS "FrgnName" 
    FROM "CRSP_Plan" T0 
        LEFT OUTER JOIN CRSP_TEMPRES T1 ON T0."AcctCode" = T1."Account" 
        LEFT OUTER JOIN OACT T3 ON T0."AcctCode" = T3."AcctCode" 
        LEFT OUTER JOIN OOCR T6 ON T1."OcrCode" = T6."OcrCode" 
        LEFT OUTER JOIN OOCR T7 ON T1."PrcCode" = T7."OcrCode" 
        LEFT OUTER JOIN OPRJ T8 ON T1."PrjCode" = T8."PrjCode" 
        LEFT OUTER JOIN OPRC T9 ON T1."PrcCode" = T9."PrcCode" 
    ORDER BY "PrcCode", T0."Sort";
	
    /* Clean up */
    /*LEFT OUTER JOIN OBPL T10 ON T1.BPLId = T10.BPLId*/
    /* External Code */
    /* Foreign Name */
    /*,IFNULL(T1.BPLId,'') As BPLId*/
    /*,IFNULL(T10.BPLName,'') As BPLName*/
    DELETE FROM "CRSP_TEMPJDT1";
    DELETE FROM "CRSP_TEMPRES";
    DELETE FROM "CRSP_OCR1DistRule";
    DELETE FROM "CRSP_Plan";
    DELETE FROM "CRSP_TemplateAccount";
    DELETE FROM "CRSP_Plan0";
    DELETE FROM "CRSP_AcctLang";
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2
CREATE PROCEDURE CRSP_TrialBalanceByCostCenter_BR_enUS4
(
in TemplateID VARCHAR(200)
) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
Plan varchar(200);
BEGIN /*
    
***** General Information *****
Name: OFRT_FinancialTemplates
Description:
Return name and absid for selected financial template

Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22

***** Updates *****
*/
    /* Financial Template ID, @@Account for Chart of Accounts. Param: '[%TemplateID]' */
    Plan := :TemplateID;
    IF :Plan = '@@Account' THEN 
        SELECT '@@Account' AS "AbsId", 'Chart of Accounts' AS "Name" 
        FROM DUMMY;
    ELSE 
        SELECT "AbsId", "Name" 
        FROM OFRT 
        WHERE "AbsId" = :Plan;
    END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2
CREATE PROCEDURE CRSP_TrialBalanceByCostCenter_BR_enUS_cont
(
in Currency VARCHAR(10),
in IgnoreAdj varchar(1),
in AddVoucher varchar(1),
in DateType varchar(256),
in FromDate timestamp,
in ToDate timestamp,
in DimCode nvarchar(10),
in BroughtForward varchar(1),
in EndYear varchar(1)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
FinancYear timestamp;
BEGIN
	SELECT 
    (
    	SELECT T0."FinancYear" FROM OACP T0 
        INNER JOIN OFPR T1 ON T0."PeriodCat" = T1."Category" 
    	WHERE T1."F_RefDate" <= :ToDate AND T1."T_RefDate" >= :ToDate
    ) INTO FinancYear FROM DUMMY;

    INSERT INTO CRSP_TEMPRES (SELECT T0."Typ", null, null, T0."RefDate", T0."FinancYear", T0."Account", 
        IFNULL(T0."PrcCode", '') AS "PrcCode", IFNULL(T0."OcrCode", '') AS "OcrCode", 
        IFNULL(T0."PrjCode", '') AS "PrjCode", 
        SUM(T0."Credit") AS "Credit", 
        SUM(T0."CreditPreviousYear") AS "CreditPreviousYear", 
        SUM(T0."Debit") AS "Debit", 
        SUM(T0."DebitPreviousYear") AS "DebitPreviousYear", 
        SUM(T0."CreditBudget") AS "CreditBudget", 
        SUM(T0."DebitBudget") AS "DebitBudget", 
        
        SUM(T0."CreditBudgetPrevYear") AS "CreditBudgetPrevYear", 
        SUM(T0."DebitBudgetPrevYear") AS "DebitBudgetPrevYear", 
        
        SUM(T0."CreditActualMonth") AS "CreditActualMonth", 
        SUM(T0."CreditMonthPreviousYear") AS "CreditMonthPreviousYear", 
        SUM(T0."DebitActualMonth") AS "DebitActualMonth", 
        SUM(T0."DebitMonthPreviousYear") AS "DebitMonthPreviousYear", 
        
        SUM(T0."CreditActualMonthBudget") AS "CreditActualMonthBudget", 
        SUM(T0."DebitActualMonthBudget") AS "DebitActualMonthBudget", 
        SUM(T0."CreditFinancYear") AS "CreditFinancYear", 
        SUM(T0."DebitFinancYear") AS "DebitFinancYear", 
        SUM(T0."CreditFinancYearBudget") AS "CreditFinancYearBudget", 
        SUM(T0."DebitFinancYearBudget") AS "DebitFinancYearBudget", 
        SUM(T0."CreditPrevFinancYear") AS "CreditPrevFinancYear", 
        SUM(T0."DebitPrevFinancYear") AS "DebitPrevFinancYear", 
        SUM(T0."BFDebit") AS "BFDebit", 
        SUM(T0."BFCredit") AS "BFCredit", 
        SUM(T0."OBDebit") AS "OBDebit", 
        SUM(T0."OBCredit") AS "OBCredit", 
        SUM(T0."BFOBDebit") AS "BFOBDebit", 
        SUM(T0."BFOBCredit") AS "BFOBCredit" 
    FROM (
    SELECT T0."TransId", T0."Line_ID", NULL AS "RefDate", NULL AS "FinancYear", T0."Account" AS "Account", 
        'BFJDT1' AS "Typ", IFNULL(T2."PrcCode", '') AS "PrcCode", IFNULL(T2."OcrCode", '') AS "OcrCode", 
        IFNULL(T0."Project", '') AS "PrjCode", 0 AS "Credit", 0 AS "CreditPreviousYear", 0 AS "Debit", 
        0 AS "DebitPreviousYear", 0 AS "CreditBudget", 0 AS "DebitBudget", 0 AS "CreditBudgetPrevYear", 
        0 AS "DebitBudgetPrevYear", 0 AS "CreditActualMonth", 0 AS "CreditMonthPreviousYear", 
        0 AS "DebitActualMonth", 0 AS "DebitMonthPreviousYear", 0 AS "CreditActualMonthBudget", 
        0 AS "DebitActualMonthBudget", 0 AS "CreditFinancYear", 0 AS "DebitFinancYear", 
        0 AS "CreditFinancYearBudget", 0 AS "DebitFinancYearBudget", 0 AS "CreditPrevFinancYear", 
        0 AS "DebitPrevFinancYear", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFDebit", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFCredit", 
        0 AS "OBDebit", 0 AS "OBCredit", 
        CASE 
            WHEN T0."TransType" = '-2' AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFOBDebit", 
        CASE 
            WHEN T0."TransType" = '-2' AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END < :FromDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "BFOBCredit"
        --into "CRSP_TEMPJDT1"
    FROM JDT1 T0 
        LEFT OUTER JOIN "CRSP_OCR1DistRule" T2 ON T2."OcrCode" = 
            CASE :DimCode 
                WHEN '2' THEN T0."OcrCode2" 
                WHEN '3' THEN T0."OcrCode3" 
                WHEN '4' THEN T0."OcrCode4" 
                WHEN '5' THEN T0."OcrCode5" 
                ELSE T0."ProfitCode" 
            END AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= T2."ValidFrom" AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= T2."ValidTo" 
        INNER JOIN "CRSP_Plan" T4 ON T0."Account" = T4."AcctCode" 
    WHERE 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END < :FromDate AND ((:IgnoreAdj = 'Y' AND T0."AdjTran" = 'N') OR (:IgnoreAdj = 'N') OR (:IgnoreAdj = 'O' AND
         T0."AdjTran" = 'Y')) AND ((T4."DocType" = 'B' AND NOT (
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END = ADD_YEARS(ADD_DAYS(:FinancYear, -1), 1) AND T0."TransType" = -3) OR (T4."DocType" = 'P' AND
         NOT T0."TransType" = -3)) OR :EndYear = 'Y') AND :BroughtForward = 'Y' 
    UNION 
    SELECT T0."TransId", T0."Line_ID", CAST('01.' || CAST(MONTH(
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END) AS varchar) || '.' || CAST(YEAR(
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END) AS varchar) AS timestamp) AS "RefDate", :FinancYear AS "FinancYear", T0."Account" AS "Account", 
        'JDT1' AS "Typ", IFNULL(T2."PrcCode", '') AS "PrcCode", IFNULL(T2."OcrCode", '') AS "OcrCode", 
        IFNULL(T0."Project", '') AS "PrjCode", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FromDate AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= :ToDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "Credit", 0 AS "CreditPreviousYear", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FromDate AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= :ToDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "Debit", 0 AS "DebitPreviousYear", 0 AS "CreditBudget", 0 AS "DebitBudget", 
        0 AS "CreditBudgetPrevYear", 0 AS "DebitBudgetPrevYear", 
        CASE 
            WHEN MONTH(
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END) = MONTH(:ToDate) THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "CreditActualMonth", 0 AS "CreditMonthPreviousYear", 
        CASE 
            WHEN MONTH(
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END) = MONTH(:ToDate) THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "DebitActualMonth", 0 AS "DebitMonthPreviousYear", 0 AS "CreditActualMonthBudget", 
        0 AS "DebitActualMonthBudget", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FinancYear AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= ADD_DAYS(ADD_YEARS(:FinancYear, 1), -1) THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "CreditFinancYear", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FinancYear AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= ADD_DAYS(ADD_YEARS(:FinancYear, 1), -1) THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "DebitFinancYear", 0 AS "CreditFinancYearBudget", 0 AS "DebitFinancYearBudget", 
        0 AS "CreditPrevFinancYear", 0 AS "DebitPrevFinancYear", 0 AS "BFDebit", 0 AS "BFCredit", 
        CASE 
            WHEN T0."TransType" = '-2' AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FromDate AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= :ToDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSDeb" 
                ELSE T0."Debit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "OBDebit", 
        CASE 
            WHEN T0."TransType" = '-2' AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= :FromDate AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= :ToDate THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "OBCredit", 0 AS "BFOBDebit", 0 AS "BFOBCredit" 
    FROM JDT1 T0 
        LEFT OUTER JOIN "CRSP_OCR1DistRule" T2 ON T2."OcrCode" = 
            CASE :DimCode 
                WHEN '2' THEN T0."OcrCode2" 
                WHEN '3' THEN T0."OcrCode3" 
                WHEN '4' THEN T0."OcrCode4" 
                WHEN '5' THEN T0."OcrCode5" 
                ELSE T0."ProfitCode" 
            END AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= T2."ValidFrom" AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= T2."ValidTo" 
        INNER JOIN "CRSP_Plan" T4 ON T0."Account" = T4."AcctCode" 
    WHERE (
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END >= :FromDate OR 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END >= :FinancYear) AND (
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END <= :ToDate OR 
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END <= ADD_DAYS(ADD_YEARS(:FinancYear, 1), -1)) AND ((:IgnoreAdj = 'Y' AND T0."AdjTran" = 'N') OR
         (:IgnoreAdj = 'N') OR (:IgnoreAdj = 'O' AND T0."AdjTran" = 'Y')) AND ((T4."DocType" = 'B' AND NOT (
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END = ADD_YEARS(ADD_DAYS(:FinancYear, -1), 1) AND T0."TransType" = -3) OR (T4."DocType" = 'P' AND
         NOT T0."TransType" = -3)) OR :EndYear = 'Y') 
    UNION ALL 
    SELECT T0."TransId", T0."Line_ID", CAST('01.' || CAST(MONTH(
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END) AS varchar) || '.' || CAST(YEAR(
        CASE :DateType 
            WHEN 'DueDate' THEN T0."DueDate" 
            WHEN 'TaxDate' THEN T0."TaxDate" 
            ELSE T0."RefDate" 
        END) AS varchar) AS timestamp) AS "RefDate", ADD_YEARS(:FinancYear, -1) AS "FinancYear", 
        T0."Account" AS "Account", 'JDT1' AS "Typ", IFNULL(T2."PrcCode", '') AS "PrcCode", 
        IFNULL(T2."OcrCode", '') AS "OcrCode", IFNULL(T0."Project", '') AS "PrjCode", 0 AS "Credit", 
        CASE 
            WHEN 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END >= ADD_YEARS(:FromDate, -1) AND 
            CASE :DateType 
                WHEN 'DueDate' THEN T0."DueDate" 
                WHEN 'TaxDate' THEN T0."TaxDate" 
                ELSE T0."RefDate" 
            END <= ADD_YEARS(:ToDate, -1) THEN 
            CASE 
                WHEN :Currency = 'Sys' THEN T0."SYSCred" 
                ELSE T0."Credit" 
            END * IFNULL(T2."OcrFactor", 1) 
            ELSE 0 
        END AS "CreditPreviousYear", 0 AS "Debit", 
        CASE 
            WHEN 
            CASE :DateType 
