        CASE 
            WHEN MONTH(ADD_MONTHS(T1."FinancYear", T0."Line_ID")) = MONTH(:ToDate) 
            THEN T0."CredLTotal" * IFNULL(T4."OcrFactor", 1) 
            ELSE 0 
        END AS "CreditActualMonthBudget", 
        CASE 
            WHEN MONTH(ADD_MONTHS(T1."FinancYear", T0."Line_ID")) = MONTH(:ToDate) 
            THEN T0."DebLTotal" * IFNULL(T4."OcrFactor", 1) 
            ELSE 0 
        END AS "DebitActualMonthBudget", 0 AS "CreditFinancYear", 0 AS "DebitFinancYear", 
        CASE 
            WHEN  ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= :FinancYear AND
            	  ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_MONTHS(:FinancYear, 12) 
           	THEN T0."CredLTotal" * IFNULL(T4."OcrFactor", 1) 
            ELSE 0 
        END AS "CreditFinancYearBudget", 
        CASE 
            WHEN  ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= :FinancYear AND  
            	  ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_MONTHS(:FinancYear, 12) 
            THEN T0."DebLTotal" * IFNULL(T4."OcrFactor", 1) 
            ELSE 0 
        END AS "DebitFinancYearBudget", 0 AS "CreditPrevFinancYear", 0 AS "DebitPrevFinancYear", 0 AS "BFDebit", 
        0 AS "BFCredit", 0 AS "OBDebit", 0 AS "OBCredit", 0 AS "BFOBDebit", 0 AS "BFOBCredit" 
    FROM BGT1 T0 
        LEFT OUTER JOIN OBGT T1 ON T0."BudgId" = T1."AbsId" 
        LEFT OUTER JOIN OBGS T2 ON T0."Instance" = T2."AbsId" 
        LEFT OUTER JOIN "CRSP_OCR1DistRule" T4 ON T4."OcrCode" = 
            CASE :DimCode 
                WHEN '2' THEN T2."OcrCode2" 
                WHEN '3' THEN T2."OcrCode3" 
                WHEN '4' THEN T2."OcrCode4" 
                WHEN '5' THEN T2."OcrCode5" 
                ELSE T2."OcrCode" 
            END AND ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= T4."ValidFrom" AND 
                    ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= T4."ValidTo" 
        INNER JOIN "CRSP_Plan" T5 ON T0."AcctCode" = T5."AcctCode" 
    WHERE ( ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= :FinancYear 
    		OR  ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= :FromDate) 
    		AND ( ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_MONTHS(:FinancYear, 12) 
    		OR ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_MONTHS(:ToDate, 12)) 
    UNION ALL 
    SELECT T0."Instance" AS "TransID", T0."Line_ID", ADD_MONTHS(T1."FinancYear", T0."Line_ID") AS "RefDate", 
    	T1."FinancYear" AS "FinancYear", 
        T0."AcctCode" AS "Account", 'BGT1' AS "Typ", IFNULL(T4."PrcCode", '') AS "PrcCode", 
        IFNULL(T4."OcrCode", '') AS "OcrCode", IFNULL(T2."PrjCode", '') AS "PrjCode", 0 AS "Credit", 
        0 AS "CreditPreviousYear", 0 AS "Debit", 0 AS "DebitPreviousYear", 0 AS "CreditBudget", 0 AS "DebitBudget", 
        CASE 
            WHEN ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= ADD_YEARS(:FromDate, -1) AND
            	 ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_YEARS(:ToDate, -1) 
            THEN T0."CredLTotal" * IFNULL(T4."OcrFactor", 1) 
            ELSE 0 
        END AS "CreditBudgetPrevYear", 
        CASE 
            WHEN  ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= ADD_YEARS(:FromDate, -1) AND
              	  ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_YEARS(:ToDate, -1) 
            THEN T0."DebLTotal" * IFNULL(T4."OcrFactor", 1) 
            ELSE 0 
        END AS "DebitBudgetPrevYear", 0 AS "CreditActualMonth", 0 AS "CreditMonthPreviousYear", 
        0 AS "DebitActualMonth", 0 AS "DebitMonthPreviousYear", 0 AS "CreditActualMonthBudget", 
        0 AS "DebitActualMonthBudget", 0 AS "CreditFinancYear", 0 AS "DebitFinancYear", 
        0 AS "CreditFinancYearBudget", 0 AS "DebitFinancYearBudget", 0 AS "CreditPrevFinancYear", 
        0 AS "DebitPrevFinancYear", 0 AS "BFDebit", 0 AS "BFCredit", 0 AS "OBDebit", 0 AS "OBCredit", 
        0 AS "BFOBDebit", 0 AS "BFOBCredit" 
    FROM BGT1 T0 
        LEFT OUTER JOIN OBGT T1 ON T0."BudgId" = T1."AbsId" 
        LEFT OUTER JOIN OBGS T2 ON T0."Instance" = T2."AbsId" 
        LEFT OUTER JOIN "CRSP_OCR1DistRule" T4 ON T4."OcrCode" = 
            CASE :DimCode 
                WHEN '2' THEN T2."OcrCode2" 
                WHEN '3' THEN T2."OcrCode3" 
                WHEN '4' THEN T2."OcrCode4" 
                WHEN '5' THEN T2."OcrCode5" 
                ELSE T2."OcrCode" 
            END AND (ADD_MONTHS(T1."FinancYear", T0."Line_ID")) >= T4."ValidFrom" AND 
            	(ADD_MONTHS(T1."FinancYear", T0."Line_ID")) <= T4."ValidTo" 
        INNER JOIN "CRSP_Plan" T5 ON T0."AcctCode" = T5."AcctCode" 
    WHERE ( ADD_MONTHS(T1."FinancYear", T0."Line_ID")>= :FinancYear OR  
    		ADD_MONTHS(T1."FinancYear", T0."Line_ID") >= ADD_YEARS(:FromDate, -1)) AND 
    	  ( ADD_MONTHS(T1."FinancYear", T0."Line_ID")<= ADD_MONTHS(:FinancYear, 12) OR 
    	  	ADD_MONTHS(T1."FinancYear", T0."Line_ID") <= ADD_MONTHS(ADD_YEARS(:ToDate, -1), 12)
   		  )
   	) T0
   	GROUP BY T0."Typ", T0."RefDate", T0."FinancYear", T0."Account", T0."PrcCode", T0."OcrCode", T0."PrjCode");
          
    /* SUM all Results */
    /*
     CAREFUL: Including the TransID and Line_ID in this summary might cause performance issue. Take this out if it is not required 
    */
    /* Budget (BGT1) Previous Year*/
    /* Budget (BGT1) Actual Year*/
    /* Journal Vouchers Prev Year*/
    /* Journal Vouchers */
    /* Journal Prev Year*/
    /* Journals (JDT1) Financ Year*/
    /*,IFNULL(CAST(T0.BPLId AS NVARCHAR(10)),'') As BPLId*/
    /* Exclude Endyear Closings */
    /*,IFNULL(CAST(T0.BPLId AS NVARCHAR(10)),'') As BPLId*/
    /*,IFNULL(CAST(T0.BPLId AS NVARCHAR(10)),'') As BPLId*/
    /*,IFNULL(CAST(T0.BPLId AS NVARCHAR(10)),'') As BPLId*/
    /*,IFNULL(CAST(T0.BPLId AS NVARCHAR(10)),'') As BPLId*/
    /*,'' As BPLId*/
    /*,'' As BPLId*/
    /* Link Distribution Rules*/
    /*,T0.BPLId*/
    /*,IFNULL(CAST(T0.BPLId AS NVARCHAR(10)),'') As BPLId*/
    
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:CRSP_TrialBalanceByCostCenter_BR_enUS_cont
CREATE PROCEDURE CRSP_TrialBalance_BR_enUS
(
in TemplateID VARCHAR(20),
in in_Currency VARCHAR(10),
in in_IgnoreAdj VARCHAR(1),
in in_AddVoucher VARCHAR(1),
in in_DateType varchar(256),
in in_FromDate timestamp,
in in_ToDate timestamp,
in in_DimCode nvarchar(10)
) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
Plan varchar(20);
MinGroupMask integer;
PlanType varchar(1);
Currency varchar(10);
IgnoreAdj varchar(1);
AddVoucher varchar(1);
DateType varchar(256);
FromDate timestamp;
ToDate timestamp;
DimCode nvarchar(10);
BroughtForward varchar(1);
EndYear varchar(1);
MainCurr varchar(3);
SysCurr varchar(3);
FinancYear timestamp;
BEGIN /*
    
***** General Information *****
Name: JDT1_AccountCalc (including Preparation for account structure)
Description: Return Journal Entries distributed according to distribution rules to cost centers
with relevant filters.
This datasource includes branches for intercompany only supported from SAP B1 8.81 PL10 or higher
Creator: coresystems ag for SAP AG, muf@coresystems.ch
Create Date: 2011-06-22
*/
    Plan := :TemplateID;
    /*
     Here we define the type of the report (P = Profit and Loss) and the Minimum Group Mask for Profit and Loss accounts 
This can be different for different localizations a mapping should be included. 
Therefore it is not supported in the official Version. 
It is kept in the datasource to enable this option in case a customer needs it. Then the MinGroupMask can be adjusted. 
    */
    MinGroupMask := 3;
    PlanType := 'P';
    /* Select which currency to display in the report. Possible values are Loc and Sys.*/
    Currency := :in_Currency;
    /*
     Include Journal Entries with checkbox "Ignore Adjustments (13. Per)" selected (Y) or not (N). Param '[%IgnoreAdj]' 
    */
    IgnoreAdj := :in_IgnoreAdj;
    IF :IgnoreAdj = '0' THEN 
        IgnoreAdj := 'N';
    ELSE 
        IgnoreAdj := 'Y';
        /* Include Journal Vouchers (Y) or not (N). */
    END IF;
    AddVoucher := :in_AddVoucher;
    IF :AddVoucher = '0' THEN 
        AddVoucher := 'N';
    ELSE 
        AddVoucher := 'Y';
        /* Date Type to set the filter and sort by. Possible values are RefDate, TaxDate and DueDate. */
    END IF;
    DateType := :in_DateType;
    /* Date Filter From and To Dates. Format 'YYYYMMDD' */
    FromDate := :in_FromDate;
    ToDate := :in_ToDate;
    /* Dimension new since Version 8.81.*/
    DimCode := in_DimCode;
    /* Include Amount Brought Forward (Y) or not (N). */
    /* Hardcoded for this report */
    BroughtForward := 'Y';
    /* Include End Year Closing (Y) or not (N). */
    /* Hardcoded for this report */
    EndYear := 'Y';
    /* Internal Parameters */
    /* Local Currency */
    SELECT 
    (
    	SELECT TOP 1 T2."MainCurncy" FROM OADM T2
    ) INTO MainCurr FROM DUMMY;
    /* System Currency */
    SELECT
    (
    	SELECT TOP 1 T2."SysCurrncy" FROM OADM T2
    ) INTO SysCurr FROM DUMMY;
    /* The Finance Year is determined by the RefDate no matter how the parameter DateType is set */
    SELECT 
    (
    	SELECT T0."FinancYear" FROM OACP T0 
        INNER JOIN OFPR T1 ON T0."PeriodCat" = T1."Category" 
    	WHERE T1."F_RefDate" <= :ToDate AND T1."T_RefDate" >= :ToDate
    ) INTO FinancYear FROM DUMMY;
    /* Account structure preparation */
    insert into "CRSP_TemplateAccount" 
    (
    	SELECT CAST(T0."CatId" AS nvarchar(32)) AS "Code", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherNum", 
        T0."Name" AS "Description", T0."Levels" AS "Lvl", T0."VisOrder" * 10000 AS "Sort", T2."DocType", 
        'N' AS "Postable", CAST(T0."CatId" AS nvarchar(32)) AS "FormatCode", 
        CAST(T0."CatId" AS nvarchar(32)) AS "AcctCodeDisp", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_0", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_1", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_2", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_3", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_4", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_5", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_6", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_7", CAST(T0."CatId" AS nvarchar(32)) AS "Segment_8", 
        CAST(T0."CatId" AS nvarchar(32)) AS "Segment_9", '' AS "ActCurr", 0 AS "GroupMask", 
        CAST(T0."CatId" AS nvarchar(32)) AS "AccntntCod", T0."FrgnName" 
    	FROM OFRC T0 
        INNER JOIN OFRT T2 ON T0."TemplateId" = T2."AbsId" 
    	WHERE CAST(T0."TemplateId" AS nvarchar) = :Plan 
    	
    	UNION 
    	
    	SELECT CAST(LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) AS nvarchar(32)) AS "Code", 
        CAST(T0."CatId" AS nvarchar(32)) AS "FatherNum", T1."AcctName" AS "Description", 
        (
        	SELECT MAX("Levels") FROM OFRC 
        	WHERE "CatId" = T0."CatId" AND CAST("TemplateId" AS nvarchar) = :Plan
        ) + 1 AS "Lvl", 
        (
        	SELECT MAX("VisOrder") * 10000 
        	FROM OFRC 
        	WHERE "CatId" = T0."CatId" AND CAST("TemplateId" AS nvarchar) = :Plan) + T0."VisOrder" AS "Sort", 
        	T2."DocType", 'Y' AS "Postable", LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) AS "FormatCode", 
        	CASE 
           		WHEN T1."FormatCode" IS NULL THEN LTRIM(RTRIM(T1."AcctCode")) 
           		WHEN T1."FormatCode" = T1."AcctCode" THEN LTRIM(RTRIM(T1."AcctCode")) 
           		ELSE REPLACE(IFNULL(T1."Segment_0", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_1", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_2", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_3", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_4", 'x') || 
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_5", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_6", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_7", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_8", 'x') ||
           		(SELECT TOP 1 "ActSep" FROM OADM) || IFNULL(T1."Segment_9", 'x'), 
           		(SELECT TOP 1 "ActSep" FROM OADM) || 'x', '') 
        	END AS "AcctCodeDisp", T1."Segment_0", T1."Segment_1", T1."Segment_2", T1."Segment_3", T1."Segment_4", 
        	T1."Segment_5", T1."Segment_6", T1."Segment_7", T1."Segment_8", T1."Segment_9", T1."ActCurr", T1."GroupMask", 
        	T1."AccntntCod", T1."FrgnName" 
    		FROM FRC1 T0 
 	    	INNER JOIN OACT T1 ON T0."AcctCode" = T1."AcctCode" 
    	   	INNER JOIN OFRT T2 ON T0."TemplateId" = T2."AbsId" 
    		WHERE CAST(T0."TemplateId" AS nvarchar) = :Plan
    );
    /* The Accounts (including Template) */
    insert into "CRSP_AcctLang"
    (
    	SELECT "AcctCode" AS "Code", "AcctName" AS "Description" 
    	FROM OACT 
    	WHERE :Plan = '@@Account' 
    	UNION 
    	SELECT "Code", "Description" 
    	FROM "CRSP_TemplateAccount" 
    	WHERE :Plan <> '@@Account'
    );

	insert into "CRSP_Plan0"
	(
    	/* OACT Structure */
    	SELECT T0."Levels" AS "Lvl", T0."AcctCode" AS "AcctCode", T0."AcctName" AS "Description", T0."Postable", 
        0.0 AS "Variator", '' AS "Liq", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T6."FormatCode", T6."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T7."FormatCode", T7."AcctCode"))) 
            ELSE '' 
        END AS "Level1", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T6."FormatCode", T6."AcctCode"))) 
            ELSE '' 
        END AS "Level2", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T5."FormatCode", T5."AcctCode"))) 
            ELSE '' 
        END AS "Level3", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T4."FormatCode", T4."AcctCode"))) 
            ELSE '' 
        END AS "Level4", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T3."FormatCode", T3."AcctCode"))) 
            ELSE '' 
        END AS "Level5", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T2."FormatCode", T2."AcctCode"))) 
            ELSE '' 
        END AS "Level6", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."FormatCode")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(IFNULL(T1."FormatCode", T1."AcctCode"))) 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."FormatCode")) 
            ELSE '' 
        END AS "Level8", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T6."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T7."AccntntCod")) 
            ELSE '' 
        END AS "Level1AccntntCod", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T6."AccntntCod")) 
            ELSE '' 
        END AS "Level2AccntntCod", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T5."AccntntCod")) 
            ELSE '' 
        END AS "Level3AccntntCod", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T4."AccntntCod")) 
            ELSE '' 
        END AS "Level4AccntntCod", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T3."AccntntCod")) 
            ELSE '' 
        END AS "Level5AccntntCod", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T2."AccntntCod")) 
            ELSE '' 
        END AS "Level6AccntntCod", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T1."AccntntCod")) 
            ELSE '' 
        END AS "Level7AccntntCod", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."AccntntCod")) 
            ELSE '' 
        END AS "Level8AccntntCod", 
        CASE 
            WHEN T0."Levels" = 1 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T5."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T6."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T7."FrgnName")) 
            ELSE '' 
        END AS "Level1FrgnName", 
        CASE 
            WHEN T0."Levels" = 2 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T5."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T6."FrgnName")) 
            ELSE '' 
        END AS "Level2FrgnName", 
        CASE 
            WHEN T0."Levels" = 3 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T4."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T5."FrgnName")) 
            ELSE '' 
        END AS "Level3FrgnName", 
        CASE 
            WHEN T0."Levels" = 4 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T3."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T4."FrgnName")) 
            ELSE '' 
        END AS "Level4FrgnName", 
        CASE 
            WHEN T0."Levels" = 5 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T2."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T3."FrgnName")) 
            ELSE '' 
        END AS "Level5FrgnName", 
        CASE 
            WHEN T0."Levels" = 6 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T1."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T2."FrgnName")) 
            ELSE '' 
        END AS "Level6FrgnName", 
        CASE 
            WHEN T0."Levels" = 7 THEN LTRIM(RTRIM(T0."FrgnName")) 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T1."FrgnName")) 
            ELSE '' 
        END AS "Level7FrgnName", 
        CASE 
            WHEN T0."Levels" = 8 THEN LTRIM(RTRIM(T0."FrgnName")) 
            ELSE '' 
        END AS "Level8FrgnName", 
        T0."GroupMask" * 10000 + T0."GrpLine" AS "Sort", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherId", CAST(T0."AcctCode" AS nvarchar(32)) AS "Id", 
        LTRIM(RTRIM(IFNULL(T0."FormatCode", T0."AcctCode"))) AS "FormatCode", 
        CASE 
            WHEN T0."FormatCode" IS NULL THEN LTRIM(RTRIM(T0."AcctCode")) 
            WHEN T0."FormatCode" = T0."AcctCode" THEN LTRIM(RTRIM(T0."AcctCode")) 
            ELSE REPLACE(IFNULL(T0."Segment_0", 'x') || 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_1", 'x') || 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_2", 'x') || 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_3", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_4", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_5", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_6", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_7", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_8", 'x') ||
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || IFNULL(T0."Segment_9", 'x'), 
            (SELECT TOP 1 "ActSep" 
            FROM OADM) || 'x', '') 
        END AS "AcctCodeDisp", 
        T0."Segment_0", T0."Segment_1", T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", T0."Segment_7", T0."Segment_8", T0."Segment_9", 
        T0."ActCurr", T0."GroupMask", 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END AS "DocType", T0."AccntntCod", T0."FrgnName"
    	
    	FROM OACT T0 
        LEFT OUTER JOIN OACT T1 ON T0."FatherNum" = T1."AcctCode" 
        LEFT OUTER JOIN OACT T2 ON T1."FatherNum" = T2."AcctCode" 
        LEFT OUTER JOIN OACT T3 ON T2."FatherNum" = T3."AcctCode" 
        LEFT OUTER JOIN OACT T4 ON T3."FatherNum" = T4."AcctCode" 
        LEFT OUTER JOIN OACT T5 ON T4."FatherNum" = T5."AcctCode" 
        LEFT OUTER JOIN OACT T6 ON T5."FatherNum" = T6."AcctCode" 
        LEFT OUTER JOIN OACT T7 ON T6."FatherNum" = T7."AcctCode" 
    	WHERE :Plan = '@@Account' AND ((:PlanType = 'P' AND 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END = 'P') OR (:PlanType = 'B' AND 
        CASE 
            WHEN T0."GroupMask" >= :MinGroupMask THEN 'P' 
            ELSE 'B' 
        END = 'B') OR :PlanType = '') 
    	
    	UNION 
    	
    	SELECT T0."Lvl", T0."Code" AS "AcctCode", T0."Description", T0."Postable", 0.0 AS "Variator", '' AS "Liq", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."Code" 
            WHEN T0."Lvl" = 2 THEN T1."Code" 
            WHEN T0."Lvl" = 3 THEN T2."Code" 
            WHEN T0."Lvl" = 4 THEN T3."Code" 
            WHEN T0."Lvl" = 5 THEN T4."Code" 
            WHEN T0."Lvl" = 6 THEN T5."Code" 
            WHEN T0."Lvl" = 7 THEN T6."Code" 
            WHEN T0."Lvl" = 8 THEN T7."Code" 
            ELSE '' 
        END AS "Level1", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."Code" 
            WHEN T0."Lvl" = 3 THEN T1."Code" 
            WHEN T0."Lvl" = 4 THEN T2."Code" 
            WHEN T0."Lvl" = 5 THEN T3."Code" 
            WHEN T0."Lvl" = 6 THEN T4."Code" 
            WHEN T0."Lvl" = 7 THEN T5."Code" 
            WHEN T0."Lvl" = 8 THEN T6."Code" 
            ELSE '' 
        END AS "Level2", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."Code" 
            WHEN T0."Lvl" = 4 THEN T1."Code" 
            WHEN T0."Lvl" = 5 THEN T2."Code" 
            WHEN T0."Lvl" = 6 THEN T3."Code" 
            WHEN T0."Lvl" = 7 THEN T4."Code" 
            WHEN T0."Lvl" = 8 THEN T5."Code" 
            ELSE '' 
        END AS "Level3", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."Code" 
            WHEN T0."Lvl" = 5 THEN T1."Code" 
            WHEN T0."Lvl" = 6 THEN T2."Code" 
            WHEN T0."Lvl" = 7 THEN T3."Code" 
            WHEN T0."Lvl" = 8 THEN T4."Code" 
            ELSE '' 
        END AS "Level4", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."Code" 
            WHEN T0."Lvl" = 6 THEN T1."Code" 
            WHEN T0."Lvl" = 7 THEN T2."Code" 
            WHEN T0."Lvl" = 8 THEN T3."Code" 
            ELSE '' 
        END AS "Level5", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."Code" 
            WHEN T0."Lvl" = 7 THEN T1."Code" 
            WHEN T0."Lvl" = 8 THEN T2."Code" 
            ELSE '' 
        END AS "Level6", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T1."Code" 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            ELSE '' 
        END AS "Level8", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."Code" 
            WHEN T0."Lvl" = 2 THEN T1."Code" 
            WHEN T0."Lvl" = 3 THEN T2."Code" 
            WHEN T0."Lvl" = 4 THEN T3."Code" 
            WHEN T0."Lvl" = 5 THEN T4."Code" 
            WHEN T0."Lvl" = 6 THEN T5."Code" 
            WHEN T0."Lvl" = 7 THEN T6."Code" 
            WHEN T0."Lvl" = 8 THEN T7."Code" 
            ELSE '' 
        END AS "Level1AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."Code" 
            WHEN T0."Lvl" = 3 THEN T1."Code" 
            WHEN T0."Lvl" = 4 THEN T2."Code" 
            WHEN T0."Lvl" = 5 THEN T3."Code" 
            WHEN T0."Lvl" = 6 THEN T4."Code" 
            WHEN T0."Lvl" = 7 THEN T5."Code" 
            WHEN T0."Lvl" = 8 THEN T6."Code" 
            ELSE '' 
        END AS "Level2AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."Code" 
            WHEN T0."Lvl" = 4 THEN T1."Code" 
            WHEN T0."Lvl" = 5 THEN T2."Code" 
            WHEN T0."Lvl" = 6 THEN T3."Code" 
            WHEN T0."Lvl" = 7 THEN T4."Code" 
            WHEN T0."Lvl" = 8 THEN T5."Code" 
            ELSE '' 
        END AS "Level3AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."Code" 
            WHEN T0."Lvl" = 5 THEN T1."Code" 
            WHEN T0."Lvl" = 6 THEN T2."Code" 
            WHEN T0."Lvl" = 7 THEN T3."Code" 
            WHEN T0."Lvl" = 8 THEN T4."Code" 
            ELSE '' 
        END AS "Level4AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."Code" 
            WHEN T0."Lvl" = 6 THEN T1."Code" 
            WHEN T0."Lvl" = 7 THEN T2."Code" 
            WHEN T0."Lvl" = 8 THEN T3."Code" 
            ELSE '' 
        END AS "Level5AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."Code" 
            WHEN T0."Lvl" = 7 THEN T1."Code" 
            WHEN T0."Lvl" = 8 THEN T2."Code" 
            ELSE '' 
        END AS "Level6AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T1."Code" 
            ELSE '' 
        END AS "Level7", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            WHEN T0."Lvl" = 8 THEN T0."Code" 
            ELSE '' 
        END AS "Level8AccntntCod", 
        CASE 
            WHEN T0."Lvl" = 1 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 2 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 3 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T5."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T6."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T7."FrgnName" 
            ELSE '' 
        END AS "Level1FrgnName", 
        CASE 
            WHEN T0."Lvl" = 2 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 3 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T5."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T6."FrgnName" 
            ELSE '' 
        END AS "Level2FrgnName", 
        CASE 
            WHEN T0."Lvl" = 3 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 4 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T4."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T5."FrgnName" 
            ELSE '' 
        END AS "Level3FrgnName", 
        CASE 
            WHEN T0."Lvl" = 4 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 5 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T3."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T4."FrgnName" 
            ELSE '' 
        END AS "Level4FrgnName", 
        CASE 
            WHEN T0."Lvl" = 5 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 6 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T2."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T3."FrgnName" 
            ELSE '' 
        END AS "Level5FrgnName", 
        CASE 
            WHEN T0."Lvl" = 6 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 7 THEN T1."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T2."FrgnName" 
            ELSE '' 
        END AS "Level6FrgnName", 
        CASE 
            WHEN T0."Lvl" = 7 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T1."FrgnName" 
            ELSE '' 
        END AS "Level7FrgnName", 
        CASE 
            WHEN T0."Lvl" = 8 THEN T0."FrgnName" 
            WHEN T0."Lvl" = 8 THEN T0."FrgnName" 
            ELSE '' 
        END AS "Level8FrgnName", T0."Sort", CAST(T0."FatherNum" AS nvarchar(32)) AS "FatherId", 
        CAST(T0."Code" AS nvarchar(32)) AS "Id", T0."FormatCode", T0."AcctCodeDisp", T0."Segment_0", T0."Segment_1", 
        T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", T0."Segment_7", 
        T0."Segment_8", T0."Segment_9", T0."ActCurr", T0."GroupMask", T0."DocType", T0."AccntntCod", T0."FrgnName" 
    	FROM "CRSP_TemplateAccount" T0 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T1 ON T0."FatherNum" = T1."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T2 ON T1."FatherNum" = T2."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T3 ON T2."FatherNum" = T3."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T4 ON T3."FatherNum" = T4."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T5 ON T4."FatherNum" = T5."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T6 ON T5."FatherNum" = T6."Code" 
        LEFT OUTER JOIN "CRSP_TemplateAccount" T7 ON T6."FatherNum" = T7."Code" 
    	WHERE :Plan <> '@@Account'
    );
    /* This is important to know which Group Masks belong to Balance and which to Profit and Loss 
 It can change for different localizations */
    /* Here the actual AccountCalc Query starts and the account preparation ends*/
    /*
     Distribution Rule (OOCR, OCR1) 
 * Temp. Table with distribution rules, created with ValidFrom and ValidTo
 * Desc: If only 1 Rule per Date oder the last one, the ValidTo Column ist ToDay+99Years 
 */
    insert into "CRSP_Plan" 
    (
    	SELECT T1.*, (SELECT MAX("Lvl") FROM "CRSP_Plan0") AS "MaxLvl", T21."Description" AS "Desc1", T22."Description" AS "Desc2", 
        T23."Description" AS "Desc3", T24."Description" AS "Desc4", T25."Description" AS "Desc5", 
        T26."Description" AS "Desc6", T27."Description" AS "Desc7", T28."Description" AS "Desc8", 
        T1."Description" AS "DescAll", 
        CASE 
            WHEN (select :Plan from dummy) = '@@Account' THEN T1."AcctCode" 
            ELSE T1."Id"
        END AS "Code" 
    	FROM "CRSP_Plan0" T1
        LEFT OUTER JOIN "CRSP_AcctLang" T21 ON T1."Level1" = T21."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T22 ON T1."Level2" = T22."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T23 ON T1."Level3" = T23."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T24 ON T1."Level4" = T24."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T25 ON T1."Level5" = T25."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T26 ON T1."Level6" = T26."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T27 ON T1."Level7" = T27."Code" 
        LEFT OUTER JOIN "CRSP_AcctLang" T28 ON T1."Level8" = T28."Code" 
    	ORDER BY T1."Sort"
    );

    /* Amount Brought Forward */
    
    INSERT INTO "CRSP_OCR1DistRule"
    (
    	SELECT T0."OcrCode", T0."PrcCode", 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."OcrTotal" 
        END AS "OcrTotal", 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."PrcAmount" 
        END AS "PrcAmount", 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."PrcAmount" 
        END / 
        CASE 
            WHEN T0."OcrTotal" = 0 THEN 1 
            ELSE T0."OcrTotal" 
        END AS "OcrFactor", T0."Direct", T0."ValidFrom", IFNULL
        (
        	(
        	SELECT ADD_DAYS(T1."ValidTo", -1) FROM
        	(
        		SELECT TOP 1 U0."OcrCode", U0."ValidFrom", MIN(U1."ValidFrom") AS "ValidTo"
        		FROM OCR1 U0 INNER JOIN OCR1 U1 ON U1."OcrCode" = U0."OcrCode" AND U1."ValidFrom" > U0."ValidFrom"
        		GROUP BY U0."OcrCode", U0."ValidFrom"
        	) T1 
        	WHERE T1."OcrCode" = T0."OcrCode" AND T1."ValidTo" > T0."ValidFrom" 
        	), ADD_YEARS(NOW(), 99)
        ) AS "ValidTo" 
        FROM OCR1 T0 
        ORDER BY T0."OcrCode", T0."ValidFrom", T0."PrcCode"
	);

	call CRSP_TrialBalanceByCostCenter_BR_enUS_cont(:Currency, :IgnoreAdj, :AddVoucher, :DateType,
				:FromDate, :ToDate, :DimCode, :BroughtForward, :EndYear);
	
	SELECT IFNULL(T1."Typ", 'Acct') AS "Typ", IFNULL(T1."TransId", 0) AS "TransId", 
        IFNULL(T1."Line_ID", -1) AS "Line_ID", T0."Lvl", IFNULL(T0."AcctCode", '') AS "AcctCode", T0."Description", 
        T0."Postable", T0."Variator", T0."Liq", T0."Level1", T0."Level2", T0."Level3", T0."Level4", T0."Level5", 
        T0."Level6", T0."Level7", T0."Level8", T0."Level1AccntntCod", T0."Level2AccntntCod", T0."Level3AccntntCod", 
        T0."Level4AccntntCod", T0."Level5AccntntCod", T0."Level6AccntntCod", T0."Level7AccntntCod", 
        T0."Level8AccntntCod", T0."Level1FrgnName", T0."Level2FrgnName", T0."Level3FrgnName", T0."Level4FrgnName", 
        T0."Level5FrgnName", T0."Level6FrgnName", T0."Level7FrgnName", T0."Level8FrgnName", T0."Sort", 
        IFNULL(T0."FatherId", '') AS "FatherId", T0."Id", T0."MaxLvl", IFNULL(T0."Desc1", '') AS "Desc1", 
        IFNULL(T0."Desc2", '') AS "Desc2", IFNULL(T0."Desc3", '') AS "Desc3", IFNULL(T0."Desc4", '') AS "Desc4", 
        IFNULL(T0."Desc5", '') AS "Desc5", IFNULL(T0."Desc6", '') AS "Desc6", IFNULL(T0."Desc7", '') AS "Desc7", 
        IFNULL(T0."Desc8", '') AS "Desc8", IFNULL(T0."DescAll", '') AS "DescAll", T1."RefDate", 
        IFNULL(T1."FinancYear", :FinancYear) AS "FinancYear", IFNULL(T1."PrcCode", '') AS "PrcCode", 
        IFNULL(T1."OcrCode", '') AS "OcrCode", IFNULL(T1."PrjCode", '') AS "PrjCode", 
        IFNULL(T1."Credit", 0) AS "Credit", IFNULL(T1."CreditPreviousYear", 0) AS "CreditPreviousYear", 
        IFNULL(T1."Debit", 0) AS "Debit", IFNULL(T1."DebitPreviousYear", 0) AS "DebitPreviousYear", 
        IFNULL(T1."CreditBudget", 0) AS "CreditBudget", IFNULL(T1."DebitBudget", 0) AS "DebitBudget", 
        IFNULL(T1."CreditBudgetPrevYear", 0) AS "CreditBudgetPrevYear", 
        IFNULL(T1."DebitBudgetPrevYear", 0) AS "DebitBudgetPrevYear", 
        IFNULL(T1."CreditActualMonth", 0) AS "CreditActualMonth", 
        IFNULL(T1."CreditMonthPreviousYear", 0) AS "CreditMonthPreviousYear", 
        IFNULL(T1."DebitActualMonth", 0) AS "DebitActualMonth", 
        IFNULL(T1."DebitMonthPreviousYear", 0) AS "DebitMonthPreviousYear", 
        IFNULL(T1."CreditActualMonthBudget", 0) AS "CreditActualMonthBudget", 
        IFNULL(T1."DebitActualMonthBudget", 0) AS "DebitActualMonthBudget", 
        IFNULL(T1."CreditFinancYear", 0) AS "CreditFinancYear", IFNULL(T1."DebitFinancYear", 0) AS "DebitFinancYear", 
        IFNULL(T1."CreditFinancYearBudget", 0) AS "CreditFinancYearBudget", 
        IFNULL(T1."DebitFinancYearBudget", 0) AS "DebitFinancYearBudget", 
        IFNULL(T1."CreditPrevFinancYear", 0) AS "CreditPrevFinancYear", 
        IFNULL(T1."DebitPrevFinancYear", 0) AS "DebitPrevFinancYear", IFNULL(T1."BFDebit", 0) AS "BFDebit", 
        IFNULL(T1."BFCredit", 0) AS "BFCredit", IFNULL(T1."OBDebit", 0) AS "OBDebit", 
        IFNULL(T1."OBCredit", 0) AS "OBCredit", IFNULL(T1."BFOBDebit", 0) AS "BFOBDebit", 
        IFNULL(T1."BFOBCredit", 0) AS "BFOBCredit", IFNULL(T6."OcrName", '') AS "OcrName", 
        IFNULL(T7."OcrName", '') AS "PrcName", IFNULL(T8."PrjName", '') AS "PrjName", 
        IFNULL(T9."GrpCode", '') AS "PrcGrpCode", T3."AcctName", T3."CurrTotal", T3."Finanse", T3."Budget", 
        T3."Frozen", T3."Levels", IFNULL(T3."ExportCode", '') AS "ExportCode", T3."GrpLine", T0."DocType", 
        T3."ActType", IFNULL(T3."OverCode", '') AS "OverCode", IFNULL(T3."Project", '') AS "OACTProject", 
        IFNULL(T0."FormatCode", '') AS "FormatCode", IFNULL(T0."AcctCodeDisp", '') AS "AcctCodeDisp", 
        IFNULL(T0."ActCurr", '') AS "ActCurr", IFNULL(T0."GroupMask", 0) AS "GroupMask", T0."Segment_0", 
        T0."Segment_1", T0."Segment_2", T0."Segment_3", T0."Segment_4", T0."Segment_5", T0."Segment_6", 
        T0."Segment_7", T0."Segment_8", T0."Segment_9", IFNULL(T0."AccntntCod", '') AS "AccntntCod", 
        IFNULL(T0."FrgnName", '') AS "FrgnName" 
    FROM "CRSP_Plan" T0 
        LEFT OUTER JOIN CRSP_TEMPRES T1 ON T0."AcctCode" = T1."Account" 
        LEFT OUTER JOIN OACT T3 ON T0."AcctCode" = T3."AcctCode" 
        LEFT OUTER JOIN OOCR T6 ON T1."OcrCode" = T6."OcrCode" 
        LEFT OUTER JOIN OOCR T7 ON T1."PrcCode" = T7."OcrCode" 
        LEFT OUTER JOIN OPRJ T8 ON T1."PrjCode" = T8."PrjCode" 
        LEFT OUTER JOIN OPRC T9 ON T1."PrcCode" = T9."PrcCode" 
    ORDER BY T0."Sort";
	
    /* Clean up */
    /*LEFT OUTER JOIN OBPL T10 ON T1.BPLId = T10.BPLId*/
    /* External Code */
    /* Foreign Name */
    /*,IFNULL(T1.BPLId,'') As BPLId*/
    /*,IFNULL(T10.BPLName,'') As BPLName*/
    DELETE FROM "CRSP_TEMPJDT1";
    DELETE FROM "CRSP_TEMPRES";
    DELETE FROM "CRSP_OCR1DistRule";
    DELETE FROM "CRSP_Plan";
    DELETE FROM "CRSP_TemplateAccount";
    DELETE FROM "CRSP_Plan0";
    DELETE FROM "CRSP_AcctLang";
END;

-- B1 DEPENDS: AFTER:SP:DWZ_CREATE_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE DWZ_CM (
IN pagingID NVARCHAR(100),
OUT dunning_cm_out DWZ_REPORT_OUT
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
docDate NVARCHAR(20);
dueDate NVARCHAR(20);
dunningDate NVARCHAR(20);
crdtNBased NVARCHAR(1);
payNoBased NVARCHAR(1);
UseBranches NVARCHAR(1);
BEGIN 

SELECT "Value" INTO crdtNBased FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'CrdtNBased';
SELECT "Value" INTO payNoBased FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'PayNoBased';

SELECT "Value" INTO docDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'docDate' ;
SELECT "Value" INTO dueDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dueDate' ;
SELECT "Value" INTO dunningDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dunningDate' ;

SELECT "Value" INTO UseBranches FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'UseBranches' ;

dunning_cm =

SELECT

T0."CardCode" AS "CardCode",
T2."CardName" AS "CardName",
T3."TermCode" AS "DunningCode",
T0."DocCur" AS "DocCur",
0 AS "DunnLevel", 
--TO_NVARCHAR ('INV CM') AS "ObjType",
T0."ObjType" AS "ObjType", 
T0."DocNum" AS "DocNum",
cast(T1."InstlmntID" as INTEGER) AS "InstlmntID",
T1."DueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate",
T1."InsTotal" AS "DocAmountLC",
T1."InsTotalFC" AS "DocAmountFC",
cast(T1."InsTotal" - T1."PaidToDate" as DECIMAL(21,6)) AS "OpenAmountLC",
cast(T1."InsTotalFC" - T1."PaidFC" as DECIMAL(21,6)) AS "OpenAmountFC",
0 AS "InterestDays",
0 AS "Interest",
0 AS "InterestAmountLC",
0 AS "InterestAmountFC",
T3."GrpMethod" AS "GrpMethod", 0 AS "FeeLC",  0 AS "FeeFC" ,  T3."AutoPost" AS "AutoPost", cast(0 as SMALLINT) AS "YearDays", 0 AS "YearlyRate",  
T3."LetterFrmt" AS "LetterFrmt", 0 AS "OrigMinBalance", 0 AS "MinBalance",  T0."DocEntry" AS "DocEntry", 
T0."DocRate" AS "DocRate", T3."FeeCurr" AS "FeeCurr" , T3."TotalFee" AS "OrigFee" , T3."BalCurr" AS "MinBalCurr", 'N' AS "LevelUpdated", 
T0."CardCode" AS "BpCode2", 'C' AS "BpType", cast('' as nvarchar(100)) AS "CardName2", T0."Comments"AS "Comment",
T0."BPLId" AS "BPLId"

FROM "OINV" T0 
INNER JOIN "INV6" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN "TMP_DWZ_CRD" T4 ON T4."CardCode" = T0."CardCode"
INNER JOIN "OCRD" T2 ON T4."CardCode" = T2."CardCode"
INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND T0."CANCELED" = ( 'N' ) 
AND T1."Status" = ( 'O' ) 
AND T1."DunWizBlck" = ( 'N' ) 
AND T0."BlockDunn" = ( 'N' ) 
AND T0."TransId" <> ( 0 ) 
AND ( T1."InsTotal" < ( 0 ) 
	OR T1."InsTotalFC" < ( 0 ) ) 
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))


UNION ALL
--CSI
SELECT

T0."CardCode" AS "CardCode",
T2."CardName" AS "CardName",
T3."TermCode" AS "DunningCode",
T0."DocCur" AS "DocCur",
0 AS "DunnLevel", 
--TO_NVARCHAR ('INV CM') AS "ObjType",
T0."ObjType" AS "ObjType", 
T0."DocNum" AS "DocNum",
cast(T1."InstlmntID" as INTEGER) AS "InstlmntID",
T1."DueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate",
T1."InsTotal" AS "DocAmountLC",
T1."InsTotalFC" AS "DocAmountFC",
cast(T1."InsTotal" - T1."PaidToDate" as DECIMAL(21,6)) AS "OpenAmountLC",
cast(T1."InsTotalFC" - T1."PaidFC" as DECIMAL(21,6)) AS "OpenAmountFC",
0 AS "InterestDays",
0 AS "Interest",
0 AS "InterestAmountLC",
0 AS "InterestAmountFC",
T3."GrpMethod" AS "GrpMethod", 0 AS "FeeLC",  0 AS "FeeFC" ,  T3."AutoPost" AS "AutoPost",cast(0 as SMALLINT) AS "YearDays", 0 AS "YearlyRate",  
T3."LetterFrmt" AS "LetterFrmt", 0 AS "OrigMinBalance", 0 AS "MinBalance",  T0."DocEntry" AS "DocEntry",
T0."DocRate" AS "DocRate", T3."FeeCurr" AS "FeeCurr" , T3."TotalFee" AS "OrigFee" , T3."BalCurr"  AS "MinBalCurr", 'N' AS "LevelUpdated",
T0."CardCode" AS "BpCode2", 'C' AS "BpType",cast('' as nvarchar(100)) AS "CardName2", T0."Comments"AS "Comment",
T0."BPLId" AS "BPLId"

FROM "OCSI" T0 
INNER JOIN "CSI6" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN "TMP_DWZ_CRD" T4 ON T4."CardCode" = T0."CardCode"
INNER JOIN "OCRD" T2 ON T4."CardCode" = T2."CardCode"
INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND T0."CANCELED" = ( 'N' ) 
AND T1."Status" = ( 'O' ) 
AND T1."DunWizBlck" = ( 'N' ) 
AND T0."BlockDunn" = ( 'N' ) 
AND T0."TransId" <> ( 0 ) 
AND ( T1."InsTotal" < ( 0 ) 
	OR T1."InsTotalFC" < ( 0 ) ) 
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))


UNION ALL 
--DPI
SELECT

T0."CardCode" AS "CardCode",
T2."CardName" AS "CardName",
T3."TermCode" AS "DunningCode",
T0."DocCur" AS "DocCur",
0 AS "DunnLevel",
--TO_NVARCHAR ('INV CM') AS "ObjType",
T0."ObjType" AS "ObjType", 
T0."DocNum" AS "DocNum",
cast(T1."InstlmntID" as INTEGER) AS "InstlmntID",
T1."DueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate", 
-T1."InsTotal" AS "DocAmountLC",
-T1."InsTotalFC" AS "DocAmountFC",
cast(-T1."InsTotal" + T1."PaidToDate" as DECIMAL(21,6)) AS "OpenAmountLC",
cast(-T1."InsTotalFC" + T1."PaidFC" as DECIMAL(21,6)) AS "OpenAmountFC",
0 AS "InterestDays",
0 AS "Interest",
0 AS "InterestAmountLC",
0 AS "InterestAmountFC",
T3."GrpMethod" AS "GrpMethod", 0 AS "Fee",  0 AS "FeeFC" ,  T3."AutoPost" AS "AutoPost", cast(0 as SMALLINT)AS "YearDays", 0 AS "YearlyRate", 
T3."LetterFrmt" AS "LetterFrmt",
0 AS "OrigMinBalance", 0 AS "MinBalance",  T0."DocEntry",
T0."DocRate" AS "DocRate", T3."FeeCurr" AS "FeeCurr" , T3."TotalFee" AS "OrigFee" , T3."BalCurr"  AS "MinBalCurr", 'N' AS "LevelUpdated",
T0."CardCode" AS "BpCode2", 'C' AS "BpType", cast('' as nvarchar(100)) AS "CardName2", T0."Comments"AS "Comment",
T0."BPLId" AS "BPLId"
 
FROM "ODPI" T0 
INNER JOIN "DPI6" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN "TMP_DWZ_CRD" T4 ON T4."CardCode" = T0."CardCode"
INNER JOIN "OCRD" T2 ON T4."CardCode" = T2."CardCode"
INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND T0."CANCELED" = ( 'N' ) 
AND T1."Status" = ( 'O' ) 
AND T1."DunWizBlck" = ( 'N' ) 
AND T0."BlockDunn" = ( 'N' ) 
AND T0."TransId" <> ( 0 ) 
AND ( T1."InsTotal" < ( 0 ) 
	OR T1."InsTotalFC" < ( 0 ) ) 
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))
;	
 
dunning_cm_RIN =
--RIN

SELECT

T0."CardCode" AS "CardCode",
T2."CardName" AS "CardName",
T3."TermCode" AS "DunningCode",
T0."DocCur" AS "DocCur",
0 AS "DunnLevel",
--TO_NVARCHAR ('INV CM') AS "ObjType",
T0."ObjType" AS "ObjType", 
T0."DocNum" AS "DocNum",
cast(T1."InstlmntID" as INTEGER) AS "InstlmntID",
T1."DueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate", 
-T1."InsTotal" AS "DocAmountLC",
-T1."InsTotalFC" AS "DocAmountFC",
cast(-T1."InsTotal" +T1."PaidToDate" as DECIMAL(21,6)) AS "OpenAmountLC",
cast(-T1."InsTotalFC" +T1."PaidFC" as DECIMAL(21,6)) AS "OpenAmountFC",
0 AS "InterestDays",
0 AS "Interest",
0 AS "InterestAmountLC",
0 AS "InterestAmountFC",
T3."GrpMethod" AS "GrpMethod", 0 AS "Fee",  0 AS "FeeFC" ,  T3."AutoPost" AS "AutoPost",cast(0 as SMALLINT) AS "YearDays", 0 AS "YearlyRate", 
T3."LetterFrmt"  AS "LetterFrmt", 0 AS "OrigMinBalance",0 AS "MinBalance",  T0."DocEntry",
T0."DocRate" AS "DocRate", T3."FeeCurr" AS "FeeCurr" , T3."TotalFee" AS "OrigFee" , T3."BalCurr"  AS "MinBalCurr", 'N' AS "LevelUpdated",
T0."CardCode" AS "BpCode2", 'C' AS "BpType", cast('' as nvarchar(100)) AS "CardName2", T0."Comments"AS "Comment",
T0."BPLId" AS "BPLId"

FROM "ORIN" T0 
INNER JOIN "RIN6" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN "TMP_DWZ_CRD" T4 ON T4."CardCode" = T0."CardCode"
INNER JOIN "OCRD" T2 ON T4."CardCode" = T2."CardCode"
INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND T0."CANCELED" = ( 'N' ) 
AND T1."Status" = ( 'O' ) 
AND T1."DunWizBlck" = ( 'N' ) 
AND T0."BlockDunn" = ( 'N' ) 
AND T0."TransId" <> ( 0 ) 
AND ( T1."InsTotal" > ( 0 ) 
	OR T1."InsTotalFC" > ( 0 ) ) 
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))
;

dunning_cm_RCT =
--RCT

SELECT

T1."ShortName" AS "CardCode",
T3."CardName" AS "CardName",
T4."TermCode" AS "DunningCode",
T0."DocCurr" AS "DocCur",
--'RC' AS "ObjType",
0 AS "DunnLevel",
'24' AS "ObjType",
T0."DocNum" AS "DocNum",
T1."Line_ID" AS "InstlmntID",
T0."DocDueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate", 
-T0."NoDocSum" AS "DocAmountLC", 
-T0."NoDocSumFC" AS "DocAmountFC", 
-T0."OpenBal" AS "OpenAmountLC",
-T0."OpenBalFc" AS "OpenAmountFC",
0 AS "InterestDays",
0 AS "Interest",
0 AS "InterestAmountLC",
0 AS "InterestAmountFC",
T4."GrpMethod" AS "GrpMethod", 0 AS "Fee",  0 AS "FeeFC" ,  T4."AutoPost" AS "AutoPost",cast(0 as SMALLINT) AS "YearDays", 0 AS "YearlyRate", 
T4."LetterFrmt"  AS "LetterFrmt", 0 AS "OrigMinBalance", 0 AS "MinBalance", T0."DocEntry",
T0."DocRate" AS "DocRate", T4."FeeCurr" AS "FeeCurr" , T4."TotalFee" AS "OrigFee" , T4."BalCurr"  AS "MinBalCurr", 'N' AS "LevelUpdated",
T0."CardCode" AS "BpCode2", 'C' AS "BpType", cast('' as nvarchar(100)) AS "CardName2", T0."Comments"AS "Comment",
T0."BPLId" AS "BPLId"

FROM "ORCT" T0 
INNER JOIN "JDT1" T1 ON T1."TransId" = T0."TransId" AND T1."TransType" = '24' 
INNER JOIN "OJDT" T2 ON T2."TransId" = T1."TransId" 
INNER JOIN "TMP_DWZ_CRD" T5 ON T5."CardCode" = T1."ShortName"
INNER JOIN "OCRD" T3 ON T5."CardCode" = T3."CardCode"
INNER JOIN "ODUT" T4 ON T4."TermCode" = T3."DunTerm" 
WHERE
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND (T0."NoDocSum" <> ( 0 ) OR T0."NoDocSumFC" <> ( 0 ) )
AND T0."Canceled" = ( 'N' ) 
AND ( ( T0."OpenBal" <> ( 0 ) 
		AND T0."OpenBal" IS NOT NULL ) 
	OR ( T0."OpenBalFc" <> ( 0 ) 
		AND T0."OpenBalFc" IS NOT NULL ) ) 
AND T0."WizDunBlck" = ( 'N' )
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))
;

IF :crdtNBased = 'Y' THEN
	IF :payNoBased = 'N' THEN dunning_cm_out = SELECT * FROM :dunning_cm UNION ALL SELECT * FROM :dunning_cm_RIN ; END IF ;
	IF :payNoBased = 'Y' THEN dunning_cm_out = SELECT * FROM :dunning_cm UNION ALL SELECT * FROM :dunning_cm_RIN UNION ALL SELECT * FROM :dunning_cm_RCT ; END IF ;
ELSE
	IF :payNoBased = 'N' THEN dunning_cm_out = SELECT * FROM :dunning_cm ; END IF ;
	IF :payNoBased = 'Y' THEN dunning_cm_out = SELECT * FROM :dunning_cm UNION ALL SELECT * FROM :dunning_cm_RCT ; END IF ;
END IF;

END;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START

CREATE PROCEDURE DWZ_CREATE_OBJECTS ()
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
cnt int;
BEGIN
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'DWZ_REPORT_OUT' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TYPE DWZ_REPORT_OUT CASCADE');
	end if;
	
	EXEC('
		CREATE TYPE DWZ_REPORT_OUT AS TABLE(
			"CardCode" NVARCHAR(15),"CardName" NVARCHAR(200),"DunningCode" NVARCHAR(25), "DocCur" NVARCHAR(3), "DunnLevel" INTEGER,"ObjType" NVARCHAR(20),"DocNum" INTEGER,"InstlmntID" INTEGER,
			"DueDate" TIMESTAMP,"LastLevelUpdateDate" TIMESTAMP,"LastDunningDate" TIMESTAMP, "NewLvlUpdDate" TIMESTAMP,
			"DocAmountLC" DECIMAL(21,6),"DocAmountFC" DECIMAL(21,6),"OpenAmountLC" DECIMAL(21,6),"OpenAmountFC" DECIMAL(21,6),"InterestDays" INTEGER,"Interest" DECIMAL(21,6),"InterestAmountLC" DECIMAL(21,6), "InterestAmountFC" DECIMAL(21,6),
			"GrpMethod" NVARCHAR(1) , "FeeLC" DECIMAL(21,6), "FeeFC" DECIMAL(21,6), "AutoPost" NVARCHAR(1) , "YearDays" SMALLINT, "YearlyRate" DECIMAL(21,6), "LetterFrmt" NVARCHAR(8) ,
			"OrigMinBalance" DECIMAL(21,6), "MinBalance" DECIMAL(21,6), "DocEntry" INTEGER, "DocRate" DECIMAL(21,6), "FeeCurr" NVARCHAR(3), "OrigFee" DECIMAL(21,6), "MinBalCurr" NVARCHAR(3), "LevelUpdated" NVARCHAR(1), 	 
			"BpCode2" NVARCHAR(15) CS_STRING, "BpType" NVARCHAR(1) CS_FIXEDSTRING, "CardName2" NVARCHAR(200) CS_STRING,	 "Comment" NVARCHAR(254) CS_STRING, "BPLId" INTEGER)
	');
	
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'TMP_DWZ_OUT_LINEPROPERTY' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE TMP_DWZ_OUT_LINEPROPERTY CASCADE');
	end if;

	EXEC('
		CREATE GLOBAL TEMPORARY TABLE "TMP_DWZ_OUT_LINEPROPERTY" ( "CheckLine" NVARCHAR(1) CS_FIXEDSTRING,
	 "ExeChkLine" NVARCHAR(1) CS_FIXEDSTRING,
	 "RowId" INT CS_INT,
	 "CardCode" NVARCHAR(15) CS_STRING,
	 "LetterNum" INT CS_INT,
	 "DunnLevel" INT CS_INT,
	 "CardName" NVARCHAR(200) CS_STRING,
	 "DocCur" NVARCHAR(3) CS_STRING,
	 "ObjType" NVARCHAR(20) CS_STRING,
	 "DocNum" INT CS_INT,
	 "InstlmntID" INT CS_INT,
	 "DueDate" LONGDATE CS_LONGDATE,
	 "LastLevelUpdateDate" LONGDATE CS_LONGDATE,
	 "LastDunningDate" LONGDATE CS_LONGDATE,
	 "NewLvlUpdDate" LONGDATE CS_LONGDATE,
	 "DocAmountLC" NVARCHAR(40),
	 "DocAmountFC" NVARCHAR(40),
	 "OpenAmountLC" NVARCHAR(40),
	 "OpenAmountFC" NVARCHAR(40),
	 "InterestDays" INT CS_INT,
	 "Interest" DECIMAL(21,6),
	 "InterestAmountLC" NVARCHAR(40),
	 "InterestAmountFC" NVARCHAR(40),
	 "TotalInclAmountLC" NVARCHAR(40),
	 "TotalInclAmountFC" NVARCHAR(40),
	 "FeeLC" NVARCHAR(40),
	 "FeeFC" NVARCHAR(40),
	 "OverallTotalLC" NVARCHAR(40),
	 "OverallTotalFC" NVARCHAR(40),
	 "AutoPost" NVARCHAR(1) CS_FIXEDSTRING,
	 "LineProperty" INT CS_INT,
	 "YearDays" SMALLINT CS_INT,
	 "YearlyRate" DECIMAL(21,6),
	 "LetterFrmt" NVARCHAR(20) CS_STRING,
	 "OrigMinBalance" NVARCHAR(40),
	 "GrpMethod" NVARCHAR(1) CS_FIXEDSTRING,
	 "DocEntry" INT CS_INT,	 
	 "DocRate" NVARCHAR(40),
	 "FeeCurr" NVARCHAR(3),
	 "OrigFee" NVARCHAR(40),  
	 "MinBalCurr" NVARCHAR(3),
	 "LevelUpdated" NVARCHAR(1),
	 "DunAddr" NVARCHAR(254),
	 "DocText" NVARCHAR(254),
	 "DocAmountLCBackup"  DECIMAL(21,6),
	 "DocAmountFCBackup"  DECIMAL(21,6),
	 "OpenAmountLCBackup" DECIMAL(21,6),
	 "OpenAmountFCBackup" DECIMAL(21,6),
	 "InterestAmountLCBackup"  DECIMAL(21,6), 
	 "InterestAmountFCBackup"  DECIMAL(21,6),
	 "TotalInclAmountLCBackup" DECIMAL(21,6), 
	 "TotalInclAmountFCBackup" DECIMAL(21,6), 
	 "FeeLCBackup" DECIMAL(21,6),
	 "FeeFCBackup" DECIMAL(21,6),
	 "OverallTotalLCBackup" DECIMAL(21,6),
	 "OverallTotalFCBackup" DECIMAL(21,6),
	 "ParentId" INT CS_INT,
 	 "BpCode2" NVARCHAR(15),
	 "BpType" NVARCHAR(1) CS_FIXEDSTRING,
	 "CardName2" NVARCHAR(200) CS_STRING,
	 "Comment" NVARCHAR(254) CS_STRING,
	 "BPLId" INT CS_INT
	 ) 
	');
	
	SELECT COUNT(*) INTO cnt FROM "PUBLIC".TABLES WHERE TABLE_NAME = 'TMP_DWZ_CRD' AND SCHEMA_NAME = CURRENT_SCHEMA;
	if :cnt > 0 then
		exec ('DROP TABLE TMP_DWZ_CRD CASCADE');
	end if;

	EXEC('
		CREATE GLOBAL TEMPORARY TABLE "TMP_DWZ_CRD"
		(
			"CardCode" NVARCHAR(15)
		)
	');
		
END;

-- B1 DEPENDS: AFTER:SP:DWZ_GETTOTAL AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE DWZ_ENTRY (
in_nvc_pagingID NVARCHAR(100),
in_i_dataMgrFlag INTEGER -- 0 Drop, 1 Create, 2 Retrieve
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
loadType NVARCHAR(1);
v_tableName NVARCHAR(200);
cnt INTEGER;
V_SQL NVARCHAR(5000);
vMaxRowId INTEGER;
localCurrency NVARCHAR(3);
wizradId INTEGER;
ovrDueOnly NVARCHAR(1);
allowNegLt NVARCHAR(1);
dunningDate TIMESTAMP;
BEGIN 

--For HANA security issue call procedure "_TmSp_ValidateSpParam"
call _TmSp_ValidateSpParam(:in_nvc_pagingID);  
	
SELECT TO_TIMESTAMP("Value", 'YYYYMMDD') INTO dunningDate FROM "SPPP" WHERE "PagingID" = :in_nvc_pagingID AND "Name" = 'dunningDate';

v_tableName := UPPER('#TMP_' || :in_nvc_pagingID);

IF :in_i_dataMgrFlag = 1 OR :in_i_dataMgrFlag = 0 THEN
    select count (*) into cnt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = :v_tableName AND SCHEMA_NAME = CURRENT_SCHEMA;
    if :cnt > 0 then  EXEC ('drop table ' || :v_tableName);
	end if;
END IF;
    
IF :in_i_dataMgrFlag = 1 THEN
---------------------------Logic---------------------------------------
----------------Create table ' || :v_tableName || --------------------
EXEC 'CREATE LOCAL TEMPORARY ROW TABLE ' || :v_tableName || ' ( 
"CheckLine" NVARCHAR(1), "ExeChkLine" NVARCHAR(1),"RowId" INTEGER, 
"CardCode" NVARCHAR(15), "LetterNum" INTEGER, "DunnLevel" INTEGER, "CardName" NVARCHAR(200), "DocCur" NVARCHAR(3),
"ObjType" NVARCHAR(20),"DocNum" INTEGER,"InstlmntID" INTEGER,
"DueDate" TIMESTAMP,"LastLevelUpdateDate" TIMESTAMP,"LastDunningDate" TIMESTAMP, "NewLvlUpdDate" TIMESTAMP,
"DocAmountLC" NVARCHAR(40),"DocAmountFC" NVARCHAR(40),"OpenAmountLC" NVARCHAR(40),"OpenAmountFC" NVARCHAR(40),
"InterestDays" INTEGER,"Interest" DECIMAL(21,6),
"InterestAmountLC" NVARCHAR(40), "InterestAmountFC" NVARCHAR(40),  "TotalInclAmountLC" NVARCHAR(40), "TotalInclAmountFC" NVARCHAR(40), 
"FeeLC" NVARCHAR(40), "FeeFC" NVARCHAR(40), "OverallTotalLC" NVARCHAR(40), "OverallTotalFC" NVARCHAR(40), 
"AutoPost" NVARCHAR(1),
"LineProperty" INTEGER, "YearDays" SMALLINT, "YearlyRate" DECIMAL(21,6), "LetterFrmt" NVARCHAR(20), "MinBalance" DECIMAL(21,6), "GrpMethod" NVARCHAR(1), "DocEntry" INTEGER, 
"DocRate" NVARCHAR(40), "FeeCurr" NVARCHAR(3), "OrigFee" DECIMAL(21,6), "MinBalCurr" NVARCHAR(3),"LevelUpdated" NVARCHAR(1), "DunAddr" NVARCHAR(254), "DocText" NVARCHAR(254),
"DocAmountLCBackup" DECIMAL(21,6),"DocAmountFCBackup" DECIMAL(21,6),"OpenAmountLCBackup" DECIMAL(21,6),"OpenAmountFCBackup" DECIMAL(21,6),
"InterestAmountLCBackup" DECIMAL(21,6), "InterestAmountFCBackup" DECIMAL(21,6),  "TotalInclAmountLCBackup" DECIMAL(21,6), "TotalInclAmountFCBackup" DECIMAL(21,6), 
"FeeLCBackup" DECIMAL(21,6), "FeeFCBackup" DECIMAL(21,6), "OverallTotalLCBackup" DECIMAL(21,6), "OverallTotalFCBackup" DECIMAL(21,6),
"ParentId" INTEGER, "BpCode2" NVARCHAR(15), "BpType" NVARCHAR(1), "CardName2" NVARCHAR(200), "Comment" NVARCHAR(254), "BPLId" INTEGER
 ) ';
 
 END IF;
 
EXEC ('DELETE from ' || :v_tableName || ' where 1=1');

SELECT "Value" INTO loadType FROM "SPPP" WHERE "PagingID" = :in_nvc_pagingID AND "Name" = 'loadType';
SELECT TO_INT("Value") INTO wizradId FROM "SPPP" WHERE "PagingID" = :in_nvc_pagingID AND "Name" = 'wizardID';

IF :loadType = '2' THEN 
EXEC ('INSERT INTO ' || :v_tableName || ' SELECT "CheckLine" , "ExeChkLine", "RowId" , "CardCode" , "LetterNum" , "DunnLevel" , "CardName" , "DocCur" ,
"DocType" ,"DocNum" ,"InstlmntID" ,
"DueDate" ,"LastLvlDte" ,"LastDunDte" , "NewLvlDate" ,

"DocAmntLC","DocAmntFC","OpenAmtLC" ,"OpenAmtFC" ,
"IntrstDays" ,"IntrstPC" ,
"IntAmntLC" , "IntAmntFC" ,  "InclAmntLC" , "InclAmntFC" , 
"FeeLC" , "FeeFC" , "AllTotalLC" , "AllTotalFC" , 

"AutoPost" ,
"LineProp" , "YearDays" , "YearlyRate" , "LetterFrmt" , "MinBlan"  , "GrpMethod" , "DocEntry" , "DocRate", "FeeCurr", "OrigFee", "MinBalCurr", "LvlUpdated", "DunAddr", "DocText", 
"DocAmntLC" ,"DocAmntFC" ,"OpenAmtLC" ,"OpenAmtFC" ,
"IntAmntLC" , "IntAmntFC" ,  "InclAmntLC" , "InclAmntFC" , 
"FeeLC" , "FeeFC" , "AllTotalLC" , "AllTotalFC" , 
"ParentId",
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"

FROM  DWZ4 WHERE "WizardId" = ' || :wizradId ) ;

ELSE
    
IF :in_i_dataMgrFlag = 1 THEN
CALL DWZ_GETTOTAL(in_nvc_pagingID);
-- Tips: row_number () over (PARTITION BY "CardCode", "LineProperty" )  AS "LetterNum" -- calculate LetterNum
EXEC ( 'INSERT INTO ' || :v_tableName || ' SELECT "CheckLine", "ExeChkLine"  ,"RowId" ,"CardCode"  ,"LetterNum" ,"DunnLevel" ,"CardName"  ,"DocCur"  ,"ObjType"  ,"DocNum" ,"InstlmntID" ,"DueDate"  ,
"LastLevelUpdateDate"  ,"LastDunningDate"  ,"NewLvlUpdDate"  ,
"DocAmountLC" ,"DocAmountFC" ,"OpenAmountLC" ,"OpenAmountFC" ,
"InterestDays" ,"Interest"  ,
"InterestAmountLC" ,"InterestAmountFC" ,"TotalInclAmountLC" ,"TotalInclAmountFC" ,
"FeeLC" ,"FeeFC" ,"OverallTotalLC" ,"OverallTotalFC" ,
"AutoPost"  ,"LineProperty" ,"YearDays" ,"YearlyRate" ,"LetterFrmt"  ,"OrigMinBalance" ,"GrpMethod"  ,"DocEntry" ,	 "DocRate" ,"FeeCurr" ,"OrigFee" ,  "MinBalCurr" ,"LevelUpdated" ,"DunAddr" ,"DocText" ,
"DocAmountLCBackup"  ,"DocAmountFCBackup"  ,"OpenAmountLCBackup" ,"OpenAmountFCBackup" ,
"InterestAmountLCBackup"  , "InterestAmountFCBackup"  ,"TotalInclAmountLCBackup" , "TotalInclAmountFCBackup" , 
"FeeLCBackup" ,"FeeFCBackup" ,"OverallTotalLCBackup" ,"OverallTotalFCBackup" ,
"ParentId", 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"
FROM TMP_DWZ_OUT_LINEPROPERTY ' );
END IF;

END IF;
 
--EXEC (:V_SQL);
      
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE DWZ_EXECUTE ( 
IN entry NVARCHAR(1),
IN pagingId NVARCHAR(100),
IN dunDateChar	NVARCHAR(10),
IN wizardId INTEGER
)LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
tableName NVARCHAR(200);
V_SQL NVARCHAR(5000);
dunDate TIMESTAMP;
IsExists INTEGER;
recOffset INTEGER;
CURSOR dwz4Cursor FOR SELECT "WizardId", "RowId" FROM DWZ4 WHERE "WizardId"=:wizardId ORDER BY "RowId";
BEGIN 

--For HANA security issue call procedure "_TmSp_ValidateSpParam"
call _TmSp_ValidateSpParam(:entry);
call _TmSp_ValidateSpParam(:pagingId);
call _TmSp_ValidateSpParam(:dunDateChar);

tableName := UPPER('#TMP_' || :pagingId);
dunDate := TO_TIMESTAMP (:dunDateChar, 'YYYYMMDD');

IF :entry = 'L' THEN

-- lock invoice
--UPDATE "INV6" T0 SET T0."DunWizBlck"='Y' FROM "INV6" T0 INNER JOIN tmp_1000 T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE "CheckLine" = 'Y';
--EXEC (' UPDATE "INV6" T0 SET T0."DunWizBlck"=''Y'' FROM "INV6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE "CheckLine" = ''N'' ');

EXEC(' UPDATE "INV6" T0 SET T0."DunWizBlck"=''Y'' FROM "INV6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''13'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "DPI6" T0 SET T0."DunWizBlck"=''Y'' FROM "DPI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''203'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "RIN6" T0 SET T0."DunWizBlck"=''Y'' FROM "RIN6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''14'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "CSI6" T0 SET T0."DunWizBlck"=''Y'' FROM "CSI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''165'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "JDT1" T0 SET T0."DunWizBlck"=''Y'' FROM "JDT1" T0 INNER JOIN ' || :tableName || ' T1 ON T0."TransId" = T1."DocEntry" AND T0."Line_ID" = T1."InstlmntID" WHERE T1."ObjType" = ''30'' AND T1."CheckLine" = ''N'' ');

EXEC(' UPDATE "ORCT" T0 SET T0."WizDunBlck"=''Y'' FROM "ORCT" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" 
INNER JOIN "JDT1" T2 ON T2."TransId" = T0."TransId" AND T2."TransType" = ''24'' WHERE T2."Line_ID" = T1."InstlmntID" AND T1."CheckLine" = ''N'' ' );
-- VENDOR DOC
EXEC(' UPDATE "PCH6" T0 SET T0."DunWizBlck"=''Y'' FROM "PCH6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''18'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "DPO6" T0 SET T0."DunWizBlck"=''Y'' FROM "DPO6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''204'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "RPC6" T0 SET T0."DunWizBlck"=''Y'' FROM "RPC6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''19'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "CPI6" T0 SET T0."DunWizBlck"=''Y'' FROM "CPI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''163'' AND T1."CheckLine" = ''N'' ');

END IF;

IF :entry = 'U' THEN
-- UPDATE "DunnLevel" of INV6
--UPDATE "INV6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", 'N', TO_TIMESTAMP('20131108', 'YYYYMMDD'), T1."NewLvlUpdDate")
--FROM "INV6" T0 INNER JOIN tmp_1000 T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE "CheckLine" = 'Y';
--EXEC (' UPDATE "INV6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ' || :dunDate || ' , T1."NewLvlUpdDate")
--FROM "INV6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE "CheckLine" = ''Y'' ');

EXEC( ' UPDATE "INV6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "INV6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''13'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
EXEC( ' UPDATE "DPI6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "DPI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''203'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
EXEC( ' UPDATE "RIN6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "RIN6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''14'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
--EXEC( ' UPDATE "RCT6" T0 SET (T0."DunnLevel",T0."WizDunBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
--FROM "RCT6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''24'' AND T1."CheckLine" = ''N'' ' );
EXEC( ' UPDATE "CSI6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "CSI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''165'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
EXEC( ' UPDATE "JDT1" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "JDT1" T0 INNER JOIN ' || :tableName || ' T1 ON T0."TransId" = T1."DocEntry" AND T0."Line_ID" = T1."InstlmntID" WHERE T1."ObjType" = ''30'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
--VENDOR DOC
EXEC( ' UPDATE "PCH6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "PCH6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''18'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
EXEC( ' UPDATE "DPO6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "DPO6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''204'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
EXEC( ' UPDATE "RPC6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "RPC6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''19'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );
EXEC( ' UPDATE "CPI6" T0 SET (T0."DunnLevel",T0."DunWizBlck",T0."DunDate",T0."LvlUpdDate") = (T1."DunnLevel", ''N'', ''' || :dunDate || ''' ,  IFNULL (T1."NewLvlUpdDate",T0."LvlUpdDate") )
FROM "CPI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''163'' AND T1."CheckLine" = ''N'' AND T1."LevelUpdated" = ''Y'' ' );

END IF;

IF :entry = 'R' THEN
-- release invoice
-- EXEC(' UPDATE "INV6" T0 SET T0."DunWizBlck"=''N'' FROM "INV6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE "CheckLine" = ''N'' ');

EXEC(' UPDATE "INV6" T0 SET T0."DunWizBlck"=''N'' FROM "INV6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''13'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "DPI6" T0 SET T0."DunWizBlck"=''N'' FROM "DPI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''203'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "RIN6" T0 SET T0."DunWizBlck"=''N'' FROM "RIN6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''14'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "CSI6" T0 SET T0."DunWizBlck"=''N'' FROM "CSI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''165'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "JDT1" T0 SET T0."DunWizBlck"=''N'' FROM "JDT1" T0 INNER JOIN ' || :tableName || ' T1 ON T0."TransId" = T1."DocEntry" AND T0."Line_ID" = T1."InstlmntID" WHERE T1."ObjType" = ''30'' AND T1."CheckLine" = ''N'' ');

EXEC(' UPDATE "ORCT" T0 SET T0."WizDunBlck"=''N'' FROM "ORCT" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" 
INNER JOIN "JDT1" T2 ON T2."TransId" = T0."TransId" AND T2."TransType" = ''24'' WHERE T2."Line_ID" = T1."InstlmntID" AND T1."CheckLine" = ''N'' ' );
--VENDOR DOC
EXEC(' UPDATE "PCH6" T0 SET T0."DunWizBlck"=''N'' FROM "PCH6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''18'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "DPO6" T0 SET T0."DunWizBlck"=''N'' FROM "DPO6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''204'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "RPC6" T0 SET T0."DunWizBlck"=''N'' FROM "RPC6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''19'' AND T1."CheckLine" = ''N'' ');
EXEC(' UPDATE "CPI6" T0 SET T0."DunWizBlck"=''N'' FROM "CPI6" T0 INNER JOIN ' || :tableName || ' T1 ON T0."DocEntry" = T1."DocEntry" AND T0."InstlmntID" = T1."InstlmntID" WHERE T1."ObjType" = ''163'' AND T1."CheckLine" = ''N'' ');

END IF;

IF :entry = 'I' THEN
-- insert DWZ4
	SELECT COUNT(*) INTO IsExists FROM "DWZ4" WHERE "WizardId" = :wizardId;
	IF :IsExists = 0 THEN
		EXEC( ' INSERT INTO "DWZ4" ("WizardId" , "CheckLine" , "ExeChkLine" , "RowId" , "CardCode" , "LetterNum" , "DunnLevel" , "CardName" , "DocCur" , "DocType" , "DocNum" , "InstlmntID" , "DueDate" , "LastLvlDte" , "LastDunDte" , "NewLvlDate" , "DocAmntLC" , "DocAmntFC" , "OpenAmtLC" , "OpenAmtFC" , "IntrstDays" , "IntrstPC" , "IntAmntLC" , "IntAmntFC" , "InclAmntLC" , "InclAmntFC" , "FeeLC" , "FeeFC" , "AllTotalLC" , "AllTotalFC" , "AutoPost" , "LineProp" , "YearDays" , "YearlyRate" , "LetterFrmt" , "MinBlan" , "GrpMethod" , "DocEntry" , "DocRate" , "FeeCurr" , "OrigFee" , "MinBalCurr" , "LvlUpdated" , "DunAddr" , "DocText" , "ParentId", "BpCode2", "BpType", "CardName2", "Comment", "BPLId" ) 
		SELECT ' || :wizardId || ' ,
		"CheckLine" , "ExeChkLine" ,"RowId" , 
		"CardCode" , "LetterNum" , "DunnLevel" , "CardName" , "DocCur" ,
		"ObjType" ,"DocNum" ,"InstlmntID" ,
		"DueDate" ,"LastLevelUpdateDate" ,"LastDunningDate" , "NewLvlUpdDate" ,
		"DocAmountLCBackup" ,"DocAmountFCBackup" ,"OpenAmountLCBackup" ,"OpenAmountFCBackup" ,
		"InterestDays" ,"Interest" ,
		"InterestAmountLCBackup" , "InterestAmountFCBackup" ,  "TotalInclAmountLCBackup" , "TotalInclAmountFCBackup" , 
		"FeeLCBackup" , "FeeFCBackup" , "OverallTotalLCBackup" , "OverallTotalFCBackup" ,
		"AutoPost" ,
		"LineProperty" , "YearDays" , "YearlyRate" , "LetterFrmt" , "MinBalance"  , "GrpMethod" , "DocEntry" , 
		"DocRate" , "FeeCurr" , "OrigFee" , "MinBalCurr" ,"LevelUpdated" , "DunAddr" , "DocText" ,
		"ParentId", "BpCode2", "BpType", "CardName2", "Comment", "BPLId"
		FROM ' || :tableName || ' WHERE "CheckLine" = ''N'' ORDER BY "RowId"');
		
INSERT INTO DWZ2 
("WizardId" , "CardCode" , "LetterNum" , "TotalFee" , "FeeCurr" , "TtlopnIntr" , 
"EDunLevel" , "OpnIntrCrr" , "DocAbs" , "DocNum" , "InstlmntID" , "IntrstPC" , 
"IntrstAmnt" , "IntrstCurr" , "ChckLine" , "IntrstDays" , "DocType" , "DueDate" , 
"LetterLvl" , "OpenSum" , "OpenCurr" , "sumIntrClc" , "folioNum" , "LvlUpdated" , 
"TotalFeeFC" , "TotalFeeLC" , "TotalFeeSC" , "TtlopnInFC" , "TtlopnInSC" , "IntrAmtFC" , 
"IntrAmtSC" , "OpenSumFC" , "OpenSumSC" , "ExeChkLine" , "AutoPost" , "DocRate" , 
"UnpaidBoEV" , "BoENumber" , "BoEStatus" , "BoEDate" , "BoEKey", "BPType", "BPLId")
SELECT 
"WizardId", 
"CardCode", 
(SELECT "LetterNum" FROM DWZ4 WHERE "RowId" = T0."ParentId" AND  "WizardId" = :wizardId ) AS "LetterNum" , 
"FeeLC",
"FeeCurr",
"InclAmntLC",
"DunnLevel",
"DocCur",
"DocEntry",
"DocNum",
"InstlmntID",
"IntrstPC",
"IntAmntLC",
"DocCur",
"CheckLine",
"IntrstDays",
"DocType",
"DueDate",
"DunnLevel",
"OpenAmtLC",
"DocCur",
NULL,
NULL,
"LvlUpdated",
(SELECT "FeeFC" FROM DWZ4 WHERE "RowId" = T0."ParentId" AND  "WizardId" = :wizardId ) as "FeeFC",
(SELECT "FeeLC" FROM DWZ4 WHERE "RowId" = T0."ParentId" AND  "WizardId" = :wizardId ) as "FeeLC",
NULL,
"InclAmntFC",
NULL,
"IntAmntFC",
NULL,
"OpenAmtFC",
NULL,
"ExeChkLine",
(SELECT "AutoPost" FROM DWZ4 WHERE "RowId" = T0."ParentId" AND  "WizardId" = :wizardId ) as "AutoPost",
NULL,
NULL,
NULL,
NULL,
NULL,
NULL,
T0."BpType",
"BPLId"
FROM DWZ4 T0 WHERE "WizardId" = :wizardId AND "LineProp" = 3 order by "RowId";

	END IF;	
END IF;

IF :entry = 'E' THEN
-- Update DWZ4."ExeChkLine"
-- Need validation 'Update' here !
EXEC( ' UPDATE DWZ4 T0 SET T0."ExeChkLine" = ''Y'' FROM DWZ4 T0 INNER JOIN DWZ3 T1 ON T0."WizardId" = T1."WizardId" AND T0."CardCode" = T1."CardCode"
WHERE T0."WizardId" = ' || :wizardId || ' AND T1."LetterNum" = (SELECT "LetterNum"  FROM DWZ4 WHERE "WizardId" = T0."WizardId" AND "RowId" = T0."ParentId")');
END IF;

-- Fix the disorder of RowIds and ParentIds of DWZ4 due to discontinuous selection of records
recOffset:=1;
FOR e AS dwz4Cursor DO
	UPDATE DWZ4 SET "ParentId"=recOffset WHERE "WizardId"=e."WizardId" AND "ParentId"=e."RowId";
	UPDATE DWZ4 SET "RowId"=recOffset WHERE "WizardId"=e."WizardId" AND "RowId"=e."RowId";
	recOffset:=recOffset+1;
END FOR; 

END;

-- B1 DEPENDS: AFTER:SP:DWZ_INV AFTER:SP:DWZ_JE AFTER:SP:DWZ_CM AFTER:SP:DWZ_VENDOR_DOC AFTER:PT:PROCESS_END

CREATE PROCEDURE DWZ_GETTOTAL (
IN pagingID NVARCHAR(100)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
dspOpnItms NVARCHAR(1);
ovrDueOnly NVARCHAR(1);
allowNegLt NVARCHAR(1);
manualJEs NVARCHAR(1);
considerVendor NVARCHAR(1);
dunningDate TIMESTAMP;
foreignCurrNum INT;
priceDec SMALLINT;
directRate NVARCHAR(1);
mainCurncy NVARCHAR(3);
rowidx INT;
forCurrNum INT;
foreignCurrency NVARCHAR(1000);
forCurr NVARCHAR(3);
BEGIN 

SELECT "Value" INTO dspOpnItms FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'DspOpnItms';
SELECT "Value" INTO manualJEs FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'ManualJEs';
SELECT "Value" INTO considerVendor FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'ConsiderVendor';

SELECT "PriceDec" INTO priceDec FROM "OADM";
SELECT "DirectRate" INTO directRate FROM "OADM";
SELECT "MainCurncy" INTO mainCurncy FROM "OADM";
SELECT TO_TIMESTAMP("Value", 'YYYYMMDD') INTO dunningDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dunningDate';

UPDATE "SPPP" SET "Value"='' WHERE "PagingID" = :pagingID AND "Name" = 'dueDate' AND "Value" is null;

CALL DWZ_INV(pagingID, doc_out);
CALL DWZ_CM(pagingID, cm_out);

IF :manualJEs = 'Y' THEN 
	CALL DWZ_JE(pagingID, 'C',je_out); 
	customer_out = SELECT * FROM :doc_out 
		UNION ALL SELECT * FROM :je_out 
		UNION ALL SELECT * FROM :cm_out ;
ELSE
	customer_out = SELECT * FROM :doc_out 
		UNION ALL SELECT * FROM :cm_out ;
END IF ;

IF (:considerVendor = 'Y') THEN 
	CALL DWZ_VENDOR_DOC(pagingID, vendor_out);	
	primary_out = SELECT * FROM :customer_out UNION ALL SELECT * FROM :vendor_out;
ELSE
	primary_out = SELECT * FROM :customer_out;
END IF;

DELETE FROM TMP_DWZ_CRD;
DELETE FROM TMP_DWZ_OUT_LINEPROPERTY;

tmpresult1 = 
SELECT
"CardCode", "DunnLevel" ,"DunningCode", "CardName","DocCur", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate","LastLevelUpdateDate","LastDunningDate", "NewLvlUpdDate" ,
CASE WHEN "GrpMethod" IS NULL THEN NULL ELSE SUM("DocAmountLC") END AS "DocAmountLC" ,
CASE WHEN "GrpMethod" IS NULL THEN NULL ELSE SUM("DocAmountFC") END AS "DocAmountFC" ,
CASE WHEN "GrpMethod" IS NULL THEN NULL ELSE SUM("OpenAmountLC") END AS "OpenAmountLC" ,
CASE WHEN "GrpMethod" IS NULL THEN NULL ELSE SUM("OpenAmountFC") END AS "OpenAmountFC" ,
"InterestDays","Interest", 
CASE WHEN "GrpMethod" IS NULL THEN NULL ELSE SUM("InterestAmountLC") END AS "InterestAmountLC" ,
CASE WHEN "GrpMethod" IS NULL THEN NULL ELSE SUM("InterestAmountFC") END AS "InterestAmountFC" ,
"FeeLC" , "FeeFC" ,
	
(SELECT "AutoPost" FROM OCRD WHERE "CardCode" = T0."CardCode" ) AS"AutoPost",
CASE WHEN "GrpMethod" is null THEN 0 
WHEN "DueDate" is not null THEN 999 
WHEN "GrpMethod" = 'B' and "ObjType" is null and "DunnLevel" is null THEN 1
WHEN "GrpMethod" = 'L' and "ObjType" is null and "DunnLevel" is not null THEN 1 
-- If per Invoice in dunning term, CM type documents should in one letter
WHEN "GrpMethod" = 'I' 	THEN 
    (CASE WHEN SUM("DocAmountLC") >0 and "ObjType" is not null and "DueDate" is null THEN 1
		 WHEN SUM("DocAmountLC") <=0 and "ObjType" is null and "DunnLevel" is not null THEN 1
	 END)
END AS "LineProperty",
"YearDays", "YearlyRate", "LetterFrmt" , "OrigMinBalance", "MinBalance", 
"GrpMethod", "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBalCurr", "LevelUpdated", 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"

FROM :primary_out T0
GROUP BY
GROUPING SETS 
--BP layer , "LineProperty" =0
( ("CardCode","CardName"),
-- !!!"LetterFrmt", "MinBalance"
--Letter title layer , "LineProperty" =1
	--"GrpMethod" = 'B'
("CardCode","CardName", "DunningCode", "BPLId", "LetterFrmt", "OrigFee", "DocCur", "GrpMethod", "AutoPost"), 
	--"GrpMethod" = 'L'
("CardCode","CardName", "DunningCode", "LetterFrmt", "FeeCurr", "OrigFee", "MinBalCurr", "DocCur","GrpMethod" , "DunnLevel", "BPLId", "FeeLC","FeeFC", "AutoPost", "MinBalance"), 
	--"GrpMethod" = 'I'
("CardCode","CardName", "DunningCode", "LetterFrmt", "FeeCurr", "OrigFee", "MinBalCurr", "DocCur","GrpMethod" , "DunnLevel", "BPLId","FeeLC","FeeFC","ObjType", "DocNum", "InstlmntID", "AutoPost", "MinBalance", "BpType"),
--Transaction detail layer , "LineProperty" =999
("CardCode","CardName", "DunningCode", "LetterFrmt", "FeeCurr", "OrigFee", "MinBalCurr", "OrigMinBalance", "MinBalance", "DocCur", "DocRate", "YearDays", "YearlyRate", "GrpMethod" , "DunnLevel", "BPLId", "FeeLC","FeeFC", "ObjType", "DocNum","DocEntry", "InstlmntID","DueDate","LastLevelUpdateDate","LastDunningDate","NewLvlUpdDate" ,"LevelUpdated", "InterestDays", "Interest", "BpCode2", "BpType", "CardName2", "Comment", "BPLId") 
);

-- select * from :tmpresult1 ;

tmpresult2 =

SELECT 'N' AS "CheckLine" ,'N' AS "ExeChkLine",
row_number () over (order by "CardCode","LetterFrmt", "DocCur","BpType","DunnLevel","BPLId","ObjType" ,"DocNum" ,"InstlmntID" , "DueDate", "DocAmountLC", "DocAmountFC") AS "RowId" , 
"CardCode","DunningCode",
row_number () over (PARTITION BY "CardCode", "LineProperty" )  AS "LetterNum",
"DunnLevel","CardName","DocCur", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate","LastLevelUpdateDate","LastDunningDate", "NewLvlUpdDate", 
"DocAmountLC" ,"DocAmountFC" ,"OpenAmountLC" ,"OpenAmountFC" ,"InterestDays","Interest", "InterestAmountLC" ,"InterestAmountFC" ,
IFNULL ("OpenAmountLC",0) + IFNULL ("InterestAmountLC",0) AS "TotalInclAmountLC", IFNULL ("OpenAmountFC",0) + IFNULL ("InterestAmountFC",0) AS "TotalInclAmountFC" ,
"FeeLC" , "FeeFC" ,
0 AS "OverallTotalLC", 0 AS "OverallTotalFC",
"AutoPost","LineProperty", "YearDays" , "YearlyRate", "LetterFrmt" , 

MAP("GrpMethod", 'B', (SELECT "MinBalance" FROM ODUT WHERE "TermCode" = "DunningCode"), "OrigMinBalance" ) AS "OrigMinBalance", 
MAP("GrpMethod", 'B', 
	(ROUND (
CASE WHEN (SELECT "BalCurr" FROM ODUT WHERE "TermCode" = "DunningCode") = :mainCurncy THEN (SELECT "MinBalance" FROM ODUT WHERE "TermCode" = "DunningCode")
ELSE MAP (:directRate, 'Y', (SELECT "MinBalance" FROM ODUT WHERE "TermCode" = "DunningCode")* (SELECT "Rate" FROM ORTT WHERE "Currency" = (SELECT "BalCurr" FROM ODUT WHERE "TermCode" = "DunningCode") AND "RateDate" = :dunningDate ), 
(SELECT "MinBalance" FROM ODUT WHERE "TermCode" = "DunningCode") / (SELECT "Rate" FROM ORTT WHERE "Currency" = (SELECT "BalCurr" FROM ODUT WHERE "TermCode" = "DunningCode") AND "RateDate" = :dunningDate ))
END,:priceDec )), "MinBalance" ) AS"MinBalance", 

"GrpMethod", "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBalCurr", "LevelUpdated", NULL AS "ParentId", 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"

FROM :tmpresult1
WHERE "LineProperty" is not null
ORDER BY "CardCode", "LetterFrmt","DocCur","DunnLevel", "BPLId", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate", "DocAmountLC", "DocAmountFC" ;

-- select * from :tmpresult2 ;

tmpresult3 = 
SELECT "CheckLine", "ExeChkLine", "RowId", "CardCode", 
MAP ("LineProperty", 999, NULL, "DunningCode") AS "DunningCode",
"LetterNum", "DunnLevel", "CardName", "DocCur", "ObjType", "DocNum", "InstlmntID", "DueDate"
, "LastLevelUpdateDate", "LastDunningDate", "NewLvlUpdDate", "DocAmountLC" , "DocAmountFC" , "OpenAmountLC" , "OpenAmountFC" , 	
"InterestDays", "Interest" , "InterestAmountLC" , 	"InterestAmountFC" , 	"TotalInclAmountLC" , 	"TotalInclAmountFC" , 	

MAP("LineProperty", 1, 
MAP("GrpMethod", 'B', 
	MAP((SELECT "HiLtrFrmt" FROM ODUT WHERE "TermCode" = "DunningCode"), 'Y',
		--Use Fee of max level as letter fee if it's highest letter format
		(SELECT "FeeLC" FROM :tmpresult2 WHERE "RowId" = (select MAX("RowId") from :tmpresult2 where "CardCode" = T0."CardCode" AND "BpType" = 'C' GROUP BY "CardCode") ),
		--
		ROUND (
			MAP( (SELECT "FeeCurr" FROM ODUT WHERE "TermCode" = "DunningCode" ), :mainCurncy , (SELECT "TotalFee" FROM ODUT WHERE "TermCode" = "DunningCode" ) ,
				MAP (:directRate, 'Y', ((SELECT "TotalFee" FROM ODUT WHERE "TermCode" = "DunningCode" ) * (SELECT "Rate" FROM ORTT WHERE "Currency" = (SELECT "FeeCurr" FROM ODUT WHERE "TermCode" = "DunningCode" ) AND "RateDate" = :dunningDate )),  
					 ((SELECT "TotalFee" FROM ODUT WHERE "TermCode" = "DunningCode" ) / (SELECT "Rate" FROM ORTT WHERE "Currency" = (SELECT "FeeCurr" FROM ODUT WHERE "TermCode" = "DunningCode" ) AND "RateDate" = :dunningDate )))
				),:priceDec ) ) ,
	"FeeLC"
	)
,"FeeLC")	AS "FeeLC", 

"FeeFC" , 	
"OverallTotalLC" , 	 
"OpenAmountFC" + "InterestAmountFC" + "FeeFC" AS "OverallTotalFC" ,
"AutoPost"  , 	"LineProperty", "YearDays", "YearlyRate" , 	"LetterFrmt", "OrigMinBalance", "MinBalance" , "GrpMethod", "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBalCurr", "LevelUpdated",
MAP("LineProperty", 0, NULL, (select MAX("RowId") from :tmpresult2 where "CardCode" = T0."CardCode" and "RowId" < T0."RowId" and "LineProperty" <  T0."LineProperty" ) ) 
AS "ParentId",
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"
FROM :tmpresult2 T0 ORDER BY "RowId";

-- SELECT * FROM :tmpresult3 ; --ORDER BY "RowId";
--SELECT "RowId" FROM :tmpresult3 WHERE "OpenAmountLC" <= "MinBalance" AND "LineProperty" = 1 AND IFNULL ("DunnLevel",1) > 0 ;

IF :dspOpnItms  = 'N' THEN
tmpresult4 =
SELECT "CheckLine", "ExeChkLine", "RowId", "CardCode", "DunningCode","LetterNum", "DunnLevel", "CardName", "DocCur", "ObjType", "DocNum", "InstlmntID", "DueDate"
, "LastLevelUpdateDate", "LastDunningDate", "NewLvlUpdDate", "DocAmountLC" , "DocAmountFC" , "OpenAmountLC" , "OpenAmountFC" , 	
"InterestDays", "Interest" , "InterestAmountLC" , 	"InterestAmountFC" , 	"TotalInclAmountLC" , 	"TotalInclAmountFC" , 	
"FeeLC", 

MAP("LineProperty", 1,
MAP("GrpMethod", 'B',
	MAP((SELECT "HiLtrFrmt" FROM ODUT WHERE "TermCode" = "DunningCode"), 'Y', 
		--Use Fee of max level as letter fee if it's highest letter format
		MAP("DocCur" , :mainCurncy , 0 ,(SELECT "FeeFC" FROM :tmpresult3 WHERE "RowId" = (select MAX("RowId") from :tmpresult3 where "CardCode" = T0."CardCode" GROUP BY "CardCode") ) ),
		--
		ROUND (
			MAP("DocCur" , :mainCurncy , 0 ,
				MAP (:directRate, 'Y', "FeeLC" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ),  "FeeLC" * (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ))
				),:priceDec ) )
	, "FeeFC" )
, "FeeFC" )	AS "FeeFC" ,

"OverallTotalLC" , 	"OverallTotalFC" ,
"AutoPost", "LineProperty", "YearDays", "YearlyRate","LetterFrmt", "OrigMinBalance", "MinBalance" , "GrpMethod", "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBalCurr", "LevelUpdated","ParentId", 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"
 FROM :tmpresult3 T0
WHERE MAP("LineProperty", 0, 0, 1,"RowId",999,"ParentId") NOT IN ( SELECT "RowId" FROM :tmpresult3 WHERE ("OpenAmountLC" <= "MinBalance") AND "LineProperty" = 1 AND IFNULL ("DunnLevel",1) > 0);

ELSE
-- If display all open items, no need compare with minimum Balance 
tmpresult4 =
SELECT "CheckLine", "ExeChkLine", "RowId", "CardCode", "DunningCode","LetterNum", "DunnLevel", "CardName", "DocCur", "ObjType", "DocNum", "InstlmntID", "DueDate"
, "LastLevelUpdateDate", "LastDunningDate", "NewLvlUpdDate", "DocAmountLC" , "DocAmountFC" , "OpenAmountLC" , "OpenAmountFC" , 	
"InterestDays", "Interest" , "InterestAmountLC" , 	"InterestAmountFC" , 	"TotalInclAmountLC" , 	"TotalInclAmountFC" , 	
"FeeLC", 

MAP("LineProperty", 1,
MAP("GrpMethod", 'B',
	MAP((SELECT "HiLtrFrmt" FROM ODUT WHERE "TermCode" = "DunningCode"), 'Y', 
		--Use Fee of max level as letter fee if it's highest letter format
		MAP("DocCur" , :mainCurncy , 0 ,(SELECT "FeeFC" FROM :tmpresult3 WHERE "RowId" = (select MAX("RowId") from :tmpresult3 where "CardCode" = T0."CardCode" GROUP BY "CardCode") ) ),
		--
		ROUND (
			MAP("DocCur" , :mainCurncy , 0 ,
				MAP (:directRate, 'Y', "FeeLC" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ),  "FeeLC" * (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ))
				),:priceDec ) )
	, "FeeFC" )
, "FeeFC" )	AS "FeeFC" ,

"OverallTotalLC" , 	"OverallTotalFC" ,
"AutoPost"  , 	"LineProperty", "YearDays", "YearlyRate" , 	"LetterFrmt", "OrigMinBalance", "MinBalance" , "GrpMethod", "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBalCurr", "LevelUpdated","ParentId" , 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"
 FROM :tmpresult3 T0 ;

END IF ;

-- SELECT * FROM :tmpresult4 ORDER BY "RowId";

SELECT "Value" INTO ovrDueOnly FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'OvrDueOnly';
SELECT "Value" INTO allowNegLt FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'AllowNegLt';

overdueCards = SELECT "CardCode" from :tmpresult4 group by "CardCode" HAVING (min("DueDate") < :dunningDate );
positiveCards = SELECT DISTINCT "CardCode" from :tmpresult4 where "GrpMethod" <> 'B' OR ("GrpMethod" = 'B' and "LineProperty" = 1 and  map (IFNULL ("TotalInclAmountFC",0) , 0, "TotalInclAmountLC", "TotalInclAmountFC") > 0 );
hasChildrenCards = SELECT "CardCode" FROM :tmpresult4 group by  "CardCode" HAVING count(1) > 1 ;

IF :ovrDueOnly = 'Y' THEN  
	IF :allowNegLt = 'N' THEN 	cards = SELECT T0."CardCode" AS "CardCode" FROM :hasChildrenCards T0 INNER JOIN :overdueCards T1 ON T0."CardCode"=T1."CardCode" INNER JOIN :positiveCards T2 ON T1."CardCode"=T2."CardCode";
	ELSE cards =  SELECT T0."CardCode" AS "CardCode" FROM :hasChildrenCards T0 INNER JOIN :overdueCards T1 ON T0."CardCode"=T1."CardCode" ; 
	END IF;
ELSE
	IF :allowNegLt = 'N' THEN 	cards = SELECT T0."CardCode" AS "CardCode" FROM :hasChildrenCards T0 INNER JOIN :positiveCards T1 ON T0."CardCode"=T1."CardCode" ;
	ELSE cards =  SELECT T0."CardCode" AS "CardCode" FROM :hasChildrenCards T0; 
	END IF;
END IF ;

tmpresult5=
SELECT T0.* FROM :tmpresult4 T0 INNER JOIN :cards T1 ON T0."CardCode"=T1."CardCode" ;

tmpresult6=
SELECT 
"CheckLine" ,  "ExeChkLine" , 
row_number () over (order by  "CardCode","LetterFrmt","DocCur", "BPLId" ,"LetterNum" , "DunnLevel", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate" 	, "DocAmountLC", "DocAmountFC" ) AS "RowId"  , 
"CardCode" ,  
row_number () over (PARTITION BY "CardCode", "LineProperty" )  AS "LetterNum", 
"DunnLevel" ,  
MAP("LineProperty" ,0 , "CardName", NULL) AS "CardName" ,  
"DocCur" , "ObjType" , "DocNum" , "InstlmntID" , "DueDate" , 
"LastLevelUpdateDate" , "LastDunningDate" ,  "NewLvlUpdDate" , "DocAmountLC" , "DocAmountFC" , "OpenAmountLC" , "OpenAmountFC" , 
"InterestDays" , "Interest" , "InterestAmountLC" ,  "InterestAmountFC" ,   "TotalInclAmountLC" ,  "TotalInclAmountFC"  , 
MAP ("LineProperty" , 1, "FeeLC" ,NULL) AS "FeeLC" ,
MAP ("LineProperty" , 1, "FeeFC" ,NULL) AS "FeeFC" ,
IFNULL ("OpenAmountLC",0) + IFNULL ("InterestAmountLC",0) + IFNULL ("FeeLC",0) AS "OverallTotalLC",
IFNULL ("OpenAmountFC",0) + IFNULL ("InterestAmountFC",0) + IFNULL ("FeeFC",0) AS "OverallTotalFC" ,
MAP("LineProperty" ,1 ,"AutoPost", NULL) AS "AutoPost" , 
"LineProperty" ,  "YearDays" ,  "YearlyRate" ,  
--CASE WHEN "GrpMethod" = 'B' THEN LAG("LetterFrmt",1) over (order by "CardCode","LetterNum" , "DunnLevel", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate" 	, "DocAmountLC", "DocAmountFC" )  
--ELSE "LetterFrmt" END AS "LetterFrmt", 
"LetterFrmt" AS "LetterFrmt",
"OrigMinBalance",  "GrpMethod" ,  "DocEntry" , "DocRate", "FeeCurr", "OrigFee", "MinBalCurr",  "LevelUpdated","ParentId", 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"

FROM :tmpresult5 T0
ORDER BY  "CardCode","LetterFrmt","DocCur", "LetterNum", "BPLId", "DunnLevel", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate" 	, "DocAmountLC", "DocAmountFC" ;

--  Fill "InstlmntID" of BP, Parent
tmpresult7=

SELECT 
"CheckLine" ,  "ExeChkLine" , 
"RowId"  , 
"CardCode" , --MAP ("LineProperty", 0, "CardCode", NULL) AS "CardCode" ,  
MAP ("LineProperty", 1, "LetterNum", NULL) AS "LetterNum", 
"DunnLevel",  
MAP ("LineProperty", 0, "CardName", NULL) AS "CardName" ,  
"DocCur" , "ObjType" , "DocNum" , "InstlmntID" , 
"DueDate" , "LastLevelUpdateDate" , "LastDunningDate" ,  "NewLvlUpdDate" , 

MAP("LineProperty" ,0, NULL, CAST ("DocAmountLC" AS NVARCHAR(40))) AS "DocAmountLC" ,  
MAP("LineProperty" ,0, NULL, CAST ("DocAmountFC" AS NVARCHAR(40))) AS "DocAmountFC" ,
MAP("LineProperty" ,0, NULL, CAST ("OpenAmountLC" AS NVARCHAR(40))) AS "OpenAmountLC" ,  
MAP("LineProperty" ,0, NULL, CAST ("OpenAmountFC" AS NVARCHAR(40))) AS "OpenAmountFC" , 
"InterestDays" , "Interest" ,   
MAP("LineProperty" ,0, NULL, CAST ("InterestAmountLC" AS NVARCHAR(40))) AS "InterestAmountLC" ,  
MAP("LineProperty" ,0, NULL, CAST ("InterestAmountFC" AS NVARCHAR(40))) AS "InterestAmountFC" ,
MAP("LineProperty" ,0, NULL, CAST ("TotalInclAmountLC" AS NVARCHAR(40))) AS "TotalInclAmountLC" ,  
MAP("LineProperty" ,0, NULL, CAST ("TotalInclAmountFC" AS NVARCHAR(40))) AS "TotalInclAmountFC" ,  
MAP("LineProperty" ,0, NULL, CAST ("FeeLC" AS NVARCHAR(40))) AS "FeeLC" ,  
MAP("LineProperty" ,0, NULL, CAST ("FeeFC" AS NVARCHAR(40))) AS "FeeFC" ,  
MAP("LineProperty" ,1, CAST ("OverallTotalLC" AS NVARCHAR(40)), NULL) AS "OverallTotalLC" ,  
MAP("LineProperty" ,1, CAST ("OverallTotalFC" AS NVARCHAR(40)), NULL) AS "OverallTotalFC" , 
"AutoPost" , "LineProperty" , "YearDays" ,  "YearlyRate" , "LetterFrmt",
"OrigMinBalance", --CAST ("OrigMinBalance" AS NVARCHAR(40)) AS "OrigMinBalance",  
"GrpMethod" ,  "DocEntry" , 
CAST ("DocRate" AS NVARCHAR(40)) AS "DocRate", 
"FeeCurr", 
"OrigFee",--CAST ("OrigFee" AS NVARCHAR(40)) AS "OrigFee", 
"MinBalCurr", "LevelUpdated", '' AS "DunAddr", '' AS "DocText",
MAP("LineProperty" ,0, NULL, "DocAmountLC"  ) AS "DocAmountLCBackup" ,  
MAP("LineProperty" ,0, NULL, "DocAmountFC"  ) AS "DocAmountFCBackup" ,
MAP("LineProperty" ,0, NULL, "OpenAmountLC" ) AS "OpenAmountLCBackup",  
MAP("LineProperty" ,0, NULL, "OpenAmountFC" ) AS "OpenAmountFCBackup", 
MAP("LineProperty" ,0, NULL, "InterestAmountLC"  ) AS  "InterestAmountLCBackup" ,  
MAP("LineProperty" ,0, NULL, "InterestAmountFC"  ) AS  "InterestAmountFCBackup" ,
MAP("LineProperty" ,0, NULL, "TotalInclAmountLC" ) AS  "TotalInclAmountLCBackup",  
MAP("LineProperty" ,0, NULL, "TotalInclAmountFC" ) AS  "TotalInclAmountFCBackup",  
MAP("LineProperty" ,0, NULL, "FeeLC") AS "FeeLCBackup",  
MAP("LineProperty" ,0, NULL, "FeeFC") AS "FeeFCBackup",  
MAP("LineProperty" ,1, "OverallTotalLC", NULL) AS "OverallTotalLCBackup",  
MAP("LineProperty" ,1, "OverallTotalFC", NULL) AS "OverallTotalFCBackup", 
MAP("LineProperty", 0, NULL, (select MAX("RowId") from :tmpresult6 where "CardCode" = T0."CardCode" and "RowId" < T0."RowId" and "LineProperty" <  T0."LineProperty" ) ) AS "ParentId", 
"BpCode2", "BpType", "CardName2", "Comment", 
MAP("LineProperty" ,0, NULL, "BPLId") AS "BPLId"

FROM :tmpresult6 T0 ORDER BY  "CardCode","LetterFrmt","DocCur", "LetterNum", "BPLId", "DunnLevel", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate" 	, "DocAmountLC", "DocAmountFC" ;

-- SELECT * FROM :tmpresult7;

tmpresult8=
SELECT 
"CheckLine" ,  "ExeChkLine" ,  "RowId"  , "CardCode" ,  "LetterNum", "DunnLevel" ,  "CardName" ,  
"DocCur" , "ObjType" , "DocNum" , 
MAP ("LineProperty", 0, 1, 
1, (CASE WHEN (SELECT COUNT(1) FROM :tmpresult7 WHERE "ParentId" = T0."RowId" AND ("DunnLevel" > 0 OR "DocAmountLCBackup">0 OR "DocAmountFCBackup" >0)) > 0 THEN 1 ELSE -1 END ),
"InstlmntID") AS "InstlmntID" , 
"DueDate" , "LastLevelUpdateDate" , "LastDunningDate" ,  "NewLvlUpdDate" , 
"DocAmountLC" , "DocAmountFC" , "OpenAmountLC" , "OpenAmountFC" , 
"InterestDays" , "Interest" , "InterestAmountLC" ,  "InterestAmountFC" ,   "TotalInclAmountLC" ,  "TotalInclAmountFC"  , "FeeLC" , "FeeFC" ,"OverallTotalLC","OverallTotalFC" ,
"AutoPost" , "LineProperty" ,  "YearDays" ,  "YearlyRate" ,  "LetterFrmt",
"OrigMinBalance",  "GrpMethod" ,  "DocEntry" , "DocRate", "FeeCurr", "OrigFee", "MinBalCurr",  "LevelUpdated", "DunAddr", "DocText",
"DocAmountLCBackup" ,"DocAmountFCBackup" ,"OpenAmountLCBackup","OpenAmountFCBackup",
"InterestAmountLCBackup" , "InterestAmountFCBackup" ,"TotalInclAmountLCBackup", "TotalInclAmountFCBackup", 
"FeeLCBackup","FeeFCBackup","OverallTotalLCBackup","OverallTotalFCBackup",
"ParentId", 
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"
FROM :tmpresult7 T0 ORDER BY  "CardCode","LetterFrmt","DocCur", "LetterNum", "BPLId", "DunnLevel", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate" 	, "DocAmountLC", "DocAmountFC" ;

INSERT INTO TMP_DWZ_OUT_LINEPROPERTY                                                                                                        
SELECT 
"CheckLine" ,  "ExeChkLine" ,  "RowId"  , "CardCode" ,  "LetterNum", "DunnLevel" ,  "CardName" ,  
"DocCur" , "ObjType" , "DocNum" , 
MAP ("LineProperty", 999, 
(CASE WHEN (SELECT "InstlmntID" FROM :tmpresult8 WHERE "RowId" = T0."ParentId") = -1 THEN -1 ELSE "InstlmntID" END ) , "InstlmntID") AS "InstlmntID" , 
"DueDate" , "LastLevelUpdateDate" , "LastDunningDate" ,  "NewLvlUpdDate" , 
"DocAmountLC" , "DocAmountFC" , "OpenAmountLC" , "OpenAmountFC" , 
"InterestDays" , "Interest" , "InterestAmountLC" ,  "InterestAmountFC" ,   "TotalInclAmountLC" ,  "TotalInclAmountFC"  , "FeeLC" , "FeeFC" ,"OverallTotalLC","OverallTotalFC" ,
"AutoPost" , 
MAP("LineProperty" , 0, 1, 1, 2, 999, 3) AS "LineProperty" ,  
"YearDays" ,  "YearlyRate" ,  "LetterFrmt",
"OrigMinBalance",  "GrpMethod" ,  "DocEntry" , "DocRate", "FeeCurr", "OrigFee", "MinBalCurr",  "LevelUpdated", "DunAddr", "DocText",
"DocAmountLCBackup" ,"DocAmountFCBackup" ,"OpenAmountLCBackup","OpenAmountFCBackup",
"InterestAmountLCBackup" , "InterestAmountFCBackup" ,"TotalInclAmountLCBackup", "TotalInclAmountFCBackup", 
"FeeLCBackup","FeeFCBackup","OverallTotalLCBackup","OverallTotalFCBackup",
"ParentId",
"BpCode2", "BpType", "CardName2", "Comment", "BPLId"
FROM :tmpresult8 T0 ORDER BY  "CardCode","LetterFrmt","DocCur", "LetterNum", "BPLId", "DunnLevel", "ObjType" ,"DocNum" ,"InstlmntID" ,"DueDate" 	, "DocAmountLC", "DocAmountFC" ;

-- Insert tree structure of result into SPPLA 
DELETE FROM SPPLA WHERE "PagingID" = :pagingID;

insert into sppla
select :pagingID ,"RowId","LineProperty"+1,
map("LineProperty", 
1, LEAD("RowId") over (partition by map("LineProperty",0,1,"LineProperty") order by "RowId") - "RowId",
0, LEAD("RowId") over (partition by  "LineProperty" order by "RowId") - "RowId"
) -1 as ChildCount
 from :tmpresult8 where "LineProperty" <>999 order by "RowId" ; 
	-- Calculate children number of last Row 
update sppla set "ChildrenNo" = (select max ("RowId") from TMP_DWZ_OUT_LINEPROPERTY )-"RowID" where "ChildrenNo" is null ;

-- Currency
-- SELECT foreign Currency which doesn't have exchange rate in dunning date into SPPP as output
forCurrTable =	
SELECT T0."Currency" AS "Currency" FROM 
( select "Currency" AS "Currency" from 
	( select "DocCur" as "Currency"  from :tmpresult5 union select "FeeCurr"  from :tmpresult5 union select "MinBalCurr"  from :tmpresult5 ) where "Currency" <> :mainCurncy and "Currency" is not null ) T0 
LEFT JOIN ( select "Currency", "RateDate","Rate" from ORTT where "RateDate" = :dunningDate ) T1 ON T0."Currency" = T1."Currency"
WHERE  T1."Rate" IS NULL ;	

foreignCurrency := '';
SELECT COUNT (1) INTO forCurrNum FROM :forCurrTable ;
IF :forCurrNum > 0 THEN
	DECLARE CURSOR F_C FOR SELECT * FROM :forCurrTable ;
	rowidx := 0;
	FOR F as F_C DO 
		if rowidx > 0 then 
			foreignCurrency := foreignCurrency || ',';
		end if;
		foreignCurrency := foreignCurrency || F."Currency";
		rowidx := rowidx + 1;
	END FOR;
END IF ;
--select :foreignCurrency from dummy;

DELETE FROM SPPP WHERE "PagingID" = :pagingID AND "Name" = 'ForeignCurrency';
IF LENGTH(:foreignCurrency) >0 THEN 
	INSERT INTO SPPP VALUES (:pagingID, 'ForeignCurrency', :foreignCurrency, '2' );
END IF;

END;

-- B1 DEPENDS: AFTER:SP:DWZ_CREATE_OBJECTS AFTER:PT:PROCESS_END
CREATE PROCEDURE DWZ_INV (
IN pagingID NVARCHAR(100)
,OUT dunning_doc_out DWZ_REPORT_OUT
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
percentDec SMALLINT;
priceDec SMALLINT;
dspOpnItms NVARCHAR(1);
allowNegLt NVARCHAR(1);
crdtNBased NVARCHAR(1);
docDate NVARCHAR(20);
dueDate NVARCHAR(20);
dunningDate NVARCHAR(20);
directRate NVARCHAR(1);
mainCurncy NVARCHAR(3);
UseBranches NVARCHAR(1);
BEGIN 

SELECT "PercentDec" INTO percentDec FROM "OADM";
SELECT "PriceDec" INTO priceDec FROM "OADM";
SELECT "DirectRate" INTO directRate FROM "OADM";
SELECT "MainCurncy" INTO mainCurncy FROM "OADM";

SELECT "Value" INTO dspOpnItms FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'DspOpnItms';
SELECT "Value" INTO allowNegLt FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'AllowNegLt';
SELECT "Value" INTO crdtNBased FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'CrdtNBased';

SELECT "Value" INTO docDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'docDate' ;
SELECT "Value" INTO dueDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dueDate' ;
SELECT "Value" INTO dunningDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dunningDate' ;

SELECT "Value" INTO UseBranches FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'UseBranches' ;

doc_out1 = 

SELECT T2."CardCode" AS "CardCode", 
       T2."CardName" AS "CardName", 
	   T3."TermCode" AS "DunningCode",
	   T1."DocCur" AS "DocCur", 
       T1."DocNum" AS "DocNum", 
       T0."DueDate" AS "DueDate", 
       MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) AS "DunnLevel", 
	   MAP(T0."DunnLevel", T3."MaxLevel", 'Y', 'N') AS "IsMaxLevel", 
       T0."InstlmntID" AS "InstlmntID", 
       T3."YearDays" AS "YearDays", 
       T3."YearlyRate" AS "YearlyRate", 
       T0."InsTotal" AS "InsTotal", 
       T0."InsTotalFC" AS "InsTotalFC", 
       T0."PaidToDate" AS "PaidToDate", 
       T0."PaidFC", 
       T0."DunDate" AS "DunDate", 
       T1."ObjType" AS "ObjType", 
       T1."DocEntry" AS "DocEntry", 
       T0."LvlUpdDate" AS "LvlUpdDate", 
       T3."RemIntrst" AS "RemIntrst",
	   T3."GrpMethod" AS "GrpMethod",
	   T3."AutoPost" AS "AutoPost",
	   
	   --CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   --ELSE T7."LetterFee" END AS "Fee",
	   T7."LetterFee"  AS "Fee",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."LetterFrmt"
	   ELSE T7."LetterFrmt" END AS "LetterFrmt",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."MinBalance"
	   ELSE T7."MinBalance" END AS "MinBalance",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."BalCurr"
	   ELSE T7."MinBlnCurr" END AS "MinBlnCurr",
	   
	   T7."FeeCurr" AS "FeeCurr",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   ELSE T7."LetterFee" END AS "OrigFee",	   
	   
	   CASE 
	   WHEN T3."XchgOrig"='Y'
	   THEN T1."DocRate"
	   ELSE T8."Rate" 
	   END
	   AS "Rate",
	   
	   T8."Rate" AS "DunningRate",
	   
	   T1."DocRate" AS "DocRate",
       
       CASE 
       WHEN T3."DateCalInt" = 'Y'
       THEN
       ( ( YEAR (:dunningDate) - YEAR (T0."DueDate")) * 12 + 
		( MONTH (:dunningDate) - MONTH (T0."DueDate")) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM T0."DueDate")
		ELSE
		( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate")))
		END		
		 AS "InterDays",       

       T7."CalcIntrst" AS "CalcIntrst",       
       CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."SumApplied"
       ELSE 0
       END AS "AppliedAfterDunningLC" ,
	   
	   CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."AppliedFC"
       ELSE 0
       END AS "AppliedAfterDunningFC" ,
	   
	   T4."SumApplied" AS "AppliedLC" ,
	   T4."AppliedFC" AS "AppliedFC" ,

	   CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))
	   THEN  T4."SumApplied"* ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END	   
       END AS "RemIntrstAmountLC" ,

		CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE
	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))  THEN
	    T4."AppliedFC" * ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END
	   
       END AS "RemIntrstAmountFC",
	   
	   T3."MonthDays" AS "MonthDays", 
	   T7."EffctAftr" AS "EffctAftr",
       T1."BPLId" AS "BPLId"
	   
FROM   "INV6" T0 
       INNER JOIN "OINV" T1 
               ON T1."DocEntry" = T0."DocEntry" 
       INNER JOIN "TMP_DWZ_CRD" T9
				ON T9."CardCode" =  MAP(T1."FatherType", 'P', ifnull(T1."FatherCard",T1."CardCode"), T1."CardCode")
       INNER JOIN "OCRD" T2 
                ON T2."CardCode" = T9."CardCode"
       INNER JOIN "ODUT" T3 
               ON T3."TermCode" = T2."DunTerm" 
	   INNER JOIN "DUT1" T7
               ON T3."TermCode" = T7."TermCode"
			   AND MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1)  = T7."LevelNum" 
	   LEFT OUTER JOIN "ORTT" T8
			   ON T1."DocCur" = T8."Currency" AND T8."RateDate" = (:dunningDate)
       LEFT OUTER JOIN "RCT2" T4 
                    ON T4."DocEntry" = T1."DocEntry" 
                       AND T4."InvType" = '13' 
       LEFT OUTER JOIN "ORCT" T5 
                    ON T5."DocNum" = T4."DocNum" 
       LEFT OUTER JOIN "OBOE" T6 
                    ON T6."BoeKey" = T5."BoeAbs" 
WHERE  		
	   T0."Status" = ( 'O' ) 
       AND T1."TransId" <> ( 0 ) 
       AND T1."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T1."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
       AND T0."DueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
       AND T1."BlockDunn" <> ( 'Y' ) 
       AND T0."DunWizBlck" <> ( 'Y' ) 
       AND ( T0."DunnLevel" IS NULL 
              OR T0."DunnLevel" <= T3."MaxLevel" ) 
       AND ( T0."InsTotal" > ( 0 ) 
              OR T0."InsTotalFC" > ( 0 ) ) 
	   AND MAP(:dspOpnItms, 'Y', 1, ( ( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )	-T7."EffctAftr"	) > 0

		AND (:UseBranches = 'N' OR T1."BPLId" IN 
		(
			SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
		))
;

doc_out2 =

SELECT T2."CardCode" AS "CardCode", 
       T2."CardName" AS "CardName", 
	   T3."TermCode" AS "DunningCode",
	   T1."DocCur" AS "DocCur", 
       T1."DocNum" AS "DocNum", 
       T0."DueDate"  AS "DueDate", 
       MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) AS "DunnLevel",
	   MAP(T0."DunnLevel", T3."MaxLevel", 'Y', 'N') AS "IsMaxLevel", 
       T0."InstlmntID" AS "InstlmntID", 
       T3."YearDays" AS "YearDays", 
       T3."YearlyRate" AS "YearlyRate", 
       T0."InsTotal" AS "InsTotal", 
       T0."InsTotalFC", 
       T0."PaidToDate" AS "PaidToDate", 
       T0."PaidFC", 
       T0."DunDate" AS "DunDate", 
       T1."ObjType" AS "ObjType", 
       T1."DocEntry" AS "DocEntry", 
       T0."LvlUpdDate" AS "LvlUpdDate", 
       T3."RemIntrst" AS "RemIntrst",
	   T3."GrpMethod" AS "GrpMethod",
	   T3."AutoPost" AS "AutoPost",
	   
	   --CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   --ELSE T7."LetterFee" END AS "Fee",
	   T7."LetterFee"  AS "Fee",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."LetterFrmt"
	   ELSE T7."LetterFrmt" END AS "LetterFrmt",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."MinBalance"
	   ELSE T7."MinBalance" END AS "MinBalance",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."BalCurr"
	   ELSE T7."MinBlnCurr" END AS "MinBlnCurr",
	   
	   T7."FeeCurr" AS "FeeCurr",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   ELSE T7."LetterFee" END AS "OrigFee",
	   
	   
	   CASE 
	   WHEN T3."XchgOrig"='Y'
	   THEN T1."DocRate"
	   ELSE T8."Rate" 
	   END
	   AS "Rate",
	   
	   T8."Rate" AS "DunningRate",
	   
	   T1."DocRate" AS "DocRate",
       
       CASE 
       WHEN T3."DateCalInt" = 'Y'
       THEN
       ( ( YEAR (:dunningDate) - YEAR (T0."DueDate")) * 12 + 
		( MONTH (:dunningDate) - MONTH (T0."DueDate")) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM T0."DueDate")
		ELSE
		( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate")))
		END		
		 AS "InterDays",       

       T7."CalcIntrst" AS "CalcIntrst",       
       CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."SumApplied"
       ELSE 0
       END AS "AppliedAfterDunningLC" ,
	   
	   CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."AppliedFC"
       ELSE 0
       END AS "AppliedAfterDunningFC" ,
	   
	   T4."SumApplied" AS "AppliedLC" ,
	   T4."AppliedFC" AS "AppliedFC" ,

	   CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate  AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate")) 
	   THEN  T4."SumApplied"* ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END	   
       END AS "RemIntrstAmountLC" ,

		CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE
	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate  AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))  THEN
	    T4."AppliedFC" * ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END
	   
       END AS "RemIntrstAmount"  ,
	   
	   T3."MonthDays" AS "MonthDays", 
	   T7."EffctAftr" AS "EffctAftr",
       T1."BPLId" AS "BPLId"
	   
FROM   "CSI6" T0 
       INNER JOIN "OCSI" T1 
               ON T1."DocEntry" = T0."DocEntry" 
       INNER JOIN "TMP_DWZ_CRD" T9
				ON T9."CardCode" =  MAP(T1."FatherType", 'P', ifnull(T1."FatherCard",T1."CardCode"), T1."CardCode")
       INNER JOIN "OCRD" T2 
                ON T2."CardCode" = T9."CardCode"
       INNER JOIN "ODUT" T3 
               ON T3."TermCode" = T2."DunTerm" 
	   INNER JOIN "DUT1" T7
               ON T3."TermCode" = T7."TermCode"
			   AND MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) = T7."LevelNum" 
	   LEFT OUTER JOIN "ORTT" T8
			   ON T1."DocCur" = T8."Currency" AND T8."RateDate" = (:dunningDate)
       LEFT OUTER JOIN "RCT2" T4 
                    ON T4."DocEntry" = T1."DocEntry" 
                       AND T4."InvType" = '165' 
       LEFT OUTER JOIN "ORCT" T5 
                    ON T5."DocNum" = T4."DocNum" 
       LEFT OUTER JOIN "OBOE" T6 
                    ON T6."BoeKey" = T5."BoeAbs" 
WHERE  		
	   T0."Status" = ( 'O' ) 
       AND T1."TransId" <> ( 0 ) 
       AND T1."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T1."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
       AND T0."DueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
       AND T1."BlockDunn" <> ( 'Y' ) 
       AND T0."DunWizBlck" <> ( 'Y' ) 
       AND ( T0."DunnLevel" IS NULL 
              OR T0."DunnLevel" <= T3."MaxLevel" ) 
       AND ( T0."InsTotal" > ( 0 ) 
              OR T0."InsTotalFC" > ( 0 ) ) 
	   AND MAP(:dspOpnItms, 'Y', 1, ( ( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )	-T7."EffctAftr"	) > 0		
		
		AND (:UseBranches = 'N' OR T1."BPLId" IN 
		(
			SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
		))
;

doc_out3 =

SELECT T2."CardCode" AS "CardCode", 
       T2."CardName" AS "CardName", 
	   T3."TermCode" AS "DunningCode",
	   T1."DocCur" AS "DocCur", 
       T1."DocNum" AS "DocNum", 
       T0."DueDate"  AS "DueDate", 
       MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) AS "DunnLevel",
	   MAP(T0."DunnLevel", T3."MaxLevel", 'Y', 'N') AS "IsMaxLevel", 
       T0."InstlmntID" AS "InstlmntID", 
       T3."YearDays" AS "YearDays", 
       T3."YearlyRate" AS "YearlyRate", 
       T0."InsTotal" AS "InsTotal", 
       T0."InsTotalFC", 
       T0."PaidToDate" AS "PaidToDate", 
       T0."PaidFC", 
       T0."DunDate" AS "DunDate", 
       T1."ObjType" AS "ObjType", 
       T1."DocEntry" AS "DocEntry", 
       T0."LvlUpdDate" AS "LvlUpdDate", 
       T3."RemIntrst" AS "RemIntrst",
	   T3."GrpMethod" AS "GrpMethod",
	   T3."AutoPost" AS "AutoPost",
	   
	   --CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   --ELSE T7."LetterFee" END AS "Fee",
	   T7."LetterFee"  AS "Fee",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."LetterFrmt"
	   ELSE T7."LetterFrmt" END AS "LetterFrmt",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."MinBalance"
	   ELSE T7."MinBalance" END AS "MinBalance",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."BalCurr"
	   ELSE T7."MinBlnCurr" END AS "MinBlnCurr",
	   
	   T7."FeeCurr" AS "FeeCurr",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   ELSE T7."LetterFee" END AS "OrigFee",
	   
	   
	   CASE 
	   WHEN T3."XchgOrig"='Y'
	   THEN T1."DocRate"
	   ELSE T8."Rate" 
	   END
	   AS "Rate",
	   
	   T8."Rate" AS "DunningRate",
	   
	   T1."DocRate" AS "DocRate",
       
       CASE 
       WHEN T3."DateCalInt" = 'Y'
       THEN
       ( ( YEAR (:dunningDate) - YEAR (T0."DueDate")) * 12 + 
		( MONTH (:dunningDate) - MONTH (T0."DueDate")) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM T0."DueDate")
		ELSE
		( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate")))
		END		
		 AS "InterDays",       

       T7."CalcIntrst" AS "CalcIntrst",       
       CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."SumApplied"
       ELSE 0
       END AS "AppliedAfterDunningLC" ,
	   
	   CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."AppliedFC"
       ELSE 0
       END AS "AppliedAfterDunningFC" ,
	   
	   T4."SumApplied" AS "AppliedLC" ,
	   T4."AppliedFC" AS "AppliedFC" ,

	   CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate   AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))
	   THEN  T4."SumApplied"* ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END	   
       END AS "RemIntrstAmountLC" ,

		CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE
	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate  AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))  THEN
	    T4."AppliedFC" * ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END
	   
       END AS "RemIntrstAmount"  	,
	   
	   T3."MonthDays" AS "MonthDays", 
	   T7."EffctAftr" AS "EffctAftr",
	   T1."BPLId" AS "BPLId"
       
FROM   "DPI6" T0 
       INNER JOIN "ODPI" T1 
               ON T1."DocEntry" = T0."DocEntry" 
       INNER JOIN "TMP_DWZ_CRD" T9
				ON T9."CardCode" =  MAP(T1."FatherType", 'P', ifnull(T1."FatherCard",T1."CardCode"), T1."CardCode")
       INNER JOIN "OCRD" T2 
                ON T2."CardCode" = T9."CardCode"
       INNER JOIN "ODUT" T3 
               ON T3."TermCode" = T2."DunTerm" 
	   INNER JOIN "DUT1" T7
               ON T3."TermCode" = T7."TermCode"
			   AND MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) = T7."LevelNum" 
	   LEFT OUTER JOIN "ORTT" T8
			   ON T1."DocCur" = T8."Currency" AND T8."RateDate" = (:dunningDate)
       LEFT OUTER JOIN "RCT2" T4 
                    ON T4."DocEntry" = T1."DocEntry" 
                       AND T4."InvType" = '203' 
       LEFT OUTER JOIN "ORCT" T5 
                    ON T5."DocNum" = T4."DocNum" 
       LEFT OUTER JOIN "OBOE" T6 
                    ON T6."BoeKey" = T5."BoeAbs" 
WHERE  		
	    T0."Status" = ( 'O' ) 
       AND T1."TransId" <> ( 0 ) 
       AND T1."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T1."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
       AND T0."DueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
       AND T1."BlockDunn" <> ( 'Y' ) 
       AND T0."DunWizBlck" <> ( 'Y' ) 
       AND ( T0."DunnLevel" IS NULL 
              OR T0."DunnLevel" <= T3."MaxLevel" ) 
       AND ( T0."InsTotal" > ( 0 ) 
              OR T0."InsTotalFC" > ( 0 ) ) 
	   AND MAP(:dspOpnItms, 'Y', 1, ( ( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )	-T7."EffctAftr"	) > 0
		
		AND (:UseBranches = 'N' OR T1."BPLId" IN 
		(
			SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
		))
;

doc_out4 =

SELECT T2."CardCode" AS "CardCode", 
       T2."CardName" AS "CardName", 
	   T3."TermCode" AS "DunningCode",
	   T1."DocCur" AS "DocCur", 
       T1."DocNum" AS "DocNum", 
       T0."DueDate"  AS "DueDate", 
       MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) AS "DunnLevel",
	   MAP(T0."DunnLevel", T3."MaxLevel", 'Y', 'N') AS "IsMaxLevel", 
       T0."InstlmntID" AS "InstlmntID", 
       T3."YearDays" AS "YearDays", 
       T3."YearlyRate" AS "YearlyRate", 
       T0."InsTotal" AS "InsTotal", 
       T0."InsTotalFC", 
       T0."PaidToDate" AS "PaidToDate", 
       T0."PaidFC", 
       T0."DunDate" AS "DunDate", 
       T1."ObjType" AS "ObjType", 
       T1."DocEntry" AS "DocEntry", 
       T0."LvlUpdDate" AS "LvlUpdDate", 
       T3."RemIntrst" AS "RemIntrst",
	   T3."GrpMethod" AS "GrpMethod",
	   T3."AutoPost" AS "AutoPost",
	   
	   --CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   --ELSE T7."LetterFee" END AS "Fee",
	   T7."LetterFee"  AS "Fee",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."LetterFrmt"
	   ELSE T7."LetterFrmt" END AS "LetterFrmt",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."MinBalance"
	   ELSE T7."MinBalance" END AS "MinBalance",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."BalCurr"
	   ELSE T7."MinBlnCurr" END AS "MinBlnCurr",
	   
	   T7."FeeCurr" AS "FeeCurr",
	   
	   CASE WHEN T3."GrpMethod" = 'B' THEN T3."TotalFee"
	   ELSE T7."LetterFee" END AS "OrigFee",
	   
	   
	   CASE 
	   WHEN T3."XchgOrig"='Y'
	   THEN T1."DocRate"
	   ELSE T8."Rate" 
	   END
	   AS "Rate",
	   
	   T8."Rate" AS "DunningRate",
	   
	   T1."DocRate" AS "DocRate",
       
       CASE 
       WHEN T3."DateCalInt" = 'Y'
       THEN
       ( ( YEAR (:dunningDate) - YEAR (T0."DueDate")) * 12 + 
		( MONTH (:dunningDate) - MONTH (T0."DueDate")) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM T0."DueDate")
		ELSE
		( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate")))
		END		
		 AS "InterDays",       

       T7."CalcIntrst" AS "CalcIntrst",       
       CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."SumApplied"
       ELSE 0
       END AS "AppliedAfterDunningLC" ,
	   
	   CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."AppliedFC"
       ELSE 0
       END AS "AppliedAfterDunningFC" ,
	   
	   T4."SumApplied" AS "AppliedLC" ,
	   T4."AppliedFC" AS "AppliedFC" ,

	   CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate  AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate")) 
	   THEN  T4."SumApplied"* ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END	   
       END AS "RemIntrstAmountLC" ,

		CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE
	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate  AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate")) THEN
	    T4."AppliedFC" * ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END
	   
       END AS "RemIntrstAmount"  ,
	   
	   T3."MonthDays" AS "MonthDays", 
	   T7."EffctAftr" AS "EffctAftr",
	   T1."BPLId" AS "BPLId"
       
FROM   "RIN6" T0 
       INNER JOIN "ORIN" T1 
               ON T1."DocEntry" = T0."DocEntry" 
       INNER JOIN "TMP_DWZ_CRD" T9
				ON T9."CardCode" =  MAP(T1."FatherType", 'P', ifnull(T1."FatherCard",T1."CardCode"), T1."CardCode")
       INNER JOIN "OCRD" T2 
                ON T2."CardCode" = T9."CardCode"
       INNER JOIN "ODUT" T3 
               ON T3."TermCode" = T2."DunTerm" 
	   INNER JOIN "DUT1" T7
               ON T3."TermCode" = T7."TermCode"
			   AND MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) = T7."LevelNum" 
	   LEFT OUTER JOIN "ORTT" T8
			   ON T1."DocCur" = T8."Currency" AND T8."RateDate" = (:dunningDate)
       LEFT OUTER JOIN "RCT2" T4 
                    ON T4."DocEntry" = T1."DocEntry" 
                       AND T4."InvType" = '14' 
       LEFT OUTER JOIN "ORCT" T5 
                    ON T5."DocNum" = T4."DocNum" 
       LEFT OUTER JOIN "OBOE" T6 
                    ON T6."BoeKey" = T5."BoeAbs" 
WHERE  		
	    T0."Status" = ( 'O' ) 
       AND T1."TransId" <> ( 0 ) 
       AND T1."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T1."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
       AND T0."DueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
       AND T1."BlockDunn" <> ( 'Y' ) 
       AND T0."DunWizBlck" <> ( 'Y' ) 
       AND ( T0."DunnLevel" IS NULL 
              OR T0."DunnLevel" <= T3."MaxLevel" ) 
       AND ( T0."InsTotal" < ( 0 ) 
              OR T0."InsTotalFC" < ( 0 ) ) 
	   AND MAP(:dspOpnItms, 'Y', 1, ( ( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )	-T7."EffctAftr"	) > 0	
		
		AND (:UseBranches = 'N' OR T1."BPLId" IN 
		(
			SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
		))
;

IF :crdtNBased='Y' THEN 
doc_out_all =
SELECT * FROM :doc_out1 UNION ALL
SELECT * FROM :doc_out2 UNION ALL
SELECT * FROM :doc_out3 UNION ALL
SELECT * FROM :doc_out4 ;
ELSE
doc_out_all =
SELECT * FROM :doc_out1 UNION ALL
SELECT * FROM :doc_out2 UNION ALL
SELECT * FROM :doc_out3 ;
END IF ;

doc_out_pre =
SELECT 
"CardCode",
"CardName",
"DunningCode",
"DocCur",
MAP("IsMaxLevel",'Y',"DunnLevel" ,
CASE WHEN ( ( ( YEAR (:dunningDate) - YEAR (IFNULL ("LvlUpdDate","DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL ("LvlUpdDate","DueDate"))) )* "MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL ("LvlUpdDate","DueDate"))) ) -"EffctAftr" >0
		THEN "DunnLevel" ELSE "DunnLevel"-1
END)
AS "DunnLevel",
"ObjType", 
--CASE WHEN "ObjType" = '13' THEN 'IN' ELSE "ObjType" END AS "ObjType",
"DocNum",
"InstlmntID",
"DueDate",
"LvlUpdDate" AS "LastLevelUpdateDate",
"DunDate" AS "LastDunningDate",

CASE WHEN ( ( ( YEAR (:dunningDate) - YEAR (IFNULL ("LvlUpdDate","DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL ("LvlUpdDate","DueDate"))) )* "MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL ("LvlUpdDate","DueDate"))) ) -"EffctAftr" >0
		THEN :dunningDate ELSE '10000000'
END
AS "NewLvlUpdDate",

CASE
WHEN "ObjType" = '14' THEN -"InsTotal" 
ELSE "InsTotal" 
END
AS "DocAmountLC",

CASE
WHEN "ObjType" = '14' THEN -"InsTotalFC" 
ELSE "InsTotalFC" 
END
AS "DocAmountFC",

ROUND(
CASE 
WHEN "ObjType" = '14' THEN -"InsTotal"+ ("PaidToDate" - SUM("AppliedAfterDunningLC"))
ELSE "InsTotal"- ("PaidToDate" - SUM("AppliedAfterDunningLC"))
END
,:priceDec)
AS "OpenAmountLC", 

ROUND(
CASE 
WHEN "ObjType" = '14' THEN -"InsTotalFC"+ ("PaidFC" - SUM("AppliedAfterDunningFC"))
ELSE "InsTotalFC"- ("PaidFC" - SUM("AppliedAfterDunningFC"))
END
,:priceDec)
AS "OpenAmountFC", 

CASE 
WHEN "RemIntrst" = 'N' AND (SUM("AppliedLC") + SUM("AppliedFC")) <> 0 THEN NULL
ELSE "InterDays" 
END AS "InterestDays", 

CASE WHEN  "InterDays" <= 0 THEN NULL ELSE
ROUND(
CASE 
WHEN "RemIntrst" = 'N' AND (SUM("AppliedLC") + SUM("AppliedFC")) <> 0  THEN NULL
ELSE "YearlyRate" * "InterDays" / "YearDays"  
END
,:percentDec)
END AS "Interest",

CASE WHEN "CalcIntrst" = 'N' OR "InterDays" <= 0 THEN 0
ELSE
	ROUND(CASE WHEN IFNULL("InsTotalFC",0) = 0 THEN
		CASE WHEN "ObjType" = '14'
		THEN (-"InsTotal"+ ("PaidToDate" - SUM("AppliedAfterDunningLC"))) * "YearlyRate" * "InterDays" / "YearDays" / 100 - SUM ("RemIntrstAmountLC" )
		ELSE ("InsTotal"- ("PaidToDate" - SUM("AppliedAfterDunningLC"))) * "YearlyRate" * "InterDays" / "YearDays" / 100  + SUM ("RemIntrstAmountLC" )
		END
	ELSE
		ROUND(CASE WHEN "ObjType" = '14'
		THEN (-"InsTotalFC"+ ("PaidFC" - SUM("AppliedAfterDunningFC"))) * "YearlyRate" * "InterDays" / "YearDays" / 100 - SUM ("RemIntrstAmountFC" )
		ELSE ("InsTotalFC"- ("PaidFC" - SUM("AppliedAfterDunningFC"))) * "YearlyRate" * "InterDays" / "YearDays" / 100  + SUM ("RemIntrstAmountFC" )
		END,:priceDec)* map(:directRate,'Y', "Rate", 1/"Rate")
	END,:priceDec)
END AS "InterestAmountLC",

ROUND(
CASE 
WHEN "CalcIntrst" = 'N' OR "InterDays" <= 0 THEN 0
ELSE

CASE 
WHEN "ObjType" = '14'
THEN (-"InsTotalFC"+ ("PaidFC" - SUM("AppliedAfterDunningFC"))) * "YearlyRate" * "InterDays" / "YearDays" / 100 - SUM ("RemIntrstAmountFC" )
ELSE
("InsTotalFC"- ("PaidFC" - SUM("AppliedAfterDunningFC"))) * "YearlyRate" * "InterDays" / "YearDays" / 100  + SUM ("RemIntrstAmountFC" )
END

END 
,:priceDec)
AS "InterestAmountFC",

"GrpMethod" , 

"Fee",

ROUND (
MAP("FeeCurr" , :mainCurncy , "Fee" ,
	MAP (:directRate, 'Y', "Fee" * (SELECT "Rate" FROM ORTT WHERE "Currency" = "FeeCurr" AND "RateDate" = :dunningDate ),  "Fee" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "FeeCurr" AND "RateDate" = :dunningDate ))
	),:priceDec ) AS "FeeLC", 
	
--"Fee" AS "FeeLC",
0  AS "FeeFC",

"AutoPost", "YearDays", "YearlyRate", "LetterFrmt", "MinBalance" as "OrigMinBalance", 
ROUND (
CASE WHEN "MinBlnCurr" = :mainCurncy THEN "MinBalance" 
ELSE MAP (:directRate, 'Y', "MinBalance"* (SELECT "Rate" FROM ORTT WHERE "Currency" = "MinBlnCurr" AND "RateDate" = :dunningDate ),  "MinBalance" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "MinBlnCurr" AND "RateDate" = :dunningDate ))
END,:priceDec ) AS "MinBalance", 

"DocEntry", "DocRate", "FeeCurr" ,"OrigFee","MinBlnCurr" AS "MinBalCurr", "BPLId"

FROM
:doc_out_all

GROUP BY  "CardCode","CardName", "DunningCode", "IsMaxLevel", "FeeCurr", "OrigFee", "MinBlnCurr", "DocCur","GrpMethod", "ObjType","Rate","DocNum","InstlmntID", "RemIntrst","InstlmntID","DueDate", "DunDate", "DocNum" ,"DunnLevel","LvlUpdDate", "InsTotal", "InsTotalFC" ,"PaidToDate","PaidFC", "YearlyRate", "InterDays", "YearDays", "CalcIntrst" , 
"Fee", "DunningRate", "AutoPost", "LetterFrmt", "MinBalance","MinBlnCurr","MonthDays","EffctAftr", "DocEntry", "DocRate", "BPLId"

;

dunning_doc_out = 

--DOC with Debit
SELECT "CardCode", "CardName", "DunningCode",  "DocCur",  "DunnLevel", "ObjType", "DocNum", "InstlmntID", 
"DueDate", "LastLevelUpdateDate", "LastDunningDate",  "NewLvlUpdDate", 
"DocAmountLC", "DocAmountFC", cast("OpenAmountLC" as DECIMAL(21,6)) as "OpenAmountLC", cast("OpenAmountFC" as DECIMAL(21,6)) as "OpenAmountFC", "InterestDays", 
cast("Interest" as DECIMAL(21,6)) as "Interest", cast("InterestAmountLC" as DECIMAL(21,6)) as "InterestAmountLC",  cast("InterestAmountFC" as DECIMAL(21,6)) as "InterestAmountFC", 
"GrpMethod" ,  cast("FeeLC" as DECIMAL(21,6))  as "FeeLC",  
cast(
MAP("DocCur" , :mainCurncy , 0 ,
MAP("FeeCurr", "DocCur", "Fee",
ROUND (
MAP (:directRate, 'Y', "FeeLC" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ),  "FeeLC" * (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ))
,:priceDec ) 
))
as DECIMAL(21,6))
AS "FeeFC", 
"AutoPost" ,  "YearDays",  "YearlyRate",  "LetterFrmt" , "OrigMinBalance", cast("MinBalance" as DECIMAL(21,6)) as "MinBalance",  "DocEntry", "DocRate", "FeeCurr" , "OrigFee","MinBalCurr", 
(CASE WHEN "NewLvlUpdDate" = '10000000' THEN 'N' ELSE 'Y' END) AS "LevelUpdated",
--MAP("NewLvlUpdDate", '10000000', 'N', 'Y') AS "LevelUpdated"
"CardCode" AS "BpCode2", 'C' AS "BpType", "CardName" AS "CardName2", '' AS "Comment", "BPLId"

FROM
:doc_out_pre
;   
	  
--select * from :dunning_doc_out;
END;

-- B1 DEPENDS: AFTER:SP:DWZ_CREATE_OBJECTS AFTER:PT:PROCESS_END

CREATE PROCEDURE DWZ_JE (
IN pagingID NVARCHAR(100),
IN bpType NVARCHAR(1),
OUT dunning_je_out DWZ_REPORT_OUT
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
percentDec SMALLINT;
priceDec SMALLINT;
dspOpnItms NVARCHAR(1);
allowNegLt NVARCHAR(1);
docDate NVARCHAR(20);
dueDate NVARCHAR(20);
dunningDate NVARCHAR(20);
directRate NVARCHAR(1);
mainCurncy NVARCHAR(3);
UseBranches NVARCHAR(1);
BEGIN 

SELECT "PercentDec" INTO percentDec FROM "OADM";
SELECT "PriceDec" INTO priceDec FROM "OADM";
SELECT "DirectRate" INTO directRate FROM "OADM";
SELECT "MainCurncy" INTO mainCurncy FROM "OADM";
SELECT "Value" INTO dspOpnItms FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'DspOpnItms';
SELECT "Value" INTO allowNegLt FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'AllowNegLt';

SELECT "Value" INTO docDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'docDate' ;
SELECT "Value" INTO dueDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dueDate' ;
SELECT "Value" INTO dunningDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dunningDate' ;

SELECT "Value" INTO UseBranches FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'UseBranches' ;

dunning_je =
SELECT T2."CardCode" AS "CardCode", 
       T2."CardName" AS "CardName", 
	   T3."TermCode" AS "DunningCode",
	   MAP ( T0."FCCurrency", NULL, :mainCurncy,  MAP(LENGTH ( T0."FCCurrency"), 0, :mainCurncy, T0."FCCurrency") ) AS "DocCur", 
       T0."DueDate" AS "DueDate", 
       CASE 
       WHEN T0."Debit" >0 OR  T0."FCDebit" >0 THEN   MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) 
       ELSE 0
       END AS "DunnLevel", 
	   MAP(T0."DunnLevel", T3."MaxLevel", 'Y', 'N') AS "IsMaxLevel", 
       T3."YearDays" AS "YearDays", 
       T3."YearlyRate" AS "YearlyRate",  
       T0."Credit" AS "Credit", 
       T0."FCCredit" AS "FCCredit", 
       T0."Debit" AS "Debit", 
       T0."FCDebit" AS "FCDebit", 
       T0."DunDate" AS "DunDate", 
       T1."TransType" AS "TransType",  
       T1."TransId" AS "TransId", 
       T0."Line_ID" AS "Line_ID", 
       T0."BalDueCred" AS "BalDueCred", 
       T0."BalFcCred", 
       T0."BalDueDeb" AS "BalDueDeb", 
       T0."BalFcDeb", 
       T0."LvlUpdDate" AS "LvlUpdDate", 
       T3."RemIntrst" AS "RemIntrst",
	   
	   T3."GrpMethod" AS "GrpMethod",
	   T3."AutoPost" AS "AutoPost",
	   
	   CASE WHEN T0."Credit" >0 OR T0."FCCredit" >0  THEN T3."TotalFee"
	   ELSE T7."LetterFee" END AS "Fee",
	   
	   CASE WHEN T3."GrpMethod" = 'B' OR T0."Credit" >0 OR T0."FCCredit" >0 THEN T3."LetterFrmt"
	   ELSE T7."LetterFrmt" END AS "LetterFrmt",
	   
	   CASE WHEN T3."GrpMethod" = 'B' OR T0."Credit" >0 OR T0."FCCredit" >0 THEN T3."MinBalance"
	   ELSE T7."MinBalance" END AS "MinBalance",
	   
	   CASE WHEN T3."GrpMethod" = 'B' OR T0."Credit" >0 OR T0."FCCredit" >0 THEN T3."BalCurr"
	   ELSE T7."MinBlnCurr" END AS "MinBlnCurr",
	   
	   CASE WHEN T3."GrpMethod" = 'B' AND T3."HiLtrFrmt" = 'N' OR T0."Credit" >0 OR T0."FCCredit" >0 THEN T3."FeeCurr"
	   ELSE T7."FeeCurr" END AS "FeeCurr",
	   
	   CASE WHEN T3."GrpMethod" = 'B' OR T0."Credit" >0 OR T0."FCCredit" >0 THEN T3."TotalFee"
	   ELSE T7."LetterFee" END AS "OrigFee",
	   
	   CASE  WHEN T3."XchgOrig"='Y'  THEN 0 ELSE T8."Rate"  END AS "Rate",
	   
	   T8."Rate" AS "DunningRate",
	   MAP ( T0."FCCurrency", NULL, 1,  MAP(LENGTH ( T0."FCCurrency"), 0, 1, (SELECT "Rate" FROM ORTT WHERE "Currency" = T0."FCCurrency" AND "RateDate" = T0."DueDate") ) ) AS "DocRate", 
	   
        
        CASE 
        WHEN  T0."Credit" >0 OR T0."FCCredit" >0 THEN 0
        ELSE
          
        CASE 
       WHEN T3."DateCalInt" = 'Y'
       THEN
       ( ( YEAR (:dunningDate) - YEAR (T0."DueDate")) * 12 + 
		( MONTH (:dunningDate) - MONTH (T0."DueDate")) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM T0."DueDate")
		ELSE
		( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate")))
		END		
		
		END
		 AS "InterDays",         
             
       T7."CalcIntrst" AS "CalcIntrst",
       
       CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."SumApplied"
       ELSE 0
       END AS "AppliedAfterDunningLC" ,
	   
	   CASE 
       WHEN T5."DocDate" > :dunningDate  THEN  T4."AppliedFC"
       ELSE 0
       END AS "AppliedAfterDunningFC" ,

	   CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate   AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))
	   THEN  T4."SumApplied"* ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END	   
       END AS "RemIntrstAmountLC" ,

		CASE 
	   WHEN T3."RemIntrst" = 'Y' THEN 0
	   ELSE
	   
	   CASE 
       WHEN T5."DocDate" <= :dunningDate  AND T5."DocDate" >= MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate")) THEN
	    T4."AppliedFC" * ( ( ( YEAR (T5."DocDate") - YEAR (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) * 12 + 
		( MONTH (T5."DocDate") - MONTH (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) )* T3."MonthDays" + 
		EXTRACT (DAY FROM T5."DocDate") - EXTRACT (DAY FROM (MAP (T3."DateCalInt" ,'Y', T0."DueDate", IFNULL (T0."LvlUpdDate",T0."DueDate"))) ) ) * T3."YearlyRate" / T3."YearDays"/100
       ELSE 0
	   END
	   
       END AS "RemIntrstAmountFC" ,
	   
	   T3."MonthDays" AS "MonthDays", 
	   T7."EffctAftr" AS "EffctAftr",
	   T10."CardCode" AS "BpCode2", T10."CardName" AS "CardName2", T0."LineMemo" AS "Comment",
	   T0."BPLId" AS "BPLId"
       
FROM   "JDT1" T0 
       INNER JOIN "OJDT" T1 
               ON T1."TransId" = T0."TransId" 
       INNER JOIN "OCRD" T2 
               ON (T2."CardCode" = T0."ShortName" AND bpType = 'C' OR T2."ConnBP" = T0."ShortName" AND bpType = 'S')
       INNER JOIN "TMP_DWZ_CRD" T9 ON (T2."CardCode" = T9."CardCode")
       INNER JOIN "ODUT" T3 
               ON T3."TermCode" = T2."DunTerm" 
	INNER JOIN "DUT1" T7
        ON T3."TermCode" = T7."TermCode"
			   AND MAP(T0."DunnLevel", T3."MaxLevel", T0."DunnLevel", T0."DunnLevel"+1) = T7."LevelNum" 
	INNER JOIN "OCRD" T10
               ON (T10."CardCode" = T0."ShortName")
	LEFT OUTER JOIN "ORTT" T8
			   ON MAP ( T0."FCCurrency", NULL, :mainCurncy,  MAP(LENGTH ( T0."FCCurrency"), 0, :mainCurncy, T0."FCCurrency") ) = T8."Currency" AND T8."RateDate" = (:dunningDate)
       LEFT OUTER JOIN "RCT2" T4 
                    ON T4."DocTransId" = T0."TransId" 
		    			AND T4."InvType" = '30' 
       LEFT OUTER JOIN "ORCT" T5 
                    ON T5."DocNum" = T4."DocNum" 
WHERE  
		T1."TransType" IN ('30','-2','-3') 
       AND  (IFNULL(T0."BalDueCred",0) <> 0 OR IFNULL(T0."BalDueDeb",0) <> 0  OR IFNULL(T0."BalFcCred",0) <> 0  OR IFNULL(T0."BalFcDeb",0) <> 0 )
       AND T0."RevSource" = ( 'N' ) 
       AND T1."RefDate" <= ( MAP (LENGTH (:docDate) , 0, T1."RefDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
       AND T0."DueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
       AND T1."BlockDunn" <> ( 'Y' ) 
       AND T0."DunWizBlck" <> ( 'Y' ) 
       AND ( T0."DunnLevel" IS NULL 
              OR T0."DunnLevel" <= T3."MaxLevel" ) 
       AND T1."StornoToTr" IS NULL 
       AND NOT EXISTS (SELECT T0.* 
                       FROM   "OJDT" U0 
                       WHERE  U0."StornoToTr" = T1."TransId") 
	   AND MAP(:dspOpnItms, 'Y', 1, ( ( ( YEAR (:dunningDate) - YEAR (IFNULL (T0."LvlUpdDate",T0."DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )* T3."MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL (T0."LvlUpdDate",T0."DueDate"))) )	-T7."EffctAftr"	) > 0
		
		AND (:UseBranches = 'N' OR T0."BPLId" IN 
		(
			SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
		))
;

dunning_je_pre =
SELECT 

"CardCode",
"CardName",
"DunningCode",
"DocCur",
CASE WHEN ( ( ( YEAR (:dunningDate) - YEAR (IFNULL ("LvlUpdDate","DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL ("LvlUpdDate","DueDate"))) )* "MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL ("LvlUpdDate","DueDate"))) ) -"EffctAftr" > 0 THEN "DunnLevel"
		ELSE "DunnLevel" -1
END
AS "DunnLevel",
"TransType" AS "ObjType", 
"TransId" AS "DocNum",
"Line_ID" AS "InstlmntID",
"DueDate",
"LvlUpdDate" AS "LastLevelUpdateDate",
"DunDate" AS "LastDunningDate",

CASE WHEN ( ( ( YEAR (:dunningDate) - YEAR (IFNULL ("LvlUpdDate","DueDate"))) * 12 + 
		( MONTH (:dunningDate) - MONTH (IFNULL ("LvlUpdDate","DueDate"))) )* "MonthDays" + 
		EXTRACT (DAY FROM :dunningDate) - EXTRACT (DAY FROM (IFNULL ("LvlUpdDate","DueDate"))) ) -"EffctAftr" > 0 
	THEN :dunningDate ELSE NULL
END
AS "NewLvlUpdDate",

ROUND("Debit"-"Credit",:priceDec)
AS "DocAmountLC",

ROUND("FCDebit"-"FCCredit",:priceDec)
AS "DocAmountFC",

ROUND(
CASE 
WHEN MAX("Debit") > 0
THEN ("BalDueDeb" + SUM("AppliedAfterDunningLC")) 
ELSE -MAX("BalDueCred")
END
,:priceDec)
AS "OpenAmountLC",

ROUND(
CASE 
WHEN MAX("FCDebit") > 0
THEN ("BalFcDeb" + SUM("AppliedAfterDunningFC")) 
ELSE -MAX("BalFcCred")
END
,:priceDec)
AS "OpenAmountFC",

CASE 
WHEN "RemIntrst" = 'N' AND MAX ("RemIntrstAmountFC" ) <> 0  THEN NULL
ELSE "InterDays"
END
AS "InterestDays",

ROUND(
CASE 
WHEN ("RemIntrst" = 'N' AND MAX ("RemIntrstAmountFC" ) <> 0 ) OR "InterDays"<=0 THEN NULL
ELSE

CASE 
WHEN MAX("Debit")> 0 OR MAX("FCDebit") > 0
THEN "YearlyRate" * "InterDays" / "YearDays" 
ELSE NULL
END 

END
,:percentDec)
AS "Interest",

ROUND(
CASE
WHEN MIN("Credit") > 0 OR MIN("FCCredit") >0 OR "InterDays"<=0 THEN NULL
ELSE

CASE 
WHEN "CalcIntrst" = 'N' THEN 0
ELSE 
	CASE WHEN IFNULL("FCDebit",0) = 0 THEN	("BalDueDeb" + SUM("AppliedAfterDunningLC")) * "YearlyRate" * "InterDays" / "YearDays" / 100 + SUM ("RemIntrstAmountLC" )
	ELSE CASE WHEN "Rate" = 0 THEN ("BalDueDeb" + SUM("AppliedAfterDunningLC")) * "YearlyRate" * "InterDays" / "YearDays" / 100 + SUM ("RemIntrstAmountLC" )
		ELSE (("BalFcDeb" + SUM("AppliedAfterDunningFC")) * "YearlyRate" * "InterDays" / "YearDays" / 100 + SUM ("RemIntrstAmountFC" ))* map(:directRate,'Y', "Rate", 1/"Rate")	END
	END
END 

END
,:priceDec)
AS "InterestAmountLC" ,

ROUND(
CASE
WHEN MIN("Credit") > 0 OR MIN("FCCredit") >0 OR "InterDays"<=0 THEN NULL
ELSE

CASE 
WHEN "CalcIntrst" = 'Y'
THEN ("BalFcDeb" + SUM("AppliedAfterDunningFC")) * "YearlyRate" * "InterDays" / "YearDays" / 100 + SUM ("RemIntrstAmountFC" )
ELSE 0
END 

END
,:priceDec)
AS "InterestAmountFC" ,

"GrpMethod" , 

"Fee" ,
ROUND (
CASE
WHEN MIN("Credit") > 0 OR MIN("FCCredit") >0 THEN 0
ELSE
MAP("FeeCurr" , :mainCurncy , "Fee" ,
	MAP (:directRate, 'Y', "Fee" * (SELECT "Rate" FROM ORTT WHERE "Currency" = "FeeCurr" AND "RateDate" = :dunningDate ),  "Fee" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "FeeCurr" AND "RateDate" = :dunningDate ))
	)
	
END	,:priceDec ) AS "FeeLC", 

0 AS "FeeFC" , "AutoPost", "YearDays", "YearlyRate", "LetterFrmt", 

CASE WHEN "DunnLevel" > 0 THEN  "MinBalance" ELSE 0 END as "OrigMinBalance", 

ROUND (
CASE WHEN "MinBlnCurr" = :mainCurncy THEN "MinBalance" 
ELSE MAP (:directRate, 'Y', "MinBalance"* (SELECT "Rate" FROM ORTT WHERE "Currency" = "MinBlnCurr" AND "RateDate" = :dunningDate ),  "MinBalance" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "MinBlnCurr" AND "RateDate" = :dunningDate ))
END,:priceDec ) AS "MinBalance", 

"TransId" AS "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBlnCurr",
"BpCode2", "CardName2", "Comment", "BPLId"

FROM :dunning_je

GROUP BY "CardCode","CardName","DunningCode","DocCur","DocRate","FeeCurr","OrigFee", "MinBlnCurr","TransId" ,"TransType", "Line_ID","GrpMethod", "Rate", "DunningRate", "RemIntrst","DunnLevel", "Debit","Credit","FCDebit","FCCredit",
 "DueDate","DunDate","LvlUpdDate","DunnLevel", "CalcIntrst", "BalDueDeb", "BalFcDeb", "YearlyRate", "InterDays", "YearDays", "Fee" , "AutoPost", "LetterFrmt", "MinBalance","MonthDays","EffctAftr", "BpCode2", "CardName2", "Comment", "BPLId"
--  "AutoPost", "YearDays", "YearlyRate", "LetterFrmt"
;	
-- SELECT * FROM :dunning_je_pre;

dunning_je_out = 

SELECT 
"CardCode", "CardName", "DunningCode",  "DocCur",  
CASE WHEN bpType = 'S' THEN 0 ELSE "DunnLevel" END AS "DunnLevel", "ObjType", "DocNum", "InstlmntID", 
"DueDate", "LastLevelUpdateDate", "LastDunningDate",  "NewLvlUpdDate", 
cast("DocAmountLC" as DECIMAL(21,6)) as "DocAmountLC", cast("DocAmountFC" as DECIMAL(21,6)) as "DocAmountFC", cast("OpenAmountLC" as DECIMAL(21,6)) as "OpenAmountLC", cast("OpenAmountFC" as DECIMAL(21,6)) as "OpenAmountFC", "InterestDays", cast("Interest" as DECIMAL(21,6)) as "Interest", cast("InterestAmountLC" as DECIMAL(21,6)) as "InterestAmountLC",  cast("InterestAmountFC" as DECIMAL(21,6)) as "InterestAmountFC", 
"GrpMethod" ,  cast("FeeLC" as DECIMAL(21,6)) as  "FeeLC",  
cast(
MAP("FeeCurr", "DocCur", "Fee", 
ROUND (
MAP("DocCur" , :mainCurncy , 0 ,
	MAP (:directRate, 'Y', "FeeLC" / (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ),  "FeeLC" * (SELECT "Rate" FROM ORTT WHERE "Currency" = "DocCur" AND "RateDate" = :dunningDate ))
	),:priceDec ) 
)
as DECIMAL(21,6))
AS "FeeFC", 
"AutoPost" ,  "YearDays",  "YearlyRate",  "LetterFrmt" , "OrigMinBalance", cast("MinBalance" as DECIMAL(21,6)) as "MinBalance",  "DocEntry", "DocRate", "FeeCurr", "OrigFee", "MinBlnCurr" AS "MinBalCurr", 
CASE WHEN "DunnLevel" > 0 THEN MAP("NewLvlUpdDate", NULL, 'N', 'Y') ELSE 'N' END AS "LevelUpdated", 

"BpCode2" AS "BpCode2", bpType AS "BpType", "CardName2", "Comment", "BPLId"

FROM :dunning_je_pre
;

END;

-- B1 DEPENDS: AFTER:SP:DWZ_CREATE_OBJECTS AFTER:SP:DWZ_JE AFTER:PT:PROCESS_END

CREATE PROCEDURE DWZ_VENDOR_DOC (
IN pagingID NVARCHAR(100),
OUT dunning_vendor_out DWZ_REPORT_OUT
) LANGUAGE SQLSCRIPT AS 
docDate NVARCHAR(20);
dueDate NVARCHAR(20);
dunningDate NVARCHAR(20);
crdtNBased NVARCHAR(1);
payNoBased NVARCHAR(1);
manualJEs NVARCHAR(1);
UseBranches NVARCHAR(1);
BEGIN 

SELECT "Value" INTO crdtNBased FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'CrdtNBased';
SELECT "Value" INTO payNoBased FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'PayNoBased';
SELECT "Value" INTO manualJEs FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'ManualJEs';

SELECT "Value" INTO docDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'docDate' ;
SELECT "Value" INTO dueDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dueDate' ;
SELECT "Value" INTO dunningDate FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'dunningDate' ;

SELECT "Value" INTO UseBranches FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" = 'UseBranches' ;

dunning_pch =
SELECT
T2."CardCode" AS "CardCode",
T2."CardName" AS "CardName",
T3."TermCode" AS "DunningCode",
T0."DocCur" AS "DocCur",
0 AS "DunnLevel", 
T0."ObjType" AS "ObjType", 
T0."DocNum" AS "DocNum",
cast(T1."InstlmntID" as INTEGER) AS "InstlmntID",
T1."DueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate",
-T1."InsTotal" AS "DocAmountLC",
-T1."InsTotalFC" AS "DocAmountFC",
cast(-(T1."InsTotal" - T1."PaidToDate") as DECIMAL(21,6)) AS "OpenAmountLC",
cast(-(T1."InsTotalFC" - T1."PaidFC") as DECIMAL(21,6)) AS "OpenAmountFC",
0 AS "InterestDays",
cast(0 as DECIMAL(21,6)) AS "Interest",
cast(0 as DECIMAL(21,6)) AS "InterestAmountLC",
cast(0 as DECIMAL(21,6)) AS "InterestAmountFC",
T3."GrpMethod" AS "GrpMethod", cast(0 as DECIMAL(21,6)) AS "FeeLC",cast(0 as DECIMAL(21,6)) AS "FeeFC" ,  T3."AutoPost" AS "AutoPost", cast(0 as SMALLINT) AS "YearDays",cast(0 as DECIMAL(21,6)) AS "YearlyRate",  
T3."LetterFrmt" AS "LetterFrmt",cast(0 as DECIMAL(21,6)) AS "OrigMinBalance",cast(0 as DECIMAL(21,6)) AS "MinBalance",  T0."DocEntry" AS "DocEntry", 
T0."DocRate" AS "DocRate", T3."FeeCurr" AS "FeeCurr" , T3."TotalFee" AS "OrigFee" , T3."BalCurr" AS "MinBalCurr", cast('N' as NVARCHAR(1)) AS "LevelUpdated", 
T0."CardCode" AS "BpCode2", cast('S' as NVARCHAR(1)) AS "BpType", T5."CardName" AS "CardName2", T0."Comments" AS "Comment", T0."BPLId" AS "BPLId"
FROM "OPCH" T0 
INNER JOIN "PCH6" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN "OCRD" T2 ON T0."CardCode" = T2."ConnBP"
INNER JOIN "TMP_DWZ_CRD" T4 ON T4."CardCode" = T2."CardCode"
INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm"
INNER JOIN "OCRD" T5 ON T0."CardCode" = T5."CardCode" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND T0."CANCELED" = ( 'N' ) 
AND T1."Status" = ( 'O' ) 
AND T1."DunWizBlck" = ( 'N' ) 
AND T0."BlockDunn" = ( 'N' ) 
AND T0."TransId" <> ( 0 )
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))
 ;

dunning_dpo =
SELECT
T2."CardCode" AS "CardCode",
T2."CardName" AS "CardName",
T3."TermCode" AS "DunningCode",
T0."DocCur" AS "DocCur",
0 AS "DunnLevel", 
T0."ObjType" AS "ObjType", 
T0."DocNum" AS "DocNum",
cast(T1."InstlmntID" as INTEGER) AS "InstlmntID",
T1."DueDate" AS "DueDate",
cast(NULL as TIMESTAMP) AS "LastLevelUpdateDate",
cast(NULL as TIMESTAMP) AS "LastDunningDate",
cast(NULL as TIMESTAMP) AS "NewLvlUpdDate",
-T1."InsTotal" AS "DocAmountLC",
-T1."InsTotalFC" AS "DocAmountFC",
cast(-(T1."InsTotal" - T1."PaidToDate") as DECIMAL(21,6)) AS "OpenAmountLC",
cast(-(T1."InsTotalFC" - T1."PaidFC") as DECIMAL(21,6)) AS "OpenAmountFC",
0 AS "InterestDays",
cast(0 as DECIMAL(21,6)) AS "Interest",
cast(0 as DECIMAL(21,6)) AS "InterestAmountLC",
cast(0 as DECIMAL(21,6)) AS "InterestAmountFC",
T3."GrpMethod" AS "GrpMethod",cast(0 as DECIMAL(21,6)) AS "FeeLC",cast(0 as DECIMAL(21,6)) AS "FeeFC" ,  T3."AutoPost" AS "AutoPost",cast(0 as SMALLINT) AS "YearDays",cast(0 as DECIMAL(21,6)) AS "YearlyRate",  
T3."LetterFrmt" AS "LetterFrmt", 0 AS "OrigMinBalance", cast(0 as DECIMAL(21,6)) AS "MinBalance",  T0."DocEntry" AS "DocEntry", 
T0."DocRate" AS "DocRate", T3."FeeCurr" AS "FeeCurr" , T3."TotalFee" AS "OrigFee" , T3."BalCurr" AS "MinBalCurr", cast('N' as NVARCHAR(1)) AS "LevelUpdated", 
T0."CardCode" AS "BpCode2", cast('S' as NVARCHAR(1)) AS "BpType", T5."CardName" AS "CardName2", T0."Comments" AS "Comment", T0."BPLId" AS "BPLId"
FROM "ODPO" T0 
INNER JOIN "DPO6" T1 ON T1."DocEntry" = T0."DocEntry" 
INNER JOIN "OCRD" T2 ON T0."CardCode" = T2."ConnBP"
INNER JOIN "TMP_DWZ_CRD" T4 ON T4."CardCode" = T2."CardCode"
INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm"
INNER JOIN "OCRD" T5 ON T0."CardCode" = T5."CardCode" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
AND T0."DocDueDate" <= ( MAP (LENGTH (:dueDate) , 0, T0."DocDueDate", TO_TIMESTAMP(:dueDate, 'YYYYMMDD') ) ) 
AND T0."CANCELED" = ( 'N' ) 
AND T1."Status" = ( 'O' ) 
AND T1."DunWizBlck" = ( 'N' ) 
AND T0."BlockDunn" = ( 'N' ) 
AND T0."TransId" <> ( 0 )
AND (:UseBranches = 'N' OR T0."BPLId" IN 
(
	SELECT CAST ("Value" as INTEGER) FROM "SPPP" WHERE "PagingID" = :pagingID AND "Name" LIKE 'BranchList%'
))
 ;

