INNER JOIN "ODUT" T3 ON T3."TermCode" = T2."DunTerm"
INNER JOIN "OCRD" T5 ON T0."CardCode" = T5."CardCode" 
WHERE 
T0."DocDate" <= ( MAP (LENGTH (:docDate) , 0, T0."DocDate", TO_TIMESTAMP(:docDate, 'YYYYMMDD') ) ) 
