CREATE PROCEDURE SBO_SP_TransactionNotification
(
	in object_type nvarchar(30), 				-- SBO Object Type
	in transaction_type nchar(1),			-- [A]dd, [U]pdate, [D]elete, [C]ancel, C[L]ose
	in num_of_cols_in_key int,
	in list_of_key_cols_tab_del nvarchar(255),
	in list_of_cols_val_tab_del nvarchar(255)
)
LANGUAGE SQLSCRIPT
AS
-- Return values
error  int;				-- Result (0 for no error)
error_message nvarchar (200); 		-- Error string to be displayed
begin

error := 0;
error_message := N'Ok';

--------------------------------------------------------------------------------------------------------------------------------

--	ADD	YOUR	CODE	HERE

--------------------------------------------------------------------------------------------------------------------------------
IF :transaction_type IN ('A','U') AND :object_type = 'MTC_AI_AGENT_USER' THEN
    DECLARE U_SlpCode INT;
    DECLARE U_SlpName NVARCHAR(100);
    DECLARE U_RoleId INT;
    DECLARE U_RoleName NVARCHAR(100);
    DECLARE cnt INT;
    
    IF :transaction_type = 'U' THEN  -- 更新操作
        -- 根据主键查询
        SELECT "U_SlpCode", "U_SlpName", "U_RoleId", "U_RoleName"
        INTO U_SlpCode, U_SlpName, U_RoleId, U_RoleName
        FROM "@MTC_AI_AGENT_USER"
        WHERE "Code" = :list_of_cols_val_tab_del;
    END IF;
    
    -- 如果是新增操作，U_SlpCode 和 U_RoleId 需要从其他参数获取
    -- 需要根据实际业务逻辑从输入参数中获取值
    
    -- 验证是否存在
    IF U_SlpCode IS NOT NULL AND U_RoleId IS NOT NULL THEN
        IF :transaction_type = 'A' THEN
            -- 新增：检查整个表中是否存在相同组合
            SELECT COUNT(*) INTO cnt
            FROM "@MTC_AI_AGENT_USER"
            WHERE "U_SlpCode" = U_SlpCode
              AND "U_RoleId" = U_RoleId;
        ELSEIF :transaction_type = 'U' THEN
            -- 更新：检查除自身外是否存在相同组合
            SELECT COUNT(*) INTO cnt
            FROM "@MTC_AI_AGENT_USER"
            WHERE "U_SlpCode" = U_SlpCode
              AND "U_RoleId" = U_RoleId
              AND "Code" != :list_of_cols_val_tab_del;
        END IF;
        
        -- 如果存在重复
        IF cnt > 0 THEN
            error := '01';
            error_message := 'Error: Salesperson ' || U_SlpName || 
                           ' already exists in the role ' || U_RoleName || '！';
        END IF;
    END IF;
END IF;
-- Select the return values
select :error, :error_message FROM dummy;

end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

