      SELECT s_pp."SCHEMA_NAME", s_pp."PROCEDURE_NAME", s_pp."PARAMETER_NAME", s_pp."DATA_TYPE_ID", s_pp."DATA_TYPE_NAME", s_pp."LENGTH", s_pp."PARAMETER_TYPE"
