Create PROCEDURE TmSp_ArcIVIDBHealthCheck
(
in USD_Rate DECIMAL(21,6),
out ret integer
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	v_Difference DECIMAL(32,6);
	v_notIncludedDocs DECIMAL(21,6);
	v_CurrentConsistency nvarchar(1);
	v_PreviousFix nvarchar(1);
	v_isPricePerWH nvarchar(1);
	v_CandidateForService nvarchar(1);
	v_isPerpetual nvarchar(1);
	v_CountPeviousUpdateDate integer;
	v_sumdec integer;
	v_Pricedec integer;
	v_IncStckSettings DECIMAL(32,6);
	v_cnt DECIMAL(21,6);
	v_cnt1 DECIMAL(21,6);
	v_cnt2 DECIMAL(21,6);
	v_exists varchar(100);
	v_flag TINYINT;
	v_USD_Rate DECIMAL(21,6);
BEGIN
ret := -100;
select "PriceDec" INTO v_Pricedec from oadm;
select top 1 "PriceSys" into v_isPricePerWH from OADM;
select ifnull(avg("Rate"),1) into v_USD_Rate from ortt where "Currency" = 'USD';

select count(*) into v_cnt from OADM where "ContInvnt" = 'N';
if :v_cnt = 1 then
	ret := 1;
end if;
	
------------------------------End Perpetual Inventory verification--------------------------------------

--------------------------------Historical data verification------------------------------------------


select distinct "Version" into v_cnt  from cinf;
IF :v_cnt < 880220  and :ret = -100 then

	create table ToStock (act nvarchar (20), trans DECIMAL(21,6));
	insert into ToStock	
	select "PriceDifAc", sum (IFNULL("PriceDiff",0)) from OINM group by "PriceDifAc" having  sum (IFNULL("PriceDiff",0)) <> 0
	Union
	select "VarianceAc", sum (IFNULL("VarVal",0)) from OINM group by "VarianceAc" having sum (IFNULL("VarVal",0)) <> 0
	Union
	select "ExcRateAct", sum (IFNULL("ExchDiff",0)) from OINM group by "ExcRateAct" having sum (IFNULL("ExchDiff",0)) <> 0 
	Union
	select "TrnsfrAct", sum (IFNULL("Allocation",0)) from OINM group by "TrnsfrAct" having sum (IFNULL("Allocation",0)) <> 0 
	Union
	select "CostAct", sum (IFNULL("CogsVal",0)) from OINM group by "CostAct" having sum (IFNULL("CogsVal",0)) <> 0 
	Union
	select "WipAct", sum (IFNULL("WipVal",0)) from OINM group by "WipAct" having sum (IFNULL("WipVal",0)) <> 0 
	Union
	select "WipVarAcc", sum (IFNULL("WipVarVal",0)) from OINM group by "WipVarAcc" having sum (IFNULL("WipVarVal",0)) <> 0 
	Union
	select "NegStckAct", sum (IFNULL("NegInvAdjs",0)) from OINM group by "NegStckAct" having sum (IFNULL("NegInvAdjs",0)) <> 0 
	Union
	select "IOffIncAcc", sum (IFNULL("IOffIncVal",0)) from OINM group by "IOffIncAcc" having sum (IFNULL("IOffIncVal",0)) <> 0 
	Union
	select "DOffDecAcc", sum (IFNULL("DOffDecVal",0)) from OINM group by "DOffDecAcc" having sum (IFNULL("DOffDecVal",0)) <> 0 
	Union
	select "DecAcc", sum (IFNULL("DecVal",0)) from OINM group by "DecAcc" having sum (IFNULL("DecVal",0)) <> 0 
	Union
	select "IncAct", sum (IFNULL("IncVal",0)) from OINM group by "IncAct" having sum (IFNULL("IncVal",0)) <> 0 ;
	--select * from tostock

	create table stacts	(stact nvarchar (20));
	insert into stacts select distinct "InvntAct" from OINM where "InvntAct" is not NULL and "InvntAct" <> '';
	
	select IFNULL(abs(sum (t0.trans)) , 0) into v_IncStckSettings
	from ToStock T0 inner join stacts T1
	on t0.act = t1.stact;
	
	drop table ToStock;
	drop table stacts;
		
	select abs(SUM(IFNULL(t0.sumTransVal,0) - IFNULL(t1.sumPosting,0))) into v_Difference
	from
		(select 
			"InvntAct",
			"TransType",
			"CreatedBy",
			"BASE_REF",
			"DocDate",
			sum("TransValue") sumTransVal
		from
			oinm
		where
			"TransValue" <> 0 
		group by
			"InvntAct",
			"TransType",
			"CreatedBy",
			"BASE_REF",
			"DocDate") t0
		Full Outer Join
		(select
			"Account",
			"TransType",
			"CreatedBy",
			"RefDate",
			sum("Debit") - sum("Credit") sumPosting
		from
			jdt1
		where
			"Account" in (select distinct "InvntAct" from oinm)
			and "TransType" in (select distinct "TransType" from oinm union select 58 from dummy) and "TransType" <> -2
		group by
			"Account",
			"RefDate",
			"TransType", 
			"CreatedBy") t1
	on
		t0."CreatedBy" = t1."CreatedBy" and 
		t0."InvntAct" = t1."Account" and
		t0."TransType" = t1."TransType";


	--------------------------------END Historical data verification------------------------------------------

	--------------------------------Current Data consistency verification-------------------------------------
	
	IF :v_isPricePerWH = 'Y' then 
		v_flag := 0;

		select top 1 TransValue into v_cnt from (select abs(sum("TransValue")) as TransValue from oinm
		group by "ItemCode", "Warehouse"
		having 
		(
		(sum("InQty"-"OutQty") = 0 and sum("TransValue")<> 0) or 
		(sum("InQty"-"OutQty") > 0 and sum("TransValue") < 0) or 
		(sum("InQty"-"OutQty") < 0 and sum("TransValue") > 0)) union select 0 from dummy) a 
		order by TransValue desc;
		
			
		
		if :v_cnt > 1 then 
			v_flag := 1;
		end if;
		/* end TESTING 2007 per whs: zero QTY/nonzero stockvalue OR negative QTY/positive stockvalue OR positive QTY/negative stockvalue */ 

		SELECT
			IFNULL(sum(abs(t0.trans - t1."StockValue")),0) into v_cnt
		From
			(SELECT sum("TransValue") Trans, "ItemCode", "Warehouse"  FROM OINM GROUP BY "ItemCode", "Warehouse") t0,
			(SELECT "StockValue", "ItemCode", "WhsCode" FROM OITW) t1,
			OITM t2
		WHERE
			t0."ItemCode" = t1."ItemCode" 
			and t0."ItemCode" = t1."WhsCode"
			and t2."ItemCode" = t0."ItemCode"
			and t2."EvalSystem" in ('A')
			and abs(t0.Trans - t1."StockValue") > 0.1;
	
		if :v_cnt/:v_USD_Rate > 100 then 
			v_flag := 1;
		end if;
			
		SELECT 
			IFNULL(sum(abs(t2.Trans)),0) into v_cnt
		FROM
			(SELECT 
				sum(t0."TransValue") Trans,
				sum(t0."OpenValue") OpenVal, 
				t0."ItemCode", 
				t0."Warehouse" 
			FROM
				OINM t0,
				OITM t1
			WHERE
				t1."ItemCode" = t0."ItemCode" 
				and t1."EvalSystem" = 'F'
			GROUP BY 
				t0."ItemCode", 
				t0."Warehouse" 
			HAVING
				abs(sum(t0."TransValue") - sum(t0."OpenValue")) > 0.1 and sum(t0."InQty")-sum(t0."OutQty") >= 0) t2;
				
		if :v_cnt/:v_USD_Rate > 100 then 
			v_flag := 1;
		end if;
				
		IF :v_flag = 1 THEN 
			/* start TESTING 2007 per whs: zero QTY/nonzero stockvalue OR negative QTY/positive stockvalue OR positive QTY/negative stockvalue */ 
			v_CurrentConsistency := 'N';  --affected
		ELSE
			v_CurrentConsistency := 'Y';  --not affected
		END IF;	
	END IF; -- v_isPricePerWH = 'Y'

	IF :v_isPricePerWH = 'N' then
	
		select top 1 TransValue into v_cnt from (select abs(sum("TransValue")) as TransValue from oinm
		group by "ItemCode"
		having 
		(
		(sum("InQty"-"OutQty") = 0 and sum("TransValue")<> 0) or 
		(sum("InQty"-"OutQty") > 0 and sum("TransValue") < 0) or 
		(sum("InQty"-"OutQty") < 0 and sum("TransValue") > 0)) union select 0 from dummy) a 
		order by TransValue desc;			
			
		if :v_cnt > 1 then 
			v_flag := 1;
		end if;
							
		SELECT
			IFNULL(sum(abs(t0.trans - t1."StockValue")),0) INTO v_cnt
		FROM
			(SELECT sum("TransValue") Trans, "ItemCode"  FROM OINM GROUP BY "ItemCode") t0,
			(SELECT "StockValue", "ItemCode" FROM OITM) t1,
			OITM t2
		WHERE
			t0."ItemCode" = t1."ItemCode" 
			and t2."ItemCode" = t0."ItemCode"
			and t2."EvalSystem" in ('A')
			and abs(t0.Trans - t1."StockValue") > 0.1;
		
		if :v_cnt/:v_USD_Rate > 100 then 
			v_flag := 1;
		end if;

		SELECT 
			IFNULL(sum(abs(t2.Trans)),0) into v_cnt
		FROM
			(SELECT 
				sum(t0."TransValue") Trans,
				sum(t0."OpenValue") OpenVal, 
				t0."ItemCode"
			FROM
				OINM t0,
				OITM t1
			WHERE
				t1."ItemCode" = t0."ItemCode" 
				and t1."EvalSystem" = 'F'
			GROUP BY 
				t0."ItemCode"
			HAVING
				abs(sum(t0."TransValue") - sum(t0."OpenValue")) > 0.1 and sum(t0."InQty")-sum(t0."OutQty") >= 0) t2;
				
		if :v_cnt/:v_USD_Rate > 100 then 
			v_flag := 1;
		end if;	
	
		IF :v_flag = 1 then
			/* Zero QTY/nonzero stockvalue OR negative QTY/positive stockvalue OR positive QTY/negative stockvalue */ 
			v_CurrentConsistency := 'N';  --affected
		ELSE
			v_CurrentConsistency := 'Y';  --not affected
		END IF;		 
	END IF; --v_isPricePerWH 
	--------------------------------END Current Data consistency verification-------------------------------------

	--------------------------------Previous fix verification----------------------------------------------------
	
	
	SELECT count(*) into v_cnt FROM "PUBLIC".tables where table_name = 'IVLG' and schema_name = current_schema;
	IF :v_cnt = 0 then
		v_PreviousFix := 'N';
	ELSE
		create local temporary table #IVLG (cnt integer);
		exec ('INSERT INTO #IVLG SELECT count(*) FROM IVLG WHERE CustDBupd=''Y''');
		SELECT cnt into v_cnt FROM #IVLG;
		if :v_cnt > 0 then
			v_PreviousFix := 'Y';
		else 
			v_PreviousFix := 'N';	
		end if;
		drop table #IVLG;
	End IF; 

	--------------------------------------------------------------------------------------------------------------

	--output results

	if ((abs((:v_Difference - :v_IncStckSettings)/ :v_USD_Rate) > 1000
				   AND :v_previousfix = 'N')
				 or :v_CurrentConsistency = 'N')  then
	
	-- Must run IVI before DA
	-- Database is candidate for the Inventory valuation Check-up service (Need to run Stock Tool)
		ret := -1;
	Else
		-- DA can be proceed
		-- Database is healthy
		ret := 0;
	end if;


--------------------------------------------------------------------------------------------------------------

END IF; -- <880220

--------------------------------------------------------------------------------------------------------------

---------------88 SCRIPT-------------------------------
select distinct "Version" into v_cnt from cinf;
IF :v_cnt >= 880220 and :ret = -100 then 
	--------------------------------Historical data verification------------------------------------------
	create table ToStock (act nvarchar (20), trans DECIMAL(21,6));
	insert into ToStock
	select "PriceDifAc", sum (IFNULL("PriceDiff",0)) from oivl group by "PriceDifAc" having  sum (IFNULL("PriceDiff",0)) <> 0
	Union
	select "VarianceAc", sum (IFNULL("VarVal",0)) from oivl group by "VarianceAc" having sum (IFNULL("VarVal",0)) <> 0
	Union
	select "ExcRateAct", sum (IFNULL("ExchDiff",0)) from oivl group by "ExcRateAct" having sum (IFNULL("ExchDiff",0)) <> 0 
	Union
	select "TrnsfrAct", sum (IFNULL("Allocation",0)) from oivl group by "TrnsfrAct" having sum (IFNULL("Allocation",0)) <> 0 
	Union
	select "CostAct", sum (IFNULL("CogsVal",0)) from oivl group by "CostAct" having sum (IFNULL("CogsVal",0)) <> 0 
	Union
	select "WipAct", sum (IFNULL("WipVal",0)) from oivl group by "WipAct" having sum (IFNULL("WipVal",0)) <> 0 
	Union
	select "WipVarAcc", sum (IFNULL("WipVarVal",0)) from oivl group by "WipVarAcc" having sum (IFNULL("WipVarVal",0)) <> 0 
	Union
	select "NegStckAct", sum (IFNULL("NegInvAdjs",0)) from oivl group by "NegStckAct" having sum (IFNULL("NegInvAdjs",0)) <> 0 
	Union
	select "IOffIncAcc", sum (IFNULL("IOffIncVal",0)) from oivl group by "IOffIncAcc" having sum (IFNULL("IOffIncVal",0)) <> 0 
	Union
	select "DOffDecAcc", sum (IFNULL("DOffDecVal",0)) from oivl group by "DOffDecAcc" having sum (IFNULL("DOffDecVal",0)) <> 0 
	Union
	select "DecAcc", sum (IFNULL("DecVal",0)) from oivl group by "DecAcc" having sum (IFNULL("DecVal",0)) <> 0 
	Union
	select "IncAct", sum (IFNULL("IncVal",0)) from oivl group by "IncAct" having sum (IFNULL("IncVal",0)) <> 0
	Union
	select "PAOffAcc", sum (IFNULL("PAOffVal",0)) from oivl group by "PAOffAcc" having sum (IFNULL("PAOffVal",0)) <> 0 
	Union
	select "PAAcc", sum (IFNULL("PAVal",0)) from oivl group by "PAAcc" having sum (IFNULL("PAVal",0)) <> 0;
	--select * from tostock

	create table stacts	(stact nvarchar (20));
	insert into stacts select distinct "InvntAct" from oivl where "InvntAct" is not NULL and "InvntAct" <> '';
	--select * from stacts

	select IFNULL(abs (sum (t0.trans)) , 0) INTO v_IncStckSettings
	from ToStock T0 inner join stacts T1
	on t0.act = t1.stact;
	drop table ToStock;
	drop table stacts;

	select  abs(SUM(IFNULL(t0.sumTransVal, 0) - IFNULL(t1.sumPosting, 0))) into v_Difference
	from    ( select	"InvntAct",
						"TransType",
						"CreatedBy",
						"BASE_REF",
						"DocDate",
						sum(ivl1."TransValue") sumTransVal
			  from      oivl
						inner join ivl1 on oivl."TransSeq" = ivl1."TransSeq"
			  where     "TransValue" <> 0
			  group by  "InvntAct",
						"TransType",
						"CreatedBy",
						"BASE_REF",
						"DocDate"
			) t0
			
			Full Outer Join ( select    "Account",
										"TransType", 		
										"CreatedBy",
										"RefDate",
										sum(IFNULL("Debit", 0)) - sum(IFNULL("Credit", 0)) sumPosting
							  from      jdt1
							  where     "Account" in ( select distinct
															 "InvntAct"
													 from   OIVL )
										and "TransType" in ( select distinct
																	"TransType"
															 from   OIVL union select 58 from dummy union select 10000046 from dummy)
															 
															 -- This JE is created by Data Archive, we also should consider it.
											
										and "TransType" <> -2
							  group by  "Account",
										"RefDate",
										"TransType", 		
										"CreatedBy"
							) t1 on t0."CreatedBy" = t1."CreatedBy"
									and t0."InvntAct" = t1."Account"
									and t0."TransType" = t1."TransType";

	--------------------------------END Historical data verification------------------------------------------



	--------------------------------Current Data consistency verification-------------------------------------

	/* Check inconsistencies in stock sub ledger - Differences between stockvalue,openvalue,transvalue */
	
	if :v_isPricePerWH = 'Y' then
		v_flag := 0;
		
	/* Zero QTY/nonzero stockvalue OR negative QTY/positive stockvalue OR positive QTY/negative stockvalue */ 


		select top 1 SumStock into v_cnt from (select abs(sum("SumStock")) as SumStock from oivl
		group by "ItemCode", "LocCode"
		having 
		(
		(sum("InQty"-"OutQty") = 0 and sum("SumStock")<> 0) or 
		(sum("InQty"-"OutQty") > 0 and sum("SumStock") < 0) or 
		(sum("InQty"-"OutQty") < 0 and sum("SumStock") > 0)) union select 0 from dummy) a 
		order by SumStock desc;

		if IFNULL(:v_cnt,0) > 1 then 
			v_flag := 1;
		end if;		
		

	/* Check consistency between sum of stock postings to stock value in items master data */ 
		select SUM(IFNULL("TransValue", 0)) into v_cnt from IVL1;
		select SUM(IFNULL(T0."StockValue", 0)) into v_cnt1 from OITW T0 
			inner join OITM T1 on T0."ItemCode" = T1."ItemCode" and T1."InvntItem" = 'Y';
			 
		if abs((:v_cnt - :v_cnt1)/:v_USD_Rate) > 100 then 
			v_flag := 1;
		end if;	

	/* Check comsistency between sum of stock postings to stock value in items master data */ 
		select  SUM(IFNULL("SumStock", 0)) into v_cnt from OIVL;
		select  SUM(IFNULL(T0."StockValue", 0)) into v_cnt1 from OITW T0 
		inner join OITM T1 on T0."ItemCode" = T1."ItemCode" and T1."InvntItem" = 'Y';
			
		if abs((:v_cnt - :v_cnt1)/:v_USD_Rate) > 100 then 
			v_flag := 1;
		end if;	
			
	/* Check consistency between sum open layers value + value of items in negative zone multiplied by statis price*/
	/* to stock postings value - fifo items */ 
		select SUM(IFNULL(Q."OpenValue", 0)) into v_cnt from OIVQ Q;
			  
		select SUM(IFNULL(W."AvgPrice", 0) * IFNULL(W."OnHand", 0)) into v_cnt1 from OITW W
			inner join OITM M on W."ItemCode" = M."ItemCode"
			and M."EvalSystem" = 'F' and  M."InvntItem" = 'Y'
			and W."OnHand" < 0;
				
		select  SUM(IFNULL("SumStock", 0)) into v_cnt2 from OIVL where "CostMethod" = 'F';
			  
		if ((:v_cnt + :v_cnt1)/:v_USD_Rate) - (:v_cnt2/:v_USD_Rate) > 100 then 
			v_flag := 1;
		end if;	

		IF	:v_flag = 1 then
			v_CurrentConsistency := 'N';  --affected
		else 
			v_CurrentConsistency := 'Y';  --not affected
		end if;
		
	elseif :v_isPricePerWH = 'N' then
		v_flag := 0;
	/*Zero QTY/nonzero stockvalue OR negative QTY/positive stockvalue OR positive QTY/negative stockvalue */ 
	
		select top 1 SumStock into v_cnt from (select abs(sum("SumStock")) as SumStock from oivl
		group by "ItemCode"
		having 
		(
		(sum("InQty"-"OutQty") = 0 and sum("SumStock")<> 0) or 
		(sum("InQty"-"OutQty") > 0 and sum("SumStock") < 0) or 
		(sum("InQty"-"OutQty") < 0 and sum("SumStock") > 0)) union select 0 from dummy) a 
		order by SumStock desc;

		if IFNULL(:v_cnt,0) > 1 then 
			v_flag := 1;
		end if;	
		
		/* Check consistency between sum of stock postings to stock value in items master data */ 

		select SUM(IFNULL("TransValue", 0)) INTO v_cnt from IVL1;
		select SUM(IFNULL("StockValue", 0)) INTO v_cnt1 from OITM where "InvntItem" = 'Y';
			
		if abs((:v_cnt - :v_cnt1)/:v_USD_Rate) > 100 then 
			v_flag := 1;
		end if;	
			
		/* Check consistency between sum of stock postings to stock value in items master data */ 
		select SUM(IFNULL("SumStock", 0)) into v_cnt from OIVL;
		select SUM(IFNULL("StockValue", 0)) into v_cnt1 from OITM where "InvntItem" = 'Y';

		if abs((:v_cnt - :v_cnt1)/:v_USD_Rate) > 100 then 
			v_flag := 1;
		end if;	

		/* Check consistency between sum open layers value + value of items in negative zone multiplied by statis price*/
		/* to stock postings value - fifo items */ 
		select SUM(IFNULL(Q."OpenValue", 0)) into v_cnt from OIVQ Q;
		
		select SUM(IFNULL(M."AvgPrice", 0) * IFNULL(M."OnHand", 0)) into v_cnt1
		  from   OITM M
		  where  M."EvalSystem" = 'F' and M."InvntItem" = 'Y'
				 and IFNULL(M."OnHand", 0) < 0;
		
		select  SUM("SumStock") into v_cnt2 from OIVL	where "CostMethod" = 'F';
		
		if ((:v_cnt + :v_cnt1)/:v_USD_Rate) - (:v_cnt2/:v_USD_Rate) > 100 then 
			v_flag := 1;
		end if;	

		IF	:v_flag = 1 then
			v_CurrentConsistency := 'N';  --affected
		else 
			v_CurrentConsistency := 'Y';  --not affected
		end if;
		
	end if; --:v_isPricePerWH = 'N' and 'Y'

			
	--------------------------------END Current Data consistency verification-------------------------------------


	--------------------------------Previous fix verification----------------------------------------------------

	select  count("UpdateDate") into v_CountPeviousUpdateDate from livi where   IFNULL("UpdateDate", '') <> '';
								  
	if :v_CountPeviousUpdateDate > 0 THEN
		v_PreviousFix := 'Y';
	else 
		v_PreviousFix := 'N';
	END IF;

	------------------------------------------------------------------------------------------------

	--output results
	if ((abs((:v_Difference - :v_IncStckSettings)/:v_USD_Rate) > 1000
				   AND :v_previousfix = 'N')
				 or :v_CurrentConsistency = 'N')  then
	
		-- Must run IVI before DA
		-- Database is candidate for the Inventory valuation Check-up service (Need to run Stock Tool)
		ret := -1;
	Else
		-- DA can be proceed
		-- Database is healthy
		ret := 0; 
	End if;
	------------------------------------------------------------------------------------------------
	
	END if; -->= 880220
	
END;

-- B1 DEPENDS: AFTER:SP:TmSp_ArcCreateDistinctTmpArc AFTER:SP:TmSp_ArcCreateIndexesForArc AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_ArcProcess(in TablePID varchar (5000))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
	--*With Encryption
AS
TmpArcName varchar(5000);
TmpArcTable  nvarchar(128);
TmpArcBackTable  nvarchar(128);
PairsArc  nvarchar(128);
StrExec VARCHAR(4000);
obj1Type  nvarchar(50);
obj2Type  nvarchar(50);
obj1Key1  nvarchar(50);
obj1Key2  nvarchar(50);
obj1Key3  nvarchar(50);
obj1Key4  nvarchar(50);
obj1Key5  nvarchar(50);
obj1Key6  nvarchar(50);

obj2Key1  nvarchar(50);
obj2Key2  nvarchar(50);
obj2Key3  nvarchar(50);
obj2Key4  nvarchar(50);
obj2Key5  nvarchar(50);
obj2Key6  nvarchar(50);

ClusterID1 int;
ClusterID2 int;

temp_var1 INT;
temp_var2 INT;
sql1 nvarchar(1000);
tmpClusterId INT;

-----------------------------20120420--------------------------------------------
--cannot use cursor here, because table "TDAP_B" does not exist, cursor will be replaced by loop temporary table, later in this procedure
--CURSOR  PairCursor FOR
--SELECT  distinct "obj1Type","obj1Key1","obj1Key2","obj1Key3","obj1Key4","obj1Key5","obj1Key6","obj2Type","obj2Key1","obj2Key2","obj2Key3","obj2Key4","obj2Key5","obj2Key6" from TDAP_B; -- edge
---------------------------------------------------------------------------------
next INT := 1;
NumOfCluster int;
NumOfCluster1 int;
index int;
index1 int;
i int;

BEGIN

-----------------------------------------------
-- Author:		<Schneider Boaz>
-- Create date: <Oct 26,2008>
-- Description:	<Procedure for clustering process>
--		Called after filling temporary data tables ##TDAR_<pId>
--		and ##TDAP_<pId>
--		Searches connections between the objects and marks all connected components with the same cluster number.
-- TMP tables names have changed due to problems in the code, with the number of characters (5.3.2009):
--	##TMP_ARC_<pid> to ##TDAR_<pid>
--	##ARC_MSSQL_PAIRS_<pid> to ##TDAP_<pid>
-----------------------------------------------

	--Vocabulary:
	--Vertex - is an object, for example Invoice No 50
	--Cluster - is group og objects connected with each others
	--Edge - Two connected objects
	--Note! The procedure based on the Korman's "Connected components" algorythm.

	-- Call to store procedure that do distinct to duplicate rows in tmp arc
	
--Parameters validation for security issues
call _TmSp_ValidateSpParam(:TablePID);

TmpArcName := '##TDAR_' || :TablePID;

call TmSp_ArcCreateDistinctTmpArc (:TmpArcName);--ODKOMENTOVAT

	
--SET NOCOUNT ON;

-- Call to procedure that create indexes and insert value instead of null in tmp arc and TDAP 
-- (for better performance)
-- It will get process id  and create permannent table from temp table ('##TDAR_' & '##TDAP_' )
delete from "TMP_ArcProcess_WithId";
--table created in TmSp_ArcCreateIndexesForArc, so have to created first in this procedure.
create global temporary column table BACKUP_TDAR_B(Line_ID int,DocType varchar(10),"DocNum" int,"DocAbs" int, "Total" int,"RefDate" date,"ClusterId" int,"Remarks" varchar(100),"CanArcObj" varchar(10),
     "CanArcClus" int,KeySeg1 varchar(100),KeySeg2 varchar(100),KeySeg3 varchar(10),KeySeg4 varchar(10),KeySeg5 varchar(10),KeySeg6 varchar(10),
	 KeySeg7 varchar(10),KeySeg8 varchar(10),KeySeg9 varchar(10),KeySeg10 varchar(10),"Series" varchar(100),"DocSubType" int,PIndicator varchar(10),
	 "Instance" varchar(10),Segment varchar(10));
	 
call TmSp_ArcCreateIndexesForArc (:TablePID,:TmpArcTable,:TmpArcBackTable);--ODKOMENTOVAT
sql1 :='select top 1 "TMPARCTABLENAME" into TmpArcTable from ARC_TAB';
exec(:sql1);
sql1 :='select top 1 "TMPARCBACKTABLENAME" into TmpArcBackTable  from ARC_TAB';
exec(:sql1);
--insert into TAB(TmpArcTableName,TmpArcBackTableName) values (1,2);
--select * from TAB;

PairsArc := 'TDAP_B';
	
obj1Key1 := 0;
obj1Key2 := 0;
obj1Key3 := 0;
obj1Key4 := 0;
obj1Key5 := 0;
obj1Key6 := 0;
obj2Key1 := 0;
obj2Key2 := 0;
obj2Key3 := 0;
obj2Key4 := 0;
obj2Key5 := 0;
obj2Key6 := 0;

ClusterID1 := 0;
ClusterID2 := 0;
-- Drop the table if exists


select "TABLE_OID" into temp_var1 from "PUBLIC"."TABLES" WHERE table_name =  N'#Cluster';
IF :temp_var1 <> 0  THEN
	drop table "#Cluster";
end if;
select "TABLE_OID" into temp_var1 from "PUBLIC"."TABLES" WHERE table_name = N'#Cluster1';
IF :temp_var2 <> 0  THEN
	drop table "#Cluster1";
end if;
--IF  EXISTS (SELECT 1 FROM  tempdb.INFORMATION_SCHEMA.Tables where table_name =  N'#Cluster') drop table #Cluster
--IF  EXISTS (SELECT 1 FROM  tempdb.INFORMATION_SCHEMA.Tables where table_name =  N'#Cluster1') drop table #Cluster1


-- Cluster table holds 
-- vertexId  : A unique ID for the vertex. This is the line_Id from TEMP_ARC
-- clusterId : A unique identifier for the cluster - This is the output of the Algorithem
--DROP TABLE Cluster; 
Create Table Cluster ("ClusterID" Int,"vertexid" int);
Create Table Cluster1 ("ClusterID" Int,"vertexid" int);
--  Initiliaze Cluster with cluster id 
exec('insert into "Cluster" select LINE_ID,0  from ' || :TmpArcBackTable );

/***************************************************************************************************************/
-- Clustering Step 1:  
--------------------------------------------------------
-- run on every pair and insert into 'Cluster' table: 
-- For each vertex (left,right) in the pair:
-- vertexid  <-- the line_Id ( from ##TDAR_<PID> ) of the vetex
-- Line_id is taken from the ##TDAR_<pid> table as a consiquent  enumarator of the records
-- clusterID <-- MIN (left.line_ID, right.line_Id) 
-- The algorythm: we take a pair and create a head of the cluster. At the end all the components will point to the same head.

--CURSOR  PairCursor FOR
--SELECT  distinct "obj1Type" into obj1Type,"obj1Key1" into obj1Key1,"obj1Key2","obj1Key3","obj1Key4","obj1Key5","obj1Key6","obj2Type","obj2Key1","obj2Key2","obj2Key3","obj2Key4","obj2Key5","obj2Key6" from TDAP_B; -- edge
sql1 :='select count(*) into next from TDAP_B';
exec (:sql1);

sql1 :='CREATE SEQUENCE TEMP_TDAP_B_ID INCREMENT BY 1 START WITH 1';
exec (:sql1);

sql1 :='INSERT INTO "TMP_ArcProcess_WithId" SELECT T2.*,TEMP_TDAP_B_ID.NEXTVAL AS ID FROM (SELECT distinct "obj1Type","obj1Key1","obj1Key2","obj1Key3","obj1Key4","obj1Key5","obj1Key6","obj2Type","obj2Key1","obj2Key2","obj2Key3","obj2Key4","obj2Key5","obj2Key6" FROM TDAP_B) T2';
exec (:sql1);


/* Cursor declartion */
--DECLARE PairCursor CURSOR LOCAL FORWARD_ONLY STATIC READ_ONLY    FOR
--OPEN PairCursor;
--FETCH PairCursor INTO obj1Type,obj1Key1,obj1Key2,obj1Key3,obj1Key4,obj1Key5,obj1Key6,obj2Type,obj2Key1,obj2Key2,obj2Key3,obj2Key4,obj2Key5,obj2Key6;

IF :next > 0 THEN
	
	--FETCH PairCursor INTO obj1Type,obj1Key1,obj1Key2,obj1Key3,obj1Key4,obj1Key5,obj1Key6,obj2Type,obj2Key1,obj2Key2,obj2Key3,obj2Key4,obj2Key5,obj2Key6;
	--IF PairCursor::NOTFOUND THEN
	--	next := -1;
	--END IF;
	
	FOR i IN 0..next do
		SELECT "obj1Type","obj1Key1","obj1Key2","obj1Key3","obj1Key4","obj1Key5","obj1Key6","obj2Type","obj2Key1","obj2Key2","obj2Key3","obj2Key4","obj2Key5","obj2Key6"
		into obj1Type,obj1Key1,obj1Key2,obj1Key3,obj1Key4,obj1Key5,obj1Key6,obj2Type,obj2Key1,obj2Key2,obj2Key3,obj2Key4,obj2Key5,obj2Key6
		from "TMP_ArcProcess_WithId"
		where id=:i;
		select IFNULL(LINE_ID,0) into ClusterID1 from BACKUP_TDAR_B where DocType = :obj1Type and KeySeg1 = :obj1Key1 and KeySeg2 = :obj1Key2 and KeySeg3 = :obj1Key3 and KeySeg4 = :obj1Key4 and KeySeg5 = :obj1Key5 and KeySeg6 = :obj1Key6;
		select IFNULL(LINE_ID,0) into ClusterID2 from BACKUP_TDAR_B where DocType = :obj2Type  and KeySeg1 = :obj2Key1 and KeySeg2 = :obj2Key2 and KeySeg3 = :obj2Key3 and KeySeg4 = :obj2Key4 and KeySeg5 = :obj2Key5 and KeySeg6 = :obj2Key6;
		
		if :ClusterID1 < :ClusterID2 then
			insert into Cluster values(:ClusterID1,:ClusterID1);
			insert into Cluster values(:ClusterID1,:ClusterID2);
			
		ELSE
			insert into Cluster values(:ClusterID2,:ClusterID1);
			insert into Cluster values(:ClusterID2,:ClusterID2);
			
		END IF;
	end for;
  --FETCH PairCursor INTO obj1Type,obj1Key1,obj1Key2,obj1Key3,obj1Key4,obj1Key5,obj1Key6,obj2Type,obj2Key1,obj2Key2,obj2Key3,obj2Key4,obj2Key5,obj2Key6;
END IF;

--CLOSE PairCursor;
--DEALLOCATE PairCursor;

-- Create index on Cluster - for better performance

---------------------------------------------------------

-- delete all 1,1 ;  2,2 etc.  so it will run in recursive

delete from Cluster where "ClusterID" = "vertexid";


select distinct * from Cluster into Cluster1;
--truncate table Cluster; TRUNCATE works only for temporary tables
insert into Cluster select * from Cluster1;
delete from Cluster1;

delete from "TMP_ArcProcess_WithId";

-- End of step 1
/***************************************************************************************************************/


/***************************************************************************************************************/

-- Step 2: Building clusters recursively:
---------------------------------------------------------
--
-- 1. For each clusterID
--       a. select all pairs that have this cluster ID
--       b. Union with recursive results - pairs that are linked indirectly to this cluster with the cluster ID
-- Example:
-- if we have pairs:
--             Cluster id |  Vertex
--             --------------------
--                  2     |   3
--                  2     |   6 
--                  3     |   4 
--       sub step (a.) will add to the result the pairs: 2,3 ; 2,6. sub step b will add the pair: 2,4 
----------------------------------------------------------------------------------------------------------------

-- recursive run to find child for each cluster
index := 1;

select count(1) into NumOfCluster from Cluster Where "vertexid" = 0;

delete from "TMP_ArcProcess_ClusterChilds";

while :index <= :NumOfCluster do

		insert into "TMP_ArcProcess_ClusterChilds" ("ClusterID","vertexid")
		SELECT  "ClusterID", "vertexid" -- Ancor part
			FROM Cluster e WHERE "ClusterID" = :index 
			UNION ALL
			SELECT  e."ClusterID", e."vertexid" -- Recursive part
			FROM Cluster e
			inner JOIN "TMP_ArcProcess_ClusterChilds" d
			ON 
			e."ClusterID" = d."vertexid";
			
		SELECT distinct :index, "vertexid"
		FROM "TMP_ArcProcess_ClusterChilds" into Cluster;

		index := :index+1;

end while;

--select * from "TMP_ArcProcess_ClusterChilds";
delete from "TMP_ArcProcess_ClusterChilds";


/***************************************************************************************************************/


-- Get rid of redundant pairs (pairs that have vertex with low cluster id i.e 2,3 2,6 3,6 get rid from 3,6)
-- insert  them to new table Cluster1 
 --insert  into #Cluster1
 select distinct  c1."ClusterID",c1."vertexid"
 from  Cluster c1
 left  join Cluster c2
 on c1."ClusterID" = c2."vertexid"
 where c2."ClusterID" is null into Cluster1;
---------------------------------------------------------------------------------


---------------------------------------------------------------------------------
-- Add index on Cluster1 - For better performance -------------------------------

---------------------------------------------------------------------------------


----------------------------------------------------------------------------------
-- change vertexid from 0 to point to itself, so it will be part of the cluster
update Cluster1
set "vertexid" = "ClusterID"
where "vertexid" = 0;
----------------------------------------------------------------------------------

-- End of step 2  

/***************************************************************************************************************/

-- Step 3: Update left vertex
----------------------------------------------------------------------------------
	

-- update cluster id of pairs that connect with left vertex i.e 2,6 3,6 --> 2,6 2,3
-- Do it while there is a connection with left vertex

-- We do it first for each cluster and then do a loop to cover those that was left - it be done in two steps for performance 	


index1 := 1;

NumOfCluster1 := :NumOfCluster;

while :index1 <= :NumOfCluster1 do

	update Cluster1 c0
	set c0."ClusterID" = (select c4.clusterid1
	from (select distinct c1."ClusterID" clusterid1,c2."ClusterID"  clusterid2  from Cluster1 c1
	inner join Cluster1 c2	on c1."vertexid" = c2."vertexid" and c1."ClusterID" < c2."ClusterID" and c1."vertexid" > 0) c4
	where c0."ClusterID" = c4.clusterid2
	and c4.clusterid1 = :index1)
	;


index1 := :index1 + 1;

end while;

select top 1 1 into temp_var1  from Cluster1 c1
	inner join Cluster1 c2
	on c1."vertexid" = c2."vertexid"
	and c1."ClusterID" < c2."ClusterID"
	and c1."vertexid" > 0;

While :temp_var1 <> 0 do
	select top 1 c1."ClusterID" into i from Cluster1 c1
	inner join Cluster1 c2
	on c1."vertexid" = c2."vertexid"
	and c1."ClusterID" < c2."ClusterID"
	and c1."vertexid" > 0 ;

	update Cluster1 c0
	set c0."ClusterID" = (select c4.clusterid1
	from (select distinct c1."ClusterID" clusterid1, c2."ClusterID"  clusterid2  from Cluster1 c1
	inner join Cluster1 c2	on c1."vertexid" = c2."vertexid" and c1."ClusterID" < c2."ClusterID" and c1."vertexid" > 0 ) c4
	where c0."ClusterID" = c4.clusterid2
	and  c4.clusterid1 = :i);


	select top 1 1 into temp_var1  from Cluster1 c1
	inner join Cluster1 c2
	on c1."vertexid" = c2."vertexid"
	and c1."ClusterID" < c2."ClusterID"
	and c1."vertexid" > 0;
end while;
-- update clusterid to start from 0

delete from "TMP_ArcProcess_RowNums";

sql1 := 'CREATE SEQUENCE my_s INCREMENT BY 1 START WITH 1';
exec ( :sql1);
sql1 := 'INSERT INTO "TMP_ArcProcess_RowNums" SELECT "ClusterID", my_s.NEXTVAL from Cluster1 group by "ClusterID"';
exec ( :sql1);
sql1 := 'DROP SEQUENCE my_s';
exec ( :sql1);

update Cluster1 c0
set c0."ClusterID" = (
select rownum from 
(select c1."ClusterID",count(*) as rownum from Cluster1 c1 group by c1."ClusterID"
) c2
where c0."ClusterID" = c2."ClusterID"
);

delete from "TMP_ArcProcess_RowNums";

-- End of step 3  
/***************************************************************************************************************/


/*****************************************************/
-- Step 4 Update  ##TDAR_ with final result

exec(' update ' || :TmpArcTable || ' set clusterid = C1."CLUSTERID" from Cluster C1 where line_id = C1."VERTEXID"');
/*****************************************************/

 --- Drop tables that was created for ARC process
 exec ('drop table cluster');
 exec ('drop table cluster1');
 exec ('drop table ' || :TmpArcBackTable );
 exec ('drop table ' || :PairsArc );
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

------------------------------- TmSp_ArcSaveArchivedProductionRecords -------------------------------

-- This stored procedure copies records from OWOR and WOR1 to UWOR and UWOR1 OR
-- from OWKO and WKO1 to UWKO and UWKO1.
-- The records that are copied are such that are going to be archived, i.e. they exist in the temporary
-- table ##TDAR_<pid> (@in_TDAR_name) with CanArcObj = 'Y' and CanArcClus = 'Y'

--------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE TmSp_ArcSaveArchivedProductionRecords
(
in in_TDAR_name varchar (5000),
in in_Object varchar (5000),
out ret int
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
	
	--*With Encryption

AS
TDAR_name varchar (5000);					
UTable varchar (5000);
OTable varchar (5000);
UTable1 varchar (5000);
OTable1 varchar (5000);
AbsField varchar (5000);
object varchar (5000);
s_sql varchar(5000);

BEGIN

--Parameters validation for security issues
call _TmSp_ValidateSpParam(:in_TDAR_name);
call _TmSp_ValidateSpParam(:in_Object);

ret :=0;
TDAR_name := :in_TDAR_name;		-- ##TDAR_<pid>

IF (:in_Object = 202) then--WOR
	object := '202';
	UTable := 'UWOR';
	OTable := 'OWOR';
	UTable1 := 'UWOR1';
	OTable1 := 'WOR1';
	AbsField := 'T0."DocEntry"';

ELSE 
	IF (:in_Object = 68) then--WKO
		object := '68';
		UTable := 'UWKO';
		OTable := 'OWKO';
		UTable1 := 'UWKO1';
		OTable1 := 'WKO1';
		AbsField := 'T0."OrderNum"';
	ELSE
		ret :=-1;
		return;
	END IF;
END IF;

s_sql :=	'-------------------'||
		'-- Header'||
		'-------------------'||
	'INSERT INTO ' || :UTable ||
	'SELECT T0.* '||--o "" hviezdicku??
	'FROM ' || :OTable || ' T0 '||
	'JOIN ' || :TDAR_name || ' T1 ON T1."DocType" = '|| :object ||'  AND T1."DocAbs" = ' || :AbsField ||
	' WHERE '||
	'T1."CanArcObj" = ''Y'' AND '||
	'T1."CanArcClus" = ''Y'' '||
	'------------------- '||
	'-- Array 1 '||
	'------------------- '||

	'INSERT INTO ' || :UTable1 ||
	'SELECT T0.* '||--o "" hviezdicku??
	'FROM ' || :OTable1 || ' T0 '||
	'JOIN ' || :TDAR_name || ' T1 ON T1."DocType" = '|| :object || '  AND T1."DocAbs" = ' || :AbsField ||
	' WHERE '||
	'T1."CanArcObj" = ''Y'' AND '||
	'T1."CanArcClus" = ''Y'' ';

exec (:s_sql);

ret :=0;

END;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START
create procedure TmSp_AttachConnContextInfo(session_information_in nvarchar(4000))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
	v_session_info nvarchar(4000);
	v_section_session_info nvarchar(500);
	v_key nvarchar(255);
	v_value nvarchar(255);
begin
	v_session_info := :session_information_in;
	v_section_session_info := substr_before(:v_session_info, ';');

	while (length(:v_section_session_info) > 0)
	do 
		v_key := substr_before(:v_section_session_info, '|');
		v_value := substr_after(:v_section_session_info, '|');
		if (length(:v_key) > 0 and length(:v_value) > 0)
		then
			--select 'set session ''' || :v_key || ''' = ''' || :v_value || '''' from dummy;
			exec 'set session ''' || :v_key || ''' = ''' || :v_value || '''';
		end if;
		v_session_info := substr_after(v_session_info, ';');
		v_section_session_info := substr_before(:v_session_info, ';');
	end while;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_B1CFLDeployFunctions
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	v_sql nclob;
	B1CFLSetTimeToZero varchar(1000);
	B1CFLMonthEnd varchar(1000);
	B1CFLMonthStart varchar(1000);
	B1CFLMonthHalf varchar(1000);
	B1CFLAddMonthsAndDays varchar(1000);
	B1CFLCreateDate varchar(1000);
	B1CFLDayOfWeek varchar(1000);
	v_cnt integer;
BEGIN
	
	select count(*) into v_cnt from "PUBLIC".procedures where procedure_name = 'B1CFLCONSIDERHOLIDAY' and schema_name = current_schema;
	
	if :v_cnt > 0 then
		exec ('drop procedure B1CFLCONSIDERHOLIDAY');
	END if;

	--here is the workaround for HANA because HANA doesnt support standard ANSI sql function yet.  here is only one complex sql procedure B1CFLConsiderHoliday
	-- other sql functions are converted to inline builtin function as indicated below:
	-- once HANA function is ready , consider refactor them.\
	-- the only block will call those functions is TmSp_B1CFLGetDocuments 

	B1CFLSetTimeToZero := 'to_date(:v_datetime)';
	B1CFLMonthEnd := 'last_day(:v_datetime)';
	B1CFLMonthStart := 'next_day(' || :B1CFLMonthEnd || ')';
	B1CFLMonthHalf := 'floor(DAYOFMONTH(' || :B1CFLMonthEnd|| '))/2+1';
	B1CFLAddMonthsAndDays := 'to_date(add_days(add_months(:v_datetime,:v_addmonth),:v_addday))';
	B1CFLCreateDate := 'add_months(add_days(to_date(:v_year),:v_day - 1),:v_month - 1)';
	B1CFLDayOfWeek := 'MAP(WEEKDAY(:v_datetime),0,2,1,3,2,4,3,5,4,6,5,7,6,1)';
	
	v_sql := '
	CREATE PROCEDURE B1CFLConsiderHoliday(v_dtIn DATE, v_nvHldCode NVARCHAR(20), out v_dtOut DATE)
	AS
		v_siWndFrm SMALLINT; -- Although OHLD.WndFrm is NVARCHAR(1) !!!
		v_siWndTo SMALLINT; -- Although OHLD.WndTo is NVARCHAR(1) !!!
		v_cIsCurYear NVARCHAR(1);
		v_cIgnrWnd NVARCHAR(1);
		v_siWeekDay SMALLINT;
		v_dtLast DATE;
		l_dtIn DATE;
		v_cnt integer := 0;
BEGIN
	IF IFNULL(:v_nvHldCode,'''') = '''' THEN
		v_dtOut := :v_dtIn;
	ELSE 
		
		select count(*) into v_cnt FROM OHLD WHERE "HldCode" = :v_nvHldCode;
		if :v_cnt > 0 then
			SELECT to_smallint("WndFrm"),to_smallint("WndTo"),"isCurYear","ignrWnd" INTO v_siWndFrm, v_siWndTo, 
			v_cIsCurYear,v_cIgnrWnd FROM OHLD WHERE "HldCode" = :v_nvHldCode;
		end if;
		v_dtLast := :v_dtIn;
		l_dtIn := :v_dtIn;
		
		WHILE :v_dtLast is not null do
		
			IF :v_cIsCurYear = ''Y'' then
				select count(*) into v_cnt FROM HLD1 WHERE "HldCode" = :v_nvHldCode AND :l_dtIn >= "StrDate" AND :l_dtIn <= "EndDate";
				if :v_cnt > 0 then
					SELECT MAX("EndDate") into v_dtLast FROM HLD1 WHERE "HldCode" = :v_nvHldCode AND :l_dtIn >= "StrDate" AND :l_dtIn <= "EndDate";
				else 
					v_dtLast := Null;
				end if;
			ELSE
				select count(*) into v_cnt FROM HLD1
					WHERE "HldCode" = :v_nvHldCode AND
					:l_dtIn >= add_months(add_days(to_date(to_varchar(YEAR(:l_dtIn))),EXTRACT (DAY FROM "StrDate") - 1),MONTH("StrDate") - 1) AND
					:l_dtIn <= add_months(add_days(to_date(to_varchar(YEAR(:l_dtIn))),EXTRACT (DAY FROM "EndDate") - 1),MONTH("EndDate") - 1);
				if :v_cnt > 0 then
					SELECT MAX(add_months(add_days(to_date(to_varchar(YEAR(:l_dtIn))),EXTRACT (DAY FROM "EndDate") - 1),MONTH("EndDate") - 1)) INTO v_dtLast FROM HLD1
					WHERE "HldCode" = :v_nvHldCode AND
					:l_dtIn >= add_months(add_days(to_date(to_varchar(YEAR(:l_dtIn))),EXTRACT (DAY FROM "StrDate") - 1),MONTH("StrDate") - 1) AND
					:l_dtIn <= add_months(add_days(to_date(to_varchar(YEAR(:l_dtIn))),EXTRACT (DAY FROM "EndDate") - 1),MONTH("EndDate") - 1);
				else 
					v_dtLast := null;
				end if;

			END IF;
			
			IF :v_dtLast is not null then 
				l_dtIn := ADD_DAYS(:l_dtIn,DAYS_BETWEEN(:l_dtIn, :v_dtLast) + 1);
			ELSE
				IF :v_cIgnrWnd = ''N'' then						
					select MAP(WEEKDAY(:l_dtIn),0,2,1,3,2,4,3,5,4,6,5,7,6,1) into v_siWeekDay from dummy;
					IF :v_siWndFrm <= :v_siWndTo THEN
						IF :v_siWeekDay >= :v_siWndFrm AND :v_siWeekDay <= :v_siWndTo THEN
							l_dtIn := ADD_DAYS(:l_dtIn,:v_siWndTo - :v_siWeekDay + 1);
							v_dtLast := :l_dtIn;
						END IF;
					ELSE
						IF :v_siWeekDay >= :v_siWndFrm then
							l_dtIn := ADD_DAYS(:l_dtIn,8 + :v_siWndTo - :v_siWeekDay);
							v_dtLast := l_dtIn;
						ELSE
							IF :v_siWeekDay <= :v_siWndTo THEN
								l_dtIn := ADD_DAYS(:l_dtIn, 1 + :v_siWndTo - :v_siWeekDay);
								v_dtLast := :l_dtIn;
							END IF;
						END if;
					END IF;
				END IF;
			END if;
		end while;
		v_dtOut := to_date(:l_dtIn);
	END IF;
END';
	
	
	EXEC (:v_sql);
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:TmSp_B1CFLDeployFunctions AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_B1CFLGetDocuments(
	v_nvFrom NVARCHAR(8),
	v_nvTo NVARCHAR(8),
	v_docViewName NVARCHAR(32),
	v_predictDueDate SMALLINT,
	v_useDelay SMALLINT,
	v_inclRecurrTrans SMALLINT,
	v_tempORCLName NVARCHAR(32))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	v_sql nclob;
	v_nvDelayTable NVARCHAR(2);
	v_nvCardCode NVARCHAR(15);
	v_nvCardCodeBeforeNext NVARCHAR(15);
	v_siPmntDate SMALLINT; -- Although CRD5."PmntDate" is NVARCHAR(2) !!!
	v_siPmntDateDayFirst SMALLINT; -- Although CRD5."PmntDate" is NVARCHAR(2) !!!
	v_siDueDateDay SMALLINT; -- Although CRD5."PmntDate" is NVARCHAR(2) !!!.
	v_nvDueDateField NVARCHAR(15);
	CURSOR crPaymentDates FOR SELECT T0."CardCode", T0."PmntDate" 
	FROM (SELECT "CardCode", TO_SMALLINT("PmntDate") AS "PmntDate" FROM CRD5) T0 ORDER BY T0."CardCode" ASC, T0."PmntDate" ASC;
	CURSOR cB1CFLGetDocuments FOR SELECT * FROM "B1CFLGetDocuments";
	v_cnt integer;
	v_HolidayDueDate date;
BEGIN
	--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:v_nvFrom);    
    call _TmSp_ValidateSpParam(:v_nvTo);    
	call _TmSp_ValidateSpParam(:v_docViewName);   
	call _TmSp_ValidateSpParam(:v_tempORCLName);   
	
	IF :v_predictDueDate = 0 THEN
		-- Query for Documents with Due Date
		v_sql := 'SELECT T0."CtlAccount", T0."CardCode", T0."DueDate", T0."Debit", T0."Credit", T0."DebitFC", T0."CreditFC", T0."DebitSC", T0."CreditSC", T0."DocCur", T0."DocDate", T0."TransId", T0."DocNum", T0."DocNum", T0."JrnlMemo", T0."ObjType", T0."Project", T0."AgrNo", T0."DocEntry", NULL AS NA, T0."AgrNum", T0."AvrageLate", T0."InstID", 
		 T0."InstNum", T0."InstPrcnt", T0."GroupNum"
			 FROM "' || :v_docViewName || '" T0 ';
		v_nvDelayTable := 'T0';
	ELSE
		select count (*) into v_cnt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#B1CFLPaymentDates' and connection_id = current_connection;	
		if :v_cnt > 0 then
			exec ('drop table "#B1CFLPaymentDates"');
		END if;
		
		--SELECT "CardCode" INTO "#B1CFLPaymentDates" FROM CRD5 WHERE "CardCode" IS NULL
		CREATE LOCAL TEMPORARY TABLE "#B1CFLPaymentDates" (
			"CardCode" NVARCHAR(15) NOT NULL ,
			"DueDateDay" SMALLINT NOT NULL, -- Although CRD5."PmntDate" is NVARCHAR(2) !!!
			"PmntDate" SMALLINT NOT NULL, -- Although CRD5."PmntDate" is NVARCHAR(2) !!!
			"NextMonth" SMALLINT NOT NULL);
		delete from "#B1CFLPaymentDates" where 1=1;
		--CREATE NONCLUSTERED INDEX B1CFLPaymentDates_PRIMARY ON "#B1CFLPaymentDates" (
		--CardCode ASC,
		--DueDateDay ASC,
		--	PmntDate ASC
		--) WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

		open crPaymentDates;
		
		FETCH crPaymentDates INTO v_nvCardCode, v_siPmntDate;
		v_siPmntDateDayFirst := v_siPmntDate;
		v_siDueDateDay := 1;
		while (NOT crPaymentDates::NOTFOUND) DO
			WHILE :v_siDueDateDay <= :v_siPmntDate do
				INSERT INTO "#B1CFLPaymentDates" VALUES (:v_nvCardCode, :v_siDueDateDay, :v_siPmntDate, 0);
				v_siDueDateDay := :v_siDueDateDay + 1;
			END while;
			v_nvCardCodeBeforeNext := :v_nvCardCode;
			
			FETCH crPaymentDates INTO v_nvCardCode, v_siPmntDate;
			
			IF :v_nvCardCodeBeforeNext <> :v_nvCardCode THEN
				WHILE :v_siDueDateDay <= 31 DO
					INSERT INTO "#B1CFLPaymentDates" VALUES (:v_nvCardCodeBeforeNext, :v_siDueDateDay, :v_siPmntDateDayFirst, 1);
					v_siDueDateDay := :v_siDueDateDay + 1;
				END WHILE;
				v_siDueDateDay := 1;
			END if;			
		END WHILE;
		WHILE (:v_siDueDateDay <= 31 AND :v_nvCardCodeBeforeNext IS NOT NULL) DO
			INSERT INTO "#B1CFLPaymentDates" VALUES (:v_nvCardCodeBeforeNext, :v_siDueDateDay, v_siPmntDateDayFirst, 1);
			v_siDueDateDay := :v_siDueDateDay + 1;
		END WHILE;
		close crPaymentDates;
		
		-- Query for Documents with Prediction of Due Date
		
		IF :v_inclRecurrTrans = 1 then
			v_nvDueDateField := 'T2."PlanDate"';
		ELSE 
			v_nvDueDateField := 'T0."DueDate"';
		end if;
		
		truncate table "B1CFLGetDocuments";
		truncate table "B1CFLGetDocumentsHoliday";
		--sub table
		v_sql := 'insert into "B1CFLGetDocuments" SELECT T0."DocEntry", T0."InstID", T0."DueDateByPaymentDates" AS "DueDate", T0."HldCode", T0."Instance", T0."Code"
			FROM (
				SELECT T0."DocEntry", T0."InstID", T0."HldCode", T0."Instance", T0."Code",
					CASE
						WHEN T1."CardCode" IS NOT NULL THEN
							CASE WHEN T1."PmntDate" > dayofmonth(last_day(add_months(T0."DueDateOnDoc",T1."NextMonth"))) 
								THEN to_date(YEAR(add_months(T0."DueDateOnDoc",T1."NextMonth"+1)) || ''-'' || MONTH(add_months(T0."DueDateOnDoc",T1."NextMonth"+1)) || ''-1'')
								ELSE to_date(YEAR(add_months(T0."DueDateOnDoc",T1."NextMonth")) || ''-'' || MONTH(add_months(T0."DueDateOnDoc",T1."NextMonth")) || ''-''	|| T1."PmntDate")
							END
						ELSE T0."DueDateOnDoc"
					END AS "DueDateByPaymentDates"
				FROM (
					SELECT T0."DocEntry", T0."InstID", T0."CardCode", T0."HldCode",
						CASE
							WHEN T0."PayDuMonth" = ''N'' THEN to_date(add_days(add_months(' || :v_nvDueDateField || ', T0."ExtraMonth" + T0."InstMonth"), T0."ExtraDays" + T0."InstDays" - COALESCE(T1."TolDays", 0)))
							WHEN T0."PayDuMonth" = ''Y'' THEN to_date(add_days(add_months(next_day(last_day(' || :v_nvDueDateField || ')), T0."ExtraMonth" + T0."InstMonth"), T0."ExtraDays" + T0."InstDays" - COALESCE(T1."TolDays", 0)))
							WHEN T0."PayDuMonth" = ''H'' THEN to_date(add_days(add_months(YEAR(' || :v_nvDueDateField || ') || ''-'' || Month(' || :v_nvDueDateField || ') || ''-'' || floor(DAYOFMONTH(last_day(' || :v_nvDueDateField || '))/2)+1, T0."ExtraMonth" + T0."InstMonth"), T0."ExtraDays" + T0."InstDays" - COALESCE(T1."TolDays", 0)))
							WHEN T0."PayDuMonth" = ''E'' THEN to_date(add_days(add_months(last_day(' || :v_nvDueDateField || '), T0."ExtraMonth" + T0."InstMonth"), T0."ExtraDays" + T0."InstDays" - COALESCE(T1."TolDays", 0)))
							ELSE NULL
						END AS "DueDateOnDoc", ';
		IF :v_inclRecurrTrans = 1 then
			v_sql := :v_sql || 'T2."Instance", T3."Code" ';
		
		ELSE 
			v_sql := :v_sql || 'NULL AS "Instance", NULL AS "Code" ';
		END IF;
		v_sql := :v_sql || '
					FROM "' || :v_docViewName || '" T0
					INNER JOIN OCTG T1 ON T1."GroupNum" = T0."GroupNum"';
		IF :v_inclRecurrTrans = 1 then
			v_sql := v_sql || ' 
				INNER JOIN (SELECT * FROM ORCL  
								UNION ALL 
								SELECT * FROM "' || :v_tempORCLName || '") T2 
						ON T2."DocEntry" = T0."DocEntry" AND ABS(T2."DocObjType") = T0."ObjType" AND T2."Status" = ''N'' 
					INNER JOIN ORCP T3 ON T3."AbsEntry" = T2."RcpEntry"';
		end if;
		v_sql := :v_sql || ') T0
				LEFT JOIN "#B1CFLPaymentDates" T1 ON T1."CardCode" = T0."CardCode" AND T1."DueDateDay" = EXTRACT (DAY FROM T0."DueDateOnDoc")
			) T0';
		--SELECT :V_SQL from dummy;
		EXEC (:v_sql);
		
		FOR cur_row as cB1CFLGetDocuments DO 
			IF cur_row."HldCode" IS NULL THEN
				call B1CFLConsiderHoliday (cur_row."DueDate", '', :v_HolidayDueDate);
			ELSE
				call B1CFLConsiderHoliday (cur_row."DueDate", cur_row."HldCode", :v_HolidayDueDate);
			END IF;
			insert into "B1CFLGetDocumentsHoliday" values(cur_row."DocEntry",cur_row."InstID",:v_HolidayDueDate,cur_row."Instance",cur_row."Code");

		END FOR;
				
		--main table
		v_sql := 'SELECT T1."CtlAccount", T1."CardCode", T0."DueDate", T1."Debit", T1."Credit", T1."DebitFC", T1."CreditFC", T1."DebitSC", T1."CreditSC", T1."DocCur", T1."DocDate", T1."TransId", T1."DocNum", T1."DocNum", T1."JrnlMemo", T1."ObjType", T1."Project", T1."AgrNo", T1."DocEntry", NULL AS NA, T1."AgrNum", T1."AvrageLate", T1."InstID", T1."InstNum", T1."InstPrcnt", T1."GroupNum"';
		IF :v_inclRecurrTrans = 1  then
			v_sql := :v_sql || ', T0."Code", T0."Instance"';
		else 
			v_sql := :v_sql || ', null,null';
		end if;
		v_sql := v_sql || ' FROM "B1CFLGetDocumentsHoliday" T0
		INNER JOIN "' || :v_docViewName || '" T1 ON T1."DocEntry" = T0."DocEntry" AND T1."InstID" = T0."InstID" ';
		v_nvDelayTable := 'T1';
	END IF;

	v_sql := :v_sql || ' WHERE T0."DueDate" >= add_days(''' || :v_nvFrom || ''', ';
	IF :v_useDelay = 1 THEN
		v_sql := v_sql || '-' || :v_nvDelayTable || '."AvrageLate") ';
	ELSE 
		v_sql := v_sql || '0)';
	END IF; 
	v_sql := v_sql || 'AND T0."DueDate" <= add_days(''' || :v_nvTo || ''', ';
	IF v_useDelay = 1 THEN
		v_sql := :v_sql || '-' || :v_nvDelayTable || '."AvrageLate") ';
	ELSE 
		v_sql := v_sql || '0)';
	END IF;
	
	IF :v_predictDueDate = 0 THEN
		v_sql := :v_sql || 'ORDER BY T0."DocEntry" ASC ';
	ELSEIF :v_inclRecurrTrans = 0  THEN
		v_sql := :v_sql || 'ORDER BY T1."DocEntry" ASC, T1."InstID" ASC ';
	ELSE 
		v_sql := :v_sql || 'ORDER BY T1."DocEntry" ASC, T0."Code" ASC, T0."Instance" ASC, T1."InstID" ASC ';
	END IF;
	
	execute immediate (:v_sql);
	--SELECT :V_SQL from dummy;
	--call TmSp_B1CFLGetDocuments (N'20020701',N'20120731',N'docview1',1,0,0,N''); 
	
END;

CREATE PROCEDURE TmSp_B1GetSumDifferences(
	docViewName NVARCHAR(32),
	LCCredFieldName NVARCHAR(20),
	FCCredFieldName NVARCHAR(20),
	LCDebFieldName NVARCHAR(20),
	FCDebFieldName NVARCHAR(20),
	excludeGainsAfterDate NVARCHAR(8),
	rDate NVARCHAR(8),
	isDirectRate SMALLINT)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	v_sql nvarchar(1000);
	SumDec NVARCHAR(2);
BEGIN	
	v_sql := 'SELECT T0."ShortName", T0."FCCurrency", T0."BPLId", T0."Account", SUM(T0."' || :LCCredFieldName || '"), SUM(T0."' || :FCCredFieldName ||
								'"), SUM(T0."' || :LCDebFieldName || '"), SUM(T0."' || :FCDebFieldName || '") FROM ' || :docViewName || ' AS T0';
	IF LENGTH(:excludeGainsAfterDate) > 0 THEN
		SELECT TOP 1 "SumDec" INTO SumDec FROM OADM;
		v_sql := :v_sql || ' LEFT OUTER JOIN ORTT AS T1 ON T0."FCCurrency" = T1."Currency" AND T1."RateDate" = TO_DATE(''' || :rDate || ''', ''YYYYMMDD'')';
		v_sql := :v_sql || ' WHERE T0."DueDate" <= TO_DATE(''' || :excludeGainsAfterDate || ''', ''YYYYMMDD'') OR ROUND((T0."'||:FCCredFieldName||'"-T0."'||:FCDebFieldName||'")';
		IF :isDirectRate = 1 THEN
			v_sql := :v_sql || '*';
		ELSE	
			v_sql := :v_sql || '/';
		END IF;
		v_sql := :v_sql || 'T1."Rate", ' || :SumDec || ') >= (T0."'||:LCCredFieldName||'"-T0."'||:LCDebFieldName||'")';
	END	IF;
	v_sql := :v_sql	|| ' GROUP BY T0."ShortName", T0."FCCurrency", T0."BPLId", T0."Account" ORDER BY T0."ShortName"';
	
	EXECUTE IMMEDIATE (:v_sql);
	--SELECT :v_sql from dummy;
END

CREATE PROCEDURE TmSp_BOM_IsFather_Group ( IN son nvarchar(50) )
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as

	 	
begin
	-- procedure uses temporary table #TmpInSpIsFatherGrp as source of father nodes to be compared
	-- RETURNS: sigle row <isFatherFound>, <Line Number of Found Father>

	DECLARE actualLayer integer;					-- current layer of the tree nodes
	DECLARE newRows integer;				-- number of new nodes 		
	DECLARE foundLineV integer;

	actualLayer := 0;
	newRows := 1;	
		
	-- check for identical father and son
	foundLineV := 0;
	IF (:foundLineV > 0)
	THEN
		CREATE LOCAL TEMPORARY TABLE "#TmpInSpIsFatherGrp" ( id nvarchar(50), "Line" integer);
	END IF;
			
	SELECT count(*) into foundLineV FROM "#TmpInSpIsFatherGrp" WHERE id = :son;	
	
	IF (:foundLineV > 0)
	THEN
 		SELECT TOP 1 1, "Line" FROM "#TmpInSpIsFatherGrp" WHERE id = :son;
 		RETURN;
	END IF;

	-- insert root node id, start with child on layer 0
    	reached = select :son as "ID", :actualLayer as "LAYER" from dummy;

	-- continu until new layer adds newly discovered nodes
	WHILE (:newRows > 0) 
	DO

		actualLayer := :actualLayer + 1;
		
		reached =
			select * from :reached
			union all
			SELECT DISTINCT id, :actualLayer 
			FROM 
			(
				SELECT DISTINCT "Father" AS id FROM "ITT1"	
					WHERE "Code" IN 
						(SELECT id FROM :reached WHERE layer = :actualLayer-1)	-- select nodes from previous layer
			
				UNION ALL

				SELECT DISTINCT A."ItemCode" FROM "OWOR" A 
					INNER JOIN "WOR1" B ON A."DocEntry" = B."DocEntry" 
					WHERE B."ItemCode" in 
						(SELECT id FROM :reached WHERE layer = :actualLayer-1)	-- select nodes from previous layer
					AND (A."Status" = ('P') OR A."Status" = ('R') ) AND ((A."AsChild" = 'Y' AND B."ItemCode" <> A."ItemCode" ) OR A."AsChild" = 'N')
			) 	Fathers		
				
			WHERE id NOT IN (SELECT id FROM :reached);   -- remove already discovered nodes present in the @reached table  
				
		-- chek if node is present in currently added layer
		SELECT count(*) into newRows FROM "#TmpInSpIsFatherGrp" WHERE id IN (SELECT id FROM :reached WHERE layer = :actualLayer);	
		IF :newRows > 0 
		THEN
			SELECT TOP 1 1, "Line" FROM "#TmpInSpIsFatherGrp" WHERE id IN (SELECT id FROM :reached WHERE layer = :actualLayer);			 
			RETURN;
		END IF;
					
		SELECT count(*) into newRows FROM :reached WHERE layer = :actualLayer;	
							
	END WHILE;

	-- node not found in any of the layers
	SELECT 0, NULL FROM dummy;
	
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE  TmSp_ChooseCIN4Correction(in card nvarchar(100),
in Type1 nvarchar(2),
in curr nvarchar(4))

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
begin

if (:Type1 = N'I')
then
	if ( LENGTH(ltrim(rtrim(:curr)))>0 )
	then
		select "DocEntry", "DocNum",  "DocDate", "CardCode", "Comments", "DocDueDate"  from OCIN
		WHERE (NOT EXISTS
				(select distinct("DocEntry") from CIN1 
					where "DocEntry" = OCIN."DocEntry" AND
						("Quantity" <= 0 OR 
						"LineStatus"= N'C' OR
						"OpenCreQty"<>"Quantity") ))
			
	
			 AND "CANCELED"<>N'Y' 
			AND "CardCode" = :card 
			AND "DocType"=N'I'
			AND "DocCur"=:curr
		ORDER BY "DocNum";
	
	else
	
		select "DocEntry", "DocNum",  "DocDate", "CardCode", "Comments", "DocDueDate"  from OCIN
		WHERE (NOT EXISTS
				(select distinct("DocEntry") from CIN1 
					where "DocEntry"=OCIN."DocEntry" AND
						("Quantity"<=0 OR 
						"LineStatus"=N'C' OR
						"OpenCreQty"<>"Quantity") ))
			
	
			 AND "CANCELED"<>N'Y' 
			AND "CardCode" = :card 
			AND "DocType"=N'I'
		ORDER BY "DocNum";
	end if;


else

	if ( LENGTH(ltrim(rtrim(:curr)))>0 )
	then	
		select "DocEntry", "DocNum",  "DocDate", "CardCode", "Comments", "DocDueDate"  from OCIN
		WHERE (NOT EXISTS
				(select distinct("DocEntry") from CIN1 
					where "DocEntry"=OCIN."DocEntry" AND
						"LineStatus"<>N'O'))
	
			 AND "CANCELED"<>N'Y' 
			AND "CardCode" = :card 
			AND "DocType"=N'S'
			AND "DocCur"=:curr
		ORDER BY "DocNum";
	
	else
	
		select "DocEntry", "DocNum",  "DocDate", "CardCode", "Comments", "DocDueDate"  from OCIN
		WHERE (NOT EXISTS
				(select distinct("DocEntry") from CIN1 
					where "DocEntry"=OCIN."DocEntry" AND
						"LineStatus"<>N'O'))
	
			 AND "CANCELED"<>N'Y' 
			AND "CardCode" = :card 
			AND "DocType"=N'S'
		ORDER BY "DocNum";
	end if;
end if;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END


