-- B1 DEPENDS: AFTER:SP:TmSp_CleanupExpiredPersonalDataOfSubjects AFTER:SP:TmSp_CleanupExpiredPersonalDataOfOCRD AFTER:SP:TmSp_CleanupExpiredPersonalDataOfUDO
CREATE PROCEDURE TmSp_CleanupExpiredPersonalData
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
    --*With Encryption
AS
BEGIN

	CALL TmSp_CleanupExpiredPersonalDataOfSubjects;
	CALL TmSp_CleanupExpiredPersonalDataOfOCRD;
	CALL TmSp_CleanupExpiredPersonalDataOfUDO;
	
END;

-- CALL TmSp_CleanupExpiredPersonalDataOfOCRD;
-- DROP PROCEDURE TmSp_CleanupExpiredPersonalDataOfOCRD;
CREATE PROCEDURE TmSp_CleanupExpiredPersonalDataOfOCRD
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
    --*With Encryption
AS
    DatSubType NVARCHAR(4);
    DatSubKey NVARCHAR(15);
    TableName NVARCHAR(10);
    QryString NVARCHAR(500);
    WhereString NVARCHAR(150);
    UpdateDateName NVARCHAR(20);
    KeyName NVARCHAR(20);
    DPPStatus NVARCHAR(2);
  
		
	CURSOR C_CURSOR FOR	
--Get Expired Personal Data of OCRD
	    SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."TableName"
		FROM OBPD T0, ODRP T1 
		WHERE T1."Active" = 'Y' AND T0."DatSubType" = T1."DatSubType" AND T0."DatSubType" = 'OCRD' AND T0."ObjType" = T1."ObjType" AND T1."ObjType" != '-1'
			AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
			AND T0."TableName" IN ('OCRD','OCPR','OUSR','OHEM','CPN1','OCIN','OCPI','OCPV','OCSI','OCSV','ODLN',
									'ODPI','ODPO','ODRF','OIEI','OIGE','OIGN','OINV','OOEI','OPCH','OPDN','OPOR',
									'OPQT','OPRR','OQUT','ORDN','ORDR','ORIN','ORPC','ORPD','ORRR','OSFC','OSFI',
									'OWTQ','OWTR','ORCT','OVPM','OBNK','OOPR','OINS','OCHO','OCTR','OSCL','OCLG',
									'OPMG','OIPF','PWZ1','PWZ3','PWZ5','OCHH','OPEX','DWZ1','OBOE','OOAT')
		
		union
		
--Get Expired Personal Data of OCRD and Object Type = ALL
		SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."TableName" 
		FROM OBPD T0, ODRP T1 
		WHERE T1."Active" = 'Y' AND T0."DatSubType" = T1."DatSubType" AND T0."DatSubType" = 'OCRD' AND T1."ObjType" = '-1'
			AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
			AND T0."TableName" IN ('OCRD','OCPR','OUSR','OHEM','CPN1','OCIN','OCPI','OCPV','OCSI','OCSV','ODLN',
									'ODPI','ODPO','ODRF','OIEI','OIGE','OIGN','OINV','OOEI','OPCH','OPDN','OPOR',
									'OPQT','OPRR','OQUT','ORDN','ORDR','ORIN','ORPC','ORPD','ORRR','OSFC','OSFI',
									'OWTQ','OWTR','ORCT','OVPM','OBNK','OOPR','OINS','OCHO','OCTR','OSCL','OCLG',
									'OPMG','OIPF','PWZ1','PWZ3','PWZ5','OCHH','OPEX','DWZ1','OBOE','OOAT')
			AND NOT EXISTS (SELECT T0.* FROM ODRP T2 WHERE T2."ObjType" != '-1' AND T2."Active" = 'Y' AND T0."DatSubType" = T2."DatSubType" AND T0."ObjType" = T2."ObjType")	
		ORDER by T0."DatSubType", T0."DatSubKey";	
		
BEGIN
    OPEN C_CURSOR;
    FETCH C_CURSOR INTO DatSubType, DatSubKey, TableName;
           
    WHILE NOT c_cursor::NOTFOUND DO
    	UpdateDateName := 'UpdateDate';
    	IF :TableName = 'OINS' OR :TableName = 'OSCL' THEN
    		UpdateDateName := 'updateDate';
    	ELSEIF :TableName = 'OOAT' THEN
    		UpdateDateName := 'UpdtDate';
    	END IF;
        
    	KeyName := 'CardCode';
        IF :TableName = 'OINS' OR :TableName = 'OSCL' THEN
    		KeyName := 'customer';
    	ELSEIF :TableName = 'OCTR' THEN
    		KeyName := 'CstmrCode';
    	ELSEIF :TableName = 'OPMG' THEN
    		KeyName := 'CARDCODE';
    	ELSEIF :TableName = 'OOAT' OR :TableName = 'CPN1' THEN
    		KeyName := 'BpCode';
    	END IF;
    	
    	DPPStatus := 'N';
    	IF :TableName = 'OCRD' OR :TableName = 'OCIN' OR :TableName = 'OCPI' OR :TableName = 'OCPV' OR :TableName = 'OCSI' OR :TableName = 'OCSV'
			OR :TableName = 'ODLN' OR :TableName = 'ODPI' OR :TableName = 'ODPO' OR :TableName = 'OIEI' OR :TableName = 'OIGE' OR :TableName = 'OIGN'
			OR :TableName = 'OINV' OR :TableName = 'OOEI' OR :TableName = 'OPCH' OR :TableName = 'OPDN' OR :TableName = 'OPOR' OR :TableName = 'OPQT'
			OR :TableName = 'OPRR' OR :TableName = 'OQUT' OR :TableName = 'ORDN' OR :TableName = 'ORDR' OR :TableName = 'ORIN' OR :TableName = 'ORPC'
			OR :TableName = 'ORPD' OR :TableName = 'ORRR' OR :TableName = 'OSFC' OR :TableName = 'OSFI' OR :TableName = 'OWTQ' OR :TableName = 'OWTR'
			OR :TableName = 'ODRF' THEN
    		DPPStatus := 'B';
    	END IF;
    
        QryString := 'UPDATE ' || :TableName || ' SET "DPPStatus" = ''D'', "' || :UpdateDateName || '" = CURDATE()';
        IF :TableName = 'OCHO' OR :TableName = 'OPEX' OR :TableName = 'OBNK' OR :TableName = 'PWZ1' OR :TableName = 'PWZ3' OR :TableName = 'PWZ5' OR :TableName = 'OCHH' OR :TableName = 'DWZ1' THEN
        	QryString := 'UPDATE ' || :TableName || ' SET "DPPStatus" = ''D''';
        END IF;
        
        WhereString :=  ' WHERE "DPPStatus" = '''|| :DPPStatus || ''' AND "' || :KeyName || '" = ''' || :DatSubKey || '''';
        IF :TableName = 'OCHO' THEN
            WhereString := ' WHERE "DPPStatus" = ''N'' AND  "VendorCode" = ''' || :DatSubKey || ''' AND "CardOrAcct" = ''C''';
        ELSEIF :TableName = 'OPEX' THEN
            WhereString := ' WHERE "DPPStatus" = ''N'' AND ("VendorNum" = ''' || :DatSubKey || ''' OR "CustNum" = ''' || :DatSubKey || ''')';
        END IF;
                
        EXEC (:QryString || :WhereString);
        
        FETCH C_CURSOR INTO DatSubType, DatSubKey, TableName;
    END WHILE;
    
    CLOSE C_CURSOR;
	
--Delete Expired Personal Data of OCRD
    QryString := 'DELETE FROM OBPD T0 WHERE T0."DatSubType" = ''OCRD'' AND EXISTS (SELECT T0.* FROM ODRP T1 WHERE T1."ObjType" != ''-1'' AND T1."Active" = ''Y'' AND T0."DatSubType" = T1."DatSubType" AND T0."ObjType" = T1."ObjType" AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE())';
	EXEC (:QryString);
--Delete Expired Personal Data of OCRD and Object Type = ALL
    QryString := 'DELETE FROM OBPD T0 WHERE T0."DatSubType" = ''OCRD'' AND EXISTS (SELECT T0.* FROM ODRP T1 WHERE T1."Active" = ''Y'' AND T0."DatSubType" = T1."DatSubType" AND T1."ObjType" = ''-1'' AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE())';
	QryString := :QryString || ' AND NOT EXISTS (SELECT T0.* FROM ODRP T2 WHERE T2."ObjType" != ''-1'' AND T2."Active" = ''Y'' AND T0."DatSubType" = T2."DatSubType" AND T0."ObjType" = T2."ObjType")';
    EXEC (:QryString);
    
    
END;

-- CALL TmSp_CleanupExpiredPersonalDataOfSubjects;
-- DROP PROCEDURE TmSp_CleanupExpiredPersonalDataOfSubjects;
CREATE PROCEDURE TmSp_CleanupExpiredPersonalDataOfSubjects
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
    --*With Encryption
AS
    DatSubType NVARCHAR(4);
    DatSubKey NVARCHAR(15);
    DatSubKey2 NVARCHAR(50);
    TableName NVARCHAR(10);
    QryString NVARCHAR(400);
    WhereString NVARCHAR(150);
    UpdateDateName NVARCHAR(20);
    KeyName NVARCHAR(20);
    DPPStatus NVARCHAR(2);
  
		
	CURSOR C_CURSOR FOR	
----Get Expired Personal Data of OHEM/OUSR/CPN1/OCPR
	    SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."DatSubKey2", T0."TableName" 
		FROM OBPD T0, ODRP T1 
		WHERE T1."Active" = 'Y' AND T0."DatSubType" = T1."DatSubType" AND T0."DatSubType" != 'OCRD' AND T0."DatSubType" != 'OUDO'
			AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
			AND T0."TableName" IN ('OCPR','OUSR','OHEM','CPN1','OPRQ','OTSH','ODRF')
		ORDER by T0."DatSubType", T0."DatSubKey", T0."DatSubKey2";	
		
BEGIN
    OPEN C_CURSOR;
    FETCH C_CURSOR INTO DatSubType, DatSubKey, DatSubKey2, TableName;
           
    WHILE NOT c_cursor::NOTFOUND DO
    	UpdateDateName := 'UpdateDate';
    	IF :TableName = 'OCPR' OR :TableName = 'OUSR' THEN
    		UpdateDateName := 'updateDate';
    	END IF;
        
    	KeyName := 'CardCode';
        IF :TableName = 'OCPR' THEN
    		KeyName := 'CntctCode';
    	ELSEIF :TableName = 'OHEM' THEN
    		KeyName := 'empID';
    	ELSEIF :TableName = 'OUSR' THEN
    		KeyName := 'USERID';
    	ELSEIF :TableName = 'CPN1' THEN
    		KeyName := 'BpCode';
    	ELSEIF :TableName = 'OPRQ' THEN
    		KeyName := 'ReqID';
    	ELSEIF :TableName = 'OTSH' THEN
    		KeyName := 'UserID';
    	ELSEIF :TableName = 'ODRF' THEN
    		KeyName := 'ReqID';
    	END IF;
    	
    	DPPStatus := 'N';
    	IF :TableName = 'OCPR' OR :TableName = 'OUSR' OR :TableName = 'OHEM' OR :TableName = 'CPN1' OR :TableName = 'OPRQ' OR :TableName = 'ODRF' THEN
    		DPPStatus := 'B';
    	END IF;
    
        QryString := 'UPDATE ' || :TableName || ' SET "DPPStatus" = ''D'', "' || :UpdateDateName || '" = CURDATE()';
        IF :TableName = 'CPN1' THEN
        	QryString := 'UPDATE ' || :TableName || ' SET "DPPStatus" = ''D''';
        END IF;
        
        WhereString :=  ' WHERE "DPPStatus" = '''|| :DPPStatus || ''' AND "' || :KeyName || '" = ''' || :DatSubKey || '''';
        IF :DatSubType = 'CPN1' AND :TableName = 'CPN1' THEN
            WhereString := ' WHERE "DPPStatus" = ''B'' AND "CpnNo" = ' || :DatSubKey || ' AND "CpnLineNum" = ' || :DatSubKey2;
        END IF;
                
        EXEC (:QryString || :WhereString);
			
		--For sales employee which linked to employee, need set DPPStatus to erased manually.
		IF :TableName = 'OHEM' THEN
			QryString := 'UPDATE T0 SET T0."DPPStatus"=''D'' FROM OSLP T0, OHEM T1 WHERE T0."SlpCode" = T1."salesPrson" AND T1."empID" = ' || :DatSubKey;
			EXEC (:QryString);
		END IF;
        
        FETCH C_CURSOR INTO DatSubType, DatSubKey, DatSubKey2, TableName;
    END WHILE;
    
    CLOSE C_CURSOR;
	
	    
--Delete Expired Personal Data of OHEM/OUSR/CPN1/OCPR
    QryString := 'DELETE FROM OBPD T0 WHERE T0."DatSubType" != ''OCRD'' AND T0."DatSubType" != ''OUDO'' AND EXISTS (SELECT T0.* FROM ODRP T1 WHERE T1."Active" = ''Y'' AND T0."DatSubType" = T1."DatSubType" AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE())';
	EXEC (:QryString);
   
    
END;

-- CALL TmSp_CleanupExpiredPersonalDataOfUDO;
-- DROP PROCEDURE TmSp_CleanupExpiredPersonalDataOfUDO;
CREATE PROCEDURE TmSp_CleanupExpiredPersonalDataOfUDO
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
    --*With Encryption
AS
    DatSubType NVARCHAR(4);
    DatSubKey NVARCHAR(15);
    TableName NVARCHAR(10);
    QryString NVARCHAR(400);
    WhereString NVARCHAR(150);
    UpdateDateName NVARCHAR(20);
    KeyName NVARCHAR(20);
    DPPStatus NVARCHAR(2);
    ObjectType NVARCHAR(20);
	TableNameWrapper NVARCHAR(12);
	
	CURSOR C_CURSOR FOR	
----Get Expired Personal Data of OHEM/OUSR/CPN1/OCPR
	SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."TableName", T2."ObjectType"
	FROM OBPD T0, ODRP T1, OUTB T2 
	WHERE T1."Active" = 'Y' AND T0."DatSubType" = T1."DatSubType" AND T0."DatSubType" = 'OUDO'
		AND  ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
		AND T0."TableName" like '@%'
		AND T0."TableName" = '@' || T2."TableName"
		AND (T2."ObjectType" = 1 OR T2."ObjectType" = 3)
	ORDER by T0."DatSubType", T0."DatSubKey";
		
BEGIN
    OPEN C_CURSOR;
    FETCH C_CURSOR INTO DatSubType, DatSubKey, TableName, ObjectType;
           
    WHILE  NOT c_cursor::NOTFOUND DO
	   	UpdateDateName := 'UpdateDate';
    	KeyName := 'DocEntry';
        IF :ObjectType = 1 THEN
				KeyName := 'Code';
		END IF;	
    	
    	DPPStatus := 'B';
		TableNameWrapper := '"' || :TableName || '"';
        QryString := 'UPDATE ' || :TableNameWrapper || ' SET "DPPStatus" = ''D'', "' || :UpdateDateName || '" = CURDATE()';
        WhereString := ' WHERE "NaturalPer" = ''Y'' AND "DPPStatus" = ''' || :DPPStatus || ''' AND "' || :KeyName || '" = ''' || :DatSubKey || '''';
        EXEC (:QryString || :WhereString);
        FETCH C_CURSOR INTO DatSubType, DatSubKey, TableName, ObjectType;
    END WHILE;
    
    CLOSE C_CURSOR;	
	    
--Delete Expired Personal Data of OUDO
    QryString := 'DELETE FROM OBPD T0 WHERE T0."DatSubType" = ''OUDO'' AND EXISTS (SELECT T0.* FROM ODRP T1 WHERE T1."Active" = ''Y'' AND T0."DatSubType" = T1."DatSubType" AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE())';
	EXEC (:QryString);   
    
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_ConGrpLinetmp_OACT_recurs(
in acct1 nvarchar(15),
in line int,
in counter tinyint,
in ErrNum int,
out LineOut int
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS

acct2 nvarchar(15);
level smallint;
postable nvarchar (1);
acct3 nvarchar(15);
acct4 nvarchar(15);
acct5 nvarchar(15);
acct6 nvarchar(15);
acct7 nvarchar(15);
acct8 nvarchar(15);
acct9 nvarchar(15);
acct10 nvarchar(15);
-------------------------------------------------
ifcond2 int;
ifcond31 int;
ifcond32 int;
ifcond41 int;
ifcond42 int;
ifcond51 int;
ifcond52 int;
ifcond61 int;
ifcond62 int;
ifcond71 int;
ifcond72 int;
ifcond81 int;
ifcond82 int;
ifcond91 int;
ifcond92 int;
ifcond101 int;
ifcond102 int;
linetmp int;  --Used to solve the issue that "in line" couldn't be assinged value temporarily.
-------------------------------------------------
begin
	linetmp := :line;
	if  :linetmp = 2 then
		level := 2; 
	else
	  select "Levels" + 1 into level
	 	 from OACT
	  where "AcctCode" = :acct1;
	end if;
 -------------------Level 2------------------------------------	
	select count("AcctCode") into ifcond2 from OACT
               where "FatherNum" = :acct1 and "Levels" = :level and      
               "Groups" = :ErrNum;
	while :ifcond2 > 0
    do
    	 select Top 1 "AcctCode" into acct2
         	from OACT
      		where "FatherNum" = :acct1 and 
      		"Levels" = :level and 
      		"Groups" = :ErrNum and
            "GrpLine" = (select MIN("GrpLine") from OACT
                       		 where "FatherNum" = :acct1 and
                          	 "Levels" = :level and 
                          	 "Groups" = :ErrNum);
 
 		  update OACT
		  set "Groups" = :linetmp,
		      "GroupMask" = :counter
		  where "AcctCode" = :acct2;
		  

		  linetmp := :linetmp + 1;

  -------------------Level 3------------------------------------		
 		  select count("AcctCode") into ifcond31
 		  	from OACT
		  where "FatherNum" = :acct2 and "Levels" = 3 and
		                "Groups" = :ErrNum;
		  
		  select count("Postable") into ifcond32 
		  	from OACT 
		  where "AcctCode" = :acct2 and
		  		 "Postable" = 'N';  
		  		 
		  WHILE (:ifcond31 > 0) and  (:ifcond32 > 0)
		  do
			 select Top 1 "AcctCode" into acct3
			  	from OACT
			 where "FatherNum" = :acct2 and "Levels" = 3 and "Groups" = :ErrNum and
					"GrpLine" = (select MIN ("GrpLine") from OACT
							   where "FatherNum" = :acct2 and
							   "Levels" = 3 and "Groups" = :ErrNum);
			 update OACT
			   set "Groups" = :linetmp,
				   "GroupMask" = :counter
			 where "AcctCode" = :acct3;
			 
			 linetmp := :linetmp + 1; 
	
	-------------------For Level 4--------------------------------------
			select count("AcctCode") into ifcond41
				 from OACT
			where "FatherNum" = :acct3 and "Levels" = 4 and
					 "Groups" = :ErrNum;
					 
			select count("Postable") into ifcond42 from OACT 
				where "AcctCode" = :acct3 and "Postable" = 'N';
				
			WHILE :ifcond41 > 0 and :ifcond42 > 0
	-------------------Level 4--------------------------------------
			
			do
				select Top 1 "AcctCode" into acct4
				   from OACT
				   where "FatherNum" = :acct3 and "Levels" = 4 and "Groups" = :ErrNum and
						 "GrpLine" = (select MIN ("GrpLine") from OACT
											where "FatherNum" = :acct3 and
									"Levels" = 4 and "Groups" = :ErrNum);
				update OACT
				set "Groups" = :linetmp,
					"GroupMask" = :counter
				where "AcctCode" = :acct4;
			 
			    linetmp := :linetmp + 1;
			    
			    -------------------For Level 5 while Condition --------------------------------------
				select count("AcctCode") into ifcond51 
					from OACT
				where "FatherNum" = :acct4 and "Levels" = 5 and
							 "Groups" = :ErrNum;
				
				select count("Postable") into ifcond52 from OACT 
					where "AcctCode" = :acct4 and "Postable" = 'N';
					  		    
				WHILE :ifcond51 > 0 and :ifcond52 > 0
				do
				-------------------Level 5--------------------------------------    
					select Top 1 "AcctCode" into acct5
						   from OACT
						   where "FatherNum" = :acct4 and "Levels" = 5 and "Groups" = :ErrNum and
								 "GrpLine" = (select MIN ("GrpLine") from OACT
											where "FatherNum" = :acct4 and
												"Levels" = 5 and "Groups" = :ErrNum);
					update OACT
					set "Groups" = :linetmp,
						"GroupMask" = :counter
					where "AcctCode" = :acct5;
					
					linetmp := :linetmp + 1;
			
				
				-------------------For Level 6 while Condition --------------------------------------		
				select count("AcctCode") into ifcond61 from OACT
					where "FatherNum" = :acct5 and "Levels" = 6 and
							 "Groups" = :ErrNum;
				select count("Postable") into ifcond62 from OACT 
				where "AcctCode" = :acct5 and "Postable" = 'N'; 	
						 
				WHILE :ifcond61 > 0 and :ifcond62 > 0
				-------------------Level 6--------------------------------------    
				do
					select Top 1 "AcctCode" into acct6
						   from OACT
						   where "FatherNum" = :acct5 
						   and "Levels" = 6 
						   and "Groups" = :ErrNum 
						   and "GrpLine" = (select MIN("GrpLine") from OACT
											where "FatherNum" = :acct5 and
											"Levels" = 6 and "Groups" = :ErrNum);
					update OACT
					set "Groups" = :linetmp,
						"GroupMask" = :counter
					where "AcctCode" = :acct6;
					linetmp := :linetmp + 1;
					
				-------------------For Level 7 while Condition --------------------------------------		
					select count("AcctCode") into ifcond71 from OACT
						where "FatherNum" = :acct6 and "Levels" = 7 and
								 "Groups" = :ErrNum;	
					select count("Postable") into ifcond72 from OACT 
						where "AcctCode" = :acct6 and  "Postable"= 'N'; 		
				-------------------Level 7--------------------------------------  
					WHILE :ifcond71 > 0 and :ifcond72 > 0
					do
						select Top 1 "AcctCode" into acct7
							   from OACT
							   where "FatherNum" = :acct6 and 
							   "Levels" = 7 and 
							   "Groups" = :ErrNum and
								"GrpLine" = (select MIN("GrpLine") from OACT
												where "FatherNum" = :acct6 and
												"Levels" = 7 and "Groups" = :ErrNum);
						update OACT
						set "Groups" = :linetmp,
							"GroupMask" = :counter
						where "AcctCode" = :acct7;
						
						linetmp := :linetmp + 1;
					-------------------For Level 8 while Condition --------------------------------------		
					select count("AcctCode") into ifcond81 from OACT
						where "FatherNum" = :acct7 and "Levels" = 8 and
							"Groups" = :ErrNum;
									 
					select count("Postable") into ifcond82 from OACT 
						where "AcctCode" = :acct7 and "Postable" = 'N'; 
					
					-------------------Level 8--------------------------------------    
					WHILE :ifcond81 > 0 and :ifcond82 > 0
					do
							select Top 1 "AcctCode" into acct8
								   from OACT
							where "FatherNum" = :acct7 and "Levels" = 8 
							and "Groups" = :ErrNum and
										 "GrpLine" = (select MIN ("GrpLine") from OACT
															where "FatherNum" = :acct7 and
													 "Levels" = 8 and "Groups" = :ErrNum);
							update OACT
							set "Groups" = :linetmp,
								"GroupMask" = :counter
							where "AcctCode" = :acct8;
							linetmp := :linetmp + 1;
							
					-------------------For Level 9 while Condition --------------------------------------						
							select count("AcctCode") into ifcond91 from OACT
								where "FatherNum" = :acct8 and "Levels" = 9 and
										 "Groups" = :ErrNum;
							select count("Postable") into ifcond92 from OACT 
							where "AcctCode" = :acct8 and "Postable" = 'N';
							-------------------Level 9--------------------------------------   
							WHILE :ifcond91 > 0 and :ifcond92 > 0
							do
								select Top 1 "AcctCode" into acct9
									   from OACT
									   where "FatherNum" = :acct8 and "Levels" = 9 and "Groups" = :ErrNum and
											 "GrpLine" = (select MIN ("GrpLine") from OACT
														where "FatherNum" = :acct8 and
														"Levels" = 9 and "Groups" = :ErrNum);
								update OACT
								set "Groups" = :linetmp,
									"GroupMask" = :counter
								where "AcctCode" = :acct9;
								linetmp := :linetmp + 1;
								
								-------------------For Level 10 while Condition --------------------------------------						
								select count("AcctCode") into ifcond101 from OACT
										where "FatherNum" = :acct9 and "Levels" =10 and
											 "Groups" = :ErrNum;
											 
								select count("Postable") into ifcond102 from OACT 
									where "AcctCode" = :acct9 and "Postable" = 'N';
								-------------------Level 10--------------------------------------    	
								WHILE :ifcond101 > 0 and :ifcond102 > 0
								do 
									select Top 1 "AcctCode" into acct10
										   from OACT
									 where "FatherNum" = :acct9 and 
										   "Levels" = 10 and "Groups" = :ErrNum 
										   and	 "GrpLine" = (select MIN ("GrpLine") from OACT
																where "FatherNum" = :acct9 and
															  "Levels" = 10 and "Groups" = :ErrNum);
									update OACT
									set "Groups" = :linetmp,
										"GroupMask" = :counter
									where "AcctCode" = :acct10;
									linetmp := :linetmp + 1;							
									-------------------For Level 10 while Condition --------------------------------------						
									select count("AcctCode") into ifcond101 from OACT
										where "FatherNum" = :acct9 and "Levels" =10 and
												 "Groups" = :ErrNum;
												 
									select count("Postable") into ifcond102 from OACT 
										where "AcctCode" = :acct9 and "Postable" = 'N';
								end while;
							-------------------For Level 9 while Condition --------------------------------------						
								select count("AcctCode") into ifcond91 from OACT
									where "FatherNum" = :acct8 and "Levels" = 9 and
											 "Groups" = :ErrNum;
								select count("Postable") into ifcond92  from OACT 
								where "AcctCode" = :acct8 and "Postable" = 'N';
							end while;

			-------------------For Level 8 while Condition --------------------------------------					

						select count("AcctCode") into ifcond81 from OACT
							where "FatherNum" = :acct7 and "Levels" = 8 and
							"Groups" = :ErrNum;								
						select count("Postable") into ifcond82 from OACT
							where "AcctCode" = :acct7 and "Postable" = 'N';
					end while;
			-------------------For Level 7 while Condition --------------------------------------	

						select count("AcctCode") into ifcond71 from OACT
							where "FatherNum" = :acct6 and "Levels" = 7 and
									 "Groups" = :ErrNum;
									 
						select "Postable" into ifcond72 from OACT
							where "AcctCode" = :acct6 and  "Postable"= 'N'; 	
					end while;
				-------------------For Level 6 while Condition --------------------------------------	

					select count("AcctCode") into ifcond61 from OACT
						where "FatherNum" = :acct5 and "Levels" = 6 and
								 "Groups" = :ErrNum;

					select count("Postable") into ifcond62 from OACT
						where "AcctCode" = :acct5 and "Postable" = 'N';
				end while;
			-------------------For Level 5 while Condition --------------------------------------	

					select count("AcctCode") into ifcond51
						from OACT
					where "FatherNum" = :acct4 and "Levels" = 5 and
								 "Groups" = :ErrNum;
								 
					select count("Postable") into ifcond52 from OACT
						where "AcctCode" = :acct4 and "Postable" = 'N';
				end while;

				-------------------For Level 4 while Condition -------------------------------------

					select count("AcctCode") into ifcond41
						 from OACT
					where "FatherNum" = :acct3 and "Levels" = 4 and
							 "Groups" = :ErrNum;
					select count("Postable") into ifcond42 from OACT
						where "AcctCode" = :acct3 and "Postable" = 'N';
			end while;
		-------------------For Level 3 while condition-----------------------------------

				select count("AcctCode") into ifcond31
		 		  	from OACT
				  where "FatherNum" = :acct2 and "Levels" = 3 and
				                "Groups" = :ErrNum;
				select count("Postable") into ifcond32
				  	from OACT
				  where "AcctCode" = :acct2 and
					 "Postable" = 'N'; 
		  end while;
 -------------------For Level 2 while condition-----------------------------------

      select count("AcctCode") into ifcond2 from OACT
          where "FatherNum" = :acct1 and "Levels" = :level and     
			 "Groups" = :ErrNum;
    end while;
	
	lineout := :linetmp;

	return;
end;

