CREATE PROCEDURE TmSp_ConGrpLine_OACT_recurs(
in acct1 NVARCHAR(15),
in line int,
in counter tinyint,
in ErrNum int,
OUT LineOut int
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
tempLine int;
level int;
sonCount int;
brotherCount int;
cur_acct nvarchar(15);
cur_acct2 nvarchar(15);
postable nvarchar(15);
something_left SMALLINT;
brother_exist SMALLINT;
BEGIN

	if :line = 2
	then
		level := 2;
	else
		SELECT "Levels" + 1 INTO level FROM OACT WHERE "AcctCode" = :acct1;
	end if;	

	tempLine := :line;
	cur_acct := :acct1;
	something_left := 1;

	while (something_left = 1) do
		sonCount := 0;		
		SELECT "Postable" INTO postable FROM OACT WHERE "AcctCode" = cur_acct;
		if (postable = 'N') then
			SELECT count("AcctCode") INTO sonCount FROM OACT 
				WHERE "FatherNum" = :cur_acct AND "Levels" = :level AND "Groups" = :ErrNum;
		end if;
		
		if (sonCount > 0) then
-- has son
			SELECT Top 1 "AcctCode" into cur_acct2 FROM OACT
				WHERE "FatherNum" = :cur_acct AND "Levels" = :level AND "Groups" = :ErrNum AND
				"GrpLine" = (SELECT MIN ("GrpLine") from OACT
						WHERE "FatherNum" = :cur_acct AND
							"Levels" = :level and "Groups" = :ErrNum);
			
			UPDATE OACT SET "Groups" = :tempLine, "GroupMask" = :counter
				WHERE "AcctCode" = :cur_acct2;
            
			cur_acct := :cur_acct2;
			tempLine := :tempLine + 1;
			level := :level + 1;

		else
-- do not have son, search brother
			brother_exist := 0;
			while (brother_exist = 0) AND (something_left <> 0) do
				level := :level - 1;
				SELECT "FatherNum" into cur_acct FROM OACT WHERE "AcctCode" = cur_acct;

				SELECT count("AcctCode") into brotherCount FROM OACT
					WHERE "FatherNum" = :cur_acct AND "Levels" = :level AND "Groups" = :ErrNum;

				if ((cur_acct = acct1) AND (brotherCount = 0)) or (cur_acct is NULL) then
					something_left := 0;
				end if;
				if (brotherCount > 0) then 
					brother_exist := 1;
				else
					brother_exist := 0;
				end if;
			end while;
				
		end if;
			
	end while;
	
END;

-- B1 DEPENDS: AFTER:SP:TmSp_ConGrpLine_OACT_recurs AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_ConvertGrpLine_OACT (in v_RandomNum nvarchar(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
------------------------------------------------------------
acct1 nvarchar(15);
acct2 nvarchar(15);
line int;
lineOut int;
counter tinyint;
countnew tinyint;
maxlevel tinyint;
ErrNum int;
rownum int;
rowcount int;
BEGIN
IF :v_RandomNum <> '' THEN

select "MaxActGrps" INTO maxlevel from CINF;

--maxlevel := 10;
counter := 1;
ErrNum := 10000;

update OACT set "GrpLine" = 0 where "GrpLine" is NULL;

update OACT set "Groups" = :ErrNum;

WHILE :counter <= :maxlevel 
do
 IF :counter <= 9 
 THEN
 SELECT CAST(:counter as nvarchar(1)) into acct1 FROM dummy;
 acct1 := :acct1 || '00000000000000';
   -- acct1 := cast (:counter as nvarchar(1)) + '00000000000000';
 ELSE 
    SELECT ASCII('A') into countnew  FROM dummy;
    countnew := :countnew + :counter - 10;
    select CHAR(:countnew) into acct1 from dummy;
    acct1 := :acct1 || '00000000000000';
  -- acct1 := char(ASCII ('A') + :counter - 10) + '00000000000000';
 END IF;

 update "OACT"
 set "Groups" = 1,
     "GroupMask" = :counter,
     "Levels" =1,
     "FatherNum" = NULL, 
     "Postable" = 'N'
 where "AcctCode" = :acct1;

 line := 2;
 
 CALL TmSp_ConGrpLine_OACT_recurs(:acct1,:line,:counter,:ErrNum, lineOut);

 counter := :counter + 1 ;

END WHILE;





update "OACT"
set "GrpLine" = "Groups",
    "Groups" = NULL;

counter := 1;

WHILE :counter <= :maxlevel
  do
 
 select MAX ("GrpLine") into line from OACT
                          where "GroupMask" =:counter and
                          "GrpLine" <> :ErrNum ;
 line := :line + 1; 
 IF :counter <= 9
  then
   SELECT CAST(:counter as nvarchar(1)) into acct1 FROM dummy;
   acct1 := :acct1 || '00000000000000';
 --set @acct1= cast (@counter as nvarchar(1)) + '00000000000000'
 ELSE 
    SELECT ASCII('A') into countnew  FROM dummy;
    countnew := :countnew + :counter - 10;
    select CHAR(:countnew) into acct1 from dummy;
    acct1 := :acct1 || '00000000000000';
  --set @acct1= char (ASCII ('A') + @counter - 10) + '00000000000000'
end if;
select count(1) into rownum from "OACT"
               where "GrpLine" = :ErrNum and
               "GroupMask" = :counter;
 WHILE :rownum > 0
 do
 select count("AcctCode") into rowcount 
         from "OACT"
         where "GrpLine" = :ErrNum and
               "GroupMask" = :counter;
 if rowcount > 0
 then
   select Top 1 "AcctCode" into acct2
         from "OACT"
         where "GrpLine" = :ErrNum and
               "GroupMask" = :counter
		ORDER BY "AcctCode";
  else acct2 := '';
  end if;
  
  
 
  if :acct2 <> ''
  then
  update "OACT"
  set "Levels" = 2,
      "FatherNum" = :acct1,
      "GrpLine" = :line
  where "AcctCode" = :acct2;
  end if;
  
  
  line := :line + 1;
  select count(1) into rownum from "OACT"
               where "GrpLine" = :ErrNum and
               "GroupMask" = :counter;
 END while;
 counter := :counter + 1;
  --select :acct2 from dummy;
END while;

END IF;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_CorrActReport(IN account NVARCHAR(255),
									IN	dateFrom NVARCHAR(8),
									IN	dateTo NVARCHAR(8))
										
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	SELECT "Account" AS "Acct",
		SUM("Debit") AS "DebitLC",
		SUM("Credit") AS "CreditLC",
		SUM("SYSDeb") AS "DebitSC",
		SUM("SYSCred") AS "CreditSC",
		0 AS "Sort"
	FROM JDT1 AS Lines, OJDT AS Header
	WHERE Header."TransId" = Lines."TransId"
	AND "Account" = :account
	AND Header."RefDate" < TO_TIMESTAMP(:dateFrom)
	GROUP BY "Account"
	
	UNION ALL

	SELECT :account AS "Acct", 0 AS "DebitLC", 0 AS "CreditLC", 0 AS "DebitSC", 0 AS "CreditSC", 0 AS "Sort" FROM DUMMY
	WHERE NOT EXISTS
	(
		SELECT 1
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE Header."TransId" = Lines."TransId"
		AND "Account" = :account
		AND Header."RefDate" < TO_TIMESTAMP(:dateFrom)
	)
		
	UNION ALL

	SELECT "Acct",
		SUM("CreditLC") AS "DebitLC",
		SUM("DebitLC") AS "CreditLC",
		SUM("CreditSC") AS "DebitSC",
		SUM("DebitSC") AS "CreditSC",
		1 AS "Sort"
	FROM
	(
		SELECT Lines."Account" AS "Acct",
			SUM("Debit") AS "DebitLC",
			SUM("Credit") AS "CreditLC",
			SUM("SYSDeb") AS "DebitSC",
			SUM("SYSCred") AS "CreditSC"
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE (
			"ContraAct" IN
			(
				SELECT "CardCode"
				FROM OCRD
				WHERE "DebPayAcct" = :account

				UNION ALL

				SELECT "CardCode"
				FROM CRD3
				WHERE "AcctCode" = :account
			)
			OR "ContraAct" = :account
		) AND :account IN
		(
			SELECT "Account"
			FROM JDT1
			WHERE JDT1."TransId" = Header."TransId"
		)
		AND "Account" <> :account
		AND Lines."TransId" = Header."TransId"
		GROUP BY "Account", Header."RefDate"
		HAVING Header."RefDate"
		BETWEEN TO_TIMESTAMP(:dateFrom) 
		AND TO_TIMESTAMP(:dateTo)
		
		UNION ALL
	
-- Debit and credit are swapped intentionally
		SELECT Lines1."Account" AS "Acct",
			SUM(Lines2."Credit") AS "DebitLC",
			SUM(Lines2."Debit") AS "CreditLC",
			SUM(Lines2."SYSCred") AS "DebitSC",
			SUM(Lines2."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines1, JDT1 AS Lines2, OJDT AS Header
		WHERE Lines1."TransId" = Lines2."TransId"
		AND Lines1."TransId" = Header."TransId"
		AND Lines2."Account" = :account
		AND Lines2."ContraAct" = Lines1."ShortName"
		AND (Lines1."ContraAct" IS NULL or Lines1."ContraAct" = '')
		AND ((Lines2."Credit" < Lines1."Debit" AND Lines2."Credit" > 0) OR (Lines2."Credit" > Lines1."Debit" AND Lines2."Credit" < 0) OR
			(Lines2."Debit" < Lines1."Credit" AND Lines2."Debit" > 0) OR (Lines2."Debit" > Lines1."Credit" AND Lines2."Debit" < 0))
		AND Header."RefDate"
			BETWEEN TO_TIMESTAMP(:dateFrom) 
			AND TO_TIMESTAMP(:dateTo)
		GROUP BY Lines1."Account"
	
		UNION ALL
	
		SELECT Lines1."Account" AS "Acct",
			SUM(Lines1."Debit") AS "DebitLC",
			SUM(Lines1."Credit") AS "CreditLC",
			SUM(Lines1."SYSDeb") AS "DebitSC",
			SUM(Lines1."SYSCred") AS "CreditSC"
		FROM JDT1 AS Lines1, JDT1 AS Lines2, OJDT AS Header
		WHERE Lines1."TransId" = Lines2."TransId"
		AND Lines1."TransId" = Header."TransId"
		AND Lines2."Account" = :account
		AND Lines2."ContraAct" = Lines1."ShortName"
		AND (Lines1."ContraAct" IS NULL or Lines1."ContraAct" = '')
		AND ((Lines2."Credit" > Lines1."Debit" AND Lines2."Credit" > 0) OR (Lines2."Credit" < Lines1."Debit" AND Lines2."Credit" < 0) OR
			(Lines2."Debit" > Lines1."Credit" AND Lines2."Debit" > 0) OR (Lines2."Debit" < Lines1."Credit" AND Lines2."Debit" < 0))
		AND Header."RefDate"
			BETWEEN TO_TIMESTAMP(:dateFrom) 
			AND TO_TIMESTAMP(:dateTo)
		GROUP BY Lines1."Account"
		
		UNION ALL

-- Debit and credit are swapped intentionally
		SELECT Lines1."Account" AS "Acct",
			SUM(-Lines3."Credit") AS "DebitLC",
			SUM(-Lines3."Debit") AS "CreditLC",
			SUM(-Lines3."SYSCred") AS "DebitSC",
			SUM(-Lines3."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines1, JDT1 AS Lines2, JDT1 AS Lines3, OJDT AS Header
		WHERE Lines2."TransId" = Lines3."TransId"
		AND Lines1."TransId" = Lines2."TransId"
		AND Lines1."TransId" = Header."TransId"
		AND Lines3."ContraAct" = Lines1."ShortName"
		AND Lines3."Account" <> :account
		AND Lines2."Account" = :account
		AND Lines2."ContraAct" = Lines1."ShortName"
		AND (Lines1."ContraAct" IS NULL or Lines1."ContraAct" = '')
		AND ((Lines2."Credit" > Lines1."Debit" AND Lines2."Credit" > 0) OR (Lines2."Credit" < Lines1."Debit" AND Lines2."Credit" < 0) OR
			(Lines2."Debit" > Lines1."Credit" AND Lines2."Debit" > 0) OR (Lines2."Debit" < Lines1."Credit" AND Lines2."Debit" < 0))
		AND Header."RefDate"
			BETWEEN TO_TIMESTAMP(:dateFrom) 
			AND TO_TIMESTAMP(:dateTo)
		GROUP BY Lines1."Account"
		
		UNION ALL

		SELECT 'Wrong correspondence 1' AS "Acct",
			SUM(Lines."Debit") AS "DebitLC",
			SUM(Lines."Credit") AS "CreditLC",
			SUM(Lines."SYSDeb") AS "DebitSC",
			SUM(Lines."SYSCred") AS "CreditSC"
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE Header."TransId" = Lines."TransId"
		AND Lines."Account" = :account
		AND Lines."ContraAct" IS NULL
		AND NOT EXISTS
		(
			SELECT 1 FROM JDT1
			WHERE Lines."TransId" = JDT1."TransId"
			AND JDT1."ContraAct" = Lines."ShortName"
		)
		AND Header."RefDate"
			BETWEEN TO_TIMESTAMP(:dateFrom) 
			AND TO_TIMESTAMP(:dateTo)
		GROUP BY "Account"
		
		UNION ALL

		SELECT 'Wrong correspondence 2' AS "Acct",
			SUM(Lines."Debit") AS "DebitLC",
			SUM(Lines."Credit") AS "CreditLC",
			SUM(Lines."SYSDeb") AS "DebitSC",
			SUM(Lines."SYSCred") AS "CreditSC"
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE Header."TransId" = Lines."TransId"
		AND Lines."Account" = :account
		AND Lines."ContraAct" IS NOT NULL
		AND Lines."ContraAct" <> ''
		AND NOT EXISTS
		(
			SELECT 1 FROM JDT1
			WHERE Lines."TransId" = JDT1."TransId"
			AND JDT1."ShortName" = Lines."ContraAct"
		)
		AND Header."RefDate"
			BETWEEN TO_TIMESTAMP(:dateFrom) 
			AND TO_TIMESTAMP(:dateTo)
		GROUP BY "Account"
	
	) DUMMY
	GROUP BY "Acct"
	ORDER BY "Sort", "Acct";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_CorrActReport_BP(IN account  NVARCHAR(255),	
									   IN dateFrom  NVARCHAR(8),
									   IN dateTo  NVARCHAR(8))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
	SELECT "ShortName" AS "Acct",
		SUM("Debit") AS "DebitLC",
		SUM("Credit") AS "CreditLC",
		SUM("SYSDeb") AS "DebitSC",
		SUM("SYSCred") AS "CreditSC",
		0 AS "Sort"
	FROM JDT1 AS Lines, OJDT AS Header
	WHERE Header."TransId" = Lines."TransId"
	AND "ShortName" = :account
	AND Header."RefDate" < TO_TIMESTAMP(:dateFrom)
	GROUP BY "ShortName"

	UNION ALL

	SELECT :account AS "Acct", 0 AS "DebitLC", 0 AS "CreditLC", 0 AS "DebitSC", 0 AS "CreditSC", 0 AS "Sort" FROM DUMMY
	WHERE NOT EXISTS
	(
		SELECT 1
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE Header."TransId" = Lines."TransId"
		AND "ShortName" = :account
		AND Header."RefDate" < TO_TIMESTAMP(:dateFrom)
	)
	
	UNION ALL

	SELECT "Acct",
		SUM("CreditLC") AS "DebitLC",
		SUM("DebitLC") AS "CreditLC",
		SUM("CreditSC") AS "DebitSC",
		SUM("DebitSC") AS "CreditSC",
		1 AS "Sort"
	FROM
	(
		SELECT "Account" AS "Acct",
			SUM("Debit") AS "DebitLC",
			SUM("Credit") AS "CreditLC",
			SUM("SYSDeb") AS "DebitSC",
			SUM("SYSCred") AS "CreditSC"
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE "ContraAct" = :account
		AND Lines."TransId" = Header."TransId"
		GROUP BY "Account", Header."RefDate"
		HAVING Header."RefDate" BETWEEN TO_TIMESTAMP(:dateFrom) AND TO_TIMESTAMP(:dateTo)
	
		UNION ALL
	
		-- Debit and credit are swapped intentionally
		SELECT Lines1."Account" AS "Acct",
			SUM(Lines2."Credit") AS "DebitLC",
			SUM(Lines2."Debit") AS "CreditLC",
			SUM(Lines2."SYSCred") AS "DebitSC",
			SUM(Lines2."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines1, JDT1 AS Lines2, OJDT AS Header
		WHERE Lines1."TransId" = Lines2."TransId"
		AND Lines1."TransId" = Header."TransId"
		AND Lines2."ShortName" = :account
		AND Lines2."ContraAct" = Lines1."ShortName"
		AND (Lines1."ContraAct" IS NULL or Lines1."ContraAct" = '')
		AND (
				(Lines2."Credit" < Lines1."Debit" AND Lines2."Credit" > 0) 
			 OR (Lines2."Credit" > Lines1."Debit" AND Lines2."Credit" < 0) 
			 OR	(Lines2."Debit" < Lines1."Credit" AND Lines2."Debit" > 0) 
			 OR (Lines2."Debit" > Lines1."Credit" AND Lines2."Debit" < 0)
			 )
		AND Header."RefDate" BETWEEN TO_TIMESTAMP(:dateFrom) AND TO_TIMESTAMP(:dateTo)
		GROUP BY Lines1."Account"

		UNION ALL

		SELECT Lines1."Account" AS "Acct",
			SUM(Lines1."Credit") AS "DebitLC",
			SUM(Lines1."Debit") AS "CreditLC",
			SUM(Lines1."SYSCred") AS "DebitSC",
			SUM(Lines1."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines1, JDT1 AS Lines2, OJDT AS Header
		WHERE Lines1."TransId" = Lines2."TransId"
		AND Lines1."TransId" = Header."TransId"
		AND Lines2."ShortName" = :account
		AND Lines2."ContraAct" = Lines1."ShortName"
		AND (Lines1."ContraAct" IS NULL or Lines1."ContraAct" = '')
		AND ((Lines2."Credit" > Lines1."Debit" AND Lines2."Credit" > 0) 
		  OR (Lines2."Credit" < Lines1."Debit"  AND Lines2."Credit" < 0) 
		  OR (Lines2."Debit" > Lines1."Credit" AND Lines2."Debit" > 0) 
		  OR (Lines2."Debit" < Lines1."Credit" AND Lines2."Debit" < 0))
		AND Header."RefDate" BETWEEN TO_TIMESTAMP(:dateFrom) AND TO_TIMESTAMP(:dateTo)
		GROUP BY Lines1."Account"

		UNION ALL

-- Debit and credit are swapped intentionally
		SELECT Lines1."Account" AS "Acct",
			SUM(-Lines3."Credit") AS "DebitLC",
			SUM(-Lines3."Debit") AS "CreditLC",
			SUM(-Lines3."SYSCred") AS "DebitSC",
			SUM(-Lines3."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines1, JDT1 AS Lines2, JDT1 AS Lines3, OJDT AS Header
		WHERE Lines2."TransId" = Lines3."TransId"
		AND Lines1."TransId" = Lines2."TransId"
		AND Lines1."TransId" = Header."TransId"
		AND Lines3."ContraAct" = Lines1."ShortName"
		AND Lines3."ShortName" <> :account
		AND Lines2."ShortName" = :account
		AND Lines2."ContraAct" = Lines1."ShortName"
		AND (Lines1."ContraAct" IS NULL or Lines1."ContraAct" = '')
		AND (
			(Lines2."Credit" > Lines1."Debit" AND Lines2."Credit" > 0) 
			OR (Lines2."Credit" < Lines1."Debit" AND Lines2."Credit" < 0) 
			OR (Lines2."Debit" > Lines1."Credit" AND Lines2."Debit" > 0) 
			OR (Lines2."Debit" < Lines1."Credit" AND Lines2."Debit" < 0)
			)
		AND Header."RefDate" BETWEEN TO_TIMESTAMP(:dateFrom) AND TO_TIMESTAMP(:dateTo)
		GROUP BY Lines1."Account"

		UNION ALL

		SELECT 'Wrong correspondence 1' AS "Acct",
			SUM(Lines."Credit") AS "DebitLC",
			SUM(Lines."Debit") AS "CreditLC",
			SUM(Lines."SYSCred") AS "DebitSC",
			SUM(Lines."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE Header."TransId" = Lines."TransId"
		AND Lines."ShortName" = :account
		AND (Lines."ContraAct" IS NULL  OR Lines."ContraAct" = '')
		AND NOT EXISTS
		(
			SELECT 1 FROM JDT1
			WHERE Lines."TransId" = JDT1."TransId"
			AND JDT1."ContraAct" = Lines."ShortName"
		)
		AND Header."RefDate" BETWEEN TO_TIMESTAMP(:dateFrom) AND TO_TIMESTAMP(:dateTo)
		GROUP BY "Account"

		UNION ALL

		SELECT 'Wrong correspondence 2' AS "Acct",
			SUM(Lines."Credit") AS "DebitLC",
			SUM(Lines."Debit") AS "CreditLC",
			SUM(Lines."SYSCred") AS "DebitSC",
			SUM(Lines."SYSDeb") AS "CreditSC"
		FROM JDT1 AS Lines, OJDT AS Header
		WHERE Header."TransId" = Lines."TransId"
		AND Lines."ShortName" = :account
		AND Lines."ContraAct" IS NOT NULL
		AND Lines."ContraAct" <> '' 
		AND NOT EXISTS
		(
			SELECT 1 FROM JDT1
			WHERE Lines."TransId" = JDT1."TransId"
			AND JDT1."ShortName" = Lines."ContraAct"
		)
		AND Header."RefDate" BETWEEN TO_TIMESTAMP(:dateFrom) AND TO_TIMESTAMP(:dateTo)
		GROUP BY "Account"
	
	) DUMMY
	GROUP BY "Acct"
	ORDER BY "Sort", "Acct";
END;

