     end if;

	sql1 := 'CREATE VIEW "'||current_schema||'"."B1_OcrbIBANView"  '||
	'AS  '||
	'SELECT T0."AbsEntry", T0."CardCode", REPLACE(T0."IBAN", '' '', '''') "IBAN", T0."ISRBillerI", T0."CustIdNum" FROM "'||current_schema||'"."OCRB" T0 '; 

	exec (:sql1);

END

