BEGIN

	-- DROP TEMP TABLE
	/*SELECT COUNT (*) INTO v_TempInt FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME = '#CASHFLOW_TMPACCTTOSHOW' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
