-- B1 DEPENDS: AFTER:PT:PROCESS_END
--DROP PROCEDURE TmSp_DAB004_AccountList_QRYSTR;
CREATE PROCEDURE TmSp_DAB004_AccountList_QRYSTR(in Indexer int, OUT outQryString nvarchar(8000))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BoeEnable nchar;
SgmActEnable nchar;
LocalSet nvarchar(3); 
ApaCheck nchar;
--QryString nvarchar(max);
QryString nvarchar(8000);
PeriodCategory nvarchar(10);
PerPageVal int := 0;
CommonStr nvarchar(8000);
ActSep nchar;

BEGIN

	SELECT "EnableBOE", "EnbSgmnAct", "LawsSet" INTO BoeEnable, SgmActEnable, LocalSet FROM CINF;

	IF :LocalSet = N'CN' OR :LocalSet = N'JP' THEN
		ApaCheck := N'Y';
	ELSE
		ApaCheck := N'N';
	END IF;
	
	SELECT "ActSep" INTO ActSep FROM OADM;

	--- Initialization
	PerPageVal := 5;

	--- Period Category
	SELECT "Category" INTO PeriodCategory FROM OFPR 
	GROUP BY "Category" HAVING MIN(TO_DATE("F_RefDate")) <= TO_DATE(CURRENT_TIMESTAMP) AND MAX(TO_DATE("T_RefDate")) >= TO_DATE(CURRENT_TIMESTAMP);
	
	---Remove duplicated record
	CommonStr := ' SELECT T6."AcctCode", T6."AcctName", T6."Balance", MIN(T6."AcctType") "AcctType" FROM (';

	-----'A' represent Cash Account, 'C' represent Check Account, 'D' represent Credit Card, 'E' represent Boe, 'V' represent Voucher, 'U' represent Vendor deduct, 'M' represent Customer deduct
	---Cash account
	CommonStr := :CommonStr || ' SELECT T0."AcctCode" "AcctCode", T0."AcctName" "AcctName", T0."CurrTotal" "Balance", ''A'' "AcctType" FROM OACT T0 WHERE T0."Finanse" = ''Y''' ||
	' UNION';
	 
	IF :ApaCheck <> N'Y' THEN
		----Check account not in CN,JP
		--- Check receivable
		CommonStr := :CommonStr || ' SELECT T1."AcctCode" "AcctCode", T1."AcctName" "AcctName", T1."CurrTotal" "Balance", ''C'' "AcctType" FROM OACP T0 INNER JOIN OACT T1 ON T0."LinkAct_2" = T1."AcctCode"' || 
		' WHERE T0."PeriodCat" = ''' || :PeriodCategory || '''' || 
		' UNION';
		--- Check in transactions
		CommonStr := :CommonStr || ' SELECT T0."CashCheck" "AcctCode", MIN(T1."AcctName") "AcctName", MIN(T1."CurrTotal") "Balance", ''C'' "AcctType" FROM OCHH T0 INNER JOIN OACT T1 ON T0."CashCheck" = T1."AcctCode"' || 
		' GROUP BY T0."CashCheck"' ||
		' UNION';
	END IF;

	IF :BoeEnable = N'Y' THEN
		--- Boe account enable
		--- Boe receivable, payable...
		CommonStr := :CommonStr || ' SELECT T1."AcctCode" "AcctCode", T1."AcctName" "AcctName", T1."CurrTotal" "Balance", ''E'' "AcctType" FROM OACP T0 , OACT T1' ||
		' WHERE (T0."CBoERcvble" = T1."AcctCode" OR' ||
				' T0."CBoEOnClct" = T1."AcctCode" OR' || 
				' T0."CBoEDiscnt" = T1."AcctCode" OR' || 
				' T0."CBoEPresnt" = T1."AcctCode" OR' || 
				' T0."CUnpaidBoE" = T1."AcctCode" OR' || 
				' T0."VBoEPayble" = T1."AcctCode" OR' || 
				' T0."VAsstBoEPy" = T1."AcctCode") AND T0."PeriodCat" = ''' || :PeriodCategory || ''''  
		' UNION';
		
		---Boe in transactions
		CommonStr := :CommonStr || ' SELECT T0."AcctCode" "AcctCode", MIN(T1."AcctName") "AcctName", MIN(T1."CurrTotal") "Balance", ''E'' "AcctType" FROM CRD3 T0 INNER JOIN  OACT T1 ON T0."AcctCode" = T1."AcctCode"' || 
		' WHERE T0."AcctType" IN (''R'', ''P'', ''C'', ''S'', ''Y'', ''I'', ''U'')'  ||
		' GROUP BY T0."AcctCode"' ||
		' UNION';
	END IF;

	--- Credit card
	CommonStr := :CommonStr || ' SELECT T0."CreditAcct" "AcctCode", MIN(T1."AcctName") "AcctName", MIN(T1."CurrTotal") "Balance", ''D'' "AcctType" FROM OCRH T0 INNER JOIN OACT T1 ON T0."CreditAcct" = T1."AcctCode"' ||
	' GROUP BY T0."CreditAcct"' || 
	' ) T6 GROUP BY T6."AcctCode", T6."AcctName", T6."Balance"';
	
	--- Voucher
	CommonStr := :CommonStr || ' UNION' ||
	' SELECT T1."AcctCode" "AcctCode", T1."AcctName" "AcctName", T1."CurrTotal" "Balance", ''V'' "AcctType" FROM OACP T0, OACT T1' ||
	' WHERE ( T0."LinkAct_5" = T1."AcctCode" OR' || 
			' T0."LinkAct_14" = T1."AcctCode" OR' ||
			' T0."LinkAct_15" = T1."AcctCode" ) AND T0."PeriodCat" = ''' || :PeriodCategory || '''';
	
	--- Customer Deduct account
	CommonStr := :CommonStr || ' UNION' || 
	' SELECT T1."AcctCode" "AcctCode", T1."AcctName" "AcctName", T1."CurrTotal" "Balance", ''M'' "AcctType" FROM OACP T0, OACT T1' ||
	' WHERE  T0."LinkAct_6" = T1."AcctCode" AND T0."PeriodCat" = ''' || :PeriodCategory || ''''; 
	
	--- Vendor Deduct account
	CommonStr := :CommonStr || ' UNION ' ||
	' SELECT T1."AcctCode" "AcctCode", T1."AcctName" "AcctName", T1."CurrTotal" "Balance", ''U'' "AcctType" FROM OACP T0, OACT T1' ||
	' WHERE  T0."LinkAct_16" = T1."AcctCode" AND T0."PeriodCat" = ''' || :PeriodCategory || ''''; 
	
	--- Final Query  
	--- Return different result collection according to @Indexer
	IF :Indexer <> 0 THEN
		----First Line is special line including total records& result type
		QryString := ' SELECT ''A'' as "AcctCode", NULL as "AcctName", COUNT(0) as "Balance" FROM (' || 
					:CommonStr || ' ) AS T7 WHERE T7."AcctType" NOT IN (''M'',''U'',''V'')' ||
					' UNION ALL (';
		IF :SgmActEnable = N'Y' THEN
			QryString := :QryString || ' SELECT REPLACE(RTRIM(IFNULL(T9."Segment_0",'''')||'' ''||IFNULL(T9."Segment_1",'''')||'' ''||IFNULL(T9."Segment_2",'''')||'' ''||IFNULL(T9."Segment_3",'''')||'' ''||IFNULL(T9."Segment_4",'''')||'' ''||IFNULL(T9."Segment_5",'''')||'' ''||IFNULL(T9."Segment_6",'''')||'' ''||IFNULL(T9."Segment_7",'''')||'' ''||IFNULL(T9."Segment_8",'''')||'' ''||IFNULL(T9."Segment_9",'''')),'' '','''||:ActSep||'''), T8."AcctName", T8."Balance"';
		ELSE
			QryString := :QryString || ' SELECT T8.*';					   
		END IF;
		
		QryString := :QryString || ' FROM ((SELECT TOP ' || :Indexer*:PerPageVal || ' T7."AcctCode", T7."AcctName", T7."Balance" FROM (' ||
					:CommonStr || ' ) AS T7 WHERE T7."AcctType" NOT IN (''M'', ''U'', ''V'')  ORDER BY T7."AcctCode")';
		
		IF :Indexer > 1 THEN
			QryString := :QryString || ' EXCEPT' ||
						' (SELECT TOP ' || (:Indexer-1)*:PerPageVal || ' T7."AcctCode", T7."AcctName", T7."Balance" FROM (' ||
						:CommonStr || ' ) AS T7 WHERE T7."AcctType" NOT IN (''M'', ''U'', ''V'') ORDER BY T7."AcctCode")';						  
		END IF;

		QryString := :QryString || ' ) AS T8';
		
		IF :SgmActEnable = N'Y' THEN
			QryString := :QryString || ' LEFT OUTER JOIN OACT T9 ON T8."AcctCode" = T9."AcctCode"';
		END IF;
		
		QryString := :QryString || ' ORDER BY T8."AcctCode")';
	ELSE
		QryString := ' SELECT T7."AcctCode", T7."AcctName", T7."AcctType" FROM (' || :CommonStr || ' ) AS T7 ORDER BY T7."AcctCode"';
	END IF;
	
	--SELECT QryString FROM DUMMY;
	--EXEC :QryString;
	outQryString := :QryString;
END;

-- B1 DEPENDS: AFTER:SP:TmSp_DAB004_AccountList_QRYSTR AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_DAB004_CashFlowDetails 
	(IN IntervalSeq INTEGER, 
	IN IncomingPage INTEGER, 
	IN OutgoingPage INTEGER, 
	IN PerPageVal INTEGER, 
	IN Threshold DECIMAL(21,6),
	IN IntervalVal nvarchar(1), 
	IN VoucherFlag nvarchar(1), 
	IN RecurringFlag nvarchar(1)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 

	/********* Begin Procedure Script ************/
	v_Today DateTime;
	v_DateFrom	  DateTime;
	v_DateTo	  DateTime;
	v_BoeEnable    nvarchar(1);
	v_SgmActEnable nvarchar(1);
	v_LocalSet     nvarChar(3);
	v_ApaCheck     nvarchar(1);
	v_QryString    nvarChar(8000);
	v_FmtString    nvarChar(100);
	v_Frequency nvarchar(1);
	v_SubFrequncy INTEGER;
	v_LimitFlag nvarchar(1);
	v_LimitDate DateTime;
	v_Currency nVarchar(3);
	v_CtrAcct nVarchar(15);
	v_AcctCode nVarchar(15);
	v_NextDue DateTime;
	v_Debit DECIMAL(21,6);
	v_Credit DECIMAL(21,6);
	v_MainCurrency nVarchar(3);
	v_DirectRateFlag nvarchar(1);
	v_Rate DECIMAL(21,6);
	v_DebitCurrency nVarchar(3);
	v_CreditCurrency nVarchar(3);
	v_Instance INTEGER;
	v_RcurCode nvarChar(8);
	v_Ref nvarChar(11);
	v_NegativeThreshold DECIMAL(21,6);
	v_CustomerDeduct nVarchar(15);
	v_VendorDeduct nVarchar(15);
	v_IncomingCount INTEGER;
	v_OutgoingCount INTEGER;
	v_TempInt INTEGER;
	v_FilterInBPFlag nvarchar(1);
	
	v_FrequencyC nvarchar(1);
	v_SubFrequncyC INTEGER;
	v_LimitFlagC nvarchar(1);
	v_LimitDateC DateTime;
	v_CurrencyC nVarchar(3);
	v_RcurCodeC nvarChar(8);
	v_RefC nvarChar(11);
	v_CtrAcctC nVarchar(15);
	v_AcctCodeC nVarchar(15);
	v_InstanceC INTEGER;
	v_NextDueC DateTime;
	v_DebitC DECIMAL(21,6);
	v_CreditC DECIMAL(21,6);
	v_DebitCurrencyC nVarchar(3);
	v_CreditCurrencyC nVarchar(3);
	
	in_IntervalVal  nvarchar(1);
	in_VoucherFlag nvarchar(1);
	in_RecurringFlag nvarchar(1);
	--- CURSOR DEFINE
	CURSOR c_RecurTransQry (DateTo DATE, Threshold DECIMAL(21,6), NegativeThreshold DECIMAL(21,6)) FOR
		SELECT T0."Frequency", T0."Remind", T0."LimitRtrns", T0."LimitDate", T1."Currency", T0."RcurCode"
			, T0."Ref1", T1."CtrlAcct", T1."AcctCode", T1."Instance", T0."NextDeu", T1."Debit", T1."Credit"  
		FROM ORCR T0 
		INNER JOIN RCR1 T1 ON T1."RcurCode" = T0."RcurCode" AND T0."Instance" = T1."Instance"
		WHERE T0."Frequency" <> 'T'  AND T0."NextDeu" <= :DateTo AND 
			(T0."LimitRtrns" <> 'Y' OR T0."NextDeu" <= T0."LimitDate") AND
	    		(T1."Debit" > :Threshold OR T1."Credit" > :Threshold OR T1."Debit" < :NegativeThreshold OR T1."Credit" < :NegativeThreshold);
	
	CURSOR c_ProjectQry1 (DateFrom DATE, DateTo DATE, Threshold DECIMAL(21,6), NegativeThreshold DECIMAL(21,6)) FOR 
		SELECT "DateID", "Debit", "DebCur", "Credit", "CredCur" 
		FROM OCFL 
		WHERE ("SecLevel" >= 1 AND "SecLevel" <= 6) AND ("DateID" BETWEEN :DateFrom AND :DateTo) AND
			("Debit" > :Threshold OR "Credit" > :Threshold OR "Debit" < :NegativeThreshold OR "Credit" < :NegativeThreshold);
			
	CURSOR c_ProjectQry2 (DateFrom DATE, DateTo DATE, Threshold DECIMAL(21,6), NegativeThreshold DECIMAL(21,6)) FOR
		  SELECT "DateID", "Debit", "DebCur", "Credit", "CredCur" 
		  FROM OCFL 
		  WHERE ("SecLevel" >= 1 AND "SecLevel" < 6) AND ("DateID" BETWEEN :DateFrom AND :DateTo) AND
		  	("Debit" > :Threshold OR "Credit" > :Threshold OR "Debit" < :NegativeThreshold OR "Credit" < :NegativeThreshold);
		
BEGIN
	--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:IntervalVal);    
    call _TmSp_ValidateSpParam(:VoucherFlag);    
	call _TmSp_ValidateSpParam(:RecurringFlag);   
	
	-- DROP TEMP TABLE
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPOCRD' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpOCRD;
	END IF;
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPACCT' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpAcct;
	END IF;
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPDETAIL' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpDetail;
	END IF;
	
	in_IntervalVal := :IntervalVal;
	in_VoucherFlag := :VoucherFlag;
	in_RecurringFlag := :RecurringFlag;
 
	IF (:IntervalVal = '' or LENGTH(:IntervalVal) = 0) THEN
		in_IntervalVal := 'D';
	END IF;
	 
	IF (:VoucherFlag = '' or LENGTH(:VoucherFlag) = 0) THEN
		in_VoucherFlag := 'N';
	END IF;
	 
	IF (:RecurringFlag = '' or LENGTH(:RecurringFlag) = 0) THEN
		in_RecurringFlag := 'N';
	END IF;
	
	SELECT "EnableBOE", "EnbSgmnAct", "LawsSet" INTO v_BoeEnable,v_SgmActEnable,v_LocalSet FROM CINF;

	IF (:v_LocalSet = 'CN' OR :v_LocalSet = 'JP') THEN
		v_ApaCheck := 'Y';
	ELSE
		v_ApaCheck := 'N';
	END IF;
	
	--- Filter the inactive BP
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpOCRD("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarchar(1));
	IF (:v_FilterInBPFlag = 'Y') THEN
		INSERT INTO #CASHFLOW_TmpOCRD SELECT "CardCode", "CardName", "CardType" FROM OCRD;
	ELSE
		INSERT INTO #CASHFLOW_TmpOCRD 
		SELECT "CardCode", "CardName", "CardType" FROM OCRD 
		WHERE ("CardCode" IS NULL OR ("validFor" = 'Y' OR ("frozenFor" = 'Y' AND ("frozenFrom" IS NOT NULL OR "frozenTo" IS NOT NULL)) 
			OR ("validFor" = 'N' AND "frozenFor" = 'N' )));
	END IF;
	
	--- Period
	v_Today := CURRENT_DATE;
	IF (:in_IntervalVal = 'D') THEN
		v_DateFrom := ADD_DAYS(:v_Today, :IntervalSeq - 1);
	 	v_DateTo := :v_DateFrom;
	ELSEIF (:in_IntervalVal = 'W') THEN
		v_DateFrom := ADD_DAYS (:v_Today, 7 * (:IntervalSeq - 1));
		v_DateTo := ADD_DAYS (:v_Today, 7 * :IntervalSeq - 1);
	ELSE
		v_DateFrom := ADD_MONTHS (:v_Today, :IntervalSeq - 1);
		v_DateTo := ADD_DAYS (ADD_MONTHS (:v_Today, :IntervalSeq), -1);
	END IF;
	
	--- Main Currency (think about different currency)
	SELECT "MainCurncy", "DirectRate" INTO v_MainCurrency, v_DirectRateFlag FROM OADM;
	
	----Get/Set Account List
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpAcct ("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarchar(1));
	CALL TmSp_DAB004_AccountList_QRYSTR (0, v_QryString);
	v_QryString := 'Insert INTO #CASHFLOW_TmpAcct (' || :v_QryString || ')';
	-- SELECT :v_QryString FROM DUMMY;
	EXEC (:v_QryString);
	
	 ----Get Customer/Vendor deduct account
	v_NegativeThreshold := (-1) * :Threshold;
	v_CustomerDeduct := '';
	v_VendorDeduct := '';
	SELECT COUNT(*) INTO v_TempInt FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'M' AND "CardCode" IS NOT NULL;
	IF (:v_TempInt > 0) THEN
		SELECT "CardCode" INTO v_CustomerDeduct FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'M' AND "CardCode" IS NOT NULL;
	END IF;
	SELECT COUNT(*) INTO v_TempInt FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'U' AND "CardCode" IS NOT NULL;
	IF (:v_TempInt > 0) THEN
		SELECT "CardCode" INTO v_VendorDeduct FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'U' AND "CardCode" IS NOT NULL;
	END IF;

	----Create temp table
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpDetail ("CardCode" nvarChar(15), "CardName" nvarChar(200), "BaseRef" nvarChar(11), 
		"BaseType" nvarChar(20), "DueDate" DateTime, "Direction" nvarchar(1), "Amount" DECIMAL(21,6), "PeyMethod" nvarChar(15), "CreatedBy" nvarChar(20));
	
	 ----I represent incoming, O represent outgoing
	 ----Cash,Check,Credit Card
	 v_QryString := ' SELECT NULL, '''', IFNULL(T0."BaseRef", ''''), T0."TransType", T0."DueDate", (CASE WHEN T0."BalDueDeb" < 0 OR T0."BalDueCred" > 0 THEN ''O'' ELSE ''I'' END), ABS(T0."BalDueDeb" - T0."BalDueCred"), IFNULL(T1."PeyMethod", ''''), T0."CreatedBy" FROM JDT1 T0 		LEFT OUTER JOIN "B1_JournalTransSourceView" T1 ON T1."ObjType" = T0."TransType" AND T1."DocEntry" = T0."CreatedBy" AND (T1."TransType" = ''I'' AND T1."InstlmntID" = T0."SourceLine")  		WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND 		(T0."BalDueDeb" > ' || :Threshold || ' OR T0."BalDueCred" > ' || :Threshold || ' OR T0."BalDueDeb" < ' || :v_NegativeThreshold || ' OR T0."BalDueCred" < ' || :v_NegativeThreshold || ') AND 		(T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0 ) AND  T0."Account" = T0."ShortName" AND		T0."ShortName" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" NOT IN (''E'', ''V'',''M'', ''U'')) AND 		(T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'') OR 		(T0."TransType" = ''24'' AND T0."ShortName" <> ''' || :v_CustomerDeduct || ''') OR		(T0."TransType" = ''46'' AND T0."ShortName" <> ''' || :v_VendorDeduct || ''') 		)		UNION ALL ';
 	
	----Customer,Vendor 
	v_QryString := :v_QryString || '		SELECT T1."CardCode", T1."CardName", IFNULL(T0."BaseRef", ''''), T0."TransType", T0."DueDate"			, (CASE WHEN T0."BalDueDeb" < 0 OR T0."BalDueCred" > 0 THEN ''O'' ELSE ''I'' END)			, ABS(T0."BalDueDeb" - T0."BalDueCred"), IFNULL(T2."PeyMethod", ''''), T0."CreatedBy"  FROM JDT1 T0 		INNER JOIN #CASHFLOW_TmpOCRD T1 ON  T1."CardCode" = T0."ShortName"  		LEFT OUTER JOIN "B1_JournalTransSourceView" T2 ON T2."ObjType" = T0."TransType" 			AND T2."DocEntry" = T0."CreatedBy" AND (T2."TransType" = ''I'' AND T2."InstlmntID" = T0."SourceLine")  		WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''') AND 			(T0."BalDueDeb" > ' || :Threshold || ' OR T0."BalDueCred" > ' || :Threshold || ' 			OR T0."BalDueDeb" < ' || :v_NegativeThreshold || ' OR T0."BalDueCred" < ' || :v_NegativeThreshold || ') AND 			(T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0) AND  T0."Account" <> T0."ShortName" AND  			T1."CardType" IN (''C'', ''S'')  AND  T0."Account" NOT IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND			T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'',''24'',''46'')			';
	
	----Boe
	IF (:v_BoeEnable = 'Y') THEN
		v_QryString := :v_QryString || '			UNION ALL 			SELECT T1."CardCode", T1."CardName", IFNULL(T0."BaseRef", ''''), T0."TransType", T0."DueDate"			, (CASE WHEN T0."BalDueDeb" < 0 OR T0."BalDueCred" > 0 THEN ''O'' ELSE ''I'' END)			, ABS(T0."BalDueDeb" - T0."BalDueCred"), IFNULL(T2."PeyMethod", ''''), T0."CreatedBy" 			FROM JDT1 T0 			INNER JOIN #CASHFLOW_TmpOCRD T1  ON  T1."CardCode" = T0."ShortName"    			LEFT OUTER JOIN "B1_JournalTransSourceView" T2 ON T2."ObjType" = T0."TransType" AND T2."DocEntry" = T0."CreatedBy" AND (T2."TransType" = ''I'' AND T2."InstlmntID" = T0."SourceLine")  			WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''') AND 			(T0."BalDueDeb" > ' || :Threshold || ' OR T0."BalDueCred" > ' || :Threshold || ' 			OR T0."BalDueDeb" < ' || :v_NegativeThreshold || ' OR T0."BalDueCred" < ' || :v_NegativeThreshold || ') AND 			(T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0) AND  T0."Account" <> T0."ShortName" AND  			T0."Account" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') ';
	END IF;
	
 	----Voucher cash,check,credit card
	IF (:in_VoucherFlag = 'Y') THEN
		v_QryString := :v_QryString || '			UNION ALL			SELECT NULL, '''', TO_NVARCHAR(T0."BatchNum"), ''28'', T0."DueDate", (CASE WHEN T0."Debit" < 0 OR T0."Credit" > 0 THEN ''O'' ELSE ''I'' END), ABS(T0."Debit" - T0."Credit"), '''', T0."CreatedBy" FROM  BTF1 T0, OBTF T1  			WHERE T0."BatchNum" = T1."BatchNum"  AND T0."TransId" = T1."TransId"  AND T0."Account" = T0."ShortName" AND			T1."BtfStatus" <> ''C''  AND (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND 			(T0."Debit" > ' || :Threshold || ' OR T0."Credit" > ' || :Threshold || ' OR T0."Debit" < ' || :v_NegativeThreshold || ' OR T0."Credit" < ' || :v_NegativeThreshold || ') AND 			T0."ShortName" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" IN (''A'', ''C'', ''V'',''D''))			UNION ALL ';
				
 		----Voucher customer,vendor		
		v_QryString := :v_QryString || '			SELECT T2."CardCode", T2."CardName", TO_NVARCHAR(T0."BatchNum"), ''28'', T0."DueDate"			, (CASE WHEN T0."Debit" < 0 OR T0."Credit" > 0 THEN ''O'' ELSE ''I'' END)			, ABS(T0."Debit" - T0."Credit"), '''', T0."CreatedBy" FROM  BTF1 T0  			INNER  JOIN OBTF T1  ON  T0."BatchNum" = T1."BatchNum"  AND  T0."TransId" = T1."TransId"   			INNER  JOIN #CASHFLOW_TmpOCRD T2  ON  T2."CardCode" = T0."ShortName"   			WHERE T1."BtfStatus" <> ''C''  AND (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND			(T0."Debit" > ' || :Threshold || ' OR T0."Credit" > ' || :Threshold || ' OR T0."Debit" < ' || :v_NegativeThreshold || ' 			OR T0."Credit" < ' || :v_NegativeThreshold || ') AND 			T0."Account" <> T0."ShortName"  AND  T2."CardType" IN (''C '', ''S'') ';
	END IF;
	 
	--SELECT :v_QryString FROM DUMMY;
	EXEC ('INSERT INTO #CASHFLOW_TmpDetail (' || :v_QryString || ')');
	
	----Recurring transaction
	IF (:in_RecurringFlag = 'Y') THEN
		--- Recurring transaction loop 1  
		OPEN c_RecurTransQry (:v_DateTo, :Threshold, :v_NegativeThreshold);
		FETCH c_RecurTransQry INTO v_FrequencyC,v_SubFrequncyC,v_LimitFlagC,v_LimitDateC,v_CurrencyC,v_RcurCodeC,v_RefC,v_CtrAcctC,v_AcctCodeC,v_InstanceC,v_NextDueC,v_DebitC,v_CreditC;
		WHILE NOT c_RecurTransQry::NOTFOUND DO
			v_Frequency := :v_FrequencyC;
			v_SubFrequncy := :v_SubFrequncyC;
			v_LimitFlag := :v_LimitFlagC;
			v_LimitDate := :v_LimitDateC;
			v_Currency := :v_CurrencyC;
			v_RcurCode := :v_RcurCodeC;
			v_Ref := :v_RefC;
			v_CtrAcct := :v_CtrAcctC;
			v_AcctCode := :v_AcctCodeC;
			v_Instance := :v_InstanceC;
			v_NextDue := :v_NextDueC;
			v_Debit := :v_DebitC;
			v_Credit := :v_CreditC;
			--- Recurring transaction  loop 2
			WHILE (:v_NextDue <= :v_DateTo AND (:v_LimitFlag <> 'Y' OR :v_NextDue <= :v_LimitDate)) DO
				v_Rate := 1;
				IF (:v_Currency <> :v_MainCurrency ) THEN 
					--- Logic for dashboard: no exchange rate that day then use exchange rate today
					SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_NextDue;
					IF (:v_TempInt = 0) THEN
						SELECT COUNT(*) INTO v_TempInt FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_Today;
						IF (:v_TempInt > 0) THEN
							SELECT "Rate" INTO v_Rate FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_Today;
							IF (:v_DirectRateFlag <> 'Y') THEN
								v_Rate := 1.0/:v_Rate;
							END IF;
						END IF;
					ELSE
						SELECT "Rate" INTO v_Rate FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_NextDue;
						IF (:v_DirectRateFlag <> 'Y') THEN
							v_Rate := 1.0/:v_Rate;
						END IF;
					END IF;
				END IF;
				IF (:v_NextDue >= :v_DateFrom AND (:v_Frequency <>'O' OR :v_Instance <> 0)) THEN					
					IF (:v_AcctCode <> :v_CtrAcct) THEN 
						INSERT INTO #CASHFLOW_TmpDetail 
						SELECT T0."CardCode", T0."CardName"
							, (CASE WHEN :v_Ref IS NULL THEN :v_RcurCode ELSE :v_Ref END), '34'
							, :v_NextDue, (CASE WHEN (:v_Debit < 0 OR :v_Credit > 0) THEN 'O' ELSE 'I' END)
							, ABS((:v_Debit - :v_Credit)*:v_Rate), '', :v_RcurCode 
						FROM #CASHFLOW_TmpOCRD T0
						WHERE T0."CardCode" = :v_AcctCode;
					ELSE			
						IF (:v_BoeEnable = 'Y') THEN						
							INSERT INTO #CASHFLOW_TmpDetail 
							SELECT NULL, '',(CASE WHEN :v_Ref IS NULL THEN :v_RcurCode ELSE :v_Ref END), '34', :v_NextDue
								, (CASE WHEN :v_Debit < 0 OR :v_Credit > 0 THEN 'O' ELSE 'I' END)
								, ABS((:v_Debit-:v_Credit)*:v_Rate), '', :v_RcurCode
							FROM #CASHFLOW_TmpAcct T0 
							WHERE :v_CtrAcct = T0."CardCode" AND T0."CardType" <> 'V';
						ELSE
							INSERT INTO #CASHFLOW_TmpDetail 
							SELECT NULL, '',(CASE WHEN :v_Ref IS NULL THEN :v_RcurCode ELSE :v_Ref END), '34', :v_NextDue
								, (CASE WHEN :v_Debit < 0 OR :v_Credit > 0 THEN 'O' ELSE 'I' END)
								, ABS((:v_Debit-:v_Credit)*:v_Rate), '', :v_RcurCode
							FROM #CASHFLOW_TmpAcct T0 
							WHERE :v_CtrAcct = T0."CardCode" AND T0."CardType" <> 'V' AND T0."CardType" <> 'E';
						END IF;
					END IF;
				END IF;
				IF (:v_Frequency = 'D') THEN
					v_NextDue := ADD_DAYS(:v_NextDue, :v_SubFrequncy);
				ELSEIF (:v_Frequency = 'W') THEN
					v_NextDue := ADD_DAYS(:v_NextDue,7);
				ELSEIF (:v_Frequency = 'A') THEN
					v_NextDue := ADD_YEARS(:v_NextDue,1);
				ELSEIF (:v_Frequency = 'M') THEN
					v_NextDue := ADD_MONTHS(:v_NextDue,1);
				ELSEIF (:v_Frequency = 'S') THEN
					v_NextDue := ADD_MONTHS(:v_NextDue,6);
				ELSEIF (:v_Frequency = 'Q') THEN
					v_NextDue := ADD_MONTHS(:v_NextDue,3);
				ELSE
					BREAK;
				END IF;
			END WHILE;
			FETCH c_RecurTransQry INTO v_FrequencyC,v_SubFrequncyC,v_LimitFlagC,v_LimitDateC,v_CurrencyC,v_RcurCodeC,v_RefC,v_CtrAcctC,v_AcctCodeC,v_InstanceC,v_NextDueC,v_DebitC,v_CreditC;
		END WHILE;	
		CLOSE c_RecurTransQry;
	END IF;

	 --- Addtional project transactions
	 IF (:v_BoeEnable = 'Y') THEN
	 	OPEN c_ProjectQry1 (:v_DateFrom, :v_DateTo, :Threshold, :v_NegativeThreshold);
		FETCH c_ProjectQry1 INTO v_NextDueC,v_DebitC,v_DebitCurrencyC,v_CreditC,v_CreditCurrencyC;
		WHILE (NOT c_ProjectQry1::NOTFOUND) DO
			v_NextDue := v_NextDueC;
			v_Debit := v_DebitC;
			v_DebitCurrency := v_DebitCurrencyC;
			v_Credit := v_CreditC;
			v_CreditCurrency := v_CreditCurrencyC;
			v_Rate := 1.0;
			IF (:v_DebitCurrency <> :v_MainCurrency  OR :v_CreditCurrency <> :v_MainCurrency) THEN
				--- Logic for dashboard: no exchange rate that day then use exchange rate today
				SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
				IF (:v_TempInt = 0) THEN
					SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_Today;
					IF (:v_TempInt > 0) THEN
						SELECT "Rate" INTO v_Rate FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_Today;
						IF (:v_DirectRateFlag <> 'Y') THEN
							v_Rate := 1.0 / :v_Rate;
						END IF;
					END IF;
				ELSE
					SELECT "Rate" INTO v_Rate FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
					IF (:v_DirectRateFlag <> 'Y') THEN
						v_Rate := 1.0 / :v_Rate;
					END IF;
				END IF;
			END IF;
			INSERT INTO #CASHFLOW_TmpDetail VALUES(NULL, '', NULL, '-8', :v_NextDue, (CASE WHEN :v_Debit < 0 OR :v_Debit > 0 THEN 'I' ELSE 'O' END), ABS((:v_Debit - :v_Credit)*:v_Rate), '', NULL);
			FETCH c_ProjectQry1 INTO v_NextDueC,v_DebitC,v_DebitCurrencyC,v_CreditC,v_CreditCurrencyC;
		END WHILE;
	 	CLOSE c_ProjectQry1;
	 ELSE
		OPEN c_ProjectQry2 (:v_DateFrom, :v_DateTo, :Threshold, :v_NegativeThreshold);
		FETCH c_ProjectQry2 INTO v_NextDueC,v_DebitC,v_DebitCurrencyC,v_CreditC,v_CreditCurrencyC;
		WHILE (NOT c_ProjectQry2::NOTFOUND) DO
			v_NextDue := v_NextDueC;
			v_Debit := v_DebitC;
			v_DebitCurrency := v_DebitCurrencyC;
			v_Credit := v_CreditC;
			v_CreditCurrency := v_CreditCurrencyC;
			v_Rate := 1.0;
			IF (:v_DebitCurrency <> :v_MainCurrency  OR :v_CreditCurrency <> :v_MainCurrency) THEN
				--- Logic for dashboard: no exchange rate that day then use exchange rate today
				SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
				IF (:v_TempInt = 0) THEN
					SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_Today;
					IF (:v_TempInt > 0) THEN
						SELECT "Rate" INTO v_Rate FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_Today;
						IF (:v_DirectRateFlag <> 'Y') THEN
							v_Rate := 1.0 / :v_Rate;
						END IF;
					END IF;
				ELSE
					SELECT "Rate" INTO v_Rate FROM ORTT WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
					IF (:v_DirectRateFlag <> 'Y') THEN
						v_Rate := 1.0 / :v_Rate;
					END IF;
				END IF;
			END IF;
			INSERT INTO #CASHFLOW_TmpDetail VALUES(NULL, '', NULL, '-8', :v_NextDue, (CASE WHEN :v_Debit < 0 OR :v_Credit > 0 THEN 'I' ELSE 'O' END), ABS((:v_Debit - :v_Credit)*:v_Rate), '', NULL);
			FETCH c_ProjectQry2 INTO v_NextDueC,v_DebitC,v_DebitCurrencyC,v_CreditC,v_CreditCurrencyC;
		END WHILE;
	 	CLOSE c_ProjectQry2;
	 END IF;
	
	----Final Results
	v_IncomingCount := 0;
	v_OutgoingCount := 0;

	SELECT COUNT(*) INTO v_IncomingCount FROM #CASHFLOW_TmpDetail WHERE "Direction" = 'I'; --HAVING COUNT(*) > 0;
	SELECT COUNT(*) INTO v_OutgoingCount FROM #CASHFLOW_TmpDetail WHERE "Direction" = 'O'; --HAVING COUNT(*) > 0;

	v_QryString := 'SELECT CAST(' || :v_IncomingCount || ' AS nvarChar(15)) AS "CardCode", CAST(' || :v_OutgoingCount || ' AS nvarChar(15)) AS "CardName", NULL As "BaseRef", NULL As "BaseType", NULL As "DueDate", NULL As "Direction", NULL AS "Amount", NULL As "PeyMethod", NULL AS "CreatedBy" FROM DUMMY';
	IF (:v_IncomingCount > 0 AND :v_IncomingCount > (:IncomingPage-1)*:PerPageVal) THEN
		v_QryString := :v_QryString || ' UNION ALL 			SELECT * FROM ( (SELECT TOP ' || (:IncomingPage*:PerPageVal) || ' * FROM #CASHFLOW_TmpDetail WHERE "Direction" = ''I'' 			ORDER BY "CardCode", "CardName", "BaseRef", "BaseType", "DueDate", "Direction", "Amount", "PeyMethod", "CreatedBy") ';
		IF (:IncomingPage > 1 AND (:IncomingPage-1)*:PerPageVal > 0) THEN
			v_QryString := :v_QryString || 'EXCEPT 				(SELECT TOP ' || ((:IncomingPage-1)*:PerPageVal) || ' * FROM #CASHFLOW_TmpDetail WHERE "Direction" = ''I'' 				ORDER BY "CardCode", "CardName", "BaseRef", "BaseType", "DueDate", "Direction", "Amount", "PeyMethod", "CreatedBy") ';
		END IF;
		v_QryString := :v_QryString || ') AS T1 ';
	END IF;
	IF (:v_OutgoingCount > 0 AND :v_OutgoingCount > (:OutgoingPage-1)*:PerPageVal) THEN
		v_QryString := :v_QryString || ' UNION ALL			SELECT * FROM ( (SELECT TOP ' || (:OutgoingPage*:PerPageVal) || ' * FROM #CASHFLOW_TmpDetail WHERE "Direction" = ''O'' 			ORDER BY "CardCode", "CardName", "BaseRef", "BaseType", "DueDate", "Direction", "Amount", "PeyMethod", "CreatedBy") ';
		IF (:OutgoingPage > 1 AND (:OutgoingPage-1)*:PerPageVal > 0) THEN
			v_QryString := :v_QryString || 'EXCEPT 				(SELECT TOP ' || ((:OutgoingPage-1)*:PerPageVal) || ' * FROM #CASHFLOW_TmpDetail WHERE "Direction" = ''O'' 				ORDER BY "CardCode", "CardName", "BaseRef", "BaseType", "DueDate", "Direction", "Amount", "PeyMethod", "CreatedBy") ';
		END IF;
		v_QryString := :v_QryString || ') AS T2 ';
	END IF;	

	EXECUTE IMMEDIATE (:v_QryString);
	
	-- Drop Temp tables
	--DROP TABLE #CASHFLOW_TmpOCRD;
	--DROP TABLE #CASHFLOW_TmpAcct;
	--DROP TABLE #CASHFLOW_TmpDetail;
	--DROP TABLE #CASHFLOW_TmpViewToShow;

END

-- B1 DEPENDS: AFTER:SP:TmSp_DAB004_AccountList_QRYSTR AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam
--DROP PROCEDURE TmSp_DAB004_CashFlowNamedDetails;
CREATE PROCEDURE TmSp_DAB004_CashFlowNamedDetails 
	(IN IntervalSeq INTEGER, 
	IN Direction nvarChar(1), 
	IN Page INTEGER, 
	IN FilterStr nvarChar(200), 
	IN PerPageVal INTEGER, 
	IN CardSlpFlag nvarChar(1), 
	IN IntervalVal nvarChar(1), 
	IN VoucherFlag nvarChar(1), 
	IN RecurringFlag nvarChar(1)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 

	/********* Begin Procedure Script ************/
	v_Today DateTime;
	v_DateFrom DateTime;
	v_DateTo	  DateTime;
	v_BoeEnable    nvarChar(1);
	v_SgmActEnable nvarChar(1);
	v_LocalSet     nvarChar(3);
	v_ApaCheck     nvarChar(1);
	v_QryString    nvarChar(8000);
	v_FmtString    nvarChar(100);
	v_Frequency nvarChar(1);
	v_SubFrequncy INTEGER;
	v_LimitFlag nvarChar(1);
	v_LimitDate DateTime;
	v_Currency nVarchar(3);
	v_AcctCode nVarchar(15);
	v_NextDue DateTime;
	v_Debit DECIMAL(21,6);
	v_Credit DECIMAL(21,6);
	v_MainCurrency nVarchar(3);
	v_DirectRateFlag nvarChar(1);
	v_Rate DECIMAL(21,6);
	v_DebitCurrency nVarchar(3);
	v_CreditCurrency nVarchar(3);
	v_RcurCode nvarChar(8);
	v_Ref nvarChar(11);
	v_TotalCount INTEGER;
	v_TempInt INTEGER;
	v_NoDefinedSlpName nvarChar(100);
	v_Multiplier INTEGER;
	v_NoDefinedSLPFlag nvarChar(1);
	v_FilterInBPFlag nvarChar(1);
	
	v_FrequencyC nvarChar(1);
	v_SubFrequncyC INTEGER;
	v_LimitFlagC nvarChar(1);
	v_LimitDateC DateTime;
	v_CurrencyC nVarchar(3);
	v_RcurCodeC nvarChar(8);
	v_RefC nvarChar(11);
	v_NextDueC DateTime;
	v_DebitC DECIMAL(21,6);
	v_CreditC DECIMAL(21,6);
	
	in_IntervalVal  nvarChar(1);
	in_VoucherFlag nvarChar(1);
	in_RecurringFlag nvarChar(1);
	--- CURSOR DEFINE
	CURSOR c_RecurTransQry (DateTo DATE, Multiplier INTEGER) FOR
	SELECT T0."Frequency", T0."Remind", T0."LimitRtrns", T0."LimitDate", T1."Currency", T0."RcurCode"
		, T0."Ref1", T0."NextDeu", T1."Debit", T1."Credit"  
	FROM ORCR T0 
	INNER JOIN RCR1 T1 ON T1."RcurCode" = T0."RcurCode" AND T0."Instance" = T1."Instance"
	WHERE T0."Frequency" <> 'T'  AND T0."NextDeu" <= :DateTo AND 
		(T0."LimitRtrns" <> 'Y' OR T0."NextDeu" <= T0."LimitDate") AND
		(T0."Frequency" <> 'O' OR T1."Instance" <> 0) AND T1."CtrlAcct" <> T1."AcctCode" AND
		((T1."Debit")*:Multiplier < 0 OR (T1."Credit")*:Multiplier > 0);
		
BEGIN
	--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:Direction);    
    call _TmSp_ValidateSpParam(:FilterStr);    
	call _TmSp_ValidateSpParam(:CardSlpFlag);   
	call _TmSp_ValidateSpParam(:IntervalVal);    
    call _TmSp_ValidateSpParam(:VoucherFlag);    
	call _TmSp_ValidateSpParam(:RecurringFlag);   
	
	-- DROP TEMP TABLE
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPOCRD' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpOCRD;
	END IF;
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPACCT' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpAcct;
	END IF;
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPNAMEDDETAIL' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpNamedDetail;
	END IF;
	select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPVIEWTOSHOW' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
	IF :v_TempInt > 0 THEN
		DROP TABLE #CASHFLOW_TmpViewToShow;
	END IF;
	
	in_IntervalVal := :IntervalVal;
	in_VoucherFlag := :VoucherFlag;
	in_RecurringFlag := :RecurringFlag;
 
	IF (:IntervalVal = '' or LENGTH(:IntervalVal) = 0) THEN
		in_IntervalVal := 'D';
	END IF;
	 
	IF (:VoucherFlag = '' or LENGTH(:VoucherFlag) = 0) THEN
		in_VoucherFlag := 'N';
	END IF;
	 
	IF (:RecurringFlag = '' or LENGTH(:RecurringFlag) = 0) THEN
		in_RecurringFlag := 'N';
	END IF;
	
	SELECT "EnableBOE", "EnbSgmnAct", "LawsSet" INTO v_BoeEnable,v_SgmActEnable,v_LocalSet FROM CINF;

	IF (:v_LocalSet = 'CN' OR :v_LocalSet = 'JP') THEN
		v_ApaCheck := 'Y';
	ELSE
		v_ApaCheck := 'N';
	END IF;
	
	--- Filter the inactive BP
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpOCRD("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarChar(1));
	
	IF (:v_FilterInBPFlag = 'Y') THEN
		INSERT INTO #CASHFLOW_TmpOCRD SELECT "CardCode", "CardName", "CardType" FROM OCRD;
	ELSE
		INSERT INTO #CASHFLOW_TmpOCRD 
		SELECT "CardCode", "CardName", "CardType" FROM OCRD 
		WHERE ("CardCode" IS NULL OR ("validFor" = 'Y' OR ("frozenFor" = 'Y' AND ("frozenFrom" IS NOT NULL OR "frozenTo" IS NOT NULL)) 
			OR ("validFor" = 'N' AND "frozenFor" = 'N' )));
	END IF;
	
	--- Period
	v_Today := CURRENT_DATE;
	IF (:in_IntervalVal = 'D') THEN
		v_DateFrom := ADD_DAYS(:v_Today, :IntervalSeq - 1);
	 	v_DateTo := :v_DateFrom;
	ELSEIF (:in_IntervalVal = 'W') THEN
		v_DateFrom := ADD_DAYS (:v_Today, 7 * (:IntervalSeq - 1));
		v_DateTo := ADD_DAYS (:v_Today, 7 * :IntervalSeq - 1);
	ELSE
		v_DateFrom := ADD_MONTHS (:v_Today, :IntervalSeq - 1);
		v_DateTo := ADD_DAYS (ADD_MONTHS (:v_Today, :IntervalSeq), -1);
	END IF;
	
	--- Initial Multiplier
	v_Multiplier := 1;
	IF (:Direction = 'I') THEN
		v_Multiplier := -1;
	END IF;
	
	--- No defined Sales Employee 
	v_NoDefinedSlpName := '';
	v_NoDefinedSLPFlag := 'N';
	SELECT COUNT(*) INTO v_TempInt FROM OSLP WHERE "SlpCode" = '-1';
	IF (:v_TempInt > 0) THEN
		SELECT "SlpName" INTO v_NoDefinedSlpName FROM OSLP WHERE "SlpCode" = '-1';	
	END IF;
	IF (LEFT(:FilterStr,2) = N'IN' AND LOCATE(:FilterStr, '-1') > 0) THEN
			v_NoDefinedSLPFlag := 'Y';
	END IF;
	
	--- Main Currency (think about different currency)
	SELECT "MainCurncy", "DirectRate" INTO v_MainCurrency, v_DirectRateFlag FROM OADM;
	
	----Get/Set Account List
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpAcct ("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarChar(1));

	CALL TmSp_DAB004_AccountList_QRYSTR (0, v_QryString);
	v_QryString := 'Insert INTO #CASHFLOW_TmpAcct (' || :v_QryString || ')';
	-- SELECT :v_QryString FROM DUMMY;
	EXEC (:v_QryString);
	
	----Create temp table
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpNamedDetail ("CardCode" nvarChar(15), "CardName" nvarChar(200), "BaseRef" nvarChar(11), 
		"BaseType" nvarChar(20), "DueDate" DateTime, "Amount" DECIMAL(21,6), "CreatedBy" nvarChar(11));
	
	----Customer,Vendor 
	IF (:CardSlpFlag = 'C') THEN
		v_QryString := 'SELECT T1."CardCode", T1."CardName", T0."BaseRef", T0."TransType", T0."DueDate", ABS(T0."BalDueDeb" - T0."BalDueCred"), T0."CreatedBy" FROM JDT1 T0 			INNER JOIN #CASHFLOW_TmpOCRD T1 ON  T1."CardCode" = T0."ShortName"  			WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''') AND 			((T0."BalDueDeb")*' || :v_Multiplier || ' < 0  			OR (T0."BalDueCred")*' || :v_Multiplier || ' > 0) AND T0."Account" <> T0."ShortName" AND  			T1."CardType" IN (''C'', ''S'')  AND  T0."Account" NOT IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND			T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'',''24'',''46'') AND T1."CardCode" ' || :FilterStr || ' ';
	ELSE
		v_QryString := 'SELECT CAST(T2."SlpCode" AS nvarChar(15)), T3."SlpName", T0."BaseRef", T0."TransType", T0."DueDate", ABS(T0."BalDueDeb" - T0."BalDueCred"), T0."CreatedBy" FROM JDT1 T0 			INNER JOIN #CASHFLOW_TmpOCRD T1 ON T1."CardCode" = T0."ShortName"			LEFT OUTER JOIN "B1_JournalTransSourceView" T2 ON T2."ObjType" = T0."TransType" AND T2."DocEntry" = T0."CreatedBy" AND (T2."TransType" = ''I'' AND T2."InstlmntID" = T0."SourceLine")  			LEFT OUTER JOIN OSLP T3 ON T2."SlpCode" = T3."SlpCode" 			WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''') AND 			 ((T0."BalDueDeb")*' || :v_Multiplier || ' < 0 OR (T0."BalDueCred")*' || :v_Multiplier || ' > 0) AND  T0."Account" <> T0."ShortName" AND  			 T1."CardType" IN (''C'', ''S'')  AND  T0."Account" NOT IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND			 T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'',''24'',''46'') AND T2."SlpCode" ' || :FilterStr || ' ';
	END IF;
	
	----Boe
	IF (:v_BoeEnable = 'Y') THEN
		IF (:CardSlpFlag = 'C') THEN
			v_QryString := :v_QryString || ' UNION ALL 				SELECT T1."CardCode", T1."CardName", T0."BaseRef", T0."TransType", T0."DueDate", ABS(T0."BalDueDeb" - T0."BalDueCred"), T0."CreatedBy" FROM JDT1 T0 				INNER JOIN #CASHFLOW_TmpOCRD T1  ON  T1."CardCode" = T0."ShortName"   				WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND  				  ((T0."BalDueDeb")*' || :v_Multiplier || ' < 0 OR (T0."BalDueCred")*' || :v_Multiplier || ' > 0) AND  T0."Account" <> T0."ShortName" AND				  T0."Account" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND T1."CardCode" ' || :FilterStr || ' ';
		ELSE
			v_QryString := :v_QryString || ' UNION ALL 				SELECT CAST(T2."SlpCode" AS nvarChar(15)), T3."SlpName", T0."BaseRef", T0."TransType", T0."DueDate", ABS(T0."BalDueDeb" - T0."BalDueCred") , T0."CreatedBy" FROM JDT1 T0 				INNER JOIN #CASHFLOW_TmpOCRD T1  ON  T1."CardCode" = T0."ShortName"   				LEFT OUTER JOIN "B1_JournalTransSourceView" T2 ON T2."ObjType" = T0."TransType" AND T2."DocEntry" = T0."CreatedBy" AND (T2."TransType" = ''I'' AND T2."InstlmntID" = T0."SourceLine")  				LEFT OUTER JOIN OSLP T3 ON T2."SlpCode" = T3."SlpCode" 				WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND  				  ((T0."BalDueDeb")*' || :v_Multiplier || ' < 0 OR (T0."BalDueCred")*' || :v_Multiplier || ' > 0) AND  T0."Account" <> T0."ShortName" AND				  T0."Account" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND T2."SlpCode" ' || :FilterStr || ' ';
		END IF;
	END IF;
	
	----Voucher customer,vendor
	IF (:in_VoucherFlag = 'Y') THEN
		IF (:CardSlpFlag = 'C') THEN
			v_QryString := :v_QryString || ' UNION ALL 				SELECT T2."CardCode", T2."CardName", T0."BatchNum", ''28'', T0."DueDate", ABS(T0."Debit" - T0."Credit"), IFNULL(T0."CreatedBy",T0."BatchNum")  FROM  BTF1 T0  				INNER  JOIN OBTF T1  ON  T0."BatchNum" = T1."BatchNum"  AND  T0."TransId" = T1."TransId"   				INNER  JOIN #CASHFLOW_TmpOCRD T2  ON  T2."CardCode" = T0."ShortName"   				WHERE T1."BtfStatus" <> ''C''  AND (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND 				  ((T0."Debit")*' || :v_Multiplier || ' < 0 OR (T0."Credit")*' || :v_Multiplier || ' > 0) AND				  T0."Account" <> T0."ShortName"  AND  T2."CardType" IN (''C'', ''S'') AND T2."CardCode" ' || :FilterStr || ' ';
		ELSE
			IF (:v_NoDefinedSLPFlag = 'Y') THEN
				v_QryString := :v_QryString || ' UNION ALL					SELECT ''-1'', ''' || :v_NoDefinedSlpName || ''', T0."BatchNum", ''28'', T0."DueDate", ABS(T0."Debit" - T0."Credit"),  IFNULL(T0."CreatedBy",T0."BatchNum")   FROM  BTF1 T0  					 INNER  JOIN OBTF T1  ON  T0."BatchNum" = T1."BatchNum"  AND  T0."TransId" = T1."TransId"   					 INNER  JOIN #CASHFLOW_TmpOCRD T2  ON  T2."CardCode" = T0."ShortName"   					 WHERE T1."BtfStatus" <> ''C''  AND (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND					   ((T0."Debit")*' || :v_Multiplier || ' < 0 OR (T0."Credit")*' || :v_Multiplier || ' > 0) AND					   T0."Account" <> T0."ShortName"  AND  T2."CardType" IN (''C '', ''S'') ';
			END IF;
		END IF;
	END IF;
	 
	--SELECT :v_QryString FROM DUMMY;
	EXEC ('INSERT INTO #CASHFLOW_TmpNamedDetail (' || :v_QryString || ')');
	
	----Recurring transaction
	IF (:in_RecurringFlag = 'Y') THEN
		--- Recurring transaction loop 1  
		OPEN c_RecurTransQry (:v_DateTo, :v_Multiplier);
		FETCH c_RecurTransQry INTO v_FrequencyC,v_SubFrequncyC,v_LimitFlagC,v_LimitDateC,v_CurrencyC,v_RcurCodeC,v_RefC,v_NextDueC,v_DebitC,v_CreditC;
		WHILE NOT c_RecurTransQry::NOTFOUND DO
			v_Frequency := :v_FrequencyC;
			v_SubFrequncy := :v_SubFrequncyC;
			v_LimitFlag := :v_LimitFlagC;
			v_LimitDate := :v_LimitDateC;
			v_Currency := :v_CurrencyC;
			v_RcurCode := :v_RcurCodeC;
			v_Ref := :v_RefC;
			v_NextDue := :v_NextDueC;
			v_Debit := :v_DebitC;
			v_Credit := :v_CreditC;
			--- Recurring transaction  loop 2
			WHILE (:v_NextDue <= :v_DateTo AND (:v_LimitFlag <> 'Y' OR :v_NextDue <= :v_LimitDate)) DO
				v_Rate := 1;
				IF (:v_Currency <> :v_MainCurrency ) THEN 
					--- Logic for dashboard: no exchange rate that day then use exchange rate today
					SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_NextDue;
					IF (:v_TempInt = 0) THEN
						SELECT COUNT(0) INTO v_TempInt FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_Today;
						IF (:v_TempInt > 0) THEN
							SELECT "Rate" INTO v_Rate FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_Today;
							IF (:v_DirectRateFlag <> 'Y') THEN
								v_Rate := 1.0/:v_Rate;
							END IF;
						END IF;
					ELSE
						SELECT "Rate" INTO v_Rate FROM ORTT WHERE "Currency" = :v_Currency AND "RateDate" = :v_NextDue;
						IF (:v_DirectRateFlag <> 'Y') THEN
							v_Rate := 1.0/:v_Rate;
						END IF;
					END IF;
				END IF;
				IF (:v_NextDue >= :v_DateFrom) THEN					
					IF (:CardSlpFlag = 'C') THEN 
						v_QryString := 'INSERT INTO #CASHFLOW_TmpNamedDetail SELECT T0."CardCode", T0."CardName", (CASE WHEN '
							|| '''' || :v_Ref || '''' || ' IS NULL THEN ' || '''' || :v_RcurCode || '''' || ' ELSE NULL END), ''34'', '
							|| '''' || :v_NextDue || '''' || ', ABS((' || :v_Debit || '- ' || :v_Credit || ')*' || :v_Rate
							|| '), T0."CardCode" FROM #CASHFLOW_TmpOCRD T0 WHERE T0."CardCode" = ''' || :v_AcctCode || ''' AND T0."CardCode" ' || :FilterStr || ' ';
						IF (:v_QryString IS NOT NULL) THEN
							EXEC (:v_QryString);
						END IF;
					ELSE			
						IF (:v_NoDefinedSLPFlag = 'Y') THEN						
		     					INSERT INTO #CASHFLOW_TmpNamedDetail 
		     					SELECT '-1', :v_NoDefinedSlpName,(CASE WHEN :v_Ref IS NULL THEN :v_RcurCode ELSE NULL END), '34', :v_NextDue, ABS((:v_Debit-:v_Credit)*:v_Rate) , '-1'
		     					FROM #CASHFLOW_TmpOCRD T0 
		     					WHERE T0."CardCode" = :v_AcctCode;
						END IF;
					END IF;
				END IF;
				IF (:v_Frequency = 'D') THEN
					v_NextDue := ADD_DAYS(:v_NextDue, :v_SubFrequncy);
				ELSEIF (:v_Frequency = 'W') THEN
					v_NextDue := ADD_DAYS(:v_NextDue,7);
				ELSEIF (:v_Frequency = 'A') THEN
					v_NextDue := ADD_YEARS(:v_NextDue,1);
				ELSEIF (:v_Frequency = 'M') THEN
					v_NextDue := ADD_MONTHS(:v_NextDue,1);
				ELSEIF (:v_Frequency = 'S') THEN
					v_NextDue := ADD_MONTHS(:v_NextDue,6);
				ELSEIF (:v_Frequency = 'Q') THEN
					v_NextDue := ADD_MONTHS(:v_NextDue,3);
				ELSE
					BREAK;
				END IF;		
			END WHILE;
			FETCH c_RecurTransQry INTO v_FrequencyC,v_SubFrequncyC,v_LimitFlagC,v_LimitDateC,v_CurrencyC,v_RcurCodeC,v_RefC,v_NextDueC,v_DebitC,v_CreditC;
		END WHILE;	
		CLOSE c_RecurTransQry;
	END IF;
	
	----Final Results
	v_TotalCount := 0;
	
	SELECT COUNT(1) INTO v_TotalCount FROM #CASHFLOW_TmpNamedDetail;
	----First Line is special line including total records& result type
	v_QryString := 'SELECT ''D'', NULL, CAST(' || :v_TotalCount || ' AS nvarChar(15)), NULL, NULL, NULL, NULL FROM DUMMY';
	IF (:v_TotalCount > 0) AND (:v_TotalCount > (:Page-1)*:PerPageVal) AND (:Page*:PerPageVal) >= 0 THEN
		v_QryString := :v_QryString || ' UNION ALL 			SELECT * FROM ( (SELECT TOP ' || (:Page*:PerPageVal)  || '* FROM #CASHFLOW_TmpNamedDetail 			ORDER BY "CardCode", "CardName", "BaseRef", "BaseType", "DueDate", "Amount") ';
		IF (:Page > 1 AND (:Page-1)*:PerPageVal > 0) THEN
			 v_QryString := :v_QryString || ' EXCEPT 				(SELECT TOP ' || ((:Page-1)*:PerPageVal)  || '* FROM #CASHFLOW_TmpNamedDetail 				ORDER BY "CardCode", "CardName", "BaseRef", "BaseType", "DueDate", "Amount") ';
		END IF;
		v_QryString := :v_QryString || ') AS T1 ';
	END IF;
	
	---- SELECT :v_QryString FROM DUMMY;
	CREATE LOCAL TEMPORARY COLUMN TABLE #CASHFLOW_TmpViewToShow ("CardCode" nvarChar(15), "CardName" nvarChar(200), "BaseRef" nvarChar(11), 
		"BaseType" nvarChar(20), "DueDate" DateTime, "Amount" DECIMAL(21,6), "CreatedBy" nvarChar(11));
	v_QryString := 'INSERT INTO #CASHFLOW_TmpViewToShow (' || :v_QryString || ')';
	EXEC (:v_QryString);
	SELECT * FROM #CASHFLOW_TmpViewToShow;
	
	-- Drop Temp tables
	--DROP TABLE #CASHFLOW_TmpOCRD;
	--DROP TABLE #CASHFLOW_TmpAcct;
	--DROP TABLE #CASHFLOW_TmpNamedDetail;
	--DROP TABLE #CASHFLOW_TmpViewToShow;

END

-- B1 DEPENDS: AFTER:SP:TmSp_DAB004_AccountList_QRYSTR AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

Create procedure TmSp_DAB004_CashFlowOverView (IN IntervalCnt INTEGER, IN IntervalVal nvarChar(1)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
 /********* Begin Procedure Script ************/ 
 v_BoeEnable    nvarChar(1);
 v_SgmActEnable nvarChar(1);
 v_LocalSet     nvarChar(3);
 v_ApaCheck     nvarChar(1);
 v_QryString    nvarChar(8000);
 v_FmtString    nvarChar(100);
 v_DateFrom     Date;
 v_DateTo       Date;
 v_DateIter     Date;
 v_Iter         INTEGER;
 v_Frequency 	nvarChar(1);
 v_SubFrequncy 	INTEGER;
 v_LimitFlag 	nvarChar(1);
 v_LimitDate	Date;
 v_Currency 	nVarchar(3);
 v_CtrAcct 		nVarchar(15);
 v_AcctCode 	nVarchar(15);
 v_NextDue 		Date;
 v_Debit 		DECIMAL(21,6);
 v_Credit 		DECIMAL(21,6);
 v_MainCurrency nVarchar(3);
 v_DirectRateFlag 	nvarChar(1);
 v_Rate 		DECIMAL(21,6);
 v_DebitCurrency 	nVarchar(3);
 v_CreditCurrency 	nVarchar(3);
 v_MainInstance 	INTEGER;
 v_SubInstance 	INTEGER;
 v_FirstEndDate Date;
 v_CustomerDeduct 	nVarchar(15);
 v_VendorDeduct 	nVarchar(15);
 v_ErrInt       INTEGER;
 v_TempInt      INTEGER;
 v_FilterInBPFlag 	nvarChar(1);
 
 v_FrequencyC 	nvarChar(1);
 v_SubFrequncyC INTEGER;
 v_LimitFlagC 	nvarChar(1);
 v_LimitDateC	Date;
 v_CurrencyC 	nVarchar(3);
 v_CtrAcctC 	nVarchar(15);
 v_AcctCodeC 	nVarchar(15);
 v_MainInstanceC 	INTEGER;
 v_SubInstanceC 	INTEGER;
 v_NextDueC 		Date;
 v_DebitC 		DECIMAL(21,6);
 v_CreditC 		DECIMAL(21,6);
 v_DebitCurrencyC 	nVarchar(3);
 v_CreditCurrencyC 	nVarchar(3);
 
 v_cDateTo		Date;
 v_IsBreakCur	INTEGER;
 v_curId		INTEGER;
 ----CURSOR DEFINE
 CURSOR c_RecurTransQry (v_cDateTo DATE) FOR
 SELECT T0."Frequency", T0."Remind", T0."LimitRtrns", T0."LimitDate", T1."Currency", T1."CtrlAcct", T1."AcctCode", T0."Instance" AS "InstanceT0", T1."Instance" AS "InstanceT1", T0."NextDeu", T1."Debit", T1."Credit"  FROM "ORCR" T0 
  INNER JOIN "RCR1" T1 ON T1."RcurCode" = T0."RcurCode" --AND T0."Instance" = T1."Instance"
  WHERE T0."Frequency" <> 'T'  AND T0."NextDeu" <= :v_cDateTo AND 
   (T0."LimitRtrns" <> 'Y' OR T0."NextDeu" <= T0."LimitDate");
   
 CURSOR c_ProjectQry1 (v_cDateTo DATE) FOR
 SELECT "DateID", "Debit", "DebCur", "Credit", "CredCur" FROM "OCFL" 
    WHERE ("SecLevel" >= 1 AND "SecLevel" <= 6) AND "DateID" <= :v_cDateTo;
	
 CURSOR c_ProjectQry2 (v_cDateTo DATE) FOR
 SELECT "DateID", "Debit", "DebCur", "Credit", "CredCur" FROM "OCFL" 
    WHERE ("SecLevel" >= 1 AND "SecLevel" < 6) AND "DateID" <= :v_cDateTo;
	
 BEGIN 
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:IntervalVal);    
	
 -- DROP TEMP TABLE
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPDATE' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpDate;
 END IF;
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPOCRD' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpOCRD;
 END IF;
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPACCT' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpAcct;
 END IF;
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPOVERVIEW' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpOverView;
 END IF;
 
 ----Get all dates
 v_DateFrom := CURRENT_DATE;
 v_DateIter := :v_DateFrom;
 v_Iter := 1;
 create local temporary COLUMN table #CASHFLOW_TmpDate("StartDate" Date, "EndDate" Date);
 WHILE :v_Iter <= :IntervalCnt DO
	IF (:IntervalVal = 'D') THEN
		exec ('INSERT INTO #CASHFLOW_TmpDate VALUES(''' || :v_DateIter || ''',''' || :v_DateIter || ''')');
		v_DateIter := ADD_DAYS (v_DateIter, 1);
	ELSEIF (:IntervalVal = 'W') THEN
		v_DateTo := ADD_DAYS(v_DateIter, 6);
		exec ('INSERT INTO #CASHFLOW_TmpDate VALUES(''' || :v_DateIter || ''',''' || :v_DateTo || ''')');
		v_DateIter := ADD_DAYS (v_DateIter, 7);
	ELSE
		v_DateTo := ADD_MONTHS(v_DateIter, 1);
		v_DateTo := ADD_DAYS (v_DateTo, -1);
		exec ('INSERT INTO #CASHFLOW_TmpDate VALUES(''' || :v_DateIter || ''',''' || :v_DateTo || ''')');
		v_DateIter := ADD_MONTHS(v_DateIter, 1);
	END IF;
	IF (:v_Iter = 1) THEN
		v_FirstEndDate := ADD_DAYS (v_DateIter, -1);
	END IF;
	v_Iter := :v_Iter + 1;
 END WHILE;
 
 v_DateTo := ADD_DAYS (v_DateIter, -1);
 
 SELECT "EnableBOE", "EnbSgmnAct", "LawsSet" INTO v_BoeEnable,v_SgmActEnable,v_LocalSet FROM "CINF";
 
 SELECT "DspFrznBP" INTO v_FilterInBPFlag FROM OADM;
 
 --- Filter the inactive BP
 create local temporary COLUMN table #CASHFLOW_TmpOCRD("CardCode" nvarChar(15), "CardType" nvarChar(1));

 IF (:v_FilterInBPFlag = 'Y') THEN
	INSERT INTO #CASHFLOW_TmpOCRD SELECT "CardCode", "CardType" FROM OCRD;
 ELSE
	INSERT INTO #CASHFLOW_TmpOCRD 
	SELECT "CardCode", "CardType" FROM OCRD 
	WHERE ("CardCode" IS NULL OR ("validFor" = 'Y' OR ("frozenFor" = 'Y' AND ("frozenFrom" IS NOT NULL OR "frozenTo" IS NOT NULL)) OR ("validFor" = 'N' AND "frozenFor" = 'N' )));
 END IF;
 
 IF (:v_LocalSet = 'CN' OR :v_LocalSet = 'JP') THEN
	v_ApaCheck := 'Y';
 ELSE
	v_ApaCheck := 'N';
 END IF;
 --- Main Currency (think about different currency)
 v_ErrInt := 0;
 SELECT "MainCurncy", "DirectRate" INTO v_MainCurrency, v_DirectRateFlag FROM OADM;
 
 ----Get/Set Account List
 create local temporary COLUMN table #CASHFLOW_TmpAcct ("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarChar(1));

 CALL TmSp_DAB004_AccountList_QRYSTR (0, v_QryString);
 v_QryString := 'Insert INTO #CASHFLOW_TmpAcct (' || :v_QryString || ')';
 -- SELECT :v_QryString FROM DUMMY;
 exec (:v_QryString);

 
 ----Get Customer/Vendor deduct account
 v_CustomerDeduct := '';
 v_VendorDeduct := '';
 SELECT COUNT(*) INTO v_ErrInt FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'M' AND "CardCode" IS NOT NULL;
 IF (:v_ErrInt > 0) THEN
	SELECT "CardCode" INTO v_CustomerDeduct FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'M' AND "CardCode" IS NOT NULL;
 END IF;
 SELECT COUNT(*) INTO v_ErrInt FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'U' AND "CardCode" IS NOT NULL;
 IF (:v_ErrInt > 0) THEN
	SELECT "CardCode" INTO v_VendorDeduct FROM #CASHFLOW_TmpAcct WHERE "CardType" = 'U' AND "CardCode" IS NOT NULL;
 END IF;
 
 
 ----Mention transtype value(the N represent normal, R represent recurring, P represent voucher)
 create local temporary COLUMN table #CASHFLOW_TmpOverView ("Indicator" Date, "Debit" DECIMAL(21,6), "Credit" DECIMAL(21,6), "OpenBalance" DECIMAL(21,6), "TransType" nvarChar(1));
 
 ----No open balance
 v_QryString := 'SELECT T5."Ind", SUM(T5."Debit"), SUM(T5."Credit"), 0, T5."Typ" FROM ( ';
 ----Cash,Check,Credit Card
 v_QryString := :v_QryString || ' SELECT T1."EndDate" AS "Ind", T0."BalDueDeb" AS "Debit", T0."BalDueCred" AS "Credit", ''N'' AS "Typ" FROM "JDT1" T0, #CASHFLOW_TmpDate T1    WHERE (T0."DueDate" BETWEEN T1."StartDate" AND T1."EndDate")  AND        (T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0 ) AND  T0."Account" = T0."ShortName" AND      T0."ShortName" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" NOT IN (''E'', ''V'',''M'', ''U'')) AND	  (T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'') OR 	   (T0."TransType" = ''24'' AND T0."ShortName" <> ''' || :v_CustomerDeduct || ''') OR	   (T0."TransType" = ''46'' AND T0."ShortName" <> ''' || :v_VendorDeduct || ''') 	   )   UNION ALL ';
 ----Customer,Vendor 
 v_QryString := :v_QryString || ' SELECT T2."EndDate" AS "Ind", T0."BalDueDeb" AS "Debit", T0."BalDueCred" AS "Credit", ''N'' AS "Typ" FROM "JDT1" T0, #CASHFLOW_TmpOCRD T1, #CASHFLOW_TmpDate T2  WHERE (T0."DueDate" BETWEEN T2."StartDate"  AND T2."EndDate") AND T1."CardCode" = T0."ShortName" AND      (T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0) AND  T0."Account" <> T0."ShortName" AND       T1."CardType" IN (''C'', ''S'')  AND  T0."Account" NOT IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND	 T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'',''24'',''46'') UNION ALL ';
 ----Boe
 IF (:v_BoeEnable = 'Y') THEN
 v_QryString := :v_QryString || '  SELECT T2."EndDate" AS "Ind", T0."BalDueDeb" AS "Debit", T0."BalDueCred" AS "Credit", ''N'' AS "Typ" FROM  "JDT1" T0, #CASHFLOW_TmpOCRD T1, #CASHFLOW_TmpDate T2   WHERE (T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate") AND  T1."CardCode" = T0."ShortName" AND      (T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0) AND  T0."Account" <> T0."ShortName" AND      T0."Account" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'')   UNION ALL ';
 END IF;
 ----Voucher cash,check,credit card
 v_QryString := :v_QryString || ' SELECT T2."EndDate" AS "Ind", T0."Debit" AS "Debit", T0."Credit" AS "Credit", ''P'' AS "Typ" FROM  "BTF1" T0, "OBTF" T1, #CASHFLOW_TmpDate T2    WHERE T0."BatchNum" = T1."BatchNum"  AND T0."TransId" = T1."TransId"  AND  T0."Account" = T0."ShortName" AND T1."BtfStatus" <> ''C'' AND       (T0."DueDate" BETWEEN T2."StartDate" AND T2."EndDate")  AND       T0."ShortName" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" IN (''A'', ''C'', ''V'',''D'')) UNION ALL ';
 ----Voucher customer,vendor
 v_QryString := :v_QryString || ' SELECT T3."EndDate" AS "Ind", T0."Debit" AS "Debit", T0."Credit" AS "Credit", ''P'' AS "Typ" FROM  "BTF1" T0, "OBTF" T1, #CASHFLOW_TmpOCRD T2, #CASHFLOW_TmpDate T3       WHERE T0."BatchNum" = T1."BatchNum"  AND T0."TransId" = T1."TransId" AND T1."BtfStatus" <> ''C''  AND      (T0."DueDate" BETWEEN  T3."StartDate"  AND T3."EndDate") AND T2."CardCode" = T0."ShortName" AND    T0."Account" <> T0."ShortName"  AND  T2."CardType" IN (''C'', ''S'')';
 v_QryString := :v_QryString || '  ) AS T5 GROUP BY "Ind", "Typ" ';
 
 ---- SELECT :v_QryString FROM DUMMY;
 exec ('INSERT INTO #CASHFLOW_TmpOverView (' || :v_QryString || ')');
 
 ----Open balance
 v_QryString := ' SELECT ''' || :v_FirstEndDate || ''',';
 v_QryString := :v_QryString || '  0, 0, SUM(T5."OpenBalance"), T5."Typ" FROM ( ';
 ----Cash,Check,Credit Card
 v_QryString := :v_QryString || '  SELECT SUM(T0."BalDueDeb" - T0."BalDueCred") AS "OpenBalance", ''N'' AS "Typ" FROM "JDT1" T0   WHERE T0."DueDate" < ''';
 v_QryString := :v_QryString || :v_DateFrom || '''';
 v_QryString := :v_QryString || ' AND T0."TransType" <> ''-3'' AND  T0."Account" = T0."ShortName" AND     T0."ShortName" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" NOT IN (''E'', ''V'', ''M'', ''U''))  UNION ALL ';
 ----Customer,Vendor 
 v_QryString := v_QryString || ' SELECT SUM(T0."BalDueDeb" - T0."BalDueCred") AS "OpenBalance", ''N'' AS "Typ" FROM "JDT1" T0  INNER JOIN #CASHFLOW_TmpOCRD T1 ON  T1."CardCode" = T0."ShortName"    WHERE T0."DueDate" < ''';
  v_QryString := :v_QryString || :v_DateFrom || '''';
  v_QryString := :v_QryString || '    AND T0."TransType" <> ''-3'' AND T0."Account" <> T0."ShortName" AND       T1."CardType" IN (''C'', ''S'')  AND  T0."Account" NOT IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'')  UNION ALL ';
 ----Boe
 IF (:v_BoeEnable = 'Y') THEN
  v_QryString := :v_QryString || '  SELECT SUM(T0."BalDueDeb" - T0."BalDueCred") AS "OpenBalance", ''N'' AS "Typ" FROM "JDT1" T0   INNER JOIN #CASHFLOW_TmpOCRD T1  ON  T1."CardCode" = T0."ShortName"     WHERE T0."DueDate" < ''';
   v_QryString := :v_QryString || :v_DateFrom || '''';
   v_QryString := :v_QryString || '     AND T0."TransType" <> ''-3''  AND  T0."Account" <> T0."ShortName" AND      T0."Account" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'')   UNION ALL ';
 END IF;
 ----Voucher cash,check,credit card
 v_QryString := :v_QryString || ' SELECT SUM(T0."Debit" - T0."Credit") AS "OpenBalance", ''P'' AS "Typ" FROM  "BTF1" T0, "OBTF" T1    WHERE T0."BatchNum" = T1."BatchNum"  AND T0."TransId" = T1."TransId" AND       T0."Account" = T0."ShortName" AND T1."BtfStatus" <> ''C'' AND T0."DueDate" < ''';
 v_QryString := :v_QryString || :v_DateFrom || '''';
 v_QryString := :v_QryString || '	  AND       T0."ShortName" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" IN (''A'', ''C'',''D'')) UNION ALL ';
 ----Voucher customer,vendor
 v_QryString := :v_QryString || ' SELECT SUM(T0."Debit" - T0."Credit") AS "OpenBalance", ''P'' AS "Typ" FROM  "BTF1" T0    INNER  JOIN "OBTF" T1  ON  T0."BatchNum" = T1."BatchNum"  AND  T0."TransId" = T1."TransId"     INNER  JOIN #CASHFLOW_TmpOCRD T2  ON  T2."CardCode" = T0."ShortName"    WHERE T1."BtfStatus" <> ''C''  AND  T0."DueDate" < ''';
  v_QryString := :v_QryString || :v_DateFrom || '''';
  v_QryString := :v_QryString || '    AND     T0."Account" <> T0."ShortName"  AND  T2."CardType" IN (''C'', ''S'')';
 v_QryString := :v_QryString || ' ) AS T5 GROUP BY "Typ" ';
 
 ---- SELECT :v_QryString FROM DUMMY;
 exec ('INSERT INTO #CASHFLOW_TmpOverView (' || :v_QryString || ')');
 
 ----Recurring transaction
 
 --- Recurring transaction loop 1
 v_IsBreakCur := 0;
 OPEN c_RecurTransQry (v_DateTo);
 FETCH c_RecurTransQry INTO v_FrequencyC,v_SubFrequncyC,v_LimitFlagC,v_LimitDateC,v_CurrencyC,v_CtrAcctC,v_AcctCodeC,v_MainInstanceC,v_SubInstanceC,v_NextDueC,v_DebitC,v_CreditC;
 WHILE NOT c_RecurTransQry::NOTFOUND DO
	v_Frequency := :v_FrequencyC;
	v_SubFrequncy := :v_SubFrequncyC;
	v_LimitFlag := :v_LimitFlagC;
	v_LimitDate := :v_LimitDateC;
	v_Currency := :v_CurrencyC;
	v_CtrAcct := :v_CtrAcctC;
	v_AcctCode := :v_AcctCodeC;
	v_MainInstance := :v_MainInstanceC;
	v_SubInstance := :v_SubInstanceC;
	v_NextDue := :v_NextDueC;
	v_Debit := :v_DebitC;
	v_Credit := :v_CreditC;
	--- Recurring transaction  loop 2
	WHILE (:v_NextDue <= :v_DateTo AND (:v_LimitFlag <> 'Y' OR :v_NextDue <= :v_LimitDate)) DO
		v_Rate := 1;
		IF (:v_Currency <> :v_MainCurrency ) THEN 
		--- Logic for dashboard: no exchange rate that day then use exchange rate today, return error even no exchange rate today
			SELECT COUNT(*) INTO v_TempInt FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_NextDue;
			IF (:v_TempInt = 0) THEN
				SELECT COUNT(*) INTO v_TempInt FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_DateFrom;
				IF (:v_TempInt = 0) THEN
					v_ErrInt := 2;
					v_IsBreakCur := 1;
					BREAK;
				ELSE
					v_ErrInt := 1;
					SELECT "Rate" INTO v_Rate FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_DateFrom;
					IF (:v_DirectRateFlag <> 'Y') THEN
						v_Rate := 1.0/:v_Rate;
					END IF;
				END IF;
			ELSE
				SELECT "Rate" INTO v_Rate FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_NextDue;
				IF (:v_DirectRateFlag <> 'Y') THEN
						v_Rate := 1.0/:v_Rate;
				END IF;
			END IF;
		END IF;
		----Not open balance
		IF (:v_NextDue >= :v_DateFrom AND :v_MainInstance = :v_SubInstance AND (:v_Frequency <>'O' OR :v_MainInstance <> 0)) THEN
			IF (:v_CtrAcct = :v_AcctCode) THEN
				IF (:v_BoeEnable = 'Y') THEN
					INSERT INTO #CASHFLOW_TmpOverView SELECT T0."EndDate", :v_Debit*:v_Rate, v_Credit*v_Rate, 0, 'R' FROM #CASHFLOW_TmpDate T0, #CASHFLOW_TmpAcct T1 WHERE (T0."StartDate" <= :v_NextDue AND T0."EndDate" >= :v_NextDue) AND T1."CardCode" = :v_CtrAcct AND T1."CardType" <> 'V';
				ELSE
					INSERT INTO #CASHFLOW_TmpOverView SELECT T0."EndDate", :v_Debit*:v_Rate, v_Credit*v_Rate, 0, 'R' FROM #CASHFLOW_TmpDate T0, #CASHFLOW_TmpAcct T1 WHERE (T0."StartDate" <= :v_NextDue AND T0."EndDate" >= :v_NextDue) AND T1."CardCode" = :v_CtrAcct AND T1."CardType" <> 'V' AND T1."CardType" <> 'E';
				END IF;
			ELSE
				INSERT INTO #CASHFLOW_TmpOverView SELECT T0."EndDate", :v_Debit*:v_Rate, v_Credit*v_Rate, 0, 'R' FROM #CASHFLOW_TmpDate T0, #CASHFLOW_TmpOCRD T1 WHERE (T0."StartDate" <= :v_NextDue AND T0."EndDate" >= :v_NextDue) AND T1."CardCode" = :v_AcctCode;
			END IF;
		END IF;
		----Open balance
		IF (:v_NextDue < :v_DateFrom AND :v_SubInstance = 0 AND :v_Debit <> :v_Credit) THEN
			IF (:v_CtrAcct = :v_AcctCode) THEN
				IF (:v_BoeEnable = 'Y') THEN
					INSERT INTO #CASHFLOW_TmpOverView SELECT :v_FirstEndDate, 0, 0,(:v_Debit - :v_Credit) * :v_Rate, 'R' FROM #CASHFLOW_TmpAcct T0 WHERE T0."CardCode" =:v_CtrAcct AND T0."CardType" <> 'V';
				ELSE
					INSERT INTO #CASHFLOW_TmpOverView SELECT :v_FirstEndDate, 0, 0,(:v_Debit - :v_Credit) * :v_Rate, 'R' FROM #CASHFLOW_TmpAcct T0 WHERE T0."CardCode" =:v_CtrAcct AND T0."CardType" <> 'V' AND T0."CardType" <> 'D';
				END IF;
			ELSE
				INSERT INTO #CASHFLOW_TmpOverView SELECT :v_FirstEndDate, 0, 0,(:v_Debit - :v_Credit) * :v_Rate, 'R' FROM #CASHFLOW_TmpOCRD T0 WHERE T0."CardCode" =:v_AcctCode;
			END IF;
		END IF;
		
		IF (:v_Frequency = 'D') THEN
			v_NextDue := ADD_DAYS (v_NextDue, v_SubFrequncy);
		ELSEIF (:v_Frequency = 'W') THEN
			v_NextDue := ADD_DAYS (v_NextDue, 7);
		ELSEIF (:v_Frequency = 'A') THEN
			v_NextDue := ADD_YEARS (v_NextDue, 1);
		ELSEIF (:v_Frequency = 'M') THEN
			v_NextDue := ADD_MONTHS (v_NextDue, 1);
		ELSEIF (:v_Frequency = 'S') THEN
			v_NextDue := ADD_MONTHS (v_NextDue, 6);
		ELSEIF (:v_Frequency = 'Q') THEN
			v_NextDue := ADD_MONTHS (v_NextDue, 3);
		ELSE
			BREAK;
		END IF;
	END WHILE;
	
	FETCH c_RecurTransQry INTO v_FrequencyC,v_SubFrequncyC,v_LimitFlagC,v_LimitDateC,v_CurrencyC,v_CtrAcctC,v_AcctCodeC,v_MainInstanceC,v_SubInstanceC,v_NextDueC,v_DebitC,v_CreditC;
	IF (:v_IsBreakCur = 1) THEN
		BREAK;
	END IF;
 END WHILE;
 CLOSE c_RecurTransQry;
 
 --- Return if Error
 --IF v_ErrInt = 2 THEN
   --GOTO FINAL_RET
 --END
 
 --- Addtional project transactions
 IF (v_ErrInt <> 2) THEN
	v_IsBreakCur := 0;
	IF (v_BoeEnable = 'Y') THEN
		OPEN c_ProjectQry1 (v_DateTo);
		FETCH c_ProjectQry1 INTO v_NextDueC, v_DebitC, v_DebitCurrencyC, v_CreditC, v_CreditCurrencyC;
		WHILE (NOT c_ProjectQry1::NOTFOUND) DO
			v_NextDue := :v_NextDueC;
			v_Debit := :v_DebitC;
			v_DebitCurrency := :v_DebitCurrencyC;
			v_Credit := :v_CreditC;
			v_CreditCurrency := :v_CreditCurrencyC;
			v_Rate := 1.0;
			IF (:v_DebitCurrency <> :v_MainCurrency  OR :v_CreditCurrency <> :v_MainCurrency) THEN
				--- Logic for dashboard: no exchange rate that day then use exchange rate today, return error even no exchange rate today
				SELECT COUNT(*) INTO v_TempInt FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
				IF (:v_TempInt = 0) THEN
					SELECT  COUNT(*) INTO v_TempInt FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_DateFrom;
					IF (:v_TempInt = 0) THEN
						v_ErrInt := 2;
						v_IsBreakCur := 1;
						BREAK;
					ELSE
						v_ErrInt := 1;
						SELECT "Rate" INTO v_Rate FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_DateFrom;
						IF (:v_DirectRateFlag <> 'Y') THEN
							v_Rate := 1.0 / :v_Rate;
						END IF;
					END IF;
				ELSE
					SELECT "Rate" INTO v_Rate FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
					IF (:v_DirectRateFlag <> 'Y') THEN
						v_Rate := 1.0 / :v_Rate;
					END IF;	
				END IF;
			END IF;
			----Not open balance
			IF (:v_NextDue >= :v_DateFrom) THEN
				INSERT INTO #CASHFLOW_TmpOverView SELECT T0."EndDate", :v_Credit * :v_Rate, :v_Debit * :v_Rate, 0, 'N' FROM #CASHFLOW_TmpDate T0 WHERE  T0."StartDate" <= :v_NextDue AND T0."EndDate" >= :v_NextDue;
			END IF;
			----Open balance
			IF :v_NextDue < :v_DateFrom THEN
				INSERT INTO #CASHFLOW_TmpOverView VALUES(:v_FirstEndDate, 0, 0, (:v_Credit - :v_Debit) * :v_Rate, 'N');
			END IF;
			FETCH c_ProjectQry1 INTO v_NextDueC, v_DebitC, v_DebitCurrencyC, v_CreditC, v_CreditCurrencyC;
		END WHILE;
		CLOSE c_ProjectQry1;
	ELSE
		OPEN c_ProjectQry2 (v_DateTo);
		FETCH c_ProjectQry2 INTO v_NextDueC, v_DebitC, v_DebitCurrencyC, v_CreditC, v_CreditCurrencyC;
		WHILE (NOT c_ProjectQry2::NOTFOUND) DO
			v_NextDue := :v_NextDueC;
			v_Debit := :v_DebitC;
			v_DebitCurrency := :v_DebitCurrencyC;
			v_Credit := :v_CreditC;
			v_CreditCurrency := :v_CreditCurrencyC;
			v_Rate := 1.0;
			IF (:v_DebitCurrency <> :v_MainCurrency  OR :v_CreditCurrency <> :v_MainCurrency) THEN
				--- Logic for dashboard: no exchange rate that day then use exchange rate today, return error even no exchange rate today
				SELECT COUNT(*) INTO v_TempInt FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
				IF (:v_TempInt = 0) THEN
					SELECT  COUNT(*) INTO v_TempInt FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_DateFrom;
					IF (:v_TempInt = 0) THEN
						v_ErrInt := 2;
						v_IsBreakCur := 1;
						BREAK;
					ELSE
						v_ErrInt := 1;
						SELECT "Rate" INTO v_Rate FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_DateFrom;
						IF (:v_DirectRateFlag <> 'Y') THEN
							v_Rate := 1.0 / :v_Rate;
						END IF;
					END IF;
				ELSE
					SELECT "Rate" INTO v_Rate FROM "ORTT" WHERE ("Currency" = :v_DebitCurrency OR "Currency" = :v_CreditCurrency) AND "RateDate" = :v_NextDue;
					IF (:v_DirectRateFlag <> 'Y') THEN
						v_Rate := 1.0 / :v_Rate;
					END IF;	
				END IF;
			END IF;
			----Not open balance
			IF (:v_NextDue >= :v_DateFrom) THEN
				INSERT INTO #CASHFLOW_TmpOverView SELECT T0."EndDate", :v_Credit * :v_Rate, :v_Debit * :v_Rate, 0, 'N' FROM #CASHFLOW_TmpDate T0 WHERE  T0."StartDate" <= :v_NextDue AND T0."EndDate" >= :v_NextDue;
			END IF;
			----Open balance
			IF :v_NextDue < :v_DateFrom THEN
				INSERT INTO #CASHFLOW_TmpOverView VALUES(:v_FirstEndDate, 0, 0, (:v_Credit - :v_Debit) * :v_Rate, 'N');
			END IF;
			FETCH c_ProjectQry2 INTO v_NextDueC, v_DebitC, v_DebitCurrencyC, v_CreditC, v_CreditCurrencyC;
		END WHILE;
		CLOSE c_ProjectQry2;
	END IF;
 END IF;
 
 ----Final Results
 --- First line show the message info,'E' represent Error, 'W' represent Warning, 'N' represent Normal
 --FINAL_RET:
 IF (:v_ErrInt = 2) THEN
	SELECT NULL As "EndDate", NULL As "Debit", NULL As "Credit", NULL As "OpenBalance", 'E' As "TransType" FROM DUMMY;
 ELSE
	v_QryString := 'SELECT T5.* FROM (';
	IF (v_ErrInt = 1) THEN
		v_QryString := :v_QryString || 'SELECT NULL AS "EndDate", NULL AS "Debit", NULL  AS "Credit", NULL AS "OpenBalance", ''W'' AS "TransType" FROM DUMMY 		UNION ALL ';
	ELSE
		v_QryString := :v_QryString || 'SELECT NULL AS "EndDate", NULL AS "Debit", NULL  AS "Credit", NULL AS "OpenBalance", ''N'' AS "TransType" FROM DUMMY         UNION ALL ';
	END IF;
	v_QryString := :v_QryString || 'SELECT T4."EndDate" AS "EndDate",  T4."Debit" AS "Debit", T4."Credit" AS "Credit", T4."OpenBalance" AS "OpenBalance", T4."TransType" AS "TransType" FROM (          SELECT T2."EndDate" AS "EndDate", SUM(T3."Debit") AS "Debit", SUM(T3."Credit") AS "Credit", SUM(T3."OpenBalance") AS "OpenBalance", T2."TransType" AS "TransType"          FROM (             SELECT T0."TransType", T1."EndDate" FROM (              SELECT ''N'' AS "TransType" FROM DUMMY              UNION              SELECT ''P'' AS "TransType" FROM DUMMY              UNION              SELECT ''R'' AS "TransType" FROM DUMMY) AS T0, #CASHFLOW_TmpDate T1          ) AS T2           LEFT JOIN #CASHFLOW_TmpOverView T3 ON T3."TransType" = T2."TransType" AND T2."EndDate" = T3."Indicator"          GROUP BY T2."EndDate", T2."TransType") AS T4    ) AS T5    ORDER BY T5."EndDate", T5."TransType" ';
	EXECUTE IMMEDIATE (:v_QryString);
 END IF;

 -- Drop Temp tables
 --DROP TABLE #CASHFLOW_TmpDate;
 --DROP TABLE #CASHFLOW_TmpOCRD;
 --DROP TABLE #CASHFLOW_TmpAcct;
 --DROP TABLE #CASHFLOW_TmpOverView;
 END;

-- B1 DEPENDS: AFTER:SP:TmSp_DAB004_AccountList_QRYSTR AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam
--DROP PROCEDURE TmSp_DAB004_CashFlowRatio;
create procedure TmSp_DAB004_CashFlowRatio (IN IntervalSeq INTEGER, IN LimitedBPsCount INTEGER, IN LimitedSLPsCount INTEGER, IN IntervalVal nvarChar(1), IN VoucherFlag nvarChar(1), IN RecurringFlag nvarChar(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
 /********* Begin Procedure Script ************/ 
 v_Today 		Date;
 v_DateFrom 	Date;
 v_DateTo	  	Date;
 v_BoeEnable    nvarChar(1);
 v_SgmActEnable nvarChar(1);
 v_LocalSet     nvarChar(3);
 v_ApaCheck     nvarChar(1);
 v_QryString    nvarChar(8000);
 v_FmtString    nvarChar(100);
 v_Frequency 	nvarChar(1);
 v_SubFrequncy 	INTEGER;
 v_LimitFlag 	nvarChar(1);
 v_LimitDate 	Date;
 v_Currency 	nVarchar(3);
 v_AcctCode 	nVarchar(15);
 v_NextDue 		Date;
 v_Debit 		DECIMAL(21,6);
 v_Credit 		DECIMAL(21,6);
 v_MainCurrency 	nVarchar(3);
 v_DirectRateFlag 	nvarChar(1);
 v_Rate 		DECIMAL(21,6);
 v_DebitCurrency 	nVarchar(3);
 v_CreditCurrency 	nVarchar(3);
 v_NoDefinedSlpName nvarChar(100);
 v_TempInt     	INTEGER;
 v_FilterInBPFlag 	nvarChar(1);
 v_cDateTo		Date;
 v_tempDate		Date;
 
 v_FrequencyC 	nvarChar(1);
 v_SubFrequncyC 	INTEGER;
 v_LimitFlagC 	nvarChar(1);
 v_LimitDateC 	Date;
 v_CurrencyC 	nVarchar(3);
 v_AcctCodeC 	nVarchar(15);
 v_DebitC 		DECIMAL(21,6);
 v_CreditC 		DECIMAL(21,6);
 
 in_IntervalVal  nvarChar(1);
 in_VoucherFlag nvarChar(1);
 in_RecurringFlag nvarChar(1);
 ----CURSOR DEFINE
 CURSOR c_RecurTransQry (v_cDateTo DATE) FOR
 SELECT T0."Frequency", T0."Remind", T0."LimitRtrns", T0."LimitDate", T1."Currency", T1."AcctCode", T0."NextDeu", T1."Debit", T1."Credit"  FROM "ORCR" T0 
   INNER JOIN "RCR1" T1 ON T1."RcurCode" = T0."RcurCode" AND T0."Instance" = T1."Instance"
   WHERE T0."Frequency" <> 'T'  AND T0."NextDeu" <= :v_cDateTo AND (T0."Frequency" <> 'O' OR T1."Instance" <> 0) AND T1."CtrlAcct" <> T1."AcctCode" AND
    (T0."LimitRtrns" <> 'Y' OR T0."NextDeu" <= T0."LimitDate");
	
 BEGIN
 --For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:IntervalVal);    
	call _TmSp_ValidateSpParam(:VoucherFlag);    
	call _TmSp_ValidateSpParam(:RecurringFlag);      
	
 -- DROP TEMP TABLE
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPOCRD' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpOCRD;
 END IF;
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPACCT' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpAcct;
 END IF;
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPRATIO' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpRatio;
 END IF;
 select count (*) into v_TempInt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#CASHFLOW_TMPRATIOTOSHOW' AND SCHEMA_NAME = CURRENT_SCHEMA and connection_id = current_connection;
 IF :v_TempInt > 0 THEN
 	DROP TABLE #CASHFLOW_TmpRatioToShow;
 END IF;
 
 in_IntervalVal := :IntervalVal;
 in_VoucherFlag := :VoucherFlag;
 in_RecurringFlag := :RecurringFlag;
 
 IF (:IntervalVal = '' or LENGTH(:IntervalVal) = 0) THEN
	in_IntervalVal := 'D';
 END IF;
 
 IF (:VoucherFlag = '' or LENGTH(:VoucherFlag) = 0) THEN
	in_VoucherFlag := 'N';
 END IF;
 
 IF (:RecurringFlag = '' or LENGTH(:RecurringFlag) = 0) THEN
	in_RecurringFlag := 'N';
 END IF;
 
 SELECT "EnableBOE", "EnbSgmnAct", "LawsSet" INTO v_BoeEnable, v_SgmActEnable, v_LocalSet FROM "CINF";
 
 IF (:v_LocalSet = 'CN' OR :v_LocalSet = 'JP') THEN
   v_ApaCheck := 'Y';
 ELSE
   v_ApaCheck := 'N';
 END IF;
 
 --- Filter the inactive BP
 create local temporary COLUMN table #CASHFLOW_TmpOCRD ("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarChar(1));
 
 IF (:v_FilterInBPFlag = 'Y') THEN
	INSERT INTO #CASHFLOW_TmpOCRD SELECT "CardCode", "CardName", "CardType" FROM "OCRD";
 ELSE
	INSERT INTO #CASHFLOW_TmpOCRD SELECT "CardCode", "CardName", "CardType" FROM "OCRD" WHERE ("CardCode" IS NULL OR ("validFor" = 'Y' OR ("frozenFor" = 'Y'  AND ("frozenFrom" IS NOT NULL OR "frozenTo" IS NOT NULL  )) OR  ("validFor" = 'N'  AND  "frozenFor" = 'N' )));
 END IF;
 
 --- Period
 v_Today := CURRENT_DATE;
 IF (:in_IntervalVal = 'D') THEN
	v_DateFrom := ADD_DAYS (v_Today, :IntervalSeq - 1);
	v_DateTo := :v_DateFrom;
 ELSEIF (:in_IntervalVal = 'W') THEN
	v_DateFrom := ADD_DAYS (v_Today, (:IntervalSeq - 1) * 7);
	v_DateTo := ADD_DAYS (v_Today, :IntervalSeq * 7);
	v_DateTo := ADD_DAYS (v_DateTo, -1);
 ELSE
	v_DateFrom := ADD_MONTHS (v_Today, :IntervalSeq - 1);
	v_DateTo := ADD_MONTHS (v_Today, :IntervalSeq);
	v_DateTo := ADD_DAYS (v_DateTo, -1);
 END IF;
 
 --- Main Currency (think about different currency)
 SELECT "MainCurncy", "DirectRate" INTO v_MainCurrency, v_DirectRateFlag FROM "OADM";
 
 --- No defined Sales Employee 
 v_NoDefinedSlpName := '';
 select count (*) into v_TempInt FROM "OSLP" WHERE "SlpCode" = '-1';
 IF :v_TempInt > 0 THEN
	SELECT "SlpName" INTO v_NoDefinedSlpName FROM "OSLP" WHERE "SlpCode" = '-1';
 END IF;
 
 ----Get/Set Account List
 CREATE local temporary COLUMN TABLE #CASHFLOW_TmpAcct ("CardCode" nvarChar(15), "CardName" nvarChar(200), "CardType" nvarChar(1));

 CALL TmSp_DAB004_AccountList_QRYSTR (0, v_QryString);
 v_QryString := 'Insert INTO #CASHFLOW_TmpAcct (' || :v_QryString || ')';
 -- SELECT :v_QryString FROM DUMMY;
 exec (:v_QryString);
 
 ----Create temp table
 CREATE local temporary COLUMN TABLE #CASHFLOW_TmpRatio ("CardCode" nvarChar(15), "CardName" nvarChar(200), "SlpCode" nvarChar(15), "SlpName" nvarChar(155), "Direction" nvarChar(1), "Amount" DECIMAL(21,6));
 ----I represent incoming, O represent outgoing
 ----Customer,Vendor 
 v_QryString := 'SELECT T1."CardCode", T1."CardName", (CASE WHEN T2."SlpCode" IS NULL THEN ''-1'' ELSE T2."SlpCode" END) AS "SlpCode", (CASE WHEN T2."SlpCode" IS NULL THEN ''' || :v_NoDefinedSlpName || ''' ELSE T3."SlpName" END) AS "SlpName", (CASE WHEN T0."BalDueDeb" < 0 OR T0."BalDueCred" > 0 THEN ''O'' ELSE ''I'' END) AS "Direction", ABS(T0."BalDueDeb" - T0."BalDueCred") AS "Amount" FROM "JDT1" T0   INNER JOIN #CASHFLOW_TmpOCRD T1 ON  T1."CardCode" = T0."ShortName"  LEFT OUTER JOIN "B1_JournalTransSourceView" T2 ON T2."ObjType" = T0."TransType" AND T2."DocEntry" = T0."CreatedBy" AND (T2."TransType" = ''I'' AND T2."InstlmntID" = T0."SourceLine")    LEFT OUTER JOIN "OSLP" T3 ON T2."SlpCode" = T3."SlpCode"   WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''') AND     (T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0) AND  T0."Account" <> T0."ShortName" AND      T1."CardType" IN (''C'', ''S'')  AND  T0."Account" NOT IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') AND	 T0."TransType" IN (''30'',''-2'',''69'',''25'',''47'',''-4'',''182'',''203'',''204'',''14'',''13'',''165'',''19'',''18'',''163'',''57'',''76'',''24'',''46'') ';
 
 ----Boe
 IF (:v_BoeEnable = 'Y') THEN
 v_QryString := :v_QryString || '  UNION ALL 
  SELECT T1."CardCode", T1."CardName", (CASE WHEN T2."SlpCode" IS NULL THEN ''-1'' ELSE T2."SlpCode" END) AS "SlpCode", (CASE WHEN T2."SlpCode" IS NULL THEN ''' || :v_NoDefinedSlpName || ''' ELSE T3."SlpName" END) AS "SlpName", (CASE WHEN T0."BalDueDeb" < 0 OR T0."BalDueCred" > 0 THEN ''O'' ELSE ''I'' END) AS "Direction", ABS(T0."BalDueDeb" - T0."BalDueCred") AS "Amount" FROM JDT1 T0    INNER JOIN #CASHFLOW_TmpOCRD T1  ON  T1."CardCode" = T0."ShortName"      LEFT OUTER JOIN "B1_JournalTransSourceView" T2 ON T2."ObjType" = T0."TransType" AND T2."DocEntry" = T0."CreatedBy" AND (T2."TransType" = ''I'' AND T2."InstlmntID" = T0."SourceLine")     LEFT OUTER JOIN "OSLP" T3 ON T2."SlpCode" = T3."SlpCode"    WHERE (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''')  AND       (T0."BalDueDeb" <> 0  OR  T0."BalDueCred" <> 0) AND  T0."Account" <> T0."ShortName" AND     T0."Account" IN (SELECT "CardCode" FROM #CASHFLOW_TmpAcct WHERE "CardType" = ''E'') ';
 END IF;
 
 ----Voucher customer,vendor
 IF (:in_VoucherFlag = 'Y') THEN
 v_QryString := :v_QryString || '  UNION ALL   SELECT T2."CardCode", T2."CardName", ''-1'' AS "SlpCode", ''' || :v_NoDefinedSlpName || ''' AS "SlpName", (CASE WHEN T0."Debit" < 0 OR T0."Credit" > 0 THEN ''O'' ELSE ''I'' END) AS "Direction", ABS(T0."Debit" - T0."Credit") AS "Amount"  FROM  "BTF1" T0      INNER  JOIN "OBTF" T1  ON  T0."BatchNum" = T1."BatchNum"  AND  T0."TransId" = T1."TransId"       INNER  JOIN #CASHFLOW_TmpOCRD T2  ON  T2."CardCode" = T0."ShortName"       WHERE T1."BtfStatus" <> ''C''  AND (T0."DueDate" BETWEEN ''' || :v_DateFrom || ''' AND ''' || :v_DateTo || ''') AND       T0."Account" <> T0."ShortName"  AND  T2."CardType" IN (''C '', ''S'') ';
 END IF;
 --SELECT :v_QryString From DUMMY;
 v_QryString := 'INSERT INTO #CASHFLOW_TmpRatio (' || :v_QryString || ')';
 EXEC (:v_QryString);
 
 ----Recurring transaction
 IF (:in_RecurringFlag = 'Y') THEN
 --- Recurring transaction loop 1 
 OPEN c_RecurTransQry (v_DateTo);
 Fetch c_RecurTransQry Into v_FrequencyC, v_SubFrequncyC, v_LimitFlagC, v_LimitDateC, v_CurrencyC, v_AcctCodeC, v_NextDue, v_DebitC, v_CreditC;
 WHILE NOT c_RecurTransQry::NOTFOUND DO
	v_Frequency := :v_FrequencyC;
	v_SubFrequncy := :v_SubFrequncyC;
	v_LimitFlag := :v_LimitFlagC;
	v_LimitDate := :v_LimitDateC;
	v_Currency := :v_CurrencyC;
	v_AcctCode := :v_AcctCodeC;
	v_Debit := :v_DebitC;
	v_Credit := :v_CreditC;
	v_tempDate := :v_NextDue;
	--- Recurring transaction  loop 2
	WHILE (:v_tempDate <= :v_DateTo AND (:v_LimitFlag <> 'Y' OR :v_tempDate <= :v_LimitDate)) DO
		v_Rate := 1;
		IF (:v_Currency <> :v_MainCurrency ) THEN 
			 --- Logic for dashboard: no exchange rate that day then use exchange rate today
			 SELECT count(*) INTO v_TempInt FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_tempDate;
			 IF (:v_TempInt = 0) THEN
				SELECT count(*) INTO v_TempInt FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_Today;
				IF (:v_TempInt > 0) THEN
					SELECT  (CASE WHEN :v_DirectRateFlag = 'Y' THEN "Rate" ELSE 1.0/"Rate" END) INTO v_Rate FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_Today;
				END IF;
			 ELSE
				SELECT (CASE WHEN :v_DirectRateFlag = 'Y' THEN "Rate" ELSE 1.0/"Rate" END) INTO v_Rate FROM "ORTT" WHERE "Currency" = :v_Currency AND "RateDate" = :v_tempDate;
			 END IF;
		END IF;
		IF (:v_tempDate >= :v_DateFrom) THEN
			INSERT INTO #CASHFLOW_TmpRatio SELECT T0."CardCode", T0."CardName", '-1' AS "SlpCode", :v_NoDefinedSlpName AS "SlpName", (CASE WHEN (:v_Debit < 0 OR :v_Credit > 0) THEN 'O' ELSE 'I' END) AS "Direction", ABS((:v_Debit - :v_Credit)*:v_Rate) AS "Amount" FROM #CASHFLOW_TmpOCRD T0 WHERE T0."CardCode" = :v_AcctCode;
		END IF;
		IF (:v_Frequency = 'D') THEN
			v_tempDate := ADD_DAYS (v_tempDate, v_SubFrequncy);
		ELSEIF (:v_Frequency = 'W') THEN
			v_tempDate := ADD_DAYS (v_tempDate, 7);
		ELSEIF (:v_Frequency = 'A') THEN
			v_tempDate := ADD_YEARS (v_tempDate, 1);
		ELSEIF (:v_Frequency = 'M') THEN
			v_tempDate := ADD_MONTHS (v_tempDate, 1);
		ELSEIF (:v_Frequency = 'S') THEN
			v_tempDate := ADD_MONTHS (v_tempDate, 6);
		ELSEIF (:v_Frequency = 'Q') THEN
			v_tempDate := ADD_MONTHS (v_tempDate, 3);
		ELSE
			BREAK;
		END IF;
	END WHILE;
	Fetch c_RecurTransQry Into v_FrequencyC, v_SubFrequncyC, v_LimitFlagC, v_LimitDateC, v_CurrencyC, v_AcctCodeC, v_NextDue, v_DebitC, v_CreditC;
 END WHILE;
 CLOSE c_RecurTransQry;
 END IF;
 
 ----Final Results
 ----Customerr & Sales Employee
 ----Create temp table
 CREATE local temporary COLUMN TABLE #CASHFLOW_TmpRatioToShow ("CardCode" nvarChar(15), "CardName" nvarChar(200), "Direction" nvarChar(1), "Amount" DECIMAL(21,6), "SubType" nvarChar(1));

 v_QryString := ' SELECT T1.* FROM (SELECT TOP ' || :LimitedBPsCount || ' *, ''C'' AS "SubType" FROM ( SELECT "CardCode", "CardName", ''I'' AS "Direction", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''I'' GROUP BY "CardCode", "CardName") T0                     ORDER BY T0."Amount" DESC) T1                    UNION ALL                    SELECT ''Other'',''Other'', ''I'', SUM("Amount"), ''C'' FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''I'' AND "CardCode" NOT IN (SELECT TOP ' || :LimitedBPsCount || ' T0."CardCode" FROM ( SELECT "CardCode", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''I'' GROUP BY "CardCode") T0 ORDER BY T0."Amount" DESC)                    UNION ALL                    SELECT T1.* FROM (SELECT TOP ' || :LimitedBPsCount || ' *, ''C'' AS "SubType" FROM ( SELECT "CardCode", "CardName", ''O'' AS "Direction", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''O'' GROUP BY "CardCode", "CardName") T0                     ORDER BY T0."Amount" DESC) T1                    UNION ALL					SELECT ''Other'',''Other'', ''O'', SUM("Amount"), ''C'' FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''O'' AND "CardCode" NOT IN (SELECT TOP ' || :LimitedBPsCount || ' T0."CardCode" FROM ( SELECT "CardCode", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''O'' GROUP BY "CardCode") T0 ORDER BY T0."Amount" DESC)                    UNION ALL                    SELECT T1.* FROM (SELECT TOP ' || :LimitedSLPsCount || ' *, ''S'' AS "SubType" FROM ( SELECT "SlpCode", "SlpName", ''I'' AS "Direction", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''I'' GROUP BY "SlpCode", "SlpName") T0                     ORDER BY T0."Amount" DESC) T1					 UNION ALL                    SELECT ''Other'',''Other'', ''I'', SUM("Amount"), ''S'' FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''I'' AND "SlpCode" NOT IN (SELECT TOP ' || :LimitedSLPsCount || ' T0."SlpCode" FROM ( SELECT "SlpCode", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''I'' GROUP BY "SlpCode") T0 ORDER BY T0."Amount" DESC)                    UNION ALL                    SELECT T1.* FROM (SELECT TOP ' || :LimitedSLPsCount || ' *, ''S'' AS "SubType" FROM ( SELECT "SlpCode", "SlpName", ''O'' AS "Direction", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''O'' GROUP BY "SlpCode", "SlpName") T0                     ORDER BY T0."Amount" DESC) T1                     UNION ALL                    SELECT ''Other'',''Other'', ''O'', SUM("Amount"), ''S'' FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''O'' AND "SlpCode" NOT IN (SELECT TOP ' || :LimitedSLPsCount || ' T0."SlpCode" FROM ( SELECT "SlpCode", SUM("Amount") AS "Amount" FROM #CASHFLOW_TmpRatio WHERE "Direction" = ''O'' GROUP BY "SlpCode") T0 ORDER BY t0."Amount" DESC) ';
 v_QryString := 'Insert INTO #CASHFLOW_TmpRatioToShow (' || :v_QryString || ')';
 --SELECT :v_QryString FROM DUMMY;
 EXEC (:v_QryString);
 SELECT * FROM #CASHFLOW_TmpRatioToShow;
 
 -- Drop Temp tables
 --DROP TABLE #CASHFLOW_TmpOCRD;
 --DROP TABLE #CASHFLOW_TmpAcct;
 --DROP TABLE #CASHFLOW_TmpRatio;
 --DROP TABLE #CASHFLOW_TmpRatioToShow;
 END;

