				T0."Value_Month_11" = (SELECT SUM(T1."Value_Month_11") FROM #TMP_TABLE_FINTEMPLATES T1 WHERE (T1."Acct_Level" = 99 OR T1."Acct_Level" = :v_CurLevel + 1) AND T1."FatherNum" = T0."AccountCode" group by T1."FatherNum"),
