CREATE PROCEDURE TmSp_GetDocVatTotals(in array nvarchar(4),
	in absEntry int, 
	in totalField int, 
	object nvarchar(4)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	--i int;
BEGIN
	IF (:totalField = 0) THEN
		EXECUTE IMMEDIATE ('SELECT
			T1."Code", 
			T1."Name", 
			T0."VatPrcnt", 
			T0."EquVatPer",
			0 As "Col1", 0 As "Col2", 0 As "Col3", 0 As "Col4", 0 As "Col5", 0 As "Col6", 0 As "Col7", 0 As "Col8", 0 As "Col9", 0 As "Col10", 0 As "Col11", 0 As "Col12", 0 As "Col13", 0 As "Col14", 0 As "Col15", 0 As "Col16"
			FROM "' || :array || '" T0 INNER  JOIN "OVTG" T1 ON  T0."VatGroup" = T1."Code"   
			INNER JOIN "' || :object || '" T2 ON T0."DocEntry" = T2."DocEntry"
		WHERE T0."DocEntry" = ' || :absEntry || '
		GROUP BY T1."Code", T1."Name", T0."VatPrcnt",  T0."EquVatPer"
		ORDER BY T1."Code"');
   	ELSE IF (:totalField = 1) THEN
		EXECUTE IMMEDIATE ('SELECT 
			T1."Code", 
			T1."Name", 
			T0."VatPrcnt", 
			T0."EquVatPer",
			0 As "Col1", 0 As "Col2", 0 As "Col3", 0 As "Col4", 0 As "Col5", 0 As "Col6", 0 As "Col7", 0 As "Col8", 0 As "Col9", 0 As "Col10", 0 As "Col11", 0 As "Col12", 0 As "Col13", 0 As "Col14", 0 As "Col15", 0 As "Col16"
			FROM "' || :array || '" T0 INNER  JOIN "OVTG" T1 ON  T0."VatGroup" = T1."Code"   
				INNER JOIN "' || :object || '" T2 ON T0."DocEntry" = T2."DocEntry"
			WHERE T0."DocEntry" = ' || :absEntry || '   
			GROUP BY T1."Code", T1."Name", T0."VatPrcnt",  T0."EquVatPer"
			ORDER BY T1."Code"');	
		ELSE
			EXECUTE IMMEDIATE ('SELECT
				T1."Code", 
				T1."Name", 
				T0."VatPrcnt", 
				T0."EquVatPer",
				0 As "Col1", 0 As "Col2", 0 As "Col3", 0 As "Col4", 0 As "Col5", 0 As "Col6", 0 As "Col7", 0 As "Col8", 0 As "Col9", 0 As "Col10", 0 As "Col11", 0 As "Col12", 0 As "Col13", 0 As "Col14", 0 As "Col15", 0 As "Col16"
				FROM "' || :array || '" T0 INNER  JOIN "OVTG" T1 ON  T0."VatGroup" = T1."Code"   
				INNER JOIN "' || :object || '" T2 ON T0."DocEntry" = T2."DocEntry"
				WHERE T0."DocEntry" = ' || :absEntry || '
				GROUP BY T1."Code", T1."Name", T0."VatPrcnt",  T0."EquVatPer"
				ORDER BY T1."Code"');
		END IF;
	END IF;
END;

-- CALL TmSp_GetExpiredPersonalData;
-- DROP PROCEDURE TmSp_GetExpiredPersonalData;
CREATE PROCEDURE TmSp_GetExpiredPersonalData
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
	--*With Encryption
AS
BEGIN
--Get Expired Personal Data of OHEM/OUSR/CPN1/OCPR
	SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."DatSubKey2", T0."ObjType", T0."KeyValue1", T0."CreateDate", T1."PeriodYear", ADD_YEARS(T0."CreateDate", T1."PeriodYear") AS "ExpiredDate"
	FROM OBPD T0, ODRP T1
	WHERE T1."Active" = 'Y' 
		 AND T0."DatSubType" = T1."DatSubType" 
		 AND T0."DatSubType" != 'OCRD' AND T0."DatSubType" != 'OUDO'
		 AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
		 AND (T0."TableName" LIKE ('O%') OR T0."TableName" = 'CPN1')
		 AND (T0."DatSubType" != 'OCPR' OR (T0."DatSubType" = 'OCPR' AND T0."TableName" != 'OCRD'))
		 
	UNION

--Get Expired Personal Data of OCRD
	SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."DatSubKey2", T0."ObjType", T0."KeyValue1", T0."CreateDate", T1."PeriodYear", ADD_YEARS(T0."CreateDate", T1."PeriodYear") AS "ExpiredDate"
	FROM OBPD T0, ODRP T1
	WHERE T1."Active" = 'Y' AND T1."ObjType" != -1
		 AND T0."DatSubType" = T1."DatSubType" 
		 AND T0."DatSubType" ='OCRD' AND T0."ObjType" = T1."ObjType"
		 AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
		 AND T0."TableName" LIKE ('O%')
		 
	UNION

--Get Expired Personal Data of OCRD and Object Type = ALL	
	SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."DatSubKey2", T0."ObjType", T0."KeyValue1", T0."CreateDate", T1."PeriodYear", ADD_YEARS(T0."CreateDate", T1."PeriodYear") AS "ExpiredDate"
	FROM OBPD T0, ODRP T1
	WHERE T1."Active" = 'Y' 
		 AND T0."DatSubType" = T1."DatSubType" 
		 AND T0."DatSubType" = 'OCRD' AND T1."ObjType" = -1
		 AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
		 AND T0."TableName" LIKE ('O%') 
		 AND T0."TableName" NOT IN ('OILM', 'OITL') 
		 AND NOT EXISTS (SELECT 1 FROM ODRP T2 WHERE T2."Active" = 'Y' AND T2."ObjType" != -1 AND T0."DatSubType" = T2."DatSubType" AND T0."ObjType" = T2."ObjType")
		 
	UNION
--Get Expired Personal Data of OUDO and Object Type = ALL	
	SELECT DISTINCT T0."DatSubType", T0."DatSubKey", T0."DatSubKey2", T0."ObjType", T0."KeyValue1", T0."CreateDate", T1."PeriodYear", ADD_YEARS(T0."CreateDate", T1."PeriodYear") AS "ExpiredDate"
	FROM OBPD T0, ODRP T1
	WHERE T1."Active" = 'Y' 
		 AND T0."DatSubType" = T1."DatSubType" 
		 AND T0."DatSubType" = 'OUDO' AND T1."ObjType" = -1
		 AND ADD_YEARS(T0."CreateDate", T1."PeriodYear") < CURDATE()
		 AND T0."TableName" LIKE ('@%') 
		 AND NOT EXISTS (SELECT 1 FROM ODRP T2 WHERE T2."Active" = 'Y' AND T2."ObjType" != -1 AND T0."DatSubType" = T2."DatSubType")
		 
	ORDER BY T0."DatSubType", T0."DatSubKey", T0."ObjType", T0."KeyValue1";
END;

/*
  drop procedure TmSp_GetFifoLayers
  Ussage:  
	call TmSp_GetFifoLayers ('01-SW-550', 'RSFGWH', 64, 6, 'Y', 'OIVQ')
*/

CREATE PROCEDURE TmSp_GetFifoLayers
(
	in ItemCodeStr NVARCHAR(100),
	in LocCodeStr NVARCHAR(100),
	in LocType INT,
	in QuantityRequested DECIMAL(21,6),
	in IsManageByWhsStr VARCHAR(1),
	in IVQ_TableStr VARCHAR(5)
)
LANGUAGE SQLSCRIPT
AS
subStrSQL NVARCHAR(5000);
strSQL NVARCHAR(5000);
BEGIN
	declare QuantityRequestedStr VARCHAR(128);
	declare LocTypeStr VARCHAR(128);
	declare IVL1_TableStr VARCHAR(5);
	
	ItemCodeStr := replace(:ItemCodeStr,'''','''''');
	LocCodeStr := replace(:LocCodeStr,'''','''''');

	QuantityRequestedStr := CAST(:QuantityRequested as VARCHAR(128));
	LocTypeStr := CAST(:LocType as VARCHAR(128));

	IVL1_TableStr := 'IVL1';
	IF :IVQ_TableStr = 'UIVQ' THEN
		IVL1_TableStr := 'UIVL1';
	END IF;

	IF :IVQ_TableStr = 'SIVQ' THEN
		IVL1_TableStr := 'SIVL1';
	END IF;
	
	IF :IsManageByWhsStr = 'Y' THEN
	   subStrSQL :=  ''' AND "LocCode" = ''' || :LocCodeStr || ''' AND "LocType" = ''' || :LocTypeStr; 
	ELSE
	   subStrSQL := '';
	END IF;
	
	strSQL := 'SELECT "SumOpenQty", "ParentID", "TreeID" , t."TransSeq" , t."LayerID" , "OpenQty" , "OpenValue" , "AbsEntry" , "RemMethod", t1."CalcPrice", t1."LayerInQty", t1."LayerOutQ", t1."TransValue" 
	FROM
	(SELECT *, SUM("OpenQty") OVER (ORDER BY "TreeID","TransSeq" DESC, "LayerID" DESC ROWS UNBOUNDED PRECEDING) as "SumOpenQty" from "' || :IVQ_TableStr || '" 
	WHERE "OpenQty">0 AND "ItemCode" = ''' || :ItemCodeStr || :subStrSQL || ''' ) as t 
	JOIN "' || :IVL1_TableStr || '" as t1 on t."TransSeq" = t1."TransSeq" and t."LayerID" = t1."LayerID" 
	where (' || :QuantityRequestedStr || ' >= t."SumOpenQty") OR (' || :QuantityRequestedStr || ' < t."SumOpenQty" AND ' || :QuantityRequestedStr || ' > t."SumOpenQty" - "OpenQty") 
	ORDER BY "TreeID", "TransSeq" DESC, "LayerID" DESC ';
				   
	--select strSQL from dummy;
	EXECUTE IMMEDIATE strSQL;
END

