CREATE PROCEDURE TmSp_GetMaxRange(
in ObjectType 		nChar(3),
in ShowType 		nChar(3),
in DocDateFrom_in 		nvarchar(8),
in DocDateTo_in			nvarchar(8),
in DocDueDateFrom_in 	nvarchar(8),
in DocDueDateTo_in		nvarchar(8),
in CardCodeFrom		nvarchar(15),
in CardCodeTo		nvarchar(15),
in CrdGroupCode  	nvarchar(11),
in ItemCodeFrom		nvarchar(50),
in ItemCodeTo		nvarchar(50),
in ItmGroupCode  	nvarchar(11),
in ItmProps	   		nvarchar(70),
in CrdProps   		nvarchar(70),
in SlpCodeFrom		nvarchar(155),
in SlpCodeTo		nvarchar(155),
in TaxDateFrom_in 	nvarchar(8),
in TaxDateTo_in		nvarchar(8),
in Brand			nvarchar(11),			
in PrjCode			nvarchar(20),
in RptType			int,
in cutbyObject		nchar(3),
in DspFrznBP		nvarchar(1),
in DspFrznITM		nvarchar(1),
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
Header nvarchar(4);
Lines  nvarchar(4);
opObject nvarchar(4);
tmpStr nvarchar(4000);
PropsRel nvarchar(10);
ii int;
jj int;
GrossBySal nChar(1);
JoinStr nvarchar(200);
WhereStr nvarchar(4000);
VatSysColName nvarchar(20);
Mult nvarchar(5);
DocDateFrom 	nvarchar(8);
DocDateTo		nvarchar(8);
DocDueDateFrom 	nvarchar(8);
DocDueDateTo	nvarchar(8);
TaxDateFrom 	nvarchar(8);
TaxDateTo		nvarchar(8);

begin
	DocDateFrom := DocDateFrom_in;
	DocDateTo := DocDateTo_in;
	DocDueDateFrom := DocDueDateFrom_in;
	DocDueDateTo := DocDueDateTo_in;
	TaxDateFrom :=	TaxDateFrom_in;
	TaxDateTo := TaxDateTo_in;

	if (:ObjectType = 'NON') then
		return;
	end if;

	if (:ShowType = 'SNG') then
		Mult := ' 1 ';
	Else
		Mult :=  ' -1 ';
	End if;
	
	if LENGTH(:DocDateFrom) = 0 then 	
		DocDateFrom := '19700101'; 
	end if;	
	if LENGTH(:DocDateTo) = 0 then 	
		DocDateTo := '21000101';
	end if;	
	if LENGTH(:DocDueDateFrom) = 0 then 	
		DocDueDateFrom :=  '19700101'; 
	end if;	
	if LENGTH(:DocDueDateTo) = 0 then 	
		DocDueDateTo := '21000101';
	end if;	
	if LENGTH(:TaxDateFrom) = 0 then 
		TaxDateFrom :=  '19700101'; 
	end if;
	if LENGTH(:TaxDateTo) = 0 then 	
		TaxDateTo := '21000101';
	end if;

	if (:ObjectType = 'INV') then
		Header := 'OINV';
		Lines :=  'INV1';
		opObject := 'RIN';
	End if;
	
	if (:ObjectType = 'RDR') then
		Header := 'ORDR';
		Lines :=  'RDR1';
		opObject := 'NON';
	End if;
	
	if (:ObjectType = 'DLN') then
		Header := 'ODLN';
		Lines :=  'DLN1';
		opObject := 'RDN';
	End if;
	
	if (:ObjectType = 'RIN') then
		Header := 'ORIN';
		Lines :=  'RIN1';
	End if;
	
	if (:ObjectType = 'RDN') then
		Header := 'ORDN';
		Lines :=  'RDN1';
	End if;
	
	if (:ObjectType = 'PCH') then
		Header := 'OPCH';
		Lines := 'PCH1';
		opObject := 'RPC';
	End if;
	
	if (:ObjectType = 'POR') then
		Header := 'OPOR';
		Lines :=  'POR1';
		opObject := 'NON';
	End if;
	
	if (:ObjectType = 'PDN') then
		Header := 'OPDN';
		Lines :=  'PDN1';
		opObject := 'RPD';
	End if;
	
	if (:ObjectType = 'RPC') then
		Header := 'ORPC';
		Lines :=  'RPC1';
	End if;
	
	if (:ObjectType = 'RPD') then
		Header := 'ORPD';
		Lines :=  'RPD1';
	End if;
	
	delete from "TMP_GetMaxRange_Results";
			
	call TmSp_GetMaxRange_Insert (:ObjectType, 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject,:DspFrznBP, :DspFrznITM, :BPLIdSet);
			
	if (:ShowType = 'SNG' and :opObject <> 'NON') then
		call TmSp_GetMaxRange_Insert (:opObject , 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject,:DspFrznBP, :DspFrznITM, :BPLIdSet);
	end if;
		
	select Min(DocDateMain) As "Min", Max(DocDateMax) As "Max" from "TMP_GetMaxRange_Results";
	
	delete from "TMP_GetMaxRange_Results";
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_GetMaxRange_Insert(
in ObjectType 		nChar(3),
in ShowType 		nChar(3),
in DocDateFrom 		nvarchar(8),
in DocDateTo		nvarchar(8),
in DocDueDateFrom 	nvarchar(8),
in DocDueDateTo		nvarchar(8),
in CardCodeFrom		nvarchar(15),
in CardCodeTo		nvarchar(15),
in CrdGroupCode  	nvarchar(11),
in ItemCodeFrom		nvarchar(50),
in ItemCodeTo		nvarchar(50),
in ItmGroupCode  	nvarchar(11),
in ItmProps	   		nvarchar(70),
in CrdProps   		nvarchar(70),
in SlpCodeFrom		nvarchar(155),
in SlpCodeTo		nvarchar(155),
in TaxDateFrom 		nvarchar(8),
in TaxDateTo		nvarchar(8),
in Brand			nvarchar(11),			
in PrjCode			nvarchar(20),
in RptType			int,
in cutbyObject		nchar(3),
in DspFrznBP		nvarchar(1),
in DspFrznITM		nvarchar(1),
in BPLIdSet 		nvarchar(1000)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
Header nvarchar(4);
Lines  nvarchar(4);
opObject nvarchar(4);
tmpStr nvarchar(4000);
PropsRel nvarchar(10);
ii int;
jj int;
GrossBySal nChar(1);
JoinStr nvarchar(200);
WhereStr nvarchar(4000);
VatSysColName nvarchar(20);
Mult nvarchar(5);

begin

call _TmSp_ValidateSpParam (:ObjectType);
call _TmSp_ValidateSpParam (:ShowType);
call _TmSp_ValidateSpParam (:DocDateFrom);
call _TmSp_ValidateSpParam (:DocDateTo);
call _TmSp_ValidateSpParam (:DocDueDateFrom);
call _TmSp_ValidateSpParam (:DocDueDateTo);
call _TmSp_ValidateSpParam (:CardCodeFrom);
call _TmSp_ValidateSpParam (:CardCodeTo);
call _TmSp_ValidateSpParam (:CrdGroupCode);
call _TmSp_ValidateSpParam (:ItemCodeFrom);
call _TmSp_ValidateSpParam (:ItemCodeTo);
call _TmSp_ValidateSpParam (:ItmGroupCode);
call _TmSp_ValidateSpParam (:ItmProps);
call _TmSp_ValidateSpParam (:CrdProps);
call _TmSp_ValidateSpParam (:SlpCodeFrom);
call _TmSp_ValidateSpParam (:SlpCodeTo);
call _TmSp_ValidateSpParam (:TaxDateFrom);
call _TmSp_ValidateSpParam (:TaxDateTo);
call _TmSp_ValidateSpParam (:Brand);
call _TmSp_ValidateSpParam (:PrjCode);
call _TmSp_ValidateSpParam (:cutbyObject);
call _TmSp_ValidateSpParam (:DspFrznBP);
call _TmSp_ValidateSpParam (:DspFrznITM);
call _TmSp_ValidateSpParam (:BPLIdSet);

	if (:ShowType = 'SNG') then
		Mult := ' 1 ';
	Else
		Mult :=  ' -1 ';
	End if;
	
	if (:ObjectType = 'INV') then
		Header := 'OINV';
		Lines :=  'INV1';
		opObject := 'RIN';
	End if;
	
	if (:ObjectType = 'RDR') then
		Header := 'ORDR';
		Lines :=  'RDR1';
		opObject := 'NON';
	End if;
	
	if (:ObjectType = 'DLN') then
		Header := 'ODLN';
		Lines :=  'DLN1';
		opObject := 'RDN';
	End if;
	
	if (:ObjectType = 'RIN') then
		Header := 'ORIN';
		Lines :=  'RIN1';
	End if;
	
	if (:ObjectType = 'RDN') then
		Header := 'ORDN';
		Lines :=  'RDN1';
	End if;
	
	if (:ObjectType = 'PCH') then
		Header := 'OPCH';
		Lines := 'PCH1';
		opObject := 'RPC';
	End if;
	
	if (:ObjectType = 'POR') then
		Header := 'OPOR';
		Lines :=  'POR1';
		opObject := 'NON';
	End if;
	
	if (:ObjectType = 'PDN') then
		Header := 'OPDN';
		Lines :=  'PDN1';
		opObject := 'RPD';
	End if;
	
	if (:ObjectType = 'RPC') then
		Header := 'ORPC';
		Lines :=  'RPC1';
	End if;
	
	if (:ObjectType = 'RPD') then
		Header := 'ORPD';
		Lines :=  'RPD1';
	End if;

	WhereStr := '
	Where      Main."DocDate"  Between  TO_DATE(''' ||  :DocDateFrom || ''', ''YYYYMMDD'' )  And    TO_DATE(''' ||  :DocDateTo || ''', ''YYYYMMDD'' ) 
	And    	   Main."DocDueDate"  Between  TO_DATE(''' ||  :DocDueDateFrom || ''', ''YYYYMMDD'' )  And    TO_DATE(''' ||  :DocDueDateTo || ''', ''YYYYMMDD'' ) 
	And 	   Main."Instance" = 0
	And	   Main."CANCELED" = ''N''
	And	   Main."TaxDate" Between TO_DATE(''' ||  :TaxDateFrom || ''', ''YYYYMMDD'' )  And  TO_DATE(''' ||  :TaxDateTo || ''', ''YYYYMMDD'' )';

		--Card Code range
		if LENGTH(:CardCodeFrom) > 0 then
			WhereStr := :WhereStr  || '   And    Main."CardCode" >=  N''' ||  :CardCodeFrom || '''  ';
		END if;
		
		if LENGTH(:CardCodeTo) > 0 then
			WhereStr := :WhereStr   || '   And    Main."CardCode" <=  N''' ||  :CardCodeTo || '''  ';
		END if;
		
		JoinStr := 'Inner Join ' || :Lines || '  Lines On Main."DocEntry" = Lines."DocEntry" ' ||
					   ' Inner  Join OCRD Cards On Cards."CardCode" = Main."CardCode" ' ||
					   ' left Join OITM Items On Items."ItemCode" = Lines."ItemCode" ';
					   
		IF :DspFrznBP = 'N' then
			WhereStr := :WhereStr || ' And ' || '(Cards."validFor" = ''Y'' or (Cards."frozenFor" = ''Y'' and (Cards."frozenFrom" is not null or Cards."frozenTo" is not null)) or (Cards."validFor" = ''N'' and Cards."frozenFor" = ''N''))';
		END if;
		
		IF :DspFrznITM = 'N' then
			WhereStr := :WhereStr || ' And ' ||  '(Items."ItemCode" is null or Items."validFor" = ''Y'' or (Items."frozenFor" = ''Y'' and (Items."frozenFrom" is not null or Items."frozenTo" is not null)) or (Items."validFor" = ''N'' and Items."frozenFor" = ''N''))';
		END if;
		
		if LENGTH(:BPLIdSet) > 0 then
			WhereStr := :WhereStr || ' And Main."BPLId" in (' || :BPLIdSet || ')';
		end if;

		tmpStr := ' Insert Into "TMP_GetMaxRange_Results" Select  Max(Main."DocDate"),  Min(Main."DocDate") From ' || :Header || ' Main  ';

		--select (:tmpStr ||:JoinStr || :WhereStr) from dummy where 1=1;
		exec (:tmpStr ||:JoinStr || :WhereStr);
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE  TmSp_GetOpenRCTs(
IN object  int,
IN card nvarchar(100),
IN frgnCurr nchar)

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
BEGIN
if (:object = 24)
THEN
	if (:frgnCurr = N'N')
	THEN
		SELECT JDT1.* FROM 
		JDT1 INNER JOIN ORCT ON JDT1."CreatedBy"= ORCT."DocEntry"
			
		WHERE
		JDT1."ShortName" = :card AND
		ORCT."PayNoDoc"=N'Y'  AND
		ORCT."NoDocSum" = (ORCT."DocTotal" -ORCT."VatSum" +ORCT."WtSum") AND
		JDT1."TransType" = 24  AND
		JDT1."IntrnMatch"=0 AND
		JDT1."Closed"=N'N' AND
		(JDT1."SourceLine" Is Null or  JDT1."SourceLine"<> -6);
	
	else

		SELECT JDT1.* FROM 
		JDT1 INNER JOIN ORCT ON JDT1."CreatedBy"= ORCT."DocEntry"
		
		WHERE
		JDT1."ShortName" =:card AND
		ORCT."PayNoDoc"=N'Y'  AND
		ORCT."NoDocSumFC" = (ORCT."DocTotalFC" - ORCT."VatSumFC" +ORCT."WtSumFrgn")  AND
		JDT1."TransType" =24  AND
		JDT1."IntrnMatch"=0 AND
		JDT1."Closed"=N'N' AND
		(JDT1."SourceLine" Is Null or  JDT1."SourceLine"<> -6);
	end IF;

else


	if (:frgnCurr = N'N')
	THEN
		SELECT JDT1.* FROM 
		JDT1 INNER JOIN OVPM ON JDT1."CreatedBy"= OVPM."DocEntry"
		
		WHERE
		JDT1."ShortName" = :card AND
		OVPM."PayNoDoc"=N'Y'  AND
		OVPM."NoDocSum" = (OVPM."DocTotal" - OVPM."VatSum" +OVPM."WtSum") AND
		JDT1."TransType" = 46  AND
		JDT1."IntrnMatch"=0 AND
		JDT1."Closed"=N'N' AND
		(JDT1."SourceLine" Is Null or  JDT1."SourceLine"<> -6);
	
	else
	
		SELECT JDT1.* FROM 
		JDT1 INNER JOIN OVPM ON JDT1."CreatedBy"= OVPM."DocEntry"
		
		WHERE
		JDT1."ShortName" = :card AND
		OVPM."PayNoDoc"=N'Y'  AND
		OVPM."NoDocSumFC" = (OVPM."DocTotalFC" - OVPM."VatSumFC" +OVPM."WtSumFrgn")  AND
		JDT1."TransType" = 46  AND
		JDT1."IntrnMatch"=0 AND
		JDT1."Closed"=N'N' AND
		(JDT1."SourceLine" Is Null or  JDT1."SourceLine"<> -6);
	end IF;
end IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE  TmSp_GetOpenRINs(
in object  int,
in card nvarchar(100),
in frgnCurr nchar)

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
begin

if (:object = 14)
then
	if (:frgnCurr = N'N')
	then
		SELECT  JDT1.* 
		FROM JDT1 INNER JOIN ORIN ON JDT1."CreatedBy"= ORIN."DocEntry" AND JDT1."TransType" = 14
		WHERE NOT EXISTS
			(select distinct("DocEntry") from RIN1 T0
			where T0."DocEntry"=ORIN."DocEntry" AND T0."BaseType" = 13)
		AND JDT1."ShortName" = :card 	AND JDT1."IntrnMatch"=0;
	
	else
	
		SELECT  JDT1.* 
		FROM JDT1 INNER JOIN ORIN ON JDT1."CreatedBy"= ORIN."DocEntry" AND JDT1."TransType" = 14
		WHERE NOT EXISTS
			(select distinct("DocEntry") from RIN1 T0
			where T0."DocEntry"=ORIN."DocEntry" AND T0."BaseType" = 13)
		AND JDT1."ShortName" = :card 	AND JDT1."IntrnMatch"=0
		AND (	(JDT1."FCCredit"<>0 AND JDT1."FCCredit" IS NOT NULL)  OR 
			(JDT1."FCDebit"<>0 AND JDT1."FCDebit" IS NOT NULL));
	end if;


else


	if (:frgnCurr = N'N')
	then
		SELECT  JDT1.* 
		FROM JDT1 INNER JOIN ORPC ON JDT1."CreatedBy"= ORPC."DocEntry" AND JDT1."TransType" = 19
		WHERE NOT EXISTS
			(select distinct("DocEntry") from RPC1 T0
			where T0."DocEntry"=ORPC."DocEntry" AND T0."BaseType" = 18)
		AND JDT1."ShortName" = :card 	AND JDT1."IntrnMatch"=0;
	
	else
	
		SELECT  JDT1.* 
		FROM JDT1 INNER JOIN ORPC ON JDT1."CreatedBy"= ORPC."DocEntry" AND JDT1."TransType" = 19
		WHERE NOT EXISTS
			(select distinct("DocEntry") from RPC1 T0
			where T0."DocEntry"=ORPC."DocEntry" AND T0."BaseType" = 18)
		AND JDT1."ShortName" = :card 	AND JDT1."IntrnMatch"=0
		AND (	(JDT1."FCCredit"<>0 AND JDT1."FCCredit" IS NOT NULL)  OR 
			(JDT1."FCDebit"<>0 AND JDT1."FCDebit" IS NOT NULL));

	end if;

end if;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_GetUsers( IN InputDbName nvarchar(128),
                                IN ProcID INT)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
myHost nvarchar(254);
iVer int;
insertsql nvarchar(2048);
begin

--Parameters validation for security issues
call _TmSp_ValidateSpParam(:InputDbName);

select count(*) into iVer from m_database 
where to_int (substr_before (version, '.')) > 1 
or (to_int (substr_before (version, '.')) = 1 
    and to_int (substr_before (substr_after (version, '.'), '.')) > 0)
or (to_int (substr_before (version, '.')) = 1 
    and to_int (substr_before (substr_after (version, '.'), '.')) = 0 
    and to_int (substr_before (substr_after (substr_after (version, '.'), '.') , '.')) >= 36);
	
if :iVer > 0 then
	create LOCAL TEMPORARY COLUMN table #dbActiveUsers (
		programname nvarchar(128),
		hostname nvarchar(128),
		clientpid int,
		spid int, status nvarchar(30),
		loginame nvarchar(128), 
		dbname nvarchar(128));

-- Get active host name
	select CLIENT_HOST into myHost from m_connections
		where connection_id = current_connection;

	insertsql := 'insert into #dbActiveUsers 
		select ''Process:''|| CLIENT_PID,
			CLIENT_HOST, 
			CLIENT_PID,
			connection_id,
			CONNECTION_STATUS, 
			USER_NAME,
	   		CURRENT_SCHEMA_NAME from  m_connections
	   			WHERE (CONNECTION_STATUS = ''RUNNING'' OR CONNECTION_STATUS = ''IDLE'')';
	exec(:insertsql);	
	if length(:InputDbName) > 0 THEN
	--select * from #dbActiveUsers where dbname = :InputDbName and hostname <> :myHost;
		select distinct programname,hostname,clientpid from #dbActiveUsers where dbname = :InputDbName and ( (hostname = :myHost and clientpid <> :ProcID) or hostname <> :myHost );
	else
		select distinct programname,hostname,clientpid from #dbActiveUsers where hostname <> :myHost;			
	end if;
	drop table #dbActiveUsers;
end if;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_GetWDD(
in producerFrom		nvarchar(156),
in producerTo		nvarchar(156),
in approverFrom		nvarchar(156),
in approverTo		nvarchar(156),
in templateFrom		nvarchar(21),
in templateTo		nvarchar(21),
in dateFrom			nvarchar(10),
in dateTo			nvarchar(10),
in cardFrom			nvarchar(16),
in cardTo			nvarchar(16),
in totalFrom		nvarchar(41),
in totalTo			nvarchar(41),
in statusWait		nchar(2),
in statusApproved		nchar(2),
in statusRejected		nchar(2),
in statusProduced		nchar(2),
in statusCanceled		nchar(2),
in statusApprProduced	nchar(2),
in objectsList			nvarchar(4000),
in numObjects		int,
in docTable			nchar(4),
in absEntry			int
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
qString 	nvarchar(2048);
hadCond  	smallint;
hadObject  	smallint;
hadStatus  	smallint;
ii	  		int;
str1 		nvarchar (2048);
isInventoryTakingObj smallint;
begin
	hadCond := 0;
	hadObject := 0;
	hadStatus := 0;

	if (:docTable<>'OICD' and :docTable<>'OIPD' and :docTable<>'OIOD') then
		isInventoryTakingObj := 0;
	else
		isInventoryTakingObj := 1;
	end if;
		
	qString := 'select T0.*  from ' ||
	'OWDD T0 inner join OUSR T1 on T0."OwnerID" = T1."INTERNAL_K" ' ||
	'inner join WDD1 T2 on T0."WddCode" = T2."WddCode" ' ||
	'inner join OUSR T3 on T2."UserID" = T3."INTERNAL_K" ' ||
	'inner join OWTM T4 on T0."WtmCode" = T4."WtmCode" ' ||
	'inner join ' || :docTable || ' T5 on ';

	if (:docTable='ODRF') then
		qString := :qString || ' T0."DraftType" = N''112'' and T0."DraftEntry" = T5."DocEntry" and T0."IsDraft" = ''Y''';
	elseif (:docTable='OPDF') then
		qString := :qString || ' T0."DraftType" = N''140'' and T0."DraftEntry" = T5."DocEntry" and T0."IsDraft" = ''Y''';
	elseif (:docTable='OICD') then
		qString := :qString || ' T0."DraftType" = N''1470000109'' and T0."DraftEntry" = T5."DocEntry" and T0."IsDraft" = ''Y''';
	elseif (:docTable='OIOD') then
		qString := :qString || ' T0."DraftType" = N''1470000131'' and T0."DraftEntry" = T5."DocEntry" and T0."IsDraft" = ''Y''';
	elseif (:docTable='OIPD') then
		qString := :qString || ' T0."DraftType" = N''1470000136'' and T0."DraftEntry" = T5."DocEntry" and T0."IsDraft" = ''Y''';
	elseif (:docTable='OOAT') then
		if(:objectsList='1250000026') then
			qString := :qString || ' T0."ObjType" = N''1250000026'' and T5."ObjType"= N''1250000025'' and T5."BpType" =N''C'' and  T0."DraftEntry" = T5."AbsID" and T0."IsDraft" = ''N''';
		else
			qString := :qString || ' T0."ObjType" = N''1250000027'' and T5."ObjType"= N''1250000025'' and T5."BpType" =N''S'' and  T0."DraftEntry" = T5."AbsID" and T0."IsDraft" = ''N''';
		end if;
	else
		qString := :qString || ' T0."ObjType" = T5."ObjType" and T0."DocEntry" = T5."DocEntry" and T0."IsDraft" = ''N''';
	end if;

	if (:absEntry>0) then 
		hadCond := 1;

		if (:docTable='ODRF' or :docTable='OPDF' or :isInventoryTakingObj=1) then
			qString := :qString || ' where T0."DraftEntry" = ' || TO_CHAR(:absEntry) || ' and T0."IsDraft" = ';
			qString := :qString || 'N''Y'' ';
		else
			qString := :qString || ' where T0."DocEntry" = ' || TO_CHAR(:absEntry) || ' and T0."IsDraft" = ';
			qString := :qString || 'N''N'' ';
		end if;
	end if;

	--------------------------------------
	/*	CONDITIONS	*/
	--------------------------------------
	-- PRODUCER
	if (LENGTH(ltrim(rtrim(:producerFrom))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || '  where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T1."U_NAME")) >= ' || 'N''' || ltrim(rtrim(:producerFrom)) || '''';
	end if;

	if (LENGTH(ltrim(rtrim(:producerTo))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T1.U_NAME)) <= ' || 'N''' || ltrim(rtrim(:producerTo)) || '''';
	end if;

	-- APPROVER
	if (LENGTH(ltrim(rtrim(:approverFrom))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T3."U_NAME")) >= ' || 'N''' || ltrim(rtrim(:approverFrom)) || '''';
	end if;


	if (LENGTH(ltrim(rtrim(:approverTo))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T3."U_NAME")) <= ' || 'N''' || ltrim(rtrim(:approverTo)) || '''';
	end if;

	-- TEMPLATES
	if (LENGTH(ltrim(rtrim(:templateFrom))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T4."Name")) >= ' || 'N''' || ltrim(rtrim(:templateFrom)) || '''';
	end if;

	if (LENGTH(ltrim(rtrim(:templateTo))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T4."Name")) <= ' || 'N''' || ltrim(rtrim(:templateTo)) || '''';
	end if;

	-- DATES
	if (LENGTH(ltrim(rtrim(:dateFrom))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T0."CreateDate")) >= ' || 'TO_DATE(''' || ltrim(rtrim(:dateFrom)) || ''', ''YYYYMMDD'') ';
	end if;

	if (LENGTH(ltrim(rtrim(:dateTo))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		
		qString := :qString || ' ltrim(rtrim(T0."CreateDate")) <= ' || 'TO_DATE(''' || ltrim(rtrim(:dateTo)) || ''', ''YYYYMMDD'') ';
	end if;

	-- CARD
	if (LENGTH(ltrim(rtrim(:cardFrom))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		if (:docTable='OOAT') then
               		qString := :qString || ' ltrim(rtrim(T5."BpCode")) >= ' || 'N''' || ltrim(rtrim(:cardFrom))|| '''';
		else
               		qString := :qString || ' ltrim(rtrim(T5."CardCode")) >= ' || 'N''' || ltrim(rtrim(:cardFrom))|| '''';
		end if;
	end if;

	if (LENGTH(ltrim(rtrim(:cardTo))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		if (:docTable='OOAT') then
               		qString := :qString || ' ltrim(rtrim(T5."BpCode")) <= ' || 'N''' || ltrim(rtrim(:cardTo))|| '''';
		else
               		qString := :qString || ' ltrim(rtrim(T5."CardCode")) <= ' || 'N''' || ltrim(rtrim(:cardTo))|| '''';
		end if;
	end if;


	-- TOTAL
	if (LENGTH(ltrim(rtrim(:totalFrom))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		if (:docTable<>'OOAT') then
			qString := :qString || ' T5."DocTotal" >= ' || ltrim(rtrim(:totalFrom));
		end if;		
	end if;

	if (LENGTH(ltrim(rtrim(:totalTo))) <> 0) then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;
		if (:docTable<>'OOAT') then
			qString := :qString || ' T5."DocTotal" <= ' || ltrim(rtrim(:totalTo));
		end if;
	end if;
	--------------------------------------
	/*	STATUS	*/
	--------------------------------------
	if (:hadCond<>1) then
		qString := :qString || ' where ';
		hadCond := 1;
	else
		qString := :qString || ' and ';
	end if;

	qString := :qString || ' T0."ProcesStat" IN ( ';

	if ((ltrim(rtrim(:statusWait))) = 'Y') then
		if (:hadStatus<>1) then
			hadStatus := 1;
		else
			qString := :qString || '  ,  ';
		end if;
		
		qString := :qString || 'N''W''';
	end if;

	if ((ltrim(rtrim(:statusApproved))) = 'Y') then
		if (:hadStatus<>1) then
			hadStatus := 1;
		else
			qString := :qString || '  ,  ';
		end if;
		
		qString := :qString || 'N''Y''';
	end if;

	if ((ltrim(rtrim(:statusRejected))) = 'Y') then
		if (:hadStatus<>1) then
			hadStatus := 1;
		else
			qString := :qString || '  ,  ';
		end if;
		
		qString := :qString || 'N''N''';
	end if;

	if ((ltrim(rtrim(:statusProduced))) = 'Y') then
		if (:hadStatus<>1) then
			hadStatus := 1;	
		else
			qString := :qString || '  ,  ';
		end if;
		
		qString := :qString || 'N''P''';	
	end if;

	if ((ltrim(rtrim(:statusCanceled))) = 'Y') then
		if (:hadStatus <> 1) then
			hadStatus := 1;
		else
			qString := :qString || '  ,  ';
		end if;
		
		qString := :qString || 'N''C''';
	end if;

	if ((ltrim(rtrim(:statusApprProduced))) = 'Y') then
		if (:hadStatus<>1) then
			hadStatus := 1;	
		else
			qString := :qString || '  ,  ';
		end if;
		
		qString := :qString || 'N''A''';
	end if;

	qString := :qString || '  )';


	--------------------------------------
	/*	OBJECTS	*/
	--------------------------------------
	if(:numObjects>0 and :docTable<>'OOAT') then
		if (:hadCond<>1) then
			qString := :qString || ' where ';
			hadCond := 1;
		else
			qString := :qString || ' and ';
		end if;

		qString := :qString || 'T5."ObjType" IN (' || :objectsList || ')';
	end if;

	if (:hadCond<>1) then
		qString := :qString || ' where ';
		hadCond := 1;
	else
		qString := :qString || ' and ';
	end if;
	
	str1 := 'select * from OWDD where EXISTS ( ' || :qString ||
			'OWDD."WddCode" = T0."WddCode" ) ' ||
			'order by OWDD."ProcessID", OWDD."WddCode" ';

	EXECUTE IMMEDIATE (:str1);
END;

