				sql2 := CONCAT(sql2, ', ');
				accountLevelStr := CONCAT('OWHS.', accountLevel);
				accountCompanyStr := CONCAT('OACP.', accountCompany);
				sql2 := CONCAT(sql2, 'NULLIF(LCASE(');
