				sql2 := CONCAT(sql2, '), LCASE(');
				sql2 := CONCAT(sql2, accountCompanyStr);
				sql2 := CONCAT(sql2, '))');
				
				/* build condition */
				sql3 := CONCAT(sql3, '((OWHS.');
