				sql3 := CONCAT(sql3, ' != OACP.');
				sql3 := CONCAT(sql3, accountCompany);
				sql3 := CONCAT(sql3, ' OR OACP.');
				sql3 := CONCAT(sql3, accountCompany);
				sql3 := CONCAT(sql3, ' IS NULL');
				sql3 := CONCAT(sql3, ' OR OACP.');
