SELECT "ItemCode","LstEvlPric","LastPurPrc","LastPurCur","EvalSystem","AvgPrice" FROM OITM) AS TVALUE ON TVALUE."ItemCode" = TLASTDATE."ItemCode" LEFT OUTER JOIN (
SELECT "Currency","Rate" AS "lastpurrat" FROM ORTT WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS TRate ON TRate."Currency" = TVALUE."LastPurCur" LEFT OUTER JOIN (
SELECT "ItemCode","Price" AS "PLPrice","Currency" AS "PLCurrency",TRate1."plrat" FROM ITM1 T3 INNER JOIN OPLN T4 ON T4."ListName" = :priceListName AND T3."PriceList" = T4."ListNum" LEFT OUTER JOIN (
SELECT "Currency" AS "plCur","Rate" AS "plrat" FROM ORTT WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS TRate1 ON TRate1."plCur" = T3."Currency") AS TPL ON TPL."ItemCode" = TLASTDATE."ItemCode" LEFT OUTER JOIN (
SELECT TLAST."ItemCode",TLAST."WhsCode",IFNULL(sum("InQty" + "OutQty"),0) AS "volume" FROM OIVL TIVL RIGHT OUTER JOIN (
SELECT T0."ItemCode",T0."WhsCode",IFNULL(T1."CountDate",T0."createDate") AS "lastCountDate",IFNULL(T1."CountTime",0) AS "lastCountTime" FROM OITW T0 LEFT OUTER JOIN (
SELECT TMAXDATE."ItemCode",TMAXDATE."WhsCode",TMAXDATE."CountDate",TMAXTIME."CountTime" FROM ((
SELECT "ItemCode","WhsCode",max("CountDate") AS "CountDate" FROM (
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM INC1 UNION
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM IQR1 WHERE "BaseEntry" IS NULL) AS TBASE GROUP BY "ItemCode","WhsCode") AS TMAXDATE LEFT OUTER JOIN (
SELECT "ItemCode","WhsCode","CountDate",max("CountTime") AS "CountTime" FROM (
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM INC1 UNION
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM IQR1 WHERE "BaseEntry" IS NULL) AS TBASE1 GROUP BY "ItemCode","WhsCode","CountDate") AS TMAXTIME ON TMAXDATE."ItemCode" = TMAXTIME."ItemCode" AND TMAXDATE."WhsCode" = TMAXTIME."WhsCode" AND TMAXDATE."CountDate" = TMAXTIME."CountDate")) AS T1 ON T0."WhsCode" = T1."WhsCode" AND T0."ItemCode" = T1."ItemCode" GROUP BY T0."WhsCode",T0."ItemCode",T0."createDate",T1."CountDate",T1."CountTime") AS TLAST ON TLAST."ItemCode" = TIVL."ItemCode" AND TLAST."WhsCode" = TIVL."LocCode" AND (TIVL."CreateDate" > TLAST."lastCountDate" OR (TIVL."CreateDate" = TLAST."lastCountDate" AND TIVL."CreateTime" > TLAST."lastCountTime")) GROUP BY TLAST."ItemCode",TLAST."WhsCode") AS TVOLUME ON TVOLUME."ItemCode" = TLASTDATE."ItemCode" AND TVOLUME."WhsCode" = TLASTDATE."WhsCode" LEFT OUTER JOIN (
SELECT "ItemCode","LocCode",CASE WHEN sum("OpenQty") = 0 THEN 0 ELSE sum("OpenValue") / sum("OpenQty") END AS "itemcost" FROM OIVQ GROUP BY "ItemCode","LocCode") AS TFIFOCOST ON TLASTDATE."ItemCode" = TFIFOCOST."ItemCode" AND TLASTDATE."WhsCode" = TFIFOCOST."LocCode" WHERE EXISTS (
SELECT * FROM OIVL WHERE "ItemCode" = TLASTDATE."ItemCode" AND "LocCode" = TLASTDATE."WhsCode") AND DAYS_BETWEEN("lastCountDate",NOW()) > :ItemPara1Max AND ("volume" > :ItemPara2Max OR (
SELECT CASE WHEN :priceListName = 'Last Evaluated Price' THEN "LstEvlPric" WHEN :priceListName = 'Last Purchase Price' THEN (CASE WHEN "LastPurCur" = (
SELECT "MainCurncy" FROM OADM) THEN "LastPurPrc" ELSE "lastpurrat" * "LastPurPrc" END) WHEN :priceListName = 'Item Cost' THEN (CASE WHEN ("EvalSystem" = 'F' AND "itemcost" > 0) THEN "itemcost" ELSE (CASE WHEN 'Y' = 'Y' THEN "AvgPriceWH" ELSE "AvgPrice" END) END) ELSE (CASE WHEN "PLCurrency" = (
SELECT "MainCurncy" FROM OADM) THEN "PLPrice" ELSE "plrat" * "PLPrice" END) END AS "lastpurlocal" FROM DUMMY) > :ItemPara3Max) GROUP BY TLASTDATE."WhsCode") AS THIGH RIGHT OUTER JOIN (
SELECT "LocCode",count(DISTINCT "ItemCode") AS "total" FROM OIVL GROUP BY "LocCode") AS TTotalItemVolume ON THIGH."WhsCode1" = TTotalItemVolume."LocCode") AS TLOWRISK WHERE "percentageMedium" <= :WhseParaMax AND "percentageMedium" >= :WhseParaMin ORDER BY "percentageMedium" DESC, "mediumcode";
END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_ICRA_GetWarehouseQty ( IN CountDate NVARCHAR(20)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
ConvertedCountDate DATE;
BEGIN
ConvertedCountDate := TO_DATE(:CountDate, 'MM/DD/YYYY');
SELECT * FROM (SELECT TOP 10 '#' || T0."WhsCode" AS "code", "BinActivat", IFNULL("qtycounted", 0) AS "qtycounted", (IFNULL("qtytotal", 0) - IFNULL("qtycounted", 0)) AS "qtyuncounted", IFNULL("qtycountedbin", 0) AS "qtycountedbin", CASE WHEN "BinActivat" = 'Y' THEN (IFNULL("qtytotalbin", 0) - IFNULL("qtycountedbin", 0) - IFNULL("qtycounted", 0)) ELSE (IFNULL("qtytotalbin", 0) - IFNULL("qtycountedbin", 0)) END AS "qtyuncountedbin", CASE WHEN "BinActivat" = 'Y' THEN IFNULL("qtytotalbin", 0) ELSE IFNULL("qtytotal", 0) END AS "totalQty" FROM (SELECT "WhsCode", "BinActivat" FROM OWHS TOWHS INNER JOIN (SELECT DISTINCT "LocCode" FROM OIVL) AS TOIVL ON TOWHS."WhsCode" = TOIVL."LocCode") AS T0 LEFT OUTER JOIN (SELECT "WhsCode", SUM(T0."OnHand") AS "qtycounted" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" WHERE T0."OnHand" > 0 AND T0."ItemCode" IN (SELECT "ItemCode" FROM (SELECT "ItemCode", "WhsCode", "BinEntry", "CountDate" FROM INC1 UNION SELECT "ItemCode", "WhsCode", "BinEntry", "CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T1 WHERE T0."WhsCode" = T1."WhsCode" AND (T1."BinEntry" IS NULL) AND T1."CountDate" >= :ConvertedCountDate) GROUP BY "WhsCode") AS TCounted ON TCounted."WhsCode" = T0."WhsCode" LEFT OUTER JOIN (SELECT "WhsCode", SUM(T0."OnHand") AS "qtytotal" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" GROUP BY "WhsCode") AS TUncounted ON T0."WhsCode" = TUncounted."WhsCode" LEFT OUTER JOIN (SELECT T1."WhsCode", SUM(T1."OnHandQty") AS "qtycountedbin" FROM OIBQ T1 INNER JOIN OITM T3 ON T3."ItemCode" = T1."ItemCode" WHERE t1."OnHandQty" > 0 AND T1."ItemCode" IN (SELECT "ItemCode" FROM (SELECT "ItemCode", "WhsCode", "BinEntry", "CountDate" FROM INC1 UNION SELECT "ItemCode", "WhsCode", "BinEntry", "CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T2 WHERE T1."WhsCode" = T2."WhsCode" AND T2."BinEntry" = T1."BinAbs" AND T2."CountDate" >= :ConvertedCountDate) AND T1."ItemCode" NOT IN (SELECT "ItemCode" FROM (SELECT "ItemCode", "WhsCode", "BinEntry", "CountDate" FROM INC1 UNION SELECT "ItemCode", "WhsCode", "BinEntry", "CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T3 WHERE T3."WhsCode" = T1."WhsCode" AND (T3."BinEntry" IS NULL) AND T3."CountDate" >= :ConvertedCountDate) GROUP BY T1."WhsCode") AS T4 ON T0."WhsCode" = T4."WhsCode" LEFT OUTER JOIN (SELECT T5."WhsCode", SUM(T5."OnHandQty") AS "qtytotalbin" FROM OIBQ T5 INNER JOIN OITM T3 ON T3."ItemCode" = T5."ItemCode" GROUP BY T5."WhsCode") AS T7 ON T0."WhsCode" = T7."WhsCode" ORDER BY "totalQty" DESC) T ORDER BY T."code";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_ICRA_GetWarehouseRiskForPie ( IN priceListName char(32),
	 IN norate nvarchar(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
localCurrency nvarChar(3);
IsPricePerWH nvarchar(1);
ItemPara1Min DECIMAL(21,6);
ItemPara1Max DECIMAL(21,6);
ItemPara2Min DECIMAL(21,6);
ItemPara2Max DECIMAL(21,6);
ItemPara3Min DECIMAL(21,6);
ItemPara3Max DECIMAL(21,6);
WhseParaMin DECIMAL(21,6);
WhseParaMax DECIMAL(21,6);
BEGIN
select "KpiValue1" into ItemPara1Min from KPS1 where "KpsCode"='ICR' and "LineNum" = 1;
select "KpiValue2" into ItemPara1Max from KPS1 where "KpsCode"='ICR' and "LineNum" = 1;
select "KpiValue1" into ItemPara2Min from KPS1 where "KpsCode"='ICR' and "LineNum" = 2;
select "KpiValue2" into ItemPara2Max from KPS1 where "KpsCode"='ICR' and "LineNum" = 2;
select "KpiValue1" into ItemPara3Min from KPS1 where "KpsCode"='ICR' and "LineNum" = 3;
select "KpiValue2" into ItemPara3Max from KPS1 where "KpsCode"='ICR' and "LineNum" = 3;
select "KpiValue1"/100 into WhseParaMin from KPS1 where "KpsCode"='ICR2' and "LineNum" = 1;
select "KpiValue2"/100 into WhseParaMax from KPS1 where "KpsCode"='ICR2' and "LineNum" = 1;
IF :ItemPara1Min IS NULL OR :ItemPara1Max IS NULL OR :ItemPara1Min IS NULL OR :ItemPara2Min IS NULL OR :ItemPara2Max IS NULL OR :ItemPara3Min IS NULL OR :ItemPara3Max IS NULL OR :WhseParaMin IS NULL OR :WhseParaMax IS NULL OR :norate <> '0' THEN
	Select 0, 0, 0 from dummy;
ELSEIf :norate = '0' then
SELECT sum(CASE WHEN "percentage" > :WhseParaMax THEN 1 ELSE 0 END) AS "high",sum(CASE WHEN ("percentage" <= :WhseParaMax AND "percentage" >= :WhseParaMin) THEN 1 ELSE 0 END) AS "medium",sum(CASE WHEN "percentage" < :WhseParaMin THEN 1 ELSE 0 END) AS "low" FROM (
SELECT CASE WHEN "total" = 0 THEN 0 ELSE IFNULL(round(TO_DECIMAL("highitemvolume",19,6) / "total",2),0) END AS "percentage" FROM (
SELECT TLASTDATE."WhsCode" AS "WhsCode1",count(TLASTDATE."ItemCode") AS "highitemvolume" FROM (
SELECT T0."ItemCode",T0."WhsCode",T0."StockValue","AvgPrice" AS "AvgPriceWH",IFNULL(max(T1."CountDate"),T0."createDate") AS "lastCountDate" FROM OITW T0 LEFT OUTER JOIN (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T1 ON T0."WhsCode" = T1."WhsCode" AND T0."ItemCode" = T1."ItemCode" GROUP BY T0."WhsCode",T0."ItemCode",T0."AvgPrice",T0."createDate",T0."OnHand",T0."StockValue") AS TLASTDATE INNER JOIN (
SELECT "ItemCode","LstEvlPric","LastPurPrc","LastPurCur","EvalSystem","AvgPrice" FROM OITM) AS TVALUE ON TVALUE."ItemCode" = TLASTDATE."ItemCode" LEFT OUTER JOIN (
SELECT "Currency","Rate" AS "lastpurrat" FROM "ORTT" WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS TRate ON TRate."Currency" = TVALUE."LastPurCur" LEFT OUTER JOIN (
SELECT "ItemCode","Price" AS "PLPrice","Currency" AS "PLCurrency",TRate1."plrat" FROM ITM1 T3 INNER JOIN OPLN T4 ON T4."ListName" = :priceListName AND T3."PriceList" = T4."ListNum" LEFT OUTER JOIN (
SELECT "Currency" AS "plCur","Rate" AS "plrat" FROM "ORTT" WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS TRate1 ON TRate1."plCur" = T3."Currency") AS TPL ON TPL."ItemCode" = TLASTDATE."ItemCode" LEFT OUTER JOIN (
SELECT TLAST."ItemCode",TLAST."WhsCode",IFNULL(sum("InQty" + "OutQty"),0) AS "volume" FROM OIVL TIVL RIGHT OUTER JOIN (
SELECT T0."ItemCode",T0."WhsCode",IFNULL(T1."CountDate",T0."createDate") AS "lastCountDate",IFNULL(T1."CountTime",0) AS "lastCountTime" FROM OITW T0 LEFT OUTER JOIN (
SELECT TMAXDATE."ItemCode",TMAXDATE."WhsCode",TMAXDATE."CountDate",TMAXTIME."CountTime" FROM ((
SELECT "ItemCode","WhsCode",max("CountDate") AS "CountDate" FROM (
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM INC1 UNION
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM IQR1 WHERE "BaseEntry" IS NULL) AS TBASE GROUP BY "ItemCode","WhsCode") AS TMAXDATE LEFT OUTER JOIN (
SELECT "ItemCode","WhsCode","CountDate",max("CountTime") AS "CountTime" FROM (
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM INC1 UNION
SELECT "ItemCode","WhsCode","CountDate","CountTime" FROM IQR1 WHERE "BaseEntry" IS NULL) AS TBASE1 GROUP BY "ItemCode","WhsCode","CountDate") AS TMAXTIME ON TMAXDATE."ItemCode" = TMAXTIME."ItemCode" AND TMAXDATE."WhsCode" = TMAXTIME."WhsCode" AND TMAXDATE."CountDate" = TMAXTIME."CountDate")) AS T1 ON T0."WhsCode" = T1."WhsCode" AND T0."ItemCode" = T1."ItemCode" GROUP BY T0."WhsCode",T0."ItemCode",T0."createDate",T1."CountDate",T1."CountTime") AS TLAST ON TLAST."ItemCode" = TIVL."ItemCode" AND TLAST."WhsCode" = TIVL."LocCode" AND (TIVL."CreateDate" > TLAST."lastCountDate" OR (TIVL."CreateDate" = TLAST."lastCountDate" AND TIVL."CreateTime" > TLAST."lastCountTime")) GROUP BY TLAST."ItemCode",TLAST."WhsCode") AS TVOLUME ON TVOLUME."ItemCode" = TLASTDATE."ItemCode" AND TVOLUME."WhsCode" = TLASTDATE."WhsCode" LEFT OUTER JOIN (
SELECT "ItemCode","LocCode",CASE WHEN sum("OpenQty") = 0 THEN 0 ELSE sum("OpenValue") / sum("OpenQty") END AS "itemcost" FROM OIVQ GROUP BY "ItemCode","LocCode") AS TFIFOCOST ON TLASTDATE."ItemCode" = TFIFOCOST."ItemCode" AND TLASTDATE."WhsCode" = TFIFOCOST."LocCode" WHERE EXISTS (
SELECT * FROM OIVL WHERE "ItemCode" = TLASTDATE."ItemCode" AND "LocCode" = TLASTDATE."WhsCode") AND DAYS_BETWEEN("lastCountDate",NOW()) > :ItemPara1Max AND ("volume" > :ItemPara2Max OR (
SELECT CASE WHEN :priceListName = 'Last Evaluated Price' THEN "LstEvlPric" WHEN :priceListName = 'Last Purchase Price' THEN (CASE WHEN "LastPurCur" = (
SELECT "MainCurncy" FROM OADM) THEN "LastPurPrc" ELSE "lastpurrat" * "LastPurPrc" END) WHEN :priceListName = 'Item Cost' THEN (CASE WHEN ("EvalSystem" = 'F' AND "itemcost" > 0) THEN "itemcost" ELSE (CASE WHEN 'Y' = 'Y' THEN "AvgPriceWH" ELSE "AvgPrice" END) END) ELSE (CASE WHEN "PLCurrency" = (
SELECT "MainCurncy" FROM OADM) THEN "PLPrice" ELSE "plrat" * "PLPrice" END) END AS "lastpurlocal" FROM DUMMY) > :ItemPara3Max) GROUP BY TLASTDATE."WhsCode") AS THIGH RIGHT OUTER JOIN (
SELECT "LocCode",count(DISTINCT "ItemCode") AS "total" FROM OIVL GROUP BY "LocCode") AS TTotalItemVolume ON THIGH."WhsCode1" = TTotalItemVolume."LocCode") AS TPERCENT;
END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_ICRA_GetWarehouseValue ( 
IN CountDate NVARCHAR(20),
IN PriceListName char(32),
IN NoRate nvarchar(1)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
LocalCurrency nvarChar(3);
IsPricePerWH nvarchar(1);
ConvertedCountDate DATE;
BEGIN
SELECT "MainCurncy" INTO LocalCurrency FROM OADM;
SELECT "PriceSys" INTO IsPricePerWH FROM OADM;
ConvertedCountDate := TO_DATE(:CountDate,'MM/DD/YYYY');
If :PriceListName='Last Evaluated Price' then
SELECT * FROM (
SELECT TOP 10 '#' || T0."WhsCode" AS "code", "BinActivat", IFNULL ("valuecounted", 0) AS "valuecounted", (IFNULL("valuetotal", 0) - IFNULL("valuecounted", 0)) AS "valueuncounted", IFNULL("valuecountedbin", 0) AS "valuecountedbin", CASE WHEN "BinActivat" = 'Y' THEN (IFNULL("valuetotalbin", 0) - IFNULL("valuecountedbin", 0) - IFNULL("valuecounted", 0)) ELSE (IFNULL("valuetotalbin", 0) - IFNULL("valuecountedbin", 0)) END AS "valueuncountedbin", CASE WHEN "BinActivat" = 'Y' THEN IFNULL("valuetotalbin", 0) ELSE IFNULL("valuetotal", 0) END AS "value" FROM (
SELECT "WhsCode","BinActivat" FROM OWHS TOWHS INNER JOIN (
SELECT DISTINCT "LocCode" FROM OIVL) AS TOIVL ON TOWHS."WhsCode" = TOIVL."LocCode") AS T0 LEFT OUTER JOIN (
SELECT "WhsCode",sum(T0."OnHand" * T3."LstEvlPric") AS "valuecounted" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" WHERE T0."OnHand" > 0 AND T0."ItemCode" IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T1 WHERE T0."WhsCode" = T1."WhsCode" AND (T1."BinEntry" IS NULL) AND T1."CountDate" >= :ConvertedCountDate) GROUP BY "WhsCode") AS TCounted ON TCounted."WhsCode" = T0."WhsCode" LEFT OUTER JOIN (
SELECT "WhsCode",sum(T0."OnHand" * T3."LstEvlPric") AS "valuetotal" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" GROUP BY "WhsCode") AS TTotal ON T0."WhsCode" = TTotal."WhsCode" LEFT OUTER JOIN (
SELECT T1."WhsCode",sum(T1."OnHandQty" * T3."LstEvlPric") AS "valuecountedbin" FROM OIBQ T1 INNER JOIN OITM T3 ON T3."ItemCode" = T1."ItemCode" WHERE t1."OnHandQty" > 0 AND T1."ItemCode" IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T2 WHERE T1."WhsCode" = T2."WhsCode" AND T2."BinEntry" = T1."BinAbs" AND T2."CountDate" >= :ConvertedCountDate) AND T1."ItemCode" NOT IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T3 WHERE T3."WhsCode" = T1."WhsCode" AND (T3."BinEntry" IS NULL) AND T3."CountDate" >= :ConvertedCountDate) GROUP BY T1."WhsCode") AS T4 ON T0."WhsCode" = T4."WhsCode" LEFT OUTER JOIN (
SELECT T5."WhsCode",sum(T5."OnHandQty" * T3."LstEvlPric") AS "valuetotalbin" FROM OIBQ T5 INNER JOIN OITM T3 ON T3."ItemCode" = T5."ItemCode" GROUP BY T5."WhsCode") AS T7 ON T0."WhsCode" = T7."WhsCode" ORDER BY "value" DESC) T ORDER BY T."code";
elseif :PriceListName='Last Purchase Price' then 
if :NoRate='0' then 
SELECT * FROM (
SELECT TOP 10 '#' || TLOCAL."WhsCode" AS "code", TLOCAL."BinActivat", ("valueCountedLocal" + "valueCountedForeign") AS "valuecounted", ("valueTotalLocal" + "valueTotalForeign" - "valueCountedLocal" - "valueCountedForeign") AS "valueUncounted", ("valueCountedLocalbin" + "valueCountedForeignbin") AS "valuecountedbin", CASE WHEN "BinActivat" = 'Y' THEN ("valueTotalLocalbin" + "valueTotalForeignbin" - "valueCountedLocalbin" - "valueCountedForeignbin" - "valueCountedLocal" - "valueCountedForeign") ELSE ("valueTotalLocalbin" + "valueTotalForeignbin" - "valueCountedLocalbin" - "valueCountedForeignbin") END AS "valueuncountedbin", CASE WHEN "BinActivat" = 'Y' THEN ("valueTotalLocalbin" + "valueTotalForeignbin") ELSE ("valueTotalLocal" + "valueTotalForeign") END AS "value" FROM (
SELECT T0."WhsCode","BinActivat",IFNULL("valueCountedLocal",0) AS "valueCountedLocal",IFNULL("valueTotalLocal",0) AS "valueTotalLocal",IFNULL("valueCountedLocalbin",0) AS "valueCountedLocalbin",IFNULL("valueTotalLocalbin",0) AS "valueTotalLocalbin" FROM (
SELECT "WhsCode","BinActivat" FROM OWHS TOWHS INNER JOIN (
SELECT DISTINCT "LocCode" FROM OIVL) AS TOIVL ON TOWHS."WhsCode" = TOIVL."LocCode") AS T0 LEFT OUTER JOIN (
SELECT "WhsCode",sum(T0."OnHand" * T3."LastPurPrc") AS "valueCountedLocal" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" AND T3."LastPurCur" = :LocalCurrency WHERE T0."OnHand" > 0 AND T0."ItemCode" IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T1 WHERE T0."WhsCode" = T1."WhsCode" AND (T1."BinEntry" IS NULL) AND T1."CountDate" >= :ConvertedCountDate) GROUP BY "WhsCode") AS T2 ON T0."WhsCode" = T2."WhsCode" LEFT OUTER JOIN (
SELECT "WhsCode",sum(T0."OnHand" * T3."LastPurPrc") AS "valueTotalLocal" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" AND T3."LastPurCur" = :LocalCurrency GROUP BY "WhsCode") AS T1 ON T0."WhsCode" = T1."WhsCode" LEFT OUTER JOIN (
SELECT T1."WhsCode",sum(T1."OnHandQty" * T3."LastPurPrc") AS "valueCountedLocalbin" FROM OIBQ T1 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T1."ItemCode" AND T3."LastPurCur" = :LocalCurrency WHERE t1."OnHandQty" > 0 AND T1."ItemCode" IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T2 WHERE T1."WhsCode" = T2."WhsCode" AND T2."BinEntry" = T1."BinAbs" AND T2."CountDate" >= :ConvertedCountDate) AND T1."ItemCode" NOT IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T3 WHERE T3."WhsCode" = T1."WhsCode" AND (T3."BinEntry" IS NULL) AND T3."CountDate" >= :ConvertedCountDate) GROUP BY T1."WhsCode") AS T4 ON T0."WhsCode" = T4."WhsCode" LEFT OUTER JOIN (
SELECT T5."WhsCode",sum(T5."OnHandQty" * T3."LastPurPrc") AS "valueTotalLocalbin" FROM OIBQ T5 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T5."ItemCode" AND T3."LastPurCur" = :LocalCurrency GROUP BY T5."WhsCode") AS T7 ON T0."WhsCode" = T7."WhsCode") AS TLOCAL INNER JOIN (
SELECT T0."WhsCode",IFNULL("valueCountedForeign",0) AS "valueCountedForeign",IFNULL("valueTotalForeign",0) AS "valueTotalForeign",IFNULL("valueCountedForeignbin",0) AS "valueCountedForeignbin",IFNULL("valueTotalForeignbin",0) AS "valueTotalForeignbin" FROM (
SELECT "WhsCode","BinActivat" FROM OWHS TOWHS INNER JOIN (
SELECT DISTINCT "LocCode" FROM OIVL) AS TOIVL ON TOWHS."WhsCode" = TOIVL."LocCode") AS T0 LEFT OUTER JOIN (
SELECT "WhsCode",sum(T0."OnHand" * T3."LastPurPrc" * T5."Rate") AS "valueCountedForeign" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" AND T3."LastPurCur" <> :LocalCurrency INNER JOIN (
SELECT "Currency","Rate" FROM ORTT WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS T5 ON T5."Currency" = T3."LastPurCur" WHERE T0."OnHand" > 0 AND T0."ItemCode" IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T1 WHERE T0."WhsCode" = T1."WhsCode" AND (T1."BinEntry" IS NULL) AND T1."CountDate" >= :ConvertedCountDate) GROUP BY "WhsCode") AS T2 ON T0."WhsCode" = T2."WhsCode" LEFT OUTER JOIN (
SELECT "WhsCode",sum(T0."OnHand" * T3."LastPurPrc" * T5."Rate") AS "valueTotalForeign" FROM OITW T0 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T0."ItemCode" AND T3."LastPurCur" <> :LocalCurrency INNER JOIN (
SELECT "Currency","Rate" FROM ORTT WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS T5 ON T5."Currency" = T3."LastPurCur" GROUP BY "WhsCode") AS T1 ON T0."WhsCode" = T1."WhsCode" LEFT OUTER JOIN (
SELECT T1."WhsCode",sum(T1."OnHandQty" * T3."LastPurPrc" * T5."Rate") AS "valueCountedForeignbin" FROM OIBQ T1 LEFT OUTER JOIN OITM T3 ON T3."ItemCode" = T1."ItemCode" AND T3."LastPurCur" <> :LocalCurrency INNER JOIN (
SELECT "Currency","Rate" FROM ORTT WHERE "RateDate" = cast(cast(NOW() AS VARCHAR) AS TIMESTAMP)) AS T5 ON T5."Currency" = T3."LastPurCur" WHERE t1."OnHandQty" > 0 AND T1."ItemCode" IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T2 WHERE T1."WhsCode" = T2."WhsCode" AND T2."BinEntry" = T1."BinAbs" AND T2."CountDate" >= :ConvertedCountDate) AND T1."ItemCode" NOT IN (
SELECT "ItemCode" FROM (
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM INC1 UNION
SELECT "ItemCode","WhsCode","BinEntry","CountDate" FROM IQR1 WHERE "BaseEntry" IS NULL) AS T3 WHERE T3."WhsCode" = T1."WhsCode" AND (T3."BinEntry" IS NULL) AND T3."CountDate" >= :ConvertedCountDate) GROUP BY T1."WhsCode") AS T4 ON T0."WhsCode" = T4."WhsCode" LEFT OUTER JOIN (
SELECT T1."WhsCode",sum(T1."OnHandQty" * T3."LastPurPrc" * T5."Rate") AS "valueTotalForeignbin" FROM OIBQ T1 INNER JOIN OITM T3 ON T3."ItemCode" = T1."ItemCode" AND T3."LastPurCur" <> :LocalCurrency INNER JOIN (
