CREATE PROCEDURE TmSp_InventoryCountingRiskAssessmentReport ( 
IN priceListName char(32), 
IN riskcode nvarchar(1),
IN ItemPara1Min nvarChar(32),
IN ItemPara1Max nvarChar(32),
IN ItemPara2Min nvarChar(32),
IN ItemPara2Max nvarChar(32),
IN ItemPara3Min nvarChar(32),
IN ItemPara3Max nvarChar(32),
IN WhsParaMin nvarChar(32),
IN WhsParaMax nvarChar(32))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	LocalCurrency nvarChar(3);
	IsPricePerWH nvarchar(1);
	High nvarchar(1);
	Medium nvarchar(1);
	Low nvarchar(1);
	DaysMin DECIMAL(21,6);
	DaysMax DECIMAL(21,6);
	VolumeMin DECIMAL(21,6);
	VolumeMax DECIMAL(21,6);
	ValueMin DECIMAL(21,6);
	ValueMax DECIMAL(21,6);
	HRiskPercentMin DECIMAL(21,6);
	HRiskPercentMax DECIMAL(21,6);
BEGIN
	SELECT "MainCurncy" into LocalCurrency FROM OADM;
	SELECT "PriceSys" into IsPricePerWH FROM OADM;

	-- Create temporary table to store data to
	CREATE LOCAL TEMPORARY 
	TABLE "#tblRiskTempData" ("ItemCode" nvarChar(50), 
		"ItemName" nvarChar(200),
		"WhsCode"	nvarChar(8),
		"DaysSinceLastCount" INT,
		"Risk1" nvarChar(10),
		"TransVolume" DECIMAL(21,6),
		"Risk2" nvarChar(10),
		"ValueOfItem" DECIMAL(21,6),
		"Risk3" nvarChar(10),
		"CalcRisk" nvarChar(10));
	
	delete from "#tblRiskTempData" where 1 = 1;
		
	High := 'H';
	Medium := 'M';
	Low := 'L';
	DaysMin := CAST(:ItemPara1Min AS DECIMAL(21,6));
	DaysMax := CAST(:ItemPara1Max AS DECIMAL(21,6));
	VolumeMin := CAST(:ItemPara2Min AS DECIMAL(21,6));
	VolumeMax := CAST(:ItemPara2Max AS DECIMAL(21,6));
	ValueMin := CAST(:ItemPara3Min AS DECIMAL(21,6));
	ValueMax := CAST(:ItemPara3Max AS DECIMAL(21,6));
	HRiskPercentMin := CAST(:WhsParaMin AS DECIMAL(21,6));
	HRiskPercentMax := CAST(:WhsParaMax AS DECIMAL(21,6));
	
	IF :priceListName = 'Last Evaluated Price' OR :priceListName = 'Last Purchase Price' OR :priceListName = 'Item Cost' THEN
	insert into "#tblRiskTempData"--("ItemCode", "ItemName", "WhsCode", "DaysSinceLastCount", "TransVolume", "ValueOfItem")
		SELECT TMIDDLE."ItemCode", TMIDDLE."ItemName", TMIDDLE."WhsCode", TMIDDLE."DaysSinceLastCount",
			(CASE WHEN TMIDDLE."DaysSinceLastCount" > :DaysMax  THEN  :High 
							WHEN TMIDDLE."DaysSinceLastCount" < :DaysMin THEN :Low 
							ELSE :Medium END) AS "Risk1",
			TMIDDLE."TransVolume",
			(CASE WHEN TMIDDLE."TransVolume" >  :VolumeMax  THEN :High 
							 WHEN TMIDDLE."TransVolume" < :VolumeMin  THEN :Low 
							 ELSE :Medium  END) AS "Risk2",
			TMIDDLE."ValueOfItem",
			(CASE WHEN TMIDDLE."ValueOfItem" > :ValueMax  THEN :High 
							WHEN TMIDDLE."ValueOfItem" < :ValueMin THEN :Low 
							ELSE :Medium END) AS "Risk3",
			(CASE  WHEN (TMIDDLE."DaysSinceLastCount" > :DaysMax ) AND ((TMIDDLE."TransVolume" >  :VolumeMax ) OR (TMIDDLE."ValueOfItem" > :ValueMax)) THEN :High 
				 WHEN TMIDDLE."DaysSinceLastCount" < :DaysMin  AND TMIDDLE."TransVolume" < :VolumeMin  AND TMIDDLE."ValueOfItem" < :ValueMin  THEN :Low 
				 ELSE :Medium END) As "CalcRisk" 
		FROM		
		(SELECT T2."ItemCode", T3."ItemName", T2."WhsCode", 
			IFNULL(DAYS_BETWEEN("LastDate", Now()),0) AS "DaysSinceLastCount",
			IFNULL((select sum("InQty" + "OutQty") from OIVL T4 WHERE T4."LocCode" = T2."WhsCode" AND T4."ItemCode" = T2."ItemCode" 
				AND (T4."CreateDate" > T2."LastDate" OR (T4."CreateDate" = T2."LastDate" AND T4."CreateTime" > T2."LastTime"))), 0) AS "TransVolume",
			(CASE WHEN :priceListName = 'Last Evaluated Price' THEN T3."LstEvlPric"
				WHEN :priceListName = 'Last Purchase Price' THEN
					(CASE WHEN "LastPurCur" = :LocalCurrency THEN "LastPurPrc" 
						ELSE "LastPurPrc" * (
							IFNULL(
								CASE WHEN DAYS_BETWEEN(ORTT."RateDate",Now()) = 0 THEN ORTT."Rate"
									ELSE NULL END, 0)) 
					END)
				WHEN :priceListName = 'Item Cost' THEN
					(CASE WHEN "EvalSystem" = 'F' AND 
							( CASE WHEN (SELECT sum(T5."OpenQty") FROM OIVQ T5 WHERE T2."WhsCode" = T5."LocCode" AND T2."ItemCode" = T5."ItemCode") = 0 THEN 0
									ELSE (SELECT sum(T6."OpenValue")/sum(T6."OpenQty") FROM OIVQ T6 WHERE T2."WhsCode" = T6."LocCode" AND T2."ItemCode" = T6."ItemCode")	END) > 0
								THEN (SELECT sum(T7."OpenValue")/sum(T7."OpenQty") FROM OIVQ T7 WHERE T2."WhsCode" = T7."LocCode" AND T2."ItemCode" = T7."ItemCode")											
						ELSE (CASE WHEN :IsPricePerWH ='Y' THEN T2."AvgPrice"
								ELSE T3."AvgPrice" END) END)
				END) AS "ValueOfItem" 						
		FROM
			(SELECT T1."ItemCode", T1."WhsCode", T1."AvgPrice",
			 CASE WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") < 0 THEN T1."LastCountDate"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") > 0  THEN T1."LastPostDate"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") IS NULL THEN 
					IFNULL(IFNULL("LastCountDate", "LastPostDate"), T1."CreateDate") END AS "LastDate",
			CASE WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") < 0 THEN T1."LastCountTime"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") > 0  THEN T1."LastPostTime"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") IS NULL THEN 
					IFNULL(IFNULL("LastCountTime", "LastPostTime"), 0) END AS "LastTime"
			FROM (SELECT T0."ItemCode" AS "ItemCode", T0."WhsCode" AS "WhsCode", T0."createDate" AS "CreateDate", T0."AvgPrice" AS "AvgPrice",
					(SELECT MAX("CountDate") FROM INC1 WHERE INC1."WhsCode" = T0."WhsCode" AND INC1."ItemCode" = T0."ItemCode") AS "LastCountDate",
					(SELECT MAX("CountTime") FROM INC1 WHERE INC1."WhsCode" = T0."WhsCode" AND INC1."ItemCode" = T0."ItemCode" 
						AND INC1."CountDate" = (SELECT MAX("CountDate") FROM INC1 WHERE INC1."WhsCode" = T0."WhsCode" AND INC1."ItemCode" = T0."ItemCode")) AS "LastCountTime",
					(SELECT MAX("CountDate") FROM IQR1 WHERE IQR1."WhsCode" = T0."WhsCode" AND IQR1."ItemCode" = T0."ItemCode") AS "LastPostDate",
					(SELECT MAX("CountTime") FROM IQR1 WHERE IQR1."WhsCode" = T0."WhsCode" AND IQR1."ItemCode" = T0."ItemCode" 
						AND IQR1."CountDate" = (SELECT MAX("CountDate") FROM IQR1 WHERE IQR1."WhsCode" = T0."WhsCode" AND IQR1."ItemCode" = T0."ItemCode")) AS "LastPostTime"
				FROM OITW T0) T1) AS T2 
			INNER JOIN OITM T3 ON T2."ItemCode" = T3."ItemCode"
			LEFT JOIN ORTT ON T3."LastPurCur" = ORTT."Currency"
			WHERE EXISTS(SELECT "ItemCode" FROM OIVL WHERE OIVL."ItemCode"=T2."ItemCode" AND OIVL."LocCode"=T2."WhsCode")) AS TMIDDLE;
	ELSE
		insert into "#tblRiskTempData"--("ItemCode", "ItemName", "WhsCode", "DaysSinceLastCount", "TransVolume", "ValueOfItem")
		SELECT TMIDDLE."ItemCode", TMIDDLE."ItemName", TMIDDLE."WhsCode", TMIDDLE."DaysSinceLastCount",
			(CASE WHEN TMIDDLE."DaysSinceLastCount" > :DaysMax  THEN  :High 
							WHEN TMIDDLE."DaysSinceLastCount" < :DaysMin THEN :Low 
							ELSE :Medium END) AS "Risk1",
			TMIDDLE."TransVolume",
			(CASE WHEN TMIDDLE."TransVolume" >  :VolumeMax  THEN :High 
							 WHEN TMIDDLE."TransVolume" < :VolumeMin  THEN :Low 
							 ELSE :Medium  END) AS "Risk2",
			TMIDDLE."ValueOfItem",
			(CASE WHEN TMIDDLE."ValueOfItem" > :ValueMax  THEN :High 
							WHEN TMIDDLE."ValueOfItem" < :ValueMin THEN :Low 
							ELSE :Medium END) AS "Risk3",
			(CASE  WHEN (TMIDDLE."DaysSinceLastCount" > :DaysMax ) AND ((TMIDDLE."TransVolume" > :VolumeMax ) OR (TMIDDLE."ValueOfItem" > :ValueMax)) THEN :High 
				 WHEN TMIDDLE."DaysSinceLastCount" < :DaysMin  AND TMIDDLE."TransVolume" < :VolumeMin  AND TMIDDLE."ValueOfItem" < :ValueMin  THEN :Low 
				 ELSE :Medium END) As "CalcRisk" 
		FROM		
		(SELECT T2."ItemCode", T3."ItemName", T2."WhsCode", 
			IFNULL(DAYS_BETWEEN("LastDate", Now()),0) AS "DaysSinceLastCount",
			IFNULL((select sum("InQty" + "OutQty") from OIVL T4 WHERE T4."LocCode" = T2."WhsCode" AND T4."ItemCode" = T2."ItemCode" 
				AND (T4."CreateDate" > T2."LastDate" OR (T4."CreateDate" = T2."LastDate" AND T4."CreateTime" > T2."LastTime"))), 0) AS "TransVolume",
			(CASE WHEN ITM1."Currency" = :LocalCurrency THEN IFNULL(ITM1."Price", 0) 
				ELSE ITM1."Price" * (
						IFNULL(
							CASE WHEN DAYS_BETWEEN(T4."RateDate", Now()) = 0 THEN T4."Rate"
						ELSE NULL END, 0)) END) AS "ValueOfItem" 						
		FROM
			(SELECT T1."ItemCode", T1."WhsCode", T1."AvgPrice",
			 CASE WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") < 0 THEN T1."LastCountDate"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") > 0  THEN T1."LastPostDate"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") IS NULL THEN 
					IFNULL(IFNULL("LastCountDate", "LastPostDate"), T1."CreateDate") END AS "LastDate",
			CASE WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") < 0 THEN T1."LastCountTime"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") > 0  THEN T1."LastPostTime"
				WHEN DAYS_BETWEEN(T1."LastCountDate", T1."LastPostDate") IS NULL THEN 
					IFNULL(IFNULL("LastCountTime", "LastPostTime"), 0) END AS "LastTime"
			FROM (SELECT T0."ItemCode" AS "ItemCode", T0."WhsCode" AS "WhsCode", T0."createDate" AS "CreateDate", T0."AvgPrice" AS "AvgPrice",
					(SELECT MAX("CountDate") FROM INC1 WHERE INC1."WhsCode" = T0."WhsCode" AND INC1."ItemCode" = T0."ItemCode") AS "LastCountDate",
					(SELECT MAX("CountTime") FROM INC1 WHERE INC1."WhsCode" = T0."WhsCode" AND INC1."ItemCode" = T0."ItemCode" 
						AND INC1."CountDate" = (SELECT MAX("CountDate") FROM INC1 WHERE INC1."WhsCode" = T0."WhsCode" AND INC1."ItemCode" = T0."ItemCode")) AS "LastCountTime",
					(SELECT MAX("CountDate") FROM IQR1 WHERE IQR1."WhsCode" = T0."WhsCode" AND IQR1."ItemCode" = T0."ItemCode") AS "LastPostDate",
					(SELECT MAX("CountTime") FROM IQR1 WHERE IQR1."WhsCode" = T0."WhsCode" AND IQR1."ItemCode" = T0."ItemCode" 
						AND IQR1."CountDate" = (SELECT MAX("CountDate") FROM IQR1 WHERE IQR1."WhsCode" = T0."WhsCode" AND IQR1."ItemCode" = T0."ItemCode")) AS "LastPostTime"
				FROM OITW T0) T1) AS T2 
			INNER JOIN OITM T3 ON T2."ItemCode" = T3."ItemCode"
			INNER JOIN ITM1 ON T3."ItemCode" = ITM1."ItemCode" 
			INNER JOIN OPLN ON ITM1."PriceList" = OPLN."ListNum" AND OPLN."ListName" = :priceListName 
			LEFT JOIN ORTT T4 ON T4."Currency" = ITM1."Currency"
			WHERE EXISTS(SELECT "ItemCode" FROM OIVL WHERE OIVL."ItemCode"=T2."ItemCode" AND OIVL."LocCode"=T2."WhsCode")) AS TMIDDLE;
	END IF;
	
					
	IF :riskcode = :High THEN
		SELECT "#tblRiskTempData"."ItemCode", "#tblRiskTempData"."ItemName",
		 	"#tblRiskTempData"."WhsCode", "#tblRiskTempData"."DaysSinceLastCount","#tblRiskTempData"."Risk1",
		 	"#tblRiskTempData"."TransVolume", "#tblRiskTempData"."Risk2", "#tblRiskTempData"."ValueOfItem",
		 	"#tblRiskTempData"."Risk3", "#tblRiskTempData"."CalcRisk", "OBPL"."BPLName", "OBPL"."BPLId" FROM "#tblRiskTempData"
		 	INNER JOIN "OWHS" ON "#tblRiskTempData"."WhsCode" = "OWHS"."WhsCode"
			LEFT JOIN "OBPL" ON "OWHS"."BPLid" = "OBPL"."BPLId"
			WHERE "#tblRiskTempData"."WhsCode" IN(
				SELECT T0."WhsCode"  AS "WhsCode" FROM (
					(SELECT "WhsCode", count("ItemCode") AS TOTAL FROM "#tblRiskTempData" GROUP BY "WhsCode") T0
					LEFT JOIN			
					(SELECT "WhsCode", "CalcRisk", IFNULL(count("ItemCode"), 0)AS TOTALBYRISK FROM "#tblRiskTempData" 
						WHERE "CalcRisk" = :High 
						GROUP BY "WhsCode", "CalcRisk") T1
						ON T0."WhsCode" = T1."WhsCode" )
				WHERE (T0.TOTAL <> 0 AND TO_DOUBLE(IFNULL(T1.TOTALBYRISK, 0))/ T0.TOTAL > :HRiskPercentMax)
			)
			ORDER BY "#tblRiskTempData"."WhsCode", "#tblRiskTempData"."ItemCode";
	ELSEIF :riskcode = :Low THEN
		SELECT "#tblRiskTempData"."ItemCode", "#tblRiskTempData"."ItemName",
		 	"#tblRiskTempData"."WhsCode", "#tblRiskTempData"."DaysSinceLastCount","#tblRiskTempData"."Risk1",
		 	"#tblRiskTempData"."TransVolume", "#tblRiskTempData"."Risk2", "#tblRiskTempData"."ValueOfItem",
		 	"#tblRiskTempData"."Risk3", "#tblRiskTempData"."CalcRisk", "OBPL"."BPLName", "OBPL"."BPLId" FROM "#tblRiskTempData"
		 	INNER JOIN "OWHS" ON "#tblRiskTempData"."WhsCode" = "OWHS"."WhsCode"
			LEFT JOIN "OBPL" ON "OWHS"."BPLid" = "OBPL"."BPLId"
			WHERE "#tblRiskTempData"."WhsCode" IN(
				SELECT T0."WhsCode"  AS "WhsCode" FROM (
						(SELECT "WhsCode", COUNT("ItemCode") AS TOTAL FROM "#tblRiskTempData" GROUP BY "WhsCode") T0
						LEFT JOIN 
						(SELECT "WhsCode", "CalcRisk", IFNULL(COUNT("ItemCode"), 0) AS TOTALBYRISK FROM "#tblRiskTempData" 
							WHERE "CalcRisk" = :High 
							GROUP BY "WhsCode", "CalcRisk") T1
						ON T0."WhsCode" = T1."WhsCode")
					WHERE (TOTAL <> 0 AND TO_DOUBLE(IFNULL(T1.TOTALBYRISK, 0))/ TOTAL < :HRiskPercentMin) OR TOTAL = 0
			)
			ORDER BY "#tblRiskTempData"."WhsCode", "#tblRiskTempData"."ItemCode";
	
	ELSEIF :riskcode = :Medium THEN
		SELECT "#tblRiskTempData"."ItemCode", "#tblRiskTempData"."ItemName",
		 	"#tblRiskTempData"."WhsCode", "#tblRiskTempData"."DaysSinceLastCount","#tblRiskTempData"."Risk1",
		 	"#tblRiskTempData"."TransVolume", "#tblRiskTempData"."Risk2", "#tblRiskTempData"."ValueOfItem",
		 	"#tblRiskTempData"."Risk3", "#tblRiskTempData"."CalcRisk", "OBPL"."BPLName", "OBPL"."BPLId" FROM "#tblRiskTempData"
		 	INNER JOIN "OWHS" ON "#tblRiskTempData"."WhsCode" = "OWHS"."WhsCode"
			LEFT JOIN "OBPL" ON "OWHS"."BPLid" = "OBPL"."BPLId"
			WHERE "#tblRiskTempData"."WhsCode" IN(
				SELECT T0."WhsCode"  AS "WhsCode" FROM (
					(SELECT "WhsCode", count("ItemCode") AS TOTAL FROM "#tblRiskTempData" GROUP BY "WhsCode") T0
					LEFT JOIN			
					(SELECT "WhsCode", "CalcRisk", IFNULL(count("ItemCode"), 0)AS TOTALBYRISK FROM "#tblRiskTempData" 
						WHERE "CalcRisk" = :High 
						GROUP BY "WhsCode", "CalcRisk") T1
						ON T0."WhsCode" = T1."WhsCode" )
				WHERE (T0.TOTAL <> 0 AND TO_DOUBLE(IFNULL(T1.TOTALBYRISK, 0))/ T0.TOTAL >= :HRiskPercentMin AND TO_DOUBLE(IFNULL(T1.TOTALBYRISK, 0))/ T0.TOTAL <= :HRiskPercentMax)
			)
			ORDER BY "#tblRiskTempData"."WhsCode", "#tblRiskTempData"."ItemCode";
	END IF;
		
	DROP TABLE "#tblRiskTempData";
END;

CREATE PROCEDURE TMSP_Inventory_Counting_GetCounterName(
in DocKey  nvarchar(12),
in ObjectId nvarchar(12),
in MultipleCounterType nvarchar(1),
in MultipleCounterOrder nvarchar(12)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
selectStr nvarchar(256);
fromStr nvarchar(256);
whereStr nvarchar(64);

CountingType nvarchar(1);

taker1Type int;

typeUSR int := 12;
typeHEM int := 171;
CountTypeSingle nvarchar(1) := '1';
CountTypeMultiple nvarchar(1) := '2';

CounterTypeTeam nvarchar(1) := 'T';
CounterTypeIndividual nvarchar(1) := 'I';

MainTable nvarchar(16);
Counter nvarchar(64);
joinTbl nvarchar(16);
joinCol nvarchar(16);

ResultCounterName nvarchar(16) := 'CounterName';

DocEntry nvarchar(16) := :DocKey;
CounterOrder nvarchar(16) := :MultipleCounterOrder;
BEGIN
if ObjectId = '1470000065' then --added doc

	whereStr := ' where "T0"."DocEntry"=' || :DocEntry;

	select "T0"."CountType" INTO CountingType from "OINC" "T0" where "T0"."DocEntry"= :DocKey;
	select "Taker1Type" INTO Taker1Type from "OINC" where "DocEntry"= :DocKey;

	IF (:CountingType = :CountTypeSingle )
	THEN
			SELECT "Taker1Type" INTO Taker1Type from "OINC" where "DocEntry"= :DocKey;
			
			IF(:taker1Type = :typeUSR)
			THEN
				 Counter := ' "T1"."U_NAME" ';
				 joinTbl := ' "OUSR" ';
				 joinCol := ' "USERID" ';
			ELSE
				 Counter := ' "T1"."lastName"||'' ''||"T1"."firstName" ';
				 joinTbl := ' "OHEM" ';
				 joinCol := ' "empID" ';
			End IF;

			selectStr := 'select ' || :Counter || ' as ' || :ResultCounterName || ' from "OINC"  "T0" ' ||  ' join ' || :joinTbl || ' "T1" on "T0"."Taker1Id" = "T1".' || :joinCol || :whereStr;
	ELSE
			IF(:MultipleCounterType = :CounterTypeTeam)
			THEN
				  MainTable :=' "INC4" "T0" ';
			ELSE
				  MainTable :=' "INC8" "T0" ';
			End IF;
		   
			selectStr := 'select ' ||  ' "T0"."CounteName" '|| ' as ' || :ResultCounterName || ' from '|| :MainTable  ||  :whereStr || ' and "T0"."VisOrder" = ' || :CounterOrder;
	END IF;
else
	whereStr := ' where "T0"."DocEntry"=' || :DocEntry;

	select "T0"."CountType" INTO CountingType from "OICD" "T0" where "T0"."DocEntry"= :DocKey;
	select "Taker1Type" INTO Taker1Type from "OICD" where "DocEntry"= :DocKey;

	IF (:CountingType = :CountTypeSingle )
	THEN
			SELECT "Taker1Type" INTO Taker1Type from "OICD" where "DocEntry"= :DocKey;
			
			IF(:taker1Type = :typeUSR)
			THEN
				 Counter := ' "T1"."U_NAME" ';
				 joinTbl := ' "OUSR" ';
				 joinCol := ' "USERID" ';
			ELSE
				 Counter := ' "T1"."lastName"||'' ''||"T1"."firstName" ';
				 joinTbl := ' "OHEM" ';
				 joinCol := ' "empID" ';
			End IF;

			selectStr := 'select ' || :Counter || ' as ' || :ResultCounterName || ' from "OICD"  "T0" ' ||  ' join ' || :joinTbl || ' "T1" on "T0"."Taker1Id" = "T1".' || :joinCol || :whereStr;
	ELSE
			IF(:MultipleCounterType = :CounterTypeTeam)
			THEN
				  MainTable :=' "ICD4" "T0" ';
			ELSE
				  MainTable :=' "ICD8" "T0" ';
			End IF;
		   
			selectStr := 'select ' ||  ' "T0"."CounteName" '|| ' as ' || :ResultCounterName || ' from '|| :MainTable  ||  :whereStr || ' and "T0"."VisOrder" = ' || :CounterOrder;
	END IF;
End if;
EXECUTE IMMEDIATE (:selectStr);

END;

CREATE PROCEDURE TMSP_Inventory_Counting_IndividualCounter (
   in DocKey  nvarchar(12),
   in ObjectId NCHAR(20)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
DocEntry INT := :DocKey;
Begin
	IF (:ObjectId = '1470000065') then
		select 	"OINC"."DocEntry", "OINC"."DocNum", "OINC"."CountDate", 
				"OINC"."Time", "OINC"."CountType", "OINC"."IndvCount",
				"INC1"."ItemCode", "INC1"."ItemDesc",
				"INC1"."WhsCode", "INC1"."InWhsQty", 
				"INC1"."CountQty", "INC1"."BinEntry", 
				"INC1"."Counted", "OBIN"."BinCode",
				"INC81"."CounteName" as "IndvCounter1Name",
				"INC82"."CounteName" as "IndvCounter2Name", 
				"INC83"."CounteName" as "IndvCounter3Name",
				"INC84"."CounteName" as "IndvCounter4Name", 
				"INC85"."CounteName" as "IndvCounter5Name", 
				"INC91"."TotalQty" as "IndvCounter1Qty", 
				"INC92"."TotalQty" as "IndvCounter2Qty", 
				"INC93"."TotalQty" as "IndvCounter3Qty", 
				"INC94"."TotalQty" as "IndvCounter4Qty", 
				"INC95"."TotalQty" as "IndvCounter5Qty"  from "INC1"
				   left join "OINC" on "OINC"."DocEntry" = "INC1"."DocEntry"
				   left join "OBIN" on "INC1"."BinEntry" = "OBIN"."AbsEntry"
				   left join "INC8" as "INC81" on ("INC1"."DocEntry" = "INC81"."DocEntry" and "INC81"."VisOrder" = 1)
				   left join "INC8" as "INC82" on ("INC1"."DocEntry" = "INC82"."DocEntry" and "INC82"."VisOrder" = 2)
				   left join "INC8" as "INC83" on ("INC1"."DocEntry" = "INC83"."DocEntry" and "INC83"."VisOrder" = 3)
				   left join "INC8" as "INC84" on ("INC1"."DocEntry" = "INC84"."DocEntry" and "INC84"."VisOrder" = 4)
				   left join "INC8" as "INC85" on ("INC1"."DocEntry" = "INC85"."DocEntry" and "INC85"."VisOrder" = 5)				   
				   left join "INC9" as "INC91" on ("INC1"."DocEntry" = "INC91"."DocEntry" and "INC1"."LineNum" = "INC91"."LineNum" and "INC81"."CounterNum" = "INC91"."CounterNum" and "INC81"."VisOrder" = 1)
				   left join "INC9" as "INC92" on ("INC1"."DocEntry" = "INC92"."DocEntry" and "INC1"."LineNum" = "INC92"."LineNum" and "INC82"."CounterNum" = "INC92"."CounterNum" and "INC82"."VisOrder" = 2)
				   left join "INC9" as "INC93" on ("INC1"."DocEntry" = "INC93"."DocEntry" and "INC1"."LineNum" = "INC93"."LineNum" and "INC83"."CounterNum" = "INC93"."CounterNum" and "INC83"."VisOrder" = 3)
				   left join "INC9" as "INC94" on ("INC1"."DocEntry" = "INC94"."DocEntry" and "INC1"."LineNum" = "INC94"."LineNum" and "INC84"."CounterNum" = "INC94"."CounterNum" and "INC84"."VisOrder" = 4)			
				   left join "INC9" as "INC95" on ("INC1"."DocEntry" = "INC95"."DocEntry" and "INC1"."LineNum" = "INC95"."LineNum" and "INC85"."CounterNum" = "INC95"."CounterNum" and "INC85"."VisOrder" = 5)
		where "OINC"."DocEntry" = :DocEntry order by "INC1"."VisOrder";
	Else
			
		select "OICD"."DocEntry", "OICD"."DocNum", "OICD"."CountDate", 
			"OICD"."Time", "OICD"."CountType", "OICD"."IndvCount",
			"ICD1"."ItemCode", "ICD1"."ItemDesc",
			"ICD1"."WhsCode", "ICD1"."InWhsQty", 
			"ICD1"."CountQty", "ICD1"."BinEntry", 
			"ICD1"."Counted", "OBIN"."BinCode",
			"ICD81"."CounteName" as "IndvCounter1Name",
			"ICD82"."CounteName" as "IndvCounter2Name", 
			"ICD83"."CounteName" as "IndvCounter3Name",
			 "ICD84"."CounteName" as "IndvCounter4Name", 
			 "ICD85"."CounteName" as "IndvCounter5Name", 
			"ICD91"."TotalQty" as "IndvCounter1Qty", 
			"ICD92"."TotalQty" as "IndvCounter2Qty", 
			"ICD93"."TotalQty" as "IndvCounter3Qty", 
			"ICD94"."TotalQty" as "IndvCounter4Qty", 
			"ICD95"."TotalQty" as "IndvCounter5Qty"  from "ICD1"
			   left join "OICD" on "OICD"."DocEntry" = "ICD1"."DocEntry"
			   left join "OBIN" on "ICD1"."BinEntry" = "OBIN"."AbsEntry"
			   left join "ICD8" as "ICD81" on ("ICD1"."DocEntry" = "ICD81"."DocEntry" and "ICD81"."VisOrder" = 1)
			   left join "ICD8" as "ICD82" on ("ICD1"."DocEntry" = "ICD82"."DocEntry" and "ICD82"."VisOrder" = 2)
			   left join "ICD8" as "ICD83" on ("ICD1"."DocEntry" = "ICD83"."DocEntry" and "ICD83"."VisOrder" = 3)
			   left join "ICD8" as "ICD84" on ("ICD1"."DocEntry" = "ICD84"."DocEntry" and "ICD84"."VisOrder" = 4)
			   left join "ICD8" as "ICD85" on ("ICD1"."DocEntry" = "ICD85"."DocEntry" and "ICD85"."VisOrder" = 5)				   
			   left join "ICD9" as "ICD91" on ("ICD1"."DocEntry" = "ICD91"."DocEntry" and "ICD1"."LineNum" = "ICD91"."LineNum" and "ICD81"."CounterNum" = "ICD91"."CounterNum" and "ICD81"."VisOrder" = 1)
			   left join "ICD9" as "ICD92" on ("ICD1"."DocEntry" = "ICD92"."DocEntry" and "ICD1"."LineNum" = "ICD92"."LineNum" and "ICD82"."CounterNum" = "ICD92"."CounterNum" and "ICD82"."VisOrder" = 2)
			   left join "ICD9" as "ICD93" on ("ICD1"."DocEntry" = "ICD93"."DocEntry" and "ICD1"."LineNum" = "ICD93"."LineNum" and "ICD83"."CounterNum" = "ICD93"."CounterNum" and "ICD83"."VisOrder" = 3)
			   left join "ICD9" as "ICD94" on ("ICD1"."DocEntry" = "ICD94"."DocEntry" and "ICD1"."LineNum" = "ICD94"."LineNum" and "ICD84"."CounterNum" = "ICD94"."CounterNum" and "ICD84"."VisOrder" = 4)			
			   left join "ICD9" as "ICD95" on ("ICD1"."DocEntry" = "ICD95"."DocEntry" and "ICD1"."LineNum" = "ICD95"."LineNum" and "ICD85"."CounterNum" = "ICD95"."CounterNum" and "ICD85"."VisOrder" = 5)
		where "OICD"."DocEntry" = :DocEntry order by "ICD1"."VisOrder";
	END if;
End;

CREATE PROCEDURE TMSP_Inventory_Counting_PerCounter (
    DocKey nvarchar(12),
    ObjectId NCHAR(20),
    MultipleCounterType nvarchar (1) default 'I' ,
    MultipleCounterOrder nvarchar (12)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
CountType nvarchar(1) ;
CountNumber INT;
DocEntry INT := :DocKey ;

BEGIN
	IF (:ObjectId = '1470000065' ) THEN
	               SELECT "OINC" ."CountType" INTO CountType FROM "OINC" WHERE "OINC" ."DocEntry" = :DocEntry ;
	
	               IF (:CountType = '1' ) THEN --single counter
	                  SELECT "T1" ."DocEntry" , "T1" ."ItemCode" , "T1" ."ItemDesc" , "T1" ."WhsCode" , "T1" ."BinEntry" , "T2" ."BinCode" , "T1" ."InWhsQty" , "T1" ."Counted" , "T1" ."CountQty"
	                  FROM "INC1" "T1" LEFT JOIN "OBIN" "T2" ON "T1" ."BinEntry" ="T2" ."AbsEntry" WHERE "T1". "DocEntry" = :DocEntry  ORDER BY "T1" ."VisOrder" ;
	               ELSE   --multiple counters
	                  IF (:MultipleCounterType = 'I' ) THEN --individual counter
	                      SELECT "T1" ."CounterNum" INTO CountNumber FROM "INC8" "T1" WHERE "T1" ."DocEntry" = :DocEntry AND "T1". "VisOrder" = :MultipleCounterOrder;
	                     
	                      SELECT "T1" ."DocEntry" , "T1" ."ItemCode" , "T1" ."ItemDesc" , "T1" ."WhsCode" , "T1" ."BinEntry" , "T2" ."BinCode" , "T1" ."InWhsQty" , "T1" ."Counted" , "T3" ."TotalQty" AS "CountQty"
	                      FROM "INC1" "T1"
	                      LEFT JOIN "OBIN" "T2" ON "T1". "BinEntry" ="T2" ."AbsEntry"
	                      LEFT JOIN "INC9" "T3" ON "T1". "DocEntry" ="T3" ."DocEntry" AND  "T1" ."LineNum" ="T3" ."LineNum" AND "T3". "CounterNum" = :CountNumber
	                      WHERE "T1" ."DocEntry" = :DocEntry ORDER BY "T1" ."VisOrder" ;
	                  ELSE   --Team counters
	                      SELECT "T1" ."CounterNum" INTO CountNumber FROM "INC4" "T1" WHERE "T1" ."DocEntry" = :DocEntry AND "T1". "VisOrder" = :MultipleCounterOrder;
	                     
	                      SELECT "T1" ."DocEntry" , "T1" ."ItemCode" , "T1" ."ItemDesc" , "T1" ."WhsCode" , "T1" ."BinEntry" , "T2" ."BinCode" , "T1" ."InWhsQty" , "T1" ."Counted" , "T3" ."TotalQty" AS "CountQty"
	                      FROM "INC1" "T1"
	                      LEFT JOIN "OBIN" "T2" ON "T1". "BinEntry" ="T2" ."AbsEntry"
	                      LEFT JOIN "INC5" "T3" ON "T1". "DocEntry" ="T3" ."DocEntry" AND  "T1" ."LineNum" ="T3" ."LineNum" AND "T3". "CounterNum" = :CountNumber
	                      WHERE "T1" ."DocEntry" = :DocEntry ORDER BY "T1" ."VisOrder" ;
	                END IF ;
	           END IF ;
	Else
			SELECT  "OICD"."CountType" into CountType  FROM "OICD" WHERE "OICD"."DocEntry" = :DocEntry;
			IF (:CountType = '1') then --single counter
					SELECT "T1"."DocEntry", "T1"."ItemCode", "T1"."ItemDesc", "T1"."WhsCode", "T1"."BinEntry", "T2"."BinCode", "T1"."InWhsQty", "T1"."Counted", "T1"."CountQty" 
					FROM "ICD1" "T1" LEFT JOIN "OBIN" "T2" ON "T1"."BinEntry"="T2"."AbsEntry" WHERE "T1"."DocEntry"=:DocEntry ORDER BY "T1"."VisOrder";
			ELSE  --multiple counters
				IF (:MultipleCounterType = 'I') then --individual counter
					SELECT "T1"."CounterNum" INTO CountNumber FROM "ICD8" "T1" WHERE "T1"."DocEntry" = :DocEntry AND "T1"."VisOrder" = :MultipleCounterOrder;
					SELECT "T1"."DocEntry", "T1"."ItemCode", "T1"."ItemDesc", "T1"."WhsCode", "T1"."BinEntry", "T2"."BinCode", "T1"."InWhsQty", "T1"."Counted", "T3"."TotalQty" AS "CountQty" 
					FROM "ICD1" "T1" 
					LEFT JOIN "OBIN" "T2" ON "T1"."BinEntry"="T2"."AbsEntry"
					LEFT JOIN "ICD9" "T3" ON "T1"."DocEntry"="T3"."DocEntry" AND  "T1"."LineNum"="T3"."LineNum" AND "T3"."CounterNum" = :CountNumber
					WHERE "T1"."DocEntry"=:DocEntry ORDER BY "T1"."VisOrder";
				 
				ELSE  --Team counters
					SELECT "T1"."CounterNum" INTO CountNumber FROM "ICD4" "T1" WHERE "T1"."DocEntry" = :DocEntry AND "T1"."VisOrder" = :MultipleCounterOrder;
					SELECT "T1"."DocEntry", "T1"."ItemCode", "T1"."ItemDesc", "T1"."WhsCode", "T1"."BinEntry", "T2"."BinCode", "T1"."InWhsQty", "T1"."Counted", "T3"."TotalQty" AS "CountQty" 
					FROM "ICD1" "T1" 
					LEFT JOIN "OBIN" "T2" ON "T1"."BinEntry"="T2"."AbsEntry"
					LEFT JOIN "ICD5" "T3" ON "T1"."DocEntry"="T3"."DocEntry" AND  "T1"."LineNum"="T3"."LineNum" AND "T3"."CounterNum" = :CountNumber
					WHERE "T1"."DocEntry"= :DocEntry ORDER BY "T1"."VisOrder";
				End if; 
			End if;
	END IF ;
END

Create PROCEDURE TMSP_Inventory_Counting_TeamCounter(
in DocKey  nvarchar(12) ,
in ObjectId NCHAR(20)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
BEGIN
IF (:ObjectId = '1470000065') then
		select "OINC"."DocEntry", "OINC"."DocNum", "OINC"."CountDate", "OINC"."Time", "OINC"."CountType", "OINC"."TeamCount",
	   "INC1"."ItemCode", "INC1"."ItemDesc", "INC1"."WhsCode", "INC1"."InWhsQty", "INC1"."CountQty", "INC1"."BinEntry", "INC1"."Counted", OBIN."BinCode",
	   "INC41"."CounteName" as "TeamCounter1Name", "INC42"."CounteName" as "TeamCounter2Name", INC43."CounteName" as "TeamCounter3Name", INC44."CounteName" as "TeamCounter4Name", INC45."CounteName" as "TeamCounter5Name",
	   INC46."CounteName" as "TeamCounter6Name", INC47."CounteName" as "TeamCounter7Name", INC48."CounteName" as "TeamCounter8Name", INC49."CounteName" as "TeamCounter9Name", INC410."CounteName" as "TeamCounter10Name",
	   INC51."TotalQty" as "TeamCounter1Qty", INC52."TotalQty" as "TeamCounter2Qty", INC53."TotalQty" as "TeamCounter3Qty", INC54."TotalQty" as "TeamCounter4Qty", INC55."TotalQty" as "TeamCounter5Qty",
	   INC56."TotalQty" as "TeamCounter6Qty", INC57."TotalQty" as "TeamCounter7Qty", INC58."TotalQty" as "TeamCounter8Qty", INC59."TotalQty" as "TeamCounter9Qty", INC510."TotalQty" as "TeamCounter10Qty" from "INC1"
				   left join "OINC" on "OINC"."DocEntry" = "INC1"."DocEntry"
				   left join OBIN on "INC1"."BinEntry" = "OBIN"."AbsEntry"
				   left join "INC4" as "INC41" on ("INC1"."DocEntry" = "INC41"."DocEntry" and "INC41"."VisOrder" = 1)
				   left join "INC4" as "INC42" on ("INC1"."DocEntry" = "INC42"."DocEntry" and "INC42"."VisOrder" = 2)
