--drop procedure TmSp_IVIInventoryValueDiffsFIFOItems;
Create procedure TmSp_IVIInventoryValueDiffsFIFOItems(out retCode INT)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
	Perpetual_Inventory nvarchar(1);
	isPricePerWH nvarchar(1);
	PriceDec TinyInt;
	roundmthd nvarchar(1);
	maincurrency char(3);
	sumdec int;
	deciamls int;
	rowcount int;
begin
	select "ContInvnt" into Perpetual_Inventory from "OADM";
	select "RoundMthd" into roundmthd from "OADM";
	select "MainCurncy" into maincurrency from "OADM";
	select "SumDec" into sumdec from "OADM";
	select "Decimals" into deciamls from "OCRN" where "CurrCode" = :maincurrency;
	Select T1."PriceSys" INTO isPricePerWH From OADM T1;

if :roundmthd = 'Y' and :deciamls <> -1
then      
	sumdec := :deciamls;
end if;

	delete from "TmSp_IVIInventoryValueDiffsFIFOItems_TMP";
 
if :Perpetual_Inventory = 'Y' and :isPricePerWH = 'Y' then


INSERT INTO "TmSp_IVIInventoryValueDiffsFIFOItems_TMP"
Select W."ItemCode" as "ItemCode", M."ItemName" as "ItemName", M."EvalSystem" as "InvnetoryMethod", W."WhsCode" as "WarehouseCode",
      W."OnHand" as "QtyInWH", W."AvgPrice", SUM (IFNULL(V."InQty",0) - IFNULL(V."OutQty",0)) AS "QtyInUIVL", W."StockValue",
	case when W."OnHand" < 0 then round(W."OnHand"*W."AvgPrice",:sumdec)  else '0' end as "Qty*StaticPrice",
	SUM(V1."TransValue")as "Sum_TransValue", Q."OpenValue" as "Sum_OpenValue"
From "UITW" W INNER join "UITM" M on W."ItemCode" = M."ItemCode" INNER join "UIVL" V on W."ItemCode" = V."ItemCode" and W."WhsCode" = V."LocCode"
INNER join "UIVL1" V1 on V."TransSeq" = V1."TransSeq" INNER join

 (select "ItemCode","LocCode",sum("OpenValue") "OpenValue" from "UIVQ" group by "ItemCode","LocCode" )Q on Q."ItemCode" = V."ItemCode" and Q."LocCode" = V."LocCode"

Group by 

W."ItemCode",M."ItemCode", V."ItemCode", Q."ItemCode", M."ItemName", M."EvalSystem", W."WhsCode", V."LocCode",Q."LocCode", W."OnHand", W."AvgPrice",W."StockValue",Q."OpenValue"
having M."EvalSystem" = 'F' and 

W."StockValue" <> sum(V1."TransValue") or  
M."EvalSystem" <> 'B' AND abs((Case when W."OnHand"  = 0 
Then '0'
else
case when W."OnHand"  < 0 
Then W."StockValue"
Else
Q."OpenValue" end end) - W."StockValue")  > 1 or 
 M."EvalSystem" = 'B' AND Q."OpenValue" <> 0;
end if;



IF :Perpetual_Inventory = 'Y' and :isPricePerWH = 'N' THEN

insert into "TmSp_IVIInventoryValueDiffsFIFOItems_TMP"
Select M."ItemCode" as "ItemCode", M."ItemName" as "ItemName", M."EvalSystem" as "InvnetoryMethod",

		'',

		M."OnHand" as "QtyInWH",

		M."AvgPrice",
				
		SUM (IFNULL(V."InQty",0) - IFNULL(V."OutQty",0)) AS "QtyInUIVL",

		 

		M."StockValue",

		case when M."OnHand" < 0

		then round(M."OnHand"*M."AvgPrice",:sumdec) 

		else

		'0'

		end as "Qty*StaticPrice",

		SUM(V1."TransValue")as "Sum_TransValue",

		Q."OpenValue" as "Sum_OpenValue"

From 

      "UITM" M INNER join "UIVL" V on M."ItemCode" = V."ItemCode" INNER join "UIVL1" V1 on V."TransSeq" = V1."TransSeq" 

      INNER join (select "ItemCode",sum("OpenValue") "OpenValue" from UIVQ group by "ItemCode" )Q on Q."ItemCode" = V."ItemCode" 

Group by 

      M."ItemCode",V."ItemCode",Q."ItemCode",M."ItemName",M."EvalSystem",M."OnHand",M."AvgPrice",M."StockValue",Q."OpenValue"

having 

      M."EvalSystem" = 'F' and 

      M."StockValue" <> sum(V1."TransValue") or 
 
      M."EvalSystem" <> 'B' and abs((Case when M."OnHand"  = 0 
      Then '0'
	  else
	  case when M."OnHand"  < 0 
      Then M."StockValue"
	  Else
	  Q."OpenValue" end end) - M."StockValue") > 1 or
     M."EvalSystem" = 'B' AND Q."OpenValue" <> 0 ;

end IF;
select count(1) into rowcount from "TmSp_IVIInventoryValueDiffsFIFOItems_TMP";
delete from "TmSp_IVIInventoryValueDiffsFIFOItems_TMP";
if(:rowcount > 0) 
then
retCode := -1;
return;

--Return -1

else
--/*Inventory Value recalculation for FIFO items is succesfull*/;
retCode := 0;
return;
--Return 0
end if;
end;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END

--alter session set current_schema=SBODEMOUS;
--drop procedure TmSp_IVIInventoryValueDiffsMAPnSTDItems;
Create procedure TmSp_IVIInventoryValueDiffsMAPnSTDItems(OUT retCode INT)
-- Return Codes
--(-1) = Empty Parameter Was Entered
--(-2)  --Enpty or invalid Line set
--(-3) -- Invalid Currency or Bad Account code
--(-4) -- Invalid Card Currency or Bad Account code

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as


isPricePerWH nvarchar(1);
PriceDec TinyInt;

roundmthd nvarchar(1);

maincurrency char(3);

sumdec int;

deciamls int;
rowcount int;

begin


select "RoundMthd" into roundmthd from "OADM";

select "MainCurncy" into maincurrency from "OADM";

select "SumDec" into sumdec from "OADM";

select "Decimals" into deciamls from "OCRN" where "CurrCode" = :maincurrency;

Select T1."PriceSys" into isPricePerWH From "OADM" T1; 

delete from "TmSp_IVIInventoryValueDiffsMAPnSTDItems_tmp";


if :roundmthd = 'Y' and :deciamls <> -1

then

      

     sumdec := :deciamls;

end if;

 if :isPricePerWH = 'Y'

 

then


insert into "TmSp_IVIInventoryValueDiffsMAPnSTDItems_tmp"
select Top 1
      W."ItemCode" as "ItemCode", 

      M."ItemName" as "ItemName",

      M."EvalSystem" as "InvnetoryMethod", 

      W."WhsCode" as "WarehouseCode",

      W."OnHand" as "QtyInWH",
	  W."AvgPrice",
	  SUM (IFNULL(V."InQty", 0) - IFNULL(V."OutQty", 0)) AS "QtyInUIVL",



W."StockValue",

case when W."OnHand" < 0

then round(W."OnHand"*W."AvgPrice",:sumdec) 
else

'0'

end as "Qty*StaticPrice",

SUM(V1."TransValue")as "Sum_TransValue"



From "UITW" W INNER join "UITM" M on W."ItemCode" = M."ItemCode" INNER join "UIVL" V on W."ItemCode" = V."ItemCode" and W."WhsCode" = V."LocCode"

 INNER join "UIVL1" V1 on V."TransSeq" = V1."TransSeq" 

Group by 

W."ItemCode",M."ItemCode", V."ItemCode",  M."ItemName", M."EvalSystem", W."WhsCode", V."LocCode", W."OnHand",

W."AvgPrice",W."StockValue"

having 

M."EvalSystem" in ('A','S') and 

(W."StockValue" <> sum(V1."TransValue") or 
	   W."OnHand"  = 0 and (W."StockValue" > 1 or W."StockValue" < -1));
end if;




if :isPricePerWH = 'N'


then



insert into "TmSp_IVIInventoryValueDiffsMAPnSTDItems_tmp"

Select  top 1

		M."ItemCode" as "ItemCode", 

		M."ItemName" as "ItemName",

		M."EvalSystem" as "InvnetoryMethod",

		'',

		M."OnHand" as "QtyInWH",

		M."AvgPrice",
				
		SUM (IFNULL(V."InQty",0) - IFNULL(V."OutQty",0)) AS "QtyInUIVLM",

		

		M."StockValue",

		case when M."OnHand" < 0

		then round(M."OnHand"*M."AvgPrice",:sumdec) 

		else

		'0'
         end as "Qty*StaticPrice",

		SUM(V1."TransValue")as "Sum_TransValue"

	

From 

      "UITM" M INNER join "UIVL" V on M."ItemCode" = V."ItemCode" INNER join "UIVL1" V1 on V."TransSeq" = V1."TransSeq" 

     

Group by 

      M."ItemCode",V."ItemCode",M."ItemName",M."EvalSystem",M."OnHand",M."AvgPrice",M."StockValue"

having 

M."EvalSystem" in ('A','S') and 

(M."StockValue" <> sum(V1."TransValue") or 
	   M."OnHand"  = 0 and (M."StockValue" > 1 or M."StockValue" < -1));

end if;
select count(1) into rowcount from "TmSp_IVIInventoryValueDiffsMAPnSTDItems_tmp";
delete from "TmSp_IVIInventoryValueDiffsMAPnSTDItems_tmp";
if(:rowcount > 0) 
then
--return -1;
retCode := -1;
return;
else
--/*Inventory Value recalculation for FIFO items is succesfull*/

--return 0;
retCode := 0;
return;
end if;
End;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END

/*HANA Inventory Value Differences - SnB items_1.0 */  

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables AFTER:PT:PROCESS_END
-- DROP PROCEDURE TmSp_IVIInventoryValueDiffsSNBItems;

CREATE PROCEDURE TmSp_IVIInventoryValueDiffsSNBItems(out retCode INT)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as  
	Perpetual_Inventory nvarchar(1);  
	isPricePerWH nvarchar(1);
	IsExistBvlBaseTMP integer;
	IsExistBvlTMP integer;
	IsExistIvlTMP integer;
	IsExistItwTMP integer;
	temp_var integer;

BEGIN  
	retCode :=  0;

	select "ContInvnt" into Perpetual_Inventory from "OADM";
	select "PriceSys" into isPricePerWH from "OADM";
	
	select count(*) into IsExistBvlBaseTMP from "PUBLIC"."M_TEMPORARY_TABLES" where schema_name = CURRENT_SCHEMA and table_name='#UBVL_Aggregation_Base';
	IF (:IsExistBvlBaseTMP > 0 ) then
		DROP TABLE "#UBVL_Aggregation_Base";
	end if; 
  
	select count(*) into IsExistBvlTMP from "PUBLIC"."M_TEMPORARY_TABLES" where schema_name = CURRENT_SCHEMA and table_name='#UBVL_Aggregation';
	IF (:IsExistBvlTMP > 0 ) then
		DROP TABLE "#UBVL_Aggregation";
	end if; 
    
	select count(*) into IsExistItwTMP from "PUBLIC"."M_TEMPORARY_TABLES" where schema_name = CURRENT_SCHEMA and table_name='#UITW_Aggregation';
	IF (:IsExistItwTMP  > 0 ) then
		DROP TABLE "#UITW_Aggregation";
	end if; 
    
	if :Perpetual_Inventory = 'Y' then
		-- TEMP TABLES
		CREATE LOCAL TEMPORARY COLUMN TABLE "#UBVL_Aggregation_Base" AS 
		(SELECT T0."ItemCode", T0."MdAbsEntry", T0."ManagedBy", SUM(T0."InvValue") AS "InvValue", MAX(T0."AbsEntry") AS "maxEntry" 
		 FROM UBVL T0 
		 WHERE "MdAbsEntry" IS NOT NULL 
		 GROUP BY T0."ItemCode", T0."MdAbsEntry", T0."ManagedBy");

		CREATE LOCAL TEMPORARY COLUMN TABLE "#UBVL_Aggregation" AS 
 		(SELECT T0.*, T1."AccQty" - t1."AccNegQ" AS "BVLQty" FROM "#UBVL_Aggregation_Base" T0, UBVL T1 WHERE T1."AbsEntry" = "maxEntry");
 		
-- UITM.StockValue  <=>  UBVL.InvValue
		if :isPricePerWH = 'Y' then
			-- TEMP TABLE BASED ON UITW
			CREATE LOCAL TEMPORARY COLUMN TABLE "#UITW_Aggregation" AS 
			(SELECT T0."ItemCode", SUM(T0."StockValue") AS "ITW_StockValue" FROM UITW T0 GROUP BY T0."ItemCode");


			select count(*) INTO temp_var from (
			SELECT "#UITW_Aggregation"."ItemCode", SUM("InvValue")
			FROM "#UITW_Aggregation", "#UBVL_Aggregation"
			WHERE "#UITW_Aggregation"."ItemCode" = "#UBVL_Aggregation"."ItemCode" 
			GROUP BY "#UITW_Aggregation"."ItemCode", "ITW_StockValue"
			HAVING "ITW_StockValue" <> SUM("InvValue"));
			
			DROP TABLE "#UITW_Aggregation";

		else 
			select count(*) INTO temp_var from (SELECT UITM."ItemCode", SUM("InvValue") FROM UITM, "#UBVL_Aggregation" 
			        WHERE UITM."ItemCode" = "#UBVL_Aggregation"."ItemCode" 
			        GROUP BY UITM."ItemCode", "StockValue" 
			        HAVING "StockValue" <> SUM("InvValue"));  
		end if;
		if :temp_var > 0 THEN 
			retCode := 1; 
		end if;
		

--UITM.OnHand  <=>  UBVL.calculatedOnHand
		if :retCode = 0 then
			select count(*) INTO temp_var from (
				SELECT UITM."ItemCode", SUM("BVLQty")
				FROM UITM, "#UBVL_Aggregation"
				WHERE UITM."ItemCode"="#UBVL_Aggregation"."ItemCode"
				GROUP BY UITM."ItemCode", "OnHand"
				HAVING "OnHand"<>SUM("BVLQty"));	
		end if;
	
		if :temp_var > 0 THEN 
			retCode := 2; 
		end if;
		
-- UBTN quantity pre batch   <=>  UBVL quantity per batch
		if :retCode = 0 then
				select count(*) INTO temp_var from ( 
				SELECT UBTN."ItemCode" , "BVLQty", (UBTN."Quantity" - UBTN."QuantOut") as "BTNQty"
				FROM "#UBVL_Aggregation", UBTN 
				WHERE UBTN."ItemCode"="#UBVL_Aggregation"."ItemCode" AND UBTN."AbsEntry"="#UBVL_Aggregation"."MdAbsEntry" and "#UBVL_Aggregation"."ManagedBy" = UBTN."ObjType"
				and "BVLQty"<>(UBTN."Quantity" - UBTN."QuantOut"));
		end if;
		
		if :temp_var > 0 THEN 
			retCode := 3; 
		end if;
	
		-- USRN quantity pre batch   <=>  UBVL quantity per batch	
		if :retCode = 0 then
				select count(*) INTO temp_var from ( 
					 SELECT USRN."ItemCode", "BVLQty", (USRN."Quantity" - USRN."QuantOut") AS "SRNQty" 
					 FROM "#UBVL_Aggregation", USRN 
					 WHERE USRN."ItemCode" = "#UBVL_Aggregation"."ItemCode" AND USRN."AbsEntry" = "#UBVL_Aggregation"."MdAbsEntry" AND "#UBVL_Aggregation"."ManagedBy" = USRN."ObjType" AND "BVLQty" <> (USRN."Quantity" - USRN."QuantOut"));
		end if;
		
		if :temp_var > 0 THEN 
			retCode := 4; 
		end if;
		
		-- UIVL Qties and TransValues <=> UBVL Qties and TransValues 		
		if :retCode = 0 then
			-- TEMP table for UIVL
			select count(*) into IsExistIvlTMP from "PUBLIC"."M_TEMPORARY_TABLES" where schema_name = CURRENT_SCHEMA and table_name='#UIVL_Aggregation_Item';
			IF (:IsExistIvlTMP > 0 ) then
				DROP TABLE "#UIVL_Aggregation_Item";
    		end if; 
    		CREATE LOCAL TEMPORARY COLUMN TABLE "#UIVL_Aggregation_Item" AS (
    			SELECT T0."ItemCode", SUM(T1."TransValue") AS "TransValue", SUM(IFNULL(T0."InQty", 0) - IFNULL(T0."OutQty", 0)) AS "QtyInUIVL" 
    			FROM UIVL T0 INNER JOIN UIVL1 T1 ON T0."TransSeq" = T1."TransSeq" WHERE T0."CostMethod"='B' GROUP BY T0."ItemCode"
    		);
			-- Stock Values
			if (:retCode = 0) then
					select count(*) INTO temp_var from (
	 					SELECT T0."ItemCode", SUM(T1."InvValue") 
	 					FROM "#UIVL_Aggregation_Item" T0, "#UBVL_Aggregation" T1 
	 					WHERE T0."ItemCode" = T1."ItemCode" 
	 					GROUP BY T0."ItemCode", T0."TransValue" 
	 					HAVING T0."TransValue" <> SUM(T1."InvValue"));
			end if;
		
			if :temp_var > 0 THEN 
				retCode := 5; 
			end if;
			-- Stock Qties
			if (:retCode = 0) then
						select count(*) INTO temp_var from ( 
							SELECT T0."ItemCode",(T0."QtyInUIVL") ,SUM(T1."BVLQty") FROM "#UIVL_Aggregation_Item" T0, "#UBVL_Aggregation" T1
							WHERE T0."ItemCode"=T1."ItemCode"
							GROUP BY T0."ItemCode",T0."QtyInUIVL"
							HAVING (T0."QtyInUIVL")<>SUM(T1."BVLQty"));
			end if;
			
			DROP TABLE "#UIVL_Aggregation_Item";
			
			if :temp_var > 0 THEN 
				retCode := 6; 
			end if;
		end if; -- UIVL <+> UBVL check

	end if;
	DROP TABLE "#UBVL_Aggregation_Base";
    DROP TABLE "#UBVL_Aggregation";

	if :retCode > 0 then
		retCode := -1;
	else
		retCode := 0;
	end if;
END;

-- B1 DEPENDS: AFTER:SP:TmSp_IVIInventoryValueDiffsFIFOItems AFTER:SP:TmSp_IVIInventoryValueDiffsMAPnSTDItems AFTER:PT:PROCESS_END

Create procedure TmSp_IVIVerifyInventoryRecalculation(out retCode int)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
-- Return Codes
--(-1) = Empty Parameter Was Entered
--(-2)  --Enpty or invalid Line set
--(-3) -- Invalid Currency or Bad Account code
--(-4) -- Invalid Card Currency or Bad Account code
As

Result int;
flag int:=0;
Begin

Result := 0;
SELECT COUNT(*) INTO flag FROM "UITM" T0
	WHERE T0."InvntItem" ='Y' and T0."EvalSystem" in ('S','A');

IF :flag>0 THEN
CALL TmSp_IVIInventoryValueDiffsMAPnSTDItems(:Result);
END IF;

If :Result <> -1
THEN 

SELECT COUNT(*) INTO flag FROM "UITM" T0
	WHERE T0."InvntItem" ='Y' and T0."EvalSystem" = 'F';
IF :flag>0 THEN
CALL TmSp_IVIInventoryValueDiffsFIFOItems(:Result);
END IF;

END IF;

If :Result <> -1
THEN 

SELECT COUNT(*) INTO flag FROM "UITM" T0
	WHERE T0."InvntItem" ='Y' and T0."EvalSystem" = 'B';
IF :flag>0 THEN
CALL TmSp_IVIInventoryValueDiffsSNBItems(:Result);
END IF;

END IF;
If :Result <> -1
THEN
retCode := 0; 
return;



else 

retCode := -1; 
return;

END IF;
end

-- B1 DEPENDS: AFTER:PT:PROCESS_END

Create procedure TmSp_IVIYearTransfer(out retCode int)

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS


	isexist1 int;
	isexist2 int;
	isexist3 int;
	isexist4 int;
	isexist5 int;
	isexist6 int;
	isexist7 int;
	isexist8 int;
	isexist9 int;
	isexist10 int;
	isexist11 int;
	isexist12 int;
BEGIN

	

	
	select count("DocEntry") into isexist1 from  "ODLN" where "Instance" >0; 
    select count("DocEntry") into isexist2 from  "ORDN" where "Instance" >0;  
    select count("DocEntry") into isexist3 from  "OINV" where "Instance" >0;  
    select count("DocEntry") into isexist4 from  "ORIN" where "Instance" >0;  
    select count("DocEntry") into isexist5 from  "OCSI" where "Instance" >0;  
    select count("DocEntry") into isexist6 from  "OCSV" where "Instance" >0; 
    select count("DocEntry") into isexist7 from  "OPDN" where "Instance" >0;  
    select count("DocEntry") into isexist8 from  "ORPD" where "Instance" >0;  
    select count("DocEntry") into isexist9 from  "OPCH" where "Instance" >0;  
    select count("DocEntry") into isexist10 from  "ORPC" where "Instance" >0;  
    select count("DocEntry") into isexist11 from  "OCPI" where "Instance" >0;  
    select count("DocEntry") into isexist12 from  "OCPV" where "Instance" >0; 
	
	isexist1 := :isexist1 + :isexist2 + :isexist3 + :isexist4 + :isexist5 + :isexist6 + :isexist7 + :isexist8 + :isexist9 + :isexist10 + :isexist11 + :isexist12;	
	
	
	
--return @Count;
retCode := :isexist1;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables

create procedure TmSp_IVSR_AutomaticHealingRequiredQuery
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
--set nocount on

	openQty			DECIMAL(21,6);
	qtySum			DECIMAL(21,6);
	transNum		int;
	instance		int;
	lastTransNum	int;
	lastInstance	int;
	cnt 			int;

 	qty_decimals 	int;
 	sum_decimals 	int;
 	main_currency 	nvarchar(3);
 	DBImpacted 		nvarchar(1) := 'N';
 	Recalc_By_OILM 	nvarchar(1) := 'Y';		--Simulation is always as recalculation based on OILM
 	roundmthd 		nvarchar(1);
 	OCRNdeciamls 	int;
	directrate 		nvarchar(1); 
	
	Update_before 	nvarchar(1);
	StockIssue 		nvarchar(1);
	isArchived 		nvarchar(1);
	
	OldTransID 		int;
	OldCreateDate 	TIMESTAMP;
	OldTransType 	int;
	OldcreatedBy 	int;

	TransID 		int;
	CreateDate 		TIMESTAMP;
	TransType 		int;
	createdBy 		int;
	
	sqlStr 			nvarchar(4000);
	tmpStr 			nvarchar(256);
	DocTable 		nvarchar(4);
	
	OldMessageID_1 	int; 
	OldCreateDate_1 TIMESTAMP;
	OldCreateTime_1 int;
	MessageID_1 	int;
	CreateDate_1 	TIMESTAMP;
	CreateTime_1 	int;
	
	cursor zXCursor for select  "TransId", "CreateDate", "TransType", "CreatedBy" from OJDT
		where "TransType" IN (13,14,15,16,18,19,20,21,58,59,60,67,68,69,162,163,164,165,166,10000071,310000001)
		order by "TransId";
		
	cursor typesCur for select "DocTable" from "TmSp_IVSR_AHRQ_Disorder_detect_DocTables";
	
	cursor zXCursor2 for select "MessageID", "CreateDate", "CreateTime" from OILM
	  where "TransType" <> 195 
	  ---exclude inflation wizard postings
	  order by "MessageID"; 
	
Begin
	delete from "TmSp_IVSR_AHRQ_CheckStockResults";

-- ==================================================================================================
-- ==================================================================================================
-- ==================================================================================================
--							SOURCE: IVI_AutomaticHealingRequiredQuery.sql
-- ==================================================================================================
	select "MainCurncy" into main_currency from OADM;
	select "QtyDec" into qty_decimals from OADM;
	
	select count(1) into cnt from CIVI where "ReorderFrm" is not null;
	if :cnt = 0 then
		StockIssue := 'N';
	else 
		StockIssue := 'Y';
	end if;
	
	select count(1) into cnt from LIVI where "UpdateDate" is not null;
	if :cnt = 0 then
		Update_before := 'N';
	else
		Update_before := 'Y';
	end if;
	
	select count(1) into cnt from livi1 where "Result" = 'A';
	if :cnt > 0 then
		isArchived := 'Y';
	else
		isArchived := 'N';
	end if;

-- Recalculation by OILM
if :Recalc_By_OILM = 'Y' or :StockIssue = 'Y' then
	
/**
 * Au_D_1002_SBO_RSP_IVI_OIVL with wrong doclinenum for WKO_Detect 
 * Doclinenum for type 68 was set to zero for all wko1 lines due to old bug in IVU 2005sp1.
*/
	select count(1) into cnt from OILM where '08.80.000.00' <= ifnull("VersionNum",'') and ifnull("VersionNum",'') < '08.80.228.09';
	delete from "TmSp_IVSR_AHRQ_RSP_IVI_Autofx_Boms";
	
	if :Update_before = 'Y' and :cnt > 0 then  
		
		insert into "TmSp_IVSR_AHRQ_RSP_IVI_Autofx_Boms"
		select distinct T0."ItemCode", T0."CreatedBy", T0."TransType", T0."DocLineNum", T0."DocLineNum", T0."MessageID"
		from OIVL T0
		inner join WKO1 T1 on T0."CreatedBy" = T1."OrderNum" and T0."ItemCode" = T1."ItemCode" and 
			T0."InQty" - T0."OutQty" = T1."Quantity" and T0."TransType" = 68 
		order by "MessageID"; 
     
    	update "TmSp_IVSR_AHRQ_RSP_IVI_Autofx_Boms" T0 
    		set T0."DocLineNum" = (select count(1) from "TmSp_IVSR_AHRQ_RSP_IVI_Autofx_Boms" T1 
                         where T1."CreatedBy" = T0."CreatedBy" and T1."MessageID" < T0."MessageID");  
     
     	select count(1) into cnt from "TmSp_IVSR_AHRQ_RSP_IVI_Autofx_Boms" where "DocLineNum" <> "OldDocLineNum";
     	
     	if :cnt > 0 then
     		DBImpacted := 'Y';
     		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values(N'DB is affected(1002)');
     	end if;
    end if;    	
    delete from "TmSp_IVSR_AHRQ_RSP_IVI_Autofx_Boms";
    	
/**
 * Au_D_1003_Production Order Issue Method is not consistent
 * come from Supp_406_Production Order Issue Method is not consistent
 * The issue method in WOR1 is 'B'. But based on the transaction records, it should be 'M'.
 * 
*/
	select count(1) into cnt from 
	(select T0."DocEntry" from OILM T0
	 inner join WOR1 T1 on T0."TransType" = 60 and T0."BaseType" = 202 and T0."AppObjAbs" = T1."DocEntry"
	 	and T0."AppObjLine" = T1."LineNum" and T1."IssueType" = 'B'
	 inner join OWOR T2 on T1."DocEntry" = T2."DocEntry" and T2."Type" = 'S'
	 inner join OIGE T3 on T3."DocEntry" = T0."DocEntry" and  ifnull(T3."VersionNum",'') < '09.10.000.00' 
	 union
	 ---Recalculation by OILM. DB was archived
	 select T0."DocEntry" from OILM T0
	 inner join UWOR1 T1 on T0."TransType" = 60 and T0."BaseType" = 202 and T0."AppObjAbs" = t1."DocEntry"
	 	and "AppObjLine" = T1."LineNum" and T1."IssueType" = 'B'
	 	and  ifnull(T0."VersionNum",'') < '09.10.000.00' 
	 inner join UWOR T2 on T1."DocEntry" = T2."DocEntry" and T2."Type" = 'S'
	 	and (select top 1 "Result" from LIVI1 order by "LogEntry" DESC) = 'A'
	 union
	 ----Dissasembly Components in Reciept for Production with IssueType backflush 
	 ----Recalculation by UILM or by OILM. DB was not archived
	 select T0."DocEntry" from OILM T0 
	 inner join WOR1 T1 on T0."TransType" = 59 and T0."BaseType" = 202 and T0."AppObjAbs" = T1."DocEntry" 
		and T0."AppObjLine" = T1."LineNum" and T1."IssueType" = 'B' 
	inner join OWOR T2 on T1."DocEntry" = T2."DocEntry" and T2."Type" = 'D' 
	union
	----Recalculation by OILM. DB was archived 
	select T0."DocEntry" from OILM T0 
	inner join UWOR1 T1 on T0."TransType" = 59 and T0."BaseType" = 202 and T0."AppObjAbs" = T1."DocEntry" 
		and T0."AppObjLine" = T1."LineNum" and T1."IssueType" = 'B' 
	inner join UWOR T2 on T1."DocEntry" = T2."DocEntry" and T2."Type" = 'D' 
		 and (select top 1 "Result" from LIVI1 order by "LogEntry" DESC) = 'A');
	 
	if :cnt > 0 then
		DBImpacted := 'Y'; 		     
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(1003)');		     
	end if;
	
/**
 * Au_D_1004_SBO_RSP_IVI_OILM.TotalLC_Is_zero & OILM.TotalSC_FC_Not_Zero_Detect 
 * Document amounts in local currency is zero but amounts in system of foreign currency are not zero
*/
	select count(1) into cnt from OILM t1 
	where  (select "LawsSet" from CINF) not in ( 'BR', 'IN' ) 
		and T1."ItemCode" in (select "ItemCode" from OITM where "InvntItem" = 'Y') 
		and T1."LocCode" not in (select "WhsCode" from OWHS where  "DropShip" = 'Y') 
		and t1."ExpensesLC" = 0 --- holds freights  
		and t1."ExpensesFC" = 0 --- holds freights  
		and t1."Price" = 0 
		and t1."TotalLC" = 0 
		and ( T1."TotalSC" <> 0 or t1."TotalFC" <> 0); 
						  
	if :cnt > 0 then 
		DBImpacted := 'Y'; 
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(1004)');
		---Au_D_1004_SBO_RSP_IVI_OILM.TotalLC_Is_zero & OILM.TotalSC_FC_Not_Zero_update 
	end if;  
end if;
---										End of Recalculation by OILM
-- ==================================================================================================
---									Start of Recalculation by OILM or UILM
---								The script which should be check in both case
/**
 * Au_D_2000_Transtype=58 -2 Pricecurr<>maincurr and Pricerate=0_Detect 
 * Document price in foreign currency but pricerate is zero
*/
	select count(1) into cnt from OILM T0
	where T0."TransType" in (58,-2) and ifnull("PriceCurr",'') <> :main_currency and "Price" <> 0 and "PriceRate" = 0;

	if :cnt > 0 then
    	DBImpacted := 'Y'; 
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(2000)');
		---Run Au_F_2000_Transtype=58 -2 Pricecurr<>maincurr and Pricerate=0_Update 
  	end if;

/**
 * Au_D_2005_OIVL_invntact_negstckact_missing 
 * 
*/
	select count(1) into cnt from OIVL where (ifnull("SumStock", 0) <> 0 and ifnull("InvntAct",'') = '') or
		ifnull("NegInvAdjs", 0) <> 0 and ifnull("NegStckAct", '') = '';	
   
  	if :cnt > 0 then
		DBImpacted := 'Y'; 
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(2005)');
		---Run Au_F_2005_OIVL_invntact_negstckact_missing 
	end if;  

/**
 * Au_D_2006_SBO_RSP_IVI_OILM.AppObjLine Is Not -1 
 * OILM.AppObjLine is not -1 for production father item
*/	
	select count(1) into cnt from OILM where "AppObjType" = 'P' and "AppObjLine" <> -1;
	
	if :cnt > 0 then
	  DBImpacted := 'Y'; 
	  insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(2006)'); 
	end if;

-------------------------------------------------End of Recalculation by OILM or UILM
if (:isArchived = 'N' or :StockIssue = 'Y') then
  	
  	/**
	 * Au_D_3001_Disorder in OJDT.CreateDate in relation to TransID_First_Detect
	 *
	 * Script detects journal entry X with createdate higher than createdate 
	 * of journal entry Y which was created later
	 * script detects as well Nulls in createdate
	*/
	OldTransID := -9999;
	OldCreateDate := '1900-01-01';
	DBImpacted := 'N';
	
	open zXCursor;
	fetch zXCursor into TransID, CreateDate, TransType, createdBy; 
	
	while not zXCursor::NOTFOUND do
	
		if :OldTransID < :TransID and 
			ifnull(:OldCreateDate, '1900-01-01') > ifnull(:CreateDate, '1900-01-01') then
			DBImpacted := 'Y';
			break;
		end if;
		
		OldTransID := :TransID;
		OldCreateDate := :CreateDate;
		OldTransType := :TransType;
		OldcreatedBy := :createdBy;
		
		fetch zXCursor into TransID, CreateDate, TransType, createdBy;
	end while;
	close zXCursor;
	
	if :DBImpacted = 'Y' then 
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(3001)');
    end if;
	
 	/**
	 * Au_D_3002_Disorder In Documents
	 *
	 * 
	*/
	delete from "TmSp_IVSR_AHRQ_Disorder_detect_DocTables"; 
	DBImpacted := 'N'; 

	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OINV');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('ORIN');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OCSI');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OCSV');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('ODLN');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('ORDN');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OPCH');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('ORPC');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OCPI');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OCPV');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OPDN');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('ORPD');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OIGN');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OIGE');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OWTR');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OIPF');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OIQI');
	insert into "TmSp_IVSR_AHRQ_Disorder_detect_DocTables" values('OIQR');

	open typesCur;
	fetch typesCur into DocTable;

	while not typesCur::NOTFOUND do		
		
		delete from "TmSp_IVSR_AHRQ_Disorder_detect_record_found";
		
		sqlStr := 'insert into "TmSp_IVSR_AHRQ_Disorder_detect_record_found" select count(1) from ' || :DocTable ||
			' T0 inner join ' || :DocTable || ' T1 on T0."DocEntry" = T1."DocEntry" - 1 ' ||
			' where T0."CreateDate" > T1."CreateDate" or (T0."CreateDate" = T1."CreateDate" and T0."DocTime" > T1."DocTime")';
	
		exec(:sqlStr);
	    
		/*DB is impacted*/
		select top 1 "rec" into cnt from "TmSp_IVSR_AHRQ_Disorder_detect_record_found";
		
		if :cnt > 0 then
			DBImpacted := 'Y';
			break;
		end if;

		fetch typesCur into DocTable;
	end while;
	close typesCur;

	delete from "TmSp_IVSR_AHRQ_Disorder_detect_record_found";
	delete from "TmSp_IVSR_AHRQ_Disorder_detect_DocTables";

	if :DBImpacted = 'Y' then 
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(3002)');
    end if;

	/**
	 * Au_D_3003_Disorders in OILM and without Journal Entry Step 2 _Detect
	 *
	 * 
	*/
	delete from "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE";
	delete from "TmSp_IVSR_AHRQ_DISORDER_OJDTTemp";

	/* collect the OILM Records without JE */
	insert into "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE" 
	select distinct "DocEntry", "TransType", "CreateDate" 
	from   OILM T0 
	where  T0."TransType" not in (-2,58,202,68,165,166) 
		and T0."AccumType" = 1 
		and T0."ActionType" not in (9,10)
		and not exists (select 1 from   OJDT T1 
						where  T1."TransType" = T0."TransType" and T1."CreatedBy" = T0."DocEntry"); 
								 
	insert into "TmSp_IVSR_AHRQ_DISORDER_OJDTTemp"
	select DISTINCT "TransType", max("CreatedBy") as "CreatedBy", "CreateDate" 
	from OJDT T1
	where "TransType" in (select DISTINCT "TransType" from "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE")
		and NOT ( ( T1."TransType" = 20
								AND ifnull(( SELECT "TransId"
											 FROM   OPDN T3
											 WHERE  T3."DocEntry" = T1."CreatedBy"
										   ), -1) <> T1."TransId"
							  )
							  OR ( T1."TransType" = 21
								   AND ifnull(( SELECT  "TransId"
												FROM    ORPD T3
												WHERE   T3."DocEntry" = T1."CreatedBy"
											  ), -1) <> T1."TransId"
								 )
							)
	 group by "TransType","CreateDate";
	 
	 insert into "TmSp_IVSR_AHRQ_DISORDER_OJDTTemp"
	 select DISTINCT "TransType", min("CreatedBy") as "CreatedBy", "CreateDate" 
	 from OJDT T1
	 where "TransType" in (select DISTINCT "TransType" from "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE")
	 and NOT ( ( T1."TransType" = 20
								AND ifnull(( SELECT "TransId"
											 FROM   OPDN T3
											 WHERE  T3."DocEntry" = T1."CreatedBy"
										   ), -1) <> T1."TransId"
							  )
							  OR ( T1."TransType" = 21
								   AND ifnull(( SELECT  "TransId"
												FROM    ORPD T3
												WHERE   T3."DocEntry" = T1."CreatedBy"
											  ), -1) <> T1."TransId"
								 )
							)
	 group by "TransType", "CreateDate";

	-- Creation of indexes is skipped, because current revision doesn't support it
		 
	-------------------------------------------------------------------- 
	select count(1) into cnt 
	from "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE" T0 
 	join "TmSp_IVSR_AHRQ_DISORDER_OJDTTemp" T1 on T1."TransType" = T0."TransType" 
 		AND T1."CreatedBy" < T0."DocEntry" AND T1."CreateDate" > T0."CreateDate";
 	
 	if :cnt = 0 then
 		select count(1) into cnt from "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE" T0 
 		join "TmSp_IVSR_AHRQ_DISORDER_OJDTTemp" T1
 		on T1."TransType" = T0."TransType" AND T1."CreatedBy" > T0."DocEntry" AND T1."CreateDate" < T0."CreateDate";
 	end if;	
 	
 	if :cnt > 0 then
		DBImpacted := 'Y';
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(3003)');
	end if;
		
	delete from "TmSp_IVSR_AHRQ_DISORDER_OJDTTemp";
	delete from "TmSp_IVSR_AHRQ_DISORDER_OILM_WITHOU_JE";

-- end of if (@isArchived = 'N' or @88stockissue = 'Y')
end if;
-- AU_F 3004 should be at last to fix the OILM.CreateDate disorder issues after 3001~3003 fix other CreateDate disorder issue 
if (:Recalc_By_OILM = 'Y' or :StockIssue = 'Y') then 
/**
 * Au_D_3004_SBO_RSP_IVI_Disorder_In_OILM_between_CreateDate&MessageID_Detect 
 *	
 *
*/	
	OldMessageID_1 := -9999;
	OldCreateDate_1 := '1900-01-01'; 
	DBImpacted := 'N'; 

	open zXCursor2;
	fetch zXCursor2 into MessageID_1, CreateDate_1, CreateTime_1; 
	
	while not zXCursor2::NOTFOUND do
			
		if (( :OldMessageID_1 < :MessageID_1 ) 
			   and (( ifnull(:OldCreateDate_1, '1900-01-01') > ifnull(:CreateDate_1, '1900-01-01')) 
					  or ( ifnull(:OldCreateDate_1, '1900-01-01') = ifnull(:CreateDate_1, '1900-01-01') 
						  /* + 1 stands for sync time tolerance is 1 minute  */
						  and (ifnull(:OldCreateTime_1, 0) > ifnull(:CreateTime_1, 0) + 1) 
						    /*The case to the last minute of an hour, i.e., :OldCreateTime 10:00, :CreateTime 9:59 */
							and not (MOD (ifnull(:OldCreateTime_1, 0), 100) = 0 and MOD (ifnull(:CreateTime_1, 0), 100) = 59 and ifnull(:OldCreateTime_1, 0) / 100 - ifnull(:CreateTime_1, 0) / 100 = 1)))) then
			DBImpacted := 'Y';
			break;
		end if;
		
		OldMessageID_1 := :MessageID_1;
		OldCreateDate_1 := :CreateDate_1;
		OldCreateTime_1 := :CreateTime_1;
		
		fetch zXCursor2 into MessageID_1, CreateDate_1, CreateTime_1;
	end while;
	close zXCursor2;

	if :DBImpacted = 'Y' then
		insert into "TmSp_IVSR_AHRQ_CheckStockResults" values (N'DB is affected(3004)');
	end if;

-- end of if (:Recalc_By_OILM = 'Y' or :StockIssue = 'Y')
end if;

	select * from "TmSp_IVSR_AHRQ_CheckStockResults";
end;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_IVSR_Check_DB_Candidate_For_IVI
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
AS
	StockIssue varchar(1) := 'N';
	tmpEntry int;
	
BEGIN
	-----------------------Start of special handle process for task 13458  CSN Note 1436758-------------------------
/* Detect if the database is affected by bug of task 13458 */
/* also detect if the database is affected by the 88 missing stock message */
/* this Part is similiar with Status sql, if change, please check Status sql also.*/
	-------------------------------------------------------------------------------- 
/* 1 odln*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   dln1 t0 
	           INNER JOIN odln t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y'
	                AND t1."UpdInvnt" <> 'N'
	                AND t0."DocEntry" = t1."DocEntry"
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	           LEFT JOIN dln14 t2
	             ON t0."TreeType" = 'A' 
	                AND t0."DocEntry" = t2."DocEntry" 
	                AND t0."LineNum" = t2."LineNum" 
	           INNER JOIN owhs t3 
	             ON t3."WhsCode" = CASE IFNULL(t2."DocEntry", -1) 
	                               WHEN -1 THEN t0."WhsCode" 
	                               ELSE t2."WhsCode" 
	                             END 
	                AND t3."DropShip" <> 'Y' 
	           INNER JOIN oitm t4 
	             ON t4."ItemCode" = CASE IFNULL(t2."DocEntry", -1) 
	                                WHEN -1 THEN t0."ItemCode" 
	                                ELSE t2."ItemCode" 
	                              END 
	                AND t4."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 15 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."SubLineNum" = IFNULL(t2."ChildNum", -1) 
	                                     AND u0."AccumType" = 1);
										 
	IF :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
	--------------------------------------------------------------------------------  
/* 2 ordn*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   rdn1 t0 
	           INNER JOIN ordn t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	           LEFT JOIN rdn14 t2 
	             ON t0."TreeType" = 'A' 
	                AND t0."DocEntry" = t2."DocEntry" 
	                AND t0."LineNum" = t2."LineNum" 
	           INNER JOIN owhs t3 
	             ON t3."WhsCode" = CASE IFNULL(t2."DocEntry", -1) 
	                               WHEN -1 THEN t0."WhsCode" 
	                               ELSE t2."WhsCode" 
	                             END 
	                AND t3."DropShip" <> 'Y' 
	           INNER JOIN oitm t4 
	             ON t4."ItemCode" = CASE IFNULL(t2."DocEntry", -1) 
	                                WHEN -1 THEN t0."ItemCode" 
	                                ELSE t2."ItemCode" 
	                              END 
	                AND t4."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 16 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."SubLineNum" = IFNULL(t2."ChildNum", -1) 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	then
	    StockIssue := 'Y'; 
	END if;
	
	--------------------------------------------------------------------------------  
/* 3 oinv*/ 
	SELECT count(t0."DocEntry") into tmpEntry 
	    FROM   inv1 t0 
	           INNER JOIN oinv t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	                AND t1."isIns" = 'N' 
	           LEFT JOIN inv14 t2 
	             ON t0."TreeType" = 'A' 
	                AND t0."DocEntry" = t2."DocEntry" 
	                AND t0."LineNum" = t2."LineNum" 
	           INNER JOIN owhs t3 
	             ON t3."WhsCode" = CASE IFNULL(t2."DocEntry", -1) 
	                               WHEN -1 THEN t0."WhsCode" 
	                               ELSE t2."WhsCode" 
	                             END 
	                AND t3."DropShip" <> 'Y' 
	           INNER JOIN oitm t4 
	             ON t4."ItemCode" = CASE IFNULL(t2."DocEntry", -1) 
	                                WHEN -1 THEN t0."ItemCode" 
	                                ELSE t2."ItemCode" 
	                              END 
	                AND t4."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 13 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."SubLineNum" = IFNULL(t2."ChildNum", -1) 
	                                     AND u0."AccumType" IN ( 1, 4 ));
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then 
	      StockIssue := 'Y'; 
	  END if;
	
	--------------------------------------------------------------------------------  
/* 4 orin*/ 
 SELECT count(t0."DocEntry") into tmpEntry
	    FROM   rin1 t0 
	           INNER JOIN orin t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."BaseType" not in (16 ,203)
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	           INNER JOIN oinv t5 
	             ON t0."BaseEntry" = t5."DocEntry"
	                AND t0."BaseType" = t5."ObjType" 
	                AND t5."isIns" = 'N' 
	                AND t5."DocType" = 'I' 
	           LEFT JOIN rin14 t2 
	             ON t0."TreeType" = 'A' 
	                AND t0."DocEntry" = t2."DocEntry" 
	                AND t0."LineNum" = t2."LineNum" 
	           INNER JOIN owhs t3 
	             ON t3."WhsCode" = CASE IFNULL(t2."DocEntry", -1) 
	                               WHEN -1 THEN t0."WhsCode" 
	                               ELSE t2."WhsCode" 
	                             END 
	                AND t3."DropShip" <> 'Y' 
	           INNER JOIN oitm t4 
	             ON t4."ItemCode" = CASE IFNULL(t2."DocEntry", -1) 
	                                WHEN -1 THEN t0."ItemCode" 
	                                ELSE t2."ItemCode" 
	                              END 
	                AND t4."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 14 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."SubLineNum" = IFNULL(t2."ChildNum", -1) 
	                                     AND u0."AccumType" IN (0, 1) );
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then 
	      StockIssue := 'Y'; 
	  END if;
	
	--------------------------------------------------------------------------------  
/* 5 opdn*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   pdn1 t0 
	           INNER JOIN opdn t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 20 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  end if; 
	-------------------------------------------------------------------------------- 
/* 6 orpd*/ 
/*AP Return*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   rpd1 t0 
	           INNER JOIN orpd t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 21 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
	--------------------------------------------------------------------------------  
/* 8 opch*/
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   pch1 t0 
	           INNER JOIN opch t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	                AND t1."isIns" = 'N' 
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 18 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
	
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
	--------------------------------------------------------------------------------  
/* 9 orpc*/ 
/*AP Credit Memo*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   rpc1 t0 
	           INNER JOIN orpc t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND t0."BaseType" not in (21 ,204)
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	           INNER JOIN opch t4 
	             ON t0."BaseEntry" = t4."DocEntry"
	                AND t0."BaseType" = t4."ObjType" 
	                AND t4."isIns" = 'N' 
	                AND t4."DocType" = 'I' 
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 19 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
/* 10 oipf*/ 
/*Landed costs*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   ipf1 t0 
	           INNER JOIN oipf t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= ( CASE (SELECT "ContInvnt" FROM oadm) 
	                                                     WHEN 'Y' THEN '08.80.000.00' 
	                                                     ELSE '08.80.225.06' 
	                                                   END ) 
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 69 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
/* 11 oign*/ 
/*Goods Receipt*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   ign1 t0 
	           INNER JOIN oign t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00'
					INNER JOIN OITM t2 on t0."ItemCode" = t2."ItemCode" and t2."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 59 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
/* 12 Goods Receipt for backflush components*/ 
/*Goods Receipt for backflush components    
e.g. when receipt from production order and bom with backflush components(N.B.by product is permitted),    
besides register message of bom itself, we will register message for component, this query     
is to detect the existance of message of component    
-- This is relevant for versions below 9.1, from 9.1 all components are issued via issue for production only 
*/ 

	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   ign1 t0 
	           INNER JOIN oign t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND t0."BaseType" = 202 
	                AND IFNULL(t0."BaseLine", -1) = -1 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00'
	                AND IFNULL(t1."VersionNum", '') < '09.10.000.00' 
	           INNER JOIN owor t2 
	             ON t0."BaseEntry" = t2."DocEntry" 
	           INNER JOIN wor1 t3 
	             ON t0."BaseEntry" = t3."DocEntry" 
	                AND t3."IssueType" = 'B' 
	           INNER JOIN owhs t7 
	             ON t7."WhsCode" = t3."wareHouse" 
	                AND t7."DropShip" <> 'Y' 
	           INNER JOIN oitm t8 
	             ON t8."ItemCode" = t3."ItemCode" 
	                AND t8."InvntItem" = 'Y' 
	    WHERE  t3."LineNum" NOT IN (SELECT "AppObjLine" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 59 
	                                     AND u0."BaseType" = 202 
	                                     AND u0."AppObjAbs" = t3."DocEntry" 
	                                     AND u0."AppObjLine" = t3."LineNum" 
	                                     AND u0."AccumType" = 1 
	                                     AND (u0."AppObjType" in ('C', 'B')));
												
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
/* 13 oige*/ 
/*Goods Issue*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   ige1 t0 
	           INNER JOIN oige t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
					INNER JOIN OITM t2 on t0."ItemCode" = t2."ItemCode" and t2."InvntItem" = 'Y'
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 60 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  end if;
	
/* 14 Goods Issue for backflush components*/ 
/*Goods Issue for backflush components    
e.g. when receipt from production order and bom with backflush components(N.B.by product is not permitted),    
besides register message of bom itself, we will register message for component, this query     
is to detect the existance of message of component 
-- This is relevant for versions below 9.1, from 9.1 all components are issued via issue for production only   
*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   ige1 t0 
	           INNER JOIN oige t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND t0."BaseType" = 202 
	                AND IFNULL(t0."BaseLine", -1) = -1 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND IFNULL(t1."VersionNum", '') < '09.10.000.00' 
	           INNER JOIN owor t2 
	             ON t0."BaseEntry" = t2."DocEntry" 
	           INNER JOIN wor1 t3 
	             ON t0."BaseEntry" = t3."DocEntry" 
	                AND t3."IssueType" = 'B' 
	           INNER JOIN owhs t7 
	             ON t7."WhsCode" = t3."wareHouse" 
	                AND t7."DropShip" <> 'Y' 
	           INNER JOIN oitm t8 
	             ON t8."ItemCode" = t3."ItemCode" 
	                AND t8."InvntItem" = 'Y' 
	    WHERE  t3."LineNum" NOT IN (SELECT "AppObjLine" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 60 
	                                     AND u0."BaseType" = 202 
	                                     AND u0."AppObjAbs" = t3."DocEntry" 
	                                     AND u0."AppObjLine" = t3."LineNum" 
	                                     AND u0."AccumType" = 1 
	                                     AND u0."AppObjType" = 'C');
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
/* 15 owtr*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   wtr1 t0 
	           INNER JOIN owtr t1 
	             ON t0."DocEntry" = t1."DocEntry" and T0."Quantity" <> 0
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 67 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1) 
	            OR t0."WhsCode" NOT IN (SELECT u1."LocCode" 
	                                  FROM   oilm u1 
	                                  WHERE  u1."TransType" = 67 
	                                         AND u1."DocEntry" = t0."DocEntry" 
	                                         AND u1."DocLineNum" = t0."LineNum" 
	                                         AND u1."AccumType" = 1) 
	            OR t0."FromWhsCod" NOT IN (SELECT u2."LocCode" 
	                                 FROM   oilm u2 
	                                 WHERE  u2."TransType" = 67 
	                                        AND u2."DocEntry" = t0."DocEntry" 
	                                        AND u2."DocLineNum" = t0."LineNum" 
	                                        AND u2."AccumType" = 1);
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
/* 16 oiqi*/ 
/*Initial Quantity*/ 
/*VersionNum < 9.00*/
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   IQI1 t0 
				   INNER JOIN OIQI t1 
					 ON t0."DocEntry" = t1."DocEntry" 
						AND IFNULL(t1."VersionNum",'') >= '08.80.000.00' 
				   INNER JOIN OITM t2 on t0."ItemCode" = t2."ItemCode" and t2."InvntItem" = 'Y'
                    WHERE NOT EXISTS (SELECT 1 FROM OILM u0 
                                                      WHERE u0."TransType" = 310000001 
                                                              AND u0."AccumType" = 1
                                                              AND u0."ItemCode" = t0."ItemCode"
                                                              AND u0."LocCode" = t0."WhsCode"
                                                              AND u0."DocEntry" = t0."DocEntry");
											
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
	
/* 17 oiqr*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   IQR1 t0 
				   INNER JOIN OIQR t1 
					 ON t0."DocEntry" = t1."DocEntry" 
						AND IFNULL(t1."VersionNum",'') >= '08.80.000.00' 
						AND t0."Quantity" <> 0 
				   INNER JOIN OITM t2 on t0."ItemCode" = t2."ItemCode" and t2."InvntItem" = 'Y'
                    WHERE NOT EXISTS (SELECT 1 FROM OILM u0 
                                                      WHERE u0."TransType" = 10000071 
                                                              AND u0."AccumType" = 1
                                                              AND u0."ItemCode" = t0."ItemCode"
                                                              AND u0."LocCode" = t0."WhsCode"
                                                              AND u0."DocEntry" = t0."DocEntry");
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;

/* 18 omrv*/ 
/*Material Revaluation for moving average, standard item*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   mrv1 t0 
	           INNER JOIN omrv t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t0."EvalSystem" IN ( 'A', 'S' )
				INNER JOIN OITM t2 on t0."ItemCode" = t2."ItemCode" and t2."InvntItem" = 'Y'
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 162 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
	
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	      StockIssue := 'Y'; 
	  END if;
/* 19 OMRV fifo*/ 
/*Material Revaluation for FIFO item*/
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   mrv2 t0 
	           INNER JOIN omrv t1 
	             ON t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum",'') >= '08.80.000.00'
					INNER JOIN MRV1 t2 on t0."DocEntry" = t2."DocEntry"
					INNER JOIN OITM t3 on t3."ItemCode" = t2."ItemCode" and t3."InvntItem" = 'Y'
	    WHERE  t0."LineNum" NOT IN (SELECT u0."SubLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 162 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."BaseLine" 
	                                     AND u0."SubLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	    StockIssue := 'Y'; 
	  END if;
	  
/* 20 AR Correction Invoice*/  
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   (SELECT shb."DocEntry",
				shb."LineNum",
				shb."ItemCode",
				(shb."Quantity" + was."Quantity") AS "Quantity",
				shb."UpdInvntry",
				shb."TreeType",
				shb."WhsCode"
			FROM csi1 shb
			INNER JOIN csi1 was ON
				shb."CEECFlag" = 'S' and
				was."CEECFlag" = 'W' and
				was."DocEntry" = shb."DocEntry" and
				was."LineNum" = shb."CiOppLineN"
			) t0 
	           INNER JOIN ocsi t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum",'') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	                AND T1."isIns" = 'N'
	           LEFT JOIN csi14 t2 
	             ON t0."TreeType" = 'A' 
	                AND t0."DocEntry" = t2."DocEntry" 
	                AND t0."LineNum" = t2."LineNum" 
	           INNER JOIN owhs t3 
	             ON t3."WhsCode" = CASE IFNULL(t2."DocEntry", -1) 
	                               WHEN -1 
	                               THEN t0."WhsCode" 
	                               ELSE t2."WhsCode" 
	                             END 
	                AND t3."DropShip" <> 'Y' 
	           INNER JOIN oitm t4 
	             ON t4."ItemCode" = CASE IFNULL(t2."DocEntry",-1) 
	                                WHEN -1 
	                                THEN t0."ItemCode" 
	                                ELSE t2."ItemCode" 
	                              END 
	                AND t4."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 165 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."SubLineNum" = IFNULL(t2."ChildNum", -1) 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	    	StockIssue := 'Y'; 
	  END if;
	  
/* 21 AR Correction Invoice Reversal*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   (SELECT shb."DocEntry",
				shb."LineNum",
				shb."ItemCode",
				(shb."Quantity" + was."Quantity") AS "Quantity",
				shb."UpdInvntry",
				shb."TreeType",
				shb."WhsCode"
			FROM csv1 shb
			INNER JOIN csv1 was ON
				shb."CEECFlag" = 'S' and
				was."CEECFlag" = 'W' and
				was."DocEntry" = shb."DocEntry" and
				was."LineNum" = shb."CiOppLineN"
			) t0 
	           INNER JOIN ocsv t1 
	             ON t0."Quantity" <> 0 
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum",'') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	                AND t1."isIns" = 'N'
	           LEFT JOIN csv14 t2 
	             ON t0."TreeType" = 'A' 
	                AND t0."DocEntry" = t2."DocEntry" 
	                AND t0."LineNum" = t2."LineNum" 
	           INNER JOIN owhs t3 
	             ON t3."WhsCode" = CASE IFNULL(t2."DocEntry",-1) 
	                               WHEN -1 
	                               THEN t0."WhsCode" 
	                               ELSE t2."WhsCode" 
	                             END 
	                AND t3."DropShip" <> 'Y' 
	           INNER JOIN oitm t4 
	             ON t4."ItemCode" = CASE IFNULL(t2."DocEntry",-1) 
	                                WHEN -1 
	                                THEN t0."ItemCode" 
	                                ELSE t2."ItemCode" 
	                              END 
	                AND t4."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 166 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."SubLineNum" = IFNULL(t2."ChildNum",-1) 
	                                     AND u0."AccumType" = 1);
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	    	StockIssue := 'Y'; 
	  END if;
	  
/* 22 AP Correction Invoice*/ 
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   (SELECT shb."DocEntry",
				shb."LineNum",
				shb."ItemCode",
				(shb."Quantity" + was."Quantity") AS "Quantity",
				(shb."StockSum" + was."StockSum") as "StockSum",
				shb."UpdInvntry",
				shb."TreeType",
				shb."WhsCode"
			FROM cpi1 shb
			INNER JOIN cpi1 was ON
				shb."CEECFlag" = 'S' and
				was."CEECFlag" = 'W' and
				was."DocEntry" = shb."DocEntry" and
				was."LineNum" = shb."CiOppLineN"
			) t0 
	           INNER JOIN ocpi t1 
	             ON (t0."Quantity" <> 0 or t0."StockSum" <> 0)
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum",'') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	                AND t1."isIns" = 'N'
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 163 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	  		StockIssue := 'Y'; 
	  END if;
	  
/* 23  AP Correction Invoice Reversal*/ 
/*AP Correction Invoice Reversal*/
	SELECT count(t0."DocEntry") into tmpEntry
	    FROM   (SELECT shb."DocEntry",
				shb."LineNum",
				shb."ItemCode",
				(shb."Quantity" + was."Quantity") AS "Quantity",
				(shb."StockSum" + was."StockSum") as "StockSum",
				shb."UpdInvntry",
				shb."TreeType",
				shb."WhsCode"
			FROM cpv1 shb
			INNER JOIN cpv1 was ON
				shb."CEECFlag" = 'S' and
				was."CEECFlag" = 'W' and
				was."DocEntry" = shb."DocEntry" and
				was."LineNum" = shb."CiOppLineN"
			) t0 
	           INNER JOIN ocpv t1 
	             ON (t0."Quantity" <> 0 or t0."StockSum" <> 0)
	                AND t0."UpdInvntry" = 'Y' 
	                AND t1."UpdInvnt" <> 'N' 
	                AND t0."DocEntry" = t1."DocEntry" 
	                AND IFNULL(t1."VersionNum", '') >= '08.80.000.00' 
	                AND t1."DocType" = 'I' 
	                AND T1."isIns" = 'N'
	           INNER JOIN owhs t2 
	             ON t2."WhsCode" = t0."WhsCode" 
	                AND t2."DropShip" <> 'Y' 
	           INNER JOIN oitm t3 
	             ON t3."ItemCode" = t0."ItemCode" 
	                AND t3."InvntItem" = 'Y' 
	    WHERE  t0."LineNum" NOT IN (SELECT u0."DocLineNum" 
	                              FROM   oilm u0 
	                              WHERE  u0."TransType" = 164 
	                                     AND u0."DocEntry" = t0."DocEntry" 
	                                     AND u0."DocLineNum" = t0."LineNum" 
	                                     AND u0."AccumType" = 1);
										 
	IF :StockIssue <> 'Y' and :tmpEntry > 0 
	  then
	  		StockIssue := 'Y'; 
	  END if;
	-----------------------End of special handle process for task 13458-------------------------
	IF :StockIssue = 'Y' then
		SELECT 'Stock issues exists in the DB.  IVI need to be used.' As "Errors" FROM DUMMY;
	ELSE
		SELECT ' ' As "Errors" FROM DUMMY Where 1 <> 1;
	END IF;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2
--Due to the structure of HANA store procedure? IVI_SupportInteractionRequiredQuery_Sub1 is hard to migrate into TmSp_IVSR_SupportInteractionRequiredQuery, 
--so the error codes 515 and 260 are hard to add into IVSR.

CREATE PROCEDURE TmSp_IVSR_SupportInteractionRequiredQuery
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
openQty	 DECIMAL(21,6);
qtySum DECIMAL(21,6);
transNum int;
instance int;
lastTransNum int;
lastInstance int;
qty_decimals int;
sum_decimals int;
Main_Currency nvarchar(3);
DB_Impacted nvarchar(1);
Recalc_By_OILM nvarchar(1);
roundmthd nvarchar(1);
OCRNdeciamls int;
directrate nvarchar(1); 
Update_before nvarchar(1);
DBImpacted nvarchar(1);
stockissue nvarchar(1);
firstTranstionDate datetime;
cha TIMESTAMP;
rowcount int;
rownum int;
rowcount1 int;
count1 integer;
count2 integer;						
stockissue88 char(1);					   
rownum1 int;
isExist INTEGER;
ver91PL02 integer;
ver90PL06 integer;

sqlStr VARCHAR(40000);
cmpVersionNum integer;
max07Msg integer;
temp_var_0 integer;
Min_526_Reorder TIMESTAMP;
Max_526_Reorder TIMESTAMP;
hasActualCostingItems char;



BEGIN

	DELETE from "TMP_IVSR_SupInterReq_Results";
	rowcount := 0;

	firstTranstionDate := '1950-01-01'; 
	select "QtyDec" into qty_decimals from "OADM";
	select "SumDec" into sum_decimals from "OADM";
	select "MainCurncy" into main_currency from "OADM";
	select "RoundMthd" into roundmthd from "OADM";
	select "Decimals" into OCRNdeciamls from ocrn where "CurrCode" = :main_currency;
	select "DirectRate" into directrate from "OADM";
	SELECT "Version" INTO cmpVersionNum FROM "CINF";

	select COUNT(1) INTO rowcount from livi where "UpdateDate" is not null;
	if :rowcount = 1 then 
		Update_before := 'Y';
	else 
		Update_before := 'N';
	end if;
	if :roundmthd = 'Y' and :OCRNdeciamls <> -1 then
		sum_decimals := :OCRNdeciamls;
	end if;

	SELECT COUNT(1) INTO rowCount FROM "CIVI" WHERE "ReorderFrm" IS NULL;
	IF :rowCount = 1 THEN 
		stockissue88 := 'N';
	ELSE 
		stockissue88 := 'Y';
	END IF;																	  
	-- ==================================================================================================
	-- ==================================================================================================
	-- ==================================================================================================
	--							SOURCE: IVI_SupportInteractionRequiredQuery.sql
	-- ==================================================================================================

------------------------------------------------------------------
/* Recalculation BY OILM & recalculation BY UILM _ Shared part*/
------------------------------------------------------------------
/**
 * Supp_310_Item is defined as Assembly/Sales bom AND as an inventory item
 *
 * 
*/	
	select COUNT(1) INTO rowcount
	from  "OITM" t0
	where "TreeType" in ( 'A', 'S' ) and "InvntItem" = 'Y';
	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 310');
	
	end if;

/**
 * Supp_401_Evaluation system IN MRV is incorrect
 *
 * Scripts detects MRV1.Evalsystem which holds the value 'N'
	*/
	select COUNT(1) INTO rowcount from "MRV1" where "EvalSystem" = 'N';
	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 401.');
	
	end if;

 /**
 * Supp_501_Rate is zero when Price Currency is FC_for_-2_58_OILM_UILM
 * --- Rate is zero when Price Currency is FC, FROM 400 query
 * Since TransType 58,-2 will be copied FROM OILM to UILM directly during reorder step,
 * it is necessary to have the same check for these 2 TransTypes IN "BY uilm" as "BY OILM" IN support query.
 * 
*/
	SELECT COUNT(t0."MessageID") into rowcount 
	FROM   "OILM" t0 
	INNER JOIN "OITM" t1 ON t0."AccumType" = 1 
	                     AND t0."ItemCode" = t1."ItemCode" 
						 AND t1."InvntItem" = 'Y' 								   
		AND "LocCode" NOT IN (SELECT "WhsCode" FROM "OWHS" WHERE  "DropShip" = 'Y') 
		AND t0."Price" <> 0 
		AND IFNULL(t0."PriceCurr",'') <> :Main_Currency 
		AND IFNULL(t0."PriceRate",0) = 0 
		AND (t0."TransType" IN (-2,58) 
			AND t0."ActionType" <> 2);

	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 501.');
	
	end if;

/**
 * Supp_502_TotalLC is zero AND TotalSC/TotalFC NOT zero_for_-2_58_OILM_UILM
 * --- TotalLC is zero AND TotalSC/TotalFC NOT zero, FROM 400 query
 * Since TransType 58,-2 will be copied FROM OILM to UILM directly during reorder step,
 * it is necessary to have the same check for these 2 TransTypes IN "BY uilm" as "BY OILM" IN support query.
 * 
*/  
	SELECT COUNT(t0."MessageID") INTO rowcount
	FROM   "OILM" t0 
	INNER JOIN "OITM" t1 ON t0."AccumType" = 1 
	                     AND t0."ItemCode" = t1."ItemCode" 
						 AND t1."InvntItem" = 'Y' 										
		AND "LocCode" NOT IN (SELECT "WhsCode" FROM "OWHS" WHERE  "DropShip" = 'Y') 
		AND IFNULL(t0."TotalLC",0) = 0 -- TotalLC is zero and TotalSC/TotalFC not zero 
		AND (IFNULL(t0."TotalSC",0) <> 0 
			OR IFNULL(t0."TotalFC",0) <> 0) 
		AND (t0."TransType" IN (-2,58) 
			AND t0."ActionType" <> 2);

	IF :rowcount > 0 then 
		DB_Impacted := 'Y'; 
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 502.');
	
	end if; 
/**
 * Supp_503_TotalLC_is_zero_AND_Price/EffectQty_not_zero_for_-2_58_OILM_UILM
 * --- TotalLC_is_zero_AND_Price/EffectQty_not_zero, FROM 400 query
 * Since TransType 58,-2 will be copied FROM OILM to UILM directly during reorder step,
 * it is necessary to have the same check for these 2 TransTypes IN "BY uilm" as "BY OILM" IN support query.
 * 
*/										
	SELECT COUNT(t0."MessageID") INTO rowcount 
	FROM   "OILM" t0 
	INNER JOIN "OITM" t1 ON t0."AccumType" = 1 
	                  AND t0."ItemCode" = t1."ItemCode" 
					  AND t1."InvntItem" = 'Y'
					  AND "LocCode" NOT IN (SELECT "WhsCode" FROM "OWHS" WHERE  "DropShip" = 'Y') 
					  AND IFNULL(t0."Price",0) <> 0 --- TotalLC is zero and Price/EffectQty not zero in OILM 
					AND IFNULL(t0."TotalLC",0) = 0 
					AND (t0."TransType" IN (-2,58) 
					AND t0."ActionType" <> 2) 
					AND Round(t0."Price" * t0."Quantity",:sum_decimals) <> 0;

	IF  :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 503.');		     
	END IF;


/**
 * Supp_1_18_Missing Header - Documents lines with no header
 * except WKO WOR MRV part
 * 
*/	  
	--WKO
	SELECT count(T0."OrderNum") into rowcount
	FROM   "WKO1" T0
	INNER JOIN "OITM" T1 ON T0."ItemCode" = T1."ItemCode"
		and T1."InvntItem" = 'Y'
	WHERE  T0."OrderNum" not in ( Select "OrderNum" from   "OWKO" );

	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 15.');		     
	end if;
	--WOR
	SELECT count(T0."DocEntry") into rowcount
	FROM   "WOR1" T0
	INNER JOIN "OITM" T1 ON T0."ItemCode" = T1."ItemCode" and T1."InvntItem" = 'Y'
	WHERE  T0."DocEntry" not in ( Select "DocEntry" from   "OWOR" );

	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 17.');
	end if;

	--MRV
	SELECT count(T0."DocEntry") into rowcount
	FROM   "MRV1" T0
	INNER JOIN "OITM" T1 ON T0."ItemCode" = T1."ItemCode"
		and T1."InvntItem" = 'Y'
	WHERE  T0."DocEntry" not in ( Select "DocEntry" from "OMRV" );

	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 18.');
	end if;


/**
 * Supp_19_37_Missing rows IN documents - Document header with no rows
 *
 * Documents with freights only will be ignored since it is a valid document
 * WKO WOR MRV part
*/	 
	--WKO
	SELECT count(T0."OrderNum") into rowcount
	FROM   OWKO T0
	WHERE  T0."OrderNum" not in ( Select "OrderNum" from WKO1 );

	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 34.');
	end if;

	--WOR
	select COUNT(t0."DocEntry") INTO rowcount
	from   "OWOR" t0 
	where  t0."DocEntry" not in (select "DocEntry" from   "WOR1") 
		and (exists (select 1 from   "IGN1" t1 where  t1."BaseEntry" = t0."DocEntry") 
			or exists (select 1 from   "IGE1" t2 where  t2."BaseEntry" = t0."DocEntry"));
		
	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 35.');
	end if; 
	--MRV

	SELECT count(T0."DocEntry") into rowcount
	FROM   "OMRV" T0
	WHERE  T0."DocEntry" not in ( Select "DocEntry" from   "MRV1" );

	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 37.');
	end if;
/**
*	Supp_180 ~ 183
*	
*	First Scenario: 
*
*	The root cause is incorrect upgrade IN CSN 3408870 2006 (2005B) OR similar fix IN 2007AC
*
*	This fix meant to switch OWOR primary key FROM   OWOR.Docnum to OWOR.DocEntry.
*	Part of the upgrade was switching IGN1/IGE1.BaseEntry  & OINM.Appobjabs FROM reference to OWOR.Docnum INTO reference to OWOR.DocEntry.
*	As a result of a bug, the IGN/IGE.BaseEntry was incorrectly linked to a different OWOR.
*
*	e.g.:
*	The IGN DocEntry 1245 which is a receipt for production order DocEntry 621 was incorrectly linked to a different production order.
*	IGN1.BaseEntry is 46 AND the baseref is 621, which is wrong (46 is DocEntry of  production order docnum 621).
*
*	Second Scenario (Identified only once IN an extremely corrupted db):
*
*	Base entry for all lines is incorrect
*	IGN1 is based on production orders 1-25
*	When drawing these 25 production orders INTO ign, production orders were grouped INTO 1 line BY ItemCode.
*	qty was grouped as well.
*
*	e.g.: production order 1-5 were grouped IN IGN1 INTO line 11.
*	The related appobjabs IN inm/ilm is correct
*	The production orders IN inm/ilm were NOT grouped AND have consecutive DocLineNum which is inconsistent with
*	IGN1.LineNum.
*/
/**
 * Supp_180_Base entry IN Receipt FROM production is incorrect
 *
 * 
*/   
	select COUNT(t0."DocEntry") INTO rowcount from  "IGN1" t0
	inner join "OWOR" t1 on t0."BaseType" = 202 
	                     and t0."BaseEntry" = t1."DocEntry" 
						 and t0."BaseLine" is null 
						 and t0."ItemCode" <> t1."ItemCode";										  

	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 180.');
	
	end if;
/**
 * Supp_181_Base entry IN Issue for production is incorrect
 *
 * 
*/

	select COUNT(t0."DocEntry") INTO rowcount from "IGE1" t0
	inner join "OWOR" t1 on t0."BaseType" = 202 
	                     and t0."BaseEntry" = t1."DocEntry" 
						 and t0."BaseLine" is null 
						 and t0."ItemCode" <> t1."ItemCode";

	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 181.');
	
	end if;
 /**
 * Supp_182_Base entry IN Receipt FROM production is incorrect - returned components
 *
 * 
*/  
	select count(t0."DocEntry") into rowcount from "IGN1" t0
	        inner join "WOR1" t1 on t0."BaseType" = 202 
			             and t0."BaseEntry" = t1."DocEntry" 
						 and t0."BaseLine" = t1."LineNum" 
						 and t0."ItemCode" <> t1."ItemCode" 
            inner join (select "BaseAbsEnt", ifnull(max("VersionNum"),'') as  "OILM_Max_VersionNum"
						 from oilm
						 where "BaseType" = 202 
						 group by "BaseAbsEnt"
                    ) t2
                    on t1."DocEntry" = t2."BaseAbsEnt"                           
                    inner join oitm t3
                    on t3."ItemCode" = t0."ItemCode" and t3."InvntItem" = 'Y'
                    and (
                    		(t2."OILM_Max_VersionNum" >= CASE
															WHEN :cmpVersionNum >= 1000000
															THEN '09.10.000.00'
															ELSE '9.10.000.00' 
															END

                                   and t0."ItemCode" not in 
                                   (select u0."ItemCode"
                                         from oivl u0
                                         inner join oilm u1
                                         on u0."MessageID" = u1."MessageID"
                                               where u1."BaseType" = 202
                                                     and u1."AccumType" = 1
                                                     and u1."AppObjType" = 'C'
                                                     and u1."BaseAbsEnt" = t1."DocEntry"
                                                     and u1."AppObjLine" = t1."LineNum"
                                               group by u0."ItemCode", u1."BaseAbsEnt", u1."AppObjLine"
                                               having sum(u0."InQty"-u0."OutQty") = 0 )
                         		or
                     		(t2."OILM_Max_VersionNum" < CASE
															WHEN :cmpVersionNum >= 1000000
															THEN '09.10.000.00'
															ELSE '9.10.000.00' 
															END)));

	if :rowcount > 0 THEN 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 182.');
	end IF;

/**
 * Supp_183_Base entry IN Issue for production is incorrect - returned components
 *
 * 
*/
	select COUNT(t0."DocEntry") INTO rowcount from "IGE1" t0
	        inner join "WOR1" t1 on t0."BaseType" = 202 
			             and t0."BaseEntry" = t1."DocEntry" 
						 and t0."BaseLine" = t1."LineNum" 
						 and t0."ItemCode" <> t1."ItemCode"
					inner join
                    (select "BaseAbsEnt", ifnull(max("VersionNum"),'') as  "OILM_Max_VersionNum"
						 from oilm
						 where "BaseType" = 202 
						 group by "BaseAbsEnt"
                    ) t2
                    on t1."DocEntry" = t2."BaseAbsEnt"                           
                    inner join oitm t3
                    on t3."ItemCode" = t0."ItemCode" and t3."InvntItem" = 'Y'
                    and (
                    		(t2."OILM_Max_VersionNum" >= CASE
															WHEN :cmpVersionNum >= 1000000
															THEN '09.10.000.00'
															ELSE '9.10.000.00' 
															END
                                   and t0."ItemCode" not in 
                                   (select u0."ItemCode"
                                         from oivl u0
                                         inner join oilm u1
                                         on u0."MessageID" = u1."MessageID"
                                               where u1."BaseType" = 202
                                                     and u1."AccumType" = 1
                                                     and u1."AppObjType" = 'C'
                                                     and u1."BaseAbsEnt" = t1."DocEntry"
                                                     and u1."AppObjLine" = t1."LineNum"
                                               group by u0."ItemCode", u1."BaseAbsEnt", u1."AppObjLine"
                                               having sum(u0."InQty"-u0."OutQty") = 0 )
                         		or
                     		(t2."OILM_Max_VersionNum" < CASE
															WHEN :cmpVersionNum >= 1000000
															THEN '09.10.000.00'
															ELSE '9.10.000.00' 
															END)));
															
	if :rowcount > 0 then 
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 183.');
	
	end if;
/**
 * Supp_230_250_CreateDate is IN the future
 * MRV WOR WKO part
 * 
*/
	---OMRV 	
	Select count(t0."CreateDate") INTO rowcount 
	from   "OMRV" t0
	where  t0."CreateDate" > CURRENT_TIMESTAMP;

	if :rowcount > 0 THEN
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 248.');
	end IF;

	---OWOR	
	Select count(t0."CreateDate") into rowcount from   "OWOR" t0
	
	where  t0."CreateDate" > CURRENT_TIMESTAMP;

	if :rowcount > 0 THEN
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 249.');
	end IF;

	---OWKO	
	Select count(t0."CreateDate") into rowcount from "OWKO" t0
	
	where t0."CreateDate" > CURRENT_TIMESTAMP or t0."FinishDate" > CURRENT_TIMESTAMP;

	if :rowcount > 0 THEN
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 250.');
	end IF;

--removed 260

/**
 * Supp_270_Null IN FinishDate IN old work order
 *
 * 
*/
	SELECT COUNT(T0."OrderNum") INTO rowcount
	FROM  "OWKO" T0
	LEFT OUTER JOIN "OINM" T1 ON T0."OrderNum" = T1."CreatedBy"
		AND T1."TransType" = 68
	LEFT OUTER JOIN "OJDT" T2 ON T0."OrderNum" = T2."CreatedBy"
		AND T2."TransType" = N'68'
	WHERE  T1."TransSeq" IS NULL 
	       AND T2."TransId" IS NULL 
		   and T0."Status" = 'E' 
		   and IFNULL(t0."FinishDate", '') = '';									  

	if :rowcount > 0 THEN
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 270.');
	end IF;

/**
 * Supp_504_505_WOR1.comptotal missing check
 * This is added for incident 21405
 * Solution : Fill the comptotal value BY the support, customer interaction may be needed.
*/
	SELECT COUNT(t1."ItemCode") INTO rowcount 
	FROM   "WOR1" t1 
		INNER JOIN "OITM" t2 ON t1."ItemCode" = t2."ItemCode" 
		INNER JOIN "OITW" t3 ON t1."ItemCode" = t3."ItemCode" AND t1."wareHouse" = t3."WhsCode" 
	WHERE t2."InvntItem" = 'N' 
	      AND t2."TreeType" = 'A'
		  AND t2."Phantom" = 'N'
	      AND IFNULL(t1."CompTotal",0) = 0 
		  AND Round((CASE 
		             WHEN (SELECT "PriceSys" FROM "OADM") = 'N' 
						THEN t2."AvgPrice" 
					 ELSE t3."AvgPrice" 
					 END)
					 * t1."IssuedQty", :sum_decimals) <> 0;
																			
	IF :rowcount > 0 then 
		DB_Impacted := 'Y'; 
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 504.');
	END if; 

	SELECT COUNT(t1."ItemCode") INTO rowcount
	FROM   "UWOR1" t1 
		INNER JOIN "OITM" t2 ON t1."ItemCode" = t2."ItemCode" 
		INNER JOIN "OITW" t3 ON t1."ItemCode" = t3."ItemCode" AND t1."wareHouse" = t3."WhsCode" 
	WHERE t2."InvntItem" = 'N' 
	      AND t2."TreeType" = 'A'
		  AND t2."Phantom" = 'N'
	      AND IFNULL(t1."CompTotal",0) = 0 
		  AND Round((CASE 
		             WHEN (SELECT "PriceSys" FROM "OADM") = 'N' 
						THEN t2."AvgPrice" 
					 ELSE t3."AvgPrice" 
					 END)
					 * t1."IssuedQty", :sum_decimals) <> 0;

	IF :rowcount > 0 then 
		DB_Impacted := 'Y'; 
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 505.');
	END if;
------------------------------------------------
/**
 * Supp_506_Inconsistency between OILM.BaseAbsEnt AND OILM.AppObjAbs of receipt/issue for prodution order
 * Solution: Update OILM set AppObjAbs = BaseAbsEnt where OILM.BaseAbsEnt <> OILM.AppObjAbs AND OILM.BaseType=202
 * As a result of issue reported IN Task 15508
*/

    select count("MessageID") into rowcount FROM  oilm WHERE  oilm."BaseAbsEnt" <> oilm."AppObjAbs" AND oilm."BaseType" = 202;
	
	if :rowcount > 0 then	
		
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 506.');
	
	end if;
	
/**
 * Supp_507_Missing production order's message(Production order was created before 8.8)
 * Solution: before fixing IN code, please remove all OILM messages for affected production order
 * As a result of issue reported IN Task 17177,17176(Code Fixing)
*/  
	select count(T0."DocEntry") into rowcount from WOR1 t0 
	    join oitm t1 on t0."ItemCode" = t1."ItemCode"
	    left join oilm t2 on t0."DocEntry" = t2."DocEntry" and t2."TransType" = 202 and t0."LineNum" = t2."DocLineNum"
	where t1."InvntItem" = 'Y' 
	      and t0."DocEntry" in (select "DocEntry" from OILM where "TransType"=202) 
		  and t2."MessageID" is null;
		
	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 507.]]]');
	END if;
	

/**
 * Supp_508_Quantity is different FROM effectqty IN OILM for production order
 * Solution: set Quantity as effectqty IN OILM for production order
 * As a result of issue reported IN Task 17177
*/	
	select count("MessageID") into rowcount
	FROM OILM t0 
	WHERE t0."TransType" = 202 
	      and t0."Quantity" <> t0."EffectQty"
		  and not exists (SELECT 1 FROM OILM t1 
		                  WHERE t1."MessageID" < t0."MessageID"
								and T1."TransType" in (59,60) 
								and T1."AppObjAbs" = t0."DocEntry" 
								and T1."AppObjLine" = t0."DocLineNum") 
		and not (T0."DocLineNum" = -1 and T0."EffectQty" = 0) 
		and t0."AccumType" in (2,3);

	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 508.]]]');
	END if;
/**
 * Supp_509_ Duplicate records IN DLN14 for non assembly BoM 
 * Solution: Please refer note 1598583 
 * As a result of issue reported IN Task 18897
*/  
	SELECT SUM("rowCount") INTO rowCount 
	FROM (SELECT COUNT(1) AS "rowCount" FROM DLN1 T1
			JOIN OILM T0 on T0."TransType" = 15 AND T1."DocEntry" = T0."DocEntry" AND T1."LineNum" = T0."DocLineNum"
			JOIN DLN14 T3 on T3."DocEntry" = T1."DocEntry" AND T3."LineNum" = T1."LineNum"
		where (T1."TreeType" <> 'A' OR T0."TreeType"<> 'A') AND (T0."VersionNum"< CASE
																					WHEN :cmpVersionNum >= 1000000
																					THEN '08.81.313.05'
																					ELSE '8.81.313.05' 
																					END OR T0."VersionNum" IS NULL)
		UNION SELECT COUNT(1) AS "rowCount" FROM INV1 T1
			JOIN OILM T0 on  T0."TransType" = 13 AND T1."DocEntry" = T0."DocEntry" AND T1."LineNum" = T0."DocLineNum"
			JOIN INV14 T3 on T3."DocEntry" = T1."DocEntry" AND T3."LineNum" = T1."LineNum"
		where (T1."TreeType"<> 'A' OR T0."TreeType"<> 'A') AND (T0."VersionNum"=  CASE
																					WHEN :cmpVersionNum >= 1000000
																					THEN '08.81.313.05'
																					ELSE '8.81.313.05' 
																					END OR T0."VersionNum"=  CASE
																												WHEN :cmpVersionNum >= 1000000
																												THEN '08.80.239.21'
																												ELSE '8.80.239.21' 
																												END)
		UNION SELECT COUNT(1) AS "rowCount" FROM RDN1 T1
			JOIN OILM T0 on  T0."TransType" = 16 AND T1."DocEntry" = T0."DocEntry" AND T1."LineNum" = T0."DocLineNum"
			JOIN RDN14 T3 on T3."DocEntry" = T1."DocEntry" AND T3."LineNum" = T1."LineNum"
		where (T1."TreeType"<> 'A' OR T0."TreeType"<> 'A') AND (T0."VersionNum"=  CASE
																					WHEN :cmpVersionNum >= 1000000
																					THEN '08.81.313.05'
																					ELSE '8.81.313.05' 
																					END OR T0."VersionNum"=  CASE
																												WHEN :cmpVersionNum >= 1000000
																												THEN '08.80.239.21'
																												ELSE '8.80.239.21' 
																												END)
		UNION SELECT COUNT(1) AS "rowCount" FROM RIN1 T1
			JOIN OILM T0 on  T0."TransType" = 14 AND T1."DocEntry" = T0."DocEntry" AND T1."LineNum" = T0."DocLineNum"
			JOIN RIN14 T3 on T3."DocEntry" = T1."DocEntry" AND T3."LineNum" = T1."LineNum"
		where (T1."TreeType"<> 'A' OR T0."TreeType"<> 'A') AND (T0."VersionNum"=  CASE
																					WHEN :cmpVersionNum >= 1000000
																					THEN '08.81.313.05'
																					ELSE '8.81.313.05' 
																					END OR T0."VersionNum"=  CASE
																												WHEN :cmpVersionNum >= 1000000
																												THEN '08.80.239.21'
																												ELSE '8.80.239.21' 
																												END)
		UNION SELECT COUNT(1) AS "rowCount" FROM CSI1 T1
			JOIN OILM T0 on  T0."TransType" = 165 AND T1."DocEntry" = T0."DocEntry" AND T1."LineNum" = T0."DocLineNum"
			JOIN CSI14 T3 on T3."DocEntry" = T1."DocEntry" AND T3."LineNum" = T1."LineNum"
		where (T1."TreeType"<> 'A' OR T0."TreeType" <> 'A') AND (T0."VersionNum"=  CASE
																					WHEN :cmpVersionNum >= 1000000
																					THEN '08.81.313.05'
																					ELSE '8.81.313.05' 
																					END OR T0."VersionNum"=  CASE
																												WHEN :cmpVersionNum >= 1000000
																												THEN '08.80.239.21'
																												ELSE '8.80.239.21' 
																												END)
		UNION SELECT COUNT(1) AS "rowCount" FROM CSV1 T1
			JOIN OILM T0 on T0."TransType" = 166 AND T1."DocEntry" = T0."DocEntry" AND T1."LineNum" = T0."DocLineNum"
			JOIN CSV14 T3 on T3."DocEntry" = T1."DocEntry" AND T3."LineNum" = T1."LineNum"
		where (T1."TreeType"<> 'A' OR T0."TreeType"<> 'A') AND (T0."VersionNum"=  CASE
																					WHEN :cmpVersionNum >= 1000000
																					THEN '08.81.313.05'
																					ELSE '8.81.313.05' 
																					END OR T0."VersionNum"=  CASE
																												WHEN :cmpVersionNum >= 1000000
																												THEN '08.80.239.21'
																												ELSE '8.80.239.21' 
																												END));
																												
	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 509.]]]');
	
	END if;
	
/* Supp_510_Quantity is negative IN OILM for production order's child with 
negative Quantity on document. 
* Solution: set Quantity as effectqty IN OILM for production order 
* As a result of issue reported IN Task 17304 
*/
	select count("MessageID") into rowcount from OILM 
	where "Quantity" < 0 and "DocLineNum" <> -1 and "TransType" = 202 and "AccumType" = 3 and 
	"ItemCode" not in (select distinct t1."ItemCode" from oilm t1 where t1."BaseType" = 202 and t1."BaseAbsEnt" = "BaseAbsEnt" and t1."AppObjType" = 'B');
		
	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 510.]]]');
	
	END if;
/* Supp_511 & 512 & 513_Inconsistencies between table WKO1 AND OILM
 * There are several inconsistencies between table WKO1 AND OILM for some workorders.
 * This query check for these inconsistencies AND RETURN theirs DocEntry AND DocLineNum.
 * It also checks for inconsistency Quantity sign vs IN/out ActionType
 * Solution: update OR delete OR create inconsistent OWKO, OITT, ITT1 OR create BoM
 * Result of investigation on CRM 455009 2011, ID 25833, ID 26333
*/
-- WKO1.OrderNum=OILM.DocEntry AND WKO1.LineID AND OILM.DocLineNum AND OILM.TransType=68 there is inconsistency IN ItemCodes
	select count(1) into rowcount 
	from (WKO1 t0 
	    LEFT OUTER JOIN OILM t1 on t0."OrderNum" = t1."DocEntry" 
		                        and t0."LineID" = t1."DocLineNum" 
								and t0."ItemCode" = t1."ItemCode" 
								-- check corresponding lines
			                    and	((t0."Quantity" > 0 and t1."ActionType" = 1) or (t0."Quantity" < 0 and t1."ActionType" = 2)) 
								-- find corresponding line FROM OILM according to Quantity AND ActionType
								and	t1."TransType" = 68) 
		where t1."MessageID" is null
		--check only TransType 68 lines, IF the MessageID is NULL, it means there is an inconsistency between OILM AND wko1
			  and exists (select count(1) 
						  from OILM t2 
						  where t2."DocEntry" = t0."OrderNum" and t2."DocLineNum" = t0."LineID" and t2."TransType" = 68);
        -- make sure that there is at least one TransType 68
		--order BY OrderNum, LineId
		
		if :rowcount > 0 then
		    DB_Impacted := 'Y';
		
		    INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 511.]]]');
			
	End if;

	-- check if any WKO1 order has quantity inconsistency with OILM transtype=68 and actiontype (2 for quantity>0 and 1 for quantity<0)
	
	select count(1) into rowcount 
	from WKO1 t0 
	    inner join 
		(SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY "DocEntry", "DocLineNum" ORDER BY "MessageID") AS "seq" FROM OILM where "TransType" = 68) p0 WHERE p0."seq" = 1) t1
			ON t0."OrderNum" = t1."DocEntry" AND t0."LineID" = t1."DocLineNum" 
			   AND t0."ItemCode" = t1."ItemCode" 
			   AND ((t0."Quantity" > 0 AND t1."ActionType" = 2)
						OR (t0."Quantity" < 0 AND t1."ActionType" = 1));
		
	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 512.]]]');
	End if;
	-- check for some work orders in OILM that are having only one action type (in or out)
	select count(1) into rowcount 
	from (select count(*) from OILM where "TransType" = 68 group by "DocEntry", "DocLineNum" having COUNT(distinct "ActionType") = 1);
	
	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 513.]]]');
	End if;

/**
 * Supp_514_FIFO items received via transactions 58 OR '-2' have zero Total LC/FC/SC
 * CRM 200230 2012 - find more info AND fix proposals 
 * 
*/

	SELECT COUNT(1) INTO rowCount 
	FROM OILM T0 
		INNER JOIN OIVL T1 ON T0."MessageID" = T1."MessageID"
		INNER JOIN IVL1 t2 ON t1."TransSeq" = T2."TransSeq"
	WHERE t0."TransType" IN (58,-2)
		  AND t0."TotalLC" = 0
		  AND t2."TransValue" <> 0
		  AND T1."InQty" <> 0
		  AND T1."CostMethod" = 'F';
		  
	IF :rowCount > 0 THEN
		DB_Impacted := 'Y';
		
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 514.]]]');

	END IF;
	
--removed 515
	/**  
	 * Supp_516_Corrupted OILM messages are created added into OILM during ATP upgrade to 9.0 PL09
	 *  E.g., messages for Sales Order, Purchase Orders, Reserve Invoices added in versions prior 8.8 
	 *  and affecting committed and ordered accumulators.  
	 *	(1) 'createdate' of such record might be set to date of the upgrade; 
	 *	(b) and 'versionnum' is set to NULL ; 
	 *	(c) finally, message is placed incorrectly in OIML with 'messageid' higher than last message 
	*/ 
       IF(:cmpVersionNum >= 890000) THEN
                    SELECT (IFNULL(MIN("MessageID"), 0) - 1) INTO max07Msg FROM OILM WHERE "VersionNum" >=  CASE
																												WHEN :cmpVersionNum >= 1000000
																												THEN '08.80.000.00'
																												ELSE '8.80.000.00' 
																												END;
                    SELECT COUNT(1) INTO rowCount 
                    FROM OILM
                    WHERE "MessageID" > :max07Msg
                             AND IFNULL("VersionNum", '') < CASE
															WHEN :cmpVersionNum >= 1000000
															THEN '08.80.000.00'
															ELSE '8.80.000.00' 
															END;
       END IF;
             
         IF :rowCount >0 THEN
                    DB_Impacted := 'Y';
 
                    INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 516.]]]');

         END IF;
             
    /** 
    * 
	* Supp_517_Incorrect lenght of user column in U tables after upgrade 
	* Solution: Increase lenght of user def.column in U table according to O table 
	* More detail in SAP Note 1645439 
    */
    IF(:cmpVersionNum >= 881319) THEN
        SELECT 
        (SELECT COUNT(*)
       		FROM 
        	TABLE_COLUMNS t0 
            INNER JOIN 
            TABLE_COLUMNS t1 
            ON 
            t0.COLUMN_NAME = t1.COLUMN_NAME 
            AND  t0.TABLE_NAME <> t1.TABLE_NAME 
            AND t0.SCHEMA_NAME = t1.SCHEMA_NAME
        	AND t0.SCHEMA_NAME IN (SELECT current_schema FROM DUMMY)
        			WHERE t0.TABLE_NAME IN ('OITM', 'UITM', 'OITW', 'UITW', 'OWKO', 'UWKO', 'OWOR', 'UWOR')
        			AND
        			t1.TABLE_NAME IN ('OITM', 'UITM', 'OITW', 'UITW', 'OWKO', 'UWKO', 'OWOR', 'UWOR')
        			AND RIGHT(t1.TABLE_NAME, 3) = RIGHT(t0.TABLE_NAME, 3) 
        			AND t1.COLUMN_NAME LIKE 'U\_%' ESCAPE '\' 
                    AND t1.LENGTH < t0.LENGTH   ) INTO rowCount FROM DUMMY;
                    
           END IF;         
                    
        IF :rowCount >0 THEN
                    DB_Impacted := 'Y';

                    INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 517.]]]');
            
        
   		END IF; 
		
	/** 
    * 
	* Supp_518_Missing warehouse 
	* Solution: add missing warehouse to Item master data or OITW 
	* see IM 100011 / 2014 / IVI Fails after OITW deletion 
    */
	IF(:cmpVersionNum >= 902000 AND :cmpVersionNum <= 902002) THEN
	        SELECT 
	        (SELECT COUNT(*)
	      		 from oivl l 
				full outer join oitw w 
					on l."ItemCode"=w."ItemCode" 
					and l."LocCode"=w."WhsCode"
					where w."WhsCode" is null) 
	        INTO rowCount FROM DUMMY;
                    
        END IF;
		
	if :rowcount > 0 then
		DB_Impacted := 'Y';
		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 518.]]]');
	End if;
	
/** 
	* Supp_519_Note_1320969 - Upgrade Wizard Precheck: Triggers check 
	* Remove any triggers before IVI 
	* rel 9.5.2014 
	*************************************************
	* on HANA there are some triggers used on many tables due some system feature - therefore this check cannot be used the same way as on SQL
	* therefore I am skipping this check for the moment till clear rules where triggers can be will not be set 
	* to avoid false detection - seems that system created triggers do not affect recalculation
	*/ 
	
	/*
    *
	* Supp_520_Stock Counting document line set to Freez
	* Solution: Un-tick the Freeze check-box on all detected Stock Counting document lines. DO NOT use SQL update query.
	* After recalculation update the documents to original state
	* Or upgrade to 9.1 PL05 or 9.0 PL16 as it is fixed there
	
    */
    
    IF((:cmpVersionNum >= 900046 AND :cmpVersionNum <= 902250) 
    	OR (:cmpVersionNum >= 910105 AND :cmpVersionNum <= 910140))
    THEN
    
   		SELECT COUNT(1) INTO temp_var_0 
    		FROM M_tables 
    			WHERE "SCHEMA_NAME" = (SELECT CURRENT_SCHEMA FROM dummy) 
    			AND TABLE_NAME = 'StcCont';
    	IF :temp_var_0 > 0 THEN 
       		 DROP TABLE "StcCont";
        END IF;
        CREATE COLUMN TABLE "StcCont" ("recCount" integer);
        
        sqlStr := '
					 INSERT INTO "StcCont"
						SELECT COUNT(*)
						FROM OITW
						WHERE "Freezed" = ''Y''
					 
        ';
        EXEC(:sqlStr);
        
        SELECT 
        (SELECT sum("recCount") 
       		 FROM "StcCont"
	 	 where "recCount"<> 0) 
		INTO rowCount FROM DUMMY;
    END IF;
        
        IF :rowCount >0 THEN
                    DB_Impacted := 'Y';

                    INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 520.]]]');
 
        END IF;
                         
        SELECT COUNT(1) INTO temp_var_0 
    		FROM M_tables 
    			WHERE "SCHEMA_NAME" = (SELECT CURRENT_SCHEMA FROM dummy) 
    			AND TABLE_NAME = 'StcCont';
    	IF :temp_var_0 > 0 THEN 
       		 DROP TABLE "StcCont";
        END IF;

/**
