             FROM   IQI1 T0
                    INNER JOIN OITM T1 ON T0."ItemCode" = T1."ItemCode"
                                          and T1."InvntItem" = 'Y'
             WHERE  T0."DocEntry" not in ( Select "DocEntry"
                                         from   OIQI );
        
    IF :rowCount > 0 THEN
		DB_Impacted := 'Y';

		INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 523.]]]');
		
