/**
 * Supp_425_Missing documents IN OILM
 * Solution: 
 *********************************IVI*********************************
 * Rebuild the UILM table
 *********************************IVI*********************************
 *
 *********************************IVSR*********************************
 * Running IVI
 *********************************IVSR*********************************
*/
		select COUNT(T0."MessageID") INTO rownum 
		from "OILM" T0
		left join "OILM" T1	on T0."BaseAbsEnt" = T1."DocEntry" 
		                    and T0."BaseType" = T1."TransType"
		where (T0."BaseAbsEnt" > 0 or T0."BaseType" > 0) 
		    and T0."BaseType" not in (17,22,23,202,67,540000006,1250000001)
			AND T0."AccumType" = 1 
			AND T0."ActionType" not in (3,4)
			AND NOT (T0."BaseType"=18 AND T0."BaseAbsEnt" IN (select "DocEntry" from "OPCH" where "UpdInvnt" = 'O')) --AP Res. Inv -> XXX
			AND NOT (T0."BaseType"=13 AND T0."BaseAbsEnt" IN (select "DocEntry" from "OINV" where "UpdInvnt" = 'C')) --AR Res. Inv -> XXX
			AND NOT (T0."BaseType"=18 AND T0."TransType" = 20) --Res. Inv -> GRPO (but Res. Inv was deleted)
			AND NOT (T0."BaseType"=13 AND T0."TransType" = 15) --Res. Inv -> DLN (but Res. Inv was deleted) 
			AND NOT (T0."BaseType"=163 AND T0."TransType" = 20) --Res. Inv -> CI -> GRPO (GRPO is calculated as not based within IVI/IVSR)  
			AND NOT (T0."BaseType"=165 AND T0."TransType" = 15) --Res. Inv -> CI -> DLN (DLN is calculated as not based within IVI/IVSR)   
			AND NOT (T0."BaseType" in (67,20,59) AND T0."TransType" = 67) -- WTR is handled as non based doc.
			AND NOT (T0."BaseType"=234000031 AND T0."TransType" = 16) -- RRR->RDN
			AND NOT (T0."BaseType"=234000031 AND T0."TransType" = 14) -- RRR->RIN
			AND NOT (T0."BaseType"=234000032 AND T0."TransType" = 19) -- RRR->RPC
			AND NOT (T0."BaseType"=234000032 AND T0."TransType" = 21) -- RRR->RPD
			AND t0."TransType" <> 202 --Production order create/update - basetype=1 by known bug
			AND (IFNULL(T1."DocEntry",0) = 0 or IFNULL(T1."TransType",0) = 0);
			
		IF :rownum > 0 then 
			DB_Impacted := 'Y'; 
			INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'DB is impacted, please contact SAP support. ErrorCode = 425.');
		END if;

/**  
 * Supp_426_Null TotalLC IN OILM for lANDed cost
 * As a result of issue reported IN Task 15365 for 8.8 AND CSN 2259123 2010 for 8.81
 * Solution: 
 *********************************IVI*********************************
 * Rebuild the UILM table
 *********************************IVI*********************************
 *
 *********************************IVSR*********************************
 * Running IVI
 *********************************IVSR*********************************
*/
		
		SELECT count("MessageID") into rownum 
		from oilm	
		where "TransType" = 69 
		      and ifnull("TotalLC",0) = 0 
			  and ifnull("VersionNum", '') < CASE 
													WHEN :cmpVersionNum >= 1000000
													THEN '08.00.000.00'
													ELSE '8.00.000.00' 
													END;
			IF :rownum > 0 then
			DB_Impacted := 'Y';
			
			INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 426.]]]');
		
		end if;
		
--Special Treatment for Supp_416_419 as IVI/IVSR has different condition









--- Assembly BoM subline numbers were wrongly updated for several scenarios.  
--- Assembly BoM qty could be wrongly calculated.  
--- As a result of issue reported in Task 13010 
		SELECT COUNT(1) INTO rowCount FROM
			   (SELECT "VersionNum"
				FROM "OILM"
				WHERE "VersionNum" >= CASE 
										WHEN :cmpVersionNum >= 1000000
										THEN '08.80.000.00'
										ELSE '8.80.000.00' 
										END
					AND "VersionNum" <= CASE 
											WHEN :cmpVersionNum >= 1000000
											THEN '08.80.228.09'
											ELSE '8.80.228.09' 
											END --- DB upgraded to 8.8 befor PL 10  
			   );
	
			SELECT COUNT(1) INTO count1 FROM	
			   (SELECT "AbsEntry"
			    FROM "CIVI"
				WHERE "ReorderFrm" <> :firstTranstionDate--NOT FROM the first date 
			   );
				
			SELECT COUNT(1) INTO count2 FROM
			   (SELECT 1
			    FROM "CIVI"
				WHERE "MsgSource" = '10000162'--NOT BY uilm 
			   );
			
			IF :rowCount > 0 
			   AND ((:stockissue88 = 'Y' AND count1 > 0)
					 OR stockissue88 = 'N' AND count2 = 0)
			THEN
				SELECT COUNT(1) INTO rowCount
				FROM CSI1 t0 
					INNER JOIN OCSI t1 
					      ON t0."DocEntry" = t1."DocEntry"
					INNER JOIN OITM t2 
						  ON t0."ItemCode" = t2."ItemCode" 
				WHERE IFNULL(t1."VersionNum", '') < CASE 
														WHEN :cmpVersionNum >= 1000000
														THEN '08.80.000.00'
														ELSE '8.80.000.00' 
														END 
					  AND t1."Instance" = 0 ---Document was NOT created via year transfer    
					  AND t2."TreeType" = 'A'; ---Item is assembly BOM  
				
				IF :rowCount > 0 THEN
				
				DB_Impacted := 'Y'; 
				
				INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 416.]]]');
				
			END if;
---AR Correction Reversal  
				---AR Correction Reversal 
			SELECT COUNT(t0."DocEntry") INTO rownum1 FROM   "CSV1" t0 
				INNER JOIN "OCSV" t1 ON t0."DocEntry" = t1."DocEntry" 
				INNER JOIN "OITM" t2 ON t0."ItemCode" = t2."ItemCode"
			WHERE IFNULL(t1."VersionNum", '') < CASE 
														WHEN :cmpVersionNum >= 1000000
														THEN '08.80.000.00'
														ELSE '8.80.000.00' 
														END
				AND t1."Instance" = 0     
				AND t2."TreeType" = 'A';  
			IF :rownum1 > 0 then 
				DB_Impacted := 'Y'; 
				
				INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 417.]]]');
				
			END if;
			--- AP AND AR Reserve Corr. Invoices AND Db was upgraded to 8.8 before PL10   
			--- AR Reserve Correction Invocie  			
			SELECT COUNT(t0."DocEntry") into rownum1 FROM   "CSI1" t0 
				INNER JOIN "OCSI" t1 ON t0."DocEntry" = t1."DocEntry" 
				INNER JOIN "OITM" t2 ON t0."ItemCode" = t2."ItemCode"
			WHERE IFNULL(t1."VersionNum", '') < CASE 
														WHEN :cmpVersionNum >= 1000000
														THEN '08.80.000.00'
														ELSE '8.80.000.00' 
														END
				AND t1."isIns" = 'Y' 
				AND ( t2."InvntItem" = 'Y' OR t2."TreeType" = 'A' ) 
				AND t1."Instance" = 0 ; 

			IF :rownum1 > 0 then 
				DB_Impacted := 'Y'; 
				
				INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 418.]]]');
				
			END if;
			--- AP Reserve Correction Invocie
			SELECT COUNT(t0."DocEntry") into rownum1 FROM   "CPI1" t0 
				INNER JOIN "OCPI" t1 ON t0."DocEntry" = t1."DocEntry" 
				INNER JOIN "OITM" t2 ON t0."ItemCode" = t2."ItemCode"
			WHERE  IFNULL(t1."VersionNum", '') < CASE 
														WHEN :cmpVersionNum >= 1000000
														THEN '08.80.000.00'
														ELSE '8.80.000.00' 
														END 
				AND t1."isIns" = 'Y' 
				AND ( t2."InvntItem" = 'Y' OR t2."TreeType" = 'A' ) 
				AND t1."Instance" = 0 ; 

			IF :rownum1 > 0 then 
				DB_Impacted := 'Y'; 
				
				INSERT INTO "TMP_IVSR_SupInterReq_Results" VALUES (N'TODO[[[db is impacted, please contact SAP support. ErrorCode = 419.]]]');
				
			END if; 
		END if; --416_419
	END IF; --Recalc_By_OILM
	
	DELETE FROM "TMP_IVSR_SupInterReq_TotalLcZeroPQNotZero";
	SELECT * FROM "TMP_IVSR_SupInterReq_Results";
	DELETE FROM "TMP_IVSR_SupInterReq_Results";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_IVSR_UserInteractionRequiredQuery

LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS


cntResults int;
CntScenarios int;
Sys_Currency nvarchar(3);
Main_Currency nvarchar(3);
rownum int;
rowcount int;

newAcctDe nvarchar(1);	
CurrPeriodCat nvarchar (10);
CmpyhasStockAct int;  
CmpyhasReturnAct int; 
oivlCnt			int;
oivlInvActOKCnt	int;
oivlRtnActOKCnt	int;

BEGIN

--IF object_id('[tempdb]..#TempCheckStockResults') IS NOT NULL DROP TABLE [#TempCheckStockResults]

delete from "IVSRUserInteractionRequiredQuery_TempCheckStockResults";
delete from "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_Item";
delete from "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_WareHouse";

select "MainCurncy"  INTO main_currency from "OADM";
select "SysCurrncy" INTO Sys_Currency from "OADM";
CntScenarios := 0;

select count(T0."ItemCode") into rowcount
            
     from   "WOR1" T0
            INNER JOIN "OITM" T1 ON T0."ItemCode" = T1."ItemCode"
     WHERE  T1."InvntItem" = 'N'
            AND T1."EvalSystem" <> 'S';
If :rowcount > 0 
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Non inventory & non Standard item in Production_Items_Lines');
        CntScenarios := :CntScenarios + 1;
    end if;



select COUNT(T0."ItemCode") INTO rowcount
     FROM   "OIVL" T0
            INNER JOIN "ITT1" t2 on T0."ItemCode" = t2."Father"
            inner join "OITM" T1 ON T0."ItemCode" = T1."ItemCode"
                                  or t2."Code" = t1."ItemCode"
     WHERE  T0."TransType" = 68
            AND T1."InvntItem" = 'N'
            AND T1."EvalSystem" <> 'S';

    If :rowcount > 0 
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Non inventory & Non Standard items in Old Work Order_ OIVL');
        CntScenarios := :CntScenarios + 1;
    end if;



select COUNT(T0."ItemCode") INTO rowcount
     FROM   "WKO1" T0
            inner join "OWKO" T1 ON T0."OrderNum" = T1."OrderNum"
     WHERE  T1."Status" = 'E'
            AND T1."OrderNum" not in ( select "CreatedBy"
                                     from   "OIVL"
                                     where  "TransType" = 68 )
            and exists ( select "Code"
                         from   "ITT1"
                         where  "Father" = t0."ItemCode"
                                and "Code" in ( select    "ItemCode"
                                              from      "OITM"
                                              where     "InvntItem" = 'N'
                                                        and "EvalSystem" <> 'S' ) );

    If :rowcount > 0 
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'ITT1 with non Inventory & Non Standard Items with no entry in oivl');
        CntScenarios := :CntScenarios + 1;
    end if;
    
----------------Advanced G/L Account Determiniation ---begin-------------------------------------------------
/**
 * check U_Inventory account or sales return account were not defined, 
 * when 'Advance GL Account Determination' is actived.
 *
 * 
*/
SELECT "NewAcctDe" INTO newAcctDe FROM "OADM" ;
SELECT "Category" INTO CurrPeriodCat FROM "OFPR" WHERE "F_RefDate" <= CURRENT_DATE AND "T_RefDate" >= CURRENT_DATE ;

/*are the Accouts defined in company level? */
CmpyhasStockAct := 0;  
CmpyhasReturnAct := 0;
SELECT COUNT("AbsEntry")INTO CmpyhasStockAct FROM "OACP" 
		WHERE "StockAct" is not null AND "StockAct" <> '' AND "PeriodCat" = :CurrPeriodCat;
		
SELECT COUNT("AbsEntry") INTO CmpyhasReturnAct FROM "OACP" 
		WHERE "RturnngAct" is not null AND "RturnngAct" <> '' AND "PeriodCat" = :CurrPeriodCat;


SELECT COUNT("TransType") INTO oivlCnt FROM "OIVL" ;

/*check inventory account*/
oivlInvActOKCnt := :oivlCnt ;
IF ( :newAcctDe = 'Y' AND :CmpyhasStockAct = 0) THEN
	SELECT COUNT(*) INTO oivlInvActOKCnt FROM
	(
		SELECT DISTINCT ("OIVL"."TransSeq")
		FROM "OIVL" INNER JOIN "OITM" ON ("OITM"."ItemCode" = "OIVL"."ItemCode")
			, "OGAR"			
		WHERE (IFNULL("OGAR"."StockAct", '') <> '' )
			AND ("OGAR"."ItemCode" = "OIVL"."ItemCode" OR "OGAR"."ItemCode" = '!^|')
			AND ("OGAR"."WhsCode" = "OIVL"."LocCode" OR "OGAR"."WhsCode" = '!^|')
			AND ("OGAR"."ItmsGrpCod" = "OITM"."ItmsGrpCod" OR "OGAR"."ItmsGrpCod" = -1)
			AND ("OGAR"."GLMethod" = "OITM"."GLPickMeth" OR "OGAR"."GLMethod" = 'A' or "OITM"."GLPickMeth" = 'A')
			AND "OGAR"."PeriodCat" = :CurrPeriodCat
			AND "OGAR"."Active" = 'Y' 
			
	);
END IF;

/*check return account*/
oivlRtnActOKCnt := :oivlCnt ;
IF ( :newAcctDe = 'Y' AND :CmpyhasReturnAct = 0) THEN
	SELECT COUNT(*) INTO oivlRtnActOKCnt FROM
	(
		SELECT DISTINCT ("OIVL"."TransSeq")
		FROM "OIVL" INNER JOIN "OITM" ON ("OITM"."ItemCode" = "OIVL"."ItemCode")
			, "OGAR"			
		WHERE  "OIVL"."TransType" NOT IN ( 16, 14 )
			OR 
			IFNULL("OGAR"."RturnngAct", '') <> '' AND "OIVL"."TransType" IN ( 16, 14 )
			AND ("OGAR"."ItemCode" = "OIVL"."ItemCode" OR "OGAR"."ItemCode" = '!^|')
			AND ("OGAR"."WhsCode" = "OIVL"."LocCode" OR "OGAR"."WhsCode" = '!^|')
			AND ("OGAR"."ItmsGrpCod" = "OITM"."ItmsGrpCod" OR "OGAR"."ItmsGrpCod" = -1)
			AND ("OGAR"."GLMethod" = "OITM"."GLPickMeth" OR "OGAR"."GLMethod" = 'A' or "OITM"."GLPickMeth" = 'A')
			AND "OGAR"."PeriodCat" = :CurrPeriodCat
			AND "OGAR"."Active" = 'Y' 
			
	);
END IF;

IF (:newAcctDe='Y' AND (:oivlCnt > :oivlRtnActOKCnt OR :oivlCnt > :oivlInvActOKCnt) ) THEN
	INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Inventory account or sales return account were not defined');
        CntScenarios := :CntScenarios + 1;
END IF;
------------------------------Advanced G/L Account Determiniation ---end---------------------------------------------

select COUNT(T0."ItemCode") INTO rowcount
     FROM   ( SELECT    T0."ItemCode",
                        T0."GLMethod",
                        T1."WhsCode",
                        CASE T0."GLMethod"
                          WHEN 'L' THEN T1."BalInvntAc"
                          WHEN 'W' THEN T2."BalInvntAc"
                          WHEN 'C' THEN T3."BalInvntAc"
                        END "BalInvntAc",
                        CASE T0."GLMethod"
                          WHEN 'L' THEN T1."ReturnAc"
                          WHEN 'W' THEN T2."ReturnAc"
                          WHEN 'C' THEN T3."ReturnAc"
                        END "ReturnAc"
              FROM      "OITM" T0
                        INNER JOIN "OITW" T1 ON T1."ItemCode" = T0."ItemCode"
                        INNER JOIN "OWHS" T2 ON T2."WhsCode" = T1."WhsCode"
                        INNER JOIN "OITB" T3 ON T3."ItmsGrpCod" = T0."ItmsGrpCod"
            ) T0
     WHERE  ( IFNULL(T0."BalInvntAc", '') = ''
              AND ( SELECT  COUNT(1)
                    FROM    "OIVL" T1
                    WHERE   T1."ItemCode" = T0."ItemCode"
                            AND T1."LocCode" = T0."WhsCode"
                  ) > 0
            )
            OR ( IFNULL(T0."ReturnAc", '') = ''
                 AND ( SELECT   COUNT(1)
                       FROM     "OIVL" T1
                       WHERE    T1."ItemCode" = T0."ItemCode"
                                AND T1."LocCode" = T0."WhsCode"
                                AND T1."TransType" IN ( 16, 14 )
                     ) > 0
               );

    If :rowcount > 0 and :newAcctDe <> 'Y'
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Inventory account or sales return account were not defined');
        CntScenarios := :CntScenarios + 1;
    end if;



--select count(*) INTO rownum from Tables where TABLE_NAME = 'SBO_RSP_IVI_Affected_Item';
--IF :rownum > 0
--      then               
--    drop table "SBO_RSP_IVI_Affected_Item";
--    end if;
--CREATE TABLE "SBO_RSP_IVI_Affected_Item"
--    (
--      "Description" nvarchar(100),
--      "ItemCode" nvarchar(50),
--      "DocNum" nvarchar(100),
--     "DocEntry" int,
--     "Document_Type" nvarchar(100)
--    );
	
	
insert  into "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_Item"
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)) As "DocNum",
                t0."DocEntry",
                'AR Delivery' as "Document_Type"
        from    "DLN1" t1
                inner join "ODLN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'                                      
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Return' as "Document_Type"
        from    "RDN1" t1
                inner join "ORDN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Invoice' as "Document_Type"
        from    "INV1" t1
                inner join "OINV" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Credit Memo' as "Document_Type"
        from    "RIN1" t1
                inner join "ORIN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Correction Invocie' as "Document_Type"
        from    "CSI1" t1
                inner join "OCSI" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
    
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Correction Reversal' as "Document_Type"
        from    "CSV1" t1
                inner join "OCSV" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'GRPO' as "Document_Type"
        from    "PDN1" t1
                inner join "OPDN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'GR' as "Document_Type"
        from    "RPD1" t1
                inner join "ORPD" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Invoice' as "Document_Type"
        from    "PCH1" t1
                inner join "OPCH" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Credit Memo' as "Document_Type"
        from    "RPC1" t1
                inner join "ORPC" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
       
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Correction Invocie' as "Document_Type"
        from    "CPI1" t1
                inner join "OCPI" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Correction Reversal' as "Document_Type"
        from    "CPV1" t1
                inner join "OCPV" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Goods Receipt' as "Document_Type"
        from    "IGN1" t1
                inner join "OIGN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
       
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Goods Issue' as "Document_Type"
        from    "IGE1" t1
                inner join "OIGE" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
       
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Inventory Transfer' as "Document_Type"
        from    "WTR1" t1
                inner join "OWTR" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."SerialNum" as nvarchar(100)),
                t0."OrderNum",
                'Old Work Order' as "Document_Type"
        from    "WKO1" t1
                inner join "OWKO" t0 on t0."OrderNum" = t1."OrderNum"
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Production Order_Components' as "Document_Type"
        from    "WOR1" t1
                inner join "OWOR" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."ItemType" = 4
                                      and t1."ItemCode" not in (
                                      select    "ItemCode"
                                      from      "OITM" )
        
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t0."ItemCode",
                CAST(t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Production Order_BOM' as "Document_Type"
        from    "OWOR" t0
        where   t0."ItemCode" not in ( select "ItemCode"
                                     from   "OITM" )
       
        union
        SELECT  distinct
                'Item code in document doesnt exist in Items Master Data' as "Description",
                t1."ItemCode",
                t1."Ref1",
                t1."MessageID",
                'Stock log' as "Document_Type"
        from    "OILM" t1
        where   t1."ItemCode" not in ( select "ItemCode"
                                     from   "OITM" );
 
select COUNT("ItemCode") INTO rowcount
     from   "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_Item";
If :rowcount > 0
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Item code in document doesnt exist in Items Master Data');
        CntScenarios := :CntScenarios + 1;
    end if;

       
--select count(*) into rownum from Tables where TABLE_NAME = 'SBO_RSP_IVI_Affected_WareHouse';
--IF :rownum > 0
--      then               
--    drop table "SBO_RSP_IVI_Affected_WareHouse";
--    end if;

--CREATE TABLE "SBO_RSP_IVI_Affected_WareHouse"
--    (
--      "Description" nvarchar(100),
--      "ItemCode" nvarchar(50),
--      "DocNum" nvarchar(100),
--      "DocEntry" int,
--      "Document_Type" nvarchar(100),
--      "WareHouse" nvarchar(100)
--    );

insert  into "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_WareHouse"
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)) As "DocNum",
                t0."DocEntry",
                'AR Delivery' as "Document_Type",
                t1."WhsCode"
        from    "DLN1" t1
                inner join "ODLN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Return' as "Document_Type",
                t1."WhsCode"
        from    "RDN1" t1
                inner join "ORDN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Invoice' as "Document_Type",
                t1."WhsCode"
        from    "INV1" t1
                inner join "OINV" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Credit Memo' as "Document_Type",
                t1."WhsCode"
        from    "RIN1" t1
                inner join "ORIN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
       
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Correction Invocie' as "Document_Type",
                t1."WhsCode"
        from    "CSI1" t1
                inner join "OCSI" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AR Correction Reversal' as "Document_Type",
                t1."WhsCode"
        from    "CSV1" t1
                inner join "OCSV" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
      
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'GRPO' as "Document_Type",
                t1."WhsCode"
        from    "PDN1" t1
                inner join "OPDN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'GR' as "Document_Type",
                t1."WhsCode"
        from    "RPD1" t1
                inner join "ORPD" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
     
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Invoice' as "Document_Type",
                t1."WhsCode"
        from    "PCH1" t1
                inner join "OPCH" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
      
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Credit Memo' as "Document_Type",
                t1."WhsCode"
        from    "RPC1" t1
                inner join "ORPC" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Correction Invocie' as "Document_Type",
                t1."WhsCode"
        from    "CPI1" t1
                inner join "OCPI" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'AP Correction Reversal' as "Document_Type",
                t1."WhsCode"
        from    "CPV1" t1
                inner join "OCPV" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t0."DocType" = 'I'
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Goods Receipt' as "Document_Type",
                t1."WhsCode"
        from    "IGN1" t1
                inner join "OIGN" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Goods Issue' as "Document_Type",
                t1."WhsCode"
        from    "IGE1" t1
                inner join "OIGE" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                '' as "ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Inventory Transfer' as "Document_Type",
                t0."Filler"
        from    "OWTR" t0
        where   t0."Filler" not in ( select   "WhsCode"
                                   from     "OWHS" )
    
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Inventory Transfer' as "Document_Type",
                t1."WhsCode"
        from    "WTR1" t1
                inner join "OWTR" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
        
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."SerialNum" as nvarchar(100)),
                t0."OrderNum",
                'Old Work Order' as "Document_Type",
                t1."WhsCode"
        from    "WKO1" t1
                inner join "OWKO" t0 on t0."OrderNum" = t1."OrderNum"
                                      and t1."WhsCode" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
       
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Production Order_Components' as "Document_Type",
                t1."wareHouse"
        from    "WOR1" t1
                inner join "OWOR" t0 on t0."DocEntry" = t1."DocEntry"
                                      and t1."wareHouse" not in (
                                      select    "WhsCode"
                                      from      "OWHS" )
    
        union
        SELECT  distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t0."ItemCode",
                cast (t0."DocNum" as nvarchar(100)),
                t0."DocEntry",
                'Production Order_BOM' as "Document_Type",
                t0."Warehouse"
        from    "OWOR" t0
        where   t0."Warehouse" not in ( select    "Warehouse"
                                      from      "OWHS" )
        
        union
       
        SELECT distinct
                'WareHouse in document doesnt exist Warehouse defintion' as "Description",
                t1."ItemCode",
                t1."Ref1",
                t1."MessageID",
                'Stock log' as "Document_Type",
                t1."LocCode"
        from    "OILM" t1
        where   t1."LocCode" not in ( select  "WhsCode"
                                    from    "OWHS" );

select COUNT("ItemCode") INTO rowcount
     from   "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_WareHouse";
If :rowcount > 0 
    then
	INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'WareHouse in document doesnt exist Warehouse defintion');
        CntScenarios := :CntScenarios + 1;
    end if;



 select COUNT("DocDate") INTO rowcount
     from   "OILM" t0
            inner join "ORTT" t1 on t0."DocDate" = t1."RateDate"
                                  and t0."PriceCurr" = t1."Currency"
                                  and IFNULL("PriceCurr", '') <> ''
                                  and IFNULL("PriceCurr", '') <> :Main_Currency
                                  and IFNULL(t1."Rate", 0) = 0;
If :rowcount > 0  
    then
	INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Price Rate is missing in exchange rate table');
       CntScenarios := :CntScenarios + 1;
    end if;


if :Main_Currency <> :Sys_Currency 
  then  
  select COUNT(t0."RefDate") INTO rowcount
       from   "OJDT" t0 
        where  t0."TransType" not in (-3,-5,10000046) 
               and not exists (select t1."RateDate" 
                               from   "ORTT" t1 
                               where  t0."RefDate" = t1."RateDate" 
                                      and :Sys_Currency = t1."Currency");   
    If :rowcount > 0  
    then
	INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Price Rate is missing in exchange rate table');
       CntScenarios := :CntScenarios + 1;
    end if;
     
  end if;



Select COUNT(T0."ItemCode") INTO rowcount
     from   "OITM" T0
     where  t0."InvntItem" = 'Y'
            and t0."EvalSystem" is null;
if :rowcount > 0 
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'No valuation method is defined for item');         
       CntScenarios := :CntScenarios + 1;
    end if;

select COUNT("ItemCode") INTO rowcount
     from   "OITM"
     where  "TreeType" = 'P'
            and "ItemCode" not in ( select    "Code"
                                  from      "OITT" )
            and ( "ItemCode" in ( select  "ItemCode"
                                from    "IGN1"
                                where   "BaseType" = 202 )
                  or "ItemCode" in ( select   "ItemCode"
                                   from     "IGE1"
                                   where    "BaseType" = 202 )
                );
if :rowcount > 0 
    then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'BOM item has no BOM defintion');         
       CntScenarios := :CntScenarios + 1;
    end if;
	

Select COUNT(T1."ItemCode") into rowcount
	from
     (select o."ItemCode" from OITM o where o."InvntItem" = 'N' and (ifnull(o."OnOrder",0) <> 0 or
     ifnull(o."IsCommited",0) <> 0 or ifnull(o."OnHand",0) <> 0 or
     ifnull(o."Consig",0) <> 0 or IfNULL(o."StockValue",0) <> 0)
	 union all
     select i."ItemCode"
     from OITW i INNER JOIN OITM o on o."ItemCode"= i."ItemCode"
	 where o."InvntItem" = 'N' and (ifnull(i."OnOrder",0) <> 0 or ifnull(i."IsCommited",0) <> 0 or
	 ifnull(i."OnHand",0) <> 0 or ifnull(i."Consig",0) <> 0 or ifnull(i."StockValue",0) <> 0)) T1;
	 
if :rowcount > 0 
	then
		INSERT INTO "IVSRUserInteractionRequiredQuery_TempCheckStockResults" VALUES (N'Non Inventory Item with non zero quantities or stockvalue - RSP task 1177631');
	end if;
  
select * from "IVSRUserInteractionRequiredQuery_TempCheckStockResults";

delete from "IVSRUserInteractionRequiredQuery_TempCheckStockResults";
delete from "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_Item";
delete from "IVSRUserInteractionRequiredQuery_SBO_RSP_IVI_Affected_WareHouse";

END;

-- B1 DEPENDS: AFTER:SP:TmSp_OpportAnalysis_CRD AFTER:SP:TmSp_OpportAnalysis_ITM AFTER:SP:TmSp_OpportAnalysis_SLP AFTER:PT:PROCESS_END

CREATE PROCEDURE Tmsp_OpportAnalysis(in CondText nvarchar(2048),in ObjType int,in CutByObject int,in GetAllOpr nchar) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as 
begin
if (:ObjType = 4) then 
call TmSp_OpportAnalysis_ITM (:CondText, :CutByObject, 0, :GetAllOpr);
elseif (:ObjType = 52) then 
call TmSp_OpportAnalysis_ITM (:CondText, :CutByObject, 1, :GetAllOpr);
elseif (:ObjType = 2) then 
call TmSp_OpportAnalysis_CRD (:CondText, 0, :GetAllOpr);
elseif (:ObjType = 10) then 
call TmSp_OpportAnalysis_CRD (:CondText, 1, :GetAllOpr);
elseif (:ObjType = 53) then 
call TmSp_OpportAnalysis_SLP (:CondText, :GetAllOpr);
end if;
end;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_OpportAnalysis_CRD (in CondText nvarchar(2048),in GetCrdGroup int,in GetAllOpr nchar) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
tmpStr nvarchar(4000);
temp_table_count int;
v_sql nvarchar(1000);
begin
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:CondText);    
	call _TmSp_ValidateSpParam(:GetAllOpr);    
	
	delete from "TMPSOpportAnal_CRD_Output" where 1 = 1;
	
tmpStr := ' FROM OOPR T1 INNER JOIN OPR1 T0 ON T1."OpprId" = T0."OpprId" INNER JOIN OSLP T4 ON T1."SlpCode" = T4."SlpCode" INNER JOIN OCRD T3 ON T1."CardCode" = T3."CardCode" INNER JOIN OOST T2 ON T0."Step_Id" = T2."Num" INNER JOIN OCRG T5 ON T3."GroupCode" = T5."GroupCode"';
if :GetAllOpr = 'N' then
	if :GetCrdGroup = 0 then 
		tmpStr := 'SELECT T3."CardCode", T3."CardName", T1."Status", T1."OpprId"'||:tmpStr||'  '||:CondText || ' GROUP BY T3."CardCode", T3."CardName", T1."Status", T1."OpprId" ORDER BY T3."CardCode"';
	else 
		tmpStr := 'SELECT T5."GroupCode", T5."GroupName", T1."Status", T1."OpprId"'||:tmpStr||'  '||:CondText || ' GROUP BY T5."GroupCode", T5."GroupName", T1."Status", T1."OpprId" ORDER BY T5."GroupCode"';
	end if;
	
else
	tmpStr := 'SELECT T0."OpprId", T0."Line", T0."SlpCode", T0."CntctCode", T0."OpenDate", T0."CloseDate", T0."Step_Id", T0."ClosePrcnt", T0."MaxSumLoc", T0."MaxSumSys", CAST(T0."Memo" AS nvarchar(50)) AS Expr1, T0."DocId", T0."ObjType", T0."Status", T0."Linked", T0."WtSumLoc", T0."WtSumSys"'||:tmpStr||
	'  '||:CondText||' GROUP BY T0."OpprId", T0."Line", T0."SlpCode", T0."CntctCode", T0."OpenDate", T0."CloseDate", T0."Step_Id", T0."ClosePrcnt", T0."MaxSumLoc", T0."MaxSumSys", CAST(T0."Memo" AS nvarchar(50)), T0."DocId", T0."ObjType", T0."Status",  T0."Linked", T0."WtSumLoc", T0."WtSumSys" ORDER BY T0."OpprId"';
	create local temporary row table #OPP_AN_CRD_OUTPUT ("OpprId" int, "Line" int, "SlpCode" int, "CntctCode" int,"OpenDate" date,"CloseDate" date, "Step_Id" int, "ClosePrcnt" DECIMAL(21,6),"MaxSumLoc" DECIMAL(21,6),"MaxSumSys" DECIMAL(21,6), "Expr1" NVARCHAR(50), "DocId" INT, "ObjType" NVARCHAR (2), "Status" NVARCHAR (1), "Linked" NVARCHAR (1), "WtSumLoc" DECIMAL(21,6), "WtSumSys" DECIMAL(21,6));
end if;

	tmpStr:='INSERT INTO "TMPSOpportAnal_CRD_Output" '||tmpStr;
	exec (:tmpStr);
	select * from "TMPSOpportAnal_CRD_Output";
	delete from "TMPSOpportAnal_CRD_Output" where 1 = 1;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE        PROCEDURE TmSp_OpportAnalysis_ITM(
in CondText 	nvarchar(2048),
in cutByObject	int,
in GetItmGroup	int,
in GetAllOpr	nchar)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS

tmpStr		nvarchar(4000);
begin
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:CondText);    
	call _TmSp_ValidateSpParam(:GetAllOpr);   

if (:GetAllOpr = N'N')
then 
    if (:GetItmGroup = 0)
    then 
	if (:cutByObject = 2)
	then 
		tmpStr := 'SELECT '||
				'T9."ItemCode" AS "INV_Itm", T9."ItemName" AS "INV_ItmN", '||
				'T1."Status", T1."OpprId", '||
				'T1."IntCat1" as "Tmp1", T1."IntCat1" as "Tmp2", T1."RealSumLoc",   '||
				'T10."ItemCode" AS "RDR_Itm", T10."ItemName" AS "RDR_ItmN",  '||
				'T11."ItemCode" AS "DLN_Itm", T11."ItemName" AS "DLN_ItmN",  '||
		         '       T12."ItemCode" AS "QUT_Itm", T12."ItemName" AS "QUT_ItmN",  '||
		         '       T3."CardCode", T3."CardName"';
		         end if;
	 if (:cutByObject = 53)
	then 
		 tmpStr := 'SELECT  '||
				'T9."ItemCode" AS "INV_Itm", T9."ItemName" AS "INV_ItmN", '|| 
				'T1."Status", T1."OpprId",  '||
				'T1."IntCat1" as "Tmp1", T1."IntCat1" as "Tmp2", T1."RealSumLoc",  '|| 
				'T10."ItemCode" AS "RDR_Itm", T10."ItemName" AS "RDR_ItmN",  '||
				'T11."ItemCode" AS "DLN_Itm", T11."ItemName" AS "DLN_ItmN",  '||
		         '       T12."ItemCode" AS "QUT_Itm", T12."ItemName" AS "QUT_ItmN",  '||
		           '     T4."SlpCode", T4."SlpName"';
		           end if;
	if(:cutByObject <> 2 and :cutByObject <> 53)
	then
		 tmpStr := 'SELECT  '||
				'T9."ItemCode" AS "INV_Itm", T9."ItemName" AS "INV_ItmN", '||
				'T1."Status", T1."OpprId",   '||
				'T1."IntCat1" as "Tmp1", T1."IntCat1" as "Tmp2", T1."RealSumLoc", '||  
				'T10."ItemCode" AS "RDR_Itm", T10."ItemName" AS "RDR_ItmN",  '||
				'T11."ItemCode" AS "DLN_Itm", T11."ItemName" AS "DLN_ItmN",  '||
		           '     T12."ItemCode" AS "QUT_Itm", T12."ItemName" AS "QUT_ItmN" ';
		           end if;
		            
    
    
    else
    
	if (:cutByObject = 2)
	then
		 tmpStr := 'SELECT  '||
				'T13."ItmsGrpCod" AS "INV_Grp", T13."ItmsGrpNam" AS "INV_GrpN", '|| 
				'T1."Status", T1."OpprId",   '||
				'T1."IntCat1" as "Tmp1", T1."IntCat1" as "Tmp2", T1."RealSumLoc", '||  
				'T14."ItmsGrpCod" AS "RDR_Grp", T14."ItmsGrpNam" AS "RDR_GrpN", '|| 
	           '    		T15."ItmsGrpCod" AS "DLN_Grp", T15."ItmsGrpNam" AS "DLN_GrpN", '|| 
				'T16."ItmsGrpCod" AS "QUT_Grp", T16."ItmsGrpNam" AS "QUT_GrpN",  '||
				'T3."CardCode", T3."CardName"';
				end if;
	if ( :cutByObject = 53)
	then
		 tmpStr := 'SELECT  '||
				'T13."ItmsGrpCod" AS "INV_Grp", T13."ItmsGrpNam" AS "INV_GrpN",  '||
				'T1."Status", T1."OpprId",   '||
				'T1."IntCat1" as "Tmp1", T1."IntCat1" as "Tmp2", T1."RealSumLoc",  '|| 
				'T14."ItmsGrpCod" AS "RDR_Grp", T14."ItmsGrpNam" AS "RDR_GrpN",  '||
	           '    		T15."ItmsGrpCod" AS "DLN_Grp", T15."ItmsGrpNam" AS "DLN_GrpN", '|| 
				'T16."ItmsGrpCod" AS "QUT_Grp", T16."ItmsGrpNam" AS "QUT_GrpN", '|| 
				'T4."SlpCode", T4."SlpName"';
				end if ;
	if(:cutByObject <> 2 and :cutByObject <> 53)
	then 
		 tmpStr := 'SELECT  '||
				'T13."ItmsGrpCod" AS "INV_Grp", T13."ItmsGrpNam" AS "INV_GrpN",  '||
				'T1."Status", T1."OpprId",   '||
				'T1."IntCat1" as "Tmp1", T1."IntCat1" as "Tmp2", T1."RealSumLoc",  '|| 
				'T14."ItmsGrpCod" AS "RDR_Grp", T14."ItmsGrpNam" AS "RDR_GrpN", '|| 
	            '   		T15."ItmsGrpCod" AS "DLN_Grp", T15."ItmsGrpNam" AS "DLN_GrpN", '|| 
				'T16."ItmsGrpCod" AS "QUT_Grp", T16."ItmsGrpNam" AS "QUT_GrpN"';
	 end if; 
	end if;
  	

else
	 tmpStr := 'SELECT T0."OpprId", T0."Line", T0."SlpCode", T0."CntctCode",  '||
			'T0."OpenDate", T0."CloseDate", T0."Step_Id", T0."ClosePrcnt",  '||
			'T0."MaxSumLoc", T0."MaxSumSys",  '||
			'T0."Memo" AS "Expr1", T0."DocId",  '||
			'T0."ObjType", T0."Status", T0."Linked", T0."WtSumLoc", T0."WtSumSys"';
end if;
 tmpStr := :tmpStr || '  		FROM  OITM T9 INNER JOIN '||
              ' INV1 T5 ON T9."ItemCode" = T5."ItemCode" INNER JOIN '||
              ' OITB T13 ON T9."ItmsGrpCod" = T13."ItmsGrpCod" FULL OUTER JOIN '||
              ' OITM T10 INNER JOIN '||
               'RDR1 T6 ON T10."ItemCode" = T6."ItemCode" INNER JOIN '||
              ' OITB T14 ON T10."ItmsGrpCod" = T14."ItmsGrpCod" FULL OUTER JOIN '||
              ' OITM T11 INNER JOIN '||
              ' DLN1 T7 ON T11."ItemCode" = T7."ItemCode" INNER JOIN '||
              ' OITB T15 ON T11."ItmsGrpCod" = T15."ItmsGrpCod" FULL OUTER JOIN '||
               'OITM T12 INNER JOIN '||
              ' QUT1 T8 ON T12."ItemCode" = T8."ItemCode" INNER JOIN '||
               'OITB T16 ON T16."ItmsGrpCod" = T12."ItmsGrpCod" FULL OUTER JOIN '||
               'OSLP T4 INNER JOIN '||
              ' OPR1 T0 INNER JOIN '||
              ' OOST T2 ON T2."Num" = T0."Step_Id" ON T4."SlpCode" = T0."SlpCode" FULL OUTER JOIN '||
               'OCRD T3 INNER JOIN '||
               'OOPR T1 ON T3."CardCode" = T1."CardCode" ON T0."OpprId" = T1."OpprId" ON T8."DocEntry" = T0."DocId" AND T0."ObjType" = 23 ON T7."DocEntry" = T0."DocId" AND '|| 
               'T0."ObjType" = 15 ON T6."DocEntry" = T0."DocId" AND T0."ObjType" = 17 ON T5."DocEntry" = T0."DocId" AND T0."ObjType" = 13';

 tmpStr  :=  :tmpStr || ' ' ||:CondText || '  ORDER BY T0."ObjType", T1."OpprId"' ;

exec (:tmpStr);
end ;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_ValidateSpParam

CREATE PROCEDURE TmSp_OpportAnalysis_SLP(in condText nvarchar(2048),
	in getAllOpr nchar)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	tmpStr nvarchar(4000);
BEGIN
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
    call _TmSp_ValidateSpParam(:condText);    
	call _TmSp_ValidateSpParam(:getAllOpr);   
	
	IF :getAllOpr=N'N' THEN
		tmpStr := 'SELECT T4."SlpCode",T4."SlpName",T1."Status",T1."OpprId"';
	ELSE
		tmpStr := 'SELECT T0."OpprId",T0."Line",T0."SlpCode",T0."CntctCode",'||
			'T0."OpenDate",T0."CloseDate",T0."Step_Id",T0."ClosePrcnt",T0."MaxSumLoc",'||
			'T0."MaxSumSys",CAST(T0."Memo" AS nvarchar(50)) AS Expr1,T0."DocId",'||
			'T0."ObjType",T0."Status",T0."Linked",T0."WtSumLoc",T0."WtSumSys"';
	END IF;
	
	tmpStr := :tmpStr||' FROM OOPR T1 INNER JOIN OPR1 T0 ON T1."OpprId"=T0."OpprId"'||
		' INNER JOIN OSLP T4 ON T1."SlpCode"=T4."SlpCode" INNER JOIN'||
		' OCRD T3 On T1."CardCode"=T3."CardCode" INNER JOIN'||
		' OOST T2 ON T0."Step_Id"=T2."Num"';
		
	IF :getAllOpr=N'N' THEN
		tmpStr := :tmpStr||' '||:condText||' GROUP BY T4."SlpCode",T4."SlpName",'||
			'T1."Status",T1."OpprId" ORDER BY T4."SlpCode"';
	ELSE 
		tmpStr := :tmpStr || ' ' || :condText || ' GROUP BY T0."OpprId", T0."Line",'|| 
						'T0."SlpCode", T0."CntctCode",T0."OpenDate", T0."CloseDate",'|| 
						'T0."Step_Id", T0."ClosePrcnt",T0."MaxSumLoc", T0."MaxSumSys",'|| 
						'CAST(T0."Memo" AS nvarchar(50)),T0."DocId", T0."ObjType",'|| 
						'T0."Status", T0."Linked",T0."WtSumLoc", T0."WtSumSys"'||
						'ORDER BY T0."OpprId"';
	END IF;
	--select :tmpstr from dual;
	EXEC(:tmpStr);	
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

create procedure TmSp_OutboxSync 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
aCode int;
aUnsentCount int;
aVar int;

cursor dbHdr for 
        select "AlertCode"
		from OAOB
		where "WasSent" = 'N'
		group by "AlertCode";
begin
	
	open dbHdr;
	fetch dbHdr into aCode;

	while NOT dbHdr::NOTFOUND do
		select count(*) into aVar from ALR1 where ALR1."Code" = :aCode;
		if :aVar <> 0 then
			select count("AlertCode") into aUnsentCount
			from AOB1
			where AOB1."AlertCode" = :aCode and (
				"SendEMail" <> "Confirmed2" And NOT "Confirmed2" = 'E' Or
				"SendSMS" <> "Confirmed3" And NOT "Confirmed3" = 'E'  Or
				"SendFax" <> "Confirmed4" And NOT "Confirmed4" = 'E' );
		
			if (:aUnsentCount = 0) then
				update OAOB set "WasSent" = 'Y' where "AlertCode" = :aCode;
			end if;
		end if;
	fetch dbHdr into aCode;
	end while;
	close dbHdr;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_PaymentsAndDuePayments (
	v_CurrentYear SMALLINT,
	v_FromBPCode NVARCHAR(15),
	v_ToBPCode NVARCHAR(15))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	v_PreviousYear SMALLINT;
	v_PreviousYearStart DATETIME;
	v_CurrentYearEnd DATETIME;
	v_vendorCode NVARCHAR(15);
	v_cnt integer;
	-- Create cursor to loop through all vendors
	-- from given range
	CURSOR vendorCursor FOR
	SELECT
		"CardCode" as CardCode
	FROM
		OCRD
	WHERE
		"CardType" = 'S'
		AND "CardCode" >= :v_FromBPCode
		AND "CardCode" <= :v_ToBPCode
	ORDER BY
		"CardCode";
BEGIN

	select count (*) into v_cnt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#TBLPDPTEMPDATA';
   	if :v_cnt > 0 then
    	drop table #tblPDPTempData;
    end if;
	
	-- Create temporary table to store data to
	CREATE LOCAL TEMPORARY TABLE #tblPDPTempData
	(
		DocType nvarchar(20),
		DocAbs int,
		DocInstalmntID smallint,
		CardCode nvarchar(15),
		CardName nvarchar(200),
		DocumentDate datetime,
		DueDate datetime,
		PaymentDate datetime,
		DocTotal DECIMAL(21,6),
		OpenAmount DECIMAL(21,6),
		BoEStatus nvarchar(1),
		BoEAbs int,
		DaysOverdue int,
		YearFlag nvarchar(1),
		DueDateOverThreshold nvarchar(1),
		ReconciliationTotal DECIMAL(21,6),
		SubDocType nvarchar(20),
		SubDocAbs int,
		SubDocInstalmntID smallint,
		ReconcAbs int
	);

	delete from #tblPDPTempData where 1=1;

	-- Initialize local variables
	v_PreviousYear := :v_CurrentYear - 1;
	SELECT  TO_DATE(TO_VARCHAR(:v_PreviousYear) || TO_VARCHAR('0101'),'YYYYMMDD') INTO v_PreviousYearStart FROM DUMMY;
	SELECT  TO_DATE(TO_VARCHAR(:v_CurrentYear) || TO_VARCHAR('1231'),'YYYYMMDD') INTO v_CurrentYearEnd FROM DUMMY;

	-- Initialize cursor variable
	
	FOR cur_row as vendorCursor DO 

	-- Select PCH records
		INSERT INTO #tblPDPTempData
		SELECT
			T0."ObjType",
			T1."DocEntry",
			T1."InstlmntID",
			T0."CardCode",
			T0."CardName",
			T0."TaxDate",
			T1."DueDate",
			NULL,
			T1."InsTotal",
			(T1."InsTotal" - T1."PaidToDate"),
			NULL,
			NULL,
			0,
			N'N',
			N'N',
			(
				SELECT
					-ABS (Sum (Ix."ReconSum"))
				FROM
				(
					SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'18'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'46'
						INNER JOIN OVPM I3 ON I3."DocNum" = I2."SrcObjAbs" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I1."SrcObjAbs" = T0."DocEntry"
						
					UNION SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'18'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'19'
						INNER JOIN ORPC I3 ON I3."DocEntry" = I2."SrcObjAbs" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I1."SrcObjAbs" = T0."DocEntry"
						
					UNION SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'18'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'30'
						INNER JOIN OJDT I3 ON I3."TransId" = I2."SrcObjAbs"
						INNER JOIN JDT1 I4 ON I4."TransId" = I3."TransId" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I4."Debit" <> 0
						AND I1."SrcObjAbs" = T0."DocEntry"
				) Ix
			),
			NULL,
			NULL,
			NULL,
			NULL
		FROM
			"OPCH" T0
			INNER JOIN "PCH6" T1 ON T1."DocEntry" = T0."DocEntry"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode 
			AND T0."CANCELED" = 'N'
			AND T1."InsTotal" > 0
			
		-- Select payments for PCH records
		UNION SELECT
			T3."ObjType",
			T2."DocEntry",
			T2."InstlmntID",
			T3."CardCode",
			T3."CardName",
			T1."TaxDate",
			T1."DocDueDate",
			T1."TaxDate",
			T0."SumApplied",
			T0."SumApplied",
			T4."BoeStatus",
			T4."BoeKey",
			0,
			N'N',
			N'N',
			NULL,
			T1."ObjType",
			T1."DocEntry",
			-1,
			NULL
		FROM
			"VPM2" T0
			INNER JOIN "OVPM" T1 ON T1."DocNum" = T0."DocNum"
			INNER JOIN "PCH6" T2 ON T2."DocEntry" = T0."DocEntry"
				AND T2."InstlmntID" = T0."InstId"
				AND T0."InvType" = N'18'
			INNER JOIN "OPCH" T3 ON T3."DocEntry" = T2."DocEntry"
			LEFT OUTER JOIN "OBOE" T4 ON T4."BoeKey" = T1."BoeAbs"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T1."TaxDate" <= :v_CurrentYearEnd
			)
			AND T3."CardCode" = cur_row.CardCode
			AND T3."CANCELED" = 'N'
			AND T2."InsTotal" > 0
			AND T1."Canceled" = 'N'
			
		-- Select credit memos for PCH records
		UNION SELECT
			T0."ObjType",
			T1."DocEntry",
			T1."InstlmntID",
			T5."CardCode",
			T5."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T6."InsTotal",
			(T6."InsTotal" - T6."PaidToDate"),
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			NULL,
			T6."ObjType",
			T6."DocEntry",
			T6."InstlmntID",
			NULL
		FROM
			"OPCH" T0
			INNER JOIN "PCH6" T1 ON T1."DocEntry" = T0."DocEntry"
			INNER JOIN "OITR" T2 ON T2."ReconType" = N'4'
			INNER JOIN "ITR1" T3 ON T3."ReconNum" = T2."ReconNum"
				AND T3."SrcObjAbs" = T0."DocEntry"
				AND T3."SrcObjTyp" = N'18'
			INNER JOIN "ITR1" T4 ON T4."ReconNum" = T3."ReconNum"
				AND T4."SrcObjTyp" = N'19'
			INNER JOIN "ORPC" T5 ON T5."DocEntry" = T4."SrcObjAbs"
			INNER JOIN "RPC6" T6 ON T6."DocEntry" = T5."DocEntry"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T0."CANCELED" = 'N'
			AND T1."InsTotal" > 0
			AND T2."CancelAbs" = 0
		
		-- Select reconciled payments for PCH records
		UNION SELECT
			T3."ObjType",
			T3."DocEntry",
			T4."InstlmntID",
			T3."CardCode",
			T3."CardName",
			T5."TaxDate",
			T5."DocDueDate",
			T5."TaxDate",
			T1."ReconSum",
			T1."ReconSum",
			T6."BoeStatus",
			T6."BoeKey",
			0,
			N'N',
			N'N',
			T2."ReconSum",
			T5."ObjType",
			T5."DocEntry",
			-1,
			T0."ReconNum"
		FROM
			"OITR" T0
			INNER JOIN "ITR1" T1 ON T1."ReconNum" = T0."ReconNum"
				AND T1."SrcObjTyp" = N'18'
			INNER JOIN "ITR1" T2 ON T2."ReconNum" = T0."ReconNum"
				AND T2."SrcObjTyp" = N'46'
			INNER JOIN "OPCH" T3 ON T3."DocEntry" = T1."SrcObjAbs"
			INNER JOIN "PCH6" T4 ON T4."DocEntry" = T3."DocEntry"
				AND T1."TransRowId" = T4."InstlmntID" - 1
			INNER JOIN "OVPM" T5 ON T5."DocEntry" = T2."SrcObjAbs"
			LEFT OUTER JOIN "OBOE" T6 ON T6."BoeKey" = T5."BoeAbs"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T3."CardCode" = cur_row.CardCode
			AND T5."Canceled" = 'N'
			AND T0."CancelAbs" = 0
			AND T0."ReconType" = N'0'
		
		-- Select reconciled credit memos for PCH records
		UNION SELECT
			T3."ObjType",
			T3."DocEntry",
			T4."InstlmntID",
			T3."CardCode",
			T3."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T1."ReconSum",
			T1."ReconSum",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			T2."ReconSum",
			T6."ObjType",
			T6."DocEntry",
			T6."InstlmntID",
			T0."ReconNum"
		FROM
			"OITR" T0
			INNER JOIN "ITR1" T1 ON T1."ReconNum" = T0."ReconNum"
				AND T1."SrcObjTyp" = N'18'
			INNER JOIN "ITR1" T2 ON T2."ReconNum" = T0."ReconNum"
				AND T2."SrcObjTyp" = N'19'
			INNER JOIN "OPCH" T3 ON T3."DocEntry" = T1."SrcObjAbs"
			INNER JOIN "PCH6" T4 ON T4."DocEntry" = T3."DocEntry"
			INNER JOIN "ORPC" T5 ON T5."DocEntry" = T2."SrcObjAbs"
			INNER JOIN "RPC6" T6 ON T6."DocEntry" = T5."DocEntry"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T3."CardCode" = cur_row.CardCode
			AND T5."CANCELED" = 'N'
			AND T0."CancelAbs" = 0
			AND T0."ReconType" = N'0'
			
		-- Select reconciled journal entries (CM type) for PCH records
		UNION SELECT
			T0."ObjType",
			T1."DocEntry",
			T1."InstlmntID",
			T7."CardCode",
			T7."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T3."ReconSum",
			T3."ReconSum",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			T4."ReconSum",
			T6."ObjType",
			T6."TransId",
			T6."Line_ID" + 1,
			T2."ReconNum"
		FROM
			"OPCH" T0
			INNER JOIN "PCH6" T1 ON T1."DocEntry" = T0."DocEntry"
			INNER JOIN "OITR" T2 ON T2."ReconType" = N'0'
			INNER JOIN "ITR1" T3 ON T3."ReconNum" = T2."ReconNum"
				AND T3."SrcObjAbs" = T0."DocEntry"
				AND T3."SrcObjTyp" = N'18'
			INNER JOIN "ITR1" T4 ON T4."ReconNum" = T3."ReconNum"
				AND T4."SrcObjTyp" = N'30'
			INNER JOIN "OJDT" T5 ON T5."TransId" = T4."SrcObjAbs"
			INNER JOIN "JDT1" T6 ON T6."TransId" = T5."TransId"
			INNER JOIN "OCRD" T7 ON T7."CardCode" = T6."ShortName"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T0."CANCELED" = 'N'
			AND T1."InsTotal" > 0
			AND T6."Debit" <> 0
			AND T2."CancelAbs" = 0
		
		-- Select DPO records
		UNION SELECT
			T0."ObjType",
			T1."DocEntry",
			T1."InstlmntID",
			T0."CardCode",
			T0."CardName",
			T0."TaxDate",
			T1."DueDate",
			NULL,
			T1."InsTotal",
			(T1."InsTotal" - T1."PaidToDate"),
			NULL,
			NULL,
			0,
			N'N',
			N'N',
			(
				SELECT
					-ABS (Sum (Ix."ReconSum"))
				FROM
				(
					SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'204'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'46'
						INNER JOIN OVPM I3 ON I3."DocNum" = I2."SrcObjAbs" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I1."SrcObjAbs" = T0."DocEntry"
						
					UNION SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'204'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'19'
						INNER JOIN ORPC I3 ON I3."DocEntry" = I2."SrcObjAbs" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I1."SrcObjAbs" = T0."DocEntry"
						
					UNION SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'204'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'30'
						INNER JOIN OJDT I3 ON I3."TransId" = I2."SrcObjAbs"
						INNER JOIN JDT1 I4 ON I4."TransId" = I3."TransId" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I4."Debit" <> 0
						AND I1."SrcObjAbs" = T0."DocEntry"
				) Ix
			),
			NULL,
			NULL,
			NULL,
			NULL
		FROM
			"ODPO" T0
			INNER JOIN "DPO6" T1 ON T1."DocEntry" = T0."DocEntry"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T0."CANCELED" = 'N'
			AND T1."InsTotal" > 0
		
		-- Select payments for DPO records
		UNION SELECT
			T3."ObjType",
			T2."DocEntry",
			T2."InstlmntID",
			T3."CardCode",
			T3."CardName",
			T3."TaxDate",
			T2."DueDate",
			T1."TaxDate",
			T0."SumApplied",
			T0."SumApplied",
			T4."BoeStatus",
			T4."BoeKey",
			0,
			N'N',
			N'N',
			NULL,
			T1."ObjType",
			T1."DocEntry",
			-1,
			NULL
		FROM
			"VPM2" T0
			INNER JOIN "OVPM" T1 ON T1."DocNum" = T0."DocNum"
			INNER JOIN "DPO6" T2 ON T2."DocEntry" = T0."DocEntry"
				AND T2."InstlmntID" = T0."InstId"
				AND T0."InvType" = N'204'
			INNER JOIN "ODPO" T3 ON T3."DocEntry" = T2."DocEntry"
			LEFT OUTER JOIN "OBOE" T4 ON T4."BoeKey" = T1."BoeAbs"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T1."TaxDate" <= :v_CurrentYearEnd
			)
			AND T3."CardCode" = cur_row.CardCode
			AND T3."CANCELED" = 'N'
			AND T2."InsTotal" > 0
			AND T1."Canceled" = 'N'
		
		-- Select credit memos for DPO records
		UNION SELECT
			T0."ObjType",
			T1."DocEntry",
			T1."InstlmntID",
			T5."CardCode",
			T5."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T6."InsTotal",
			(T6."InsTotal" - T6."PaidToDate"),
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			NULL,
			T6."ObjType",
			T6."DocEntry",
			T6."InstlmntID",
			NULL
		FROM
			"ODPO" T0
			INNER JOIN "DPO6" T1 ON T1."DocEntry" = T0."DocEntry"
			INNER JOIN "OITR" T2 ON T2."ReconType" = N'4'
			INNER JOIN "ITR1" T3 ON T3."ReconNum" = T2."ReconNum"
				AND T3."SrcObjAbs" = T0."DocEntry"
				AND T3."SrcObjTyp" = N'204'
			INNER JOIN "ITR1" T4 ON T4."ReconNum" = T3."ReconNum"
				AND T4."SrcObjTyp" = N'19'
			INNER JOIN "ORPC" T5 ON T5."DocEntry" = T4."SrcObjAbs"
			INNER JOIN "RPC6" T6 ON T6."DocEntry" = T5."DocEntry"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T0."CANCELED" = 'N'
			AND T1."InsTotal" > 0
			AND T2."CancelAbs" = 0
		
		-- Select reconciled payments for DPO records
		UNION SELECT
			T3."ObjType",
			T3."DocEntry",
			T4."InstlmntID",
			T3."CardCode",
			T3."CardName",
			T5."TaxDate",
			T5."DocDueDate",
			T5."TaxDate",
			T1."ReconSum",
			T1."ReconSum",
			T6."BoeStatus",
			T6."BoeKey",
			0,
			N'N',
			N'N',
			T2."ReconSum",
			T5."ObjType",
			T5."DocEntry",
			-1,
			T0."ReconNum"
		FROM
			"OITR" T0
			INNER JOIN "ITR1" T1 ON T1."ReconNum" = T0."ReconNum"
				AND T1."SrcObjTyp" = N'204'
			INNER JOIN "ITR1" T2 ON T2."ReconNum" = T0."ReconNum"
				AND T2."SrcObjTyp" = N'46'
			INNER JOIN "ODPO" T3 ON T3."DocEntry" = T1."SrcObjAbs"
			INNER JOIN "DPO6" T4 ON T4."DocEntry" = T3."DocEntry"
				AND T1."TransRowId" = T4."InstlmntID" - 1
			INNER JOIN "OVPM" T5 ON T5."DocEntry" = T2."SrcObjAbs"
			LEFT OUTER JOIN "OBOE" T6 ON T6."BoeKey" = T5."BoeAbs"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T3."CardCode" = cur_row.CardCode
			AND T5."Canceled" = 'N'
			AND T0."CancelAbs" = 0
			AND T0."ReconType" = N'0'
		
		-- Select reconciled credit memos for DPO records
		UNION SELECT
			T3."ObjType",
			T3."DocEntry",
			T4."InstlmntID",
			T3."CardCode",
			T3."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T1."ReconSum",
			T1."ReconSum",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			T2."ReconSum",
			T6."ObjType",
			T6."DocEntry",
			T6."InstlmntID",
			T0."ReconNum"
		FROM
			"OITR" T0
			INNER JOIN "ITR1" T1 ON T1."ReconNum" = T0."ReconNum"
				AND T1."SrcObjTyp" = N'204'
			INNER JOIN "ITR1" T2 ON T2."ReconNum" = T0."ReconNum"
				AND T2."SrcObjTyp" = N'19'
			INNER JOIN "ODPO" T3 ON T3."DocEntry" = T1."SrcObjAbs"
			INNER JOIN "DPO6" T4 ON T4."DocEntry" = T3."DocEntry"
			INNER JOIN "ORPC" T5 ON T5."DocEntry" = T2."SrcObjAbs"
			INNER JOIN "RPC6" T6 ON T6."DocEntry" = T5."DocEntry"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T3."CardCode" = cur_row.CardCode
			AND T5."CANCELED" = 'N'
			AND T0."CancelAbs" = 0
			AND T0."ReconType" = N'0'
		
		-- Select reconciled journal entries (CM type) for DPO records
		UNION SELECT
			T0."ObjType",
			T1."DocEntry",
			T1."InstlmntID",
			T7."CardCode",
			T7."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T3."ReconSum",
			T3."ReconSum",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			T4."ReconSum",
			T6."ObjType",
			T6."TransId",
			T6."Line_ID" + 1,
			T2."ReconNum"
		FROM
			"ODPO" T0
			INNER JOIN "DPO6" T1 ON T1."DocEntry" = T0."DocEntry"
			INNER JOIN "OITR" T2 ON T2."ReconType" = N'0'
			INNER JOIN "ITR1" T3 ON T3."ReconNum" = T2."ReconNum"
				AND T3."SrcObjAbs" = T0."DocEntry"
				AND T3."SrcObjTyp" = N'204'
			INNER JOIN "ITR1" T4 ON T4."ReconNum" = T3."ReconNum"
				AND T4."SrcObjTyp" = N'30'
			INNER JOIN "OJDT" T5 ON T5."TransId" = T4."SrcObjAbs"
			INNER JOIN "JDT1" T6 ON T6."TransId" = T5."TransId"
			INNER JOIN "OCRD" T7 ON T7."CardCode" = T6."ShortName"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T0."CANCELED" = 'N'
			AND T1."InsTotal" > 0
			AND T6."Debit" <> 0
			AND T2."CancelAbs" = 0

		-- Select JE records (invoice type)
		UNION SELECT
			T0."ObjType",
			T1."TransId",
			T1."Line_ID" + 1,
			T2."CardCode",
			T2."CardName",
			T0."TaxDate",
			T1."DueDate",
			NULL,
			T1."Credit",
			T1."BalDueCred",
			NULL,
			NULL,
			0,
			N'N',
			N'N',
			(
				SELECT
					-ABS (Sum (Ix."ReconSum"))
				FROM
				(
					SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'30'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'46'
						INNER JOIN OVPM I3 ON I3."DocNum" = I2."SrcObjAbs" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I1."SrcObjAbs" = T0."TransId"
						
					UNION SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'30'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'19'
						INNER JOIN ORPC I3 ON I3."DocEntry" = I2."SrcObjAbs" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I1."SrcObjAbs" = T0."TransId"
						
					UNION SELECT
						I2."ReconSum"
					FROM
						OITR I0
						INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
							AND I1."SrcObjTyp" = N'30'
						INNER JOIN ITR1 I2 ON I2."ReconNum" = I0."ReconNum"
							AND I2."SrcObjTyp" = N'30'
						INNER JOIN OJDT I3 ON I3."TransId" = I2."SrcObjAbs"
						INNER JOIN JDT1 I4 ON I4."TransId" = I3."TransId" 
					WHERE
						I0."CancelAbs" = 0
						AND I0."ReconType" IN (0, 3)
						AND I3."TaxDate" > :v_CurrentYearEnd
						AND I4."Debit" <> 0
						AND I1."SrcObjAbs" = T0."TransId"
						AND I2."SrcObjAbs" <> T0."TransId"
				) Ix
			),
			NULL,
			NULL,
			NULL,
			NULL
		FROM
			"OJDT" T0
			INNER JOIN "JDT1" T1 ON T1."TransId" = T0."TransId"
			INNER JOIN "OCRD" T2 ON T2."CardCode" = T1."ShortName"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
			)
			AND T1."ShortName" = cur_row.CardCode
			AND T0."TransType" IN (N'30',N'-2',N'-3')
			AND T1."Credit" <> 0
			AND T0."StornoToTr" IS NULL
			AND NOT EXISTS (
				SELECT
					T0."TransId"
				FROM
					"OJDT" U0
				WHERE
					U0."StornoToTr" = T0."TransId"
			)
		
		-- Select payments for JE records
		UNION SELECT
			T3."ObjType",
			T2."TransId",
			T2."Line_ID" + 1,
			T4."CardCode",
			T4."CardName",
			T1."TaxDate",
			T1."DocDueDate",
			T1."TaxDate",
			T0."SumApplied",
			T0."SumApplied",
			T5."BoeStatus",
			T5."BoeKey",
			0,
			N'N',
			N'N',
			NULL,
			T1."ObjType",
			T1."DocEntry",
			-1,
			NULL
		FROM
			"VPM2" T0
			INNER JOIN "OVPM" T1 ON T1."DocNum" = T0."DocNum"
			INNER JOIN "JDT1" T2 ON T2."TransId" = T0."DocEntry"
				AND T0."InvType" = N'30'
			INNER JOIN "OJDT" T3 ON T3."TransId" = T2."TransId"
			INNER JOIN "OCRD" T4 ON T4."CardCode" = T2."ShortName"
			LEFT OUTER JOIN "OBOE" T5 ON T5."BoeKey" = T1."BoeAbs"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T1."TaxDate" <= :v_CurrentYearEnd
			)
			AND T2."ShortName" = cur_row.CardCode
			AND T3."TransType" IN (N'30',N'-2',N'-3')
			AND T2."Credit" <> 0
			AND T3."StornoToTr" IS NULL
			AND NOT EXISTS (
				SELECT
					T0."DocEntry"
				FROM
					"OJDT" U0
				WHERE
					U0."StornoToTr" = T3."TransId"
			)
			AND T1."Canceled" = 'N'
		
		-- Select reconciled payments for JE records
		UNION SELECT
			T3."ObjType",
			T4."TransId",
			T4."Line_ID" + 1,
			T7."CardCode",
			T7."CardName",
			T5."TaxDate",
			T5."DocDueDate",
			T5."TaxDate",
			T1."ReconSum",
			T1."ReconSum",
			T6."BoeStatus",
			T6."BoeKey",
			0,
			N'N',
			N'N',
			T2."ReconSum",
			T5."ObjType",
			T5."DocEntry",
			-1,
			T0."ReconNum"
		FROM
			"OITR" T0
			INNER JOIN "ITR1" T1 ON T1."ReconNum" = T0."ReconNum"
				AND T1."SrcObjTyp" = N'30'
			INNER JOIN "ITR1" T2 ON T2."ReconNum" = T0."ReconNum"
				AND T2."SrcObjTyp" = N'46'
			INNER JOIN "OJDT" T3 ON T3."TransId" = T1."SrcObjAbs"
			INNER JOIN "JDT1" T4 ON T4."TransId" = T3."TransId"
				AND T1."TransRowId" = T4."Line_ID"
			INNER JOIN "OVPM" T5 ON T5."DocEntry" = T2."SrcObjAbs"
			LEFT OUTER JOIN "OBOE" T6 ON T6."BoeKey" = T5."BoeAbs"
			INNER JOIN "OCRD" T7 ON T7."CardCode" = T1."ShortName"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T4."ShortName" = cur_row.CardCode
			AND T4."Credit" <> 0
			AND T3."StornoToTr" IS NULL
			AND NOT EXISTS (
				SELECT
					T0."ReconNum"
				FROM
					"OJDT" U0
				WHERE
					U0."StornoToTr" = T3."TransId"
			)
			AND T5."Canceled" = 'N'
			AND T0."CancelAbs" = 0
			AND T0."ReconType" = N'0'
		
		-- Select reconciled credit memos for JE records
		UNION SELECT
			T3."ObjType",
			T4."TransId",
			T4."Line_ID" + 1,
			T7."CardCode",
			T7."CardName",
			T5."TaxDate",
			T5."DocDueDate",
			T5."TaxDate",
			T1."ReconSum",
			T1."ReconSum",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			T2."ReconSum",
			T6."ObjType",
			T6."DocEntry",
			T6."InstlmntID",
			T0."ReconNum"
		FROM
			"OITR" T0
			INNER JOIN "ITR1" T1 ON T1."ReconNum" = T0."ReconNum"
				AND T1."SrcObjTyp" = N'30'
			INNER JOIN "ITR1" T2 ON T2."ReconNum" = T0."ReconNum"
				AND T2."SrcObjTyp" = N'19'
			INNER JOIN "OJDT" T3 ON T3."TransId" = T1."SrcObjAbs"
			INNER JOIN "JDT1" T4 ON T4."TransId" = T3."TransId"
			INNER JOIN "ORPC" T5 ON T5."DocEntry" = T2."SrcObjAbs"
			INNER JOIN "RPC6" T6 ON T6."DocEntry" = T6."DocEntry"
			INNER JOIN "OCRD" T7 ON T7."CardCode" = T1."ShortName"
		WHERE
			(
				T3."TaxDate" >= :v_PreviousYearStart
				AND T3."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T4."ShortName" = cur_row.CardCode
			AND T4."Credit" <> 0
			AND T3."StornoToTr" IS NULL
			AND NOT EXISTS (
				SELECT
					T0."ReconNum"
				FROM
					"OJDT" U0
				WHERE
					U0."StornoToTr" = T3."TransId"
			)
			AND T5."CANCELED" = 'N'
			AND T0."CancelAbs" = 0
			AND T0."ReconType" = N'0'
		
		-- Select reconciled journal entries (CM type) for JE (invoice type) records
		UNION SELECT
			T0."ObjType",
			T1."TransId",
			T1."Line_ID" + 1,
			T7."CardCode",
			T7."CardName",
			T5."TaxDate",
			T6."DueDate",
			T5."TaxDate",
			T3."ReconSum",
			T3."ReconSum",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			T4."ReconSum",
			T6."ObjType",
			T6."TransId",
			T6."Line_ID" + 1,
			T2."ReconNum"
		FROM
			"OJDT" T0
			INNER JOIN "JDT1" T1 ON T1."TransId" = T0."TransId"
				AND T1."Credit" <> 0
			INNER JOIN "OITR" T2 ON T2."ReconType" = N'0'
			INNER JOIN "ITR1" T3 ON T3."ReconNum" = T2."ReconNum"
				AND T3."SrcObjAbs" = T0."TransId"
				AND T3."SrcObjTyp" = N'30'
			INNER JOIN "ITR1" T4 ON T4."ReconNum" = T3."ReconNum"
				AND T4."SrcObjTyp" = N'30'
			INNER JOIN "OJDT" T5 ON T5."TransId" = T4."SrcObjAbs"
			INNER JOIN "JDT1" T6 ON T6."TransId" = T5."TransId"
			INNER JOIN "OCRD" T7 ON T7."CardCode" = T6."ShortName"
				AND T7."CardCode" = T1."ShortName"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
				AND T5."TaxDate" <= :v_CurrentYearEnd
			)
			AND T7."CardCode" = cur_row.CardCode
			AND T6."Debit" <> 0
			AND T2."CancelAbs" = 0
			
		-- Select non-based payments (they may be paid by BoE
		-- and may be partially reconciled)
		UNION SELECT
			T0."ObjType",
			T0."DocEntry",
			-1,
			T0."CardCode",
			T0."CardName",
			T0."TaxDate",
			T0."DocDueDate",
			T0."TaxDate",
			T0."NoDocSum",
			T0."NoDocSum",
			(
				SELECT
					"BoeStatus"
				FROM
					OBOE B0
				WHERE
					B0."BoeKey" = T0."BoeAbs"
			),
			T0."BoeAbs",
			0,
			'N',
			'N',
			(
				SELECT
					Sum (I1."ReconSum")
				FROM
					OITR I0
					INNER JOIN ITR1 I1 ON I1."ReconNum" = I0."ReconNum"
				WHERE
					I0."CancelAbs" = 0
					AND I0."ReconType" IN (0, 3)
					AND I1."SrcObjTyp" = 46
					AND I1."SrcObjAbs" = T0."DocEntry"
			),
			T0."ObjType",
			T0."DocEntry",
			-1,
			NULL
		FROM
			OVPM T0
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T0."NoDocSum" > 0
		
		-- Select non-based credit memos
		UNION SELECT
			T0."ObjType",
			T1."DocEntry",
			-1,
			T0."CardCode",
			T0."CardName",
			T0."TaxDate",
			T1."DueDate",
			NULL,
			T1."InsTotal",
			(T1."InsTotal" - T1."PaidToDate"),
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			NULL,
			NULL,
			NULL,
			NULL,
			NULL 
		FROM
			"ORPC" T0
			INNER JOIN "RPC6" T1 ON T1."DocEntry" = T0."DocEntry"
			LEFT OUTER JOIN "ITR1" T2 ON T2."SrcObjAbs" = T0."DocEntry"
				AND T2."SrcObjTyp" = N'19'
			LEFT OUTER JOIN "OITR" T3 ON T3."ReconNum" = T2."ReconNum"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
			)
			AND T0."CardCode" = cur_row.CardCode
			AND T1."InsTotal" > 0
			AND T1."InsTotal" > T1."PaidToDate"
			AND
			(
				T3."ReconType" IS NULL
				OR T3."ReconType" <> N'4'
			)

		-- Select JE records (credit memo type)
		UNION SELECT
			T0."ObjType",
			T1."TransId",
			T1."Line_ID" + 1,
			T2."CardCode",
			T2."CardName",
			T0."TaxDate",
			T1."DueDate",
			NULL,
			T1."Debit",
			T1."BalDueDeb",
			NULL,
			NULL,
			-10,
			N'N',
			N'N',
			NULL,
			NULL,
			NULL,
			NULL,
			NULL
		FROM
			"OJDT" T0
			INNER JOIN "JDT1" T1 ON T1."TransId" = T0."TransId"
			INNER JOIN "OCRD" T2 ON T2."CardCode" = T1."ShortName"
		WHERE
			(
				T0."TaxDate" >= :v_PreviousYearStart
				AND T0."TaxDate" <= :v_CurrentYearEnd
			)
			AND T1."ShortName" = cur_row.CardCode
			AND T0."TransType" IN (N'30',N'-2',N'-3')
			AND T1."Debit" <> 0
			AND T1."BalDueDeb" > 0
			AND T0."StornoToTr" IS NULL
			AND NOT EXISTS (
				SELECT
					T0."TransId"
				FROM
					"OJDT" U0
				WHERE
					U0."StornoToTr" = T0."TransId"
			);
	
	END FOR; -- Close cursor


	-- Present collected data
	SELECT
		DocType AS "Doc. No. (Type)", -- 1
		DocAbs AS "Doc. No. (Doc. number)", -- 2
		DocInstalmntID AS "Doc. No. (Installment ID)", -- 3
		CardCode AS "Card Code", -- 4
		CardName AS "Card Name", -- 5
		DocumentDate AS "Document Date", -- 6
		DueDate AS "Due Date", -- 7
		PaymentDate AS "Payment Date", -- 8
		DocTotal AS "Document Total", -- 9
		OpenAmount AS "Open Amount", -- 10
		BoEStatus AS "BoE Status", -- 11
		BoEAbs AS "BoE Key", -- 12
		DaysOverdue AS "Days Overdue", -- 13
		YearFlag AS "Year Flag", -- 14
		DueDateOverThreshold AS "Due Date is Over Threshold", -- 15
		ReconciliationTotal AS "Reconciliation Total", -- 16
		SubDocType AS "Sub Document Type", -- 17
		SubDocAbs AS "Sub Document Number", -- 18
		SubDocInstalmntID AS "Sub Document Installment", --19
		ReconcAbs AS "Reconciliation Number" --20
	FROM
		#tblPDPTempData
	ORDER BY
		1, 2, 3, 17, 18, 19, 20;

	-- Close table
	--DROP TABLE #tblPDPTempData;
END;

CREATE PROCEDURE TmSp_Pervasive_Sequence_Creation
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
