CASE WHEN UPPER(T7."ReportCode") = 'C-INT' OR UPPER(T7."ReportCode") = 'IVACON-INT' THEN T5."VatSum" ELSE 0 END AS "I6", 
CASE WHEN UPPER(T7."ReportCode") = 'C-NOR' OR UPPER(T7."ReportCode") = 'IVACON-NOR' THEN COALESCE(T5."BaseSum", 0) ELSE 0 END AS "I7", 
CASE WHEN UPPER(T7."ReportCode") = 'C-NOR' OR UPPER(T7."ReportCode") = 'IVACON-NOR' THEN T5."VatSum" ELSE 0 END AS "I8", 
CASE WHEN T5."ExtVatSum" <> '0' THEN T5."ExtVatSum" ELSE 0 END AS "L", (T1."VatSum") AS "G", (T1."DocTotal") AS "H", (T1."WTSum") AS "WTSum", 'Q:' ||
 substring(T1."SignDigest", 1, 1) || substring(T1."SignDigest", 11, 1) || substring(T1."SignDigest", 21, 1) || substring(T1."SignDigest", 31, 1) AS "SignD",
CASE WHEN IFNULL(T8."AssignedID", '') = '' THEN '0' ELSE T8."AssignedID" || '-' || T1."DocNum" END AS "ATCUD"
FROM INV12 T0 
INNER JOIN OINV T1 ON T0."DocEntry" = T1."DocEntry" 
INNER JOIN OCRD T2 ON T1."CardCode" = T2."CardCode" 
INNER JOIN OTAX T6 ON T6."SrcObjType" = T1."ObjType" AND T6."SrcObjAbs" = T1."DocEntry" 
INNER JOIN TAX1 T5 ON T5."AbsEntry" = T6."AbsEntry" 
INNER JOIN OVTG T7 ON T5."TaxCode" = T7."Code"
INNER JOIN NNM1 T8 ON T1."Series" = T8."Series", OADM T3 WHERE T1."DocEntry" = :DocKey) 

AS tblData 
GROUP BY A, B, C, D, E, F, G1, G2, G3, G, H, "SignD", "ATCUD";

END;

