 rtrim(CAST(CAST(SUM(I5) AS decimal(20, 2)) AS char)) || '*' END || CASE WHEN SUM(I6) IS NULL OR SUM(I6) = 0 THEN '' ELSE 'I6:' || rtrim(CAST(CAST(SUM(I6) AS decimal(20, 2)) AS char)) ||
 '*' END || CASE WHEN SUM(I7) IS NULL OR SUM(I7) = 0 THEN '' ELSE 'I7:' || rtrim(CAST(CAST(SUM(I7) AS decimal(20, 2)) AS char)) || '*' END || 
