-- 24 RCT Incomming Payment
-- CALL TmSp_QRCodeSPGenerated_PT_24(:DocKey, :ObjectId);
-- DROP PROCEDURE TmSp_QRCodeSPGenerated_PT_24;
CREATE PROCEDURE TmSp_QRCodeSPGenerated_PT_24 (in DocKey integer, in ObjectID integer)
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
AS
BEGIN

SELECT 'A:' || A || '*' || 'B:' || B || '*' || 'C:' || C || '*' || 'D:' || D || '*' || 'E:' || E || '*' || 'F:' || F || '*' || 'G:' || G1 || ' ' || G2 || '/' || G3 || '*' || 'H:' || ATCUD ||
 '*' || CAST('I1:' AS varchar(500)) || 'PT' || '*' || CASE WHEN SUM(I2) IS NULL OR SUM(IFNULL(I2, 0)) = 0 THEN '' ELSE 'I2:' || rtrim(CAST(CAST(SUM(I2) AS decimal(20, 2)) AS char)) ||
 '*' END || CASE WHEN SUM(I3) IS NULL OR SUM(I3) = 0 THEN '' ELSE 'I3:' || rtrim(CAST(CAST(SUM(I3) AS decimal(20, 2)) AS char)) || '*' END || CASE WHEN SUM(I4) IS NULL OR SUM(I4) = 0 THEN
 '' ELSE 'I4:' || rtrim(CAST(CAST(SUM(I4) AS decimal(20, 2)) AS char)) || '*' END || CASE WHEN SUM(I5) IS NULL OR SUM(I5) = 0 THEN '' ELSE 'I5:' || rtrim(CAST(CAST(SUM(I5) 
AS decimal(20, 2)) AS char)) || '*' END || CASE WHEN SUM(I6) IS NULL OR SUM(I6) = 0 THEN '' ELSE 'I6:' || rtrim(CAST(CAST(SUM(I6) AS decimal(20, 2)) AS char)) || '*' END || 
CASE WHEN SUM(I7) IS NULL OR SUM(I7) = 0 THEN '' ELSE 'I7:' || rtrim(CAST(CAST(SUM(I7) AS decimal(20, 2)) AS char)) || '*' END || 
CASE WHEN SUM(I8) IS NULL OR SUM(I8) = 0 THEN '' ELSE 'I8:' || rtrim(CAST(CAST(SUM(I8) AS decimal(20, 2)) AS char)) || '*' END || 
CASE WHEN SUM(L) IS NULL OR SUM(L) = 0 THEN '' ELSE 'L:' || rtrim(CAST(CAST(SUM(L) AS decimal(20, 2)) AS char)) || '*' END || 'N:' || rtrim(CAST(CAST(G AS decimal(12, 2)) AS char)) ||
 '*' || 'O:' || rtrim(CAST(CAST(H AS decimal(12, 2)) AS char)) || '*' || CASE WHEN SUM("WtSum") IS NULL OR SUM("WtSum") = 0 THEN '' ELSE 
'P:' || CAST(SUM("WtSum") AS varchar(20)) || '*' END || "SignD" || '*' || 
'R:' || '0130' 
FROM (
SELECT substring(T3."TaxIdNum", 3, 11) AS "A", 
(CASE WHEN T2."LicTradNum" <> ' ' THEN substring(T2."LicTradNum", 3, 11) ELSE '999999990' END) AS "B", 
'PT' AS "C", 
(CASE WHEN T7."Code" IS NULL THEN 'RG' ELSE 'RC' END) AS "D", 
(CASE WHEN T1."Canceled" = 'Y' OR T1."Canceled" = 'C' THEN 'A' ELSE 'N' END) AS "E", 
(TO_CHAR (T1."DocDate" , 'YYYYMMDD')) AS "F", 
T1."ObjType" AS "G1", CAST(T1."Series" AS varchar) AS "G2", CAST(T1."DocNum" AS varchar) AS "G3", 
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") LIKE 'M%' OR UPPER(T7."ReportCode") = 'OUTROS / ISE' OR UPPER(T7."ReportCode") = 'UE / ISE' OR UPPER(T7."ReportCode") = 'IVACON-ISE' THEN IFNULL(T5."BaseSum", 0) ELSE 0 END) END) AS "I2",
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") = 'C-RED' OR UPPER(T7."ReportCode") = 'IVACON-RED' THEN T5."BaseSum" ELSE 0 END) END) AS "I3", 
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") = 'C-RED' OR UPPER(T7."ReportCode") = 'IVACON-RED' THEN T5."VatSum" ELSE 0 END) END) AS "I4",
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") = 'C-INT' OR UPPER(T7."ReportCode") = 'IVACON-INT' THEN T5."BaseSum" ELSE 0 END) END) AS "I5",
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") = 'C-INT' OR UPPER(T7."ReportCode") = 'IVACON-INT' THEN T5."VatSum" ELSE 0 END) END) AS "I6",
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") = 'C-NOR' OR UPPER(T7."ReportCode") = 'IVACON-NOR' THEN COALESCE(T5."BaseSum", 0) ELSE 0 END) END) AS "I7",
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN UPPER(T7."ReportCode") = 'C-NOR' OR UPPER(T7."ReportCode") = 'IVACON-NOR' THEN T5."VatSum" ELSE 0 END) END) AS "I8",
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(CASE WHEN T5."ExtVatSum" <> '0' THEN T5."ExtVatSum" ELSE 0 END) END) AS "L",
(T1."VatSum") AS "G", 
(T1."DocTotal") AS "H", 
(CASE WHEN T7."Code" IS NULL THEN NULL ELSE
	(T1."WtSum") END) AS "WtSum",
'Q:' || substring(T1."SignDigest", 1, 1) || substring(T1."SignDigest", 11, 1) || substring(T1."SignDigest", 21, 1) || substring(T1."SignDigest", 31, 1) AS "SignD",
CASE WHEN IFNULL(T8."AssignedID", '') = '' THEN '0' ELSE T8."AssignedID" || '-' || T1."DocNum" END AS "ATCUD"
FROM ORCT T1 
INNER JOIN OCRD T2 ON T1."CardCode" = T2."CardCode" 
LEFT OUTER JOIN OTAX T6 ON T6."SrcObjType" = T1."ObjType" AND T6."SrcObjAbs" = T1."DocEntry" 
LEFT OUTER JOIN TAX1 T5 ON T5."AbsEntry" = T6."AbsEntry" 
LEFT OUTER JOIN OVTG T7 ON T5."TaxCode" = T7."Code"
INNER JOIN NNM1 T8 ON T1."Series" = T8."Series",
OADM T3 
WHERE T1."DocEntry" = :DocKey) 
AS tblData 
GROUP BY A, B, C, D, E, F, G1, G2, G3, G, H, "SignD", "ATCUD";

END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE   procedure TmSp_RebuildAcctMatch(IN actCode nvarchar (15), IN actCurr nvarchar (3),IN useLocal nchar (1), IN isCard nvarchar (1), IN external1 nvarchar(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
maxMatch  	int;
count1     	int;
maxMatchBnk    int;
begin



if (:external1 = N'N')
THEN
	if (:useLocal = N'Y')
	THEN
		    insert into OMTH 
			select "ShortName", N'I', "IntrnMatch", sum ("Debit"),
			:isCard, N'0', -1, CURRENT_TIMESTAMP, :actCurr, NULL, N'1' ,CURRENT_TIMESTAMP
			from JDT1 where "ShortName" = :actCode  and "IntrnMatch" > 0
			group by "ShortName", "IntrnMatch" ; 

	else
	
		    insert into OMTH 
			select "ShortName", N'I', "IntrnMatch", sum ("FCDebit"),
			:isCard, N'0', -1, CURRENT_TIMESTAMP, :actCurr, NULL, N'1' ,CURRENT_TIMESTAMP
			from JDT1 where "ShortName" = :actCode  and "IntrnMatch" > 0
			group by "ShortName", "IntrnMatch" ; 
	end IF;
END IF;

if (:external1 = N'Y')
THEN
	if (:useLocal = N'Y')
	THEN
		    insert into OMTH 
			select "ShortName", N'E', "ExtrMatch", (sum("Debit")-sum("Credit")),
			:isCard, N'0', -1, CURRENT_TIMESTAMP, :actCurr, NULL, N'1' ,CURRENT_TIMESTAMP
			from JDT1 where "ShortName" = :actCode  and "ExtrMatch" >0
			group by "ShortName", "ExtrMatch"  ;
	
	else
	
		    insert into OMTH 
			select "ShortName", N'E', "ExtrMatch", (sum("FCDebit")-sum("FCCredit")),
			:isCard, N'0', -1, CURRENT_TIMESTAMP, :actCurr, NULL, N'1' ,CURRENT_TIMESTAMP
			from JDT1 where "ShortName" = :actCode  and "ExtrMatch" >0
			group by "ShortName", "ExtrMatch" ; 		
	end	IF;	
end IF;

end;

-- B1 DEPENDS: AFTER:SP:TmSp_RebuildAcctMatch AFTER:PT:PROCESS_END

CREATE  procedure TmSp_RebuildMatchHistory  
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
As
errCode	int;
maxMatchNum	int;
mainCurr	nvarchar (3);
actCode	nvarchar (15);
actCurr	nvarchar (3);
useLocal	nchar (1);
external1	nchar (1);
isCard		nchar (1);
    cursor dbAccounts  for 
	SELECT JDT1."Account", max(OACT."ActCurr"), N'A'
	FROM OACT INNER JOIN
        	JDT1 ON OACT."AcctCode" = JDT1."Account"
	WHERE (JDT1."IntrnMatch" > 0 AND JDT1."ShortName" = JDT1."Account")
	GROUP by JDT1."Account"
	union
	SELECT JDT1."ShortName", max(OCRD."Currency"), N'C'
	FROM OCRD INNER JOIN
        	JDT1 ON OCRD."CardCode" = JDT1."ShortName"
	WHERE (JDT1."IntrnMatch" > 0 AND JDT1."ShortName" <> JDT1."Account")
	GROUP by JDT1."ShortName";
	cursor dbAccounts1  for 
	SELECT JDT1."Account", max(OACT."ActCurr"), N'A'
	FROM OACT INNER JOIN
        	JDT1 ON OACT."AcctCode" = JDT1."Account"
	WHERE (JDT1."ExtrMatch" > 0 AND JDT1."ShortName" = JDT1."Account")
	GROUP by JDT1."Account"
	union
	SELECT JDT1."ShortName", max(OCRD."Currency"), N'C'
	FROM OCRD INNER JOIN
        	JDT1 ON OCRD."CardCode" = JDT1."ShortName"
	WHERE (JDT1."ExtrMatch" > 0 AND JDT1."ShortName" <> JDT1."Account")
	GROUP by JDT1."ShortName";
begin



select "MainCurncy" into mainCurr from OADM;



delete from OMTH;

open dbAccounts;
Fetch dbAccounts into actCode, actCurr, isCard;
while NOT dbAccounts::NOTFOUND do
    if (:actCurr = N'' or :actCurr = N'##')
    THEN
	actCurr := :mainCurr;
    END IF;
    if (:actCurr = :mainCurr)
    THEN
	useLocal := N'Y';
    else
	useLocal := N'N';
	END IF;
   
    update OACT set "IntrMatch" = 0
	where "AcctCode" = :actCode;

    update OCRD set "InMatchNum" = 0
	where "CardCode" = :actCode;

    external1 := N'N';
	
	IF (:actCode <> NULL) Then
		CALL TmSp_RebuildAcctMatch(:actCode, :actCurr, :useLocal, :isCard, :external1);
	End IF;
	
    select max("MatchNum") INTO maxMatchNum from OMTH 
    where "MthAcctCod" = :actCode AND "IsInternal" = N'I';     

    update OACT set "IntrMatch" = :maxMatchNum 
    where "AcctCode" = :actCode;

    update OCRD set "InMatchNum" = :maxMatchNum
    where "CardCode" = :actCode;

    Fetch dbAccounts into actCode, actCurr, isCard;
end WHILE;

close dbAccounts;


--external


	
open dbAccounts1;
Fetch dbAccounts1 into actCode, actCurr,isCard;
while NOT dbAccounts1::NOTFOUND do


    if (:actCurr = N'' or :actCurr = N'##')
    THEN
	actCurr := :mainCurr;
     END IF;
    if (:actCurr = :mainCurr)
    THEN
	useLocal := N'Y';
    else
	useLocal := N'N';
	END IF;
   
    update OACT set "ExtrMatch" = 0
	where "AcctCode" = :actCode;

    update OCRD set "ExMatchNum" = 0
	where "CardCode" = :actCode;

    external1 := N'Y';

    CALL TmSp_RebuildAcctMatch(:actCode, :actCurr, :useLocal, :isCard, :external1);

    select max("MatchNum") INTO maxMatchNum from OMTH 
    where "MthAcctCod" = :actCode AND "IsInternal" = N'E' ;    

    update OACT set "ExtrMatch" = :maxMatchNum
    where "AcctCode" = :actCode;

    update OCRD set "ExMatchNum" = :maxMatchNum
    where "CardCode" = :actCode;

    Fetch dbAccounts1 into actCode, actCurr, isCard;
end WHILE;

close dbAccounts1;


end;

