CREATE  PROCEDURE TmSp_Sales_An_Itm_Sng_Y_LC (
in ObjectType 		nChar(3),
in ShowType 		nChar(3),
in DocDateFrom 		nvarchar(30),
in DocDateTo		nvarchar(30),
in DocDueDateFrom 	nvarchar(8),
in DocDueDateTo		nvarchar(8),
in CardCodeFrom		nvarchar(30),
in CardCodeTo		nvarchar(30),
in CrdGroupCode 	nvarchar(11),
in ItemCodeFrom		nvarchar(100),
in ItemCodeTo		nvarchar(100),
in ItmGroupCode 	nvarchar(11),
in ItmProps	   		nvarchar(70),
in CrdProps   		nvarchar(70 ),
in SlpCodeFrom		nvarchar(155),
in SlpCodeTo		nvarchar(155),
in TaxDateFrom 		nvarchar(8),
in TaxDateTo		nvarchar(8),
in Brand			nvarchar(11),			
in PrjCode			nvarchar(20),
in RptType			int,
in cutbyObject		nchar(3),
in DspFrznBP		nvarchar(1),
in DspFrznITM		nvarchar(1),
in BPLIdSet 		nvarchar(1000),
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS

Header 			nvarchar(4);
Lines  			nvarchar(4);
opObject 		nvarchar(4);
WTLines			nvarchar(4);
 
BEGIN
	opObject := 'NON';

	if (:ObjectType = 'INV') then
		Header := 'OINV';
		Lines :=  'INV1';
		WTLines := :ObjectType || '5';
		opObject := 'RIN';		
	end if;
	
	if (:ObjectType = 'CSI') then		
		Header := 'OCSI';
		Lines :=  ' (SELECT * FROM CSI1) ';
		WTLines := :ObjectType || '5';
		opObject := 'NON';
	end if;
	
	if (:ObjectType = 'CSV') then			
		Header := 'OCSV';
		Lines := ' (SELECT * FROM CSV1) ';
		WTLines := :ObjectType || '5';
		opObject := 'NON';
	end if;
	
	if (:ObjectType = 'RDR') then
		Header := 'ORDR';
		Lines := 'RDR1';
		WTLines := :ObjectType || '5';
		opObject := 'NON';		
	end if;

	if (:ObjectType = 'DLN') then
		Header := 'ODLN';
		Lines := 'DLN1';
		WTLines := :ObjectType || '5';
		opObject := 'RDN';		
	end if;

	if (:ObjectType = 'RIN') then
		Header := 'ORIN';
		Lines := 'RIN1';
		WTLines := :ObjectType || '5';
	end if;

	if (:ObjectType = 'RDN') then
		Header := 'ORDN';
		Lines :=  'RDN1';
		WTLines := :ObjectType || '5';
	end if;


	delete from "TmpPsar_Sales_An_Itm_Sng_Y_LC";
			
	call TmSp_Sales_An_Itm_Sng_Y_LC_Insert(:ObjectType, :ShowType, :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, 
		:SlpCodeTo, :TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine );
	if(:ObjectType = 'INV' OR :ObjectType = 'DLN') then
	call TmSp_Sales_An_Itm_Sng_Y_LC_Insert(:ObjectType, 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, 
		:SlpCodeTo, :TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine );
	end if;
-- print :tmpStr
-- print :WhereStr
	
	if (:ShowType = 'SNG') then
		if (:cutbyObject = 'NON') then		
			if (:opObject <> 'NON') then
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert (:opObject, 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert (:opObject, 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
			end if;
		
			if (:ObjectType = 'INV') then 		
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert ('CSI' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
					:TaxDateFrom, :TaxDateTo, '', '', 0, 'NON', :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
				

				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert ('CSV' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);			
			end if;

			select ItemCode, ItemName,  'Dummy' ,'Dummy' ,'Dummy' ,Sum(Quantity), Sum(Sales), Sum(GrossProfit), Avg(GrossPrcnt), Sum(SalesSys), Sum(GrossProfitSys), Avg(GrossPrcntSys), Sum(SalesForPrcnt) , Sum(SalesForPrcntSys)
			from "TmpPsar_Sales_An_Itm_Sng_Y_LC" 
			group by ItemCode, ItemName
			Order By ItemCode;
			
		end if;
	
		if (:cutbyObject = 'SLP') then	
			if (:opObject <> 'NON') then
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert (:opObject, 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert (:opObject, 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
			end if;
		
			if (:ObjectType = 'INV') then 		
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert ('CSI' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
					:TaxDateFrom, :TaxDateTo, '', '', 0, 'NON', :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);

				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert ('CSV' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
			end if;

			select ItemCode, ItemName, SlpCode, SlpName ,'Dummy' ,Sum(Quantity), Sum(Sales), Sum(GrossProfit), Avg(GrossPrcnt), Sum(SalesSys), Sum(GrossProfitSys), Avg(GrossPrcntSys), Sum(SalesForPrcnt) , Sum(SalesForPrcntSys)
			from "TmpPsar_Sales_An_Itm_Sng_Y_LC" 
			group by ItemCode, ItemName,  SlpCode , SlpName
			Order By ItemCode, SlpCode;
			
		end if;
	
		if (:cutbyObject = 'CRD') then	
			if (:opObject <> 'NON') then
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert (:opObject, 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine); 
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert (:opObject, 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine); 
			end if;

			if (:ObjectType = 'INV') then 	
				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert ('CSI' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);

				call TmSp_Sales_An_Itm_Sng_Y_LC_Insert ('CSV' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom , :DocDueDateTo, 	 
				:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
				:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :WTaxEngine);
			end if;

			select ItemCode, ItemName, CardCode, CardName ,'Dummy' ,Sum(Quantity), Sum(Sales), Sum(GrossProfit), Avg(GrossPrcnt), Sum(SalesSys), Sum(GrossProfitSys), Avg(GrossPrcntSys), Sum(SalesForPrcnt) , Sum(SalesForPrcntSys)
			from "TmpPsar_Sales_An_Itm_Sng_Y_LC" 
			group by ItemCode, ItemName, CardCode , CardName
			Order By ItemCode, CardCode;
			
		end if;
	
	else
		select * From "TmpPsar_Sales_An_Itm_Sng_Y_LC";
	end if;
	
	delete from "TmpPsar_Sales_An_Itm_Sng_Y_LC";
	/* SBO_APA_DEV : TaxOnly */
		
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

CREATE procedure TmSp_Sales_An_Itm_Sng_Y_LC_Insert (
in ObjectType 		nChar(3),
in ShowType 		nChar(3),
in DocDateFrom_in 	nvarchar(30),   --= '19700101',
in DocDateTo_in		nvarchar(30),   --= '21000101',
in DocDueDateFrom_in 	nvarchar(8),   	--= '19700101',
in DocDueDateTo_in		nvarchar(8),   	--= '21000101',
in CardCodeFrom		nvarchar(30), 	--= '' ,
in CardCodeTo		nvarchar(30), 	--= '',
in CrdGroupCode  	nvarchar(11), 	--= '',
in ItemCodeFrom		nvarchar(100), 	--= '' ,
in ItemCodeTo		nvarchar(100), 	--= '',
in ItmGroupCode  	nvarchar(11), 	--= '',
in ItmProps	   		nvarchar(70), 	--= '',
in CrdProps   		nvarchar(70 ),	--= '',
in SlpCodeFrom		nvarchar(155), 	--= '',
in SlpCodeTo		nvarchar(155), 	--= '',
in TaxDateFrom_in 		nvarchar(8),   	--= '19700101',
in TaxDateTo_in		nvarchar(8),   	--= '21000101',
in Brand			nvarchar(11), 	--='',			
in PrjCode			nvarchar(20),   --='',
in RptType			int, 	     	--= 0,
in cutbyObject		nchar(3), 		--= 'NON',
in DspFrznBP		nvarchar(1), 		--= 'Y',
in DspFrznITM		nvarchar(1) ,		--= 'Y',
in BPLIdSet 		nvarchar(1000),	--= ''
in WTaxEngine		nvarchar(1)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS

DocDateFrom	 		nvarchar(30);
DocDateTo 			nvarchar(30);
DocDueDateFrom 		nvarchar(8); 
DocDueDateTo 		nvarchar(8);
TaxDateFrom 		nvarchar(8); 
TaxDateTo			nvarchar(8);

MultOrDivSysRate nvarchar(4);
Header 			nvarchar(4);
Lines  			nvarchar(255);
WTLines  		nvarchar(4);
--opObject 		nvarchar(4);
divideStr nvarchar(1000);
divideStrSys nvarchar(1000);
insertStr nvarchar(4000);

joinStr nvarchar(4000);
salesStr nvarchar(2000);
grossProfitStr nvarchar(2000);
grossPrcntStr nvarchar(2000);
priceSysStr nvarchar(2000);
salesSysStr nvarchar(2000);
grossProfitSysStr  nvarchar(2000);
grossPrcntSysStr	nvarchar(2000);
grossCalcStr		nvarchar(2000);
grossCalcSysStr	nvarchar(2000);
PropsRel 		nvarchar(10);
ii 				int;
jj 				int;
GrossBySal 		nChar(1);
WhereStr 		nvarchar(4000);
DiscSumSysColName nvarchar(20);
VatSysColName 	nvarchar(20);
QtyFldName 		nvarchar(100);
Mult 			nvarchar(5);
CutObjects nvarchar(50);
DpmAffectsTotal		int;
DpmSUM		nvarchar(500);
DpmSUM_SC		nvarchar(500);

begin

call _TmSp_ValidateSpParam (:ObjectType);
call _TmSp_ValidateSpParam (:ShowType);
call _TmSp_ValidateSpParam (:DocDateFrom_in);
call _TmSp_ValidateSpParam (:DocDateTo_in);
call _TmSp_ValidateSpParam (:DocDueDateFrom_in);
call _TmSp_ValidateSpParam (:DocDueDateTo_in);
call _TmSp_ValidateSpParam (:CardCodeFrom);
call _TmSp_ValidateSpParam (:CardCodeTo);
call _TmSp_ValidateSpParam (:CrdGroupCode);
call _TmSp_ValidateSpParam (:ItemCodeFrom);
call _TmSp_ValidateSpParam (:ItemCodeTo);
call _TmSp_ValidateSpParam (:ItmGroupCode);
call _TmSp_ValidateSpParam (:ItmProps);
call _TmSp_ValidateSpParam (:CrdProps);
call _TmSp_ValidateSpParam (:SlpCodeFrom);
call _TmSp_ValidateSpParam (:SlpCodeTo);
call _TmSp_ValidateSpParam (:TaxDateFrom_in);
call _TmSp_ValidateSpParam (:TaxDateTo_in);
call _TmSp_ValidateSpParam (:Brand);
call _TmSp_ValidateSpParam (:PrjCode);
call _TmSp_ValidateSpParam (:cutbyObject);
call _TmSp_ValidateSpParam (:DspFrznBP);
call _TmSp_ValidateSpParam (:DspFrznITM);
call _TmSp_ValidateSpParam (:BPLIdSet);
call _TmSp_ValidateSpParam (:WTaxEngine);

	DocDateFrom := DocDateFrom_in;
	DocDateTo := DocDateTo_in;
	DocDueDateFrom := DocDueDateFrom_in;
	DocDueDateTo := DocDueDateTo_in;
	TaxDateFrom :=	TaxDateFrom_in;
	TaxDateTo := TaxDateTo_in;
	
	SELECT CASE WHEN "DpmAffTot" = 'Y' THEN 1 ELSE 0 END into DpmAffectsTotal FROM CINF;
	
	if (:ObjectType = 'NON') then  
		--return (0)
		Mult := :Mult;
	end if;
		
	Select MIN("DirectRate") into MultOrDivSysRate from OADM;
	
	if (:MultOrDivSysRate = 'Y') then
		MultOrDivSysRate := '/';
	else
		MultOrDivSysRate := '*';
	end if;
	
	if ((:ShowType = 'SNG' or :ShowType = 'SN1' or :ShowType = 'SN2') OR (:ShowType = 'CAN' AND (:ObjectType = 'RIN' OR :ObjectType = 'RDN'))) then
		Mult := ' 1 '; 
	else
		Mult :=  ' -1 ';
	end if;
	
	if LENGTH(:DocDateFrom) = 0 then 	
		DocDateFrom := '19700101'; 
	end if;	
	if LENGTH(:DocDateTo) = 0 then 	
		DocDateTo := '21000101';
	end if;	
	if LENGTH(:DocDueDateFrom) = 0 then 	
		DocDueDateFrom :=  '19700101'; 
	end if;	
	if LENGTH(:DocDueDateTo) = 0 then 	
		DocDueDateTo := '21000101';
	end if;	
	if LENGTH(:TaxDateFrom) = 0 then 
		TaxDateFrom :=  '19700101'; 
	end if;
	if LENGTH(:TaxDateTo) = 0 then 	
		TaxDateTo := '21000101';
	end if;
	
	if (:ObjectType = 'INV') then
		Header := 'OINV';
		Lines :=  'INV1';
		WTLines := :ObjectType || '5';
		--opObject := 'RIN';		
	end if;
	
	if (:ObjectType = 'CSI') then		
		Header := 'OCSI';
		Lines :=  ' (SELECT * FROM CSI1) ';
		WTLines := :ObjectType || '5';
		--opObject := 'NON';
	end if;
	
	if (:ObjectType = 'CSV') then
		Header := 'OCSV';
		Lines := ' (SELECT * FROM CSV1) ';
		WTLines := :ObjectType || '5';
		--opObject := 'NON';
	end if;
	
	if (:ObjectType = 'RDR') then
		Header := 'ORDR';
		Lines := 'RDR1';
		WTLines := :ObjectType || '5';
		--opObject := 'NON';		
	end if;

	if (:ObjectType = 'DLN') then
		Header := 'ODLN';
		Lines := 'DLN1';
		WTLines := :ObjectType || '5';
		--opObject := 'RDN';		
	end if;

	if (:ObjectType = 'RIN') then
		Header := 'ORIN';
		Lines := 'RIN1';
		WTLines := :ObjectType || '5';
	end if;

	if (:ObjectType = 'RDN') then
		Header := 'ORDN';
		Lines :=  'RDN1';
		WTLines := :ObjectType || '5';
	end if;

-- Comment from original SQL SP 
--[RemoveCIN]
--if (:ObjectType = 'CIN')
--Begin
--	Set :Header = 'OCIN'
--	Set :Lines =  'CIN1'
--	WTLines := :ObjectType || '5';
--End

	SELECT TOP 1 COLUMN_NAME into DiscSumSysColName FROM "PUBLIC"."TABLE_COLUMNS" as A WHERE TABLE_NAME = :Header and POSITION = 58;	
	SELECT TOP 1 COLUMN_NAME into VatSysColName FROM "PUBLIC"."TABLE_COLUMNS" as A WHERE TABLE_NAME = :Header and POSITION = 57;	

	WhereStr :=' Main."DocDate" Between  TO_DATE( ''' ||  :DocDateFrom || ''', ''YYYYMMDD'' ) And  TO_DATE( ''' ||  :DocDateTo 
		|| ''', ''YYYYMMDD'' )  And  Main."DocDueDate" Between  TO_DATE( ''' ||  :DocDueDateFrom || ''', ''YYYYMMDD'' )   And  TO_DATE( ''' 
		||  :DocDueDateTo || ''', ''YYYYMMDD'' ) ';
	
--Card Code range
	if LENGTH(:CardCodeFrom) > 0 then 
		WhereStr := :WhereStr  || '   And    Main."CardCode" >=  N''' ||  :CardCodeFrom || '''  ';
	end if;

	if LENGTH(:CardCodeTo) > 0 then 
		WhereStr := :WhereStr   || '   And    Main."CardCode" <=  N''' ||  :CardCodeTo || '''  ';
	end if;
	
	--Sales person range
	if LENGTH(:SlpCodeFrom) > 0 then 	
		WhereStr := :WhereStr  || '    And   Slp."SlpName" >=  N''' ||  :SlpCodeFrom || '''  ';
	end if;
	
	if LENGTH(:SlpCodeTo) > 0 then 	
		WhereStr := :WhereStr  || '    And   Slp."SlpName" <=  N''' ||  :SlpCodeTo || '''  ';
	end if;

	--Item Code range
	if LENGTH(:ItemCodeFrom) > 0 then 	
		WhereStr := :WhereStr  || '    And    Items."ItemCode" >=  N''' ||  :ItemCodeFrom || '''  ';
	end if;
	
	if LENGTH(:ItemCodeTo) > 0 then 	
		WhereStr := :WhereStr  || '    And    Items."ItemCode" <=  N''' ||  :ItemCodeTo || '''  ';
	end if;

	WhereStr := :WhereStr  || '  And 	   Main."Instance" = 0 And	   Main."TaxDate"  Between  TO_DATE( ''' || :TaxDateFrom || ''', ''YYYYMMDD'' )  And  TO_DATE( ''' || :TaxDateTo || ''', ''YYYYMMDD'' )';
	
	
	if(:ObjectType='INV' OR :ObjectType='DLN' OR :ObjectType = 'RIN' OR :ObjectType = 'RDN') then
		if(:ShowType = 'CAN') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''C'' '	;
		else
			WhereStr := :WhereStr || 'And	   Main."CANCELED" <> ''C'' '	;
		end if;
	else
		if(:ObjectType <> 'CSI') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''N'' '	;
		end if;
	end if;
	
	if (:ObjectType = 'INV' or :ObjectType = 'DLN') then
		WhereStr := WhereStr || ' And Lines."Quantity" <> 0';
	end if;

	if LENGTH(:CrdGroupCode) > 0 then
		WhereStr := :WhereStr || ' And  Cards."GroupCode" = ' || :CrdGroupCode; 
	end if;
							
	if LENGTH(:CrdProps) > 0 then 
		if (SUBSTRING (:CrdProps, 65, 1)  = 'N') then
			PropsRel := ' OR ';
		else 
			PropsRel := ' AND ';
		end if;
		
		WhereStr := :WhereStr || '  And ( ';
		ii := 1;
		jj := 1;
		
		while (:ii <= 64) do
			if (SUBSTRING (:CrdProps, :ii, 1)  = 'Y') then
				if (:jj <> 1) then
					WhereStr := :WhereStr || :PropsRel;
				end if;
				 	
				WhereStr := :WhereStr || ' Cards."QryGroup' || Cast (:ii As nChar(2)) || '" = ''Y''';
				jj := :jj + 1;
			end if;
			 
			ii := :ii + 1;
		end while;
		WhereStr := :WhereStr || ') ';
		 
	end if;
	
	if LENGTH(:ItmProps) > 0 then 
		if (SUBSTRING (:ItmProps, 65, 1)  = 'N') then		
			PropsRel := ' OR ';		
		else
			PropsRel := ' AND ';
		end if;
		 
		WhereStr := :WhereStr || '  And ( '; 
		ii := 1;
		jj := 1;
		while (:ii <= 64) do		
			if (SUBSTRING (:ItmProps, :ii, 1)  = 'Y') then
				if (:jj <> 1) then
					WhereStr := :WhereStr || :PropsRel;
				end if;
				 	
				WhereStr := :WhereStr || ' Items."QryGroup' || Cast (:ii As Char(2)) || '" = ''Y''';
				jj := :jj + 1;
			end if;
			 
			ii := :ii + 1;
		end while;
		
		if(:jj = 1) then  
				WhereStr := WhereStr || ' 1 = 1 ';	/* fill empty brackets */ 
			end if;
		WhereStr := WhereStr || ') '; 
	end if;
	
	if LENGTH(:ItmGroupCode) > 0 then 
		WhereStr := WhereStr || ' And  ItmGrp."ItmsGrpCod" = ' || :ItmGroupCode; 
	end if;
	
	
	if (:ObjectType = 'RIN') then
		if(:ShowType <> 'CAN') then
			WhereStr := :WhereStr || ' AND NOT  EXISTS (SELECT 1 FROM '|| :ObjectType || '1 T1 WHERE T1."DocEntry" = Main."DocEntry"    AND T1."BaseType" = 203) ';
		else
			WhereStr := :WhereStr || ' AND NOT EXISTS (SELECT 1 FROM ' || :ObjectType || '1 T1 ,' || :ObjectType || '1 T2 WHERE T1."DocEntry" = Main."DocEntry"  AND T1."BaseType" = 14 AND T1."BaseEntry" = T2."DocEntry" AND T2."BaseType" = 203)';
		end if;
	end if;

	if (:ObjectType = 'INV' or :ObjectType = 'CSI' or :ObjectType = 'CSV' or :ObjectType = 'RIN') then	
		QtyFldName := ' Lines."Quantity"  ';	
	else	
		if (:ObjectType = 'DLN') then		
			QtyFldName := ' ( case when Lines."BaseType" in (13,165) then 0 else ( Lines."OpenCreQty" ) end )';		
		else		
			QtyFldName := ' Lines."OpenCreQty" ';
		end if;
	end if;
	
	DpmSUM := '';
	DpmSUM_SC := '';
	if (:DpmAffectsTotal = 1) then 	 	
		DpmSUM := ' + Sum(Distinct(Main."DpmAmnt")) ';		
		DpmSUM_SC := ' + Sum(Distinct(Main."DpmAmntSC")) ';		
	end if;


	divideStr := '( ( case when ( Sum(Distinct(Main."DocTotal")) - Sum(Distinct(Main."VatSum")) + Sum(Distinct(IfNull(Main."FoCTax",0))) - Sum(Distinct(Main."TotalExpns")) '
		|| ' + Sum(Distinct(Main."DiscSum")) ) = 0 then 0 else ( case (Sum(Distinct(Main."DocTotal")) ' || :DpmSUM 
		|| ' + IFNULL(WT."WTSum",0.0) - Sum(Distinct(Main."VatSum")) + Sum(Distinct(IfNull(Main."FoCTax",0))) - Sum(Distinct(Main."TotalExpns")) + Sum(Distinct(Main."DiscSum"))) '
		|| ' when 0 then 0 else (Sum(Distinct(Main."DiscSum")) / nullif((Sum(Distinct(Main."DocTotal"))' || :DpmSUM 
		|| ' + IFNULL(WT."WTSum",0.0)-Sum(Distinct(Main."VatSum")) + Sum(Distinct(IfNull(Main."FoCTax",0))) -Sum(Distinct(Main."TotalExpns"))+Sum(Distinct(Main."DiscSum"))),0)) '
		|| '  end) end ) * 100 ) / 100 ';

	divideStrSys := '( ( case when ((Sum(Distinct(Main."DocTotalSy"))  -  Sum(Distinct(Main."' || :VatSysColName || '"))  '
		|| ' + Sum(Distinct(IfNull(Main."FoCTaxSC",0))) -  Sum(Distinct(Main."TotalExpSC"))  + Sum(Distinct(Main."' || :DiscSumSysColName || '")))) = 0 ' 
		|| ' then 0 else (case (Sum(Distinct(Main."DocTotalSy")) ' || :DpmSUM_SC || ' + IFNULL(WT."WTSumSC",0.0) '
		|| ' -  Sum(Distinct(Main."' || :VatSysColName || '")) + Sum(Distinct(IfNull(Main."FoCTaxSC",0))) -  Sum(Distinct(Main."TotalExpSC"))  + Sum(Distinct(Main."' 
		|| :DiscSumSysColName || '"))) when 0 then 0 else (Sum(Distinct(Main."' || :DiscSumSysColName 
		|| '")) / nullif(Sum(Distinct(Main."DocTotalSy")) ' || :DpmSUM_SC || ' + IFNULL(WT."WTSumSC",0.0)-Sum(Distinct(Main."' 
		|| :VatSysColName || '")) + Sum(Distinct(IfNull(Main."FoCTaxSC",0))) -Sum(Distinct(Main."TotalExpSC")) + Sum(Distinct(Main."' || :DiscSumSysColName 
		|| '"))),0)) end) end ) * 100 ) / 100 ';

	insertStr := ' Insert Into "TmpPsar_Sales_An_Itm_Sng_Y_LC" ' 
		|| ' Select Main."DocEntry", Main."DocNum", Slp."SlpCode", Slp."SlpName", 	Cards."CardCode", Cards."CardName", '
		|| ' Main."DocDate", Main."DocDueDate",   Items."ItemCode", Items."ItemName", '
		|| ' 	case Lines."NoInvtryMv" when ''Y'' then 0 else '
		|| ' case Lines."UseBaseUn" when ''Y'' then  ' || :QtyFldName || ' * ' || :Mult 
		|| ' else (' || :QtyFldName || ' * Lines."NumPerMsr")  * ' || :Mult 
		|| ' end end as Quantity, '		
		|| ' 0 as Price, '; 		 

	if (:ObjectType = 'CSI' or :ObjectType = 'CSV') then	
		salesStr := '((((cast (Sum( Lines."LineTotal") as DECIMAL(21,6)) / nullif(Lines."Quantity",0))  / nullif(Lines."NumPerMsr",0))  * (' 
			|| :QtyFldName || ' * Lines."NumPerMsr")) )   * ' || :Mult || ' As Sales , ';
			
		grossProfitStr := '((((cast (Sum( Lines."LineTotal") as DECIMAL(21,6)) / nullif(Lines."Quantity",0))  / nullif(Lines."NumPerMsr",0))  * (' 
			|| :QtyFldName || ' * Lines."NumPerMsr")) - (Lines."GrossBuyPr" *' || :QtyFldName || ' )) * ' || :Mult || ' As GrossProfit,';
			
		grossPrcntStr := '-1 As GrossPrcnt,';
		
		priceSysStr := '0 As PriceSys ,';
		
		salesSysStr := '0 As SalesSys ,';
			
		grossProfitSysStr := ' 0 As GrossProfitSys,';
			
		grossPrcntSysStr := '-1 As GrossPrcntSys,Lines."LineNum", ';
		
		grossCalcStr := '0 AS GrossCalc,';
			
		grossCalcSysStr := '0 AS GrossCalcSys	';
	
	else
		salesStr := ' case when Lines."TaxOnly" = ''Y'' OR Lines."FreeChrgBP" = ''Y'' then  0 else ( (((cast (Sum( Lines."LineTotal") as DECIMAL(21,6)) / nullif(Lines."Quantity",0)) '
			|| '  / nullif(Lines."NumPerMsr",0))  * (' || :QtyFldName || ' * Lines."NumPerMsr"))  - (   (((cast (Sum( Lines."LineTotal") '
			|| ' as DECIMAL(21,6)) / nullif(Lines."Quantity",0))  / nullif(Lines."NumPerMsr",0))  * (' || :QtyFldName || ' * Lines."NumPerMsr")) * '
			|| :divideStr || ') )   * ' || :Mult || ' end as Sales, ';
			
		grossProfitStr := ' case when Lines."TaxOnly" = ''Y'' OR Lines."FreeChrgBP" = ''Y'' then (0 - (Lines."GrossBuyPr" * ' || :QtyFldName || ' )) * ' 
			|| :Mult || ' else ( (((cast (Sum( Lines."LineTotal") as DECIMAL(21,6)) / nullif(Lines."Quantity",0))  / nullif(Lines."NumPerMsr",0))  * (' 
			|| :QtyFldName || ' * Lines."NumPerMsr"))  - (   (((cast (Sum( Lines."LineTotal") as DECIMAL(21,6)) / nullif(Lines."Quantity",0)) '
			|| '  / nullif(Lines."NumPerMsr",0))  * (' || :QtyFldName || ' * Lines."NumPerMsr")) *  ' 
			|| :divideStr || ' )   - (Lines."GrossBuyPr" * ' || :QtyFldName || ' )) * ' || :Mult || ' end as GrossProfit, ';
			
		grossPrcntStr := ' -1  As GrossPrcnt,'; 
			
		priceSysStr := '  0 as PriceSys, ';
			
		salesSysStr := ' 0 as SalesSys, ';
			
		grossProfitSysStr := ' 0 as GrossProfitSys, ';
			
			
		grossPrcntSysStr :=	' -1  As GrossPrcntSYS, Lines."LineNum",';
	
	
		grossCalcStr := ' 0 as GrossCalc, ';
			
			
		grossCalcSysStr := ' 0 as GrossCalcSys';
	end if;

	joinStr := '  From  ' || :Header || ' Main 	'
		|| ' Inner Join ' || :Lines || ' Lines On Main."DocEntry" = Lines."DocEntry" '
		|| ' Inner Join OITM Items On Items."ItemCode" = Lines."ItemCode" '
		|| ' Inner Join OITB ItmGrp On ItmGrp."ItmsGrpCod" = Items."ItmsGrpCod" '
		|| ' Inner  Join OCRD Cards On Cards."CardCode" = Main."CardCode" ';
		
	if (:RptType = 0) then	
		joinStr := :joinStr || ' Inner Join OSLP slp On Slp."SlpCode" = Main."SlpCode" ';
	end if;
	
	if (:RptType = 1) then
		joinStr := :joinStr || ' Inner Join OSLP slp On Slp."SlpCode" = Lines."SlpCode" ';
	end if;
	
	if (:WTaxEngine = 'N') then
		joinStr := :joinStr || ' LEFT OUTER JOIN (select WT0."DocEntry", WT0."WTSum", WT0."WTSumSC" from ' || :Header 
		|| ' WT0 INNER JOIN ' || :WTLines || ' WT1 on WT1."AbsEntry" = WT0."DocEntry" where WT1."Category" = ''I'' '
		|| ' GROUP BY WT0."DocEntry", WT0."WTSum", WT0."WTSumSC") WT on WT."DocEntry" = Main."DocEntry" ';
	else
		joinStr := :joinStr || ' LEFT OUTER JOIN (select WT0."DocEntry", WT0."WTSum", WT0."WTSumSC" from ' || :Header 
		|| ' WT0 GROUP BY WT0."DocEntry", WT0."WTSum", WT0."WTSumSC") WT on WT."DocEntry" = Main."DocEntry" ';
	end if;
	
	if :DspFrznBP = 'N' then
		WhereStr := '(' || :WhereStr || ') And ' || '(Cards."validFor" = ''Y'' or (Cards."frozenFor" = ''Y'' and '
			|| '(Cards."frozenFrom" is not null or Cards."frozenTo" is not null)) or (Cards."validFor" = ''N'' and Cards."frozenFor" = ''N''))';
	end if;

	if :DspFrznITM = 'N' then
		WhereStr := '(' || :WhereStr || ') And ' || '(Items."validFor" = ''Y'' or (Items."frozenFor" = ''Y'' and '
			|| ' (Items."frozenFrom" is not null or Items."frozenTo" is not null)) or (Items."validFor" = ''N'' and Items."frozenFor" = ''N''))';
	end if;			
	
	if LENGTH(:BPLIdSet) > 0 then
		WhereStr := :WhereStr || ' And Main."BPLId" in (' || :BPLIdSet || ')';
	end if;

	WhereStr := ' Where ' || :WhereStr || '  Group BY Main."DocEntry", Slp."SlpCode", Slp."SlpName", '
		|| ' Main."DocEntry", Main."DocNum", Main."DocDate", '
		|| '  Items."ItemCode", Items."ItemName", Lines."TaxOnly", Lines."FreeChrgBP", Lines."Price", Main."DocDueDate", Cards."CardCode", Cards."CardName", '
		|| ' Lines."GrossBuyPr", Lines."Quantity", Main."SysRate", Lines."LineNum", Lines."NumPerMsr", '
		|| ' Lines."OpenCreQty",	Main."DocTotal", Main."VatSum", lines."UseBaseUn", WT."WTSum", WT."WTSumSC", Lines."BaseType", Lines."NoInvtryMv" ';
		
	if LENGTH(:CrdGroupCode) > 0 then 
		WhereStr := :WhereStr || ', Cards."GroupCode" '; 
	end if;
	
	if LENGTH(:ItmGroupCode) > 0 then 
		WhereStr := :WhereStr || ', ItmGrp."ItmsGrpCod" ';
	end if;

	WhereStr := :WhereStr || ' Order By Items."ItemCode", Main."DocEntry", Lines."LineNum" ';
  
	exec (:insertStr || :salesStr || :grossProfitStr || :grossPrcntStr || :priceSysStr || :salesSysStr || :grossProfitSysStr || :grossPrcntSysStr || :grossCalcStr || :grossCalcSysStr || :joinStr || :WhereStr);
	
	--select 1, (:insertStr || :salesStr || :grossProfitStr || :grossPrcntStr || :priceSysStr || :salesSysStr   ) from dummy
	--union all
	--select 2, (:grossProfitSysStr || :grossPrcntSysStr || :grossCalcStr || :grossCalcSysStr   ) from dummy
	--union all
	--select 3, ( :joinStr || :WhereStr  ) from dummy;	
		
end;

-- B1 DEPENDS: AFTER:SP:TmSp_Sales_An_Slp_Sng_M_Insert AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2

CREATE  PROCEDURE TmSp_Sales_An_Slp_Sng_M (
in ObjectType		nChar(3),
in ShowType			nChar(3),
in DocDateFrom 		nvarchar(30),
in DocDateTo		nvarchar(30),   -- = '21000101',
in DocDueDateFrom 	nvarchar(8),   -- = '19700101',
in DocDueDateTo		nvarchar(8),   -- = '21000101',
in CardCodeFrom		nvarchar(15), -- = '' ,
in CardCodeTo		nvarchar(15), -- = '',
in CrdGroupCode  	nvarchar(11), -- = '',
in ItemCodeFrom		nvarchar(50), -- = '' ,
in ItemCodeTo		nvarchar(50), -- = '',
in ItmGroupCode  	nvarchar(11), -- = '',
in ItmProps	   		nvarchar(70), -- = '',
in CrdProps   		nvarchar(70),-- = '',
in SlpCodeFrom		nvarchar(155), -- = '',
in SlpCodeTo		nvarchar(155), -- = '',
in TaxDateFrom 		nvarchar(8),   -- = '19700101',
in TaxDateTo		nvarchar(8),   -- = '21000101',
in Brand			nvarchar(11), -- ='',			
in PrjCode			nvarchar(20),   -- ='',
in RptType			int, 	     -- = 0,
in cutbyObject		nchar(3), -- = 'NON',
in DspFrznBP		nvarchar(1), -- = 'Y',
in DspFrznITM		nvarchar(1), -- = 'Y',
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1) -- = 'N'
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

   --* With Encryption

AS

Header 		nvarchar(4);
Lines  		nvarchar(4);
InstLines  	nvarchar(4);
opObject 	nvarchar(4);
WTLines		nvarchar(4);

BEGIN
	
	opObject := 'NON';
	
	if (:ObjectType = 'INV') then	
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		opObject := 'RIN';
		WTLines := 'INV5';
	end if;	
	if (:ObjectType = 'CSI') then	
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV') then	
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR') then	
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN') then	
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN') then	
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN') then	
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;
	
	delete from "TmpPsar_Sales_An_Slp_Sng_M";
							
	call TmSp_Sales_An_Slp_Sng_M_Insert (:ObjectType , :ShowType, :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
	
	if(:ObjectType = 'INV' OR :ObjectType = 'DLN') then
	call TmSp_Sales_An_Slp_Sng_M_Insert (:ObjectType , 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
	:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
	:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
	end if;
	/* End Here */

	--print @tmpStr
	--print @WhereStr

	if (:ShowType = 'SNG') then		
		if (:opObject <> 'NON') then
			call TmSp_Sales_An_Slp_Sng_M_Insert (:opObject , 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
			call TmSp_Sales_An_Slp_Sng_M_Insert (:opObject , 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
		end if;

		if (:ObjectType = 'INV') then 		
			call TmSp_Sales_An_Slp_Sng_M_Insert ('CSI' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
			
			call TmSp_Sales_An_Slp_Sng_M_Insert ('CSV' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
		end if;
	end if;
	
	Select CardCode, CardOrSlpName, Month, Year, Sum(Sales), Sum(GrossPrft) , Sum(GrossPrcnt) , Sum(SalesSys) , Sum(GrossPrftSys) , Sum(GrossPrcntSys), 
		Sum(SalesForPrcnt) , Sum(SalesForPrcntSys)
	From "TmpPsar_Sales_An_Slp_Sng_M" 
	Group By CardCode, CardOrSlpName, Month, Year
	Order By CardCode, Year, Month;
	
	delete from "TmpPsar_Sales_An_Slp_Sng_M";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

CREATE  PROCEDURE TmSp_Sales_An_Slp_Sng_M_Insert (
in ObjectType		nChar(3),
in ShowType			nChar(3),
in DocDateFrom_in 		nvarchar(30),
in DocDateTo_in		nvarchar(30),   -- = '21000101',
in DocDueDateFrom_in 	nvarchar(8),   -- = '19700101',
in DocDueDateTo_in		nvarchar(8),   -- = '21000101',
in CardCodeFrom		nvarchar(15), -- = '' ,
in CardCodeTo		nvarchar(15), -- = '',
in CrdGroupCode  	nvarchar(11), -- = '',
in ItemCodeFrom		nvarchar(50), -- = '' ,
in ItemCodeTo		nvarchar(50), -- = '',
in ItmGroupCode  	nvarchar(11), -- = '',
in ItmProps	   		nvarchar(70), -- = '',
in CrdProps   		nvarchar(70),-- = '',
in SlpCodeFrom		nvarchar(155), -- = '',
in SlpCodeTo		nvarchar(155), -- = '',
in TaxDateFrom_in 		nvarchar(8),   -- = '19700101',
in TaxDateTo_in		nvarchar(8),   -- = '21000101',
in Brand			nvarchar(11), -- ='',			
in PrjCode			nvarchar(20),   -- ='',
in RptType			int, 	     -- = 0,
in cutbyObject		nchar(3), -- = 'NON',
in DspFrznBP		nvarchar(1), -- = 'Y',
in DspFrznITM		nvarchar(1), -- = 'Y',
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1) -- = 'N'
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

   --* With Encryption

AS

DocDateFrom 		nvarchar(30);
DocDateTo			nvarchar(30);   -- = '21000101',
DocDueDateFrom 		nvarchar(8);   -- = '19700101',
DocDueDateTo		nvarchar(8);   -- = '21000101',
TaxDateFrom 		nvarchar(8);   -- = '19700101',
TaxDateTo			nvarchar(8);   -- = '21000101',



Header 		nvarchar(4);
Lines  		nvarchar(4);
InstLines  	nvarchar(4);
--opObject 	nvarchar(4);
tmpStr 		nvarchar(4000);
PropsRel 	nvarchar(10);
ii 			int;
jj 			int;
GrossBySal 	nChar(1);
WhereStr 	nvarchar(4000);
VatSysColName 	nvarchar(20);
Mult 		nvarchar(5);
WTLines		nvarchar(4);
SQ		nvarchar(1000);
DpmAffectsTotal		int;
DpmSUM_with_Inst		nvarchar(500);
DpmSUM_SC_with_Inst		nvarchar(500);
DpmSUM		nvarchar(500);
DpmSUM_SC		nvarchar(500);


BEGIN

call _TmSp_ValidateSpParam (:ObjectType);
call _TmSp_ValidateSpParam (:ShowType);
call _TmSp_ValidateSpParam (:DocDateFrom_in);
call _TmSp_ValidateSpParam (:DocDateTo_in);
call _TmSp_ValidateSpParam (:DocDueDateFrom_in);
call _TmSp_ValidateSpParam (:DocDueDateTo_in);
call _TmSp_ValidateSpParam (:CardCodeFrom);
call _TmSp_ValidateSpParam (:CardCodeTo);
call _TmSp_ValidateSpParam (:CrdGroupCode);
call _TmSp_ValidateSpParam (:ItemCodeFrom);
call _TmSp_ValidateSpParam (:ItemCodeTo);
call _TmSp_ValidateSpParam (:ItmGroupCode);
call _TmSp_ValidateSpParam (:ItmProps);
call _TmSp_ValidateSpParam (:CrdProps);
call _TmSp_ValidateSpParam (:SlpCodeFrom);
call _TmSp_ValidateSpParam (:SlpCodeTo);
call _TmSp_ValidateSpParam (:TaxDateFrom_in);
call _TmSp_ValidateSpParam (:TaxDateTo_in);
call _TmSp_ValidateSpParam (:Brand);
call _TmSp_ValidateSpParam (:PrjCode);
call _TmSp_ValidateSpParam (:cutbyObject);
call _TmSp_ValidateSpParam (:DspFrznBP);
call _TmSp_ValidateSpParam (:DspFrznITM);
call _TmSp_ValidateSpParam (:BPLIdSet);
call _TmSp_ValidateSpParam (:SlpIncludeInactive);
call _TmSp_ValidateSpParam (:WTaxEngine);

	DocDateFrom := DocDateFrom_in;
	DocDateTo := DocDateTo_in;
	DocDueDateFrom := DocDueDateFrom_in;
	DocDueDateTo := DocDueDateTo_in;
	TaxDateFrom :=	TaxDateFrom_in;
	TaxDateTo := TaxDateTo_in;
	
	SELECT CASE WHEN "DpmAffTot" = 'Y' THEN 1 ELSE 0 END into DpmAffectsTotal FROM CINF;

	if :ObjectType = 'NON' then	
		--* return (0)		
		Mult := Mult; --* empty statement 
	end if; 
	
	if ((:ShowType = 'SNG' or :ShowType = 'SN1' or :ShowType = 'SN2') OR (:ShowType = 'CAN' AND (:ObjectType = 'RIN' OR :ObjectType = 'RDN'))) then
		Mult := ' 1 ';
	else	
		Mult :=  ' -1 ';
	end if;

					
	if LENGTH(:DocDateFrom) = 0 then 	
		DocDateFrom := '19700101'; 
	end if;	
	if LENGTH(:DocDateTo) = 0 then 	
		DocDateTo := '21000101';
	end if;	
	if LENGTH(:DocDueDateFrom) = 0 then 	
		DocDueDateFrom :=  '19700101'; 
	end if;	
	if LENGTH(:DocDueDateTo) = 0 then 	
		DocDueDateTo := '21000101';
	end if;	
	if LENGTH(:TaxDateFrom) = 0 then 
		TaxDateFrom :=  '19700101'; 
	end if;
	if LENGTH(:TaxDateTo) = 0 then 	
		TaxDateTo := '21000101';
	end if;
	
	if (:ObjectType = 'INV') then	
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		--opObject := 'RIN';
		WTLines := 'INV5';
	end if;	
	if (:ObjectType = 'CSI') then	
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV') then	
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR') then	
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		--opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN') then	
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		--opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN') then	
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN') then	
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;
	
	--[RemoveCIN]
	--if (@ObjectType = 'CIN')
	--Begin
	--	Set @Header = 'OCIN'
	--	Set @Lines =  'CIN1'
	--	Set @InstLines = 'CIN6'
	--	Set @WTLines = 'CIN5'
	--End
	
	--* NOT USED	
	SELECT TOP 1 COLUMN_NAME into VatSysColName FROM "PUBLIC"."TABLE_COLUMNS" as A WHERE TABLE_NAME = :Header and POSITION = 57;	
	 
	
	WhereStr := ' Main."DocDate" Between   TO_DATE( ''' ||  :DocDateFrom 
		|| ''', ''YYYYMMDD'' )	And  TO_DATE( ''' ||  :DocDateTo 
		|| ''', ''YYYYMMDD'' ) And  Inst."DueDate" Between TO_DATE( ''' 
		||  :DocDueDateFrom || ''', ''YYYYMMDD'' )	And  TO_DATE( ''' 
		||  :DocDueDateTo || ''', ''YYYYMMDD'' ) ';
	
	--Card Code range
	if LENGTH(:CardCodeFrom) > 0 then 
		WhereStr := :WhereStr  || '   And    Main."CardCode" >=  N''' ||  :CardCodeFrom || '''  ';
	end if;

	if LENGTH(:CardCodeTo) > 0 then 
		WhereStr := :WhereStr   || '   And    Main."CardCode" <=  N''' ||  :CardCodeTo || '''  ';
	end if;
	
	--Sales person range
	if LENGTH(:SlpCodeFrom) > 0 then
		WhereStr := :WhereStr  || '    And   Slps."SlpName" >=  N''' ||  :SlpCodeFrom || '''  ';
	end if;
	if LENGTH(:SlpCodeTo) > 0 then	
		WhereStr := :WhereStr  || '    And   Slps."SlpName" <=  N''' ||  :SlpCodeTo || '''  ';
	end if;
	
	if :SlpIncludeInactive = 'N' then
		WhereStr := :WhereStr || ' And Slps."Active" = ''Y''';
	end if;
	
	WhereStr := :WhereStr  || '	And	 Main."Instance" = 0	'
		|| ' And Main."TaxDate"  Between  TO_DATE( ''' ||  :TaxDateFrom 
		|| ''', ''YYYYMMDD'' )  And  TO_DATE( ''' ||  :TaxDateTo || ''', ''YYYYMMDD'' )	';
		
	
	if(:ObjectType='INV' OR :ObjectType='DLN' OR :ObjectType = 'RIN' OR :ObjectType = 'RDN') then
		if(:ShowType = 'CAN') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''C'' '	;
		else
			WhereStr := :WhereStr || 'And	   Main."CANCELED" <> ''C'' '	;
		end if;
	else
		if(:ObjectType <> 'CSI') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''N'' '	;
		end if;
	end if;

	
	if LENGTH(:CrdGroupCode) > 0 then 	
		WhereStr := :WhereStr || ' And  Crdg."GroupCode" = ' || :CrdGroupCode; 
	end if;
	
	if LENGTH(:CrdProps) > 0 then
	 	
		if (SUBSTRING (:CrdProps, 65, 1)  = 'N') then		
			PropsRel := ' OR ';		
		Else		
			PropsRel := ' AND ';
		end if;
		 
		WhereStr := :WhereStr || '  And ( '; 
		ii := 1;
		jj := 1;
		While (:ii <= 64) do		
			if (SUBSTRING (:CrdProps, :ii, 1)  = 'Y') then			
				if (:jj <> 1) then				
					WhereStr := :WhereStr || :PropsRel;
				end if; 	
				WhereStr := :WhereStr || ' Cards."QryGroup' || Cast (:ii As nChar(2)) || '" = ''Y''';
				jj := :jj + 1;
			end if; 
			ii := :ii + 1;
		end while;
		WhereStr := :WhereStr || ') '; 
	end if;
	
	if (:ObjectType = 'RIN') then
		if(:ShowType <> 'CAN') then
			WhereStr := :WhereStr || ' AND NOT  EXISTS (SELECT 1 FROM '|| :ObjectType || '1 T1 WHERE T1."DocEntry" = Main."DocEntry"    AND T1."BaseType" = 203) ';
		else
			WhereStr := :WhereStr || ' AND NOT EXISTS (SELECT 1 FROM ' || :ObjectType || '1 T1 ,' || :ObjectType || '1 T2 WHERE T1."DocEntry" = Main."DocEntry"  AND T1."BaseType" = 14 AND T1."BaseEntry" = T2."DocEntry" AND T2."BaseType" = 203)';
		end if;
	end if;
		
	DpmSUM := '';
	DpmSUM_SC := '';
	DpmSUM_with_Inst := '';
	DpmSUM_SC_with_Inst := '';
	if (:DpmAffectsTotal = 1) then 	 	
		DpmSUM := ' + Sum(aa."DpmAmnt") ';		
		DpmSUM_SC := ' + Sum(aa."DpmAmntSC") ';		
		DpmSUM_with_Inst := ' + Sum(Main."DpmAmnt" * Inst."InstPrcnt"/100) ';		
		DpmSUM_SC_with_Inst := ' + Sum(Main."DpmAmntSC" * Inst."InstPrcnt"/100)';		
	end if;
						
	tmpStr := ' Insert into "TmpPsar_Sales_An_Slp_Sng_M" ' ||
	'Select Slps."SlpCode", Slps."SlpName", Month(Main."DocDate") As Month, Year(Main."DocDate") As Year, ' ||
	'	(Sum(Inst."InsTotal") - Sum(Inst."VatSum") + Sum(IfNull(Main."FoCTax",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpns") + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| :DpmSUM_with_Inst  
          	|| ' - Sum(Main."RoundDif" * Inst."InstPrcnt"/100))  * ' || :Mult 
          	|| '  As Sales,	(Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100))  * ' || :Mult 
          	|| ' As GrossProfit, ((Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100)  /  '
          	|| ' nullif((Sum(Inst."InsTotal") - Sum(Inst."VatSum") + Sum(IfNull(Main."FoCTax",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpns") + ' 
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| '),0)) * 100)  * ' || :Mult 
           	|| ' as GrossPrcnt, '
          	|| ' (Sum(Inst."InsTotalSy") - Sum(Inst."' || :VatSysColName 
         	|| '" ) + Sum((IfNull(Main."FoCTaxSC",0) * Inst."InstPrcnt" / 100)) - Sum(Inst."TotalExpSC") + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSumSC")' END)
			|| :DpmSUM_SC_with_Inst  
          	|| ' - Sum(Main."RoundDifSy" * Inst."InstPrcnt"/100	) ) * ' || :Mult 
          	|| '  As SalesSys, (Sum(Main."GrosProfSy"  * Inst."InstPrcnt" / 100) ) * ' 
          	|| :Mult || 'As GrossProfitSys, ((Sum(Main."GrosProfSy"  * Inst."InstPrcnt" / 100)'
          	|| ' /  nullif((Sum(Inst."InsTotalSy") - Sum(Inst."' || :VatSysColName || '") + Sum((IfNull(Main."FoCTaxSC",0) * Inst."InstPrcnt" / 100)) + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSumSC")' END)
			|| ' - Sum(Inst."TotalExpSC")),0)) * 100) * ' 
          	|| :Mult || ' as GrossPrcntSys, ';
  
	tmpStr := :tmpStr || ' (Select  (Sum(aa."DocTotal") - Sum(aa."VatSum") + Sum(IfNull(aa."FoCTax",0)) + ' 
        			  || (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
							ELSE '-Sum(Inst."WTSum")' END)
					 || :DpmSUM || ' - Sum(aa."RoundDif")- Sum(aa."TotalExpns")) From ' || :Header 
          			 || ' aa   Where  aa."DocEntry" = Main."DocEntry" )  * ' || :Mult 
          			 || '  As  SalesForPrcnt  , '          			 
          			 || '  (Select  (Sum(aa."DocTotalSy") - Sum(aa."' || :VatSysColName || '") + Sum(IfNull(aa."FoCTaxSC",0)) + '
					 || (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
						ELSE '-Sum(Inst."WTSumSC")' END)
					 || :DpmSUM_SC  
          			 || ' - Sum(aa."RoundDifSy") - Sum(aa."TotalExpSC")) From ' 
          			 || :Header || ' aa   Where  aa."DocEntry" = Main."DocEntry" )  * ' 
          			 || :Mult || '  As  SalesForPrcntSys ';          			  
   
	tmpStr := :tmpStr || ' From  ' || :Header || ' Main '  
		|| ' Inner  Join OCRD Cards On Cards."CardCode" = Main."CardCode" '
		|| ' Inner  Join OCRG Crdg On Crdg."GroupCode" = Cards."GroupCode" '
		|| ' Inner  Join OSLP  Slps On Slps."SlpCode" = Main."SlpCode" '
		|| ' Inner  Join ' || :InstLines || ' Inst On inst."DocEntry" = Main."DocEntry"';
		
	if (:WTaxEngine = 'N') then
		tmpStr := :tmpStr || ' Left Join "TmpPsar_MinCategory" cate on cate."AbsEntry" = Main."DocEntry" ';
	end if;

	if :DspFrznBP = 'N' then	
		WhereStr := ' (' || :WhereStr || ') And ' || 
					'(Cards."validFor" = ''Y'' or (Cards."frozenFor" = ''Y'' and ' ||
					'(Cards."frozenFrom" is not null or Cards."frozenTo" is not null))' ||
					' or (Cards."validFor" = ''N'' and Cards."frozenFor" = ''N''))';
	end if;
	
	if LENGTH(:BPLIdSet) > 0 then
		WhereStr := :WhereStr || ' And Main."BPLId" in (' || :BPLIdSet || ')';
	end if;

	WhereStr := 'Where	' || :WhereStr || '  Group By  Slps."SlpCode", Slps."SlpName",  Month(Main."DocDate"), ' ||
	  			' Year(Main."DocDate")  , Main."DocEntry"';
				
	if (:WTaxEngine = 'N') then
		WhereStr := :WhereStr || ', cate."Category"'; 
	end if;

	if LENGTH(:CrdGroupCode) > 0 then 	
		WhereStr := :WhereStr || ', Crdg."GroupCode" ';
	end if;
	
	WhereStr := :WhereStr || ' Order By Slps."SlpCode"   , Year(Main."DocDate"), Month(Main."DocDate")';

	if (:WTaxEngine = 'N') then
		Delete from "TmpPsar_MinCategory";
		SQ := 'Insert into "TmpPsar_MinCategory" Select "AbsEntry", MIN("Category") from '||:WTLines||' Group by "AbsEntry"';
		EXEC (:SQ);
	end if;
	
	exec (:tmpStr || :WhereStr );
	/* End Here */

	--print @tmpStr
	--print @WhereStr
	
END;

-- B1 DEPENDS: AFTER:SP:TmSp_Sales_An_Slp_Sng_M_LC_Insert AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2

CREATE  PROCEDURE TmSp_Sales_An_Slp_Sng_M_LC (
in ObjectType		nChar(3),
in ShowType			nChar(3),
in DocDateFrom 		nvarchar(30),
in DocDateTo		nvarchar(30),   -- = '21000101',
in DocDueDateFrom 	nvarchar(8),   -- = '19700101',
in DocDueDateTo		nvarchar(8),   -- = '21000101',
in CardCodeFrom		nvarchar(15), -- = '' ,
in CardCodeTo		nvarchar(15), -- = '',
in CrdGroupCode  	nvarchar(11), -- = '',
in ItemCodeFrom		nvarchar(50), -- = '' ,
in ItemCodeTo		nvarchar(50), -- = '',
in ItmGroupCode  	nvarchar(11), -- = '',
in ItmProps	   		nvarchar(70), -- = '',
in CrdProps   		nvarchar(70),-- = '',
in SlpCodeFrom		nvarchar(155), -- = '',
in SlpCodeTo		nvarchar(155), -- = '',
in TaxDateFrom 		nvarchar(8),   -- = '19700101',
in TaxDateTo		nvarchar(8),   -- = '21000101',
in Brand			nvarchar(11), -- ='',			
in PrjCode			nvarchar(20),   -- ='',
in RptType			int, 	     -- = 0,
in cutbyObject		nchar(3), -- = 'NON',
in DspFrznBP		nvarchar(1), -- = 'Y',
in DspFrznITM		nvarchar(1), -- = 'Y',
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1) -- = 'N'
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

   --* With Encryption

AS

Header 		nvarchar(4);
Lines  		nvarchar(4);
InstLines  	nvarchar(4);
opObject 	nvarchar(4);
WTLines		nvarchar(4);

BEGIN
	
	opObject := 'NON';
	
	if (:ObjectType = 'INV') then	
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		opObject := 'RIN';
		WTLines := 'INV5';
	end if;	
	if (:ObjectType = 'CSI') then	
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV') then	
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR') then	
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN') then	
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN') then	
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN') then	
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;

	delete from "TmpPsar_Sales_An_Slp_Sng_M_LC";
							
	call TmSp_Sales_An_Slp_Sng_M_LC_Insert (:ObjectType , :ShowType, :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
	if(:ObjectType = 'INV' OR :ObjectType = 'DLN') then
	call TmSp_Sales_An_Slp_Sng_M_LC_Insert (:ObjectType , 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
	end if;
	/* End Here */

	--print @tmpStr
	--print @WhereStr

	if (:ShowType = 'SNG') then	

		if (:opObject <> 'NON') then
			call TmSp_Sales_An_Slp_Sng_M_LC_Insert (:opObject , 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
			call TmSp_Sales_An_Slp_Sng_M_LC_Insert (:opObject , 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
		end if;

		if (:ObjectType = 'INV') then 		
			call TmSp_Sales_An_Slp_Sng_M_LC_Insert ('CSI' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
			
			call TmSp_Sales_An_Slp_Sng_M_LC_Insert ('CSV' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
		end if;
	end if;
	
	Select CardCode, CardOrSlpName, Month, Year, Sum(Sales), Sum(GrossPrft) , Sum(GrossPrcnt) , Sum(SalesSys) , Sum(GrossPrftSys) , Sum(GrossPrcntSys), 
		Sum(SalesForPrcnt) , Sum(SalesForPrcntSys)
	From "TmpPsar_Sales_An_Slp_Sng_M_LC"
	Group By CardCode, CardOrSlpName, Month, Year
	Order By CardCode, Year, Month;

	delete from "TmpPsar_Sales_An_Slp_Sng_M_LC";
END;

