CREATE  PROCEDURE TmSp_Sales_An_Slp_Sng_M_LC_Insert (
in ObjectType		nChar(3),
in ShowType			nChar(3),
in DocDateFrom_in 		nvarchar(30),
in DocDateTo_in		nvarchar(30),   -- = '21000101',
in DocDueDateFrom_in 	nvarchar(8),   -- = '19700101',
in DocDueDateTo_in		nvarchar(8),   -- = '21000101',
in CardCodeFrom		nvarchar(15), -- = '' ,
in CardCodeTo		nvarchar(15), -- = '',
in CrdGroupCode  	nvarchar(11), -- = '',
in ItemCodeFrom		nvarchar(50), -- = '' ,
in ItemCodeTo		nvarchar(50), -- = '',
in ItmGroupCode  	nvarchar(11), -- = '',
in ItmProps	   		nvarchar(70), -- = '',
in CrdProps   		nvarchar(70),-- = '',
in SlpCodeFrom		nvarchar(155), -- = '',
in SlpCodeTo		nvarchar(155), -- = '',
in TaxDateFrom_in 		nvarchar(8),   -- = '19700101',
in TaxDateTo_in		nvarchar(8),   -- = '21000101',
in Brand			nvarchar(11), -- ='',			
in PrjCode			nvarchar(20),   -- ='',
in RptType			int, 	     -- = 0,
in cutbyObject		nchar(3), -- = 'NON',
in DspFrznBP		nvarchar(1), -- = 'Y',
in DspFrznITM		nvarchar(1), -- = 'Y',
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1) -- = 'N'
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

   --* With Encryption

AS

DocDateFrom 		nvarchar(30);
DocDateTo			nvarchar(30);   -- = '21000101',
DocDueDateFrom 		nvarchar(8);   -- = '19700101',
DocDueDateTo		nvarchar(8);   -- = '21000101',
TaxDateFrom 		nvarchar(8);   -- = '19700101',
TaxDateTo			nvarchar(8);   -- = '21000101',


SQ			nvarchar(1000);
Header 		nvarchar(4);
Lines  		nvarchar(4);
InstLines  	nvarchar(4);
--opObject 	nvarchar(4);
tmpStr 		nvarchar(4000);
PropsRel 	nvarchar(10);
ii 			int;
jj 			int;
GrossBySal 	nChar(1);
WhereStr 	nvarchar(4000);
VatSysColName 	nvarchar(20);
Mult 		nvarchar(5);
WTLines		nvarchar(4);
DpmAffectsTotal		int;
DpmSUM_with_Inst		nvarchar(500);
DpmSUM		nvarchar(500);

BEGIN

call _TmSp_ValidateSpParam (:ObjectType);
call _TmSp_ValidateSpParam (:ShowType);
call _TmSp_ValidateSpParam (:DocDateFrom_in);
call _TmSp_ValidateSpParam (:DocDateTo_in);
call _TmSp_ValidateSpParam (:DocDueDateFrom_in);
call _TmSp_ValidateSpParam (:DocDueDateTo_in);
call _TmSp_ValidateSpParam (:CardCodeFrom);
call _TmSp_ValidateSpParam (:CardCodeTo);
call _TmSp_ValidateSpParam (:CrdGroupCode);
call _TmSp_ValidateSpParam (:ItemCodeFrom);
call _TmSp_ValidateSpParam (:ItemCodeTo);
call _TmSp_ValidateSpParam (:ItmGroupCode);
call _TmSp_ValidateSpParam (:ItmProps);
call _TmSp_ValidateSpParam (:CrdProps);
call _TmSp_ValidateSpParam (:SlpCodeFrom);
call _TmSp_ValidateSpParam (:SlpCodeTo);
call _TmSp_ValidateSpParam (:TaxDateFrom_in);
call _TmSp_ValidateSpParam (:TaxDateTo_in);
call _TmSp_ValidateSpParam (:Brand);
call _TmSp_ValidateSpParam (:PrjCode);
call _TmSp_ValidateSpParam (:cutbyObject);
call _TmSp_ValidateSpParam (:DspFrznBP);
call _TmSp_ValidateSpParam (:DspFrznITM);
call _TmSp_ValidateSpParam (:BPLIdSet);
call _TmSp_ValidateSpParam (:SlpIncludeInactive);
call _TmSp_ValidateSpParam (:WTaxEngine);

	DocDateFrom := DocDateFrom_in;
	DocDateTo := DocDateTo_in;
	DocDueDateFrom := DocDueDateFrom_in;
	DocDueDateTo := DocDueDateTo_in;
	TaxDateFrom :=	TaxDateFrom_in;
	TaxDateTo := TaxDateTo_in;
	
	SELECT CASE WHEN "DpmAffTot" = 'Y' THEN 1 ELSE 0 END into DpmAffectsTotal FROM CINF;

	--if :ObjectType = 'NON' then	
		--* return (0)		
	--end if; 
	
	if ((:ShowType = 'SNG' or :ShowType = 'SN1' or :ShowType = 'SN2') OR (:ShowType = 'CAN' AND (:ObjectType = 'RIN' OR :ObjectType = 'RDN'))) then
		Mult := ' 1 ';
	else	
		Mult :=  ' -1 ';
	end if;

					
	if LENGTH(:DocDateFrom) = 0 then 	
		DocDateFrom := '19700101'; 
	end if;	
	if LENGTH(:DocDateTo) = 0 then 	
		DocDateTo := '21000101';
	end if;	
	if LENGTH(:DocDueDateFrom) = 0 then 	
		DocDueDateFrom :=  '19700101'; 
	end if;	
	if LENGTH(:DocDueDateTo) = 0 then 	
		DocDueDateTo := '21000101';
	end if;	
	if LENGTH(:TaxDateFrom) = 0 then 
		TaxDateFrom :=  '19700101'; 
	end if;
	if LENGTH(:TaxDateTo) = 0 then 	
		TaxDateTo := '21000101';
	end if;
	
	if (:ObjectType = 'INV') then	
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		--opObject := 'RIN';
		WTLines := 'INV5';
	end if;	
	if (:ObjectType = 'CSI') then	
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV') then	
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR') then	
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		--opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN') then	
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		--opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN') then	
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN') then	
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;
	
	--[RemoveCIN]
	--if (@ObjectType = 'CIN')
	--Begin
	--	Set @Header = 'OCIN'
	--	Set @Lines =  'CIN1'
	--	Set @InstLines = 'CIN6'
	--	Set @WTLines = 'CIN5'
	--End

	---for dashboard bug fix of no revenue data
	if (:DocDateFrom = '26') then 						
	  DocDateFrom := to_char(add_months(add_days(last_day(curdate()), 1) , -6), 'YYYYMMDD'); 
	  DocDateTo := to_char(last_day(curdate()), 'YYYYMMDD'); 	 
	else if (:DocDateFrom = '27') then	
	  		DocDateFrom := to_char(add_months(add_days(last_day(curdate()), 1) , -12), 'YYYYMMDD');
	  		DocDateTo := to_char(last_day(curdate()), 'YYYYMMDD');	
		else if (:DocDateFrom = '28') then	
	  			DocDateFrom := to_char(add_days(last_day(add_months(add_years(CURDATE(),-2), 3-MOD(month(CURDATE()),3))),1), 'YYYYMMDD'); 
	  			DocDateTo := to_char(last_day(curdate()), 'YYYYMMDD');
	  		end if;
	  	end if;
	end if;
	
	--* NOT USED
	--* VatSysColName := SELECT COLUMN_NAME FROM "PUBLIC"."TABLE_COLUMNS" as A WHERE TABLE_NAME = :Header and POSITION = 57;
	 
	
	WhereStr := ' Main."DocDate" Between   TO_DATE( ''' ||  :DocDateFrom 
		|| ''', ''YYYYMMDD'' )	And  TO_DATE( ''' ||  :DocDateTo 
		|| ''', ''YYYYMMDD'' ) And  Inst."DueDate" Between TO_DATE( ''' 
		||  :DocDueDateFrom || ''', ''YYYYMMDD'' )	And  TO_DATE( ''' 
		||  :DocDueDateTo || ''', ''YYYYMMDD'' ) ';
	
	--Card Code range
	if LENGTH(:CardCodeFrom) > 0 then 
		WhereStr := :WhereStr  || '   And    Main."CardCode" >=  N''' ||  :CardCodeFrom || '''  ';
	end if;

	if LENGTH(:CardCodeTo) > 0 then 
		WhereStr := :WhereStr   || '   And    Main."CardCode" <=  N''' ||  :CardCodeTo || '''  ';
	end if;
	
	--Sales person range
	if LENGTH(:SlpCodeFrom) > 0 then
		WhereStr := :WhereStr  || '    And   Slps."SlpName" >=  N''' ||  :SlpCodeFrom || '''  ';
	end if;
	if LENGTH(:SlpCodeTo) > 0 then	
		WhereStr := :WhereStr  || '    And   Slps."SlpName" <=  N''' ||  :SlpCodeTo || '''  ';
	end if;
	
	if :SlpIncludeInactive = 'N' then
		WhereStr := :WhereStr || ' And Slps."Active" = ''Y''';
	end if;
	
	WhereStr := :WhereStr  || '	And	 Main."Instance" = 0	'
		|| ' And Main."TaxDate"  Between  TO_DATE( ''' ||  :TaxDateFrom 
		|| ''', ''YYYYMMDD'' )  And  TO_DATE( ''' ||  :TaxDateTo || ''', ''YYYYMMDD'' )	';
		
	if(:ObjectType='INV' OR :ObjectType='DLN' OR :ObjectType = 'RIN' OR :ObjectType = 'RDN') then
		if(:ShowType = 'CAN') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''C'' '	;
		else
			WhereStr := :WhereStr || 'And	   Main."CANCELED" <> ''C'' '	;
		end if;
	else
		if(:ObjectType <> 'CSI') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''N'' '	;
		end if;
	end if;

	
	if LENGTH(:CrdGroupCode) > 0 then 	
		WhereStr := :WhereStr || ' And  Crdg."GroupCode" = ' || :CrdGroupCode; 
	end if;
	
	if LENGTH(:CrdProps) > 0 then
	 	
		if (SUBSTRING (:CrdProps, 65, 1)  = 'N') then		
			PropsRel := ' OR ';		
		Else		
			PropsRel := ' AND ';
		end if;
		 
		WhereStr := :WhereStr || '  And ( '; 
		ii := 1;
		jj := 1;
		While (:ii <= 64) do		
			if (SUBSTRING (:CrdProps, :ii, 1)  = 'Y') then			
				if (:jj <> 1) then				
					WhereStr := :WhereStr || :PropsRel;
				end if; 	
				WhereStr := :WhereStr || ' Cards."QryGroup' || Cast (:ii As nChar(2)) || '" = ''Y''';
				jj := :jj + 1;
			end if; 
			ii := :ii + 1;
		end while;
		WhereStr := :WhereStr || ') '; 
	end if;
	
	if (:ObjectType = 'RIN') then
		if(:ShowType <> 'CAN') then
			WhereStr := :WhereStr || ' AND NOT  EXISTS (SELECT 1 FROM '|| :ObjectType || '1 T1 WHERE T1."DocEntry" = Main."DocEntry"    AND T1."BaseType" = 203) ';
		else
			WhereStr := :WhereStr || ' AND NOT EXISTS (SELECT 1 FROM ' || :ObjectType || '1 T1 ,' || :ObjectType || '1 T2 WHERE T1."DocEntry" = Main."DocEntry"  AND T1."BaseType" = 14 AND T1."BaseEntry" = T2."DocEntry" AND T2."BaseType" = 203)';
		end if;
	end if;
	
	DpmSUM := '';	
	DpmSUM_with_Inst := '';	
	if (:DpmAffectsTotal = 1) then 	 	
		DpmSUM := ' + Sum(aa."DpmAmnt") ';				
		DpmSUM_with_Inst := ' + Sum(Main."DpmAmnt" * Inst."InstPrcnt"/100) ';				
	end if;
							
	tmpStr := ' Insert into "TmpPsar_Sales_An_Slp_Sng_M_LC" ' ||
	'Select Slps."SlpCode", Slps."SlpName", Month(Main."DocDate") As Month, Year(Main."DocDate") As Year, ' ||
	'	(Sum(Inst."InsTotal") - Sum(Inst."VatSum") + Sum(IfNull(Main."FoCTax",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpns") + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| :DpmSUM_with_Inst  
          	|| ' - Sum(Main."RoundDif" * Inst."InstPrcnt"/100))  * ' || :Mult 
          	|| '  As Sales,	(Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100))  * ' || :Mult 
          	|| ' As GrossPrft, ((Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100)  /  '
          	|| ' nullif((Sum(Inst."InsTotal") - Sum(Inst."VatSum") + Sum(IfNull(Main."FoCTax",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpns") + ' 
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| '),0)) * 100)  * ' || :Mult 
          	|| ' as GrossPrcnt, 0  As SalesSys, 0 As GrossPrftSys,0 as GrossPrcntSys, ';
          	
	tmpStr := :tmpStr || ' (Select  (Sum(aa."DocTotal") - Sum(aa."VatSum") + Sum(IfNull(aa."FoCTax",0)) + ' 
					 || (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
						ELSE '-Sum(Inst."WTSumSC")' END)
					 || :DpmSUM  
          			 || ' - Sum(aa."RoundDif")- Sum(aa."TotalExpns")) From ' || :Header 
          			 || ' aa   Where  aa."DocEntry" = Main."DocEntry" )  * ' || :Mult 
          			 || '  As  SalesForPrcnt  , 0  As  SalesForPrcntSys ';

	tmpStr := :tmpStr || ' From  ' || :Header || ' Main '  
		|| ' Inner  Join OCRD Cards On Cards."CardCode" = Main."CardCode" '
		|| ' Inner  Join OCRG Crdg On Crdg."GroupCode" = Cards."GroupCode" '
		|| ' Inner  Join OSLP  Slps On Slps."SlpCode" = Main."SlpCode" '
		|| ' Inner  Join ' || :InstLines || ' Inst On inst."DocEntry" = Main."DocEntry" ';
		
	if (:WTaxEngine = 'N') then
		tmpStr := :tmpStr || ' Left Join "TmpPsar_MinCategory" cate on cate."AbsEntry" = Main."DocEntry" ';
	end if;
	
	if :DspFrznBP = 'N' then	
		WhereStr := ' (' || :WhereStr || ') And ' || 
					'(Cards."validFor" = ''Y'' or (Cards."frozenFor" = ''Y'' and ' ||
					'(Cards."frozenFrom" is not null or Cards."frozenTo" is not null))' ||
					' or (Cards."validFor" = ''N'' and Cards."frozenFor" = ''N''))';
	end if;
	
	if LENGTH(:BPLIdSet) > 0 then
		WhereStr := :WhereStr || ' And Main."BPLId" in (' || :BPLIdSet || ')';
	end if;

	WhereStr := 'Where	' || :WhereStr || '  Group By  Slps."SlpCode", Slps."SlpName",  Month(Main."DocDate"), ' ||
	  			' Year(Main."DocDate")  , Main."DocEntry" ';
				
	if (:WTaxEngine = 'N') then
		WhereStr := :WhereStr || ', cate."Category"'; 
	end if;
	
	if LENGTH(:CrdGroupCode) > 0 then 	
		WhereStr := :WhereStr || ', Crdg."GroupCode" ';
	end if;
	
	WhereStr := :WhereStr || ' Order By Slps."SlpCode"   , Year(Main."DocDate"), Month(Main."DocDate")';

	if (:WTaxEngine = 'N') then
	
		Delete from "TmpPsar_MinCategory";
		SQ := 'Insert into "TmpPsar_MinCategory" Select "AbsEntry", MIN("Category") from '||:WTLines||' Group by "AbsEntry"';
		EXEC (:SQ);
		
	end if;
	
	exec (:tmpStr || :WhereStr );
	/* End Here */

	--print @tmpStr
	--print @WhereStr
	
END;

-- B1 DEPENDS: AFTER:SP:TmSp_Sales_An_Slp_Sng_Y_Insert AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2

CREATE  PROCEDURE TmSp_Sales_An_Slp_Sng_Y (
in ObjectType		nChar(3),
in ShowType			nChar(3),
in DocDateFrom 		nvarchar(8),
in DocDateTo		nvarchar(8),   -- = '21000101',
in DocDueDateFrom 	nvarchar(8),   -- = '19700101',
in DocDueDateTo		nvarchar(8),   -- = '21000101',
in CardCodeFrom		nvarchar(15), -- = '' ,
in CardCodeTo		nvarchar(15), -- = '',
in CrdGroupCode  	nvarchar(11), -- = '',
in ItemCodeFrom		nvarchar(50), -- = '' ,
in ItemCodeTo		nvarchar(50), -- = '',
in ItmGroupCode  	nvarchar(11), -- = '',
in ItmProps	   		nvarchar(70), -- = '',
in CrdProps   		nvarchar(70),-- = '',
in SlpCodeFrom		nvarchar(155), -- = '',
in SlpCodeTo		nvarchar(155), -- = '',
in TaxDateFrom 		nvarchar(8),   -- = '19700101',
in TaxDateTo		nvarchar(8),   -- = '21000101',
in Brand			nvarchar(11), -- ='',			
in PrjCode			nvarchar(20),   -- ='',
in RptType			int, 	     -- = 0,
in cutbyObject		nchar(3), -- = 'NON',
in DspFrznBP		nvarchar(1), -- = 'Y',
in DspFrznITM		nvarchar(1), -- = 'Y',
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine		nvarchar(1) -- = 'N'
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

   --* With Encryption

AS

Header 		nvarchar(4);
Lines  		nvarchar(4);
InstLines  	nvarchar(4);
opObject 	nvarchar(4);
WTLines		nvarchar(4);

BEGIN
	
	opObject := 'NON';
	
	if (:ObjectType = 'INV') then	
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		opObject := 'RIN';
		WTLines := 'INV5';
	end if;	
	if (:ObjectType = 'CSI') then	
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV') then	
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR') then	
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN') then	
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN') then	
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN') then	
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;

	delete from "TmpPsar_Sales_An_Slp_Sng_Y";	

	call TmSp_Sales_An_Slp_Sng_Y_Insert (:ObjectType , :ShowType, :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
	if(:ObjectType = 'INV' OR :ObjectType = 'DLN') then
	call TmSp_Sales_An_Slp_Sng_Y_Insert (:ObjectType , 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
		:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
		:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
	end if;
	/* End Here */

	--print @tmpStr
	--print @WhereStr

	if (:ShowType = 'SNG') then		
	
		if (:opObject <> 'NON') then
			call TmSp_Sales_An_Slp_Sng_Y_Insert (:opObject , 'NST', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
			call TmSp_Sales_An_Slp_Sng_Y_Insert (:opObject , 'CAN', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
		end if;

		if (:ObjectType = 'INV') then 		
			call TmSp_Sales_An_Slp_Sng_Y_Insert ('CSI' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
			
			call TmSp_Sales_An_Slp_Sng_Y_Insert ('CSV' , 'SN1', :DocDateFrom ,:DocDateTo, :DocDueDateFrom ,:DocDueDateTo, 	 
			:CardCodeFrom, :CardCodeTo, :CrdGroupCode, :ItemCodeFrom, :ItemCodeTo, :ItmGroupCode, :ItmProps, :CrdProps, :SlpCodeFrom, :SlpCodeTo, 
			:TaxDateFrom, :TaxDateTo, :Brand, :PrjCode, :RptType, :cutbyObject, :DspFrznBP, :DspFrznITM, :BPLIdSet, :SlpIncludeInactive, :WTaxEngine);
		end if;
	end if;		

	Select CardCode, CardOrSlpName , Sum(DocCount) , Sum(Sales) , Sum(GrossPrft) , Sum(GrossPrcnt ), Sum(TotalOpen) ,  Sum(SalesSys) , Sum(GrossPrftSys),
			Sum( GrossPrcntSys) ,  Sum(TotalOpenSys), Sum(SalesForPrcnt) , Sum(SalesForPrcntSys)
	From "TmpPsar_Sales_An_Slp_Sng_Y" 
	Group By CardCode, CardOrSlpName 
	Order By CardCode;
	
	delete from "TmpPsar_Sales_An_Slp_Sng_Y";
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

CREATE  PROCEDURE TmSp_Sales_An_Slp_Sng_Y_Insert (
in ObjectType		nChar(3),
in ShowType			nChar(3),
in DocDateFrom_in 		nvarchar(30),
in DocDateTo_in		nvarchar(30),   -- = '21000101',
in DocDueDateFrom_in 	nvarchar(8),   -- = '19700101',
in DocDueDateTo_in		nvarchar(8),   -- = '21000101',
in CardCodeFrom		nvarchar(15), -- = '' ,
in CardCodeTo		nvarchar(15), -- = '',
in CrdGroupCode  	nvarchar(11), -- = '',
in ItemCodeFrom		nvarchar(50), -- = '' ,
in ItemCodeTo		nvarchar(50), -- = '',
in ItmGroupCode  	nvarchar(11), -- = '',
in ItmProps	   		nvarchar(70), -- = '',
in CrdProps   		nvarchar(70),-- = '',
in SlpCodeFrom		nvarchar(155), -- = '',
in SlpCodeTo		nvarchar(155), -- = '',
in TaxDateFrom_in 		nvarchar(8),   -- = '19700101',
in TaxDateTo_in		nvarchar(8),   -- = '21000101',
in Brand			nvarchar(11), -- ='',			
in PrjCode			nvarchar(20),   -- ='',
in RptType			int, 	     -- = 0,
in cutbyObject		nchar(3), -- = 'NON',
in DspFrznBP		nvarchar(1), -- = 'Y',
in DspFrznITM		nvarchar(1), -- = 'Y',
in BPLIdSet 		nvarchar(1000), 	--= ''
in SlpIncludeInactive	nvarchar(1),
in WTaxEngine	nvarchar(1) -- = 'N'
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

   --* With Encryption

AS

DocDateFrom 		nvarchar(30);
DocDateTo			nvarchar(30);   -- = '21000101',
DocDueDateFrom 		nvarchar(8);   -- = '19700101',
DocDueDateTo		nvarchar(8);   -- = '21000101',
TaxDateFrom 		nvarchar(8);   -- = '19700101',
TaxDateTo			nvarchar(8);   -- = '21000101',



Header 		nvarchar(4);
Lines  		nvarchar(4);
InstLines  	nvarchar(4);
--opObject 	nvarchar(4);
tmpStr 		nvarchar(4000);
tmpStr2 	nvarchar(4000); --[i037610 add at 26/05/06 10:36] buffer "tmpStr" is not big enough, so add a new buffer
PropsRel 	nvarchar(10);
ii 			int;
jj 			int;
GrossBySal 	nChar(1);
WhereStr 	nvarchar(4000);
VatSysColName 	nvarchar(20);
Mult 		nvarchar(5);
WTLines		nvarchar(4);
SQ		nvarchar(1000);
DpmAffectsTotal		int;
DpmSUM_with_Inst		nvarchar(500);
DpmSUM_SC_with_Inst		nvarchar(500);
DpmSUM		nvarchar(500);
DpmSUM_SC		nvarchar(500);

BEGIN

call _TmSp_ValidateSpParam (:ObjectType);
call _TmSp_ValidateSpParam (:ShowType);
call _TmSp_ValidateSpParam (:DocDateFrom_in);
call _TmSp_ValidateSpParam (:DocDateTo_in);
call _TmSp_ValidateSpParam (:DocDueDateFrom_in);
call _TmSp_ValidateSpParam (:DocDueDateTo_in);
call _TmSp_ValidateSpParam (:CardCodeFrom);
call _TmSp_ValidateSpParam (:CardCodeTo);
call _TmSp_ValidateSpParam (:CrdGroupCode);
call _TmSp_ValidateSpParam (:ItemCodeFrom);
call _TmSp_ValidateSpParam (:ItemCodeTo);
call _TmSp_ValidateSpParam (:ItmGroupCode);
call _TmSp_ValidateSpParam (:ItmProps);
call _TmSp_ValidateSpParam (:CrdProps);
call _TmSp_ValidateSpParam (:SlpCodeFrom);
call _TmSp_ValidateSpParam (:SlpCodeTo);
call _TmSp_ValidateSpParam (:TaxDateFrom_in);
call _TmSp_ValidateSpParam (:TaxDateTo_in);
call _TmSp_ValidateSpParam (:Brand);
call _TmSp_ValidateSpParam (:PrjCode);
call _TmSp_ValidateSpParam (:cutbyObject);
call _TmSp_ValidateSpParam (:DspFrznBP);
call _TmSp_ValidateSpParam (:DspFrznITM);
call _TmSp_ValidateSpParam (:BPLIdSet);
call _TmSp_ValidateSpParam (:SlpIncludeInactive);
call _TmSp_ValidateSpParam (:WTaxEngine);

	DocDateFrom := DocDateFrom_in;
	DocDateTo := DocDateTo_in;
	DocDueDateFrom := DocDueDateFrom_in;
	DocDueDateTo := DocDueDateTo_in;
	TaxDateFrom :=	TaxDateFrom_in;
	TaxDateTo := TaxDateTo_in;

	SELECT CASE WHEN "DpmAffTot" = 'Y' THEN 1 ELSE 0 END into DpmAffectsTotal FROM CINF;

	if :ObjectType = 'NON' then	
		--* return (0)		
		Mult := Mult; --* empty statement 
	end if; 
	
	if ((:ShowType = 'SNG' or :ShowType = 'SN1' or :ShowType = 'SN2') OR (:ShowType = 'CAN' AND (:ObjectType = 'RIN' OR :ObjectType = 'RDN'))) then
		Mult := ' 1 ';
	else	
		Mult :=  ' -1 ';
	end if;

					
	if LENGTH(:DocDateFrom) = 0 then 	
		DocDateFrom := '19700101'; 
	end if;	
	if LENGTH(:DocDateTo) = 0 then 	
		DocDateTo := '21000101';
	end if;	
	if LENGTH(:DocDueDateFrom) = 0 then 	
		DocDueDateFrom :=  '19700101'; 
	end if;	
	if LENGTH(:DocDueDateTo) = 0 then 	
		DocDueDateTo := '21000101';
	end if;	
	if LENGTH(:TaxDateFrom) = 0 then 
		TaxDateFrom :=  '19700101'; 
	end if;
	if LENGTH(:TaxDateTo) = 0 then 	
		TaxDateTo := '21000101';
	end if;
	
	if (:ObjectType = 'INV') then	
		Header := 'OINV';
		Lines :=  'INV1';
		InstLines := 'INV6';
		--opObject := 'RIN';
		WTLines := 'INV5';
	end if;	
	if (:ObjectType = 'CSI') then	
		Header := 'OCSI';
		Lines :=  'CSI1';
		InstLines := 'CSI6';
		WTLines := 'CSI5';
	end if;
	if (:ObjectType = 'CSV') then	
		Header := 'OCSV';
		Lines :=  'CSV1';
		InstLines := 'CSV6';
		WTLines := 'CSV5';
	end if;
	if (:ObjectType = 'RDR') then	
		Header := 'ORDR';
		Lines :=  'RDR1';
		InstLines := 'RDR6';
		--opObject := 'NON';
		WTLines := 'RDR5';
	end if;
	if (:ObjectType = 'DLN') then	
		Header := 'ODLN';
		Lines :=  'DLN1';
		InstLines := 'DLN6';
		--opObject := 'RDN';
		WTLines := 'DLN5';
	end if;
	if (:ObjectType = 'RIN') then	
		Header := 'ORIN';
		Lines :=  'RIN1';
		InstLines := 'RIN6';
		WTLines := 'RIN5';
	end if;
	if (:ObjectType = 'RDN') then	
		Header := 'ORDN';
		Lines :=  'RDN1';
		InstLines := 'RDN6';
		WTLines := 'RDN5';
	end if;
	
	--[RemoveCIN]
	--if (@ObjectType = 'CIN')
	--Begin
	--	Set @Header = 'OCIN'
	--	Set @Lines =  'CIN1'
	--	Set @InstLines = 'CIN6'
	--	Set @WTLines = 'CIN5'
	--End
	
	--* NOT USED	
	SELECT TOP 1 COLUMN_NAME into VatSysColName FROM "PUBLIC"."TABLE_COLUMNS" as A WHERE TABLE_NAME = :Header and POSITION = 57;	
	 
	
	WhereStr := ' Main."DocDate" Between   TO_DATE( ''' ||  :DocDateFrom 
		|| ''', ''YYYYMMDD'' )	And  TO_DATE( ''' ||  :DocDateTo 
		|| ''', ''YYYYMMDD'' ) And  Inst."DueDate" Between TO_DATE( ''' 
		||  :DocDueDateFrom || ''', ''YYYYMMDD'' )	And  TO_DATE( ''' 
		||  :DocDueDateTo || ''', ''YYYYMMDD'' ) ';
	
	--Card Code range
	if LENGTH(:CardCodeFrom) > 0 then 
		WhereStr := :WhereStr  || '   And    Main."CardCode" >=  N''' ||  :CardCodeFrom || '''  ';
	end if;

	if LENGTH(:CardCodeTo) > 0 then 
		WhereStr := :WhereStr   || '   And    Main."CardCode" <=  N''' ||  :CardCodeTo || '''  ';
	end if;
	
	--Sales person range
	if LENGTH(:SlpCodeFrom) > 0 then
		WhereStr := :WhereStr  || '    And   Slps."SlpName" >=  N''' ||  :SlpCodeFrom || '''  ';
	end if;
	if LENGTH(:SlpCodeTo) > 0 then	
		WhereStr := :WhereStr  || '    And   Slps."SlpName" <=  N''' ||  :SlpCodeTo || '''  ';
	end if;
	
	if :SlpIncludeInactive = 'N' then
		WhereStr := :WhereStr || ' And Slps."Active" = ''Y''';
	end if;
	
	WhereStr := :WhereStr  || '	And	 Main."Instance" = 0	'
		|| ' And Main."TaxDate"  Between  TO_DATE( ''' ||  :TaxDateFrom 
		|| ''', ''YYYYMMDD'' )  And  TO_DATE( ''' ||  :TaxDateTo || ''', ''YYYYMMDD'' )	';
		
	
	if(:ObjectType='INV' OR :ObjectType='DLN' OR :ObjectType = 'RIN' OR :ObjectType = 'RDN') then
		if(:ShowType = 'CAN') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''C'' '	;
		else
			WhereStr := :WhereStr || 'And	   Main."CANCELED" <> ''C'' '	;
		end if;
	else
		if(:ObjectType <> 'CSI') then
			WhereStr := :WhereStr || 'And	   Main."CANCELED" = ''N'' '	;
		end if;
	end if;

	
	if LENGTH(:CrdGroupCode) > 0 then 	
		WhereStr := :WhereStr || ' And  Cards."GroupCode" = ' || :CrdGroupCode; 
	end if;
	
	if LENGTH(:CrdProps) > 0 then
	 	
		if (SUBSTRING (:CrdProps, 65, 1)  = 'N') then		
			PropsRel := ' OR ';		
		Else		
			PropsRel := ' AND ';
		end if;
		 
		WhereStr := :WhereStr || '  And ( '; 
		ii := 1;
		jj := 1;
		While (:ii <= 64) do		
			if (SUBSTRING (:CrdProps, :ii, 1)  = 'Y') then			
				if (:jj <> 1) then				
					WhereStr := :WhereStr || :PropsRel;
				end if; 	
				WhereStr := :WhereStr || ' Cards."QryGroup' || Cast (:ii As nChar(2)) || '" = ''Y''';
				jj := :jj + 1;
			end if; 
			ii := :ii + 1;
		end while;
		WhereStr := :WhereStr || ') '; 
	end if;
	
	if (:ObjectType = 'RIN') then
		if(:ShowType <> 'CAN') then
			WhereStr := :WhereStr || ' AND NOT  EXISTS (SELECT 1 FROM '|| :ObjectType || '1 T1 WHERE T1."DocEntry" = Main."DocEntry"    AND T1."BaseType" = 203) ';
		else
			WhereStr := :WhereStr || ' AND NOT EXISTS (SELECT 1 FROM ' || :ObjectType || '1 T1 ,' || :ObjectType || '1 T2 WHERE T1."DocEntry" = Main."DocEntry"  AND T1."BaseType" = 14 AND T1."BaseEntry" = T2."DocEntry" AND T2."BaseType" = 203)';
		end if;
	end if;
		
	DpmSUM := '';
	DpmSUM_SC := '';
	DpmSUM_with_Inst := '';
	DpmSUM_SC_with_Inst := '';
	if (:DpmAffectsTotal = 1) then 	 	
		DpmSUM := ' + Sum(aa."DpmAmnt") ';		
		DpmSUM_SC := ' + Sum(aa."DpmAmntSC") ';		
		DpmSUM_with_Inst := ' + Sum(Main."DpmAmnt" * Inst."InstPrcnt"/100) ';		
		DpmSUM_SC_with_Inst := ' + Sum(Main."DpmAmntSC" * Inst."InstPrcnt"/100)';		
	end if;

						
	tmpStr := ' Insert into "TmpPsar_Sales_An_Slp_Sng_Y" ' ||
	'Select Slps."SlpCode", Slps."SlpName",  Count(Main."DocNum") As TotalDocs, ' ||
	'	(Sum(Inst."InsTotal") - Sum(Inst."VatSum") + Sum(IfNull(Main."FoCTax",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpns") + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| :DpmSUM_with_Inst  
          	|| ' - Sum(Main."RoundDif" * Inst."InstPrcnt"/100))  * ' || :Mult 
          	|| '  As Sales,	(Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100))  * ' || :Mult 
          	|| ' As GrossProfit, ((Sum(Main."GrosProfit" * Inst."InstPrcnt" / 100)  /  '
          	|| ' nullif((Sum(Inst."InsTotal") - Sum(Inst."VatSum") + Sum(IfNull(Main."FoCTax",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpns") + ' 
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| '),0)) * 100)  * ' || :Mult 
           	|| ' as GrossPrcnt, ';
           	
	if (:ShowType = 'SNG' or :ShowType = 'SN1') then	
			tmpStr := :tmpStr || '(Select Sum(Distinct(aa."DocTotal"))  - Sum(Distinct(aa."VatSum")) + Sum(Distinct(IfNull(aa."FoCTax",0))) - Sum(Distinct(aa."TotalExpns")) + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSum")' END)
			|| ' - (Sum(Distinct(aa."PaidToDate"))-Sum(Distinct(aa."VatPaid")) - Sum(Distinct(aa."ExpAppl")) ) From ' 
			|| :Header || ' aa   Where  aa."DocEntry" = Main."DocEntry" And Main."PaidToDate" <> Main."DocTotal")  * ' 
			|| :Mult || '  As TotalOpen, ';	
	else 	
		tmpStr := :tmpStr || ' 0, ';
	end if;
	
	tmpStr := :tmpStr || ' (Sum(Inst."InsTotalSy") - Sum(Inst."' || :VatSysColName 
         	|| '" ) + Sum(IfNull(Main."FoCTaxSC",0) * Inst."InstPrcnt" / 100) - Sum(Inst."TotalExpSC") + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSumSC")' END)
			|| :DpmSUM_SC_with_Inst  
          	|| ' - Sum(Main."RoundDifSy" * Inst."InstPrcnt"/100	) ) * ' || :Mult 
          	|| '  As SalesSys, Sum(Main."GrosProfSy"  * Inst."InstPrcnt" / 100) * ' 
          	|| :Mult || 'As GrossProfitSys, ((Sum(Main."GrosProfSy"  * Inst."InstPrcnt" / 100)'
          	|| ' /  nullif((Sum(Inst."InsTotalSy") - Sum(Inst."' || :VatSysColName || '") + Sum(IfNull(Main."FoCTaxSC",0) * Inst."InstPrcnt" / 100) + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSumSC")' END)
			|| ' - Sum(Inst."TotalExpSC")),0)) * 100) * ' 
          	|| :Mult || ' as GrossPrcntSys, ';
  
	if (:ShowType = 'SNG' or :ShowType = 'SN1') then	
		tmpStr := :tmpStr || '(Select Sum(Distinct(aa."DocTotalSy"))  - Sum(Distinct(aa."' 
			|| :VatSysColName || '")) + Sum(Distinct(IfNull(aa."FoCTaxSC",0))) + '
			|| (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
				ELSE '-Sum(Inst."WTSumSC")' END)
			|| ' -  Sum(Distinct(aa."TotalExpSC")) - (Sum(Distinct(aa."PaidSys")) '
			|| ' - Sum(Distinct(aa."VatPaidSys")) - Sum(Distinct(aa."ExpApplSC")) ) From ' || :Header 
			|| ' aa   Where  aa."DocEntry" = Main."DocEntry" And Main."PaidSys" <> Main."DocTotalSy")  * ' || :Mult || '  As TotalOpenSys, ';	
	else 	
		tmpStr := :tmpStr || ' 0 , ';
	end if;
  
	tmpStr2 :=  ' (Select  (Sum(aa."DocTotal") - Sum(aa."VatSum") + Sum(IfNull(aa."FoCTax",0)) - Sum(aa."TotalExpns") ' || :DpmSUM  || ' - Sum(aa."RoundDif") + ' 
					 || (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSum") ELSE 0 END)'
						ELSE '-Sum(Inst."WTSum")' END)
					 || ' ) From ' || :Header 
          			 || ' aa   Where  aa."DocEntry" = Main."DocEntry" )  * ' || :Mult 
          			 || '  As  SalesForPrcnt  , '          			 
          			 || '  (Select  (Sum(aa."DocTotalSy") - Sum(aa."' || :VatSysColName 
          			 || '") + Sum(IfNull(aa."FoCTaxSC",0)) - Sum(aa."TotalExpSC") + '
					 || (CASE :WTaxEngine WHEN 'N' THEN '(CASE cate."Category" WHEN ''I'' THEN Sum(Inst."WTSumSC") ELSE 0 END)'
						ELSE '-Sum(Inst."WTSumSC")' END)
					 || :DpmSUM_SC  || ' - Sum(aa."RoundDifSy") ) From ' 
          			 || :Header || ' aa   Where  aa."DocEntry" = Main."DocEntry" )  * ' 
          			 || :Mult || '  As  SalesForPrcntSys ';          			  
   
	tmpStr2 := :tmpStr2 || ' From  ' || :Header || ' Main '  
		|| ' Inner  Join OCRD Cards On Cards."CardCode" = Main."CardCode" '
		|| ' Inner  Join OCRG Crdg On Crdg."GroupCode" = Cards."GroupCode" '
		|| ' Inner  Join OSLP  Slps On Slps."SlpCode" = Main."SlpCode" '
		|| ' Inner  Join ' || :InstLines || ' Inst On inst."DocEntry" = Main."DocEntry" ';
	
	if (:WTaxEngine = 'N') then
		tmpStr2 := :tmpStr2 || ' Left Join "TmpPsar_MinCategory" cate on cate."AbsEntry" = Main."DocEntry" ';
	end if;
	
	if :DspFrznBP = 'N' then	
		WhereStr := ' (' || :WhereStr || ') And ' || 
					'(Cards."validFor" = ''Y'' or (Cards."frozenFor" = ''Y'' and ' ||
					'(Cards."frozenFrom" is not null or Cards."frozenTo" is not null))' ||
					' or (Cards."validFor" = ''N'' and Cards."frozenFor" = ''N''))';
	end if;
	
	if LENGTH(:BPLIdSet) > 0 then
		WhereStr := :WhereStr || ' And Main."BPLId" in (' || :BPLIdSet || ')';
	end if;

	WhereStr := 'Where	' || :WhereStr || '  Group By  Slps."SlpCode", Slps."SlpName", Main."DocEntry", Main."PaidToDate", '
		|| ' Main."DocTotal", Main."DocTotalSy", Main."PaidSys" ';
		
	if (:WTaxEngine = 'N') then
		WhereStr := :WhereStr || ', cate."Category"'; 
	end if;

	if LENGTH(:CrdGroupCode) > 0 then 	
		WhereStr := :WhereStr || ', Cards."GroupCode" ';
	end if;

	if (:WTaxEngine = 'N') then
		Delete from "TmpPsar_MinCategory";
		SQ := 'Insert into "TmpPsar_MinCategory" Select "AbsEntry", MIN("Category") from '||:WTLines||' Group by "AbsEntry"';
		EXEC (:SQ);
	end if;

	exec ( :tmpStr || :tmpStr2 || :WhereStr );
	-- select top 1 (:tmpStr || :tmpStr2 || :WhereStr) from dual;
	/* End Here */

	--print @tmpStr
	--print @WhereStr
	
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_SetBalanceByJdt (IN jdtAbs INT, OUT retCode INT)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
-- Return Codes
--(-1) = Empty Parameter Was Entered
--(-2)  --Enpty or invalid Line set
--(-3) -- Invalid Currency or Bad Account code
--(-4) -- Invalid Card Currency or Bad Account code
--****************
acctCode nvarchar(15);
cardCode nvarchar(15);
Acctcurr nchar(3);
Cardcurr nchar(3);
mainCurr  nchar(3);
sys DECIMAL(21,6);
loc DECIMAL(21,6);
fc  DECIMAL(21,6);
IsCard int;
IsAcctFc int;
IsCardFc int;
DisNegativeSign nchar(1);

CURSOR Currs FOR
select	JDT1."Account", OACT."ActCurr", JDT1."ShortName", OCRD."Currency",
	sum(IFNULL(JDT1."Credit", 0)) - sum(IFNULL(JDT1."Debit", 0)),
	sum(IFNULL(JDT1."SYSCred", 0)) - sum(IFNULL(JDT1."SYSDeb", 0)),
	sum(IFNULL(JDT1."FCCredit", 0)) - sum(IFNULL(JDT1."FCDebit", 0))
From JDT1 
	inner join OACT on OACT."AcctCode" = JDT1."Account"
	Left Outer join OCRD on OCRD."CardCode" = JDT1."ShortName"
Where JDT1."TransId" = :jdtAbs 
group by JDT1."Account", OACT."ActCurr", JDT1."ShortName", OCRD."Currency";

begin
	if :jdtAbs = 0 then
		retCode := -1;
		return;
	end if;
	
	select top 1 "MainCurncy", "DispPosDeb" into mainCurr, DisNegativeSign from OADM;
	Open Currs;
	Fetch Currs into acctCode, Acctcurr, cardCode, Cardcurr, loc, sys, fc;
	
	if (Currs::NOTFOUND) then
		Close Currs;
		retCode := -2;
		return ;
	end if;
	
	While not Currs::NOTFOUND do
		if :DisNegativeSign = 'Y' then
			loc := :loc * -1;
			sys := :sys * -1;
			fc := :fc * -1;
		END if;
		
	--Check to see if this involves a CARD
		IsCard := 0;
		IsCardFc := 0;
		if :acctCode <> :cardCode then
		   	IsCard := 1;
		
			if :Cardcurr <> '##' then
				if :mainCurr <> :Cardcurr then
				      IsCardFc := 1; --FC balance
				end	if;
			end if;
		end if;
	-- Validations **************************
		if :Acctcurr Is null then
			Close Currs;
			retCode := -3;
			return; -- Invalid Account Currency or Bad Account code
		end if;
	
		if :Cardcurr Is null and :IsCard = 1 then
			Close Currs;
			retCode := -4;
			return ; -- Invalid Card Currency or Bad Account code
		end if;
	
		IsAcctFc := 0;
		if :Acctcurr <> '##' then
			if :mainCurr <> :Acctcurr then 
				IsAcctFc := 1; --FC balance
			end if;
		end if;
	-- Do not update FC balance if account is multicurrency or account's currency is as a main currency
		if :IsAcctFc = 0 then
	        UPDATE OACT SET "CurrTotal" = IFNULL("CurrTotal", 0) + :loc, "SysTotal" = IFNULL("SysTotal", 0) + :sys WHERE  OACT."AcctCode"  = :acctCode;
	-- update FC
		Else
	        UPDATE OACT SET "CurrTotal" = IFNULL("CurrTotal",0) + :loc, "SysTotal" = IFNULL("SysTotal", 0) + :sys, "FcTotal" = IFNULL("FcTotal", 0) + :fc WHERE OACT."AcctCode"  = :acctCode;
		End if;
	--Update A card  ***********************************************
		if :IsCard = 1 then
			if :IsCardFc = 0 then
				UPDATE OCRD SET "Balance" = IFNULL("Balance", 0) + :loc, "BalanceSys" = IFNULL("BalanceSys", 0) + :sys WHERE  OCRD."CardCode"  = :cardCode;
			Else
				UPDATE OCRD SET "Balance" = IFNULL("Balance", 0) + :loc, "BalanceSys" = IFNULL("BalanceSys", 0) + :sys, "BalanceFC" = IFNULL("BalanceFC", 0) + :fc WHERE  OCRD."CardCode"  = :cardCode;
			end if;
		end if;
	
		Fetch Currs Into acctCode, Acctcurr, cardCode, Cardcurr, loc, sys, fc;
	End while;
	
	Close Currs;
	
	retCode := 0;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2

CREATE PROCEDURE TmSp_SetBgtAccumulators_ByJdt (in jdtAbs int, in Alert nchar(1), in CurPeriod nvarchar(11)) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
month int;
tmpStr nvarchar(20);
AcctCode nvarchar(15);
RefDate datetime;
RefYear nchar(4);
sysCredit dec(19,6);
sysDebit dec(19,6);
locCredit dec(19,6);
locDebit dec(19,6);
BgtNum int;
YearStart datetime;
AlrType nchar(1);
YFmonth int;
TotsysDebit dec(19,6);
TotlocDebit dec(19,6);
YearRsum dec(19,6);
monthRsum dec(19,6);
YearDebTotal dec(19,6);
YearCredTotal dec(19,6);
monthDebTotal dec(19,6);
YOverSum dec(19,6);
MOverSum dec(19,6);
DoAlert nchar(1);
DisNegativeSign nchar(1);
IsBgtCredit nchar(1);
cnt int;
bgtCount int;

CURSOR Currs for
	select   JDT1."Account", JDT1."RefDate", sum(ifnull(JDT1."Credit", 0)), sum(ifnull(JDT1."Debit", 0)),	sum(ifnull(JDT1."SYSCred", 0)), sum(ifnull(JDT1."SYSDeb", 0))
	From JDT1 inner join OACT on OACT."AcctCode" = JDT1."Account"
	Where JDT1."TransId" = :jdtAbs  AND OACT."Budget" = N'Y' And JDT1."ShortName" = JDT1."Account"
	group by JDT1."Account", JDT1."RefDate";
	
begin
	delete from "TMP_SetBgtAcc_BgAlrChk";

	select "BgtWarning", "DispPosDeb" into AlrType, DisNegativeSign from OADM;
	select "FinancYear" into YearStart from OACP  Where "PeriodCat" = :CurPeriod;	

	Open Currs;
	Fetch Currs Into AcctCode, RefDate, locCredit, locDebit, sysCredit, sysDebit;
    
	While not Currs::NOTFOUND do
		RefYear := TO_NCHAR(year(:RefDate));
		BgtNum := 0;

		select count(*) into bgtCount
		From OBGT Inner Join OBGS on OBGS."AbsId" = OBGT."Instance"
		Where
			:RefDate BETWEEN OBGT."FinancYear" AND ADD_DAYS(ADD_YEARS(OBGT."FinancYear", 1), -1)
			And OBGT."AcctCode" = :AcctCode
			And OBGS."IsMain" = N'Y';
		if(:bgtCount = 0) then
			Fetch Currs Into AcctCode, RefDate, locCredit, locDebit, sysCredit, sysDebit;
			continue;
		end if;
			
		select OBGT."AbsId", ifnull(OBGT."DebLTotal", 0), ifnull(OBGT."CredLTotal", 0), ifnull(OBGT."DebRLTotal", 0) - ifnull(OBGT."CrdRLTotal", 0)
		 into BgtNum, YearDebTotal, YearCredTotal, YearRsum
		From OBGT Inner Join OBGS on OBGS."AbsId" = OBGT."Instance"
		Where
			:RefDate BETWEEN OBGT."FinancYear" AND ADD_DAYS(ADD_YEARS(OBGT."FinancYear", 1), -1)
			And OBGT."AcctCode" = :AcctCode
			And OBGS."IsMain" = N'Y';
       
		If :YearCredTotal > 0 then
			IsBgtCredit := N'Y';
		ELSE
			IsBgtCredit := N'N';
		end if;

		month := month(:RefDate);		
		
		YFmonth := month(:YearStart);
		month := :month - :YFmonth;

		if (:month < 0) then
			month := :month + 12;
		end if;
		
		select ifnull(BGT1."DebLTotal", 0), ifnull(BGT1."DebRLTotal", 0) - ifnull(BGT1."CrdRLTotal", 0)
		into monthDebTotal, monthRsum
		From BGT1
		Where "BudgId" = :BgtNum And "Line_ID" = :month;

	--Alert Validation
		if not :Alert = N'N' then
			if :IsBgtCredit = N'N' then
				if not (:locDebit = 0) then
					 YOverSum := :YearRsum - :YearDebTotal + :locDebit - :locCredit;
				Else
					YOverSum := :YearRsum - :YearDebTotal - :locCredit + :locCredit;
				end if;
				
				--MONTH accumulators		
				if not (:locDebit = 0) then
					MOverSum := :monthRsum - :monthDebTotal + :locDebit - :locCredit;
				Else
					MOverSum := :monthRsum - :monthDebTotal - :locCredit + :locCredit;
				end if;
				--*****************************		
				if (:AlrType = N'A') then
					if (:YOverSum <= 0) then
						DoAlert := N'N';
					Else
						DoAlert := N'Y';
					end if;
				Else
					if (:MOverSum <= 0 ) then
						DoAlert := N'N';
					Else
						DoAlert := N'Y';
					end if;
				End if;
				
		--if (:DoAlert = 'Y')
				if not (:BgtNum <= 0) then
					insert into "TMP_SetBgtAcc_BgAlrChk" (AcctCode , DoAlert , AlrType, MOverSum, YOverSum)
						values ( :AcctCode, :DoAlert, :AlrType, :MOverSum, :YOverSum);
				end if;
			end if;
		end if;

		if not :Alert = N'W' then
			select count(*) into cnt
			From OBGT Inner Join OBGS on OBGS."AbsId" = OBGT."Instance"
			Where
				:RefDate BETWEEN OBGT."FinancYear" AND
				ADD_DAYS(ADD_YEARS(OBGT."FinancYear", 1), -1)
				And OBGT."AcctCode" = :AcctCode
				And OBGS."IsMain" = N'Y';
				
			Update OBGT  Set
				"DebRLTotal" = ifnull("DebRLTotal", 0) + :locDebit,
				"CrdRLTotal" = ifnull("CrdRLTotal", 0) + :locCredit,
				"DebRSTotal" = ifnull("DebRSTotal", 0) + :sysDebit,
				"CrdRSTotal" = ifnull("CrdRSTotal", 0) + :sysCredit			
			Where
				:RefDate BETWEEN OBGT."FinancYear" AND
				ADD_DAYS(ADD_YEARS(OBGT."FinancYear", 1), -1)
				And OBGT."AcctCode" = :AcctCode
				AND "Instance" IN (select  "AbsId" from OBGS where "IsMain" = N'Y') ;

			If not :cnt = 0 then
				Update BGT1 Set
					"DebRLTotal" = ifnull("DebRLTotal", 0) + :locDebit  ,
					"CrdRLTotal" = ifnull("CrdRLTotal", 0) + :locCredit  ,
					"DebRSTotal" = ifnull("DebRSTotal", 0) + :sysDebit ,
					"CrdRSTotal" = ifnull("CrdRSTotal", 0) + :sysCredit
				Where "BudgId" = :BgtNum And "Line_ID" = :month;
			End if;
		End if;

		Fetch Currs Into AcctCode, RefDate, locCredit, locDebit, sysCredit, sysDebit;
	
	End while;

	select * from "TMP_SetBgtAcc_BgAlrChk";
	delete from "TMP_SetBgtAcc_BgAlrChk";
	CLOSE Currs;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE   procedure TmSp_SetGlStamp(IN FldType int)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
as
begin
	if (:FldType = 1) then 
		UPDATE CINF SET "ADMStamp" = "ADMStamp" + 1; 
	end if;
	if (:FldType = 2) then 
		UPDATE CINF SET "ACTStamp" = "ACTStamp" + 1;
	end if;
	if (:FldType = 3) then 
		UPDATE CINF SET "RTTStamp" = "RTTStamp" + 1;
	end if;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_SetVendorDeductPercent(
	in jdtAbs   int, 
	in PeriodCat nvarchar(11),
	out result int
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	 cardCode		nvarchar(15);
	 mainVendLoc		nvarchar(15);
	 mainVendFrgn		nvarchar(15);
	 locSum		float;
	 currentPayments	float;
	 ddctPrcnt		float;
	 ddgPrcnt		float;
	 DisNegativeSign	nchar(1);
	 currentDDT		int;
	 today        TIMESTAMP;
	 dateFrom		TIMESTAMP;
	 dateTo		TIMESTAMP;
	 c_next int := 1;
	 cursor Currs (jdtAbs   int) for 
				select JDT1."ShortName", ODDG."DdctPrcnt", sum(IfNull(JDT1."Credit",0)) - sum(IfNull(JDT1."Debit",0))
				From JDT1 inner join OCRD on OCRD."CardCode" = JDT1."ShortName" 
					inner join ODDG on OCRD."DdgKey" = ODDG."Numerator"
				Where JDT1."TransId" = :jdtAbs AND JDT1."ShortName" <> JDT1."Account" AND OCRD."CardType" = N'S'
					group by JDT1."ShortName", ODDG."DdctPrcnt";

begin

	if (:jdtAbs = null) then
		result := -1; 
		return;
	end if;


--	today := CONVERT(TIMESTAMP, cast(DATEPART(yyyy, getdate()) as nchar(4)) || REPLACE( STR(MONTH(getdate()), 2), ' ' , '0')|| REPLACE( STR(DAY(getdate()), 2), ' ' , '0'), 112);

    today := CURRENT_TIMESTAMP;

	select "DispPosDeb" into DisNegativeSign from OADM; 
	select "LinkAct_10" into mainVendLoc from OACP where "PeriodCat" = :PeriodCat;
	select "LinkAct_11" into mainVendFrgn from OACP where "PeriodCat" = :PeriodCat;
	
	--/***********************	Main Query	*************************/

	Open Currs (:jdtAbs);
	Fetch Currs Into  cardCode, ddgPrcnt,  locSum;

	--/***********************	Validations	*************************/
	if  Currs::NOTFOUND  then
			Close Currs;
			result := -2;
			return;  --Enpty or invalid Line set
	end if;
	--/*************************************************************************/
 

	While ( :c_next > 0) do
		Fetch Currs Into  cardCode, ddgPrcnt, locSum;  
		
		if (:DisNegativeSign = N'Y') then
			locSum := :locSum * -1;
		END if;

		--  Check if local sum > 0
		if (:locSum = 0) then
			Fetch Currs 
			Into  cardCode, ddgPrcnt, locSum;
			continue;
		end if;

		-- Get current DDT
		currentDDT := -1;

		select "Numerator" into currentDDT
		FROM ODDT  
		WHERE "CardCode" = :cardCode  AND  
			"DateFrom" <= :today  AND  
			"DateTo" >= :today;

		select "DateFrom" into dateFrom
		FROM ODDT 
		WHERE "CardCode" = :cardCode  AND  
			"DateFrom" <= :today  AND  
			"DateTo" >= :today;
			
		select "DateTo" into dateTo
		FROM ODDT 
		WHERE "CardCode" = :cardCode  AND  
			"DateFrom" <= :today  AND  
			"DateTo" >= :today;
			
		if (:currentDDT = -1)
		then
			dateFrom := '';

			select TOP 1  "Numerator" into currentDDT
	    	FROM ODDT 
			WHERE "CardCode" = :cardCode  AND  
				"DateFrom" <= :today  AND  
				"DateTo" >= :today
			ORDER BY "DateTo" DESC;
			
--			select TOP 1 DATEADD(dd, 1,"DateTo") into dateFrom
			select TOP 1 ADD_DAYS(To_Date("DateTo"),1) into dateFrom
			FROM ODDT 
			WHERE "CardCode" = :cardCode  AND  
				"DateFrom" <= :today  AND  
				"DateTo" >= :today
			ORDER BY "DateTo" DESC;
			
		--	dateFrom := ADD_DAYS()
		end if; 

		-- Get current payments to card
		SELECT sum(IfNull(T0."Debit", 0)) - sum(IfNull(T0."Credit", 0)) into currentPayments
		FROM JDT1 T0 
		WHERE ((T0."TransType" IN (30, 57, 25, 76, 46 ) AND  
				T0."RefDate" >= :dateFrom  AND  T0."RefDate" <= :dateTo)
				OR  T0."RelType" = N'D' ) AND  
			(T0."Account" = :mainVendLoc  OR  T0."Account" = :mainVendFrgn ) AND  
			T0."ShortName" <> T0."Account"  AND  T0."Debit" <> 0  AND  
			T0."ShortName" = :cardCode AND T0."RelType" <> N'D';  

		-- Get appropriate DDT1
		ddctPrcnt := -1;

		if (:currentDDT <> -1)
		then
			select IfNULL (MIN (T0."DdctPrcnt"), -1) into ddctPrcnt
			FROM DDT1 T0
			WHERE T0."DdtKey" = :currentDDT AND T0."MaxSum" >= :currentPayments;

			if (:ddctPrcnt = -1) then		
					select IFNULL (T0."DdctPrcnt", -1) into ddctPrcnt
					FROM DDT1 T0
					WHERE T0."DdtKey" = :currentDDT AND (T0."MaxSum" = 0 OR T0."MaxSum" Is Null);
			end if;
		end if;

		if (:ddctPrcnt = -1) then
			ddctPrcnt := :ddgPrcnt;
		end if;



		/****************	Update the card	*****************/
    	UPDATE OCRD
	    SET "DdctPrcnt" = :ddctPrcnt
		WHERE "CardCode"  = :cardCode;
		
		IF Currs::NOTFOUND THEN
			c_next := -1;
		END IF;	
	End While; 
 
	Close Currs;
	
	result := 0;
	return;
end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:SP:_TmSp_ValidateSpParam

create procedure TmSp_SpecialPriceCopy (in targetCrd nvarchar(15),in sourceCrd nvarchar(15),in userID int,In class int,in tempTableSuffix nvarchar(10))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
tempname nvarchar(100);
table_nm nvarchar(100);
sql_str nvarchar(200);
cnt int;
ospp nvarchar(100);
spp1 nvarchar(100);
spp2 nvarchar(100);
targetCrd1 nvarchar(15);
sourceCrd1 nvarchar(15);
SQ NVARCHAR(1000);
i int;
begin
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
call _TmSp_ValidateSpParam(:targetCrd);
call _TmSp_ValidateSpParam(:sourceCrd);
call _TmSp_ValidateSpParam(:tempTableSuffix);

targetCrd1 := :targetCrd;
sourceCrd1 := :sourceCrd;
targetCrd1 := ltrim(:targetCrd1);
targetCrd1 := rtrim(:targetCrd1);
sourceCrd1 := ltrim(:sourceCrd1);
sourceCrd1 := rtrim(:sourceCrd1);
SELECT 'temp_'|| CURRENT_CONNECTION into tempname FROM DUMMY;

delete from "TMP_SpecialPriceCopy_RowCount";

if length (:tempTableSuffix) = 0
then
	--ins_msg_proc ('tempTableSuffix = 0');
	ospp := 'OSPP';
	spp1 := 'SPP1';
	spp2 := 'SPP2';
else
	--ins_msg_proc ('tempTableSuffix = ' || :tempTableSuffix);
	ospp := '#ospp_' || :tempTableSuffix;
	spp1 := '#spp1_' || :tempTableSuffix;
	spp2 := '#spp2_' || :tempTableSuffix;
end if;

if :class = 1 
then
	-- Check availability
	if :ospp <> 'OSPP' then
		delete from "TMP_SpecialPriceCopy_RowCount";
		SQ :='insert into "TMP_SpecialPriceCopy_RowCount" select count(*) from "PUBLIC"."M_TEMPORARY_TABLES" where table_name like ''' || :ospp ||'%''';
	    --ins_msg_proc (:SQ);
        EXEC (:SQ);
        select top 1 "rownum" into cnt from "TMP_SpecialPriceCopy_RowCount";
      	if :cnt = 0 then
      		--ins_msg_proc ('we don not have it');
			delete from "TMP_SpecialPriceCopy_RowCount";
			return;
		end if;
	end if;

	delete from "TMP_SpecialPriceCopy_RowCount";
	SQ :='insert into "TMP_SpecialPriceCopy_RowCount" select count(*) from "' || :ospp || '" where "CardCode" = N''' || :sourceCrd1 || ''' and "ItemCode" in (select "ItemCode" from "OSPP" where "CardCode" = N''' || :targetCrd1 || ''')';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);
	
	select top 1 "rownum" into cnt from "TMP_SpecialPriceCopy_RowCount";
	if :cnt = 0 then
	    delete from "TMP_SpecialPriceCopy_RowCount";
		return;
	end if;

	cnt := 1;
	i := -1;
	WHILE :cnt <> 0 DO
		i := :i + 1;
		table_nm := :tempname || :i;
		SELECT COUNT(*) INTO cnt FROM "PUBLIC"."TABLES" where "TABLE_NAME" = :table_nm;		
	END WHILE;

	SQ := 'create column table ' || :table_nm || ' as (select * from "' || :ospp || '" where "CardCode" = N''' || :sourceCrd1 || ''' and "ItemCode" in (select "ItemCode" from "OSPP" where "CardCode" = N''' || :targetCrd1 || '''))' ;
 	--ins_msg_proc (:SQ);
    EXEC (:SQ);
 
    SQ :='update ' || :table_nm || ' set "CardCode" = N''' || :targetCrd1 || ''', "UserSign" =  N''' || :userID || '''';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);


	-- Remove old data
    SQ :='delete from "SPP2" where "CardCode" = N''' || :targetCrd1 || ''' and "ItemCode" in (select "ItemCode" from "' || :ospp || '" where "CardCode" = N''' || :sourceCrd1 || ''')';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);
    
    SQ :='delete from "SPP1" where "CardCode" = N''' || :targetCrd1 || ''' and "ItemCode" in (select "ItemCode" from "' || :ospp || '" where "CardCode" = N''' || :sourceCrd1 || ''')';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);
    
    SQ :='delete from "OSPP" where "CardCode" = N''' || :targetCrd1 || ''' and "ItemCode" in (select "ItemCode" from "' || :ospp || '" where "CardCode" = N''' || :sourceCrd1 || ''')';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);
    
	-- Copy new data
    SQ :='insert into "OSPP" select * from ' || :table_nm || '';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);
	
    SQ :='drop table ' || :table_nm || '';
    --ins_msg_proc (:SQ);
    EXEC (:SQ);
	-- Check if there is temp table

    	
	if :spp1 <> 'SPP1' 	then
		delete from "TMP_SpecialPriceCopy_RowCount";
	    SQ :='insert into "TMP_SpecialPriceCopy_RowCount" select count(*) from "PUBLIC"."M_TEMPORARY_TABLES" where table_name like ''' || :spp1 || '%''';
        --ins_msg_proc (:SQ);
        EXEC (:SQ);
		select top 1 "rownum" into cnt from "TMP_SpecialPriceCopy_RowCount";
		if :cnt = 0 then
        	delete from "TMP_SpecialPriceCopy_RowCount";
			return;
		end if;
	end if;
	

	cnt := 1;
	i := -1;
	WHILE :cnt <> 0 DO
		i := :i + 1;
		table_nm := :tempname || :i;
		SELECT COUNT(*) INTO cnt FROM "PUBLIC"."TABLES" where "TABLE_NAME" = :table_nm;		
