CREATE PROCEDURE TmSp_TaxableDeliveryReport (

v_CardCode nvarchar(100),
v_postingDateFrom datetime,
v_postingDateTo datetime,
v_deliveryDateFrom datetime,
v_deliveryDateTo datetime,
v_documentDateFrom datetime,
v_documentDateTo datetime,
v_documentNumberFrom nvarchar(20),
v_documentNumberTo nvarchar(20),
v_dateDiffValue nvarchar(10)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	v_sqlString nvarchar (4000);
	v_vardate nvarchar(1000);
	v_cnt integer;
BEGIN
	
	select count (*) into v_cnt from "PUBLIC"."M_TEMPORARY_TABLES" where TABLE_NAME = '#TAXABLEDELIVERYREPORT';
   	if :v_cnt > 0 then
    	drop table #TAXABLEDELIVERYREPORT;
    end if;

	create local temporary column table #TaxableDeliveryReport(
	"DocNum" INTEGER not null,
	"DocEntry" INTEGER not null,
	"CardCode" NVARCHAR (15) null,
	"CardName" NVARCHAR (200) null,
	"DocDate" TIMESTAMP null,
	"VatSum" DECIMAL (34) null);
	v_sqlString := 'insert into #TaxableDeliveryReport select "DocNum", "DocEntry", "CardCode", "CardName", "DocDate", "VatSum"  from ODLN 	where "DocEntry" in  	( 		( 			 			select distinct T0."DocEntry" from DLN4 T0 			inner join OSTT T1 ON  T0."staType" = T1."AbsId"  AND  T1."NfTaxId" = -3 			inner join ODLN T9 ON T9."DocEntry" = T0."DocEntry" 			left outer join DLN1 T2 ON T2."DocEntry" = T0."DocEntry" and T2."LineNum" = T0."LineNum" and (T0."RelateType" = 1 or T0."RelateType" = 2) 			left outer join DLN3 T4 ON T4."DocEntry" = T0."DocEntry" and T4."LineNum" = T0."LineNum" and T4."ExpnsCode" = T0."ExpnsCode" and T0."RelateType" = 3 			where  			( 			(T0."RelateType" = 1 and t2."LineStatus" = ''O'') 			or 			(T0."RelateType" = 2 and t2."LineStatus"  = ''O'') 			or 			(T0."RelateType" = 3 and T4."Status" = ''O'') 			) 		)  		intersect  		( 			 			( 				select distinct T0."DocEntry" from DLN4 T0 				inner join OSTT T1  ON  T1."AbsId" = T0."staType"  AND  T1."NfTaxId" = -3 				where "DocEntry" not in 				( 				select distinct t0."DocEntry" from dln4 t0 				inner join OSTT T1 ON  T0."staType" = T1."AbsId"  AND  T1."NfTaxId" = -3 				inner join DPI1 T2 ON T2."BaseEntry" = t0."DocEntry" and T2."BaseType" = 15 and T2."BaseLine" = t0."LineNum" and t0."RelateType" = 1 				inner join DLN1 T3 ON T3."DocEntry" = T0."DocEntry" and T3."LineNum" = T0."LineNum" and T0."RelateType" = 1 				inner join ODLN T4 ON T4."DocEntry" = T0."DocEntry" 				where (T3."Quantity" = T2."Quantity" and T4."DocType" = ''I'') or (T3."Price" = T2."Price" and T4."DocType" = ''S'') 				) 			)  			union  			 			( 				select distinct T0."DocEntry" from DLN4 T0 				inner join OSTT T1  ON  T1."AbsId" = T0."staType"  AND  T1."NfTaxId" = -3 and t0."RelateType" = 1 				inner join ODLN T2  ON  T2."DocEntry" = T0."DocEntry" 				inner join DPI1 T3 ON T3."BaseEntry" = t0."DocEntry" and T3."BaseType" = 15 and T3."BaseLine" = t0."LineNum" and t0."RelateType" = 1 				inner join ODPI T4 ON T4."DocEntry" = T3."DocEntry" 				where T4."DocStatus"  <> ''C'' 			) 		)  	) 	AND "ServPostID" IS NULL 	AND "DocDate" < ADD_DAYS (current_date, -' || :v_dateDiffValue || ')';                                                                                                  
	
	
	
	-- "CardCode"
	if (:v_CardCode <> '') THEN
		v_sqlString := :v_sqlString || ' AND "CardCode" = ''' || :v_CardCode || '''';
	end if;

	SELECT TO_VARCHAR(:v_postingDateFrom, 'YYYYMMDD') INTO v_vardate from dummy;
	
	-- posting date
	if (:v_postingDateFrom <> '') then 
		v_sqlString := :v_sqlString || ' AND "DocDate" >= ''' || :v_vardate  || '''';
	end if;
	
	SELECT TO_VARCHAR(:v_postingDateTo, 'YYYYMMDD')  INTO v_vardate from dummy;
	if (:v_postingDateTo <> '') then
		v_sqlString := :v_sqlString || ' AND "DocDate" <= ''' || :v_vardate || '''';
	end if;
	
	-- delivery date

	SELECT TO_VARCHAR(:v_deliveryDateFrom, 'YYYYMMDD') INTO v_vardate from dummy;
	if (:v_deliveryDateFrom <> '') then
		v_sqlString := :v_sqlString || ' AND "DocDueDate" >= ''' || :v_vardate || '''';
	end if;

	SELECT TO_VARCHAR(:v_deliveryDateTo, 'YYYYMMDD') INTO v_vardate from dummy;
	if (:v_deliveryDateTo <> '') then
		v_sqlString := :v_sqlString || ' AND "DocDueDate" <= ''' || :v_vardate || '''';
	end if;
	
	-- document date
	SELECT TO_VARCHAR(:v_documentDateFrom, 'YYYYMMDD') INTO v_vardate from dummy;
	if (:v_documentDateFrom <> '') then
		v_sqlString := :v_sqlString || ' AND "TaxDate" >= ''' || :v_vardate || '''';
	end if;

	SELECT  TO_VARCHAR(:v_documentDateTo, 'YYYYMMDD') INTO v_vardate from dummy;
	if (:v_documentDateTo <> '') then
		v_sqlString := :v_sqlString || ' AND "TaxDate" <= ''' || :v_vardate || '''';
	end if;

	-- document number
	if (:v_documentNumberFrom <> '') then
		v_sqlString := :v_sqlString || ' AND "DocNum" >= ''' || :v_documentNumberFrom || '''';
	end if;

	if (:v_documentNumberTo <> '') then
		v_sqlString := :v_sqlString || ' AND "DocNum" <= ''' || :v_documentNumberTo || '''';
	end if;

	select * from #TaxableDeliveryReport;
	--exec (:v_sqlString);
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables2 AFTER:PT:PROCESS_END

create procedure TmSp_TransferRecordsToUILM(in MsgFromCopy INT,in MsgToCopy INT)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
	MaxMIDfromUILM INT; 
	MessageIDDelta INT;
	cnum int;
	col nvarchar(256);
	sqll varchar(4096);
	extFields nclob;
	orgUDFField varchar(20);
	countUDFField int;
	curFieldID int;
	findInUILM1 int;
	sqlStr nclob;
BEGIN
	SELECT IFNULL(MAX("MessageID"),0) into MaxMIDfromUILM FROM UILM; 
	MessageIDDelta := :MaxMIDfromUILM - :MsgFromCopy;
	
	delete from "TmSpTransferRecordsToUILM_TMP";
	
	insert into "TmSpTransferRecordsToUILM_TMP" 
	SELECT SC.COLUMN_NAME, SC.POSITION
	FROM "PUBLIC".TABles SO INNER JOIN "PUBLIC"."TABLE_COLUMNS" SC ON SO.TABLE_OID = SC.TABLE_OID  
	WHERE SO.Table_name = 'OILM' and SC.POSITION <> 1 and SC.SCHEMA_NAME = CURRENT_SCHEMA 	ORDER BY SC.POSITION;
	
	sqll := 'INSERT INTO UILM SELECT "MessageID" + ' || cast(:MessageIDDelta as char(128));
	
	select count(*) into cnum from "TmSpTransferRecordsToUILM_TMP";
	--select cnum from dummy;
	while (:cnum) > 0 do
		select top 1 "NAME" into col from "TmSpTransferRecordsToUILM_TMP" order by "POS";
		delete from "TmSpTransferRecordsToUILM_TMP" where name = :col;
		sqll := :sqll || ', "' || :col || '"';
		cnum := :cnum - 1;
	END while;
	
	sqll := :sqll || ' FROM OILM WHERE "MessageID" > '
		|| cast (:MsgFromCopy as char(128)) || ' AND "MessageID" <= '
		|| cast (:MsgToCopy as char(128));
	exec (:sqll);

	select Min("FieldID") , count(1) into curFieldID,countUDFField FROM CUFD WHERE "TableID" = 'UILM1';

	extFields := '';
	curFieldID := :curFieldID - 1;

	while :countUDFField > 0
		do
		select TOP 1 "AliasID" , "FieldID" into orgUDFField, curFieldID FROM CUFD WHERE "TableID" = 'UILM1' AND "FieldID" > :curFieldID  ORDER BY "FieldID";

		SELECT count(1) into findInUILM1 FROM CUFD WHERE "TableID" = 'UILM1' and "AliasID" = :orgUDFField;
		
		if :findInUILM1 > 0
		then 
			extFields := :extFields || ', ILM1."U_' || :orgUDFField || '" AS "U_' || :orgUDFField || '" ';
		END if;
		countUDFField := :countUDFField - 1;
	END while;
	
	sqlStr := 'INSERT INTO UILM1 ' ||
	 	'SELECT "MessageID" + ' || :MessageIDDelta || ', "ItemCode", "SysNumber", "Quantity", "MdAbsEntry"' ||
	 	:extFields ||
	'FROM "ILM1"' ||
		'WHERE "MessageID" > ' || :MsgFromCopy || ' AND "MessageID" <= ' || :MsgToCopy;
	exec (:sqlStr);
	
	INSERT INTO UILM2
		SELECT "MessageID" + :MessageIDDelta,"AccountId","AcctCode","DebitCredi"
	FROM "ILM2"
		WHERE "MessageID" > :MsgFromCopy AND "MessageID" <= :MsgToCopy; 
	
	INSERT INTO UILM3
		SELECT "MessageID" + :MessageIDDelta, "LineID", "POLine", "ItemType", "ItemCode", "LocType", "LocCode",
		"Quantity", "TotalLC", "BaseAbsEnt", "BaseType", "BaseLine", "StgSeqNum", "StgEntry", "StgDesc"
	FROM "ILM3"
		WHERE "MessageID" > :MsgFromCopy AND "MessageID" <= :MsgToCopy; 

	delete from "TmSpTransferRecordsToUILM_TMP";
end;

CREATE PROCEDURE TmSP_UpdateESEnabled (Enabled NVARCHAR(1))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN
		DECLARE OldStatus NVARCHAR(1);
		DECLARE Counter INT;
		SELECT "ESEnabled" INTO OldStatus FROM "CINF";
		IF :OldStatus <> :Enabled THEN
			UPDATE "CINF" SET "ESEnabled"=:Enabled;
			--CACHE_OBJECT_CINF 124
			Counter := 0;
			SELECT count("ID") INTO Counter FROM "CHEN" WHERE "ID"=124 AND "Component"='C';
			IF :Counter = 0 THEN 
				INSERT INTO "CHEN"("Component", "ID", "Counter") VALUES('C', 124, 1);
			ELSE 
				UPDATE "CHEN" SET "Counter"="Counter" + 1  WHERE "ID"=124 AND "Component"='C';
			END IF;
		END IF;
		--CACHE_OBJECT_USR 12
		Counter := 0;
		SELECT count("ID") INTO Counter FROM "CHEN" WHERE "ID"=12 AND "Component"='U';
		IF :Counter = 0 THEN
			INSERT INTO "CHEN"("Component", "ID", "Counter") VALUES('U', 12, 1);
		ELSE 
			UPDATE "CHEN" SET "Counter"="Counter" + 1 WHERE "ID"=12 AND "Component"='U';
		END IF;
END;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

CREATE PROCEDURE TmSp_UpdateNum
(
	in obj_id int,
	in dockey int,
	in docnum int,
	in tempnum int,
	in docsubtype nvarchar(2)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
-- Return values
error  int;				-- Result (0 for no error)
error_message nvarchar (200); 		-- Error string to be displayed
begin

error := 0;
error_message := N'Ok';

if (:obj_id = 17) then	-- Sales Orders
UPDATE "ORDR" SET "DocNum"=:docnum, "Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;

elseif (:obj_id = 22) then	-- Purchase Orders
UPDATE "OPOR" SET "DocNum"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "RDR1" SET "PoTrgNum"=:docnum WHERE "PoTrgEntry" = :dockey and "PcDocType" = :obj_id;
UPDATE "QUT1" SET "PoTrgNum"=:docnum WHERE "PoTrgEntry" = :dockey and "PcDocType" = :obj_id;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;

elseif (:obj_id = 23) then	-- Quotations
UPDATE "OQUT" SET "DocNum"=:docnum WHERE "DocEntry"=:dockey;

elseif (:obj_id = 540000006) then	-- Purchase Quotations
UPDATE "OPQT" SET "DocNum"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "RDR1" SET "PoTrgNum"=:docnum WHERE "PoTrgEntry" = :dockey and "PcDocType" = :obj_id;
UPDATE "QUT1" SET "PoTrgNum"=:docnum WHERE "PoTrgEntry" = :dockey and "PcDocType" = :obj_id;

elseif (:obj_id = 13) then	-- AR Invoices
UPDATE "OINV" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;
UPDATE "ORTI" SET "BaseRef"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OINS" SET "invoiceNum"=:docnum WHERE "invoice" = :dockey;

elseif (:obj_id = 15) then	-- Deliveries
UPDATE "ODLN" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;
UPDATE "OINS" SET "deliveryNo"=:docnum WHERE "delivery" = :dockey;

elseif (:obj_id = 18) then	-- AP Invoices
UPDATE "OPCH" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;
UPDATE "OACQ" SET "BaseRef"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;

elseif (:obj_id = 20) then	-- Goods Receipts
UPDATE "OPDN" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;

elseif (:obj_id = 59) then	-- Goods Receipts
UPDATE "OIGN" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;
UPDATE "ORTL" SET "DocNum"=:docnum WHERE "DocEntry" = :dockey AND "DocType" = :obj_id;

elseif (:obj_id = 60) then	-- Goods Receipts
UPDATE "OIGE" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;
UPDATE "ORTL" SET "DocNum"=:docnum WHERE "DocEntry" = :dockey AND "DocType" = :obj_id;

elseif (:obj_id = 67) then	-- Goods Receipts
UPDATE "OWTR" SET "DocNum"=:docnum,"Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OILM" SET "Ref1"=:docnum, "BASE_REF"=:docnum WHERE "DocEntry" = :dockey AND "TransType" = :obj_id;
UPDATE "OIVL" SET "BASE_REF"=:docnum WHERE "CreatedBy" = :dockey AND "TransType" = :obj_id;
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
--UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OITL" SET "DocNum"=:docnum, "AppDocNum"=:docnum WHERE "ApplyType" = :obj_id AND "ApplyEntry" = :dockey;
UPDATE "NFN4" SET "DocNumber"=:docnum WHERE "ObjectCode" = :obj_id AND "DocEntry" = :dockey;

elseif (:obj_id = 24) then  -- Incoming Payments
UPDATE "ORCT" SET "DocNum"=:docnum, "Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "ORCT" SET "BoeNum"=:docnum WHERE "DocEntry"=:dockey and ("BoeNum" <= 0 OR "BoeNum" IS NULL);
UPDATE "OBOE" SET "BoeNum"=:docnum WHERE "PmntNum"=:dockey and "BoeType" = 'I' and ("BoeNum" <= 0 OR "BoeNum" IS NULL);
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;

elseif (:obj_id = 46) then  -- Outgoing Payments
UPDATE "OVPM" SET "DocNum"=:docnum, "Ref1"=:docnum WHERE "DocEntry"=:dockey;
UPDATE "OVPM" SET "BoeNum"=:docnum WHERE "DocEntry"=:dockey and ("BoeNum" <= 0 OR "BoeNum" IS NULL);
UPDATE "OBOE" SET "BoeNum"=:docnum WHERE "PmntNum"=:dockey and "BoeType" = 'O' and ("BoeNum" <= 0 OR "BoeNum" IS NULL);
--UPDATE "OJDT" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
UPDATE "OCHO" SET "TransRef"=:docnum WHERE "PmntNum"=:dockey;

end if;

-- Handle reference link
if :obj_id = 13 or :obj_id = 15 or :obj_id = 18 or :obj_id = 20 or :obj_id = 59  or :obj_id = 60  or :obj_id = 67 then
	DECLARE status nchar;
	DECLARE rowidx int;
	DECLARE exe_cmd nvarchar(512);
	DECLARE isBasedOnWOR int;
	
	isBasedOnWOR :=0;
	if :obj_id = 59 then
		select count(*) into isBasedOnWOR from IGN1 where "DocEntry" = :dockey and "BaseType" = 202; 
	end if;
	if :obj_id = 60 then
		select count(*) into isBasedOnWOR from IGE1 where "DocEntry" = :dockey and "BaseType" = 202;
	end if;
	
	
	exe_cmd := 'update JDT1 set ';
	select "Status" into status from ORLD where "ObjectCode" = :obj_id and "DocSubType" = :docsubtype;	
	if status = 'C' and isBasedOnWOR = 0 then 
		DECLARE CURSOR C_L FOR select DISTINCT "TargetFld","TargetType" from RLD1 as t0 join ORLD as t1 on t0."AbsEntry" = t1."AbsEntry" where t0."TargetType" = 'L' and t0."SourceFld" = 'DocNum' and t1."ObjectCode" = :obj_id  and t1."DocSubType" = :docsubtype;
		DECLARE CURSOR C_B FOR select DISTINCT "TargetFld","TargetType" from RLD1 as t0 join ORLD as t1 on t0."AbsEntry" = t1."AbsEntry" where t0."TargetType" = 'B' and t0."SourceFld" = 'DocNum' and t1."ObjectCode" = :obj_id and t1."DocSubType" = :docsubtype;
		
		-- Always Update the BaseRef
		UPDATE "JDT1" SET "BaseRef"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
		
		-- Note: because currently HANA doesn't support user defined function, I have to repeat some codes in the follow section. I don't want to encapsulate such small section into a SP either. 
		-- update the account line
		rowidx := 0;
		FOR R as C_L DO 
			if rowidx > 0 then 
				exe_cmd := exe_cmd || ',';
			end if;
			exe_cmd := exe_cmd || '"' || R."TargetFld" || '"' || '=' || :docnum;
			rowidx := rowidx + 1;
		END FOR;
		
		if rowidx > 0 then 
			exe_cmd := exe_cmd || ' where "CreatedBy"=' || dockey || ' and "TransType"=' || obj_id || ' and "Account" = "ShortName"';
			EXECUTE IMMEDIATE exe_cmd;
		end if;
		
		-- update the BP line
		exe_cmd := 'update JDT1 set ';
		rowidx := 0;
		FOR R as C_B DO 
			if rowidx > 0 then 
				exe_cmd := exe_cmd || ',';
			end if;
			exe_cmd := exe_cmd || '"' || R."TargetFld" || '"' || '=' || :docnum;
			rowidx := rowidx + 1;
		END FOR;
		if rowidx > 0 then
			exe_cmd := exe_cmd || ' where "CreatedBy"=' || :dockey || ' and "TransType"=' || :obj_id || ' and "Account" <> "ShortName"';
			EXECUTE IMMEDIATE exe_cmd;
		end if;                                                                          
	else
		UPDATE "JDT1" SET "BaseRef"=:docnum, "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
	end if;
end if; 

if :obj_id = 24 or :obj_id = 46 then
	UPDATE "JDT1" SET "BaseRef"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id;
	UPDATE "JDT1" SET "Ref1"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id and "Ref1"=TO_NVARCHAR(:tempnum);
	UPDATE "JDT1" SET "Ref3Line"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id and "Ref3Line"=TO_NVARCHAR(:tempnum);
	UPDATE "JDT1" SET "DocNum"=:docnum WHERE "CreatedBy"=:dockey AND "TransType"=:obj_id and "DocArr"=15;
end if;

-- Select the return values
select :error, :error_message FROM DUMMY;

end;

-- B1 DEPENDS: AFTER:PT:PROCESS_END

