create procedure TmSp_ZZZ_VIEW_B1_OinmWithBinTransfer
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
cnt int;
sqlStr nvarchar(50000);
BEGIN
	select count (*) into cnt from "PUBLIC"."VIEWS" where "VIEW_NAME" = 'B1_OinmWithBinTransfer' AND "SCHEMA_NAME" = CURRENT_SCHEMA;
	if :cnt > 0 then
		sqlStr := ('drop view "B1_OinmWithBinTransfer"');
		exec (:sqlStr);
	end if;
	
	sqlStr := 'CREATE VIEW "B1_OinmWithBinTransfer" ( "TransNum",
	 "TransType",
	 "CreatedBy",
