				left("OACT"."AcctName",60) AS "TXTLG"
				FROM "' || CURRENT_SCHEMA || '"."OACT"  WHERE ("OACT"."Postable" = ''Y'')';
	
	--ins_msg_proc (:sqlStr);
	exec (:sqlStr);
END;

