CREATE PROCEDURE _TmSp_CreateOILMBuildIndexes
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
	sqlStr nvarchar(1000);
BEGIN
	sqlStr :='CREATE INDEX "OILM_CARD" ON OILM("BPCardCode" ASC)';
	EXEC sqlStr;
	
	sqlStr :='CREATE INDEX "OILM_DocLine" ON OILM("TransType" ASC,"DocEntry" ASC,"DocLineNum" ASC,"SubLineNum" ASC)';
	EXEC sqlStr;
	sqlStr :='CREATE INDEX "OILM_APPOBJ" ON OILM("ApplObj" ASC,"AppObjAbs" ASC,"AppObjType" ASC,"AppObjLine" ASC)';
	EXEC sqlStr;
	
END;

CREATE PROCEDURE _TmSp_CreateVBINView
language sqlscript
SQL SECURITY INVOKER
AS
  sql1    nvarchar(4999);
  rowNum  int;
BEGIN
	  SELECT COUNT(*) INTO rowNum FROM "PUBLIC"."VIEWS" WHERE "VIEW_NAME" = 'VBIN' AND "SCHEMA_NAME" = current_schema;
	  IF :rowNum > 0
	  THEN
	    sql1 := 'DROP VIEW  "'||current_schema||'"."VBIN"';
	    EXEC(:sql1);
	  END IF;
	  
	  SELECT COUNT(*) INTO rowNum FROM "PUBLIC"."VIEWS" WHERE "VIEW_NAME" = 'VBIN_Qty' AND "SCHEMA_NAME" = current_schema;
	  IF :rowNum > 0
	  THEN
	    sql1 := 'DROP VIEW  "'||current_schema||'"."VBIN_Qty"';
	    EXEC(:sql1);
	  END IF;
	
	sql1 := 'create view  "'||current_schema||'"."VBIN_Qty" '||
		'as  '||
		'SELECT T0."BinAbs", SUM(T0."OnHandQty") AS "ItemQty", COUNT(DISTINCT T0."ItemCode") AS "ItemsNum", 
		COUNT(DISTINCT T0."ItemCode") AS "SnBNum", COUNT(DISTINCT T0."ItemCode") AS "ItemWeight" 
		FROM "OIBQ" T0 
		WHERE T0."OnHandQty" <> (0 ) 
		GROUP BY T0."BinAbs" 
		';
	EXEC (:sql1);
	sql1 := '
		create view  "'||current_schema||'"."VBIN" '||
		'as  '||
		'SELECT T0.*,T1.*
		FROM "OBIN" T0 
		LEFT OUTER JOIN "VBIN_Qty" T1 ON T1."BinAbs" = T0."AbsEntry"
	'
	;
	EXEC (:sql1);
END

-- B1 DEPENDS: BEFORE:PT:PROCESS_START

CREATE PROCEDURE _TmSp_CreateViewB1_EDFLatestLogsView
language sqlscript
SQL SECURITY INVOKER
AS
  sql1    nvarchar(4999);
  rowNum  int;
BEGIN
  SELECT COUNT(*) INTO rowNum FROM "PUBLIC"."VIEWS" WHERE "VIEW_NAME" = 'B1_EDFLatestLogsView' AND "SCHEMA_NAME" = current_schema;
  IF :rowNum > 0
  THEN
    sql1 := 'DROP VIEW  "'||current_schema||'"."B1_EDFLatestLogsView"';
    EXEC(:sql1);
  END IF;

	sql1 := '
	CREATE VIEW "B1_EDFLatestLogsView"
	AS
	SELECT *
FROM (SELECT
	 *,
	 CAST(RANK() OVER (PARTITION BY "AbsEntry",
	 "LogType" 
			ORDER BY "LogOpDate" DESC,
	 "LogOpTS" DESC,
	 "LogNum" DESC) AS Integer) AS "RankByDT" 
	FROM "ECM3" ) tblRank 
WHERE tblRank."RankByDT" = 1 
ORDER BY "AbsEntry",
	 "LogType" WITH READ ONLY
';

	EXEC(:sql1);
END

