CREATE PROCEDURE _TmSp_CreateViewIBT1
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
AS
sql1 varchar(4999);
rownum int;
DBName varchar(255);
BEGIN


	SELECT COUNT(*) into rownum  FROM "PUBLIC"."VIEWS" 
	where "VIEW_NAME" = 'IBT1_LINK' AND "SCHEMA_NAME" = CURRENT_SCHEMA;
	
	IF :rownum > 0 	then
		sql1 := 'DROP VIEW ' || '"'|| CURRENT_SCHEMA || '"' ||'.IBT1_LINK';
		exec (:sql1);
     end if;

	sql1 := 'create view ' || '"'|| CURRENT_SCHEMA || '"' || '.IBT1_LINK '||
		' as  ' ||

		' SELECT	MIN(b."LogEntry")		as "LogEntry", '||
					'MIN(b."ItemCode")		as "ItemCode", '||
					'MIN(c."DistNumber")	as "BatchNum", '||
					'MIN(b."LocCode")		as "WhsCode", '||
					'MIN(b."ItemName")		as "ItemName", '||
					'MIN(b."ApplyType")	as "BaseType",    ' ||  
					'MIN(b."ApplyEntry")	as "BaseEntry", '||
					'MIN(b."AppDocNum")	as "BaseNum", '||
					'MIN(b."ApplyLine")	as "BaseLinNum", '||
					'MIN(b."DocDate")		as "DocDate", '||
					'(	  '						 ||
					'	CASE WHEN ABS(SUM(a."Quantity")) = 0 THEN SUM(a."AllocQty") '||
					'	ELSE ABS(SUM(a."Quantity")) END '||
					')					as "Quantity", '||
					'MIN(b."CardCode")		as "CardCode", '||
					'MIN(b."CardName")		as "CardName", '||
					'( '||
					'	CASE WHEN  SUM(a."Quantity") > 0 THEN 0 '||
					'	WHEN SUM(a."Quantity") < 0 THEN 1 '||
					'	ELSE 2 END '||
					')					as "Direction", '||
					'MIN(b."CreateDate")	as "CreateDate", '||
					'MIN(b."BaseType")		as "BsDocType", '||
					'MIN(b."BaseEntry")	as "BsDocEntry", '||
					'MIN(b."BaseLine")		as "BsDocLine", '||
					' ''N''				as "DataSource", '||
					'NULL				as "UserSign" '||
		'FROM		ITL1 a '||
		'INNER JOIN	OITL b ON a."LogEntry" = b."LogEntry" '||
		'INNER JOIN	OBTN c ON a."ItemCode" = c."ItemCode" and a."SysNumber" = c."SysNumber" '||
		'GROUP BY	b."ItemCode", a."SysNumber", b."ApplyType", b."ApplyEntry", b."ApplyLine", b."LocCode", b."StockEff" '||
		'having		(SUM(b."DocQty") <> 0) '		||
		'OR			(SUM(b."DefinedQty") <> 0)  '	||
		'OR			(SUM(b."DocQty") = 0 and b."StockEff" = 2  '||
					 'and min(b."BaseType") <> 17 and min(b."BaseType") <> 13 ) ';
    
	exec (:sql1);

	SELECT COUNT(*) into rownum  FROM "PUBLIC"."VIEWS" where "VIEW_NAME" = 'IBT1' AND "SCHEMA_NAME" = CURRENT_SCHEMA;
	IF :rownum > 0 	then
		sql1 := 'DROP VIEW '|| '"'|| CURRENT_SCHEMA || '"' ||'.IBT1';
		exec (:sql1);
     end if;
     
     sql1 := 'create view ' || '"'|| CURRENT_SCHEMA || '"' ||'.IBT1 '||
		'as '||

		'SELECT  "ItemCode" '||
			 ' ,"BatchNum" '||
			 ' ,"WhsCode" '||
			 ' ,(	'||
			'		row_number() over (partition by "ItemCode", "BatchNum", "WhsCode" order by "LogEntry") - 1'||
			 ' ) as "LineNum" '||
			 ' ,"ItemName" '||
			 ' ,"BaseType" '||
			  ',"BaseEntry" '||
			  ',"BaseNum" '||
			 ' ,"BaseLinNum" '||
			 ' ,"DocDate" '||
			 ' ,"Quantity" '||
			  ',"CardCode" '||
			 ' ,"CardName" '||
			 ' ,"Direction" '||
			 ' ,"CreateDate" '||
			 ' ,"BsDocType" '||
			 ' ,"BsDocEntry" '||
			 ' ,"BsDocLine" '||
			 ' ,"DataSource" '||
			 ' ,"UserSign" ' ||     
		'from '|| '"'|| CURRENT_SCHEMA || '"' ||'.IBT1_LINK a ';
		exec (:sql1);
     
END;

-- B1 DEPENDS: BEFORE:PT:CREATE_TABLES_TO_VIEWS

CREATE PROCEDURE _TmSp_CreateViewOIBT
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
sql1 nclob;
	extFields nclob;
	orgUDFField varchar(20);
	countUDFField int;
	curFieldID int;
	findInBTN int;
	tableID varchar(10);
	rownum int;
BEGIN

	SELECT COUNT(*) into rownum  FROM "PUBLIC"."VIEWS" where "VIEW_NAME" = 'ixvITL_Min' AND "SCHEMA_NAME" = CURRENT_SCHEMA;

	-- DROP UNUSED VIEW ixvITL_Min
	IF  rownum > 0 then
		exec('DROP VIEW ' || '"'|| CURRENT_SCHEMA || '"' || '."ixvITL_Min"');
	end if;

	tableID := 'OBTN';
	select Min("FieldID") , count(1) into curFieldID,countUDFField FROM CUFD WHERE "TableID" = :tableID;

	if :countUDFField = 0 
	then
		tableID := 'OIBT';
		select Min("FieldID"), count(1) into curFieldID,countUDFField FROM CUFD WHERE "TableID" = :tableID;
	end if;

	extFields := '';
	curFieldID := :curFieldID - 1;

	while :countUDFField > 0
		do
		select TOP 1 "AliasID" , "FieldID" into orgUDFField, curFieldID FROM CUFD WHERE "TableID" = :tableID AND "FieldID" > :curFieldID  ORDER BY "FieldID";

		SELECT count(1) into findInBTN FROM CUFD WHERE "TableID" = 'OBTN' and "AliasID" = :orgUDFField;
		
		if :findInBTN > 0
			then 
			extFields := :extFields || ', OBTN."U_' || :orgUDFField || '" AS "U_' || :orgUDFField || '" ';
			END if;
		countUDFField := :countUDFField - 1;
		END while;


	-- create view OIBT
	SELECT COUNT(*) into rownum  FROM "PUBLIC"."VIEWS" where "VIEW_NAME" = 'OIBT' AND "SCHEMA_NAME" = CURRENT_SCHEMA;

	IF  rownum > 0 then
		exec('DROP VIEW ' || '"'|| CURRENT_SCHEMA || '"' || '.OIBT');
	end if;


sql1 := 'CREATE VIEW  OIBT '||
		'AS '||

		'SELECT '||
					'OBTN."ItemCode"	AS "ItemCode", '||
					'OBTN."DistNumber"	AS "BatchNum", '||
					'OBTQ."WhsCode"		AS "WhsCode", '||
					'OITL."ItemName"	AS "ItemName", '||
					'OBTN."MnfSerial"	AS "SuppSerial", '||
					'OBTN."LotNumber"	AS "IntrSerial", '||
					'OBTN."ExpDate"		AS "ExpDate", '||
					'OBTN."MnfDate"		AS "PrdDate", '||
					'OBTN."InDate"		AS "InDate", '||
					'OBTW."Location"	AS "Located", '||
					'OBTN."Notes"		AS "Notes", '||
					'OBTQ."Quantity"	AS "Quantity", '||
					'OITL."DocType"		AS "BaseType", '||
					'OITL."DocEntry"	AS "BaseEntry", '||
					'OITL."DocNum"		AS "BaseNum", '||
					'OITL."DocLine"		AS "BaseLinNum", '||
					'( '||
						'CASE WHEN OITL."DocType" = 59 OR OITL."DocType" = 60 '||
						'		OR OITL."DocType" = 10000071 OR OITL."DocType" = 310000001 '||
						'		OR OITL."DocType" = 58 THEN NULL '||
						'ELSE OITL."CardCode" END '||
					')			AS "CardCode", '||
					'( '||
					'	CASE WHEN OITL."DocType" = 59 OR OITL."DocType" = 60 '||
					'			OR OITL."DocType" = 10000071 OR OITL."DocType" = 310000001 '||
					'			OR OITL."DocType" = 58 THEN NULL '||
					'	ELSE OITL."CardName" END '||
					')			AS "CardName", '||
					'OBTN."CreateDate"	AS "CreateDate", '||
					'OBTN."Status"		AS "Status", '||
					'0			AS "Direction", '||
					'OBTQ."CommitQty"	AS "IsCommited", '||
					'0			AS "OnOrder", '||
					'0			AS "Consig", '||
					'OBTN."DataSource"	AS "DataSource", '||
					'OBTN."UserSign"	AS "UserSign", '||
					'OBTN."Transfered"	AS "Transfered", '||
					'OBTN."Instance"	AS "Instance", '||
                    			'OBTN."SysNumber"	AS "SysNumber", '||
					'OBTN."LogInstanc"	AS "LogInstanc", '||
					'OBTN."UserSign2"	AS "UserSign2", '||
					'OBTN."UpdateDate"	AS "UpdateDate" '||
					:extFields ||	
		'FROM		OBTN '||
		'LEFT JOIN	OBTQ OBTQ ON OBTN."ItemCode" = OBTQ."ItemCode" AND OBTN."SysNumber" = OBTQ."SysNumber" ' ||
		'INNER JOIN	OBTW OBTW ON OBTN."ItemCode" = OBTW."ItemCode" AND OBTN."SysNumber" = OBTW."SysNumber" AND OBTQ."WhsCode" = OBTW."WhsCode" '||
		'INNER JOIN OITL ON OITL."LogEntry" IN ( '||
				'SELECT MIN(T1."LogEntry") AS "LogEntry" '||
				'FROM OITL T1 '||
				'INNER JOIN ITL1 T2 ON T1."LogEntry" = T2."LogEntry" AND T1."ItemCode" = T2."ItemCode" AND T1."ItemCode" = OITL."ItemCode" AND T2."SysNumber" = OBTN."SysNumber" '||
				'GROUP BY T1."ItemCode", T2."SysNumber" ) '||
			'AND OITL."ItemCode" = OBTN."ItemCode"';

		exec (:sql1);

END

-- B1 DEPENDS: BEFORE:PT:CREATE_TABLES_TO_VIEWS

CREATE PROCEDURE _TmSp_CreateViewOSRD
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER

AS

sqlString1 nvarchar(4000);
sqlString2 nvarchar(4000);
sqlString3 nvarchar(4000);
sqlStrDrop nvarchar(1000);
exists1 int;
DBName nvarchar(255);      
      
BEGIN
	exists1 := 0;
	sqlStrDrop := 'drop view ' || '"'|| CURRENT_SCHEMA || '"' ||'.OSRD';
	-- create view OSRD
	select count(*) into exists1
	from "PUBLIC".objects
	where object_oid = (select VIEW_OID from "PUBLIC"."VIEWS" where VIEW_NAME = 'OSRD' AND "SCHEMA_NAME" = CURRENT_SCHEMA)
		and object_type = 'VIEW';
	
	if (:exists1 <> 0)then
		exec(:sqlStrDrop);
	end if;
	
	sqlString1 := ' CREATE VIEW ' || '"'|| CURRENT_SCHEMA || '"' ||'. OSRD AS ' 
				||  'SELECT '   
				||  'MIN(a."ItemCode")	as "ItemCode",'
				||	'MIN(a."ApplyType")	as "DocType",'
				||	'MIN(a."ApplyEntry")	as "DocEntry",'
				||	'MIN(a."AppDocNum")	as "DocNum",'
				||	'MIN(a."ApplyLine")	as "DocLineNum",'
				||	'ABS(SUM(a."DocQty") - SUM(IFNULL (d."DocQty", 0)))	as "DocQuty",'
				||	'ABS(SUM(a."DocQty") - SUM(IFNULL (d."DocQty", 0))) - MIN(b."DefinedQty") as "DocOpenQty",'
				||	'MIN(a."DocDate")		as "DocDate",'
				||	'(CASE WHEN ABS(SUM(a."DocQty") - SUM(IFNULL (d."DocQty", 0))) > MIN(b."DefinedQty") THEN ''0'''
				||	' ELSE ''1'' END)		as "Status",'
				||	'(CASE WHEN MIN(a."ManagedBy") = 10000044 THEN 106'
				||	' ELSE 94 END)			as "SrdType",'
				||	'MIN(a."ItemName")	as "ItemName",'
				||	'MIN(a."LocCode")		as "WhsCode",'
				||	'MIN(a."CardCode")	as "CardCode",'
				||	'MIN(a."CardName")		as "CardName",'
				||	'MIN(c."ManOutOnly")	as "ManOutOnly",'
				||	'(CASE WHEN (SUM(a."DocQty") > 0 AND MIN(a."StockEff") = 1)'
				||	' OR (SUM(a."DocQty") < 0 AND MIN(a."StockEff") = 2)  THEN ''0'''
				||	' ELSE ''1'' END)		as "Direction",'
				||	'NULL				as "CreateNew",'
				||	'''N''				as "DataSource",'
				||	'NULL				as "UserSign"'
				||  ' FROM  ' || '"'|| CURRENT_SCHEMA || '"' ||'.OITL  a';
				
	sqlString2 := '	LEFT  JOIN	( '
				||  'select '	
				||  '(CASE when IFNULL(ABS(SUM(bb."Quantity")), 0) > 0 THEN'
				||  '	IFNULL(ABS(SUM(bb."Quantity")), 0)'
				||  '	else IFNULL(ABS(SUM(bb."AllocQty")), 0) END'
				||  '	) 					as "DefinedQty",'
				||  'MIN (aa."LogEntry") as "LogEntry"'
				||  ' from  ' || '"'|| CURRENT_SCHEMA || '"' ||'.OITL aa'
				||  ' left join	' || '"'|| CURRENT_SCHEMA || '"' ||'.ITL1 bb on aa."LogEntry" = bb."LogEntry"'
				||  ' group by	aa."ItemCode", aa."ApplyType", aa."ApplyEntry", aa."ApplyLine", aa."LocCode"'
				||  ' ) b on b."LogEntry" = a."LogEntry" ';
				
	sqlString3 := ' INNER JOIN	' || '"'|| CURRENT_SCHEMA || '"' ||'.OITM c on c."ItemCode" = a."ItemCode"'
				||	' LEFT OUTER JOIN ' || '"'|| CURRENT_SCHEMA || '"'
				||	'.OITL d on (d."LogEntry" = a."LogEntry" and d."StockQty" = 0 and d."DefinedQty" > 0 and d."StockEff" = 1) '
				||	' or (d."LogEntry" = a."LogEntry" and d."StockEff" = 2 and d."ApplyType" in (13,14,15,60,59,67))'
				||	'WHERE d."ApplyType" <> 13 or d."LogEntry" is null '
				||	'or  d."ApplyType" = 13 and exists (select 1 from "'|| CURRENT_SCHEMA || '".OITL U0 WHERE U0."TransId" = a."TransId" AND U0."StockEff" <> 2) '
				||  ' GROUP BY	a."ItemCode", a."ApplyType", a."ApplyEntry", a."ApplyLine", a."LocCode"'
				||  ' HAVING (MIN(a."ApplyType") <> 67 and SUM(a."DocQty") <> 0)'
				||  '	OR	 (MIN(a."ApplyType") = 67 and SUM(a."DocQty") < 0)';
				
	exec (:sqlString1 || :sqlString2 || :sqlString3);
END;

-- B1 DEPENDS: BEFORE:PT:CREATE_TABLES_TO_VIEWS

CREATE PROCEDURE _TmSp_CreateViewOSRI
language sqlscript
SQL SECURITY INVOKER
as 
	sql1 nclob;
	extFields nclob;
	finalExtFields nclob;
	orgUDFField varchar(20);
	newUDFField varchar(20);
	countUDFField int;
	curFieldID int;
	dupFieldInIBT int;
	findInSRN int;
	sufixString varchar (20);
	sufixIndex int;	
	ctmp int;
	tableID varchar(10);
-----------------store local result of STR----------------------	
	chtmp1 varchar(1);
	chtmp2 varchar(1);
	chtmp3 varchar(1);
-----------------store local result of STR----------------------	
	DBName nvarchar(255);
	
begin
		select count(*) into ctmp 
		from  "PUBLIC".views 
		WHERE view_name = 'ixvITL_Min' AND "SCHEMA_NAME" = CURRENT_SCHEMA;

		
		IF  ctmp > 0 then	
			exec('drop view ' || '"' || CURRENT_SCHEMA || '"' || '."ixvITL_Min"');
		end if;
		sql1 := 'CREATE VIEW ' || '"' || CURRENT_SCHEMA || '"' || '."ixvITL_Min" AS SELECT MIN("LogEntry") AS "LogEntry", "ItemCode", "SysNumber" FROM ITL1 GROUP BY "ItemCode", "SysNumber" ';
		
		exec (:sql1);
		
		-- CREATE VIEW ixvITL_LastWhs
		select count(*) into ctmp from "PUBLIC".views where view_name = 'ixvITL_LastWhs' AND "SCHEMA_NAME" = CURRENT_SCHEMA;
	
	IF  ctmp > 0 then
		exec('DROP VIEW ' || '"' || CURRENT_SCHEMA || '"' || '."ixvITL_LastWhs"');
    end if;
	
	sql1 := 'CREATE VIEW ' || '"' || CURRENT_SCHEMA || '"' || '."ixvITL_LastWhs"	AS	SELECT		T0."ItemCode", lastLogEntry."SysNumber", T0."LocCode" AS "WhsCode" FROM		' || '"' || CURRENT_SCHEMA || '"' || '.OITL  T0 INNER JOIN	(SELECT	MAX("LogEntry") AS "LogEntry", "ItemCode", "SysNumber" FROM ' || '"' || CURRENT_SCHEMA || '"' || '.ITL1 GROUP BY "ItemCode", "SysNumber") AS lastLogEntry ON lastLogEntry."LogEntry" = T0."LogEntry" AND T0."ItemCode" = lastLogEntry."ItemCode" ';
	exec (:sql1);
	
	-- prepare UDF
	tableID := 'OSRN';
	select  Min("FieldID") into curFieldID FROM CUFD WHERE "TableID" = :tableID;
	select  count(1) into countUDFField FROM CUFD WHERE "TableID" = :tableID;
	
	if :countUDFField = 0 then
		tableID := 'OSRI';
		select Min("FieldID") into curFieldID FROM CUFD WHERE "TableID" = :tableID;
		select  count(1) into countUDFField  FROM CUFD WHERE "TableID" = :tableID;
	end if;
	
	extFields := '';
	finalExtFields := '';
	curFieldID := :curFieldID - 1;
	
		
	while :countUDFField > 0 do
		--get old column name
			select TOP 1 "AliasID" into orgUDFField FROM CUFD WHERE "TableID" = :tableID AND "FieldID" > :curFieldID ORDER BY "FieldID";
			select TOP 1 "FieldID" into curFieldID  FROM CUFD WHERE "TableID" = :tableID AND "FieldID" > :curFieldID ORDER BY "FieldID";
			newUDFField := :orgUDFField;
		
			if :tableID = 'OSRI' then
				SELECT count(1) into dupFieldInIBT FROM CUFD WHERE "TableID" = 'OIBT' and "AliasID" = :newUDFField;
				sufixIndex := 1;
				--get new column name
				while :dupFieldInIBT > 0 do
					sufixString := '_' || LTRIM(:sufixIndex);
					newUDFField := RTRIM(SUBSTRING(:orgUDFField, 1, (18 - LENGTH(:sufixString)))) || :sufixString;			
					SELECT count(1) into dupFieldInIBT FROM CUFD WHERE "TableID" = 'OIBT' and "AliasID" = :newUDFField;
					sufixIndex := :sufixIndex + 1;
				end while;
				--check new column name
				SELECT count(1) into findInSRN FROM CUFD WHERE "TableID" = 'OSRN' and "AliasID" = :newUDFField;				
			else 
				findInSRN := 1;
			end if;
		--add column into view
			if :findInSRN > 0
				then
					extFields := :extFields || ', T0."U_' || :newUDFField || '" AS "U_' || :orgUDFField || '" ';
					finalExtFields := :finalExtFields || ',"U_' || :orgUDFField || '" ';
			END if;
			countUDFField := :countUDFField - 1;					
	end while;
		-- create view OSRI
	select count(*) into ctmp FROM "PUBLIC".views WHERE view_name = 'OSRI' AND "SCHEMA_NAME" = CURRENT_SCHEMA;
	IF  ctmp > 0 then
		exec('DROP VIEW ' || '"' || CURRENT_SCHEMA || '"' || '. OSRI');
	end if;
	
	sql1 := 'CREATE VIEW ' || '"' || CURRENT_SCHEMA || '"' || '."OSRI" ( "ItemCode",'||
	 '"SysSerial","SuppSerial","IntrSerial","BatchId","ExpDate",'||
	 '"PrdDate","InDate","GrntStart","GrntExp","WhsCode","Located",'||
	 '"Notes","Quantity","BaseType","BaseEntry","BaseNum","BaseLinNum",'||
	 '"CreateDate","CardCode","CardName","ItemName","Status","Direction",'||
	 '"DataSource","UserSign","Transfered","Instance" ' || :finalExtFields ||') AS ('||
		 'select t11.* from ('||
			 'SELECT '||
			     'T0."ItemCode" AS "ItemCode",'||
			     'T0."SysNumber" AS "SysSerial",'||
			     'T0."MnfSerial" AS "SuppSerial",'||
			     'T0."DistNumber" AS "IntrSerial",'||
			     'T0."LotNumber" AS "BatchId",'||
			     'T0."ExpDate" AS "ExpDate",'||
			     'T0."MnfDate" AS "PrdDate",'||
			     'T0."InDate" AS "InDate",'||
			     'T0."GrntStart" AS "GrntStart",'||
			     'T0."GrntExp" AS "GrntExp",'||
			     'OSRQ."WhsCode" AS "WhsCode",'||
			     'T0."Location" AS "Located",'||
			     'T0."Notes" AS "Notes",'||
			     'T2."DocQty" AS "Quantity",'||
			     'T2."DocType" AS "BaseType",'||
			     'T2."DocEntry" AS "BaseEntry",'||
			     'T2."DocNum" AS "BaseNum",'||
			     'T2."DocLine" AS "BaseLinNum",'||
			     'T0."CreateDate" AS "CreateDate",'||
			     '( CASE when T2."DocType" = 59 or T2."DocType" = 60 or T2."DocType" = 10000071 or T2."DocType" = 310000001 or T2."DocType" = 58 then NULL ELSE T2."CardCode" END ) AS "CardCode",'||
			     '( CASE when T2."DocType" = 59 or T2."DocType" = 60 or T2."DocType" = 10000071 or T2."DocType" = 310000001 or T2."DocType" = 58 then NULL ELSE T2."CardName" END ) AS "CardName",'||
			     'T2."ItemName" AS "ItemName",'||
			    '(case when OSRQ."Quantity" is null then 1 when OSRQ."Quantity" = 0 then 1 when OSRQ."Quantity" = 1 then 0 else null end) AS "Status",'||
			     '0 AS "Direction",'||
			     'T0."DataSource" AS "DataSource",'||
			     'T0."UserSign" AS "UserSign",'||
			     'T0."Transfered" AS "Transfered",'||
			     'T0."Instance" AS "Instance" '||
			     :extFields||
			'FROM '|| '"' || CURRENT_SCHEMA || '"' || '.OSRN T0  '||
			    'LEFT JOIN ' || '"' || CURRENT_SCHEMA || '"' || '.OSRQ OSRQ  '||
			        'ON T0."ItemCode" = OSRQ."ItemCode" AND T0."SysNumber" = OSRQ."SysNumber"  '||
			    'INNER JOIN ' || '"' || CURRENT_SCHEMA || '"' || '."ixvITL_Min" T1  '||
			        'ON T0."ItemCode" = T1."ItemCode" AND T0."SysNumber" = T1."SysNumber"  '||
			    'INNER JOIN ' || '"' || CURRENT_SCHEMA || '"' || '.OITL T2  '||
			        'ON T2."LogEntry" = T1."LogEntry" AND T2."ItemCode" = T1."ItemCode"  '||
			'WHERE (OSRQ."Quantity" is null OR OSRQ."Quantity" = 0 or OSRQ."Quantity" = 1)  '||
			') t11  '||
			   'INNER JOIN ' || '"' || CURRENT_SCHEMA || '"' || '."ixvITL_LastWhs" T3  '||
			        'ON T11."ItemCode" = T3."ItemCode" AND T11."SysSerial" = T3."SysNumber"   AND t11."WhsCode" = T3."WhsCode"  '||
		') 	'||
	 'WITH READ ONLY';
	 exec(:sql1);
end;

