			SELECT COLUMN_NAME into FieldID FROM "PUBLIC"."TABLE_COLUMNS" 
			WHERE   TABLE_NAME = 'JDT1'		
				AND POSITION = TO_BIGINT(FieldID) - :ui25 + :db25 + 1
				AND SCHEMA_NAME = CURRENT_SCHEMA;
		--------26-Profit Centers------------------------------------------
		ELSEIF TO_BIGINT(FieldID) >= :ui26 AND 
		:ByField = 'Y' AND
