				AND POSITION = TO_BIGINT(FieldID) - :ui26 + :db26 + 1
				AND SCHEMA_NAME = CURRENT_SCHEMA;
		--------27-Distribution Rules-------------------------------------
		ELSEIF TO_BIGINT(FieldID) >= :ui27 AND 
		:ByField = 'Y' AND
		(:FormID = '810') THEN
			SELECT COLUMN_NAME into FieldID FROM "PUBLIC"."TABLE_COLUMNS" 
			WHERE   TABLE_NAME = 'OPRC'		
				AND POSITION = TO_BIGINT(FieldID) - :ui27 + :db27 + 1
				AND SCHEMA_NAME = CURRENT_SCHEMA;
		--------28-Budget--------------------------------------------------
		ELSEIF TO_BIGINT(FieldID) >= :ui28 AND 
		:ByField = 'N' AND
		(:FormID = '452') THEN
			SELECT COLUMN_NAME into FieldID FROM "PUBLIC"."TABLE_COLUMNS" 
			WHERE   TABLE_NAME = 'OBGS'		
				AND POSITION = TO_BIGINT(FieldID) - :ui28 + :db28 + 1
				AND SCHEMA_NAME = CURRENT_SCHEMA;
		--------29-Projects-----------------------------------------------
		ELSEIF TO_BIGINT(FieldID) >= :ui29 AND 
		:ByField = 'N' AND
		(:FormID = '711') THEN
			SELECT COLUMN_NAME into FieldID FROM "PUBLIC"."TABLE_COLUMNS" 
			WHERE   TABLE_NAME = 'OPRJ'		
				AND POSITION = TO_BIGINT(FieldID) - :ui29 + :db29 + 1
				AND SCHEMA_NAME = CURRENT_SCHEMA;
		-----------------------------------------------------------------
		END IF;
		
		Fetch Currs Into FieldID,ColId,ByField,FormID,ItemId;
		
		if NOT Currs::NOTFOUND then
			hasNext := -1;
		end if;
		
		Update CSHS Set "FieldID" = :FieldID;
	end while;

	Close Currs;

end;

CREATE PROCEDURE _TmSp_InsertOCUL( IN StartRef int,
	 IN EventType int,
	 IN DateTime nvarchar(20),
	 OUT ID int) 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS 
BEGIN 
SELECT
	 OCUL_S.NEXTVAL 
INTO ID 
FROM DUMMY;
INSERT INTO OCUL VALUES (:ID,
	 :StartRef,
	 :EventType,
	 :DateTime);

END

-- B1 DEPENDS: BEFORE:PT:PROCESS_START AFTER:SP:_TmSp_ValidateSpParam
--
-- This is pre-upgrade proc, which must be executed before CRD object upgrade.
-- It fixes duplicate keys in ACRD table - because of new unique index (DocEntry, LogInstanc).

CREATE PROCEDURE _TmSp_MakeUnique_ACRD_DocEntryLogInstance(IN tableName nvarchar(100))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
  textSQL    nvarchar(2000);
  existsSeq  int;
BEGIN
--For HANA security issue call procedure "_TmSp_ValidateSpParam"
  call _TmSp_ValidateSpParam(:tableName);      
  
  SELECT Count(1) INTO existsSeq
  FROM "PUBLIC"."SEQUENCES"
  WHERE "SEQUENCE_NAME" = 'ACRD_MAXLOGINSTANCE'
    AND "SCHEMA_NAME" = CURRENT_SCHEMA;

  IF :existsSeq <> 0 THEN
    Exec('DROP SEQUENCE ACRD_MaxLogInstance');
  END IF;

  Exec('CREATE SEQUENCE ACRD_MaxLogInstance');

  textSQL := '';

  textSQL := :textSQL || 'UPDATE "%TABLE%" ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || 'SET "LogInstanc" = (SELECT MAX("LogInstanc") FROM "%TABLE%") + ACRD_MaxLogInstance.NextVal ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || 'WHERE ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '  ("CardCode", "LogInstanc") ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '  IN ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '  (SELECT tblMain2."CardCode", tblMain2."LogInstanc" ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '   FROM ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '     "%TABLE%" tblMain2 ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '     INNER JOIN (SELECT "DocEntry", "LogInstanc" AS "LogInstance" ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '                 FROM "%TABLE%" ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '                 GROUP BY "DocEntry", "LogInstanc" ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '                 HAVING COUNT(*) > 1 ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '                ) tblMulti ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '       ON tblMulti."DocEntry"    = tblMain2."DocEntry" AND ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '          tblMulti."LogInstance" = tblMain2."LogInstanc" ' || CHAR(13) || CHAR(10);
  textSQL := :textSQL || '  )';

  textSQL := REPLACE(:textSQL, '%TABLE%', :tableName);
  Exec(:textSQL);

  Exec('DROP SEQUENCE ACRD_MaxLogInstance');
END;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START

CREATE PROCEDURE _TmSp_MthDate_Update_JDT1
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS

exists1 int;
begin
-----------------------------------------------------------
 select count(*) into exists1 from "PUBLIC".objects where object_name = 'JDT1_TEMP' and schema_name = current_schema;
 if :exists1 <> 0 then
	drop table JDT1_TEMP;
 end if;

EXEC('create  table JDT1_TEMP(DocEntry int,'
||									'InvType nvarchar(20),'
||									'CardCode nvarchar(15),'
||									'DocDate timestamp) ');
--------------------------Receipt-----------------------------
EXEC('INSERT INTO JDT1_TEMP '
|| 'SELECT RCT2."DocEntry",RCT2."InvType",ORCT."CardCode",ORCT."DocDate" '
|| 'FROM RCT2 INNER JOIN ORCT ON RCT2."DocNum" = ORCT."DocNum" '
||           'INNER JOIN JDT1 ON (ORCT."TransId" = JDT1."TransId" AND '
||           'JDT1."Account" <> JDT1."ShortName") '
|| 'WHERE JDT1."IntrnMatch" = -1 AND ORCT."TransId" = JDT1."TransId" AND '
||       'JDT1."Account" <> JDT1."ShortName" AND '
||      'JDT1."Line_ID" = (SELECT Top 1 "Line_ID" '
||						   'FROM JDT1 INNER JOIN ORCT ON ORCT."TransId" = JDT1."TransId" ' 
||						             'INNER JOIN RCT2 ON RCT2."DocNum" = ORCT."DocNum" '
||						   'WHERE  JDT1."IntrnMatch" = -1 AND ' 
||								  'JDT1."Account" <> JDT1."ShortName") ');
-------------------------Payments to sup.---------------------- 
EXEC('INSERT INTO JDT1_TEMP '
|| 'SELECT VPM2."DocEntry",VPM2."InvType",OVPM."CardCode",OVPM."DocDate" '
|| 'FROM VPM2 INNER JOIN OVPM ON VPM2."DocNum" = OVPM."DocNum" '
||           'INNER JOIN JDT1 ON (OVPM."TransId" = JDT1."TransId" AND '
||           'JDT1."Account" <> JDT1."ShortName") '
|| 'WHERE JDT1."IntrnMatch" = -1 AND OVPM."TransId" = JDT1."TransId" AND '
||       'JDT1."Account" <> JDT1."ShortName" AND '
||       'JDT1."Line_ID" = (SELECT Top 1 "Line_ID" '
||						   'FROM JDT1 INNER JOIN OVPM ON OVPM."TransId" = JDT1."TransId"'
||									 'INNER JOIN VPM2 ON VPM2."DocNum" = OVPM."DocNum" '
||						   'WHERE  JDT1."IntrnMatch" = -1 AND '
||								  'JDT1."Account" <> JDT1."ShortName") ');
-------------------------Credit note----------------------------- 
EXEC('INSERT INTO JDT1_TEMP '
|| 'SELECT RIN1."BaseEntry",RIN1."BaseType",ORIN."CardCode",ORIN."DocDate" '
|| 'FROM RIN1 INNER JOIN ORIN ON RIN1."DocEntry" = ORIN."DocEntry" '
||           'INNER JOIN JDT1 ON (ORIN."TransId" = JDT1."TransId" AND '
||           'JDT1."Account" <> JDT1."ShortName") '
|| 'WHERE JDT1."IntrnMatch" = -1 AND RIN1."BaseEntry" <> 0 AND '
||       'NOT RIN1."BaseEntry" is NULL ');
------------------------Purshase credit note--------------------- 
EXEC('INSERT INTO JDT1_TEMP '
|| 'SELECT RPC1."BaseEntry",RPC1."BaseType",ORPC."CardCode",ORPC."DocDate" '
|| 'FROM RPC1 INNER JOIN ORPC ON RPC1."DocEntry" = ORPC."DocEntry" '
||           'INNER JOIN JDT1 ON (ORPC."TransId" = JDT1."TransId" AND '
||           'JDT1."Account" <> JDT1."ShortName") '
|| 'WHERE JDT1."IntrnMatch" = -1 AND RPC1."BaseEntry" <> 0 AND '
||       'NOT RPC1."BaseEntry" is NULL ');
----------------------------------------------------------------
EXEC('UPDATE JDT1_TEMP '
|| 'SET DocEntry = OJDT."TransId" '
|| 'FROM JDT1_TEMP INNER JOIN OJDT ON '
||      'JDT1_TEMP.InvType = OJDT."TransType" AND '
||      'JDT1_TEMP.DocEntry = OJDT."CreatedBy" '
|| 'WHERE  JDT1_TEMP.InvType = 13 OR JDT1_TEMP.InvType = 18 ');
----------------------------------------------------------------
EXEC('UPDATE JDT1 '
|| 'SET "MthDate" = JDT1_TEMP.DocDate '
|| 'FROM JDT1 INNER JOIN JDT1_TEMP ON  '
||      'JDT1."TransId" = JDT1_TEMP.DocEntry '
|| 'WHERE JDT1."IntrnMatch" = -1 AND JDT1."Account" <> JDT1."ShortName" ');

EXEC('UPDATE JDT1 '
|| 'SET "MthDate" = "RefDate" '
|| 'WHERE "IntrnMatch" = -1 AND "MthDate" is NULL ');

EXEC('UPDATE JDT1 '
|| 'SET  "MthDate" = OMTH."MatchDate" '
|| 'FROM JDT1 INNER JOIN OMTH ON  '
|| 'JDT1."IntrnMatch" = OMTH."MatchNum" AND  '
|| 'JDT1."ShortName" = OMTH."MthAcctCod" '
|| 'WHERE JDT1."IntrnMatch" > 0 AND OMTH."IsInternal" = ''I'' AND '
||       'JDT1."MthDate" is NULL ');
----------------------------------------------------------------
DROP TABLE JDT1_TEMP;
end;

