CREATE procedure _TmSp_RemoveUDFsUDTsInconsistencies
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
 exists1 int;
 tables nvarchar(30) array = array('TMP1', 'ABF1', 'ABF2', 'ABTD', 'ABTF', 'OPBU', 'ORPA', 'ARPA', 'ORPR', 'ARPR');
 idx integer;
 statement nvarchar(500);
 table_es_query_template nvarchar(30)  = 'ES_QUERY_TEMPLATE';
BEGIN

-- Fixing query for pre-check nr.11 - space after table name in OUTB.TableName
------------------------------------------------------------------------------
UPDATE OUTB SET "TableName" = LTRIM(RTRIM("TableName")) WHERE "TableName" LIKE '% %';

-- Fixing queries from SAP note 1076082 - UDT and UDF Related Issues:
---------------------------------------------------------------------
-- 7a) UDF contains extra spaces in field TableID in User-fields description CUFD table
update cufd
set "TableID" = REPLACE ("TableID", char(32), char(0)) from cufd
where "TableID"  LIKE '% %';

-- 7b) UDF contains extra spaces in field AliasID in User-fields
update cufd
set "AliasID" = REPLACE ("AliasID", char(32), char(0)) from cufd
where "AliasID"  LIKE '% %';

-- 1) UDT is defined but does not exist
delete from OUTB T0 where not exists (select 1 from sys.tables T1 where T1.schema_name = current_schema and T1.is_system_table = 'FALSE' and T1.table_name = '@' || "TableName");

-- 3) UDF is defined on an unregistered UDT
delete from CUFD T0 
where left(T0."TableID",1)='@' 
and not exists (select 1 from OUTB T1 where '@' || T1."TableName" =T0."TableID" or '@' || 
T1."LogTable"= T0."TableID");

-- 4) UDF is defined but does not exist
delete from CUFD where not exists (
select 1 from public.tables t0 inner join public.table_columns t1 on t0.table_oid = t1.table_oid
where t0.schema_name = current_schema and t0.is_system_table = 'FALSE'
and t0.table_name = "TableID" and t1.column_name='U_' || "AliasID") and "TableID" not in ('BTNT', 'BTNT1', 'OIBT', 'OSRI', 'SRNT', 'SRNT1', 'ODIB', 'ODSR');

-- 5) UDF valid values are defined for non-existing UDF
delete from UFD1 T
where not exists(select 1 from CUFD where "TableID" = T."TableID"
and "FieldID"=T."FieldID");

-- Fixing query for obsolete tables 
-----------------------------------
for idx in 1.. cardinality(:tables) do
	delete from CUFD where "TableID" = :tables[:idx];
	select count(1) into exists1 from "PUBLIC"."M_TABLES"
	where "TABLE_NAME" = :tables[:idx] and "SCHEMA_NAME" = CURRENT_SCHEMA;
	if :exists1 <> 0 then
		statement := 'drop table ' || :tables[:idx] || ' CASCADE';
		exec :statement;
	end if;
end for;

-- Fixing query for table ES_QUERY_TEMPLATE 
-------------------------------------------
select count(1) into exists1 from "PUBLIC"."M_TABLES"
where "TABLE_NAME" = :table_es_query_template and "SCHEMA_NAME" = CURRENT_SCHEMA;
if :exists1 <> 0 then
	statement := 'alter table ' || :table_es_query_template || ' row';
	exec :statement;
	statement := 'alter table ' || :table_es_query_template || ' column';
	exec :statement;
end if;

END;

-- B1 DEPENDS: AFTER:PT:CREATE_TABLES_TO_VIEWS

CREATE PROCEDURE _TmSp_RestoreIsCommited_CursorInOIBT(IN ItemCode nvarchar (50),
													  IN BatchNum nvarchar (32),
													  IN WhsCode  nvarchar (8),
													  OUT IsCommited DECIMAL(21,6))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
-------------------------------------------------------------
Quantity	DECIMAL(21,6);
BaseType	smallint;
BsDocType	smallint;
BsDocEntry	int;
BsDocLine	int;

exists1 int;
BaseQuantity DECIMAL(21,6);

CURSOR Currs for 
	 select "Quantity","BaseType","BsDocType","BsDocEntry","BsDocLine"
	 from IBT1
	 where "ItemCode" = :ItemCode and
		   "BatchNum" = :BatchNum and
		   "WhsCode" = :WhsCode and
		   ("BaseType" = 17 or "BsDocType" = 17);
begin

	
		Open Currs;
		 
		Fetch Currs 
		Into Quantity,BaseType,BsDocType,BsDocEntry,BsDocLine;
		While NOT Currs::NOTFOUND do

			If :BaseType = 17 then
				IsCommited := :IsCommited + :Quantity;
			Else
				select count(*) into exists1 from IBT1
				where "ItemCode"  = :ItemCode   and "BatchNum"   = :BatchNum  and
					  "WhsCode"   = :WhsCode    and "BaseType"   = :BsDocType and
					  "BaseEntry" = :BsDocEntry and "BaseLinNum" = :BsDocLine;
				if exists1 <> 0 then 	  
					select "Quantity" into BaseQuantity 
					from IBT1
					where "ItemCode"  = :ItemCode   and "BatchNum"   = :BatchNum  and
						  "WhsCode"   = :WhsCode    and "BaseType"   = :BsDocType and
						  "BaseEntry" = :BsDocEntry and "BaseLinNum" = :BsDocLine;		   
					if :BaseQuantity is not null then
						If :Quantity <= :BaseQuantity then
							IsCommited := :IsCommited - :Quantity;
						Else
							IsCommited := :IsCommited - :BaseQuantity;
						End if;
					end if;	
				end if;	
			End if;
			
			Fetch Currs
			Into Quantity,BaseType,BsDocType,BsDocEntry,BsDocLine;
		end while;
		
		Close Currs;
	
end;

-- B1 DEPENDS: AFTER:PT:CREATE_TABLES_TO_VIEWS AFTER:SP:_TmSp_RestoreIsCommited_CursorInOIBT

CREATE PROCEDURE _TmSp_RestoreIsCommited_OIBT
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
-------------------------------------------------------------
ItemCode	nvarchar (50);
BatchNum	nvarchar (32);
WhsCode		nvarchar (8);

hasNext 	int := 1;
IsCommited 	DECIMAL(21,6);

--SET NOCOUNT ON

CURSOR Currs for 
	select "ItemCode","BatchNum","WhsCode"
	from OIBT;

begin

	Open Currs;

	Fetch Currs Into ItemCode,BatchNum,WhsCode;
	if not Currs::NOTFOUND then
		hasNext := -1;
	end if;
	
	While (:hasNext > 0) do
	
		IsCommited := 0;
		-----------------------------------------------------
		call _TmSp_RestoreIsCommited_CursorInOIBT(ItemCode,BatchNum,WhsCode,IsCommited);
		--------------------------------------------------------------
		Update OBTQ Set "CommitQty" = :IsCommited;

		Fetch Currs Into ItemCode,BatchNum,WhsCode;
		if not Currs::NOTFOUND then
			hasNext := -1;
		end if;
		
	end while;
	
	Close Currs;
	
	--SET NOCOUNT OFF
end;

create PROCEDURE _TmSp_RetrieveDocLineBatchAndSerialNumbers
(
	IN docType integer,
	IN docEntry integer
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
	docTable nvarchar(4);
	sqlStatement nvarchar(4000);

	currentRow integer;
	number nvarchar(6000) :='';
	managedByOfLastLine integer;
	rowNo integer;
	managedBy integer;
	batch_number nvarchar(60);
	serial_number nvarchar(60);
	qty DECIMAL(21,6);
	lcPrice DECIMAL(21,6);
	doc1Price DECIMAL(21,6);
	doc1Rate DECIMAL(21,6);
	doc1Price2 DECIMAL(21,6);
	doc1Rate2 DECIMAL(21,6);
	
	rowCount integer;
	iter integer;
	hasNext integer;
BEGIN

	if :docType = 15 then
		docTable :='DLN1';
	elseif :docType =16 then
		docTable :='RDN1';
	elseif :docType =20 then
		docTable :='PDN1';
	elseif :docType =21 then
		docTable :='RPD1';
	elseif :docType =59 then
		docTable :='IGN1';
	elseif :docType =60 then
		docTable :='IGE1';
	elseif :docType =67 then
		docTable :='WTR1';
	elseif :docType =112 then
		docTable :='DRF1';
	end if;
	
	CREATE local temporary TABLE #RetrieveDocLineSnB_TempTable 
	(
		"ID" integer,
		"DocRow" integer,
		"ManagedBy" integer,
		"BatchNumber" nvarchar(60),
		"SerialNumber" nvarchar(60),
		"Quantity" DECIMAL(21,6),
		"SysNumber" integer,
		"Price" DECIMAL(21,6),
		"Rate" DECIMAL(21,6)
	);
	DELETE FROM #RetrieveDocLineSnB_TempTable WHERE 1=1;
	
	CREATE local temporary TABLE #RetrieveDocLineSnB_TempTable_Merge 
	(
		"DocRow" integer,
		"ManagedBy" integer,
		"BatchNumber" nvarchar(60),
		"SerialNumber" nvarchar(60),
		"Quantity" DECIMAL(21,6),
		"Price" DECIMAL(21,6),
		"Rate" DECIMAL(21,6),
		"ID" integer
		--"ID_in_Group" integer
	);
	DELETE FROM #RetrieveDocLineSnB_TempTable_Merge WHERE 1=1;
	
	CREATE local temporary TABLE #RetrieveDocLineSnB_ReturnTable
	(
		"DocumentEntry" integer,
		"DocRow" integer,
		"ManagedBy" integer,
		"BatchNumber" nvarchar(5000),
		"SerialNumber" nvarchar(5000),
		"Quantity" DECIMAL(21,6),
		"Price" DECIMAL(21,6)
	);
	DELETE FROM #RetrieveDocLineSnB_ReturnTable WHERE 1=1;
	
	--select t0."LineNum", t5."ManagedBy",t5."BatchNumber",t5."SerialNumber",t5."Quantity", t5."SysNumber" from PDN1 t0 
	--left join 
	--(
	--	select  t1."DocEntry",t1."DocLine", t1."ManagedBy",t3."DistNumber" as "BatchNumber", t4."DistNumber" as "SerialNumber", t2."Quantity" ,case t1."ManagedBy"
	--										when 10000044 then t3."SysNumber" 
	--										when 10000045 then t4."SysNumber"
	--										else NULL end as "SysNumber"   
	--	from OITL t1 
	--		join ITL1 t2 on t1."LogEntry"=t2."LogEntry" and t1."DocType"= 20 and t1."DocEntry"=3  
	--		left outer join OBTN t3 on t2."SysNumber"=t3."SysNumber" and t2."ItemCode"=t3."ItemCode" and t1."ManagedBy"=10000044
	--		left outer join OSRN t4 on t2."SysNumber"=t4."SysNumber" and t2."ItemCode"=t4."ItemCode" and t1."ManagedBy"=10000045
	--) t5 
	--on t0."DocEntry"=t5."DocEntry" and t0."LineNum"=t5."DocLine"
	--where t0."DocEntry"=3  
	--order by t0."LineNum", t5."SysNumber";

	sqlStatement := N'insert into #RetrieveDocLineSnB_TempTable("DocRow","ManagedBy","BatchNumber","SerialNumber","Quantity","SysNumber","Price","Rate") ';
	sqlStatement := :sqlStatement || N'select t0."LineNum",t5."ManagedBy",t5."BatchNumber",t5."SerialNumber",t5."Quantity", t5."SysNumber",t0."Price",t0."Rate" from ' || :docTable ||' t0  
										left join
										(
											select  t1."DocEntry",t1."DocLine", t1."ManagedBy",t3."DistNumber" as "BatchNumber", t4."DistNumber" as "SerialNumber", t2."Quantity" ,
													case t1."ManagedBy" 
														when 10000044 then t3."SysNumber"  
														when 10000045 then t4."SysNumber" 
														else NULL end as "SysNumber"   
											from OITL t1 
											join ITL1 t2 on t1."LogEntry"=t2."LogEntry" and t1."DocType"= ' || cast(:docType as nvarchar) ||'  and t1."DocEntry"=' || cast(:docEntry as nvarchar) || 
											N' left outer join OBTN t3 on t2."SysNumber"=t3."SysNumber" and t2."ItemCode"=t3."ItemCode" and t1."ManagedBy"=10000044 
											left outer join OSRN t4 on t2."SysNumber"=t4."SysNumber" and t2."ItemCode"=t4."ItemCode" and t1."ManagedBy"=10000045 
										) as t5
										on t0."DocEntry"=t5."DocEntry" and t0."LineNum"=t5."DocLine" 
										where t0."DocEntry"=' ||cast(:docEntry as nvarchar) || 
										N' order by t0."LineNum", t5."SysNumber"'; 										
	exec (:sqlStatement);													

	insert into #RetrieveDocLineSnB_TempTable_Merge 
	select t0."DocRow", t0."ManagedBy",t0."BatchNumber", t0."SerialNumber", t0."Quantity",t0."Price",t0."Rate", 
			ROW_NUMBER() over (order by t0."DocRow",t0."SysNumber") as "ID" 
			--ROW_NUMBER() over (PARTITION by t0."DocRow" order by t0."DocRow") as "id_in_group"
	from #RetrieveDocLineSnB_TempTable t0; 
	update #RetrieveDocLineSnB_TempTable_Merge t0 set t0."BatchNumber" = t0."BatchNumber" || '(' || cast (abs(t0."Quantity") as nvarchar) || ')' where t0."ManagedBy" = 10000044;
	
	select count(*) into rowCount  from #RetrieveDocLineSnB_TempTable_Merge;
	
	iter := 1;
	hasNext := 1;
	number := '';
	
	select t0."DocRow",t0."ManagedBy",t0."BatchNumber",t0."SerialNumber",t0."Quantity",t0."Price",t0."Rate" 
	into rowNo, managedBy, batch_number, serial_number, qty, doc1Price, doc1Rate 
	from #RetrieveDocLineSnB_TempTable_Merge t0 
	where t0."ID" = :iter;
	
	currentRow := :rowNo;

	while :iter <= :rowCount and :hasNext = 1 do
		if :managedBy = 10000044 then 
				number := :number || :batch_number || '; ';
		elseif :managedBy = 10000045 then 
				number := :number || :serial_number || '; ';
		end if;
		managedByOfLastLine := :managedBy;
		
		if iter < rowCount then 
			iter := :iter + 1;
			select t0."DocRow",t0."ManagedBy",t0."BatchNumber",t0."SerialNumber",t0."Quantity",t0."Price",t0."Rate" 
			into rowNo, managedBy, batch_number, serial_number, qty, doc1Price2, doc1Rate2 
			from #RetrieveDocLineSnB_TempTable_Merge t0 
			where t0."ID" = :iter;
		else
			hasNext := 0;
			
		end if;

		if :hasNext = 0  OR :currentRow <> :rowNo then 
			if :doc1Rate is not null and :doc1Rate <> 0 then
				lcPrice := :doc1Price * :doc1Rate;
			else
				lcPrice := :doc1Price;
			end if;
			
			if :managedByOfLastLine = 10000044 then
				insert into #RetrieveDocLineSnB_ReturnTable values(:docEntry,:currentRow,:managedByOfLastLine,substring(:number,1,length(:number) - 2),NULL,:qty,:lcPrice);
			elseif :managedByOfLastLine = 10000045 then
				insert into #RetrieveDocLineSnB_ReturnTable values(:docEntry,:currentRow,:managedByOfLastLine,NULL,substring(:number,1,length(:number) - 2),:qty,:lcPrice);
			else
				insert into #RetrieveDocLineSnB_ReturnTable values(:docEntry,:currentRow,:managedByOfLastLine,NULL,NULL,NULL,:lcPrice);
			end if;
			doc1Price := :doc1Price2;
			doc1Rate := :doc1Rate2;
			if :hasNext = 1 then
				currentRow := :rowNo;
				number := '';
			end if;
		end if;
			
	end while;
	
	--select * from #RetrieveDocLineSnB_TempTable;
	--select * from #RetrieveDocLineSnB_TempTable_Merge;
	select * from #RetrieveDocLineSnB_ReturnTable;
	drop table #RetrieveDocLineSnB_TempTable;
	drop table #RetrieveDocLineSnB_TempTable_Merge;
	drop table #RetrieveDocLineSnB_ReturnTable;
END;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START

CREATE procedure _TmSp_SetCategoryAtOFPR
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS

exists1 int;
exists2 int;
begin

	select count(*) into exists1 from "PUBLIC".objects
	where object_name = 'OFPR' and object_type = 'TABLE' and schema_name = CURRENT_SCHEMA;

	select count(*) into exists2 from "PUBLIC"."TABLE_COLUMNS" c
	inner Join "PUBLIC".objects o on (o.object_oid = c.table_oid
							 and o.schema_name = CURRENT_SCHEMA
							 and c.schema_name = CURRENT_SCHEMA)
	where o.object_name = 'OFPR' And 
		  c.column_name = 'Category';
		  
	IF (:exists1 <> 0) and (:exists2 = 0)
	THEN
		exec('alter table OFPR add("Category9999" nvarchar(10))');
	END IF;

	exec('UPDATE OFPR SET "Category" = "AbsEntry" WHERE IFNULL("Category",'''') = ''''');

end;

