-- B1 DEPENDS: BEFORE:PT:PROCESS_START

CREATE procedure _TmSp_SetUniqueDocEntryAtOCRD
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
-------------------------------------------------------------
Oline     int;
cardCode  nvarchar (15);
hasNext   int := 1;
 
--CURSOR Currs for 
--	select  "CardCode"
--	From  TEMP_OCRD;
--  Order By "CardCode"

begin
--	Open Currs;
	
	Oline := 1;

