		strSQL := 'insert into "#tempAsmOINM" select T0."ItemCode", T0."LocCode" as "Warehouse", T0."TransType", T0."DocEntry" as "CreatedBy", T0."DocLineNum", T1."CostMethod", T0."SubLineNum" from OILM T0 inner join OIVL T1 on T0."MessageID" = T1."MessageID" where T0."SubLineNum" >= 0 and T0."TransType" <> 162 union all select T0."ItemCode", T0."LocCode" as "Warehouse", T0."TransType", T0."DocEntry" as "CreatedBy", T0."DocLineNum", T2."CostMethod", T0."SubLineNum" from OILM T0 inner join OILM T1 on T0."BaseType" = T1."TransType" and T0."BaseAbsEnt" = T1."DocEntry" and T0."BaseLine" = T1."DocLineNum" and T0."ItemCode" = T1."ItemCode" and T0."LocCode" = T1."LocCode" and T0."TransType" = 13 and T0."BaseType" = 15 inner join OIVL T2 on T1."MessageID" = T2."MessageID" where T0."SubLineNum" >= 0 ';
	end if;
	
	select count(*) into cond from "PUBLIC"."M_TEMPORARY_TABLES" where  table_name = '#tmp_OILMAllParents_grouped';
	if(:cond > 0) then 
	   drop table "#tmp_OILMAllParents_grouped";
	end if;
	
	create local TEMPORARY TABLE "#tmp_OILMAllParents_grouped"(
		"ItemCode" NVARCHAR (50),
		"TransType" INTEGER,
		"DocEntry" INTEGER,
		"DocLineNum" SMALLINT, 
		"MinSubLineNum" INTEGER
	);
	DELETE FROM "#tmp_OILMAllParents_grouped" WHERE 1=1;

	select count(*) into cond from "PUBLIC"."M_TEMPORARY_TABLES" where  table_name = '#tmp_OILMSonsWHSNotChanged';
	if(:cond > 0) then 
	   drop table "#tmp_OILMSonsWHSNotChanged";
	end if;
	
	create local TEMPORARY COLUMN TABLE "#tmp_OILMSonsWHSNotChanged"(
		"ItemCode" NVARCHAR (50),
		"TransType" INTEGER,
		"DocEntry" INTEGER,
		"DocLineNum" SMALLINT,
		"BaseType" INTEGER,
		"BaseAbsEnt" INTEGER,
		"BaseLine" SMALLINT, 
		"MessageID" INTEGER not null, 
		"BSubLineNo" INTEGER
	);
	TRUNCATE TABLE "#tmp_OILMSonsWHSNotChanged";
	
	select count(*) into cond from "PUBLIC"."M_TEMPORARY_TABLES" where  table_name = '#tmp_OILMSonsWHSChanged';
	if(:cond > 0) then 
	   drop table "#tmp_OILMSonsWHSChanged";
	end if;
	
	create local TEMPORARY TABLE "#tmp_OILMSonsWHSChanged"(
		"ItemCode" NVARCHAR (50),
		"TransType" INTEGER,
		"DocEntry" INTEGER,
		"DocLineNum" SMALLINT, 
		"BaseType" INTEGER, 
		"BaseAbsEnt" INTEGER, 
		"BaseLine" SMALLINT, 
		"MessageID" INTEGER not null
	);
	DELETE FROM "#tmp_OILMSonsWHSChanged" WHERE 1=1;

-- [NOT FIFO]
-- HANDLE PARENTS
-- 2) Get all parents with rank
-- Create temp tables of all parents 
	exec(:strSQL);
	strSQL := ' Insert into "#tmp_OILMAllParents" select P1."MessageID",P1."ItemCode",P1."LocCode",P1."TransType",P1."DocEntry",P1."DocLineNum",P1."SubLineNum" As "NewSubLineNum" from OILM P1 INNER JOIN "#tempAsmOINM" P2 On P1."ItemCode" = P2."ItemCode" AND P1."LocCode" = P2."Warehouse" AND P1."TransType" = P2."TransType" AND P1."DocEntry" = P2."CreatedBy" AND P1."DocLineNum" = P2."DocLineNum" AND P2."CostMethod" <> N''F''';
	exec(:strSQL);				
	strSQL :='insert into "#tmp_OILMAllParents_grouped" select P1."ItemCode",P1."TransType",P1."DocEntry",P1."DocLineNum", MIN(P1."NewSubLineNum") As '||'"MinSubLineNum"'||' from "#tmp_OILMAllParents" P1 group by P1."TransType", P1."DocEntry", P1."DocLineNum", P1."ItemCode"';
	exec(:strSQL);
	strSQL := 'insert into "#tmp_OILMSonsWHSNotChanged" select S1."ItemCode",S1."TransType",S1."DocEntry",S1."DocLineNum",S1."BaseType",S1."BaseAbsEnt", S1."BaseLine", S1."MessageID", O2."SubLineNum" As '||'"BSubLineNo"'||' from OILM S1 INNER JOIN "#tempAsmOINM" O1 On	S1."ItemCode" = O1."ItemCode" AND S1."LocCode" = O1."Warehouse" AND S1."TransType" = O1."TransType" AND S1."DocEntry" = O1."CreatedBy" AND S1."DocLineNum" = O1."DocLineNum" AND O1."CostMethod" <> N''F'' INNER JOIN "#tempAsmOINM" O2 ON	S1."BaseType" = O2."TransType" AND S1."BaseLine" = O2."DocLineNum" AND  S1."ItemCode" = O2."ItemCode" AND	S1."LocCode" = O2."Warehouse" AND S1."BaseAbsEnt" = O2."CreatedBy" where S1."BaseType"<>-1 AND S1."BaseType" IS NOT NULL AND (S1."TransType" <> 15 OR S1."BaseType" <> 165) AND S1."BSubLineNo" = -1';	
	exec(:strSQL);

	-- strSQL :='update OILM set "BSubLineNo" = S2."BSubLineNo" from OILM S1 inner join "#tmp_OILMSonsWHSNotChanged" S2 On S1."MessageID" = S2."MessageID"';
	strSQL := '
		update OILM S1
		set "BSubLineNo" = (select "BSubLineNo" from "#tmp_OILMSonsWHSNotChanged" S2 where S1."MessageID" = S2."MessageID")
		where exists (select 1 from "#tmp_OILMSonsWHSNotChanged" S2 where S1."MessageID" = S2."MessageID")
	';
	exec(:strSQL);

	strSQL :='insert into "#tmp_OILMSonsWHSChanged" select S1."ItemCode",S1."TransType",S1."DocEntry",S1."DocLineNum", S1."BaseType", S1."BaseAbsEnt", S1."BaseLine", S1."MessageID" from OILM S1 INNER JOIN "#tempAsmOINM" O1 On S1."ItemCode" = O1."ItemCode" AND  S1."TransType" = O1."TransType" AND  S1."DocEntry" = O1."CreatedBy" AND  S1."DocLineNum" = O1."DocLineNum" AND  O1."CostMethod" <> N''F'' AND  S1."BaseType"<>-1 where (S1."TransType" <> 15 OR S1."BaseType" <> 165) AND S1."BSubLineNo" = -1';
	exec(:strSQL);

	-- strSQL :='UPDATE OILM set "BSubLineNo" = P1."MinSubLineNum" from OILM S2 inner join "#tmp_OILMSonsWHSChanged" S1 ON S2."MessageID" = S1."MessageID" inner join "#tmp_OILMAllParents_grouped" P1 ON S1."BaseType" = P1."TransType" AND  S1."BaseAbsEnt" = P1."DocEntry" AND S1."BaseLine" = P1."DocLineNum" AND S1."ItemCode"= P1."ItemCode"';
	strSQL := '
		UPDATE OILM S2 
		set "BSubLineNo" = (
			select P1."MinSubLineNum" 
			from "#tmp_OILMSonsWHSChanged" S1 
			inner join "#tmp_OILMAllParents_grouped" P1 ON S1."BaseType" = P1."TransType" AND S1."BaseAbsEnt" = P1."DocEntry" 
				AND S1."BaseLine" = P1."DocLineNum" AND S1."ItemCode"= P1."ItemCode" 
			where S2."MessageID" = S1."MessageID")
		where exists (
			select 1 
			from "#tmp_OILMSonsWHSChanged" S1 
			inner join "#tmp_OILMAllParents_grouped" P1 ON S1."BaseType" = P1."TransType" AND S1."BaseAbsEnt" = P1."DocEntry" 
				AND S1."BaseLine" = P1."DocLineNum" AND S1."ItemCode"= P1."ItemCode" 
			where S2."MessageID" = S1."MessageID") 
	';
	exec(:strSQL);
	
	-- strSQL :='UPDATE OILM Set "BSubLineNo" = S1."SubLineNum" from OILM S1 INNER JOIN "#tempAsmOINM" O1 On S1."ItemCode" = O1."ItemCode" AND  S1."TransType" = O1."TransType" AND S1."DocEntry" = O1."CreatedBy" AND  S1."DocLineNum" = O1."DocLineNum" AND  O1."CostMethod" = N''F'' AND ((S1."BaseType"<>-1 AND S1."BaseType" IS NOT NULL) AND (S1."TransType" <> 15 OR S1."BaseType" <> 165) AND ( S1."BaseAbsEnt" IN ( select "CreatedBy" FROM "#tempAsmOINM" P3 where S1."BaseType" = P3."TransType" AND S1."BaseAbsEnt" = P3."CreatedBy" AND S1."BaseLine" = P3."DocLineNum" AND S1."ItemCode" = P3."ItemCode")))';
	strSQL := '
		UPDATE OILM S1 
		Set "BSubLineNo" = "SubLineNum" 
		where exists (
			select 1 
			from "#tempAsmOINM" O1 
			where S1."ItemCode" = O1."ItemCode" AND S1."TransType" = O1."TransType" 
				AND S1."DocEntry" = O1."CreatedBy" AND S1."DocLineNum" = O1."DocLineNum" AND O1."CostMethod" = N''F'' 
				AND ((S1."BaseType"<>-1 AND S1."BaseType" IS NOT NULL) AND (S1."TransType" <> 15 OR S1."BaseType" <> 165)
					AND ( S1."BaseAbsEnt" IN (
						select "CreatedBy" 
						FROM "#tempAsmOINM" P3 
						where S1."BaseType" = P3."TransType" AND S1."BaseAbsEnt" = P3."CreatedBy" 
							AND S1."BaseLine" = P3."DocLineNum" AND S1."ItemCode" = P3."ItemCode"))) )
	';
	exec(:strSQL);

	-- strSQL :='UPDATE OIVL SET "BSubLineNo" = O2."BSubLineNo" FROM OIVL O1, OILM O2 WHERE O2."BSubLineNo" >= 0 AND O1."MessageID" = O2."MessageID"';
	strSQL :='
		UPDATE OIVL O1 
		SET "BSubLineNo" = (select O2."BSubLineNo" from OILM O2 where O2."BSubLineNo" >= 0 AND O1."MessageID" = O2."MessageID") 
		WHERE exists (select 1 from OILM O2 where O2."BSubLineNo" >= 0 AND O1."MessageID" = O2."MessageID")
	';
	exec(:strSQL);

	strSQL :='drop table "#tempAsmOINM"';
	exec(:strSQL);
	strSQL :='drop table "#tmp_OILMAllParents"';	
	exec(:strSQL);
	strSQL :='drop table "#tmp_OILMAllParents_grouped"';	
	exec(:strSQL);
	strSQL :='drop table "#tmp_OILMSonsWHSNotChanged"';
	exec(:strSQL);
	strSQL :=' drop table "#tmp_OILMSonsWHSChanged"';
	exec(:strSQL);
*/
end;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START
-- dependencies does not work in msq sql, and since we are updating fields that will be created during structural upgrade
-- so during creation of this SP, fields does not exists and table exits, so it will fail.  therefore we have to do it via 
-- string execution
-- please also note that doing this query by DBQ, it will fail on HANA, therefore SP creation
CREATE procedure _TmSp_UpgradeClosingDataTimeVersionNum
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
	v_sql nvarchar(4000);	
BEGIN
    v_sql:='UPDATE T0
	SET T0."SysCloseDt" = T1."CreateDate", T0."SysCloseTm" = T1."CreateTime", T0."CloseVerNm" = T1."VersionNum"
	FROM OWOR T0, OJDT T1
	WHERE T0."DocEntry" = T1."CreatedBy"
	AND T1."TransType" = ''202''';
	exec(:v_sql);
END;

CREATE PROCEDURE _TmSp_UpgradeECM2ForEWB
(	IN DocTable nvarchar(8),
	IN ProtocolCode nvarchar(1),
	IN ActType int,
	IN ObjName nvarchar(2)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
maxEntry int := 0;
isExist int := 0;
execStr nvarchar(4000);
BEGIN

	select ifnull(max("AbsEntry"), 0) into maxEntry from ECM2;
	
	SELECT COUNT(1) into isExist FROM SYS.TABLES WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = 'ECM2_EWB';
	if (:isExist > 0) then
		execStr := 'drop table "ECM2_EWB"';
		exec(:execStr);
	end if;

	create table "ECM2_EWB" as
	(select * from "ECM2" where 1<>1);

	execStr := 'insert into ECM2_EWB ("AbsEntry", "Code", "ActType", "ActDesc", "ActStatus", "IsRemoved", "BPLId", "ObjectID", "SrcObjType", "SrcObjAbs", "Cancel", "GenType", "UserSign", "GUID")
				select row_number() over(ORDER BY t0."DocEntry"), '''|| :ProtocolCode || ''', ''' || :ActType || ''', ''Upgrade'', ''W'', ''N'', ifnull(t0."BPLId", 0), concat(''' || :ObjName ||' '', t0."DocNum"),
				(case when ''' || :DocTable ||''' = ''ODRF'' then 112 else t0."ObjType" end), t0."DocEntry", t0."CANCELED", t0."EWBGenType", t0."UserSign",
				HASH_SHA256(NEWUID())
				from ' || :DocTable || ' t0
				inner join NNM1 t1 on t0."Series" = t1."Series" and t1."IsDigSerie" = ''Y''
				where ("EWBGenType" in (''G'', ''L'')
				and "CANCELED" <> ''C''
				and "DocType" = ''I''
				and not exists (select 1 from ECM2 t2 where t2."SrcObjType" = (case when ''' || :DocTable ||''' = ''ODRF'' then 112 else t0."ObjType" end)
															and t2."SrcObjAbs" = t0."DocEntry" and t2."Code" = '''|| :ProtocolCode ||'''))
				';
	exec(:execStr);
	
	update ECM2_EWB set "AbsEntry" = "AbsEntry"  + :maxEntry;
	
	if (:DocTable = 'ODRF')	then
		update t0 set "ActType" = (case when "SrcObjType" in (13, 14, 15, 16) then 5 else 6 end),
					  "ObjectID" = concat((case when t1."ObjType" = 13 then 'IN'
									   when t1."ObjType" = 14 then 'CN'
									   when t1."ObjType" = 15 then 'DN'
									   when t1."ObjType" = 16 then 'RE'
									   when t1."ObjType" = 18 then 'PU'
									   when t1."ObjType" = 19 then 'PC'
									   when t1."ObjType" = 20 then 'PD'
									   when t1."ObjType" = 21 then 'PR' end), "ObjectID")
		from ECM2_EWB t0
		inner join ODRF t1 on t0."SrcObjAbs" = t1."DocEntry"
		where "SrcObjType" = 112;
	end if;
	
	insert into ECM2 select * from ECM2_EWB;
	
	execStr := 'drop table "ECM2_EWB"';
	exec(:execStr);
END

-- B1 DEPENDS: BEFORE:PT:PROCESS_START AFTER:SP:_TmSp_ValidateSpParam

CREATE procedure _TmSp_UpgradeEDF
(
	IN ECM2tableName nvarchar(100), 
	IN ECM3tableName nvarchar(100)
)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS

retValue		int 			:= 0;
IsExists1 	int				:= 0;
IsExists2 	int				:= 0;
IsExists3 	int				:= 0;
ecm2CopyName	nvarchar(100)	:= ECM2tableName || '_COPY';
ecm2TempName	nvarchar(100)	:= 'TEMP_' || ECM2tableName;
ecm3TempName	nvarchar(100)	:= 'TEMP_' || ECM3tableName;
execStr 		nvarchar(4000);

BEGIN
	call _TmSp_ValidateSpParam (:ECM2tableName);
	call _TmSp_ValidateSpParam (:ECM3tableName);
	
	-- create copy of current table if not already exists
	SELECT COUNT(*) INTO IsExists1 FROM OBJECTS 
	WHERE SCHEMA_NAME = CURRENT_SCHEMA AND OBJECT_TYPE = 'TABLE' AND OBJECT_NAME = :ecm2TempName;
	
	SELECT COUNT(*) INTO IsExists2 FROM OBJECTS 
	WHERE SCHEMA_NAME = CURRENT_SCHEMA AND OBJECT_TYPE = 'TABLE' AND OBJECT_NAME = :ecm2CopyName;
	
	IF :IsExists1 > 0 and :IsExists2 = 0 THEN
		execStr := 'CREATE TABLE ' || :ecm2CopyName || ' AS (SELECT * FROM ' || :ecm2TempName || ')';
		exec(:execStr);
		-- do not continue to upgrade (just copy table)
		return;
	END IF;

	-- necessary checks before upgrade
	-- ecm2CopyName (ECM2_COPY/AEC2_COPY) must exist. Copied from TEMP table
	IF :IsExists2 = 0  THEN
		-- do not continue to upgrade, TEMP table does not exist for "non fast upgrade" cases (if main table was empty or same structure, ...)
		return;
	END IF;

	-- test for upgraded ECM2/ECM3 table structure (9.1 -> 9.2)
	-- ECM2: removed field ActData
	SELECT COUNT(*) INTO IsExists1 FROM "PUBLIC"."TABLE_COLUMNS"
	WHERE TABLE_NAME = :ECM2tableName AND SCHEMA_NAME = CURRENT_SCHEMA AND COLUMN_NAME = 'ActData';
	IF :IsExists1 <> 0 THEN
		return;
	END IF;

	-- ECM3: new field LogData
	SELECT COUNT(*) INTO IsExists1 FROM "PUBLIC"."TABLE_COLUMNS"
	WHERE TABLE_NAME = :ECM3tableName AND SCHEMA_NAME = CURRENT_SCHEMA AND COLUMN_NAME = 'LogData';
	IF :IsExists1 = 0 THEN
		return;
	END IF;

	-- if TEMP_ECM3 table does not exist then use ECM3
	SELECT COUNT(*) INTO IsExists3 FROM OBJECTS 
	WHERE SCHEMA_NAME = CURRENT_SCHEMA AND OBJECT_TYPE = 'TABLE' AND OBJECT_NAME = :ecm3TempName;
	IF :IsExists3 = 0 THEN
	  ecm3TempName := ECM3tableName;
	END IF;


	-- upgrade steps

	-- mark old  ecm3 rows as 'Note'
	execStr := 'update ' || :ECM3tableName || ' set "LogType" = ''N''';
	exec(:execStr);
  
	-- copy	ActData to ECM3 as 'Send'
	execStr := 'insert into ' || :ECM3tableName || '("AbsEntry", "LogNum", "LogMessage", "UserSign", "CreateDate", "UserSign2", "UpdateDate", "LogInstanc", "CreateTS", "UpdateTS", "LogType", "LogData", "LogOpDate", "LogOpTS")
		select t0."AbsEntry", 1 + ifNull(t3."NextLogNum",0),
		"ActMessage", "UserSign", "CreateDate", "UserSign2", "UpdateDate", "LogInstanc", "CreateTS", "UpdateTS", ''S'', "ActData", "SendDate", "SendTS"
		from ' || :ecm2CopyName || ' t0 
		left outer join 
		(
			select "AbsEntry", max ("NextLogNum") as "NextLogNum" from
			(select "AbsEntry", ifNull(max("LogNum"),0) as "NextLogNum" from ' || :ecm3TempName || ' group by "AbsEntry"
			union all
			select "AbsEntry", ifNull(max("LogNum"),0) as "NextLogNum" from ' || :ECM3tableName || ' group by "AbsEntry"
			)as nieco
			group by "AbsEntry"
		) 
		t3 on t3."AbsEntry" = t0."AbsEntry" 
		where t0."ActData" is not null or t0."ActData2" is not null';
	exec(:execStr);

	-- copy	ActData2 to ECM3 as 'Receive'
	execStr := 'insert into ' || :ECM3tableName || '("AbsEntry", "LogNum", "LogMessage", "UserSign", "CreateDate", "UserSign2", "UpdateDate", "LogInstanc", "CreateTS", "UpdateTS", "LogType", "LogData", "LogOpDate", "LogOpTS")
		select t0."AbsEntry", 1 + ifNull(t3."NextLogNum",0),
		"ActMessage", "UserSign", "CreateDate", "UserSign2", "UpdateDate", "LogInstanc", "CreateTS", "UpdateTS", ''R'', "ActData2", "ReceivDate", NULL
		from ' || :ecm2CopyName || ' t0
		left outer join
		(
			select "AbsEntry", max ("NextLogNum") as "NextLogNum" from
			(select "AbsEntry", ifNull(max("LogNum"),0) as "NextLogNum" from ' || :ecm3TempName || ' group by "AbsEntry"
			union all
			select "AbsEntry", ifNull(max("LogNum"),0) as "NextLogNum" from ' || :ECM3tableName || ' group by "AbsEntry"
			)as nieco
			group by "AbsEntry"
		) 
		t3 on t3."AbsEntry" = t0."AbsEntry" 
		where t0."ActData" is not null or t0."ActData2" is not null';
	exec(:execStr);
 
	-- drop copy table
	execStr := 'drop table ' || :ecm2CopyName;
	exec(:execStr);

END

-- B1 DEPENDS: BEFORE:PT:PROCESS_START

create procedure _TmSp_UpgradeILMTotalSCforBackFlushChild
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS 
	dec TINYINT;
BEGIN 
      /*   
      *Task: 14305  
      *this query is trying to fix the TotalSC in OILM for production back flush child while we upgrade compamy DB to 8.8  
      */ 
	  select "SumDec" into dec from OADM; 
	  
	  UPDATE oilm t1
      SET    "TotalSC" = Round ("TotalLC" * t1."TotalLC" / nullif(t1."TotalLC",0), :dec) 
      WHERE  "ApplObj" = 202 
             AND t1."ApplObj" = 202 
             AND "AppObjAbs" = t1."AppObjAbs" 
             AND "AppObjType" = 'C' 
             AND t1."AppObjType" = 'P' 
             AND "DocEntry" = t1."DocEntry" 
             AND "TransType" = t1."TransType" 
             AND "DocLineNum" = t1."DocLineNum" 
			 -- AND Isnull(t1.totallc, 0) <> 0 ;
             AND t1."TotalLC" is not null; 
END;

