create procedure _TmSp_UpgradePCH1RPC1StockSumforND(
					IN objID int)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
	SumDec int;
BEGIN

--	SET ANSI_WARNINGS OFF;--not supported current
	select "SumDec" into SumDec from OADM;
	IF :objID = 18 then
			Update PCH1 T0 
			set ("StockSum", "StockSumFc", "StockSumSc") = (
				select T0."StockSum" +	ROUND(T2."NDTaxSum",:SumDec), 
					T0."StockSumFc" + ROUND(T2."NDTaxSumFrgn",:SumDec),
					T0."StockSumSc" + ROUND(T2."NDTaxSumSys",:SumDec)
				from (
					select SUM("TaxSum"-"DeductTax") as "NDTaxSum", SUM("TaxSumFrgn"-"DdctTaxFrg") as "NDTaxSumFrgn", SUM("TaxSumSys"-"DdctTaxSys") as "NDTaxSumSys"
					from PCH4
					where "DocEntry" = T0."DocEntry" and "LineNum" = T0."LineNum" 
						and ("NonDdctAct" is NULL or "NonDdctAct" = N'') and "NonDdctPrc" >0  
				) T2
			)
			where exists (
				select 1 from OPCH T1
				where		T0."DocEntry" = T1."DocEntry"  
							and T1."DocType" = N'I' 
							and (T1."VersionNum" >'7.40.000.00' and T1."VersionNum" <= '7.40.999.00')
			);
    end if;
	
	IF( :objID = 19) then
			Update RPC1 T0 
			set ("StockSum", "StockSumFc", "StockSumSc") = (
				select T0."StockSum" +	ROUND(T2."NDTaxSum",:SumDec), 
					T0."StockSumFc" + ROUND(T2."NDTaxSumFrgn",:SumDec),
					T0."StockSumSc" + ROUND(T2."NDTaxSumSys",:SumDec)
				from (
					select SUM("TaxSum"-"DeductTax") as "NDTaxSum", SUM("TaxSumFrgn"-"DdctTaxFrg") as "NDTaxSumFrgn", SUM("TaxSumSys"-"DdctTaxSys") as "NDTaxSumSys"
					from RPC4
					where "DocEntry" = T0."DocEntry" and "LineNum" = T0."LineNum" 
						and ("NonDdctAct" is NULL or "NonDdctAct" = N'') and "NonDdctPrc" >0  
				) T2
			)
			where exists (
				select 1 from ORPC T1
				where		T0."DocEntry" = T1."DocEntry"  
							and T1."DocType" = N'I' 
							and (T1."VersionNum" >'7.40.000.00' and T1."VersionNum" <= '7.40.999.00')
			);
	end if;
END;

CREATE PROCEDURE _TmSp_UpgradeProductionSubLine
language sqlscript
SQL SECURITY INVOKER
as 
v_sql nvarchar(4000);	

begin
	v_sql:= 'update  "t"
	Set "t"."INMSubLine" = "Source"."Rank"
	from "WOR3" "t"
	inner join 
		(select "DocEntry", "LineNum", "LayerID",
		"Rank"() OVER (PARTITION BY "DocEntry" ORDER BY "DocEntry", "LineNum", "LayerID") - 1 AS "Rank"
		from "WOR3") as "Source"
	on "t"."DocEntry" = "Source"."DocEntry" and "t"."LineNum" = "Source"."LineNum" and "t"."LayerID" = "Source"."LayerID"';
	exec(:v_sql);
	
	update  "t"
	Set "t"."SubLineNum" = "Source"."Rank"
	from "OILM" "t"
	inner join 
		(select "MessageID",
		"Rank"() OVER (PARTITION BY "DocEntry" ORDER BY "MessageID") - 1 AS "Rank"
		from "OILM" where "TransType"=202 and "ActionType" in (7,8)) as "Source"
	on "t"."MessageID" = "Source"."MessageID" and "t"."TransType"=202 and "t"."ActionType" in (7,8);
	
	update  "t"
	Set "t"."SubLineNum" = "Source"."SubLineNum"
	from "OIVL" "t"
	inner join 
		(select "MessageID", "SubLineNum", "ActionType" from "OILM") as "Source"
	on "t"."MessageID" = "Source"."MessageID" and "t"."TransType"=202 and "Source"."ActionType" in (7,8); 
	
	v_sql:= 'update "MRV2" set "INMSubLine" = 0 where "INMTransTy" = 202';
	exec(:v_sql);
	
	v_sql:= 'update  "t"
	Set "t"."INMSubLine" = "Source"."SubLineNum"
	from "MRV2" "t"
	inner join "MRV1" on "t"."DocEntry" = "MRV1"."DocEntry" and "t"."BaseLine"="MRV1"."LineNum"
	inner join 
		(select "OILM"."MessageID", "OILM"."LocCode", "OILM"."ItemCode", "OILM"."Quantity", "OILM"."SubLineNum", "OILM"."DocEntry", "OIVL"."TransSeq" from "OIVL" 
		inner join "OILM" on "OILM"."MessageID" = "OIVL"."MessageID" 
		where "OILM"."TransType"=202 and "OILM"."ActionType" in (7,8)) as "Source"
	on "t"."IVLTransSe" = "Source"."TransSeq" and "MRV1"."ItemCode" = "Source"."ItemCode" and "MRV1"."WhsCode" = "Source"."LocCode" and "t"."INMTransTy"=202 and "t"."INMCreatBy" = "Source"."DocEntry" and "t"."INMOpenQty"="Source"."Quantity" and "t"."INMSubLine" = -1';
	exec(:v_sql);

	v_sql:= ' do begin
			declare i int;
			while 1 = 1 do
			update  "u"
			Set "u"."INMSubLine" = "Result"."SubLineNum"
			from "MRV2" "u"
			inner join 
			(select "t"."DocEntry", "t"."BaseLine", min("t"."LineNum") "LineNum", min("Source"."SubLineNum") "SubLineNum"
			from "MRV2" "t"
			inner join "MRV1" on "t"."DocEntry" = "MRV1"."DocEntry" and "t"."BaseLine"="MRV1"."LineNum"
			inner join 
				(select "OILM"."MessageID", "OILM"."LocCode", "OILM"."ItemCode", "OILM"."Quantity", "OILM"."SubLineNum", "OILM"."DocEntry", "OIVL"."TransSeq" from "OIVL" 
				inner join "OILM" on "OILM"."MessageID" = "OIVL"."MessageID" 
				LEFT JOIN "MRV2" "b" ON "OILM"."SubLineNum" = "b"."INMSubLine" 
				where "OILM"."TransType"=202 and "OILM"."ActionType" in (7,8) and "b"."INMSubLine" is NULL) as "Source"
			on "MRV1"."ItemCode" = "Source"."ItemCode" and "MRV1"."WhsCode" = "Source"."LocCode" and "t"."INMTransTy"=202 and "t"."INMCreatBy" = "Source"."DocEntry" and "t"."INMOpenQty"="Source"."Quantity" and "t"."INMSubLine" = -1
			group by "t"."DocEntry", "t"."BaseLine" ) as "Result"
			on "u"."DocEntry" = "Result"."DocEntry" and "u"."BaseLine" = "Result"."BaseLine" and "u"."LineNum" = "Result"."LineNum";
			
			SELECT ::ROWCOUNT INTO i FROM DUMMY;
			
			if :i = 0 then 
				break;
			end if;
	
		END while;
	end;';		
	exec(:v_sql);
end;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START
create procedure _TmSp_ValidateSpParam(IN passin_parameter_in nvarchar(5000))
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
READS SQL DATA
as
	paralist nvarchar(5000);
	--paralistUpper nvarchar(5000);
	first_quote_position int;
	second_quote_position int;
	string_of_condition nvarchar(256);
	previous_string_of_condition nvarchar(256);
	string_of_parameter nvarchar(256);
	previous_string_of_parameter nvarchar(256);
	paralist_after nvarchar(100);
	length_of_paralist int;
	vi int;
	vCout int := 0;
	debugM int := 0; --Debug witch 1-enable
    Timeout_behavior int := 0; --0 return, 1 exception
    startpoint timestamp := current_timestamp;
begin
    DECLARE arraySplict NVARCHAR(20) ARRAY = ARRAY('''', '"');
    DECLARE VaildFailed CONDITION FOR SQL_ERROR_CODE 10000;
    DECLARE VaildException CONDITION FOR SQL_ERROR_CODE 10001;
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    begin
        if debugM = 0 then --debug switch
	        if ::SQL_ERROR_CODE = 10000 then
	            SIGNAL VaildFailed SET MESSAGE_TEXT = ::SQL_ERROR_MESSAGE;    
	        else  
	            SIGNAL VaildException SET MESSAGE_TEXT = ::SQL_ERROR_MESSAGE;    
	        end if;
        end if;
    end;
    
    --check if feature has enabled.
    if session_context('ValidateSpParam') <> 'ENABLE' or session_context('ValidateSpParam') is null then
        return;
    end if;
    
    --Setting on Exception of timeout
    if session_context('ValidateTimeout') = 'Exception' then 
        Timeout_behavior := 1;      
    end if;
    
    begin
        DECLARE VaildFailed CONDITION FOR SQL_ERROR_CODE 10000;
         
        paralist := passin_parameter_in;
        if locate(replace(paralist, ' ', ''), 'or1=1') + locate(paralist, ' --') + locate(paralist, '/*') > 0 then
            SIGNAL VaildFailed SET MESSAGE_TEXT ='RiskyBehaviorsDetected:03';
        end if;
        
        for vi in 1.. CARDINALITY(:arraySplict)
        do  
            paralist := passin_parameter_in;
            --paralistUpper := upper(paralist);

	        first_quote_position := locate(paralist, :arraySplict[vi], 0, 1);
	    
		    while :first_quote_position > 0
		    do
			    vCout := vCout +1;
	            if vCout > 5000 then
	                  SIGNAL VaildFailed SET MESSAGE_TEXT ='ValidateStringTooLong';
	            end if;
	            
                --timeout setting 0.5s
		        if NANO100_BETWEEN(startpoint, current_timestamp) > 5000000  then 
		            if Timeout_behavior = 0 then
		                  return;
		            else 
		                  SIGNAL VaildException SET MESSAGE_TEXT ='ValidateTimeout';
		            end if;
		        end if;
            
		        length_of_paralist := length(paralist);
		        second_quote_position := locate(paralist, :arraySplict[vi], 0, 2); 
		        
		        string_of_condition := substring(paralist, 0, first_quote_position - 1);
		        paralist_after := substring(paralist, second_quote_position+1, length_of_paralist - second_quote_position);
		        string_of_parameter := substring(paralist, first_quote_position+1, second_quote_position- first_quote_position-1);
		        
                if locate(string_of_condition, ';') > 0 then
					SIGNAL VaildFailed SET MESSAGE_TEXT ='RiskyBehaviorsDetected:00';
				end if;	           
		        
		        if (locate(previous_string_of_condition, ' or ') > 0 and 
						locate(trim(string_of_condition), '=') > 0  and
						trim(previous_string_of_parameter) = trim(string_of_parameter) and
				        (  :arraySplict[vi] != '"' or 
				           (:arraySplict[vi] = '"' and locate(string_of_condition, replace(previous_string_of_condition, ' or ', '')) > 0)
						))
				then
		            SIGNAL VaildFailed SET MESSAGE_TEXT ='RiskyBehaviorsDetected:01';
		        end if;
		        
                paralist := paralist_after;
		        first_quote_position :=  locate(paralist, :arraySplict[vi], 0, 1);
		        previous_string_of_condition := string_of_condition;
		        previous_string_of_parameter := string_of_parameter;
		          
		    end while;
        end for;
    end;    
end;

-- B1 DEPENDS: BEFORE:PT:PROCESS_START

create procedure _TmSp_VariableUpdate_OUQR () 
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER
AS
CURSOR Currs for select "QString" From OUQR Where "QType" = 'W' AND locate(cast("QString" as nchar(80000)),'?') > 0;--CHARINDEX('?',"QString")> 0; 
text nvarchar (4000);
textBefore nvarchar(4000);
textAfter nvarchar(4000);
textHasChanged nvarchar (4000);
v_index int;
n tinyint;
ntmp tinyint;
v_next int := 1;
BEGIN
Open Currs;
--Fetch next From Currs 
--Into @text;
fetch  Currs into text;
	if Currs::NOTFOUND then 
	v_next:=-1;
else
	n := 0;
	v_index := locate(:text, '?');
	textBefore := substr_before(:text,'?');
	textAfter := substr_after(:text,'?');
	ntmp := :n;
	textHasChanged := :textBefore||'[%'||cast(ntmp as nchar(3))||']' || :textAfter;
	--STUFF( :text ,:v_index , 1 , '"%'||cast(n as nchar(3))||'"' );
	n := :n + 1;
	Update OUQR Set "QString" = cast(:texthasChanged as NCLOB) Where cast("QString" as nchar(4000)) = :text;
end if;	
Close Currs;
END;

-- B1 DEPENDS: AFTER:SP:_TmSp_BootCreateGlobalTempTables BEFORE:PT:PROCESS_START

CREATE PROCEDURE _TmSp_VatSumCalc (
in obj nvarchar(4),
in field nvarchar(20))
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER

AS
obj1 nvarchar(4);
vdec tinyint;
rowNum int:=1;
rowCount int:=0;
vatSum1 float;
vatSumFrgn1 float;
vatSumSy1 float;	
vsum float;
sumFrgn float;
sumsy float;
sqlStr varchar(5000);
BEGIN
	delete from VatSumCalc_TmpTab;
	obj1 := right(:obj,3)||'1';
	SELECT MAX("SumDec") INTO vdec FROM OADM;
	vsum :=0;
	sumFrgn :=0;
	sumSy :=0;
	
	exec 'CREATE SEQUENCE my_s INCREMENT BY 1 START WITH 1';
	sqlStr := 'INSERT INTO VatSumCalc_TmpTab SELECT my_s.NEXTVAL, A."DocEntry",A."LineNum",A."VatPrcnt",A."LineTotal",'||
		'A."TotalFrgn",A."TotalSumSy",B."VatSum",B."VatSumFC",B."'||:field||'",B."DiscPrcnt"'||
		' FROM '||:obj1||' A INNER JOIN '||:obj||' B ON A."DocEntry"=B."DocEntry" '||
		' WHERE (A."VatSum" IS NULL OR A."VatSum"=0) AND (NOT A."VatPrcnt" IS NULL AND A."VatPrcnt"<>0)'||
		' AND NOT A."VatGroup" IS NULL ORDER BY A."DocEntry",A."LineNum"';
	--exec 'insert into TEST111 select my_s.NEXTVAL from dual';
	select :sqlStr from DUMMY;
	exec sqlStr;
	SELECT MAX(RowNum) INTO rowCount FROM VatSumCalc_TmpTab;
	IF :rowCount>0 THEN
		WHILE :rowNum < :rowCount DO
			SELECT ROUND(LineTotal*(VatPrcnt/100)*(1-DiscPrcnt/100),:vdec) INTO vatSum1
				FROM VatSumCalc_TmpTab WHERE RowNum=:rowNum;
			SELECT ROUND(TotalFrgn*(VatPrcnt/100)*(1-DiscPrcnt/100),:vdec) INTO vatSumFrgn1
				FROM VatSumCalc_TmpTab WHERE RowNum=:rowNum;
			SELECT ROUND(TotalSumSy*(VatPrcnt/100)*(1-DiscPrcnt/100),:vdec) INTO vatSumSy1
				FROM VatSumCalc_TmpTab WHERE RowNum=:rowNum;
			
			vsum := :vsum+:vatSum1;
			sumFrgn := :sumFrgn+:vatSumFrgn1;
			sumsy := :sumsy+:vatSumSy1;
			sqlStr := 'UPDATE '||:obj1||' SET "VatSum"='||:vatSum1||',"VatSumFrgn"='||:vatSumFrgn1||
				',"VatSumSy"='||:vatSumSy1||
				' WHERE "DocEntry" IN (SELECT DocEntry FROM VatSumCalc_TmpTab WHERE RowNum='||:rowNum||')'||
				' AND "LineNum" IN (SELECT LineNum FROM VatSumCalc_TmpTab WHERE RowNum='||:rowNum||')';
			EXEC sqlStr;
			rowNum := :rowNum+1;
		END WHILE;
			SELECT ROUND(VatSum-:vsum,:vdec) INTO vatSum1
				FROM VatSumCalc_TmpTab WHERE RowNum=:rowCount;
			SELECT ROUND(VatSumFc-:sumFrgn,:vdec) INTO vatSumFrgn1
				FROM VatSumCalc_TmpTab WHERE RowNum=:rowCount;
			SELECT ROUND(Dfield-:sumsy ,:vdec) INTO vatSumSy1
				FROM VatSumCalc_TmpTab WHERE RowNum=:rowCount;
			vsum :=0;
			sumFrgn:=0;
			sumSy:=0;
			
			sqlStr := 'UPDATE '||:obj1||' SET "VatSum"='||:vatSum1||',"VatSumFrgn"='||:vatSumFrgn1||
				',"VatSumSy"='||:vatSumSy1||
				' WHERE "DocEntry" IN (SELECT DocEntry FROM VatSumCalc_TmpTab WHERE RowNum='||:rowCount||')'||
				' AND "LineNum" IN (SELECT LineNum FROM VatSumCalc_TmpTab WHERE RowNum='||:rowCount||')';
			EXEC sqlStr;
	END IF;		
	exec 'drop sequence my_s';
	delete from VatSumCalc_TmpTab;
END;


-- ========== FUNCTION (32) ==========

CREATE FUNCTION "AgentAll_BOM_LIST"(
	IN OnlyBottom INTEGER	--是否只取最底层节点：1：是；0：否
)
/*
	获取BOM完整节点
*/
RETURNS TABLE("ProductCode" NVARCHAR(50),
	"ProductName" NVARCHAR(200),
    "ItemCode" NVARCHAR(50),
    "ItemName" NVARCHAR(200),
	"Type" INTEGER,
	"TypeName" NVARCHAR(20),
	"BomItemCode" NVARCHAR(500),
	"BomItemName" NVARCHAR(500),
	"WhsCode" NVARCHAR(50),
	"IssueMthd" NVARCHAR(10),
	"Quantity" DECIMAL(21,6),
	"ProdBaseQty" DECIMAL(21,6),
	"AddQuantity" DECIMAL(21,6),
	"Phantom" NVARCHAR(10),
	"IsPurchase" NVARCHAR(100),
	"BomLevel" NVARCHAR(300),
	"Level" INTEGER,"BomNum" INTEGER,
	"Father" NVARCHAR(50),
	"Code" NVARCHAR(50),
	"ChildNum" INTEGER,
	"LeadTime" INTEGER,
	"TreeType" NVARCHAR(2),
	"TreeTypeName" NVARCHAR(10))
AS
BEGIN
  DECLARE CNT INTEGER;
  
  --获取所有产成品
  TMP_Product=
    SELECT 
      -1 AS "Key",
      T0."Code" AS "ProductCode",
      T0."Name" AS "ProductName",
      T0."Code" AS "ItemCode",
      T0."Name" AS "ItemName",  
      4 AS "Type",
      T0."ToWH" AS "WhsCode",
      CAST('' AS NVARCHAR(10)) AS "IssueMthd",
      T0."Qauntity" AS "Quantity", 
      T0."Qauntity" AS "ProdBaseQty",--基于成品的基础数量
	  0 AS "AddQuantity",
      T1."Phantom",  --虚拟物料 
      'N' AS "IsPurchase",--是否采购 
      0 AS "BomNum",
      CAST('000' AS NVARCHAR(300)) AS "BomLevel",
      CAST('' AS NVARCHAR(50)) AS "BomTag",--BOM层级标识
      CAST('' AS NVARCHAR(50)) AS "Father",
      T0."Code" AS "Code",
      -1 AS "ChildNum",
      T1."LeadTime",
      T0."TreeType"
    FROM "OITT" T0
    INNER JOIN "OITM" T1 ON T1."ItemCode"=T0."Code"
    ORDER BY T0."Code";

  --获取所有BOM明细清单
  TMP_ITT1=
    SELECT
      T0.*,
      CASE WHEN NOT EXISTS(SELECT 1 FROM "ITT1" D0 WHERE D0."Father"=T0."Code")
           THEN 'N' ELSE 'Y' END AS "ExistsSub"--存在子件
    FROM "ITT1" T0;
    
  TMP_BOMDetail=
    SELECT
      ROW_NUMBER() OVER() AS "Key",
      ROW_NUMBER() OVER(PARTITION BY TT."ItemCode" ORDER BY TT."StageId",TT."Type" DESC,TT."ChildNum") AS "BomNum",
      TT.*
    FROM
    (
	    SELECT 
	      T1."StageId",
	      T0."Code" AS "ItemCode",
	      T0."Name" AS "ItemName",
	      T0."Qauntity" AS "Quantity",
	      CASE WHEN T1."Type"=-18 THEN TO_CHAR(T1."LineText") ELSE T1."Code" END AS "ChildCode",
	      CASE WHEN T1."Type"=-18 THEN TO_CHAR(T1."LineText") ELSE T1."ItemName" END AS "ChildName",
	      T1."Quantity" AS "ChildQuantity",
	      T1."AddQuantit" AS "AddQuantity",
	      T1."Type",
	      T1."Warehouse" AS "WhsCode",
	      T1."IssueMthd",
	      T1."ChildNum",
	      T2."Phantom",  --虚拟物料  
	      T2."LeadTime",--提前期
	      CASE --1.子件不存在下级物料，且当前不是虚拟物料，则为采购 
	           WHEN T1."ExistsSub"='N' AND T2."Phantom"='N' 
	           THEN 'Y'
	           --2.子件不存在下级物料，且当前是虚拟物料，则为不采购 
	           WHEN T1."ExistsSub"='N' AND T2."Phantom"='Y' 
	           THEN 'N'
	           --3.子件存在下级物料，当前子件不是虚拟物料，子件的下级物料存在虚拟物料，则当前子件为采购
	           WHEN T1."ExistsSub"='Y' AND T2."Phantom"='N' 
	                AND EXISTS(SELECT 1 FROM "ITT1" D0  
	                           INNER JOIN "OITM" D1 ON D1."ItemCode"=D0."Code"
	                           WHERE D0."Father"=T1."Code" AND D1."Phantom"='Y')
	           THEN 'Y'
	           --4.子件存在下级物料，当前子件不是虚拟物料，子件的下级物料不存在虚拟物料，则当前子件为采购
	           WHEN T1."ExistsSub"='Y' AND T2."Phantom"='N' 
	                AND NOT EXISTS(SELECT 1 FROM "ITT1" D0  
	                               INNER JOIN "OITM" D1 ON D1."ItemCode"=D0."Code"
	                               WHERE D0."Father"=T1."Code" AND D1."Phantom"='Y')
	           THEN 'Y'
	           --5.子件存在下级物料，当前子件是虚拟物料，子件的下级物料不存在虚拟物料，则当前子件为不采购 
	           WHEN T1."ExistsSub"='Y' AND T2."Phantom"='Y' 
	                AND NOT EXISTS(SELECT 1 FROM "ITT1" D0  
	                               INNER JOIN "OITM" D1 ON D1."ItemCode"=D0."Code"
	                               WHERE D0."Father"=T1."Code" AND D1."Phantom"='Y')
	           THEN 'N'  
	           ELSE 'N' END AS "IsPurchase",--是否采购
	      CAST('000.'||RIGHT('000'||(T1."ChildNum"),3) AS NVARCHAR(300)) AS "BomLevel",
		  T0."TreeType"
	    FROM "OITT" T0
	    INNER JOIN :TMP_ITT1 T1 ON T1."Father"=T0."Code"
	    LEFT JOIN "OITM" T2 ON T2."ItemCode"=T1."Code"
	    UNION ALL
	    SELECT 
	      T1."StageId",
	      T0."Code" AS "ItemCode",
	      T0."Name" AS "ItemName",
	      T0."Qauntity" AS "Quantity",
	      T2."Code" AS "ChildCode",
	      T2."Desc" AS "ChildName",
	      0 AS "ChildQuantity",
	      0 AS "AddQuantity",
	      296 AS "Type",
	      NULL AS "WhsCode",
	      NULL AS "IssueMthd",
	      T1."SeqNum" AS "ChildNum",
	      NULL AS "Phantom",  --虚拟物料  
	      T1."WaitDays" AS "LeadTime",--提前期
	      NULL AS "IsPurchase",--是否采购
	      CAST('000.'||RIGHT('000'||(T1."SeqNum"),3) AS NVARCHAR(300)) AS "BomLevel",
		  T0."TreeType"
	    FROM "OITT" T0
	    INNER JOIN "ITT2" T1 ON T1."Father"=T0."Code"
	    INNER JOIN "ORST" T2 ON T2."AbsEntry"=T1."StgEntry"
    )TT; 

  --将产成品构建到总表中
  TMP_ProcBom=
    SELECT * FROM :TMP_PRODUCT;
  
  --获取下级清单
  TMP_Child=
    SELECT
      T1."Key",
      T0."ProductCode",
      T0."ProductName",
      T1."ChildCode" AS "ItemCode",
      T1."ChildName" AS "ItemName",
      T1."Type",
      T1."WhsCode",
      T1."IssueMthd",
      T1."ChildQuantity" AS "Quantity", 
      T1."ChildQuantity"*T0."Quantity" AS "ProdBaseQty",--基于成品的基础数量
      T1."AddQuantity",
      T1."Phantom",  --虚拟物料 
      T1."IsPurchase",--是否采购
      T1."BomNum",
      CAST(T0."BomLevel"||'.'||RIGHT('000'||T1."BomNum",3) AS NVARCHAR(300)) AS "BomLevel", 
      CAST(T0."BomTag"||'.' AS NVARCHAR(50)) AS "BomTag",
      T1."ItemCode" AS "Father",
      T1."ChildCode" AS "Code",
      T1."ChildNum",
      T1."LeadTime",--提前期
	  T0."TreeType"
    FROM :TMP_PRODUCT T0
    INNER JOIN :TMP_BOMDETAIL T1 ON T1."ItemCode"=T0."ItemCode"
    ORDER BY T0."ProductCode",T1."BomNum";

  --判断是否存在下级，存在则进行合并
  SELECT COUNT(1) INTO CNT FROM :TMP_CHILD;
  WHILE :CNT>0 DO
    --合并到总表
    TMP_ProcBom=
      SELECT * FROM :TMP_PROCBOM
      UNION ALL
      SELECT * FROM :TMP_CHILD;
    
    --根据下级清单继续获取下下级清单
    TMP_Child=
      SELECT  
        T1."Key",
        T0."ProductCode",
        T0."ProductName",
        T1."ChildCode" AS "ItemCode",
        T1."ChildName" AS "ItemName",
        T1."Type",
        T1."WhsCode",
        T1."IssueMthd",
        T1."ChildQuantity" AS "Quantity",
        T1."ChildQuantity"*T0."Quantity" AS "ProdBaseQty",--基于成品的基础数量
		T1."AddQuantity",
        T1."Phantom",  --虚拟物料 
        T1."IsPurchase",--是否采购
        T1."BomNum",
        CAST(T0."BomLevel"||'.'||RIGHT('000'||T1."BomNum",3) AS NVARCHAR(300)) AS "BomLevel",
        CAST(T0."BomTag"||'.' AS NVARCHAR(50)) AS "BomTag",
        T1."ItemCode" AS "Father",
        T1."ChildCode" AS "Code",
        T1."ChildNum",
        T1."LeadTime",--提前期
	    T1."TreeType"
      FROM :TMP_CHILD T0
      INNER JOIN :TMP_BOMDETAIL T1 ON T1."ItemCode"=T0."ItemCode"
      INNER JOIN "OITM" T2 ON T2."ItemCode"=T1."ChildCode" 
      WHERE 1=1
      --根据产品，子件代码及Key值标识，检查是否已经存在BOM层级中，存在则不汇总到子件中，防止BOM主子件设定死循环
      AND NOT EXISTS(SELECT 1 FROM :TMP_PROCBOM D0 
                     WHERE D0."ProductCode"=T0."ProductCode"
                     AND D0."ItemCode"=T1."ChildCode" AND D0."Key"=T1."Key")
      ORDER BY T0."ProductCode",T1."BomNum";
    
    --获取下级记录数(当记录数>0时，循环合并和取下级操作)
    SELECT COUNT(1) INTO CNT FROM :TMP_CHILD;
  
  END WHILE;

  -- 创建叶子节点标识表
  TMP_LeafNodes = 
    SELECT 
        T0."ProductCode",
        T0."ItemCode",
        T0."BomLevel",
        -- 判断是否为叶子节点：在当前BOM层级下没有更深的子节点
        CASE WHEN NOT EXISTS (
            SELECT 1 FROM :TMP_PROCBOM T1 
            WHERE T1."ProductCode" = T0."ProductCode" 
            AND T1."BomLevel" LIKE T0."BomLevel" || '.%'
        ) THEN 1 ELSE 0 END AS "IsLeaf"
    FROM :TMP_PROCBOM T0;
  
  --返回结果 - 只返回叶子节点
  RETURN
  SELECT 
    T0."ProductCode", 
    T0."ProductName",
    T0."ItemCode",
    T0."ItemName",
    T0."Type",
    CASE WHEN T0."Type"=4 THEN 'Item'
         WHEN T0."Type"=296 THEN 'Route Stage'
         WHEN T0."Type"=290 THEN 'Resource'
         WHEN T0."Type"=-18 THEN 'Text'
         ELSE '' END AS "TypeName",
    CAST(REPLACE(T0."BomTag",'.',NCHAR(12288)||NCHAR(12288))||T0."ItemCode" AS NVARCHAR(500)) AS "BomItemCode",
    CAST(REPLACE(T0."BomTag",'.',NCHAR(12288)||NCHAR(12288))||T0."ItemName" AS NVARCHAR(500)) AS "BomItemName",
    T0."WhsCode",
    T0."IssueMthd",
    T0."Quantity",
    T0."ProdBaseQty",--基于成品的基础数量
    T0."AddQuantity",
    T0."Phantom",  --虚拟物料 
    CASE WHEN EXISTS(SELECT 1 FROM :TMP_PROCBOM D0 WHERE D0."ProductCode"=T0."ProductCode" AND D0."BomLevel"='000' AND D0."Phantom"='Y')
         THEN 'N'
         WHEN EXISTS(SELECT 1 FROM :TMP_PROCBOM D0 WHERE D0."ProductCode"=T0."ProductCode" AND LOCATE(T0."BomLevel",D0."BomLevel")=1
                     AND LENGTH(D0."BomLevel")<LENGTH(T0."BomLevel") AND D0."IsPurchase"='Y') 
         THEN 'N'
         ELSE T0."IsPurchase" END AS "IsPurchase",--是否采购
    CAST(T0."BomLevel" AS NVARCHAR(300)) AS "BomLevel",
    LENGTH(T0."BomTag")+1 AS "Level",
    T0."BomNum",
    T0."Father",
    T0."Code",
    T0."ChildNum",
    IFNULL(T0."LeadTime",0) AS "LeadTime",--提前期
    T0."TreeType",
    CASE T0."TreeType"
    WHEN 'A' THEN 'Assembly'
    WHEN 'S' THEN 'Sales Production'
    WHEN 'P' THEN 'Production'
    WHEN 'T' THEN 'Template'
    END AS "TreeTypeName"
  FROM :TMP_PROCBOM T0
  INNER JOIN :TMP_LEAFNODES L ON L."ProductCode" = T0."ProductCode" 
                              AND L."ItemCode" = T0."ItemCode" 
                              AND L."BomLevel" = T0."BomLevel"
  WHERE L."IsLeaf" = CASE :ONLYBOTTOM WHEN 1 THEN 1 ELSE L."IsLeaf" END  -- 只选择叶子节点
  ORDER BY T0."ProductCode",T0."BomLevel";
 
END;

CREATE FUNCTION "AgentAll_EXTRACT_LOGINUSER"
(
   input_string NVARCHAR(500)
)

RETURNS result_string NVARCHAR(500)
LANGUAGE SQLSCRIPT
AS
BEGIN
    DECLARE result_string_temp NVARCHAR(500);
    DECLARE at_position INTEGER;
     
    -- 检查输入是否为NULL
    IF :INPUT_STRING IS NULL THEN
        result_string_temp :=null;
    END IF;
    
    -- 查找@符号位置
    at_position := LOCATE(:INPUT_STRING, '@');
    
    -- 如果找到@符号，提取后面的内容
    IF :AT_POSITION > 0 THEN
        result_string_temp := SUBSTRING(:INPUT_STRING, :AT_POSITION + 1);
    ELSE
        result_string_temp := NULL;
    END IF;
   
  SELECT result_string_temp INTO result_string FROM DUMMY;
END;

CREATE FUNCTION "AgentAll_FORMATAMOUNT" (
   IN Amount DECIMAL(18, 5), --金额
   IN Separator NVARCHAR(1),--分隔符
   IN DecimalPlaces INT  --小数位
)
RETURNS FormatAmount NVARCHAR(100)
AS
BEGIN
    DECLARE Formatted NVARCHAR(100);
    DECLARE Sign NVARCHAR(1) := CASE WHEN Amount < 0 THEN '-' ELSE '' END;
    DECLARE AbsoluteValue DECIMAL(18,5) := ABS(Amount);
    
    -- 格式化绝对值部分
    Formatted = TO_NVARCHAR(
        ROUND(AbsoluteValue, DecimalPlaces), 
        '999,999,999.' || LPAD('9', DecimalPlaces, '9')
    );
    
    -- 替换分隔符并添加符号
    Formatted = :SIGN || REPLACE(:FORMATTED, ',', :SEPARATOR);
    
    -- 处理零值（如 0 → '0.00'）
    IF Amount = 0 THEN
        Formatted = REPLACE('0.' || LPAD('0', DecimalPlaces, '0'), ',', :SEPARATOR);
    END IF;
    FormatAmount:=Formatted;
 
END;

create FUNCTION "AgentAll_FORMATAMOUNT_EUR" (
   IN Amount DECIMAL(18, 5),  -- 金额
   IN Separator NVARCHAR(1),  -- 分隔符 (此参数在修改后不再使用)
   IN DecimalPlaces INT       -- 小数位
)
RETURNS FormatAmount NVARCHAR(100)
AS
BEGIN
    DECLARE Formatted NVARCHAR(100);
    DECLARE Sign NVARCHAR(1) := CASE WHEN Amount < 0 THEN '-' ELSE '' END;
    DECLARE AbsoluteValue DECIMAL(18,5) := ABS(Amount);
    DECLARE formatStr NVARCHAR(50);
    DECLARE pos INT;
    
    -- 动态构建格式字符串 (添加FM前缀移除前导空格)
    IF DecimalPlaces > 0 THEN
        formatStr := '999,999,999.' || LPAD('9', DecimalPlaces, '9');
    ELSE
        formatStr := '999,999,999';
    END IF;
    
    -- 格式化绝对值部分
    Formatted := TO_NVARCHAR(ROUND(AbsoluteValue, DecimalPlaces), formatStr);
    
    -- 处理有小数位的情况
    IF DecimalPlaces > 0 THEN
        -- 查找小数点位置
        pos := LOCATE(Formatted, '.');
        -- 分别处理整数部分和小数部分
        IF pos > 0 THEN
            -- 整数部分替换：将千分位逗号替换为点号
            Formatted := REPLACE(SUBSTR(:FORMATTED, 1, :POS-1), ',', '.') 
                      || ',' 
                      || SUBSTR(:FORMATTED, :POS+1);
        END IF;
    ELSE
        -- 无小数位：直接替换千分位逗号为点号
        Formatted := REPLACE(Formatted, ',', '.');
    END IF;
    
    -- 添加符号
    FormatAmount := :SIGN || :FORMATTED;
END;

CREATE FUNCTION "AgentAll_FORMATDATE" (
       InDate DATE,                -- 输入日期
      DateFormat INT,             -- 格式编码（0,1,2,3,4,5,6）
      DateStep NVARCHAR(1)        -- 分隔符（如 '.', '/'）
) 
RETURNS FormattedDate NVARCHAR(20)
LANGUAGE SQLSCRIPT
AS
BEGIN


 
    -- 提取年、月、日（补零处理）
    DECLARE YearFull NVARCHAR(4) := TO_NVARCHAR(EXTRACT(YEAR FROM :INDATE));
    DECLARE YearShort NVARCHAR(2) := RIGHT(:YEARFULL, 2);
    DECLARE Month NVARCHAR(2) := LPAD(TO_NVARCHAR(EXTRACT(MONTH FROM :INDATE)), 2, '0');
    DECLARE Day NVARCHAR(2) := LPAD(TO_NVARCHAR(EXTRACT(DAY FROM :INDATE)), 2, '0');
    

 
 
    -- 根据 DateFormat 生成对应格式
    FormattedDate := CASE :DATEFORMAT
    
        -- DateFormat=6 → 'YY/MM/DD' → 替换分隔符，年份取后两位
        WHEN 6 THEN :DAY || :DATESTEP || :MONTH || :DATESTEP || :YEARSHORT
        
         -- DateFormat=5 → 'DD/Month/YYYY' → 替换分隔符，年份取后两位
        WHEN 5 THEN :DAY || :DATESTEP || :MONTH || :DATESTEP || :YEARFULL
        
        -- DateFormat=4 → 'CCYY/MM/DD' → 替换分隔符
        WHEN 4 THEN :YEARFULL || :DATESTEP || :MONTH || :DATESTEP || :DAY

        -- DateFormat=3 → 'MM/DD/CCYY' → 替换分隔符
        WHEN 3 THEN :MONTH || :DATESTEP || :DAY || :DATESTEP || :YEARFULL

        -- DateFormat=2 → 'MM/DD/YY' → 替换分隔符，年份取后两位
        WHEN 2 THEN :MONTH || :DATESTEP || :DAY || :DATESTEP || :YEARSHORT

        -- DateFormat=1 → 'DD/MM/CCYY' → 替换分隔符
        WHEN 1 THEN :DAY || :DATESTEP || :MONTH || :DATESTEP || :YEARFULL
         -- DateFormat=0 → 'DD/MM/YY' → 替换分隔符
        WHEN 0 THEN :DAY || :DATESTEP || :MONTH || :DATESTEP || :YEARFULL

        -- 默认格式：YYYY-MM-DD
        ELSE :YEARFULL || '-' || :MONTH || '-' || :DAY
    END;
END;

CREATE FUNCTION "AgentAll_FORMAT_STRING"(
    template NVARCHAR(5000), 
    args NVARCHAR(5000) ARRAY
) RETURNS result NVARCHAR(5000)
LANGUAGE SQLSCRIPT
AS
BEGIN

    --- 创建人: sherry 
    --- 创建时间: 2025.4.15
    --- 功能描述: 用于多语言输出动态值
    ---语言：zh-CN、en-US、de-CH
    DECLARE i INTEGER;
    DECLARE placeholder NVARCHAR(10);
    DECLARE temp NVARCHAR(5000) := template;
    
    -- 遍历参数数组
    FOR i IN 1..CARDINALITY(:ARGS) DO
        placeholder := '{' || (:I - 1) || '}';
        temp := REPLACE(:TEMP, :PLACEHOLDER, :ARGS[:I]);
    END FOR;
    
    result := :TEMP;
END;

CREATE FUNCTION "AgentAll_FindBPByEmail" (
    p_Email NVARCHAR(100),
    p_BPCode NVARCHAR(100) DEFAULT NULL,
    p_BPName NVARCHAR(100) DEFAULT NULL,
    p_Currency NVARCHAR(3) DEFAULT NULL
)
RETURNS v_CardCode NVARCHAR(100)
LANGUAGE SQLSCRIPT
AS
BEGIN

   --SELECT "AgentAll_FindBPByEmail"('test@example.com') FROM DUMMY;
    DECLARE v_Count INT;
    DECLARE v_MatchingCount INT;
     v_CardCode='';
    -- 1. 优先按邮箱精确匹配
    SELECT COUNT(1) INTO v_MatchingCount
    FROM "OCRD" BP
    JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode" 
    WHERE (CP."E_MailL" = :P_EMAIL or CP."Cellolar" = :P_EMAIL)  and BP."CardType"='C';
   
 
        
    -- 1.1 如果邮箱唯一匹配，直接返回
    IF :V_MATCHINGCOUNT = 1 THEN
    
       SELECT BP."CardCode" INTO v_CardCode
	        FROM "OCRD" BP
	        JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode" 
	        WHERE (CP."E_MailL" = :P_EMAIL or CP."Cellolar" = :P_EMAIL) and BP."CardType"='C' ;
        
    END IF;
    
      -- 1.1 当邮件为空时或者指定客户时，直接返回
    IF (:V_MATCHINGCOUNT = 0 or :V_MATCHINGCOUNT > 0)  AND IFNULL(:P_BPCODE,'')!='' THEN
        SELECT COUNT(1) INTO v_Count
        FROM "OCRD" BP
        JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
        WHERE BP."CardType"='C' AND BP."CardCode" = :P_BPCODE;
        -- 2.1 如果BP名称唯一匹配，返回
            IF :V_COUNT>0 then
	            SELECT BP."CardCode" INTO v_CardCode
	            FROM "OCRD" BP
	            WHERE BP."CardType"='C' AND BP."CardCode" = :P_BPCODE;
            END IF;

    END IF;
    
    -- 1.2 如果邮箱匹配到多个，尝试用BP名称筛选
     IF :V_MATCHINGCOUNT > 1 AND IFNULL(:P_BPNAME,'')!='' THEN
        SELECT COUNT(1) INTO v_Count
        FROM "OCRD" BP
        JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
        WHERE BP."CardType"='C'  and (CP."E_MailL" = :P_EMAIL or CP."Cellolar" = :P_EMAIL)  AND BP."CardName" = :P_BPNAME;
        -- 2.1 如果BP名称唯一匹配，返回
            IF :V_COUNT>0 then
	            SELECT BP."CardCode" INTO v_CardCode
	            FROM "OCRD" BP
	            JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
	            WHERE BP."CardType"='C'  and  CP."E_MailL" = :P_EMAIL AND BP."CardName" = :P_BPNAME;
            END IF;
        END IF;
        
        -- 2.2 如果BP名称未匹配或仍有多条，尝试邮箱+名称+货币
        IF (:V_MATCHINGCOUNT > 1) AND IFNULL(:P_BPNAME,'')!='' AND IFNULL(:P_CURRENCY,'')!=''  THEN
            
                SELECT COUNT(1) INTO v_Count
                FROM "OCRD" BP
                JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
                WHERE BP."CardType"='C'  and (CP."E_MailL" = :P_EMAIL or CP."Cellolar" = :P_EMAIL) AND BP."CardName" = :P_BPNAME  AND BP."Currency" = :P_CURRENCY;
               
                IF :V_COUNT>0 then 
	                SELECT BP."CardCode" INTO v_CardCode
	                FROM "OCRD" BP
	                JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
	                WHERE BP."CardType"='C'  and (CP."E_MailL" = :P_EMAIL or CP."Cellolar" = :P_EMAIL) AND BP."CardName" = :P_BPNAME  AND BP."Currency" = :P_CURRENCY;
                END IF;
        
        END IF;
    
   SELECT case when :V_CARDCODE='' then null else :V_CARDCODE end INTO v_CardCode FROM DUMMY;
 
END;

CREATE FUNCTION  "AgentAll_GET_DOCSTATUS_TYPE"(
    IN Status NVARCHAR(10), --状态
    IN CANCELED NVARCHAR(1) --取消
) 
RETURNS status_type NVARCHAR(20)
AS
BEGIN
    DECLARE temp NVARCHAR(20);
    
    IF CANCELED = 'Y' THEN
        temp := 'Cancelled';
    ELSEIF Status = 'O' THEN
        temp := 'Open';
    ELSEIF Status = 'C' THEN
        temp := 'Closed';
    ELSE
        temp := 'UnKnow';
    END IF;
    
     status_type := :TEMP;
END;

CREATE FUNCTION "AgentAll_GET_LANGUAGE" (
    IN pLang NVARCHAR(20)  -- 输入枚举名称字符串
) 
RETURNS CODE NVARCHAR(20)  -- 输出语言代码
LANGUAGE SQLSCRIPT
AS
    --- 创建人: sherry 
    --- 创建时间: 2025.4.15
    --- 功能描述: 根据B1用户获取语言
      ---语言：zh-CN、en-US、de-CH
/*
ln_Null = 0,
    ln_Hebrew = 1,
    ln_Spanish_Ar = 2,
    ln_English = 3,
    ln_Polish = 5,
    ln_English_Sg = 6,
    ln_Spanish_Pa = 7,
    ln_English_Gb = 8,
    ln_German = 9,
    ln_Serbian = 10,
    ln_Danish = 11,
    ln_Norwegian = 12,
    ln_Italian = 13,
    ln_Hungarian = 14,
    ln_Chinese = 15,
    ln_Dutch = 16,
    ln_Finnish = 17,
    ln_Greek = 18,
    ln_Portuguese = 19,
    ln_Swedish = 20,
    ln_English_Cy = 21,
    ln_French = 22,
    ln_Spanish = 23,
    ln_Russian = 24,
    ln_Spanish_La = 25,
    ln_Czech_Cz = 26,
    ln_Slovak_Sk = 27,
    ln_Korean_Kr = 28,
    ln_Portuguese_Br = 29,
    ln_Japanese_Jp = 30,
    ln_Turkish_Tr = 31,
    ln_Arabic = 32,
    ln_Ukrainian = 33,
    ln_TrdtnlChinese_Hk = 35,
*/
BEGIN
    
   CODE := CASE :PLANG 
    WHEN '15' THEN 'zh_CN'
    WHEN '35' THEN 'zh_Hant'
    WHEN '30' THEN 'ja_JP'
    WHEN '9' THEN 'de'
    WHEN '22' THEN 'fr'
    WHEN '32' THEN 'ar'
    WHEN '16' THEN 'nl'
    WHEN '23' THEN 'es'
    WHEN '28' THEN 'ko'
    WHEN '19' THEN 'pt'
    WHEN '29' THEN 'pt_Br'
    -- 合并所有英语变种
    WHEN 'en' THEN 'en_US'
    WHEN '0' THEN 'en_US'
    WHEN '1' THEN 'en_US'  -- Hebrew (assuming you want to include this)
    WHEN '2' THEN 'en_US'  -- Spanish_Ar (assuming you want to include this)
    WHEN '3' THEN 'en_US'  -- English
    WHEN '5' THEN 'en_US'  -- Polish (assuming you want to include this)
    WHEN '6' THEN 'en_US'  -- English_Sg
    WHEN '7' THEN 'en_US'  -- Spanish_Pa
    WHEN '8' THEN 'en_US'  -- English_Gb
    WHEN '21' THEN 'en_US' -- English_Cy
    ELSE :PLANG  -- 默认值
    END;
END;

CREATE FUNCTION "AgentAll_GET_MSG" (
    IN LANG NVARCHAR(10),    -- 语言代码 (zh-CN/en-US/de-CH)
    IN MSG_KEY NVARCHAR(50),-- 消息键值
    IN DefaultMsg NVARCHAR(200) default ''-- 默认值 
) RETURNS MSG_TEXT NVARCHAR(2000)
AS
    --- 创建人: sherry 
    --- 创建时间: 2025.4.15
    --- 功能描述: 多语言输出函数
      ---语言：zh-CN、en-US、de-CH
BEGIN
    DECLARE TEMPLATE NVARCHAR(2000);
    DECLARE CNT Int;
    SELECT Count(1) INTO CNT 
    FROM "AgentAll_MSG_LANG"
    WHERE "LANG" = :LANG AND "MSG_KEY" = :MSG_KEY;
    IF :CNT>0 then
	    -- 获取消息模板
	    SELECT "MSG_TEXT" INTO MSG_TEXT 
	    FROM "AgentAll_MSG_LANG"
	    WHERE "LANG" = :LANG AND "MSG_KEY" = :MSG_KEY;
    ELSE 
       SELECT IFNULL(:DEFAULTMSG,'Msg Not Found!') INTO MSG_TEXT FROM DUMMY;
    END IF;
END;

CREATE FUNCTION "AgentAll_GetFileMaterialInfo" (
    IN V_ItemCode NVARCHAR(100),--物料代码
    IN V_ItemName NVARCHAR(200),--物料描述
    IN V_BarCode NVARCHAR(254),--barCode
    IN V_SubCode NVARCHAR(200) --业务编码

)
RETURNS v_Result NVARCHAR(100)
LANGUAGE SQLSCRIPT
AS
BEGIN
     /*
    --- 创建人: sherry 
    --- 创建时间: 2025.6.17
    --- 功能描述: 物料匹配规则：1、物料 2、barcode 3、客户目录编号、4、物料描述
    --- 功能描述: select  "AgentAll_GetFileMaterialInfo"('C00001','','','','') from dummy
*/
    DECLARE v_Found INTEGER:=0;
     v_Result='';
    -- 1. 优先匹配ItemCode
    IF :V_RESULT='' AND IFNULL(:V_ITEMCODE,'')!=''  THEN
         SELECT :V_ITEMCODE INTO v_Result  FROM DUMMY;
    END IF;
     -- 2. 如果未找到，匹配条码(CodeBars)
    IF :V_RESULT='' AND IFNULL(:V_BARCODE,'')!=''  THEN
         SELECT :V_BARCODE INTO v_Result  FROM DUMMY;
    END IF;
    IF :V_RESULT='' AND IFNULL(:V_SUBCODE,'')!=''  THEN
         SELECT :V_SUBCODE INTO v_Result  FROM DUMMY;
    END IF;
    IF :V_RESULT='' AND IFNULL(:V_ITEMNAME,'')!=''  THEN
         SELECT :V_ITEMNAME INTO v_Result  FROM DUMMY;
    END IF;
 
   SELECT case when :V_RESULT='' then '' else :V_RESULT end INTO v_Result FROM DUMMY;
END;

CREATE  FUNCTION "AgentAll_GetMatchedItemCode" (
    IN V_ItemCode NVARCHAR(100),--物料代码
    IN V_ItemName NVARCHAR(200),--物料描述
    IN V_BarCode NVARCHAR(254),--barCode
    IN V_SubCode NVARCHAR(200),--客户目录编号匹配
    IN V_CardCode NVARCHAR(20)
)
RETURNS v_Result NVARCHAR(100)
LANGUAGE SQLSCRIPT
AS
BEGIN
   /*
    --- 创建人: sherry 
    --- 创建时间: 2025.6.17
    --- 功能描述: 物料匹配规则：1、物料 2、barcode 3、客户目录编号、4、物料描述
    --- 功能描述: select  "AgentAll_GetMatchedItemCode"('C00001','','','','') from dummy
*/
    DECLARE v_Found INTEGER:=0;
     v_Result='';
    -- 1. 优先匹配ItemCode
    SELECT COUNT(*) INTO v_Found FROM "OITM" 
    WHERE "ItemCode"=:V_ITEMCODE;
    
    IF :V_FOUND > 0 THEN
        SELECT  "ItemCode" INTO v_Result 
        FROM "OITM" 
        WHERE "ItemCode"=:V_ITEMCODE
        LIMIT 1;
    END IF;
    
    -- 2. 如果未找到，匹配条码(CodeBars)
    IF :V_RESULT='' AND IFNULL(:V_BARCODE,'')!=''  THEN
        SELECT COUNT(*) INTO v_Found FROM "OITM" 
        WHERE "CodeBars"=:V_BARCODE;
        IF :V_FOUND > 0 THEN
            SELECT  "ItemCode" INTO v_Result 
            FROM "OITM" 
            WHERE "CodeBars"=:V_BARCODE
            LIMIT 1;
        END IF;
    END IF;
    
    -- 2. 如果未找到，匹配条码(CodeBars)
    IF :V_RESULT='' AND IFNULL(:V_ITEMCODE,'')!=''  THEN
        SELECT COUNT(*) INTO v_Found FROM "OITM" 
        WHERE "CodeBars"=:V_ITEMCODE;
        IF :V_FOUND > 0 THEN
            SELECT  "ItemCode" INTO v_Result 
            FROM "OITM" 
            WHERE "CodeBars"=:V_ITEMCODE
            LIMIT 1;
        END IF;
    END IF;
    
    -- 3. 如果未找到且提供了CardCode，匹配业务伙伴参考编号
    IF :V_RESULT='' AND IFNULL(:V_CARDCODE,'')!='' AND IFNULL(:V_SUBCODE,'')!=''  THEN
         SELECT COUNT(*) INTO v_Found FROM  "OSCN"  WHERE "Substitute"=:V_SUBCODE   and "CardCode"=:V_CARDCODE;
        
        IF :V_FOUND > 0 THEN
           SELECT "ItemCode" INTO v_Result  FROM  "OSCN"  
           WHERE "Substitute"=:V_SUBCODE   
           and "CardCode"=:V_CARDCODE
           LIMIT 1;
        END IF;
    END IF;
    
        -- 4. 如果未找到且提供了CardCode，匹配业务伙伴参考编号
    IF :V_RESULT='' AND IFNULL(:V_CARDCODE,'')!='' AND IFNULL(:V_ITEMCODE,'')!=''  THEN
         SELECT COUNT(*) INTO v_Found FROM  "OSCN"  WHERE "Substitute"=:V_ITEMCODE   and "CardCode"=:V_CARDCODE;
        
        IF :V_FOUND > 0 THEN
           SELECT "ItemCode" INTO v_Result  FROM  "OSCN"  
           WHERE "Substitute"=:V_ITEMCODE   
           and "CardCode"=:V_CARDCODE
           LIMIT 1;
        END IF;
    END IF;
    
          -- 5. 如果未找到且提供了CardCode，匹配业务伙伴参考描述
    IF :V_RESULT='' AND IFNULL(:V_CARDCODE,'')!='' AND IFNULL(:V_ITEMNAME,'')!=''  THEN
         SELECT COUNT(*) INTO v_Found FROM  "OSCN"  WHERE "Descriptio"=:V_ITEMNAME   and "CardCode"=:V_CARDCODE;
        
        IF :V_FOUND > 0 THEN
           SELECT "ItemCode" INTO v_Result  FROM  "OSCN"  
           WHERE "Descriptio"=:V_ITEMNAME 
           and "CardCode"=:V_CARDCODE
           LIMIT 1;
        END IF;
    END IF;
    
    -- 6. 如果仍未找到，匹配物料描述(ItemName)
    IF :V_RESULT='' AND IFNULL(:V_ITEMNAME,'')!=''  THEN
        SELECT COUNT(*) INTO v_Found FROM "OITM" 
        WHERE "ItemName"=:V_ITEMNAME;
        IF :V_FOUND > 0 THEN
            SELECT  "ItemCode" INTO v_Result 
            FROM "OITM" 
            WHERE "ItemName"=:V_ITEMNAME
            LIMIT 1;
        END IF;
    END IF;

   SELECT case when :V_RESULT='' then null else :V_RESULT end INTO v_Result FROM DUMMY;
END;

CREATE FUNCTION "AgentAll_ReplaceCharacters" (
    IN input_string NVARCHAR(2000),  -- 修改参数名以更准确
    IN old_char NVARCHAR(10),
    IN new_char NVARCHAR(10) 
) 
RETURNS output_string NVARCHAR(2000)  -- 修改返回参数名以避免混淆
AS
BEGIN
    /*
    创建人: sherry 
    创建时间: 2025.7.11
    最后修改: 2025.7.11
    功能描述: 多语言字符替换函数
    支持语言: zh-CN、en-US、de-CH
    
    参数说明:
        input_string - 原始输入字符串
        old_char - 需要被替换的字符或子串
        new_char - 替换后的新字符或子串
    
    返回:
        替换后的新字符串
    
    示例:
        SELECT "AgentAll_ReplaceCharacters"('Hello World', 'o', '0') FROM DUMMY;
 SELECT "AgentAll_ReplaceCharacters"('"
				PC - P4 2.4 G,
				DDR 512 M,
				400 G HD "', '"', '""') FROM DUMMY;
        返回: Hell0 W0rld
    */
   DECLARE output_string_Temp  NVARCHAR(2000);
   
    -- 处理NULL值情况
    IF :INPUT_STRING IS NULL THEN
        select '' into output_string_Temp from dummy;
    END IF;
    
    -- 如果old_char为空或NULL，则返回原字符串
    IF :OLD_CHAR IS NULL OR LENGTH(:OLD_CHAR) = 0 THEN
        select :INPUT_STRING into output_string_Temp from dummy;
        
    END IF;
    
    -- 执行替换操作
    output_string_Temp := REPLACE(:INPUT_STRING, :OLD_CHAR, COALESCE(:NEW_CHAR, ''));
    
    SELECT output_string_Temp INTO output_string FROM DUMMY;
END;

CREATE FUNCTION "AgentAll_SubStrListToTB"
(
  InputStr NVARCHAR(8000),
  Split CHAR(1) DEFAULT ',',      --拆分行,默认以逗号分开 
  ColSplit CHAR(1) DEFAULT NULL    --拆分列,默认以横线分开
)
RETURNS TABLE("Val1" NVARCHAR(100),"Val2" NVARCHAR(100))
AS
BEGIN

  DECLARE InputStr2 NVARCHAR(9000);  
  
  InputStr2=:INPUTSTR||',';

  --构建临时表结构
  TMP_DATA=SELECT :INPUTSTR2 AS "Value" FROM DUMMY WHERE 1=2;
  
  WHILE LOCATE(:INPUTSTR2,:SPLIT) <> 0 DO
    IF SUBSTRING(:INPUTSTR2,1,LOCATE(:INPUTSTR2,:SPLIT)-1) <> '' THEN
      TMP_DATA=
        SELECT "Value" FROM :TMP_DATA
        UNION ALL
        SELECT SUBSTRING(:INPUTSTR2,0,LOCATE(InputStr2,:SPLIT)-1) AS "Value" FROM DUMMY;
    END IF;
    InputStr2 := SUBSTRING(:INPUTSTR2,LOCATE(:INPUTSTR2,:SPLIT)+1,LENGTH(:INPUTSTR2)-LOCATE(:INPUTSTR2,:SPLIT));
  END WHILE;  
  
  IF ColSplit IS NULL THEN
    RETURN SELECT "Value" AS "Val1",NULL AS "Val2" FROM :TMP_DATA;
  ELSE
    RETURN SELECT SUBSTR_BEFORE("Value",:COLSPLIT) AS "Val1",SUBSTR_AFTER("Value",:COLSPLIT) AS "Val2" FROM :TMP_DATA; 
  END IF;
END;

CREATE FUNCTION "AgentAll_USERBPL"(
    IN USERCODE NVARCHAR(50)
)
    RETURNS TABLE (BPLID INT)
/*
    根据当前用户ID获取该用户ID下所有能看到的分支数据
    如果查不到数据，返回0
*/
AS
BEGIN
    -- 先检查用户是否存在
    DECLARE USER_EXISTS INT;
    SELECT COUNT(*) INTO USER_EXISTS FROM "OUSR" WHERE "USER_CODE" = :USERCODE;
    
    -- 如果用户不存在，直接返回0
    IF USER_EXISTS = 0 THEN
        RETURN SELECT 0 AS BPLID FROM DUMMY;
    END IF;
    
    -- 返回权限范围内的所有分支，如果没有关联分支则返回0
    RETURN
    
    SELECT 
        CASE 
            WHEN COUNT(IFNULL(T2."BPLId", 0)) = 0 THEN 0
            ELSE IFNULL(T2."BPLId", 0) 
        END AS BPLID
    FROM "OUSR" T1
    LEFT JOIN "USR6" T2 ON T1."USERID" = T2."UserID"
    LEFT JOIN "OBPL" T3 ON T3."BPLId" = T2."BPLId"
    WHERE T1."USER_CODE" = :USERCODE
    GROUP BY T2."BPLId";
END;

CREATE  FUNCTION "AgentAll_USERRIGHT"(
	IN USERCODE NVARCHAR(50)
)
	RETURNS TABLE (USERID INT)
/*
	根据当前用户ID获取该用户ID下所有能看到的用户数据范围

SELECT * FROM "AgentAll_USERRIGHT"('A001');
*/
AS
BEGIN
	DECLARE UID INT;
	DECLARE CNT  INT;
	-- 获取当前用户UID，后面取数使用
   SELECT COUNT(1) into CNT FROM OUSR WHERE USER_CODE=:USERCODE;
    IF :CNT>0 then
	     RETURN SELECT USERID  FROM OUSR WHERE USER_CODE=:USERCODE;
    else 
         RETURN SELECT USERID FROM OUSR;
    END IF; 
	 
END;

CREATE FUNCTION "MTC_AI_EXTRACT_LOGINUSER"
(
   input_string NVARCHAR(500)
)

RETURNS result_string NVARCHAR(500)
LANGUAGE SQLSCRIPT
AS
BEGIN
    DECLARE result_string_temp NVARCHAR(500);
    DECLARE at_position INTEGER;
     
    -- 检查输入是否为NULL
    IF :input_string IS NULL THEN
        result_string_temp :=null;
    END IF;
    
    -- 查找@符号位置
    at_position := LOCATE(:input_string, '@');
    
    -- 如果找到@符号，提取后面的内容
    IF :at_position > 0 THEN
        result_string_temp := SUBSTRING(:input_string, :at_position + 1);
    ELSE
        result_string_temp := NULL;
    END IF;
   
  SELECT result_string_temp INTO result_string FROM DUMMY;
END;

CREATE FUNCTION "MTC_AI_FORMATAMOUNT" (
   IN Amount DECIMAL(18, 5), --金额
   IN Separator NVARCHAR(1),--分隔符
   IN DecimalPlaces INT  --小数位
)
RETURNS FormatAmount NVARCHAR(100)
AS
BEGIN
    DECLARE Formatted NVARCHAR(100);
    DECLARE Sign NVARCHAR(1) := CASE WHEN Amount < 0 THEN '-' ELSE '' END;
    DECLARE AbsoluteValue DECIMAL(18,5) := ABS(Amount);
    
    -- 格式化绝对值部分
    Formatted = TO_NVARCHAR(
        ROUND(AbsoluteValue, DecimalPlaces), 
        '999,999,999.' || LPAD('9', DecimalPlaces, '9')
    );
    
    -- 替换分隔符并添加符号
    Formatted = :Sign || REPLACE(:Formatted, ',', :Separator);
    
    -- 处理零值（如 0 → '0.00'）
    IF Amount = 0 THEN
        Formatted = REPLACE('0.' || LPAD('0', DecimalPlaces, '0'), ',', :Separator);
    END IF;
    FormatAmount:=Formatted;
 
END;

create FUNCTION "MTC_AI_FORMATAMOUNT_EUR" (
   IN Amount DECIMAL(18, 5),  -- 金额
   IN Separator NVARCHAR(1),  -- 分隔符 (此参数在修改后不再使用)
   IN DecimalPlaces INT       -- 小数位
)
RETURNS FormatAmount NVARCHAR(100)
AS
BEGIN
    DECLARE Formatted NVARCHAR(100);
    DECLARE Sign NVARCHAR(1) := CASE WHEN Amount < 0 THEN '-' ELSE '' END;
    DECLARE AbsoluteValue DECIMAL(18,5) := ABS(Amount);
    DECLARE formatStr NVARCHAR(50);
    DECLARE pos INT;
    
    -- 动态构建格式字符串 (添加FM前缀移除前导空格)
    IF DecimalPlaces > 0 THEN
        formatStr := '999,999,999.' || LPAD('9', DecimalPlaces, '9');
    ELSE
        formatStr := '999,999,999';
    END IF;
    
    -- 格式化绝对值部分
    Formatted := TO_NVARCHAR(ROUND(AbsoluteValue, DecimalPlaces), formatStr);
    
    -- 处理有小数位的情况
    IF DecimalPlaces > 0 THEN
        -- 查找小数点位置
        pos := LOCATE(Formatted, '.');
        -- 分别处理整数部分和小数部分
        IF pos > 0 THEN
            -- 整数部分替换：将千分位逗号替换为点号
            Formatted := REPLACE(SUBSTR(:Formatted, 1, :pos-1), ',', '.') 
                      || ',' 
                      || SUBSTR(:Formatted, :pos+1);
        END IF;
    ELSE
        -- 无小数位：直接替换千分位逗号为点号
        Formatted := REPLACE(Formatted, ',', '.');
    END IF;
    
    -- 添加符号
    FormatAmount := :Sign || :Formatted;
END;

CREATE FUNCTION "MTC_AI_FORMATDATE" (
       InDate DATE,                -- 输入日期
      DateFormat INT,             -- 格式编码（0,1,2,3,4,5,6）
      DateStep NVARCHAR(1)        -- 分隔符（如 '.', '/'）
) 
RETURNS FormattedDate NVARCHAR(20)
LANGUAGE SQLSCRIPT
AS
BEGIN


 
    -- 提取年、月、日（补零处理）
    DECLARE YearFull NVARCHAR(4) := TO_NVARCHAR(EXTRACT(YEAR FROM :InDate));
    DECLARE YearShort NVARCHAR(2) := RIGHT(:YearFull, 2);
    DECLARE Month NVARCHAR(2) := LPAD(TO_NVARCHAR(EXTRACT(MONTH FROM :InDate)), 2, '0');
    DECLARE Day NVARCHAR(2) := LPAD(TO_NVARCHAR(EXTRACT(DAY FROM :InDate)), 2, '0');
    

 
 
    -- 根据 DateFormat 生成对应格式
    FormattedDate := CASE :DateFormat
    
        -- DateFormat=6 → 'YY/MM/DD' → 替换分隔符，年份取后两位
        WHEN 6 THEN :Day || :DateStep || :Month || :DateStep || :YearShort
        
         -- DateFormat=5 → 'DD/Month/YYYY' → 替换分隔符，年份取后两位
        WHEN 5 THEN :Day || :DateStep || :Month || :DateStep || :YearFull
        
        -- DateFormat=4 → 'CCYY/MM/DD' → 替换分隔符
        WHEN 4 THEN :YearFull || :DateStep || :Month || :DateStep || :Day

        -- DateFormat=3 → 'MM/DD/CCYY' → 替换分隔符
        WHEN 3 THEN :Month || :DateStep || :Day || :DateStep || :YearFull

        -- DateFormat=2 → 'MM/DD/YY' → 替换分隔符，年份取后两位
        WHEN 2 THEN :Month || :DateStep || :Day || :DateStep || :YearShort

        -- DateFormat=1 → 'DD/MM/CCYY' → 替换分隔符
        WHEN 1 THEN :Day || :DateStep || :Month || :DateStep || :YearFull
         -- DateFormat=0 → 'DD/MM/YY' → 替换分隔符
        WHEN 0 THEN :Day || :DateStep || :Month || :DateStep || :YearFull

        -- 默认格式：YYYY-MM-DD
        ELSE :YearFull || '-' || :Month || '-' || :Day
    END;
END;

CREATE FUNCTION "MTC_AI_FORMAT_STRING"(
    template NVARCHAR(5000), 
    args NVARCHAR(5000) ARRAY
) RETURNS result NVARCHAR(5000)
LANGUAGE SQLSCRIPT
AS
BEGIN

    --- 创建人: sherry 
    --- 创建时间: 2025.4.15
    --- 功能描述: 用于多语言输出动态值
    ---语言：zh-CN、en-US、de-CH
    DECLARE i INTEGER;
    DECLARE placeholder NVARCHAR(10);
    DECLARE temp NVARCHAR(5000) := template;
    
    -- 遍历参数数组
    FOR i IN 1..CARDINALITY(:args) DO
        placeholder := '{' || (:i - 1) || '}';
        temp := REPLACE(:temp, :placeholder, :args[:i]);
    END FOR;
    
    result := :temp;
END;

CREATE FUNCTION "MTC_AI_FindBPByEmail" (
    p_Email NVARCHAR(100),
    p_BPCode NVARCHAR(100) DEFAULT NULL,
    p_BPName NVARCHAR(100) DEFAULT NULL,
    p_Currency NVARCHAR(3) DEFAULT NULL
)
RETURNS v_CardCode NVARCHAR(100)
LANGUAGE SQLSCRIPT
AS
BEGIN

   --SELECT "MTC_AI_FindBPByEmail"('test@example.com') FROM DUMMY;
    DECLARE v_Count INT;
    DECLARE v_MatchingCount INT;
     v_CardCode='';
    -- 1. 优先按邮箱精确匹配
    SELECT COUNT(1) INTO v_MatchingCount
    FROM "OCRD" BP
    JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode" 
    WHERE (CP."E_MailL" = :p_Email or CP."Cellolar" = :p_Email)  and BP."CardType"='C';
   
 
        
    -- 1.1 如果邮箱唯一匹配，直接返回
    IF :v_MatchingCount = 1 THEN
    
       SELECT BP."CardCode" INTO v_CardCode
	        FROM "OCRD" BP
	        JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode" 
	        WHERE (CP."E_MailL" = :p_Email or CP."Cellolar" = :p_Email) and BP."CardType"='C' ;
        
    END IF;
    
      -- 1.1 当邮件为空时或者指定客户时，直接返回
    IF (:v_MatchingCount = 0 or :v_MatchingCount > 0)  AND IFNULL(:p_BPCode,'')!='' THEN
        SELECT COUNT(1) INTO v_Count
        FROM "OCRD" BP
        JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
        WHERE BP."CardType"='C' AND BP."CardCode" = :p_BPCode;
        -- 2.1 如果BP名称唯一匹配，返回
            IF :v_Count>0 then
	            SELECT BP."CardCode" INTO v_CardCode
	            FROM "OCRD" BP
	            WHERE BP."CardType"='C' AND BP."CardCode" = :p_BPCode;
            END IF;

    END IF;
    
    -- 1.2 如果邮箱匹配到多个，尝试用BP名称筛选
     IF :v_MatchingCount > 1 AND IFNULL(:p_BPName,'')!='' THEN
        SELECT COUNT(1) INTO v_Count
        FROM "OCRD" BP
        JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
        WHERE BP."CardType"='C'  and (CP."E_MailL" = :p_Email or CP."Cellolar" = :p_Email)  AND BP."CardName" = :p_BPName;
        -- 2.1 如果BP名称唯一匹配，返回
            IF :v_Count>0 then
	            SELECT BP."CardCode" INTO v_CardCode
	            FROM "OCRD" BP
	            JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
	            WHERE BP."CardType"='C'  and  CP."E_MailL" = :p_Email AND BP."CardName" = :p_BPName;
            END IF;
        END IF;
        
        -- 2.2 如果BP名称未匹配或仍有多条，尝试邮箱+名称+货币
        IF (:v_MatchingCount > 1) AND IFNULL(:p_BPName,'')!='' AND IFNULL(:p_Currency,'')!=''  THEN
            
                SELECT COUNT(1) INTO v_Count
                FROM "OCRD" BP
                JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
                WHERE BP."CardType"='C'  and (CP."E_MailL" = :p_Email or CP."Cellolar" = :p_Email) AND BP."CardName" = :p_BPName  AND BP."Currency" = :p_Currency;
               
                IF :v_Count>0 then 
	                SELECT BP."CardCode" INTO v_CardCode
	                FROM "OCRD" BP
	                JOIN "OCPR" CP ON BP."CardCode" = CP."CardCode"
	                WHERE BP."CardType"='C'  and (CP."E_MailL" = :p_Email or CP."Cellolar" = :p_Email) AND BP."CardName" = :p_BPName  AND BP."Currency" = :p_Currency;
                END IF;
        
        END IF;
    
   SELECT case when :v_CardCode='' then null else :v_CardCode end INTO v_CardCode FROM DUMMY;
 
END;

CREATE FUNCTION  "MTC_AI_GET_DOCSTATUS_TYPE"(
    IN Status NVARCHAR(10), --状态
    IN CANCELED NVARCHAR(1) --取消
) 
RETURNS status_type NVARCHAR(20)
AS
BEGIN
    DECLARE temp NVARCHAR(20);
    
    IF CANCELED = 'Y' THEN
        temp := 'Cancelled';
    ELSEIF Status = 'O' THEN
        temp := 'Open';
    ELSEIF Status = 'C' THEN
        temp := 'Closed';
    ELSE
        temp := 'UnKnow';
    END IF;
    
     status_type := :temp;
END;

CREATE FUNCTION "MTC_AI_GET_LANGUAGE" (
    IN pLang NVARCHAR(20)  -- 输入枚举名称字符串
) 
RETURNS CODE NVARCHAR(20)  -- 输出语言代码
LANGUAGE SQLSCRIPT
AS
    --- 创建人: sherry 
    --- 创建时间: 2025.4.15
    --- 功能描述: 根据B1用户获取语言
      ---语言：zh-CN、en-US、de-CH
/*
ln_Null = 0,
    ln_Hebrew = 1,
    ln_Spanish_Ar = 2,
    ln_English = 3,
    ln_Polish = 5,
    ln_English_Sg = 6,
    ln_Spanish_Pa = 7,
    ln_English_Gb = 8,
    ln_German = 9,
    ln_Serbian = 10,
    ln_Danish = 11,
    ln_Norwegian = 12,
    ln_Italian = 13,
    ln_Hungarian = 14,
    ln_Chinese = 15,
    ln_Dutch = 16,
    ln_Finnish = 17,
    ln_Greek = 18,
    ln_Portuguese = 19,
    ln_Swedish = 20,
    ln_English_Cy = 21,
    ln_French = 22,
    ln_Spanish = 23,
    ln_Russian = 24,
    ln_Spanish_La = 25,
    ln_Czech_Cz = 26,
    ln_Slovak_Sk = 27,
    ln_Korean_Kr = 28,
    ln_Portuguese_Br = 29,
    ln_Japanese_Jp = 30,
    ln_Turkish_Tr = 31,
    ln_Arabic = 32,
    ln_Ukrainian = 33,
    ln_TrdtnlChinese_Hk = 35,
*/
BEGIN
    
   CODE := CASE :pLang 
    WHEN '15' THEN 'zh_CN'
    WHEN '35' THEN 'zh_Hant'
    WHEN '30' THEN 'ja_JP'
    WHEN '9' THEN 'de'
    WHEN '22' THEN 'fr'
    WHEN '32' THEN 'ar'
    WHEN '16' THEN 'nl'
    WHEN '23' THEN 'es'
    WHEN '28' THEN 'ko'
    -- 合并所有英语变种
    WHEN 'en' THEN 'en_US'
    WHEN '0' THEN 'en_US'
    WHEN '1' THEN 'en_US'  -- Hebrew (assuming you want to include this)
    WHEN '2' THEN 'en_US'  -- Spanish_Ar (assuming you want to include this)
    WHEN '3' THEN 'en_US'  -- English
    WHEN '5' THEN 'en_US'  -- Polish (assuming you want to include this)
    WHEN '6' THEN 'en_US'  -- English_Sg
    WHEN '7' THEN 'en_US'  -- Spanish_Pa
    WHEN '8' THEN 'en_US'  -- English_Gb
    WHEN '21' THEN 'en_US' -- English_Cy
    ELSE :pLang  -- 默认值
    END;
END;

CREATE FUNCTION "MTC_AI_GET_MSG" (
    IN LANG NVARCHAR(10),    -- 语言代码 (zh-CN/en-US/de-CH)
    IN MSG_KEY NVARCHAR(50),-- 消息键值
    IN DefaultMsg NVARCHAR(200) default ''-- 默认值 
) RETURNS MSG_TEXT NVARCHAR(2000)
AS
    --- 创建人: sherry 
    --- 创建时间: 2025.4.15
    --- 功能描述: 多语言输出函数
      ---语言：zh-CN、en-US、de-CH
BEGIN
    DECLARE TEMPLATE NVARCHAR(2000);
    DECLARE CNT Int;
    SELECT Count(1) INTO CNT 
    FROM "MTC_AI_MSG_LANG"
    WHERE "LANG" = :LANG AND "MSG_KEY" = :MSG_KEY;
    IF :CNT>0 then
	    -- 获取消息模板
	    SELECT "MSG_TEXT" INTO MSG_TEXT 
	    FROM "MTC_AI_MSG_LANG"
	    WHERE "LANG" = :LANG AND "MSG_KEY" = :MSG_KEY;
    ELSE 
       SELECT IFNULL(:DefaultMsg,'Msg Not Found!') INTO MSG_TEXT FROM DUMMY;
    END IF;
END;

CREATE FUNCTION "MTC_AI_GetFileMaterialInfo" (
    IN V_ItemCode NVARCHAR(100),--物料代码
    IN V_ItemName NVARCHAR(200),--物料描述
    IN V_BarCode NVARCHAR(254),--barCode
    IN V_SubCode NVARCHAR(200) --业务编码

)
RETURNS v_Result NVARCHAR(100)
LANGUAGE SQLSCRIPT
AS
BEGIN
     /*
    --- 创建人: sherry 
    --- 创建时间: 2025.6.17
    --- 功能描述: 物料匹配规则：1、物料 2、barcode 3、客户目录编号、4、物料描述
    --- 功能描述: select  "MTC_AI_GetFileMaterialInfo"('C00001','','','','') from dummy
*/
    DECLARE v_Found INTEGER:=0;
     v_Result='';
    -- 1. 优先匹配ItemCode
    IF :v_Result='' AND IFNULL(:V_ItemCode,'')!=''  THEN
         SELECT :V_ItemCode INTO v_Result  FROM DUMMY;
    END IF;
     -- 2. 如果未找到，匹配条码(CodeBars)
    IF :v_Result='' AND IFNULL(:V_BarCode,'')!=''  THEN
         SELECT :V_BarCode INTO v_Result  FROM DUMMY;
    END IF;
    IF :v_Result='' AND IFNULL(:V_SubCode,'')!=''  THEN
         SELECT :V_SubCode INTO v_Result  FROM DUMMY;
    END IF;
    IF :v_Result='' AND IFNULL(:V_ItemName,'')!=''  THEN
         SELECT :V_ItemName INTO v_Result  FROM DUMMY;
    END IF;
 
   SELECT case when :v_Result='' then '' else :v_Result end INTO v_Result FROM DUMMY;
END;

CREATE  FUNCTION "MTC_AI_GetMatchedItemCode" (
    IN V_ItemCode NVARCHAR(100),--物料代码
    IN V_ItemName NVARCHAR(200),--物料描述
    IN V_BarCode NVARCHAR(254),--barCode
    IN V_SubCode NVARCHAR(200),--客户目录编号匹配
    IN V_CardCode NVARCHAR(20)
)
RETURNS v_Result NVARCHAR(100)
LANGUAGE SQLSCRIPT
AS
BEGIN
   /*
    --- 创建人: sherry 
    --- 创建时间: 2025.6.17
    --- 功能描述: 物料匹配规则：1、物料 2、barcode 3、客户目录编号、4、物料描述
    --- 功能描述: select  "MTC_AI_GetMatchedItemCode"('C00001','','','','') from dummy
*/
    DECLARE v_Found INTEGER:=0;
     v_Result='';
    -- 1. 优先匹配ItemCode
    SELECT COUNT(*) INTO v_Found FROM "OITM" 
    WHERE "ItemCode"=:V_ItemCode;
    
    IF :v_Found > 0 THEN
        SELECT  "ItemCode" INTO v_Result 
        FROM "OITM" 
        WHERE "ItemCode"=:V_ItemCode
        LIMIT 1;
    END IF;
    
    -- 2. 如果未找到，匹配条码(CodeBars)
    IF :v_Result='' AND IFNULL(:V_BarCode,'')!=''  THEN
        SELECT COUNT(*) INTO v_Found FROM "OITM" 
        WHERE "CodeBars"=:V_BarCode;
        IF :v_Found > 0 THEN
            SELECT  "ItemCode" INTO v_Result 
            FROM "OITM" 
            WHERE "CodeBars"=:V_BarCode
            LIMIT 1;
        END IF;
    END IF;
    
    -- 2. 如果未找到，匹配条码(CodeBars)
    IF :v_Result='' AND IFNULL(:V_ItemCode,'')!=''  THEN
        SELECT COUNT(*) INTO v_Found FROM "OITM" 
        WHERE "CodeBars"=:V_ItemCode;
        IF :v_Found > 0 THEN
            SELECT  "ItemCode" INTO v_Result 
            FROM "OITM" 
            WHERE "CodeBars"=:V_ItemCode
            LIMIT 1;
        END IF;
    END IF;
    
    -- 3. 如果未找到且提供了CardCode，匹配业务伙伴参考编号
    IF :v_Result='' AND IFNULL(:V_CardCode,'')!='' AND IFNULL(:V_SubCode,'')!=''  THEN
         SELECT COUNT(*) INTO v_Found FROM  "OSCN"  WHERE "Substitute"=:V_SubCode   and "CardCode"=:V_CardCode;
        
        IF :v_Found > 0 THEN
           SELECT "ItemCode" INTO v_Result  FROM  "OSCN"  
           WHERE "Substitute"=:V_SubCode   
           and "CardCode"=:V_CardCode
           LIMIT 1;
        END IF;
    END IF;
    
        -- 4. 如果未找到且提供了CardCode，匹配业务伙伴参考编号
    IF :v_Result='' AND IFNULL(:V_CardCode,'')!='' AND IFNULL(:V_ItemCode,'')!=''  THEN
         SELECT COUNT(*) INTO v_Found FROM  "OSCN"  WHERE "Substitute"=:V_ItemCode   and "CardCode"=:V_CardCode;
        
        IF :v_Found > 0 THEN
           SELECT "ItemCode" INTO v_Result  FROM  "OSCN"  
           WHERE "Substitute"=:V_ItemCode   
           and "CardCode"=:V_CardCode
           LIMIT 1;
        END IF;
    END IF;
    
          -- 5. 如果未找到且提供了CardCode，匹配业务伙伴参考描述
    IF :v_Result='' AND IFNULL(:V_CardCode,'')!='' AND IFNULL(:V_ItemName,'')!=''  THEN
         SELECT COUNT(*) INTO v_Found FROM  "OSCN"  WHERE "Descriptio"=:V_ItemName   and "CardCode"=:V_CardCode;
        
        IF :v_Found > 0 THEN
           SELECT "ItemCode" INTO v_Result  FROM  "OSCN"  
           WHERE "Descriptio"=:V_ItemName 
           and "CardCode"=:V_CardCode
           LIMIT 1;
        END IF;
    END IF;
    
    -- 6. 如果仍未找到，匹配物料描述(ItemName)
    IF :v_Result='' AND IFNULL(:V_ItemName,'')!=''  THEN
        SELECT COUNT(*) INTO v_Found FROM "OITM" 
        WHERE "ItemName"=:V_ItemName;
        IF :v_Found > 0 THEN
            SELECT  "ItemCode" INTO v_Result 
            FROM "OITM" 
            WHERE "ItemName"=:V_ItemName
            LIMIT 1;
        END IF;
    END IF;

   SELECT case when :v_Result='' then null else :v_Result end INTO v_Result FROM DUMMY;
END;

CREATE FUNCTION "MTC_AI_ReplaceCharacters" (
    IN input_string NVARCHAR(2000),  -- 修改参数名以更准确
    IN old_char NVARCHAR(10),
    IN new_char NVARCHAR(10) 
) 
RETURNS output_string NVARCHAR(2000)  -- 修改返回参数名以避免混淆
AS
BEGIN
    /*
    创建人: sherry 
    创建时间: 2025.7.11
    最后修改: 2025.7.11
    功能描述: 多语言字符替换函数
    支持语言: zh-CN、en-US、de-CH
    
    参数说明:
        input_string - 原始输入字符串
        old_char - 需要被替换的字符或子串
        new_char - 替换后的新字符或子串
    
    返回:
        替换后的新字符串
    
    示例:
        SELECT "MTC_AI_ReplaceCharacters"('Hello World', 'o', '0') FROM DUMMY;
 SELECT "MTC_AI_ReplaceCharacters"('"
				PC - P4 2.4 G,
				DDR 512 M,
				400 G HD "', '"', '""') FROM DUMMY;
        返回: Hell0 W0rld
    */
   DECLARE output_string_Temp  NVARCHAR(2000);
   
    -- 处理NULL值情况
    IF :input_string IS NULL THEN
        select '' into output_string_Temp from dummy;
    END IF;
    
    -- 如果old_char为空或NULL，则返回原字符串
    IF :old_char IS NULL OR LENGTH(:old_char) = 0 THEN
        select :input_string into output_string_Temp from dummy;
        
    END IF;
    
    -- 执行替换操作
    output_string_Temp := REPLACE(:input_string, :old_char, COALESCE(:new_char, ''));
    
    SELECT output_string_Temp INTO output_string FROM DUMMY;
END;

CREATE FUNCTION "MTC_AI_SubStrListToTB"
(
  InputStr NVARCHAR(8000),
  Split CHAR(1) DEFAULT ',',      --拆分行,默认以逗号分开 
  ColSplit CHAR(1) DEFAULT NULL    --拆分列,默认以横线分开
)
RETURNS TABLE("Val1" NVARCHAR(100),"Val2" NVARCHAR(100))
AS
BEGIN

  DECLARE InputStr2 NVARCHAR(9000);  
  
  InputStr2=:InputStr||',';

  --构建临时表结构
  TMP_DATA=SELECT :InputStr2 AS "Value" FROM DUMMY WHERE 1=2;
  
  WHILE LOCATE(:InputStr2,:Split) <> 0 DO
    IF SUBSTRING(:InputStr2,1,LOCATE(:InputStr2,:Split)-1) <> '' THEN
      TMP_DATA=
        SELECT "Value" FROM :TMP_DATA
        UNION ALL
        SELECT SUBSTRING(:InputStr2,0,LOCATE(InputStr2,:Split)-1) AS "Value" FROM DUMMY;
    END IF;
    InputStr2 := SUBSTRING(:InputStr2,LOCATE(:InputStr2,:Split)+1,LENGTH(:InputStr2)-LOCATE(:InputStr2,:Split));
  END WHILE;  
  
  IF ColSplit IS NULL THEN
    RETURN SELECT "Value" AS "Val1",NULL AS "Val2" FROM :TMP_DATA;
  ELSE
    RETURN SELECT SUBSTR_BEFORE("Value",:ColSplit) AS "Val1",SUBSTR_AFTER("Value",:ColSplit) AS "Val2" FROM :TMP_DATA; 
  END IF;
END;

CREATE FUNCTION "MTC_FN_AI_USERBPL"(
    IN USERCODE NVARCHAR(50)
)
    RETURNS TABLE (BPLID INT)
/*
    根据当前用户ID获取该用户ID下所有能看到的分支数据
    如果查不到数据，返回0
*/
AS
BEGIN
    -- 先检查用户是否存在
    DECLARE USER_EXISTS INT;
    SELECT COUNT(*) INTO USER_EXISTS FROM "OUSR" WHERE "USER_CODE" = :USERCODE;
    
    -- 如果用户不存在，直接返回0
    IF USER_EXISTS = 0 THEN
        RETURN SELECT 0 AS BPLID FROM DUMMY;
    END IF;
    
    -- 返回权限范围内的所有分支，如果没有关联分支则返回0
    RETURN
    
    SELECT 
        CASE 
            WHEN COUNT(IFNULL(T2."BPLId", 0)) = 0 THEN 0
            ELSE IFNULL(T2."BPLId", 0) 
        END AS BPLID
    FROM "OUSR" T1
    LEFT JOIN "USR6" T2 ON T1."USERID" = T2."UserID"
    LEFT JOIN "OBPL" T3 ON T3."BPLId" = T2."BPLId"
    WHERE T1."USER_CODE" = :USERCODE
    GROUP BY T2."BPLId";
END;

CREATE  FUNCTION "MTC_FN_AI_USERRIGHT"(
	IN USERCODE NVARCHAR(50)
)
	RETURNS TABLE (USERID INT)
/*
	根据当前用户ID获取该用户ID下所有能看到的用户数据范围

SELECT * FROM "MTC_FN_AI_USERRIGHT"('A001');
*/
AS
BEGIN
	DECLARE UID INT;
	DECLARE CNT  INT;
	-- 获取当前用户UID，后面取数使用
   SELECT COUNT(1) into CNT FROM OUSR WHERE USER_CODE=:USERCODE;
    IF :CNT>0 then
	     RETURN SELECT USERID  FROM OUSR WHERE USER_CODE=:USERCODE;
    else 
         RETURN SELECT USERID FROM OUSR;
    END IF; 
	 
END;

CREATE FUNCTION "MTC_FN_BOM_LIST"(
	IN OnlyBottom INTEGER	--是否只取最底层节点：1：是；0：否
)
/*
	获取BOM完整节点
*/
RETURNS TABLE("ProductCode" NVARCHAR(50),
	"ProductName" NVARCHAR(200),
    "ItemCode" NVARCHAR(50),
    "ItemName" NVARCHAR(200),
	"Type" INTEGER,
	"TypeName" NVARCHAR(20),
	"BomItemCode" NVARCHAR(500),
	"BomItemName" NVARCHAR(500),
	"WhsCode" NVARCHAR(50),
	"IssueMthd" NVARCHAR(10),
	"Quantity" DECIMAL(21,6),
	"ProdBaseQty" DECIMAL(21,6),
	"AddQuantity" DECIMAL(21,6),
	"Phantom" NVARCHAR(10),
	"IsPurchase" NVARCHAR(100),
	"BomLevel" NVARCHAR(300),
	"Level" INTEGER,"BomNum" INTEGER,
	"Father" NVARCHAR(50),
	"Code" NVARCHAR(50),
	"ChildNum" INTEGER,
	"LeadTime" INTEGER,
	"TreeType" NVARCHAR(2),
	"TreeTypeName" NVARCHAR(10))
AS
BEGIN
  DECLARE CNT INTEGER;
  
  --获取所有产成品
  TMP_Product=
    SELECT 
      -1 AS "Key",
      T0."Code" AS "ProductCode",
      T0."Name" AS "ProductName",
      T0."Code" AS "ItemCode",
      T0."Name" AS "ItemName",  
      4 AS "Type",
      T0."ToWH" AS "WhsCode",
      CAST('' AS NVARCHAR(10)) AS "IssueMthd",
      T0."Qauntity" AS "Quantity", 
      T0."Qauntity" AS "ProdBaseQty",--基于成品的基础数量
	  0 AS "AddQuantity",
      T1."Phantom",  --虚拟物料 
      'N' AS "IsPurchase",--是否采购 
      0 AS "BomNum",
      CAST('000' AS NVARCHAR(300)) AS "BomLevel",
      CAST('' AS NVARCHAR(50)) AS "BomTag",--BOM层级标识
      CAST('' AS NVARCHAR(50)) AS "Father",
      T0."Code" AS "Code",
      -1 AS "ChildNum",
      T1."LeadTime",
      T0."TreeType"
    FROM "OITT" T0
    INNER JOIN "OITM" T1 ON T1."ItemCode"=T0."Code"
    ORDER BY T0."Code";

  --获取所有BOM明细清单
  TMP_ITT1=
    SELECT
      T0.*,
      CASE WHEN NOT EXISTS(SELECT 1 FROM "ITT1" D0 WHERE D0."Father"=T0."Code")
           THEN 'N' ELSE 'Y' END AS "ExistsSub"--存在子件
    FROM "ITT1" T0;
    
  TMP_BOMDetail=
    SELECT
      ROW_NUMBER() OVER() AS "Key",
      ROW_NUMBER() OVER(PARTITION BY TT."ItemCode" ORDER BY TT."StageId",TT."Type" DESC,TT."ChildNum") AS "BomNum",
      TT.*
    FROM
    (
	    SELECT 
	      T1."StageId",
	      T0."Code" AS "ItemCode",
	      T0."Name" AS "ItemName",
	      T0."Qauntity" AS "Quantity",
	      CASE WHEN T1."Type"=-18 THEN TO_CHAR(T1."LineText") ELSE T1."Code" END AS "ChildCode",
	      CASE WHEN T1."Type"=-18 THEN TO_CHAR(T1."LineText") ELSE T1."ItemName" END AS "ChildName",
	      T1."Quantity" AS "ChildQuantity",
	      T1."AddQuantit" AS "AddQuantity",
	      T1."Type",
	      T1."Warehouse" AS "WhsCode",
	      T1."IssueMthd",
	      T1."ChildNum",
	      T2."Phantom",  --虚拟物料  
	      T2."LeadTime",--提前期
	      CASE --1.子件不存在下级物料，且当前不是虚拟物料，则为采购 
	           WHEN T1."ExistsSub"='N' AND T2."Phantom"='N' 
	           THEN 'Y'
	           --2.子件不存在下级物料，且当前是虚拟物料，则为不采购 
	           WHEN T1."ExistsSub"='N' AND T2."Phantom"='Y' 
	           THEN 'N'
	           --3.子件存在下级物料，当前子件不是虚拟物料，子件的下级物料存在虚拟物料，则当前子件为采购
	           WHEN T1."ExistsSub"='Y' AND T2."Phantom"='N' 
	                AND EXISTS(SELECT 1 FROM "ITT1" D0  
	                           INNER JOIN "OITM" D1 ON D1."ItemCode"=D0."Code"
	                           WHERE D0."Father"=T1."Code" AND D1."Phantom"='Y')
	           THEN 'Y'
	           --4.子件存在下级物料，当前子件不是虚拟物料，子件的下级物料不存在虚拟物料，则当前子件为采购
	           WHEN T1."ExistsSub"='Y' AND T2."Phantom"='N' 
	                AND NOT EXISTS(SELECT 1 FROM "ITT1" D0  
	                               INNER JOIN "OITM" D1 ON D1."ItemCode"=D0."Code"
	                               WHERE D0."Father"=T1."Code" AND D1."Phantom"='Y')
	           THEN 'Y'
	           --5.子件存在下级物料，当前子件是虚拟物料，子件的下级物料不存在虚拟物料，则当前子件为不采购 
	           WHEN T1."ExistsSub"='Y' AND T2."Phantom"='Y' 
	                AND NOT EXISTS(SELECT 1 FROM "ITT1" D0  
	                               INNER JOIN "OITM" D1 ON D1."ItemCode"=D0."Code"
	                               WHERE D0."Father"=T1."Code" AND D1."Phantom"='Y')
	           THEN 'N'  
	           ELSE 'N' END AS "IsPurchase",--是否采购
	      CAST('000.'||RIGHT('000'||(T1."ChildNum"),3) AS NVARCHAR(300)) AS "BomLevel",
		  T0."TreeType"
	    FROM "OITT" T0
	    INNER JOIN :TMP_ITT1 T1 ON T1."Father"=T0."Code"
	    LEFT JOIN "OITM" T2 ON T2."ItemCode"=T1."Code"
	    UNION ALL
	    SELECT 
	      T1."StageId",
	      T0."Code" AS "ItemCode",
	      T0."Name" AS "ItemName",
	      T0."Qauntity" AS "Quantity",
	      T2."Code" AS "ChildCode",
	      T2."Desc" AS "ChildName",
	      0 AS "ChildQuantity",
	      0 AS "AddQuantity",
	      296 AS "Type",
	      NULL AS "WhsCode",
	      NULL AS "IssueMthd",
	      T1."SeqNum" AS "ChildNum",
	      NULL AS "Phantom",  --虚拟物料  
	      T1."WaitDays" AS "LeadTime",--提前期
	      NULL AS "IsPurchase",--是否采购
	      CAST('000.'||RIGHT('000'||(T1."SeqNum"),3) AS NVARCHAR(300)) AS "BomLevel",
		  T0."TreeType"
	    FROM "OITT" T0
	    INNER JOIN "ITT2" T1 ON T1."Father"=T0."Code"
	    INNER JOIN "ORST" T2 ON T2."AbsEntry"=T1."StgEntry"
    )TT; 

  --将产成品构建到总表中
  TMP_ProcBom=
    SELECT * FROM :TMP_Product;
  
  --获取下级清单
  TMP_Child=
    SELECT
      T1."Key",
      T0."ProductCode",
      T0."ProductName",
      T1."ChildCode" AS "ItemCode",
      T1."ChildName" AS "ItemName",
      T1."Type",
      T1."WhsCode",
      T1."IssueMthd",
      T1."ChildQuantity" AS "Quantity", 
      T1."ChildQuantity"*T0."Quantity" AS "ProdBaseQty",--基于成品的基础数量
      T1."AddQuantity",
      T1."Phantom",  --虚拟物料 
      T1."IsPurchase",--是否采购
      T1."BomNum",
      CAST(T0."BomLevel"||'.'||RIGHT('000'||T1."BomNum",3) AS NVARCHAR(300)) AS "BomLevel", 
      CAST(T0."BomTag"||'.' AS NVARCHAR(50)) AS "BomTag",
      T1."ItemCode" AS "Father",
      T1."ChildCode" AS "Code",
      T1."ChildNum",
      T1."LeadTime",--提前期
	  T0."TreeType"
    FROM :TMP_Product T0
    INNER JOIN :TMP_BOMDetail T1 ON T1."ItemCode"=T0."ItemCode"
    ORDER BY T0."ProductCode",T1."BomNum";

  --判断是否存在下级，存在则进行合并
  SELECT COUNT(1) INTO CNT FROM :TMP_Child;
  WHILE :CNT>0 DO
    --合并到总表
    TMP_ProcBom=
      SELECT * FROM :TMP_ProcBom
      UNION ALL
      SELECT * FROM :TMP_Child;
    
    --根据下级清单继续获取下下级清单
    TMP_Child=
      SELECT  
        T1."Key",
        T0."ProductCode",
        T0."ProductName",
        T1."ChildCode" AS "ItemCode",
        T1."ChildName" AS "ItemName",
        T1."Type",
        T1."WhsCode",
        T1."IssueMthd",
        T1."ChildQuantity" AS "Quantity",
        T1."ChildQuantity"*T0."Quantity" AS "ProdBaseQty",--基于成品的基础数量
		T1."AddQuantity",
        T1."Phantom",  --虚拟物料 
        T1."IsPurchase",--是否采购
        T1."BomNum",
        CAST(T0."BomLevel"||'.'||RIGHT('000'||T1."BomNum",3) AS NVARCHAR(300)) AS "BomLevel",
        CAST(T0."BomTag"||'.' AS NVARCHAR(50)) AS "BomTag",
        T1."ItemCode" AS "Father",
        T1."ChildCode" AS "Code",
        T1."ChildNum",
        T1."LeadTime",--提前期
	    T1."TreeType"
      FROM :TMP_Child T0
      INNER JOIN :TMP_BOMDetail T1 ON T1."ItemCode"=T0."ItemCode"
      INNER JOIN "OITM" T2 ON T2."ItemCode"=T1."ChildCode" 
      WHERE 1=1
      --根据产品，子件代码及Key值标识，检查是否已经存在BOM层级中，存在则不汇总到子件中，防止BOM主子件设定死循环
      AND NOT EXISTS(SELECT 1 FROM :TMP_ProcBom D0 
                     WHERE D0."ProductCode"=T0."ProductCode"
                     AND D0."ItemCode"=T1."ChildCode" AND D0."Key"=T1."Key")
      ORDER BY T0."ProductCode",T1."BomNum";
    
    --获取下级记录数(当记录数>0时，循环合并和取下级操作)
    SELECT COUNT(1) INTO CNT FROM :TMP_Child;
  
  END WHILE;

  -- 创建叶子节点标识表
  TMP_LeafNodes = 
    SELECT 
        T0."ProductCode",
        T0."ItemCode",
        T0."BomLevel",
        -- 判断是否为叶子节点：在当前BOM层级下没有更深的子节点
        CASE WHEN NOT EXISTS (
            SELECT 1 FROM :TMP_ProcBom T1 
            WHERE T1."ProductCode" = T0."ProductCode" 
            AND T1."BomLevel" LIKE T0."BomLevel" || '.%'
        ) THEN 1 ELSE 0 END AS "IsLeaf"
    FROM :TMP_ProcBom T0;
  
  --返回结果 - 只返回叶子节点
  RETURN
  SELECT 
    T0."ProductCode", 
    T0."ProductName",
    T0."ItemCode",
    T0."ItemName",
    T0."Type",
    CASE WHEN T0."Type"=4 THEN 'Item'
         WHEN T0."Type"=296 THEN 'Route Stage'
         WHEN T0."Type"=290 THEN 'Resource'
         WHEN T0."Type"=-18 THEN 'Text'
         ELSE '' END AS "TypeName",
    CAST(REPLACE(T0."BomTag",'.',NCHAR(12288)||NCHAR(12288))||T0."ItemCode" AS NVARCHAR(500)) AS "BomItemCode",
    CAST(REPLACE(T0."BomTag",'.',NCHAR(12288)||NCHAR(12288))||T0."ItemName" AS NVARCHAR(500)) AS "BomItemName",
    T0."WhsCode",
    T0."IssueMthd",
    T0."Quantity",
    T0."ProdBaseQty",--基于成品的基础数量
    T0."AddQuantity",
    T0."Phantom",  --虚拟物料 
    CASE WHEN EXISTS(SELECT 1 FROM :TMP_ProcBom D0 WHERE D0."ProductCode"=T0."ProductCode" AND D0."BomLevel"='000' AND D0."Phantom"='Y')
         THEN 'N'
         WHEN EXISTS(SELECT 1 FROM :TMP_ProcBom D0 WHERE D0."ProductCode"=T0."ProductCode" AND LOCATE(T0."BomLevel",D0."BomLevel")=1
                     AND LENGTH(D0."BomLevel")<LENGTH(T0."BomLevel") AND D0."IsPurchase"='Y') 
         THEN 'N'
         ELSE T0."IsPurchase" END AS "IsPurchase",--是否采购
    CAST(T0."BomLevel" AS NVARCHAR(300)) AS "BomLevel",
    LENGTH(T0."BomTag")+1 AS "Level",
    T0."BomNum",
    T0."Father",
    T0."Code",
    T0."ChildNum",
    IFNULL(T0."LeadTime",0) AS "LeadTime",--提前期
    T0."TreeType",
    CASE T0."TreeType"
    WHEN 'A' THEN 'Assembly'
    WHEN 'S' THEN 'Sales Production'
    WHEN 'P' THEN 'Production'
    WHEN 'T' THEN 'Template'
    END AS "TreeTypeName"
  FROM :TMP_ProcBom T0
  INNER JOIN :TMP_LeafNodes L ON L."ProductCode" = T0."ProductCode" 
                              AND L."ItemCode" = T0."ItemCode" 
                              AND L."BomLevel" = T0."BomLevel"
  WHERE L."IsLeaf" = CASE :OnlyBottom WHEN 1 THEN 1 ELSE L."IsLeaf" END  -- 只选择叶子节点
  ORDER BY T0."ProductCode",T0."BomLevel";
 
END;


-- ========== SYNONYM (1) ==========

CREATE SYNONYM "SBODEMOUS"."CAULG" FOR "B1LOGGING"."SBODEMOUS_15068"


